(* ========================================================================= *)
(* Carleson's theorem: the Fourier series of an L^2 function on the circle   *)
(* converges pointwise almost everywhere.                                    *)
(*                                                                           *)
(* Proof route: the concrete Lacey-Thiele time-frequency (tile) proof on R   *)
(* as presented in Fremlin, Measure Theory vol 2, section 286 (286A-286V).   *)
(* ========================================================================= *)

needs "Autoformalization/fourier_transform.ml";;

(* ========================================================================= *)
(* Fremlin 256M: the directed-supremum-integral identity.                    *)
(*                                                                           *)
(* For a family {v_z : z in R} of x-continuous functions with pointwise sup  *)
(*   Ah(x) = sup_z |v_z(x)|  and F of finite measure,                        *)
(*   int_F Ah = sup { int_F (max_{i<=n} |v_{z i}|) : z:num->real, n:num }.   *)
(* Absent from HOL Light; the entry point of Fremlin 286P.  Built from the   *)
(* sequence-form monotone convergence (finite maxima cmaxseq increase to the *)
(* countable sup; a Lindelof reduction recovers the uncountable sup).        *)
(* Self-contained: depends only on the measure/realanalysis base.            *)
(* ========================================================================= *)

(* The recursive finite maximum of |u 0|,...,|u n| (a sequence u:num->real-> *)
(* real of functions).  cmaxseq u n x = max_{i<=n} |u i x|.                  *)
let cmaxseq = define
 `(cmaxseq (u:num->real->real) 0 x = abs(u 0 x)) /\
  (cmaxseq u (SUC n) x = max (cmaxseq u n x) (abs(u (SUC n) x)))`;;

(* cmaxseq is increasing in n.                                               *)
let CMAXSEQ_INCREASING = prove
 (`!(u:num->real->real) n x. cmaxseq u n x <= cmaxseq u (SUC n) x`,
  REWRITE_TAC[cmaxseq] THEN REAL_ARITH_TAC);;

(* cmaxseq is nonnegative.                                                   *)
let CMAXSEQ_POS = prove
 (`!(u:num->real->real) n x. &0 <= cmaxseq u n x`,
  GEN_TAC THEN INDUCT_TAC THEN REWRITE_TAC[cmaxseq] THEN REAL_ARITH_TAC);;

(* cmaxseq u n dominates each |u i x| for i <= n.                            *)
let CMAXSEQ_GE = prove
 (`!(u:num->real->real) n i x. i <= n ==> abs(u i x) <= cmaxseq u n x`,
  GEN_TAC THEN INDUCT_TAC THEN REWRITE_TAC[cmaxseq] THENL
   [SIMP_TAC[LE] THEN REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[LE] THEN REPEAT STRIP_TAC THENL
     [ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
      MATCH_MP_TAC(REAL_ARITH `a <= b ==> a <= max b c`) THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

(* cmaxseq preserves real-continuity-on (finite max of continuous).          *)
let CMAXSEQ_CONTINUOUS = prove
 (`!(u:num->real->real) s n.
     (!i. (u i) real_continuous_on s) ==> (cmaxseq u n) real_continuous_on s`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN DISCH_TAC THENL
   [SUBGOAL_THEN
     `cmaxseq (u:num->real->real) 0 = (\x. abs(u 0 x))` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; cmaxseq]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_ABS THEN REWRITE_TAC[ETA_AX] THEN
      ASM_SIMP_TAC[];
    SUBGOAL_THEN
     `cmaxseq (u:num->real->real) (SUC n) = (\x. max (cmaxseq u n x) (abs(u
       (SUC n) x)))`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; cmaxseq]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_MAX THEN CONJ_TAC THENL
     [REWRITE_TAC[ETA_AX] THEN ASM_SIMP_TAC[];
      MATCH_MP_TAC REAL_CONTINUOUS_ON_ABS THEN REWRITE_TAC[ETA_AX] THEN
      ASM_SIMP_TAC[]]]);;

(* Each |u i x| is <= the sup of the family (given a uniform bound B).       *)
let CMAXSEQ_TERM_LE_SUP = prove
 (`!(u:num->real->real) x B i.
     (!j. abs(u j x) <= B)
     ==> abs(u i x) <= sup {abs(u j x) | j IN (:num)}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC [`B:real`; `abs((u:num->real->real) i x)`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `i:num` THEN REWRITE_TAC[IN_UNIV];
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN
      `j:num` (CONJUNCTS_THEN2 (K ALL_TAC) SUBST1_TAC)) THEN
    ASM_REWRITE_TAC[]]);;

(* sup-approximation: for e>0 some term |u j x| exceeds sup - e.             *)
let CMAXSEQ_SUP_APPROX = prove
 (`!(u:num->real->real) x S e.
     (!i. abs(u i x) <= S) /\ &0 < e /\ S = sup {abs(u j x) | j IN (:num)}
     ==> ?j. S - e < abs((u:num->real->real) j x)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[GSYM REAL_NOT_LE] THEN
  REWRITE_TAC[MESON[] `(?j. ~P j) <=> ~(!j. P j)`] THEN DISCH_TAC THEN
  SUBGOAL_THEN `S <= S - e` MP_TAC THENL
   [GEN_REWRITE_TAC LAND_CONV
     [ASSUME `S = sup {abs((u:num->real->real) j x) | j IN (:num)}`] THEN
    MATCH_MP_TAC REAL_SUP_LE THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`abs((u:num->real->real) 0 x)`; `0`] THEN
       REWRITE_TAC[IN_UNIV];
      X_GEN_TAC `w:real` THEN
      DISCH_THEN(X_CHOOSE_THEN
        `j:num` (CONJUNCTS_THEN2 (K ALL_TAC) SUBST1_TAC)) THEN
      ASM_REWRITE_TAC[]];
    ASM_REAL_ARITH_TAC]);;

(* cmaxseq converges pointwise to the sup of the (bounded) family.           *)
let CMAXSEQ_LIMIT_SUP = prove
 (`!(u:num->real->real) x B.
     (!i. abs(u i x) <= B)
     ==> ((\n. cmaxseq u n x) ---> sup {abs(u j x) | j IN (:num)})
       sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!i. abs((u:num->real->real) i x) <=
                    sup {abs(u j x) | j IN (:num)}` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC CMAXSEQ_TERM_LE_SUP THEN
    EXISTS_TAC `B:real` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `S = sup {abs((u:num->real->real) j x) | j IN (:num)}` THEN
  SUBGOAL_THEN `!n. cmaxseq (u:num->real->real) n x <= S` ASSUME_TAC THENL
   [INDUCT_TAC THEN REWRITE_TAC[cmaxseq] THEN
     ASM_REWRITE_TAC[REAL_MAX_LE]; ALL_TAC] THEN
  REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`u:num->real->real`; `x:real`; `S:real`;
    `e:real`] CMAXSEQ_SUP_APPROX) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  EXISTS_TAC `j:num` THEN X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  SUBGOAL_THEN `abs((u:num->real->real) j x) <= cmaxseq u n x` ASSUME_TAC THENL
   [MATCH_MP_TAC CMAXSEQ_GE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n:num` o check (is_forall o concl)) THEN
  ASM_REAL_ARITH_TAC);;

(* cmaxseq is absolutely integrable on s if each u i is (finite max + abs).  *)
let CMAXSEQ_ABSINT = prove
 (`!(u:num->real->real) s n.
     (!i. (u i) absolutely_real_integrable_on s)
     ==> (cmaxseq u n) absolutely_real_integrable_on s`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN DISCH_TAC THENL
   [SUBGOAL_THEN
     `cmaxseq (u:num->real->real) 0 = (\x. abs(u 0 x))` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; cmaxseq]; ALL_TAC] THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_ABS THEN ASM_REWRITE_TAC[ETA_AX];
    SUBGOAL_THEN
     `cmaxseq (u:num->real->real) (SUC n) = (\x. max (cmaxseq u n x) (abs(u
       (SUC n) x)))`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; cmaxseq]; ALL_TAC] THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_MAX THEN CONJ_TAC THENL
     [REWRITE_TAC[ETA_AX] THEN ASM_SIMP_TAC[];
      MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_ABS THEN
        ASM_REWRITE_TAC[ETA_AX]]]);;

(* Monotone convergence for the finite maxima: if each u i is absolutely     *)
(* integrable on s, |u i| is bounded by B on s, and the integrals of cmaxseq *)
(* are bounded by C, then the pointwise sup sup_j |u j x| is integrable and  *)
(* int_s (cmaxseq u n) --> int_s (sup).                                      *)
(* (REAL_MONOTONE_CONVERGENCE_INCREASING)                                    *)
let CMAXSEQ_MCT = prove
 (`!(u:num->real->real) s B C.
     (!i. (u i) absolutely_real_integrable_on s) /\
     (!i x. x IN s ==> abs(u i x) <= B) /\
     (!n. real_integral s (cmaxseq u n) <= C)
     ==> (\x. sup {abs(u j x) | j IN (:num)}) real_integrable_on s /\
         ((\n. real_integral s (cmaxseq u n)) --->
          real_integral s (\x. sup {abs(u j x) | j IN (:num)})) sequentially`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC REAL_MONOTONE_CONVERGENCE_INCREASING THEN
  REPEAT CONJ_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
    ASM_SIMP_TAC[CMAXSEQ_ABSINT];
    REPEAT STRIP_TAC THEN MATCH_ACCEPT_TAC CMAXSEQ_INCREASING;
    REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN
      MATCH_MP_TAC CMAXSEQ_LIMIT_SUP THEN
    EXISTS_TAC `B:real` THEN ASM_SIMP_TAC[];
    REWRITE_TAC[real_bounded; FORALL_IN_GSPEC; IN_UNIV] THEN
    EXISTS_TAC `C:real` THEN X_GEN_TAC `k:num` THEN
    SUBGOAL_THEN
      `&0 <= real_integral s (cmaxseq (u:num->real->real) k)` MP_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_POS THEN CONJ_TAC THENL
       [MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
        ASM_SIMP_TAC[CMAXSEQ_ABSINT];
        REPEAT STRIP_TAC THEN REWRITE_TAC[CMAXSEQ_POS]];
      FIRST_X_ASSUM(MP_TAC o SPEC `k:num` o check(is_forall o concl)) THEN
      REAL_ARITH_TAC]]);;

(* The usable 256Mb bound: if every finite-max integral is <= C, then the    *)
(* integral of the pointwise sup (the maximal function) is <= C. This is     *)
(* what                                                                      *)
(* 286P consumes -- bound each finite max via 286N, conclude int_F Ah <= C.  *)
let CMAXSEQ_SUP_INTEGRAL_LE = prove
 (`!(u:num->real->real) s B C.
     (!i. (u i) absolutely_real_integrable_on s) /\
     (!i x. x IN s ==> abs(u i x) <= B) /\
     (!n. real_integral s (cmaxseq u n) <= C)
     ==> real_integral s (\x. sup {abs(u j x) | j IN (:num)}) <= C`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`u:num->real->real`; `s:real->bool`; `B:real`;
    `C:real`] CMAXSEQ_MCT) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPEC `sequentially` REALLIM_LE) THEN
  MAP_EVERY EXISTS_TAC
   [`\n. real_integral s (cmaxseq (u:num->real->real) n)`;
    `\n:num. C:real`] THEN
  ASM_REWRITE_TAC[REALLIM_CONST; TRIVIAL_LIMIT_SEQUENTIALLY] THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
  ASM_SIMP_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Fremlin 256M countable reduction: for a family {g i | i IN t} of          *)
(* x-continuous functions,                                                   *)
(* pointwise bounded above, the uncountable pointwise sup sup_{i in t} g i x *)
(* equals sup_{i in j} g i x for a COUNTABLE j SUBSET t.  This is exactly    *)
(* Fremlin's step "there is a countable Psi SUBSET Phi with g = sup Psi":    *)
(* continuity makes each superlevel {g i > a} open, so {sup > a} is an open  *)
(* union that a countable subcover (LINDELOF = 2nd-countability of R, the    *)
(* abstract form of Fremlin's rational boxes) captures; collecting over the  *)
(* countable rational thresholds yields the single countable index set.      *)
(* Combined with CMAXSEQ_SUP_INTEGRAL_LE (which supplies                     *)
(* Fremlin's running-max B.Levi step), this gives the 256Mb integral bound   *)
(* WITHOUT any upper-integral machinery.                                     *)
(* ------------------------------------------------------------------------- *)

(* Real-line Lindelof: any family of real_open sets has a countable          *)
(* subfamily with the same union (transported from the R^1 topological       *)
(* LINDELOF).                                                                *)
let CM_REAL_LINDELOF = prove
 (`!f:(real->bool)->bool.
     (!s. s IN f ==> real_open s)
     ==> ?f'. f' SUBSET f /\ COUNTABLE f' /\ UNIONS f' = UNIONS f`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `IMAGE (IMAGE lift) (f:(real->bool)->bool)` LINDELOF) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `s:real->bool` THEN
    DISCH_TAC THEN REWRITE_TAC[GSYM REAL_OPEN] THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:(real^1->bool)->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `IMAGE (IMAGE drop) (g:(real^1->bool)->bool)` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN X_GEN_TAC `t:real^1->bool` THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
      `(t:real^1->bool) IN IMAGE (IMAGE lift) (f:(real->bool)->bool)`
     MP_TAC THENL [ASM SET_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:real->bool` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
      `IMAGE drop (t:real^1->bool) = s` (fun th -> ASM_REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID];
    MATCH_MP_TAC COUNTABLE_IMAGE THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[GSYM IMAGE_UNIONS] THEN
    REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID] THEN
    REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID]]);;

(* Superlevel set of an everywhere-continuous real function is real_open.    *)
let CM_REAL_OPEN_SUPERLEVEL_CONTINUOUS = prove
 (`!g:real->real a. (!x. g real_continuous atreal x) ==> real_open {y | g y >
   a}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_OPEN; OPEN_CONTAINS_BALL] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM] THEN X_GEN_TAC `y:real` THEN
  DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN
  REWRITE_TAC[real_continuous_atreal] THEN
  DISCH_THEN(fun th -> MP_TAC(SPEC `(g:real->real) y - a` th)) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `d:real` THEN ASM_REWRITE_TAC[SUBSET; IN_BALL] THEN
  REWRITE_TAC[IN_IMAGE; IN_ELIM_THM] THEN
  X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN EXISTS_TAC `drop z` THEN
  REWRITE_TAC[LIFT_DROP] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `drop z`) THEN
  SUBGOAL_THEN `abs(drop z - y) < d` (fun th -> SIMP_TAC[th]) THENL
   [FIRST_X_ASSUM MP_TAC THEN REWRITE_TAC[DIST_1; LIFT_DROP] THEN
     REAL_ARITH_TAC;
    REWRITE_TAC[real_gt] THEN ASM_REAL_ARITH_TAC]);;

(* Indexed Lindelof: an index set t of real_open sets u i has a countable    *)
(* sub-index set j with the same union.                                      *)
let CM_LINDELOF_INDEXED = prove
 (`!(u:A->real->bool) t.
     (!i. i IN t ==> real_open (u i))
     ==> ?j. j SUBSET t /\ COUNTABLE j /\
             UNIONS {u i | i IN j} = UNIONS {u i | i IN t}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `{(u:A->real->bool) i | i IN t}` CM_REAL_LINDELOF) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[FORALL_IN_GSPEC] THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `f':(real->bool)->bool` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
    `?pick. !s. s IN f' ==> pick s IN t /\ (u:A->real->bool)(pick s) = s`
   STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[GSYM SKOLEM_THM] THEN X_GEN_TAC `s:real->bool` THEN
    ASM_CASES_TAC `(s:real->bool) IN f'` THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `s:real->bool` o
        GEN_REWRITE_RULE I [SUBSET]) THEN
      ASM_REWRITE_TAC[IN_ELIM_THM] THEN MESON_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `IMAGE (pick:(real->bool)->A) f'` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN ASM_SIMP_TAC[];
    MATCH_MP_TAC COUNTABLE_IMAGE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{(u:A->real->bool) i | i IN IMAGE pick f'} = f'`
   (fun th -> ASM_REWRITE_TAC[th]) THEN
  REWRITE_TAC[SIMPLE_IMAGE; GSYM IMAGE_o] THEN
  SUBGOAL_THEN
    `IMAGE ((u:A->real->bool) o (pick:(real->bool)->A)) f' = IMAGE (\s. s) f'`
   (fun th -> REWRITE_TAC[th; IMAGE_ID]) THEN
  MATCH_MP_TAC IMAGE_EQ THEN X_GEN_TAC `s:real->bool` THEN DISCH_TAC THEN
  REWRITE_TAC[o_THM] THEN ASM_SIMP_TAC[]);;

(* Cover-to-sup bridge (rational thresholds): if j SUBSET t is nonempty, the *)
(* family is pointwise bounded above at x, and for every RATIONAL a the      *)
(* superlevels {g i > a} over j and over t have equal union, then the sups   *)
(* at x                                                                      *)
(* agree.  (Rational a suffices: the refutation uses a rational strictly     *)
(* between sup_j and g i x from RATIONAL_BETWEEN.)                           *)
let CM_COVER_SUP_EQ_RAT = prove
 (`!(g:A->real->real) t j x.
     j SUBSET t /\ ~(j = {}) /\
     (?B. !i. i IN t ==> g i x <= B) /\
     (!a. rational a
          ==> UNIONS {{y | (g:A->real->real) i y > a} | i IN j} =
              UNIONS {{y | g i y > a} | i IN t})
     ==> sup {g i x | i IN t} = sup {g i x | i IN j}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[GSYM REAL_LE_ANTISYM] THEN
  FIRST_X_ASSUM(LABEL_TAC "cover" o
    check(fun th -> is_forall(concl th) &&
                    (let b = snd(dest_forall(concl th)) in is_imp b &&
                     (is_eq(snd(dest_imp b)))))) THEN
  CONJ_TAC THENL
   [ALL_TAC;
    MATCH_MP_TAC REAL_SUP_LE_SUBSET THEN REPEAT CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
      FIRST_X_ASSUM(X_CHOOSE_TAC `i0:A` o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY])
        THEN
      REWRITE_TAC[IN_ELIM_THM] THEN ASM_MESON_TAC[];
      REWRITE_TAC[SUBSET; FORALL_IN_GSPEC; IN_ELIM_THM] THEN
      X_GEN_TAC `i:A` THEN DISCH_TAC THEN EXISTS_TAC `i:A` THEN ASM SET_TAC[];
      EXISTS_TAC `B:real` THEN REWRITE_TAC[FORALL_IN_GSPEC] THEN
        ASM_SIMP_TAC[]]] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
     ASM SET_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `S = sup {(g:A->real->real) i x | i IN j}` THEN
  SUBGOAL_THEN `!i'. i' IN j ==> (g:A->real->real) i' x <= S`
   (LABEL_TAC "bnd") THENL
   [EXPAND_TAC "S" THEN
    X_GEN_TAC `i':A` THEN DISCH_TAC THEN MATCH_MP_TAC REAL_LE_SUP THEN
    MAP_EVERY EXISTS_TAC [`B:real`; `(g:A->real->real) i' x`] THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `i':A` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_LE_REFL];
      REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `i'':A` THEN DISCH_TAC THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM SET_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[FORALL_IN_GSPEC] THEN
  X_GEN_TAC `i:A` THEN DISCH_TAC THEN
  GEN_REWRITE_TAC I [GSYM REAL_NOT_LT] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`S:real`; `(g:A->real->real) i x`] RATIONAL_BETWEEN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:real` STRIP_ASSUME_TAC) THEN
  REMOVE_THEN "cover" (MP_TAC o SPEC `a:real`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[EXTENSION] THEN DISCH_THEN(MP_TAC o SPEC `x:real`) THEN
  REWRITE_TAC[IN_UNIONS; EXISTS_IN_GSPEC; IN_ELIM_THM] THEN
  MATCH_MP_TAC(TAUT `(q /\ ~p) ==> ~(p <=> q)`) THEN CONJ_TAC THENL
   [EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[real_gt];
    REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `i'':A` THEN
    REWRITE_TAC[DE_MORGAN_THM; real_gt; REAL_NOT_LT] THEN
    ASM_CASES_TAC `(i'':A) IN j` THENL
     [DISJ2_TAC THEN
      SUBGOAL_THEN `(g:A->real->real) i'' x <= S`
       (fun th -> MP_TAC th THEN ASM_REAL_ARITH_TAC) THEN
      USE_THEN "bnd" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]]);;

(* MAIN 256M countable reduction: a pointwise-bounded family of x-continuous *)
(* functions has a COUNTABLE sub-index set realising the same pointwise sup  *)
(* everywhere.                                                               *)
let CM_MEASURABLE_SUP_COUNTABLE_REDUCTION = prove
 (`!(g:A->real->real) t.
     (!i. i IN t ==> (!x. (g i) real_continuous atreal x)) /\
     (!x. ?B. !i. i IN t ==> g i x <= B) /\ ~(t = {})
     ==> ?j. j SUBSET t /\ COUNTABLE j /\ ~(j = {}) /\
             (!x. sup {g i x | i IN t} = sup {g i x | i IN j})`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!a:real. ?ja. ja SUBSET t /\ COUNTABLE ja /\
        UNIONS {{y | (g:A->real->real) i y > a} | i IN ja} =
        UNIONS {{y | g i y > a} | i IN t}`
   (fun th -> MP_TAC(REWRITE_RULE[SKOLEM_THM] th)) THENL
   [X_GEN_TAC `a:real` THEN
    MP_TAC(ISPECL [`\i:A. {x | (g:A->real->real) i x > a}`; `t:A->bool`]
      CM_LINDELOF_INDEXED) THEN
    REWRITE_TAC[] THEN ANTS_TAC THENL
     [X_GEN_TAC `i:A` THEN DISCH_TAC THEN
      MATCH_MP_TAC CM_REAL_OPEN_SUPERLEVEL_CONTINUOUS THEN
      GEN_TAC THEN REWRITE_TAC[ETA_AX] THEN ASM_SIMP_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `ja:A->bool` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `ja:A->bool` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `J:real->A->bool` (LABEL_TAC "J")) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `i0:A` o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
  ABBREV_TAC `j = (i0:A) INSERT (UNIONS {(J:real->A->bool) q | rational q})`
    THEN
  SUBGOAL_THEN `(j:A->bool) SUBSET t` (LABEL_TAC "jsub") THENL
   [EXPAND_TAC "j" THEN REWRITE_TAC[INSERT_SUBSET] THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REWRITE_TAC[UNIONS_SUBSET; FORALL_IN_GSPEC] THEN
      X_GEN_TAC `q:real` THEN DISCH_TAC THEN
      USE_THEN "J" (MP_TAC o SPEC `q:real`) THEN SIMP_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `j:A->bool` THEN ASM_REWRITE_TAC[] THEN
  REPEAT(CONJ_TAC THENL
   [EXPAND_TAC "j" THEN REWRITE_TAC[COUNTABLE_INSERT] THEN
    MATCH_MP_TAC COUNTABLE_UNIONS THEN CONJ_TAC THENL
     [SUBGOAL_THEN
       `{(J:real->A->bool) q | rational q} = IMAGE J {q | rational q}`
       SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_IMAGE] THEN
         MESON_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC COUNTABLE_IMAGE THEN
      MP_TAC COUNTABLE_RATIONAL THEN MATCH_MP_TAC EQ_IMP THEN
      AP_TERM_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN];
      REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `q:real` THEN DISCH_TAC THEN
      USE_THEN "J" (MP_TAC o SPEC `q:real`) THEN SIMP_TAC[]];
    ALL_TAC]) THEN
  CONJ_TAC THENL
   [EXPAND_TAC "j" THEN REWRITE_TAC[NOT_INSERT_EMPTY]; ALL_TAC] THEN
  X_GEN_TAC `x:real` THEN
  MATCH_MP_TAC CM_COVER_SUP_EQ_RAT THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    EXPAND_TAC "j" THEN REWRITE_TAC[NOT_INSERT_EMPTY];
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `a:real` THEN DISCH_TAC THEN
  REWRITE_TAC[EXTENSION; IN_UNIONS; EXISTS_IN_GSPEC; IN_ELIM_THM] THEN
  X_GEN_TAC `x':real` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `i:A` STRIP_ASSUME_TAC) THEN EXISTS_TAC `i:A` THEN
    ASM_REWRITE_TAC[] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[SUBSET]) THEN ASM_MESON_TAC[];
    DISCH_TAC THEN
    USE_THEN "J" (MP_TAC o SPEC `a:real`) THEN
    DISCH_THEN(MP_TAC o CONJUNCT2 o CONJUNCT2) THEN
    REWRITE_TAC[EXTENSION; IN_UNIONS; EXISTS_IN_GSPEC; IN_ELIM_THM] THEN
    DISCH_THEN(MP_TAC o SPEC `x':real`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `i:A` STRIP_ASSUME_TAC) THEN EXISTS_TAC `i:A` THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "j" THEN
    REWRITE_TAC[IN_INSERT; IN_UNIONS; IN_ELIM_THM] THEN DISJ2_TAC THEN
    EXISTS_TAC `(J:real->A->bool) a` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `a:real` THEN ASM_REWRITE_TAC[]]);;


(* ========================================================================= *)
(* Fremlin 282: complex-exponential Fourier series on the circle. This       *)
(* supplies the two facts                                                    *)
(* Fremlin 286O(b) consumes: 282Rb (absolute summability sum_n |c_n(g)| <    *)
(* inf for C^2 periodic g) and 282L (pointwise inversion                     *)
(* sum c_n e^{int} --> g).                                                   *)
(* Here c_n(g) = (1/2pi) int_{-pi}^{pi} g e^{-int}, complex-valued.          *)
(*                                                                           *)
(* This layer uses complex cfourier_coeff / cfourier_partial / periodize,    *)
(* specialized to the tile theory.                                           *)
(* ========================================================================= *)

(* Complex Fourier coefficient of g on [-pi,pi]: c_n = (1/2pi) int g         *)
(* e^{-int}.                                                                 *)
let cfourier_coeff = new_definition
 `cfourier_coeff (g:real->complex) (n:int) =
    Cx(inv(&2 * pi)) * integral (IMAGE lift (real_interval[--pi,pi]))
      (\t. g(drop t) * cexp(--(ii * Cx(real_of_int n) * Cx(drop t))))`;;

(* Two-sided symmetric partial sum S_N g (t) = sum over abs n <= N of c_n    *)
(* e^int.                                                                    *)
let cfourier_partial = new_definition
 `cfourier_partial (g:real->complex) (N:num) (t:real) =
    vsum {n:int | abs n <= &N}
      (\n. cfourier_coeff g n * cexp(ii * Cx(real_of_int n) * Cx t))`;;

(* The symmetric index set {n : |n| <= N} is finite.                         *)
let CFOURIER_INDEX_FINITE = prove
 (`!N:num. FINITE {n:int | abs n <= &N}`,
  GEN_TAC THEN REWRITE_TAC[INT_ABS_LE; GSYM CONJ_ASSOC] THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `{n:int | --(&N) <= n /\ n <= &N}` THEN
  REWRITE_TAC[FINITE_INT_SEG] THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
  INT_ARITH_TAC);;

(* Boundary values of the kernel agree at +-pi (both are (-1)^n), because    *)
(* the difference of exponents is 2 pi n i with n an integer                 *)
(* (CEXP_INTEGER_2PI).                                                       *)
let CEXP_BOUNDARY_PERIODIC = prove
 (`!n:int. cexp(--(ii * Cx(real_of_int n) * Cx pi)) =
           cexp(--(ii * Cx(real_of_int n) * Cx(--pi)))`,
  GEN_TAC THEN
  MP_TAC(ISPEC `real_of_int n` CEXP_INTEGER_2PI) THEN
  REWRITE_TAC[INTEGER_REAL_OF_INT] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `--(ii * Cx(real_of_int n) * Cx(--pi)) =
    --(ii * Cx(real_of_int n) * Cx pi) + Cx(&2 * real_of_int n * pi) * ii`
   SUBST1_TAC THENL
   [REWRITE_TAC[CX_NEG; CX_MUL] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  REWRITE_TAC[CEXP_ADD] THEN ASM_REWRITE_TAC[] THEN CONV_TAC COMPLEX_RING);;

(* 282(deriv): for a C^1 periodic g, the Fourier coefficient of g' is        *)
(* i n c_n(g).  Integration by parts (FOURIER_IBP_FINITE); the boundary term *)
(* g(pi)e^{-in pi} - g(-pi)e^{in pi} vanishes by periodicity +               *)
(* CEXP_BOUNDARY_                                                            *)
(* PERIODIC.  Iterating this twice gives c_n(g'') = -n^2 c_n(g), the decay   *)
(* estimate behind absolute summability (282Rb).                             *)
let CFOURIER_COEFF_DERIV = prove
 (`!(g:real->complex) g' n.
     (!x. ((\z. g(drop z)) has_vector_derivative (g' x)) (at(lift x))) /\
     (\z. cexp(--(ii * Cx(real_of_int n) * Cx(drop z))) * g'(drop z))
        integrable_on interval[lift(--pi),lift pi] /\
     g(pi) = g(--pi)
     ==> cfourier_coeff g' n = ii * Cx(real_of_int n) * cfourier_coeff g n`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[cfourier_coeff; IMAGE_LIFT_REAL_INTERVAL] THEN
  SUBGOAL_THEN
   `integral (interval[lift(--pi),lift pi])
      (\t. (g':real->complex)(drop t) * cexp(--(ii * Cx(real_of_int n) *
        Cx(drop t)))) =
    integral (interval[lift(--pi),lift pi])
      (\t. cexp(--(ii * Cx(real_of_int n) * Cx(drop t))) *
        (g':real->complex)(drop t)) /\
    integral (interval[lift(--pi),lift pi])
      (\t. (g:real->complex)(drop t) * cexp(--(ii * Cx(real_of_int n) * Cx(drop
        t)))) =
    integral (interval[lift(--pi),lift pi])
      (\t. cexp(--(ii * Cx(real_of_int n) * Cx(drop t))) *
        (g:real->complex)(drop t))`
   (CONJUNCTS_THEN SUBST1_TAC) THENL
   [CONJ_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
    GEN_TAC THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  MP_TAC(ISPECL [`g:real->complex`; `g':real->complex`; `real_of_int n`; `pi`]
    FOURIER_IBP_FINITE) THEN
  ASM_SIMP_TAC[REAL_LT_IMP_LE; PI_POS] THEN DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[CEXP_BOUNDARY_PERIODIC] THEN CONV_TAC COMPLEX_RING);;

(* 282(deriv2): c_n(g'') = -n^2 c_n(g), iterating CFOURIER_COEFF_DERIV       *)
(* twice.                                                                    *)
let CFOURIER_COEFF_DERIV2 = prove
 (`!(g:real->complex) g' g'' n.
     (!x. ((\z. g(drop z)) has_vector_derivative (g' x)) (at(lift x))) /\
     (!x. ((\z. g'(drop z)) has_vector_derivative (g'' x)) (at(lift x))) /\
     (\z. cexp(--(ii * Cx(real_of_int n) * Cx(drop z))) * g'(drop z))
        integrable_on interval[lift(--pi),lift pi] /\
     (\z. cexp(--(ii * Cx(real_of_int n) * Cx(drop z))) * g''(drop z))
        integrable_on interval[lift(--pi),lift pi] /\
     g(pi) = g(--pi) /\ g'(pi) = g'(--pi)
     ==> cfourier_coeff g'' n =
         --(Cx(real_of_int n) pow 2) * cfourier_coeff g n`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`g':real->complex`; `g'':real->complex`;
    `n:int`] CFOURIER_COEFF_DERIV) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`g:real->complex`; `g':real->complex`;
    `n:int`] CFOURIER_COEFF_DERIV) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_RING `ii * n * ii * n * c = --(n pow 2) * c`]);;

(* The modulation kernel e^{-int} is measurable on [-pi,pi] (continuous).    *)
let CEXP_KERNEL_MEASURABLE_INTERVAL = prove
 (`!n. (\t:real^1. cexp(--(ii * Cx(real_of_int n) * Cx(drop t))))
       measurable_on interval[lift(--pi),lift pi]`,
  GEN_TAC THEN MATCH_MP_TAC MEASURABLE_ON_MEASURABLE_SUBSET THEN
  EXISTS_TAC `(:real^1)` THEN REWRITE_TAC[SUBSET_UNIV] THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    SUBGOAL_THEN
     `(\t:real^1. cexp(--(ii * Cx(real_of_int n) * Cx(drop t)))) =
      cexp o (\t. --((ii * Cx(real_of_int n)) * Cx(drop t)))`
     SUBST1_TAC THENL [REWRITE_TAC[o_DEF; COMPLEX_MUL_ASSOC]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_CEXP] THEN
    MATCH_MP_TAC CONTINUOUS_ON_NEG THEN
      MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
      MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN
    REWRITE_TAC[CONTINUOUS_ON_ID];
    REWRITE_TAC[MEASURABLE_INTERVAL]]);;

(* The modulation kernel has modulus 1.                                      *)
let CFOURIER_KERNEL_NORM = prove
 (`!n:int t. norm(cexp(--(ii * Cx(real_of_int n) * Cx t))) = &1`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
    `--(ii * Cx(real_of_int n) * Cx t) = ii * Cx(--(real_of_int n * t))`
    SUBST1_TAC THENL
   [REWRITE_TAC[CX_NEG; CX_MUL] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  REWRITE_TAC[NORM_CEXP_II]);;

(* g absolutely integrable ==> g * (modulation kernel) absolutely integrable *)
(* (bounded-measurable x abs-integrable,                                     *)
(* ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_ PRODUCT after commuting to      *)
(* kernel-first order).                                                      *)
let CFOURIER_INTEGRAND_ABSINT = prove
 (`!(g:real->complex) n.
     (\t. g(drop t)) absolutely_integrable_on interval[lift(--pi),lift pi]
     ==> (\t:real^1. g(drop t) * cexp(--(ii * Cx(real_of_int n) * Cx(drop t))))
      absolutely_integrable_on interval[lift(--pi),lift pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\t:real^1. g(drop t) * cexp(--(ii * Cx(real_of_int n) * Cx(drop t)))) =
    (\t:real^1. cexp(--(ii * Cx(real_of_int n) * Cx(drop t))) * g(drop t))`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  MP_TAC(ISPECL [`( * ):complex->complex->complex`;
                 `\t:real^1. cexp(--(ii * Cx(real_of_int n) * Cx(drop t)))`;
                 `\t:real^1. (g:real->complex)(drop t)`;
                 `interval[lift(--pi),lift pi]`]
    ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT) THEN
  REWRITE_TAC[BILINEAR_COMPLEX_MUL] THEN
  DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[CEXP_KERNEL_MEASURABLE_INTERVAL];
    REWRITE_TAC[bounded; FORALL_IN_IMAGE] THEN EXISTS_TAC `&1` THEN
    X_GEN_TAC `t:real^1` THEN DISCH_TAC THEN
      REWRITE_TAC[CFOURIER_KERNEL_NORM; REAL_LE_REFL];
    ASM_REWRITE_TAC[]]);;

(* 282(bound): |c_n(g)| <= (1/2pi) int_{-pi}^{pi} |g|, uniformly in n. The   *)
(* kernel                                                                    *)
(* has modulus 1, so norm-of-integral <= integral-of-norm = int|g|.          *)
let CFOURIER_COEFF_L1_BOUND = prove
 (`!(g:real->complex) n.
     (\t. g(drop t)) absolutely_integrable_on interval[lift(--pi),lift pi]
     ==> norm(cfourier_coeff g n)
         <= inv(&2 * pi) * drop(integral (interval[lift(--pi),lift pi]) (\t.
           lift(norm(g(drop t)))))`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[cfourier_coeff; IMAGE_LIFT_REAL_INTERVAL] THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `abs(inv(&2 * pi)) = inv(&2 * pi)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_INV; REAL_ABS_REFL] THEN
    MATCH_MP_TAC REAL_LE_INV THEN MP_TAC PI_POS THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_INV THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\t:real^1. g(drop t) * cexp(--(ii * Cx(real_of_int n) * Cx(drop t)))`;
    `interval[lift(--pi),lift pi]`] ABSOLUTELY_INTEGRABLE_LE) THEN
  ASM_SIMP_TAC[CFOURIER_INTEGRAND_ABSINT] THEN
  MATCH_MP_TAC(REAL_ARITH `a = b ==> x <= a ==> x <= b`) THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
  AP_TERM_TAC THEN REWRITE_TAC[COMPLEX_NORM_MUL; CFOURIER_KERNEL_NORM] THEN
    REAL_ARITH_TAC);;

(* 282Rb(decay): n^2 |c_n(g)| <= (1/2pi) int|g''|, for C^2 periodic g.  From *)
(* c_n(g'') = -n^2 c_n(g) (DERIV2) + the uniform L^1 bound at g''            *)
(* (L1_BOUND). This                                                          *)
(* is the O(1/n^2) decay that yields absolute summability of the             *)
(* coefficients.                                                             *)
let CFOURIER_COEFF_DECAY = prove
 (`!(g:real->complex) g' g'' n.
     (!x. ((\z. g(drop z)) has_vector_derivative (g' x)) (at(lift x))) /\
     (!x. ((\z. g'(drop z)) has_vector_derivative (g'' x)) (at(lift x))) /\
     (\z. cexp(--(ii * Cx(real_of_int n) * Cx(drop z))) * g'(drop z))
        integrable_on interval[lift(--pi),lift pi] /\
     (\z. cexp(--(ii * Cx(real_of_int n) * Cx(drop z))) * g''(drop z))
        integrable_on interval[lift(--pi),lift pi] /\
     (\t. g''(drop t)) absolutely_integrable_on interval[lift(--pi),lift pi] /\
     g(pi) = g(--pi) /\ g'(pi) = g'(--pi)
     ==> (real_of_int n) pow 2 * norm(cfourier_coeff g n)
         <= inv(&2 * pi) * drop(integral (interval[lift(--pi),lift pi]) (\t.
           lift(norm(g''(drop t)))))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`g:real->complex`; `g':real->complex`; `g'':real->complex`;
    `n:int`]
    CFOURIER_COEFF_DERIV2) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`g'':real->complex`; `n:int`] CFOURIER_COEFF_L1_BOUND) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(REAL_ARITH `a = b ==> b <= c ==> a <= c`) THEN
  ASM_REWRITE_TAC[COMPLEX_NORM_MUL; NORM_NEG; COMPLEX_NORM_POW;
    COMPLEX_NORM_CX] THEN
  REWRITE_TAC[REAL_POW2_ABS]);;

(* Arithmetic helper: kk>0 /\ kk*N<=M ==> N<=M/kk. Applied via MATCH_MP_TAC  *)
(* so                                                                        *)
(* the concrete M is inferred from the goal, dodging any type-annotation     *)
(* mismatch.                                                                 *)
let CFOURIER_DECAY_ARITH = prove
 (`!(N:real) M kk. &0 < kk /\ kk * N <= M ==> N <= M * inv kk`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[GSYM real_div; REAL_LE_RDIV_EQ] THEN
  ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN ASM_REWRITE_TAC[]);;

(* 282Rb: for C^2 periodic g, the Fourier-coefficient tail sum_{k>=1}        *)
(* |c_{idx k}(g)| converges, for any integer index family idx with           *)
(* |idx k| = k (covers both the k and -k tails). Comparison of               *)
(* |c_n| <= (M/n^2) [DECAY, M = (1/2pi)int|g''|] to the zeta sum sum 1/k^2   *)
(* (REAL_SUMMABLE_ZETA_INTEGER, m=2); the index enters only through n^2 =    *)
(* k^2.                                                                      *)
let CFOURIER_COEFF_SUMMABLE_GEN = prove
 (`!(g:real->complex) (g':real->complex) (g'':real->complex) (idx:num->int).
     (!x. ((\z. g(drop z)) has_vector_derivative (g' x)) (at(lift x))) /\
     (!x. ((\z. g'(drop z)) has_vector_derivative (g'' x)) (at(lift x))) /\
     (!n. (\z. cexp(--(ii * Cx(real_of_int n) * Cx(drop z))) * g'(drop z))
        integrable_on interval[lift(--pi),lift pi]) /\
     (!n. (\z. cexp(--(ii * Cx(real_of_int n) * Cx(drop z))) * g''(drop z))
        integrable_on interval[lift(--pi),lift pi]) /\
     (\t. g''(drop t)) absolutely_integrable_on interval[lift(--pi),lift pi] /\
     g(pi) = g(--pi) /\ g'(pi) = g'(--pi) /\
     (!k. (real_of_int(idx k)) pow 2 = (&k:real) pow 2)
     ==> real_summable (from 1) (\k. norm(cfourier_coeff g (idx k)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC REAL_SUMMABLE_COMPARISON THEN
  EXISTS_TAC `\k. (inv(&2 * pi) * drop(integral (interval[lift(--pi),lift pi])
    (\t. lift(norm((g'':real->complex)(drop t)))))) * inv(&k pow 2)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_SUMMABLE_LMUL THEN
    MP_TAC(ISPECL [`1`; `2`] REAL_SUMMABLE_ZETA_INTEGER) THEN
      REWRITE_TAC[ARITH];
    EXISTS_TAC `1` THEN X_GEN_TAC `k:num` THEN REWRITE_TAC[IN_FROM] THEN
      STRIP_TAC THEN
    REWRITE_TAC[REAL_ABS_NORM] THEN
    MATCH_MP_TAC CFOURIER_DECAY_ARITH THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_POW_LT THEN REWRITE_TAC[REAL_OF_NUM_LT] THEN
       ASM_ARITH_TAC;
      MP_TAC(ISPECL [`g:real->complex`; `g':real->complex`;
        `g'':real->complex`;
        `(idx:num->int) k`] CFOURIER_COEFF_DECAY) THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(fun th -> REWRITE_TAC[SPEC `k:num` th])]]);;

(* ========================================================================= *)
(* Schwartz + compact support => both Fourier coefficient tails summable.    *)
(* This packages 282Rb (CFOURIER_COEFF_SUMMABLE_GEN) for the common case     *)
(* of a Schwartz function supported inside (-pi,pi): the C^2 chain, the      *)
(* integrability of the modulated derivatives, and the periodicity           *)
(* g(pi)=g(-pi), g'(pi)=g'(-pi) (both = 0 since g vanishes on R < |x| with   *)
(* R < pi) are all automatic.  Used for the tile base g of 286O(b).          *)
(* ========================================================================= *)

(* The modulation e^{-int} times a Schwartz function is integrable on any    *)
(* compact interval, being continuous there (product of the continuous       *)
(* kernel e^{-int} and the continuous Schwartz factor).                      *)
let CEXP_SCHWARTZ_INTEGRABLE_INTERVAL = prove
 (`!(w:real->complex) (n:int).
     schwartz w
     ==> (\z. cexp(--(ii * Cx(real_of_int n) * Cx(drop z))) * w(drop z))
         integrable_on interval[lift(--pi),lift pi]`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC INTEGRABLE_CONTINUOUS THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\z:real^1. cexp(--(ii * Cx(real_of_int n) * Cx(drop z)))) =
      cexp o (\t. --((ii * Cx(real_of_int n)) * Cx(drop t)))`
     SUBST1_TAC THENL [REWRITE_TAC[o_DEF; COMPLEX_MUL_ASSOC]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_CEXP] THEN
    MATCH_MP_TAC CONTINUOUS_ON_NEG THEN
      MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
      MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN
    REWRITE_TAC[CONTINUOUS_ON_ID];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    REWRITE_TAC[SUBSET_UNIV] THEN MATCH_MP_TAC SCHWARTZ_CONT THEN
      ASM_REWRITE_TAC[]]);;

(* 282Rb for a compactly-supported Schwartz function, index-agnostic core:   *)
(* the C^2 chain, modulated-derivative integrability, and periodicity        *)
(* g(pi)=g(-pi), g'(pi)=g'(-pi) (both 0, as g vanishes for |x| > R, R < pi)  *)
(* are all automatic; feed them + the |idx k| = k side condition to          *)
(* CFOURIER_COEFF_SUMMABLE_GEN.                                              *)
let SCHWARTZ_CSUPP_SUMMABLE_GEN = prove
 (`!(g:real->complex) R (idx:num->int).
     schwartz g /\ &0 <= R /\ R < pi /\ (!x. R < abs x ==> g x = Cx(&0)) /\
     (!k. (real_of_int(idx k)) pow 2 = (&k:real) pow 2)
     ==> real_summable (from 1) (\k. norm(cfourier_coeff g (idx k)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_THEN `d:num->real->complex` STRIP_ASSUME_TAC o
    MATCH_MP SCHWARTZ_CHAIN_ALL) THEN
  FIRST_ASSUM(LABEL_TAC "der" o check (fun th ->
    can (term_match [] `!n x. ((\z. (dd:num->real->complex) n (drop z))
       has_vector_derivative dd (SUC n) x)(at(lift x))`) (concl th))) THEN
  SUBGOAL_THEN
    `!n x. R < abs x ==> (d:num->real->complex) n x = Cx(&0)` ASSUME_TAC THENL
   [MATCH_MP_TAC CHAIN_SUPPORT THEN ASM_REWRITE_TAC[real_gt] THEN
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `abs pi = pi /\ abs(--pi) = pi` STRIP_ASSUME_TAC THENL
   [MP_TAC PI_POS THEN REWRITE_TAC[REAL_ABS_NEG] THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(!n. (d:num->real->complex) n pi = Cx(&0)) /\
                (!n. (d:num->real->complex) n (--pi) = Cx(&0))`
                  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN GEN_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
     ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC CFOURIER_COEFF_SUMMABLE_GEN THEN
  MAP_EVERY EXISTS_TAC [`(d:num->real->complex) 1`;
    `(d:num->real->complex) 2`] THEN
  FIRST_X_ASSUM(fun th -> if concl th = `(d:num->real->complex) 0 = g` then
     SUBST1_TAC(SYM th) else NO_TAC) THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "der" (fun th -> GEN_TAC THEN
     MP_TAC(SPECL [`0`; `x:real`] th)) THEN
    REWRITE_TAC[ARITH_RULE `SUC 0 = 1`];
    USE_THEN "der" (fun th -> GEN_TAC THEN
      MP_TAC(SPECL [`1`; `x:real`] th)) THEN
    REWRITE_TAC[ARITH_RULE `SUC 1 = 2`];
    GEN_TAC THEN MATCH_MP_TAC CEXP_SCHWARTZ_INTEGRABLE_INTERVAL THEN
    REWRITE_TAC[ETA_AX] THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN MATCH_MP_TAC CEXP_SCHWARTZ_INTEGRABLE_INTERVAL THEN
    REWRITE_TAC[ETA_AX] THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `(:real^1)` THEN REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC SCHWARTZ_ABSINT THEN REWRITE_TAC[ETA_AX] THEN
      ASM_REWRITE_TAC[]]);;

(* The two tails as named corollaries (idx = &k and idx = -- &k).            *)
let SCHWARTZ_CSUPP_SUMMABLE_POS = prove
 (`!(g:real->complex) R.
     schwartz g /\ &0 <= R /\ R < pi /\ (!x. R < abs x ==> g x = Cx(&0))
     ==> real_summable (from 1) (\k. norm(cfourier_coeff g (&k)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`g:real->complex`; `R:real`; `\k:num. &k:int`]
    SCHWARTZ_CSUPP_SUMMABLE_GEN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  GEN_TAC THEN REWRITE_TAC[int_of_num_th]);;

let SCHWARTZ_CSUPP_SUMMABLE_NEG = prove
 (`!(g:real->complex) R.
     schwartz g /\ &0 <= R /\ R < pi /\ (!x. R < abs x ==> g x = Cx(&0))
     ==> real_summable (from 1) (\k. norm(cfourier_coeff g (-- &k)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`g:real->complex`; `R:real`; `\k:num. -- &k:int`]
    SCHWARTZ_CSUPP_SUMMABLE_GEN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  GEN_TAC THEN
  REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES; int_neg_th; int_of_num_th] THEN
  REWRITE_TAC[REAL_POW2_ABS; REAL_ABS_NEG; REAL_ABS_NUM] THEN
    CONV_TAC REAL_RING);;

(* ========================================================================= *)
(* 282L pointwise inversion, part 1: the complex symmetric Dirichlet sum.    *)
(* sum over abs n <= N of e^{inu} = 2 D_N(u), D_N = 100/fourier.ml's         *)
(* Dirichlet                                                                 *)
(* kernel. Route: split the symmetric integer segment, pair e^{iku}+e^{-iku} *)
(* = 2 cos(ku), and match DIRICHLET_KERNEL_COSINE_SUM (1/2 + sum cos).       *)
(* ========================================================================= *)

(* The symmetric integer segment splits as {0} together with the images of   *)
(* 1..N under k|->k and k|->-k.                                              *)
let INT_ABS_SEG_SPLIT = prove
 (`!N:num. {j:int | abs j <= &N} =
           (&0) INSERT (IMAGE (\k. &k) (1..N) UNION IMAGE (\k. -- &k) (1..N))`,
  GEN_TAC THEN
    REWRITE_TAC[EXTENSION; IN_INSERT; IN_UNION; IN_IMAGE; IN_ELIM_THM;
    IN_NUMSEG] THEN
  X_GEN_TAC `j:int` THEN EQ_TAC THENL
   [DISCH_TAC THEN
    DISJ_CASES_TAC(SPEC `j:int` INT_IMAGE) THEN
    POP_ASSUM(X_CHOOSE_THEN `m:num` ASSUME_TAC) THEN
    ASM_CASES_TAC `m = 0` THEN
    TRY(FIRST_X_ASSUM SUBST_ALL_TAC) THENL
     [DISJ1_TAC THEN ASM_REWRITE_TAC[INT_NEG_0];
      DISJ2_TAC THEN DISJ1_TAC THEN EXISTS_TAC `m:num` THEN
      REPEAT(POP_ASSUM MP_TAC) THEN
      REWRITE_TAC[INT_ABS_NUM; INT_OF_NUM_LE] THEN ASM_ARITH_TAC;
      DISJ1_TAC THEN ASM_REWRITE_TAC[INT_NEG_0];
      DISJ2_TAC THEN DISJ2_TAC THEN EXISTS_TAC `m:num` THEN
      REPEAT(POP_ASSUM MP_TAC) THEN
      REWRITE_TAC[INT_ABS_NEG; INT_ABS_NUM; INT_OF_NUM_LE] THEN ASM_ARITH_TAC];
    STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
     [INT_ARITH_TAC;
      REWRITE_TAC[INT_ABS_NUM; INT_OF_NUM_LE] THEN ASM_ARITH_TAC;
      REWRITE_TAC[INT_ABS_NEG; INT_ABS_NUM; INT_OF_NUM_LE] THEN
        ASM_ARITH_TAC]]);;

(* Reindex a real sum over the image of 1..N under k|->&k / k|->-&k to a nat *)
(* sum.                                                                      *)
let SUM_IMAGE_POS = prove
 (`!(ff:int->real) N. sum (IMAGE (\k. &k) (1..N)) ff = sum (1..N) (\k.
   ff(&k))`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`\k:num. &k:int`; `ff:int->real`; `1..N`] SUM_IMAGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[INT_OF_NUM_EQ] THEN SIMP_TAC[];
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]]);;

let SUM_IMAGE_NEG = prove
 (`!(ff:int->real) N. sum (IMAGE (\k. -- &k) (1..N)) ff = sum (1..N) (\k. ff(--
   &k))`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`\k:num. -- &k:int`; `ff:int->real`; `1..N`] SUM_IMAGE) THEN
  ANTS_TAC THENL
   [REPEAT GEN_TAC THEN CONV_TAC(DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[INT_NEG_EQ; INT_NEG_NEG; INT_OF_NUM_EQ]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]]);;

(* The sum of |c_n| over abs n <= N split into the 0 term and two nat tails  *)
(* 1..N.                                                                     *)
let CFOURIER_ABSSEG_SUM_SPLIT = prove
 (`!(g:real->complex) N.
    sum {n:int | abs n <= &N} (\n. norm(cfourier_coeff g n)) =
    norm(cfourier_coeff g (&0)) +
    sum (1..N) (\k. norm(cfourier_coeff g (&k))) +
    sum (1..N) (\k. norm(cfourier_coeff g (-- &k)))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[INT_ABS_SEG_SPLIT] THEN
  SIMP_TAC[SUM_CLAUSES; FINITE_INSERT; FINITE_UNION; FINITE_IMAGE;
    FINITE_NUMSEG] THEN
  COND_CASES_TAC THENL
   [FIRST_X_ASSUM(MP_TAC) THEN
    REWRITE_TAC[IN_UNION; IN_IMAGE; IN_NUMSEG] THEN
    REWRITE_TAC[INT_ARITH `&0 = &x <=> &x = &0`;
      INT_ARITH `&0 = -- &x <=> &x = &0`] THEN
    REWRITE_TAC[INT_OF_NUM_EQ] THEN
    DISCH_THEN(DISJ_CASES_THEN (X_CHOOSE_THEN `x:num` STRIP_ASSUME_TAC)) THEN
      ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT (IMAGE (\k. &k) (1..N):int->bool) (IMAGE (\k. -- &k) (1..N))`
   ASSUME_TAC THENL
   [REWRITE_TAC[SET_RULE `DISJOINT s t <=> !x. x IN s ==> ~(x IN t)`] THEN
    REWRITE_TAC[FORALL_IN_IMAGE; IN_IMAGE; IN_NUMSEG] THEN
    REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `(&1:int) <= &x /\ (&0:int) <= &x''` MP_TAC THENL
     [REWRITE_TAC[INT_OF_NUM_LE] THEN ASM_ARITH_TAC; ASM_INT_ARITH_TAC];
    ALL_TAC] THEN
  ASM_SIMP_TAC[SUM_UNION; FINITE_IMAGE; FINITE_NUMSEG] THEN
  REWRITE_TAC[SUM_IMAGE_POS; SUM_IMAGE_NEG] THEN REAL_ARITH_TAC);;

(* For a nonnegative summable nat-series, every finite initial sum <= the    *)
(* infsum.                                                                   *)
let SUM_NUMSEG_LE_INFSUM = prove
 (`!f:num->real N. real_summable (from 1) f /\ (!i. &0 <= f i)
    ==> sum (1..N) f <= real_infsum (from 1) f`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:num->real`; `from 1`;
    `N:num`] REAL_PARTIAL_SUMS_LE_INFSUM) THEN
  ASM_REWRITE_TAC[FROM_INTER_NUMSEG]);;

(* Uniform (in N and t) bound on the Fourier partial sum, given both         *)
(* coefficient                                                               *)
(* tails absolutely summable: |cfourier_partial g N t| <= |c_0| +            *)
(* sum_{k>=1}|c_k|                                                           *)
(* + sum_{k>=1}|c_{-k}|. This fixed bound is the dominator for the L^2       *)
(* dominated                                                                 *)
(* convergence of the tile partial sums in the 286O(b) spatial identity.     *)
let CFOURIER_PARTIAL_UNIF_BOUND = prove
 (`!(g:real->complex).
     real_summable (from 1) (\k. norm(cfourier_coeff g (&k))) /\
     real_summable (from 1) (\k. norm(cfourier_coeff g (-- &k)))
     ==> !N t. norm(cfourier_partial g N t) <=
               norm(cfourier_coeff g (&0)) +
               real_infsum (from 1) (\k. norm(cfourier_coeff g (&k))) +
               real_infsum (from 1) (\k. norm(cfourier_coeff g (-- &k)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cfourier_partial] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum {n:int | abs n <= &N} (\n. norm(cfourier_coeff g n))` THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`\n:int. cfourier_coeff g n * cexp(ii * Cx(real_of_int n) *
     Cx t)`;
                   `{n:int | abs n <= &N}`] VSUM_NORM) THEN
    REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN
    MATCH_MP_TAC(REAL_ARITH `s = s2 ==> x <= s ==> x <= s2`) THEN
    MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `n:int` THEN DISCH_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL] THEN
    SUBGOAL_THEN
      `cexp(ii * Cx(real_of_int n) * Cx t) = cexp(ii * Cx(real_of_int n * t))`
     SUBST1_TAC THENL
     [AP_TERM_TAC THEN REWRITE_TAC[CX_MUL] THEN
       CONV_TAC COMPLEX_RING; ALL_TAC] THEN
    REWRITE_TAC[NORM_CEXP_II; REAL_MUL_RID];
    ALL_TAC] THEN
  REWRITE_TAC[CFOURIER_ABSSEG_SUM_SPLIT] THEN
  MATCH_MP_TAC REAL_LE_ADD2 THEN REWRITE_TAC[REAL_LE_REFL] THEN
  MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THEN
  MATCH_MP_TAC SUM_NUMSEG_LE_INFSUM THEN ASM_REWRITE_TAC[NORM_POS_LE]);;

(* e^{iz} + e^{-iz} = 2 cos z (complex form).                                *)
let CEXP_PAIR_COS = prove
 (`!z. cexp(ii * z) + cexp(--(ii * z)) = Cx(&2) * ccos z`,
  GEN_TAC THEN REWRITE_TAC[CEXP_EULER] THEN
  REWRITE_TAC[COMPLEX_RING `--(ii * z) = ii * (--z)`] THEN
  REWRITE_TAC[CEXP_EULER; CCOS_NEG; CSIN_NEG] THEN CONV_TAC COMPLEX_RING);;

(* 282L(a): the symmetric complex Dirichlet sum equals 2 D_N (sin(u/2)<>0,   *)
(* abs u < 2 pi -- both hold at the interior points |u|<=1/4 where 286O(b)   *)
(* applies it).                                                              *)
let CFOURIER_DIRICHLET_SUM = prove
 (`!N u. ~(sin(u / &2) = &0) /\ abs u < &2 * pi
         ==> vsum {n:int | abs n <= &N} (\n. cexp(ii * Cx(real_of_int n) * Cx
           u)) =
             Cx(&2 * dirichlet_kernel N u)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[INT_ABS_SEG_SPLIT] THEN
  SUBGOAL_THEN
    `~((&0:int) IN (IMAGE (\k. &k:int) (1..N) UNION IMAGE (\k:num. -- &k:int)
    (1..N)))`
   ASSUME_TAC THENL
   [REWRITE_TAC[IN_UNION; IN_IMAGE; IN_NUMSEG] THEN
    REWRITE_TAC[INT_ARITH `(&0:int) = &k <=> &k:int = &0`;
                INT_ARITH `(&0:int) = -- &k <=> &k:int = &0`] THEN
    REWRITE_TAC[INT_OF_NUM_EQ; NOT_EXISTS_THM] THEN GEN_TAC THEN
      ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[VSUM_CLAUSES; FINITE_UNION; FINITE_IMAGE; FINITE_NUMSEG] THEN
  SUBGOAL_THEN `cexp(ii * Cx(real_of_int(&0)) * Cx u) = Cx(&1)`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[int_of_num_th; COMPLEX_RING `ii * Cx(&0) * Cx u = Cx(&0)`;
     CEXP_0]; ALL_TAC] THEN
  SUBGOAL_THEN
    `DISJOINT (IMAGE (\k. &k:int) (1..N)) (IMAGE (\k:num. -- &k:int) (1..N))`
   ASSUME_TAC THENL
   [REWRITE_TAC[SET_RULE `DISJOINT s t <=> !x. x IN s ==> ~(x IN t)`] THEN
    REWRITE_TAC[IN_IMAGE; IN_NUMSEG] THEN
    X_GEN_TAC `j:int` THEN DISCH_THEN(X_CHOOSE_THEN
      `a:num` STRIP_ASSUME_TAC) THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `b:num` THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[DE_MORGAN_THM] THEN DISJ1_TAC THEN
    UNDISCH_TAC `1 <= a` THEN REWRITE_TAC[GSYM INT_OF_NUM_LE] THEN
      INT_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[VSUM_UNION; FINITE_IMAGE; FINITE_NUMSEG] THEN
  MP_TAC(ISPECL [`\k. &k:int`; `\n:int. cexp(ii * Cx(real_of_int n) * Cx u)`;
    `1..N`] VSUM_IMAGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[FINITE_NUMSEG; IN_NUMSEG] THEN REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o AP_TERM `real_of_int`) THEN
    REWRITE_TAC[int_of_num_th; REAL_OF_NUM_EQ] THEN SIMP_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`\k:num. -- &k:int`;
    `\n:int. cexp(ii * Cx(real_of_int n) * Cx u)`; `1..N`] VSUM_IMAGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[FINITE_NUMSEG; IN_NUMSEG] THEN REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o AP_TERM `(--):int->int`) THEN
      REWRITE_TAC[INT_NEG_NEG] THEN
    DISCH_THEN(MP_TAC o AP_TERM `real_of_int`) THEN
    REWRITE_TAC[int_of_num_th; REAL_OF_NUM_EQ] THEN SIMP_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[o_DEF; int_of_num_th; int_neg_th] THEN
  SUBGOAL_THEN
   `vsum (1..N) (\k. cexp(ii * Cx(&k) * Cx u)) +
    vsum (1..N) (\x. cexp(ii * Cx(--(&x)) * Cx u)) =
    vsum (1..N) (\k. Cx(&2 * cos(&k * u)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM VSUM_ADD_NUMSEG] THEN MATCH_MP_TAC VSUM_EQ_NUMSEG THEN
    X_GEN_TAC `k:num` THEN STRIP_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN
      `ii * Cx(--(&k)) * Cx u = --(ii * Cx(&k * u))` SUBST1_TAC THENL
     [REWRITE_TAC[CX_NEG; CX_MUL] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
    SUBGOAL_THEN `ii * Cx(&k) * Cx u = ii * Cx(&k * u)` SUBST1_TAC THENL
     [REWRITE_TAC[CX_MUL] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
    REWRITE_TAC[CEXP_PAIR_COS; GSYM CX_COS; CX_MUL]; ALL_TAC] THEN
  SUBGOAL_THEN `dirichlet_kernel N u = &1 / &2 + sum(1..N) (\k. cos(&k * u))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC DIRICHLET_KERNEL_COSINE_SUM THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN UNDISCH_TAC `~(sin(u / &2) = &0)` THEN
    ASM_REWRITE_TAC[REAL_ARITH `&0 / &2 = &0`; SIN_0]; ALL_TAC] THEN
  ASM_REWRITE_TAC[VSUM_CX_NUMSEG; GSYM CX_ADD; CX_INJ; SUM_LMUL] THEN
    REAL_ARITH_TAC);;

(* ========================================================================= *)
(* 282L part 2: the partial sum as a Dirichlet-kernel convolution.           *)
(* ========================================================================= *)

(* Per-term: c_n(g) e^{int} = (1/2pi) int_{-pi}^{pi} g(z) e^{in(t-z)} dz.    *)
let CFOURIER_TERM_CONV = prove
 (`!(g:real->complex) n t.
     (\z. g(drop z)) absolutely_integrable_on interval[lift(--pi),lift pi]
     ==> cfourier_coeff g n * cexp(ii * Cx(real_of_int n) * Cx t) =
         Cx(inv(&2 * pi)) *
         integral (interval[lift(--pi),lift pi])
           (\z. g(drop z) * cexp(ii * Cx(real_of_int n) * Cx(t - drop z)))`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[cfourier_coeff; IMAGE_LIFT_REAL_INTERVAL] THEN
  REWRITE_TAC[GSYM COMPLEX_MUL_ASSOC] THEN AP_TERM_TAC THEN
  ONCE_REWRITE_TAC[COMPLEX_MUL_SYM] THEN
  SUBGOAL_THEN
   `(\z. g(drop z) * cexp(--(ii * Cx(real_of_int n) * Cx(drop z))))
     integrable_on
    interval[lift(--pi),lift pi]`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC CFOURIER_INTEGRAND_ABSINT THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM INTEGRAL_COMPLEX_LMUL] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN
  REWRITE_TAC[COMPLEX_RING `e * (g * f) = g * (e * f)`] THEN
  GEN_REWRITE_TAC RAND_CONV [COMPLEX_MUL_SYM] THEN
  AP_TERM_TAC THEN
  REWRITE_TAC[GSYM CEXP_ADD] THEN AP_TERM_TAC THEN
  REWRITE_TAC[CX_SUB] THEN CONV_TAC COMPLEX_RING);;

(* Integrability of the convolution integrand g(z) e^{in(t-z)} = e^{int}(g   *)
(* e^{-inz}).                                                                *)
let CFOURIER_CONV_INTEGRAND = prove
 (`!(g:real->complex) n t.
     (\z. g(drop z)) absolutely_integrable_on interval[lift(--pi),lift pi]
     ==> (\z. g(drop z) * cexp(ii * Cx(real_of_int n) * Cx(t - drop z)))
       integrable_on
         interval[lift(--pi),lift pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. g(drop z) * cexp(ii * Cx(real_of_int n) * Cx(t - drop z))) =
    (\z. cexp(ii * Cx(real_of_int n) * Cx t) *
         (g(drop z) * cexp(--(ii * Cx(real_of_int n) * Cx(drop z)))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[COMPLEX_RING `e * (g * f) = g * (e * f)`] THEN
    AP_TERM_TAC THEN REWRITE_TAC[GSYM CEXP_ADD] THEN AP_TERM_TAC THEN
    REWRITE_TAC[CX_SUB] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC CFOURIER_INTEGRAND_ABSINT THEN ASM_REWRITE_TAC[]);;

(* 282L(b): cfourier_partial g N t = (1/2pi) int g(z) (sum_{abs n<=N}        *)
(* e^{in(t-z)}) dz.                                                          *)
let CFOURIER_PARTIAL_CONV = prove
 (`!(g:real->complex) N t.
     (\z. g(drop z)) absolutely_integrable_on interval[lift(--pi),lift pi]
     ==> cfourier_partial g N t =
         Cx(inv(&2 * pi)) *
         integral (interval[lift(--pi),lift pi])
           (\z. g(drop z) *
                vsum {n:int | abs n <= &N} (\n. cexp(ii * Cx(real_of_int n) *
                  Cx(t - drop z))))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cfourier_partial] THEN
  SUBGOAL_THEN
   `vsum {n:int | abs n <= &N} (\n. cfourier_coeff g n * cexp(ii *
     Cx(real_of_int n) * Cx t)) =
    vsum {n:int | abs n <= &N}
      (\n. Cx(inv(&2 * pi)) *
           integral (interval[lift(--pi),lift pi])
             (\z. g(drop z) * cexp(ii * Cx(real_of_int n) * Cx(t - drop z))))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `n:int` THEN DISCH_TAC THEN
     REWRITE_TAC[] THEN
    MATCH_MP_TAC CFOURIER_TERM_CONV THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SIMP_TAC[VSUM_COMPLEX_LMUL; CFOURIER_INDEX_FINITE] THEN AP_TERM_TAC THEN
  SUBGOAL_THEN
   `!z. g(drop z) *
        vsum {n:int | abs n <= &N} (\n. cexp(ii * Cx(real_of_int n) * Cx(t -
          drop z))) =
        vsum {n:int | abs n <= &N} (\n. g(drop z) * cexp(ii * Cx(real_of_int n)
          * Cx(t - drop z)))`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN
     SIMP_TAC[VSUM_COMPLEX_LMUL; CFOURIER_INDEX_FINITE]; ALL_TAC] THEN
  CONV_TAC SYM_CONV THEN
  MP_TAC(ISPECL
   [`\n:int z:real^1. g(drop z) * cexp(ii * Cx(real_of_int n) * Cx(t - drop
     z))`;
    `interval[lift(--pi),lift pi]`;
    `{n:int | abs n <= &N}`] INTEGRAL_VSUM) THEN
  REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN
  ANTS_TAC THENL
   [X_GEN_TAC `n:int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC CFOURIER_CONV_INTEGRAND THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* ========================================================================= *)
(* 282L part 3a: collapse the convolution to the Dirichlet kernel.           *)
(* ========================================================================= *)

(* z |-> D_N(t - z) is real-continuous on [-pi,pi] (image in (-2pi,2pi),     *)
(* where dirichlet_kernel is continuous), provided abs t < pi.               *)
let DN_SHIFT_CONTINUOUS = prove
 (`!N t. abs t < pi
         ==> (\z. dirichlet_kernel N (t - z)) real_continuous_on
           real_interval[--pi,pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z. dirichlet_kernel N (t - z)) = (dirichlet_kernel N) o (\z. t - z)`
   SUBST1_TAC THENL [REWRITE_TAC[o_DEF]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_CONTINUOUS_ON_SUB THEN
    REWRITE_TAC[REAL_CONTINUOUS_ON_CONST; REAL_CONTINUOUS_ON_ID];
    MATCH_MP_TAC REAL_CONTINUOUS_ON_SUBSET THEN
    EXISTS_TAC `real_interval(--(&2 * pi), &2 * pi)` THEN
    REWRITE_TAC[DIRICHLET_KERNEL_CONTINUOUS_STRONG] THEN
    REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_REAL_INTERVAL] THEN
    GEN_TAC THEN STRIP_TAC THEN MP_TAC PI_POS THEN ASM_REAL_ARITH_TAC]);;

(* g absint /\ abs t < pi ==> g(z) Cx(D_N(t-z)) integrable on [-pi,pi].      *)
(* (Cx(D_N(t-.)) continuous hence bounded-measurable; g absint; product      *)
(* absint.)                                                                  *)
let CFOURIER_DN_INTEGRAND = prove
 (`!(g:real->complex) N t.
     (\z. g(drop z)) absolutely_integrable_on interval[lift(--pi),lift pi] /\
       abs t < pi
     ==> (\z. g(drop z) * Cx(dirichlet_kernel N (t - drop z))) integrable_on
         interval[lift(--pi),lift pi]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  SUBGOAL_THEN
   `(\z. g(drop z) * Cx(dirichlet_kernel N (t - drop z))) =
    (\z. Cx(dirichlet_kernel N (t - drop z)) * g(drop z))`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\z:real^1. Cx(dirichlet_kernel N (t - drop z))) continuous_on
     interval[lift(--pi),lift pi]`
   ASSUME_TAC THENL
   [REWRITE_TAC[CONTINUOUS_ON_CX_LIFT] THEN
    MP_TAC(ISPECL [`N:num`; `t:real`] DN_SHIFT_CONTINUOUS) THEN
      ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[REAL_CONTINUOUS_ON; IMAGE_LIFT_REAL_INTERVAL; o_DEF];
      ALL_TAC] THEN
  MP_TAC(ISPECL [`( * ):complex->complex->complex`;
                 `\z:real^1. Cx(dirichlet_kernel N (t - drop z))`;
                 `\z:real^1. (g:real->complex)(drop z)`;
                 `interval[lift(--pi),lift pi]`]
    ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT) THEN
  REWRITE_TAC[BILINEAR_COMPLEX_MUL] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
    ASM_REWRITE_TAC[LEBESGUE_MEASURABLE_INTERVAL];
    MATCH_MP_TAC COMPACT_IMP_BOUNDED THEN
    MATCH_MP_TAC COMPACT_CONTINUOUS_IMAGE THEN
    ASM_REWRITE_TAC[COMPACT_INTERVAL];
    ASM_REWRITE_TAC[]]);;

(* 282L(c): cfourier_partial g N t = (1/pi) int_{-pi}^{pi} g(z) D_N(t-z) dz, *)
(* the classical Dirichlet convolution (abs t < pi).  Combine PARTIAL_CONV + *)
(* the keystone (inner sum = 2 D_N off the measure-zero point z=t) +         *)
(* inv2pi*2 =                                                                *)
(* inv pi.                                                                   *)
let CFOURIER_PARTIAL_DIRICHLET = prove
 (`!(g:real->complex) N t.
     (\z. g(drop z)) absolutely_integrable_on interval[lift(--pi),lift pi] /\
       abs t < pi
     ==> cfourier_partial g N t =
         Cx(inv pi) *
         integral (interval[lift(--pi),lift pi])
           (\z. g(drop z) * Cx(dirichlet_kernel N (t - drop z)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`g:real->complex`; `N:num`;
    `t:real`] CFOURIER_PARTIAL_CONV) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `integral (interval[lift(--pi),lift pi])
      (\z. g(drop z) *
           vsum {n:int | abs n <= &N} (\n. cexp(ii * Cx(real_of_int n) * Cx(t -
             drop z)))) =
    integral (interval[lift(--pi),lift pi])
      (\z. g(drop z) * Cx(&2 * dirichlet_kernel N (t - drop z)))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC INTEGRAL_SPIKE THEN EXISTS_TAC `{lift t}` THEN
    REWRITE_TAC[NEGLIGIBLE_SING] THEN X_GEN_TAC `z:real^1` THEN
    REWRITE_TAC[IN_DIFF; IN_SING; IN_INTERVAL_1; LIFT_DROP] THEN STRIP_TAC THEN
    AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC CFOURIER_DIRICHLET_SUM THEN
    CONJ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `drop(z:real^1) = t` ASSUME_TAC THENL
       [MP_TAC(ISPEC `(t - drop z) / &2` SIN_EQ_0_PI) THEN
        ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN ASM_REAL_ARITH_TAC;
        UNDISCH_TAC `~(z = lift t)` THEN REWRITE_TAC[] THEN
          ASM_MESON_TAC[LIFT_DROP]];
      ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `integral (interval[lift(--pi),lift pi])
      (\z. g(drop z) * Cx(&2 * dirichlet_kernel N (t - drop z))) =
    Cx(&2) * integral (interval[lift(--pi),lift pi])
      (\z. g(drop z) * Cx(dirichlet_kernel N (t - drop z)))`
   SUBST1_TAC THENL
   [SUBGOAL_THEN
     `(\z:real^1. g(drop z) * Cx(&2 * dirichlet_kernel N (t - drop z))) =
      (\z. Cx(&2) * (g(drop z) * Cx(dirichlet_kernel N (t - drop z))))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[CX_MUL] THEN
       CONV_TAC COMPLEX_RING;
      ALL_TAC] THEN
    MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
    MATCH_MP_TAC CFOURIER_DN_INTEGRAND THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
  MP_TAC PI_POS THEN CONV_TAC REAL_FIELD);;

(* ========================================================================= *)
(* 282L part 3b: reflection helpers toward the convergence limit.            *)
(* (The full convergence cfourier_partial g N t -> g(t) is the remaining     *)
(* step; these symmetric-interval reflections are reusable building blocks.) *)
(* ========================================================================= *)

(* Reflection on the symmetric interval [-pi,pi] (real-valued).              *)
let REAL_INTEGRAL_REFLECT_SYM = prove
 (`!(ff:real->real). real_integral (real_interval[--pi,pi]) (\z. ff(--z)) =
                     real_integral (real_interval[--pi,pi]) ff`,
  GEN_TAC THEN
  MP_TAC(ISPECL [`ff:real->real`; `--pi`; `pi`] REAL_INTEGRAL_REFLECT) THEN
  REWRITE_TAC[REAL_NEG_NEG] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* Reflection on the symmetric real^1 interval [lift(-pi),lift pi]           *)
(* (complex-valued).                                                         *)
let INTEGRAL_REFLECT_SYM_1 = prove
 (`!(ff:real^1->complex).
     integral (interval[lift(--pi),lift pi]) (\z. ff(--z)) =
     integral (interval[lift(--pi),lift pi]) ff`,
  GEN_TAC THEN
  MP_TAC(ISPECL [`ff:real^1->complex`; `lift(--pi)`;
    `lift pi`] INTEGRAL_REFLECT) THEN
  REWRITE_TAC[VECTOR_NEG_NEG; LIFT_NEG]);;

(* ========================================================================= *)
(* 282L part 3b (coefficient-bridge route): toward cfourier_partial -> g.    *)
(* ========================================================================= *)

(* cnj commutes with a complex integral (cnj is linear).                     *)
let CNJ_INTEGRAL = prove
 (`!(f:real^N->complex) s. f integrable_on s
     ==> cnj(integral s f) = integral s (\x. cnj(f x))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real^N->complex`; `s:real^N->bool`;
    `cnj`] INTEGRAL_LINEAR) THEN
  ASM_REWRITE_TAC[LINEAR_CNJ; o_DEF] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[]);;

(* For a real function phi, c_{-n} = conj(c_n): the Fourier coefficients are *)
(* conjugate-symmetric.  (This makes the +-n pairing real, matching the real *)
(* trigonometric partial sum.)                                               *)
let CFOURIER_COEFF_CONJ = prove
 (`!(phi:real->real) n.
     (\t. Cx(phi(drop t))) absolutely_integrable_on interval[lift(--pi),lift
       pi]
     ==> cnj(cfourier_coeff (\x. Cx(phi x)) n) = cfourier_coeff (\x. Cx(phi x))
       (--n)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cfourier_coeff] THEN
  REWRITE_TAC[CNJ_MUL; CNJ_CX] THEN
  REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
  MP_TAC(ISPECL
   [`\t:real^1. Cx(phi(drop t)) * cexp(--(ii * Cx(real_of_int n) * Cx(drop
     t)))`;
    `interval[lift(--pi),lift pi]`] CNJ_INTEGRAL) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MP_TAC(ISPEC `(\x. Cx(phi x)):real->complex` CFOURIER_INTEGRAND_ABSINT)
      THEN
    DISCH_THEN(MP_TAC o SPEC `n:int`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
  REWRITE_TAC[CNJ_MUL; CNJ_CX; CNJ_CEXP] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[CNJ_NEG; CNJ_MUL; CNJ_II; CNJ_CX; int_neg_th; CX_NEG] THEN
  CONV_TAC COMPLEX_RING);;

(* Symmetric-sum reorganization: cfourier_partial g N t = c_0 term + the     *)
(* paired                                                                    *)
(* +-k terms for k=1..N. (Same INT_ABS_SEG_SPLIT decomposition as the        *)
(* Dirichlet                                                                 *)
(* sum keystone.)  Feeds the real-trigonometric bridge for real g.           *)
let CFOURIER_PARTIAL_SPLIT = prove
 (`!(g:real->complex) N t.
     cfourier_partial g N t =
     cfourier_coeff g (&0) +
     vsum (1..N) (\k. cfourier_coeff g (&k) * cexp(ii * Cx(&k) * Cx t) +
                      cfourier_coeff g (-- &k) * cexp(ii * Cx(-- &k) * Cx t))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cfourier_partial; INT_ABS_SEG_SPLIT] THEN
  SUBGOAL_THEN
    `~((&0:int) IN (IMAGE (\k. &k:int) (1..N) UNION IMAGE (\k:num. -- &k:int)
    (1..N)))`
   ASSUME_TAC THENL
   [REWRITE_TAC[IN_UNION; IN_IMAGE; IN_NUMSEG] THEN
    REWRITE_TAC[INT_ARITH `(&0:int) = &k <=> &k:int = &0`;
                INT_ARITH `(&0:int) = -- &k <=> &k:int = &0`] THEN
    REWRITE_TAC[INT_OF_NUM_EQ; NOT_EXISTS_THM] THEN GEN_TAC THEN
      ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[VSUM_CLAUSES; FINITE_UNION; FINITE_IMAGE; FINITE_NUMSEG] THEN
  BINOP_TAC THENL
   [REWRITE_TAC[int_of_num_th; COMPLEX_RING `ii * Cx(&0) * Cx t = Cx(&0)`;
     CEXP_0] THEN
    REWRITE_TAC[COMPLEX_MUL_RID]; ALL_TAC] THEN
  SUBGOAL_THEN
    `DISJOINT (IMAGE (\k. &k:int) (1..N)) (IMAGE (\k:num. -- &k:int) (1..N))`
   ASSUME_TAC THENL
   [REWRITE_TAC[SET_RULE `DISJOINT s t <=> !x. x IN s ==> ~(x IN t)`] THEN
    REWRITE_TAC[IN_IMAGE; IN_NUMSEG] THEN
    X_GEN_TAC `j:int` THEN DISCH_THEN(X_CHOOSE_THEN
      `a:num` STRIP_ASSUME_TAC) THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `b:num` THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[DE_MORGAN_THM] THEN DISJ1_TAC THEN
    UNDISCH_TAC `1 <= a` THEN REWRITE_TAC[GSYM INT_OF_NUM_LE] THEN
      INT_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[VSUM_UNION; FINITE_IMAGE; FINITE_NUMSEG] THEN
  MP_TAC(ISPECL [`\k. &k:int`;
    `\n:int. cfourier_coeff g n * cexp(ii * Cx(real_of_int n) * Cx t)`;
    `1..N`] VSUM_IMAGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[FINITE_NUMSEG; IN_NUMSEG] THEN REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o AP_TERM `real_of_int`) THEN
    REWRITE_TAC[int_of_num_th; REAL_OF_NUM_EQ] THEN SIMP_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`\k:num. -- &k:int`;
    `\n:int. cfourier_coeff g n * cexp(ii * Cx(real_of_int n) * Cx t)`;
    `1..N`] VSUM_IMAGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[FINITE_NUMSEG; IN_NUMSEG] THEN REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o AP_TERM `(--):int->int`) THEN
      REWRITE_TAC[INT_NEG_NEG] THEN
    DISCH_THEN(MP_TAC o AP_TERM `real_of_int`) THEN
    REWRITE_TAC[int_of_num_th; REAL_OF_NUM_EQ] THEN SIMP_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[o_DEF; int_of_num_th; int_neg_th] THEN
  REWRITE_TAC[GSYM VSUM_ADD_NUMSEG]);;

(* Re commutes with a complex integral (component 1).                        *)
let RE_INTEGRAL = prove
 (`!(ff:real^1->complex) s. ff integrable_on s
     ==> Re(integral s ff) = drop(integral s (\z. lift(Re(ff z))))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[RE_DEF] THEN
  ASM_SIMP_TAC[INTEGRAL_COMPONENT]);;

(* Paired +-k terms collapse to twice the real part (conjugate symmetry for  *)
(* real phi): c_k e^{ikt} + c_{-k} e^{-ikt} = Cx(2 Re(c_k e^{ikt})).         *)
let CFOURIER_PAIR_RE = prove
 (`!(phi:real->real) k t.
     (\z. Cx(phi(drop z))) absolutely_integrable_on interval[lift(--pi),lift
       pi]
     ==> cfourier_coeff (\x. Cx(phi x)) (&k) * cexp(ii * Cx(&k) * Cx t) +
         cfourier_coeff (\x. Cx(phi x)) (-- &k) * cexp(ii * Cx(-- &k) * Cx t) =
         Cx(&2 * Re(cfourier_coeff (\x. Cx(phi x)) (&k) * cexp(ii * Cx(&k) * Cx
           t)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`phi:real->real`; `&k:int`] CFOURIER_COEFF_CONJ) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[INT_NEG_NEG] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  SUBGOAL_THEN
   `cexp(ii * Cx(-- &k) * Cx t) = cnj(cexp(ii * Cx(&k) * Cx t))`
   SUBST1_TAC THENL
   [REWRITE_TAC[CNJ_CEXP] THEN AP_TERM_TAC THEN
    REWRITE_TAC[CNJ_MUL; CNJ_II; CNJ_CX; int_neg_th; CX_NEG] THEN
      CONV_TAC COMPLEX_RING;
    ALL_TAC] THEN
  REWRITE_TAC[GSYM CNJ_MUL] THEN
  REWRITE_TAC[COMPLEX_ADD_CNJ; GSYM CX_MUL] THEN
  REWRITE_TAC[COMPLEX_MUL_SYM]);;

(* ------------------------------------------------------------------------- *)
(* 282L convergence via ROUTE B (coefficient bridge to the classical         *)
(* real-trigonometric Fourier convergence in 100/fourier.ml).                *)
(*                                                                           *)
(* We show the complex-exponential partial sum of Cx o phi equals Cx of the  *)
(* real-trigonometric partial sum sum(0..2N) fc phi k * ts k t, then invoke  *)
(* DIFFERENTIABLE_FOURIER_CONVERGENCE_PERIODIC.  This avoids the             *)
(* dirichlet_kernel-periodicity wall (D_N is NOT exactly 2pi-periodic at     *)
(* sin(x/2)=0 points), which blocks the direct kernel-substitution route.    *)
(* ------------------------------------------------------------------------- *)

(* Re(cexp(ii r)) = cos r.                                                   *)
let RE_CEXP_II = prove
 (`!r. Re(cexp(ii * Cx r)) = cos r`,
  GEN_TAC THEN REWRITE_TAC[RE_CEXP; RE_MUL_II; IM_MUL_II; RE_CX; IM_CX] THEN
  REWRITE_TAC[REAL_NEG_0; REAL_EXP_0; REAL_MUL_LID]);;

(* c_k(phi) e^{ikt} = Cx(inv 2pi) * int(phi(z) cexp(ii k (t - z))): push the *)
(* modulation e^{ikt} into the coefficient integral (companion of            *)
(* CFOURIER_TERM_CONV but with a +ii exponent).                              *)
let CFOURIER_TERM_CONV_POS = prove
 (`!(phi:real->real) k t.
     (\z. Cx(phi(drop z))) absolutely_integrable_on interval[lift(--pi),lift
       pi]
     ==> cfourier_coeff (\x. Cx(phi x)) (&k) * cexp(ii * Cx(&k) * Cx t) =
         Cx(inv(&2 * pi)) *
         integral (interval[lift(--pi),lift pi])
           (\z. Cx(phi(drop z)) * cexp(ii * Cx(&k) * Cx(t - drop z)))`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[cfourier_coeff; IMAGE_LIFT_REAL_INTERVAL] THEN
  REWRITE_TAC[GSYM COMPLEX_MUL_ASSOC] THEN AP_TERM_TAC THEN
  ONCE_REWRITE_TAC[COMPLEX_MUL_SYM] THEN
  SUBGOAL_THEN
   `(\z. Cx(phi(drop z)) * cexp(--(ii * Cx(real_of_int(&k)) * Cx(drop z))))
     integrable_on
    interval[lift(--pi),lift pi]`
   ASSUME_TAC THENL
   [MP_TAC(ISPEC `(\x. Cx(phi x)):real->complex` CFOURIER_INTEGRAND_ABSINT)
     THEN
    DISCH_THEN(MP_TAC o SPEC `&k:int`) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE]; ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM INTEGRAL_COMPLEX_LMUL] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[int_of_num_th] THEN
  REWRITE_TAC[COMPLEX_RING `e * (p * f) = p * (e * f)`] THEN
  GEN_REWRITE_TAC RAND_CONV [COMPLEX_MUL_SYM] THEN AP_TERM_TAC THEN
  REWRITE_TAC[GSYM CEXP_ADD] THEN AP_TERM_TAC THEN
  REWRITE_TAC[CX_SUB] THEN CONV_TAC COMPLEX_RING);;

(* 2 Re(c_k e^{ikt}) = inv pi * int_{-pi}^{pi} phi(z) cos(k(t-z)) dz.        *)
let CFOURIER_PAIR_RE_COS = prove
 (`!(phi:real->real) k t.
     (\z. Cx(phi(drop z))) absolutely_integrable_on interval[lift(--pi),lift
       pi]
     ==> &2 * Re(cfourier_coeff (\x. Cx(phi x)) (&k) * cexp(ii * Cx(&k) * Cx
       t)) =
         inv pi *
         drop(integral (interval[lift(--pi),lift pi])
                (\z. lift(phi(drop z) * cos(&k * (t - drop z)))))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`phi:real->real`; `k:num`;
    `t:real`] CFOURIER_TERM_CONV_POS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[RE_MUL_CX; RE_CX] THEN
  SUBGOAL_THEN
   `(\z. Cx(phi(drop z)) * cexp(ii * Cx(&k) * Cx(t - drop z))) integrable_on
    interval[lift(--pi),lift pi]`
   ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(\z. Cx(phi(drop z)) * cexp(ii * Cx(&k) * Cx(t - drop z))) =
      (\z. cexp(ii * Cx(&k) * Cx t) *
           (Cx(phi(drop z)) * cexp(--(ii * Cx(real_of_int(&k)) * Cx(drop
             z)))))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; int_of_num_th] THEN GEN_TAC THEN
      REWRITE_TAC[COMPLEX_RING `e * (p * f) = p * (e * f)`] THEN
        AP_TERM_TAC THEN
      REWRITE_TAC[GSYM CEXP_ADD] THEN AP_TERM_TAC THEN
      REWRITE_TAC[CX_SUB] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
    MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN
    MP_TAC(ISPEC `(\x. Cx(phi x)):real->complex` CFOURIER_INTEGRAND_ABSINT)
      THEN
    DISCH_THEN(MP_TAC o SPEC `&k:int`) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE]; ALL_TAC] THEN
  ASM_SIMP_TAC[RE_INTEGRAL] THEN
  SUBGOAL_THEN `&2 * inv(&2 * pi) *
    drop(integral (interval[lift(--pi),lift pi])
      (\z. lift(Re(Cx(phi(drop z)) * cexp(ii * Cx(&k) * Cx(t - drop z)))))) =
    inv pi *
    drop(integral (interval[lift(--pi),lift pi])
      (\z. lift(Re(Cx(phi(drop z)) * cexp(ii * Cx(&k) * Cx(t - drop z))))))`
   SUBST1_TAC THENL
   [MP_TAC PI_POS THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN AP_TERM_TAC THEN
  REWRITE_TAC[RE_MUL_CX] THEN
  SUBGOAL_THEN
    `ii * Cx(&k) * Cx(t - drop z) =
     ii * Cx(&k * (t - drop z))` SUBST1_TAC THENL
   [REWRITE_TAC[CX_MUL] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  REWRITE_TAC[RE_CEXP_II]);;

(* phi abs-real-integrable ==> Cx o phi abs-integrable (linear embedding).   *)
let CX_PHI_ABSINT = prove
 (`!(phi:real->real). phi absolutely_real_integrable_on real_interval[--pi,pi]
     ==> (\z. Cx(phi(drop z))) absolutely_integrable_on
       interval[lift(--pi),lift pi]`,
  GEN_TAC THEN REWRITE_TAC[ABSOLUTELY_REAL_INTEGRABLE_ON] THEN
  REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(\z. Cx(phi(drop z))) = (\z:real^1. Cx(drop z)) o (lift o phi o drop)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_LINEAR THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[linear; DROP_ADD; DROP_CMUL; CX_ADD; CX_MUL] THEN
  REWRITE_TAC[COMPLEX_CMUL; CX_MUL] THEN CONV_TAC COMPLEX_RING);;

(* real_integral over [a,b] as the drop of the vector integral over          *)
(* lift[a,b].                                                                *)
let REAL_INTEGRAL_DROP_BRIDGE = prove
 (`!f a b. f real_integrable_on real_interval[a,b]
           ==> real_integral (real_interval[a,b]) f =
               drop(integral (interval[lift a,lift b]) (\z. lift(f(drop z))))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[REAL_INTEGRAL] THEN
  REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; o_DEF]);;

(* The real-trigonometric pair term: for k>=1,                               *)
(*   fc(2k-1) ts(2k-1)t + fc(2k) ts(2k)t = inv pi int phi(x) cos(k(t-x)) dx. *)
let CFOURIER_TRIG_PAIR_MATCH = prove
 (`!(phi:real->real) k t. 1 <= k /\
     phi absolutely_real_integrable_on real_interval[--pi,pi]
     ==> fourier_coefficient phi (2*k-1) * trigonometric_set (2*k-1) t +
         fourier_coefficient phi (2*k) * trigonometric_set (2*k) t =
         inv pi * real_integral (real_interval[--pi,pi]) (\x. phi x * cos(&k*(t
           - x)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `2 * k - 1 = 2 * (k - 1) + 1` SUBST1_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `2 * k = 2 * (k - 1) + 2` SUBST1_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[fourier_coefficient; orthonormal_coefficient; l2product] THEN
  REWRITE_TAC[trigonometric_set] THEN
  SUBGOAL_THEN `(k - 1) + 1 = k` SUBST1_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x. sin(&k * x) / sqrt pi * phi x) absolutely_real_integrable_on
    real_interval[--pi,pi] /\
    (\x. cos(&k * x) / sqrt pi * phi x) absolutely_real_integrable_on
    real_interval[--pi,pi]`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN
    ONCE_REWRITE_TAC[REAL_ARITH `s / sqrt pi * ph = inv(sqrt pi) * (s * ph)`]
      THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_LMUL THEN
    ASM_SIMP_TAC[ABSOLUTELY_INTEGRABLE_SIN_PRODUCT;
                 ABSOLUTELY_INTEGRABLE_COS_PRODUCT]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x. phi x * cos(&k * (t - x))) real_integrable_on real_interval[--pi,pi]`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
    SUBGOAL_THEN
     `(\x. phi x * cos(&k * (t - x))) =
      (\x. cos(&k * t) * (cos(&k * x) * phi x) +
           sin(&k * t) * (sin(&k * x) * phi x))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REWRITE_TAC[REAL_ARITH `&k * (t - x) = &k * t - &k * x`; COS_SUB] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_ADD THEN CONJ_TAC THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_LMUL THEN
    ASM_SIMP_TAC[ABSOLUTELY_INTEGRABLE_SIN_PRODUCT;
                 ABSOLUTELY_INTEGRABLE_COS_PRODUCT]; ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM REAL_INTEGRAL_RMUL;
    ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE] THEN
  ASM_SIMP_TAC[GSYM REAL_INTEGRAL_ADD;
    ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE;
               REAL_INTEGRABLE_RMUL] THEN
  ASM_SIMP_TAC[GSYM REAL_INTEGRAL_LMUL] THEN
  MATCH_MP_TAC REAL_INTEGRAL_EQ THEN X_GEN_TAC `x:real` THEN DISCH_TAC THEN
  REWRITE_TAC[REAL_ARITH `&k * (t - x) = &k * t - &k * x`; COS_SUB] THEN
  MP_TAC(ISPEC `pi` SQRT_POW_2) THEN REWRITE_TAC[PI_POS_LE] THEN
  REWRITE_TAC[REAL_POW_2] THEN
  MP_TAC PI_POS THEN MP_TAC(ISPEC `pi` SQRT_POS_LT) THEN
  REWRITE_TAC[real_div] THEN CONV_TAC REAL_FIELD);;

(* Connector: the +-k complex pair equals the real-trig pair term (k>=1).    *)
let CFOURIER_PAIR_TRIG = prove
 (`!(phi:real->real) k t. 1 <= k /\
     phi absolutely_real_integrable_on real_interval[--pi,pi]
     ==> &2 * Re(cfourier_coeff (\x. Cx(phi x)) (&k) * cexp(ii * Cx(&k) * Cx
       t)) =
         fourier_coefficient phi (2*k-1) * trigonometric_set (2*k-1) t +
         fourier_coefficient phi (2*k) * trigonometric_set (2*k) t`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`phi:real->real`; `k:num`;
    `t:real`] CFOURIER_PAIR_RE_COS) THEN
  ASM_SIMP_TAC[CX_PHI_ABSINT] THEN DISCH_THEN SUBST1_TAC THEN
  ASM_SIMP_TAC[CFOURIER_TRIG_PAIR_MATCH] THEN
  AP_TERM_TAC THEN
  SUBGOAL_THEN
   `(\x. phi x * cos(&k * (t - x))) real_integrable_on real_interval[--pi,pi]`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
    SUBGOAL_THEN
     `(\x. phi x * cos(&k * (t - x))) =
      (\x. cos(&k * t) * (cos(&k * x) * phi x) +
           sin(&k * t) * (sin(&k * x) * phi x))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REWRITE_TAC[REAL_ARITH `&k * (t - x) = &k * t - &k * x`; COS_SUB] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_ADD THEN CONJ_TAC THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_LMUL THEN
    ASM_SIMP_TAC[ABSOLUTELY_INTEGRABLE_SIN_PRODUCT;
                 ABSOLUTELY_INTEGRABLE_COS_PRODUCT]; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_INTEGRAL_DROP_BRIDGE]);;

(* The n=0 coefficient: c_0(Cx o phi) = Cx(fc phi 0 * ts 0 t).               *)
let CFOURIER_COEFF_ZERO_TRIG = prove
 (`!(phi:real->real) t. phi absolutely_real_integrable_on
   real_interval[--pi,pi]
     ==> cfourier_coeff (\x. Cx(phi x)) (&0) =
         Cx(fourier_coefficient phi 0 * trigonometric_set 0 t)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[cfourier_coeff; IMAGE_LIFT_REAL_INTERVAL] THEN
  REWRITE_TAC[int_of_num_th; COMPLEX_MUL_LZERO; COMPLEX_MUL_RZERO;
              COMPLEX_NEG_0; CEXP_0; COMPLEX_MUL_RID] THEN
  REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
  ASM_SIMP_TAC[CX_REAL_INTEGRAL_BRIDGE;
    ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE] THEN
  REWRITE_TAC[fourier_coefficient; orthonormal_coefficient; l2product;
              trigonometric_set; REAL_MUL_LZERO; COS_0] THEN
  REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
  ASM_SIMP_TAC[REAL_INTEGRAL_LMUL;
    ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE] THEN
  MP_TAC(ISPEC `&2 * pi` SQRT_POW_2) THEN
  SIMP_TAC[REAL_LE_MUL; REAL_POS; PI_POS_LE; REAL_ARITH `&0 <= &2`] THEN
  REWRITE_TAC[REAL_POW_2] THEN
  MP_TAC PI_POS THEN MP_TAC(ISPEC `&2 * pi` SQRT_POS_LT) THEN
  ASM_SIMP_TAC[REAL_LT_MUL; REAL_ARITH `&0 < &2`] THEN
  CONV_TAC REAL_FIELD);;

(* Grouping a 0..2N sum into the head plus paired (2k-1,2k) terms.           *)
let SUM_GROUP_PAIRS = prove
 (`!(g:num->real) N. sum(0..2*N) g = g 0 + sum(1..N)(\k. g(2*k-1) + g(2*k))`,
  GEN_TAC THEN INDUCT_TAC THENL
   [REWRITE_TAC[MULT_CLAUSES; SUM_CLAUSES_NUMSEG; ARITH; REAL_ADD_RID];
     ALL_TAC] THEN
  SUBGOAL_THEN
   `sum(0..2 * SUC N) g = sum(0..2 * N) g + g(2 * N + 1) + g(2 * N + 2)`
   SUBST1_TAC THENL
   [SUBGOAL_THEN `2 * SUC N = SUC(SUC(2 * N))` SUBST1_TAC THENL
     [ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[SUM_CLAUSES_NUMSEG; LE_0] THEN
    REWRITE_TAC[ADD1; ARITH_RULE `(2 * N + 1) + 1 = 2 * N + 2`] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[SUM_CLAUSES_NUMSEG; ARITH_RULE `1 <= SUC N`] THEN
  REWRITE_TAC[ARITH_RULE `2 * SUC N - 1 = 2 * N + 1`;
              ARITH_RULE `2 * SUC N = 2 * N + 2`] THEN
  REAL_ARITH_TAC);;

(* KEYSTONE 282L(a): the complex-exponential partial sum of Cx o phi is Cx   *)
(* of the classical real-trigonometric partial sum sum(0..2N) fc phi k * ts  *)
(* k t.                                                                      *)
let CFOURIER_PARTIAL_REAL_TRIG = prove
 (`!(phi:real->real) N t. phi absolutely_real_integrable_on
   real_interval[--pi,pi]
     ==> cfourier_partial (\x. Cx(phi x)) N t =
         Cx(sum(0..2*N)(\k. fourier_coefficient phi k * trigonometric_set k
           t))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[SUM_GROUP_PAIRS] THEN
  ONCE_REWRITE_TAC[CFOURIER_PARTIAL_SPLIT] THEN
  ASM_SIMP_TAC[CFOURIER_COEFF_ZERO_TRIG] THEN
  REWRITE_TAC[CX_ADD] THEN AP_TERM_TAC THEN
  W(fun (asl,w) -> MP_TAC(ISPECL [`\k. fourier_coefficient phi (2*k-1) *
      trigonometric_set (2*k-1) t + fourier_coefficient phi (2*k) *
      trigonometric_set (2*k) t`; `1..N`] VSUM_CX)) THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `k:num` THEN
  REWRITE_TAC[IN_NUMSEG] THEN STRIP_TAC THEN
  REWRITE_TAC[GSYM CX_ADD] THEN
  ASM_SIMP_TAC[GSYM CFOURIER_PAIR_TRIG] THEN
  MP_TAC(ISPECL [`phi:real->real`; `k:num`; `t:real`] CFOURIER_PAIR_RE) THEN
  ASM_SIMP_TAC[CX_PHI_ABSINT]);;

(* 282L: pointwise Fourier inversion for a differentiable 2pi-periodic phi.  *)
(* The complex-exponential partial sum converges to Cx(phi t).               *)
let CFOURIER_CONVERGENCE_DIFFERENTIABLE = prove
 (`!(phi:real->real) t.
     phi absolutely_real_integrable_on real_interval[--pi,pi] /\
     (!x. phi(x + &2 * pi) = phi x) /\
     phi real_differentiable atreal t
     ==> ((\N. cfourier_partial (\x. Cx(phi x)) N t) --> Cx(phi t))
       sequentially`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CFOURIER_PARTIAL_REAL_TRIG] THEN
  REWRITE_TAC[GSYM o_DEF] THEN
  ONCE_REWRITE_TAC[GSYM REALLIM_COMPLEX] THEN
  MP_TAC(ISPECL
   [`phi:real->real`; `0`; `t:real`;
     `phi(t:real):real`] FOURIER_SUM_LIMIT_PAIR) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC DIFFERENTIABLE_FOURIER_CONVERGENCE_PERIODIC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 282L(i) in Fremlin's FAITHFUL form: pointwise Fourier inversion at an     *)
(* INTERIOR point, with NO global-periodicity hypothesis (only integrability *)
(* on [-pi,pi] and differentiability at the one interior point t). Fremlin's *)
(* proof uses the periodic extension internally; at an interior point that   *)
(* extension agrees with phi on a neighbourhood, so differentiability        *)
(* transfers                                                                 *)
(* and the Fourier coefficients are unchanged.  We realise this with an      *)
(* explicit 2pi-periodisation and reduce to                                  *)
(* CFOURIER_CONVERGENCE_DIFFERENTIABLE.                                      *)
(* This removes the spurious periodicity assumption the tile function g of   *)
(* 286O(b) does not satisfy (g is a compactly-supported bump).               *)
(* ------------------------------------------------------------------------- *)

(* The 2pi-periodisation: fold x into [-pi,pi) by subtracting the right      *)
(* multiple of 2pi (floor of (x+pi)/2pi).                                    *)
let periodize = new_definition
 `periodize (phi:real->real) x = phi(x - &2 * pi * floor((x + pi)/(&2 *
   pi)))`;;

(* periodize phi is 2pi-periodic: the +2pi shift bumps the floor by 1.       *)
let PERIODIZE_PERIODIC = prove
 (`!(phi:real->real) x. periodize phi (x + &2 * pi) = periodize phi x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[periodize] THEN AP_TERM_TAC THEN
  SUBGOAL_THEN
    `((x + &2 * pi) + pi)/(&2 * pi) = (x + pi)/(&2 * pi) + &1` SUBST1_TAC THENL
   [MP_TAC PI_POS THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  SUBGOAL_THEN
    `floor((x + pi)/(&2 * pi) + &1) = floor((x + pi)/(&2 * pi)) + &1`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM FLOOR_UNIQUE] THEN
     MP_TAC(SPEC `(x + pi)/(&2 * pi)` FLOOR) THEN
    SIMP_TAC[INTEGER_CLOSED] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_ADD_RDISTRIB; REAL_MUL_RID] THEN REAL_ARITH_TAC);;

(* On the open interval (-pi,pi) the floor is 0, so periodize phi = phi.     *)
let PERIODIZE_INTERIOR = prove
 (`!(phi:real->real) x. --pi < x /\ x < pi ==> periodize phi x = phi x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[periodize] THEN
  SUBGOAL_THEN `floor((x + pi)/(&2 * pi)) = &0` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM FLOOR_UNIQUE; INTEGER_CLOSED] THEN
    SUBGOAL_THEN `&0 < &2 * pi` ASSUME_TAC THENL
     [MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LE_RDIV_EQ; REAL_LT_LDIV_EQ] THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_RZERO; REAL_SUB_RZERO]);;

(* The Fourier coefficients are unchanged by periodisation (integrands agree *)
(* on [-pi,pi] off the two endpoints, a negligible set).                     *)
let CFOURIER_COEFF_PERIODIZE = prove
 (`!(phi:real->real) n.
     cfourier_coeff (\x. Cx(periodize phi x)) n = cfourier_coeff (\x. Cx(phi
       x)) n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cfourier_coeff] THEN AP_TERM_TAC THEN
  MATCH_MP_TAC INTEGRAL_SPIKE THEN
  EXISTS_TAC `{lift(--pi), lift pi}` THEN
  REWRITE_TAC[NEGLIGIBLE_INSERT; NEGLIGIBLE_EMPTY] THEN
  X_GEN_TAC `x:real^1` THEN
  REWRITE_TAC[IN_DIFF; IMAGE_LIFT_REAL_INTERVAL; IN_INTERVAL_1; LIFT_DROP] THEN
  REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY; DE_MORGAN_THM] THEN STRIP_TAC THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC PERIODIZE_INTERIOR THEN
  SUBGOAL_THEN `~(drop x = --pi) /\ ~(drop (x:real^1) = pi)` MP_TAC THENL
   [REWRITE_TAC[GSYM LIFT_EQ; LIFT_DROP] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT(POP_ASSUM MP_TAC) THEN REAL_ARITH_TAC);;

(* Hence the partial sums agree too.                                         *)
let CFOURIER_PARTIAL_PERIODIZE = prove
 (`!(phi:real->real) N t.
     cfourier_partial (\x. Cx(periodize phi x)) N t = cfourier_partial (\x.
       Cx(phi x)) N t`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cfourier_partial] THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `n:int` THEN DISCH_TAC THEN
  REWRITE_TAC[CFOURIER_COEFF_PERIODIZE]);;

(* periodize phi is absolutely integrable when phi is (spike on the          *)
(* endpoints).                                                               *)
let PERIODIZE_ABSINT = prove
 (`!(phi:real->real). phi absolutely_real_integrable_on real_interval[--pi,pi]
     ==> periodize phi absolutely_real_integrable_on real_interval[--pi,pi]`,
  GEN_TAC THEN REWRITE_TAC[absolutely_real_integrable_on] THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `!x. x IN real_interval[--pi,pi] DIFF {--pi, pi} ==> periodize phi x =
     phi x`
   ASSUME_TAC THENL
   [X_GEN_TAC `x:real` THEN
    REWRITE_TAC[IN_DIFF; IN_REAL_INTERVAL; IN_INSERT; NOT_IN_EMPTY;
      DE_MORGAN_THM] THEN
    STRIP_TAC THEN MATCH_MP_TAC PERIODIZE_INTERIOR THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`phi:real->real`; `periodize phi`; `{--pi, pi}`;
                   `real_interval[--pi,pi]`] REAL_INTEGRABLE_SPIKE_EQ) THEN
    ASM_SIMP_TAC[REAL_NEGLIGIBLE_INSERT; REAL_NEGLIGIBLE_EMPTY];
    MP_TAC(ISPECL [`\x. abs((phi:real->real) x)`; `\x. abs(periodize phi x)`;
      `{--pi, pi}`;
                   `real_interval[--pi,pi]`] REAL_INTEGRABLE_SPIKE_EQ) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[REAL_NEGLIGIBLE_INSERT; REAL_NEGLIGIBLE_EMPTY] THEN
      REPEAT STRIP_TAC THEN AP_TERM_TAC THEN ASM_SIMP_TAC[];
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[]]]);;

(* Interior differentiability transfers to periodize (local agreement on a   *)
(* neighbourhood of t contained in (-pi,pi)).                                *)
let PERIODIZE_DIFFERENTIABLE = prove
 (`!(phi:real->real) t. --pi < t /\ t < pi /\ phi real_differentiable atreal t
     ==> periodize phi real_differentiable atreal t`,
  REPEAT GEN_TAC THEN REWRITE_TAC[real_differentiable] THEN STRIP_TAC THEN
  EXISTS_TAC `f':real` THEN
  MATCH_MP_TAC HAS_REAL_DERIVATIVE_TRANSFORM_ATREAL THEN
  MAP_EVERY EXISTS_TAC [`phi:real->real`; `min (t + pi) (pi - t)`] THEN
  ASM_REWRITE_TAC[REAL_LT_MIN] THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `x':real` THEN STRIP_TAC THEN CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC PERIODIZE_INTERIOR THEN ASM_REAL_ARITH_TAC);;

(* 282L(i): pointwise Fourier inversion at an interior point, NO periodicity *)
(* hypothesis -- Fremlin's actual statement. The complex-exponential partial *)
(* sum of Cx o phi converges to Cx(phi t) whenever phi is integrable on      *)
(* [-pi,pi]                                                                  *)
(* and differentiable at the interior point t in (-pi,pi).                   *)
let CFOURIER_CONVERGENCE_INTERIOR = prove
 (`!(phi:real->real) t.
     phi absolutely_real_integrable_on real_interval[--pi,pi] /\
     --pi < t /\ t < pi /\
     phi real_differentiable atreal t
     ==> ((\N. cfourier_partial (\x. Cx(phi x)) N t) --> Cx(phi t))
       sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `Cx(phi t) = Cx(periodize phi t)` SUBST1_TAC THENL
   [AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
     MATCH_MP_TAC PERIODIZE_INTERIOR THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ONCE_REWRITE_TAC[GSYM CFOURIER_PARTIAL_PERIODIZE] THEN
  MATCH_MP_TAC CFOURIER_CONVERGENCE_DIFFERENTIABLE THEN
  REWRITE_TAC[PERIODIZE_PERIODIC; ETA_AX] THEN
  ASM_SIMP_TAC[PERIODIZE_ABSINT] THEN
  MATCH_MP_TAC PERIODIZE_DIFFERENTIABLE THEN ASM_REWRITE_TAC[]);;

(* Reindexing symmetry (Fremlin 286O-b-ii, step 2094->2097): the symmetric   *)
(* sum                                                                       *)
(* of c_{-n} e^{-inu} over |n|<=N equals cfourier_partial g N u (substitute  *)
(* n -> -n on the symmetric index set {n | abs n <= N}).  This is the bridge *)
(* that turns the R_k tile-sum (indexed by n_I in ZZ) into the 282A partial  *)
(* sum.                                                                      *)
let CFOURIER_PARTIAL_REINDEX = prove
 (`!(g:real->complex) N u.
     vsum {n:int | abs n <= &N}
          (\n. cfourier_coeff g (--n) * cexp(--(ii * Cx(real_of_int n) * Cx
            u))) =
     cfourier_partial g N u`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cfourier_partial] THEN
  MATCH_MP_TAC VSUM_EQ_GENERAL THEN
  EXISTS_TAC `\n:int. --n` THEN
  REWRITE_TAC[IN_ELIM_THM; INT_ABS_NEG] THEN CONJ_TAC THENL
   [X_GEN_TAC `m:int` THEN DISCH_TAC THEN
    REWRITE_TAC[EXISTS_UNIQUE_THM; IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [EXISTS_TAC `--m:int` THEN ASM_REWRITE_TAC[INT_ABS_NEG; INT_NEG_NEG];
      REPEAT STRIP_TAC THEN ASM_INT_ARITH_TAC];
    X_GEN_TAC `n:int` THEN DISCH_TAC THEN REWRITE_TAC[INT_NEG_NEG] THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      AP_TERM_TAC THEN AP_TERM_TAC THEN
      REWRITE_TAC[int_neg_th; CX_NEG] THEN CONV_TAC COMPLEX_RING]]);;

(* Finite reindexed sum with a constant window W: pulls the nI-independent   *)
(* factor Cx(2pi)*W out of the tile-sum and collapses the c_{-nI} e^{-inI u} *)
(* part to the 282A partial sum (Fremlin 286O-b-ii, the sum over R_k at      *)
(* fixed scale k).                                                           *)
let CARLESON_FINITE_REINDEX_SUM = prove
 (`!(G:real->complex) N u (W:complex).
     vsum {nI:int | abs nI <= &N}
          (\nI. Cx(&2 * pi) *
                (cfourier_coeff G (--nI) * cexp(--(ii * Cx(real_of_int nI) * Cx
                  u))) * W) =
     Cx(&2 * pi) * cfourier_partial G N u * W`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[COMPLEX_RING `Cx(&2 * pi) * a * W = (Cx(&2 * pi) * W) * a`] THEN
  ASM_SIMP_TAC[VSUM_COMPLEX_LMUL; CFOURIER_INDEX_FINITE] THEN
  REWRITE_TAC[CFOURIER_PARTIAL_REINDEX] THEN CONV_TAC COMPLEX_RING);;

(* Complex 282L support: cfourier_coeff of a complex g splits into the real  *)
(* and imaginary Cx-coefficients (g = Cx(Re g) + ii Cx(Im g), integral is    *)
(* C-linear). Needs the two component integrands integrable on the interval. *)
let CFOURIER_COEFF_REIM = prove
 (`!(g:real->complex) n.
     (\t. Cx(Re(g(drop t))) * cexp(--(ii * Cx(real_of_int n) * Cx(drop t))))
       integrable_on
       interval[lift(--pi),lift pi] /\
     (\t. Cx(Im(g(drop t))) * cexp(--(ii * Cx(real_of_int n) * Cx(drop t))))
       integrable_on
       interval[lift(--pi),lift pi]
     ==> cfourier_coeff g n =
         cfourier_coeff (\x. Cx(Re(g x))) n + ii * cfourier_coeff (\x. Cx(Im(g
           x))) n`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[cfourier_coeff; IMAGE_LIFT_REAL_INTERVAL] THEN
  MATCH_MP_TAC EQ_TRANS THEN
  EXISTS_TAC
   `Cx(inv(&2 * pi)) *
    (integral (interval[lift(--pi),lift pi])
       (\t. Cx(Re(g(drop t))) * cexp(--(ii * Cx(real_of_int n) * Cx(drop t))))
         +
     ii * integral (interval[lift(--pi),lift pi])
       (\t. Cx(Im(g(drop t))) * cexp(--(ii * Cx(real_of_int n) * Cx(drop
         t)))))` THEN
  CONJ_TAC THENL
   [AP_TERM_TAC THEN
    ASM_SIMP_TAC[GSYM INTEGRAL_COMPLEX_LMUL] THEN
    MATCH_MP_TAC EQ_TRANS THEN
    EXISTS_TAC
     `integral (interval[lift(--pi),lift pi])
        (\t. Cx(Re(g(drop t))) * cexp(--(ii * Cx(real_of_int n) * Cx(drop t)))
          +
             ii * (Cx(Im(g(drop t))) * cexp(--(ii * Cx(real_of_int n) * Cx(drop
               t)))))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `t:real^1` THEN DISCH_TAC THEN
      REWRITE_TAC[] THEN
      GEN_REWRITE_TAC (LAND_CONV o RATOR_CONV o RAND_CONV) [COMPLEX_EXPAND]
        THEN
      CONV_TAC COMPLEX_RING;
      MATCH_MP_TAC INTEGRAL_ADD THEN ASM_SIMP_TAC[INTEGRABLE_COMPLEX_LMUL]];
    ALL_TAC] THEN
  REWRITE_TAC[cfourier_coeff; IMAGE_LIFT_REAL_INTERVAL] THEN
    CONV_TAC COMPLEX_RING);;

(* Partial-sum Re/Im split (lifts CFOURIER_COEFF_REIM to the partial sum).   *)
let CFOURIER_PARTIAL_REIM = prove
 (`!(g:real->complex) N t.
     (!n. abs n <= &N ==>
        (\z. Cx(Re(g(drop z))) * cexp(--(ii * Cx(real_of_int n) * Cx(drop z))))
          integrable_on
          interval[lift(--pi),lift pi] /\
        (\z. Cx(Im(g(drop z))) * cexp(--(ii * Cx(real_of_int n) * Cx(drop z))))
          integrable_on
          interval[lift(--pi),lift pi])
     ==> cfourier_partial g N t =
         cfourier_partial (\x. Cx(Re(g x))) N t + ii * cfourier_partial (\x.
           Cx(Im(g x))) N t`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cfourier_partial] THEN
  SIMP_TAC[GSYM VSUM_COMPLEX_LMUL; CFOURIER_INDEX_FINITE] THEN
  SIMP_TAC[GSYM VSUM_ADD; CFOURIER_INDEX_FINITE] THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `n:int` THEN
  REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n:int`) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN
  ASM_SIMP_TAC[CFOURIER_COEFF_REIM] THEN CONV_TAC COMPLEX_RING);;

(* 282L(i) for a COMPLEX g: if Re g, Im g are integrable on [-pi,pi] and     *)
(* differentiable at the interior point t, then cfourier_partial g N t --> g *)
(* t.                                                                        *)
(* Splits g into its real/imaginary parts and combines two real              *)
(* interior-282L                                                             *)
(* limits (LIM_ADD + LIM_COMPLEX_LMUL).  This is the tool the complex tile   *)
(* function g(t)=hhat(2^k t+yhat_k) e^{it/2} phihat(t) needs.                *)
let CFOURIER_CONVERGENCE_INTERIOR_CX = prove
 (`!(g:real->complex) t.
     (\x. Re(g x)) absolutely_real_integrable_on real_interval[--pi,pi] /\
     (\x. Im(g x)) absolutely_real_integrable_on real_interval[--pi,pi] /\
     --pi < t /\ t < pi /\
     (\x. Re(g x)) real_differentiable atreal t /\
     (\x. Im(g x)) real_differentiable atreal t
     ==> ((\N. cfourier_partial g N t) --> g t) sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!N. cfourier_partial (g:real->complex) N t =
        cfourier_partial (\x. Cx(Re(g x))) N t + ii * cfourier_partial (\x.
          Cx(Im(g x))) N t`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MATCH_MP_TAC CFOURIER_PARTIAL_REIM THEN
    X_GEN_TAC `n:int` THEN DISCH_TAC THEN CONJ_TAC THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC CFOURIER_INTEGRAND_ABSINT THEN
    MATCH_MP_TAC CX_PHI_ABSINT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [COMPLEX_EXPAND] THEN
  MATCH_MP_TAC LIM_ADD THEN CONJ_TAC THENL
   [MATCH_MP_TAC CFOURIER_CONVERGENCE_INTERIOR THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC LIM_COMPLEX_LMUL THEN
    MATCH_MP_TAC CFOURIER_CONVERGENCE_INTERIOR THEN ASM_REWRITE_TAC[]]);;

(* Vector-differentiability of g(drop .) at lift t gives                     *)
(* real-differentiability of Re g and Im g at t (Re, Im are linear           *)
(* real^2->real^1 up to lift, chain rule). Bridges a complex tile function's *)
(* vector derivative to the Re/Im hypotheses of                              *)
(* CFOURIER_CONVERGENCE_INTERIOR_CX.                                         *)
let VECTOR_DIFF_IMP_REIM_DIFF = prove
 (`!(g:real->complex) t.
     (\z. g(drop z)) differentiable (at(lift t))
     ==> (\x. Re(g x)) real_differentiable atreal t /\
         (\x. Im(g x)) real_differentiable atreal t`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[REAL_DIFFERENTIABLE_AT; o_DEF] THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\z. lift(Re(g(drop z)))) = (\w. lift(Re w)) o (\z. g(drop z))`
     SUBST1_TAC THENL [REWRITE_TAC[o_DEF]; ALL_TAC];
    SUBGOAL_THEN
     `(\z. lift(Im(g(drop z)))) = (\w. lift(Im w)) o (\z. g(drop z))`
     SUBST1_TAC THENL [REWRITE_TAC[o_DEF]; ALL_TAC]] THEN
  MATCH_MP_TAC DIFFERENTIABLE_CHAIN_AT THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC DIFFERENTIABLE_LINEAR THEN
  REWRITE_TAC[linear; LIFT_ADD; LIFT_CMUL; RE_ADD; IM_ADD; RE_CMUL;
    IM_CMUL] THEN
  REWRITE_TAC[LIFT_ADD; LIFT_CMUL]);;

(* Product rule for complex-valued functions of a real^1 variable (via the   *)
(* bilinear vector-derivative rule).  A building block for showing the tile  *)
(* function g = hhat(2^k .+yhat_k) * e^{i./2} * phihat is                    *)
(* vector-differentiable.                                                    *)
let DIFFERENTIABLE_COMPLEX_MUL_AT = prove
 (`!(f:real^1->complex) g a.
     f differentiable (at a) /\ g differentiable (at a)
     ==> (\x. f x * g x) differentiable (at a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC HAS_VECTOR_DERIVATIVE_IMP_DIFFERENTIABLE THEN
  EXISTS_TAC
   `f a * vector_derivative (g:real^1->complex) (at a) +
    vector_derivative (f:real^1->complex) (at a) * g a` THEN
  MP_TAC(ISPECL
   [`(\x y. x * y):complex->complex->complex`;
    `f:real^1->complex`; `g:real^1->complex`;
    `vector_derivative (f:real^1->complex) (at a)`;
    `vector_derivative (g:real^1->complex) (at a)`; `a:real^1`]
   HAS_VECTOR_DERIVATIVE_BILINEAR_AT) THEN
  ASM_SIMP_TAC[BILINEAR_COMPLEX_MUL; GSYM VECTOR_DERIVATIVE_WORKS] THEN
  BETA_TAC THEN DISCH_THEN MATCH_MP_TAC THEN
  SUBGOAL_THEN `(\x y. x * y):complex->complex->complex = (*)` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM]; REWRITE_TAC[BILINEAR_COMPLEX_MUL]]);;

(* fourier of a Schwartz function is vector-differentiable everywhere        *)
(* (FOURIER_SCHWARTZ_DERIV gives the derivative --ii*fourier(x*h)).          *)
let FOURIER_SCHWARTZ_DIFFERENTIABLE = prove
 (`!(h:real->complex) a. schwartz h ==>
     (\z. fourier h (drop z)) differentiable (at a)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC HAS_VECTOR_DERIVATIVE_IMP_DIFFERENTIABLE THEN
  EXISTS_TAC `--ii * fourier (\x. Cx x * h x) (drop a)` THEN
  MP_TAC(ISPECL [`h:real->complex`; `drop a`] FOURIER_SCHWARTZ_DERIV) THEN
  ASM_REWRITE_TAC[LIFT_DROP]);;

(* fourier h composed with an affine real map c*t+b is                       *)
(* vector-differentiable.                                                    *)
let FOURIER_SCHWARTZ_AFFINE_DIFF = prove
 (`!(h:real->complex) c b a. schwartz h ==>
     (\z. fourier h (c * drop z + b)) differentiable (at a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. fourier h (c * drop z + b)) =
    (\w. fourier h (drop w)) o (\z:real^1. c % z + lift b)`
   SUBST1_TAC THENL
   [REWRITE_TAC[o_DEF; FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[DROP_ADD; DROP_CMUL; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC DIFFERENTIABLE_CHAIN_AT THEN CONJ_TAC THENL
   [MATCH_MP_TAC DIFFERENTIABLE_ADD THEN
    REWRITE_TAC[DIFFERENTIABLE_CONST] THEN
    MATCH_MP_TAC DIFFERENTIABLE_CMUL THEN REWRITE_TAC[DIFFERENTIABLE_ID];
    ASM_SIMP_TAC[FOURIER_SCHWARTZ_DIFFERENTIABLE]]);;

(* cexp of a linear real^1->complex map c*Cx(drop z) is                      *)
(* vector-differentiable.                                                    *)
let CEXP_LINEAR_DIFF = prove
 (`!(c:complex) a. (\z. cexp(c * Cx(drop z))) differentiable (at a)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\z. cexp(c * Cx(drop z))) = cexp o (\z:real^1. c * Cx(drop z))`
   SUBST1_TAC THENL [REWRITE_TAC[o_DEF]; ALL_TAC] THEN
  MATCH_MP_TAC DIFFERENTIABLE_CHAIN_AT THEN CONJ_TAC THENL
   [MATCH_MP_TAC DIFFERENTIABLE_LINEAR THEN
    REWRITE_TAC[linear; DROP_ADD; DROP_CMUL; CX_ADD; CX_MUL; COMPLEX_CMUL] THEN
    CONV_TAC COMPLEX_RING;
    MATCH_MP_TAC COMPLEX_DIFFERENTIABLE_IMP_DIFFERENTIABLE THEN
    REWRITE_TAC[COMPLEX_DIFFERENTIABLE_AT_CEXP]]);;

(* If g(drop .) is vector-differentiable everywhere then Re g, Im g are      *)
(* absolutely-real-integrable on [-pi,pi] (differentiable => continuous on   *)
(* the                                                                       *)
(* compact interval => absolutely integrable).  Supplies the integrability   *)
(* hypotheses of CFOURIER_CONVERGENCE_INTERIOR_CX.                           *)
let VECTOR_DIFF_IMP_REIM_ABSINT = prove
 (`!(g:real->complex).
     (!a. (\z. g(drop z)) differentiable (at a))
     ==> (\x. Re(g x)) absolutely_real_integrable_on real_interval[--pi,pi] /\
         (\x. Im(g x)) absolutely_real_integrable_on real_interval[--pi,pi]`,
  GEN_TAC THEN DISCH_TAC THEN CONJ_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_CONTINUOUS THEN
  MATCH_MP_TAC REAL_DIFFERENTIABLE_ON_IMP_REAL_CONTINUOUS_ON THEN
  REWRITE_TAC[real_differentiable_on; GSYM real_differentiable] THEN
  X_GEN_TAC `x:real` THEN DISCH_TAC THEN
  MATCH_MP_TAC REAL_DIFFERENTIABLE_ATREAL_WITHIN THEN
  MP_TAC(ISPECL [`g:real->complex`; `x:real`] VECTOR_DIFF_IMP_REIM_DIFF) THEN
  ASM_REWRITE_TAC[] THEN SIMP_TAC[]);;


(* ------------------------------------------------------------------------- *)
(* The one-dimensional Hardy-Littlewood maximal function (Fremlin 286A).     *)
(* f*(x) = sup of the average of |f| over intervals [a,b] containing x.      *)
(* ------------------------------------------------------------------------- *)

(* ========================================================================= *)
(* Layer-cake / distribution-function infrastructure (Fremlin 252O).         *)
(*                                                                           *)
(* Not present in the library as a named result, but derivable: the region   *)
(* under the graph of a nonnegative g has measure int g (via                 *)
(* HAS_INTEGRAL_MEASURE_UNDER_CURVE), and slicing it horizontally at height  *)
(* t (via FUBINI_MEASURE_ALT) has section {x | t <= g x}.  Equating the two  *)
(* gives  int g = int_{t} measure {x | t <= g x} dt.                         *)
(* ========================================================================= *)

(* Vector-level engine: g:real^1->real^1, g >= 0, integrating to m.          *)
(* Then t |-> measure {x | t <= g x} (with the &0 <= t guard from the        *)
(* closed region [vec 0, g x]) integrates to the same m over all of R.       *)


(* ========================================================================= *)
(* Fremlin 286E(b): the Lacey-Thiele test function and tile-bump family.     *)
(* ========================================================================= *)

let psi0 = new_definition
  `psi0 (x:real) = rtheta(&11 - &60 * x) * rtheta(&11 + &60 * x)`;;

let PSI0_ONE = prove
 (`!x. abs x <= &1 / &6 ==> psi0 x = &1`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[psi0] THEN
  SUBGOAL_THEN `rtheta(&11 - &60 * x) = &1 /\ rtheta(&11 + &60 * x) = &1`
   (fun th -> REWRITE_TAC[th; REAL_MUL_LID]) THEN
  CONJ_TAC THEN MATCH_MP_TAC RTHETA_ONE THEN ASM_REAL_ARITH_TAC);;

let PSI0_SUPPORT = prove
 (`!x. &1 / &5 < abs x ==> psi0 x = &0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[psi0] THEN
  DISJ_CASES_TAC(REAL_ARITH `x < &0 \/ &0 <= x`) THENL
   [SUBGOAL_THEN `rtheta(&11 + &60 * x) = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC RTHETA_ZERO THEN
       ASM_REAL_ARITH_TAC; REWRITE_TAC[REAL_MUL_RZERO]];
    SUBGOAL_THEN `rtheta(&11 - &60 * x) = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC RTHETA_ZERO THEN
       ASM_REAL_ARITH_TAC; REWRITE_TAC[REAL_MUL_LZERO]]]);;

let PSI0_BOUNDS = prove
 (`!x. &0 <= psi0 x /\ psi0 x <= &1`,
  GEN_TAC THEN REWRITE_TAC[psi0] THEN
  MP_TAC(SPEC `&11 - &60 * x` RTHETA_BOUNDS) THEN
  MP_TAC(SPEC `&11 + &60 * x` RTHETA_BOUNDS) THEN
  STRIP_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `rtheta(&11 - &60 * x) * &1` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_MUL_RID] THEN ASM_REAL_ARITH_TAC]]);;

let PSI0_EVEN = prove
 (`!x. psi0(--x) = psi0 x`,
  GEN_TAC THEN REWRITE_TAC[psi0] THEN
  REWRITE_TAC[REAL_ARITH `&11 - &60 * --x = &11 + &60 * x`;
              REAL_ARITH `&11 + &60 * --x = &11 - &60 * x`] THEN
  REAL_ARITH_TAC);;

(* psi0 is smooth with compact support, hence Schwartz.                      *)
let PSI0_CHAIN = prove
 (`?q:num->real->complex.
     q 0 = (\x. Cx(psi0 x)) /\
     (!n y. ((\z. q n(drop z)) has_vector_derivative (q(SUC n) y))(at(lift
       y)))`,
  X_CHOOSE_THEN `d:num->real->complex` STRIP_ASSUME_TAC RTHETA_CHAIN THEN
  MP_TAC(ISPECL [`d:num->real->complex`; `&11`; `-- &60`] AFFINE_CHAIN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`d:num->real->complex`; `&11`; `&60`] AFFINE_CHAIN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL
    [`\n x. Cx(-- &60) pow n * (d:num->real->complex) n (&11 + -- &60 * x)`;
     `\n x. Cx(&60) pow n * (d:num->real->complex) n (&11 + &60 * x)`]
    LEIBNIZ_CHAIN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:num->real->complex` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `q:num->real->complex` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real` THEN
  ASM_REWRITE_TAC[complex_pow; COMPLEX_MUL_LID; psi0; CX_MUL] THEN
  REWRITE_TAC[REAL_ARITH `&11 + -- &60 * x = &11 - &60 * x`]);;

let SCHWARTZ_PSI0 = prove
 (`schwartz (\x. Cx(psi0 x))`,
  X_CHOOSE_THEN `q:num->real->complex` STRIP_ASSUME_TAC PSI0_CHAIN THEN
  SUBGOAL_THEN `(\x. Cx(psi0 x)) = (q:num->real->complex) 0` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC COMPACT_SUPPORT_SMOOTH_IMP_SCHWARTZ THEN
  EXISTS_TAC `&1 / &5` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[real_gt] THEN MATCH_MP_TAC CHAIN_SUPPORT THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REAL_ARITH_TAC;
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `psi0 x = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC PSI0_SUPPORT THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[COMPLEX_VEC_0; CX_INJ]]]);;

(* phi = fourier(Cx o psi0);  fourier phi = Cx o psi0 (psi0 even + double    *)
(* transform).  So phi-hat is real and satisfies the plateau sandwich.       *)
let PHI_FOURIER = prove
 (`!z. fourier (fourier (\x. Cx(psi0 x))) z = Cx(psi0 z)`,
  GEN_TAC THEN
  MP_TAC(ISPECL [`\x:real. Cx(psi0 x)`; `--z:real`] DOUBLE_TRANSFORM) THEN
  REWRITE_TAC[SCHWARTZ_PSI0; REAL_NEG_NEG] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[PSI0_EVEN]);;

(* ------------------------------------------------------------------------- *)
(* Toward 284C (fhat of a compactly-supported smooth fn is Schwartz), which  *)
(* will give phi = fourier(Cx o psi0) itself Schwartz.  Product rule for the *)
(* multiplication-by-x operator (first brick of "Schwartz closed under       *)
(* x*.").                                                                    *)
(* ------------------------------------------------------------------------- *)

let CARLESON_286EB = prove
 (`?phi:real->complex.
     schwartz phi /\
     (!y. real(fourier phi y)) /\
     (!y. (if abs y <= &1 / &6 then &1 else &0) <= Re(fourier phi y)) /\
     (!y. Re(fourier phi y) <= (if abs y <= &1 / &5 then &1 else &0))`,
  EXISTS_TAC `fourier (\x. Cx(psi0 x))` THEN
  REWRITE_TAC[PHI_FOURIER; RE_CX; REAL_CX] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_FOURIER THEN REWRITE_TAC[SCHWARTZ_PSI0];
    GEN_TAC THEN COND_CASES_TAC THENL
     [ASM_SIMP_TAC[PSI0_ONE; REAL_LE_REFL];
      MP_TAC(SPEC `y:real` PSI0_BOUNDS) THEN REAL_ARITH_TAC];
    GEN_TAC THEN COND_CASES_TAC THENL
     [MP_TAC(SPEC `y:real` PSI0_BOUNDS) THEN REAL_ARITH_TAC;
      SUBGOAL_THEN `psi0 y = &0` SUBST1_TAC THENL
       [MATCH_MP_TAC PSI0_SUPPORT THEN
         ASM_REAL_ARITH_TAC; REWRITE_TAC[REAL_LE_REFL]]]]);;

(* ------------------------------------------------------------------------- *)
(* Toward the phi_sigma family (286E): a nonzero affine map is onto R.       *)
(* (First building block for the L^2 dilation-invariance                     *)
(* ||phi_sigma||=||phi||)                                                    *)
(* ------------------------------------------------------------------------- *)

let PHISIG_LNORM_SQ = prove
 (`!(psi:real->complex) mJ a b.
     &0 < mJ /\ (\x:real^1. lift(norm(psi(drop x)) pow 2)) integrable_on
       (:real^1)
     ==> integral (:real^1)
           (\x. lift(norm(Cx(sqrt mJ) * cexp(ii * Cx b * Cx(drop x)) *
                          psi(mJ * (drop x - a))) pow 2)) =
         integral (:real^1) (\x. lift(norm(psi(drop x)) pow 2))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `ff = \y:real^1. lift(norm((psi:real->complex)(drop y)) pow 2)`
    THEN
  SUBGOAL_THEN
   `(\x:real^1. lift(norm(Cx(sqrt mJ) * cexp(ii * Cx b * Cx(drop x)) *
                    (psi:real->complex)(mJ * (drop x - a))) pow 2)) =
    (\x. mJ % (ff:real^1->real^1) (mJ % x + --(mJ % lift a)))`
   SUBST1_TAC THENL
   [EXPAND_TAC "ff" THEN
    REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX; GSYM CX_MUL;
      NORM_CEXP_II] THEN
    REWRITE_TAC[REAL_MUL_RID; REAL_POW_ONE; VECTOR_MUL_LID] THEN
    REWRITE_TAC[REAL_POW_MUL; GSYM LIFT_CMUL] THEN
    REWRITE_TAC[DROP_ADD; DROP_CMUL; DROP_NEG; LIFT_DROP] THEN
    REWRITE_TAC[REAL_ARITH `mJ * drop x + --(mJ * a) = mJ * (drop x - a)`] THEN
    AP_TERM_TAC THEN REWRITE_TAC[REAL_POW_ONE; REAL_MUL_LID] THEN
    SUBGOAL_THEN `abs(sqrt mJ) = sqrt mJ` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC SQRT_POS_LE THEN
       ASM_REAL_ARITH_TAC;
      ASM_SIMP_TAC[SQRT_POW_2; REAL_LT_IMP_LE]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(ff:real^1->real^1) integrable_on (:real^1)` ASSUME_TAC THENL
   [EXPAND_TAC "ff" THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[INTEGRAL_CMUL; INTEGRABLE_DILATE_UNIV; REAL_LT_IMP_NZ] THEN
  ASM_SIMP_TAC[INTEGRAL_DILATE_UNIV; REAL_LT_IMP_NZ] THEN
  REWRITE_TAC[VECTOR_MUL_ASSOC] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < m ==> abs m = m`; REAL_MUL_RINV;
    REAL_LT_IMP_NZ;
               VECTOR_MUL_LID]);;

(* ------------------------------------------------------------------------- *)
(* The phi_sigma family (286E b), abstract in the scalars mJ (= mu J > 0),   *)
(* a (= x_sigma), b (= y^l_sigma):                                           *)
(*   phimst mJ a b phi = \x. sqrt(mJ) e^{i b x} phi(mJ (x - a)).             *)
(* b(i): ||phimst||_2 = ||phi||_2 (PHIMST_L2, from PHISIG_LNORM_SQ).         *)
(* ------------------------------------------------------------------------- *)

(* Polynomial-growth helpers for the affine Schwartz-closure decay bounds.   *)
let phimst = new_definition
  `phimst mJ a b (phi:real->complex) =
     \x. Cx(sqrt mJ) * cexp(ii * Cx b * Cx x) * phi(mJ * (x - a))`;;

let PHIMST_L2 = prove
 (`!(phi:real->complex) mJ a b.
     &0 < mJ /\ (\x:real^1. lift(norm(phi(drop x)) pow 2)) integrable_on
       (:real^1)
     ==> lnorm (:real^1) (&2) (\z. phimst mJ a b phi (drop z)) =
         lnorm (:real^1) (&2) (\z. phi(drop z))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lnorm; phimst] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  SUBGOAL_THEN
   `(\x. lift(norm(Cx(sqrt mJ) * cexp(ii * Cx b * Cx(drop x)) *
                   (phi:real->complex)(mJ * (drop x - a))) rpow &2)) =
    (\x. lift(norm(Cx(sqrt mJ) * cexp(ii * Cx b * Cx(drop x)) *
                   phi(mJ * (drop x - a))) pow 2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[RPOW_POW]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x. lift(norm((phi:real->complex)(drop x)) rpow &2)) =
    (\x. lift(norm(phi(drop x)) pow 2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[RPOW_POW]; ALL_TAC] THEN
  MATCH_MP_TAC PHISIG_LNORM_SQ THEN ASM_REWRITE_TAC[]);;

(* Schwartz closed under affine reparametrization x |-> c + s x (s <> 0):    *)
(* chain via AFFINE_CHAIN; decay bounds via the |x|^k <=                     *)
(* 2^k(|u|^k+|c|^k)/|s|^k estimate (AFFINE_XPOW_BOUND/AFFINE_WEIGHT_BOUND    *)
(* from POW_ADD_2BOUND).                                                     *)
let PHIMST_SCHWARTZ = prove
 (`!(phi:real->complex) mJ a b. schwartz phi /\ ~(mJ = &0)
     ==> schwartz (phimst mJ a b phi)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[phimst] THEN
  MATCH_MP_TAC SCHWARTZ_CMUL THEN MATCH_MP_TAC SCHWARTZ_MODULATE THEN
  SUBGOAL_THEN
    `(\x. (phi:real->complex)(mJ * (x - a))) = (\x. phi(--(mJ * a) + mJ * x))`
    SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    MATCH_MP_TAC SCHWARTZ_AFFINE THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The modulated-affine core \x. e^{i b x} phi(mJ (x - a)) is Schwartz       *)
(* (phimst without the constant factor).  Reused for FOURIER_LMUL's side     *)
(* condition below.                                                          *)
(* ------------------------------------------------------------------------- *)

let FOURIER_PHI_SCALE_SHIFT = prove
 (`!(phi:real->complex) mJ a z. &0 < mJ /\ schwartz phi
     ==> fourier (\x. phi(mJ * (x - a))) z =
         Cx(&1 / mJ) * cexp(--(ii * Cx a * Cx z)) * fourier phi (z / mJ)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\x. (phi:real->complex)(mJ * (x - a))) =
     (\x. (\t. phi(mJ * t))(x + (--a)))`
    SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
     AP_TERM_TAC THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`\t. (phi:real->complex)(mJ * t)`; `--a:real`;
    `z:real`] FOURIER_SHIFT) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    SUBGOAL_THEN `schwartz (\t. (phi:real->complex)(mJ * t))` MP_TAC THENL
     [SUBGOAL_THEN
       `(\t. (phi:real->complex)(mJ * t)) =
        (\t. phi(&0 + mJ * t))` SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM; REAL_ADD_LID];
        MATCH_MP_TAC SCHWARTZ_AFFINE THEN ASM_REWRITE_TAC[] THEN
          ASM_REAL_ARITH_TAC];
      DISCH_THEN(MP_TAC o SPEC `z:real` o MATCH_MP SCHWARTZ_MOD_ABSINT) THEN
      REWRITE_TAC[]];
    DISCH_THEN SUBST1_TAC] THEN
  MP_TAC(ISPECL [`phi:real->complex`; `mJ:real`;
    `z:real`] FOURIER_DILATION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC SCHWARTZ_MOD_ABSINT THEN ASM_REWRITE_TAC[];
    DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[CX_NEG; COMPLEX_MUL_LNEG; COMPLEX_MUL_RNEG; COMPLEX_NEG_NEG] THEN
  REWRITE_TAC[COMPLEX_MUL_AC]);;

(* ------------------------------------------------------------------------- *)
(* Scalar identity:  sqrt mJ * (1/mJ) = 1/sqrt mJ   (mJ > 0).                *)
(* ------------------------------------------------------------------------- *)

let PHIMST_FHAT = prove
 (`!(phi:real->complex) mJ a b y. &0 < mJ /\ schwartz phi
     ==> fourier (phimst mJ a b phi) y =
         Cx(&1 / sqrt mJ) * cexp(--(ii * Cx a * Cx(y - b))) * fourier phi ((y -
           b) / mJ)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[phimst] THEN
  MP_TAC(BETA_RULE(ISPECL [`\x. cexp(ii * Cx b * Cx x) * (phi:real->complex)(mJ
    * (x - a))`;
    `Cx(sqrt mJ)`; `y:real`] FOURIER_LMUL)) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MP_TAC(ISPECL [`phi:real->complex`; `mJ:real`; `a:real`;
      `b:real`] SCHWARTZ_MODAFFINE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `y:real` o MATCH_MP SCHWARTZ_MOD_ABSINT) THEN
      REWRITE_TAC[];
    DISCH_THEN SUBST1_TAC] THEN
  MP_TAC(BETA_RULE(ISPECL [`\x. (phi:real->complex)(mJ * (x - a))`; `b:real`;
    `y:real`]
    FOURIER_MODULATION)) THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`phi:real->complex`; `mJ:real`; `a:real`; `y - b:real`]
    FOURIER_PHI_SCALE_SHIFT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC; GSYM CX_MUL] THEN
  ASM_SIMP_TAC[SQRT_SCALE_ID]);;

(* ------------------------------------------------------------------------- *)
(* 286E b(iii): frequency support of phimst.  If fhat = fourier phi is       *)
(* supported in [c,d], then fourier(phimst mJ a b phi) is supported in       *)
(* [b + mJ c, b + mJ d] (support scales by mJ and shifts by b -- exactly the *)
(* frequency-interval transformation of the tile). Immediate from            *)
(* PHIMST_FHAT:                                                              *)
(* the transform is a NONZERO multiple of fhat((y-b)/mJ).                    *)
(* ------------------------------------------------------------------------- *)

let PHIMST_FHAT_SUPPORT = prove
 (`!(phi:real->complex) mJ a b c d. &0 < mJ /\ schwartz phi /\
     (!u. u < c \/ d < u ==> fourier phi u = Cx(&0))
     ==> (!y. y < b + mJ * c \/ b + mJ * d < y
              ==> fourier (phimst mJ a b phi) y = Cx(&0))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `y:real` THEN DISCH_TAC THEN
  ASM_SIMP_TAC[PHIMST_FHAT] THEN
  SUBGOAL_THEN
    `fourier (phi:real->complex) ((y - b) / mJ) = Cx(&0)` SUBST1_TAC THENL
   [FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `((y:real) - b) / mJ` th)) THEN
     ANTS_TAC THENL
     [UNDISCH_TAC `y < b + mJ * c \/ b + mJ * d < y` THEN STRIP_TAC THENL
       [DISJ1_TAC THEN ASM_SIMP_TAC[REAL_LT_LDIV_EQ] THEN ASM_REAL_ARITH_TAC;
        DISJ2_TAC THEN ASM_SIMP_TAC[REAL_LT_RDIV_EQ] THEN ASM_REAL_ARITH_TAC];
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[COMPLEX_MUL_RZERO]];
    REWRITE_TAC[COMPLEX_MUL_RZERO]]);;

(* ------------------------------------------------------------------------- *)
(* 286E b(iv), abstract core: two Schwartz functions with DISJOINT frequency *)
(* supports are L^2-orthogonal.  If for every u at least one of fhat_f(u),   *)
(* ghat(u) vanishes, then <f,g> = INT f cnj g = 0.  Immediate from 284Ob     *)
(* (PARSEVAL_SCHWARTZ_BILINEAR): the transform-side integrand is identically *)
(* 0.                                                                        *)
(* ------------------------------------------------------------------------- *)

(* ========================================================================= *)

(* Structural core: the superlevel set of a monotone-const-monotone g is an  *)
(* interval.  (Order reasoning; the geometric fact that makes the per-level  *)
(* maximal-average bound int_{g>=t} f <= gamma mu{g>=t} applicable.)         *)
let MCM_SUPERLEVEL_INTERVAL = prove
 (`!(gg:real->real) al be t.
     al <= be /\
     (!x y. x <= y /\ y <= al ==> gg x <= gg y) /\
     (!x y. be <= x /\ x <= y ==> gg y <= gg x) /\
     (!x. al <= x /\ x <= be ==> gg x = gg al)
     ==> is_realinterval {x | t <= gg x}`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "inc")
      (CONJUNCTS_THEN2 (LABEL_TAC "dec") (LABEL_TAC "flat")))) THEN
  REWRITE_TAC[is_realinterval; IN_ELIM_THM] THEN
  MAP_EVERY X_GEN_TAC [`x1:real`; `x2:real`; `c:real`] THEN STRIP_TAC THEN
  ASM_CASES_TAC `c <= al` THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(gg:real->real) x1` THEN
    ASM_REWRITE_TAC[] THEN USE_THEN
      "inc" (MP_TAC o SPECL [`x1:real`; `c:real`]) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_CASES_TAC `be <= c` THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(gg:real->real) x2` THEN
    ASM_REWRITE_TAC[] THEN USE_THEN
      "dec" (MP_TAC o SPECL [`c:real`; `x2:real`]) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(gg:real->real) c = gg al` SUBST1_TAC THENL
   [USE_THEN "flat" (MP_TAC o SPEC `c:real`) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REWRITE_TAC[]]; ALL_TAC] THEN
  ASM_CASES_TAC `x1 <= al` THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(gg:real->real) x1` THEN
    ASM_REWRITE_TAC[] THEN USE_THEN
      "inc" (MP_TAC o SPECL [`x1:real`; `al:real`]) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REWRITE_TAC[]];
    SUBGOAL_THEN
      `(gg:real->real) x1 = gg al` (fun th -> ASM_MESON_TAC[th]) THEN
    USE_THEN "flat" (MP_TAC o SPEC `x1:real`) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REWRITE_TAC[]]]);;


let LAYER_CAKE_UNDER_CURVE = prove
 (`!g:real^1->real^1 m.
      (!x. &0 <= drop(g x)) /\ (g has_integral lift m) (:real^1)
      ==> ((\t. lift(measure {x | drop t <= drop(g x) /\ &0 <= drop t}))
           has_integral lift m) (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `measurable {pastecart x y | y IN interval[vec 0, (g:real^1->real^1) x]}`
   ASSUME_TAC THENL
   [ASM_MESON_TAC[INTEGRABLE_IFF_MEASURABLE_UNDER_CURVE; integrable_on];
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP FUBINI_MEASURE_ALT) THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!t. {x:real^1 | pastecart x t IN
                    {pastecart x y | y IN interval[vec 0,(g:real^1->real^1)
                      x]}}
        = {x | drop t <= drop(g x) /\ &0 <= drop t}`
   (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THENL
   [GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_ELIM_PASTECART_THM;
      PASTECART_INJ; IN_INTERVAL_1; DROP_VEC] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `measure {pastecart x y | y IN interval[vec 0, (g:real^1->real^1) x]} = m`
   (fun th -> ASM_MESON_TAC[th]) THEN
  MP_TAC(ISPECL [`g:real^1->real^1`;
    `m:real`] HAS_INTEGRAL_MEASURE_UNDER_CURVE) THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[HAS_MEASURE_MEASURABLE_MEASURE; HAS_MEASURE_UNIQUE]);;

(* Real-valued layer-cake: for nonnegative real g integrating to m over R,   *)
(* the distribution function t |-> real_measure {x | t <= g x} integrates to *)
(* the same m over (0,inf).  This is the M1 workhorse (Fremlin 252O).        *)

let REAL_LAYER_CAKE = prove
 (`!g m. (!x. &0 <= g x) /\ (g has_real_integral m) (:real)
         ==> ((\t. real_measure {x | t <= g x}) has_real_integral m) {t | &0 <
           t}`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[has_real_integral]) THEN
  REWRITE_TAC[IMAGE_LIFT_UNIV] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`lift o g o drop`; `m:real`] LAYER_CAKE_UNDER_CURVE) THEN
  ASM_REWRITE_TAC[o_THM; LIFT_DROP] THEN DISCH_TAC THEN
  REWRITE_TAC[has_real_integral; o_DEF] THEN
  ONCE_REWRITE_TAC[GSYM HAS_INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC HAS_INTEGRAL_SPIKE THEN
  EXISTS_TAC `(\t. lift (measure {x | drop t <= g (drop x) /\ &0 <= drop t}))
              :real^1->real^1` THEN
  EXISTS_TAC `{lift(&0)}` THEN
  ASM_REWRITE_TAC[NEGLIGIBLE_SING] THEN
  REWRITE_TAC[IN_DIFF; IN_SING; IN_IMAGE_LIFT_DROP; IN_ELIM_THM; IN_UNIV] THEN
  X_GEN_TAC `t:real^1` THEN DISCH_TAC THEN
  SUBGOAL_THEN `~(drop t = &0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[LIFT_DROP]; ALL_TAC] THEN
  SUBGOAL_THEN `{x | drop t <= g (drop x) /\ &0 <= drop t} =
                if &0 < drop t then IMAGE lift {x | drop t <= g x} else {}`
    SUBST1_TAC THENL
   [COND_CASES_TAC THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE_LIFT_DROP; IN_ELIM_THM; NOT_IN_EMPTY] THEN
    GEN_TAC THEN REWRITE_TAC[GSYM DROP_EQ; LIFT_DROP] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  COND_CASES_TAC THEN
  ASM_REWRITE_TAC[MEASURE_EMPTY; LIFT_NUM; GSYM REAL_MEASURE_MEASURE]);;

(* ========================================================================= *)
(* Rising-sun infrastructure for the maximal theorem (Fremlin 286A(b)).      *)
(*                                                                           *)
(* The heart of the weak-type bound is a rising-sun argument. We package it  *)
(* as a clean statement about continuous functions: if every interior point  *)
(* of [a,b] is "in shadow" (some later point has a strictly larger value),   *)
(* then the left endpoint value does not exceed the right endpoint value.    *)
(* Applied to F(x) = int_a^x f - t*(x-a), the shadow condition is exactly    *)
(* the running-average maximal condition and the conclusion is the desired   *)
(* interval bound  int_a^b f >= t*(b-a).                                     *)
(* ========================================================================= *)

(* The upper level set {x in [a,b] | c <= ff x} of a continuous ff is        *)
(* real_compact (closed sublevel of a continuous fn, intersect a compact).   *)

let REAL_COMPACT_UPPER_LEVEL = prove
 (`!ff a b c. ff real_continuous_on real_interval[a,b]
      ==> real_compact {x | x IN real_interval[a,b] /\ c <= ff x}`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[real_compact; COMPACT_EQ_BOUNDED_CLOSED] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC BOUNDED_SUBSET THEN EXISTS_TAC `interval[lift a,lift b]` THEN
    REWRITE_TAC[BOUNDED_INTERVAL; GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
      SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `closed {y:real^1 | c <= drop y}` ASSUME_TAC THENL
   [REWRITE_TAC[drop; GSYM real_ge; CLOSED_HALFSPACE_COMPONENT_GE];
     ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE lift {x | x IN real_interval[a,b] /\ c <= ff x} =
    {z | z IN IMAGE lift (real_interval[a,b]) /\
         (lift o (ff:real->real) o drop) z IN {y:real^1 | c <= drop y}}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM; o_THM; LIFT_DROP] THEN
    MESON_TAC[LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_CLOSED_PREIMAGE THEN ASM_REWRITE_TAC[ETA_AX] THEN
  ASM_REWRITE_TAC[GSYM REAL_CONTINUOUS_ON; IMAGE_LIFT_REAL_INTERVAL;
                  CLOSED_INTERVAL]);;

(* The rising-sun lemma. Take the largest maximizer x0 of ff on [a,b]; if x0 *)
(* < b the shadow condition produces a strictly larger value, contradicting  *)
(* maximality, so x0 = b and ff a <= ff c = ff x0 = ff b.                    *)

let RISING_SUN = prove
 (`!ff a b.
      a <= b /\ ff real_continuous_on real_interval[a,b] /\
      (!x. a <= x /\ x < b ==> ?d. x < d /\ d <= b /\ ff x < ff d)
      ==> ff a <= ff b`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`ff:real->real`; `real_interval[a,b]`]
    REAL_CONTINUOUS_ATTAINS_SUP) THEN
  ASM_REWRITE_TAC[REAL_COMPACT_INTERVAL; REAL_INTERVAL_EQ_EMPTY;
    REAL_NOT_LT] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:real` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`ff:real->real`; `a:real`; `b:real`; `ff(c:real):real`]
    REAL_COMPACT_UPPER_LEVEL) THEN ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`\x:real. x`; `{x | x IN real_interval[a,b] /\ ff c <= ff x}`]
    REAL_CONTINUOUS_ATTAINS_SUP) THEN
  ASM_REWRITE_TAC[REAL_CONTINUOUS_ON_ID] THEN
  ANTS_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    EXISTS_TAC `c:real` THEN ASM_REWRITE_TAC[REAL_LE_REFL]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `x0:real` STRIP_ASSUME_TAC) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[IN_ELIM_THM; IN_REAL_INTERVAL]) THEN
  SUBGOAL_THEN `ff(x0:real):real = ff c` ASSUME_TAC THENL
   [ASM_MESON_TAC[REAL_LE_ANTISYM]; ALL_TAC] THEN
  SUBGOAL_THEN `ff(a:real):real <= ff c` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(x0:real < b)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    UNDISCH_TAC `!x. a <= x /\ x < b ==> ?d. x < d /\ d <= b /\ ff x < ff d`
      THEN
    DISCH_THEN(MP_TAC o SPEC `x0:real`) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `ff(d:real) <= ff c` MP_TAC THENL
     [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN ASM_REAL_ARITH_TAC;
      ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `x0:real = b` SUBST_ALL_TAC THENL
   [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]);;

(* The integral form of the rising-sun bound (Fremlin 286A(b), part gamma):  *)
(* if throughout (x,b) there is a later point d with average of f exceeding  *)
(* t,                                                                        *)
(* i.e. (d-x)*t < int_[x,d] f, then int_[a,b] f >= (b-a)*t.  Obtained from   *)
(* RISING_SUN with ff x = int_[a,x] f - t*(x-a) (continuous; shadow <=>      *)
(* the maximal condition via integral additivity).                           *)

let MAXIMAL_INTERVAL_BOUND = prove
 (`!f t a b.
     f real_integrable_on real_interval[a,b] /\ a < b /\
     (!x. a <= x /\ x < b
          ==> ?d. x < d /\ d <= b /\
                  (d - x) * t < real_integral (real_interval[x,d]) f)
     ==> (b - a) * t <= real_integral (real_interval[a,b]) f`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\x. real_integral (real_interval[a,x]) f - t * (x - a)`;
    `a:real`; `b:real`] RISING_SUN) THEN
  REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_CONTINUOUS_ON_SUB THEN CONJ_TAC THENL
       [ASM_SIMP_TAC[REAL_INDEFINITE_INTEGRAL_CONTINUOUS_RIGHT];
        MATCH_MP_TAC REAL_CONTINUOUS_ON_MUL THEN
        REWRITE_TAC[REAL_CONTINUOUS_ON_CONST] THEN
        MATCH_MP_TAC REAL_CONTINUOUS_ON_SUB THEN
        REWRITE_TAC[REAL_CONTINUOUS_ON_ID; REAL_CONTINUOUS_ON_CONST]];
      X_GEN_TAC `x:real` THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real`) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `d:real` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`f:real->real`; `a:real`; `d:real`; `x:real`]
        REAL_INTEGRAL_COMBINE) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC;
          MATCH_MP_TAC REAL_INTEGRABLE_SUBINTERVAL THEN
          MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN
          ASM_REWRITE_TAC[SUBSET_REAL_INTERVAL] THEN ASM_REAL_ARITH_TAC];
        DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REAL_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `real_integral (real_interval[a:real,a]) f = &0` SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN REWRITE_TAC[HAS_REAL_INTEGRAL_REFL];
    ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* The running integral x |-> int_[x,a] f (lower limit varying) is           *)
(* continuous at any point x0 < a. Obtained from                             *)
(* REAL_INDEFINITE_INTEGRAL_CONTINUOUS_LEFT on a neighbourhood [x0-1,a],     *)
(* upgrading within-continuity at the interior point x0 to atreal-continuity *)
(* (delta shrunk to keep inside the interval).                               *)

let RUNNING_INTEGRAL_CONTINUOUS = prove
 (`!f a x0. f real_integrable_on (:real) /\ x0 < a
        ==> (\x. real_integral (real_interval[x,a]) f) real_continuous (atreal
          x0)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `x0 - &1`; `a:real`]
    REAL_INDEFINITE_INTEGRAL_CONTINUOUS_LEFT) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV]; ALL_TAC] THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON_EQ_CONTINUOUS_WITHIN] THEN
  DISCH_THEN(MP_TAC o SPEC `x0:real`) THEN
  ANTS_TAC THENL [REWRITE_TAC[IN_REAL_INTERVAL] THEN
    ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[real_continuous_withinreal; real_continuous_atreal] THEN
  DISCH_TAC THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `min d (min (&1) (a - x0))` THEN
  ASM_REWRITE_TAC[REAL_LT_MIN; REAL_LT_01] THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `x':real` THEN STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[IN_REAL_INTERVAL] THEN ASM_REAL_ARITH_TAC);;

(* The superlevel set of the one-sided maximal function is open (Fremlin     *)
(* 286A(b)(i)). Stated as Fremlin's G_t without any sup: the set of x from   *)
(* which some later point a gives above-threshold average of f. Openness is  *)
(* pointwise continuity of x |-> int_[x,a] f - (a-x)*t (positive at x0, so   *)
(* positive nearby).                                                         *)

let MAXIMAL_SUPERLEVEL_OPEN = prove
 (`!f t. f real_integrable_on (:real) /\ &0 < t
        ==> real_open {x | ?a. x < a /\
                              (a - x) * t < real_integral (real_interval[x,a])
                                f}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_OPEN; open_def] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM; FORALL_LIFT; DIST_LIFT] THEN
  X_GEN_TAC `x0:real` THEN DISCH_THEN(X_CHOOSE_THEN
    `a:real` STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[LIFT_IN_IMAGE_LIFT; IN_ELIM_THM] THEN
  SUBGOAL_THEN
   `(\x. real_integral (real_interval[x,a]) f - (a - x) * t) real_continuous
     (atreal x0)`
   MP_TAC THENL
   [MATCH_MP_TAC REAL_CONTINUOUS_SUB THEN CONJ_TAC THENL
     [MATCH_MP_TAC RUNNING_INTEGRAL_CONTINUOUS THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_CONTINUOUS_MUL THEN
        REWRITE_TAC[REAL_CONTINUOUS_CONST] THEN
      MATCH_MP_TAC REAL_CONTINUOUS_SUB THEN
      REWRITE_TAC[REAL_CONTINUOUS_CONST; REAL_CONTINUOUS_AT_ID]];
    ALL_TAC] THEN
  REWRITE_TAC[real_continuous_atreal; REALLIM_ATREAL] THEN
  DISCH_THEN(MP_TAC o SPEC
    `real_integral (real_interval[x0,a]) f - (a - x0) * t`) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `min d (a - x0)` THEN ASM_REWRITE_TAC[REAL_LT_MIN] THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `x':real` THEN STRIP_TAC THEN EXISTS_TAC `a:real` THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `x':real`) THEN ASM_REAL_ARITH_TAC);;

(* The per-component interval bound (Fremlin 286A(b)(ii), parts              *)
(* alpha-gamma):                                                             *)
(* if (a,b) is a component interval of the superlevel set G_t -- i.e. every  *)
(* interior point is in G_t, and the right endpoint b is not (stated as the  *)
(* one-sided condition int_[b,c] f <= (c-b)*t for all c > b) -- then         *)
(*    (b - a) * t <= int_[a,b] f.                                            *)
(* Proof: (alpha) the shadow witness for an interior x can be capped at b,   *)
(* using b notin G_t and integral additivity; (beta) MAXIMAL_INTERVAL_BOUND  *)
(* on                                                                        *)
(* [z,b] gives (b-z)*t <= int_[z,b] f for each z in (a,b); (gamma) let z ->  *)
(* a                                                                         *)
(* (REALLIM_LE with RUNNING_INTEGRAL_CONTINUOUS).                            *)

let MAXIMAL_COMPONENT_BOUND = prove
 (`!f t a b.
      f real_integrable_on (:real) /\ &0 < t /\ a < b /\
      (!x. a < x /\ x < b
           ==> ?c. x < c /\ (c - x) * t < real_integral (real_interval[x,c]) f)
             /\
      (!c. b < c ==> real_integral (real_interval[b,c]) f <= (c - b) * t)
      ==> (b - a) * t <= real_integral (real_interval[a,b]) f`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 (LABEL_TAC "interior") (LABEL_TAC "bnotin"))))) THEN
  SUBGOAL_THEN
   `!z. a < z /\ z < b ==> (b - z) * t <= real_integral (real_interval[z,b]) f`
   ASSUME_TAC THENL
   [X_GEN_TAC `z:real` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`f:real->real`; `t:real`; `z:real`; `b:real`]
       MAXIMAL_INTERVAL_BOUND) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
      EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV]; ALL_TAC] THEN
    X_GEN_TAC `x:real` THEN STRIP_TAC THEN
    SUBGOAL_THEN `a < x /\ x < b` STRIP_ASSUME_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    USE_THEN "interior" (fun th -> MP_TAC(SPEC `x:real` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `c:real` STRIP_ASSUME_TAC) THEN
    ASM_CASES_TAC `c:real <= b` THENL
     [EXISTS_TAC `c:real` THEN ASM_REWRITE_TAC[] THEN
       ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    EXISTS_TAC `b:real` THEN
    REPEAT CONJ_TAC THENL [ASM_REAL_ARITH_TAC; REAL_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`f:real->real`; `x:real`; `c:real`; `b:real`]
      REAL_INTEGRAL_COMBINE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV]]; ALL_TAC] THEN
    USE_THEN "bnotin" (fun th -> MP_TAC(SPEC `c:real` th)) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_TAC THEN DISCH_THEN(MP_TAC o SYM) THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`atreal a within real_interval[a,b]`;
    `\z:real. (b - z) * t`;
     `\z:real. real_integral (real_interval[z,b]) (f:real->real)`] REALLIM_LE)
       THEN
  REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REALLIM_MUL THEN REWRITE_TAC[REALLIM_CONST] THEN
    MATCH_MP_TAC REALLIM_SUB THEN
      REWRITE_TAC[REALLIM_CONST; REALLIM_WITHINREAL_ID];
    MP_TAC(ISPECL [`f:real->real`; `b:real`;
      `a:real`] RUNNING_INTEGRAL_CONTINUOUS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `real_interval[a,b]` o
       MATCH_MP REAL_CONTINUOUS_ATREAL_WITHINREAL) THEN
    REWRITE_TAC[REAL_CONTINUOUS_WITHINREAL];
    MP_TAC(ISPECL [`real_interval[a,b]`;
      `a:real`] TRIVIAL_LIMIT_WITHIN_REALINTERVAL) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[IN_REAL_INTERVAL] THEN CONJ_TAC THENL
       [REWRITE_TAC[IS_REALINTERVAL_CONNECTED; IMAGE_LIFT_REAL_INTERVAL;
                    CONNECTED_INTERVAL];
        ASM_REAL_ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[EXTENSION; IN_REAL_INTERVAL; IN_SING; NOT_FORALL_THM] THEN
    EXISTS_TAC `b:real` THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[EVENTUALLY_WITHINREAL; IN_REAL_INTERVAL] THEN
    EXISTS_TAC `(b:real) - a` THEN ASM_REWRITE_TAC[REAL_SUB_LT] THEN
    X_GEN_TAC `z:real` THEN STRIP_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The one-dimensional Hardy-Littlewood maximal function (Fremlin 286A).     *)
(* f*(x) = sup of the average of |f| over intervals [a,b] containing x.      *)
(* ------------------------------------------------------------------------- *)

let hl_maximal = new_definition
 `hl_maximal (f:real->real) x =
    sup {real_integral (real_interval[a,b]) (\t. abs(f t)) / (b - a)
        | a,b | a <= x /\ x <= b /\ a < b}`;;

(* The one-sided (forward) maximal function f1*(x) = sup over intervals      *)
(* [x,a]                                                                     *)
(* to the RIGHT of x.  Its superlevel set {x | u < f1* x} is Fremlin's G_u.  *)
(* CAVEAT: the average set can be unbounded above (near an L^1 spike), where *)
(* HOL's sup returns junk; so only the FORWARD inclusion {f1*>u} SUBSET G_u  *)
(* is junk-free (HL_FWD_SUPERLEVEL_SUB). The two agree up to a NULL set (the *)
(* unbounded locus, contained in every G_u hence of measure 0 by the         *)
(* weak-type                                                                 *)
(* bound), which is all the layer-cake needs.                                *)
let hl_maximal_fwd = new_definition
 `hl_maximal_fwd (f:real->real) x =
    sup {real_integral (real_interval[x,a]) f / (a - x) | a | x < a}`;;

(* Junk-free forward inclusion: {x | u < f1* x} SUBSET G_u.  Proved by       *)
(* contrapositive -- if x is NOT in G_u then every average is <= u, so the   *)
(* sup                                                                       *)
(* (now genuinely bounded above by u) is <= u.                               *)
let HL_FWD_SUPERLEVEL_SUB = prove
 (`!f u x. u < hl_maximal_fwd f x
           ==> (?a. x < a /\ (a - x) * u < real_integral (real_interval[x,a])
             f)`,
  REPEAT GEN_TAC THEN GEN_REWRITE_TAC I [GSYM CONTRAPOS_THM] THEN
  REWRITE_TAC[NOT_EXISTS_THM; REAL_NOT_LT; DE_MORGAN_THM] THEN DISCH_TAC THEN
  REWRITE_TAC[hl_maximal_fwd] THEN MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`real_integral (real_interval[x,x + &1]) f / (x + &1 - x)`;
       `x + &1`] THEN
    REWRITE_TAC[] THEN REAL_ARITH_TAC;
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `a:real` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `a:real`) THEN
    ASM_SIMP_TAC[REAL_ARITH `x < a ==> ~(a <= x)`] THEN
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT]]);;

(* Under a uniform bound |f| <= M, the one-sided maximal function is bounded *)
(* by M everywhere (each average of things <= M is <= M;                     *)
(* REAL_INTEGRAL_UBOUND). Hence f1* is FINITE, the sup-junk locus is empty,  *)
(* and the reverse superlevel inclusion G_u SUBSET {f1*>u} holds -- giving   *)
(* the full biconditional needed for the layer-cake to see genuine bounded   *)
(* interval sections.                                                        *)
let HL_FWD_BOUNDED = prove
 (`!f:real->real M. f real_integrable_on (:real) /\ (!x. abs(f x) <= M)
   ==> !x. hl_maximal_fwd f x <= M`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN
  REWRITE_TAC[hl_maximal_fwd] THEN MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`real_integral (real_interval[x,x + &1]) f / (x + &1 - x)`;
       `x + &1`] THEN
    REWRITE_TAC[] THEN REAL_ARITH_TAC;
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `a:real` THEN DISCH_TAC THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN
    MATCH_MP_TAC REAL_INTEGRAL_UBOUND THEN REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[REAL_LT_IMP_LE];
      MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real)` THEN
      ASM_REWRITE_TAC[SUBSET_UNIV];
      GEN_TAC THEN DISCH_TAC THEN
      FIRST_X_ASSUM(fun th -> if concl th = `!x. abs((f:real->real) x) <= M`
         then MP_TAC(SPEC `x':real` th) else NO_TAC) THEN REAL_ARITH_TAC]]);;

(* Reverse superlevel inclusion (needs boundedness): if x IN G_u -- i.e.     *)
(* some                                                                      *)
(* right-average exceeds u -- then u < f1*(x). That average is a member of   *)
(* the                                                                       *)
(* sup-set which, under |f| <= M, is bounded above by M (REAL_LE_SUP         *)
(* applies).                                                                 *)
(* With HL_FWD_SUPERLEVEL_SUB this gives the biconditional {x | u < f1* x} = *)
(* G_u.                                                                      *)
let HL_FWD_SUPERLEVEL_SUPER = prove
 (`!f:real->real M u x. f real_integrable_on (:real) /\ (!x. abs(f x) <= M) /\
     (?a. x < a /\ (a - x) * u < real_integral (real_interval[x,a]) f)
     ==> u < hl_maximal_fwd f x`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[hl_maximal_fwd] THEN
  MATCH_MP_TAC REAL_LTE_TRANS THEN
  EXISTS_TAC `real_integral (real_interval[x,a]) f / (a - x)` THEN
    CONJ_TAC THENL
   [ASM_SIMP_TAC[REAL_LT_RDIV_EQ; REAL_SUB_LT] THEN
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_LE_SUP THEN
    MAP_EVERY EXISTS_TAC
     [`M:real`; `real_integral (real_interval[x,a]) f / (a - x)`] THEN
    REWRITE_TAC[REAL_LE_REFL] THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `a:real` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `b:real` THEN DISCH_TAC THEN
      ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN
      MATCH_MP_TAC REAL_INTEGRAL_UBOUND THEN REPEAT CONJ_TAC THENL
       [ASM_SIMP_TAC[REAL_LT_IMP_LE];
        MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
          EXISTS_TAC `(:real)` THEN
        ASM_REWRITE_TAC[SUBSET_UNIV];
        GEN_TAC THEN DISCH_TAC THEN
        FIRST_X_ASSUM(fun th -> if concl th = `!x. abs((f:real->real) x) <= M`
           then MP_TAC(SPEC `x':real` th) else NO_TAC) THEN
             REAL_ARITH_TAC]]]);;

(* f >= 0 (and bounded) ==> f1* >= 0: the [x,x+1] average is >= 0 and, being *)
(* a member of the (bounded) sup-set, is <= f1*(x).                          *)
let HL_FWD_POS = prove
 (`!f:real->real M. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ (!x.
   abs(f x) <= M)
   ==> !x. &0 <= hl_maximal_fwd f x`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN
    REWRITE_TAC[hl_maximal_fwd] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral (real_interval[x,x + &1]) f / ((x + &1) - x)` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_POS THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
         EXISTS_TAC `(:real)` THEN
        ASM_REWRITE_TAC[SUBSET_UNIV];
        ASM_REWRITE_TAC[]];
      REAL_ARITH_TAC];
    MATCH_MP_TAC REAL_LE_SUP THEN
    MAP_EVERY EXISTS_TAC [`M:real`;
       `real_integral (real_interval[x,x + &1]) f / ((x + &1) - x)`] THEN
    REWRITE_TAC[REAL_LE_REFL] THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `x + &1` THEN REWRITE_TAC[] THEN
       REAL_ARITH_TAC;
      REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `b:real` THEN DISCH_TAC THEN
      ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN
      MATCH_MP_TAC REAL_INTEGRAL_UBOUND THEN REPEAT CONJ_TAC THENL
       [ASM_SIMP_TAC[REAL_LT_IMP_LE];
        MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
          EXISTS_TAC `(:real)` THEN
        ASM_REWRITE_TAC[SUBSET_UNIV];
        GEN_TAC THEN DISCH_TAC THEN
        FIRST_X_ASSUM(fun th -> if concl th = `!x. abs((f:real->real) x) <= M`
           then MP_TAC(SPEC `x':real` th) else NO_TAC) THEN
             REAL_ARITH_TAC]]]);;

(* The running integral x |-> int_[x,a] f, lifted to a real^1->real^1 map,   *)
(* is continuous at y0 whenever drop y0 < a (bridges RUNNING_INTEGRAL_       *)
(* CONTINUOUS to the vector world for the 2D region-openness argument).      *)
let RUNNING_INTEGRAL_CONTINUOUS_LIFT = prove
 (`!f a y0:real^1. f real_integrable_on (:real) /\ drop y0 < a
   ==> (\y:real^1. lift(real_integral (real_interval[drop y, a]) f)) continuous
     (at y0)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `a:real`;
    `drop(y0:real^1)`] RUNNING_INTEGRAL_CONTINUOUS) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[real_continuous_atreal; CONTINUOUS_AT; REALLIM_ATREAL;
    LIM_AT] THEN
  REWRITE_TAC[DIST_LIFT; o_THM; DIST_REAL; GSYM drop] THEN
  DISCH_TAC THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `d:real` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `y:real^1` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `drop(y:real^1)`) THEN
  ASM_REWRITE_TAC[GSYM DIST_REAL; DIST_LIFT; LIFT_DROP] THEN
  ASM_REWRITE_TAC[dist; GSYM DROP_SUB; GSYM NORM_LIFT; LIFT_DROP]);;

(* The 2D region S = {(x,u) | 0 < u /\ x IN G_u} whose 2u-weighted integral  *)
(* gives the p=2 layer-cake is OPEN.  For each fixed a the set               *)
(*   {z | z$1 < a /\ (a - z$1)*z$2 < int_[z$1,a] f}                          *)
(* is the strict-positivity set of the continuous function                   *)
(* Phi(z) = int_[z$1,a] f - (a - z$1)*z$2 (running-integral continuity in    *)
(* z$1 lifted + composed, times the polynomial z$2 part), and S is the union *)
(* over a intersected with the open halfspace {z$2 > 0}.  Openness makes S   *)
(* measurable for FREE -- no measurability of the (sup-junky) f1* needed.    *)
let MAXIMAL_REGION_OPEN_FS = prove
 (`!f:real->real. f real_integrable_on (:real)
   ==> open {z:real^(1,1)finite_sum | &0 < drop(sndcart z) /\
              ?a. drop(fstcart z) < a /\
                  (a - drop(fstcart z)) * drop(sndcart z) <
                  real_integral (real_interval[drop(fstcart z),a]) f}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[OPEN_CONTAINS_BALL] THEN
  X_GEN_TAC `z0:real^(1,1)finite_sum` THEN REWRITE_TAC[IN_ELIM_THM] THEN
    STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^(1,1)finite_sum.
       lift(real_integral (real_interval[drop(fstcart z), a]) f -
            (a - drop(fstcart z)) * drop(sndcart z))) continuous (at z0)`
   MP_TAC THENL
   [REWRITE_TAC[LIFT_SUB] THEN MATCH_MP_TAC CONTINUOUS_SUB THEN CONJ_TAC THENL
     [SUBGOAL_THEN
       `(\z:real^(1,1)finite_sum. lift(real_integral
         (real_interval[drop(fstcart z), a]) f)) =
        (\y:real^1. lift(real_integral (real_interval[drop y, a]) f)) o
          fstcart`
       SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
      MATCH_MP_TAC CONTINUOUS_AT_COMPOSE THEN CONJ_TAC THENL
       [SIMP_TAC[LINEAR_CONTINUOUS_AT; LINEAR_FSTCART];
        MATCH_MP_TAC RUNNING_INTEGRAL_CONTINUOUS_LIFT THEN ASM_REWRITE_TAC[]];
      REWRITE_TAC[LIFT_CMUL] THEN MATCH_MP_TAC CONTINUOUS_MUL THEN
        CONJ_TAC THENL
       [REWRITE_TAC[o_DEF; LIFT_SUB] THEN MATCH_MP_TAC CONTINUOUS_SUB THEN
        REWRITE_TAC[CONTINUOUS_CONST] THEN
        SUBGOAL_THEN
          `(\z:real^(1,1)finite_sum. lift(drop(fstcart z))) =
           fstcart` SUBST1_TAC THENL
         [REWRITE_TAC[FUN_EQ_THM; LIFT_DROP]; ALL_TAC] THEN
        SIMP_TAC[LINEAR_CONTINUOUS_AT; LINEAR_FSTCART];
        SUBGOAL_THEN
          `(\z:real^(1,1)finite_sum. lift(drop(sndcart z))) =
           sndcart` SUBST1_TAC THENL
         [REWRITE_TAC[FUN_EQ_THM; LIFT_DROP]; ALL_TAC] THEN
        SIMP_TAC[LINEAR_CONTINUOUS_AT; LINEAR_SNDCART]]];
    ALL_TAC] THEN
  REWRITE_TAC[CONTINUOUS_AT; LIM_AT; DIST_LIFT] THEN
  DISCH_THEN(MP_TAC o SPEC
    `real_integral (real_interval[drop(fstcart(z0:real^(1,1)finite_sum)), a]) f
      -
     (a - drop(fstcart z0)) * drop(sndcart z0)`) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d1:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `min d1 (min (drop(sndcart(z0:real^(1,1)finite_sum))) (a -
    drop(fstcart z0)))` THEN
  REWRITE_TAC[REAL_LT_MIN] THEN CONJ_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_BALL; IN_ELIM_THM] THEN
  X_GEN_TAC `z:real^(1,1)finite_sum` THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `drop(fstcart(z:real^(1,1)finite_sum)) < a /\ &0 < drop(sndcart z) /\
                dist(z0:real^(1,1)finite_sum,z) < d1` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`z - z0:real^(1,1)finite_sum`; `1`] COMPONENT_LE_NORM) THEN
    MP_TAC(ISPECL [`z - z0:real^(1,1)finite_sum`; `2`] COMPONENT_LE_NORM) THEN
    REWRITE_TAC[DIMINDEX_FINITE_SUM; DIMINDEX_1; ARITH;
      VECTOR_SUB_COMPONENT] THEN
    SUBGOAL_THEN
      `!w:real^(1,1)finite_sum. w$1 = drop(fstcart w) /\ w$2 = drop(sndcart w)`
     (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN REWRITE_TAC[drop] THEN
      SIMP_TAC[FSTCART_COMPONENT; SNDCART_COMPONENT; DIMINDEX_1; ARITH];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `norm(z - z0:real^(1,1)finite_sum) = dist(z0,z)` SUBST1_TAC THENL
     [REWRITE_TAC[dist; NORM_SUB]; ALL_TAC] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN EXISTS_TAC `a:real` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `z:real^(1,1)finite_sum = z0` THENL
   [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:real^(1,1)finite_sum`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[GSYM DIST_NZ] THEN
    ASM_MESON_TAC[DIST_SYM]; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* ========================================================================= *)
(* Hardy-Littlewood maximal estimates (Fremlin 286A).                        *)
(*                                                                           *)
(* Fremlin's 1D proof needs NO Vitali covering: the superlevel set           *)
(* G_t = {x : f1*(x) > t} is open, hence a countable union of intervals,     *)
(* and a rising-sun argument bounds each. Combined with the layer-cake       *)
(* identity (Fremlin 252O) and Fubini.                                       *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* Summation infrastructure for the weak-type bound.                         *)
(* ------------------------------------------------------------------------- *)

(* Integral over a finite disjoint union splits as a sum of integrals.       *)

let REAL_INTEGRAL_DISJOINT_UNIONS = prove
 (`!f D. FINITE D /\ (!C:real->bool. C IN D ==> f real_integrable_on C) /\
      (!C C'. C IN D /\ C' IN D /\ ~(C = C') ==> DISJOINT C C')
      ==> real_integral (UNIONS D) f = sum D (\C. real_integral C f)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
  MP_TAC(ISPECL [`f:real->real`; `\C:real->bool. real_integral C f`;
    `D:(real->bool)->bool`] HAS_REAL_INTEGRAL_UNIONS) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[GSYM REAL_INTEGRABLE_INTEGRAL];
    MAP_EVERY X_GEN_TAC [`C:real->bool`; `C':real->bool`] THEN STRIP_TAC THEN
    REWRITE_TAC[real_negligible] THEN
    SUBGOAL_THEN `C INTER C':real->bool = {}` (fun th -> REWRITE_TAC[th]) THENL
     [ASM_MESON_TAC[DISJOINT]; REWRITE_TAC[IMAGE_CLAUSES;
       NEGLIGIBLE_EMPTY]]]);;

(* Integrability on a finite disjoint union, from integrability on each      *)
(* piece.                                                                    *)

let REAL_INTEGRABLE_DISJOINT_UNIONS = prove
 (`!f D. FINITE D /\ (!C:real->bool. C IN D ==> f real_integrable_on C) /\
      (!C C'. C IN D /\ C' IN D /\ ~(C = C') ==> DISJOINT C C')
      ==> f real_integrable_on (UNIONS D)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[real_integrable_on] THEN
  EXISTS_TAC `sum D (\C. real_integral C (f:real->real))` THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_UNIONS THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[GSYM REAL_INTEGRABLE_INTEGRAL];
    MAP_EVERY X_GEN_TAC [`C:real->bool`; `C':real->bool`] THEN STRIP_TAC THEN
    REWRITE_TAC[real_negligible] THEN
    SUBGOAL_THEN `C INTER C':real->bool = {}` (fun th -> REWRITE_TAC[th]) THENL
     [ASM_MESON_TAC[DISJOINT]; REWRITE_TAC[IMAGE_CLAUSES;
       NEGLIGIBLE_EMPTY]]]);;

(* Finite-union core of the weak-type bound: if D is a finite disjoint       *)
(* family                                                                    *)
(* of measurable sets, each with t*measure(C) <= int_C f, then the same      *)
(* bound                                                                     *)
(* holds for their union.  (Summed via SUM_LE.)                              *)

let WEAK_TYPE_FINITE_CORE = prove
 (`!f t D.
      FINITE D /\
      (!C. C IN D ==> f real_integrable_on C /\ real_measurable C /\
                      t * real_measure C <= real_integral C f) /\
      (!C C'. C IN D /\ C' IN D /\ ~(C = C') ==> DISJOINT C C')
      ==> t * real_measure (UNIONS D) <= real_integral (UNIONS D) f`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\C:real->bool. real_measure C`; `D:(real->bool)->bool`]
    REAL_MEASURE_DISJOINT_UNIONS) THEN
  ASM_SIMP_TAC[HAS_REAL_MEASURE_REAL_MEASURABLE_REAL_MEASURE] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `D:(real->bool)->bool`]
    REAL_INTEGRAL_DISJOINT_UNIONS) THEN
  ASM_SIMP_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[GSYM SUM_LMUL] THEN MATCH_MP_TAC SUM_LE THEN
  ASM_SIMP_TAC[]);;

(* A real number bounded above by y + e for every positive e is at most y.   *)

let REAL_LE_EPSILON = prove
 (`!x y. (!e. &0 < e ==> x <= y + e) ==> x <= y`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC(REAL_ARITH
   `~(x > y) ==> x <= y`) THEN REWRITE_TAC[real_gt] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `(x - y) / &2`) THEN
  ASM_REAL_ARITH_TAC);;

(* Inner regularity at the real level: a real_measurable set is approximated *)
(* from within by compact subsets (bridged from MEASURABLE_INNER_COMPACT).   *)

let REAL_MEASURABLE_INNER_COMPACT = prove
 (`!s e. real_measurable s /\ &0 < e
        ==> ?k. real_compact k /\ k SUBSET s /\ real_measurable k /\
                real_measure s < real_measure k + e`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`IMAGE lift s`; `e:real`] MEASURABLE_INNER_COMPACT) THEN
  ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:real^1->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `IMAGE drop k` THEN
  SUBGOAL_THEN `IMAGE lift (IMAGE drop k) = k` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP] THEN
    REWRITE_TAC[IMAGE_ID] THEN ASM SET_TAC[LIFT_DROP];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[real_compact; REAL_MEASURABLE_MEASURABLE;
    REAL_MEASURE_MEASURE] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[SUBSET; IN_IMAGE]) THEN
  REWRITE_TAC[SUBSET; IN_IMAGE] THEN ASM_MESON_TAC[LIFT_DROP]);;

(* Unbounded real intervals (half-lines and the whole line) are not          *)
(* real_bounded.                                                             *)

let NOT_RBOUNDED_GT = prove
 (`~real_bounded {x | a < x}`,
  REWRITE_TAC[REAL_BOUNDED_POS_LT; NOT_EXISTS_THM] THEN GEN_TAC THEN
  REWRITE_TAC[TAUT `~(p /\ q) <=> p ==> ~q`; NOT_FORALL_THM] THEN
    DISCH_TAC THEN
  EXISTS_TAC `abs a + b + &1` THEN REWRITE_TAC[IN_ELIM_THM; NOT_IMP] THEN
  ASM_REAL_ARITH_TAC);;

let NOT_RBOUNDED_GE = prove
 (`~real_bounded {x | a <= x}`,
  REWRITE_TAC[REAL_BOUNDED_POS_LT; NOT_EXISTS_THM] THEN GEN_TAC THEN
  REWRITE_TAC[TAUT `~(p /\ q) <=> p ==> ~q`; NOT_FORALL_THM] THEN
    DISCH_TAC THEN
  EXISTS_TAC `abs a + b + &1` THEN REWRITE_TAC[IN_ELIM_THM; NOT_IMP] THEN
  ASM_REAL_ARITH_TAC);;

let NOT_RBOUNDED_LT = prove
 (`~real_bounded {x | x < b}`,
  REWRITE_TAC[REAL_BOUNDED_POS_LT; NOT_EXISTS_THM] THEN GEN_TAC THEN
  REWRITE_TAC[TAUT `~(p /\ q) <=> p ==> ~q`; NOT_FORALL_THM] THEN
    DISCH_TAC THEN
  EXISTS_TAC `--(abs b + b' + &1)` THEN REWRITE_TAC[IN_ELIM_THM; NOT_IMP] THEN
  ASM_REAL_ARITH_TAC);;

let NOT_RBOUNDED_LE = prove
 (`~real_bounded {x | x <= b}`,
  REWRITE_TAC[REAL_BOUNDED_POS_LT; NOT_EXISTS_THM] THEN GEN_TAC THEN
  REWRITE_TAC[TAUT `~(p /\ q) <=> p ==> ~q`; NOT_FORALL_THM] THEN
    DISCH_TAC THEN
  EXISTS_TAC `--(abs b + b' + &1)` THEN REWRITE_TAC[IN_ELIM_THM; NOT_IMP] THEN
  ASM_REAL_ARITH_TAC);;

let NOT_RBOUNDED_UNIV = prove
 (`~real_bounded (:real)`,
  REWRITE_TAC[REAL_BOUNDED_POS_LT; NOT_EXISTS_THM] THEN GEN_TAC THEN
  REWRITE_TAC[TAUT `~(p /\ q) <=> p ==> ~q`; NOT_FORALL_THM] THEN
    DISCH_TAC THEN
  EXISTS_TAC `abs b + &1` THEN REWRITE_TAC[IN_UNIV; NOT_IMP] THEN
  ASM_REAL_ARITH_TAC);;

(* A real set with a minimum (resp. maximum) element is not real_open.       *)

let REAL_NOT_OPEN_MIN = prove
 (`!C a. a IN C /\ (!x. x IN C ==> a <= x) ==> ~real_open C`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[REAL_OPEN; open_def]) THEN
  REWRITE_TAC[FORALL_IN_IMAGE; FORALL_LIFT; DIST_LIFT; LIFT_IN_IMAGE_LIFT] THEN
  DISCH_THEN(MP_TAC o SPEC `a:real`) THEN ASM_REWRITE_TAC[NOT_FORALL_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `a - e / &2`) THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `abs((a - e / &2) - a) < e` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `a - e / &2`) THEN
  ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC);;

let REAL_NOT_OPEN_MAX = prove
 (`!C b. b IN C /\ (!x. x IN C ==> x <= b) ==> ~real_open C`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[REAL_OPEN; open_def]) THEN
  REWRITE_TAC[FORALL_IN_IMAGE; FORALL_LIFT; DIST_LIFT; LIFT_IN_IMAGE_LIFT] THEN
  DISCH_THEN(MP_TAC o SPEC `b:real`) THEN ASM_REWRITE_TAC[NOT_FORALL_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `b + e / &2`) THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `abs((b + e / &2) - b) < e` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `b + e / &2`) THEN
  ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC);;

(* A nonempty bounded real_open set is an open interval (a,b) with a < b. By *)
(* IS_REAL_INTERVAL_CASES: unbounded forms killed by NOT_RBOUNDED_*, closed- *)
(* endpoint forms by REAL_NOT_OPEN_MIN/MAX, empty by hypothesis.             *)

let REAL_OPEN_BOUNDED_INTERVAL = prove
 (`!C. real_open C /\ is_realinterval C /\ real_bounded C /\ ~(C = {})
       ==> ?a b. a < b /\ C = real_interval(a,b)`,
  GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [IS_REAL_INTERVAL_CASES]) THEN
  STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[];
    ASM_MESON_TAC[NOT_RBOUNDED_UNIV];
    ASM_MESON_TAC[NOT_RBOUNDED_GT];
    ASM_MESON_TAC[NOT_RBOUNDED_GE];
    ASM_MESON_TAC[NOT_RBOUNDED_LE];
    ASM_MESON_TAC[NOT_RBOUNDED_LT];
    MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN
    SUBGOAL_THEN `a:real < b` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
      REWRITE_TAC[IN_ELIM_THM] THEN REAL_ARITH_TAC;
      ASM_REWRITE_TAC[EXTENSION; IN_REAL_INTERVAL; IN_ELIM_THM]];
    SUBGOAL_THEN `a:real < b` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
      REWRITE_TAC[IN_ELIM_THM] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `~real_open {x | a < x /\ x <= b}` MP_TAC THENL
     [MATCH_MP_TAC REAL_NOT_OPEN_MAX THEN EXISTS_TAC `b:real` THEN
      REWRITE_TAC[IN_ELIM_THM] THEN
      CONJ_TAC THENL [ASM_REAL_ARITH_TAC; X_GEN_TAC `z:real` THEN
        REAL_ARITH_TAC];
      ASM_REWRITE_TAC[]];
    SUBGOAL_THEN `a:real < b` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
      REWRITE_TAC[IN_ELIM_THM] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `~real_open {x | a <= x /\ x < b}` MP_TAC THENL
     [MATCH_MP_TAC REAL_NOT_OPEN_MIN THEN EXISTS_TAC `a:real` THEN
      REWRITE_TAC[IN_ELIM_THM] THEN
      CONJ_TAC THENL [ASM_REAL_ARITH_TAC; X_GEN_TAC `z:real` THEN
        REAL_ARITH_TAC];
      ASM_REWRITE_TAC[]];
    SUBGOAL_THEN `a:real <= b` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
      REWRITE_TAC[IN_ELIM_THM] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `~real_open {x | a <= x /\ x <= b}` MP_TAC THENL
     [MATCH_MP_TAC REAL_NOT_OPEN_MIN THEN EXISTS_TAC `a:real` THEN
      REWRITE_TAC[IN_ELIM_THM] THEN
      CONJ_TAC THENL [ASM_REAL_ARITH_TAC; X_GEN_TAC `z:real` THEN
        REAL_ARITH_TAC];
      ASM_REWRITE_TAC[]]]);;

(* For c a subset of a lifted set, lift o drop is the identity on it.        *)

let LIFT_IMAGE_DROP_SUBSET = prove
 (`!c:real^1->bool s. c SUBSET IMAGE lift s ==> IMAGE lift (IMAGE drop c) = c`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP] THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE] THEN X_GEN_TAC `z:real^1` THEN
  EQ_TAC THENL [STRIP_TAC THEN ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  EXISTS_TAC `z:real^1` THEN ASM_REWRITE_TAC[] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[SUBSET; IN_IMAGE]) THEN
    ASM_MESON_TAC[LIFT_DROP]);;

(* Transfer of openness and interval-ness from a lifted vector set to its    *)
(* drop. (Generalised over c so they apply via MATCH_MP_TAC even in a        *)
(* cluttered assumption context, where REWRITE_TAC[REAL_OPEN] on the goal    *)
(* misbehaves.)                                                              *)

let REAL_OPEN_IMAGE_DROP = prove
 (`!c:real^1->bool. open c /\ IMAGE lift (IMAGE drop c) = c
                    ==> real_open (IMAGE drop c)`,
  GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[REAL_OPEN] THEN ASM_REWRITE_TAC[]);;

let IS_REALINTERVAL_IMAGE_DROP = prove
 (`!c:real^1->bool. connected c /\ IMAGE lift (IMAGE drop c) = c
                    ==> is_realinterval (IMAGE drop c)`,
  GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[IS_REALINTERVAL_CONNECTED] THEN
  ASM_REWRITE_TAC[]);;

(* A real_open set is the union of a pairwise-disjoint family of real_open   *)
(* sets                                                                      *)
(* (its connected components, transferred from the vector world), stated for *)
(* the                                                                       *)
(* EXPLICIT family D0 = IMAGE (IMAGE drop) (components (IMAGE lift s)) so it *)
(* can be                                                                    *)
(* instantiated directly.  This is the family fed to MAXIMAL_WEAK_TYPE_LIFT. *)

let MAXIMAL_COMPONENT_FAMILY = prove
 (`!s. real_open s
       ==> (!C. C IN IMAGE (IMAGE drop) (components (IMAGE lift s)) ==>
         real_open C) /\
           (!C C'. C IN IMAGE (IMAGE drop) (components (IMAGE lift s)) /\
                   C' IN IMAGE (IMAGE drop) (components (IMAGE lift s)) /\ ~(C
                     = C')
                   ==> DISJOINT C C') /\
           UNIONS (IMAGE (IMAGE drop) (components (IMAGE lift s))) = s`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `open (IMAGE lift s)` ASSUME_TAC THENL
   [ASM_MESON_TAC[REAL_OPEN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c:real^1->bool. c IN components (IMAGE lift s) ==> c SUBSET IMAGE lift s`
   ASSUME_TAC THENL [ASM_MESON_TAC[IN_COMPONENTS_SUBSET]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `c:real^1->bool` THEN
     DISCH_TAC THEN
    REWRITE_TAC[REAL_OPEN] THEN
    SUBGOAL_THEN
      `IMAGE lift (IMAGE drop c) = c` (fun th -> REWRITE_TAC[th]) THENL
     [MATCH_MP_TAC LIFT_IMAGE_DROP_SUBSET THEN EXISTS_TAC `s:real->bool` THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[OPEN_COMPONENTS];
    MAP_EVERY X_GEN_TAC [`C:real->bool`; `C':real->bool`] THEN
    REWRITE_TAC[IN_IMAGE] THEN STRIP_TAC THEN
    SUBGOAL_THEN `~(x':real^1->bool = x)` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `DISJOINT (x':real^1->bool) x` MP_TAC THENL
     [MP_TAC(ISPEC `IMAGE lift s` PAIRWISE_DISJOINT_COMPONENTS) THEN
      REWRITE_TAC[pairwise] THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `(x':real^1->bool) SUBSET IMAGE lift s /\ x SUBSET IMAGE lift s`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_IMAGE] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[SUBSET; IN_IMAGE]) THEN
      ASM_MESON_TAC[LIFT_DROP];
    REWRITE_TAC[GSYM IMAGE_UNIONS] THEN
    SUBGOAL_THEN `UNIONS (components (IMAGE lift s)) = IMAGE lift s`
     (fun th -> REWRITE_TAC[th]) THENL
     [MESON_TAC[UNIONS_COMPONENTS]; ALL_TAC] THEN
    REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID]]);;

(* Real-level Heine-Borel: a real_compact set covered by a family of         *)
(* real_open sets is covered by a finite subfamily (bridged from             *)
(* COMPACT_IMP_HEINE_BOREL).                                                 *)

let REAL_COMPACT_HEINE_BOREL_UNIONS = prove
 (`!k D. real_compact k /\ (!C:real->bool. C IN D ==> real_open C) /\
        k SUBSET UNIONS D
        ==> ?D'. D' SUBSET D /\ FINITE D' /\ k SUBSET UNIONS D'`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `IMAGE lift k` COMPACT_IMP_HEINE_BOREL) THEN
  ASM_REWRITE_TAC[GSYM real_compact] THEN
  DISCH_THEN(MP_TAC o SPEC `IMAGE (IMAGE lift) D`) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `C:real->bool` THEN
       DISCH_TAC THEN
      ASM_MESON_TAC[REAL_OPEN];
      REWRITE_TAC[GSYM IMAGE_UNIONS] THEN MATCH_MP_TAC IMAGE_SUBSET THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:(real^1->bool)->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `IMAGE (IMAGE drop) g` THEN
  ASM_SIMP_TAC[FINITE_IMAGE] THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `u:real^1->bool` THEN DISCH_TAC THEN
    SUBGOAL_THEN `u IN IMAGE (IMAGE lift) D` MP_TAC THENL
     [ASM SET_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `C:real->bool` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `IMAGE drop u = C` (fun th -> ASM_MESON_TAC[th]) THEN
    ASM_REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    SUBGOAL_THEN `lift x IN UNIONS g` MP_TAC THENL
     [ASM SET_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[IN_UNIONS] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:real^1->bool` STRIP_ASSUME_TAC) THEN
    REWRITE_TAC[IN_UNIONS] THEN EXISTS_TAC `IMAGE drop u` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:real^1->bool` THEN
       ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `lift x` THEN
      ASM_REWRITE_TAC[LIFT_DROP]]]);;

(* Lifting: for a family D of pairwise-disjoint real_open sets each          *)
(* satisfying t*measure(C) <= int_C f (f >= 0), the same bound holds for     *)
(* their union. This is the reusable heart of the weak-type argument: inner  *)
(* regularity (REAL_MEASURABLE_INNER_COMPACT) reduces to a compact subset K; *)
(* Heine-Borel (REAL_COMPACT_HEINE_BOREL_UNIONS) covers K by a finite        *)
(* subfamily; and WEAK_TYPE_FINITE_CORE bounds that finite union.            *)

let MAXIMAL_WEAK_TYPE_LIFT = prove
 (`!f t D.
      &0 < t /\
      (!C. C IN D ==> real_open C /\ real_measurable C /\
                      f real_integrable_on C /\
                      t * real_measure C <= real_integral C f) /\
      (!C C'. C IN D /\ C' IN D /\ ~(C = C') ==> DISJOINT C C') /\
      real_measurable (UNIONS D) /\ f real_integrable_on (UNIONS D) /\
      (!x. x IN UNIONS D ==> &0 <= f x)
      ==> t * real_measure (UNIONS D) <= real_integral (UNIONS D) f`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_EPSILON THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`UNIONS D:real->bool`; `(e:real) / t`]
    REAL_MEASURABLE_INNER_COMPACT) THEN
  ASM_SIMP_TAC[REAL_LT_DIV] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:real->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`k:real->bool`; `D:(real->bool)->bool`]
    REAL_COMPACT_HEINE_BOREL_UNIONS) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `D':(real->bool)->bool` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `!C:real->bool. C IN D' ==> C IN D` ASSUME_TAC THENL
   [ASM SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `real_measurable (UNIONS D')` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_UNIONS THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `f real_integrable_on (UNIONS D')` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_DISJOINT_UNIONS THEN
     ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `UNIONS D' SUBSET UNIONS D:real->bool` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_UNIONS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `t:real`; `D':(real->bool)->bool`]
    WEAK_TYPE_FINITE_CORE) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  SUBGOAL_THEN `real_measure k <= real_measure (UNIONS D')` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_MEASURE_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `real_integral (UNIONS D') f <= real_integral (UNIONS D) f`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `t * real_measure (UNIONS D) < t * (real_measure k + e / t)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_LMUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `t * (real_measure k + e / t) = t * real_measure k + e`
    ASSUME_TAC THENL
   [REWRITE_TAC[REAL_ADD_LDISTRIB] THEN AP_TERM_TAC THEN
    MATCH_MP_TAC REAL_DIV_LMUL THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `t * real_measure k <= t * real_measure (UNIONS D')` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* Quantitative level-set bound (Fremlin 286A(b)(ii) beta): any x whose      *)
(* average of f from z exceeds the threshold t lies within ||f||_1/t of z.   *)
(* This forces the components of the superlevel set G_t to be bounded (no    *)
(* half-lines).                                                              *)

let MAXIMAL_LEVEL_SET_BOUND = prove
 (`!f t z. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t
     ==> !x. z <= x /\ (x - z) * t <= real_integral (real_interval[z,x]) f
             ==> x <= z + real_integral (:real) f / t`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `real_integral (real_interval[z,x]) f <= real_integral (:real) f`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN
    ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x - z) * t <= real_integral (:real) f` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `x - z <= real_integral (:real) f / t` MP_TAC THENL
   [ONCE_REWRITE_TAC[REAL_ARITH `x - z <= y <=> (x - z) <= y`] THEN
    ASM_SIMP_TAC[REAL_LE_RDIV_EQ]; ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* If a real_open set s contains the open interval (a,b) and also its right  *)
(* endpoint b, the interval extends to the right within s. Contrapositive: a *)
(* component of s of the form (a,b) cannot contain b, i.e. b is not in s.    *)
(* Used to discharge the "endpoint not in G_t" hypothesis of                 *)
(* MAXIMAL_COMPONENT_BOUND.                                                  *)

let REAL_OPEN_INTERVAL_EXTEND_RIGHT = prove
 (`!s a b. real_open s /\ real_interval(a,b) SUBSET s /\ b IN s /\ a < b
           ==> ?b'. b < b' /\ real_interval(a,b') SUBSET s`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "op")
   (CONJUNCTS_THEN2 (LABEL_TAC "sub")
    (CONJUNCTS_THEN2 (LABEL_TAC "bin") (LABEL_TAC "ab")))) THEN
  USE_THEN "op" (MP_TAC o REWRITE_RULE[REAL_OPEN; open_def; FORALL_IN_IMAGE;
     FORALL_LIFT; DIST_LIFT; LIFT_IN_IMAGE_LIFT]) THEN
  DISCH_THEN(MP_TAC o SPEC `b:real`) THEN
  ANTS_TAC THENL [USE_THEN "bin" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `b + e / &2` THEN CONJ_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN X_GEN_TAC `y:real` THEN
    STRIP_TAC THEN
  ASM_CASES_TAC `y < b` THENL
   [USE_THEN "sub" (MP_TAC o REWRITE_RULE[SUBSET; IN_REAL_INTERVAL]) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC;
    FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; SIMP_TAC[]]]);;

let REAL_COMPONENT_ENDPOINT_RIGHT = prove
 (`!s a b. real_open s /\ a < b /\ real_interval(a,b) SUBSET s /\
           (!t. real_interval(a,b) SUBSET t /\ t SUBSET s /\ is_realinterval t
                ==> t = real_interval(a,b))
           ==> ~(b IN s)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`s:real->bool`; `a:real`;
    `b:real`] REAL_OPEN_INTERVAL_EXTEND_RIGHT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b':real` STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `real_interval(a,b')`) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN ASM_REAL_ARITH_TAC;
      ASM_REWRITE_TAC[];
      REWRITE_TAC[IS_REALINTERVAL_INTERVAL]];
    REWRITE_TAC[EXTENSION; IN_REAL_INTERVAL] THEN
    DISCH_THEN(MP_TAC o SPEC `(b + b') / &2`) THEN ASM_REAL_ARITH_TAC]);;

let MAXIMAL_REACH_COMPACT = prove
 (`!f t z. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t
   ==> real_compact {x | z <= x /\ (x - z) * t <= real_integral
     (real_interval[z,x]) f}`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `K = z + real_integral (:real) f / t` THEN
  SUBGOAL_THEN
   `{x | z <= x /\ (x - z) * t <= real_integral (real_interval[z,x]) f}
    = {x | x IN real_interval[z,K] /\
           &0 <= real_integral (real_interval[z,x]) f - (x - z) * t}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_REAL_INTERVAL] THEN
    X_GEN_TAC `x:real` THEN
    SUBGOAL_THEN `z <= x /\ (x - z) * t <= real_integral (real_interval[z,x]) f
                  ==> x <= K` (fun th -> MP_TAC th) THENL
     [EXPAND_TAC "K" THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`f:real->real`; `t:real`;
        `z:real`] MAXIMAL_LEVEL_SET_BOUND) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `x:real`) THEN
      ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[real_compact; COMPACT_EQ_BOUNDED_CLOSED] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC BOUNDED_SUBSET THEN EXISTS_TAC `interval[lift z,lift K]` THEN
    REWRITE_TAC[BOUNDED_INTERVAL; GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
      SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `closed {y:real^1 | &0 <= drop y}` ASSUME_TAC THENL
   [REWRITE_TAC[drop; REAL_ARITH `&0 <= a <=> a >= &0`;
               CLOSED_HALFSPACE_COMPONENT_GE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE lift {x | x IN real_interval[z,K] /\
                    &0 <= real_integral (real_interval[z,x]) f - (x - z) * t}
    = {w | w IN IMAGE lift (real_interval[z,K]) /\
           (lift o (\x. real_integral (real_interval[z,x]) f - (x - z) * t) o
             drop) w
           IN {y:real^1 | &0 <= drop y}}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM; o_THM; LIFT_DROP] THEN
    MESON_TAC[LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_CLOSED_PREIMAGE THEN ASM_REWRITE_TAC[ETA_AX] THEN
  REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; CLOSED_INTERVAL;
    GSYM REAL_CONTINUOUS_ON] THEN
  MATCH_MP_TAC REAL_CONTINUOUS_ON_SUB THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INDEFINITE_INTEGRAL_CONTINUOUS_RIGHT THEN
    MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV];
    MATCH_MP_TAC REAL_CONTINUOUS_ON_MUL THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON_CONST] THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_SUB THEN
    REWRITE_TAC[REAL_CONTINUOUS_ON_ID; REAL_CONTINUOUS_ON_CONST]]);;

(* Fremlin 286A(b)(ii) beta: the right endpoint of a G_t-interval through z  *)
(* is at most z + ||f||_1/t, hence finite. Let M = max A_z (A_z compact via  *)
(* MAXIMAL_REACH_COMPACT, nonempty as z in A_z). If b > M then M lies in the *)
(* open interval (a,b) subset G_t, so M has a G_t-witness c > M with (c-M)t  *)
(* < int_[M,c]f; by additivity int_[z,c]f >= (M-z)t + (c-M)t = (c-z)t, so c  *)
(* in A_z with c > M, contradicting maximality. Thus b <= M <= z + ||f||_1/t *)
(* (MAXIMAL_LEVEL_SET_BOUND).                                                *)

let MAXIMAL_COMPONENT_SUP_BOUND = prove
 (`!f t a b z.
    f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t /\
    a < z /\ z < b /\
    real_interval(a,b) SUBSET
      {x | ?c. x < c /\ (c - x) * t < real_integral (real_interval[x,c]) f}
    ==> b <= z + real_integral (:real) f / t`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `Az = {x | z <= x /\ (x - z) * t <= real_integral
    (real_interval[z,x]) f}` THEN
  SUBGOAL_THEN `(z:real) IN Az` ASSUME_TAC THENL
   [EXPAND_TAC "Az" THEN
     REWRITE_TAC[IN_ELIM_THM; REAL_LE_REFL; REAL_SUB_REFL] THEN
    REWRITE_TAC[REAL_MUL_LZERO] THEN
    SUBGOAL_THEN `real_integral (real_interval[z:real,z]) f = &0`
     (fun th -> REWRITE_TAC[th; REAL_LE_REFL]) THEN
    MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN REWRITE_TAC[HAS_REAL_INTEGRAL_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN `real_compact Az` ASSUME_TAC THENL
   [EXPAND_TAC "Az" THEN MATCH_MP_TAC MAXIMAL_REACH_COMPACT THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\x:real. x`;
    `Az:real->bool`] REAL_CONTINUOUS_ATTAINS_SUP) THEN
  ASM_REWRITE_TAC[REAL_CONTINUOUS_ON_ID] THEN
  ANTS_TAC THENL [ASM_MESON_TAC[MEMBER_NOT_EMPTY]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `M:real` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `z <= M /\ (M - z) * t <= real_integral (real_interval[z,M]) f`
    STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `(M:real) IN Az` THEN EXPAND_TAC "Az" THEN
    REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  SUBGOAL_THEN `M <= z + real_integral (:real) f / t` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`f:real->real`; `t:real`;
     `z:real`] MAXIMAL_LEVEL_SET_BOUND) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `b <= M` (fun th -> ASM_MESON_TAC[th; REAL_LE_TRANS]) THEN
  REWRITE_TAC[GSYM REAL_NOT_LT] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `?c. M < c /\ (c - M) * t < real_integral (real_interval[M,c]) f`
   STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `real_interval(a,b) SUBSET
        {x | ?c. x < c /\ (c - x) * t < real_integral (real_interval[x,c]) f}`
          THEN
    REWRITE_TAC[SUBSET; IN_REAL_INTERVAL; IN_ELIM_THM] THEN
    DISCH_THEN(MP_TAC o SPEC `M:real`) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(c:real) IN Az` MP_TAC THENL
   [EXPAND_TAC "Az" THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`f:real->real`; `z:real`; `c:real`;
      `M:real`] REAL_INTEGRAL_COMBINE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV]];
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `c <= M` MP_TAC THENL [ASM_MESON_TAC[]; ASM_REAL_ARITH_TAC]);;

(* Point version: any x to the right of a base point z in a G_t-component C  *)
(* is within ||f||_1/t of z. (Pick a in C just left of z since C is open,    *)
(* apply MAXIMAL_COMPONENT_SUP_BOUND to the sub-interval (a,x) which lies in *)
(* C hence G_t.)                                                             *)

let MAXIMAL_COMPONENT_PT_SUP = prove
 (`!f t z C x.
    f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t /\
    real_open C /\ is_realinterval C /\ z IN C /\ x IN C /\ z < x /\
    C SUBSET {y | ?c. y < c /\ (c - y) * t < real_integral (real_interval[y,c])
      f}
    ==> x <= z + real_integral (:real) f / t`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `z:real` o
    REWRITE_RULE[REAL_OPEN; open_def; FORALL_IN_IMAGE; FORALL_LIFT; DIST_LIFT;
                 LIFT_IN_IMAGE_LIFT]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN
    `e:real` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC `a = z - e / &2` THEN
  SUBGOAL_THEN `(a:real) IN C` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `a:real`) THEN EXPAND_TAC "a" THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `real_interval(a,x) SUBSET C` ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN X_GEN_TAC `y:real` THEN
     STRIP_TAC THEN
    UNDISCH_TAC `is_realinterval C` THEN REWRITE_TAC[is_realinterval] THEN
    DISCH_THEN(MP_TAC o SPECL [`a:real`; `x:real`; `y:real`]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `t:real`; `a:real`; `x:real`; `z:real`]
    MAXIMAL_COMPONENT_SUP_BOUND) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  CONJ_TAC THENL
   [EXPAND_TAC "a" THEN ASM_REAL_ARITH_TAC; ASM_MESON_TAC[SUBSET_TRANS]]);;

(* Consequently a component C of G_t is real_bounded: every w in C is within *)
(* ||f||_1/t of a fixed base point z (apply the point bound in whichever     *)
(* direction w lies from z).                                                 *)

let MAXIMAL_COMPONENT_BOUNDED = prove
 (`!f t z C.
    f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t /\
    real_open C /\ is_realinterval C /\ z IN C /\
    C SUBSET {y | ?c. y < c /\ (c - y) * t < real_integral (real_interval[y,c])
      f}
    ==> real_bounded C`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= real_integral (:real) f / t` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_DIV THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
    MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[REAL_BOUNDED_POS_LT] THEN
  EXISTS_TAC `abs z + real_integral (:real) f / t + &1` THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `w:real` THEN DISCH_TAC THEN
  SUBGOAL_THEN `w <= z + real_integral (:real) f / t /\
                z <= w + real_integral (:real) f / t` MP_TAC THENL
   [CONJ_TAC THENL
     [ASM_CASES_TAC `z:real < w` THENL
       [MP_TAC(ISPECL [`f:real->real`; `t:real`; `z:real`; `C:real->bool`;
         `w:real`]
          MAXIMAL_COMPONENT_PT_SUP) THEN ASM_REWRITE_TAC[];
        ASM_REAL_ARITH_TAC];
      ASM_CASES_TAC `w:real < z` THENL
       [MP_TAC(ISPECL [`f:real->real`; `t:real`; `w:real`; `C:real->bool`;
         `z:real`]
          MAXIMAL_COMPONENT_PT_SUP) THEN ASM_REWRITE_TAC[];
        ASM_REAL_ARITH_TAC]];
    ASM_REAL_ARITH_TAC]);;

(* Structural facts for a component c (in the vector world) of the           *)
(* superlevel                                                                *)
(* set G_t: its real image IMAGE drop c is real_open, an interval, nonempty, *)
(* and                                                                       *)
(* contained in G_t. (Transfer via REAL_OPEN_IMAGE_DROP /                    *)
(* IS_REALINTERVAL_IMAGE_                                                    *)
(* DROP / OPEN_COMPONENTS / IN_COMPONENTS_*. NB: annotate `open              *)
(* (c:real^1->bool)`                                                         *)
(* -- an unannotated `open c` parses c polymorphically and breaks the        *)
(* proof.)                                                                   *)

let MAXIMAL_COMPONENT_STRUCT = prove
 (`!f t c.
    f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t /\
    c IN components (IMAGE lift
      {y | ?a. y < a /\ (a - y) * t < real_integral (real_interval[y,a]) f})
    ==> real_open (IMAGE drop c) /\ is_realinterval (IMAGE drop c) /\
        ~(IMAGE drop c = {}) /\
        (IMAGE drop c) SUBSET
          {y | ?a. y < a /\ (a - y) * t < real_integral (real_interval[y,a])
            f}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `s = {y | ?a. y < a /\ (a - y) * t < real_integral
    (real_interval[y,a]) f}` THEN
  SUBGOAL_THEN `real_open s` ASSUME_TAC THENL
   [EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_OPEN THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `open (IMAGE lift s)` ASSUME_TAC THENL
    [ASM_MESON_TAC[REAL_OPEN]; ALL_TAC] THEN
  SUBGOAL_THEN `c SUBSET IMAGE lift s` ASSUME_TAC THENL
   [MATCH_MP_TAC IN_COMPONENTS_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `open (c:real^1->bool)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`IMAGE lift s`; `c:real^1->bool`] OPEN_COMPONENTS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP IN_COMPONENTS_CONNECTED) THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP IN_COMPONENTS_NONEMPTY) THEN
  SUBGOAL_THEN `IMAGE lift (IMAGE drop c) = c` ASSUME_TAC THENL
   [MATCH_MP_TAC LIFT_IMAGE_DROP_SUBSET THEN EXISTS_TAC `s:real->bool` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(IMAGE drop c) SUBSET s` ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `y:real` THEN
    REWRITE_TAC[IN_IMAGE] THEN DISCH_THEN(X_CHOOSE_THEN
      `w:real^1` STRIP_ASSUME_TAC) THEN
    UNDISCH_TAC `c SUBSET IMAGE lift s` THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN(MP_TAC o SPEC `w:real^1`) THEN ASM_REWRITE_TAC[IN_IMAGE] THEN
    ASM_MESON_TAC[LIFT_DROP]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_OPEN_IMAGE_DROP THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC IS_REALINTERVAL_IMAGE_DROP THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[IMAGE_EQ_EMPTY] THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* Real-level maximality of a component: any real-interval t with            *)
(* (IMAGE drop c) SUBSET t SUBSET G_t equals IMAGE drop c.                   *)
(* (COMPONENTS_MAXIMAL                                                       *)
(* applied to IMAGE lift t.) Feeds the endpoint lemmas                       *)
(* REAL_COMPONENT_ENDPOINT_*.                                                *)

let MAXIMAL_COMPONENT_MAXIMALITY = prove
 (`!f th c t.
    c IN components (IMAGE lift
      {y | ?a. y < a /\ (a - y) * th < real_integral (real_interval[y,a]) f})
        /\
    IMAGE lift (IMAGE drop c) = c /\ is_realinterval t /\
    (IMAGE drop c) SUBSET t /\
    t SUBSET {y | ?a. y < a /\ (a - y) * th < real_integral
      (real_interval[y,a]) f} /\
    ~(IMAGE drop c = {})
    ==> t = IMAGE drop c`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `s = {y | ?a. y < a /\ (a - y) * th < real_integral
    (real_interval[y,a]) f}` THEN
  SUBGOAL_THEN `connected (IMAGE lift t)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM IS_REALINTERVAL_CONNECTED] THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE lift t SUBSET IMAGE lift s` ASSUME_TAC THENL
   [MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(c INTER IMAGE lift t = {})` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    SUBGOAL_THEN `?y:real. y IN IMAGE drop c` STRIP_ASSUME_TAC THENL
     [ASM_REWRITE_TAC[MEMBER_NOT_EMPTY]; ALL_TAC] THEN
    EXISTS_TAC `lift y` THEN REWRITE_TAC[IN_INTER] THEN CONJ_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th = `IMAGE lift (IMAGE drop c) = c`
                              then SUBST1_TAC(SYM th) else NO_TAC) THEN
      ASM_REWRITE_TAC[LIFT_IN_IMAGE_LIFT];
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `y:real` THEN
        ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `IMAGE drop c SUBSET t` THEN REWRITE_TAC[SUBSET] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE lift t SUBSET c` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`IMAGE lift s`; `IMAGE lift t`;
     `c:real^1->bool`] COMPONENTS_MAXIMAL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `t SUBSET IMAGE drop c` ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `y:real` THEN DISCH_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `lift y` THEN
      REWRITE_TAC[LIFT_DROP] THEN
    UNDISCH_TAC `IMAGE lift t SUBSET c` THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
    EXISTS_TAC `y:real` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[GSYM SUBSET_ANTISYM_EQ]);;

(* Per-component bound: each component c (vector world) of G_t satisfies     *)
(*    t * real_measure(IMAGE drop c) <= real_integral (IMAGE drop c) f.      *)
(* Chain: STRUCT (real_open/interval/nonempty/subset) +                      *)
(* MAXIMAL_COMPONENT_BOUNDED                                                 *)
(* (bounded) + REAL_OPEN_BOUNDED_INTERVAL => IMAGE drop c =                  *)
(* real_interval(a,b),a<b;                                                   *)
(* MAXIMAL_COMPONENT_MAXIMALITY + REAL_COMPONENT_ENDPOINT_RIGHT => b not in  *)
(* G_t;                                                                      *)
(* interior in G_t (subset); MAXIMAL_COMPONENT_BOUND => (b-a)*t <=           *)
(* int_[a,b]f;                                                               *)
(* real_measure(a,b)=b-a, int_(a,b)=int_[a,b]. (NB annotate `(b:real) IN     *)
(* s`.)                                                                      *)

let MAXIMAL_COMPONENT_MEASURE_BOUND = prove
 (`!f t c.
    f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t /\
    c IN components (IMAGE lift
      {y | ?a. y < a /\ (a - y) * t < real_integral (real_interval[y,a]) f})
    ==> t * real_measure (IMAGE drop c) <= real_integral (IMAGE drop c) f`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `s = {y | ?a. y < a /\ (a - y) * t < real_integral
    (real_interval[y,a]) f}` THEN
  SUBGOAL_THEN `real_open s` ASSUME_TAC THENL
   [EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_OPEN THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `t:real`;
    `c:real^1->bool`] MAXIMAL_COMPONENT_STRUCT) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `?z:real. z IN IMAGE drop c` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[MEMBER_NOT_EMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `real_bounded (IMAGE drop c)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`f:real->real`; `t:real`; `z:real`; `IMAGE drop c`]
      MAXIMAL_COMPONENT_BOUNDED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `c SUBSET IMAGE lift s` ASSUME_TAC THENL
   [MATCH_MP_TAC IN_COMPONENTS_SUBSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE lift (IMAGE drop c) = c` ASSUME_TAC THENL
   [MATCH_MP_TAC LIFT_IMAGE_DROP_SUBSET THEN EXISTS_TAC `s:real->bool` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC `IMAGE drop c` REAL_OPEN_BOUNDED_INTERVAL) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
    `b:real` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `!u. real_interval(a,b) SUBSET u /\ u SUBSET s /\ is_realinterval u
        ==> u = real_interval(a,b)` ASSUME_TAC THENL
   [X_GEN_TAC `u:real->bool` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`f:real->real`; `t:real`; `c:real^1->bool`; `u:real->bool`]
      MAXIMAL_COMPONENT_MAXIMALITY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[]; ASM_MESON_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `real_interval(a,b) SUBSET s` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~((b:real) IN s)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_COMPONENT_ENDPOINT_RIGHT THEN
     ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL; REAL_INTEGRAL_OPEN_INTERVAL] THEN
  SUBGOAL_THEN `max (b - a) (&0) = b - a` SUBST1_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
  MP_TAC(ISPECL [`f:real->real`; `t:real`; `a:real`;
    `b:real`] MAXIMAL_COMPONENT_BOUND) THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `x:real` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(x:real) IN s` MP_TAC THENL
     [UNDISCH_TAC `real_interval(a,b) SUBSET s` THEN
      REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN DISCH_THEN MATCH_MP_TAC THEN
      ASM_REAL_ARITH_TAC;
      EXPAND_TAC "s" THEN REWRITE_TAC[IN_ELIM_THM] THEN SIMP_TAC[]];
    UNDISCH_TAC `~((b:real) IN s)` THEN EXPAND_TAC "s" THEN
    REWRITE_TAC[IN_ELIM_THM; NOT_EXISTS_THM] THEN
    DISCH_TAC THEN X_GEN_TAC `cc:real` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `cc:real`) THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC]);;

(* Companion: each component image is real_measurable and f is integrable on *)
(* it (it is a bounded interval).                                            *)

let MAXIMAL_COMPONENT_MEASURABLE = prove
 (`!f t c.
    f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t /\
    c IN components (IMAGE lift
      {y | ?a. y < a /\ (a - y) * t < real_integral (real_interval[y,a]) f})
    ==> real_measurable (IMAGE drop c) /\ f real_integrable_on (IMAGE drop c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `s = {y | ?a. y < a /\ (a - y) * t < real_integral
    (real_interval[y,a]) f}` THEN
  MP_TAC(ISPECL [`f:real->real`; `t:real`;
    `c:real^1->bool`] MAXIMAL_COMPONENT_STRUCT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `?z:real. z IN IMAGE drop c` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[MEMBER_NOT_EMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `real_bounded (IMAGE drop c)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`f:real->real`; `t:real`; `z:real`; `IMAGE drop c`]
      MAXIMAL_COMPONENT_BOUNDED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC `IMAGE drop c` REAL_OPEN_BOUNDED_INTERVAL) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
    `b:real` STRIP_ASSUME_TAC)) THEN
  FIRST_ASSUM(fun th -> if concl th = `IMAGE drop c = real_interval(a,b)`
                        then SUBST1_TAC th else NO_TAC) THEN
  CONJ_TAC THENL
   [REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
    REWRITE_TAC[REAL_INTEGRABLE_ON_OPEN_INTERVAL] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV]]);;

(* The measure of any finite subfamily of G_t's component-images is at most  *)
(* ||f||_1 / t. (Per-component bounds summed via WEAK_TYPE_FINITE_CORE, then *)
(* the                                                                       *)
(* union integral bounded by int over R.) This is the uniform partial-sum    *)
(* bound                                                                     *)
(* needed to conclude G_t is real_measurable via                             *)
(* REAL_MEASURABLE_COUNTABLE_UNIONS_                                         *)
(* STRONG, even when G_t is unbounded.                                       *)

let MAXIMAL_FINITE_MEASURE_BOUND = prove
 (`!f t D'.
    f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t /\ FINITE D' /\
    D' SUBSET IMAGE (IMAGE drop) (components (IMAGE lift
      {y | ?a. y < a /\ (a - y) * t < real_integral (real_interval[y,a]) f}))
    ==> real_measure (UNIONS D') <= real_integral (:real) f / t`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `s = {y | ?a. y < a /\ (a - y) * t < real_integral
    (real_interval[y,a]) f}` THEN
  SUBGOAL_THEN
   `!C. C IN D' ==> f real_integrable_on C /\ real_measurable C /\
                    t * real_measure C <= real_integral C f`
   ASSUME_TAC THENL
   [X_GEN_TAC `C:real->bool` THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `?c. C =
       IMAGE drop c /\ c IN components (IMAGE lift s)` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `D' SUBSET IMAGE (IMAGE drop) (components (IMAGE lift s))`
       THEN
      REWRITE_TAC[SUBSET; IN_IMAGE] THEN
        DISCH_THEN(MP_TAC o SPEC `C:real->bool`) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM SUBST1_TAC THEN
    MP_TAC(ISPECL [`f:real->real`; `t:real`;
      `c:real^1->bool`] MAXIMAL_COMPONENT_MEASURABLE) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`f:real->real`; `t:real`;
      `c:real^1->bool`] MAXIMAL_COMPONENT_MEASURE_BOUND) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC `s:real->bool` MAXIMAL_COMPONENT_FAMILY) THEN
  ANTS_TAC THENL
   [EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_OPEN THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN
    `!C C':real->bool. C IN D' /\ C' IN D' /\ ~(C = C') ==> DISJOINT C C'`
   ASSUME_TAC THENL
   [ASM_MESON_TAC[SUBSET]; ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `t:real`;
    `D':(real->bool)->bool`] WEAK_TYPE_FINITE_CORE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `!C:real->bool. C IN D' ==> f real_integrable_on C` ASSUME_TAC THENL
   [X_GEN_TAC `C:real->bool` THEN DISCH_TAC THEN
    UNDISCH_TAC `!C:real->bool. C IN D' ==> f real_integrable_on C /\
      real_measurable C /\
                    t * real_measure C <= real_integral C f` THEN
    DISCH_THEN(MP_TAC o SPEC `C:real->bool`) THEN ASM_REWRITE_TAC[] THEN
      SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `real_integral (UNIONS D') f <= real_integral (:real) f` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_DISJOINT_UNIONS THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `t * real_measure (UNIONS D') <= real_integral (:real) f` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
  ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The superlevel set G_t of the one-sided maximal function is               *)
(* real_measurable.                                                          *)
(* G_t is real_open (MAXIMAL_SUPERLEVEL_OPEN) but possibly UNBOUNDED, so we  *)
(* decompose IMAGE lift G_t into its (countably many) connected components,  *)
(* enumerate them (COUNTABLE_AS_IMAGE), and apply the STRONG countable-union *)
(* measurability criterion whose partial measures are bounded by ||f||_1 / t *)
(* (MAXIMAL_FINITE_MEASURE_BOUND).  Empty-component case handled separately. *)
(* ------------------------------------------------------------------------- *)
let MAXIMAL_SUPERLEVEL_MEASURABLE = prove
 (`!f t. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t
   ==> real_measurable
        {x | ?a. x < a /\ (a - x) * t < real_integral (real_interval[x,a]) f}`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `s = {y | ?a. y < a /\ (a - y) * t < real_integral
    (real_interval[y,a]) f}` THEN
  SUBGOAL_THEN `real_open s` ASSUME_TAC THENL
   [EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_OPEN THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `open (IMAGE lift s)` ASSUME_TAC THENL
    [ASM_MESON_TAC[REAL_OPEN]; ALL_TAC] THEN
  ASM_CASES_TAC `components (IMAGE lift s) = {}` THENL
   [SUBGOAL_THEN `s:real->bool = {}` SUBST1_TAC THENL
     [MP_TAC(ISPEC `IMAGE lift s` UNIONS_COMPONENTS) THEN
       ASM_REWRITE_TAC[UNIONS_0] THEN
      REWRITE_TAC[IMAGE_EQ_EMPTY] THEN SIMP_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[REAL_MEASURABLE_EMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `COUNTABLE (components (IMAGE lift s))` ASSUME_TAC THENL
   [MATCH_MP_TAC COUNTABLE_COMPONENTS THEN
     MATCH_MP_TAC OPEN_IMP_LOCALLY_CONNECTED THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC `components (IMAGE lift s)` COUNTABLE_AS_IMAGE) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `g:num->real^1->bool`) THEN
  SUBGOAL_THEN
    `!n. (g:num->real^1->bool) n IN components (IMAGE lift s)` ASSUME_TAC THENL
   [GEN_TAC THEN FIRST_ASSUM(fun th ->
      if concl th = `components (IMAGE lift s) = IMAGE (g:num->real^1->bool)
        (:num)`
      then SUBST1_TAC th else NO_TAC) THEN
    REWRITE_TAC[IN_IMAGE; IN_UNIV] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `s = UNIONS {IMAGE drop ((g:num->real^1->bool) n) | n IN (:num)}`
    SUBST1_TAC THENL
   [MP_TAC(ISPEC `s:real->bool` MAXIMAL_COMPONENT_FAMILY) THEN
     ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o last o CONJUNCTS) THEN
    ASM_REWRITE_TAC[SIMPLE_IMAGE; GSYM IMAGE_o; o_DEF] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_THEN
    `components (IMAGE lift s) = IMAGE (g:num->real^1->bool) (:num)` (K
    ALL_TAC) THEN
  MATCH_MP_TAC REAL_MEASURABLE_COUNTABLE_UNIONS_STRONG THEN
  EXISTS_TAC `real_integral (:real) f / t` THEN CONJ_TAC THENL
   [X_GEN_TAC `n:num` THEN
    MP_TAC(ISPECL [`f:real->real`; `t:real`; `(g:num->real^1->bool) n`]
      MAXIMAL_COMPONENT_MEASURABLE) THEN
    ASM_REWRITE_TAC[] THEN SIMP_TAC[];
    X_GEN_TAC `n:num` THEN
    MP_TAC(ISPECL [`f:real->real`; `t:real`;
      `{IMAGE drop ((g:num->real^1->bool) k) | k <= n}`]
      MAXIMAL_FINITE_MEASURE_BOUND) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
     [REWRITE_TAC[SET_RULE `{(fn:num->real->bool) k | k <= n} = IMAGE fn {k | k
       <= n}`] THEN
      SIMP_TAC[FINITE_IMAGE; FINITE_NUMSEG_LE];
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
      ASM_REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `(g:num->real^1->bool) k` THEN
      ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* f is real_integrable_on G_t (needed as a global hypothesis of the LIFT).  *)
(* Route: f is real_measurable_on R (integrable), G_t is real_lebesgue_      *)
(* measurable (from MAXIMAL_SUPERLEVEL_MEASURABLE), so the restriction       *)
(* f*1_{G_t} is real_measurable_on R and bounded by the integrable f (f >=   *)
(* 0),                                                                       *)
(* hence integrable on R; REAL_INTEGRABLE_RESTRICT_INTER then gives f on     *)
(* G_t.                                                                      *)
(* ------------------------------------------------------------------------- *)

let MAXIMAL_SUPERLEVEL_INTEGRABLE = prove
 (`!f t. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t
   ==> f real_integrable_on
        {x | ?a. x < a /\ (a - x) * t < real_integral (real_interval[x,a]) f}`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `s = {x | ?a. x < a /\ (a - x) * t < real_integral
    (real_interval[x,a]) f}` THEN
  SUBGOAL_THEN `real_measurable s` ASSUME_TAC THENL
   [EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_MEASURABLE THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x. if x IN s then f x else &0) real_integrable_on (:real)` MP_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
    EXISTS_TAC `f:real->real` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
       [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
          ASM_REWRITE_TAC[]];
      GEN_TAC THEN DISCH_TAC THEN COND_CASES_TAC THENL
       [ASM_SIMP_TAC[real_abs; REAL_LE_REFL];
        REWRITE_TAC[REAL_ABS_NUM] THEN ASM_REWRITE_TAC[]]];
    REWRITE_TAC[REAL_INTEGRABLE_RESTRICT_INTER; INTER_UNIV]]);;

(* ------------------------------------------------------------------------- *)
(* Intermediate weak-type bound (Fremlin 286A(b)(iii)). For f >= 0           *)
(* integrable                                                                *)
(* and t > 0, the superlevel set G_t of the one-sided maximal function has   *)
(*    t * measure(G_t) <= int_{G_t} f.                                       *)
(* Assembled by instantiating MAXIMAL_WEAK_TYPE_LIFT with the component      *)
(* family                                                                    *)
(* D0 = IMAGE(IMAGE drop)(components(IMAGE lift G_t)); per-component facts   *)
(* from                                                                      *)
(* MAXIMAL_COMPONENT_{STRUCT,MEASURABLE,MEASURE_BOUND}, global facts from    *)
(* MAXIMAL_COMPONENT_FAMILY + MAXIMAL_SUPERLEVEL_{MEASURABLE,INTEGRABLE}.    *)
(* ------------------------------------------------------------------------- *)

let MAXIMAL_WEAK_TYPE = prove
 (`!f t. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t
         ==> t * real_measure {x | ?a. x < a /\
                      (a - x) * t < real_integral (real_interval[x,a]) f}
             <= real_integral
                  {x | ?a. x < a /\
                       (a - x) * t < real_integral (real_interval[x,a]) f} f`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `s = {y | ?a. y < a /\ (a - y) * t < real_integral
    (real_interval[y,a]) f}` THEN
  SUBGOAL_THEN `real_open s` ASSUME_TAC THENL
   [EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_OPEN THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `t:real`;
    `IMAGE (IMAGE drop) (components (IMAGE lift s))`] MAXIMAL_WEAK_TYPE_LIFT)
      THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `c:real^1->bool` THEN
       DISCH_TAC THEN
      REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL [`f:real->real`; `t:real`;
         `c:real^1->bool`] MAXIMAL_COMPONENT_STRUCT) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[];
        MP_TAC(ISPECL [`f:real->real`; `t:real`;
          `c:real^1->bool`] MAXIMAL_COMPONENT_MEASURABLE) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[];
        MP_TAC(ISPECL [`f:real->real`; `t:real`;
          `c:real^1->bool`] MAXIMAL_COMPONENT_MEASURABLE) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[];
        MP_TAC(ISPECL [`f:real->real`; `t:real`;
          `c:real^1->bool`] MAXIMAL_COMPONENT_MEASURE_BOUND) THEN
        ASM_REWRITE_TAC[]];
      MP_TAC(ISPEC `s:real->bool` MAXIMAL_COMPONENT_FAMILY) THEN
        ASM_REWRITE_TAC[] THEN
      SIMP_TAC[];
      MP_TAC(ISPEC `s:real->bool` MAXIMAL_COMPONENT_FAMILY) THEN
        ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o last o CONJUNCTS) THEN DISCH_THEN SUBST1_TAC THEN
      EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_MEASURABLE THEN
        ASM_REWRITE_TAC[];
      MP_TAC(ISPEC `s:real->bool` MAXIMAL_COMPONENT_FAMILY) THEN
        ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o last o CONJUNCTS) THEN DISCH_THEN SUBST1_TAC THEN
      EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_INTEGRABLE THEN
        ASM_REWRITE_TAC[]];
    MP_TAC(ISPEC `s:real->bool` MAXIMAL_COMPONENT_FAMILY) THEN
      ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o last o CONJUNCTS) THEN DISCH_THEN SUBST1_TAC THEN
    EXPAND_TAC "s" THEN REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* L^2 assembly helpers (Fremlin 286A(c), specialized to p = 2).             *)
(* ------------------------------------------------------------------------- *)

(* The positive part (f - c)_+ = max 0 (f - c) is integrable, for f >= 0     *)
(* integrable and c >= 0 (dominated by f itself since c >= 0).               *)
let POS_PART_INTEGRABLE = prove
 (`!f c. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 <= c
         ==> (\x. max (&0) (f x - c)) real_integrable_on (:real)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `f:real->real` THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MAX THEN
    REWRITE_TAC[REAL_MEASURABLE_ON_CONST] THEN
    MATCH_MP_TAC REAL_MEASURABLE_ON_SUB THEN
    REWRITE_TAC[REAL_MEASURABLE_ON_CONST] THEN
    MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(REAL_ARITH `&0 <= fx /\ &0 <= c ==> abs(max (&0) (fx - c)) <=
      fx`) THEN
    ASM_REWRITE_TAC[]]);;

(* A non-negative function integrable on R is integrable on any measurable   *)
(* subset (restrict, dominate by the whole-line function, RESTRICT_INTER).   *)
let INTEGRABLE_ON_MEASURABLE_SUBSET_UNIV = prove
 (`!g s. g real_integrable_on (:real) /\ (!x. &0 <= g x) /\ real_measurable s
         ==> g real_integrable_on s`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\x. if x IN s then g x else &0) real_integrable_on (:real)` MP_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
    EXISTS_TAC `g:real->real` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
       [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
          ASM_REWRITE_TAC[]];
      GEN_TAC THEN DISCH_TAC THEN COND_CASES_TAC THENL
       [ASM_SIMP_TAC[real_abs; REAL_LE_REFL];
        REWRITE_TAC[REAL_ABS_NUM] THEN ASM_REWRITE_TAC[]]];
    REWRITE_TAC[REAL_INTEGRABLE_RESTRICT_INTER; INTER_UNIV]]);;

(* A constant is integrable on a measurable set, with integral c * measure.  *)
let CONST_INTEGRABLE_MEASURABLE = prove
 (`!s c. real_measurable s
         ==> (\x:real. c) real_integrable_on s /\
             real_integral s (\x:real. c) = c * real_measure s`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `(\x:real. &1) real_integrable_on s` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\x:real. &1`; `s:real->bool`;
     `(:real)`] REAL_INTEGRABLE_RESTRICT_INTER) THEN
    REWRITE_TAC[INTER_UNIV] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    FIRST_ASSUM(MP_TAC o REWRITE_RULE[REAL_MEASURABLE_REAL_INTEGRABLE]) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(\x:real. c) = (\x:real. c * &1)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_MUL_RID]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN ASM_REWRITE_TAC[];
    ASM_SIMP_TAC[REAL_INTEGRAL_LMUL] THEN
    ASM_SIMP_TAC[REAL_INTEGRAL_REAL_MEASURE] THEN REAL_ARITH_TAC]);;

(* FTC brick for the p=2 layer-cake: int_[0,A] 2u du = A^2 (A >= 0).         *)
(* Gives the pointwise identity g(x)^2 = int_[0,g(x)] 2u du used to turn     *)
(* int g^2 into the weighted layer-cake int_{u>0} 2u mu{g>u} du via Fubini.  *)
let INTEGRAL_2U = prove
 (`!A. &0 <= A ==> ((\u. &2 * u) has_real_integral A pow 2)
   (real_interval[&0,A])`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\u:real. u pow 2`; `\u:real. &2 * u`; `&0:real`; `A:real`]
    REAL_FUNDAMENTAL_THEOREM_OF_CALCULUS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
    REAL_DIFF_TAC THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[REAL_POW_1] THEN REAL_ARITH_TAC;
    REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    CONV_TAC REAL_RAT_REDUCE_CONV THEN REWRITE_TAC[REAL_SUB_RZERO]]);;

(* Inner 1D integral (part B of the p=2 layer-cake bound):                   *)
(*   int_{u>0} (A - u/2)_+ du = A^2   for A >= 0.                            *)
(* The integrand is supported on (0,2A] where it equals A - u/2 (antideriv   *)
(* A*u - u^2/4), and vanishes on (2A,inf); split the domain as [0,2A] union  *)
(* (2A,inf) (HAS_REAL_INTEGRAL_UNION) and spike-set to (0,inf).              *)
let INNER_POS_PART_INTEGRAL = prove
 (`!A. &0 <= A
   ==> ((\u. max (&0) (A - u / &2)) has_real_integral A pow 2) {u | &0 < u}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE_SET THEN
  EXISTS_TAC `real_interval[&0, &2 * A] UNION {u | &2 * A < u}` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `{&0}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_SING] THEN
    REWRITE_TAC[SUBSET; IN_UNION; IN_DIFF; IN_ELIM_THM; IN_SING;
      IN_REAL_INTERVAL] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `A pow 2 = A pow 2 + &0` SUBST1_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_UNION THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE THEN
    EXISTS_TAC `\u. A - u / &2` THEN EXISTS_TAC `{}:real->bool` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY; IN_DIFF; NOT_IN_EMPTY] THEN
      CONJ_TAC THENL
     [X_GEN_TAC `u:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
      REWRITE_TAC[REAL_ARITH `max (&0) (A - u / &2) = A - u / &2 <=> &0 <= A -
        u / &2`] THEN
      ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(\u. A * u - u pow 2 / &4) (&2 * A) - (\u. A * u - u pow 2 / &4) (&0) = A
       pow 2`
     (fun th -> ONCE_REWRITE_TAC[GSYM th]) THENL
     [REWRITE_TAC[] THEN CONV_TAC REAL_RING; ALL_TAC] THEN
    MATCH_MP_TAC REAL_FUNDAMENTAL_THEOREM_OF_CALCULUS THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      REPEAT STRIP_TAC THEN REAL_DIFF_TAC THEN
      CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[REAL_POW_1] THEN
        REAL_ARITH_TAC];
    MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE THEN
    EXISTS_TAC `\u:real. &0` THEN EXISTS_TAC `{}:real->bool` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY; IN_DIFF; NOT_IN_EMPTY;
      HAS_REAL_INTEGRAL_0] THEN
    X_GEN_TAC `u:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
    REWRITE_TAC[REAL_ARITH `max (&0) (A - u / &2) = &0 <=> A - u / &2 <= &0`]
      THEN
    ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `{&2 * A}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_SING] THEN
    REWRITE_TAC[SUBSET; IN_INTER; IN_REAL_INTERVAL; IN_ELIM_THM; IN_SING] THEN
    ASM_REAL_ARITH_TAC]);;

(* x-slice inner integral for the p=2 weighted layer-cake (real level):      *)
(*   int_{u>0} (if u < A then 2u else 0) du = A^2   for A >= 0.              *)
(* This is the vertical slice of the weighted region integrand 2u over       *)
(* {0 < u < g(x)} at a fixed x with A = g(x); reuses INTEGRAL_2U on [0,A]    *)
(* and vanishes on (A,inf), split via HAS_REAL_INTEGRAL_UNION.               *)
let XSLICE_REAL = prove
 (`!A. &0 <= A
   ==> ((\u. if u < A then &2 * u else &0) has_real_integral A pow 2) {u | &0 <
     u}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE_SET THEN
  EXISTS_TAC `real_interval[&0, A] UNION {u | A < u}` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `{&0}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_SING; SUBSET; IN_UNION; IN_DIFF; IN_ELIM_THM;
      IN_SING; IN_REAL_INTERVAL] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `A pow 2 = A pow 2 + &0` SUBST1_TAC THENL
    [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_UNION THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE THEN
    EXISTS_TAC `\u. &2 * u` THEN EXISTS_TAC `{A:real}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_SING; IN_DIFF; IN_SING] THEN CONJ_TAC THENL
     [X_GEN_TAC `u:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      ASM_SIMP_TAC[INTEGRAL_2U]];
    MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE THEN
    EXISTS_TAC `\u:real. &0` THEN EXISTS_TAC `{}:real->bool` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY; IN_DIFF; NOT_IN_EMPTY;
      HAS_REAL_INTEGRAL_0] THEN
    X_GEN_TAC `u:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `{A:real}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_SING; SUBSET; IN_INTER; IN_REAL_INTERVAL;
      IN_ELIM_THM; IN_SING] THEN ASM_REAL_ARITH_TAC]);;

(* u-slice inner integral for the p=2 weighted layer-cake (vector level):    *)
(* for fixed u > 0 with {x | u < g x} real_measurable, the horizontal slice  *)
(* int_{x:real^1} (if 0<u<g(drop x) then lift(2u) else 0) =                  *)
(* lift(2u*mu{u<g}).                                                         *)
(* The integrand is (2u) times the indicator of IMAGE lift {x | u < g x};    *)
(* use                                                                       *)
(* HAS_INTEGRAL_CMUL + the HAS_MEASURE definition (indicator has_integral    *)
(* lift(measure)).  This is the inner integral of FUBINI_INTEGRAL_ALT.       *)
let MAXIMAL_WEAK_TYPE_REFINED = prove
 (`!f t. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < t
   ==> t * real_measure {x | ?a. x < a /\ (a - x) * t < real_integral
     (real_interval[x,a]) f}
       <= &2 * real_integral (:real) (\x. max (&0) (f x - t / &2))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `s = {x | ?a. x < a /\ (a - x) * t < real_integral
    (real_interval[x,a]) f}` THEN
  MP_TAC(ISPECL [`f:real->real`; `t:real`] MAXIMAL_WEAK_TYPE) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `real_measurable s` ASSUME_TAC THENL
   [EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_MEASURABLE THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `f real_integrable_on s` ASSUME_TAC THENL
   [EXPAND_TAC "s" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_INTEGRABLE THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x. max (&0) (f x - t / &2)) real_integrable_on (:real)` ASSUME_TAC THENL
   [MATCH_MP_TAC POS_PART_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
     ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x. max (&0) (f x - t / &2)) real_integrable_on s` ASSUME_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_ON_MEASURABLE_SUBSET_UNIV THEN
     ASM_REWRITE_TAC[] THEN
    GEN_TAC THEN REWRITE_TAC[] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`s:real->bool`; `t / &2`] CONST_INTEGRABLE_MEASURABLE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `real_integral s f
    <= real_integral s (\x. max (&0) (f x - t / &2)) + t / &2 * real_measure s`
   ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th ->
       if concl th = `real_integral s (\x:real. t / &2) = t / &2 * real_measure
         s`
       then SUBST1_TAC(SYM th) else NO_TAC) THEN
    ASM_SIMP_TAC[GSYM REAL_INTEGRAL_ADD] THEN
    MATCH_MP_TAC REAL_INTEGRAL_LE THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_ADD THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral s (\x. max (&0) (f x - t / &2))
    <= real_integral (:real) (\x. max (&0) (f x - t / &2))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* Measurability brick: a real-measurable f on R, precomposed with the first *)
(* coordinate projection, is (lift-)measurable on R^2.  (Via                 *)
(* MEASURABLE_ON_COMPOSE_FSTCART at N:=1; the real<->vector bridge           *)
(* real_measurable_on = lift o f o drop measurable_on IMAGE lift.)           *)
let LIFTF_MEAS = prove
 (`!f:real->real.
     f real_measurable_on (:real)
     ==> (\z:real^(1,1)finite_sum. lift(f(drop(fstcart z)))) measurable_on
       (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\y:real^1. lift((f:real->real)(drop y))`]
    (INST_TYPE [`:1`,`:N`] MEASURABLE_ON_COMPOSE_FSTCART)) THEN
  REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [RULE_ASSUM_TAC(REWRITE_RULE[real_measurable_on; IMAGE_LIFT_UNIV;
     o_DEF]) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[]]);;

(* The height coordinate u = drop(sndcart z), scaled, is (lift-)measurable   *)
(* on R^2 -- it is linear (LINEAR_SNDCART) hence continuous.                 *)
let SND_MEAS = prove
 (`(\z:real^(1,1)finite_sum. lift(drop(sndcart z) / &2)) measurable_on
   (:real^(1,1)finite_sum)`,
  MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  SUBGOAL_THEN
   `(\z:real^(1,1)finite_sum. lift(drop(sndcart z) / &2)) =
    (\z:real^(1,1)finite_sum. (&1 / &2) % sndcart z)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [GSYM LIFT_DROP] THEN
    REWRITE_TAC[GSYM LIFT_CMUL] THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
  SIMP_TAC[LINEAR_CONTINUOUS_ON; LINEAR_SNDCART]);;

(* Hence  z |-> lift(f(x) - u/2)  (x = fstcart, u = sndcart) is measurable.  *)
let DIFF_MEAS = prove
 (`!f:real->real. f real_measurable_on (:real)
   ==> (\z:real^(1,1)finite_sum. lift(f(drop(fstcart z)) - drop(sndcart z) /
     &2))
       measurable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^(1,1)finite_sum. lift(f(drop(fstcart z)) - drop(sndcart z) / &2))
     =
    (\z:real^(1,1)finite_sum. lift(f(drop(fstcart z))) - lift(drop(sndcart z) /
      &2))`
   SUBST1_TAC THENL [REWRITE_TAC[LIFT_SUB]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_SUB THEN
  ASM_SIMP_TAC[LIFTF_MEAS; SND_MEAS]);;

(* And the positive part  z |-> lift(max 0 (f(x) - u/2))  is measurable, via *)
(* the identity max 0 a = (a + abs a)/2 (MEASURABLE_ON_LIFT_ABS + ADD +      *)
(* CMUL).                                                                    *)
let MAXPART_MEAS = prove
 (`!f:real->real. f real_measurable_on (:real)
   ==> (\z:real^(1,1)finite_sum. lift(max (&0) (f(drop(fstcart z)) -
     drop(sndcart z) / &2)))
       measurable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^(1,1)finite_sum. lift(max (&0) (f(drop(fstcart z)) - drop(sndcart
     z) / &2))) =
    (\z:real^(1,1)finite_sum. (&1 / &2) %
        (lift(f(drop(fstcart z)) - drop(sndcart z) / &2) +
         lift(abs(f(drop(fstcart z)) - drop(sndcart z) / &2))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[GSYM LIFT_ADD; GSYM LIFT_CMUL] THEN AP_TERM_TAC THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_CMUL THEN MATCH_MP_TAC MEASURABLE_ON_ADD THEN
  ASM_SIMP_TAC[DIFF_MEAS] THEN
  MATCH_MP_TAC MEASURABLE_ON_LIFT_ABS THEN ASM_SIMP_TAC[DIFF_MEAS]);;

(* The full (f-u/2)_+ region integrand (0 off the upper halfspace u>0) is    *)
(* measurable on R^2: restrict the positive part MAXPART_MEAS to the open    *)
(* halfspace {w | w$2 > 0} = {w | 0 < drop(sndcart w)} (OPEN_HALFSPACE_      *)
(* COMPONENT_GT), via MEASURABLE_ON_RESTRICT.                                *)
let PSI_MEAS = prove
 (`!f:real->real. f real_measurable_on (:real)
   ==> (\z:real^(1,1)finite_sum.
            if &0 < drop(sndcart z)
            then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))
            else vec 0) measurable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^(1,1)finite_sum.
       if &0 < drop(sndcart z)
       then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2)) else vec
         0) =
    (\z:real^(1,1)finite_sum.
       if z IN {w | &0 < drop(sndcart w)}
       then (\z. lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))) z
         else vec 0)`
   SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[MAXPART_MEAS];
    MATCH_MP_TAC LEBESGUE_MEASURABLE_OPEN THEN
    SUBGOAL_THEN
     `{w:real^(1,1)finite_sum | &0 < drop(sndcart w)} =
      {w:real^(1,1)finite_sum | w$2 > &0}` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN
      SIMP_TAC[SNDCART_COMPONENT; DIMINDEX_1; ARITH; GSYM drop; LIFT_DROP;
        drop] THEN
      REAL_ARITH_TAC;
      REWRITE_TAC[OPEN_HALFSPACE_COMPONENT_GT]]]);;

(* The vertical (u-)slice of the (f-u/2)_+ region integrand at a fixed x     *)
(* integrates to f(x)^2.  Real level first (extend INNER_POS_PART_INTEGRAL   *)
(* from {u>0} to (:real) by zero, forward HAS_REAL_INTEGRAL_RESTRICT_UNIV -- *)
(* NOT GSYM under ONCE_DEPTH_CONV, which LOOPS), then bridge to the vector   *)
(* slice through the definition of has_real_integral.                        *)
let PSI_XSLICE_REAL = prove
 (`!f:real->real x. &0 <= f x
   ==> ((\t. if t IN {u | &0 < u} then max (&0) (f x - t / &2) else &0)
        has_real_integral (f x) pow 2) (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[HAS_REAL_INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC INNER_POS_PART_INTEGRAL THEN ASM_REWRITE_TAC[]);;

let PSI_XSLICE_VEC = prove
 (`!f:real->real x. &0 <= f x
   ==> ((\u:real^1. if &0 < drop u then lift(max (&0) (f x - drop u / &2)) else
     vec 0)
        has_integral lift((f x) pow 2)) (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `x:real`] PSI_XSLICE_REAL) THEN
    ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[has_real_integral; IMAGE_LIFT_UNIV; o_DEF] THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  ABS_TAC THEN COND_CASES_TAC THEN REWRITE_TAC[LIFT_NUM]);;

(* Each vertical slice of the (f-u/2)_+ region integrand is absolutely       *)
(* integrable (nonnegative + integrable via PSI_XSLICE_VEC).  Feeds the      *)
(* "all slices" hypothesis of REAL_FUBINI_NONNEG_ABS.                        *)
let PSI_SLICE_ABS = prove
 (`!f:real->real x:real^1. (!x. &0 <= f x)
   ==> (\u. if &0 < drop u then lift(max (&0) (f(drop x) - drop u / &2)) else
     vec 0)
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC NONNEGATIVE_ABSOLUTELY_INTEGRABLE THEN
    CONJ_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `i = 1` SUBST_ALL_TAC THENL
     [RULE_ASSUM_TAC(REWRITE_RULE[DIMINDEX_1]) THEN
       ASM_ARITH_TAC; ALL_TAC] THEN
    COND_CASES_TAC THEN REWRITE_TAC[LIFT_COMPONENT; VEC_COMPONENT] THEN
      REAL_ARITH_TAC;
    MP_TAC(ISPECL [`f:real->real`; `drop(x:real^1)`] PSI_XSLICE_VEC) THEN
      ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN REWRITE_TAC[integrable_on] THEN
    EXISTS_TAC `lift((f:real->real)(drop x) pow 2)` THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Fubini abs-integrability gate for the p=2 layer-cake.  For a NONNEGATIVE  *)
(* measurable 2D integrand ff whose every vertical slice is abs-integrable   *)
(* and whose x-iterate is integrable, ff is absolutely integrable on R^2.    *)
(* (FUBINI_TONELLI: the "bad slice" set is EMPTY here -- all slices          *)
(* integrable                                                                *)
(* -- so the negligibility condition is trivial; the norm-iterate = the      *)
(* x-iterate since norm = drop = abs on nonnegative real^1 values.)          *)
(* NOTE: never name the integrand `F` -- it is the boolean constant `false`. *)
let REAL_FUBINI_NONNEG_ABS = prove
 (`!ff:real^(1,1)finite_sum->real^1.
     ff measurable_on (:real^(1,1)finite_sum) /\
     (!z. &0 <= drop(ff z)) /\
     (!x. (\u. ff(pastecart x u)) absolutely_integrable_on (:real^1)) /\
     (\x. integral (:real^1) (\u. ff(pastecart x u))) integrable_on (:real^1)
     ==> ff absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(fun th -> ONCE_REWRITE_TAC[MATCH_MP FUBINI_TONELLI th]) THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
     `{x | ~((\y. (ff:real^(1,1)finite_sum->real^1) (pastecart x y))
              absolutely_integrable_on (:real^1))} = {}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN ASM_MESON_TAC[];
      REWRITE_TAC[NEGLIGIBLE_EMPTY]];
    SUBGOAL_THEN
     `!x u. lift(norm((ff:real^(1,1)finite_sum->real^1)(pastecart x u))) =
       ff(pastecart x u)`
     (fun th -> ASM_REWRITE_TAC[th]) THEN
    REPEAT GEN_TAC THEN REWRITE_TAC[NORM_1] THEN
    MP_TAC(SPEC `pastecart (x:real^1) (u:real^1)`
       (ASSUME `!z. &0 <= drop((ff:real^(1,1)finite_sum->real^1) z)`)) THEN
    SIMP_TAC[real_abs] THEN DISCH_TAC THEN REWRITE_TAC[LIFT_DROP]]);;

(* The u-outer companion of REAL_FUBINI_NONNEG_ABS (FUBINI_TONELLI_ALT): the *)
(* integrability CONDITION is the outer-u iterate (\y. int_x ff(pastecart x  *)
(* y)). Used for the MAIN region S, whose x-iterate is f1star squared (NOT   *)
(* known integrable a priori -- circular), but whose u-iterate is 2u         *)
(* mu(G_u), integrable by domination against the (f-u/2)_+ integral          *)
(* (POS_PART_LAYER_CAKE).                                                    *)
let REAL_FUBINI_NONNEG_ABS_ALT = prove
 (`!ff:real^(1,1)finite_sum->real^1.
     ff measurable_on (:real^(1,1)finite_sum) /\
     (!z. &0 <= drop(ff z)) /\
     (!y. (\x. ff(pastecart x y)) absolutely_integrable_on (:real^1)) /\
     (\y. integral (:real^1) (\x. ff(pastecart x y))) integrable_on (:real^1)
     ==> ff absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(fun th -> ONCE_REWRITE_TAC[MATCH_MP FUBINI_TONELLI_ALT th]) THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
     `{y | ~((\x. (ff:real^(1,1)finite_sum->real^1) (pastecart x y))
              absolutely_integrable_on (:real^1))} = {}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN ASM_MESON_TAC[];
      REWRITE_TAC[NEGLIGIBLE_EMPTY]];
    SUBGOAL_THEN
     `!x y. lift(norm((ff:real^(1,1)finite_sum->real^1)(pastecart x y))) =
       ff(pastecart x y)`
     (fun th -> ASM_REWRITE_TAC[th]) THEN
    REPEAT GEN_TAC THEN REWRITE_TAC[NORM_1] THEN
    MP_TAC(SPEC `pastecart (x:real^1) (y:real^1)`
       (ASSUME `!z. &0 <= drop((ff:real^(1,1)finite_sum->real^1) z)`)) THEN
    SIMP_TAC[real_abs] THEN DISCH_TAC THEN REWRITE_TAC[LIFT_DROP]]);;

(* The (f-u/2)_+ region integrand is absolutely integrable on R^2, for f     *)
(* real-                                                                     *)
(* measurable, nonnegative, with f^2 integrable.  This is the NON-CIRCULAR   *)
(* entry point: the x-iterate is int_u (f(x)-u/2)_+ = f(x)^2                 *)
(* (PSI_XSLICE_VEC),                                                         *)
(* integrable BY HYPOTHESIS -- so REAL_FUBINI_NONNEG_ABS applies with no     *)
(* appeal to the very bound we are trying to prove.                          *)
let PSI_ABS = prove
 (`!f:real->real.
     f real_measurable_on (:real) /\ (!x. &0 <= f x) /\
     (\x. f x pow 2) real_integrable_on (:real)
     ==> (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z)
            then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))
              else vec 0)
         absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_FUBINI_NONNEG_ABS THEN
  REPEAT CONJ_TAC THENL
   [ASM_SIMP_TAC[PSI_MEAS];
    GEN_TAC THEN REWRITE_TAC[] THEN COND_CASES_TAC THEN
    REWRITE_TAC[DROP_VEC; LIFT_DROP; REAL_LE_REFL] THEN REAL_ARITH_TAC;
    GEN_TAC THEN REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
    ASM_SIMP_TAC[PSI_SLICE_ABS];
    SUBGOAL_THEN
     `(\x. integral (:real^1)
         (\u. (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z)
                 then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) /
                   &2)) else vec 0)
              (pastecart x u))) =
      (\x:real^1. lift(f(drop x) pow 2))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
      REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
      MATCH_MP_TAC INTEGRAL_UNIQUE THEN
      MP_TAC(ISPECL [`f:real->real`; `drop(x:real^1)`] PSI_XSLICE_VEC) THEN
      ASM_REWRITE_TAC[];
      UNDISCH_TAC `(\x. f x pow 2) real_integrable_on (:real)` THEN
      REWRITE_TAC[real_integrable_on] THEN STRIP_TAC THEN
      REWRITE_TAC[integrable_on] THEN EXISTS_TAC `lift y` THEN
      FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[has_real_integral; IMAGE_LIFT_UNIV;
        o_DEF]) THEN
      REWRITE_TAC[]]]);;

(* x-outer Fubini value: integrating the (f-u/2)_+ region first over u (the  *)
(* vertical slice = f(x)^2) then over x gives lift(int_R f^2).               *)
let XOUT = prove
 (`!f:real->real.
     f real_measurable_on (:real) /\ (!x. &0 <= f x) /\ (\x. f x pow 2)
       real_integrable_on (:real)
     ==> integral (:real^(1,1)finite_sum)
           (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z)
              then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))
                else vec 0)
         = lift(real_integral (:real) (\x. f x pow 2))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(MATCH_MP FUBINI_INTEGRAL (MATCH_MP PSI_ABS (ASSUME
    `f real_measurable_on (:real) /\ (!x. &0 <= f x) /\ (\x. f x pow 2)
      real_integrable_on (:real)`))) THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `(\x. integral (:real^1)
       (\u. (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z)
               then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))
                 else vec 0)
            (pastecart x u))) = (\x:real^1. lift(f(drop x) pow 2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
    REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
    MATCH_MP_TAC INTEGRAL_UNIQUE THEN
    MP_TAC(ISPECL [`f:real->real`; `drop(x:real^1)`] PSI_XSLICE_VEC) THEN
      ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP REAL_INTEGRAL) THEN
  REWRITE_TAC[IMAGE_LIFT_UNIV; o_DEF] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[LIFT_DROP]);;

(* The u-slice (fixed height u = drop u_pt > 0) of the (f-u/2)_+ region      *)
(* integrand, integrated over x, has_integral lift(int_R (f - drop           *)
(* u_pt/2)_+).                                                               *)
let PSI_USLICE = prove
 (`!f:real->real u. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 <
   drop u
   ==> ((\x:real^1. (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z)
              then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))
                else vec 0)
            (pastecart x u))
        has_integral lift(real_integral (:real) (\y. max (&0) (f y - drop u /
          &2))))
       (:real^1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `(\y. max (&0) ((f:real->real) y - drop u / &2))
     real_integrable_on (:real)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC POS_PART_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
     ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP REAL_INTEGRABLE_INTEGRAL) THEN
  REWRITE_TAC[has_real_integral; IMAGE_LIFT_UNIV; o_DEF]);;

(* The inner x-integral as a function of the height y: it is the u-slice     *)
(* value                                                                     *)
(* on {y>0} and vec 0 elsewhere. Feeds the outer u-integral of the           *)
(* layer-cake.                                                               *)
let INNER_U = prove
 (`!f:real->real y. f real_integrable_on (:real) /\ (!x. &0 <= f x)
   ==> integral (:real^1) (\x. (\z:real^(1,1)finite_sum. if &0 < drop(sndcart
     z)
              then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))
                else vec 0)
            (pastecart x y))
       = (if &0 < drop y then lift(real_integral (:real) (\t. max (&0) (f t -
         drop y / &2))) else vec 0)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THENL
   [MATCH_MP_TAC INTEGRAL_UNIQUE THEN
    MP_TAC(ISPECL [`f:real->real`; `y:real^1`] PSI_USLICE) THEN
      ASM_REWRITE_TAC[];
    REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
      ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[INTEGRAL_0]]);;

(* Raw u-outer Fubini for the (f-u/2)_+ region: the outer iterate (integrate *)
(* over x first) has_integral lift(int f^2).                                 *)
(* FUBINI_ABSOLUTELY_INTEGRABLE_ALT                                          *)
(* on PSI_ABS gives has_integral (int_R^2 Psi); SUBS the XOUT value. Stated  *)
(* in                                                                        *)
(* the raw (unreduced pastecart) form so the combine goes through without    *)
(* the                                                                       *)
(* ABS-failing rewriter (MP_TAC ... THEN REWRITE_TAC[] closes the plain      *)
(* implication A ==> A by beta alone).                                       *)
let POS_PART_FUBINI_RAW = prove
 (`!f:real->real.
     f real_measurable_on (:real) /\ (!x. &0 <= f x) /\ (\x. f x pow 2)
       real_integrable_on (:real)
     ==> ((\v:real^1. integral (:real^1) (\x. (\z:real^(1,1)finite_sum. if &0 <
       drop(sndcart z)
              then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))
                else vec 0)
            (pastecart x v)))
          has_integral lift(real_integral (:real) (\x. f x pow 2))) (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SUBS[MATCH_MP XOUT (ASSUME
    `f real_measurable_on (:real) /\ (!x. &0 <= f x) /\ (\x. f x pow 2)
      real_integrable_on (:real)`)]
    (CONJUNCT2 (MATCH_MP FUBINI_ABSOLUTELY_INTEGRABLE_ALT (MATCH_MP PSI_ABS
      (ASSUME
    `f real_measurable_on (:real) /\ (!x. &0 <= f x) /\ (\x. f x pow 2)
      real_integrable_on (:real)`))))) THEN
  REWRITE_TAC[]);;

(* The p=2 layer-cake for the positive part (Fremlin 286A(c), the (f-u/2)_+  *)
(* half):                                                                    *)
(*   int_{u>0} (int_R (f - u/2)_+ dx) du = int_R f^2.                        *)
(* Real-level restatement of POS_PART_FUBINI_RAW: spike the vector outer     *)
(* integrand to the real-level one (INNER_U identifies the x-slice), on      *)
(* {u>0}.                                                                    *)
let POS_PART_LAYER_CAKE = prove
 (`!f:real->real.
     f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
       f x) /\
     (\x. f x pow 2) real_integrable_on (:real)
     ==> ((\u. real_integral (:real) (\y. max (&0) (f y - u / &2)))
          has_real_integral real_integral (:real) (\x. f x pow 2)) {u | &0 <
            u}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[has_real_integral] THEN
  ONCE_REWRITE_TAC[GSYM HAS_INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC HAS_INTEGRAL_SPIKE THEN
  EXISTS_TAC `\v:real^1. integral (:real^1) (\x. (\z:real^(1,1)finite_sum. if
    &0 < drop(sndcart z)
            then lift(max (&0) (f(drop(fstcart z)) - drop(sndcart z) / &2))
              else vec 0)
          (pastecart x v))` THEN
  EXISTS_TAC `{}:real^1->bool` THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; IN_DIFF; NOT_IN_EMPTY] THEN CONJ_TAC THENL
   [X_GEN_TAC `v:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[IN_IMAGE_LIFT_DROP; IN_ELIM_THM; o_THM] THEN
    MP_TAC(ISPECL [`f:real->real`; `v:real^1`] INNER_U) THEN
      ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    COND_CASES_TAC THEN REWRITE_TAC[LIFT_DROP];
    MP_TAC(ISPEC `f:real->real` POS_PART_FUBINI_RAW) THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286B weighted layer-cake (M5): the crux analytic brick of the monotone-   *)
(* kernel maximal domination.  For nonnegative f (abs-integrable) and        *)
(* nonnegative continuous gg with f*gg integrable,                           *)
(*    int_{u>0} (int_{gg>=u} f) du = int_R f*gg.                             *)
(* Route = 2D Tonelli on the region integrand                                *)
(*    H(z) = if 0 < snd z /\ snd z <= gg(fst z) then f(fst z) else 0,        *)
(* a structural clone of the POS_PART_LAYER_CAKE machinery just above.       *)
(* ========================================================================= *)

(* The constant k on the half-open interval (0,c] integrates to k*c (c>=0).  *)
(* Spike from the closed interval [0,c] (differ only at the single point 0). *)
let CONST_HALFOPEN_INTEGRAL = prove
 (`!k c. &0 <= c
   ==> ((\t. if &0 < t /\ t <= c then k else &0) has_real_integral k * c)
     (:real)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE THEN
  EXISTS_TAC `\t. if t IN real_interval[&0,c] then k else &0` THEN
  EXISTS_TAC `{&0}` THEN
  REWRITE_TAC[REAL_NEGLIGIBLE_SING] THEN CONJ_TAC THENL
   [REWRITE_TAC[IN_DIFF; IN_UNIV; IN_SING; IN_REAL_INTERVAL] THEN
    REPEAT STRIP_TAC THEN REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC;
    REWRITE_TAC[HAS_REAL_INTEGRAL_RESTRICT_UNIV] THEN
    SUBGOAL_THEN `k * c = k * (c - &0)` SUBST1_TAC THENL
     [REAL_ARITH_TAC; ASM_SIMP_TAC[HAS_REAL_INTEGRAL_CONST]]]);;

(* Vertical (x-fixed) slice of H: integral over u of the (0,gg x]-indicator  *)
(* times f x is f x * gg x  (when gg x >= 0).                                *)
let WLC_XSLICE = prove
 (`!(f:real->real) (gg:real->real) x. &0 <= gg x
   ==> ((\u:real^1. if &0 < drop u /\ drop u <= gg x then lift(f x) else vec 0)
        has_integral lift(f x * gg x)) (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`(f:real->real) x`;
    `(gg:real->real) x`] CONST_HALFOPEN_INTEGRAL) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[has_real_integral; IMAGE_LIFT_UNIV; o_DEF] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  ABS_TAC THEN COND_CASES_TAC THEN REWRITE_TAC[LIFT_NUM]);;

(* Absolute integrability of the vertical slice (nonnegative, integral       *)
(* known).                                                                   *)
let WLC_SLICE_ABS = prove
 (`!(f:real->real) (gg:real->real) x:real^1. (!x. &0 <= f x) /\ (!x. &0 <= gg
   x)
   ==> (\u:real^1. if &0 < drop u /\ drop u <= gg(drop x) then lift(f(drop x))
     else vec 0)
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC NONNEGATIVE_ABSOLUTELY_INTEGRABLE THEN
    CONJ_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `i = 1` SUBST_ALL_TAC THENL
     [RULE_ASSUM_TAC(REWRITE_RULE[DIMINDEX_1]) THEN
       ASM_ARITH_TAC; ALL_TAC] THEN
    COND_CASES_TAC THEN REWRITE_TAC[LIFT_COMPONENT; VEC_COMPONENT] THEN
    ASM_SIMP_TAC[REAL_LE_REFL];
    REWRITE_TAC[integrable_on] THEN
    EXISTS_TAC `lift(f(drop(x:real^1)) * gg(drop x))` THEN
    MP_TAC(ISPECL [`f:real->real`; `gg:real->real`;
      `drop(x:real^1)`] WLC_XSLICE) THEN
    ASM_REWRITE_TAC[]]);;

(* The 2D region integrand H is measurable on R^2: f o fst is measurable     *)
(* (LIFTF_MEAS), and the region {0<snd /\ snd<=gg(fst)} is the intersection  *)
(* of an open halfspace with a closed continuous-preimage.                   *)
let WLC_MEAS = prove
 (`!(f:real->real) (gg:real->real).
     f real_measurable_on (:real) /\ gg real_continuous_on (:real)
     ==> (\z:real^(1,1)finite_sum.
            if &0 < drop(sndcart z) /\ drop(sndcart z) <= gg(drop(fstcart z))
            then lift(f(drop(fstcart z))) else vec 0)
         measurable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^(1,1)finite_sum.
        if &0 < drop(sndcart z) /\ drop(sndcart z) <= gg(drop(fstcart z))
        then lift(f(drop(fstcart z))) else vec 0) =
    (\z:real^(1,1)finite_sum.
        if z IN {w | &0 < drop(sndcart w) /\ drop(sndcart w) <= gg(drop(fstcart
          w))}
        then (\z. lift(f(drop(fstcart z)))) z else vec 0)`
   SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[LIFTF_MEAS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `{w:real^(1,1)finite_sum | &0 < drop (sndcart w) /\ drop (sndcart w) <= gg
     (drop (fstcart w))} =
    {w | drop(sndcart w) > &0} INTER
    {w | (lift o (\z. gg(drop(fstcart z)) - drop(sndcart z))) w IN {y:real^1 |
      &0 <= drop y}}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM; o_THM; LIFT_DROP] THEN
    GEN_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
   [MATCH_MP_TAC LEBESGUE_MEASURABLE_OPEN THEN
    SUBGOAL_THEN
      `{w:real^(1,1)finite_sum | drop (sndcart w) > &0} = {w | w$2 > &0}`
      SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN
      SIMP_TAC[SNDCART_COMPONENT; DIMINDEX_1; ARITH; GSYM drop; LIFT_DROP;
        drop] THEN REAL_ARITH_TAC;
      REWRITE_TAC[OPEN_HALFSPACE_COMPONENT_GT]];
    ALL_TAC] THEN
  MATCH_MP_TAC LEBESGUE_MEASURABLE_CLOSED THEN
  MATCH_MP_TAC CONTINUOUS_CLOSED_PREIMAGE_UNIV THEN CONJ_TAC THENL
   [ALL_TAC;
    REWRITE_TAC[drop; GSYM real_ge; CLOSED_HALFSPACE_COMPONENT_GE]] THEN
  X_GEN_TAC `w:real^(1,1)finite_sum` THEN REWRITE_TAC[o_DEF; LIFT_SUB] THEN
  MATCH_MP_TAC CONTINUOUS_SUB THEN CONJ_TAC THENL
   [SUBGOAL_THEN `(\w:real^(1,1)finite_sum. lift (gg (drop (fstcart w)))) =
                  (lift o gg o drop) o (fstcart:real^(1,1)finite_sum->real^1)`
                    SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_AT_COMPOSE THEN CONJ_TAC THENL
     [MATCH_MP_TAC LINEAR_CONTINUOUS_AT THEN
       REWRITE_TAC[LINEAR_FSTCART]; ALL_TAC] THEN
    SUBGOAL_THEN `(lift o gg o drop) continuous_on (:real^1)` MP_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REAL_CONTINUOUS_ON]) THEN
      REWRITE_TAC[IMAGE_LIFT_UNIV];
      SIMP_TAC[CONTINUOUS_ON_EQ_CONTINUOUS_AT; OPEN_UNIV; IN_UNIV]];
    REWRITE_TAC[LIFT_DROP; ETA_AX] THEN
    MATCH_MP_TAC LINEAR_CONTINUOUS_AT THEN REWRITE_TAC[LINEAR_SNDCART]]);;

(* H is absolutely integrable on R^2 (Tonelli via REAL_FUBINI_NONNEG_ABS):   *)
(* measurable, nonnegative, vertical slices abs-integrable, x-iterate f*gg   *)
(* integrable by hypothesis.                                                 *)
let WLC_ABS = prove
 (`!(f:real->real) (gg:real->real).
     f real_measurable_on (:real) /\ gg real_continuous_on (:real) /\
     (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\
     (\x. f x * gg x) real_integrable_on (:real)
     ==> (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z) /\ drop(sndcart z)
       <= gg(drop(fstcart z))
            then lift(f(drop(fstcart z))) else vec 0)
         absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_FUBINI_NONNEG_ABS THEN
    REPEAT CONJ_TAC THENL
   [ASM_SIMP_TAC[WLC_MEAS];
    GEN_TAC THEN REWRITE_TAC[] THEN COND_CASES_TAC THEN
    REWRITE_TAC[DROP_VEC; LIFT_DROP; REAL_LE_REFL] THEN ASM_SIMP_TAC[];
    GEN_TAC THEN REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
    ASM_SIMP_TAC[WLC_SLICE_ABS];
    SUBGOAL_THEN
     `(\x:real^1. integral (:real^1)
         (\u. (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z) /\ drop(sndcart
           z) <= gg(drop(fstcart z))
                 then lift(f(drop(fstcart z))) else vec 0) (pastecart x u))) =
      (\x:real^1. lift(f(drop x) * gg(drop x)))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
      REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
      MATCH_MP_TAC INTEGRAL_UNIQUE THEN
      MP_TAC(ISPECL [`f:real->real`; `gg:real->real`;
        `drop(x:real^1)`] WLC_XSLICE) THEN
      ASM_REWRITE_TAC[];
      UNDISCH_TAC `(\x. f x * gg x) real_integrable_on (:real)` THEN
      REWRITE_TAC[real_integrable_on] THEN STRIP_TAC THEN
      REWRITE_TAC[integrable_on] THEN EXISTS_TAC `lift y` THEN
      FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[has_real_integral; IMAGE_LIFT_UNIV;
        o_DEF]) THEN
      REWRITE_TAC[]]]);;

(* Superlevel set of a continuous gg is real-Lebesgue-measurable (closed).   *)
let SUPERLEVEL_RLM = prove
 (`!(gg:real->real) u. gg real_continuous_on (:real)
     ==> real_lebesgue_measurable {x | u <= gg x}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_LEBESGUE_MEASURABLE] THEN
  SUBGOAL_THEN `IMAGE lift {x | u <= gg x} =
                {z:real^1 | (lift o gg o drop) z IN {y:real^1 | u <= drop y}}`
                  SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM; o_THM; LIFT_DROP] THEN
    MESON_TAC[LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC LEBESGUE_MEASURABLE_CLOSED THEN
  MATCH_MP_TAC CONTINUOUS_CLOSED_PREIMAGE_UNIV THEN CONJ_TAC THENL
   [REWRITE_TAC[ETA_AX] THEN X_GEN_TAC `z:real^1` THEN
    SUBGOAL_THEN `(lift o gg o drop) continuous_on (:real^1)` MP_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REAL_CONTINUOUS_ON]) THEN
      REWRITE_TAC[IMAGE_LIFT_UNIV];
      SIMP_TAC[CONTINUOUS_ON_EQ_CONTINUOUS_AT; OPEN_UNIV; IN_UNIV]];
    REWRITE_TAC[drop; GSYM real_ge; CLOSED_HALFSPACE_COMPONENT_GE]]);;

(* f (abs-integrable on R) is integrable on any superlevel {gg>=u}.          *)
let F_SUPERLEVEL_INT = prove
 (`!(f:real->real) (gg:real->real) u.
     f absolutely_real_integrable_on (:real) /\ gg real_continuous_on (:real)
     ==> f real_integrable_on {x | u <= gg x}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
  REWRITE_TAC[ABSOLUTELY_REAL_INTEGRABLE_ON] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `IMAGE lift (:real)` THEN
  ASM_REWRITE_TAC[GSYM ABSOLUTELY_REAL_INTEGRABLE_ON] THEN CONJ_TAC THENL
   [REWRITE_TAC[IMAGE_LIFT_UNIV; SUBSET_UNIV];
    MP_TAC(ISPECL [`gg:real->real`; `u:real`] SUPERLEVEL_RLM) THEN
      ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[REAL_LEBESGUE_MEASURABLE]]);;

(* Horizontal (u-fixed, u>0) slice of H integrated over x is int_{gg>=u} f.  *)
let WLC_USLICE = prove
 (`!(f:real->real) (gg:real->real) u:real^1.
     f absolutely_real_integrable_on (:real) /\ gg real_continuous_on (:real)
       /\ &0 < drop u
   ==> integral (:real^1) (\x. (\z:real^(1,1)finite_sum. if &0 < drop(sndcart
     z) /\ drop(sndcart z) <= gg(drop(fstcart z))
              then lift(f(drop(fstcart z))) else vec 0) (pastecart x u))
       = lift(real_integral {x | drop u <= gg x} f)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `(\x:real^1. if drop u <= gg (drop x) then lift (f (drop x)) else vec 0) =
    (\x:real^1. if x IN IMAGE lift {x | drop u <= gg x} then (lift o f o drop)
      x else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
    REWRITE_TAC[IN_IMAGE_LIFT_DROP; IN_ELIM_THM; o_THM]; ALL_TAC] THEN
  REWRITE_TAC[INTEGRAL_RESTRICT_UNIV; ETA_AX] THEN
  MP_TAC(ISPECL [`f:real->real`; `gg:real->real`;
    `drop(u:real^1)`] F_SUPERLEVEL_INT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o MATCH_MP REAL_INTEGRAL) THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[LIFT_DROP]);;

(* x-outer Fubini value: int_R^2 H = int_R f*gg.                             *)
let WLC_XOUT = prove
 (`!(f:real->real) (gg:real->real).
     f real_measurable_on (:real) /\ gg real_continuous_on (:real) /\
     (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\
     (\x. f x * gg x) real_integrable_on (:real)
     ==> integral (:real^(1,1)finite_sum)
           (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z) /\ drop(sndcart z)
             <= gg(drop(fstcart z))
              then lift(f(drop(fstcart z))) else vec 0)
         = lift(real_integral (:real) (\x. f x * gg x))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(MATCH_MP FUBINI_INTEGRAL (MATCH_MP WLC_ABS (ASSUME
    `f real_measurable_on (:real) /\ gg real_continuous_on (:real) /\
     (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\
     (\x. f x * gg x) real_integrable_on (:real)`))) THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `(\x. integral (:real^1)
       (\y. (\z:real^(1,1)finite_sum. if &0 < drop(sndcart z) /\ drop(sndcart
         z) <= gg(drop(fstcart z))
               then lift(f(drop(fstcart z))) else vec 0) (pastecart x y))) =
    (\x:real^1. lift(f(drop x) * gg(drop x)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
    REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
    MATCH_MP_TAC INTEGRAL_UNIQUE THEN
    MP_TAC(ISPECL [`f:real->real`; `gg:real->real`;
      `drop(x:real^1)`] WLC_XSLICE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP REAL_INTEGRAL) THEN
  REWRITE_TAC[IMAGE_LIFT_UNIV; o_DEF] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[LIFT_DROP]);;

(* Raw u-outer Fubini: the outer (integrate x first) iterate has_integral    *)
(* int_R f*gg  (FUBINI_ABSOLUTELY_INTEGRABLE_ALT on WLC_ABS, SUBS WLC_XOUT). *)
let WLC_UOUT_RAW = prove
 (`!(f:real->real) (gg:real->real).
     f real_measurable_on (:real) /\ gg real_continuous_on (:real) /\
     (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\
     (\x. f x * gg x) real_integrable_on (:real)
     ==> ((\v:real^1. integral (:real^1) (\x. (\z:real^(1,1)finite_sum.
              if &0 < drop(sndcart z) /\ drop(sndcart z) <= gg(drop(fstcart z))
              then lift(f(drop(fstcart z))) else vec 0) (pastecart x v)))
          has_integral lift(real_integral (:real) (\x. f x * gg x)))
            (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SUBS[MATCH_MP WLC_XOUT (ASSUME
    `f real_measurable_on (:real) /\ gg real_continuous_on (:real) /\
     (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\
     (\x. f x * gg x) real_integrable_on (:real)`)]
    (CONJUNCT2 (MATCH_MP FUBINI_ABSOLUTELY_INTEGRABLE_ALT (MATCH_MP WLC_ABS
      (ASSUME
    `f real_measurable_on (:real) /\ gg real_continuous_on (:real) /\
     (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\
     (\x. f x * gg x) real_integrable_on (:real)`))))) THEN
  REWRITE_TAC[]);;

(* 286B weighted layer-cake proper: int_{u>0} (int_{gg>=u} f) du = int_R     *)
(* f*gg.                                                                     *)
let WEIGHTED_LAYER_CAKE = prove
 (`!(f:real->real) (gg:real->real).
     f real_measurable_on (:real) /\ f absolutely_real_integrable_on (:real) /\
     gg real_continuous_on (:real) /\
     (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\
     (\x. f x * gg x) real_integrable_on (:real)
     ==> ((\u. real_integral {x | u <= gg x} f) has_real_integral
          real_integral (:real) (\x. f x * gg x)) {u | &0 < u}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[has_real_integral] THEN
  ONCE_REWRITE_TAC[GSYM HAS_INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC HAS_INTEGRAL_SPIKE THEN
  EXISTS_TAC `\v:real^1. integral (:real^1) (\x. (\z:real^(1,1)finite_sum.
              if &0 < drop(sndcart z) /\ drop(sndcart z) <= gg(drop(fstcart z))
              then lift(f(drop(fstcart z))) else vec 0) (pastecart x v))` THEN
  EXISTS_TAC `{}:real^1->bool` THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; IN_DIFF; NOT_IN_EMPTY] THEN CONJ_TAC THENL
   [X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[IN_IMAGE_LIFT_DROP; IN_ELIM_THM; o_THM] THEN
    REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
    COND_CASES_TAC THENL
     [MP_TAC(ISPECL [`f:real->real`; `gg:real->real`;
       `x:real^1`] WLC_USLICE) THEN
      ASM_REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC;
      SUBGOAL_THEN
        `!x':real^1. ~(&0 < drop x /\ drop x <= gg(drop x'))` (fun th ->
        REWRITE_TAC[th]) THENL
       [ASM_MESON_TAC[]; REWRITE_TAC[INTEGRAL_0]]];
    SUBGOAL_THEN
     `f real_measurable_on (:real) /\ gg real_continuous_on (:real) /\
      (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\ (\x. f x * gg x)
        real_integrable_on (:real)`
     ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o MATCH_MP WLC_UOUT_RAW) THEN
    REWRITE_TAC[SNDCART_PASTECART; FSTCART_PASTECART]]);;

(* ========================================================================= *)
(* 286B assembly (M5): from the weighted layer-cake to the monotone-kernel   *)
(* maximal domination.  MCM = monotone-const-monotone (nondecr on (-inf,al], *)
(* nonincr on [be,inf), const on [al,be]).                                   *)
(* ========================================================================= *)

(* P2 (the endpoint-free integral assembly): given the PER-LEVEL bound       *)
(*   int_{gg>=u} f <= M * mu{gg>=u}   for all u>0,                           *)
(* the two layer-cakes (WEIGHTED_LAYER_CAKE for int f*gg, REAL_LAYER_CAKE    *)
(* for                                                                       *)
(* int gg) + REAL_INTEGRAL_LE give  int f*gg <= M * int gg.                  *)
let MCM_DOMINATION_FROM_LEVEL = prove
 (`!(f:real->real) (gg:real->real) M.
     f real_measurable_on (:real) /\ f absolutely_real_integrable_on (:real) /\
     gg real_continuous_on (:real) /\ (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\
     (\x. f x * gg x) real_integrable_on (:real) /\ gg real_integrable_on
       (:real) /\
     (!u. &0 < u ==> real_integral {x | u <= gg x} f <= M * real_measure {x | u
       <= gg x})
     ==> real_integral (:real) (\x. f x * gg x) <= M * real_integral (:real)
       gg`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `gg:real->real`] WEIGHTED_LAYER_CAKE) THEN
  ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> SUBST1_TAC(SYM(MATCH_MP REAL_INTEGRAL_UNIQUE th)) THEN
    ASSUME_TAC(MATCH_MP HAS_REAL_INTEGRAL_INTEGRABLE th)) THEN
  MP_TAC(ISPECL [`gg:real->real`;
    `real_integral (:real) gg`] REAL_LAYER_CAKE) THEN
  ASM_SIMP_TAC[REAL_INTEGRABLE_INTEGRAL] THEN
  DISCH_THEN(fun th -> ASSUME_TAC(MATCH_MP HAS_REAL_INTEGRAL_INTEGRABLE th)
    THEN
    MP_TAC(SYM(MATCH_MP REAL_INTEGRAL_UNIQUE th))) THEN
  DISCH_THEN(fun th -> GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [th]) THEN
  ASM_SIMP_TAC[GSYM REAL_INTEGRAL_LMUL] THEN
  MATCH_MP_TAC REAL_INTEGRAL_LE THEN
  ASM_SIMP_TAC[IN_ELIM_THM; REAL_INTEGRABLE_LMUL]);;

(* A bounded nonempty real-interval S has real_interval(inf S, sup S) SUBSET *)
(* S.                                                                        *)
let BOUNDED_REALINTERVAL_OPEN_SUBSET = prove
 (`!S. is_realinterval S /\ ~(S = {}) /\ real_bounded S
   ==> real_interval(inf S, sup S) SUBSET S`,
  GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ri") STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN X_GEN_TAC `x:real` THEN
    STRIP_TAC THEN
  SUBGOAL_THEN `?a. a IN S /\ a < x` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`x:real`] (INST [`S:real->bool`,`s:real->bool`] REAL_LE_INF))
     THEN
    ASM_MESON_TAC[REAL_NOT_LT; REAL_LTE_TRANS; REAL_LT_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN `?b. b IN S /\ x < b` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`x:real`] (INST [`S:real->bool`,`s:real->bool`] REAL_SUP_LE))
     THEN
    ASM_MESON_TAC[REAL_NOT_LT; REAL_LET_TRANS; REAL_LT_REFL];
    ALL_TAC] THEN
  USE_THEN "ri" (fun th -> MP_TAC(REWRITE_RULE[is_realinterval] th)) THEN
  DISCH_THEN(MP_TAC o SPECL [`a:real`; `b:real`; `x:real`]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC);;

(* Every bounded nonempty S sits inside the closed interval [inf S, sup S].  *)
let BOUNDED_SUBSET_REALINTERVAL_CLOSED = prove
 (`!S. ~(S = {}) /\ real_bounded S ==> S SUBSET real_interval[inf S, sup S]`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_THEN
    `B:real` STRIP_ASSUME_TAC o REWRITE_RULE[REAL_BOUNDED_POS_LT]) THEN
  REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN X_GEN_TAC `x:real` THEN
    DISCH_TAC THEN
  MP_TAC(SPEC `S:real->bool` INF) THEN MP_TAC(SPEC `S:real->bool` SUP) THEN
  ANTS_TAC THENL
    [ASM_MESON_TAC[REAL_ARITH `abs(x) < B ==> x <= B`]; ALL_TAC] THEN
  STRIP_TAC THEN
  ANTS_TAC THENL
    [ASM_MESON_TAC[REAL_ARITH `abs(x) < B ==> --B <= x`]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_SIMP_TAC[]);;

(* A bounded nonempty real-interval S is measurable with measure sup S - inf *)
(* S (it differs from the open interval (inf S, sup S) by at most 2          *)
(* endpoints).                                                               *)
let MCM_LEVEL_MEASURE = prove
 (`!S. is_realinterval S /\ ~(S = {}) /\ real_bounded S /\ inf S <= sup S
   ==> real_measurable S /\ real_measure S = sup S - inf S`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPEC `S:real->bool` BOUNDED_REALINTERVAL_OPEN_SUBSET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPEC `S:real->bool` BOUNDED_SUBSET_REALINTERVAL_CLOSED) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `real_negligible((real_interval(inf S, sup S) DIFF S) UNION (S DIFF
    real_interval(inf S, sup S)))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `{inf S, sup S}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_INSERT; REAL_NEGLIGIBLE_SING] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[SUBSET; IN_REAL_INTERVAL]) THEN
    REWRITE_TAC[SUBSET; IN_UNION; IN_DIFF; IN_REAL_INTERVAL; IN_INSERT;
      NOT_IN_EMPTY] THEN
    GEN_TAC THEN STRIP_TAC THEN
      ASM_MESON_TAC[REAL_LE_ANTISYM; REAL_LE_LT; REAL_LT_LE]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_REAL_NEGLIGIBLE_SYMDIFF THEN
    EXISTS_TAC `real_interval(inf S, sup S)` THEN
    ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
    MP_TAC(ISPECL [`real_interval(inf S, sup S)`;
      `S:real->bool`] REAL_MEASURE_REAL_NEGLIGIBLE_SYMDIFF) THEN
    ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN ASM_REAL_ARITH_TAC]);;

(* MCM structure: gg attains its global maximum on the flat middle [al,be],  *)
(* so gg x <= gg al for every x.                                             *)
let MCM_GLOBAL_MAX = prove
 (`!(gg:real->real) (al:real) (be:real) (x:real).
     al <= be /\
     (!x y. x <= y /\ y <= al ==> gg x <= gg y) /\
     (!x y. be <= x /\ x <= y ==> gg y <= gg x) /\
     (!x. al <= x /\ x <= be ==> gg x = gg al)
     ==> gg x <= gg al`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "inc")
      (CONJUNCTS_THEN2 (LABEL_TAC "dec") (LABEL_TAC "flat")))) THEN
  ASM_CASES_TAC `x <= al` THENL
   [USE_THEN "inc" (MP_TAC o SPECL [`x:real`; `al:real`]) THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `x <= be` THENL
   [SUBGOAL_THEN
     `(gg:real->real) x = gg al` (fun th -> REWRITE_TAC[th; REAL_LE_REFL]) THEN
    USE_THEN "flat" (MP_TAC o SPEC `x:real`) THEN ANTS_TAC THENL
     [ASM_REAL_ARITH_TAC; REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(gg:real->real) be = gg al` (fun th -> ONCE_REWRITE_TAC[GSYM th]) THENL
   [USE_THEN "flat" (MP_TAC o SPEC `be:real`) THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  USE_THEN "dec" (MP_TAC o SPECL [`be:real`; `x:real`]) THEN
    ASM_REAL_ARITH_TAC);;

(* P1 (the per-level bound): for u>0 the superlevel set gg>=u is a bounded   *)
(* interval that (when nonempty) contains [al,be] (MCM_GLOBAL_MAX + MCM_     *)
(* SUPERLEVEL_INTERVAL); its endpoints straddle [al,be] so the               *)
(* interval-average hypothesis gives int_S f = int_[inf,sup] f <=            *)
(* M*(sup-inf) = M*mu S.                                                     *)
let MCM_LEVEL_INTEGRAL_BOUND = prove
 (`!(f:real->real) (gg:real->real) al be (M:real) u.
     al <= be /\
     (!x y. x <= y /\ y <= al ==> gg x <= gg y) /\
     (!x y. be <= x /\ x <= y ==> gg y <= gg x) /\
     (!x. al <= x /\ x <= be ==> gg x = gg al) /\
     (!x. &0 <= f x) /\ f absolutely_real_integrable_on (:real) /\
     real_bounded {x | u <= gg x} /\
     (!a b. a <= al /\ be <= b ==> real_integral (real_interval[a,b]) f <= M *
       (b - a)) /\
     &0 < u
     ==> real_integral {x | u <= gg x} f <= M * real_measure {x | u <= gg x}`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "albe")
   (CONJUNCTS_THEN2 (LABEL_TAC "inc")
    (CONJUNCTS_THEN2 (LABEL_TAC "dec")
     (CONJUNCTS_THEN2 (LABEL_TAC "flat")
      (CONJUNCTS_THEN2 (LABEL_TAC "fpos")
       (CONJUNCTS_THEN2 (LABEL_TAC "fint")
        (CONJUNCTS_THEN2 (LABEL_TAC "bdd")
         (CONJUNCTS_THEN2 (LABEL_TAC "avg") (LABEL_TAC "upos"))))))))) THEN
  ASM_CASES_TAC `{x | u <= gg x} = ({}:real->bool)` THENL
   [ASM_REWRITE_TAC[REAL_INTEGRAL_EMPTY; REAL_MEASURE_EMPTY] THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `S = {x:real | u <= gg x}` THEN
  SUBGOAL_THEN `u <= (gg:real->real) al` (LABEL_TAC "ugal") THENL
   [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
    EXPAND_TAC "S" THEN REWRITE_TAC[IN_ELIM_THM] THEN
      DISCH_THEN(X_CHOOSE_TAC `x0:real`) THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(gg:real->real) x0` THEN
      ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`gg:real->real`; `al:real`; `be:real`;
      `x0:real`] MCM_GLOBAL_MAX) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(gg:real->real) be = gg al` (LABEL_TAC "gbe") THENL
   [USE_THEN "flat" (MP_TAC o SPEC `be:real`) THEN
    ANTS_TAC THENL [USE_THEN "albe" MP_TAC THEN
      REAL_ARITH_TAC; REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(al:real) IN S /\ (be:real) IN S` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "S" THEN REWRITE_TAC[IN_ELIM_THM] THEN CONJ_TAC THENL
     [USE_THEN "ugal" ACCEPT_TAC;
      USE_THEN "gbe" (fun th -> REWRITE_TAC[th]) THEN USE_THEN
        "ugal" ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `is_realinterval S` (LABEL_TAC "ri") THENL
   [EXPAND_TAC "S" THEN
    MP_TAC(ISPECL [`gg:real->real`; `al:real`; `be:real`;
      `u:real`] MCM_SUPERLEVEL_INTERVAL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `inf S <= al /\ be <= sup S` STRIP_ASSUME_TAC THENL
   [USE_THEN "bdd" (X_CHOOSE_THEN
     `B:real` STRIP_ASSUME_TAC o REWRITE_RULE[REAL_BOUNDED_POS_LT]) THEN
    MP_TAC(SPEC `S:real->bool` INF) THEN MP_TAC(SPEC `S:real->bool` SUP) THEN
    ANTS_TAC THENL
      [ASM_MESON_TAC[REAL_ARITH `abs(x) < B ==> x <= B`]; ALL_TAC] THEN
    STRIP_TAC THEN
    ANTS_TAC THENL
      [ASM_MESON_TAC[REAL_ARITH `abs(x) < B ==> --B <= x`]; ALL_TAC] THEN
    STRIP_TAC THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `inf S <= sup S` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPEC `S:real->bool` MCM_LEVEL_MEASURE) THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN
   `real_negligible((S DIFF real_interval[inf S,sup S]) UNION
     (real_interval[inf S,sup S] DIFF S))`
   ASSUME_TAC THENL
   [MP_TAC(ISPEC `S:real->bool` BOUNDED_REALINTERVAL_OPEN_SUBSET) THEN
     ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(ISPEC `S:real->bool` BOUNDED_SUBSET_REALINTERVAL_CLOSED) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `{inf S, sup S}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_INSERT; REAL_NEGLIGIBLE_SING] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[SUBSET; IN_REAL_INTERVAL]) THEN
    REWRITE_TAC[SUBSET; IN_UNION; IN_DIFF; IN_REAL_INTERVAL; IN_INSERT;
      NOT_IN_EMPTY] THEN
    GEN_TAC THEN STRIP_TAC THEN
      ASM_MESON_TAC[REAL_LE_ANTISYM; REAL_LE_LT; REAL_LT_LE]; ALL_TAC] THEN
  SUBGOAL_THEN
    `real_integral S f = real_integral (real_interval[inf S, sup S]) f`
    SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SPIKE_SET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `M * (sup S - inf S)` THEN
    CONJ_TAC THENL
   [USE_THEN "avg" (MP_TAC o SPECL [`inf S:real`; `sup S:real`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; REWRITE_TAC[]];
    REWRITE_TAC[REAL_LE_REFL]]);;

(* 286B (the monotone-kernel maximal domination lemma, Fremlin): for f>=0    *)
(* measurable+abs-integrable and gg an MCM kernel (nondecr on (-inf,al],     *)
(* nonincr on [be,inf), const on [al,be]) that is >=0, continuous,           *)
(* integrable                                                                *)
(* with bounded superlevels, and with all straddling averages bounded by M,  *)
(*    int_R f*gg <= M * int_R gg.                                            *)
(* = P1 (MCM_LEVEL_INTEGRAL_BOUND, per-level) fed into P2 (MCM_DOMINATION_   *)
(* FROM_LEVEL, the layer-cake assembly). The M is folded (no REAL_SUP here)  *)
(* --                                                                        *)
(* AVG_LE_HL_MAXIMAL identifies M with the H-L maximal function at the M6    *)
(* step.                                                                     *)
let MCM_MAXIMAL_DOMINATION = prove
 (`!(f:real->real) (gg:real->real) al be (M:real).
     al <= be /\
     (!x y. x <= y /\ y <= al ==> gg x <= gg y) /\
     (!x y. be <= x /\ x <= y ==> gg y <= gg x) /\
     (!x. al <= x /\ x <= be ==> gg x = gg al) /\
     f real_measurable_on (:real) /\ f absolutely_real_integrable_on (:real) /\
     (!x. &0 <= f x) /\ (!x. &0 <= gg x) /\ gg real_continuous_on (:real) /\
     (\x. f x * gg x) real_integrable_on (:real) /\ gg real_integrable_on
       (:real) /\
     (!u. &0 < u ==> real_bounded {x | u <= gg x}) /\
     (!a b. a <= al /\ be <= b ==> real_integral (real_interval[a,b]) f <= M *
       (b - a))
     ==> real_integral (:real) (\x. f x * gg x) <= M * real_integral (:real)
       gg`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MCM_DOMINATION_FROM_LEVEL THEN
    ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:real` THEN DISCH_TAC THEN
  MATCH_MP_TAC MCM_LEVEL_INTEGRAL_BOUND THEN
  MAP_EVERY EXISTS_TAC [`al:real`; `be:real`] THEN ASM_SIMP_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The MAIN region layer-cake (Fremlin 286A(c) proper): the 2u-weighted      *)
(* integral over S = {(x,u) | 0<u, x IN G_u} computed two ways gives         *)
(*   int_R (f1star x)^2 dx = int_{u>0} 2u mu(G_u) du.                        *)
(* Integrand SIGMA(z) = if z IN S then lift(2 drop(sndcart z)) else 0.       *)
(* ------------------------------------------------------------------------- *)

(* SIGMA is measurable: 2*sndcart (continuous) restricted to the OPEN region *)
(* S (MAXIMAL_REGION_OPEN_FS => lebesgue_measurable).                        *)
let SIGMA_MEAS = prove
 (`!f:real->real. f real_integrable_on (:real)
   ==> (\z:real^(1,1)finite_sum.
            if &0 < drop(sndcart z) /\
               (?a. drop(fstcart z) < a /\
                    (a - drop(fstcart z)) * drop(sndcart z) <
                    real_integral (real_interval[drop(fstcart z),a]) f)
            then lift(&2 * drop(sndcart z)) else vec 0)
       measurable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^(1,1)finite_sum.
       if &0 < drop(sndcart z) /\
          (?a. drop(fstcart z) < a /\
               (a - drop(fstcart z)) * drop(sndcart z) <
               real_integral (real_interval[drop(fstcart z),a]) f)
       then lift(&2 * drop(sndcart z)) else vec 0) =
    (\z:real^(1,1)finite_sum.
       if z IN {w | &0 < drop(sndcart w) /\
                    ?a. drop(fstcart w) < a /\
                        (a - drop(fstcart w)) * drop(sndcart w) <
                        real_integral (real_interval[drop(fstcart w),a]) f}
       then (\z. lift(&2 * drop(sndcart z))) z else vec 0)`
   SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
   [SUBGOAL_THEN `(\z:real^(1,1)finite_sum. lift(&2 * drop(sndcart z))) =
                  (\z:real^(1,1)finite_sum. &2 % sndcart z)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [GSYM LIFT_DROP] THEN
      REWRITE_TAC[GSYM LIFT_CMUL] THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
      SIMP_TAC[LINEAR_CONTINUOUS_ON; LINEAR_SNDCART];
    MATCH_MP_TAC LEBESGUE_MEASURABLE_OPEN THEN
    MATCH_MP_TAC MAXIMAL_REGION_OPEN_FS THEN ASM_REWRITE_TAC[]]);;

(* The horizontal (x-)slice of SIGMA at fixed height u_pt (drop u_pt > 0):   *)
(* integral over x = 2u * mu(G_u), where G_u is the (measurable) superlevel  *)
(* set. SIGMA(pastecart x u) = (2u) times the indicator of IMAGE lift G_u;   *)
(* use HAS_INTEGRAL_CMUL + the HAS_MEASURE definition (as in U_INNER).       *)
let SIGMA_USLICE = prove
 (`!f:real->real u_pt. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 <
   drop u_pt
   ==> ((\x:real^1. (\z:real^(1,1)finite_sum.
            if &0 < drop(sndcart z) /\
               (?a. drop(fstcart z) < a /\
                    (a - drop(fstcart z)) * drop(sndcart z) <
                    real_integral (real_interval[drop(fstcart z),a]) f)
            then lift(&2 * drop(sndcart z)) else vec 0)
          (pastecart x u_pt))
        has_integral
        lift(&2 * drop u_pt *
             real_measure {x | ?a. x < a /\ (a - x) * drop u_pt < real_integral
               (real_interval[x,a]) f}))
       (:real^1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `G = {x | ?a. x < a /\ (a - x) * drop u_pt < real_integral
    (real_interval[x,a]) f}` THEN
  SUBGOAL_THEN `real_measurable G` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN MATCH_MP_TAC MAXIMAL_SUPERLEVEL_MEASURABLE THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x:real^1. (if ?a. drop x < a /\ (a - drop x) * drop u_pt <
                       real_integral (real_interval[drop x,a]) f
               then lift(&2 * drop u_pt) else vec 0) =
               (&2 * drop u_pt) % (if x IN IMAGE lift G then vec 1 else vec 0)`
   (fun th -> REWRITE_TAC[th]) THENL
   [X_GEN_TAC `x:real^1` THEN
    SUBGOAL_THEN `(x IN IMAGE lift G) <=>
                  (?a. drop x < a /\ (a - drop x) * drop u_pt <
                       real_integral (real_interval[drop x,a]) f)` SUBST1_TAC
                         THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXPAND_TAC "G" THEN
       REWRITE_TAC[IN_ELIM_THM] THEN
      EQ_TAC THENL
       [DISCH_THEN(X_CHOOSE_THEN `y:real` STRIP_ASSUME_TAC) THEN
        FIRST_X_ASSUM SUBST_ALL_TAC THEN REWRITE_TAC[LIFT_DROP] THEN
        EXISTS_TAC `a:real` THEN ASM_REWRITE_TAC[];
        DISCH_TAC THEN EXISTS_TAC `drop x` THEN ASM_REWRITE_TAC[LIFT_DROP]];
      COND_CASES_TAC THEN
        REWRITE_TAC[GSYM LIFT_EQ_CMUL; VECTOR_MUL_RZERO; LIFT_NUM]];
    ALL_TAC] THEN
  SUBGOAL_THEN `lift(&2 * drop u_pt * real_measure G) =
                (&2 * drop u_pt) % lift(real_measure G)` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM LIFT_CMUL; REAL_MUL_ASSOC]; ALL_TAC] THEN
  MATCH_MP_TAC HAS_INTEGRAL_CMUL THEN
  REWRITE_TAC[REAL_MEASURE_MEASURE; GSYM HAS_MEASURE] THEN
  REWRITE_TAC[GSYM HAS_MEASURE_MEASURE] THEN
  ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE]);;

(* Vector form of XSLICE_REAL: int_{u:real^1} (if 0<drop u /\ drop u<A then  *)
(* 2 drop u else 0) = A^2, for A >= 0.  (Bridge via has_real_integral defn.) *)
let XSLICE_VEC = prove
 (`!A. &0 <= A
   ==> ((\u:real^1. if &0 < drop u /\ drop u < A then lift(&2 * drop u) else
     vec 0)
        has_integral lift(A pow 2)) (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `A:real`
    (prove(`!A. &0 <= A
       ==> ((\t. if t IN {u | &0 < u} then (if t < A then &2 * t else &0) else
         &0)
            has_real_integral A pow 2) (:real)`,
      REPEAT STRIP_TAC THEN REWRITE_TAC[HAS_REAL_INTEGRAL_RESTRICT_UNIV] THEN
      MATCH_MP_TAC XSLICE_REAL THEN ASM_REWRITE_TAC[]))) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[has_real_integral; IMAGE_LIFT_UNIV; o_DEF] THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  ABS_TAC THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[LIFT_NUM] THEN
  COND_CASES_TAC THEN REWRITE_TAC[LIFT_NUM] THEN ASM_REAL_ARITH_TAC);;

(* The horizontal (x-)slice of SIGMA at fixed spatial point x_pt: integral   *)
(* over                                                                      *)
(* u = f1star(x_pt)^2. Uses the superlevel BICONDITIONAL                     *)
(* (HL_FWD_SUPERLEVEL_SUB                                                    *)
(* + _SUPER, needs boundedness) to rewrite the region condition to u <       *)
(* f1star,                                                                   *)
(* then XSLICE_VEC with A = f1star(x_pt) >= 0 (HL_FWD_POS).                  *)
let SIGMA_XSLICE = prove
 (`!f:real->real M x_pt. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\
   (!x. abs(f x) <= M)
   ==> ((\u:real^1. (\z:real^(1,1)finite_sum.
            if &0 < drop(sndcart z) /\
               (?a. drop(fstcart z) < a /\
                    (a - drop(fstcart z)) * drop(sndcart z) <
                    real_integral (real_interval[drop(fstcart z),a]) f)
            then lift(&2 * drop(sndcart z)) else vec 0)
          (pastecart x_pt u))
        has_integral lift((hl_maximal_fwd f (drop x_pt)) pow 2)) (:real^1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  SUBGOAL_THEN
   `!u:real^1. (&0 < drop u /\
                (?a. drop x_pt < a /\ (a - drop x_pt) * drop u <
                     real_integral (real_interval[drop x_pt,a]) f))
               <=> (&0 < drop u /\ drop u < hl_maximal_fwd f (drop x_pt))`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN AP_TERM_TAC THEN EQ_TAC THENL
     [STRIP_TAC THEN MATCH_MP_TAC HL_FWD_SUPERLEVEL_SUPER THEN
      EXISTS_TAC `M:real` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `a:real` THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
        MP_TAC(ISPECL [`f:real->real`; `drop u`;
        `drop x_pt`] HL_FWD_SUPERLEVEL_SUB) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPEC `hl_maximal_fwd f (drop x_pt)` XSLICE_VEC) THEN
  ANTS_TAC THENL
   [MP_TAC(ISPECL [`f:real->real`; `M:real`] HL_FWD_POS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `drop(x_pt:real^1)`) THEN
      REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[]);;

(* The superlevel set G_u is ANTITONE in u (u <= v ==> G_v SUBSET G_u): a    *)
(* larger threshold is harder to meet. Hence u |-> mu(G_u) is                *)
(* non-increasing,                                                           *)
(* which (with the refined bound) will give integrability of u |-> 2u        *)
(* mu(G_u).                                                                  *)
(* NOTE annotate the fresh product `((b:real) - y) * v` fed to EXISTS_TAC    *)
(* (else                                                                     *)
(* it parses as real^2 vector subtraction).                                  *)
let GU_ANTITONE = prove
 (`!f:real->real u v. &0 < u /\ u <= v
   ==> {y | ?a. y < a /\ (a - y) * v < real_integral (real_interval[y,a]) f}
     SUBSET
       {y | ?a. y < a /\ (a - y) * u < real_integral (real_interval[y,a]) f}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
  X_GEN_TAC `y:real` THEN DISCH_THEN(X_CHOOSE_THEN
    `b:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `b:real` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LET_TRANS THEN EXISTS_TAC `((b:real) - y) * v` THEN
    ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC);;

(* Hence u |-> mu(G_u) is non-increasing on u > 0 (GU_ANTITONE +             *)
(* REAL_MEASURE_                                                             *)
(* SUBSET, both G's measurable via MAXIMAL_SUPERLEVEL_MEASURABLE). Route to  *)
(* the                                                                       *)
(* integrability of the u-iterate u |-> 2u mu(G_u).                          *)
let MU_G_DECREASING = prove
 (`!f:real->real u v. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < u
   /\ u <= v
   ==> real_measure {y | ?a. y < a /\ (a - y) * v < real_integral
     (real_interval[y,a]) f} <=
       real_measure {y | ?a. y < a /\ (a - y) * u < real_integral
         (real_interval[y,a]) f}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_MEASURE_SUBSET THEN
    REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MAXIMAL_SUPERLEVEL_MEASURABLE THEN ASM_REWRITE_TAC[] THEN
     ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC MAXIMAL_SUPERLEVEL_MEASURABLE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC GU_ANTITONE THEN ASM_REWRITE_TAC[]]);;

(* u |-> 2u mu(G_u) is integrable on any closed subinterval [a,b] with a >   *)
(* 0: 2u is continuous (integrable) and mu(G_u) is decreasing there          *)
(* (REAL_INTEGRABLE_DECREASING_PRODUCT + MU_G_DECREASING).                   *)
let MAIN_UITER_INTERVAL = prove
 (`!f:real->real a b. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ &0 < a
   ==> (\u. &2 * u * real_measure {y | ?c. y < c /\ (c - y) * u < real_integral
     (real_interval[y,c]) f})
       real_integrable_on real_interval[a,b]`,
  REPEAT STRIP_TAC THEN
  ONCE_REWRITE_TAC[REAL_ARITH `&2 * u * m = m * &2 * u`] THEN
  MATCH_MP_TAC REAL_INTEGRABLE_DECREASING_PRODUCT THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_CONTINUOUS THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_LMUL THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON_ID];
    REPEAT STRIP_TAC THEN MATCH_MP_TAC MU_G_DECREASING THEN
    ASM_REWRITE_TAC[] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[IN_REAL_INTERVAL]) THEN ASM_REAL_ARITH_TAC]);;

(* The dominating function h(u) = 4 int_R (f - u/2)_+ is integrable on {u>0} *)
(* (4 times the POS_PART_LAYER_CAKE integrand).                              *)
let DOMH = prove
 (`!f:real->real. f real_measurable_on (:real) /\ f real_integrable_on (:real)
   /\
     (!x. &0 <= f x) /\ (\x. f x pow 2) real_integrable_on (:real)
   ==> (\u. &4 * real_integral (:real) (\y. max (&0) (f y - u / &2)))
     real_integrable_on {u | &0 < u}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
  REWRITE_TAC[real_integrable_on] THEN
  EXISTS_TAC `real_integral (:real) (\x. (f:real->real) x pow 2)` THEN
  MATCH_MP_TAC POS_PART_LAYER_CAKE THEN ASM_REWRITE_TAC[]);;

(* Domination for the dominated-convergence argument: the truncated          *)
(* approximant                                                               *)
(* (2u mu(G_u) on [1/(k+1),k+1], else 0) is bounded in abs by h(u) = 4 int   *)
(* (f-u/2)_+, uniformly in k, for u > 0.  Uses MAXIMAL_WEAK_TYPE_REFINED     *)
(* (u mu(G_u) <= 2 int(f-u/2)_+) and mu(G_u) >= 0.  ABBREV m, q to keep      *)
(* ASM_REAL_ARITH_TAC linear (the whole context has the nonlinear refined    *)
(* bound).                                                                   *)
let MAIN_DOM = prove
 (`!f:real->real k u. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\ u IN
   {u | &0 < u}
   ==> abs((if u IN real_interval[inv(&k + &1), &k + &1]
            then &2 * u * real_measure {x | ?a. x < a /\ (a - x) * u <
              real_integral (real_interval[x,a]) f}
            else &0))
       <= &4 * real_integral (:real) (\y. max (&0) (f y - u / &2))`,
  REPEAT STRIP_TAC THEN RULE_ASSUM_TAC(REWRITE_RULE[IN_ELIM_THM]) THEN
  MP_TAC(ISPECL [`f:real->real`; `u:real`] MAXIMAL_WEAK_TYPE_REFINED) THEN
    ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `m = real_measure {x | ?a. x < a /\ (a - x) * u < real_integral
    (real_interval[x,a]) f}` THEN
  ABBREV_TAC `q = real_integral (:real) (\y. max (&0) (f y - u / &2))` THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `&0 <= m` ASSUME_TAC THENL
   [EXPAND_TAC "m" THEN MATCH_MP_TAC REAL_MEASURE_POS_LE THEN
    MATCH_MP_TAC MAXIMAL_SUPERLEVEL_MEASURABLE THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= u * m` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  COND_CASES_TAC THEN
  REWRITE_TAC[REAL_ARITH `&2 * u * m = &2 * (u * m)`] THEN
    ASM_REAL_ARITH_TAC);;

(* Arithmetic helper for the pointwise limit: inv K <= u when u+inv u <= K.  *)
let INV_HELP = prove
 (`!u K:real. &0 < u /\ &0 < K /\ u + inv u <= K ==> inv K <= u`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `inv u <= K` ASSUME_TAC THENL
   [MP_TAC(SPEC `u:real` REAL_LE_INV_EQ) THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM REAL_INV_INV] THEN
  MATCH_MP_TAC REAL_LE_INV2 THEN ASM_SIMP_TAC[REAL_LT_INV_EQ]);;

(* The truncated approximant f_k (= 2u mu(G_u) on [1/(k+1),k+1], else 0) is  *)
(* integrable on {u>0}: MAIN_UITER_INTERVAL on [1/(k+1),k+1] (a>0),          *)
(* restricted to {u>0} (REAL_INTEGRABLE_RESTRICT_INTER; the interval meets   *)
(* {u>0} in itself).                                                         *)
let MAIN_FK = prove
 (`!f:real->real k. f real_integrable_on (:real) /\ (!x. &0 <= f x)
   ==> (\u. if u IN real_interval[inv(&k + &1), &k + &1]
            then &2 * u * real_measure {x | ?a. x < a /\ (a - x) * u <
              real_integral (real_interval[x,a]) f}
            else &0) real_integrable_on {u | &0 < u}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_INTEGRABLE_RESTRICT_INTER] THEN
  SUBGOAL_THEN
   `real_interval[inv(&k + &1), &k + &1] INTER {u | &0 < u} =
    real_interval[inv(&k + &1), &k + &1]`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_REAL_INTERVAL; IN_ELIM_THM] THEN
    GEN_TAC THEN EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPEC `&k + &1` REAL_LT_INV_EQ) THEN
    SIMP_TAC[REAL_ARITH `&0 < &k + &1`] THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC MAIN_UITER_INTERVAL THEN ASM_REWRITE_TAC[REAL_LT_INV_EQ] THEN
    REAL_ARITH_TAC]);;

(* Pointwise limit: for fixed u > 0, f_k(u) -> c (the value 2u mu(G_u))      *)
(* since u lies in [1/(k+1),k+1] for all large k (REALLIM_EVENTUALLY +       *)
(* REAL_ARCH).                                                               *)
let MAIN_LIM = prove
 (`!u:real c. &0 < u
   ==> ((\k. if u IN real_interval[inv(&k + &1), &k + &1] then c else &0) --->
     c) sequentially`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REALLIM_EVENTUALLY THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN BETA_TAC THEN
  X_CHOOSE_TAC `N:num` (SPEC `(u:real) + inv u` REAL_ARCH_SIMPLE) THEN
  EXISTS_TAC `N:num` THEN X_GEN_TAC `k:num` THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < inv u` ASSUME_TAC THENL
   [ASM_SIMP_TAC[REAL_LT_INV_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `(u:real) + inv u <= &k + &1` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&N:real` THEN
     ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `&N:real <= &k` MP_TAC THENL
     [ASM_REWRITE_TAC[REAL_OF_NUM_LE]; REAL_ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `u IN real_interval[inv(&k + &1), &k + &1]`
   (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[IN_REAL_INTERVAL] THEN CONJ_TAC THENL
   [MATCH_MP_TAC INV_HELP THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    ASM_REAL_ARITH_TAC]);;

(* THE u-iterate is integrable: u |-> 2u mu(G_u) is integrable on {u>0}.     *)
(* REAL_DOMINATED_CONVERGENCE with approximants f_k truncated to             *)
(* [1/(k+1),k+1]:                                                            *)
(* MAIN_FK (each integrable), DOMH (dominator 4 int(f-u/2)_+ integrable),    *)
(* MAIN_DOM (uniform domination), MAIN_LIM (pointwise limit).  This is the   *)
(* integrability hypothesis of the u-outer Fubini gate for the main region.  *)
let MAIN_UITER = prove
 (`!f:real->real. f real_measurable_on (:real) /\ f real_integrable_on (:real)
   /\
     (!x. &0 <= f x) /\ (\x. f x pow 2) real_integrable_on (:real)
   ==> (\u. &2 * u * real_measure {x | ?a. x < a /\ (a - x) * u < real_integral
     (real_interval[x,a]) f})
       real_integrable_on {u | &0 < u}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\k u. if u IN real_interval[inv(&k + &1), &k + &1]
           then &2 * u * real_measure {x | ?a. x < a /\ (a - x) * u <
             real_integral (real_interval[x,a]) f}
           else &0`;
    `\u. &2 * u * real_measure {x | ?a. x < a /\ (a - x) * u < real_integral
      (real_interval[x,a]) f}`;
    `\u. &4 * real_integral (:real) (\y. max (&0) (f y - u / &2))`;
    `{u | &0 < u}`] REAL_DOMINATED_CONVERGENCE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [GEN_TAC THEN REWRITE_TAC[] THEN MATCH_MP_TAC MAIN_FK THEN
       ASM_REWRITE_TAC[];
      MATCH_MP_TAC DOMH THEN ASM_REWRITE_TAC[];
      REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN MATCH_MP_TAC MAIN_DOM THEN
        ASM_REWRITE_TAC[];
      REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN MATCH_MP_TAC MAIN_LIM THEN
      RULE_ASSUM_TAC(REWRITE_RULE[IN_ELIM_THM]) THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]]);;

(* Real->vector bridge for the u-iterate: a real function integrable on      *)
(* {u>0} gives the lift-extended (0 off {drop y>0}) vector function          *)
(* integrable on (:real^1) (via has_real_integral defn +                     *)
(* HAS_INTEGRAL_RESTRICT_UNIV).                                              *)
let UITER_VEC_BRIDGE = prove
 (`!g:real->real. g real_integrable_on {u | &0 < u}
   ==> (\y:real^1. if &0 < drop y then lift(g(drop y)) else vec 0)
     integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o REWRITE_RULE[real_integrable_on]) THEN
  DISCH_THEN(X_CHOOSE_TAC `k:real`) THEN
  REWRITE_TAC[integrable_on] THEN EXISTS_TAC `lift k` THEN
  SUBGOAL_THEN
   `(\y:real^1. if &0 < drop y then lift(g(drop y)) else vec 0) =
    (\y:real^1. if y IN {w | &0 < drop w} then (\w. lift(g(drop w))) y else vec
      0)`
   SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  REWRITE_TAC[HAS_INTEGRAL_RESTRICT_UNIV] THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[has_real_integral; o_DEF]) THEN
  SUBGOAL_THEN `IMAGE lift {u | &0 < u} = {w:real^1 | &0 < drop w}`
   (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN GEN_TAC THEN EQ_TAC THENL
   [STRIP_TAC THEN ASM_REWRITE_TAC[LIFT_DROP];
    DISCH_TAC THEN EXISTS_TAC `drop x` THEN ASM_REWRITE_TAC[LIFT_DROP]]);;

(* The x-slice (fixed height y with drop y > 0) of the SIGMA region          *)
(* integrand is absolutely integrable on x (its integral = 2 (drop y)        *)
(* mu(G_(drop y))). Mirrors PSI_SLICE_ABS; witness from SIGMA_USLICE.        *)
let SIGMA_SLICE_ABS = prove
 (`!f:real->real y:real^1. f real_integrable_on (:real) /\ (!x. &0 <= f x) /\
   &0 < drop y
   ==> (\x. (\z:real^(1,1)finite_sum.
            if &0 < drop(sndcart z) /\
               (?a. drop(fstcart z) < a /\
                    (a - drop(fstcart z)) * drop(sndcart z) <
                    real_integral (real_interval[drop(fstcart z),a]) f)
            then lift(&2 * drop(sndcart z)) else vec 0)
          (pastecart x y))
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC NONNEGATIVE_ABSOLUTELY_INTEGRABLE THEN
    CONJ_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
     STRIP_TAC THEN
    SUBGOAL_THEN `i = 1` SUBST_ALL_TAC THENL
     [RULE_ASSUM_TAC(REWRITE_RULE[DIMINDEX_1]) THEN
       ASM_ARITH_TAC; ALL_TAC] THEN
    COND_CASES_TAC THEN REWRITE_TAC[LIFT_COMPONENT; VEC_COMPONENT] THEN
      ASM_REAL_ARITH_TAC;
    MP_TAC(ISPECL [`f:real->real`; `y:real^1`] SIGMA_USLICE) THEN
      ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN REWRITE_TAC[integrable_on] THEN
    EXISTS_TAC `lift(&2 * drop y * real_measure {x | ?a. x < a /\ (a - x) *
      drop y < real_integral (real_interval[x,a]) f})` THEN
    ASM_REWRITE_TAC[]]);;

(* The SIGMA region integrand  z |-> 2 sndcart z * [z in main region]  is    *)
(* absolutely integrable on R^2. u-OUTER Tonelli gate                        *)
(* (REAL_FUBINI_NONNEG_ABS_                                                  *)
(* ALT): nonneg + every x-slice abs-int (SIGMA_SLICE_ABS for y>0, else zero) *)
(* +                                                                         *)
(* the u-iterate (\y. int_x SIGMA)(y) = 2y mu(G_y) integrable (SIGMA_USLICE  *)
(* identifies the slice integral; MAIN_UITER + UITER_VEC_BRIDGE give its     *)
(* integrability).  Twin of PSI_ABS, oriented u-outer to dodge the circular  *)
(* "int (f1star)^2 finite".                                                  *)
let SIGMA_ABS = prove
 (`!f:real->real.
     f real_measurable_on (:real) /\ f real_integrable_on (:real) /\
     (!x. &0 <= f x) /\ (\x. f x pow 2) real_integrable_on (:real)
     ==> (\z:real^(1,1)finite_sum.
            if &0 < drop(sndcart z) /\
               (?a. drop(fstcart z) < a /\
                    (a - drop(fstcart z)) * drop(sndcart z) <
                    real_integral (real_interval[drop(fstcart z),a]) f)
            then lift(&2 * drop(sndcart z)) else vec 0)
         absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_FUBINI_NONNEG_ABS_ALT THEN
  REPEAT CONJ_TAC THENL
   [ASM_SIMP_TAC[SIGMA_MEAS];
    GEN_TAC THEN REWRITE_TAC[] THEN COND_CASES_TAC THEN
    REWRITE_TAC[DROP_VEC; LIFT_DROP; REAL_LE_REFL] THEN ASM_REAL_ARITH_TAC;
    X_GEN_TAC `y:real^1` THEN
    ASM_CASES_TAC `&0 < drop(y:real^1)` THENL
     [ASM_SIMP_TAC[SIGMA_SLICE_ABS];
      REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
        ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[ABSOLUTELY_INTEGRABLE_0]];
    SUBGOAL_THEN
     `(\y. integral (:real^1)
        (\x. (\z:real^(1,1)finite_sum.
            if &0 < drop(sndcart z) /\
               (?a. drop(fstcart z) < a /\ (a - drop(fstcart z)) * drop(sndcart
                 z) < real_integral (real_interval[drop(fstcart z),a]) f)
            then lift(&2 * drop(sndcart z)) else vec 0) (pastecart x y))) =
      (\y:real^1. if &0 < drop y
                  then lift(&2 * drop y * real_measure {x | ?a. x < a /\ (a -
                    x) * drop y < real_integral (real_interval[x,a]) f})
                  else vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `y:real^1` THEN
       COND_CASES_TAC THENL
       [MP_TAC(ISPECL [`f:real->real`; `y:real^1`] SIGMA_USLICE) THEN
         ASM_REWRITE_TAC[] THEN
        DISCH_TAC THEN
          FIRST_X_ASSUM(fun th -> ONCE_REWRITE_TAC[MATCH_MP INTEGRAL_UNIQUE
           th]) THEN
        REFL_TAC;
        REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
          ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[INTEGRAL_0]];
      ALL_TAC] THEN
     MP_TAC(ISPEC
       `\u. &2 * u * real_measure {x | ?a. x < a /\ (a - x) * u < real_integral
         (real_interval[x,a]) f}`
       UITER_VEC_BRIDGE) THEN
     ANTS_TAC THENL [MATCH_MP_TAC MAIN_UITER THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
     REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The MAIN region layer-cake (Fremlin 286A(c) proper).  SIGMA integrated    *)
(* two ways:  int_R (f1star)^2 = int_(:R^2) SIGMA = int_{u>0} 2u mu(G_u) du. *)
(* Twin of the POS_PART_FUBINI_RAW / POS_PART_LAYER_CAKE construction.       *)
(* ------------------------------------------------------------------------- *)

(* x-OUTER raw Fubini: the x-outer iterate (\x. int_y SIGMA(pastecart x y))  *)
(* has_integral int_(:R^2) SIGMA.  Stated in the raw (unreduced pastecart,   *)
(* inner bound var y matching FUBINI's) form so the combine avoids "Failure  *)
(* ABS" -- MP_TAC(...FUBINI_ABSOLUTELY_INTEGRABLE...) THEN REWRITE_TAC[].    *)
let MAIN_XOUT_RAW = prove
 (`!f:real->real.
     f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
       f x) /\
     (\x. f x pow 2) real_integrable_on (:real)
     ==> ((\x:real^1.
             integral (:real^1)
             (\y. (\z:real^(1,1)finite_sum.
                if &0 < drop(sndcart z) /\
                   (?a. drop(fstcart z) < a /\
                        (a - drop(fstcart z)) * drop(sndcart z) <
                        real_integral (real_interval[drop(fstcart z),a]) f)
                then lift(&2 * drop(sndcart z)) else vec 0)
              (pastecart x y)))
          has_integral
          (integral (:real^(1,1)finite_sum)
            (\z:real^(1,1)finite_sum.
               if &0 < drop(sndcart z) /\
                  (?a. drop(fstcart z) < a /\
                       (a - drop(fstcart z)) * drop(sndcart z) <
                       real_integral (real_interval[drop(fstcart z),a]) f)
               then lift(&2 * drop(sndcart z)) else vec 0))) (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(CONJUNCT2(MATCH_MP FUBINI_ABSOLUTELY_INTEGRABLE (MATCH_MP SIGMA_ABS
    (ASSUME
    `f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
      f x) /\
     (\x. f x pow 2) real_integrable_on (:real)`)))) THEN
  REWRITE_TAC[]);;

(* Reduced x-outer: (\x. (f1star x)^2) has_integral int_(:R^2) SIGMA.  Spike *)
(* the inner x-slice int_y SIGMA(pastecart x y) to lift((f1star x)^2) via    *)
(* SIGMA_XSLICE (needs boundedness M for the superlevel biconditional).      *)
let MAIN_XOUT = prove
 (`!f:real->real M.
     f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
       f x) /\
     (\x. f x pow 2) real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> ((\x:real^1. lift((hl_maximal_fwd f (drop x)) pow 2))
          has_integral
          (integral (:real^(1,1)finite_sum)
            (\z:real^(1,1)finite_sum.
               if &0 < drop(sndcart z) /\
                  (?a. drop(fstcart z) < a /\
                       (a - drop(fstcart z)) * drop(sndcart z) <
                       real_integral (real_interval[drop(fstcart z),a]) f)
               then lift(&2 * drop(sndcart z)) else vec 0))) (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `f:real->real` MAIN_XOUT_RAW) THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
  MATCH_MP_TAC INTEGRAL_UNIQUE THEN
  MP_TAC(ISPECL [`f:real->real`; `M:real`; `x:real^1`] SIGMA_XSLICE) THEN
  ASM_REWRITE_TAC[]);;

(* u-OUTER raw Fubini (ALT): the u-outer iterate (\y. int_x SIGMA(pastecart  *)
(* x y)) has_integral int_(:R^2) SIGMA.                                      *)
let MAIN_UOUT_RAW = prove
 (`!f:real->real.
     f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
       f x) /\
     (\x. f x pow 2) real_integrable_on (:real)
     ==> ((\y:real^1.
             integral (:real^1)
             (\x. (\z:real^(1,1)finite_sum.
                if &0 < drop(sndcart z) /\
                   (?a. drop(fstcart z) < a /\
                        (a - drop(fstcart z)) * drop(sndcart z) <
                        real_integral (real_interval[drop(fstcart z),a]) f)
                then lift(&2 * drop(sndcart z)) else vec 0)
              (pastecart x y)))
          has_integral
          (integral (:real^(1,1)finite_sum)
            (\z:real^(1,1)finite_sum.
               if &0 < drop(sndcart z) /\
                  (?a. drop(fstcart z) < a /\
                       (a - drop(fstcart z)) * drop(sndcart z) <
                       real_integral (real_interval[drop(fstcart z),a]) f)
               then lift(&2 * drop(sndcart z)) else vec 0))) (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(CONJUNCT2(MATCH_MP FUBINI_ABSOLUTELY_INTEGRABLE_ALT (MATCH_MP
    SIGMA_ABS (ASSUME
    `f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
      f x) /\
     (\x. f x pow 2) real_integrable_on (:real)`)))) THEN
  REWRITE_TAC[]);;

(* SIGMA analogue of INNER_U: the u-outer inner x-slice.                     *)
let SIGMA_INNER_U = prove
 (`!f:real->real y. f real_integrable_on (:real) /\ (!x. &0 <= f x)
   ==> integral (:real^1) (\x. (\z:real^(1,1)finite_sum.
              if &0 < drop(sndcart z) /\
                 (?a. drop(fstcart z) < a /\
                      (a - drop(fstcart z)) * drop(sndcart z) <
                      real_integral (real_interval[drop(fstcart z),a]) f)
              then lift(&2 * drop(sndcart z)) else vec 0)
            (pastecart x y))
       = (if &0 < drop y
          then lift(&2 * drop y * real_measure {x | ?a. x < a /\ (a - x) * drop
            y < real_integral (real_interval[x,a]) f})
          else vec 0)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THENL
   [MATCH_MP_TAC INTEGRAL_UNIQUE THEN
    MP_TAC(ISPECL [`f:real->real`; `y:real^1`] SIGMA_USLICE) THEN
      ASM_REWRITE_TAC[];
    REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
      ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[INTEGRAL_0]]);;

(* The MAIN layer-cake identity, real-level u-side:                          *)
(*   (\u. 2u mu(G_u)) has_real_integral drop(int_(:R^2) SIGMA)  on {u>0}.    *)
(* Real-level restatement of MAIN_UOUT_RAW; spike via SIGMA_INNER_U.         *)
(* Combined                                                                  *)
(* with MAIN_XOUT this gives int_R (f1star)^2 = int_{u>0} 2u mu(G_u) du.     *)
let MAIN_LAYER_CAKE = prove
 (`!f:real->real.
     f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
       f x) /\
     (\x. f x pow 2) real_integrable_on (:real)
     ==> ((\u. &2 * u * real_measure {x | ?a. x < a /\ (a - x) * u <
       real_integral (real_interval[x,a]) f})
          has_real_integral
          drop(integral (:real^(1,1)finite_sum)
            (\z:real^(1,1)finite_sum.
               if &0 < drop(sndcart z) /\
                  (?a. drop(fstcart z) < a /\
                       (a - drop(fstcart z)) * drop(sndcart z) <
                       real_integral (real_interval[drop(fstcart z),a]) f)
               then lift(&2 * drop(sndcart z)) else vec 0))) {u | &0 < u}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[has_real_integral] THEN
  ONCE_REWRITE_TAC[GSYM HAS_INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC HAS_INTEGRAL_SPIKE THEN
  EXISTS_TAC `\y:real^1. integral (:real^1) (\x. (\z:real^(1,1)finite_sum.
              if &0 < drop(sndcart z) /\
                 (?a. drop(fstcart z) < a /\
                      (a - drop(fstcart z)) * drop(sndcart z) <
                      real_integral (real_interval[drop(fstcart z),a]) f)
              then lift(&2 * drop(sndcart z)) else vec 0)
            (pastecart x y))` THEN
  EXISTS_TAC `{}:real^1->bool` THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; IN_DIFF; NOT_IN_EMPTY] THEN CONJ_TAC THENL
   [X_GEN_TAC `y:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[IN_IMAGE_LIFT_DROP; IN_ELIM_THM; o_THM] THEN
    MP_TAC(ISPECL [`f:real->real`; `y:real^1`] SIGMA_INNER_U) THEN
      ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    COND_CASES_TAC THEN REWRITE_TAC[LIFT_DROP];
    REWRITE_TAC[LIFT_DROP] THEN
    MP_TAC(ISPEC `f:real->real` MAIN_UOUT_RAW) THEN
      ASM_REWRITE_TAC[LIFT_DROP]]);;

(* Real-level bridge of MAIN_XOUT: (\x. (f1star x)^2) has_real_integral      *)
(* drop(int_(:R^2) SIGMA)  on (:real).                                       *)
let MAIN_XOUT_REAL = prove
 (`!f:real->real M.
     f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
       f x) /\
     (\x. f x pow 2) real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> ((\x. (hl_maximal_fwd f x) pow 2)
          has_real_integral
          drop(integral (:real^(1,1)finite_sum)
            (\z:real^(1,1)finite_sum.
               if &0 < drop(sndcart z) /\
                  (?a. drop(fstcart z) < a /\
                       (a - drop(fstcart z)) * drop(sndcart z) <
                       real_integral (real_interval[drop(fstcart z),a]) f)
               then lift(&2 * drop(sndcart z)) else vec 0))) (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[has_real_integral; IMAGE_LIFT_UNIV; o_DEF; LIFT_DROP] THEN
  MP_TAC(ISPECL [`f:real->real`; `M:real`] MAIN_XOUT) THEN ASM_REWRITE_TAC[]);;

(* The MAIN comparison bound (Fremlin 286A(c) endgame, one-sided):           *)
(*   int_R (f1star)^2 <= 4 int_R f^2.                                        *)
(* Combine MAIN_XOUT_REAL (LHS = drop(int SIGMA)) with MAIN_LAYER_CAKE       *)
(* (drop(int SIGMA) = int_{u>0} 2u mu(G_u)) and the 4-scaled                 *)
(* POS_PART_LAYER_CAKE                                                       *)
(* (int_{u>0} 4 int(f-u/2)_+ = 4 int f^2) via HAS_REAL_INTEGRAL_LE, with the *)
(* pointwise 2u mu(G_u) <= 4 int(f-u/2)_+ coming from                        *)
(* MAXIMAL_WEAK_TYPE_REFINED                                                 *)
(* (u mu(G_u) <= 2 int(f-u/2)_+, doubled). The nonlinear product u*mu(G_u)   *)
(* is                                                                        *)
(* generalized to a fresh var so ASM_REAL_ARITH can finish.                  *)
let MAIN_COMPARISON = prove
 (`!f:real->real M.
     f real_measurable_on (:real) /\ f real_integrable_on (:real) /\ (!x. &0 <=
       f x) /\
     (\x. f x pow 2) real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> real_integral (:real) (\x. (hl_maximal_fwd f x) pow 2)
         <= &4 * real_integral (:real) (\x. f x pow 2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `M:real`] MAIN_XOUT_REAL) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> SUBST1_TAC(MATCH_MP REAL_INTEGRAL_UNIQUE th)) THEN
  MP_TAC(ISPEC `f:real->real` MAIN_LAYER_CAKE) THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
  MP_TAC(ISPEC `f:real->real` POS_PART_LAYER_CAKE) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `&4` o MATCH_MP HAS_REAL_INTEGRAL_LMUL) THEN
  REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_LE THEN
  MAP_EVERY EXISTS_TAC
   [`\u. &2 * u * real_measure {x | ?a. x < a /\ (a - x) * u < real_integral
     (real_interval[x,a]) f}`;
    `\u. &4 * real_integral (:real) (\y. max (&0) (f y - u / &2))`;
    `{u | &0 < u}`] THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `u:real` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`f:real->real`; `u:real`] MAXIMAL_WEAK_TYPE_REFINED) THEN
    ASM_REWRITE_TAC[] THEN
    SPEC_TAC(`real_measure {x | ?a. x < a /\ (a - x) * u < real_integral
      (real_interval[x,a]) f}`,`m:real`) THEN
    SPEC_TAC(`real_integral (:real) (\x. max (&0) (f x - u / &2))`,`i:real`)
      THEN
    REPEAT STRIP_TAC THEN
    REWRITE_TAC[REAL_ARITH `&2 * u * m = &2 * (u * m) /\ &4 * i = &2 * (&2 *
      i:real)`] THEN
    ASM_REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Two-sided assembly (Fremlin 286A(d)): the full maximal fn hl_maximal is   *)
(* the max of the forward one-sided fn f1star and a BACKWARD one-sided fn    *)
(* f2star, so int (hl_maximal)^2 <= int f1star^2 + int f2star^2 <= 8 int     *)
(* f^2.                                                                      *)
(* The backward fn is obtained from the forward machinery by reflection      *)
(* x |-> -x (a single reflection lemma), so no separate rising-sun/layer-    *)
(* cake development is needed for it.                                        *)
(* ------------------------------------------------------------------------- *)

(* The backward one-sided maximal function: sup of averages over intervals   *)
(* [a,x] to the LEFT of x.                                                   *)
let hl_maximal_bwd = new_definition
 `hl_maximal_bwd (f:real->real) x =
    sup {real_integral (real_interval[a,x]) f / (x - a) | a | a < x}`;;

(* Reflection bridge: bwd f x = fwd (\t. f(-t)) (-x).  Via REAL_INTEGRAL_    *)
(* REFLECT (int_[--b,--a](\t.f(--t)) = int_[a,b]f) on the defining set.      *)
let HL_BWD_REFLECT = prove
 (`!f:real->real x. hl_maximal_bwd f x = hl_maximal_fwd (\t. f(--t)) (--x)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[hl_maximal_bwd; hl_maximal_fwd] THEN
  AP_TERM_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN
  X_GEN_TAC `r:real` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `--a:real` THEN CONJ_TAC THENL
      [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[REAL_ARITH `!a x:real. --a - --x = x - a`] THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
    MP_TAC(ISPECL [`f:real->real`; `a:real`;
      `x:real`] REAL_INTEGRAL_REFLECT) THEN
    REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `--b:real` THEN CONJ_TAC THENL
      [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[REAL_ARITH `!b x:real. b - --x = x - --b`] THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN
    MP_TAC(ISPECL [`f:real->real`; `--b:real`;
      `x:real`] REAL_INTEGRAL_REFLECT) THEN
    REWRITE_TAC[REAL_NEG_NEG]]);;

(* An admissible right-average is <= f1star (it is a member of the sup-set,  *)
(* which is bounded above by M when g <= M).                                 *)
let HL_FWD_GE = prove
 (`!g:real->real M x b. g real_integrable_on (:real) /\ (!y. g y <= M) /\ x < b
   ==> real_integral (real_interval[x,b]) g / (b - x) <= hl_maximal_fwd g x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hl_maximal_fwd] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC
   [`M:real`;
     `real_integral (real_interval[x,b]) (g:real->real) / (b - x)`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `b:real` THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `a:real` THEN DISCH_TAC THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN
    MATCH_MP_TAC REAL_INTEGRAL_UBOUND THEN REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[REAL_LT_IMP_LE];
      MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real)` THEN
      ASM_REWRITE_TAC[SUBSET_UNIV];
      ASM_REWRITE_TAC[]]]);;

(* An admissible left-average is <= f2star (bwd), same argument.             *)
let HL_BWD_GE = prove
 (`!g:real->real M x a. g real_integrable_on (:real) /\ (!y. g y <= M) /\ a < x
   ==> real_integral (real_interval[a,x]) g / (x - a) <= hl_maximal_bwd g x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hl_maximal_bwd] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC
   [`M:real`;
     `real_integral (real_interval[a,x]) (g:real->real) / (x - a)`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `a:real` THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `c:real` THEN DISCH_TAC THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN
    MATCH_MP_TAC REAL_INTEGRAL_UBOUND THEN REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[REAL_LT_IMP_LE];
      MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real)` THEN
      ASM_REWRITE_TAC[SUBSET_UNIV];
      ASM_REWRITE_TAC[]]]);;

(* Mediant inequality: (ll+rr)/(p+q) <= max(ll/p, rr/q) for p,q > 0.         *)
let MEDIANT_LE_MAX = prove
 (`!ll rr p q. &0 < p /\ &0 < q ==> (ll + rr) / (p + q) <= max (ll / p) (rr /
   q)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < p + q` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_ADD_LDISTRIB] THEN
  MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`ll:real`; `p:real`] REAL_DIV_RMUL) THEN
     ASM_SIMP_TAC[REAL_LT_IMP_NZ] THEN
    DISCH_THEN(fun th -> GEN_REWRITE_TAC LAND_CONV [SYM th]) THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN
      ASM_SIMP_TAC[REAL_LT_IMP_LE; REAL_ARITH `!x y:real. x <= max x y`];
    MP_TAC(ISPECL [`rr:real`; `q:real`] REAL_DIV_RMUL) THEN
      ASM_SIMP_TAC[REAL_LT_IMP_NZ] THEN
    DISCH_THEN(fun th -> GEN_REWRITE_TAC LAND_CONV [SYM th]) THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN
      ASM_SIMP_TAC[REAL_LT_IMP_LE; REAL_ARITH `!x y:real. y <= max x y`]]);;

(* The pointwise two-sided <= max bound: hl_maximal f x <=                   *)
(* max(f1star,f2star)                                                        *)
(* of |f|.  Every two-sided average over [a,b] (a<=x<=b) splits at x into a  *)
(* convex combination of the left average (<= f2star, HL_BWD_GE) and right   *)
(* average (<= f1star, HL_FWD_GE); MEDIANT_LE_MAX bounds it by the max.  The *)
(* boundary cases a=x, x=b are pure one-sided.                               *)
let HL_MAX_LE_MAX = prove
 (`!f:real->real M x.
     (\t. abs(f t)) real_integrable_on (:real) /\ (!y. abs(f y) <= M)
     ==> hl_maximal f x <= max (hl_maximal_fwd (\t. abs(f t)) x)
       (hl_maximal_bwd (\t. abs(f t)) x)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hl_maximal] THEN
    MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`real_integral (real_interval[x,x + &1]) (\t. abs((f:real->real) t)) /
       ((x + &1) - x)`;
      `x:real`; `x + &1`] THEN REAL_ARITH_TAC;
    REWRITE_TAC[FORALL_IN_GSPEC]] THEN
  MAP_EVERY X_GEN_TAC [`a:real`; `b:real`] THEN STRIP_TAC THEN
  ASM_CASES_TAC `a:real = x` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `hl_maximal_fwd (\t. abs((f:real->real) t)) x` THEN
    ASM_SIMP_TAC[REAL_ARITH `!x y:real. x <= max x y`] THEN
    MATCH_MP_TAC HL_FWD_GE THEN EXISTS_TAC `M:real` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `x:real = b` THENL
   [FIRST_X_ASSUM(SUBST_ALL_TAC o SYM) THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `hl_maximal_bwd (\t. abs((f:real->real) t)) x` THEN
    ASM_SIMP_TAC[REAL_ARITH `!x y:real. y <= max x y`] THEN
    MATCH_MP_TAC HL_BWD_GE THEN EXISTS_TAC `M:real` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `a < x /\ x < b` STRIP_ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (real_interval[a,b]) (\t. abs((f:real->real) t)) =
    real_integral (real_interval[a,x]) (\t. abs(f t)) +
    real_integral (real_interval[x,b]) (\t. abs(f t))`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_INTEGRAL_COMBINE THEN
     ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN EXISTS_TAC `(:real)` THEN
      ASM_REWRITE_TAC[SUBSET_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN `b - a:real = (x - a) + (b - x)` SUBST1_TAC THENL
    [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `max (real_integral (real_interval[a,x]) (\t. abs((f:real->real)
    t)) / (x - a))
                  (real_integral (real_interval[x,b]) (\t. abs((f:real->real)
                    t)) / (b - x))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC MEDIANT_LE_MAX THEN ASM_REWRITE_TAC[REAL_SUB_LT];
    REWRITE_TAC[REAL_MAX_LE] THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `hl_maximal_bwd (\t. abs((f:real->real) t)) x` THEN
      ASM_SIMP_TAC[REAL_ARITH `!x y:real. y <= max x y`] THEN
      MATCH_MP_TAC HL_BWD_GE THEN EXISTS_TAC `M:real` THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `hl_maximal_fwd (\t. abs((f:real->real) t)) x` THEN
      ASM_SIMP_TAC[REAL_ARITH `!x y:real. x <= max x y`] THEN
      MATCH_MP_TAC HL_FWD_GE THEN EXISTS_TAC `M:real` THEN
        ASM_REWRITE_TAC[]]]);;

(* Whole-line reflection x |-> -x preserves the integral and integrability   *)
(* on                                                                        *)
(* (:real) (IMAGE (--) (:real) = (:real)). Bridges the backward maximal fn   *)
(* to                                                                        *)
(* the forward machinery.                                                    *)
let REAL_INTEGRAL_REFLECT_UNIV = prove
 (`!h:real->real. real_integral (:real) (\x. h(--x)) = real_integral (:real)
   h`,
  GEN_TAC THEN REWRITE_TAC[real_integral] THEN AP_TERM_TAC THEN ABS_TAC THEN
  REWRITE_TAC[HAS_REAL_INTEGRAL_REFLECT_GEN] THEN
  SUBGOAL_THEN `IMAGE (--) (:real) = (:real)` (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN MESON_TAC[REAL_NEG_NEG]);;

let REAL_INTEGRABLE_REFLECT_UNIV = prove
 (`!h:real->real. (\x. h(--x)) real_integrable_on (:real) <=> h
   real_integrable_on (:real)`,
  GEN_TAC THEN REWRITE_TAC[real_integrable_on] THEN
  REWRITE_TAC[HAS_REAL_INTEGRAL_REFLECT_GEN] THEN
  SUBGOAL_THEN `IMAGE (--) (:real) = (:real)` (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN MESON_TAC[REAL_NEG_NEG]);;

(* Forward comparison for |f|:  int (f1star|f|)^2 <= 4 int f^2.              *)
(* MAIN_COMPARISON at g = |f| (measurable via                                *)
(* INTEGRABLE_IMP_REAL_MEASURABLE,                                           *)
(* nonneg, |f|^2 = f^2).                                                     *)
let FWD_COMPARISON_ABS = prove
 (`!f:real->real M.
     (\x. abs(f x)) real_integrable_on (:real) /\
     (\x. f x pow 2) real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> real_integral (:real) (\x. (hl_maximal_fwd (\t. abs(f t)) x) pow 2)
         <= &4 * real_integral (:real) (\x. f x pow 2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\t. abs((f:real->real) t)`; `M:real`] MAIN_COMPARISON) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_ABS_POS];
      REWRITE_TAC[REAL_POW2_ABS] THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN REWRITE_TAC[REAL_ABS_ABS] THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[REAL_POW2_ABS]]);;

(* Backward comparison: int (f2star|f|)^2 <= 4 int f^2. Reflect the backward *)
(* maximal fn to a forward one (HL_BWD_REFLECT), reflect the integration var *)
(* (REAL_INTEGRAL_REFLECT_UNIV), then MAIN_COMPARISON at g = \t. |f(-t)|.    *)
let BWD_COMPARISON = prove
 (`!f:real->real M.
     (\x. abs(f x)) real_integrable_on (:real) /\
     (\x. f x pow 2) real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> real_integral (:real) (\x. (hl_maximal_bwd (\t. abs(f t)) x) pow 2)
         <= &4 * real_integral (:real) (\x. f x pow 2)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[HL_BWD_REFLECT] THEN
  SUBGOAL_THEN
   `real_integral (:real) (\x. (hl_maximal_fwd (\t. abs((f:real->real)(--t)))
     (--x)) pow 2) =
    real_integral (:real) (\y. (hl_maximal_fwd (\t. abs(f(--t))) y) pow 2)`
   SUBST1_TAC THENL
   [GEN_REWRITE_TAC (RAND_CONV) [GSYM REAL_INTEGRAL_REFLECT_UNIV] THEN
     REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `real_integral (:real) (\x. (f:real->real) x pow 2) =
                real_integral (:real) (\x. (f(--x)) pow 2)` SUBST1_TAC THENL
   [GEN_REWRITE_TAC (LAND_CONV) [GSYM REAL_INTEGRAL_REFLECT_UNIV] THEN
     REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\t. abs((f:real->real)(--t))`;
    `M:real`] MAIN_COMPARISON) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN
      ONCE_REWRITE_TAC[GSYM REAL_INTEGRABLE_REFLECT_UNIV] THEN
      REWRITE_TAC[REAL_NEG_NEG] THEN ASM_REWRITE_TAC[];
      ONCE_REWRITE_TAC[GSYM REAL_INTEGRABLE_REFLECT_UNIV] THEN
      REWRITE_TAC[REAL_NEG_NEG] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_ABS_POS];
      REWRITE_TAC[REAL_LE_POW2; REAL_POW2_ABS] THEN
      ONCE_REWRITE_TAC[GSYM REAL_INTEGRABLE_REFLECT_UNIV] THEN
      REWRITE_TAC[REAL_NEG_NEG] THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN REWRITE_TAC[REAL_ABS_ABS] THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[REAL_POW2_ABS]]);;

(* Integrability of the forward maximal fn squared (from MAIN_XOUT_REAL's    *)
(* has_real_integral) and, by reflection, of the backward one squared.       *)
let FWD_SQ_INTEGRABLE = prove
 (`!f:real->real M.
     (\x. abs(f x)) real_integrable_on (:real) /\
     (\x. f x pow 2) real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> (\x. (hl_maximal_fwd (\t. abs(f t)) x) pow 2) real_integrable_on
       (:real)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\t. abs((f:real->real) t)`; `M:real`] MAIN_XOUT_REAL) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_ABS_POS];
      REWRITE_TAC[REAL_POW2_ABS] THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN REWRITE_TAC[REAL_ABS_ABS] THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[real_integrable_on] THEN DISCH_TAC THEN ASM_MESON_TAC[]]);;

let BWD_SQ_INTEGRABLE = prove
 (`!f:real->real M.
     (\x. abs(f x)) real_integrable_on (:real) /\
     (\x. f x pow 2) real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> (\x. (hl_maximal_bwd (\t. abs(f t)) x) pow 2) real_integrable_on
       (:real)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[HL_BWD_REFLECT] THEN
  ONCE_REWRITE_TAC[GSYM REAL_INTEGRABLE_REFLECT_UNIV] THEN
    REWRITE_TAC[REAL_NEG_NEG] THEN
  MP_TAC(ISPECL [`\t. (f:real->real)(--t)`; `M:real`] FWD_SQ_INTEGRABLE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ONCE_REWRITE_TAC[GSYM REAL_INTEGRABLE_REFLECT_UNIV] THEN
      REWRITE_TAC[REAL_NEG_NEG] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[] THEN
      ONCE_REWRITE_TAC[GSYM REAL_INTEGRABLE_REFLECT_UNIV] THEN
      REWRITE_TAC[REAL_NEG_NEG] THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[]]);;

(* The superlevel-open lemma with unrestricted threshold t, needed for       *)
(* f1star measurability at all thresholds.                                   *)
let MAXIMAL_SUPERLEVEL_OPEN_GEN = prove
 (`!f t. f real_integrable_on (:real)
        ==> real_open {x | ?a. x < a /\ (a - x) * t < real_integral
          (real_interval[x,a]) f}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_OPEN; open_def] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM; FORALL_LIFT; DIST_LIFT] THEN
  X_GEN_TAC `x0:real` THEN DISCH_THEN(X_CHOOSE_THEN
    `a:real` STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[LIFT_IN_IMAGE_LIFT; IN_ELIM_THM] THEN
  SUBGOAL_THEN
   `(\x. real_integral (real_interval[x,a]) f - (a - x) * t) real_continuous
     (atreal x0)`
   MP_TAC THENL
   [MATCH_MP_TAC REAL_CONTINUOUS_SUB THEN CONJ_TAC THENL
     [MATCH_MP_TAC RUNNING_INTEGRAL_CONTINUOUS THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_CONTINUOUS_MUL THEN
        REWRITE_TAC[REAL_CONTINUOUS_CONST] THEN
      MATCH_MP_TAC REAL_CONTINUOUS_SUB THEN
      REWRITE_TAC[REAL_CONTINUOUS_CONST; REAL_CONTINUOUS_AT_ID]];
    ALL_TAC] THEN
  REWRITE_TAC[real_continuous_atreal; REALLIM_ATREAL] THEN
  DISCH_THEN(MP_TAC o SPEC `real_integral (real_interval[x0,a]) f - (a - x0) *
    t`) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `min d (a - x0)` THEN ASM_REWRITE_TAC[REAL_LT_MIN] THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `x':real` THEN STRIP_TAC THEN EXISTS_TAC `a:real` THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `x':real`) THEN ASM_REAL_ARITH_TAC);;

(* Each one-sided maximal fn is <= the full two-sided one (a one-sided       *)
(* average                                                                   *)
(* is an admissible two-sided average). With HL_MAX_LE_MAX this gives the    *)
(* EXACT                                                                     *)
(* decomposition hl_maximal f = max(f1star,f2star) of |f|.                   *)
let HL_FWD_LE_MAXIMAL = prove
 (`!f:real->real M x.
     (\t. abs(f t)) real_integrable_on (:real) /\ (!y. abs(f y) <= M)
     ==> hl_maximal_fwd (\t. abs(f t)) x <= hl_maximal f x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hl_maximal_fwd] THEN
    MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    EXISTS_TAC `real_integral (real_interval[x,x + &1]) (\t. abs((f:real->real)
      t)) / ((x + &1) - x)` THEN
    EXISTS_TAC `x + &1` THEN REAL_ARITH_TAC;
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `b:real` THEN DISCH_TAC] THEN
  REWRITE_TAC[hl_maximal] THEN MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC
   [`M:real`;
     `real_integral (real_interval[x,b]) (\t. abs((f:real->real) t)) / (b -
     x)`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN MAP_EVERY EXISTS_TAC [`x:real`;`b:real`] THEN
    ASM_REWRITE_TAC[REAL_LE_REFL] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN
      MAP_EVERY X_GEN_TAC [`p:real`;`q:real`] THEN STRIP_TAC THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN
    MATCH_MP_TAC REAL_INTEGRAL_UBOUND THEN REPEAT CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV];
      ASM_REWRITE_TAC[]]]);;

let HL_BWD_LE_MAXIMAL = prove
 (`!f:real->real M x.
     (\t. abs(f t)) real_integrable_on (:real) /\ (!y. abs(f y) <= M)
     ==> hl_maximal_bwd (\t. abs(f t)) x <= hl_maximal f x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hl_maximal_bwd] THEN
    MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    EXISTS_TAC `real_integral (real_interval[x - &1,x]) (\t. abs((f:real->real)
      t)) / (x - (x - &1))` THEN
    EXISTS_TAC `x - &1` THEN REAL_ARITH_TAC;
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `a:real` THEN DISCH_TAC] THEN
  REWRITE_TAC[hl_maximal] THEN MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC
   [`M:real`;
     `real_integral (real_interval[a,x]) (\t. abs((f:real->real) t)) / (x -
     a)`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN MAP_EVERY EXISTS_TAC [`a:real`;`x:real`] THEN
    ASM_REWRITE_TAC[REAL_LE_REFL] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN
      MAP_EVERY X_GEN_TAC [`p:real`;`q:real`] THEN STRIP_TAC THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN
    MATCH_MP_TAC REAL_INTEGRAL_UBOUND THEN REPEAT CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV];
      ASM_REWRITE_TAC[]]]);;

(* Whole-line reflection preserves real-measurability (via the vector        *)
(* MEASURABLE_ON_REFLECT and the real<->vector bridge).                      *)
let REAL_MEASURABLE_ON_REFLECT_UNIV = prove
 (`!h:real->real. (\x. h(--x)) real_measurable_on (:real) <=> h
   real_measurable_on (:real)`,
  GEN_TAC THEN REWRITE_TAC[real_measurable_on; IMAGE_LIFT_UNIV] THEN
  SUBGOAL_THEN
    `lift o (\x. h(--x)) o drop =
     (\v. (lift o h o drop)(--v))` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
     REWRITE_TAC[DROP_NEG]; ALL_TAC] THEN
  REWRITE_TAC[MEASURABLE_ON_REFLECT; ETA_AX] THEN
  SUBGOAL_THEN `IMAGE (--) (:real^1) = (:real^1)` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN
     MESON_TAC[VECTOR_NEG_NEG]; REWRITE_TAC[]]);;

(* f1star is measurable: its superlevel {x | a < f1star g x} = the OPEN G_a  *)
(* (SUB/SUPER biconditional under boundedness) for every threshold a;        *)
(* halfspace- GT criterion + open => lebesgue-measurable.                    *)
let HL_FWD_MEASURABLE = prove
 (`!g:real->real M. g real_integrable_on (:real) /\ (!x. abs(g x) <= M)
   ==> hl_maximal_fwd g real_measurable_on (:real)`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[REAL_MEASURABLE_ON_PREIMAGE_HALFSPACE_GT] THEN
  X_GEN_TAC `a:real` THEN REWRITE_TAC[real_gt] THEN
  SUBGOAL_THEN
   `{x | a < hl_maximal_fwd (g:real->real) x} =
    {x | ?c. x < c /\ (c - x) * a < real_integral (real_interval[x,c]) g}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN X_GEN_TAC `x:real` THEN
     EQ_TAC THENL
     [DISCH_TAC THEN MATCH_MP_TAC HL_FWD_SUPERLEVEL_SUB THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN MATCH_MP_TAC HL_FWD_SUPERLEVEL_SUPER THEN
      EXISTS_TAC `M:real` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_OPEN THEN
  MATCH_MP_TAC MAXIMAL_SUPERLEVEL_OPEN_GEN THEN ASM_REWRITE_TAC[]);;

(* f2star is measurable, by reflecting f1star.                               *)
let HL_BWD_MEASURABLE = prove
 (`!g:real->real M. g real_integrable_on (:real) /\ (!x. abs(g x) <= M)
   ==> hl_maximal_bwd g real_measurable_on (:real)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `hl_maximal_bwd (g:real->real) = (\x. hl_maximal_fwd (\t. g(--t)) (--x))`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; HL_BWD_REFLECT]; ALL_TAC] THEN
  MP_TAC(ISPEC `hl_maximal_fwd (\t. (g:real->real)(--t))`
    REAL_MEASURABLE_ON_REFLECT_UNIV) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC HL_FWD_MEASURABLE THEN EXISTS_TAC `M:real` THEN CONJ_TAC THENL
   [ONCE_REWRITE_TAC[GSYM REAL_INTEGRABLE_REFLECT_UNIV] THEN
    REWRITE_TAC[REAL_NEG_NEG; ETA_AX] THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN ASM_REWRITE_TAC[]]);;

(* hl_maximal f is measurable: it equals max(f1star,f2star) of |f|           *)
(* (HL_MAX_LE_MAX + the two reverse inequalities), and                       *)
(* REAL_MEASURABLE_ON_MAX.                                                   *)
let HL_MAXIMAL_MEASURABLE = prove
 (`!f:real->real M.
     (\t. abs(f t)) real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> hl_maximal f real_measurable_on (:real)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `hl_maximal (f:real->real) =
    (\x. max (hl_maximal_fwd (\t. abs(f t)) x) (hl_maximal_bwd (\t. abs(f t))
      x))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real` THEN
    REWRITE_TAC[GSYM REAL_LE_ANTISYM] THEN CONJ_TAC THENL
     [MATCH_MP_TAC HL_MAX_LE_MAX THEN EXISTS_TAC `M:real` THEN
       ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_MAX_LE] THEN CONJ_TAC THENL
       [MATCH_MP_TAC HL_FWD_LE_MAXIMAL THEN EXISTS_TAC `M:real` THEN
         ASM_REWRITE_TAC[];
        MATCH_MP_TAC HL_BWD_LE_MAXIMAL THEN EXISTS_TAC `M:real` THEN
          ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_MAX THEN REWRITE_TAC[ETA_AX] THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC HL_FWD_MEASURABLE THEN EXISTS_TAC `M:real` THEN
    ASM_REWRITE_TAC[] THEN GEN_TAC THEN REWRITE_TAC[REAL_ABS_ABS] THEN
      ASM_REWRITE_TAC[];
    MATCH_MP_TAC HL_BWD_MEASURABLE THEN EXISTS_TAC `M:real` THEN
    ASM_REWRITE_TAC[] THEN GEN_TAC THEN REWRITE_TAC[REAL_ABS_ABS] THEN
      ASM_REWRITE_TAC[]]);;

(* hl_maximal f is nonnegative (sup of averages of the nonnegative |f|).     *)
let HL_MAXIMAL_POS = prove
 (`!f:real->real M x. (\t. abs(f t)) real_integrable_on (:real) /\ (!y. abs(f
   y) <= M)
   ==> &0 <= hl_maximal f x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hl_maximal] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral (real_interval[x,x + &1]) (\t. abs((f:real->real)
    t)) / ((x + &1) - x)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_POS THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
         EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV];
        REWRITE_TAC[REAL_ABS_POS]];
      REAL_ARITH_TAC];
    MATCH_MP_TAC REAL_LE_SUP THEN
    MAP_EVERY EXISTS_TAC
     [`M:real`;
       `real_integral (real_interval[x,x + &1]) (\t. abs((f:real->real) t)) /
       ((x + &1) - x)`] THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN
       MAP_EVERY EXISTS_TAC [`x:real`; `x + &1`] THEN REAL_ARITH_TAC;
      REWRITE_TAC[REAL_LE_REFL];
      REWRITE_TAC[FORALL_IN_GSPEC] THEN
        MAP_EVERY X_GEN_TAC [`a:real`;`b:real`] THEN STRIP_TAC THEN
      ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_SUB_LT] THEN
      MATCH_MP_TAC REAL_INTEGRAL_UBOUND THEN REPEAT CONJ_TAC THENL
       [ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
          EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV];
        ASM_REWRITE_TAC[]]]]);;

(* Backward maximal function is bounded by M when |f| <= M (via              *)
(* HL_BWD_REFLECT to the forward maximal function of the reflection, which   *)
(* is also bounded).                                                         *)
let HL_BWD_BOUNDED = prove
 (`!f:real->real M. f real_integrable_on (:real) /\ (!x. abs(f x) <= M)
     ==> !x. hl_maximal_bwd f x <= M`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN
  REWRITE_TAC[HL_BWD_REFLECT] THEN
  MP_TAC(ISPECL [`\t. (f:real->real)(--t)`; `M:real`] HL_FWD_BOUNDED) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[REAL_INTEGRABLE_REFLECT_UNIV; ETA_AX] THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN REWRITE_TAC[] THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* The two-sided H-L maximal function is bounded by M when |f| <= M. (fwd,   *)
(* bwd                                                                       *)
(* both <= M, and hl_maximal <= max of them by HL_MAX_LE_MAX.)               *)
let HL_MAXIMAL_BOUNDED = prove
 (`!f:real->real M. (\t. abs(f t)) real_integrable_on (:real) /\ (!x. abs(f x)
   <= M)
     ==> !x. hl_maximal f x <= M`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `max (hl_maximal_fwd (\t. abs((f:real->real) t)) x)
                  (hl_maximal_bwd (\t. abs(f t)) x)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC HL_MAX_LE_MAX THEN EXISTS_TAC `M:real` THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_MAX_LE] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`\t. abs((f:real->real) t)`;
       `M:real`] HL_FWD_BOUNDED) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[REAL_ABS_ABS]; DISCH_THEN(fun th -> REWRITE_TAC[th])];
      MP_TAC(ISPECL [`\t. abs((f:real->real) t)`;
        `M:real`] HL_BWD_BOUNDED) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[REAL_ABS_ABS];
         DISCH_THEN(fun th -> REWRITE_TAC[th])]]]);;

(* max(a,b)^2 <= a^2 + b^2.                                                  *)
let MAX_SQ_LE = prove
 (`!a b:real. max a b pow 2 <= a pow 2 + b pow 2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[real_max] THEN COND_CASES_TAC THEN
  REWRITE_TAC[REAL_LE_ADDL; REAL_LE_ADDR; REAL_LE_POW_2]);;

(* Pointwise:  (hl_maximal f x)^2 <= (f1star x)^2 + (f2star x)^2  of |f|.    *)
(* From 0 <= hl_maximal f x <= max(f1star,f2star) (square-monotone) and      *)
(* MAX_SQ_LE.                                                                *)
let HL_SQ_PTBOUND = prove
 (`!f:real->real M x.
     (\t. abs(f t)) real_integrable_on (:real) /\ (!y. abs(f y) <= M)
     ==> hl_maximal f x pow 2 <=
         (hl_maximal_fwd (\t. abs(f t)) x) pow 2 + (hl_maximal_bwd (\t. abs(f
           t)) x) pow 2`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(max (hl_maximal_fwd (\t. abs((f:real->real) t)) x)
                   (hl_maximal_bwd (\t. abs(f t)) x)) pow 2` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_POW_LE2 THEN CONJ_TAC THENL
     [MATCH_MP_TAC HL_MAXIMAL_POS THEN EXISTS_TAC `M:real` THEN
       ASM_REWRITE_TAC[];
      MATCH_MP_TAC HL_MAX_LE_MAX THEN EXISTS_TAC `M:real` THEN
        ASM_REWRITE_TAC[]];
    REWRITE_TAC[MAX_SQ_LE]]);;

(* 286B/(vi) support: a per-interval average of |f| over [a,b] (with         *)
(* a<=x<=b) is                                                               *)
(* <= hl_maximal f x, provided the averages are bounded above by some M      *)
(* (needed                                                                   *)
(* for HOL's sup to behave; holds for bounded f, e.g. Schwartz). This is the *)
(* "gamma <= f-star(x')" step of Fremlin's monotone-kernel bound (286B), in  *)
(* the                                                                       *)
(* form part (h)(vi) consumes: the maximal average over intervals straddling *)
(* [alpha,beta] is dominated by the H-L maximal function at any interior     *)
(* point.                                                                    *)
let AVG_LE_HL_MAXIMAL = prove
 (`!f:real->real M a b x.
     a <= x /\ x <= b /\ a < b /\
     (!c d. c < d ==> real_integral (real_interval[c,d]) (\t. abs(f t)) / (d -
       c) <= M)
     ==> real_integral (real_interval[a,b]) (\t. abs(f t)) / (b - a) <=
       hl_maximal f x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hl_maximal] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC
   [`M:real`;
    `real_integral (real_interval[a,b]) (\t. abs((f:real->real) t)) / (b - a)`]
      THEN
  REWRITE_TAC[IN_ELIM_THM] THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_REFL];
    X_GEN_TAC `z:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `c:real` (X_CHOOSE_THEN
      `d:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* The Hardy-Littlewood maximal theorem at p = 2 (Fremlin 286A).             *)
(*                                                                           *)
(* The application in 286L is to a Schwartz (hence L^1 cap L^2) function.    *)
(* Thus only the strong p=2 estimate is needed, with                         *)
(* constant 2 (p/(p-1)) rpow p = 8 at p = 2, i.e. ||fstar||_2 <= 2 sqrt2     *)
(* ||f||_2.                                                                  *)
(*                                                                           *)
(* Assembled from MAXIMAL_WEAK_TYPE (= Fremlin 286A(b), the p-independent    *)
(* core) via the refined per-level bound u mu(G_u) <= 2 int (f-u/2)_+        *)
(* and the t = u squared layer-cake + Fubini (286A(c)), with fstar =         *)
(* max(f1star,f2star) (286A(d)) contributing the factor 2 (hence 4 -> 8).    *)
(*                                                                           *)
(* BOUNDEDNESS HYPOTHESIS: we assume f is                                    *)
(* BOUNDED (?M. !x. abs(f x) <= M).  This makes the one-sided maximal fn     *)
(* hl_maximal_fwd finite EVERYWHERE (average of things <= M is <= M), so the *)
(* sup-junk locus B (where the running averages are unbounded) is EMPTY, the *)
(* superlevel identity {x | u < f1* x} = G_u holds as a full biconditional,  *)
(* and every layer-cake section is a genuine bounded interval.  The          *)
(* application below is to a Schwartz function, so this suffices.            *)
(* ========================================================================= *)

(* NOTE on the integrability hypothesis: we assume the ABSOLUTE              *)
(* integrability                                                             *)
(* (\x. abs(f x)) real_integrable_on (:real) -- equivalently f in L^1 --     *)
(* rather                                                                    *)
(* than the weaker conditional f real_integrable_on (:real). This is what    *)
(* the                                                                       *)
(* two-sided average (which is built from |f|) genuinely needs, and it is    *)
(* automatic for Carleson's Schwartz g~ (286L), which is L^1 cap L^2.        *)
let HARDY_LITTLEWOOD_MAXIMAL_L2 = prove
 (`!f. (\x. abs(f x)) real_integrable_on (:real) /\
       (\x. f x pow 2) real_integrable_on (:real) /\
       (?M. !x. abs(f x) <= M)
       ==> (\x. hl_maximal f x pow 2) real_integrable_on (:real) /\
           real_integral (:real) (\x. hl_maximal f x pow 2)
           <= &8 * real_integral (:real) (\x. f x pow 2)`,
  GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `M:real`))) THEN
  MP_TAC(ISPECL [`f:real->real`;`M:real`] FWD_SQ_INTEGRABLE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->real`;`M:real`] BWD_SQ_INTEGRABLE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->real`;`M:real`] FWD_COMPARISON_ABS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->real`;`M:real`] BWD_COMPARISON) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->real`;`M:real`] HL_MAXIMAL_MEASURABLE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(\x. (hl_maximal_fwd (\t. abs((f:real->real) t)) x) pow 2 +
         (hl_maximal_bwd (\t. abs(f t)) x) pow 2) real_integrable_on (:real)`
   ASSUME_TAC THENL [MATCH_MP_TAC REAL_INTEGRABLE_ADD THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x. hl_maximal (f:real->real) x pow 2) real_integrable_on (:real)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
    EXISTS_TAC `(\x. (hl_maximal_fwd (\t. abs((f:real->real) t)) x) pow 2 +
                     (hl_maximal_bwd (\t. abs(f t)) x) pow 2)` THEN
    REPEAT CONJ_TAC THENL
     [ONCE_REWRITE_TAC[REAL_POW_2] THEN
       MATCH_MP_TAC REAL_MEASURABLE_ON_MUL THEN
      CONJ_TAC THEN ASM_REWRITE_TAC[ETA_AX];
      ASM_REWRITE_TAC[];
      X_GEN_TAC `x:real` THEN DISCH_TAC THEN
        REWRITE_TAC[REAL_ABS_POW; REAL_POW2_ABS] THEN
      MATCH_MP_TAC HL_SQ_PTBOUND THEN EXISTS_TAC `M:real` THEN
        ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral (:real) (\x. (hl_maximal_fwd (\t.
    abs((f:real->real) t)) x) pow 2 +
                                         (hl_maximal_bwd (\t. abs(f t)) x) pow
                                           2)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    MATCH_MP_TAC HL_SQ_PTBOUND THEN EXISTS_TAC `M:real` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (:real) (\x. (hl_maximal_fwd (\t. abs((f:real->real) t)) x)
     pow 2 +
                               (hl_maximal_bwd (\t. abs(f t)) x) pow 2) =
    real_integral (:real) (\x. (hl_maximal_fwd (\t. abs(f t)) x) pow 2) +
    real_integral (:real) (\x. (hl_maximal_bwd (\t. abs(f t)) x) pow 2)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_ADD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&4 * real_integral (:real) (\x. (f:real->real) x pow 2) +
              &4 * real_integral (:real) (\x. f x pow 2)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_ADD2 THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_ARITH `&4 * a + &4 * a = &8 * a`; REAL_LE_REFL]]);;

(* ========================================================================= *)
(* Tile setup and partial orders (Fremlin 286E-286G).                        *)
(* The dyadic grid, tile orders, and weight estimates are geometric; the     *)
(* tile-localized test functions use the Fourier and Schwartz theory above.  *)
(* ========================================================================= *)

(* --- The dyadic grid (286E) ---------------------------------------------  *)
(* Fremlin's dyadic intervals are the half-open  [2^k n, 2^k (n+1))  with    *)
(* k,n in Z (here dyho k n).  Half-open is essential: it makes distinct      *)
(* same-scale intervals genuinely DISJOINT (closed intervals would share an  *)
(* endpoint) and gives the clean nesting trichotomy.  2^k for k in Z is the  *)
(* integer power  &2 zpow k.                                                 *)

let dyho = new_definition
 `dyho (k:int) (n:int) =
    {x:real | real_of_int n * &2 zpow k <= x /\ x < (real_of_int n + &1) * &2
      zpow k}`;;

(* 2^d is a positive integer when d >= 0 (used to change scale).             *)
let DYADIC_SCALE_INT = prove
 (`!d:int. &0 <= d ==> ?u:int. &2 zpow d = real_of_int u /\ &1 <= u`,
  REPEAT STRIP_TAC THEN EXISTS_TAC `(&2:int) pow (num_of_int d)` THEN
  ASM_SIMP_TAC[real_zpow] THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[REAL_OF_INT_CLAUSES]; REWRITE_TAC[INT_LE_POW2]]);;

(* int<->real bridges kept LOCAL and TARGETED: the full REAL_OF_INT_CLAUSES  *)
(* under GSYM would rewrite &2 into real_of_int(&2) and corrupt the zpow     *)
(* base, so we extract only the product/sum/one clauses as directed          *)
(* rewrites.                                                                 *)
let ROI_LT_SUCC = prove
 (`!a b:int. real_of_int a < real_of_int b + &1 ==> a <= b`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM INT_NOT_LT] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`b:int`;`a:int`] INT_LT_DISCRETE) THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
  SUBGOAL_THEN `real_of_int b + &1 <= real_of_int a` MP_TAC THENL
   [SUBGOAL_THEN `real_of_int(b + &1) <= real_of_int a` MP_TAC THENL
     [ASM_REWRITE_TAC[GSYM int_le]; ALL_TAC] THEN
    REWRITE_TAC[REAL_OF_INT_CLAUSES] THEN
      SIMP_TAC[GSYM REAL_OF_INT_CLAUSES] THEN
    REWRITE_TAC[REAL_OF_INT_CLAUSES]; ALL_TAC] THEN ASM_REAL_ARITH_TAC);;

let ROI_MUL = prove
 (`!a b:int. real_of_int(a * b) = real_of_int a * real_of_int b`,
  REWRITE_TAC[REAL_OF_INT_CLAUSES]);;

let ROI_ADD = prove
 (`!a b:int. real_of_int(a + b) = real_of_int a + real_of_int b`,
  REWRITE_TAC[REAL_OF_INT_CLAUSES]);;

let ROI_1 = prove
 (`real_of_int(&1) = &1`,
  REWRITE_TAC[REAL_OF_INT_CLAUSES]);;

(* Same-scale disjointness: distinct dyadic intervals of the same length are *)
(* disjoint.                                                                 *)
let DYHO_DISJOINT_SAMESCALE = prove
 (`!k n m. ~(n = m) ==> DISJOINT (dyho k n) (dyho k m)`,
  SUBGOAL_THEN
    `!k p q:int. p < q ==> DISJOINT (dyho k p) (dyho k q)` ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `real_of_int p + &1 <= real_of_int q` ASSUME_TAC THENL
     [SUBGOAL_THEN `real_of_int(p + &1) <= real_of_int q` MP_TAC THENL
       [REWRITE_TAC[GSYM int_le] THEN
         ASM_MESON_TAC[INT_LT_DISCRETE]; ALL_TAC] THEN
      REWRITE_TAC[ROI_ADD; ROI_1]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(real_of_int p + &1) * &2 zpow k <= real_of_int q * &2 zpow k`
      ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_LE_RMUL THEN
       ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; dyho;
      IN_ELIM_THM] THEN
    X_GEN_TAC `x:real` THEN ASM_REAL_ARITH_TAC;
    REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`n:int`; `m:int`] INT_LT_TOTAL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[DISJOINT_SYM]]);;

(* NESTING (the essential geometric property, 286E): if a finer dyadic       *)
(* interval (k <= k', so length 2^k <= 2^k') meets a coarser one, it is      *)
(* contained in it.  Reduce to integers by writing 2^k' = 2^k * u with u a   *)
(* positive integer (DYADIC_SCALE_INT), then n' u <= n and n+1 <= (n'+1) u.  *)
let DYHO_NEST = prove
 (`!k k' n n' x.
     k <= k' /\ x IN dyho k n /\ x IN dyho k' n'
     ==> dyho k n SUBSET dyho k' n'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM; SUBSET] THEN
    STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPEC `k' - k:int` DYADIC_SCALE_INT) THEN ANTS_TAC THENL
    [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:int` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `&2 zpow k' = &2 zpow k * real_of_int u` ASSUME_TAC THENL
   [SUBGOAL_THEN
     `k':int = k + (k' - k)` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
     [th]) THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`]; ALL_TAC] THEN
  FIRST_ASSUM(fun th -> if concl th = `&2 zpow k' = &2 zpow k * real_of_int u`
     then (ONCE_REWRITE_TAC[th] THEN
       RULE_ASSUM_TAC(ONCE_REWRITE_RULE[th])) else NO_TAC) THEN
  ABBREV_TAC `tt = &2 zpow k` THEN
  SUBGOAL_THEN `(n':int) * u <= n` ASSUME_TAC THENL
   [MATCH_MP_TAC ROI_LT_SUCC THEN REWRITE_TAC[ROI_MUL] THEN
    SUBGOAL_THEN
      `(real_of_int n' * real_of_int u) * tt < (real_of_int n + &1) * tt`
      MP_TAC THENL
     [SUBGOAL_THEN
       `(real_of_int n' * real_of_int u) * tt =
        real_of_int n' * (tt * real_of_int u)`
        SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
          ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LT_RMUL_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `(n:int) < (n' + &1) * u` ASSUME_TAC THENL
   [SUBGOAL_THEN `real_of_int n < real_of_int((n' + &1) * u)` MP_TAC THENL
     [REWRITE_TAC[ROI_MUL; ROI_ADD; ROI_1] THEN
      SUBGOAL_THEN
        `real_of_int n * tt < ((real_of_int n' + &1) * real_of_int u) * tt`
        MP_TAC THENL
       [SUBGOAL_THEN
         `((real_of_int n' + &1) * real_of_int u) * tt = (real_of_int n' + &1)
         * (tt * real_of_int u)`
          SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
            ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_SIMP_TAC[REAL_LT_RMUL_EQ]; ALL_TAC] THEN
    REWRITE_TAC[REAL_OF_INT_CLAUSES]; ALL_TAC] THEN
  SUBGOAL_THEN `(n:int) + &1 <= (n' + &1) * u` ASSUME_TAC THENL
   [ASM_MESON_TAC[INT_LT_DISCRETE]; ALL_TAC] THEN
  X_GEN_TAC `y:real` THEN STRIP_TAC THEN
  SUBGOAL_THEN `real_of_int n' * (tt * real_of_int u) <= real_of_int n * tt /\
                (real_of_int n + &1) * tt <= (real_of_int n' + &1) * (tt *
                  real_of_int u)` MP_TAC THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN
       `real_of_int n' * (tt * real_of_int u) =
        (real_of_int n' * real_of_int u) * tt`
        SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
      REWRITE_TAC[GSYM ROI_MUL; GSYM int_le] THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN
        `(real_of_int n' + &1) * (tt * real_of_int u) = ((real_of_int n' + &1)
        * real_of_int u) * tt`
        SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
      REWRITE_TAC[GSYM ROI_1; GSYM ROI_ADD; GSYM ROI_MUL; GSYM int_le] THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* The nesting trichotomy: any two dyadic intervals are nested or disjoint.  *)
let DYHO_TRICHOTOMY = prove
 (`!k n k' n'. dyho k n SUBSET dyho k' n' \/ dyho k' n' SUBSET dyho k n \/
               DISJOINT (dyho k n) (dyho k' n')`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `DISJOINT (dyho k n) (dyho k' n')` THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[DISJOINT; GSYM MEMBER_NOT_EMPTY;
    IN_INTER]) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:real` STRIP_ASSUME_TAC) THEN
  DISJ_CASES_TAC(INT_ARITH `(k:int) <= k' \/ k':int <= k`) THENL
   [DISJ1_TAC THEN MATCH_MP_TAC DYHO_NEST THEN EXISTS_TAC `x:real` THEN
     ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ1_TAC THEN MATCH_MP_TAC DYHO_NEST THEN
      EXISTS_TAC `x:real` THEN ASM_REWRITE_TAC[]]);;

(* A dyadic interval is nonempty (contains its left endpoint).               *)
let DYHO_NONEMPTY = prove
 (`!k n. (real_of_int n * &2 zpow k) IN dyho k n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN
  SUBGOAL_THEN `&0 < &2 zpow k` MP_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
     REAL_ARITH_TAC);;

(* Same-scale nesting forces EQUALITY: two dyadic cells of the same length,  *)
(* one                                                                       *)
(* contained in the other, must coincide (a nonempty subset cannot be        *)
(* disjoint                                                                  *)
(* from its superset, but distinct same-scale cells ARE disjoint). The       *)
(* equal-                                                                    *)
(* scale companion to DYHO_SUBSET_SCALE; feeds the tree J-orthogonality of   *)
(* 286L.                                                                     *)
let DYHO_SAMESCALE_EQ = prove
 (`!k m n. dyho k m SUBSET dyho k n ==> m = n`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  GEN_REWRITE_TAC I [TAUT `p <=> ~ ~p`] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`k:int`; `m:int`; `n:int`] DYHO_DISJOINT_SAMESCALE) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`k:int`; `m:int`] DYHO_NONEMPTY) THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  DISCH_TAC THEN DISCH_THEN(MP_TAC o SPEC `real_of_int m * &2 zpow k`) THEN
  ASM SET_TAC[]);;

(* 2^k = 2 * 2^(k-1); and the halving dyho k n = dyho(k-1)(2n) UNION         *)
(* dyho(k-1)(2n+1).                                                          *)
let ZPOWK_HALF = prove
 (`!k:int. &2 zpow k = &2 * &2 zpow (k - &1)`,
  GEN_TAC THEN
  SUBGOAL_THEN
    `k:int = (k - &1) + &1` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
    [th]) THENL
   [INT_ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
  REWRITE_TAC[REAL_ZPOW_1] THEN REAL_ARITH_TAC);;

let ROI_2 = prove (`real_of_int(&2) = &2`, MESON_TAC[REAL_OF_INT_CLAUSES]);;

(* Integer arithmetic helpers for the 286Fc J^l-disjointness (parity)        *)
(* argument. 2 zpow d for d >= 1 is an EVEN positive integer: it equals 2 *  *)
(* 2^(d-1).                                                                  *)
let ZPOW_POS_EVEN_INT = prove
 (`!d:int. &1 <= d
     ==> ?M:int. &2 zpow d = real_of_int M /\ (?M':int. M = &2 * M' /\ &1 <=
       M')`,
  REPEAT STRIP_TAC THEN
  EXISTS_TAC `&2 * &(2 EXP (num_of_int (d - &1))):int` THEN
  SUBGOAL_THEN `d - &1 = &(num_of_int (d - &1))` ASSUME_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC INT_OF_NUM_OF_INT THEN
     ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [GEN_REWRITE_TAC (LAND_CONV) [ZPOWK_HALF] THEN
    REWRITE_TAC[int_mul_th; int_of_num_th] THEN AP_TERM_TAC THEN
    FIRST_ASSUM(fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [th]) THEN
    REWRITE_TAC[REAL_ZPOW_POW; REAL_OF_NUM_POW];
    EXISTS_TAC `&(2 EXP (num_of_int (d - &1))):int` THEN
    REWRITE_TAC[INT_OF_NUM_LE] THEN
    REWRITE_TAC[ARITH_RULE `1 <= m <=> ~(m = 0)`; EXP_EQ_0] THEN ARITH_TAC]);;

(* even <= odd => even <= odd - 1 (over Z): 2B <= 2Q+1 ==> 2B <= 2Q.         *)
let PARITY_HALF_LE = prove
 (`!B Q:int. &2 * B <= &2 * Q + &1 ==> &2 * B <= &2 * Q`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `B <= Q:int` (fun th -> MP_TAC th THEN INT_ARITH_TAC) THEN
  SUBGOAL_THEN `B < Q + &1:int` (fun th -> MP_TAC th THEN INT_ARITH_TAC) THEN
  ONCE_REWRITE_TAC[GSYM(SPECL [`B:int`; `Q + &1:int`;
    `&2:int`] INT_LT_LMUL_EQ)] THEN
  ASM_INT_ARITH_TAC);;

(* Product form of the halving: 2 zpow d (d>=1) = real_of_int(&2 * M'),      *)
(* M'>=1.                                                                    *)
let ZPOW_POS_EVEN_INT2 = prove
 (`!d:int. &1 <= d ==> ?M':int. &2 zpow d = real_of_int (&2 * M') /\ &1 <= M'`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `d:int` ZPOW_POS_EVEN_INT) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `M:int`
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN
      `M':int` STRIP_ASSUME_TAC))) THEN
  EXISTS_TAC `M':int` THEN ASM_REWRITE_TAC[] THEN
  UNDISCH_TAC `&2 zpow d = real_of_int M` THEN ASM_REWRITE_TAC[]);;

(* even <= odd => even <= odd-1, in the c*(2M') product form (PARITY_HALF_LE *)
(* with B = c*M', pushed through INT_RING).                                  *)
let ODD_PROD_HALF_LE = prove
 (`!c M' Q:int. c * (&2 * M') <= &2 * Q + &1 ==> c * (&2 * M') <= &2 * Q`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `!X:int. c * (&2 * M') <= X <=> &2 * (c * M') <= X`
    (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
     CONV_TAC INT_RING; ALL_TAC] THEN
  REWRITE_TAC[PARITY_HALF_LE]);;

let DYHO_HALVES = prove
 (`!k n. dyho k n = dyho (k - &1) (&2 * n) UNION dyho (k - &1) (&2 * n + &1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_UNION; dyho; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real` THEN
  SUBGOAL_THEN `&0 < &2 zpow (k - &1)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[ROI_MUL; ROI_ADD; ROI_1; ROI_2] THEN
  MP_TAC(SPEC `k:int` ZPOWK_HALF) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REAL_ARITH_TAC);;

(* Exponent-monotonicity for base 2:  p <= q ==> 2^p <= 2^q.                 *)
let ZPOW2_MONOE = prove
 (`!p q:int. p <= q ==> &2 zpow p <= &2 zpow q`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&2 zpow q = &2 zpow p * &2 zpow (q - p)` SUBST1_TAC THENL
   [SUBGOAL_THEN
     `q:int = p + (q - p)` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
     [th]) THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
       SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`]; ALL_TAC] THEN
  MP_TAC(SPEC `q - p:int` DYADIC_SCALE_INT) THEN ANTS_TAC THENL
    [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:int` STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN
  GEN_REWRITE_TAC LAND_CONV [GSYM REAL_MUL_RID] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
     REAL_ARITH_TAC;
    UNDISCH_TAC `&1 <= u:int` THEN REWRITE_TAC[int_le] THEN
      REWRITE_TAC[REAL_OF_INT_CLAUSES]]);;

(* Strict version: 2 zpow is strictly increasing in the exponent.            *)
let ZPOW2_MONOE_LT = prove
 (`!k1 k2:int. k1 < k2 ==> &2 zpow k1 < &2 zpow k2`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `&2 zpow (k1 + &1)` THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN `&2 zpow (k1 + &1) = &2 zpow k1 * &2` SUBST1_TAC THENL
     [SIMP_TAC[REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ; REAL_ZPOW_1];
       ALL_TAC] THEN
    SUBGOAL_THEN `&0 < &2 zpow k1` MP_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
       REAL_ARITH_TAC;
    MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC]);;

(* Strict-monotonicity contrapositive: 2^a0 < 2^kk forces a0 <= kk           *)
(* (integers).                                                               *)
let ZPOW2_LT_IMP_LE = prove
 (`!a0 kk:int. &2 zpow a0 < &2 zpow kk ==> a0 <= kk`,
  REPEAT STRIP_TAC THEN
  GEN_REWRITE_TAC I [GSYM INT_NOT_LT] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`kk:int`; `a0:int`] ZPOW2_MONOE_LT) THEN
  ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC);;

(* Non-strict reverse monotonicity: 2^x <= 2^y => x <= y (integers).         *)
let ZPOW2_LE_REV = prove
 (`!x y:int. &2 zpow x <= &2 zpow y ==> x <= y`,
  REPEAT STRIP_TAC THEN GEN_REWRITE_TAC I [GSYM INT_NOT_LT] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`y:int`; `x:int`] ZPOW2_MONOE_LT) THEN ASM_REWRITE_TAC[] THEN
  ASM_REAL_ARITH_TAC);;

(* Strict reverse monotonicity: 2^a < 2^b => a < b (integers).               *)
(* (Contrapositive of                                                        *)
(* ZPOW2_MONOE: b <= a => 2^b <= 2^a.)  Needed for the alpha1 W1 level bound *)
(* mu K > mu I_tau (2^{-kt} < 2^{FST ap}) => -kt < FST ap => -kt + 1 <= FST  *)
(* ap.                                                                       *)
let ZPOW2_LT_REV = prove
 (`!a b:int. &2 zpow a < &2 zpow b ==> a < b`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(b <= a:int)` MP_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(ISPECL [`b:int`; `a:int`] ZPOW2_MONOE) THEN ASM_REWRITE_TAC[] THEN
    ASM_REAL_ARITH_TAC;
    INT_ARITH_TAC]);;

(* Containment forces the scale ordering: dyho a m SUBSET dyho b p ==> a <=  *)
(* b                                                                         *)
(* (the contained interval is the shorter one).  Proof: if b < a, the left   *)
(* endpoint and midpoint of dyho a m are at distance 2^(a-1) >= 2^b = the    *)
(* full                                                                      *)
(* width of dyho b p, so they cannot both lie in dyho b p.                   *)
let DYHO_SUBSET_SCALE = prove
 (`!a m b p. dyho a m SUBSET dyho b p ==> a <= b`,
  REPEAT GEN_TAC THEN REWRITE_TAC[GSYM INT_NOT_LT] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow a` ASSUME_TAC THENL
    [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow b <= &2 zpow (a - &1)` ASSUME_TAC THENL
   [MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow a = &2 * &2 zpow (a - &1)` ASSUME_TAC THENL
   [SUBGOAL_THEN
     `a:int = (a - &1) + &1` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
     [th]) THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`; REAL_ZPOW_1] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(fun th ->
    let th' = REWRITE_RULE[SUBSET; dyho; IN_ELIM_THM] th in
    MP_TAC(SPEC `real_of_int m * &2 zpow a` th') THEN
    MP_TAC(SPEC `(real_of_int m + &1 / &2) * &2 zpow a` th')) THEN
  ASM_REAL_ARITH_TAC);;

(* PARENT-CELL NESTING: a dyadic cell dyho a p sits inside its parent at the *)
(* next                                                                      *)
(* coarser scale a+1, whose index is the integer floor p div 2 (a cell [p    *)
(* 2^a,                                                                      *)
(* (p+1)2^a) with p = 2q+r, r in {0,1}, lies in [q 2^{a+1}, (q+1)2^{a+1})).  *)
(* The                                                                       *)
(* step that grows a cell toward the maximal cover Cal K one level at a      *)
(* time.                                                                     *)
let DYHO_PARENT = prove
 (`!a p:int. dyho a p SUBSET dyho (a + &1) (p div &2)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; SUBSET; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real` THEN
  SUBGOAL_THEN
    `&0 < &2 zpow a /\ &2 zpow (a + &1) =
     &2 * &2 zpow a` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
      SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
      REWRITE_TAC[REAL_ZPOW_1] THEN REAL_ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
    `real_of_int p = &2 * real_of_int (p div &2) + real_of_int(p rem &2) /\
                &0 <= real_of_int(p rem &2) /\ real_of_int(p rem &2) <= &1`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`p:int`; `&2:int`] INT_DIVISION) THEN
    ANTS_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
    STRIP_TAC THEN REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES] THEN
    REPEAT CONJ_TAC THEN REWRITE_TAC[REAL_OF_INT_CLAUSES] THEN
      ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_of_int (p div &2) * &2 zpow (a + &1) =
    real_of_int p * &2 zpow a - real_of_int(p rem &2) * &2 zpow a /\
    (real_of_int (p div &2) + &1) * &2 zpow (a + &1) =
    real_of_int p * &2 zpow a + (&2 - real_of_int(p rem &2)) * &2 zpow a`
    (CONJUNCTS_THEN SUBST1_TAC) THENL
   [CONJ_TAC THEN
    MAP_EVERY UNDISCH_TAC
     [`real_of_int p = &2 * real_of_int (p div &2) + real_of_int(p rem &2)`;
      `&2 zpow (a + &1) = &2 * &2 zpow a`] THEN
    CONV_TAC REAL_RING; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= real_of_int(p rem &2) * &2 zpow a /\
                &2 zpow a <= (&2 - real_of_int(p rem &2)) * &2 zpow a`
                  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE];
      GEN_REWRITE_TAC LAND_CONV [GSYM REAL_MUL_LID] THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
        ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  FIRST_X_ASSUM(K ALL_TAC o check (fun th ->
    free_in `(p:int) div &2` (concl th)) o SPEC_ALL) THEN
  SUBGOAL_THEN
    `(real_of_int p + &1) * &2 zpow a = real_of_int p * &2 zpow a + &2 zpow a`
    ASSUME_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  STRIP_TAC THEN CONJ_TAC THEN ASM_REAL_ARITH_TAC);;

(* SUB-CELL ENUMERATION (286Gf): a finer cell dyho a p (a <= b, so length    *)
(* 2 zpow a <= 2 zpow b) sits inside the coarser dyho b n exactly when its   *)
(* index                                                                     *)
(* p lands in the block [n*M, n*M + M) of the M = 2 zpow (b - a) sub-cells   *)
(* of                                                                        *)
(* dyho b n. Forward: the left endpoint p * 2 zpow a of dyho a p lies in     *)
(* dyho                                                                      *)
(* b n, giving both integer bounds (upper via int discreteness).  Backward:  *)
(* interval nesting.  This is the workhorse for enumerating the same-scale   *)
(* sub-tiles sigma <= tau of a coarse spatial cell I_tau.                    *)
let DYHO_SUBCELL_IFF = prove
 (`!a b M n p. a <= b /\ &2 zpow (b - a) = real_of_int M
     ==> (dyho a p SUBSET dyho b n <=> n * M <= p /\ p < n * M + M)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow a` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow b = real_of_int M * &2 zpow a` ASSUME_TAC THENL
   [FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN
    SUBGOAL_THEN
      `b:int = (b - a) + a` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
      [th]) THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_ZPOW_ADD THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[dyho; SUBSET; IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `tt = &2 zpow a` THEN
  SUBGOAL_THEN
    `real_of_int n * real_of_int M * tt = real_of_int (n * M) * tt /\
     (real_of_int n + &1) * real_of_int M * tt =
       (real_of_int (n * M) + real_of_int M) * tt`
    STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[ROI_MUL] THEN CONJ_TAC THEN CONV_TAC REAL_RING; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN ABBREV_TAC `q = real_of_int (n * M)` THEN
  SUBGOAL_THEN `(n * M <= p <=> q <= real_of_int p) /\
                (p < n * M + M <=> real_of_int p < q + real_of_int M)`
    (fun th -> REWRITE_TAC[th]) THENL
   [EXPAND_TAC "q" THEN REWRITE_TAC[GSYM ROI_ADD] THEN
    REWRITE_TAC[int_le; int_lt]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `real_of_int p * tt`) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC REAL_LT_RMUL THEN ASM_REAL_ARITH_TAC;
      ASM_SIMP_TAC[REAL_LE_RMUL_EQ; REAL_LT_RMUL_EQ]];
    STRIP_TAC THEN
    SUBGOAL_THEN `real_of_int p + &1 <= q + real_of_int M` ASSUME_TAC THENL
     [MP_TAC(ASSUME `real_of_int p < q + real_of_int M`) THEN
       EXPAND_TAC "q" THEN
      REWRITE_TAC[GSYM ROI_1] THEN REWRITE_TAC[GSYM ROI_ADD] THEN
      REWRITE_TAC[GSYM int_lt; GSYM int_le] THEN INT_ARITH_TAC;
      ALL_TAC] THEN
    X_GEN_TAC `x:real` THEN STRIP_TAC THEN CONJ_TAC THENL
     [SUBGOAL_THEN `q * tt <= real_of_int p * tt` MP_TAC THENL
       [ASM_SIMP_TAC[REAL_LE_RMUL_EQ]; ASM_REAL_ARITH_TAC];
      SUBGOAL_THEN
        `(real_of_int p + &1) * tt <= (q + real_of_int M) * tt` MP_TAC THENL
       [ASM_SIMP_TAC[REAL_LE_RMUL_EQ]; ASM_REAL_ARITH_TAC]]]);;

(* M4: dyadic coarsening -- a length-2^a dyadic cell sits inside the coarser *)
(* length-2^b cell dyho b (p div 2^{b-a}) whenever a <= b.  Existence of the *)
(* containing length-2^m interval Jhat for J_tau = dyho k_tau n (take b=m,   *)
(* nhat = n div 2^{m-k_tau}, m >= k_tau). Via DYHO_SUBCELL_IFF +             *)
(* INT_DIVISION                                                              *)
(* (Euclidean bounds n*M <= p < n*M+M with n = p div M, M = 2^{b-a} > 0).    *)
let DYHO_COARSEN = prove
 (`!a b p:int. a <= b ==> dyho a p SUBSET dyho b (p div (&2 pow (num_of_int (b
   - a))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < (&2:int) pow (num_of_int (b - a))` ASSUME_TAC THENL
   [MATCH_MP_TAC INT_POW_LT THEN INT_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `M = (&2:int) pow (num_of_int (b - a))` THEN
  SUBGOAL_THEN `&2 zpow (b - a) = real_of_int M` ASSUME_TAC THENL
   [EXPAND_TAC "M" THEN
    SUBGOAL_THEN
      `b - a = &(num_of_int(b - a)):int` (fun th -> ONCE_REWRITE_TAC[th]) THENL
     [ASM_SIMP_TAC[INT_OF_NUM_OF_INT; INT_SUB_LE]; ALL_TAC] THEN
    REWRITE_TAC[REAL_ZPOW_NUM; int_pow_th; int_of_num_th; NUM_OF_INT_OF_NUM];
      ALL_TAC] THEN
  MP_TAC(ISPECL [`a:int`; `b:int`; `M:int`; `p div M`;
    `p:int`] DYHO_SUBCELL_IFF) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `~(M:int = &0)` ASSUME_TAC THENL
    [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `abs(M:int) = M` ASSUME_TAC THENL
    [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:int`; `M:int`] INT_DIVISION) THEN
  ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

(* M4 tree geometry: two dyadic cells that MEET, the first no coarser than   *)
(* the                                                                       *)
(* second (k <= k'), nest with the finer inside the coarser (shared point +  *)
(* DYHO_NEST).  Drives both (A-tree) containments (J_sigma SUBSET Jhat, Jhat *)
(* SUBSET J^r_sigma) from the shared J^r_tau.                                *)
let DYHO_MEET_NEST = prove
 (`!k k' n n':int.
     k <= k' /\ ~(DISJOINT (dyho k n) (dyho k' n'))
     ==> dyho k n SUBSET dyho k' n'`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[SET_RULE
   `~DISJOINT s t <=> ?x. x IN s /\ x IN t`]) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:real` STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC DYHO_NEST THEN EXISTS_TAC `x:real` THEN ASM_REWRITE_TAC[]);;

(* The k-scale index span [p*M, p*M+M) of a cell dyho a p (M = 2^{a+k}),     *)
(* viewed                                                                    *)
(* at tile-scale --k, is exactly dyho a p as a point set: q*2^{-k} = p*2^a   *)
(* and                                                                       *)
(* (q+M)*2^{-k} = (p+1)*2^a. This makes CARLESON_ALPHA_SCALE's k-span domain *)
(* condition definitional for a cover cell (Sc SUBSET dyho a p by            *)
(* construction).                                                            *)
let DYHO_SPAN_INTERVAL = prove
 (`!a p k M. &2 zpow (a + k) = real_of_int M
     ==> {x | real_of_int (p * M) * &2 zpow (--k) <= x /\
              x < real_of_int (p * M + M) * &2 zpow (--k)} = dyho a p`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[dyho; EXTENSION; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real` THEN
  SUBGOAL_THEN
    `real_of_int (p * M) * &2 zpow (--k) = real_of_int p * &2 zpow a /\
                real_of_int (p * M + M) * &2 zpow (--k) =
                (real_of_int p + &1) * &2 zpow a`
    (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN `&2 zpow (a + k) * &2 zpow (--k) = &2 zpow a` ASSUME_TAC THENL
   [SUBGOAL_THEN `~(&2 = &0)`
      (fun th -> REWRITE_TAC[GSYM(MATCH_MP REAL_ZPOW_ADD th)]) THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    AP_TERM_TAC THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[int_mul_th; int_add_th] THEN
  UNDISCH_TAC `&2 zpow (a + k) = real_of_int M` THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  UNDISCH_TAC `&2 zpow (a + k) * &2 zpow (--k) = &2 zpow a` THEN
  CONV_TAC REAL_RING);;

(* --- The tile set Q and its associated quantities (286E) ----------------  *)
(* A tile sigma = (I_sigma, J_sigma) with mu(I)*mu(J) = 1 is parametrised by *)
(* (k, nI, nJ) : int#int#int, with I_sigma = dyho(-k) nI of length 2^-k and  *)
(* J_sigma = dyho k nJ of length 2^k, so mu(I)*mu(J) = 1 holds by            *)
(* construction.                                                             *)
(* k_sigma = k;  x_sigma, y_sigma the midpoints;  J^l, J^r the halves of J.  *)

let tile_I = new_definition `tile_I (k:int,nI:int,nJ:int) = dyho (--k) nI`;;
let tile_J = new_definition `tile_J (k:int,nI:int,nJ:int) = dyho k nJ`;;
let tile_k = new_definition `tile_k (k:int,nI:int,nJ:int) = k`;;
let dyho_mid = new_definition
 `dyho_mid (k:int) (n:int) = (real_of_int n + &1 / &2) * &2 zpow k`;;
let tile_xmid = new_definition `tile_xmid (k:int,nI:int,nJ:int) = dyho_mid
  (--k) nI`;;
let tile_ymid = new_definition
  `tile_ymid (k:int,nI:int,nJ:int) = dyho_mid (k - &1) (&2 * nJ)`;;
let tile_Jl = new_definition `tile_Jl (k:int,nI:int,nJ:int) = dyho (k - &1) (&2
  * nJ)`;;
let tile_Jr = new_definition `tile_Jr (k:int,nI:int,nJ:int) = dyho (k - &1) (&2
  * nJ + &1)`;;

(* The right half J^r of J is a sub-cell of J (the odd child                 *)
(* dyho(k-1)(2nJ+1) of                                                       *)
(* dyho k nJ), hence tile_Jr s SUBSET tile_J s. Used so that h x IN J_s^r    *)
(* ==>                                                                       *)
(* h x IN J_s, letting the Sc = ... cap h^-1[J_s^r] domain satisfy           *)
(* CARLESON_ALPHA_                                                           *)
(* SCALE's Sc SUBSET {x | h x IN tile_J s}.                                  *)
let TILE_JR_SUBSET_J = prove
 (`!s:int#int#int. tile_Jr s SUBSET tile_J s`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_Jr; tile_J] THEN REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`p1 - &1:int`; `p1:int`; `&2:int`; `p2:int`;
    `&2 * p2 + &1:int`]
    DYHO_SUBCELL_IFF) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `p1 - (p1 - &1):int = &1` SUBST1_TAC THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_ZPOW_1] THEN REWRITE_TAC[int_of_num_th];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN INT_ARITH_TAC]);;

(* Positional identity for the sub-tile enumeration (286Gf). A cell dyho kp  *)
(* p                                                                         *)
(* whose index p = M * n + j (M = 2 zpow (k - kp), the sub-cell count) sits  *)
(* inside dyho k n; its midpoint measured from the parent left edge n * 2    *)
(* zpow k                                                                    *)
(* equals (j + 1/2) * 2 zpow kp. Proof: 2 zpow k = 2 zpow (k-kp) * 2 zpow    *)
(* kp,                                                                       *)
(* so M * n * 2 zpow kp = n * 2 zpow k cancels.                              *)
let DYHO_MID_OFFSET = prove
 (`!k kp M n j. &2 zpow (k - kp) = real_of_int M
     ==> dyho_mid kp (M * n + j) - real_of_int n * &2 zpow k =
         (real_of_int j + &1 / &2) * &2 zpow kp`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[dyho_mid] THEN
  REWRITE_TAC[int_add_th; int_mul_th; int_of_num_th] THEN
  SUBGOAL_THEN `&2 zpow k = &2 zpow (k - kp) * &2 zpow kp` SUBST1_TAC THENL
   [SUBGOAL_THEN
     `k:int = (k - kp) + kp` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
     [th]) THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_ZPOW_ADD THEN REAL_ARITH_TAC;
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC]);;

(* K-relative edge-distance (286L alpha0/alpha1 offset value). For a scale-k *)
(* tile                                                                      *)
(* centre dyho_mid(--k) p and a coarser cover-cell left edge mm * 2^b (b + k *)
(* >= 0,                                                                     *)
(* M = 2 zpow (b+k) the sub-cell count), the scaled distance to that edge is *)
(* a                                                                         *)
(* HALF-INTEGER: 2^k (dyho_mid(--k) p - mm 2^b) = real_of_int (p - mm M) +   *)
(* 1/2.                                                                      *)
(* So the offset of x_sigma past K's edge, in units of 2^{-k}, is the        *)
(* integer                                                                   *)
(* p - mm M plus 1/2 -- exactly the argument of w(n + 1/2) in the alpha-sum  *)
(* tail.                                                                     *)
(* (2^k 2^{--k} = 1 and 2^k 2^b = 2^{b+k} = M cancel; REAL_RING closes.)     *)
let TILE_DIST_TO_CELL = prove
 (`!k q M nI x.
     (q + M <= nI \/ nI <= q - &1) /\
     real_of_int q * &2 zpow (--k) <= x /\ x < real_of_int (q + M) * &2 zpow
       (--k)
     ==> (real_of_int (if q + M <= nI then nI - (q + M) else (q - &1) - nI) +
       &1 / &2)
         <= &2 zpow k * abs(x - dyho_mid (--k) nI)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow k * &2 zpow (--k) = &1` ASSUME_TAC THENL
   [SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
    SUBGOAL_THEN `(k:int) + --k = &0` SUBST1_TAC THENL
     [INT_ARITH_TAC; REWRITE_TAC[REAL_ZPOW_0]]; ALL_TAC] THEN
  REWRITE_TAC[dyho_mid] THEN
  SUBGOAL_THEN
    `&2 zpow k * abs(x - (real_of_int nI + &1 / &2) * &2 zpow (--k)) =
     abs(&2 zpow k * x - (real_of_int nI + &1 / &2))`
    SUBST1_TAC THENL
   [SUBGOAL_THEN
     `&2 zpow k * abs(x - (real_of_int nI + &1 / &2) * &2 zpow (--k)) =
                  abs(&2 zpow k * (x - (real_of_int nI + &1 / &2) * &2 zpow
                    (--k)))`
      SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_MUL] THEN
      SUBGOAL_THEN `abs(&2 zpow k) = &2 zpow k` SUBST1_TAC THENL
       [ASM_REAL_ARITH_TAC; REWRITE_TAC[]];
      AP_TERM_TAC THEN
      FIRST_X_ASSUM(fun th -> if concl th = `&2 zpow k * &2 zpow (--k) = &1`
                             then MP_TAC th else NO_TAC) THEN
                               CONV_TAC REAL_RING]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&2 zpow k * (real_of_int q * &2 zpow (--k)) = real_of_int q /\
     &2 zpow k * (real_of_int (q + M) * &2 zpow (--k)) = real_of_int (q + M)`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN
    FIRST_X_ASSUM(fun th -> if concl th = `&2 zpow k * &2 zpow (--k) = &1`
                            then MP_TAC th else NO_TAC) THEN
                              CONV_TAC REAL_RING; ALL_TAC] THEN
  SUBGOAL_THEN
    `real_of_int q <= &2 zpow k * x /\ &2 zpow k * x < real_of_int (q + M)`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [FIRST_X_ASSUM(SUBST1_TAC o SYM o
        check (fun th -> concl th = `&2 zpow k * (real_of_int q * &2 zpow
          (--k)) = real_of_int q`)) THEN
      ASM_SIMP_TAC[REAL_LE_LMUL_EQ];
      FIRST_X_ASSUM(SUBST1_TAC o SYM o
        check (fun th -> concl th = `&2 zpow k * (real_of_int (q + M) * &2 zpow
          (--k)) = real_of_int (q + M)`)) THEN
      ASM_SIMP_TAC[REAL_LT_LMUL_EQ]]; ALL_TAC] THEN
  REPEAT (FIRST_X_ASSUM(K ALL_TAC o check (fun th ->
     free_in `&2 zpow (--k)` (concl th)))) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[int_add_th; int_sub_th; int_of_num_th]) THEN
  COND_CASES_TAC THEN
  POP_ASSUM(MP_TAC o REWRITE_RULE[int_le; int_add_th; int_sub_th;
    int_of_num_th]) THEN
  REWRITE_TAC[int_add_th; int_sub_th; int_of_num_th] THEN
  ASM_REAL_ARITH_TAC);;

(* dyho_mid is INJECTIVE in the index at a fixed scale: (n + 1/2) 2^k =      *)
(* (m+1/2)                                                                   *)
(* 2^k forces n = m (cancel the positive 2^k, then the +1/2, then int_eq).   *)
(* Used                                                                      *)
(* to recover a tile's spatial index from its centre in the                  *)
(* tree-orthogonality.                                                       *)
let DYHO_MID_INJ = prove
 (`!k m n. dyho_mid k m = dyho_mid k n ==> m = n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho_mid] THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_EQ_MUL_RCANCEL; REAL_LT_IMP_NZ] THEN
  REWRITE_TAC[REAL_EQ_ADD_RCANCEL; GSYM int_eq]);;

(* Distinct same-scale dyadic centres are at least 2^k apart: their          *)
(* difference is                                                             *)
(* (real_of_int m - real_of_int n) 2^k with |m - n| >= 1 (distinct           *)
(* integers).                                                                *)
(* This is the delta = 2^k SEPARATION that feeds CARD_LE_1_SEPARATED for the *)
(* alpha0/alpha1 offset fibers (the tile centres of a tree at scale k are    *)
(* distinct                                                                  *)
(* -- TILE_TREE_SAMESCALE_XMID_INJ -- hence 2^{-k}-separated at scale -k).   *)
let tile_le = new_definition
 `tile_le s t <=> tile_I s SUBSET tile_I t /\ tile_J t SUBSET tile_J s`;;
let tile_ler = new_definition
 `tile_ler s t <=> tile_I s SUBSET tile_I t /\ tile_Jr t SUBSET tile_Jr s`;;
let TILE_LE_SCALE = prove
 (`!s t. tile_le s t ==> tile_k t <= tile_k s`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_le; tile_I; tile_J; tile_k] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN INT_ARITH_TAC);;

(* SUB-CELL INDEX (286Gf): if sigma = (k,nIs,nJs) <= tau = (kt,nIt,nJt) with *)
(* kt <= k, its spatial index nIs falls in the block [nIt*M, nIt*M + M) of   *)
(* the                                                                       *)
(* M = 2 zpow (k - kt) scale-k sub-cells of I_tau. Direct from               *)
(* DYHO_SUBCELL_IFF                                                          *)
(* on I_sigma = dyho(--k) nIs SUBSET dyho(--kt) nIt = I_tau.                 *)
let TILE_LE_SUBCELL_INDEX = prove
 (`!k kt nIs nJs nIt nJt M.
     tile_le (k,nIs,nJs) (kt,nIt,nJt) /\ kt <= k /\
     &2 zpow (k - kt) = real_of_int M
     ==> nIt * M <= nIs /\ nIs < nIt * M + M`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_le; tile_I] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`--k:int`; `--kt:int`; `M:int`; `nIt:int`;
    `nIs:int`] DYHO_SUBCELL_IFF) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_INT_ARITH_TAC;
      SUBGOAL_THEN `--kt - --k:int = k - kt` SUBST1_TAC THENL
       [INT_ARITH_TAC; ASM_REWRITE_TAC[]]];
    DISCH_THEN(fun th -> ASM_MESON_TAC[th])]);;

(* SUB-CELL EDGE DISTANCES (286Gf): for a scale-k sub-tile of I_tau at       *)
(* offset j                                                                  *)
(* (index nIt*M + j, M = 2 zpow (k - kt) sub-cells), the scaled distance of  *)
(* its                                                                       *)
(* centre x_sigma from the LEFT edge alpha = nIt * 2 zpow (--kt) of I_tau is *)
(* 2^k*(x_sigma - alpha) = j + 1/2, and from the RIGHT edge gamma = (nIt+1)  *)
(* *                                                                         *)
(* 2 zpow (--kt) is 2^k*(gamma - x_sigma) = (M-1-j) + 1/2. These are exactly *)
(* the                                                                       *)
(* arguments of CWTILE_TAIL_COMPLEMENT, mapping the per-tile tail onto the   *)
(* half-integer pair (j, M-1-j) of TWO_SIDED_TAIL_SUM. Proof:                *)
(* DYHO_MID_OFFSET                                                           *)
(* plus 2 zpow k * 2 zpow (--k) = 1 and 2 zpow (--kt) = M * 2 zpow (--k),    *)
(* REAL_                                                                     *)
(* RING closes both.                                                         *)
let TILE_SUBCELL_EDGE_DIST = prove
 (`!k kt M nIt j nJs.
     &2 zpow (k - kt) = real_of_int M
     ==> &2 zpow k *
         (tile_xmid (k, M * nIt + j, nJs) - real_of_int nIt * &2 zpow (--kt)) =
         real_of_int j + &1 / &2 /\
         &2 zpow k *
         ((real_of_int nIt + &1) * &2 zpow (--kt) - tile_xmid (k, M * nIt + j,
           nJs)) =
         (real_of_int M - real_of_int j - &1) + &1 / &2`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[tile_xmid] THEN
  SUBGOAL_THEN `&2 zpow k * &2 zpow (--k) = &1` ASSUME_TAC THENL
   [SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
    SUBGOAL_THEN `(k:int) + --k = &0` SUBST1_TAC THENL
     [INT_ARITH_TAC; REWRITE_TAC[REAL_ZPOW_0]];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `&2 zpow (--kt) = real_of_int M * &2 zpow (--k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th = `&2 zpow (k - kt) = real_of_int M`
     then SUBST1_TAC(SYM th) else NO_TAC) THEN
    SUBGOAL_THEN `(--kt):int = (k - kt) + (--k)` SUBST1_TAC THENL
     [INT_ARITH_TAC; SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`--kt:int`; `--k:int`; `M:int`; `nIt:int`;
    `j:int`] DYHO_MID_OFFSET) THEN
  REWRITE_TAC[INT_ARITH `--kt - --k:int = k - kt`] THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  CONJ_TAC THEN POP_ASSUM_LIST(fun ths -> MP_TAC(end_itlist CONJ ths)) THEN
  CONV_TAC REAL_RING);;

(* <= is reflexive; <=_r refines <= (sigma <=_r tau ==> sigma <= tau).       *)
let TILE_LE_REFL = prove
 (`!s. tile_le s s`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_le; SUBSET_REFL]);;

(* tile_le is TRANSITIVE (the chain/tree arguments of M3 rely on this).      *)
let TILE_LE_TRANS = prove
 (`!s t u. tile_le s t /\ tile_le t u ==> tile_le s u`,
  REWRITE_TAC[tile_le] THEN REPEAT STRIP_TAC THEN ASM SET_TAC[]);;

(* Dyadic ANCESTOR: for a <= b (with 2^{b-a} = M an integer), the cell dyho  *)
(* a p sits                                                                  *)
(* inside its scale-b ancestor dyho b (p div M). (DYHO_SUBCELL_IFF at n = p  *)
(* div M; the                                                                *)
(* index bounds (p div M) M <= p < (p div M) M + M are INT_DIVISION with M   *)
(* >= 1.) This                                                               *)
(* is the tool for constructing intermediate-scale intervals (286F(a-iv)).   *)
let DYHO_ANCESTOR = prove
 (`!a b M p:int. a <= b /\ &2 zpow (b - a) = real_of_int M
     ==> dyho a p SUBSET dyho b (p div M)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= M:int` ASSUME_TAC THENL
   [SUBGOAL_THEN `real_of_int (&1) <= real_of_int M` MP_TAC THENL
     [REWRITE_TAC[int_of_num_th] THEN
      UNDISCH_TAC `&2 zpow (b - a) = real_of_int M` THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN
      GEN_REWRITE_TAC LAND_CONV [GSYM(ISPEC `&2` REAL_ZPOW_0)] THEN
      MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC;
      REWRITE_TAC[GSYM int_le]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`a:int`; `b:int`; `M:int`; `p div M:int`;
    `p:int`] DYHO_SUBCELL_IFF) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`p:int`; `M:int`] INT_DIVISION) THEN
  ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  ASM_INT_ARITH_TAC);;

(* 286F(a-iv) TREE INTERPOLATION: if sig <= tau (my tile_le sig tau: I_sig   *)
(* SUBSET I_tau,                                                             *)
(* J_tau SUBSET J_sig) and k_tau <= k <= k_sig, there is an intermediate     *)
(* tile ups with                                                             *)
(* sig <= ups <= tau and k_ups = k. Witness ups = (k, nI_sig div Mi, nJ_tau  *)
(* div Mj):                                                                  *)
(* I_ups = the scale-2^{-k} ancestor of I_sig (DYHO_ANCESTOR, Mi =           *)
(* 2^{ksig-k}); J_ups =                                                      *)
(* the scale-2^k ancestor of J_tau (Mj = 2^{k-ktau}). The two "nest"         *)
(* containments                                                              *)
(* I_ups SUBSET I_tau, J_ups SUBSET J_sig follow from DYHO_NEST at the       *)
(* common point of                                                           *)
(* I_sig (resp J_tau). This is the key lemma for the G_K measure bound in    *)
(* alpha2/alpha3.                                                            *)
let TILE_INTERP = prove
 (`!sig tau k:int.
     tile_le sig tau /\ tile_k tau <= k /\ k <= tile_k sig
     ==> ?ups. tile_le sig ups /\ tile_le ups tau /\ tile_k ups = k`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
   [`ksig:int`; `nIsig:int`; `nJsig:int`; `ktau:int`; `nItau:int`; `nJtau:int`;
     `k:int`] THEN
  REWRITE_TAC[tile_le; tile_I; tile_J; tile_k] THEN STRIP_TAC THEN
  MP_TAC(ISPEC `ksig - k:int` DYADIC_SCALE_INT) THEN ANTS_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Mi:int` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPEC `k - ktau:int` DYADIC_SCALE_INT) THEN ANTS_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Mj:int` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `(k, nIsig div Mi, nJtau div Mj):int#int#int` THEN
  REWRITE_TAC[tile_I; tile_J; tile_k] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC DYHO_ANCESTOR THEN
    CONJ_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `--k - --ksig = ksig - k:int` SUBST1_TAC THENL
     [INT_ARITH_TAC; ASM_REWRITE_TAC[]];
    MATCH_MP_TAC DYHO_NEST THEN
    EXISTS_TAC `real_of_int nJtau * &2 zpow ktau` THEN
    CONJ_TAC THENL
     [ASM_INT_ARITH_TAC;
      CONJ_TAC THENL
       [MP_TAC(ISPECL [`ktau:int`; `k:int`; `Mj:int`;
         `nJtau:int`] DYHO_ANCESTOR) THEN
        ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
          REWRITE_TAC[DYHO_NONEMPTY];
        UNDISCH_TAC `dyho ktau nJtau SUBSET dyho ksig nJsig` THEN
        REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
          REWRITE_TAC[DYHO_NONEMPTY]]];
    MATCH_MP_TAC DYHO_NEST THEN
    EXISTS_TAC `real_of_int nIsig * &2 zpow (--ksig)` THEN
    CONJ_TAC THENL
     [ASM_INT_ARITH_TAC;
      CONJ_TAC THENL
       [MP_TAC(ISPECL [`--ksig:int`; `--k:int`; `Mi:int`;
         `nIsig:int`] DYHO_ANCESTOR) THEN
        ANTS_TAC THENL
         [CONJ_TAC THENL [ASM_INT_ARITH_TAC;
           SUBGOAL_THEN `--k - --ksig = ksig - k:int` SUBST1_TAC THENL
            [INT_ARITH_TAC; ASM_REWRITE_TAC[]]];
          ALL_TAC] THEN
        REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
          REWRITE_TAC[DYHO_NONEMPTY];
        UNDISCH_TAC `dyho (--ksig) nIsig SUBSET dyho (--ktau) nItau` THEN
        REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
          REWRITE_TAC[DYHO_NONEMPTY]]];
    MATCH_MP_TAC DYHO_ANCESTOR THEN
    ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC]);;

(* TREE J-ORTHOGONALITY (286L): two tiles s, t below a common tile u with    *)
(* the                                                                       *)
(* SAME scale k_s = k_t have the SAME frequency cell J_s = J_t. Both J_s,    *)
(* J_t                                                                       *)
(* contain J_u (from tile_le: J_u SUBSET J_s and J_u SUBSET J_t), and J_u is *)
(* nonempty; DYHO_NEST at the equal scale k_s nests J_s, J_t both ways       *)
(* (SUBSET_ANTISYM) using J_u's left endpoint as the common point. This is   *)
(* what                                                                      *)
(* collapses the tree Gram matrix onto the 286J diagonal (equal-J block).    *)
let TILE_TREE_SAMESCALE_J = prove
 (`!s t u. tile_le s u /\ tile_le t u /\ tile_k s = tile_k t
     ==> tile_J s = tile_J t`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
   [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`;
    `ku:int`;`nIu:int`;`nJu:int`] THEN
  REWRITE_TAC[tile_le; tile_k; tile_J; tile_I] THEN STRIP_TAC THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN
  FIRST_X_ASSUM SUBST_ALL_TAC THEN
  CONJ_TAC THEN MATCH_MP_TAC DYHO_NEST THEN
  EXISTS_TAC `real_of_int nJu * &2 zpow ku` THEN
  ASM_REWRITE_TAC[INT_LE_REFL] THEN
  CONJ_TAC THEN FIRST_X_ASSUM(MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  REWRITE_TAC[DYHO_NONEMPTY]);;

(* TREE same-scale CENTRE-injectivity: two tiles s, t below a common u with  *)
(* equal                                                                     *)
(* scale AND equal centre x_sigma are EQUAL. Same centre + DYHO_MID_INJ      *)
(* gives                                                                     *)
(* nI_s = nI_t; TILE_TREE_SAMESCALE_J then gives J_s = J_t hence nJ_s = nJ_t *)
(* (DYHO_SAMESCALE_EQ); with k_s = k_t the triples coincide. This is why     *)
(* distinct                                                                  *)
(* scale-k tiles of a tree have DISTINCT centres -- the injectivity that     *)
(* makes the                                                                 *)
(* alpha0/alpha1 offset map at most 2-to-1 (one tile per side of the cover   *)
(* cell).                                                                    *)
let TILE_TREE_SAMESCALE_XMID_INJ = prove
 (`!s t u. tile_le s u /\ tile_le t u /\ tile_k s = tile_k t /\ tile_xmid s =
   tile_xmid t
     ==> s = t`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
   [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`;
    `ku:int`;`nIu:int`;`nJu:int`] THEN
  REWRITE_TAC[tile_k; tile_xmid] THEN STRIP_TAC THEN
  UNDISCH_TAC `ks:int = kt` THEN DISCH_THEN SUBST_ALL_TAC THEN
  SUBGOAL_THEN `nIs:int = nIt` ASSUME_TAC THENL
   [MATCH_MP_TAC DYHO_MID_INJ THEN EXISTS_TAC `--kt:int` THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `nJs:int = nJt` ASSUME_TAC THENL
   [SUBGOAL_THEN `dyho kt nJs = dyho kt nJt` MP_TAC THENL
     [MP_TAC(ISPECL [`(kt,nIs,nJs):int#int#int`; `(kt,nIt,nJt):int#int#int`;
                     `(ku,nIu,nJu):int#int#int`] TILE_TREE_SAMESCALE_J) THEN
      REWRITE_TAC[tile_k; tile_J] THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
      DISCH_TAC THEN MATCH_MP_TAC DYHO_SAMESCALE_EQ THEN
        EXISTS_TAC `kt:int` THEN
      ASM_REWRITE_TAC[SUBSET_REFL]];
    ASM_REWRITE_TAC[PAIR_EQ]]);;

(* Corollary: on a scale-k tree, the SPATIAL INDEX nI determines the tile.   *)
(* Same                                                                      *)
(* nI (with same scale k, common upper bound u) => same centre x_sigma =>    *)
(* equal                                                                     *)
(* tile (TILE_TREE_SAMESCALE_XMID_INJ).                                      *)
let TILE_TREE_NI_INJ = prove
 (`!k nI nJs nJt u.
     tile_le (k,nI,nJs) u /\ tile_le (k,nI,nJt) u
     ==> (k,nI,nJs):int#int#int = (k,nI,nJt)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC TILE_TREE_SAMESCALE_XMID_INJ THEN
  EXISTS_TAC `u:int#int#int` THEN ASM_REWRITE_TAC[tile_k; tile_xmid]);;

(* Packaged for a tree SUBSET: if every tile of Pk has scale k and lies      *)
(* below u, then FST(SND .) = nI is INJECTIVE on Pk.                         *)
let TILE_TREE_FST_SND_INJ = prove
 (`!(Pk:(int#int#int)->bool) k u s t.
     (!r. r IN Pk ==> tile_k r = k /\ tile_le r u) /\
     s IN Pk /\ t IN Pk /\ FST(SND s) = FST(SND t)
     ==> s = t`,
  MAP_EVERY X_GEN_TAC [`Pk:(int#int#int)->bool`; `k:int`; `u:int#int#int`] THEN
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[FST; SND] THEN STRIP_TAC THEN
  SUBGOAL_THEN `tile_k (ks,nIs,nJs) = k /\ tile_le (ks,nIs,nJs) u /\
                tile_k (kt,nIt,nJt) = k /\ tile_le (kt,nIt,nJt) u`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[tile_k]) THEN
  UNDISCH_TAC `kt:int = k` THEN UNDISCH_TAC `ks:int = k` THEN
  DISCH_THEN SUBST_ALL_TAC THEN DISCH_THEN SUBST_ALL_TAC THEN
  UNDISCH_TAC `nIs:int = nIt` THEN DISCH_THEN SUBST_ALL_TAC THEN
  MATCH_MP_TAC TILE_TREE_NI_INJ THEN EXISTS_TAC `u:int#int#int` THEN
    ASM_REWRITE_TAC[]);;

(* 286L alpha0/alpha1 OFFSET-FIBER CARD <= 2. For a scale-k tree Pk and an   *)
(* integer                                                                   *)
(* reference index q (= mm * M, the cover cell K's left-edge index scaled to *)
(* level                                                                     *)
(* -k), the fiber {sigma in Pk : |nI_sigma - q| = n} has at most TWO tiles:  *)
(* nI is                                                                     *)
(* injective on Pk (TILE_TREE_FST_SND_INJ), and |nI - q| = n pins nI in      *)
(* {q-n, q+n},                                                               *)
(* a 2-element set. This is the <=2-to-1 property SUM_FIBER_COUNT_2 consumes *)
(* (the                                                                      *)
(* integer route: no separation/side split needed -- nI-injectivity + the    *)
(* two                                                                       *)
(* solutions of |nI - q| = n).                                               *)
let FIBER_CARD_LE_INJ_PREIMAGE_GUARD = prove
 (`!(A:B->bool) (key:B->C) (Q:C->bool) (h:C->num) (n:num).
     FINITE A /\ (!s t. s IN A /\ t IN A /\ key s = key t ==> s = t) /\
     (!s. s IN A ==> Q(key s)) /\
     CARD {c:C | Q c /\ h c = n} <= 2 /\ FINITE {c:C | Q c /\ h c = n}
     ==> CARD {s | s IN A /\ h(key s) = n} <= 2`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC LE_TRANS THEN
  EXISTS_TAC `CARD (IMAGE (key:B->C) {s:B | s IN A /\ (h:C->num)(key s) =
    (n:num)})` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC EQ_IMP_LE THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC CARD_IMAGE_INJ THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC FINITE_RESTRICT THEN ASM_REWRITE_TAC[]];
    MATCH_MP_TAC LE_TRANS THEN
    EXISTS_TAC `CARD {c:C | (Q:C->bool) c /\ (h:C->num) c = (n:num)}` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[SUBSET; IN_IMAGE; IN_ELIM_THM] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      ASM_REWRITE_TAC[]]]);;

(* 286L alpha0/alpha1 NEAREST-EDGE value-set count. The guarded value-set of *)
(* the                                                                       *)
(* nearest-edge offset -- indices nI OUTSIDE the cover cell's index-span [q, *)
(* q+M)                                                                      *)
(* (guard nI >= q+M \/ nI <= q-1) whose edge-distance num_of_int(if nI>=q+M  *)
(* then                                                                      *)
(* nI-(q+M) else (q-1)-nI) equals n -- has at most TWO elements {q+M+n,      *)
(* q-1-n}                                                                    *)
(* (one per side). Given &0 <= M. This is the CARD{c | Q c /\ h c = n} <= 2  *)
(* input                                                                     *)
(* to FIBER_CARD_LE_INJ_PREIMAGE_GUARD. ASM_CASES on the guard simplifies    *)
(* the                                                                       *)
(* if-then-else; each branch pins nI to q+M+&n resp. q-1-&n                  *)
(* (INT_OF_NUM_OF_INT on                                                     *)
(* the nonneg edge-distance).                                                *)
let EDGEOFF_VALSET_CARD = prove
 (`!q M n:num.
     &0 <= M
     ==> CARD {nI:int | (q + M <= nI \/ nI <= q - &1) /\
                    num_of_int(if q + M <= nI then nI - (q + M) else (q - &1) -
                      nI) = n} <= 2`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC LE_TRANS THEN
  EXISTS_TAC `CARD {(q + M) + &n:int, (q - &1) - &n}` THEN CONJ_TAC THENL
   [MATCH_MP_TAC CARD_SUBSET THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INSERT; NOT_IN_EMPTY] THEN
      X_GEN_TAC `nI:int` THEN
      ASM_CASES_TAC `q + M <= nI:int` THEN ASM_REWRITE_TAC[] THEN
        STRIP_TAC THENL
       [DISJ1_TAC THEN
        MP_TAC(ISPEC `nI - (q + M):int` INT_OF_NUM_OF_INT) THEN
        ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
        DISJ2_TAC THEN
        MP_TAC(ISPEC `(q - &1) - nI:int` INT_OF_NUM_OF_INT) THEN
        ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN INT_ARITH_TAC];
      REWRITE_TAC[FINITE_INSERT; FINITE_EMPTY]];
    SIMP_TAC[CARD_CLAUSES; FINITE_INSERT; FINITE_EMPTY] THEN ARITH_TAC]);;

(* Companion to EDGEOFF_VALSET_CARD: the guarded nearest-edge value-set is   *)
(* FINITE                                                                    *)
(* (it is a subset of the 2-element {q+M+n, q-1-n}). Both CARD<=2 and FINITE *)
(* are                                                                       *)
(* the two hypotheses FIBER_CARD_LE_INJ_PREIMAGE_GUARD needs on the          *)
(* value-set.                                                                *)
let EDGEOFF_VALSET_FINITE = prove
 (`!q M n:num.
     FINITE {nI:int | (q + M <= nI \/ nI <= q - &1) /\
                    num_of_int(if q + M <= nI then nI - (q + M) else (q - &1) -
                      nI) = n}`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `{(q + M) + &n:int, (q - &1) - &n}` THEN
  REWRITE_TAC[FINITE_INSERT; FINITE_EMPTY] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INSERT; NOT_IN_EMPTY] THEN
  X_GEN_TAC `c:int` THEN
  ASM_CASES_TAC `q + M <= c:int` THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [DISJ1_TAC THEN
    MP_TAC(ISPEC `c - (q + M):int` INT_OF_NUM_OF_INT) THEN
    ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    DISJ2_TAC THEN
    MP_TAC(ISPEC `(q - &1) - c:int` INT_OF_NUM_OF_INT) THEN
    ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC]);;

(* The concrete tile offset-fiber count: among the tiles of a same-scale     *)
(* tree A                                                                    *)
(* whose index nI lies OUTSIDE the cover cell's span [q,q+M), at most two    *)
(* share                                                                     *)
(* any given nearest-edge offset value n.  Composes the abstract fiber-count *)
(* engine (FIBER_CARD_LE_INJ_PREIMAGE_GUARD) with tree nI-injectivity        *)
(* (TILE_TREE_FST_SND_INJ) and the value-set count plus finiteness lemmas.   *)
(* This discharges the fiber hypothesis of ALPHA_SCALE_BOUND_ABSTRACT.       *)
let TILE_OFFSET_FIBER_CARD = prove
 (`!(A:(int#int#int)->bool) k u q M n.
     FINITE A /\ &0 <= M /\
     (!s. s IN A ==> tile_k s = k /\ tile_le s u) /\
     (!s. s IN A ==> (q + M <= FST(SND s) \/ FST(SND s) <= q - &1))
     ==> CARD {s | s IN A /\
               num_of_int(if q + M <= FST(SND s) then FST(SND s) - (q + M)
                          else (q - &1) - FST(SND s)) = n} <= 2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
   [`A:(int#int#int)->bool`;
    `\s:int#int#int. FST(SND s)`;
    `\c:int. q + M <= c \/ c <= q - &1`;
    `\c:int. num_of_int(if q + M <= c then c - (q + M) else (q - &1) - c)`;
    `n:num`] FIBER_CARD_LE_INJ_PREIMAGE_GUARD)) THEN
  DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN MATCH_MP_TAC TILE_TREE_FST_SND_INJ THEN
    MAP_EVERY EXISTS_TAC [`A:(int#int#int)->bool`; `k:int`;
      `u:int#int#int`] THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`q:int`; `M:int`; `n:num`] EDGEOFF_VALSET_CARD) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[EDGEOFF_VALSET_FINITE]]);;

(* Dyadic half-interval facts underlying the 286F-b refinement.              *)
(* J^r = dyho(k-1)(2n+1) is the RIGHT half of J = dyho k n, hence inside it. *)
let DYHO_JR_SUBSET_J = prove
 (`!k n. dyho (k - &1) (&2 * n + &1) SUBSET dyho k n`,
  REPEAT GEN_TAC THEN GEN_REWRITE_TAC (RAND_CONV) [DYHO_HALVES] THEN
  REWRITE_TAC[SUBSET_UNION]);;

(* Jr-nesting forces J-nesting: Jr t SUBSET Jr s ==> J t SUBSET J s. The     *)
(* left                                                                      *)
(* endpoint z of Jr t lies in Jr t (DYHO_NONEMPTY), hence in J t and (via Jr *)
(* s                                                                         *)
(* SUBSET J s) in J s; the shared point z + the scale ordering from          *)
(* DYHO_SUBSET_                                                              *)
(* SCALE feed DYHO_NEST to nest the full J's.                                *)
let DYHO_JR_NEST_J = prove
 (`!k n k' n'.
     dyho (k' - &1) (&2 * n' + &1) SUBSET dyho (k - &1) (&2 * n + &1)
     ==> dyho k' n' SUBSET dyho k n`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `z = real_of_int(&2 * n' + &1) * &2 zpow (k' - &1)` THEN
  SUBGOAL_THEN `(z:real) IN dyho (k' - &1) (&2 * n' + &1)` ASSUME_TAC THENL
   [EXPAND_TAC "z" THEN REWRITE_TAC[DYHO_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:real) IN dyho k' n'` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`k':int`;`n':int`] DYHO_JR_SUBSET_J) THEN
     ASM SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:real) IN dyho k n` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`k:int`;`n:int`] DYHO_JR_SUBSET_J) THEN
     ASM SET_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC DYHO_NEST THEN EXISTS_TAC `z:real` THEN ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN INT_ARITH_TAC);;

(* 286F-b: sigma <=_r tau ==> sigma <= tau. The I-parts coincide;            *)
(* DYHO_JR_NEST_J                                                            *)
(* upgrades the J^r-nesting to J-nesting.                                    *)
let TILE_LER_IMP_LE = prove
 (`!s t. tile_ler s t ==> tile_le s t`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_ler; tile_le; tile_I; tile_J; tile_Jr] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC DYHO_JR_NEST_J THEN ASM_REWRITE_TAC[]);;

let TILE_LER_REFL = prove
 (`!s. tile_ler s s`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_ler; SUBSET_REFL]);;

(* 286F-a-i for <=_r: sigma <=_r tau ==> k_tau <= k_sigma (via               *)
(* TILE_LER_IMP_LE).                                                         *)
let TILE_LER_SCALE = prove
 (`!s t. tile_ler s t ==> tile_k t <= tile_k s`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC TILE_LE_SCALE THEN
  MATCH_MP_TAC TILE_LER_IMP_LE THEN ASM_REWRITE_TAC[]);;

(* <=_r is TRANSITIVE (I-parts nest forward, J^r-parts nest backward, both   *)
(* by                                                                        *)
(* SUBSET transitivity).  Underlies the tile-tree monotonicity below and the *)
(* nested-tree bookkeeping in 286K.                                          *)
let cw = new_definition `cw (x:real) = &1 / (&1 + abs x) pow 3`;;

(* cw is continuous everywhere since the denominator (1+|x|)^3 is nonzero.  *)
let CW_CONTINUOUS = prove
 (`cw real_continuous_on (:real)`,
  SUBGOAL_THEN `cw = (\x. &1 / (&1 + abs x) pow 3)` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; cw]; ALL_TAC] THEN
  MP_TAC(BETA_RULE(ISPECL [`(\x:real. &1)`; `(\x:real. (&1 + abs x) pow 3)`;
    `(:real)`]
    REAL_CONTINUOUS_ON_DIV)) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[REAL_CONTINUOUS_ON_CONST] THEN CONJ_TAC THENL
     [MP_TAC(BETA_RULE(ISPECL [`(\x:real. &1 + abs x)`; `3`; `(:real)`]
        REAL_CONTINUOUS_ON_POW)) THEN DISCH_THEN MATCH_MP_TAC THEN
      MP_TAC(BETA_RULE(ISPECL [`(\x:real. &1)`; `(\x:real. abs x)`; `(:real)`]
        REAL_CONTINUOUS_ON_ADD)) THEN DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON_CONST] THEN
      MP_TAC(BETA_RULE(ISPECL [`(\x:real. x)`;
        `(:real)`] REAL_CONTINUOUS_ON_ABS)) THEN
      DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[REAL_CONTINUOUS_ON_ID];
      GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC REAL_POW_NZ THEN
      MP_TAC(ISPEC `x:real` REAL_ABS_POS) THEN REAL_ARITH_TAC];
    DISCH_THEN ACCEPT_TAC]);;

(* The affinely-shifted weight is continuous: x |-> w(a x + b) = w o         *)
(* (affine).                                                                 *)
let CW_SHIFT_CONTINUOUS = prove
 (`!a b. (\x. cw(a * x + b)) real_continuous_on (:real)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `(\x. cw(a * x + b)) = cw o (\x. a * x + b)` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [MP_TAC(BETA_RULE(ISPECL [`(\x:real. a * x)`; `(\x:real. b:real)`;
     `(:real)`]
      REAL_CONTINUOUS_ON_ADD)) THEN DISCH_THEN MATCH_MP_TAC THEN
    REWRITE_TAC[REAL_CONTINUOUS_ON_CONST] THEN
    MP_TAC(BETA_RULE(ISPECL [`(\x:real. x)`; `a:real`;
      `(:real)`] REAL_CONTINUOUS_ON_LMUL)) THEN
    REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON_ID];
    MATCH_MP_TAC REAL_CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real)` THEN
    REWRITE_TAC[CW_CONTINUOUS; SUBSET_UNIV]]);;

(* cw is even.                                                               *)
let CW_EVEN = prove
 (`!x. cw(--x) = cw x`,
  GEN_TAC THEN REWRITE_TAC[cw; REAL_ABS_NEG]);;

let CW_POS = prove
 (`!x. &0 < cw x`,
  GEN_TAC THEN REWRITE_TAC[cw] THEN MATCH_MP_TAC REAL_LT_DIV THEN
  CONJ_TAC THENL [REAL_ARITH_TAC; MATCH_MP_TAC REAL_POW_LT THEN
    REAL_ARITH_TAC]);;

let CW_LE_1 = prove
 (`!x. cw x <= &1`,
  GEN_TAC THEN REWRITE_TAC[cw] THEN
  SUBGOAL_THEN `&0 < (&1 + abs x) pow 3` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN REWRITE_TAC[REAL_MUL_LID] THEN
  GEN_REWRITE_TAC LAND_CONV [GSYM(REAL_ARITH `&1 pow 3 = &1`)] THEN
  MATCH_MP_TAC REAL_POW_LE2 THEN REAL_ARITH_TAC);;

(* The tile-localized weight w_sigma(x) = 2^k w(2^k (x - x_sigma)) (286E-c); *)
(* this is positive by construction.                                         *)
let cw_tile = new_definition
 `cw_tile (s:int#int#int) (x:real) =
    &2 zpow (tile_k s) * cw (&2 zpow (tile_k s) * (x - tile_xmid s))`;;

let CW_TILE_POS = prove
 (`!s x. &0 < cw_tile s x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cw_tile] THEN MATCH_MP_TAC REAL_LT_MUL THEN
  CONJ_TAC THENL [MATCH_MP_TAC REAL_ZPOW_LT THEN
    REAL_ARITH_TAC; REWRITE_TAC[CW_POS]]);;

(* Antiderivative / definite integral of the profile 1/(1+x)^3 (needed for   *)
(* the 286G weight estimates: normalization int w = 1, tails, and 286G-d).   *)
(* F(x) = -1/(2(1+x)^2) has F'(x) = 1/(1+x)^3 for x > -1.                    *)
let W_DERIV = prove
 (`!x. &0 < &1 + x
   ==> ((\x. --(&1 / (&2 * (&1 + x) pow 2))) has_real_derivative (&1 / (&1 + x)
     pow 3)) (atreal x)`,
  REPEAT STRIP_TAC THEN REAL_DIFF_TAC THEN
  SUBGOAL_THEN `~(&1 + x = &0)` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[REAL_POW_1] THEN
  POP_ASSUM MP_TAC THEN CONV_TAC REAL_FIELD);;

let W_INTEGRAL = prove
 (`!a b. -- &1 < a /\ a <= b
   ==> ((\x. &1 / (&1 + x) pow 3) has_real_integral
        (&1 / (&2 * (&1 + a) pow 2) - &1 / (&2 * (&1 + b) pow 2)))
          (real_interval[a,b])`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `&1 / (&2 * (&1 + a) pow 2) - &1 / (&2 * (&1 + b) pow 2) =
    (\x. --(&1 / (&2 * (&1 + x) pow 2))) b - (\x. --(&1 / (&2 * (&1 + x) pow
      2))) a`
   SUBST1_TAC THENL [REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_FUNDAMENTAL_THEOREM_OF_CALCULUS THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `x:real` THEN DISCH_TAC THEN
  MATCH_MP_TAC HAS_REAL_DERIVATIVE_ATREAL_WITHIN THEN MATCH_MP_TAC W_DERIV THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[IN_REAL_INTERVAL]) THEN
    ASM_REAL_ARITH_TAC);;

(* inv(1+x) -> 0 and hence the tail value 1/(2(1+b)^2) -> 0 at +infinity     *)
(* (the residual term in W_INTEGRAL as the upper limit goes to infinity).    *)
let INV_1PX_LIM = prove
 (`((\x. inv(&1 + x)) ---> &0) at_posinfinity`,
  REWRITE_TAC[REALLIM_AT_POSINFINITY] THEN X_GEN_TAC `e:real` THEN
    DISCH_TAC THEN
  EXISTS_TAC `&1 / e` THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[real_ge] THEN
    DISCH_TAC THEN
  SUBGOAL_THEN `&0 < &1 / e` ASSUME_TAC THENL
    [ASM_SIMP_TAC[REAL_LT_DIV; REAL_LT_01]; ALL_TAC] THEN
  ABBREV_TAC `d = &1 / e` THEN
  SUBGOAL_THEN `d < &1 + x` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &1 + x` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_SUB_RZERO] THEN
    ASM_SIMP_TAC[REAL_ABS_INV; REAL_ARITH `&0 < y ==> abs y = y`] THEN
  MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `inv(d:real)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LT_INV2 THEN ASM_REWRITE_TAC[];
    EXPAND_TAC "d" THEN ASM_SIMP_TAC[REAL_INV_DIV] THEN ASM_REAL_ARITH_TAC]);;

let TAIL_PW = prove
 (`!x. &0 <= x ==> abs(&1 / (&2 * (&1 + x) pow 2)) <= inv(&1 + x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &1 + x` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < (&1 + x) pow 2` ASSUME_TAC THENL
    [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 * (&1 + x) pow 2` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_ABS_DIV; REAL_ABS_NUM;
    REAL_ARITH `&0 < a ==> abs a = a`] THEN
  REWRITE_TAC[REAL_ARITH `&1 / y = inv y`] THEN
  MATCH_MP_TAC REAL_LE_INV2 THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[REAL_POW_2] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < a ==> (a <= &2 * a * a <=> &1 * a <= (&2 * a) *
    a)`] THEN
  MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REAL_ARITH_TAC);;

let TAILVAL_LIM = prove
 (`((\b. &1 / (&2 * (&1 + b) pow 2)) ---> &0) at_posinfinity`,
  MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN EXISTS_TAC `\x. inv(&1 + x)` THEN
  REWRITE_TAC[INV_1PX_LIM] THEN REWRITE_TAC[EVENTUALLY_AT_POSINFINITY] THEN
  EXISTS_TAC `&0` THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[real_ge] THEN
  DISCH_TAC THEN MATCH_MP_TAC TAIL_PW THEN ASM_REWRITE_TAC[]);;

(* A reusable real-level HALF-LINE integral criterion: f has integral l over *)
(* {x | a <= x} iff f is integrable on every [a,b] and the finite integrals  *)
(* converge to l as b -> +infinity.  Bridged from the vector                 *)
(* HAS_INTEGRAL_LIM_AT_POSINFINITY_GEN via the has_real_integral definition  *)
(* (IMAGE lift {x | a<=x} = {t | a<=drop t}, TENDSTO_REAL, REAL_INTEGRAL).   *)
let IMAGE_LIFT_GE = prove
 (`!a. IMAGE lift {x | a <= x} = {t:real^1 | a <= drop t}`,
  GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN GEN_TAC THEN
    EQ_TAC THENL
   [STRIP_TAC THEN ASM_REWRITE_TAC[LIFT_DROP];
    DISCH_TAC THEN EXISTS_TAC `drop x` THEN ASM_REWRITE_TAC[LIFT_DROP]]);;

let REAL_HALFLINE_INTEGRAL = prove
 (`!f a l. (f has_real_integral l) {x | a <= x} <=>
           (!b. f real_integrable_on real_interval[a,b]) /\
           ((\b. real_integral (real_interval[a,b]) f) ---> l) at_posinfinity`,
  REPEAT GEN_TAC THEN REWRITE_TAC[has_real_integral; IMAGE_LIFT_GE] THEN
  MP_TAC(ISPECL [`lift o f o drop`; `a:real`;
    `lift l`] HAS_INTEGRAL_LIM_AT_POSINFINITY_GEN) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL; GSYM REAL_INTEGRABLE_ON] THEN
  MATCH_MP_TAC(TAUT `(a ==> (b <=> b')) ==> (a /\ b <=> a /\ b')`) THEN
  DISCH_TAC THEN REWRITE_TAC[TENDSTO_REAL] THEN
  SUBGOAL_THEN
   `(\b. integral (IMAGE lift (real_interval [a,b])) (lift o f o drop)) =
    (lift o (\b. real_integral (real_interval [a,b]) f))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN X_GEN_TAC `b:real` THEN
    ASM_SIMP_TAC[REAL_INTEGRAL] THEN
      REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; LIFT_DROP]; REWRITE_TAC[]]);;

(* w on [0,b] (b>=0) equals the profile 1/(1+x)^3 (abs x = x there), so its  *)
(* integral is the W_INTEGRAL value.                                         *)
let CW_INTEGRAL_0B = prove
 (`!b. &0 <= b
   ==> (cw has_real_integral (&1 / (&2 * (&1 + &0) pow 2) - &1 / (&2 * (&1 + b)
     pow 2))) (real_interval[&0,b])`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE THEN
  EXISTS_TAC `\x. &1 / (&1 + x) pow 3` THEN EXISTS_TAC `{}:real->bool` THEN
  REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY; IN_DIFF; NOT_IN_EMPTY] THEN CONJ_TAC THENL
   [X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    REWRITE_TAC[cw] THEN AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      AP_TERM_TAC THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC W_INTEGRAL THEN ASM_REAL_ARITH_TAC]);;

let CW_TAIL_LIM = prove
 (`((\b. real_integral (real_interval[&0,b]) cw) ---> &1 / &2) at_posinfinity`,
  MATCH_MP_TAC REALLIM_TRANSFORM_EVENTUALLY THEN
  EXISTS_TAC `\b. &1 / &2 - &1 / (&2 * (&1 + b) pow 2)` THEN CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_AT_POSINFINITY] THEN EXISTS_TAC `&0` THEN
    X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN DISCH_TAC THEN
    MATCH_MP_TAC EQ_TRANS THEN
    EXISTS_TAC `&1 / (&2 * (&1 + &0) pow 2) - &1 / (&2 * (&1 + b) pow 2)` THEN
      CONJ_TAC THENL
     [CONV_TAC REAL_RAT_REDUCE_CONV;
      CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
        ASM_SIMP_TAC[CW_INTEGRAL_0B]];
    GEN_REWRITE_TAC (RATOR_CONV o RAND_CONV) [REAL_ARITH `&1 / &2 = &1 / &2 -
      &0`] THEN
    MATCH_MP_TAC REALLIM_SUB THEN REWRITE_TAC[REALLIM_CONST; TAILVAL_LIM]]);;

(* The right-hand half of the normalization:  int_{[0,inf)} w = 1/2.         *)
let CW_HALFLINE = prove
 (`(cw has_real_integral (&1 / &2)) {x | &0 <= x}`,
  REWRITE_TAC[REAL_HALFLINE_INTEGRAL; CW_TAIL_LIM] THEN
  X_GEN_TAC `b:real` THEN
  DISJ_CASES_TAC(REAL_ARITH `&0 <= b \/ b < &0`) THENL
   [MATCH_MP_TAC HAS_REAL_INTEGRAL_INTEGRABLE THEN
    EXISTS_TAC `&1 / (&2 * (&1 + &0) pow 2) - &1 / (&2 * (&1 + b) pow 2)` THEN
    ASM_SIMP_TAC[CW_INTEGRAL_0B];
    SUBGOAL_THEN `real_interval[&0,b] = {}` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_INTERVAL_EQ_EMPTY] THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_INTEGRABLE_ON_EMPTY]]]);;

(* ------------------------------------------------------------------------- *)
(* Weight-tail integrals from a base point c >= 0 (toward Fremlin 286Gf, the *)
(* "mass leaking outside I_tau" estimate).  cw = 1/(1+|x|)^3 = 1/(1+x)^3 on  *)
(* x >= 0, so the FTC value 1/(2(1+a)^2) - 1/(2(1+b)^2) (W_INTEGRAL)         *)
(* transfers.                                                                *)
(* ------------------------------------------------------------------------- *)

(* Finite [c,b] tail (c <= b, c >= 0).                                       *)
let CW_INTEGRAL_CB = prove
 (`!c b. &0 <= c /\ c <= b
   ==> (cw has_real_integral (&1 / (&2 * (&1 + c) pow 2) - &1 / (&2 * (&1 + b)
     pow 2)))
       (real_interval[c,b])`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC HAS_REAL_INTEGRAL_SPIKE THEN
  EXISTS_TAC `\x. &1 / (&1 + x) pow 3` THEN EXISTS_TAC `{}:real->bool` THEN
  REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY; IN_DIFF; NOT_IN_EMPTY] THEN CONJ_TAC THENL
   [X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    REWRITE_TAC[cw] THEN AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      AP_TERM_TAC THEN
    ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC W_INTEGRAL THEN ASM_REAL_ARITH_TAC]);;

(* The finite tail -> 1/(2(1+c)^2) as b -> +inf.                             *)
let CW_TAIL_LIM_C = prove
 (`!c. &0 <= c
     ==> ((\b. real_integral (real_interval[c,b]) cw) ---> &1 / (&2 * (&1 + c)
       pow 2))
         at_posinfinity`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REALLIM_TRANSFORM_EVENTUALLY THEN
  EXISTS_TAC `\b. &1 / (&2 * (&1 + c) pow 2) - &1 / (&2 * (&1 + b) pow 2)` THEN
    CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_AT_POSINFINITY] THEN EXISTS_TAC `c:real` THEN
    X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN DISCH_TAC THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
    MATCH_MP_TAC CW_INTEGRAL_CB THEN ASM_REWRITE_TAC[];
    GEN_REWRITE_TAC (RATOR_CONV o RAND_CONV)
      [REAL_ARITH `&1 / (&2 * (&1 + c) pow 2) = &1 / (&2 * (&1 + c) pow 2) -
        &0`] THEN
    MATCH_MP_TAC REALLIM_SUB THEN REWRITE_TAC[REALLIM_CONST; TAILVAL_LIM]]);;

(* The half-line tail value:  int_{x >= c} w = 1/(2(1+c)^2)  for c >= 0.     *)
(* (At c=0 this is CW_HALFLINE = 1/2.) The exact weight mass to the right of *)
(* c.                                                                        *)
let CW_TAIL_FROM_C = prove
 (`!c. &0 <= c ==> (cw has_real_integral (&1 / (&2 * (&1 + c) pow 2))) {x | c
   <= x}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_HALFLINE_INTEGRAL] THEN ASM_SIMP_TAC[CW_TAIL_LIM_C] THEN
  X_GEN_TAC `b:real` THEN
  DISJ_CASES_TAC(REAL_ARITH `c <= b \/ b < c`) THENL
   [MATCH_MP_TAC HAS_REAL_INTEGRAL_INTEGRABLE THEN
    EXISTS_TAC `&1 / (&2 * (&1 + c) pow 2) - &1 / (&2 * (&1 + b) pow 2)` THEN
    ASM_SIMP_TAC[CW_INTEGRAL_CB];
    SUBGOAL_THEN `real_interval[c,b] = {}` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_INTERVAL_EQ_EMPTY] THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_INTEGRABLE_ON_EMPTY]]]);;

(* ------------------------------------------------------------------------- *)
(* Change-of-variables for the scaled weight (the tile-weight is             *)
(* w_sigma(x) = 2^k cw(2^k(x - x_sigma)), an affine scaling of cw).  Reduces *)
(* int_{[a,b]} cw(m x + e) / int_{{x>=beta}} to cw over the m-scaled domain. *)
(* ------------------------------------------------------------------------- *)

(* Real affine change-of-variables over an ARBITRARY set (the library's      *)
(* HAS_REAL_INTEGRAL_AFFINITY is interval-only; the vector                   *)
(* HAS_INTEGRAL_AFFINITY                                                     *)
(* is general-set, so lift through the has_real_integral def). Lets the      *)
(* halfline                                                                  *)
(* tail transform without an (absent) limit-composition lemma.               *)
let HAS_REAL_INTEGRAL_AFFINITY_GEN = prove
 (`!f:real->real i s m c.
        (f has_real_integral i) s /\ ~(m = &0)
        ==> ((\x. f(m * x + c)) has_real_integral (inv(abs(m)) * i))
            (IMAGE (\x. inv m * (x - c)) s)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[has_real_integral] THEN
  DISCH_THEN(MP_TAC o SPEC `lift c` o MATCH_MP HAS_INTEGRAL_AFFINITY) THEN
  REWRITE_TAC[DIMINDEX_1; REAL_POW_1] THEN
  REWRITE_TAC[o_DEF; DROP_ADD; DROP_CMUL; LIFT_DROP; LIFT_CMUL] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
  REWRITE_TAC[GSYM IMAGE_o; o_DEF] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM; LIFT_CMUL; LIFT_SUB] THEN VECTOR_ARITH_TAC);;

(* The affine map x |-> inv m (x - e) sends the halfline {x | c <= x} onto   *)
(* {x | inv m (c - e) <= x} (m>0).                                           *)
let IMAGE_AFFINE_HALFLINE_CW = prove
 (`!m e c. &0 < m
     ==> IMAGE (\x. inv m * (x - e)) {x | c <= x} = {x | inv m * (c - e) <=
       x}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN
  X_GEN_TAC `y:real` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN
     `x:real` (CONJUNCTS_THEN2 SUBST1_TAC ASSUME_TAC)) THEN
    ONCE_REWRITE_TAC[GSYM(MATCH_MP REAL_LE_LMUL_EQ (ASSUME `&0 < m`))] THEN
    ASM_SIMP_TAC[REAL_FIELD `&0 < m ==> m * inv m * (z - e) = z - e`] THEN
    ASM_REAL_ARITH_TAC;
    DISCH_TAC THEN EXISTS_TAC `m * y + e:real` THEN CONJ_TAC THENL
     [ASM_SIMP_TAC[REAL_FIELD `&0 < m ==> inv m * ((m * y + e) - e) = y`];
      SUBGOAL_THEN `m * (inv m * (c - e)) <= m * y` MP_TAC THENL
       [ASM_SIMP_TAC[REAL_LE_LMUL_EQ];
        ASM_SIMP_TAC[REAL_FIELD `&0 < m ==> m * (inv m * (c - e)) = c - e`]
          THEN
        REAL_ARITH_TAC]]]);;

(* The affine map x |-> inv m (x - e) sends [m a + e, m b + e] onto [a,b]    *)
(* (m>0).                                                                    *)
let CWTILE_TAIL_RIGHT = prove
 (`!(s:int#int#int) beta. tile_xmid s <= beta
     ==> (cw_tile s has_real_integral
          (&1 / (&2 * (&1 + &2 zpow (tile_k s) * (beta - tile_xmid s)) pow 2)))
         {x | beta <= x}`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `m = &2 zpow (tile_k s)` THEN
  SUBGOAL_THEN `&0 < m` ASSUME_TAC THENL
   [EXPAND_TAC "m" THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPEC `m * (beta - tile_xmid s)` CW_TAIL_FROM_C) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
     ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`m:real`; `--(m * tile_xmid s)`] o
    MATCH_MP (REWRITE_RULE[IMP_CONJ] HAS_REAL_INTEGRAL_AFFINITY_GEN)) THEN
  ASM_SIMP_TAC[REAL_LT_IMP_NZ; IMAGE_AFFINE_HALFLINE_CW] THEN
  SUBGOAL_THEN
    `inv m * (m * (beta - tile_xmid s) - --(m * tile_xmid s)) = beta`
    SUBST1_TAC THENL
   [ASM_SIMP_TAC[REAL_FIELD `&0 < m ==> inv m * (m * (beta - tile_xmid s) -
                             --(m * tile_xmid s)) = beta`]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `m:real` o MATCH_MP HAS_REAL_INTEGRAL_LMUL) THEN
  SUBGOAL_THEN
    `(\x. m * cw(m * x + --(m * tile_xmid s))) = cw_tile s` ASSUME_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; cw_tile] THEN GEN_TAC THEN ASM_REWRITE_TAC[] THEN
    AP_TERM_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `abs m = m` SUBST1_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_FIELD `&0 < m ==> m * inv m * x = x`]);;

(* The tile weight is symmetric about its centre x_sigma (cw is even):       *)
(*   w_sigma(2 x_sigma - x) = w_sigma(x).                                    *)
(* Gives the LEFT tail from the right one by the reflection x |-> 2 x_sigma  *)
(* - x.                                                                      *)
let CWTILE_REFLECT = prove
 (`!(s:int#int#int) x. cw_tile s (&2 * tile_xmid s - x) = cw_tile s x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cw_tile] THEN AP_TERM_TAC THEN
  GEN_REWRITE_TAC (LAND_CONV) [GSYM CW_EVEN] THEN AP_TERM_TAC THEN
    CONV_TAC REAL_RING);;

(* The tile weight's LEFT TAIL, by reflecting CWTILE_TAIL_RIGHT about        *)
(* x_sigma                                                                   *)
(* (affinity x |-> 2 x_sigma - x = -1 * x + 2 x_sigma,                       *)
(* CWTILE_REFLECT-invariant):                                                *)
(* int_{x <= alpha} w_sigma = 1 / (2 (1 + 2^k (x_sigma - alpha))^2)          *)
(* (alpha<=x_s).                                                             *)
let CWTILE_TAIL_LEFT = prove
 (`!(s:int#int#int) alpha. alpha <= tile_xmid s
     ==> (cw_tile s has_real_integral
          (&1 / (&2 * (&1 + &2 zpow (tile_k s) * (tile_xmid s - alpha)) pow
            2)))
         {x | x <= alpha}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`s:int#int#int`;
    `&2 * tile_xmid s - alpha`] CWTILE_TAIL_RIGHT) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`-- &1:real`; `&2 * tile_xmid s`] o
    MATCH_MP (REWRITE_RULE[IMP_CONJ] HAS_REAL_INTEGRAL_AFFINITY_GEN)) THEN
  REWRITE_TAC[REAL_ARITH `~(-- &1 = &0)`; REAL_ABS_NEG; REAL_ABS_NUM;
    REAL_INV_1;
              REAL_MUL_LID] THEN
  SUBGOAL_THEN
   `IMAGE (\x. inv (-- &1) * (x - &2 * tile_xmid s)) {x | &2 * tile_xmid s -
     alpha <= x} =
    {x | x <= alpha}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM; REAL_INV_NEG;
     REAL_INV_1] THEN
    X_GEN_TAC `y:real` THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN
       `x:real` (CONJUNCTS_THEN2 SUBST1_TAC ASSUME_TAC)) THEN
      ASM_REAL_ARITH_TAC;
      DISCH_TAC THEN EXISTS_TAC `&2 * tile_xmid s - y:real` THEN
      CONJ_TAC THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(\x. cw_tile s (-- &1 * x + &2 * tile_xmid s)) = cw_tile s`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    GEN_REWRITE_TAC (RAND_CONV) [GSYM CWTILE_REFLECT] THEN AP_TERM_TAC THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
    `&2 * tile_xmid s - alpha - tile_xmid s =
     tile_xmid s - alpha` SUBST1_TAC THENL
   [REAL_ARITH_TAC; DISCH_THEN ACCEPT_TAC]);;

(* The tile weight's mass OUTSIDE an interval (alpha,gamma) containing       *)
(* x_sigma =                                                                 *)
(* left tail + right tail (the two disjoint halflines {x<=alpha},            *)
(* {gamma<=x}).                                                              *)
(*   int_{{x<=alpha} U {gamma<=x}} w_sigma                                   *)
(*     = 1/(2(1+2^k(x_s-alpha))^2) + 1/(2(1+2^k(gamma-x_s))^2).              *)
(* The complete per-tile 286Gf ingredient (mass leaking past both edges of   *)
(* I_tau).                                                                   *)
let CWTILE_TAIL_COMPLEMENT = prove
 (`!(s:int#int#int) alpha gamma.
     alpha <= tile_xmid s /\ tile_xmid s <= gamma /\ alpha < gamma
     ==> (cw_tile s has_real_integral
          (&1 / (&2 * (&1 + &2 zpow (tile_k s) * (tile_xmid s - alpha)) pow 2)
            +
           &1 / (&2 * (&1 + &2 zpow (tile_k s) * (gamma - tile_xmid s)) pow
             2)))
         ({x | x <= alpha} UNION {x | gamma <= x})`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC HAS_REAL_INTEGRAL_UNION THEN
  ASM_SIMP_TAC[CWTILE_TAIL_LEFT; CWTILE_TAIL_RIGHT] THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `{}:real->bool` THEN
  REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY; SUBSET; IN_INTER; IN_ELIM_THM;
    NOT_IN_EMPTY] THEN
  X_GEN_TAC `x:real` THEN STRIP_TAC THEN ASM_REAL_ARITH_TAC);;

(* w is even; the left half-line integral equals the right one (reflection), *)
(* and the two halves combine to the full-line NORMALIZATION int_R w = 1     *)
(* (Fremlin 286E-c-ii).                                                      *)
let IMAGE_NEG_LE0 = prove
 (`IMAGE (--) {x:real | x <= &0} = {x | &0 <= x}`,
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN GEN_TAC THEN EQ_TAC THENL
   [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    DISCH_TAC THEN EXISTS_TAC `--x:real` THEN REWRITE_TAC[REAL_NEG_NEG] THEN
      ASM_REAL_ARITH_TAC]);;

let CW_NEGHALF = prove
 (`(cw has_real_integral (&1 / &2)) {x | x <= &0}`,
  MP_TAC(ISPECL [`cw`; `&1 / &2`;
    `{x:real | x <= &0}`] HAS_REAL_INTEGRAL_REFLECT_GEN) THEN
  REWRITE_TAC[CW_EVEN; ETA_AX; IMAGE_NEG_LE0] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[CW_HALFLINE]);;

let CW_FULL = prove
 (`(cw has_real_integral (&1)) (:real)`,
  MP_TAC(ISPECL [`cw`; `&1 / &2`; `&1 / &2`; `{x:real | x <= &0}`;
    `{x:real | &0 <= x}`]
    HAS_REAL_INTEGRAL_UNION) THEN
  REWRITE_TAC[CW_NEGHALF; CW_HALFLINE] THEN ANTS_TAC THENL
   [SUBGOAL_THEN
     `{x:real | x <= &0} INTER {x | &0 <= x} = {&0}` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM; IN_SING] THEN GEN_TAC THEN
       REAL_ARITH_TAC;
      REWRITE_TAC[REAL_NEGLIGIBLE_SING]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `{x:real | x <= &0} UNION {x | &0 <= x} = (:real)` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM; IN_UNIV] THEN GEN_TAC THEN
     REAL_ARITH_TAC;
    CONV_TAC REAL_RAT_REDUCE_CONV]);;

(* Whole-line real affine change of variables (the UNIV analog of the        *)
(* library's                                                                 *)
(* HAS_REAL_INTEGRAL_AFFINITY, which is stated only over an interval).       *)
(* Reduces                                                                   *)
(* to the vector HAS_INTEGRAL_AFFINITY on lifted data; the affine image of   *)
(* the                                                                       *)
(* whole line is the whole line (AFFINE_IMAGE_UNIV).                         *)
let HAS_REAL_INTEGRAL_AFFINITY_UNIV = prove
 (`!(f:real->real) i m c. ~(m = &0) /\ (f has_real_integral i) (:real)
     ==> ((\x. f(m * x + c)) has_real_integral (inv(abs m) * i)) (:real)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[has_real_integral; IMAGE_LIFT_UNIV]) THEN
  DISCH_THEN(fun th ->
    MP_TAC(MATCH_MP (REWRITE_RULE[IMP_CONJ] HAS_INTEGRAL_AFFINITY) th)) THEN
  DISCH_THEN(MP_TAC o SPECL [`m:real`; `lift c`]) THEN
  ASM_REWRITE_TAC[DIMINDEX_1; REAL_POW_1] THEN
  ASM_SIMP_TAC[AFFINE_IMAGE_UNIV] THEN
  REWRITE_TAC[has_real_integral; IMAGE_LIFT_UNIV; LIFT_CMUL] THEN
  SUBGOAL_THEN `(\x. (lift o f o drop) (m % x + lift c)) =
                (lift o (\x. f (m * x + c)) o drop)` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; DROP_ADD; DROP_CMUL; LIFT_DROP];
     ALL_TAC] THEN
  REWRITE_TAC[]);;

(* 286G(a), tile form: INT_R cw_tile s = 1 (the tile weight is a probability *)
(* density: change of variables y = 2^k(x - x_sigma) from CW_FULL).          *)
let CW_TILE_FULL = prove
 (`!s:int#int#int. (cw_tile s has_real_integral (&1)) (:real)`,
  GEN_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `abs(&2 zpow (tile_k s)) = &2 zpow (tile_k s)` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[REAL_ABS_REFL] THEN
     ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `cw_tile s =
    (\x. &2 zpow (tile_k s) *
         cw (&2 zpow (tile_k s) * x + --(&2 zpow (tile_k s) * tile_xmid s)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[cw_tile; FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
     AP_TERM_TAC THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `&1 = &2 zpow (tile_k s) * inv(&2 zpow (tile_k s)) * &1` SUBST1_TAC THENL
   [UNDISCH_TAC `&0 < &2 zpow (tile_k s)` THEN
     CONV_TAC REAL_FIELD; ALL_TAC] THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_LMUL THEN
  MP_TAC(ISPECL [`cw`; `&1`; `&2 zpow (tile_k s)`;
    `--(&2 zpow (tile_k s) * tile_xmid s)`]
    HAS_REAL_INTEGRAL_AFFINITY_UNIV) THEN
  ASM_SIMP_TAC[CW_FULL; REAL_LT_IMP_NZ]);;

(* Fremlin 286G(a): sum_{n>=m} w(n + 1/2) <= 1/(2(1+m)^2). We prove the      *)
(* finite                                                                    *)
(* partial-sum form (uniform in n), which is the reusable content; the       *)
(* infinite                                                                  *)
(* sum follows by real_summable when a downstream bound needs it. The        *)
(* per-term                                                                  *)
(* estimate w(k+1/2) <= F(k) - F(k+1) (F(k) = 1/(2(1+k)^2)) is purely        *)
(* algebraic                                                                 *)
(* -- it reduces to the polynomial 16(1+t)^2(2+t)^2 <= (3+2t)^4 -- and       *)
(* telescopes.                                                               *)

let CW_POLY_BND = prove
 (`!t. &0 <= t ==> &16 * (&1 + t) pow 2 * (&2 + t) pow 2 <= (&3 + &2 * t) pow
   4`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(REAL_RING
    `(&3 + &2 * t) pow 4 =
     &16 * (&1 + t) pow 2 * (&2 + t) pow 2 + (&8 * (&1 + t) * (&2 + t) + &1)`)
       THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(REAL_ARITH `&0 <= e ==> x <= x + e`) THEN
  MATCH_MP_TAC REAL_LE_ADD THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_ARITH `&8 * a * b = &8 * (a * b)`] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC];
    REAL_ARITH_TAC]);;

let CW_TERM_BOUND = prove
 (`!t. &0 <= t
   ==> cw(t + &1 / &2) <= &1 / (&2 * (&1 + t) pow 2) - &1 / (&2 * (&1 + (t +
     &1)) pow 2)`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `&0 < &1 + t /\ &0 < &2 + t /\ &0 < &3 + &2 * t` STRIP_ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `cw(t + &1 / &2) = &8 / (&3 + &2 * t) pow 3` SUBST1_TAC THENL
   [REWRITE_TAC[cw] THEN
    SUBGOAL_THEN `abs(t + &1 / &2) = t + &1 / &2` SUBST1_TAC THENL
      [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(REAL_FIELD
      `&0 < &3 + &2 * t ==> &1 / (&1 + (t + &1 / &2)) pow 3 = &8 / (&3 + &2 *
        t) pow 3`) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `&1 / (&2 * (&1 + t) pow 2) - &1 / (&2 * (&1 + (t + &1)) pow 2) =
    (&3 + &2 * t) / (&2 * (&1 + t) pow 2 * (&2 + t) pow 2)` SUBST1_TAC THENL
   [MATCH_MP_TAC(REAL_FIELD
     `&0 < &1 + t /\ &0 < &2 + t
      ==> &1 / (&2 * (&1 + t) pow 2) - &1 / (&2 * (&1 + (t + &1)) pow 2) =
          (&3 + &2 * t) / (&2 * (&1 + t) pow 2 * (&2 + t) pow 2)`) THEN
            ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 < (&3 + &2 * t) pow 3 /\ &0 < &2 * (&1 + t) pow 2 * (&2 + t) pow 2`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN REPEAT(MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC) THEN
    TRY(MATCH_MP_TAC REAL_POW_LT) THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_DIV2_EQ; REAL_LE_LDIV_EQ; REAL_LE_RDIV_EQ] THEN
  SUBGOAL_THEN
   `(&3 + &2 * t) / (&2 * (&1 + t) pow 2 * (&2 + t) pow 2) * (&3 + &2 * t) pow
     3 =
    (&3 + &2 * t) pow 4 / (&2 * (&1 + t) pow 2 * (&2 + t) pow 2)` SUBST1_TAC
      THENL
   [CONV_TAC REAL_FIELD; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP CW_POLY_BND) THEN REAL_ARITH_TAC);;

(* Geometric-series atoms for the 286L outer summation (alpha0/alpha1 sum    *)
(* over                                                                      *)
(* scales k). The dyadic tail sum_{k>=L} 2^{-k} = 2*2^{-L} drives the        *)
(* convergence                                                               *)
(* after CARLESON_ALPHA_SCALE gives C1 2^{-k} energy mass per scale.         *)

(* Closed form for the finite dyadic GP:  sum_{n=0}^m (1/2)^n = 2 - (1/2)^m. *)
let GP_HALF_CLOSED = prove
 (`!m. sum (0..m) (\n. inv(&2) pow n) = &2 - inv(&2) pow m`,
  GEN_TAC THEN REWRITE_TAC[SUM_GP] THEN
  COND_CASES_TAC THENL [POP_ASSUM MP_TAC THEN ARITH_TAC; ALL_TAC] THEN
  COND_CASES_TAC THENL [POP_ASSUM MP_TAC THEN
    CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[real_pow; REAL_POW_ADD] THEN CONV_TAC REAL_FIELD);;

(* Any finite set of natural exponents: sum of (1/2)^n <= 2 (bounded by      *)
(* 0..max GP).                                                               *)
let SUM_HALF_POW_LE_2 = prove
 (`!(N:num->bool). FINITE N ==> sum N (\n. inv(&2) pow n) <= &2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\n:num. n`; `N:num->bool`] UPPER_BOUND_FINITE_SET) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `m:num`) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (0..m) (\n. inv(&2) pow n)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
    ASM_SIMP_TAC[FINITE_NUMSEG; SUBSET; IN_NUMSEG; LE_0] THEN
    REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_POW_LE THEN REAL_ARITH_TAC;
    REWRITE_TAC[GP_HALF_CLOSED] THEN
    MP_TAC(ISPECL [`inv(&2)`; `m:num`] REAL_POW_LE) THEN REAL_ARITH_TAC]);;

(* Scaled half-power GP: sum over any finite K of naturals of c(1/2)^k <= 2c *)
(* (c>=0).  = SUM_HALF_POW_LE_2 scaled by c.  In 286J part (d) this sums the *)
(* per-scale bounds gamma sum_{R_k} muI_tau <= 2^{11-k} muE = (2^11          *)
(* muE)(1/2)^k                                                               *)
(* over k to gamma sum_{R} muI_tau <= 2*(2^11 muE) = 2^12 muE = C5 muE.      *)
let SUM_HALF_POW_SCALED_LE = prove
 (`!(K:num->bool) c. FINITE K /\ &0 <= c
     ==> sum K (\k. c * inv(&2) pow k) <= &2 * c`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SUM_LMUL] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `&2 * c = c * &2`] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[SUM_HALF_POW_LE_2]);;

(* 286J part(b) geometric bound: sum_{k<K} 2^{-k-4} <= 1/8 (= half of the    *)
(* tail                                                                      *)
(* sum_{k>=0} 2^{-k-4} = 2^{-3}). Each annulus threshold in the R_k          *)
(* dichotomy is                                                              *)
(* 2^{-k-4} gam, and if all annulus terms are below threshold their sum is   *)
(* <gam/8.                                                                   *)
(* Summand 2^{-k-4} = (1/16) inv(2)^k [ZPOW_ADD split + ZPOW_NEG/NUM], then  *)
(* SUM_HALF_POW_LE_2 (sum inv(2)^k <= 2).                                    *)
let SUM_ZPOW_QUARTER = prove
 (`!K:num. sum {k | k < K} (\k. &2 zpow (--(&k) - &4)) <= &1 / &8`,
  GEN_TAC THEN
  SUBGOAL_THEN `!k:num. &2 zpow (--(&k) - &4) = (&1 / &16) * inv(&2) pow k`
    (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN
    SUBGOAL_THEN `--(&k) - &4 = (--(&k)) + (-- &4):int` SUBST1_TAC THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    SIMP_TAC[REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ] THEN
    REWRITE_TAC[REAL_ZPOW_NEG; REAL_ZPOW_NUM; GSYM REAL_POW_INV] THEN
    CONV_TAC REAL_FIELD; ALL_TAC] THEN
  REWRITE_TAC[SUM_LMUL] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(&1 / &16) * &2` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      MP_TAC(SPEC `{k:num | k < K}` SUM_HALF_POW_LE_2) THEN
      REWRITE_TAC[FINITE_NUMSEG_LT]];
    REAL_ARITH_TAC]);;

(* 286J part(b): cw(2^{k-1}) <= 2^{-3k+3} (Fremlin's                         *)
(* w(2^{k-1})=(1+2^{k-1})^{-3}                                               *)
(* <= 2^{-3(k-1)}). 1/(1+x)^3 <= 1/x^3 (x=2^{k-1}>0, REAL_LE_INV2+POW_LE2)   *)
(* then                                                                      *)
(* 1/(2^{k-1})^3 = 2^{-3k+3} (REAL_ZPOW_ZPOW).  Feeds the annulus threshold  *)
(* arithmetic cw(2^{k-1}) 2^{2k-7} <= 2^{-k-4} in the R_k dichotomy.         *)
let CW_IDIL_EDGE_POW_BOUND = prove
 (`!k:num. cw (&2 zpow (&k - &1)) <= &2 zpow (--(&3) * &k + &3)`,
  GEN_TAC THEN REWRITE_TAC[cw] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&1 / (&2 zpow (&k - &1)) pow 3` THEN CONJ_TAC THENL
   [SUBGOAL_THEN `&0 < &2 zpow (&k - &1)` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[real_div; REAL_MUL_LID] THEN MATCH_MP_TAC REAL_LE_INV2 THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_POW_LE2 THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LT_IMP_LE THEN ASM_REWRITE_TAC[];
        SUBGOAL_THEN
          `abs(&2 zpow (&k - &1)) = &2 zpow (&k - &1)` SUBST1_TAC THENL
         [ASM_REAL_ARITH_TAC; REAL_ARITH_TAC]]];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    REWRITE_TAC[GSYM REAL_ZPOW_POW; REAL_ZPOW_ZPOW] THEN
    REWRITE_TAC[real_div; REAL_MUL_LID; GSYM REAL_ZPOW_NEG] THEN
    AP_TERM_TAC THEN INT_ARITH_TAC]);;

(* 286J part(b): the annulus term is below its threshold when R_{k+1} would  *)
(* fail.                                                                     *)
(* If M = muJ_tau mu(S cap I^(k+1)) <= 2^{2k-7}gam, then cw(2^{k-1}) M <=    *)
(* 2^{-3k+3} 2^{2k-7} gam = 2^{-k-4} gam. REAL_LE_MUL2 (cw>=0,               *)
(* cw<=2^{-3k+3}) +                                                          *)
(* zpow exponent collapse.                                                   *)
let CWTILE_ANNULUS_TERM_BOUND = prove
 (`!k M gam. &0 <= M /\ &0 <= gam /\ M <= &2 zpow (&2 * &k - &7) * gam
     ==> cw (&2 zpow (&k - &1)) * M <= &2 zpow (--(&k) - &4) * gam`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 zpow (--(&3) * &k + &3) * (&2 zpow (&2 * &k - &7) * gam)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL2 THEN
    ASM_REWRITE_TAC[CW_IDIL_EDGE_POW_BOUND] THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN REWRITE_TAC[CW_POS];
    REWRITE_TAC[REAL_MUL_ASSOC] THEN
    SUBGOAL_THEN `&2 zpow (--(&3) * &k + &3) * &2 zpow (&2 * &k - &7) =
                  &2 zpow (--(&k) - &4)` SUBST1_TAC THENL
     [SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ] THEN
      AP_TERM_TAC THEN INT_ARITH_TAC;
      REWRITE_TAC[REAL_LE_REFL]]]);;

(* Pointwise reindex: for integers L <= k, inv(2^k) = inv(2^L) (1/2)^(k-L).  *)
let INV_ZPOW_REINDEX = prove
 (`!L k:int. L <= k
     ==> inv(&2 zpow k) = inv(&2 zpow L) * inv(&2) pow (num_of_int(k - L))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `n = num_of_int(k - L)` THEN
  SUBGOAL_THEN `k:int = L + &n` SUBST1_TAC THENL
   [EXPAND_TAC "n" THEN
    MP_TAC(ISPEC `k - L:int` INT_OF_NUM_OF_INT) THEN
    ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(&2 = &0)` ASSUME_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_ZPOW_ADD; REAL_ZPOW_NUM; REAL_INV_MUL;
    GSYM REAL_INV_POW]);;

(* THE dyadic geometric tail: a finite set SK of integer scales all >= L has *)
(* sum_{k in SK} inv(2^k) <= 2 inv(2^L). (Reindex each term via              *)
(* INV_ZPOW_REINDEX,                                                         *)
(* factor inv(2^L), then the residual sum of distinct (1/2)^(k-L) <= 2 via   *)
(* SUM_HALF_POW_LE_2 after SUM_IMAGE with num_of_int(.-L) injective on SK.)  *)
let SUM_INV_ZPOW_GE_LE = prove
 (`!(SK:int->bool) L. FINITE SK /\ (!k. k IN SK ==> L <= k)
     ==> sum SK (\k. inv(&2 zpow k)) <= &2 * inv(&2 zpow L)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `sum SK (\k. inv(&2 zpow k)) =
    inv(&2 zpow L) * sum SK (\k. inv(&2) pow (num_of_int(k - L)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM SUM_LMUL] THEN MATCH_MP_TAC SUM_EQ THEN
    X_GEN_TAC `k:int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC INV_ZPOW_REINDEX THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  GEN_REWRITE_TAC (RAND_CONV) [REAL_MUL_SYM] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `sum SK (\k. inv(&2) pow (num_of_int(k - L))) =
    sum (IMAGE (\k:int. num_of_int(k - L)) SK) (\n. inv(&2) pow n)`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN
    MP_TAC(ISPECL [`\k:int. num_of_int(k - L)`; `\n:num. inv(&2) pow n`;
      `SK:int->bool`]
      SUM_IMAGE) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[] THEN MAP_EVERY X_GEN_TAC [`a:int`; `b:int`] THEN
       STRIP_TAC THEN
      SUBGOAL_THEN `L <= a:int /\ L <= b:int` STRIP_ASSUME_TAC THENL
       [ASM_SIMP_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPEC `a - L:int` INT_OF_NUM_OF_INT) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      MP_TAC(ISPEC `b - L:int` INT_OF_NUM_OF_INT) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      REPEAT DISCH_TAC THEN
      SUBGOAL_THEN `a - L:int = b - L` MP_TAC THENL
       [FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC LAND_CONV [SYM th]) THEN
        FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC RAND_CONV [SYM th]) THEN
        ASM_REWRITE_TAC[];
        INT_ARITH_TAC];
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]];
    MATCH_MP_TAC SUM_HALF_POW_LE_2 THEN MATCH_MP_TAC FINITE_IMAGE THEN
      ASM_REWRITE_TAC[]]);;

(* Scaled dyadic geometric tail: sum over a finite set of scales k >= L of   *)
(* c/2^k <= 2c/2^L (c >= 0). = SUM_INV_ZPOW_GE_LE scaled by c. In 286K's H_j *)
(* estimate, c = C3^2 gam^2 C4 and L = k_(tau_j), giving H_j <= 2 C3^2 C4    *)
(* gam^2                                                                     *)
(* 2^(-k_tau_j) = 2 C3^2 C4 gam^2 muI_(tau_j).                               *)
let SUM_INV_ZPOW_GE_SCALED = prove
 (`!(SK:int->bool) L c. FINITE SK /\ &0 <= c /\ (!k. k IN SK ==> L <= k)
     ==> sum SK (\k. c * inv(&2 zpow k)) <= &2 * c * inv(&2 zpow L)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SUM_LMUL] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `&2 * c * x = c * (&2 * x)`] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC SUM_INV_ZPOW_GE_LE THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Two-sided dyadic geometric sum (286M part b tail): the level-sum          *)
(* sum_{n in NN} min(2^{k-n}, 2^{n-k}) that appears when 286M sums           *)
(* CARLESON_286L                                                             *)
(* over the iterated stopping-time decomposition. Fremlin bounds the ZZ-sum  *)
(* by                                                                        *)
(* 3; we bound the NN-sum by 4 (2 per half), which suffices for a valid C8.  *)
(* ------------------------------------------------------------------------- *)

(* One-sided halves: reindex the exponent to a plain (1/2)^j GP <= 2.        *)
let MINGEOM_UPPER = prove
 (`!(N:num->bool) k. FINITE N
     ==> sum {n | n IN N /\ k < n} (\n. inv(&2) pow (n - k)) <= &2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\n:num. n - (k:num)`;
    `\j:num. inv(&2) pow j`] SUM_IMAGE) THEN
  DISCH_THEN(MP_TAC o SPEC `{n:num | n IN N /\ k < n}`) THEN
  ANTS_TAC THENL
   [SIMP_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
     ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[o_DEF] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC SUM_HALF_POW_LE_2 THEN MATCH_MP_TAC FINITE_IMAGE THEN
  MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `N:num->bool` THEN
  ASM_REWRITE_TAC[] THEN SET_TAC[]);;

let MINGEOM_LOWER = prove
 (`!(N:num->bool) k. FINITE N
     ==> sum {n | n IN N /\ n <= k} (\n. inv(&2) pow (k - n)) <= &2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\n:num. (k:num) - n`;
    `\j:num. inv(&2) pow j`] SUM_IMAGE) THEN
  DISCH_THEN(MP_TAC o SPEC `{n:num | n IN N /\ n <= k}`) THEN
  ANTS_TAC THENL
   [SIMP_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
     ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[o_DEF] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC SUM_HALF_POW_LE_2 THEN MATCH_MP_TAC FINITE_IMAGE THEN
  MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `N:num->bool` THEN
  ASM_REWRITE_TAC[] THEN SET_TAC[]);;

(* Per-term power identities collapsing the min-branches to (1/2)^|k-n|.     *)
let MINGEOM_POW_LO = prove
 (`!k n:num. n <= k ==> inv(&2 pow k) * &2 pow n = inv(&2) pow (k - n)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[REAL_POW_SUB; REAL_ARITH `~(inv(&2) = &0)`] THEN
  REWRITE_TAC[REAL_INV_POW; real_div] THEN
  REWRITE_TAC[REAL_INV_INV] THEN CONV_TAC REAL_RING);;

let MINGEOM_POW_HI = prove
 (`!k n:num. k < n ==> &2 pow k * inv(&2) pow n = inv(&2) pow (n - k)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[REAL_POW_SUB; REAL_ARITH `~(inv(&2) = &0)`; LT_IMP_LE] THEN
  REWRITE_TAC[REAL_INV_POW; real_div] THEN
  REWRITE_TAC[REAL_INV_INV] THEN CONV_TAC REAL_RING);;

(* The two-sided min-geometric sum <= 4 over any finite set of level         *)
(* indices.                                                                  *)
let TWO_SIDED_MIN_GEOM = prove
 (`!(N:num->bool) k. FINITE N
     ==> sum N (\n. min (&2 pow k * inv(&2) pow n) (inv(&2 pow k) * &2 pow n))
       <= &4`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum N (\n. if n <= k then inv(&2) pow (k - n) else inv(&2) pow (n - k))`
     THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN X_GEN_TAC `n:num` THEN
    DISCH_TAC THEN COND_CASES_TAC THENL
     [ASM_SIMP_TAC[GSYM MINGEOM_POW_LO] THEN REAL_ARITH_TAC;
      FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[NOT_LE]) THEN DISCH_TAC THEN
      ASM_SIMP_TAC[GSYM MINGEOM_POW_HI] THEN REAL_ARITH_TAC];
    ASM_SIMP_TAC[SUM_CASES] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&2 + &2` THEN
    CONJ_TAC THENL [ALL_TAC; REAL_ARITH_TAC] THEN
    MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THENL
     [ASM_SIMP_TAC[MINGEOM_LOWER];
      SUBGOAL_THEN `{n | n IN N /\ ~(n <= k)} = {n:num | n IN N /\ k < n}`
       SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN
        MATCH_MP_TAC(TAUT `(b <=> c) ==> (a /\ b <=> a /\ c)`) THEN ARITH_TAC;
        ASM_SIMP_TAC[MINGEOM_UPPER]]]]);;

(* 286M part (b), per-level arithmetic bridge.  At stopping-time level n the *)
(* CARLESON_286M_LEVEL RHS is C7 energy(P_n) mass(P_n) sum_{R_n} muI; with   *)
(* the                                                                       *)
(* invariants energy(P_n) <= gam_n, mass(P_n) <= min(1, gam_n^2) and the     *)
(* budget                                                                    *)
(* gam_n^2 sum_{R_n} muI <= B (=C5+C6), this collapses to C7 B               *)
(* min(1/gam_n,gam_n).                                                       *)
(* At gam_n = 2^{k-n} that is C7 B min(2^{n-k},2^{k-n}), summable by         *)
(* TWO_SIDED_MIN_                                                            *)
(* GEOM. Abstract core (e=energy, m=mass, S=sum muI): e m S <= B min(inv     *)
(* gam,gam).                                                                 *)
(* Cases on inv gam <= gam (gam>=1, use m<=1) vs gam<inv gam (gam<1, use     *)
(* m<=gam^2);                                                                *)
(* each REAL_LE_TRANS through gam*(mbound)*(B inv gam^2) collapsed by        *)
(* REAL_FIELD.                                                               *)
let LEVEL_PROD_BOUND = prove
 (`!e m S gam B:real.
     &0 <= e /\ &0 <= m /\ &0 <= S /\ e <= gam /\ m <= &1 /\ m <= gam pow 2 /\
     &0 < gam /\ gam pow 2 * S <= B
     ==> e * m * S <= B * min (inv gam) gam`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < gam pow 2` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(S:real) <= B * inv(gam pow 2)` ASSUME_TAC THENL
   [REWRITE_TAC[real_div] THEN ONCE_REWRITE_TAC[GSYM real_div] THEN
    ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= B` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `gam pow 2 * (S:real)` THEN
    ASM_SIMP_TAC[REAL_LE_MUL; REAL_LT_IMP_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= inv(gam pow 2)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[REAL_LE_INV_EQ; REAL_LT_IMP_LE]; ALL_TAC] THEN
  REWRITE_TAC[real_min] THEN COND_CASES_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `gam * (&1 * ((B:real) * inv(gam pow 2)))` THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL2 THEN REPEAT CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_LE_MUL2 THEN ASM_REWRITE_TAC[]];
      MATCH_MP_TAC REAL_EQ_IMP_LE THEN
      SUBGOAL_THEN `~(gam = &0)` MP_TAC THENL
       [ASM_REAL_ARITH_TAC; REWRITE_TAC[REAL_POW_2] THEN CONV_TAC REAL_FIELD]];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `gam * ((gam pow 2) * ((B:real) * inv(gam pow 2)))` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL2 THEN REPEAT CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_LE_MUL2 THEN ASM_REWRITE_TAC[]];
      MATCH_MP_TAC REAL_EQ_IMP_LE THEN
      SUBGOAL_THEN `~(gam = &0)` MP_TAC THENL
       [ASM_REAL_ARITH_TAC; REWRITE_TAC[REAL_POW_2] THEN
         CONV_TAC REAL_FIELD]]]);;

(* Abstract OUTER-SUMMATION engine for alpha0/alpha1: group a finite sum by  *)
(* the                                                                       *)
(* scale sc a, and if every scale-fiber sums to <= C 2^{-k} and all scales   *)
(* are                                                                       *)
(* >= L, then the whole sum is <= 2 C 2^{-L}. Composes SUM_GROUP (regroup by *)
(* scale) with SUM_INV_ZPOW_GE_LE (the dyadic geometric tail).  In 286L this *)
(* consumes CARLESON_ALPHA_SCALE as the per-scale-fiber bound (C = C1 energy *)
(* mass,                                                                     *)
(* L = l_K within a cover cell, or k_tau across cells), decoupling the       *)
(* geometric                                                                 *)
(* series from the tile geometry.                                            *)
let ABSTRACT_SCALE_GEOM_SUM = prove
 (`!(A:B->bool) (sc:B->int) (g:B->real) L C.
     FINITE A /\ &0 <= C /\
     (!a. a IN A ==> L <= sc a) /\
     (!k. sum {a | a IN A /\ sc a = k} g <= C * inv(&2 zpow k))
     ==> sum A g <= &2 * C * inv(&2 zpow L)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`sc:B->int`; `g:B->real`; `A:B->bool`; `IMAGE (sc:B->int) A`]
    SUM_GROUP) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (IMAGE (sc:B->int) A) (\y. C * inv(&2 zpow y))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_SIMP_TAC[FINITE_IMAGE];
    REWRITE_TAC[SUM_LMUL] THEN
    SUBGOAL_THEN
      `&2 * C * inv(&2 zpow L) = C * (&2 * inv(&2 zpow L))` SUBST1_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SUM_INV_ZPOW_GE_LE THEN
    ASM_SIMP_TAC[FINITE_IMAGE; FORALL_IN_IMAGE]]);;

(* --- CUBIC (ratio 1/8) geometric machinery for alpha1's k-sum ---          *)
(* alpha1's per-scale-slice bound is <= C inv(2^{2a}) inv(2^{3k}) (the TIGHT *)
(* decay);                                                                   *)
(* the inner sum over scales k >= k_tau is a CUBIC geometric series (ratio   *)
(* 1/8, not                                                                  *)
(* 1/2 as in alpha0). inv(2^{3k}) = inv(8^k) (ZPOW_2_3), so these are the    *)
(* base-8                                                                    *)
(* analogues of INV_ZPOW_REINDEX / SUM_INV_ZPOW_GE_LE /                      *)
(* ABSTRACT_SCALE_GEOM_SUM.                                                  *)

(* Generic finite geometric bound: sum of r^n over any finite exponent set   *)
(* <= 1/(1-r) for 0 <= r < 1 (bounded by the 0..max closed form SUM_GP).     *)
let SUM_POW_LE_GEN = prove
 (`!(N:num->bool) r. FINITE N /\ &0 <= r /\ r < &1
     ==> sum N (\n. r pow n) <= inv(&1 - r)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\n:num. n`; `N:num->bool`] UPPER_BOUND_FINITE_SET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:num`) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `sum (0..m) (\n. r pow n)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
    ASM_SIMP_TAC[FINITE_NUMSEG; SUBSET; IN_NUMSEG; LE_0] THEN
    REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_POW_LE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SUM_GP] THEN
    COND_CASES_TAC THENL [POP_ASSUM MP_TAC THEN ARITH_TAC; ALL_TAC] THEN
    COND_CASES_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `&0 < &1 - r` ASSUME_TAC THENL
      [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN
    SUBGOAL_THEN `inv(&1 - r) * (&1 - r) = &1` SUBST1_TAC THENL
     [MATCH_MP_TAC REAL_MUL_LINV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(REAL_ARITH `&0 <= b ==> r pow 0 - b <= &1`) THEN
    REWRITE_TAC[real_pow] THEN
    ONCE_REWRITE_TAC[GSYM real_pow] THEN MATCH_MP_TAC REAL_POW_LE THEN
      ASM_REWRITE_TAC[]]);;

let ZPOW_2_3 = prove
 (`!k:int. &2 zpow (&3 * k) = &8 zpow k`,
  GEN_TAC THEN
  SUBGOAL_THEN `(&8:real) = &2 zpow (&3)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_POW] THEN
     CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[REAL_ZPOW_ZPOW]);;

let INV_ZPOW8_REINDEX = prove
 (`!L k:int. L <= k
     ==> inv(&8 zpow k) = inv(&8 zpow L) * inv(&8) pow (num_of_int(k - L))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `n = num_of_int(k - L)` THEN
  SUBGOAL_THEN `k:int = L + &n` SUBST1_TAC THENL
   [EXPAND_TAC "n" THEN
    MP_TAC(ISPEC `k - L:int` INT_OF_NUM_OF_INT) THEN
    ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(&8 = &0)` ASSUME_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_ZPOW_ADD; REAL_ZPOW_NUM; REAL_INV_MUL;
    GSYM REAL_INV_POW]);;

(* The cubic dyadic tail: a finite set SK of scales all >= L has sum         *)
(* inv(8^k) <=                                                               *)
(* (8/7) inv(8^L). (Reindex via INV_ZPOW8_REINDEX, factor inv(8^L), residual *)
(* sum of                                                                    *)
(* distinct (1/8)^{k-L} <= 8/7 = inv(1 - 1/8) via SUM_POW_LE_GEN after       *)
(* SUM_IMAGE.)                                                               *)
let SUM_INV_ZPOW8_GE_LE = prove
 (`!(SK:int->bool) L. FINITE SK /\ (!k. k IN SK ==> L <= k)
     ==> sum SK (\k. inv(&8 zpow k)) <= (&8 / &7) * inv(&8 zpow L)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `sum SK (\k. inv(&8 zpow k)) =
    inv(&8 zpow L) * sum SK (\k. inv(&8) pow (num_of_int(k - L)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM SUM_LMUL] THEN MATCH_MP_TAC SUM_EQ THEN
    X_GEN_TAC `k:int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC INV_ZPOW8_REINDEX THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(&8 / &7) * inv(&8 zpow L) = inv(&8 zpow L) * (&8 / &7)` SUBST1_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `sum SK (\k. inv(&8) pow (num_of_int(k - L))) =
    sum (IMAGE (\k:int. num_of_int(k - L)) SK) (\n. inv(&8) pow n)`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN
    MP_TAC(ISPECL [`\k:int. num_of_int(k - L)`; `\n:num. inv(&8) pow n`;
      `SK:int->bool`]
      SUM_IMAGE) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[] THEN MAP_EVERY X_GEN_TAC [`a:int`; `b:int`] THEN
       STRIP_TAC THEN
      SUBGOAL_THEN `L <= a:int /\ L <= b:int` STRIP_ASSUME_TAC THENL
       [ASM_SIMP_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPEC `a - L:int` INT_OF_NUM_OF_INT) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      MP_TAC(ISPEC `b - L:int` INT_OF_NUM_OF_INT) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      REPEAT DISCH_TAC THEN
      SUBGOAL_THEN `a - L:int = b - L` MP_TAC THENL
       [FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC LAND_CONV [SYM th]) THEN
        FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC RAND_CONV [SYM th]) THEN
        ASM_REWRITE_TAC[];
        INT_ARITH_TAC];
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]];
    ALL_TAC] THEN
  SUBGOAL_THEN `&8 / &7 = inv(&1 - inv(&8))` SUBST1_TAC THENL
   [CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  MATCH_MP_TAC SUM_POW_LE_GEN THEN
  SIMP_TAC[FINITE_IMAGE; ASSUME `FINITE(SK:int->bool)`] THEN
  CONV_TAC REAL_RAT_REDUCE_CONV);;

(* Abstract cubic outer-summation engine (base-8 analogue of                 *)
(* ABSTRACT_SCALE_GEOM_SUM): per-scale slices <= C inv(8^k) for scales >= L  *)
(* give total <= (8/7) C inv(8^L).                                           *)
let ABSTRACT_SCALE_GEOM_SUM8 = prove
 (`!(A:B->bool) (sc:B->int) (g:B->real) L C.
     FINITE A /\ &0 <= C /\
     (!a. a IN A ==> L <= sc a) /\
     (!k. sum {a | a IN A /\ sc a = k} g <= C * inv(&8 zpow k))
     ==> sum A g <= (&8 / &7) * C * inv(&8 zpow L)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`sc:B->int`; `g:B->real`; `A:B->bool`; `IMAGE (sc:B->int) A`]
    SUM_GROUP) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (IMAGE (sc:B->int) A) (\y. C * inv(&8 zpow y))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_SIMP_TAC[FINITE_IMAGE];
    REWRITE_TAC[SUM_LMUL] THEN
    SUBGOAL_THEN
      `(&8 / &7) * C * inv(&8 zpow L) = C * ((&8 / &7) * inv(&8 zpow L))`
      SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SUM_INV_ZPOW8_GE_LE THEN
    ASM_SIMP_TAC[FINITE_IMAGE; FORALL_IN_IMAGE]]);;

(* --- QUADRATIC (ratio 1/4) geometric machinery for alpha1's coarse-LEVEL   *)
(* sum ---                                                                   *)
(* The alpha1 OUTER sum over cover levels a carries the inv(2^{2a}) =        *)
(* inv(4^a) weight;                                                          *)
(* summed over levels a >= L (with a bounded count per level) it is a        *)
(* QUADRATIC geometric                                                       *)
(* series (ratio 1/4, constant 4/3). Base-4 analogues of the base-8 lemmas   *)
(* above.                                                                    *)
let ZPOW_2_2 = prove
 (`!k:int. &2 zpow (&2 * k) = &4 zpow k`,
  GEN_TAC THEN
  SUBGOAL_THEN `(&4:real) = &2 zpow (&2)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_POW] THEN
     CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[REAL_ZPOW_ZPOW]);;

let INV_ZPOW4_REINDEX = prove
 (`!L k:int. L <= k
     ==> inv(&4 zpow k) = inv(&4 zpow L) * inv(&4) pow (num_of_int(k - L))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `n = num_of_int(k - L)` THEN
  SUBGOAL_THEN `k:int = L + &n` SUBST1_TAC THENL
   [EXPAND_TAC "n" THEN
    MP_TAC(ISPEC `k - L:int` INT_OF_NUM_OF_INT) THEN
    ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(&4 = &0)` ASSUME_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_ZPOW_ADD; REAL_ZPOW_NUM; REAL_INV_MUL;
    GSYM REAL_INV_POW]);;

let SUM_INV_ZPOW4_GE_LE = prove
 (`!(SK:int->bool) L. FINITE SK /\ (!k. k IN SK ==> L <= k)
     ==> sum SK (\k. inv(&4 zpow k)) <= (&4 / &3) * inv(&4 zpow L)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `sum SK (\k. inv(&4 zpow k)) =
    inv(&4 zpow L) * sum SK (\k. inv(&4) pow (num_of_int(k - L)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM SUM_LMUL] THEN MATCH_MP_TAC SUM_EQ THEN
    X_GEN_TAC `k:int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC INV_ZPOW4_REINDEX THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(&4 / &3) * inv(&4 zpow L) = inv(&4 zpow L) * (&4 / &3)` SUBST1_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `sum SK (\k. inv(&4) pow (num_of_int(k - L))) =
    sum (IMAGE (\k:int. num_of_int(k - L)) SK) (\n. inv(&4) pow n)`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN
    MP_TAC(ISPECL [`\k:int. num_of_int(k - L)`; `\n:num. inv(&4) pow n`;
      `SK:int->bool`]
      SUM_IMAGE) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[] THEN MAP_EVERY X_GEN_TAC [`a:int`; `b:int`] THEN
       STRIP_TAC THEN
      SUBGOAL_THEN `L <= a:int /\ L <= b:int` STRIP_ASSUME_TAC THENL
       [ASM_SIMP_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPEC `a - L:int` INT_OF_NUM_OF_INT) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      MP_TAC(ISPEC `b - L:int` INT_OF_NUM_OF_INT) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      REPEAT DISCH_TAC THEN
      SUBGOAL_THEN `a - L:int = b - L` MP_TAC THENL
       [FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC LAND_CONV [SYM th]) THEN
        FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC RAND_CONV [SYM th]) THEN
        ASM_REWRITE_TAC[];
        INT_ARITH_TAC];
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]];
    ALL_TAC] THEN
  SUBGOAL_THEN `&4 / &3 = inv(&1 - inv(&4))` SUBST1_TAC THENL
   [CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  MATCH_MP_TAC SUM_POW_LE_GEN THEN
  SIMP_TAC[FINITE_IMAGE; ASSUME `FINITE(SK:int->bool)`] THEN
  CONV_TAC REAL_RAT_REDUCE_CONV);;

(* 286L(d) tight-decay: the tight per-scale factor inv((1+M)^2), M =         *)
(* 2^{a+k}, is                                                               *)
(* <= inv(2^{2a}) inv(2^{2k}). (1+M > M > 0 so (1+M)^2 > M^2 = 2^{2a+2k} =   *)
(* 2^{2a}2^{2k};                                                             *)
(* REAL_LE_INV2.) This converts the tight per-scale bound into the CUBIC     *)
(* form                                                                      *)
(* C inv(2^{2a}) inv(8^k) whose k-sum (>= k_tau) converges (ratio 1/8) and   *)
(* whose                                                                     *)
(* inv(2^{2a}) constant feeds the coarse-level (ratio 1/4) outer sum.        *)
let TIGHT_DECAY_BOUND = prove
 (`!a k M:int. &2 zpow (a + k) = real_of_int M /\ &1 <= M
     ==> inv((&1 + real_of_int M) pow 2)
         <= inv(&2 zpow (&2 * a)) * inv(&2 zpow (&2 * k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= real_of_int M` ASSUME_TAC THENL
   [UNDISCH_TAC `&1 <= (M:int)` THEN
     REWRITE_TAC[int_le; GSYM ROI_1]; ALL_TAC] THEN
  SUBGOAL_THEN `inv(&2 zpow (&2 * a)) * inv(&2 zpow (&2 * k)) =
                inv((real_of_int M) pow 2)` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM REAL_INV_MUL] THEN AP_TERM_TAC THEN
    SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
    SUBGOAL_THEN `&2 * a + &2 * k = &2 * (a + k):int` SUBST1_TAC THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    ONCE_REWRITE_TAC[INT_MUL_SYM] THEN REWRITE_TAC[GSYM REAL_ZPOW_ZPOW] THEN
    ASM_REWRITE_TAC[REAL_ZPOW_POW] THEN CONV_TAC REAL_RAT_REDUCE_CONV;
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_INV2 THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_POW_LE2 THEN ASM_REAL_ARITH_TAC]);;

(* alpha1 OUTER coarse-level geometric combinators. The per-cover-cell       *)
(* alpha1 bound                                                              *)
(* carries the weight inv(4^{a_K}) (a_K = -l_K the cover level); summed over *)
(* the cover                                                                 *)
(* with a per-level bound it telescopes via the QUADRATIC tail               *)
(* SUM_INV_ZPOW4_GE_LE.                                                      *)

(* Fiber form (flexible): if each level-fiber sum of g is <= N inv(4^m),     *)
(* then the total                                                            *)
(* over S is <= N (4/3) inv(4^L). SUM_GROUP by lev, per-fiber bound, then    *)
(* base-4 tail.                                                              *)
let LEVEL_FIBER_SUM_LE = prove
 (`!(S:A->bool) (lev:A->int) (g:A->real) L N.
     FINITE S /\ &0 <= N /\
     (!x. x IN S ==> L <= lev x) /\
     (!m. sum {x | x IN S /\ lev x = m} g <= N * inv(&4 zpow m))
     ==> sum S g <= N * (&4 / &3) * inv(&4 zpow L)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`lev:A->int`; `g:A->real`; `S:A->bool`;
                 `IMAGE (lev:A->int) S`] SUM_GROUP) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (IMAGE (lev:A->int) S) (\m. N * inv(&4 zpow m))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_SIMP_TAC[FINITE_IMAGE];
    REWRITE_TAC[SUM_LMUL] THEN
    SUBGOAL_THEN
      `N * (&4 / &3) * inv(&4 zpow L) = N * ((&4 / &3) * inv(&4 zpow L))`
      SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SUM_INV_ZPOW4_GE_LE THEN
    ASM_SIMP_TAC[FINITE_IMAGE; FORALL_IN_IMAGE]]);;

(* Count form: if each level-fiber has <= N members, then sum inv(4^{lev x}) *)
(* over S is                                                                 *)
(* <= N (4/3) inv(4^L). (Specialises LEVEL_FIBER_SUM_LE at g = inv(4^{lev    *)
(* .}); each                                                                 *)
(* fiber sum = &(CARD fiber) inv(4^m) <= N inv(4^m).)                        *)
let LEVEL_WEIGHTED_SUM_LE = prove
 (`!(S:A->bool) (lev:A->int) L N.
     FINITE S /\ &0 <= N /\
     (!x. x IN S ==> L <= lev x) /\
     (!m. &(CARD {x | x IN S /\ lev x = m}) <= N)
     ==> sum S (\x. inv(&4 zpow (lev x))) <= N * (&4 / &3) * inv(&4 zpow L)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC LEVEL_FIBER_SUM_LE THEN
  EXISTS_TAC `lev:A->int` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `m:int` THEN
  SUBGOAL_THEN
   `sum {x:A | x IN S /\ lev x = m} (\x. inv(&4 zpow (lev x))) =
    sum {x:A | x IN S /\ lev x = m} (\x. inv(&4 zpow m))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `x:A` THEN REWRITE_TAC[IN_ELIM_THM] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[SUM_CONST; FINITE_RESTRICT] THEN
  MATCH_MP_TAC REAL_LE_RMUL THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
      REAL_ARITH_TAC]);;

let CW_SUM_BOUND = prove
 (`!m n. sum(m..n) (\k. cw(&k + &1 / &2)) <= &1 / (&2 * (&1 + &m) pow 2)`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum(m..n) (\k. &1 / (&2 * (&1 + &k) pow 2) - &1 / (&2 * (&1 + (&k
    + &1)) pow 2))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN REWRITE_TAC[FINITE_NUMSEG] THEN
    X_GEN_TAC `k:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC CW_TERM_BOUND THEN REWRITE_TAC[REAL_POS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `sum(m..n) (\k. &1 / (&2 * (&1 + &k) pow 2) - &1 / (&2 * (&1 + (&k + &1))
     pow 2)) =
    sum(m..n) (\k. (\j. &1 / (&2 * (&1 + &j) pow 2)) k - (\j. &1 / (&2 * (&1 +
      &j) pow 2)) (k + 1))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `k:num` THEN DISCH_TAC THEN
     REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
      AP_TERM_TAC THEN
    REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[SUM_DIFFS] THEN COND_CASES_TAC THENL
   [MATCH_MP_TAC(REAL_ARITH `&0 <= b ==> a - b <= a`) THEN
    MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; MATCH_MP_TAC REAL_POW_LE THEN REAL_ARITH_TAC]];
    MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; MATCH_MP_TAC REAL_POW_LE THEN REAL_ARITH_TAC]]]);;

(* The QUADRATIC-decay half-integer sum (distinct from CW_SUM_BOUND's cubic  *)
(* one):                                                                     *)
(*   sum_{k=m..n} 1/(2(1+(k+1/2))^2) <= 1/(2(1+m)).                          *)
(* This is the convergent series behind Fremlin's C4 = 2 sum_j               *)
(* int_{j+1/2}^inf w =                                                       *)
(* 2 sum_j 1/(2(1+(j+1/2))^2): each tile-tail value is                       *)
(* 1/(2(1+scaled-dist)^2)                                                    *)
(* (the CWTILE_TAIL family) and the scaled distances run over the            *)
(* half-integer grid.                                                        *)
(* Telescopes via CW_QUAD_TERM_BOUND (term <= 1/(2(1+k)) - 1/(2(1+k+1))) +   *)
(* SUM_DIFFS.                                                                *)
let CW_QUAD_TERM_BOUND = prove
 (`!t. &0 <= t
   ==> &1 / (&2 * (&1 + (t + &1 / &2)) pow 2)
       <= &1 / (&2 * (&1 + t)) - &1 / (&2 * (&1 + (t + &1)))`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `&0 < &1 + t /\ &0 < &2 + t /\ &0 < &3 + &2 * t` STRIP_ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `&1 / (&2 * (&1 + (t + &1 / &2)) pow 2) = &2 / (&3 + &2 * t) pow 2`
    SUBST1_TAC THENL
   [MATCH_MP_TAC(REAL_FIELD `&0 < &3 + &2 * t ==>
      &1 / (&2 * (&1 + (t + &1 / &2)) pow 2) = &2 / (&3 + &2 * t) pow 2`) THEN
        ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&1 / (&2 * (&1 + t)) - &1 / (&2 * (&1 + (t + &1))) =
                &1 / (&2 * (&1 + t) * (&2 + t))` SUBST1_TAC THENL
   [MATCH_MP_TAC(REAL_FIELD `&0 < &1 + t /\ &0 < &2 + t ==>
      &1 / (&2 * (&1 + t)) - &1 / (&2 * (&1 + (t + &1))) = &1 / (&2 * (&1 + t)
        * (&2 + t))`) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < (&3 + &2 * t) pow 2 /\ &0 < &2 * (&1 + t) * (&2 + t)`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_POW_LT THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; MATCH_MP_TAC REAL_LT_MUL THEN ASM_REAL_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `&2 * &2 * (&1 + t) * (&2 + t) <= (&3 + &2 * t) pow 2` ASSUME_TAC THENL
   [MP_TAC(SPEC `t:real` (REAL_RING
      `!t:real. (&3 + &2 * t) pow 2 - &2 * (&2 * (&1 + t) * (&2 + t)) = &1`))
        THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
  ASM_SIMP_TAC[REAL_FIELD `&0 < A ==> &2 / A * &2 * (&1 + t) * (&2 + t) =
                          (&2 * &2 * (&1 + t) * (&2 + t)) / A`] THEN
  ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_MUL_LID]);;

let QUAD_HALF_SUM_BOUND = prove
 (`!m n. sum(m..n) (\k. &1 / (&2 * (&1 + (&k + &1 / &2)) pow 2)) <= &1 / (&2 *
   (&1 + &m))`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum(m..n) (\k. &1 / (&2 * (&1 + &k)) - &1 / (&2 * (&1 + (&k +
    &1))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN REWRITE_TAC[FINITE_NUMSEG] THEN
    X_GEN_TAC `k:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC CW_QUAD_TERM_BOUND THEN REWRITE_TAC[REAL_POS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `sum(m..n) (\k. &1 / (&2 * (&1 + &k)) - &1 / (&2 * (&1 + (&k + &1)))) =
    sum(m..n) (\k. (\j. &1 / (&2 * (&1 + &j))) k - (\j. &1 / (&2 * (&1 + &j)))
      (k + 1))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `k:num` THEN DISCH_TAC THEN
     REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
      AP_TERM_TAC THEN
    REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[SUM_DIFFS] THEN COND_CASES_TAC THENL
   [MATCH_MP_TAC(REAL_ARITH `&0 <= b ==> a - b <= a`) THEN
    MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; MATCH_MP_TAC REAL_LE_MUL THEN REAL_ARITH_TAC];
    MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; MATCH_MP_TAC REAL_LE_MUL THEN REAL_ARITH_TAC]]);;

(* Fremlin's C4 = 2 sum_{j>=0} int_{j+1/2}^inf w <= 1: the doubled quadratic *)
(* tail                                                                      *)
(* sum from 0 is <= 1 (QUAD_HALF_SUM_BOUND at m=0 gives sum <= 1/2). The     *)
(* two-sided                                                                 *)
(* per-tile tail (left + right, CWTILE_TAIL_COMPLEMENT) summed over the      *)
(* same-scale                                                                *)
(* sub-tiles of I_tau reduces to this after re-indexing the mirror half.     *)
let QUAD_HALF_SUM_DOUBLED = prove
 (`!n. &2 * sum(0..n) (\k. &1 / (&2 * (&1 + (&k + &1 / &2)) pow 2)) <= &1`,
  GEN_TAC THEN
  MP_TAC(SPECL [`0`; `n:num`] QUAD_HALF_SUM_BOUND) THEN
  REWRITE_TAC[REAL_ADD_RID; REAL_MUL_RID] THEN REAL_ARITH_TAC);;

(* The TWO-SIDED tail sum <= 1: summing over j = 0..N the pair               *)
(*   [left tail 1/(2(1+(j+1/2))^2)] + [right tail 1/(2(1+((N-j)+1/2))^2)]    *)
(* is <= 1. The right half re-indexes (SUM_REFLECT, j |-> N-j) to the left   *)
(* half, so                                                                  *)
(* the total is 2 * (one half) <= 1 (QUAD_HALF_SUM_DOUBLED). This is the     *)
(* abstract                                                                  *)
(* combinatorial core of 286Gf's sum over the same-scale sub-tiles of I_tau  *)
(* of                                                                        *)
(* int_{R\I_tau} w_sigma <= C4 (C4 = 1): each sub-tile's complement mass is  *)
(* left+                                                                     *)
(* right tail (CWTILE_TAIL_COMPLEMENT), and the sub-tiles tile I_tau so the  *)
(* scaled                                                                    *)
(* edge-distances are exactly j+1/2 and (N-j)+1/2.                           *)
let TWO_SIDED_TAIL_SUM = prove
 (`!N. sum(0..N) (\j. &1 / (&2 * (&1 + (&j + &1 / &2)) pow 2) +
                      &1 / (&2 * (&1 + (&(N - j) + &1 / &2)) pow 2)) <= &1`,
  GEN_TAC THEN REWRITE_TAC[SUM_ADD_NUMSEG] THEN
  SUBGOAL_THEN
   `sum (0..N) (\j. &1 / (&2 * (&1 + &(N - j) + &1 / &2) pow 2)) =
    sum (0..N) (\j. &1 / (&2 * (&1 + &j + &1 / &2) pow 2))`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`\i. &1 / (&2 * (&1 + &i + &1 / &2) pow 2)`; `0`;
     `N:num`] SUM_REFLECT) THEN
    REWRITE_TAC[SUB_0; LT] THEN
      DISCH_THEN(fun th -> GEN_REWRITE_TAC RAND_CONV [th]) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `&2 * s <= &1 ==> s + s <= &1`) THEN
  REWRITE_TAC[QUAD_HALF_SUM_DOUBLED]);;

(* 286Gf, per-sub-tile step: the weight-mass of a scale-k sub-tile of I_tau  *)
(* OUTSIDE I_tau = (alpha, gamma) equals the tail pair (j, N-1-j) of half-   *)
(* integer arguments. alpha = nIt * 2 zpow (--kt) (left edge of I_tau),      *)
(* gamma                                                                     *)
(* = (nIt + 1) * 2 zpow (--kt) (right edge); the sub-tile at offset j (index *)
(* &N * nIt + &j, N = 2 zpow (k - kt) sub-cells) has centre edge-distances   *)
(* j + 1/2 and (N-1-j) + 1/2 (TILE_SUBCELL_EDGE_DIST), so                    *)
(* CWTILE_TAIL_COMPLEMENT                                                    *)
(* gives exactly the two quadratic tail terms. 1 <= N from 2 zpow (k-kt) =   *)
(* &N                                                                        *)
(* >= 1; the alpha < xmid < gamma hypotheses of CWTILE_TAIL_COMPLEMENT       *)
(* follow                                                                    *)
(* from the edge distances by cancelling the positive factor 2 zpow k.       *)
let CWTILE_SUBTILE_COMPL_VALUE = prove
 (`!k kt N nIt nJs j.
     kt <= k /\ &2 zpow (k - kt) = &N /\ j <= N - 1
     ==> real_integral
           ({x | x <= real_of_int nIt * &2 zpow (--kt)} UNION
            {x | (real_of_int nIt + &1) * &2 zpow (--kt) <= x})
           (cw_tile (k, &N * nIt + &j, nJs)) =
         &1 / (&2 * (&1 + (&j + &1 / &2)) pow 2) +
         &1 / (&2 * (&1 + (&((N - 1) - j) + &1 / &2)) pow 2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `1 <= N` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`&2:real`; `k - kt:int`] REAL_ZPOW_LT) THEN
    REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[REAL_OF_NUM_LT] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(&N:real) - &j - &1 = &((N - 1) - j)` ASSUME_TAC THENL
   [MP_TAC(SPECL [`j:num`; `N - 1`] REAL_OF_NUM_SUB) THEN
     ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`1`; `N:num`] REAL_OF_NUM_SUB) THEN ASM_REWRITE_TAC[] THEN
    REPEAT(DISCH_THEN(SUBST1_TAC o SYM)) THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`k:int`;`kt:int`;`&N:int`;`nIt:int`;`&j:int`;`nJs:int`]
             TILE_SUBCELL_EDGE_DIST) THEN
  REWRITE_TAC[int_of_num_th] THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`(k, &N * nIt + &j, nJs):int#int#int`;
                 `real_of_int nIt * &2 zpow (--kt)`;
                 `(real_of_int nIt + &1) * &2 zpow (--kt)`]
            CWTILE_TAIL_COMPLEMENT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_LT_LCANCEL_IMP THEN
      EXISTS_TAC `&2 zpow k` THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_LT_LCANCEL_IMP THEN
      EXISTS_TAC `&2 zpow k` THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_LCANCEL_IMP THEN EXISTS_TAC `&2 zpow k` THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[tile_k] THEN
  DISCH_THEN(MP_TAC o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN
  DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]);;

(* 286Gf PROPER: summing the per-sub-tile complement mass over the N = 2     *)
(* zpow                                                                      *)
(* (k - kt) scale-k sub-tiles of I_tau (offsets j = 0..N-1) gives <= C4 = 1. *)
(* Each term is the (j, N-1-j) half-integer tail pair (CWTILE_SUBTILE_COMPL_ *)
(* VALUE), and TWO_SIDED_TAIL_SUM at N-1 bounds their sum by 1.  This is     *)
(* Fremlin's 286G(f): the total weight leaking outside a coarse spatial      *)
(* cell,                                                                     *)
(* summed over one frequency level's sub-tiles, is bounded by the tail       *)
(* constant.                                                                 *)
let CARLESON_SUBTILE_TAIL_SUM = prove
 (`!k kt N nIt nJs.
     kt <= k /\ &2 zpow (k - kt) = &N
     ==> sum (0..N - 1) (\j.
           real_integral
             ({x | x <= real_of_int nIt * &2 zpow (--kt)} UNION
              {x | (real_of_int nIt + &1) * &2 zpow (--kt) <= x})
             (cw_tile (k, &N * nIt + &j, nJs)))
         <= &1`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (0..N - 1) (\j.
       &1 / (&2 * (&1 + (&j + &1 / &2)) pow 2) +
       &1 / (&2 * (&1 + (&((N - 1) - j) + &1 / &2)) pow 2))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_EQ_IMP_LE THEN MATCH_MP_TAC SUM_EQ THEN
    X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_NUMSEG] THEN STRIP_TAC THEN
    MATCH_MP_TAC CWTILE_SUBTILE_COMPL_VALUE THEN ASM_REWRITE_TAC[];
    MP_TAC(SPEC `N - 1` TWO_SIDED_TAIL_SUM) THEN REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286E-b: the tile-localized test function phi_sigma.                       *)
(*                                                                           *)
(* The abstract modulated-scaled-translated family                           *)
(*   phimst mJ a b phi = \x. sqrt(mJ) e^{i b x} phi(mJ (x - a))              *)
(* and its properties are instantiated at the                               *)
(* tile parameters mJ = 2^k, a = x_sigma = tile_xmid, b = y^l = tile_ymid:   *)
(* phi_sigma s phi = 2^(k/2) M_{y_s} S_{-x_s} D_{2^k} phi = Fremlin's phi_s. *)
(* CARLESON_286EB supplies the base test function with                       *)
(* char[-1/6,1/6] <= phi^ <= char[-1/5,1/5].                                *)
(* ------------------------------------------------------------------------- *)

let phi_sigma = new_definition
 `phi_sigma (s:int#int#int) (phi:real->complex) =
    phimst (&2 zpow (tile_k s)) (tile_xmid s) (tile_ymid s) phi`;;

(* The tile scale mJ = 2^k is strictly positive (discharges the mJ>0 / mJ<>0 *)
(* hypotheses of every PHIMST_* lemma below).                                *)
let PHISIG_SCALE_POS = prove
 (`!s:int#int#int. &0 < &2 zpow (tile_k s)`,
  GEN_TAC THEN MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC);;

(* A Schwartz function is square-integrable in the lift(norm . ^2) form the  *)
(* norm lemmas need (from SCHWARTZ_L2 membership in lspace(&2), RPOW_POW).   *)
let SCHWARTZ_NORMSQ_INTEGRABLE = prove
 (`!(phi:real->complex). schwartz phi
     ==> (\x:real^1. lift(norm(phi(drop x)) pow 2)) integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN FIRST_ASSUM(MP_TAC o MATCH_MP SCHWARTZ_L2) THEN
  REWRITE_TAC[lspace; IN_ELIM_THM] THEN STRIP_TAC THEN
  POP_ASSUM MP_TAC THEN REWRITE_TAC[RPOW_POW]);;

(* 286E b: phi_sigma of a Schwartz function is Schwartz.                     *)
let PHISIG_SCHWARTZ = prove
 (`!(s:int#int#int) (phi:real->complex). schwartz phi ==> schwartz (phi_sigma s
   phi)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[phi_sigma] THEN
  MATCH_MP_TAC PHIMST_SCHWARTZ THEN
  ASM_SIMP_TAC[REAL_LT_IMP_NZ; PHISIG_SCALE_POS]);;

(* 286E b-i: ||phi_sigma s phi||_2 = ||phi||_2  (L^2-norm preserved).        *)
let PHISIG_L2 = prove
 (`!(s:int#int#int) (phi:real->complex). schwartz phi
     ==> lnorm (:real^1) (&2) (\z. phi_sigma s phi (drop z)) =
         lnorm (:real^1) (&2) (\z. phi (drop z))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[phi_sigma] THEN
  MATCH_MP_TAC PHIMST_L2 THEN
  ASM_SIMP_TAC[PHISIG_SCALE_POS; SCHWARTZ_NORMSQ_INTEGRABLE]);;

(* 286E b-ii: the Fourier transform of phi_sigma.                            *)
let PHISIG_FHAT = prove
 (`!(s:int#int#int) (phi:real->complex) y. schwartz phi
     ==> fourier (phi_sigma s phi) y =
         Cx(&1 / sqrt(&2 zpow (tile_k s))) *
         cexp(--(ii * Cx(tile_xmid s) * Cx(y - tile_ymid s))) *
         fourier phi ((y - tile_ymid s) / &2 zpow (tile_k s))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[phi_sigma] THEN
  MATCH_MP_TAC PHIMST_FHAT THEN ASM_REWRITE_TAC[PHISIG_SCALE_POS]);;

(* 286E b-iii: frequency support of phi_sigma. If phi^ is supported in       *)
(* [c,d],                                                                    *)
(* then (phi_sigma s phi)^ is supported in [y_s + 2^k c, y_s + 2^k d].       *)
let PHISIG_FHAT_SUPPORT = prove
 (`!(s:int#int#int) (phi:real->complex) c d. schwartz phi /\
     (!u. u < c \/ d < u ==> fourier phi u = Cx(&0))
     ==> (!y. y < tile_ymid s + &2 zpow (tile_k s) * c \/
              tile_ymid s + &2 zpow (tile_k s) * d < y
              ==> fourier (phi_sigma s phi) y = Cx(&0))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[phi_sigma] THEN STRIP_TAC THEN
  MATCH_MP_TAC PHIMST_FHAT_SUPPORT THEN ASM_REWRITE_TAC[PHISIG_SCALE_POS]);;

(* 286E b-ii, L^1 half: INT|phi_sigma^| = sqrt(2^k) INT|phi^|.               *)
let carleson_phi = new_specification ["carleson_phi"]
  (REWRITE_RULE[SKOLEM_THM] CARLESON_286EB);;

let CARLESON_PHI_SCHWARTZ = prove
 (`schwartz carleson_phi`,
  STRIP_ASSUME_TAC carleson_phi THEN ASM_REWRITE_TAC[]);;

(* fourier carleson_phi vanishes for |y| > 1/5: at such y both the lower and *)
(* upper characteristic bounds are 0, forcing Re(fourier phi y) = 0; and     *)
(* fourier phi y is real, so it is Cx(&0).                                   *)
let CARLESON_PHI_FHAT_SUPPORT = prove
 (`!y. &1 / &5 < abs y ==> fourier carleson_phi y = Cx(&0)`,
  GEN_TAC THEN DISCH_TAC THEN STRIP_ASSUME_TAC carleson_phi THEN
  SUBGOAL_THEN `Re(fourier carleson_phi y) = &0` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN
    COND_CASES_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    COND_CASES_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REAL] o SPEC `y:real`) THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC COMPLEX_RING);;

(* Support in the [c,d] = [-1/5,1/5] form the phi_sigma lemmas consume.      *)
let CARLESON_PHI_SUPP_CD = prove
 (`!u. u < --(&1 / &5) \/ &1 / &5 < u ==> fourier carleson_phi u = Cx(&0)`,
  GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC CARLESON_PHI_FHAT_SUPPORT THEN
  ASM_REAL_ARITH_TAC);;

(* M4 brick (step iv-ii): fourier carleson_phi = 1 on [-1/6,1/6].  From the  *)
(* carleson_phi spec char[-1/6,1/6] <= Re(fhat) <= char[-1/5,1/5] and fhat   *)
(* real:                                                                     *)
(* for abs y <= 1/6, lower gives 1 <= Re fhat and (1/6<=1/5) upper gives     *)
(* Re fhat <= 1, so Re fhat = 1; fhat real => fhat y = Cx 1.                 *)
let CARLESON_PHI_FHAT_ONE = prove
 (`!y. abs y <= &1 / &6 ==> fourier carleson_phi y = Cx(&1)`,
  GEN_TAC THEN DISCH_TAC THEN STRIP_ASSUME_TAC carleson_phi THEN
  SUBGOAL_THEN `Re(fourier carleson_phi y) = &1` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN
    REPEAT COND_CASES_TAC THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REAL] o SPEC `y:real`) THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC COMPLEX_RING);;

(* CLOSED support (Fremlin 286(h)(iii) uses the CLOSED cutoff abs(arg) >=    *)
(* 1/5,                                                                      *)
(* line 1617): fourier carleson_phi vanishes on the CLOSED complement        *)
(* 1/5 <= abs y, not just the open 1/5 < abs y.  This is the knife-edge      *)
(* keystone: at the finest excluded scale k_sigma = m+1 the KILL separation  *)
(* is                                                                        *)
(* exactly (3/5)2^m (line 1616 uses >=, not >), so the support edge and      *)
(* cutoff                                                                    *)
(* meet at abs(arg) = 1/5 EXACTLY. The abstract spec only forces vanishing   *)
(* on                                                                        *)
(* the open ray, so we CLOSE it by continuity: fourier carleson_phi is       *)
(* Schwartz                                                                  *)
(* (SCHWARTZ_FOURIER), hence continuous, and vanishes on (1/5,inf);          *)
(* approaching                                                               *)
(* y (with 1/5 <= abs y) from OUTSIDE along y*(1+1/(n+1)) [abs strictly >    *)
(* abs y                                                                     *)
(* >= 1/5], LIM_RE_UBOUND gives Re(fhat y) <= 0, while the lower chi-bound   *)
(* gives                                                                     *)
(* Re >= 0 (abs y > 1/6), so Re = 0; fhat real => fhat y = 0.                *)
let CARLESON_PHI_FHAT_CLOSED = prove
 (`!y. &1 / &5 <= abs y ==> fourier carleson_phi y = Cx(&0)`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `carleson_phi` SCHWARTZ_FOURIER) THEN
  REWRITE_TAC[CARLESON_PHI_SCHWARTZ] THEN DISCH_TAC THEN
  STRIP_ASSUME_TAC carleson_phi THEN
  SUBGOAL_THEN `Re(fourier carleson_phi y) = &0` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_ARITH `x = &0 <=> x <= &0 /\ &0 <= x`] THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ISPEC `sequentially` LIM_RE_UBOUND) THEN
      EXISTS_TAC `\n. fourier carleson_phi (y * (&1 + inv(&n + &1)))` THEN
      REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY] THEN CONJ_TAC THENL
       [MP_TAC(ISPECL [`carleson_phi`; `y:real`] FOURIER_CONTINUOUS_SEQ) THEN
        ANTS_TAC THENL
         [CONJ_TAC THENL
           [X_GEN_TAC `y':real` THEN
            MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
            MP_TAC(ISPEC `carleson_phi` FOURIER_MODULATE_ABSINT) THEN
            REWRITE_TAC[ETA_AX; CARLESON_PHI_SCHWARTZ] THEN
            DISCH_THEN(MP_TAC o SPEC `y':real`) THEN REWRITE_TAC[];
            MP_TAC(ISPEC `carleson_phi` SCHWARTZ_ABSINT) THEN
            REWRITE_TAC[CARLESON_PHI_SCHWARTZ] THEN
            DISCH_THEN(MP_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_NORM) THEN
            REWRITE_TAC[o_DEF] THEN
            SIMP_TAC[ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE]];
          DISCH_THEN(MP_TAC o SPEC `\n. y * (&1 + inv(&n + &1))`) THEN
          REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
          REWRITE_TAC[REAL_ADD_LDISTRIB; REAL_MUL_RID] THEN
          SUBST1_TAC(REAL_ARITH `y = y + &0`) THEN
          MATCH_MP_TAC REALLIM_ADD THEN
          REWRITE_TAC[REAL_ADD_RID; REALLIM_CONST] THEN
          MATCH_MP_TAC REALLIM_NULL_LMUL THEN
            REWRITE_TAC[REALLIM_1_OVER_N_OFFSET]];
        REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
        X_GEN_TAC `n:num` THEN DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `y * (&1 + inv(&n + &1))`) THEN
        SUBGOAL_THEN `&1 / &5 < abs(y * (&1 + inv(&n + &1)))` MP_TAC THENL
         [REWRITE_TAC[REAL_ABS_MUL] THEN
          SUBGOAL_THEN `&1 < abs(&1 + inv(&n + &1))` ASSUME_TAC THENL
           [MATCH_MP_TAC(REAL_ARITH `&0 < i ==> &1 < abs(&1 + i)`) THEN
            MATCH_MP_TAC REAL_LT_INV THEN REAL_ARITH_TAC;
            ALL_TAC] THEN
          MATCH_MP_TAC REAL_LTE_TRANS THEN
          EXISTS_TAC `&1 / &5 * abs(&1 + inv(&n + &1))` THEN CONJ_TAC THENL
           [GEN_REWRITE_TAC LAND_CONV [GSYM REAL_MUL_RID] THEN
            MATCH_MP_TAC REAL_LT_LMUL THEN
            CONJ_TAC THENL [REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
            MATCH_MP_TAC REAL_LE_RMUL THEN
            CONJ_TAC THENL [ASM_REAL_ARITH_TAC; REAL_ARITH_TAC]];
          DISCH_TAC THEN COND_CASES_TAC THENL
           [ASM_REAL_ARITH_TAC; REWRITE_TAC[]]]];
      FIRST_X_ASSUM(K ALL_TAC o SPEC `y:real`) THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN
      COND_CASES_TAC THENL [ASM_REAL_ARITH_TAC; REAL_ARITH_TAC]];
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REAL] o SPEC `y:real`) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC COMPLEX_RING]);;

(* ------------------------------------------------------------------------- *)
(* Fremlin 286H(v): psicheck, the inverse Fourier transform of the           *)
(* m-cutoff multiplier psi.  Fremlin: psicheck(x) = 3*2^m e^{ix yhat}        *)
(* phi(3*2^m x), i.e. 3*2^m M_yhat D_{3*2^m} phi -- an                       *)
(* affine-reparametrized,                                                    *)
(* modulated, scaled copy of the base test function.  scal = 3*2^m > 0.      *)
(* ------------------------------------------------------------------------- *)
(* The m-cutoff frequency multiplier cpsi (Fremlin 286H(i)).                 *)
(* cpsi(y) = phihat((1/3) 2^{-m}(y - yhat)), the frequency-domain cutoff     *)
(* whose inverse transform is (1/sqrt2pi) psicheck.  Parametrized by scale   *)
(* m:int and anchor yhat:real.                                               *)
let cpsi = new_definition
 `cpsi (m:int) (yhat:real) (y:real) =
    fourier carleson_phi ((&1 / &3) * &2 zpow (--m) * (y - yhat))`;;

(* cpsi = 1 on the band abs(y - yhat) <= 2^m/2 (Fremlin (h)(ii)): there the  *)
(* argument (1/3)2^{-m}(y-yhat) has absolute value <= 1/6, where phihat = 1. *)
let CPSI_ONE = prove
 (`!m yhat y. abs(y - yhat) <= &2 zpow m / &2 ==> cpsi m yhat y = Cx(&1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cpsi] THEN
    MATCH_MP_TAC CARLESON_PHI_FHAT_ONE THEN
  SUBGOAL_THEN `&0 < &2 zpow m` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_ZPOW_NEG; REAL_ABS_MUL; REAL_ABS_INV] THEN
  SUBGOAL_THEN `abs(&2 zpow m) = &2 zpow m` SUBST1_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `inv(&2 zpow m) * abs(y - yhat) <= inv(&2 zpow m) * (&2 zpow m / &2)`
    MP_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN
     ASM_SIMP_TAC[REAL_LE_INV_EQ; REAL_LT_IMP_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `inv(&2 zpow m) * (&2 zpow m / &2) = &1 / &2` SUBST1_TAC THENL
   [REWRITE_TAC[real_div; REAL_MUL_ASSOC] THEN
    ASM_SIMP_TAC[REAL_MUL_LINV; REAL_LT_IMP_NZ] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* cpsi = 0 outside the band abs(y - yhat) > 3 2^m/5 (Fremlin (h)(iii)       *)
(* support side): there abs((1/3)2^{-m}(y-yhat)) > 1/5, beyond phihat's      *)
(* support.                                                                  *)
let CPSI_ZERO_CLOSED = prove
 (`!m yhat y. &3 * &2 zpow m / &5 <= abs(y - yhat) ==> cpsi m yhat y = Cx(&0)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cpsi] THEN
  MP_TAC(ISPEC `(&1 / &3) * &2 zpow (--m) * (y - yhat)`
    CARLESON_PHI_FHAT_CLOSED) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow m` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_ZPOW_NEG; REAL_ABS_MUL; REAL_ABS_INV] THEN
  SUBGOAL_THEN `abs(&2 zpow m) = &2 zpow m` SUBST1_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `inv(&2 zpow m) * (&3 * &2 zpow m / &5) <= inv(&2 zpow m) * abs(y - yhat)`
    MP_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN
     ASM_SIMP_TAC[REAL_LT_INV_EQ; REAL_LT_IMP_LE]; ALL_TAC] THEN
  SUBGOAL_THEN
    `inv(&2 zpow m) * (&3 * &2 zpow m / &5) = &3 / &5` SUBST1_TAC THENL
   [REWRITE_TAC[real_div] THEN
    ONCE_REWRITE_TAC[REAL_ARITH `i * (&3 * M * f) = (&3 * f) * (i * M)`] THEN
    ASM_SIMP_TAC[REAL_MUL_LINV; REAL_LT_IMP_NZ] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `abs(&1 / &3) = &1 / &3` SUBST1_TAC THENL
    [REAL_ARITH_TAC; ALL_TAC] THEN
  REAL_ARITH_TAC);;

let psicheck = new_definition
 `psicheck (scal:real) (yhat:real) (phi:real->complex) (x:real) =
    Cx scal * cexp(ii * Cx yhat * Cx x) * phi(scal * x)`;;

(* psicheck of a Schwartz phi is Schwartz (scal>0): SCHWARTZ_AFFINE          *)
(* (s=scal), then SCHWARTZ_MODULATE (b=yhat), then SCHWARTZ_CMUL (c=Cx       *)
(* scal).                                                                    *)
let PSICHECK_SCHWARTZ = prove
 (`!(phi:real->complex) scal yhat. schwartz phi /\ &0 < scal
     ==> schwartz (psicheck scal yhat phi)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `psicheck scal yhat (phi:real->complex) =
                (\x. Cx scal * cexp(ii * Cx yhat * Cx x) * phi(scal * x))`
                  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; psicheck]; ALL_TAC] THEN
  MATCH_MP_TAC SCHWARTZ_CMUL THEN
  MP_TAC(ISPECL [`\x. (phi:real->complex)(scal * x)`;
    `yhat:real`] SCHWARTZ_MODULATE) THEN
  ANTS_TAC THENL
   [MP_TAC(ISPECL [`phi:real->complex`; `scal:real`;
     `&0`] SCHWARTZ_AFFINE) THEN
    ASM_SIMP_TAC[REAL_LT_IMP_NZ; REAL_ADD_LID; ETA_AX];
    MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM]]);;

(* M4 (part h step v) DUALITY: the Fourier transform of psicheck is cpsi.    *)
(*   fourier (psicheck (3*2^m) yhat carleson_phi) y = cpsi m yhat y.         *)
(* psicheck = 3*2^m M_yhat D_{3*2^m} phi, so its transform is                *)
(* 3*2^m * (1/(3*2^m)) S_{-yhat} D_{1/(3*2^m)} phihat =                      *)
(* phihat((y-yhat)/(3*2^m))                                                  *)
(* = cpsi. FOURIER_LMUL (pull Cx(3*2^m)) + FOURIER_MODULATION (shift by      *)
(* yhat,                                                                     *)
(* unconditional) + FOURIER_DILATION (scale 3*2^m); integrability of the     *)
(* dilated/modulated Schwartz factors via FOURIER_MODULATE_ABSINT. This is   *)
(* the                                                                       *)
(* bridge that makes gt_m = (1/sqrt2pi)(gt * psicheck) (step C).             *)
let PSICHECK_FOURIER = prove
 (`!m yhat y.
     fourier (psicheck (&3 * &2 zpow m) yhat carleson_phi) y = cpsi m yhat y`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `&0 < &3 * &2 zpow m` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC]; ALL_TAC] THEN
  ABBREV_TAC `c = &3 * &2 zpow m` THEN
  SUBGOAL_THEN
    `schwartz (\x. (carleson_phi:real->complex)(c * x))` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`carleson_phi`; `c:real`; `&0`] SCHWARTZ_AFFINE) THEN
    ASM_SIMP_TAC[REAL_LT_IMP_NZ; REAL_ADD_LID; ETA_AX; CARLESON_PHI_SCHWARTZ];
      ALL_TAC] THEN
  SUBGOAL_THEN
   `schwartz (\x. cexp(ii * Cx yhat * Cx x) * (carleson_phi:real->complex)(c *
     x))`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\x. (carleson_phi:real->complex)(c * x)`;
     `yhat:real`] SCHWARTZ_MODULATE) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM]; ALL_TAC] THEN
  SUBGOAL_THEN `psicheck c yhat (carleson_phi:real->complex) =
                (\x. Cx c * cexp(ii * Cx yhat * Cx x) * carleson_phi(c * x))`
                  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; psicheck]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\x. cexp(ii * Cx yhat * Cx x) *
    (carleson_phi:real->complex)(c * x)`;
                 `Cx c`; `y:real`] FOURIER_LMUL) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MP_TAC(ISPECL [`\x. cexp(ii * Cx yhat * Cx x) *
      (carleson_phi:real->complex)(c * x)`; `y:real`]
      FOURIER_MODULATE_ABSINT) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[ETA_AX];
    ALL_TAC] THEN
  REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`\x. (carleson_phi:real->complex)(c * x)`; `yhat:real`;
    `y:real`]
    FOURIER_MODULATION) THEN
  REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(SPECL [`carleson_phi`; `c:real`;
    `y - yhat:real`] FOURIER_DILATION) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MP_TAC(SPECL [`carleson_phi`;
        `((y:real) - yhat) / c`] FOURIER_MODULATE_ABSINT) THEN
      REWRITE_TAC[CARLESON_PHI_SCHWARTZ]];
    DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[cpsi] THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC; GSYM CX_MUL] THEN
  SUBGOAL_THEN `c * &1 / c = &1` SUBST1_TAC THENL
   [ASM_SIMP_TAC[REAL_FIELD `&0 < c ==> c * &1 / c = &1`]; ALL_TAC] THEN
  REWRITE_TAC[CX_MUL; COMPLEX_MUL_LID] THEN AP_TERM_TAC THEN
  EXPAND_TAC "c" THEN REWRITE_TAC[REAL_ZPOW_NEG] THEN
  SUBGOAL_THEN `&0 < &2 zpow m` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[real_div] THEN
  ASM_SIMP_TAC[REAL_FIELD
   `&0 < p ==> (y - yhat) * inv(&3 * p) = &1 * inv(&3) * inv p * (y - yhat)`]
     THEN
  REWRITE_TAC[REAL_MUL_ASSOC]);;

(* M6 brick: the pointwise modulus of psicheck.  The modulation factor       *)
(* cexp(ii yhat t) has modulus 1, so |psicheck scal yhat phi t| = |scal|     *)
(* |phi(scal t)|.                                                            *)
(* Feeds Fremlin (h)(vi): (1/sqrt2pi) int |gt(x-t)| |psicheck(t)| =          *)
(* (3 2^m/sqrt2pi) int |gt(x-t)| |phi(3 2^m t)|.                             *)
let PSICHECK_NORM = prove
 (`!scal yhat (phi:real->complex) t.
     norm(psicheck scal yhat phi t) = abs scal * norm(phi(scal * t))`,
  REWRITE_TAC[psicheck; COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `ii * Cx yhat * Cx t = ii * Cx(yhat * t)` ASSUME_TAC THENL
   [REWRITE_TAC[CX_MUL] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  ASM_REWRITE_TAC[NORM_CEXP_II; REAL_MUL_LID]);;

(* M4 brick (part h step v / 283G everywhere-uniqueness): the Fourier        *)
(* transform                                                                 *)
(* is injective on Schwartz functions. Apply DOUBLE_TRANSFORM (inversion) on *)
(* both sides: f x = fourier(fourier f)(-x) = fourier(fourier g)(-x) = g x.  *)
let FOURIER_VSUM = prove
 (`!(s:A->bool) (f:A->real->complex) y.
     FINITE s /\ (!i. i IN s ==> schwartz (f i))
     ==> fourier (\x. vsum s (\i. f i x)) y = vsum s (\i. fourier (f i) y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[fourier] THEN
  ASM_SIMP_TAC[VSUM_COMPLEX_LMUL] THEN AP_TERM_TAC THEN
  SUBGOAL_THEN
   `(\x. cexp (--(ii * Cx y * Cx (drop x))) * vsum s (\i. (f:A->real->complex)
     i (drop x))) =
    (\x. vsum s (\i. cexp (--(ii * Cx y * Cx (drop x))) * f i (drop x)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     ASM_SIMP_TAC[VSUM_COMPLEX_LMUL]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\i:A. \x:real^1. cexp (--(ii * Cx y * Cx (drop x))) * (f:A->real->complex)
     i (drop x)`;
    `(:real^1)`; `s:A->bool`] INTEGRAL_VSUM) THEN
  ASM_SIMP_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  X_GEN_TAC `i:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC FOURIER_MODULATE_ABSINT THEN
  REWRITE_TAC[ETA_AX] THEN ASM_SIMP_TAC[]);;

(* M4 brick: the Fourier transform of a tile-tree reconstruction pushes onto *)
(* the individual tile transforms.  For any FINITE index set Q,              *)
(* (vsum Q (\s. c_s phi_sigma_s))^ (y) = vsum Q (\s. c_s phihat_sigma_s(y)). *)
(* FOURIER_VSUM (each summand Schwartz via SCHWARTZ_CMUL + PHISIG_SCHWARTZ)  *)
(* then                                                                      *)
(* FOURIER_LMUL termwise (modulated phi_sigma integrable via                 *)
(* FOURIER_MODULATE_                                                         *)
(* ABSINT). The backbone for gt_m^ = cpsi*gt^ (step (iv) summed over the     *)
(* tree).                                                                    *)
let FTILDE_FHAT = prove
 (`!(c:(int#int#int)->complex) (Q:(int#int#int)->bool) y. FINITE Q
     ==> fourier (\x. vsum Q (\s. c s * phi_sigma s carleson_phi x)) y =
         vsum Q (\s. c s * fourier (phi_sigma s carleson_phi) y)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`Q:(int#int#int)->bool`;
                 `\s:int#int#int. \x. c s * phi_sigma s carleson_phi x`;
                   `y:real`]
    FOURIER_VSUM) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
    MATCH_MP_TAC SCHWARTZ_CMUL THEN REWRITE_TAC[ETA_AX] THEN
    MATCH_MP_TAC PHISIG_SCHWARTZ THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN MATCH_MP_TAC VSUM_EQ THEN
  X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN BETA_TAC THEN
  MATCH_MP_TAC FOURIER_LMUL THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC FOURIER_MODULATE_ABSINT THEN
  REWRITE_TAC[ETA_AX] THEN
  MATCH_MP_TAC PHISIG_SCHWARTZ THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ]);;

(* 286E b-i, concrete: ||phi_sigma s carleson_phi||_2 = ||carleson_phi||_2.  *)
let PHISIG_CARLESON_L2 = prove
 (`!(s:int#int#int). lnorm (:real^1) (&2) (\z. phi_sigma s carleson_phi (drop
   z)) =
                     lnorm (:real^1) (&2) (\z. carleson_phi (drop z))`,
  GEN_TAC THEN MATCH_MP_TAC PHISIG_L2 THEN
    REWRITE_TAC[CARLESON_PHI_SCHWARTZ]);;

(* 286E b-iii, TILE-NATIVE: the frequency support of phi_sigma s             *)
(* carleson_phi                                                              *)
(* lies inside tile_J s. tile_J s = [nJ 2^k,(nJ+1)2^k); the modulation       *)
(* anchor                                                                    *)
(* ymid = dyho_mid(k-1)(2nJ) = (nJ+1/4)2^k (Fremlin's lower quartile y^l,    *)
(* the                                                                       *)
(* midpoint of J^l), and the support half-width is 2^k/5, so the support     *)
(* [(nJ+1/4-1/5)2^k,(nJ+1/4+1/5)2^k] = [(nJ+1/20)2^k,(nJ+9/20)2^k] fits in   *)
(* J.                                                                        *)
let PHISIG_CARLESON_SUPP_IN_JL = prove
 (`!(s:int#int#int) y. ~(y IN tile_Jl s)
     ==> fourier (phi_sigma s carleson_phi) y = Cx(&0)`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
    MAP_EVERY X_GEN_TAC [`k:int`;`nI:int`;`nJ:int`] THEN
  GEN_TAC THEN
    REWRITE_TAC[tile_Jl; dyho; IN_ELIM_THM; DE_MORGAN_THM; REAL_NOT_LE] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`(k,nI,nJ):int#int#int`; `carleson_phi`; `--(&1 / &5)`;
    `&1 / &5`]
    PHISIG_FHAT_SUPPORT) THEN
  REWRITE_TAC[CARLESON_PHI_SCHWARTZ; CARLESON_PHI_SUPP_CD] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  REWRITE_TAC[tile_ymid; tile_k; dyho_mid] THEN
  SUBGOAL_THEN `&2 zpow (k - &1) = &2 zpow k / &2` SUBST1_TAC THENL
   [SIMP_TAC[REAL_ZPOW_SUB; REAL_ZPOW_1; REAL_OF_NUM_EQ; ARITH_EQ];
     ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE
   [MESON[REAL_ZPOW_SUB; REAL_ZPOW_1; REAL_OF_NUM_EQ; ARITH_EQ]
      `&2 zpow (k - &1) = &2 zpow k / &2`]) THEN
  SUBGOAL_THEN
    `real_of_int (&2 * nJ) = &2 * real_of_int nJ` SUBST_ALL_TAC THENL
   [REWRITE_TAC[int_mul_th; int_of_num_th]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `M = &2 zpow k` THEN
  FIRST_X_ASSUM DISJ_CASES_TAC THENL [DISJ1_TAC; DISJ2_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* M4 step (iv), pointwise, k_sigma<=m case: if the whole left-half tile     *)
(* J^l_s                                                                     *)
(* sits inside the cpsi=1 band [yhat +- 2^m/2], then phihat_s * cpsi =       *)
(* phihat_s                                                                  *)
(* pointwise. On J^l_s cpsi=1 (CPSI_ONE); off J^l_s phihat_s=0 (SUPP_IN_JL). *)
(* The band-containment (tile-geometry from J_s SUBSET Jhat) is a            *)
(* hypothesis.                                                               *)
let PHISIG_CPSI_KEEP = prove
 (`!(s:int#int#int) m yhat y.
     (!z. z IN tile_Jl s ==> abs(z - yhat) <= &2 zpow m / &2)
     ==> fourier (phi_sigma s carleson_phi) y * cpsi m yhat y =
         fourier (phi_sigma s carleson_phi) y`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `(y:real) IN tile_Jl s` THENL
   [SUBGOAL_THEN
     `cpsi m yhat y = Cx(&1)` (fun th -> REWRITE_TAC[th; COMPLEX_MUL_RID]) THEN
    MATCH_MP_TAC CPSI_ONE THEN ASM_SIMP_TAC[];
    SUBGOAL_THEN `fourier (phi_sigma s carleson_phi) y = Cx(&0)`
      (fun th -> REWRITE_TAC[th; COMPLEX_MUL_LZERO]) THEN
    MATCH_MP_TAC PHISIG_CARLESON_SUPP_IN_JL THEN ASM_REWRITE_TAC[]]);;

(* M4 step (iv), pointwise, k_sigma>m case: if J^l_s sits in the cpsi=0      *)
(* region (abs(z-yhat) > 3 2^m/5 for all z in J^l_s), then phihat_s * cpsi = *)
(* 0.                                                                        *)
let DYHO_MEM_BAND = prove
 (`!(mm:int) (nhat:int) (z:real).
     z IN dyho mm nhat ==> abs(z - dyho_mid mm nhat) <= &2 zpow mm / &2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; dyho_mid; IN_ELIM_THM] THEN
  SUBGOAL_THEN `&0 < &2 zpow mm` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `(real_of_int nhat + &1 / &2) * &2 zpow mm - &2 zpow mm / &2 =
                real_of_int nhat * &2 zpow mm` ASSUME_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(real_of_int nhat + &1 / &2) * &2 zpow mm + &2 zpow mm / &2 =
                (real_of_int nhat + &1) * &2 zpow mm` ASSUME_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* M4 step (iv) KEEP, geometric form: if the left-half tile J^l_s sits       *)
(* inside                                                                    *)
(* the length-2^mm dyadic interval Jhat = dyho mm nhat (anchor yhat = its    *)
(* midpoint), then phihat_s * cpsi = phihat_s pointwise. Reduces KEEP's band *)
(* hypothesis to the dyadic containment J^l_s SUBSET Jhat (Fremlin (h)(ii)). *)
let PHISIG_CPSI_KEEP_GEOM = prove
 (`!(s:int#int#int) mm nhat y.
     tile_Jl s SUBSET dyho mm nhat
     ==> fourier (phi_sigma s carleson_phi) y * cpsi mm (dyho_mid mm nhat) y =
         fourier (phi_sigma s carleson_phi) y`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC PHISIG_CPSI_KEEP THEN
  X_GEN_TAC `z:real` THEN DISCH_TAC THEN
  MATCH_MP_TAC DYHO_MEM_BAND THEN ASM SET_TAC[]);;

(* M4 (h)(iii) SHARP support: fourier(phi_sigma s carleson_phi) vanishes     *)
(* outside                                                                   *)
(* [tile_ymid s - (1/5)2^k, tile_ymid s + (1/5)2^k] (half-width (1/5)muJ     *)
(* about                                                                     *)
(* the lower-quartile anchor y^l_sigma = tile_ymid). Direct                  *)
(* PHISIG_FHAT_SUPPORT                                                       *)
(* at c=-1/5,d=1/5 (carleson_phi support); keeps the sharp bounds, unlike    *)
(* SUPP_IN_JL which weakens to J^l. Needed for the KILL side's 1/20 muJ      *)
(* slack.                                                                    *)
let PHISIG_CARLESON_SUPP_CLOSED = prove
 (`!(s:int#int#int) y.
     y <= tile_ymid s - &1 / &5 * &2 zpow (tile_k s) \/
     tile_ymid s + &1 / &5 * &2 zpow (tile_k s) <= y
     ==> fourier (phi_sigma s carleson_phi) y = Cx(&0)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_SIMP_TAC[PHISIG_FHAT; CARLESON_PHI_SCHWARTZ] THEN
  SUBGOAL_THEN
    `fourier carleson_phi ((y - tile_ymid s) / &2 zpow (tile_k s)) = Cx(&0)`
    SUBST1_TAC THENL
   [MATCH_MP_TAC CARLESON_PHI_FHAT_CLOSED THEN
    SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_ABS_DIV] THEN
    SUBGOAL_THEN
      `abs(&2 zpow (tile_k s)) = &2 zpow (tile_k s)` SUBST1_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN ASM_REAL_ARITH_TAC;
    CONV_TAC COMPLEX_RING]);;

(* M4 step (iv) KILL, sharp-support form: if the whole sharp frequency       *)
(* support [tile_ymid s +- (1/5)2^k] lies in the cpsi=0 region abs(z-yhat) > *)
(* 3 2^m/5, then phihat_s * cpsi = 0 pointwise (CPSI_ZERO on supp, else      *)
(* SUPP_SHARP).                                                              *)
let PHISIG_CPSI_KILL_CLOSED = prove
 (`!(s:int#int#int) m yhat y.
     (!z. tile_ymid s - &1 / &5 * &2 zpow (tile_k s) <= z /\
          z <= tile_ymid s + &1 / &5 * &2 zpow (tile_k s)
          ==> &3 * &2 zpow m / &5 <= abs(z - yhat))
     ==> fourier (phi_sigma s carleson_phi) y * cpsi m yhat y = Cx(&0)`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC
   `tile_ymid s - &1 / &5 * &2 zpow (tile_k s) <= y /\
    y <= tile_ymid s + &1 / &5 * &2 zpow (tile_k s)` THENL
   [SUBGOAL_THEN
     `cpsi m yhat y =
      Cx(&0)` (fun th -> REWRITE_TAC[th; COMPLEX_MUL_RZERO]) THEN
    MATCH_MP_TAC CPSI_ZERO_CLOSED THEN ASM_SIMP_TAC[];
    SUBGOAL_THEN `fourier (phi_sigma s carleson_phi) y = Cx(&0)`
      (fun th -> REWRITE_TAC[th; COMPLEX_MUL_LZERO]) THEN
    MATCH_MP_TAC PHISIG_CARLESON_SUPP_CLOSED THEN ASM_REAL_ARITH_TAC]);;

(* 286E b-iv, TILE-NATIVE: phi_sigma at two tiles with DISJOINT frequency    *)
(* intervals tile_J are orthogonal (each support sits inside its own         *)
(* tile_J).                                                                  *)
let PHISIG_CARLESON_ORTHO_JL = prove
 (`!(s:int#int#int) (t:int#int#int). DISJOINT (tile_Jl s) (tile_Jl t)
     ==> integral (:real^1)
           (\z. phi_sigma s carleson_phi (drop z) *
                cnj(phi_sigma t carleson_phi (drop z))) = Cx(&0)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC SCHWARTZ_ORTHO_DISJOINT_FHAT THEN
  REWRITE_TAC[ETA_AX] THEN
    SIMP_TAC[PHISIG_SCHWARTZ; CARLESON_PHI_SCHWARTZ] THEN
  X_GEN_TAC `u:real` THEN ASM_CASES_TAC `(u:real) IN tile_Jl s` THENL
   [DISJ2_TAC THEN MATCH_MP_TAC PHISIG_CARLESON_SUPP_IN_JL THEN
    ASM_MESON_TAC[DISJOINT; IN_INTER; NOT_IN_EMPTY; EXTENSION];
    DISJ1_TAC THEN MATCH_MP_TAC PHISIG_CARLESON_SUPP_IN_JL THEN
      ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286G(e-f): the KERNEL BOUNDS -- the test function is dominated pointwise  *)
(* by                                                                        *)
(* the tile weight. norm(phi_sigma s carleson_phi x)^2 <= C cw_tile s x. The *)
(* mass/energy estimates of M3 use this to reduce tile correlations to the   *)
(* summable weight cw. Foundations: a Schwartz function decays like          *)
(* C/(1+u^2)                                                                 *)
(* (SCHWARTZ_DECAY_EXISTS from the k=0,k=2 bounds), and (1+|u|)^3 <=         *)
(* 4(1+u^2)^2                                                                *)
(* (CUBE_LE_SQSQ, via the degree-4 positivity POLY43_BOUND) gives            *)
(* inv(1+u^2)^2 <= 4 cw u (INVSQ_LE_CW).                                     *)
(* ------------------------------------------------------------------------- *)

(* Degree-4 positivity: 4t^4 - t^3 + 5t^2 - 3t + 3 >= 0 for t >= 0. Split at *)
(* t = 1 (t^3 <= t^2 below, t^3 <= t^4 above) + the square 4t^2 - 4t + 1 >=  *)
(* 0.                                                                        *)
let SCHWARTZ_DECAY_EXISTS = prove
 (`!h:real->complex. schwartz h
     ==> ?C. &0 <= C /\ !u. norm(h u) <= C * inv(&1 + u pow 2)`,
  GEN_TAC THEN REWRITE_TAC[schwartz] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num->real->complex` STRIP_ASSUME_TAC) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B0:real` o SPECL [`0`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B2:real` o SPECL [`2`; `0`]) THEN
  EXISTS_TAC `B0 + B2:real` THEN CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `&0`) THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `&0`) THEN
    MP_TAC(ISPEC `(d:num->real->complex) 0 (&0)` NORM_POS_LE) THEN
    REWRITE_TAC[real_pow; REAL_MUL_LID] THEN REAL_ARITH_TAC;
    X_GEN_TAC `u:real` THEN
    FIRST_ASSUM(SUBST1_TAC o SYM o check (fun th -> concl th =
      `(d:num->real->complex) 0 = h`)) THEN
    MATCH_MP_TAC SCHWARTZ_DECAY_DOMINATION THEN ASM_REWRITE_TAC[]]);;

(* 286G(e): base kernel bound  norm(carleson_phi u)^2 <= C cw u.             *)
let SUM_QUADRATIC_EXPAND = prove
 (`!(s:A->bool) f g y. FINITE s
     ==> sum s (\i. (f i * y + g i) pow 2) =
         sum s (\i. f i pow 2) * y pow 2 +
         &2 * sum s (\i. f i * g i) * y +
         sum s (\i. g i pow 2)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[GSYM SUM_LMUL; GSYM SUM_RMUL; GSYM SUM_ADD] THEN
  MATCH_MP_TAC SUM_EQ THEN REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN
    REAL_ARITH_TAC);;

let SUM_CAUCHY_SCHWARZ = prove
 (`!(s:A->bool) f g. FINITE s
     ==> (sum s (\i. f i * g i)) pow 2 <= (sum s (\i. f i pow 2)) * (sum s (\i.
       g i pow 2))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `A = sum s (\i. (f:A->real) i pow 2)` THEN
  ABBREV_TAC `B = sum s (\i. (f:A->real) i * g i)` THEN
  ABBREV_TAC `C = sum s (\i. (g:A->real) i pow 2)` THEN
  SUBGOAL_THEN `!y:real. &0 <= A * y pow 2 + &2 * B * y + C` ASSUME_TAC THENL
   [GEN_TAC THEN
    MP_TAC(ISPECL [`s:A->bool`; `f:A->real`; `g:A->real`;
      `y:real`] SUM_QUADRATIC_EXPAND) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC SUM_POS_LE THEN REWRITE_TAC[REAL_LE_POW_2];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= A` ASSUME_TAC THENL
   [EXPAND_TAC "A" THEN MATCH_MP_TAC SUM_POS_LE THEN
     REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= C` ASSUME_TAC THENL
   [EXPAND_TAC "C" THEN MATCH_MP_TAC SUM_POS_LE THEN
     REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= A * C` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `A = &0` THENL
   [SUBGOAL_THEN `B = &0` MP_TAC THENL
     [MATCH_MP_TAC(REAL_ARITH `~(&0 < abs B) ==> B = &0`) THEN DISCH_TAC THEN
      FIRST_X_ASSUM(fun th -> if is_forall(concl th)
        then MP_TAC(SPEC `--(C + &1) / (&2 * B):real` th) else NO_TAC) THEN
      ASM_REWRITE_TAC[REAL_MUL_LZERO; REAL_ADD_LID] THEN
      ASM_SIMP_TAC[REAL_FIELD `&0 < abs B ==> &2 * B * --(C + &1) / (&2 * B) +
        C = --(&1)`] THEN
      REAL_ARITH_TAC;
      DISCH_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
    SUBGOAL_THEN `&0 < A` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM(fun th -> if is_forall(concl th)
      then MP_TAC(SPEC `--B / A:real` th) else NO_TAC) THEN
    ASM_SIMP_TAC[REAL_FIELD
     `&0 < A ==> A * (--B / A) pow 2 + &2 * B * --B / A + C = C - B pow 2 / A`]
       THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `B pow 2 / A <= C` MP_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN REWRITE_TAC[REAL_MUL_SYM]]);;

(* WEIGHTED discrete Cauchy-Schwarz (the 286L energy x mass split).          *)
(* Inserting                                                                 *)
(* the trivial factor sqrt(w) * inv(sqrt(w)) = 1 into sum |a b| and applying *)
(* SUM_CAUCHY_SCHWARZ splits the bilinear sum into a w-weighted a-factor and *)
(* an                                                                        *)
(* inv(w)-weighted b-factor: (sum|a_i b_i|)^2 <= (sum w_i a_i^2)(sum w_i^-1  *)
(* b_i^2)                                                                    *)
(* for w_i > 0.  In 286L: w_i = 2 zpow k_s makes the a-factor the energy sum *)
(* (sum 2^k_s |(f|phi_s)|^2) and the b-factor the mass sum (sum 2^-k_s       *)
(* |int|^2).                                                                 *)
let SUM_FIBER_COUNT_2 = prove
 (`!(A:(int#int#int)->bool) (g:(int#int#int)->num) (ff:num->real) N M.
     FINITE A /\ (!n. &0 <= ff n) /\
     (!a. a IN A ==> g a IN N..M) /\
     (!n. CARD {a | a IN A /\ g a = n} <= 2)
     ==> sum A (\a. ff(g a)) <= &2 * sum (N..M) ff`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`g:(int#int#int)->num`;
    `\a:(int#int#int). (ff:num->real)(g a)`;
                 `A:(int#int#int)->bool`] SUM_IMAGE_GEN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (IMAGE (g:(int#int#int)->num) A) (\y. &2 * ff y)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_SIMP_TAC[FINITE_IMAGE] THEN
    X_GEN_TAC `y:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN
      `sum {x | x IN A /\ (g:(int#int#int)->num) x = y} (\a. ff(g a)) =
                  sum {x | x IN A /\ g x = y} (\a:int#int#int. ff y)`
                    SUBST1_TAC THENL
     [MATCH_MP_TAC SUM_EQ THEN SIMP_TAC[IN_ELIM_THM]; ALL_TAC] THEN
    ASM_SIMP_TAC[SUM_CONST; FINITE_RESTRICT] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[REAL_OF_NUM_LE];
    REWRITE_TAC[SUM_LMUL] THEN MATCH_MP_TAC REAL_LE_LMUL THEN
    CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[FINITE_NUMSEG];
      REWRITE_TAC[SUBSET; IN_IMAGE] THEN ASM_MESON_TAC[];
      X_GEN_TAC `n:num` THEN REWRITE_TAC[IN_DIFF] THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[]]]);;

(* 286L alpha0/alpha1 PER-SCALE WEIGHT SUM. If g : A -> num is <=2-to-1 with *)
(* range                                                                     *)
(* in N..M, then sum_{a in A} cw(&(g a) + 1/2) <= 1/(1 + &N)^2.              *)
(* SUM_FIBER_COUNT_2                                                         *)
(* bounds the sum by 2 sum_{N..M} cw(&n + 1/2); CW_SUM_BOUND bounds that     *)
(* tail by                                                                   *)
(* 1/(2(1+N)^2), and the 2 cancels the 1/2. In 286L: g = the nearest-edge    *)
(* offset                                                                    *)
(* of x_sigma past the cover cell K (so cw(&(g)+1/2) = w(2^k rho)); N =      *)
(* 2^{k-l_K},                                                                *)
(* giving Fremlin's sum_{k_sigma=k} w(2^k rho) <= (1 + 2^{k-l_K})^{-2}.      *)
let WEIGHT_OFFSET_SUM_BOUND = prove
 (`!(A:(int#int#int)->bool) g N M.
     FINITE A /\ (!a. a IN A ==> g a IN N..M) /\
     (!n. CARD {a | a IN A /\ g a = n} <= 2)
     ==> sum A (\a. cw(&(g a) + &1 / &2)) <= &1 / (&1 + &N) pow 2`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 * sum (N..M) (\n. cw(&n + &1 / &2))` THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`A:(int#int#int)->bool`; `g:(int#int#int)->num`;
                   `\n:num. cw(&n + &1 / &2)`; `N:num`;
                     `M:num`] SUM_FIBER_COUNT_2) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    GEN_TAC THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN REWRITE_TAC[CW_POS];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 * &1 / (&2 * (&1 + &N) pow 2)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; REWRITE_TAC[CW_SUM_BOUND]];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    SUBGOAL_THEN `&0 < (&1 + &N) pow 2` MP_TAC THENL
     [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC; CONV_TAC REAL_FIELD]]);;

(* 286L alpha0/alpha1 PER-SCALE ALPHA BOUND (abstract).  If each term f a is *)
(* dominated by B * cw(&(g a) + 1/2) with g a <=2-to-1 and range in N..M,    *)
(* then                                                                      *)
(* sum_A f <= B / (1 + N)^2. Combines a per-tile bound (SUM_LE termwise)     *)
(* with                                                                      *)
(* WEIGHT_OFFSET_SUM_BOUND (SUM_LMUL pulls out B, REAL_LE_LMUL). In 286L: f  *)
(* sigma =                                                                   *)
(* norm(alpha_sigma_K), B = C1 2^{-k} gamma gamma' (from                     *)
(* CARLESON_ALPHA_PAIR, since                                                *)
(* w(2^k rho) = cw(&(g sigma) + 1/2)), g = the nearest-edge offset, N =      *)
(* 2^{k-l_K};                                                                *)
(* gives the per-scale sum_{k_sigma=k} norm(alpha_sK) <= C1 2^{-k} gg'       *)
(* /(1+2^{k-lK})^2.                                                          *)
let ALPHA_SCALE_BOUND_ABSTRACT = prove
 (`!(A:(int#int#int)->bool) f g B N M.
     FINITE A /\ &0 <= B /\
     (!a. a IN A ==> f a <= B * cw(&(g a) + &1 / &2)) /\
     (!a. a IN A ==> g a IN N..M) /\
     (!n. CARD {a | a IN A /\ g a = n} <= 2)
     ==> sum A f <= B * &1 / (&1 + &N) pow 2`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (A:(int#int#int)->bool)
                  (\a. B * cw(&((g:(int#int#int)->num) a) + &1 / &2))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SUM_LMUL] THEN
    ONCE_REWRITE_TAC[REAL_ARITH `B * &1 / x = B * (&1 / x)`] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC WEIGHT_OFFSET_SUM_BOUND THEN
    EXISTS_TAC `M:num` THEN ASM_REWRITE_TAC[]]);;

(* SEPARATED-SET COUNTING: a set A whose x-values are pairwise >= d apart,   *)
(* all                                                                       *)
(* confined to a half-open window [c, c+d), has at most ONE element. (Two    *)
(* distinct                                                                  *)
(* elements would lie < d apart in the window, contradicting the >= d        *)
(* separation.)                                                              *)
(* This is the "at most one tile per side of the cover cell K, per offset"   *)
(* atom of                                                                   *)
(* the alpha0/alpha1 <=2-to-1 count: on each side of K the offset pins       *)
(* x_sigma to a                                                              *)
(* 2^{-k}-window, and the tree centres are 2^{-k}-separated                  *)
(* (TILE_TREE_SAMESCALE_                                                     *)
(* XMID_INJ). Two such windows (the two sides) give the CARD <= 2 for        *)
(* SUM_FIBER_                                                                *)
(* COUNT_2.                                                                  *)
let carleson_ip = new_definition
 `carleson_ip (f:real->complex) (s:int#int#int) =
    lproduct (:real^1) (\z. f(drop z)) (\z. phi_sigma s carleson_phi (drop
      z))`;;

(* Every element of a finite set has a maximal element above it, for any     *)
(* reflexive transitive relation R (a finite-poset maximal-above lemma; on   *)
(* tiles                                                                     *)
(* R = tile_le). 286J part (a) picks R = minimal witnesses = tile_le-MAXIMAL *)
(* representatives (Fremlin's <=-minimal, our reversed order). Induction on  *)
(* the                                                                       *)
(* finite set; the INSERT step: if the new element a lies R-above the        *)
(* recursively-                                                              *)
(* found maximal m (and nothing in S is R-above a) then a is the new         *)
(* maximal, else                                                             *)
(* m stays maximal. NB the relation var R MUST be fully type-annotated in    *)
(* every                                                                     *)
(* ASM_CASES/EXISTS tactic term -- a bare `R m a` invents a polymorphic type *)
(* for R                                                                     *)
(* and SPEC(EXCLUDED_MIDDLE) then fails "inventing type variables".          *)
let TILE_LE_MAXIMAL_ABOVE = prove
 (`!(R:(int#int#int)->(int#int#int)->bool) S.
     FINITE S /\ (!x. R x x) /\ (!x y z. R x y /\ R y z ==> R x z)
     ==> !s. s IN S ==> ?m. m IN S /\ R s m /\
                            (!n. n IN S /\ R m n ==> R n m)`,
  GEN_TAC THEN GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `FINITE (S:(int#int#int)->bool)` THEN
  SPEC_TAC(`S:(int#int#int)->bool`,`S:(int#int#int)->bool`) THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN
  REWRITE_TAC[NOT_IN_EMPTY] THEN
  MAP_EVERY X_GEN_TAC [`a:int#int#int`; `S:(int#int#int)->bool`] THEN
    STRIP_TAC THEN
  X_GEN_TAC `s:int#int#int` THEN REWRITE_TAC[IN_INSERT] THEN STRIP_TAC THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    ASM_CASES_TAC `?t:int#int#int. t IN S /\
                   (R:(int#int#int)->(int#int#int)->bool) a t` THENL
     [FIRST_X_ASSUM(X_CHOOSE_THEN `t:int#int#int` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN
       `?m:int#int#int. m IN S /\ R (t:int#int#int) m /\
                        (!n. n IN S /\ R m n ==> R n m)` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `m:int#int#int` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[];
        X_GEN_TAC `n:int#int#int` THEN
        DISCH_THEN(CONJUNCTS_THEN2 DISJ_CASES_TAC ASSUME_TAC) THEN
          ASM_MESON_TAC[]];
      EXISTS_TAC `a:int#int#int` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `n:int#int#int` THEN
      DISCH_THEN(CONJUNCTS_THEN2 DISJ_CASES_TAC ASSUME_TAC) THEN
        ASM_MESON_TAC[]];
    SUBGOAL_THEN
     `?m:int#int#int. m IN S /\ R (s:int#int#int) m /\
                      (!n. n IN S /\ R m n ==> R n m)` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_CASES_TAC `(R:(int#int#int)->(int#int#int)->bool) m a` THENL
     [ASM_CASES_TAC `?u:int#int#int. u IN S /\
                     (R:(int#int#int)->(int#int#int)->bool) a u` THENL
       [EXISTS_TAC `m:int#int#int` THEN ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `n:int#int#int` THEN
        DISCH_THEN(CONJUNCTS_THEN2 DISJ_CASES_TAC ASSUME_TAC) THEN
          ASM_MESON_TAC[];
        EXISTS_TAC `a:int#int#int` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [ASM_MESON_TAC[];
          X_GEN_TAC `n:int#int#int` THEN
          DISCH_THEN(CONJUNCTS_THEN2 DISJ_CASES_TAC ASSUME_TAC) THEN
            ASM_MESON_TAC[]]];
      EXISTS_TAC `m:int#int#int` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `n:int#int#int` THEN
      DISCH_THEN(CONJUNCTS_THEN2 DISJ_CASES_TAC ASSUME_TAC) THEN
        ASM_MESON_TAC[]]]);;

(* 286H mass: mass_{E,h}(P) = sup over sigma in P and tiles tau >= sigma of  *)
(* the                                                                       *)
(* weight w_tau = cw_tile tau integrated over E INTER h^-1[J_tau]. Bounded   *)
(* by 1                                                                      *)
(* since INT w_tau = 1.                                                      *)
let mass_Eh = new_definition
 `mass_Eh (E:real->bool) (h:real->real) (P:(int#int#int)->bool) =
    sup { real_integral {x | x IN E /\ h x IN tile_J t} (cw_tile t)
          | s,t | s IN P /\ tile_le s t }`;;

(* 286H energy:  energy_f(P) = sup over tiles tau of 2^(k_tau/2) times the   *)
(* l^2-aggregate sqrt(sum_{sigma in P, sigma <=_r tau} |(f|phi_sigma)|^2) of *)
(* the                                                                       *)
(* coefficients along the <=_r-tree below tau.  (2^(k/2) = sqrt(2 zpow k).)  *)
let energy_f = new_definition
 `energy_f (f:real->complex) (P:(int#int#int)->bool) =
    sup { sqrt(&2 zpow (tile_k t)) *
          sqrt(sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow
            2))
          | t IN (:int#int#int) }`;;

(* The integral of the tile weight over ANY set where it is integrable is <= *)
(* 1 (subset monotonicity + CW_TILE_FULL + cw_tile >= 0).                    *)
let CW_TILE_SUBSET_LE_1 = prove
 (`!(s:int#int#int) t. cw_tile s real_integrable_on t
     ==> real_integral t (cw_tile s) <= &1`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_SUBSET_LE THEN
  MAP_EVERY EXISTS_TAC [`cw_tile s`; `t:real->bool`; `(:real)`] THEN
  ASM_SIMP_TAC[SUBSET_UNIV; CW_TILE_FULL; REAL_INTEGRABLE_INTEGRAL] THEN
  REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`s:int#int#int`; `x:real`] CW_TILE_POS) THEN
  REAL_ARITH_TAC);;

(* 286H: mass_{E,h}(P) <= 1. Each term INT_{E cap h^-1[J_tau]} w_tau <=      *)
(* INT_R                                                                     *)
(* w_tau = 1; the sup of a nonempty set bounded by 1 is <= 1. The            *)
(* nonemptiness                                                              *)
(* (P nonempty, via tile_le reflexivity) and per-tile integrability are the  *)
(* explicit hypotheses that the 286I caller supplies (E measurable, P        *)
(* finite).                                                                  *)
let MASS_LE_1 = prove
 (`!(E:real->bool) (h:real->real) (P:(int#int#int)->bool).
     ~(P = {}) /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> mass_Eh E h P <= &1`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[mass_Eh] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[EXTENSION; NOT_FORALL_THM; IN_ELIM_THM; NOT_IN_EMPTY] THEN
    FIRST_X_ASSUM(X_CHOOSE_TAC `s0:int#int#int` o
      REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
    MAP_EVERY EXISTS_TAC
     [`real_integral {x | x IN E /\ h x IN tile_J s0} (cw_tile s0)`] THEN
    MAP_EVERY EXISTS_TAC [`s0:int#int#int`; `s0:int#int#int`] THEN
    ASM_REWRITE_TAC[TILE_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN
    MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN
    STRIP_TAC THEN MATCH_MP_TAC CW_TILE_SUBSET_LE_1 THEN ASM_REWRITE_TAC[]]);;

(* 286H: mass is MONOTONE in the tile set. P' SUBSET P ==> mass P' <= mass   *)
(* P.                                                                        *)
(* The P'-value-set is a subset of the P-value-set (same terms, fewer        *)
(* sigma);                                                                   *)
(* REAL_SUP_LE_SUBSET with nonemptiness (tile_le refl) and the bound 1       *)
(* above.                                                                    *)
let MASS_MONO = prove
 (`!(E:real->bool) h (P:(int#int#int)->bool) P'.
     P' SUBSET P /\ ~(P' = {}) /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> mass_Eh E h P' <= mass_Eh E h P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[mass_Eh] THEN
  MATCH_MP_TAC REAL_SUP_LE_SUBSET THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    FIRST_X_ASSUM(X_CHOOSE_TAC `s0:int#int#int` o REWRITE_RULE[GSYM
      MEMBER_NOT_EMPTY]) THEN
    EXISTS_TAC `real_integral {x | x IN E /\ h x IN tile_J s0} (cw_tile s0)`
      THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC [`s0:int#int#int`; `s0:int#int#int`] THEN
    ASM_REWRITE_TAC[TILE_LE_REFL];
    REWRITE_TAC[SUBSET; FORALL_IN_GSPEC] THEN
    MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN STRIP_TAC THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
      MAP_EVERY EXISTS_TAC [`s:int#int#int`; `t:int#int#int`] THEN
    ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    EXISTS_TAC `&1` THEN REWRITE_TAC[FORALL_IN_GSPEC] THEN
    MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN STRIP_TAC THEN
    MATCH_MP_TAC CW_TILE_SUBSET_LE_1 THEN ASM_REWRITE_TAC[]]);;

(* 286J part (a) core: mass_Eh E h S <= c whenever EVERY qualifying          *)
(* single-tile                                                               *)
(* integral (over the tile_le-cone above some s in S) is <= c. Direct        *)
(* REAL_SUP_LE                                                               *)
(* on the mass_Eh sup (index nonempty since S nonempty: t := s,              *)
(* TILE_LE_REFL). In                                                         *)
(* 286J this turns the Vitali conclusion "P\R+ SUBSET {sigma :               *)
(* mass({sigma})<=gam/4}"                                                    *)
(* into mass_Eh(P\R+) <= gam/4.                                              *)
let MASS_EH_LE = prove
 (`!(E:real->bool) h (S:(int#int#int)->bool) c.
     ~(S = {}) /\
     (!s t. s IN S /\ tile_le s t
            ==> real_integral {x | x IN E /\ h x IN tile_J t} (cw_tile t) <= c)
     ==> mass_Eh E h S <= c`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[mass_Eh] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    FIRST_X_ASSUM(X_CHOOSE_TAC `s0:int#int#int` o REWRITE_RULE[GSYM
      MEMBER_NOT_EMPTY]) THEN
    EXISTS_TAC `real_integral {x | x IN E /\ h x IN tile_J s0} (cw_tile s0)`
      THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC [`s0:int#int#int`; `s0:int#int#int`] THEN
    ASM_REWRITE_TAC[TILE_LE_REFL];
    REWRITE_TAC[IN_ELIM_THM] THEN
    X_GEN_TAC `y:real` THEN
    DISCH_THEN(REPEAT_TCL CHOOSE_THEN
      (CONJUNCTS_THEN2 STRIP_ASSUME_TAC SUBST1_TAC)) THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN EXISTS_TAC `s:int#int#int` THEN
    ASM_REWRITE_TAC[]]);;

(* 286J part (a) witness: mass_Eh{sigma} > c ==> some tile t >= sigma has    *)
(* int_{E cap h^-1[J_t]} w_t > c.  SUP_APPROACH on the mass_Eh{sigma} sup    *)
(* (nonempty t:=sigma; bounded by 1 via CW_TILE_SUBSET_LE_1). Picks          *)
(* Fremlin's                                                                 *)
(* witnessing tile sigma' for each large-single-mass sigma in the            *)
(* R-selection.                                                              *)
let MASS_EH_WITNESS = prove
 (`!(E:real->bool) h sigma c.
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
     c < mass_Eh E h {sigma}
     ==> ?t. tile_le sigma t /\
             c < real_integral {x | x IN E /\ h x IN tile_J t} (cw_tile t)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`{ real_integral {x | x IN E /\ h x IN tile_J t} (cw_tile t)
       | s,t | s IN {sigma:int#int#int} /\ tile_le s t }`; `c:real`]
   SUP_APPROACH) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      EXISTS_TAC `real_integral {x | x IN E /\ h x IN tile_J sigma} (cw_tile
        sigma)` THEN
      MAP_EVERY EXISTS_TAC [`sigma:int#int#int`; `sigma:int#int#int`] THEN
      REWRITE_TAC[IN_SING; TILE_LE_REFL];
      EXISTS_TAC `&1` THEN REWRITE_TAC[FORALL_IN_GSPEC; IN_SING] THEN
      MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN
        STRIP_TAC THEN
      MATCH_MP_TAC CW_TILE_SUBSET_LE_1 THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[GSYM mass_Eh]];
    REWRITE_TAC[IN_ELIM_THM; IN_SING] THEN
    DISCH_THEN(X_CHOOSE_THEN `v:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `t:int#int#int` THEN CONJ_TAC THENL
     [ASM_MESON_TAC[];
      FIRST_X_ASSUM(fun th -> SUBST1_TAC(SYM th)) THEN ASM_REWRITE_TAC[]]]);;

(* 286H mass, single-term lower bound: for sigma in P, the tile-weight       *)
(* integral                                                                  *)
(* over E cap h^-1[J_sigma] is <= mass_Eh E h P. The (s,t) = (sigma,sigma)   *)
(* term                                                                      *)
(* of the mass sup (tile_le reflexive); upper bound 1 via                    *)
(* CW_TILE_SUBSET_LE_1.                                                      *)
(* This is how the mass factor gamma' enters the 286L(c-i) kernel estimate.  *)
let MASS_TERM_LE = prove
 (`!(E:real->bool) h (P:(int#int#int)->bool) sigma.
     sigma IN P /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> real_integral {x | x IN E /\ h x IN tile_J sigma} (cw_tile sigma)
         <= mass_Eh E h P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[mass_Eh] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC
   [`&1`;
    `real_integral {x | x IN E /\ h x IN tile_J sigma} (cw_tile sigma)`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC [`sigma:int#int#int`; `sigma:int#int#int`] THEN
    ASM_REWRITE_TAC[TILE_LE_REFL];
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN
    MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN STRIP_TAC THEN
    MATCH_MP_TAC CW_TILE_SUBSET_LE_1 THEN ASM_REWRITE_TAC[]]);;

(* Generalisation of MASS_TERM_LE to any ups ABOVE a P-element (Fremlin mass *)
(* sup is over sigma in P, tau <= sigma -- my tile_le sigma ups, the         *)
(* (s,t)=(sigma,ups) term). This is the gamma' bound int_{E cap g^-1[J_ups]} *)
(* w_ups <= mass_Eh used in 286L(e).                                         *)
let MASS_TERM_LE_GEN = prove
 (`!(E:real->bool) h (P:(int#int#int)->bool) sigma ups.
     sigma IN P /\ tile_le sigma ups /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> real_integral {x | x IN E /\ h x IN tile_J ups} (cw_tile ups)
         <= mass_Eh E h P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[mass_Eh] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC
   [`&1`;
    `real_integral {x | x IN E /\ h x IN tile_J ups} (cw_tile ups)`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC [`sigma:int#int#int`; `ups:int#int#int`] THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN
    MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN STRIP_TAC THEN
    MATCH_MP_TAC CW_TILE_SUBSET_LE_1 THEN ASM_REWRITE_TAC[]]);;

(* 286L(c-i) step 2: split w_sigma^2 = w_sigma * w_sigma, bound ONE factor   *)
(* by its                                                                    *)
(* upper bound Mw on S (= sup_K w_sigma later), integrate the other.  So     *)
(* int_S w_sigma^2 <= Mw int_S w_sigma. Pure integral monotonicity (cw_tile  *)
(* > 0                                                                       *)
(* by CW_TILE_POS, so w^2 = w*w <= Mw*w pointwise) + REAL_INTEGRAL_LMUL.     *)
let CWTILE_SQ_INT_LE = prove
 (`!(sigma:int#int#int) S Mw.
     cw_tile sigma real_integrable_on S /\
     (\x. (cw_tile sigma x) pow 2) real_integrable_on S /\
     (!x. x IN S ==> cw_tile sigma x <= Mw)
     ==> real_integral S (\x. (cw_tile sigma x) pow 2)
         <= Mw * real_integral S (cw_tile sigma)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral S (\x. Mw * cw_tile (sigma:int#int#int) x)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LE THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN ASM_REWRITE_TAC[ETA_AX];
      X_GEN_TAC `x:real` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`sigma:int#int#int`; `x:real`] CW_TILE_POS) THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:real`) THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[REAL_POW_2] THEN REPEAT STRIP_TAC THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REAL_ARITH_TAC];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    MATCH_MP_TAC REAL_INTEGRAL_LMUL THEN ASM_REWRITE_TAC[]]);;

(* The inner energy sum over a SINGLETON tile set collapses: sum over        *)
(* {s | s IN {sigma} /\ sigma <=_r t} is |(f|phi_sigma)|^2 if sigma <=_r t,  *)
(* else 0 (empty index set).                                                 *)
let ENERGY_SING_SUM = prove
 (`!(f:real->complex) sigma t.
     sum {s | s IN {sigma} /\ tile_ler s t} (\s. norm(carleson_ip f s) pow 2) =
     (if tile_ler sigma t then norm(carleson_ip f sigma) pow 2 else &0)`,
  REPEAT GEN_TAC THEN COND_CASES_TAC THENL
   [SUBGOAL_THEN
     `{s | s IN {sigma} /\ tile_ler s t} = {sigma}` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_SING] THEN GEN_TAC THEN
       EQ_TAC THENL
       [SIMP_TAC[]; ASM_MESON_TAC[]]; ALL_TAC] THEN REWRITE_TAC[SUM_SING];
    SUBGOAL_THEN `{s | s IN {sigma} /\ tile_ler s t} = {}` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_SING; NOT_IN_EMPTY] THEN
      X_GEN_TAC `u:int#int#int` THEN ASM_CASES_TAC `u:int#int#int = sigma` THEN
      ASM_REWRITE_TAC[]; REWRITE_TAC[SUM_CLAUSES]]]);;

(* 286H: energy of a SINGLETON. energy_f({sigma}) =                          *)
(* 2^(k_sigma/2)|(f|phi_sigma)|.                                             *)
(* The sup over tiles t is attained at t = sigma: for sigma <=_r t we have   *)
(* k_t <= k_sigma (TILE_LER_SCALE) so sqrt(2^k_t) <= sqrt(2^k_sigma); and    *)
(* the                                                                       *)
(* t = sigma term realises the bound (TILE_LER_REFL).                        *)
let ENERGY_SING = prove
 (`!(f:real->complex) sigma.
     energy_f f {sigma} = sqrt(&2 zpow (tile_k sigma)) * norm(carleson_ip f
       sigma)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[energy_f; ENERGY_SING_SUM] THEN
  MATCH_MP_TAC REAL_SUP_UNIQUE THEN CONJ_TAC THENL
   [REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `t:int#int#int` THEN
    COND_CASES_TAC THENL
     [REWRITE_TAC[POW_2_SQRT_ABS; REAL_ABS_NORM] THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
      MATCH_MP_TAC SQRT_MONO_LE THEN MATCH_MP_TAC ZPOW2_MONOE THEN
      MATCH_MP_TAC TILE_LER_SCALE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[SQRT_0; REAL_MUL_RZERO] THEN
      MATCH_MP_TAC REAL_LE_MUL THEN
      REWRITE_TAC[NORM_POS_LE] THEN MATCH_MP_TAC SQRT_POS_LE THEN
      MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
        REAL_ARITH_TAC];
    X_GEN_TAC `b':real` THEN DISCH_TAC THEN
    EXISTS_TAC `sqrt(&2 zpow (tile_k sigma)) * norm(carleson_ip f sigma)` THEN
    ASM_REWRITE_TAC[IN_ELIM_THM] THEN
    EXISTS_TAC `sigma:int#int#int` THEN
    REWRITE_TAC[IN_UNIV; TILE_LER_REFL; POW_2_SQRT_ABS; REAL_ABS_NORM]]);;

(* ------------------------------------------------------------------------- *)
(* Energy finiteness and the per-coefficient bound (used throughout 286K/L). *)
(* The energy value E(t) = 2^(k_t/2) sqrt(sum_{s in P, s <=_r t}             *)
(* |(f|phi_s)|^2)                                                            *)
(* is uniformly bounded by sqrt(sum_{s in P} 2^k_s |(f|phi_s)|^2) (since     *)
(* s <=_r t forces k_t <= k_s), so energy_f is a genuine finite sup; and     *)
(* each                                                                      *)
(* single coefficient obeys 2^(k_sigma/2) |(f|phi_sigma)| <= energy_f(P).    *)
(* ------------------------------------------------------------------------- *)

(* The core term estimate: 2^k_t sum_{s<=_r t} c_s <= sum_{s in P} 2^k_s     *)
(* c_s.                                                                      *)
let ENERGY_TERM_BOUND = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (t:int#int#int). FINITE P
     ==> (&2 zpow (tile_k t)) * sum {s | s IN P /\ tile_ler s t} (\s.
       norm(carleson_ip f s) pow 2)
         <= sum P (\s. (&2 zpow (tile_k s)) * norm(carleson_ip f s) pow 2)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM SUM_LMUL] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum {s | s IN P /\ tile_ler s t} (\s. (&2 zpow (tile_k s)) *
    norm(carleson_ip f s) pow 2)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_SIMP_TAC[FINITE_RESTRICT; IN_ELIM_THM] THEN
    X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[REAL_LE_POW_2] THEN
    MATCH_MP_TAC ZPOW2_MONOE THEN MATCH_MP_TAC TILE_LER_SCALE THEN
      ASM_REWRITE_TAC[];
    MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
      X_GEN_TAC `s:int#int#int` THEN REWRITE_TAC[IN_DIFF; IN_ELIM_THM] THEN
        STRIP_TAC THEN
      MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[REAL_LE_POW_2] THEN
      MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
        REAL_ARITH_TAC]]);;

(* energy_f is finite: bounded by sqrt(sum_{s in P} 2^k_s |(f|phi_s)|^2).    *)
let ENERGY_LE = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> energy_f f P <= sqrt(sum P (\s. (&2 zpow (tile_k s)) *
       norm(carleson_ip f s) pow 2))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[energy_f] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `sqrt(&2 zpow (tile_k (ARB:int#int#int))) *
                sqrt(sum {s | s IN P /\ tile_ler s ARB} (\s. norm(carleson_ip f
                  s) pow 2))` THEN
    REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `ARB:int#int#int` THEN
      REWRITE_TAC[IN_UNIV];
    REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `t:int#int#int` THEN
    SUBGOAL_THEN
     `sqrt(&2 zpow (tile_k t)) *
      sqrt(sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow 2))
        =
      sqrt((&2 zpow (tile_k t)) *
           sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow 2))`
     SUBST1_TAC THENL
     [REWRITE_TAC[GSYM SQRT_MUL]; ALL_TAC] THEN
    MATCH_MP_TAC SQRT_MONO_LE THEN ASM_SIMP_TAC[ENERGY_TERM_BOUND]]);;

(* energy_f is NONNEGATIVE (a sup of nonneg terms sqrt(..)*sqrt(sum of       *)
(* squares) over the nonempty universe of tiles; bounded above via           *)
(* ENERGY_TERM_BOUND).                                                       *)
let ENERGY_F_POS = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P ==> &0 <= energy_f f
   P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[energy_f] THEN
    MATCH_MP_TAC REAL_LE_SUP THEN
  EXISTS_TAC `sqrt(sum P (\s. (&2 zpow (tile_k s)) * norm(carleson_ip f s) pow
    2))` THEN
  EXISTS_TAC `sqrt(&2 zpow (tile_k (ARB:int#int#int))) *
              sqrt(sum {s | s IN P /\ tile_ler s ARB} (\s. norm(carleson_ip f
                s) pow 2))` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `ARB:int#int#int` THEN
     REWRITE_TAC[IN_UNIV];
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THEN MATCH_MP_TAC SQRT_POS_LE THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      MATCH_MP_TAC SUM_POS_LE THEN SIMP_TAC[FINITE_RESTRICT] THEN
      REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_LE_POW_2]];
    REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `t:int#int#int` THEN
    SUBGOAL_THEN
     `sqrt(&2 zpow (tile_k t)) *
      sqrt(sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow 2))
        =
      sqrt((&2 zpow (tile_k t)) *
           sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow 2))`
     SUBST1_TAC THENL
     [REWRITE_TAC[GSYM SQRT_MUL]; ALL_TAC] THEN
    MATCH_MP_TAC SQRT_MONO_LE THEN ASM_SIMP_TAC[ENERGY_TERM_BOUND]]);;

(* 286H single-tile energy bound: for sigma in P, sqrt(2^{k_sigma})          *)
(* |(f|phi_sigma)| <=                                                        *)
(* energy_f f P (i.e. |(f|phi_sigma)| <= sqrt(mu I_sigma) gamma). The energy *)
(* sup at                                                                    *)
(* t = sigma: the tile-set {s | tile_ler s sigma} contains sigma             *)
(* (TILE_LER_REFL), so                                                       *)
(* sum |ip|^2 >= |ip_sigma|^2; the sup is bounded above by ENERGY_TERM_BOUND *)
(* as usual.                                                                 *)
(* This is the gamma-input to the alpha2 v2 pointwise bound (286L f-iii).    *)
let ENERGY_IP_BOUND = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) sigma.
     FINITE P /\ sigma IN P
     ==> sqrt(&2 zpow (tile_k sigma)) * norm(carleson_ip f sigma) <= energy_f f
       P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[energy_f] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sqrt(&2 zpow (tile_k sigma)) *
              sqrt(sum {s | s IN P /\ tile_ler s sigma} (\s. norm(carleson_ip f
                s) pow 2))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
      MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `norm(carleson_ip (f:real->complex) sigma) =
                  sqrt(norm(carleson_ip f sigma) pow 2)` SUBST1_TAC THENL
     [REWRITE_TAC[POW_2_SQRT_ABS; REAL_ABS_NORM]; ALL_TAC] THEN
    MATCH_MP_TAC SQRT_MONO_LE THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `sum {sigma:int#int#int} (\s. norm(carleson_ip f s) pow 2)` THEN
      CONJ_TAC THENL
     [REWRITE_TAC[SUM_SING; REAL_LE_REFL];
      MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
      ASM_SIMP_TAC[FINITE_RESTRICT] THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_SING; IN_ELIM_THM] THEN
        REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[TILE_LER_REFL];
        REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_LE_POW_2]]];
    MATCH_MP_TAC REAL_LE_SUP THEN
    EXISTS_TAC `sqrt(sum P (\s. (&2 zpow (tile_k s)) * norm(carleson_ip
      (f:real->complex) s) pow 2))` THEN
    EXISTS_TAC `sqrt(&2 zpow (tile_k sigma)) *
                sqrt(sum {s | s IN P /\ tile_ler s sigma} (\s. norm(carleson_ip
                  (f:real->complex) s) pow 2))` THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `sigma:int#int#int` THEN
       REWRITE_TAC[IN_UNIV];
      REWRITE_TAC[REAL_LE_REFL];
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `t:int#int#int` THEN
      SUBGOAL_THEN
       `sqrt(&2 zpow (tile_k t)) *
        sqrt(sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip
          (f:real->complex) s) pow 2)) =
        sqrt((&2 zpow (tile_k t)) *
             sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow
               2))`
       SUBST1_TAC THENL
       [REWRITE_TAC[GSYM SQRT_MUL]; ALL_TAC] THEN
      MATCH_MP_TAC SQRT_MONO_LE THEN ASM_SIMP_TAC[ENERGY_TERM_BOUND]]]);;

(* 286M part (b) residual-vanishing: on a zero-energy tile set every         *)
(* carleson                                                                  *)
(* coefficient vanishes (ENERGY_IP_BOUND + sqrt(2^k)>0), hence any           *)
(* correlation                                                               *)
(* sum vanishes. This kills the INTER_n P_n tail in the 286M iteration       *)
(* (Fremlin                                                                  *)
(* 1832: <f|phi_sigma>=0 for sigma in INTER P_n as energy(P_n) -> 0).        *)
let MASS_EH_POS = prove
 (`!(E:real->bool) (h:real->real) (P:(int#int#int)->bool).
     ~(P = {}) /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> &0 <= mass_Eh E h P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[mass_Eh] THEN MATCH_MP_TAC REAL_LE_SUP THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `s0:int#int#int` o REWRITE_RULE[GSYM
    MEMBER_NOT_EMPTY]) THEN
  EXISTS_TAC `&1` THEN
  EXISTS_TAC `real_integral {x | x IN E /\ h x IN tile_J s0} (cw_tile s0)` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN
     MAP_EVERY EXISTS_TAC [`s0:int#int#int`; `s0:int#int#int`] THEN
    ASM_REWRITE_TAC[TILE_LE_REFL];
    MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_SIMP_TAC[] THEN
    REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
      REWRITE_TAC[CW_TILE_POS];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN
    MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN STRIP_TAC THEN
    MATCH_MP_TAC CW_TILE_SUBSET_LE_1 THEN ASM_REWRITE_TAC[]]);;


(* 286H/286L(c-i): 2^(k_sigma/2) |(f|phi_sigma)| <= energy_f(P) for sigma in *)
(* P.                                                                        *)
let COEFF_LE_ENERGY = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (sigma:int#int#int). FINITE P /\
   sigma IN P
     ==> sqrt(&2 zpow (tile_k sigma)) * norm(carleson_ip f sigma) <= energy_f f
       P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[energy_f] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  EXISTS_TAC `sqrt(sum P (\s. (&2 zpow (tile_k s)) * norm(carleson_ip f s) pow
    2))` THEN
  EXISTS_TAC `sqrt(&2 zpow (tile_k sigma)) *
              sqrt(sum {s | s IN P /\ tile_ler s sigma} (\s. norm(carleson_ip f
                s) pow 2))` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `sigma:int#int#int` THEN
     REWRITE_TAC[IN_UNIV];
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
      MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_RSQRT THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `sum {sigma:int#int#int} (\s. norm(carleson_ip f s) pow 2)` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[SUM_SING; REAL_LE_REFL];
      MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
      ASM_SIMP_TAC[FINITE_RESTRICT; FINITE_SING] THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_SING; IN_ELIM_THM] THEN
        REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[TILE_LER_REFL];
        REWRITE_TAC[IN_DIFF; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
        REWRITE_TAC[REAL_LE_POW_2]]];
    REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `t:int#int#int` THEN
    SUBGOAL_THEN
     `sqrt(&2 zpow (tile_k t)) *
      sqrt(sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow 2))
        =
      sqrt((&2 zpow (tile_k t)) *
           sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow 2))`
     SUBST1_TAC THENL
     [REWRITE_TAC[GSYM SQRT_MUL]; ALL_TAC] THEN
    MATCH_MP_TAC SQRT_MONO_LE THEN ASM_SIMP_TAC[ENERGY_TERM_BOUND]]);;

(* 286L(c-i) form:  |(f|phi_sigma)| <= 2^(-k_sigma/2) energy_f(P)  (dividing *)
(* COEFF_LE_ENERGY through by the positive sqrt(2^k_sigma)).                 *)
let COEFF_LE_ENERGY_HALF = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (sigma:int#int#int). FINITE P /\
   sigma IN P
     ==> norm(carleson_ip f sigma) <= inv(sqrt(&2 zpow (tile_k sigma))) *
       energy_f f P`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < sqrt(&2 zpow (tile_k sigma))` ASSUME_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LT THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`f:real->complex`; `P:(int#int#int)->bool`;
    `sigma:int#int#int`] COEFF_LE_ENERGY) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `inv(sqrt(&2 zpow (tile_k sigma))) * energy_f f P =
                energy_f f P / sqrt(&2 zpow (tile_k sigma))` SUBST1_TAC THENL
   [REWRITE_TAC[real_div] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN REWRITE_TAC[REAL_MUL_SYM]);;

(* sqrt(2^k) sqrt(2^-k) = 1 (the tile mass/scale cancellation, muI_tau       *)
(* muJ_tau=1                                                                 *)
(* under the root).  Recurs in the 286K H_j coefficient bound.               *)
let SQRT_ZPOW_NEG_MUL = prove
 (`!k:int. sqrt(&2 zpow k) * sqrt(&2 zpow (--k)) = &1`,
  GEN_TAC THEN
  SUBGOAL_THEN `&2 zpow (--k) = inv(&2 zpow k)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_NEG]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM SQRT_INV; GSYM SQRT_MUL; REAL_MUL_RINV; REAL_LT_IMP_NZ;
    SQRT_1]);;

(* 286Gc->286Gg arithmetic reshape: given the midpoint-integral bound        *)
(* W*2^(-kt)                                                                 *)
(* <= INT (286Gc with W = w_sigma(x_tau), muI_tau = 2^(-kt), INT =           *)
(* int_{I_tau}                                                               *)
(* w_sigma) and W >= 0, upgrade inv(sqrt 2^kt)*W <= sqrt(2^kt)*INT.  (LHS =  *)
(* sqrt(muI_tau) W; RHS = sqrt(muJ_tau) INT.) Cancel sqrt(2^kt)>0            *)
(* [REAL_LE_LCANCEL_                                                         *)
(* IMP]: sqrt*sqrt = 2^kt [SQRT_POW_2], sqrt*inv sqrt = 1, and               *)
(* 2^kt*(W*2^-kt) = W                                                        *)
(* [2^kt 2^-kt = 1, INT_ADD_RINV] <= 2^kt*INT [REAL_LE_LMUL].                *)
let GG_RESHAPE = prove
 (`!kt W INT:real. &0 <= W /\ W * &2 zpow (--kt) <= INT
   ==> inv(sqrt(&2 zpow kt)) * W <= sqrt(&2 zpow kt) * INT`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow kt` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < sqrt(&2 zpow kt)` ASSUME_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `sqrt(&2 zpow kt) * sqrt(&2 zpow kt) = &2 zpow kt` ASSUME_TAC THENL
   [MP_TAC(SPEC `&2 zpow kt` SQRT_POW_2) THEN
     ASM_SIMP_TAC[REAL_LT_IMP_LE; REAL_POW_2];
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow kt * &2 zpow (--kt) = &1` ASSUME_TAC THENL
   [SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
    REWRITE_TAC[INT_ADD_RINV; REAL_ZPOW_0]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LCANCEL_IMP THEN EXISTS_TAC `sqrt(&2 zpow kt)` THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `sqrt(&2 zpow kt) * inv(sqrt(&2 zpow kt)) * W = W` SUBST1_TAC THENL
   [SUBGOAL_THEN `~(sqrt(&2 zpow kt) = &0)` MP_TAC THENL
     [ASM_REAL_ARITH_TAC; CONV_TAC REAL_FIELD]; ALL_TAC] THEN
  SUBGOAL_THEN
    `sqrt(&2 zpow kt) * sqrt(&2 zpow kt) * INT =
     &2 zpow kt * INT` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[REAL_MUL_ASSOC]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 zpow kt * (W * &2 zpow (--kt))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    MP_TAC(ASSUME `&2 zpow kt * &2 zpow (--kt) = &1`) THEN CONV_TAC REAL_RING;
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE]]);;

(* 286K H_j coefficient bound: for tau in P with energy_f f P <= gam,        *)
(*   norm(f|phi_tau) <= gam sqrt(2^(-k_tau)) = gam sqrt(muI_tau).            *)
(* From COEFF_LE_ENERGY (sqrt(2^k) norm <= energy <= gam) x sqrt(2^-k) >= 0, *)
(* using                                                                     *)
(* sqrt(2^k) sqrt(2^-k) = 1 (SQRT_ZPOW_NEG_MUL). This is Fremlin's           *)
(* |<phi_tau|f>|                                                             *)
(* <= gam sqrt(muI_tau) used termwise inside the H_j Cauchy-Schwarz          *)
(* estimate.                                                                 *)
let COEFF_LE_ENERGY_MASS = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) tau gam.
     FINITE P /\ tau IN P /\ energy_f f P <= gam
     ==> norm(carleson_ip f tau) <= gam * sqrt(&2 zpow (--(tile_k tau)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `sqrt(&2 zpow (tile_k tau)) * norm(carleson_ip f tau) <= gam`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
     EXISTS_TAC `energy_f (f:real->complex) P` THEN
    ASM_SIMP_TAC[COEFF_LE_ENERGY]; ALL_TAC] THEN
  MP_TAC(ISPECL [`sqrt(&2 zpow (--(tile_k tau)))`;
                 `sqrt(&2 zpow (tile_k tau)) * norm(carleson_ip f tau)`;
                 `gam:real`] REAL_LE_LMUL) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
       REAL_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC(REAL_ARITH
     `a = n /\ b = g * m ==> a <= b ==> n <= g * m`) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[REAL_MUL_ASSOC] THEN
      GEN_REWRITE_TAC (RAND_CONV) [GSYM REAL_MUL_LID] THEN
      AP_THM_TAC THEN AP_TERM_TAC THEN
      ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN REWRITE_TAC[SQRT_ZPOW_NEG_MUL];
      REWRITE_TAC[REAL_MUL_AC]]]);;

(* Any single energy value E_P(t) is below the energy sup (the 286H energy   *)
(* is attained/dominated at every tile), and energy is MONOTONE under P      *)
(* subset Q (the <=_r-trees only grow) -- the energy analog of MASS_MONO.    *)
let ENERGY_TERM_LE_SELF = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (t:int#int#int). FINITE P
     ==> sqrt(&2 zpow (tile_k t)) *
         sqrt(sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s) pow
           2))
         <= energy_f f P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[energy_f] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  EXISTS_TAC `sqrt(sum P (\s. (&2 zpow (tile_k s)) * norm(carleson_ip f s) pow
    2))` THEN
  EXISTS_TAC `sqrt(&2 zpow (tile_k t)) *
              sqrt(sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip f s)
                pow 2))` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `t:int#int#int` THEN
     REWRITE_TAC[IN_UNIV];
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `u:int#int#int` THEN
    SUBGOAL_THEN
     `sqrt(&2 zpow (tile_k u)) *
      sqrt(sum {s | s IN P /\ tile_ler s u} (\s. norm(carleson_ip f s) pow 2))
        =
      sqrt((&2 zpow (tile_k u)) *
           sum {s | s IN P /\ tile_ler s u} (\s. norm(carleson_ip f s) pow 2))`
     SUBST1_TAC THENL
     [REWRITE_TAC[GSYM SQRT_MUL]; ALL_TAC] THEN
    MATCH_MP_TAC SQRT_MONO_LE THEN ASM_SIMP_TAC[ENERGY_TERM_BOUND]]);;

(* Arithmetic helper: from c > 0 and c D <= E, conclude D <= E / c (as E *   *)
(* inv c).                                                                   *)
let LE_INV_MUL_FROM_MUL = prove
 (`!c D E. &0 < c /\ c * D <= E ==> D <= E * inv c`,
  REPEAT STRIP_TAC THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM REAL_INV_INV] THEN
  ASM_SIMP_TAC[GSYM real_div; REAL_LE_RDIV_EQ; REAL_LT_INV_EQ;
    REAL_INV_INV] THEN
  ASM_REWRITE_TAC[REAL_INV_INV] THEN ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
  ASM_REWRITE_TAC[]);;

(* 286L(g) ENERGY STEP: for the tree P' = {s IN P : s <=_r tau}, the sum of  *)
(* squared coefficients is bounded by energy^2 . 2^{-k_tau}. This is the     *)
(* energy                                                                    *)
(* input to the alpha3 Gram bound ||g~||_2^2 <= C3 gamma^2 2^{-k_tau}.       *)
(* Square the                                                                *)
(* energy-sup bound ENERGY_TERM_LE_SELF at t = tau (sqrt(2^{k_tau})          *)
(* sqrt(sum|ip|^2)                                                           *)
(* <= energy) and divide by 2^{k_tau} > 0 (LE_INV_MUL_FROM_MUL).             *)
let FTILDE_ENERGY_SUM = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) tau. FINITE P
     ==> sum {s | s IN P /\ tile_ler s tau} (\s. norm(carleson_ip f s) pow 2)
         <= (energy_f f P) pow 2 * &2 zpow (--(tile_k tau))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`]
                ENERGY_TERM_LE_SELF) THEN
  ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `D = sum {s | s IN P /\ tile_ler s tau}
                     (\s. norm(carleson_ip (f:real->complex) s) pow 2)` THEN
  SUBGOAL_THEN `&0 <= D` ASSUME_TAC THENL
   [EXPAND_TAC "D" THEN MATCH_MP_TAC SUM_POS_LE THEN
    REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P` ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k tau)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_TAC THEN
  REWRITE_TAC[REAL_ZPOW_NEG] THEN
  MATCH_MP_TAC LE_INV_MUL_FROM_MUL THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`2`; `sqrt(&2 zpow (tile_k tau)) * sqrt D`;
                 `energy_f (f:real->complex) P`] REAL_POW_LE2) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THEN MATCH_MP_TAC SQRT_POS_LE THEN
      ASM_SIMP_TAC[REAL_LT_IMP_LE]; ASM_REWRITE_TAC[]];
    REWRITE_TAC[REAL_POW_MUL] THEN
    ASM_SIMP_TAC[SQRT_POW_2; REAL_LT_IMP_LE]]);;

let ENERGY_MONO = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (Q:(int#int#int)->bool).
     FINITE Q /\ P SUBSET Q ==> energy_f f P <= energy_f f Q`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `FINITE (P:(int#int#int)->bool)` ASSUME_TAC THENL
   [ASM_MESON_TAC[FINITE_SUBSET]; ALL_TAC] THEN
  GEN_REWRITE_TAC LAND_CONV [energy_f] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `sqrt(&2 zpow (tile_k (ARB:int#int#int))) *
                sqrt(sum {s | s IN P /\ tile_ler s ARB} (\s. norm(carleson_ip f
                  s) pow 2))` THEN
    REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `ARB:int#int#int` THEN
      REWRITE_TAC[IN_UNIV];
    REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `t:int#int#int` THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `sqrt(&2 zpow (tile_k t)) *
                sqrt(sum {s | s IN Q /\ tile_ler s t} (\s. norm(carleson_ip f
                  s) pow 2))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
        MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC SQRT_MONO_LE THEN MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
      ASM_SIMP_TAC[FINITE_RESTRICT] THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN ASM_MESON_TAC[SUBSET];
        REWRITE_TAC[IN_DIFF; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
        REWRITE_TAC[REAL_LE_POW_2]];
      MATCH_MP_TAC ENERGY_TERM_LE_SELF THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Fremlin's coefficient-mass functional Delta(A) = sum_{sigma in A}         *)
(* |(f|phi_sigma)|^2, pervasive in the 286K induction. Nonnegative,          *)
(* monotone,                                                                 *)
(* and finitely additive over disjoint unions.                               *)
(* ------------------------------------------------------------------------- *)

let delta_f = new_definition
 `delta_f (f:real->complex) (A:(int#int#int)->bool) =
    sum A (\s. norm(carleson_ip f s) pow 2)`;;

let DELTA_POS = prove
 (`!(f:real->complex) (A:(int#int#int)->bool). &0 <= delta_f f A`,
  REPEAT GEN_TAC THEN REWRITE_TAC[delta_f] THEN
  MATCH_MP_TAC SUM_POS_LE THEN REWRITE_TAC[REAL_LE_POW_2]);;

let DELTA_MONO = prove
 (`!(f:real->complex) (A:(int#int#int)->bool) (B:(int#int#int)->bool).
     FINITE B /\ A SUBSET B ==> delta_f f A <= delta_f f B`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[delta_f] THEN
  MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_LE_POW_2]);;

let DELTA_UNIONS = prove
 (`!(f:real->complex) (S:((int#int#int)->bool)->bool).
     FINITE S /\ (!A. A IN S ==> FINITE A) /\
     (!A B. A IN S /\ B IN S /\ ~(A = B) ==> DISJOINT A B)
     ==> delta_f f (UNIONS S) = sum S (\A. delta_f f A)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[delta_f] THEN
  MATCH_MP_TAC SUM_UNIONS_NONZERO THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`A:(int#int#int)->bool`; `B:(int#int#int)->bool`;
    `s:int#int#int`] THEN
  STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`A:(int#int#int)->bool`;
    `B:(int#int#int)->bool`]) THEN
  ASM_REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  ASM_MESON_TAC[]);;

(* Subset splitting: Delta(P) = Delta(Q) + Delta(P \ Q) for Q SUBSET P. The  *)
(* mass removed when the recursion peels off a subtree Q = T(tau_j) from P_j *)
(* (via the library SUM_DIFF: sum(P\Q) = sum P - sum Q).                     *)
let tile_tree = new_definition
 `tile_tree (P:(int#int#int)->bool) (t:int#int#int) = {s | s IN P /\ tile_ler s
   t}`;;

let TILE_TREE_FINITE = prove
 (`!(P:(int#int#int)->bool) (t:int#int#int). FINITE P ==> FINITE (tile_tree P
   t)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[tile_tree] THEN
  MATCH_MP_TAC FINITE_RESTRICT THEN ASM_REWRITE_TAC[]);;

(* The tree is a subset of P; it grows monotonically in the root order <=_r  *)
(* (via                                                                      *)
(* TILE_LER_TRANS) and in the ambient tile set P; and it commutes with       *)
(* restriction                                                               *)
(* to a subset. These are the set-algebra facts the 286K stopping-time       *)
(* recursion                                                                 *)
(* uses to reason about the shrinking tile sets P'_j = P'_{j-1} \ T(tau_j).  *)
let TILE_TREE_SUBSET = prove
 (`!(P:(int#int#int)->bool) t. tile_tree P t SUBSET P`,
  REWRITE_TAC[tile_tree; SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

let TILE_TREE_MONO_SET = prove
 (`!(P:(int#int#int)->bool) Q t. P SUBSET Q ==> tile_tree P t SUBSET tile_tree
   Q t`,
  REWRITE_TAC[tile_tree; SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

let TILE_TREE_INTER = prove
 (`!(P:(int#int#int)->bool) Q t. tile_tree (P INTER Q) t = tile_tree P t INTER
   Q`,
  REWRITE_TAC[tile_tree; EXTENSION; IN_INTER; IN_ELIM_THM] THEN MESON_TAC[]);;

let ENERGY_WITNESS = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) c. FINITE P /\ &0 <= c /\ c <
   energy_f f P
     ==> ?t. c pow 2 < (&2 zpow (tile_k t)) * delta_f f (tile_tree P t)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`{sqrt (&2 zpow tile_k t) *
      sqrt (sum {s | s IN P /\ tile_ler s t} (\s. norm(carleson_ip
        (f:real->complex) s) pow 2))
      | t IN (:int#int#int)}`; `c:real`] SUP_APPROACH) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
      EXISTS_TAC `sqrt (&2 zpow tile_k (ARB:int#int#int)) *
        sqrt (sum {s | s IN P /\ tile_ler s ARB} (\s. norm(carleson_ip
          (f:real->complex) s) pow 2))` THEN
      REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `ARB:int#int#int` THEN
        REWRITE_TAC[IN_UNIV];
      EXISTS_TAC `sqrt(sum P (\s. (&2 zpow (tile_k s)) * norm(carleson_ip
        (f:real->complex) s) pow 2))` THEN
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `t:int#int#int` THEN
      MP_TAC(ISPECL [`f:real->complex`; `P:(int#int#int)->bool`;
        `t:int#int#int`] ENERGY_TERM_LE_SELF) THEN
      ASM_REWRITE_TAC[energy_f] THEN
        DISCH_THEN(fun th -> MATCH_MP_TAC REAL_LE_TRANS THEN
        EXISTS_TAC `energy_f (f:real->complex) P` THEN CONJ_TAC THENL
        [REWRITE_TAC[energy_f] THEN
         MP_TAC(ISPECL [`f:real->complex`; `P:(int#int#int)->bool`;
           `t:int#int#int`] ENERGY_TERM_LE_SELF) THEN
         ASM_REWRITE_TAC[energy_f]; ALL_TAC]) THEN
      MP_TAC(ISPECL [`f:real->complex`;
        `P:(int#int#int)->bool`] ENERGY_LE) THEN
      ASM_REWRITE_TAC[energy_f];
      ASM_REWRITE_TAC[GSYM energy_f]];
    ALL_TAC] THEN
  REWRITE_TAC[IN_ELIM_THM; IN_UNIV] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:real` (CONJUNCTS_THEN2 MP_TAC ASSUME_TAC)) THEN
  DISCH_THEN(X_CHOOSE_THEN `t:int#int#int` SUBST_ALL_TAC) THEN
  EXISTS_TAC `t:int#int#int` THEN REWRITE_TAC[delta_f; tile_tree] THEN
  SUBGOAL_THEN `&0 <= &2 zpow tile_k t *
     sum {s | s IN P /\ tile_ler s t} (\s. norm (carleson_ip (f:real->complex)
       s) pow 2)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      MATCH_MP_TAC SUM_POS_LE THEN REWRITE_TAC[REAL_LE_POW_2]];
    ALL_TAC] THEN
  SUBGOAL_THEN `c pow 2 < (sqrt (&2 zpow tile_k t *
     sum {s | s IN P /\ tile_ler s t} (\s. norm (carleson_ip (f:real->complex)
       s) pow 2))) pow 2`
   MP_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT2 THEN ASM_REWRITE_TAC[ARITH_EQ] THEN
    ASM_REWRITE_TAC[SQRT_MUL];
    ASM_SIMP_TAC[SQRT_POW_2]]);;

(* The stopping condition (contrapositive of ENERGY_WITNESS): if NO          *)
(* tile-tree                                                                 *)
(* carries mass exceeding c^2, then energy_f f P <= c. This bounds the       *)
(* leftover                                                                  *)
(* energy when the 286K recursion halts (Fremlin's energy(P1) <= gamma/2     *)
(* once no                                                                   *)
(* tau survives the R_j selection).                                          *)
let ENERGY_THRESHOLD = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) c. FINITE P /\ &0 <= c /\
     (!t. (&2 zpow (tile_k t)) * delta_f f (tile_tree P t) <= c pow 2)
     ==> energy_f f P <= c`,
  REPEAT STRIP_TAC THEN
  GEN_REWRITE_TAC I [REAL_ARITH `x <= c <=> ~(c < x)`] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`; `P:(int#int#int)->bool`;
    `c:real`] ENERGY_WITNESS) THEN
  ASM_REWRITE_TAC[NOT_EXISTS_THM] THEN
  X_GEN_TAC `t:int#int#int` THEN
  REWRITE_TAC[REAL_NOT_LT] THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286M infrastructure: the up-set R+ and a union-sum bound.  Fremlin's      *)
(* stopping-time lemmas (286J/286K) select R subset Q and remove R+ =        *)
(* {sigma : some tau in R has tau <= sigma} (Fremlin's order) from P; the    *)
(* combine step of 286M takes R = R0 UNION R1 and needs both the             *)
(* nested-removal                                                            *)
(* identity P\(R0uR1)+ = (P\R0+)\R1+ and the sub-additive measure budget     *)
(* sum_{R0uR1} <= sum + sum.  In our reversed order (tile_le s t = Fremlin   *)
(* t <= s), Fremlin tau <= sigma becomes tile_le sigma tau, so R+ = {s | ?t  *)
(* IN                                                                        *)
(* R. tile_le s t} -- the union of the 286L trees {s | tile_le s tau}.       *)
(* ------------------------------------------------------------------------- *)

(* R+ up-set (Fremlin 286Fb): sigma in R+ iff some tau in R has tau <= sigma *)
(* (Fremlin's order).  Our tile_le s t = Fremlin (t <= s), so Fremlin tau <= *)
(* sigma = our tile_le sigma tau; hence R+ = {s | ?t IN R. tile_le s t}.     *)
(* This is the union of the 286L trees {s | tile_le s tau}, tau in R.        *)
let tile_upset = new_definition
 `tile_upset (R:(int#int#int)->bool) = {s | ?t. t IN R /\ tile_le s t}`;;

let TILE_UPSET_UNION_DIFF = prove
 (`!P R0 R1:(int#int#int)->bool.
     P DIFF tile_upset (R0 UNION R1) =
     (P DIFF tile_upset R0) DIFF tile_upset R1`,
  REWRITE_TAC[tile_upset; EXTENSION; IN_DIFF; IN_ELIM_THM; IN_UNION] THEN
  MESON_TAC[]);;

(* ========================================================================= *)
(* 286J part (a) (Fremlin mt286.tex 833-846): the greedy minimal-witness R.  *)
(* R = tile_le-maximal elements of {sigma' : sigma in P, mass{sigma}>c},     *)
(* where                                                                     *)
(* sigma' = carleson_jwit is a witnessing tile >= sigma (tile_le sigma       *)
(* sigma')                                                                   *)
(* with big integral (MASS_EH_WITNESS).  Then P \ R^+ SUBSET {sigma :        *)
(* mass{sigma}<=c}, so mass_Eh(P\R^+) <= c (MASS_EH_LE, guarded by           *)
(* nonempty).                                                                *)
(* The mass and energy stopping sets.                                        *)
(* ========================================================================= *)
let carleson_jwit = new_definition
 `carleson_jwit E h c sigma =
    @t. tile_le sigma t /\
        c < real_integral {x | x IN E /\ h x IN tile_J t} (cw_tile t)`;;

let carleson_jwitset = new_definition
 `carleson_jwitset E h c (P:(int#int#int)->bool) =
    { carleson_jwit E h c sigma | sigma | sigma IN P /\ c < mass_Eh E h {sigma}
      }`;;

let carleson_jR = new_definition
 `carleson_jR E h c (P:(int#int#int)->bool) =
    { r | r IN carleson_jwitset E h c P /\
          (!n. n IN carleson_jwitset E h c P /\ tile_le r n ==> tile_le n r)
            }`;;

(* the witness spec: mass{sigma}>c ==> jwit sigma >= sigma with big integral *)
let CARLESON_JWIT_SPEC = prove
 (`!E h c sigma.
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
     c < mass_Eh E h {sigma}
     ==> tile_le sigma (carleson_jwit E h c sigma) /\
         c < real_integral {x | x IN E /\ h x IN tile_J (carleson_jwit E h c
           sigma)}
                (cw_tile (carleson_jwit E h c sigma))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[carleson_jwit] THEN
  CONV_TAC SELECT_CONV THEN
  MP_TAC(ISPECL [`E:real->bool`;`h:real->real`;`sigma:int#int#int`;`c:real`]
    MASS_EH_WITNESS) THEN
  ASM_REWRITE_TAC[]);;

let CARLESON_JWITSET_FINITE = prove
 (`!E h c P:(int#int#int)->bool. FINITE P ==> FINITE (carleson_jwitset E h c
   P)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_jwitset] THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `IMAGE (carleson_jwit E h c) P` THEN
  ASM_SIMP_TAC[FINITE_IMAGE] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_IMAGE] THEN MESON_TAC[]);;

let CARLESON_JR_FINITE = prove
 (`!E h c P:(int#int#int)->bool. FINITE P ==> FINITE (carleson_jR E h c P)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_jR] THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `carleson_jwitset E h c P` THEN
  ASM_SIMP_TAC[CARLESON_JWITSET_FINITE] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

(* every big-single-mass sigma in P lies in R^+                              *)
let CARLESON_JR_UPSET = prove
 (`!E h c P sigma:int#int#int.
     FINITE P /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
     sigma IN P /\ c < mass_Eh E h {sigma}
     ==> sigma IN tile_upset (carleson_jR E h c P)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `sp = carleson_jwit E h c sigma` THEN
  SUBGOAL_THEN `(sp:int#int#int) IN carleson_jwitset E h c P` ASSUME_TAC THENL
   [REWRITE_TAC[carleson_jwitset; IN_ELIM_THM] THEN
    EXISTS_TAC `sigma:int#int#int` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `tile_le sigma (sp:int#int#int)` ASSUME_TAC THENL
   [EXPAND_TAC "sp" THEN
    MP_TAC(ISPECL [`E:real->bool`;`h:real->real`;`c:real`;`sigma:int#int#int`]
      CARLESON_JWIT_SPEC) THEN ASM_REWRITE_TAC[] THEN SIMP_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`tile_le`;
    `carleson_jwitset E h c P`] TILE_LE_MAXIMAL_ABOVE) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[CARLESON_JWITSET_FINITE; TILE_LE_REFL] THEN
    MESON_TAC[TILE_LE_TRANS]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `sp:int#int#int`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:int#int#int` STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[tile_upset; IN_ELIM_THM] THEN
  EXISTS_TAC `r:int#int#int` THEN CONJ_TAC THENL
   [REWRITE_TAC[carleson_jR; IN_ELIM_THM] THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC TILE_LE_TRANS THEN EXISTS_TAC `sp:int#int#int` THEN
    ASM_REWRITE_TAC[]]);;

(* 286J part (a) MASS BOUND: mass_Eh(P \ R^+) <= c (guarded by nonemptiness, *)
(* matching carleson_mass_budget's guarded conclusion -- mass_Eh is a raw    *)
(* sup so mass_Eh {} is junk; Fremlin's mass is 0 on empty, so the guard     *)
(* loses nothing).                                                           *)
let CARLESON_JMASS_BOUND = prove
 (`!E h c P:(int#int#int)->bool.
     FINITE P /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> ~(P DIFF tile_upset (carleson_jR E h c P) = {})
         ==> mass_Eh E h (P DIFF tile_upset (carleson_jR E h c P)) <= c`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC MASS_EH_LE THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN
  REWRITE_TAC[IN_DIFF] THEN STRIP_TAC THEN
  (* s in P, s NOT in R^+, tile_le s t.  Then mass{s} <= c (contrapositive of
     JR_UPSET), and int_{J_t} w_t <= mass{s} (MASS_TERM_LE_GEN on {s}).      *)
  SUBGOAL_THEN `mass_Eh E h {s:int#int#int} <= c` ASSUME_TAC THENL
   [MATCH_MP_TAC(REAL_ARITH `~(c < m) ==> m <= c`) THEN DISCH_TAC THEN
    UNDISCH_TAC `~(s:int#int#int IN tile_upset (carleson_jR E h c P))` THEN
    REWRITE_TAC[] THEN
    MATCH_MP_TAC CARLESON_JR_UPSET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `mass_Eh E h {s:int#int#int}` THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`E:real->bool`;`h:real->real`;`{s:int#int#int}`;
    `s:int#int#int`;`t:int#int#int`] MASS_TERM_LE_GEN) THEN
  ASM_REWRITE_TAC[IN_SING]);;

(* Sub-additive measure budget over a (possibly overlapping) union, for the  *)
(* nonnegative interval-lengths mu I_tau. Inclusion-exclusion + sum(s INTER  *)
(* t)                                                                        *)
(* >= 0.                                                                     *)
let SUM_UNION_LE_POS = prove
 (`!(f:A->real) s t. FINITE s /\ FINITE t /\ (!x. x IN s INTER t ==> &0 <= f x)
     ==> sum (s UNION t) f <= sum s f + sum t f`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`s:A->bool`; `t:A->bool`; `f:A->real`] SUM_INCL_EXCL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC(REAL_ARITH `&0 <= i ==> u <= u + i`) THEN
  MATCH_MP_TAC SUM_POS_LE THEN ASM_SIMP_TAC[FINITE_INTER]);;

(* Peel one index a from a UNIONS-of-IMAGE set identity. Used to bound the   *)
(* sum                                                                       *)
(* over a finite union of tree-supports by the sum of per-tree sums.         *)
let UNIONS_IMAGE_DELETE = prove
 (`!(G:A->(B->bool)) R a. a IN R
     ==> UNIONS (IMAGE G R) = G a UNION UNIONS (IMAGE G (R DELETE a))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `R = (a:A) INSERT (R DELETE a)`
   (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV) [th]) THENL
   [ASM SET_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[IMAGE_CLAUSES; UNIONS_INSERT]);;

(* Subadditive union-sum: for a nonnegative phi, the sum over a finite union *)
(* of                                                                        *)
(* pieces is at most the sum of the per-piece sums. 286M part (b) uses this  *)
(* to                                                                        *)
(* bound sum over P cap R+ = sum over UNIONS of the trees {sigma : sigma >=  *)
(* tau}                                                                      *)
(* (tau in R) by sum_{tau in R} (tree sum). WF-induction on CARD R; peel one *)
(* tau                                                                       *)
(* (SUM_DELETE on RHS, UNIONS_IMAGE_DELETE + SUM_UNION_LE_POS on LHS),       *)
(* recurse.                                                                  *)
let SUM_UNIONS_LE_SUM = prove
 (`!(G:A->(B->bool)) (R:A->bool) (phi:B->real).
     FINITE R /\ (!t. t IN R ==> FINITE (G t)) /\ (!x. &0 <= phi x)
     ==> sum (UNIONS (IMAGE G R)) phi <= sum R (\t. sum (G t) phi)`,
  GEN_TAC THEN GEN_TAC THEN GEN_TAC THEN
  WF_INDUCT_TAC `CARD(R:A->bool)` THEN STRIP_TAC THEN
  ASM_CASES_TAC `R:A->bool = {}` THENL
   [ASM_REWRITE_TAC[IMAGE_CLAUSES; UNIONS_0; SUM_CLAUSES; REAL_LE_REFL];
    ALL_TAC] THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `a:A` o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
  SUBGOAL_THEN `FINITE((R:A->bool) DELETE a)` ASSUME_TAC THENL
   [REWRITE_TAC[FINITE_DELETE] THEN FIRST_ASSUM MATCH_ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `sum R (\t. sum ((G:A->(B->bool)) t) phi) =
    sum (G a) phi + sum (R DELETE a) (\t. sum (G t) phi)`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`\t. sum ((G:A->(B->bool)) t) phi`; `R:A->bool`; `a:A`]
      SUM_DELETE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; REAL_ARITH_TAC];
    ALL_TAC] THEN
  ASM_SIMP_TAC[UNIONS_IMAGE_DELETE] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum ((G:A->(B->bool)) a) phi +
              sum (UNIONS (IMAGE G (R DELETE a))) phi` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_UNION_LE_POS THEN REPEAT CONJ_TAC THENL
     [UNDISCH_TAC `!t:A. t IN R ==> FINITE ((G:A->(B->bool)) t)` THEN
      DISCH_THEN(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[FINITE_UNIONS; FORALL_IN_IMAGE] THEN
      ASM_SIMP_TAC[FINITE_IMAGE; IN_DELETE];
      GEN_TAC THEN DISCH_TAC THEN FIRST_ASSUM MATCH_ACCEPT_TAC];
    MATCH_MP_TAC REAL_LE_ADD2 THEN REWRITE_TAC[REAL_LE_REFL] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `(R:A->bool) DELETE a`) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[CARD_DELETE] THEN
      MATCH_MP_TAC(ARITH_RULE `~(n = 0) ==> n - 1 < n`) THEN
      ASM_SIMP_TAC[CARD_EQ_0] THEN REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
      EXISTS_TAC `a:A` THEN FIRST_ASSUM MATCH_ACCEPT_TAC;
      DISCH_THEN MATCH_MP_TAC THEN ASM_SIMP_TAC[IN_DELETE]]]);;

(* A descending chain of sets is contained in its first term.                *)
let GRAM_ALPHA_BOUND = prove
 (`!alpha K:real. &0 <= alpha /\ &0 <= K /\ alpha pow 2 <= K * alpha ==> alpha
   <= K`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `alpha = &0` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&0 < alpha` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`alpha:real`; `K:real`; `alpha:real`] REAL_LE_RMUL_EQ) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  ASM_REWRITE_TAC[GSYM REAL_POW_2]);;

(* ------------------------------------------------------------------------- *)
(* 286I geometry/analysis bricks (part b). I_tau^(k) = the interval with the *)
(* same centre x_tau = tile_xmid as I_tau but 2^k times the length; since    *)
(* |I_tau| = 2^(-k_tau), its half-width is 2^(k - k_tau - 1).                *)
(* ------------------------------------------------------------------------- *)

let tile_Idil = new_definition
 `tile_Idil (s:int#int#int) (k:num) =
    {x:real | abs(x - tile_xmid s) < &2 zpow (&k - tile_k s - &1)}`;;

(* Outside the dilate, the distance to the centre is at least the            *)
(* half-width.                                                               *)
let CW_ANTITONE = prove
 (`!a b:real. abs a <= abs b ==> cw b <= cw a`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cw; REAL_ARITH `&1 / x = inv x`] THEN
  MATCH_MP_TAC REAL_LE_INV2 THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_POW_LE2 THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* The even tent cw1 = min(cw 3, cw x) (Fremlin's w1 = min(w(3),             *)
(* w(x))). Flat on [-3,3], = cw outside; this is the monotone-const-monotone *)
(* (MCM) kernel that 286B (MCM_MAXIMAL_DOMINATION) needs, dominating |phi|.  *)
(* ------------------------------------------------------------------------- *)
let cw1 = new_definition `cw1 (x:real) = min (cw(&3)) (cw x)`;;

let CW1_POS = prove
 (`!x. &0 < cw1 x`,
  GEN_TAC THEN REWRITE_TAC[cw1] THEN
  MP_TAC(SPEC `&3` CW_POS) THEN MP_TAC(SPEC `x:real` CW_POS) THEN
    REAL_ARITH_TAC);;

let CW1_EVEN = prove
 (`!x. cw1(--x) = cw1 x`,
  GEN_TAC THEN REWRITE_TAC[cw1; CW_EVEN]);;

let CW1_LE_CW = prove
 (`!x. cw1 x <= cw x`,
  GEN_TAC THEN REWRITE_TAC[cw1] THEN REAL_ARITH_TAC);;

(* cw1 is MCM with al = -3, be = 3: nondecreasing on (-inf,-3],              *)
(* nonincreasing                                                             *)
(* on [3,inf), constant on [-3,3]. All from CW_ANTITONE (cw antitone in      *)
(* |.|).                                                                     *)
let CW1_MCM = prove
 (`(!x y. x <= y /\ y <= --(&3) ==> cw1 x <= cw1 y) /\
   (!x y. &3 <= x /\ x <= y ==> cw1 y <= cw1 x) /\
   (!x. --(&3) <= x /\ x <= &3 ==> cw1 x = cw1(--(&3)))`,
  REWRITE_TAC[cw1] THEN REPEAT CONJ_TAC THEN REPEAT STRIP_TAC THENL
   [MP_TAC(SPECL [`y:real`; `x:real`] CW_ANTITONE) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REAL_ARITH_TAC];
    MP_TAC(SPECL [`x:real`; `y:real`] CW_ANTITONE) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REAL_ARITH_TAC];
    SUBGOAL_THEN `cw(&3) <= cw x /\ cw(&3) <= cw(--(&3))` MP_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC CW_ANTITONE THEN ASM_REAL_ARITH_TAC;
      REAL_ARITH_TAC]]);;

(* cw1 is continuous (min of two continuous) and, being <= cw (L^1, CW_FULL) *)
(* and >= 0, absolutely integrable on R. Both are MCM_MAXIMAL_DOMINATION     *)
(* hyps.                                                                     *)
let CW1_CONTINUOUS = prove
 (`cw1 real_continuous_on (:real)`,
  SUBGOAL_THEN `cw1 = \x. min ((\y. cw(&3)) x) (cw x)` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; cw1]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_CONTINUOUS_ON_MIN THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON_CONST; CW_CONTINUOUS]);;

let CW1_ABSINT = prove
 (`cw1 absolutely_real_integrable_on (:real)`,
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE
    THEN
  EXISTS_TAC `cw` THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
     REWRITE_TAC[CW1_CONTINUOUS];
    MATCH_MP_TAC HAS_REAL_INTEGRAL_INTEGRABLE THEN EXISTS_TAC `&1` THEN
      REWRITE_TAC[CW_FULL];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    MP_TAC(SPEC `x:real` CW1_POS) THEN MP_TAC(SPEC `x:real` CW1_LE_CW) THEN
      REAL_ARITH_TAC]);;

(* The DILATED tent gg(t) = cw1(3 2^m t) is MCM with al = -2^{-m}, be =      *)
(* 2^{-m}:                                                                   *)
(* the flat edges 3 2^m (+-2^{-m}) = +-3 map to cw1's flat region [-3,3].    *)
(* This                                                                      *)
(* is the exact gg for the (h)(vi) application of MCM_MAXIMAL_DOMINATION.    *)
(* Key                                                                       *)
(* arithmetic: 3 2^m (+-2^{-m}) = +-3 (since 2^m 2^{-m}=1); monotone scaling *)
(* of                                                                        *)
(* the argument (REAL_LE_LMUL, 3 2^m > 0) then CW1_MCM.                      *)
let CW1_DILATE_MCM = prove
 (`!m. &0 < &2 zpow m
   ==> (!x y. x <= y /\ y <= --(&2 zpow(--m))
              ==> cw1(&3 * &2 zpow m * x) <= cw1(&3 * &2 zpow m * y)) /\
       (!x y. &2 zpow(--m) <= x /\ x <= y
              ==> cw1(&3 * &2 zpow m * y) <= cw1(&3 * &2 zpow m * x)) /\
       (!x. --(&2 zpow(--m)) <= x /\ x <= &2 zpow(--m)
            ==> cw1(&3 * &2 zpow m * x) = cw1(&3 * &2 zpow m * (--(&2
              zpow(--m)))))`,
  GEN_TAC THEN DISCH_TAC THEN
  ABBREV_TAC `M = &2 zpow m` THEN
  SUBGOAL_THEN
    `&3 * M * (&2 zpow(--m)) = &3 /\ &3 * M * (--(&2 zpow(--m))) = --(&3)`
    STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `M * &2 zpow(--m) = &1` MP_TAC THENL
     [EXPAND_TAC "M" THEN REWRITE_TAC[REAL_ZPOW_NEG] THEN
      MATCH_MP_TAC REAL_MUL_RINV THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_ARITH `&3 * M * b = &3 * (M * b)`;
                  REAL_ARITH `&3 * M * --b = --(&3 * (M * b))`] THEN
      DISCH_THEN SUBST1_TAC THEN REAL_ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!p q:real. p <= q ==> &3 * M * p <= &3 * M * q` ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    REWRITE_TAC[REAL_ARITH `&3 * M * p = (&3 * M) * p`] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT CONJ_TAC THEN REPEAT STRIP_TAC THENL
   [MATCH_MP_TAC(CONJUNCT1 CW1_MCM) THEN
    CONJ_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC) THEN ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(MP_TAC o SPECL [`y:real`; `--(&2 zpow(--m))`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
    MATCH_MP_TAC(CONJUNCT1(CONJUNCT2 CW1_MCM)) THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPECL [`&2 zpow(--m)`; `x:real`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      FIRST_ASSUM(MATCH_MP_TAC) THEN ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(CONJUNCT2(CONJUNCT2 CW1_MCM)) THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPECL [`--(&2 zpow(--m))`; `x:real`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      FIRST_X_ASSUM(MP_TAC o SPECL [`x:real`; `&2 zpow(--m)`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC]]);;

(* Superlevel sets of the dilated tent are bounded: {t | u <= cw1(3 2^m t)}  *)
(* SUBSET [-R,R] with R = (1/u - 1)/(3 2^m).  From cw1 <= cw = 1/(1+|.|)^3:  *)
(* u <= 1/(1+|3 2^m t|)^3 forces (1+|3 2^m t|)^3 <= 1/u, hence 1+|3 2^m t|   *)
(* <= 1/u                                                                    *)
(* (cube >= base for base >= 1), so |t| <= R. The last                       *)
(* MCM_MAXIMAL_DOMINATION                                                    *)
(* hypothesis for gg = cw1(3 2^m .).                                         *)
let CW1_DILATE_SUPERLEVEL_BOUNDED = prove
 (`!m u. &0 < &2 zpow m /\ &0 < u
         ==> real_bounded {t | u <= cw1(&3 * &2 zpow m * t)}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_BOUNDED_SUBSET THEN
  EXISTS_TAC `real_interval[--((inv u - &1)/(&3 * &2 zpow m)), (inv u - &1)/(&3
    * &2 zpow m)]` THEN
  REWRITE_TAC[REAL_BOUNDED_REAL_INTERVAL] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_REAL_INTERVAL] THEN
  X_GEN_TAC `t:real` THEN DISCH_TAC THEN
  SUBGOAL_THEN `u <= cw(&3 * &2 zpow m * t)` MP_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `cw1(&3 * &2 zpow m * t)` THEN
    ASM_REWRITE_TAC[CW1_LE_CW]; ALL_TAC] THEN
  REWRITE_TAC[cw; REAL_ARITH `&1 / x = inv x`] THEN
  SUBGOAL_THEN `&0 < (&1 + abs(&3 * &2 zpow m * t)) pow 3` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(&1 + abs(&3 * &2 zpow m * t)) pow 3 <= inv u` ASSUME_TAC THENL
   [GEN_REWRITE_TAC LAND_CONV [GSYM REAL_INV_INV] THEN
    MATCH_MP_TAC REAL_LE_INV2 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `&1 + abs(&3 * &2 zpow m * t) <= inv u` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `(&1 + abs(&3 * &2 zpow m * t)) pow 3` THEN
      ASM_REWRITE_TAC[] THEN
    GEN_REWRITE_TAC LAND_CONV [GSYM REAL_POW_1] THEN
    MATCH_MP_TAC REAL_POW_MONO THEN CONJ_TAC THENL
      [REAL_ARITH_TAC; ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
    `abs(&3 * &2 zpow m * t) = (&3 * &2 zpow m) * abs t` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_ABS_MUL] THEN
    SUBGOAL_THEN `abs(&3 * &2 zpow m) = &3 * &2 zpow m` MP_TAC THENL
     [ASM_REAL_ARITH_TAC; REWRITE_TAC[REAL_ABS_MUL] THEN
       REAL_ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &3 * &2 zpow m` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(&3 * &2 zpow m) * abs t <= inv u - &1` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `abs t <= (inv u - &1) / (&3 * &2 zpow m)` MP_TAC THENL
   [ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* Dilated tent is continuous (cw1 continuous o linear) and real_integrable  *)
(* (affine image of the L^1 cw1, HAS_REAL_INTEGRAL_AFFINITY_UNIV): the last  *)
(* two MCM_MAXIMAL_DOMINATION hyps for gg = cw1(3 2^m .).                    *)
let CW1_DILATE_CONT = prove
 (`!m. (\t. cw1(&3 * &2 zpow m * t)) real_continuous_on (:real)`,
  GEN_TAC THEN
  SUBGOAL_THEN
    `(\t. cw1(&3 * &2 zpow m * t)) = cw1 o (\t. (&3 * &2 zpow m) * t)`
    SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; REAL_MUL_ASSOC]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [MP_TAC(BETA_RULE(ISPECL [`(\x:real. x)`; `&3 * &2 zpow m`;
     `(:real)`] REAL_CONTINUOUS_ON_LMUL)) THEN
    REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON_ID];
    MATCH_MP_TAC REAL_CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real)` THEN
    REWRITE_TAC[CW1_CONTINUOUS; SUBSET_UNIV]]);;

let CW1_DILATE_INTEGRABLE = prove
 (`!m. &0 < &2 zpow m ==> (\t. cw1(&3 * &2 zpow m * t)) real_integrable_on
   (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_MUL_ASSOC] THEN
  MP_TAC(SPECL [`cw1`; `real_integral (:real) cw1`; `&3 * &2 zpow m`; `&0`]
    HAS_REAL_INTEGRAL_AFFINITY_UNIV) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN
      MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
      REWRITE_TAC[CW1_ABSINT]];
    REWRITE_TAC[REAL_ADD_RID] THEN
    DISCH_THEN(MP_TAC o MATCH_MP HAS_REAL_INTEGRAL_INTEGRABLE) THEN
      REWRITE_TAC[]]);;

(* norm(gt(x+.)) is absolutely real-integrable for Schwartz gt               *)
(* (SCHWARTZ_AFFINE s=1,c=x -> shifted Schwartz -> SCHWARTZ_ABSINT ->        *)
(* ABSOLUTELY_INTEGRABLE_NORM).                                              *)
let GT_SHIFT_NORM_REAL_ABSINT = prove
 (`!(gt:real->complex) x. schwartz gt
     ==> (\t. norm(gt(x + t))) absolutely_real_integrable_on (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ABSOLUTELY_REAL_INTEGRABLE_ON; IMAGE_LIFT_UNIV] THEN
  SUBGOAL_THEN `schwartz (\t. (gt:real->complex)(x + t))` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`gt:real->complex`; `&1`; `x:real`] SCHWARTZ_AFFINE) THEN
    ASM_REWRITE_TAC[REAL_MUL_LID; ETA_AX] THEN
    DISCH_THEN MATCH_MP_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP SCHWARTZ_ABSINT) THEN
  DISCH_THEN(MP_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_NORM) THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[o_DEF; FUN_EQ_THM]);;

(* M6 CORE: the (h)(vi) maximal domination for the dilated tent. For         *)
(* Schwartz                                                                  *)
(* gt and a bound M on every straddling average of |gt(x+.)| (a<=-2^{-m},    *)
(* b>=2^{-m}),                                                               *)
(*   int_R |gt(x+t)| cw1(3 2^m t) dt <= M * int_R cw1(3 2^m t) dt.           *)
(* Instantiate MCM_MAXIMAL_DOMINATION at f=|gt(x+.)|, gg=cw1(3 2^m .),       *)
(* al=-2^{-m},                                                               *)
(* be=2^{-m}; all 12 hyps discharged from the CW1_DILATE_* facts +           *)
(* GT_SHIFT_NORM_                                                            *)
(* REAL_ABSINT + the bounded*measurable product (f*gg integrable).           *)
let GT_DILATE_MCM_BOUND = prove
 (`!(gt:real->complex) x m M.
     schwartz gt /\ &0 < &2 zpow m /\
     (!a b. a <= --(&2 zpow(--m)) /\ &2 zpow(--m) <= b
            ==> real_integral (real_interval[a,b]) (\t. norm(gt(x + t))) <= M *
              (b - a))
     ==> real_integral (:real) (\t. norm(gt(x + t)) * cw1(&3 * &2 zpow m * t))
         <= M * real_integral (:real) (\t. cw1(&3 * &2 zpow m * t))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\t. norm((gt:real->complex)(x + t))`;
    `\t. cw1(&3 * &2 zpow m * t)`;
    `--(&2 zpow(--m))`; `&2 zpow(--m)`; `M:real`] MCM_MAXIMAL_DOMINATION) THEN
  ANTS_TAC THENL [ALL_TAC; SIMP_TAC[]] THEN
  MP_TAC(SPEC `m:int` CW1_DILATE_MCM) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow(--m)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\t. norm((gt:real->complex)(x + t)))
     absolutely_real_integrable_on (:real)`
    ASSUME_TAC THENL [MATCH_MP_TAC GT_SHIFT_NORM_REAL_ABSINT THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\t. norm((gt:real->complex)(x + t))) real_measurable_on (:real)`
    ASSUME_TAC THENL
   [ASM_MESON_TAC[ABSOLUTELY_REAL_INTEGRABLE_REAL_MEASURABLE]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\t. cw1(&3 * &2 zpow m * t)) real_measurable_on (:real)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
     REWRITE_TAC[CW1_DILATE_CONT]; ALL_TAC] THEN
  SUBGOAL_THEN
    `real_bounded (IMAGE (\t. cw1(&3 * &2 zpow m * t)) (:real))`
     ASSUME_TAC THENL
   [REWRITE_TAC[real_bounded; FORALL_IN_IMAGE] THEN EXISTS_TAC `cw(&3)` THEN
    X_GEN_TAC `t:real` THEN REWRITE_TAC[IN_UNIV] THEN
    MP_TAC(SPEC `&3 * &2 zpow m * t` CW1_POS) THEN
    SUBGOAL_THEN `cw1(&3 * &2 zpow m * t) <= cw(&3)` MP_TAC THENL
     [REWRITE_TAC[cw1] THEN REAL_ARITH_TAC; REAL_ARITH_TAC]; ALL_TAC] THEN
  ASM_REWRITE_TAC[CW1_POS; NORM_POS_LE; REAL_LE_REFL; CW1_DILATE_CONT] THEN
  REPEAT CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC;
    GEN_TAC THEN MP_TAC(SPEC `&3 * &2 zpow m * x'` CW1_POS) THEN
      REAL_ARITH_TAC;
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC CW1_DILATE_INTEGRABLE THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN MATCH_MP_TAC CW1_DILATE_SUPERLEVEL_BOUNDED THEN
      ASM_REWRITE_TAC[]]);;

(* Reflected companion of GT_SHIFT_NORM_REAL_ABSINT: norm(gt(x-t))           *)
(* real-absint                                                               *)
(* (SCHWARTZ_AFFINE s=-1: gt(x - t) Schwartz). Needed for the (h)(vi)        *)
(* integrand                                                                 *)
(* norm(gt(x0 - t)) (CONVOL_NORM_BOUND gives x0 - t, not x0 + t).            *)
let GT_SHIFT_NORM_REAL_ABSINT_NEG = prove
 (`!(gt:real->complex) x. schwartz gt
     ==> (\t. norm(gt(x - t))) absolutely_real_integrable_on (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ABSOLUTELY_REAL_INTEGRABLE_ON; IMAGE_LIFT_UNIV] THEN
  SUBGOAL_THEN `schwartz (\t. (gt:real->complex)(x - t))` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`gt:real->complex`; `-- &1`; `x:real`] SCHWARTZ_AFFINE) THEN
    REWRITE_TAC[REAL_ARITH `x + -- &1 * t = x - t`] THEN
    ASM_REWRITE_TAC[ETA_AX] THEN DISCH_THEN MATCH_MP_TAC THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP SCHWARTZ_ABSINT) THEN
  DISCH_THEN(MP_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_NORM) THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[o_DEF; FUN_EQ_THM]);;

(* The (h)(vi) product integrand norm(gt(x0-t)) cw1(3 2^m t) is integrable:  *)
(* cw1(3 2^m .) bounded-measurable (CW1_DILATE_CONT + cw1<=cw3) times the    *)
(* L^1 norm(gt(x0-.)) (GT_SHIFT_NORM_REAL_ABSINT_NEG);                       *)
(* ABSOLUTELY_REAL_INTEGRABLE_ BOUNDED_MEASURABLE_PRODUCT after REAL_MUL_SYM *)
(* orients cw1 first.                                                        *)
let GT_CW1_PROD_INTEGRABLE = prove
 (`!(gt:real->complex) m x0.
     schwartz gt /\ &0 < &2 zpow m
     ==> (\t. lift(norm(gt(x0 - drop t)) * cw1(&3 * &2 zpow m * drop t)))
       integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[GSYM IMAGE_LIFT_UNIV] THEN
  REWRITE_TAC[REWRITE_RULE[o_DEF;
    IMAGE_LIFT_UNIV] (GSYM REAL_INTEGRABLE_ON)] THEN
  ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
     REWRITE_TAC[CW1_DILATE_CONT];
    REWRITE_TAC[real_bounded; FORALL_IN_IMAGE] THEN EXISTS_TAC `cw(&3)` THEN
    X_GEN_TAC `s:real` THEN REWRITE_TAC[IN_UNIV] THEN
    MP_TAC(SPEC `&3 * &2 zpow m * s` CW1_POS) THEN
    SUBGOAL_THEN `cw1(&3 * &2 zpow m * s) <= cw(&3)` MP_TAC THENL
     [REWRITE_TAC[cw1] THEN REAL_ARITH_TAC; REAL_ARITH_TAC];
    MATCH_MP_TAC GT_SHIFT_NORM_REAL_ABSINT_NEG THEN ASM_REWRITE_TAC[]]);;

(* Real<->vector integral bridges + the (h)(vi) pointwise arithmetic.        *)
let DROP_VEC_INTEGRAL_EQ_REAL = prove
 (`!(gg:real->real). gg real_integrable_on (:real)
   ==> drop(integral (:real^1) (\t. lift(gg(drop t)))) = real_integral (:real)
     gg`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP REAL_INTEGRAL) THEN
  REWRITE_TAC[IMAGE_LIFT_UNIV; o_DEF] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REFL_TAC);;

let PSICHECK_PTWISE_ARITH = prove
 (`!a M p C1 c. &0 <= a /\ &0 < M /\ &0 <= C1 /\ &0 <= c /\ p <= C1 * c
   ==> a * M * p <= (M * C1) * a * c`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `a * M * (C1 * c):real` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC];
    ASM_REAL_ARITH_TAC]);;

(* Fremlin 286H(vi): |convol gt psicheck (x0)| <= 3 2^m C1 int_R             *)
(* |gt(x0-t)|                                                               *)
(* cw1(3 2^m t) dt.  CONVOL_NORM_BOUND (triangle) -> drop-vec = real bridge  *)
(* (DROP_VEC_INTEGRAL_EQ_REAL) -> REAL_INTEGRAL_LE with the pointwise        *)
(* integrand                                                                 *)
(* bound |psicheck| = 3 2^m |phi(3 2^m t)| <= 3 2^m C1 cw1 (PSICHECK_NORM +  *)
(* CARLESON_PHI_CW1, via PSICHECK_PTWISE_ARITH) -> REAL_INTEGRAL_LMUL pulls  *)
(* the                                                                       *)
(* constant. Integrabilities: GT_CW1_PROD_INTEGRABLE +                       *)
(* CONVOL_INTEGRAND_ABSINT.                                                  *)
let GTM_CONVOL_REAL_BOUND = prove
 (`!(gt:real->complex) m nhat x0 C1.
     schwartz gt /\ &0 < &2 zpow m /\ &0 <= C1 /\
     (!u. norm(carleson_phi u) <= C1 * cw1 u)
     ==> norm(convol gt (psicheck (&3 * &2 zpow m) (dyho_mid m nhat)
       carleson_phi) x0)
         <= (&3 * &2 zpow m) * C1 *
            real_integral (:real) (\t. norm(gt(x0 - t)) * cw1(&3 * &2 zpow m *
              t))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &3 * &2 zpow m` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `schwartz (psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC PSICHECK_SCHWARTZ THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ] THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\t. norm((gt:real->complex)(x0 - t)) * cw1(&3 * &2 zpow m * t))
     real_integrable_on (:real)`
   ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[REAL_INTEGRABLE_ON] THEN
     REWRITE_TAC[IMAGE_LIFT_UNIV; o_DEF] THEN
    MP_TAC(ISPECL [`gt:real->complex`; `m:int`;
      `x0:real`] GT_CW1_PROD_INTEGRABLE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\t. norm((gt:real->complex)(x0 - t)) *
         norm(psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi t))
    real_integrable_on (:real)`
   ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[REAL_INTEGRABLE_ON] THEN
     REWRITE_TAC[IMAGE_LIFT_UNIV; o_DEF] THEN
    MP_TAC(ISPECL [`gt:real->complex`;
                   `psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi`;
                     `x0:real`]
      CONVOL_INTEGRAND_ABSINT) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_NORM) THEN
    DISCH_THEN(MP_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE) THEN
    MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[o_DEF; FUN_EQ_THM; COMPLEX_NORM_MUL]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral (:real)
     (\t. norm((gt:real->complex)(x0 - t)) *
          norm(psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi t))`
            THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`gt:real->complex`;
                   `psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi`;
                     `x0:real`]
      CONVOL_NORM_BOUND) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPEC `\t. norm((gt:real->complex)(x0 - t)) *
                      norm(psicheck (&3 * &2 zpow m) (dyho_mid m nhat)
                        carleson_phi t)`
      DROP_VEC_INTEGRAL_EQ_REAL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      REWRITE_TAC[]; ALL_TAC] THEN
  GEN_REWRITE_TAC (RAND_CONV) [REAL_ARITH `(&3 * M) * C1 * a = ((&3 * M) * C1)
    * a`] THEN
  ASM_SIMP_TAC[GSYM REAL_INTEGRAL_LMUL] THEN
  MATCH_MP_TAC REAL_INTEGRAL_LE THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `t:real` THEN DISCH_TAC THEN REWRITE_TAC[PSICHECK_NORM] THEN
  SUBGOAL_THEN `abs(&3 * &2 zpow m) = &3 * &2 zpow m` SUBST1_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC PSICHECK_PTWISE_ARITH THEN
  REWRITE_TAC[NORM_POS_LE] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(SPEC `&3 * &2 zpow m * t` CW1_POS) THEN REAL_ARITH_TAC;
    REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN ASM_REWRITE_TAC[]]);;

(* --- M6 (h)(vi) reflect: cw1 is even, so the minus-shift integral equals   *)
(* the                                                                       *)
(* plus-shift integral. This turns GTM_CONVOL_REAL_BOUND's int               *)
(* norm(gt(x0-t)) cw1                                                        *)
(* into int norm(gt(x0+t)) cw1, matching GT_DILATE_MCM_BOUND (which uses     *)
(* gt(x+.)).                                                                 *)
let M6_REFLECT = prove
 (`!(gt:real->complex) m x0.
      real_integral (:real) (\t. norm(gt(x0 - t)) * cw1(&3 * &2 zpow m * t)) =
      real_integral (:real) (\t. norm(gt(x0 + t)) * cw1(&3 * &2 zpow m * t))`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`\t. norm((gt:real->complex)(x0 + t)) * cw1(&3 * &2 zpow m *
    t)`;
                 `(:real)`] REAL_INTEGRAL_REFLECT_GEN) THEN
  BETA_TAC THEN
  REWRITE_TAC[REAL_ARITH `!a t:real. a + --t = a - t`; REAL_MUL_RNEG;
    CW1_EVEN] THEN
  SUBGOAL_THEN `IMAGE (--) (:real) = (:real)` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN
    GEN_TAC THEN EXISTS_TAC `--x:real` THEN REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* ========================================================================= *)
(* M6 (h)(vi) capstone: the maximal-domination assembly.  These lemmas take  *)
(* the convolution bound (GTM_CONVOL_REAL_BOUND) through the reflected even  *)
(* kernel (M6_REFLECT), the dilated-tent monotone-kernel domination          *)
(* (GT_DILATE_MCM_BOUND), and the straddling-average <= H-L maximal step     *)
(* (AVG_SHIFT_LE_HL) to the abstract bound |v| <= (C1 int cw1 / sqrt2pi) g~* *)
(* (GTM_MAXIMAL_ABSTRACT). The concrete CARLESON_GTILDE_MAXIMAL (which needs *)
(* FTILDE_CONVOL_EQ) is assembled later, after that lemma.                   *)
(* ========================================================================= *)

(* Pure nonlinear reassociation exposing the (s * inv s) cancellation --     *)
(* REAL_ARITH cannot do it, REAL_RING throws "find" on the inv atom, so      *)
(* state it over a fresh variable w standing for inv s.                      *)
let GTM_REARR = prove
 (`!s c1 mm iv w:real. s * c1 * (mm * (w * iv)) = (s * w) * (c1 * (mm * iv))`,
  REPEAT GEN_TAC THEN CONV_TAC REAL_RING);;

let GTM_DIV_REARR = prove
 (`!c1 iv sp mm:real. ~(sp = &0) ==> (c1 * iv / sp) * mm = (c1 * mm * iv) /
   sp`,
  REPEAT STRIP_TAC THEN CONV_TAC REAL_FIELD);;

(* The constant-folding arithmetic: sp * nv <= s * c1 * (mm * (inv s * iv))  *)
(* ==> nv <= (c1 * iv / sp) * mm. The s cancels against inv s                *)
(* (m-independence                                                           *)
(* of Cgm); sp = sqrt(2 pi) divides through.                                 *)
let GTM_CONST_ARITH = prove
 (`!s c1 mm iv sp nv:real.
     &0 < s /\ &0 < sp /\ &0 <= c1 /\
     sp * nv <= s * c1 * (mm * (inv s * iv))
     ==> nv <= (c1 * iv / sp) * mm`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(s = &0) /\ ~(sp = &0)` STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN
  SUBGOAL_THEN `sp * nv <= c1 * mm * iv` ASSUME_TAC THENL
   [UNDISCH_TAC `sp * nv <= s * c1 * (mm * (inv s * iv))` THEN
    REWRITE_TAC[GTM_REARR] THEN ASM_SIMP_TAC[REAL_MUL_RINV; REAL_MUL_LID];
    ALL_TAC] THEN
  ASM_SIMP_TAC[GTM_DIV_REARR] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
  GEN_REWRITE_TAC (LAND_CONV) [REAL_MUL_SYM] THEN FIRST_X_ASSUM ACCEPT_TAC);;

(* int_R cw1 >= 0 (cw1 nonneg, L^1).                                         *)
let CW1_INTEGRAL_POS = prove
 (`&0 <= real_integral (:real) cw1`,
  MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral (:real) (\x:real. &0)` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[REAL_INTEGRAL_0; REAL_LE_REFL];
    MATCH_MP_TAC REAL_INTEGRAL_LE THEN
    REWRITE_TAC[REAL_INTEGRABLE_0] THEN CONJ_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
       REWRITE_TAC[CW1_ABSINT];
      GEN_TAC THEN DISCH_TAC THEN MP_TAC(SPEC `x:real` CW1_POS) THEN
        REAL_ARITH_TAC]]);;

(* The dilated tent integral value: int_R cw1(3 2^m t) dt = inv(3 2^m) int   *)
(* cw1. This is where the 2^m in Cgm CANCELS -- making Cgm = C1 int cw1 /    *)
(* sqrt2pi m-INDEPENDENT (change of variables via                            *)
(* HAS_REAL_INTEGRAL_AFFINITY_UNIV).                                         *)
let CW1_DILATE_INTEGRAL_VALUE = prove
 (`!m. &0 < &2 zpow m
       ==> real_integral (:real) (\t. cw1(&3 * &2 zpow m * t)) =
           inv(&3 * &2 zpow m) * real_integral (:real) cw1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &3 * &2 zpow m` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_ASSOC] THEN
  MP_TAC(ISPECL [`cw1`; `real_integral (:real) cw1`; `&3 * &2 zpow m`;
    `&0:real`]
    HAS_REAL_INTEGRAL_AFFINITY_UNIV) THEN
  REWRITE_TAC[REAL_ADD_RID] THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN
      MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
        REWRITE_TAC[CW1_ABSINT]];
    ALL_TAC] THEN
  SUBGOAL_THEN `abs(&3 * &2 zpow m) = &3 * &2 zpow m` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[REAL_ABS_REFL] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN REFL_TAC);;

(* Translation of the shift integral: int_[a,b] |gt(x+t)| =                  *)
(* int_[x+a,x+b]|gt|. HAS_REAL_INTEGRAL_AFFINITY at m=1,c=x; the image       *)
(* [x+a,x+b] maps to [a,b].                                                  *)
let NORM_GT_TRANSLATE_INTEGRAL = prove
 (`!(gt:real->complex) x a b.
     schwartz gt
     ==> real_integral (real_interval[a,b]) (\t. norm(gt(x + t))) =
         real_integral (real_interval[x + a,x + b]) (\z. norm(gt z))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\z. norm((gt:real->complex) z)`;
                 `real_integral (real_interval[x+a,x+b]) (\z.
                   norm((gt:real->complex) z))`;
                 `x + a:real`; `x + b:real`; `&1:real`;
                   `x:real`] HAS_REAL_INTEGRAL_AFFINITY) THEN
  REWRITE_TAC[REAL_MUL_LID; REAL_INV_1; REAL_ABS_NUM;
    REAL_ARITH `&1 * x' + x = x + x'`] THEN
  ANTS_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_EQ; ARITH_EQ] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN
    MATCH_MP_TAC REAL_INTEGRABLE_CONTINUOUS THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real)` THEN
    REWRITE_TAC[SUBSET_UNIV; REAL_CONTINUOUS_ON; o_DEF; IMAGE_LIFT_UNIV] THEN
    MATCH_MP_TAC CONTINUOUS_ON_LIFT_NORM_COMPOSE THEN
    MP_TAC(ISPEC `gt:real->complex` SCHWARTZ_CONT) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `IMAGE (\x'. x' - x) (real_interval[x + a,x + b]) = real_interval[a,b]`
    SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL] THEN
    GEN_TAC THEN EQ_TAC THENL
     [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      STRIP_TAC THEN EXISTS_TAC `x + x':real` THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN REFL_TAC);;

(* Every average of |gt| is <= any Schwartz sup bound B (the technical sup   *)
(* upper-bound feeding AVG_LE_HL_MAXIMAL's REAL_LE_SUP).                     *)
let AVG_NORM_LE_BOUND = prove
 (`!(gt:real->complex) B c d.
     schwartz gt /\ (!x. norm(gt x) <= B) /\ c < d
     ==> real_integral (real_interval[c,d]) (\t. abs(norm(gt t))) / (d - c) <=
       B`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_ABS_NORM] THEN
  SUBGOAL_THEN `&0 < d - c` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral (real_interval[c,d]) (\t:real. B)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LE THEN
    ASM_SIMP_TAC[REAL_LT_IMP_LE; NORM_POS_LE] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_CONTINUOUS THEN
      MATCH_MP_TAC REAL_CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real)` THEN
      REWRITE_TAC[SUBSET_UNIV; REAL_CONTINUOUS_ON; o_DEF; IMAGE_LIFT_UNIV] THEN
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_NORM_COMPOSE THEN
      MP_TAC(ISPEC `gt:real->complex` SCHWARTZ_CONT) THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_INTEGRABLE_CONST]];
    ASM_SIMP_TAC[REAL_INTEGRAL_CONST; REAL_LT_IMP_LE] THEN
    REWRITE_TAC[REAL_MUL_SYM; REAL_LE_REFL]]);;

(* The straddling-average step: for |x-x'|<=2^{-m} and a<=-2^{-m},           *)
(* b>=2^{-m},                                                                *)
(* int_[a,b]|gt(x+t)| <= g~*(x') (b-a).  Translate then AVG_LE_HL_MAXIMAL    *)
(* (x' is interior to [x+a,x+b]).                                            *)
let AVG_SHIFT_LE_HL = prove
 (`!(gt:real->complex) x x' m a b.
     schwartz gt /\ &0 < &2 zpow m /\ abs(x - x') <= &2 zpow(--m) /\
     a <= --(&2 zpow(--m)) /\ &2 zpow(--m) <= b
     ==> real_integral (real_interval[a,b]) (\t. norm(gt(x + t)))
         <= hl_maximal (\z. norm(gt z)) x' * (b - a)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `gt:real->complex` SCHWARTZ_BOUNDED) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `B:real`) THEN
  SUBGOAL_THEN `&0 < &2 zpow(--m)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`gt:real->complex`; `x:real`; `a:real`; `b:real`]
    NORM_GT_TRANSLATE_INTEGRAL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `&0 < b - a` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\z. norm((gt:real->complex) z)`; `B:real`; `x + a:real`; `x + b:real`;
     `x':real`]
   AVG_LE_HL_MAXIMAL) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC;
      REPEAT STRIP_TAC THEN BETA_TAC THEN
      MATCH_MP_TAC AVG_NORM_LE_BOUND THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[REAL_ABS_NORM;
    REAL_ARITH `!x a b:real. (x + b) - (x + a) = b - a`] THEN
  ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN REWRITE_TAC[REAL_MUL_SYM]);;

(* GTM_MAXIMAL_ABSTRACT = Fremlin 286L (h)(vi), abstract form.  Whenever the *)
(* convolution gt * psicheck at x factors as sqrt(2 pi) v, the complex value *)
(* v                                                                         *)
(* is dominated by (C1 int cw1 / sqrt2pi) times the H-L maximal function of  *)
(* gt                                                                        *)
(* at any x' with |x-x'| <= 2^{-m}. This is the whole (vi) chain: convol     *)
(* norm                                                                      *)
(* bound -> reflect -> dilated-tent MCM domination -> straddling avg <= g~*  *)
(* ->                                                                        *)
(* 2^m cancellation -> constant fold.                                        *)
let GTM_MAXIMAL_ABSTRACT = prove
 (`!(gt:real->complex) (v:complex) m nhat x x' C1.
     schwartz gt /\ &0 < &2 zpow m /\ abs(x - x') <= &2 zpow(--m) /\
     &0 <= C1 /\ (!u. norm(carleson_phi u) <= C1 * cw1 u) /\
     convol gt (psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi) x =
       Cx(sqrt(&2 * pi)) * v
     ==> norm v <= (C1 * real_integral (:real) cw1 / sqrt(&2 * pi)) *
                   hl_maximal (\z. norm(gt z)) x'`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `M = hl_maximal (\z. norm((gt:real->complex) z)) x'` THEN
  SUBGOAL_THEN `&0 < sqrt(&2 * pi)` ASSUME_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &3 * &2 zpow m` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `norm(convol gt (psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi)
     x)
    <= (&3 * &2 zpow m) * C1 *
       real_integral (:real) (\t. norm((gt:real->complex)(x + t)) * cw1(&3 * &2
         zpow m * t))`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`gt:real->complex`; `m:int`; `nhat:int`; `x:real`;
     `C1:real`]
      GTM_CONVOL_REAL_BOUND) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[M6_REFLECT]; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (:real) (\t. norm((gt:real->complex)(x + t)) * cw1(&3 * &2
     zpow m * t))
    <= M * (inv(&3 * &2 zpow m) * real_integral (:real) cw1)`
   ASSUME_TAC THENL
   [MP_TAC(SPEC `m:int` CW1_DILATE_INTEGRAL_VALUE) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [GSYM th])
      THEN
    MATCH_MP_TAC GT_DILATE_MCM_BOUND THEN ASM_REWRITE_TAC[] THEN
    REPEAT STRIP_TAC THEN EXPAND_TAC "M" THEN
    MATCH_MP_TAC AVG_SHIFT_LE_HL THEN EXISTS_TAC `m:int` THEN
      ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `sqrt(&2 * pi) * norm(v:complex)
    <= (&3 * &2 zpow m) * C1 *
       (M * (inv(&3 * &2 zpow m) * real_integral (:real) cw1))`
   ASSUME_TAC THENL
   [SUBGOAL_THEN
     `sqrt(&2 * pi) * norm(v:complex) =
      norm(convol gt (psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi)
        x)`
     SUBST1_TAC THENL
     [ASM_REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
      ASM_SIMP_TAC[REAL_ARITH `&0 < s ==> abs s = s`]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `(&3 * &2 zpow m) * C1 *
       real_integral (:real) (\t. norm((gt:real->complex)(x + t)) * cw1(&3 * &2
         zpow m * t))` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`&3 * &2 zpow m`; `C1:real`; `M:real`;
    `real_integral (:real) cw1`;
                 `sqrt(&2 * pi)`; `norm(v:complex)`] GTM_CONST_ARITH) THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* --- 286Gd: the two-sided continuous weight sum sum_{n in Z} w(x-n) <= 2   *)
(* ---                                                                       *)
(* (v2's pointwise engine in alpha2: sum_{sigma: k_sigma=k}                  *)
(* w(2^k(x-x_sigma)) <=                                                      *)
(* sum_n w(2^k x - n - 1/2) <= 2, since the x_sigma lie on the half-integer  *)
(* grid.)                                                                    *)
(* Route: nearest-integer split; peak term w(r) <= 1; each side sum <= 1/2   *)
(* via the                                                                   *)
(* CUBIC telescoping tail CW_SUM_BOUND (NOT the Hermite-Hadamard integral    *)
(* comparison).                                                              *)

(* Per-term shift bound: for |r| <= 1/2 and offset j >= 1, both cw(r-&j) and *)
(* cw(r+&j)                                                                  *)
(* are <= cw(j-1/2) (the nearest the shifted point can get to 0 is j-1/2).   *)
(* CW_ANTITONE.                                                              *)
let CW_SHIFT_BND = prove
 (`!r j:num. abs r <= &1 / &2 /\ 1 <= j
     ==> cw(r - &j) <= cw(&j - &1 / &2) /\ cw(r + &j) <= cw(&j - &1 / &2)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= &j` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_LE] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THEN MATCH_MP_TAC CW_ANTITONE THEN ASM_REAL_ARITH_TAC);;

(* The half-integer partial sum sum_{1..N} w(j-1/2) <= 1/2. Reindex j |->    *)
(* j-1 (via                                                                  *)
(* SUM_OFFSET, instantiated EXPLICITLY to avoid the aggressive 1 = 0+1       *)
(* rewrite hitting                                                           *)
(* the &1/&2) to sum_{0..N-1} w(j+1/2), then CW_SUM_BOUND at m=0 gives <=    *)
(* 1/(2 (1)^2).                                                              *)
let CW_NUMSEG_HALF_SUM = prove
 (`!N:num. sum (1..N) (\j. cw(&j - &1 / &2)) <= &1 / &2`,
  GEN_TAC THEN ASM_CASES_TAC `N = 0` THENL
   [ASM_REWRITE_TAC[] THEN REWRITE_TAC[num_CONV `1`; SUM_CLAUSES_NUMSEG] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  SUBGOAL_THEN `?M. N = M + 1` (CHOOSE_THEN SUBST_ALL_TAC) THENL
   [EXISTS_TAC `N - 1` THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `sum (1..M + 1) (\j. cw(&j - &1 / &2)) = sum (0..M) (\j. cw(&j + &1 / &2))`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`1`; `\j:num. cw(&j - &1 / &2)`; `0`;
     `M:num`] SUM_OFFSET) THEN
    REWRITE_TAC[ADD_CLAUSES] THEN DISCH_THEN SUBST1_TAC THEN
    MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      REWRITE_TAC[] THEN
    AP_TERM_TAC THEN REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN REAL_ARITH_TAC;
    MP_TAC(ISPECL [`0`; `M:num`] CW_SUM_BOUND) THEN
    MATCH_MP_TAC(REAL_ARITH `c = &1 / &2 ==> s <= c ==> s <= &1 / &2`) THEN
    CONV_TAC REAL_RAT_REDUCE_CONV]);;

(* One-sided sums (left and right of the peak): for a finite set J of        *)
(* offsets >= 1,                                                             *)
(* sum_{j in J} cw(r -/+ &j) <= 1/2. Dominate termwise by cw(j-1/2)          *)
(* (CW_SHIFT_BND),                                                           *)
(* then by the full sum_{1..maxJ} (nonneg tail, CW_POS), then                *)
(* CW_NUMSEG_HALF_SUM.                                                       *)
let CW_ONESIDE_SUM = prove
 (`!r (J:num->bool). abs r <= &1 / &2 /\ FINITE J /\ (!j. j IN J ==> 1 <= j)
     ==> sum J (\j. cw(r - &j)) <= &1 / &2`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum J (\j. cw(&j - &1 / &2))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `j:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`r:real`; `j:num`] CW_SHIFT_BND) THEN ASM_SIMP_TAC[] THEN
      SIMP_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\j:num. j`; `J:num->bool`] UPPER_BOUND_FINITE_SET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (1..N) (\j. cw(&j - &1 / &2))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
    ASM_REWRITE_TAC[FINITE_NUMSEG] THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_NUMSEG] THEN X_GEN_TAC `j:num` THEN DISCH_TAC THEN
      CONJ_TAC THENL [ASM_SIMP_TAC[]; ASM_SIMP_TAC[]];
      X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_DIFF] THEN STRIP_TAC THEN
      MATCH_MP_TAC REAL_LT_IMP_LE THEN REWRITE_TAC[CW_POS]];
    REWRITE_TAC[CW_NUMSEG_HALF_SUM]]);;

let CW_ONESIDE_SUM_R = prove
 (`!r (J:num->bool). abs r <= &1 / &2 /\ FINITE J /\ (!j. j IN J ==> 1 <= j)
     ==> sum J (\j. cw(r + &j)) <= &1 / &2`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum J (\j. cw(&j - &1 / &2))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `j:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`r:real`; `j:num`] CW_SHIFT_BND) THEN ASM_SIMP_TAC[] THEN
      SIMP_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\j:num. j`; `J:num->bool`] UPPER_BOUND_FINITE_SET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (1..N) (\j. cw(&j - &1 / &2))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
    ASM_REWRITE_TAC[FINITE_NUMSEG] THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_NUMSEG] THEN X_GEN_TAC `j:num` THEN DISCH_TAC THEN
      CONJ_TAC THENL [ASM_SIMP_TAC[]; ASM_SIMP_TAC[]];
      X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_DIFF] THEN STRIP_TAC THEN
      MATCH_MP_TAC REAL_LT_IMP_LE THEN REWRITE_TAC[CW_POS]];
    REWRITE_TAC[CW_NUMSEG_HALF_SUM]]);;

(* The tile weight is antitone in the distance from its centre x_sigma:      *)
(* points                                                                    *)
(* further from x_sigma have smaller w_sigma. (Underlies 286L(c)'s sup_{x in *)
(* K}                                                                        *)
(* w_sigma bound.)  Lifts CW_ANTITONE through the positive 2^k scaling.      *)
let CWTILE_ANTITONE = prove
 (`!(s:int#int#int) x y. abs(y - tile_xmid s) <= abs(x - tile_xmid s)
     ==> cw_tile s x <= cw_tile s y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cw_tile] THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC CW_ANTITONE THEN
  REWRITE_TAC[REAL_ABS_MUL] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_ABS_POS]; ASM_REWRITE_TAC[]]);;

(* 286L(c-i) geometric decay: if the point x is at distance >= d from the    *)
(* tile                                                                      *)
(* centre x_sigma, the tile weight there is <= its value at distance exactly *)
(* d,                                                                        *)
(*   cw_tile s x <= 2^{k} cw(2^{k} d).                                       *)
(* (cw_tile s (x_s + d) = 2^k cw(2^k d), and CWTILE_ANTITONE monotone in the *)
(* centre-distance.) Supplies the Mw = 2^{k} cw(2^{k} rho(x_s,K)) upper      *)
(* bound to                                                                  *)
(* CARLESON_KERNEL_CI, with d = rho(x_s,K) the distance from x_sigma to the  *)
(* cover                                                                     *)
(* cell K (x_sigma lies outside K, since I_sigma escapes the tripled cell    *)
(* Kstar).                                                                   *)
let CWTILE_DIST_BOUND = prove
 (`!(s:int#int#int) x d. &0 <= d /\ d <= abs(x - tile_xmid s)
     ==> cw_tile s x <= &2 zpow (tile_k s) * cw(&2 zpow (tile_k s) * d)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&2 zpow (tile_k s) * cw(&2 zpow (tile_k s) * d) =
                cw_tile s (tile_xmid s + d)` SUBST1_TAC THENL
   [REWRITE_TAC[cw_tile] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC CWTILE_ANTITONE THEN
  REWRITE_TAC[REAL_ARITH `(tile_xmid s + d) - tile_xmid s = d`] THEN
  ASM_REAL_ARITH_TAC);;

(* 2^k_tau * 2^(k - k_tau - 1) = 2^(k-1)  (zpow exponent arithmetic).        *)
let TILE_IDIL_INTERVAL = prove
 (`!(s:int#int#int) k. tile_Idil s k =
     real_interval(tile_xmid s - &2 zpow (&k - tile_k s - &1),
                   tile_xmid s + &2 zpow (&k - tile_k s - &1))`,
  REPEAT GEN_TAC THEN
    REWRITE_TAC[tile_Idil; EXTENSION; IN_ELIM_THM; IN_REAL_INTERVAL] THEN
  GEN_TAC THEN REAL_ARITH_TAC);;

let ZPOW_DOUBLE_KTAU = prove
 (`!(s:int#int#int) k. &2 * &2 zpow (&k - tile_k s - &1) = &2 zpow (&k - tile_k
   s)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
    `&2 zpow (&k - tile_k s) = &2 zpow (&1 + (&k - tile_k s - &1))` SUBST1_TAC
    THENL
   [AP_TERM_TAC THEN INT_ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`; REAL_ZPOW_1]);;

let TILE_IDIL_MEASURABLE = prove
 (`!(s:int#int#int) k. real_measurable (tile_Idil s k)`,
  REWRITE_TAC[TILE_IDIL_INTERVAL; REAL_MEASURABLE_REAL_INTERVAL]);;

let TILE_IDIL_MEASURE = prove
 (`!(s:int#int#int) k. real_measure (tile_Idil s k) = &2 zpow (&k - tile_k s)`,
  REPEAT GEN_TAC THEN
    REWRITE_TAC[TILE_IDIL_INTERVAL; REAL_MEASURE_REAL_INTERVAL] THEN
  SUBGOAL_THEN
   `(tile_xmid s + &2 zpow (&k - tile_k s - &1)) -
    (tile_xmid s - &2 zpow (&k - tile_k s - &1)) = &2 zpow (&k - tile_k s)`
   SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ARITH `(c + r) - (c - r) = &2 * r`; ZPOW_DOUBLE_KTAU];
     ALL_TAC] THEN
  REWRITE_TAC[REAL_ARITH `max x (&0) = x <=> &0 <= x`] THEN
  MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
    REAL_ARITH_TAC);;

(* Dilate geometry for 286J(c): the I_tau^(k) nest and base-containment.     *)
(* Monotone in k: I^(k)_s SUBSET I^(k')_s for k<=k' (half-widths 2^(k-k_s-1) *)
(* <=                                                                        *)
(* 2^(k'-k_s-1) via ZPOW2_MONOE). Base: I_s SUBSET I^(k)_s for k>=1 (a point *)
(* of                                                                        *)
(* I_s is within 2^(-k_s) of x_s [DYHO_MID_DIST] <= 2^(k-k_s-1) half-width). *)
let TILE_IDIL_MONO = prove
 (`!(s:int#int#int) k k'. k <= k' ==> tile_Idil s k SUBSET tile_Idil s k'`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[TILE_IDIL_INTERVAL; SUBSET; IN_REAL_INTERVAL] THEN
  X_GEN_TAC `x:real` THEN
  SUBGOAL_THEN `&2 zpow (&k - tile_k s - &1) <= &2 zpow (&k' - tile_k s - &1)`
   MP_TAC THENL
   [MATCH_MP_TAC ZPOW2_MONOE THEN
    FIRST_ASSUM(MP_TAC o REWRITE_RULE[GSYM INT_OF_NUM_LE]) THEN INT_ARITH_TAC;
    REAL_ARITH_TAC]);;

let CWTILE_OUTSIDE_IDIL_LE = prove
 (`!tau k x.
     ~(x IN tile_Idil tau k)
     ==> cw_tile tau x <=
         cw_tile tau (tile_xmid tau + &2 zpow (&k - tile_k tau - &1))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CWTILE_ANTITONE THEN
  POP_ASSUM MP_TAC THEN
  REWRITE_TAC[tile_Idil; IN_ELIM_THM; REAL_NOT_LT] THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 <= &2 zpow (&k - tile_k tau - &1)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* the edge value: cw_tile tau (x_tau + 2^{k-k_tau-1}) = 2^{k_tau}           *)
(* cw(2^{k-1}).                                                              *)
let CWTILE_IDIL_EDGE_VALUE = prove
 (`!tau k.
     cw_tile tau (tile_xmid tau + &2 zpow (&k - tile_k tau - &1)) =
     &2 zpow (tile_k tau) * cw (&2 zpow (&k - &1))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cw_tile] THEN
  SUBGOAL_THEN `&2 zpow (tile_k tau) *
      ((tile_xmid tau + &2 zpow (&k - tile_k tau - &1)) - tile_xmid tau) =
      &2 zpow (&k - &1)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ARITH `!x e:real. (x + e) - x = e`] THEN
    SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ] THEN
    AP_TERM_TAC THEN INT_ARITH_TAC;
    REFL_TAC]);;

(* combined: outside I^(k)_tau, w_tau(x) <= 2^{k_tau} cw(2^{k-1}). This is   *)
(* the                                                                       *)
(* pointwise weight bound feeding the annulus tail sum of 286J(b).           *)
let CWTILE_OUTSIDE_IDIL_BOUND = prove
 (`!tau k x.
     ~(x IN tile_Idil tau k)
     ==> cw_tile tau x <= &2 zpow (tile_k tau) * cw (&2 zpow (&k - &1))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `cw_tile tau (tile_xmid tau + &2 zpow (&k - tile_k tau - &1))`
    THEN
  ASM_SIMP_TAC[CWTILE_OUTSIDE_IDIL_LE; CWTILE_IDIL_EDGE_VALUE; REAL_LE_REFL]);;

(* peak weight bound: w_tau(x) <= muJ_tau = 2^{k_tau} everywhere (cw <= 1).  *)
let CWTILE_LE_MUJ = prove
 (`!s x. cw_tile s x <= &2 zpow (tile_k s)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cw_tile] THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN
  REWRITE_TAC[CW_LE_1] THEN MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Measure of a dyadic interval: mu(dyho k n) = 2^k, and of a tile's spatial *)
(* interval: mu(I_tau) = 2^(-k_tau). dyho k n = (a,b) UNION {a} (half-open), *)
(* so the left endpoint is a null add-on.                                    *)
(* ------------------------------------------------------------------------- *)

let REAL_MEASURABLE_SING = prove
 (`!a:real. real_measurable {a}`,
  GEN_TAC THEN MATCH_MP_TAC HAS_REAL_MEASURE_IMP_REAL_MEASURABLE THEN
  EXISTS_TAC `&0` THEN REWRITE_TAC[HAS_REAL_MEASURE_0; REAL_NEGLIGIBLE_SING]);;

let REAL_MEASURE_SING = prove
 (`!a:real. real_measure {a} = &0`,
  GEN_TAC THEN MATCH_MP_TAC REAL_MEASURE_UNIQUE THEN
  REWRITE_TAC[HAS_REAL_MEASURE_0; REAL_NEGLIGIBLE_SING]);;

let DYHO_UNION_SING = prove
 (`!k n. dyho k n =
     real_interval(real_of_int n * &2 zpow k, (real_of_int n + &1) * &2 zpow k)
       UNION
     {real_of_int n * &2 zpow k}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; EXTENSION; IN_UNION; IN_ELIM_THM;
    IN_REAL_INTERVAL; IN_SING] THEN
  GEN_TAC THEN
  SUBGOAL_THEN
    `real_of_int n * &2 zpow k < (real_of_int n + &1) * &2 zpow k` MP_TAC THENL
   [MATCH_MP_TAC REAL_LT_RMUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC]; ALL_TAC] THEN
  REAL_ARITH_TAC);;

let DYHO_MEASURABLE = prove
 (`!k n. real_measurable (dyho k n)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[DYHO_UNION_SING] THEN
  MATCH_MP_TAC REAL_MEASURABLE_UNION THEN
  REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL; REAL_MEASURABLE_SING]);;

let DYHO_MEASURE = prove
 (`!k n. real_measure (dyho k n) = &2 zpow k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[DYHO_UNION_SING] THEN
  W(MP_TAC o PART_MATCH (lhs o rand) REAL_MEASURE_REAL_NEGLIGIBLE_UNION o lhs o
    snd) THEN
  REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL; REAL_MEASURABLE_SING] THEN
    ANTS_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN
    EXISTS_TAC `{real_of_int n * &2 zpow k}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_SING; INTER_SUBSET]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL; REAL_MEASURE_SING; REAL_ADD_RID] THEN
  SUBGOAL_THEN
    `(real_of_int n + &1) * &2 zpow k - real_of_int n * &2 zpow k = &2 zpow k`
    SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_ARITH `max x (&0) = x <=> &0 <= x`] THEN
  MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
    REAL_ARITH_TAC);;

let TILE_I_MEASURE = prove
 (`!(k:int) (nI:int) (nJ:int).
     real_measure (tile_I (k,nI,nJ)) = &2 zpow (--k)`,
  REWRITE_TAC[tile_I; DYHO_MEASURE]);;

let TILE_I_MEASURABLE = prove
 (`!(k:int) (nI:int) (nJ:int). real_measurable (tile_I (k,nI,nJ))`,
  REWRITE_TAC[tile_I; DYHO_MEASURABLE]);;

(* ------------------------------------------------------------------------- *)
(* 286L maximal-cover backbone (abstract set theory).  In a finite family of *)
(* sets, every member is contained in a SUBSET-MAXIMAL member -- the greedy  *)
(* selection Fremlin's maximal dyadic cover K rests on. No such lemma exists *)
(* in the library, so it is built here from finiteness.                      *)
(* ------------------------------------------------------------------------- *)

(* The candidate set {N in Fam | s' SUBSET N} shrinks strictly when s'       *)
(* strictly enlarges s (s stays above s but drops below s'), giving the      *)
(* well-founded measure for the maximal-member recursion.                    *)
let DISJOINT_FAMILY_MEASURE_SUM = prove
 (`!K:(real->bool)->bool. FINITE K /\
     (!c. c IN K ==> real_measurable c) /\
     (!M1 M2. M1 IN K /\ M2 IN K /\ ~(M1 = M2) ==> DISJOINT M1 M2)
     ==> real_measure(UNIONS K) = sum K (\c. real_measure c)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\c:real->bool. c`; `K:(real->bool)->bool`]
    REAL_MEASURE_DISJOINT_UNIONS_IMAGE) THEN
  ASM_REWRITE_TAC[IMAGE_ID; ETA_AX]);;

(* 286L(a-ii) measure-counting core: a FINITE family K of pairwise-disjoint  *)
(* measurable cells, all contained in a bounded measurable B, has total      *)
(* measure                                                                   *)
(* sum_{c in K} mu(c) <= mu(B). (sum = mu(UNIONS K) by                       *)
(* DISJOINT_FAMILY_MEASURE_SUM;                                              *)
(* UNIONS K SUBSET B by REAL_MEASURE_SUBSET.) In 286L: the cover cells K     *)
(* with                                                                      *)
(* l_K >= k_tau are disjoint and sit in Ihat (mu = 7 2^{-k_tau}), so sum     *)
(* 2^{-l_K} <=                                                               *)
(* 7 2^{-k_tau} -- the a-ii bound driving alpha0.                            *)
let DISJOINT_CELLS_MEASURE_SUM_LE = prove
 (`!(K:(real->bool)->bool) B.
     FINITE K /\ real_measurable B /\
     (!c. c IN K ==> real_measurable c) /\
     (!c. c IN K ==> c SUBSET B) /\
     (!M1 M2. M1 IN K /\ M2 IN K /\ ~(M1 = M2) ==> DISJOINT M1 M2)
     ==> sum K (\c. real_measure c) <= real_measure B`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `K:(real->bool)->bool` DISJOINT_FAMILY_MEASURE_SUM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_MEASURE_SUBSET THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_UNIONS THEN ASM_REWRITE_TAC[];
    ASM SET_TAC[]]);;

(* Abstract per-cover-cell summation: if each cell's contribution g(c) <= D  *)
(* mu(c) (D >= 0) and the cells' total measure sum mu(c) <= S, then sum g(c) *)
(* <= D S. Packages the alpha0/alpha1 "per-cell bound x measure-counting"    *)
(* step: with D = 2 C1 energy mass (the per-cell factor from                 *)
(* ABSTRACT_SCALE_GEOM_SUM, since mu(K) = 2^{-l_K}) and S = mu(Ihat) = 7     *)
(* 2^{-k_tau} (from DISJOINT_CELLS_MEASURE_ SUM_LE), gives sum_K g(K) <= 14  *)
(* C1 energy mass 2^{-k_tau} -- the alpha0 shape.                            *)
let dyho_star = new_definition
 `dyho_star (k:int) (n:int) =
    {x:real | (real_of_int n - &1) * &2 zpow k <= x /\
              x < (real_of_int n + &2) * &2 zpow k}`;;

let DYHO_SUBSET_STAR = prove
 (`!k n. dyho k n SUBSET dyho_star k n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; dyho_star; SUBSET; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real` THEN
  SUBGOAL_THEN `&0 < &2 zpow k` MP_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* The TRIPLED child cell sits inside the TRIPLED parent: (dyho a p)* SUBSET *)
(* (dyho (a+1) (p div 2))*. Key to the maximal-cover soundness -- with p =   *)
(* 2q+r,                                                                     *)
(* r in {0,1}: child* = [(p-1)2^a,(p+2)2^a), parent* =                       *)
(* [(2q-2)2^a,(2q+4)2^a); -1<=r                                              *)
(* and r<=2 give the containment on both edges.                              *)
let DYHO_STAR_PARENT = prove
 (`!a p:int. dyho_star a p SUBSET dyho_star (a + &1) (p div &2)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho_star; SUBSET; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real` THEN
  SUBGOAL_THEN
    `&0 < &2 zpow a /\ &2 zpow (a + &1) =
     &2 * &2 zpow a` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
      SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
      REWRITE_TAC[REAL_ZPOW_1] THEN REAL_ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
    `real_of_int p = &2 * real_of_int (p div &2) + real_of_int(p rem &2) /\
                &0 <= real_of_int(p rem &2) /\ real_of_int(p rem &2) <= &1`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`p:int`; `&2:int`] INT_DIVISION) THEN
    ANTS_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
    STRIP_TAC THEN REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES] THEN
    REPEAT CONJ_TAC THEN REWRITE_TAC[REAL_OF_INT_CLAUSES] THEN
      ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(real_of_int (p div &2) - &1) * &2 zpow (a + &1) =
    (real_of_int p - &1) * &2 zpow a - (&1 + real_of_int(p rem &2)) * &2 zpow a
      /\
    (real_of_int (p div &2) + &2) * &2 zpow (a + &1) =
    (real_of_int p + &2) * &2 zpow a + (&2 - real_of_int(p rem &2)) * &2 zpow
      a`
    (CONJUNCTS_THEN SUBST1_TAC) THENL
   [CONJ_TAC THEN
    MAP_EVERY UNDISCH_TAC
     [`real_of_int p = &2 * real_of_int (p div &2) + real_of_int(p rem &2)`;
      `&2 zpow (a + &1) = &2 * &2 zpow a`] THEN
    CONV_TAC REAL_RING; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= (&1 + real_of_int(p rem &2)) * &2 zpow a /\
                &0 <= (&2 - real_of_int(p rem &2)) * &2 zpow a`
                  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC REAL_LE_MUL THEN
     ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  FIRST_X_ASSUM(K ALL_TAC o check (fun th ->
    free_in `(p:int) div &2` (concl th)) o SPEC_ALL) THEN
  STRIP_TAC THEN CONJ_TAC THEN ASM_REAL_ARITH_TAC);;

(* 286L(a) buffer: a point x OUTSIDE the tripled cell dyho_star k n is at    *)
(* least                                                                     *)
(* 2^k away from every point y IN dyho k n. (dyho_star = [(n-1)2^k,          *)
(* (n+2)2^k),                                                                *)
(* dyho = [n 2^k, (n+1)2^k); the excluded region is a full cell-width past   *)
(* each                                                                      *)
(* edge.) This is the rho(x_sigma, K) >= 2^{-l_K} lower bound feeding the    *)
(* alpha0/                                                                   *)
(* alpha1 offset map's range: I_sigma escapes K-tripled => x_sigma outside   *)
(* K* =>                                                                     *)
(* dist(x_sigma, K) >= mu K = 2^{-l_K}.                                      *)
let in_jscript = new_definition
 `in_jscript (P:(int#int#int)->bool) (a:int) (p:int) <=>
    !s. s IN P /\ &2 zpow (--(tile_k s)) <= &2 zpow a
        ==> ~(tile_I s SUBSET dyho_star a p)`;;

(* in_kcover P a p: dyho a p is a MAXIMAL member of Cal J = a cover cell of  *)
(* Cal K.                                                                    *)
let in_kcover = new_definition
 `in_kcover (P:(int#int#int)->bool) (a:int) (p:int) <=>
    in_jscript P a p /\ ~(in_jscript P (a + &1) (p div &2))`;;

(* PARENT-DOWNWARD-CLOSURE of Cal J: if the parent cell is in Cal J, so is   *)
(* the                                                                       *)
(* child. This is what makes in_kcover (in J /\ parent not in J) coincide    *)
(* with the                                                                  *)
(* genuine "maximal member of Cal J": climbing parents, once you leave Cal J *)
(* you                                                                       *)
(* stay out (contrapositive), so the first cell to leave IS the maximal one. *)
(* Proof:                                                                    *)
(* a witness sigma for child-not-in-J (mu I_sigma <= 2^a, I_sigma inside     *)
(* child-triple)                                                             *)
(* also witnesses parent-not-in-J: 2^a <= 2^{a+1} and child-triple SUBSET    *)
(* parent-                                                                   *)
(* triple (DYHO_STAR_                                                        *)
(* PARENT).                                                                  *)
let KCOVER_PARENT_WITNESS = prove
 (`!P:(int#int#int)->bool a p.
     in_kcover P a p
     ==> ?sig. sig IN P /\ &2 zpow (--(tile_k sig)) <= &2 zpow (a + &1) /\
               tile_I sig SUBSET dyho_star (a + &1) (p div &2)`,
  REWRITE_TAC[in_kcover; in_jscript] THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o check (is_neg o concl)) THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN
  MATCH_MP_TAC MONO_EXISTS THEN GEN_TAC THEN SIMP_TAC[]);;

(* 286L(e) step a (interpolate): from the witness sigma (mu I_sigma <= 2 mu  *)
(* K = 2^{a+1})                                                              *)
(* and P's lower bound tau (tile_le sig tau), with 2 mu K <= mu I_tau        *)
(* (2^{a+1} <=                                                               *)
(* 2^{-k_tau}, the W2 case mu K < mu I_tau), TILE_INTERP yields upsilon at   *)
(* scale                                                                     *)
(* k_ups = -(a+1) (mu I_ups = 2^{a+1} = 2 mu K) with tau <= ups <= sigma (my *)
(* tile_le sig                                                               *)
(* ups /\ tile_le ups tau). Scale bounds k_tau <= -(a+1) <= k_sig via        *)
(* ZPOW2_LE_REV.                                                             *)
let GK_UPSILON = prove
 (`!P:(int#int#int)->bool a p sig tau.
     sig IN P /\ tile_le sig tau /\
     &2 zpow (--(tile_k sig)) <= &2 zpow (a + &1) /\
     &2 zpow (a + &1) <= &2 zpow (--(tile_k tau))
     ==> ?ups. tile_le sig ups /\ tile_le ups tau /\ tile_k ups = --(a + &1)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC TILE_INTERP THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o MATCH_MP ZPOW2_LE_REV o
      check(fun th -> rand(concl th) = `&2 zpow (--(tile_k tau))`)) THEN
        INT_ARITH_TAC;
    FIRST_X_ASSUM(MP_TAC o MATCH_MP ZPOW2_LE_REV o
      check(fun th -> lhand(concl th) = `&2 zpow (--(tile_k sig))`)) THEN
        INT_ARITH_TAC]);;

(* GENERAL nested-cell facts (for cover disjointness). From dyho a p SUBSET  *)
(* dyho b                                                                    *)
(* q: the endpoint inequalities (left/right), the tripled cells nest too,    *)
(* and Cal J                                                                 *)
(* is closed under passing to sub-cells.                                     *)
let DYHO_SUBSET_ENDPOINTS = prove
 (`!a b p q:int. a <= b /\ dyho a p SUBSET dyho b q
     ==> real_of_int q * &2 zpow b <= real_of_int p * &2 zpow a /\
         (real_of_int p + &1) * &2 zpow a <= (real_of_int q + &1) * &2 zpow b`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow a /\ &0 < &2 zpow b` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_ASSUM(LABEL_TAC "mem" o REWRITE_RULE[dyho; SUBSET; IN_ELIM_THM] o
    check (fun th -> is_binary "SUBSET" (concl th))) THEN
  CONJ_TAC THENL
   [USE_THEN "mem" (MP_TAC o SPEC `real_of_int p * &2 zpow a`) THEN
    ANTS_TAC THENL [CONJ_TAC THENL
      [REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]; REAL_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `~(y < x) ==> x <= y`) THEN DISCH_TAC THEN
  USE_THEN "mem" (MP_TAC o SPEC
    `max (real_of_int p * &2 zpow a) ((real_of_int q + &1) * &2 zpow b)`) THEN
  MATCH_MP_TAC(TAUT `a /\ ~b ==> (a ==> b) ==> F`) THEN CONJ_TAC THENL
   [CONJ_TAC THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[DE_MORGAN_THM; REAL_NOT_LE; REAL_NOT_LT] THEN DISJ2_TAC THEN
    ASM_REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* One-sidedness (286Gg geometry): a proper dyadic sub-cell lies entirely on *)
(* one side of the coarser cell's midpoint.  Needed so 286Gc (the CWTILE     *)
(* midpoint-integral lemmas) applies to int_{I_tau} w_sigma (I_tau one side  *)
(* of                                                                        *)
(* x_sigma).                                                                 *)
(* ------------------------------------------------------------------------- *)

(* roi m < roi n + 1 ==> m <= n (integer discreteness through the reals).    *)
let INT_LE_OF_REAL_LT1 = prove
 (`!m n:int. real_of_int m < real_of_int n + &1 ==> m <= n`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `real_of_int n + &1 = real_of_int(n + &1)` SUBST1_TAC THENL
   [REWRITE_TAC[int_add_th; int_of_num_th]; ALL_TAC] THEN
  REWRITE_TAC[GSYM int_lt] THEN INT_ARITH_TAC);;

(* CRUX: for a<b, the coarser midpoint (q+1/2)2^b cannot lie strictly INSIDE *)
(* the finer cell [p 2^a,(p+1)2^a] -- because 2^(b-a) is even (=2M'), so     *)
(* (q+1/2)2^b = (2qM'+M')2^a with 2qM'+M' an INTEGER, which cannot be        *)
(* strictly between the consecutive integers p and p+1 (after cancelling     *)
(* 2^a>0).                                                                   *)
let DYHO_MID_INTERIOR_EVEN_FALSE = prove
 (`!a b p q M':int. &2 zpow (b - a) = real_of_int (&2 * M') /\
      real_of_int p * &2 zpow a < (real_of_int q + &1 / &2) * &2 zpow b /\
      (real_of_int q + &1 / &2) * &2 zpow b < (real_of_int p + &1) * &2 zpow a
   ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow a` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(real_of_int q + &1 / &2) * &2 zpow b =
                real_of_int(&2 * q * M' + M') * &2 zpow a` ASSUME_TAC THENL
   [SUBGOAL_THEN
     `&2 zpow b = real_of_int(&2 * M') * &2 zpow a` SUBST1_TAC THENL
     [FIRST_X_ASSUM(fun th -> MP_TAC th THEN DISCH_THEN(SUBST1_TAC o SYM)) THEN
      SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
      AP_TERM_TAC THEN INT_ARITH_TAC;
      REWRITE_TAC[int_add_th; int_mul_th; int_of_num_th] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `real_of_int p * &2 zpow a < real_of_int(&2 * q * M' + M') * &2 zpow a /\
                real_of_int(&2 * q * M' + M') * &2 zpow a < (real_of_int p +
                  &1) * &2 zpow a`
   MP_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LT_RMUL_EQ] THEN
  REWRITE_TAC[int_add_th; int_mul_th; int_of_num_th] THEN
  REWRITE_TAC[GSYM int_of_num_th; GSYM int_mul_th; GSYM int_add_th] THEN
  REWRITE_TAC[GSYM int_lt] THEN INT_ARITH_TAC);;

(* Same-scale case: the coarser midpoint interior forces equal indices.      *)
let DYHO_ONESIDE_SAMESCALE_EQ = prove
 (`!b p q:int.
     real_of_int p * &2 zpow b < (real_of_int q + &1 / &2) * &2 zpow b /\
     (real_of_int q + &1 / &2) * &2 zpow b < (real_of_int p + &1) * &2 zpow b
     ==> p = q`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow b` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LT_RMUL_EQ] THEN STRIP_TAC THEN
  SUBGOAL_THEN `p:int <= q` ASSUME_TAC THENL
   [MATCH_MP_TAC INT_LE_OF_REAL_LT1 THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `q:int <= p` ASSUME_TAC THENL
   [MATCH_MP_TAC INT_LE_OF_REAL_LT1 THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_INT_ARITH_TAC);;

(* One-sidedness proper: dyho a p SUBSET dyho b q (a<=b, proper) ==> the     *)
(* finer cell dyho a p lies wholly at-or-left, or wholly at-or-right, of     *)
(* dyho_mid b q. 3-case split on the coarse midpoint vs the finer cell's     *)
(* endpoints; the "strict interior" case is impossible                       *)
(* (DYHO_MID_INTERIOR_EVEN_FALSE for a<b, or forces p=q hence equal cells    *)
(* for a=b).                                                                 *)
let DYHO_ONESIDE = prove
 (`!a b p q:int. a <= b /\ dyho a p SUBSET dyho b q /\ ~(dyho a p = dyho b q)
   ==> (!x. x IN dyho a p ==> x <= dyho_mid b q) \/
       (!x. x IN dyho a p ==> dyho_mid b q <= x)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`a:int`; `b:int`; `p:int`;
    `q:int`] DYHO_SUBSET_ENDPOINTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  REWRITE_TAC[dyho_mid] THEN
  DISJ_CASES_TAC(REAL_ARITH
   `(real_of_int p + &1) * &2 zpow a <= (real_of_int q + &1 / &2) * &2 zpow b
     \/
    (real_of_int q + &1 / &2) * &2 zpow b <= real_of_int p * &2 zpow a \/
    (real_of_int p * &2 zpow a < (real_of_int q + &1 / &2) * &2 zpow b /\
     (real_of_int q + &1 / &2) * &2 zpow b < (real_of_int p + &1) * &2 zpow
       a)`) THENL
   [DISJ1_TAC THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN
    STRIP_TAC THEN ASM_REAL_ARITH_TAC;
    POP_ASSUM(DISJ_CASES_THEN2 ASSUME_TAC ASSUME_TAC) THENL
     [DISJ2_TAC THEN X_GEN_TAC `x:real` THEN
       REWRITE_TAC[dyho; IN_ELIM_THM] THEN
      STRIP_TAC THEN ASM_REAL_ARITH_TAC;
      ASM_CASES_TAC `a:int = b` THENL
       [UNDISCH_TAC `~(dyho a p = dyho b q)` THEN REWRITE_TAC[] THEN
        FIRST_X_ASSUM SUBST_ALL_TAC THEN
        SUBGOAL_THEN `p:int = q` (fun th -> REWRITE_TAC[th]) THEN
        MATCH_MP_TAC DYHO_ONESIDE_SAMESCALE_EQ THEN EXISTS_TAC `b:int` THEN
        ASM_REWRITE_TAC[];
        SUBGOAL_THEN `&1 <= b - a:int` ASSUME_TAC THENL
         [ASM_INT_ARITH_TAC; ALL_TAC] THEN
        MP_TAC(ISPEC `b - a:int` ZPOW_POS_EVEN_INT2) THEN
          ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `M':int` STRIP_ASSUME_TAC) THEN
        MP_TAC(ISPECL [`a:int`; `b:int`; `p:int`; `q:int`; `M':int`]
          DYHO_MID_INTERIOR_EVEN_FALSE) THEN
        ASM_REWRITE_TAC[]]]]);;

(* Disjoint case of one-sidedness: disjoint dyadic cells are                 *)
(* order-separated. From DISJOINT + the finer cell not entirely left of dyho *)
(* b q, it is entirely right (common-point contradiction at the max          *)
(* endpoint).                                                                *)
let DYHO_DISJOINT_RIGHTSEP = prove
 (`!a b p q:int. DISJOINT (dyho a p) (dyho b q) /\ &0 < &2 zpow a /\ &0 < &2
   zpow b /\
     real_of_int q * &2 zpow b < (real_of_int p + &1) * &2 zpow a
     ==> (real_of_int q + &1) * &2 zpow b <= real_of_int p * &2 zpow a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[GSYM REAL_NOT_LT] THEN
    DISCH_TAC THEN
  UNDISCH_TAC `DISJOINT (dyho a p) (dyho b q)` THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; dyho;
    IN_ELIM_THM] THEN
  DISCH_THEN(MP_TAC o SPEC `max (real_of_int p * &2 zpow a) (real_of_int q * &2
    zpow b)`) THEN
  ASM_REAL_ARITH_TAC);;

let DYHO_DISJOINT_ONESIDE = prove
 (`!a b p q:int. DISJOINT (dyho a p) (dyho b q) /\ ~(dyho a p = {})
   ==> (!x. x IN dyho a p ==> x <= dyho_mid b q) \/
       (!x. x IN dyho a p ==> dyho_mid b q <= x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow a /\ &0 < &2 zpow b` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  DISJ_CASES_TAC(REAL_ARITH
   `(real_of_int p + &1) * &2 zpow a <= real_of_int q * &2 zpow b \/
    real_of_int q * &2 zpow b < (real_of_int p + &1) * &2 zpow a`) THENL
   [DISJ1_TAC THEN X_GEN_TAC `x:real` THEN
     REWRITE_TAC[dyho; dyho_mid; IN_ELIM_THM] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN
      `real_of_int q * &2 zpow b <= (real_of_int q + &1 / &2) * &2 zpow b`
      MP_TAC THENL
     [MATCH_MP_TAC REAL_LE_RMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
       REAL_ARITH_TAC;
      ASM_REAL_ARITH_TAC];
    DISJ2_TAC THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN
      STRIP_TAC THEN
    MP_TAC(ISPECL [`a:int`; `b:int`; `p:int`;
      `q:int`] DYHO_DISJOINT_RIGHTSEP) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[dyho_mid] THEN
    SUBGOAL_THEN
      `(real_of_int q + &1 / &2) * &2 zpow b <= (real_of_int q + &1) * &2 zpow
      b` MP_TAC THENL
     [MATCH_MP_TAC REAL_LE_RMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
       REAL_ARITH_TAC;
      ASM_REAL_ARITH_TAC]]);;

(* Same-scale subset forces equal indices (disjointness would empty the      *)
(* subset).                                                                  *)
let DYHO_SAMESCALE_SUBSET_EQ = prove
 (`!b p q:int. dyho b q SUBSET dyho b p ==> q = p`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `q:int = p` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`b:int`; `q:int`; `p:int`] DYHO_DISJOINT_SAMESCALE) THEN
  ASM_REWRITE_TAC[DISJOINT] THEN
  SUBGOAL_THEN `dyho b q INTER dyho b p = dyho b q` SUBST1_TAC THENL
   [ASM SET_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`b:int`; `q:int`] DYHO_NONEMPTY) THEN SET_TAC[]);;

(* One-sidedness, all positions (286Gg): for a<=b and distinct cells, the    *)
(* finer dyho a p lies wholly at-or-left, or wholly at-or-right, of dyho_mid *)
(* b q. Trichotomy: nested -> DYHO_ONESIDE; reverse-nested -> equal (measure *)
(* forces a=b, DYHO_SAMESCALE_SUBSET_EQ forces q=p) contra ~=; disjoint ->   *)
(* DYHO_DISJOINT_ ONESIDE.                                                   *)
let DYHO_ONESIDE_FULL = prove
 (`!a b p q:int. a <= b /\ ~(dyho a p = dyho b q)
   ==> (!x. x IN dyho a p ==> x <= dyho_mid b q) \/
       (!x. x IN dyho a p ==> dyho_mid b q <= x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(dyho a p = {})` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `real_of_int p * &2 zpow a` THEN
      REWRITE_TAC[DYHO_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(ISPECL [`a:int`; `p:int`; `b:int`; `q:int`] DYHO_TRICHOTOMY) THEN
  STRIP_TAC THENL
   [MATCH_MP_TAC DYHO_ONESIDE THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `a:int = b` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM INT_LE_ANTISYM] THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC ZPOW2_LE_REV THEN
      MP_TAC(ISPECL [`dyho b q`; `dyho a p`] REAL_MEASURE_SUBSET) THEN
      ASM_REWRITE_TAC[DYHO_MEASURABLE; DYHO_MEASURE]; ALL_TAC] THEN
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MP_TAC(ISPECL [`b:int`; `p:int`; `q:int`] DYHO_SAMESCALE_SUBSET_EQ) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    UNDISCH_TAC `~(dyho b p = dyho b q)` THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC DYHO_DISJOINT_ONESIDE THEN ASM_REWRITE_TAC[]]);;

(* Endpoint form of one-sidedness (feeds CWTILE_TILE_I_MIDPOINT's            *)
(* hypothesis).                                                              *)
(* Right endpoint: all-of-cell <= c forces (p+1)2^a <= c (limit witness      *)
(* approaching                                                               *)
(* the sup, REAL_LE_EPSILON). Left endpoint: all-of-cell >= c forces c <= p  *)
(* 2^a                                                                       *)
(* (left endpoint p 2^a is IN the cell, DYHO_NONEMPTY).                      *)
let DYHO_RIGHT_ENDPOINT_LE = prove
 (`!a p c:real. &0 < &2 zpow a /\ (!x. x IN dyho a p ==> x <= c)
   ==> (real_of_int p + &1) * &2 zpow a <= c`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_EPSILON THEN
  X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC
    `max (real_of_int p * &2 zpow a) ((real_of_int p + &1) * &2 zpow a - e /
      &2)`) THEN
  REWRITE_TAC[dyho; IN_ELIM_THM] THEN ANTS_TAC THENL
   [REWRITE_TAC[REAL_LE_MAX; REAL_MAX_LT] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[REAL_MAX_LE] THEN ASM_REAL_ARITH_TAC]);;

let DYHO_LEFT_ENDPOINT_GE = prove
 (`!a p c:real. (!x. x IN dyho a p ==> c <= x) ==> c <= real_of_int p * &2 zpow
   a`,
  REPEAT STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
  REWRITE_TAC[DYHO_NONEMPTY]);;

(* dyho a p (finer, a<=b) is wholly at-or-left/at-or-right of dyho_mid b q,  *)
(* in the ENDPOINT form CWTILE_TILE_I_MIDPOINT wants (dyho_mid b q <= left   *)
(* \/ right <= mid).                                                         *)
let TILE_ONESIDE_ENDPOINTS = prove
 (`!a b p q:int. a <= b /\ ~(dyho a p = dyho b q)
   ==> dyho_mid b q <= real_of_int p * &2 zpow a \/
       (real_of_int p + &1) * &2 zpow a <= dyho_mid b q`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`a:int`; `b:int`; `p:int`; `q:int`] DYHO_ONESIDE_FULL) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&0 < &2 zpow a` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  STRIP_TAC THENL
   [DISJ2_TAC THEN MATCH_MP_TAC DYHO_RIGHT_ENDPOINT_LE THEN ASM_REWRITE_TAC[];
    DISJ1_TAC THEN MATCH_MP_TAC DYHO_LEFT_ENDPOINT_GE THEN
      ASM_REWRITE_TAC[]]);;

let DYHO_STAR_MONO = prove
 (`!a b p q:int. dyho a p SUBSET dyho b q ==> dyho_star a p SUBSET dyho_star b
   q`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN
  MP_TAC(SPECL [`a:int`; `b:int`; `p:int`; `q:int`] DYHO_SUBSET_ENDPOINTS) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow a /\ &0 < &2 zpow b /\ &2 zpow a <= &2 zpow b`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
      MATCH_MP_TAC ZPOW2_MONOE THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[dyho_star; SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `x:real` THEN
  STRIP_TAC THEN CONJ_TAC THEN ASM_REAL_ARITH_TAC);;

let JSCRIPT_MONO = prove
 (`!P a b p q:int. dyho a p SUBSET dyho b q /\ in_jscript P b q ==> in_jscript
   P a p`,
  REPEAT GEN_TAC THEN REWRITE_TAC[in_jscript] THEN STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN
  X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `s:int#int#int`) THEN
  SUBGOAL_THEN `&2 zpow (--(tile_k s)) <= &2 zpow b` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&2 zpow a` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ZPOW2_MONOE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT `(c ==> d) ==> ~d ==> ~c`) THEN DISCH_TAC THEN
  MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `dyho_star a p` THEN
  ASM_SIMP_TAC[DYHO_STAR_MONO]);;

(* The parent of a cell nested in a coarser cell (at scale > a) is still     *)
(* nested in                                                                 *)
(* it (DYHO_NEST via the shared left endpoint). Used to climb toward         *)
(* maximality.                                                               *)
let DYHO_PARENT_NEST = prove
 (`!a b p q:int. a + &1 <= b /\ dyho a p SUBSET dyho b q
     ==> dyho (a + &1) (p div &2) SUBSET dyho b q`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`a + &1:int`; `b:int`; `p div &2:int`; `q:int`;
                 `real_of_int p * &2 zpow a`] DYHO_NEST) THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`a:int`; `p:int`] DYHO_PARENT) THEN
    REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[DYHO_NONEMPTY];
    FIRST_X_ASSUM(MP_TAC o check (fun t -> is_binary "SUBSET" (concl t))) THEN
    REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[DYHO_NONEMPTY]]);;

(* A cover cell contained in a Cal J cell must EQUAL it: a proper            *)
(* containment would make the cover cell's parent a Cal J cell too           *)
(* (JSCRIPT_MONO on parent SUBSET the bigger cell), contradicting maximality *)
(* (in_kcover: parent not in J).                                             *)
let KCOVER_SUBSET_EQ = prove
 (`!P a b p q:int. in_kcover P a p /\ in_jscript P b q /\ dyho a p SUBSET dyho
   b q
     ==> dyho a p = dyho b q`,
  REPEAT GEN_TAC THEN REWRITE_TAC[in_kcover] THEN STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN
  FIRST_ASSUM(DISJ_CASES_TAC o MATCH_MP
    (INT_ARITH `!a b:int. a <= b ==> a = b \/ a + &1 <= b`)) THENL
   [UNDISCH_TAC `a:int = b` THEN DISCH_THEN SUBST_ALL_TAC THEN
    FIRST_X_ASSUM(MP_TAC o MATCH_MP DYHO_SAMESCALE_EQ o
      check (fun t -> is_binary "SUBSET" (concl t))) THEN
    DISCH_THEN SUBST1_TAC THEN REFL_TAC;
    SUBGOAL_THEN `in_jscript P (a + &1) (p div &2)` ASSUME_TAC THENL
     [MATCH_MP_TAC JSCRIPT_MONO THEN
      MAP_EVERY EXISTS_TAC [`b:int`; `q:int`] THEN CONJ_TAC THENL
       [MATCH_MP_TAC DYHO_PARENT_NEST THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* Distinct cover cells are DISJOINT (laminar + both maximal: trichotomy     *)
(* gives nested-or-disjoint; either nesting forces equality by               *)
(* KCOVER_SUBSET_EQ).                                                        *)
let KCOVER_DISJOINT = prove
 (`!P a b p q:int. in_kcover P a p /\ in_kcover P b q /\ ~(dyho a p = dyho b q)
     ==> DISJOINT (dyho a p) (dyho b q)`,
  REPEAT STRIP_TAC THEN
  STRIP_ASSUME_TAC(SPECL [`a:int`; `p:int`; `b:int`;
    `q:int`] DYHO_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[in_kcover]) THEN
  ASM_MESON_TAC[KCOVER_SUBSET_EQ; in_kcover]);;

(* The two ENDS of the maximal-cover parent chain (feeding the covering      *)
(* argument):                                                                *)
(* small cells are VACUOUSLY in Cal J; cells whose triple engulfs a          *)
(* qualifying I_sigma                                                        *)
(* leave Cal J.  Between them a maximal (cover) cell sits over every point.  *)
let JSCRIPT_SMALL = prove
 (`!P a p:int. (!s. s IN P ==> &2 zpow a < &2 zpow (--(tile_k s)))
     ==> in_jscript P a p`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[in_jscript] THEN
  X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `s:int#int#int`) THEN ASM_REWRITE_TAC[] THEN
  ASM_REAL_ARITH_TAC);;

let JSCRIPT_FAIL = prove
 (`!P a p:int s. s IN P /\ &2 zpow (--(tile_k s)) <= &2 zpow a /\
                 tile_I s SUBSET dyho_star a p
     ==> ~(in_jscript P a p)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[in_jscript]) THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN
  EXISTS_TAC `s:int#int#int` THEN ASM_REWRITE_TAC[]);;

(* --- Geometric engine for the COVERING property (UNIONS Cal K = R) ---     *)

(* The triple of a scale-b cell containing x contains the whole              *)
(* 2^b-neighbourhood of x (dyho b q = [q2^b,(q+1)2^b) with x inside;         *)
(* dyho_star b q = [(q-1)2^b, (q+2)2^b) reaches a full cell-width past each  *)
(* edge).                                                                    *)
let DYHO_STAR_CONTAINS_NBHD = prove
 (`!b q x w:real. x IN dyho b q /\ abs(w - x) < &2 zpow b ==> w IN dyho_star b
   q`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; dyho_star; IN_ELIM_THM] THEN
  STRIP_TAC THEN CONJ_TAC THEN ASM_REAL_ARITH_TAC);;

(* Every real lies in some dyadic cell at every scale (q = int floor of      *)
(* x/2^b).                                                                   *)
let DYHO_COVERS_POINT = prove
 (`!b x:real. ?q. x IN dyho b q`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow b` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  EXISTS_TAC `int_of_real(floor(x / &2 zpow b))` THEN
  MP_TAC(SPEC `x / &2 zpow b` FLOOR) THEN
  ABBREV_TAC `t = floor(x / &2 zpow b)` THEN STRIP_TAC THEN
  REWRITE_TAC[dyho; IN_ELIM_THM] THEN
  SUBGOAL_THEN
    `real_of_int(int_of_real t) = t` (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[int_rep]; ALL_TAC] THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[GSYM REAL_LE_RDIV_EQ];
    ASM_SIMP_TAC[GSYM REAL_LT_LDIV_EQ]]);;

(* x lies in its SELECT-ed scale-b cell (the cover-climb refers to x's cell  *)
(* by the choice operator, whose membership is DYHO_COVERS_POINT via         *)
(* SELECT).                                                                  *)
let XCELL_IN = prove
 (`!b x:real. x IN dyho b (@q. x IN dyho b q)`,
  REPEAT GEN_TAC THEN CONV_TAC SELECT_CONV THEN
    REWRITE_TAC[DYHO_COVERS_POINT]);;

(* Abstract num boundary: if a predicate Q holds at 0 but fails somewhere,   *)
(* there is a                                                                *)
(* boundary point n with Q n but ~Q(SUC n). Isolates the well-ordering used  *)
(* to climb                                                                  *)
(* the cells-containing-x chain to the maximal Cal J cell (= cover cell).    *)
let NUM_BOUNDARY = prove
 (`!Q:num->bool. Q 0 /\ (?N. ~(Q N)) ==> ?n. Q n /\ ~(Q(SUC n))`,
  GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?n:num. ~(Q n) /\ (!m. m < n ==> Q m)` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPEC `\n:num. ~(Q n)` num_WOP) THEN BETA_TAC THEN
    DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
    ANTS_TAC THENL [EXISTS_TAC `N:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC MONO_EXISTS THEN GEN_TAC THEN REWRITE_TAC[] THEN
      STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN GEN_TAC THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `1 <= n` ASSUME_TAC THENL
   [ASM_MESON_TAC[ARITH_RULE `~(1 <= n) ==> n = 0`]; ALL_TAC] THEN
  EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `n - 1`) THEN
    ASM_SIMP_TAC[ARITH_RULE `1 <= n ==> n - 1 < n`];
    ASM_SIMP_TAC[ARITH_RULE `1 <= n ==> SUC(n - 1) = n`]]);;

(* Every point of a cell dyho c m is within |m 2^c - x| + 2^c of any x.      *)
let CELL_DIST_BOUND = prove
 (`!c m x w:real. w IN dyho c m
     ==> abs(w - x) <= abs(real_of_int m * &2 zpow c - x) + &2 zpow c`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN
  SUBGOAL_THEN `&0 < &2 zpow c` MP_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* 2^b is unbounded above: for any M and start a, some b >= a has M < 2^b.   *)
let ZPOW2_ARCH = prove
 (`!M a:int. ?b:int. a <= b /\ M < &2 zpow b`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`&2:real`; `M:real`] REAL_ARCH_POW) THEN
  ANTS_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `n:num`) THEN
  EXISTS_TAC `abs a + &n:int` THEN CONJ_TAC THENL
   [INT_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `&2 pow n` THEN
    ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&2 pow n = &2 zpow (&n:int)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_NUM]; ALL_TAC] THEN
  MATCH_MP_TAC ZPOW2_MONOE THEN INT_ARITH_TAC);;

(* 286J part(b): the dilated intervals I^(K)_tau exhaust R -- every x lies   *)
(* in                                                                        *)
(* tile_Idil tau K for K large.  ZPOW2_ARCH gives an int exponent b with     *)
(* 2^b > |x - x_tau| and b >= -k_tau-1, so K = num_of_int(b+k_tau+1) is a    *)
(* valid                                                                     *)
(* num with half-width 2^{&K-k_tau-1} = 2^b > |x-x_tau|.  Underlies the      *)
(* monotone-convergence decomposition int_S w = lim_K int_{S cap I^(K)} w.   *)
let TILE_IDIL_EXHAUSTS = prove
 (`!tau x. ?K. x IN tile_Idil tau K`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_Idil; IN_ELIM_THM] THEN
  MP_TAC(ISPECL [`abs(x - tile_xmid tau)`;
    `--(tile_k tau) - &1`] ZPOW2_ARCH) THEN
  DISCH_THEN(X_CHOOSE_THEN `b:int` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `num_of_int(b + tile_k tau + &1)` THEN
  SUBGOAL_THEN `&(num_of_int(b + tile_k tau + &1)) = b + tile_k tau + &1:int`
    ASSUME_TAC THENL
   [MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `(b + tile_k tau + &1) - tile_k tau - &1 = b:int` SUBST1_TAC THENL
   [INT_ARITH_TAC; ASM_REWRITE_TAC[]]);;

(* THE covering-termination geometric crux: for any tile s and point x,      *)
(* arbitrarily                                                               *)
(* large scales b have x in a cell dyho b q whose TRIPLE engulfs the whole   *)
(* spatial                                                                   *)
(* interval tile_I s. (tile_I s is bounded; ZPOW2_ARCH picks b with 2^b      *)
(* beyond its                                                                *)
(* distance to x; DYHO_STAR_CONTAINS_NBHD + CELL_DIST_BOUND then give        *)
(* containment.)                                                             *)
(* This is what makes the parent-climb leave Cal J (JSCRIPT_FAIL) at large   *)
(* scales.                                                                   *)
let TILE_I_ENGULF = prove
 (`!s x a:int. ?b q. a <= b /\ x IN dyho b q /\ tile_I s SUBSET dyho_star b q`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_I; tile_k] THEN
  MAP_EVERY X_GEN_TAC [`k:int`; `nI:int`; `x:real`; `a:int`] THEN
  MP_TAC(SPECL [`abs(real_of_int nI * &2 zpow (--k) - x) + &2 zpow (--k)`;
    `a:int`]
    ZPOW2_ARCH) THEN
  DISCH_THEN(X_CHOOSE_THEN `b:int` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`b:int`; `x:real`] DYHO_COVERS_POINT) THEN
  DISCH_THEN(X_CHOOSE_TAC `q:int`) THEN
  MAP_EVERY EXISTS_TAC [`b:int`; `q:int`] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `w:real` THEN DISCH_TAC THEN
  MATCH_MP_TAC DYHO_STAR_CONTAINS_NBHD THEN EXISTS_TAC `x:real` THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LET_TRANS THEN
  EXISTS_TAC `abs(real_of_int nI * &2 zpow (--k) - x) + &2 zpow (--k)` THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`--k:int`; `nI:int`; `x:real`; `w:real`] CELL_DIST_BOUND) THEN
  ASM_REWRITE_TAC[]);;

(* x lies in a UNIQUE scale-b cell; its scale-(b+1) cell is the parent       *)
(* (index div 2).                                                            *)
let DYHO_POINT_UNIQUE = prove
 (`!b m n x:real. x IN dyho b m /\ x IN dyho b n ==> m = n`,
  REPEAT STRIP_TAC THEN
  GEN_REWRITE_TAC I [TAUT `p <=> ~ ~p`] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`b:int`; `m:int`; `n:int`] DYHO_DISJOINT_SAMESCALE) THEN
  ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `x:real`) THEN ASM_REWRITE_TAC[]);;

let DYHO_POINT_PARENT = prove
 (`!b m x:real. x IN dyho b m ==> x IN dyho (b + &1) (m div &2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`b:int`; `m:int`] DYHO_PARENT) THEN
  REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* An int-valued function on a finite set has an int upper bound (set        *)
(* induction with                                                            *)
(* max). Gives a scale below all -k_sigma so JSCRIPT_SMALL applies           *)
(* (SMALL_SCALE_                                                             *)
(* EXISTS): for finite P, some scale a has 2^a < 2^{-k_sigma} for every      *)
(* sigma.                                                                    *)
let INT_UPPER_BOUND_FINITE = prove
 (`!(f:A->int) s. FINITE s ==> ?K. !x. x IN s ==> f x <= K`,
  GEN_TAC THEN MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
   [EXISTS_TAC `&0:int` THEN REWRITE_TAC[NOT_IN_EMPTY];
    MAP_EVERY X_GEN_TAC [`e:A`; `t:A->bool`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_TAC `K:int`) ASSUME_TAC) THEN
    EXISTS_TAC `max (f(e:A):int) K` THEN
    REWRITE_TAC[IN_INSERT] THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[INT_MAX_MAX; INT_LE_TRANS]]);;

let SMALL_SCALE_EXISTS = prove
 (`!P:(int#int#int)->bool. FINITE P
     ==> ?a. !s. s IN P ==> &2 zpow a < &2 zpow (--(tile_k s))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`tile_k:int#int#int->int`; `P:(int#int#int)->bool`]
    INT_UPPER_BOUND_FINITE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `K:int`) THEN
  EXISTS_TAC `--K - &1:int` THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  MATCH_MP_TAC ZPOW2_MONOE_LT THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `s:int#int#int`) THEN ASM_REWRITE_TAC[] THEN
  INT_ARITH_TAC);;

(* Every point x lies in some maximal Cal J cell (in_kcover).  Climb from a  *)
(* very fine scale a0 (where in_jscript holds vacuously, JSCRIPT_SMALL) up   *)
(* to the scale bT where the tile tile_I s0 is engulfed (TILE_I_ENGULF, so   *)
(* in_jscript fails, JSCRIPT_FAIL); NUM_BOUNDARY picks the boundary scale    *)
(* a0+n where in_jscript still holds but fails one scale up.  x's cell       *)
(* there is a maximal member.                                               *)
let KCOVER_EXISTS = prove
 (`!P:(int#int#int)->bool. FINITE P /\ ~(P = {})
     ==> !x:real. ?a q. in_kcover P a q /\ x IN dyho a q`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `P:(int#int#int)->bool` SMALL_SCALE_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a0:int` ASSUME_TAC) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `s0:int#int#int` o REWRITE_RULE[GSYM
    MEMBER_NOT_EMPTY]) THEN
  MP_TAC(SPECL [`s0:int#int#int`; `x:real`;
    `--(tile_k s0)`] TILE_I_ENGULF) THEN
  DISCH_THEN(X_CHOOSE_THEN `bT:int` (X_CHOOSE_THEN
    `qT:int` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `a0:int <= bT` ASSUME_TAC THENL
   [MATCH_MP_TAC INT_LE_TRANS THEN EXISTS_TAC `--(tile_k s0):int` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ZPOW2_LT_IMP_LE THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `s0:int#int#int`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&(num_of_int(bT - a0)):int = bT - a0` ASSUME_TAC THENL
   [MATCH_MP_TAC INT_OF_NUM_OF_INT THEN REWRITE_TAC[INT_SUB_LE] THEN
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `a0 + &(num_of_int(bT - a0)):int = bT` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN
     MATCH_ACCEPT_TAC(INT_ARITH `!a b:int. a + (b - a) = b`);
    ALL_TAC] THEN
  SUBGOAL_THEN `(@q. x IN dyho bT q) = qT` ASSUME_TAC THENL
   [MP_TAC(SPECL [`bT:int`; `(@q. x IN dyho bT q)`; `qT:int`; `x:real`]
       DYHO_POINT_UNIQUE) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[XCELL_IN];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `in_jscript P (a0 + &0) (@q. x IN dyho (a0 + &0) q)` ASSUME_TAC THENL
   [REWRITE_TAC[INT_ADD_RID] THEN MATCH_MP_TAC JSCRIPT_SMALL THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(in_jscript P (a0 + &(num_of_int(bT - a0)))
        (@q. x IN dyho (a0 + &(num_of_int(bT - a0))) q))` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`P:(int#int#int)->bool`; `bT:int`; `qT:int`;
      `s0:int#int#int`]
       JSCRIPT_FAIL) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC ZPOW2_MONOE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?n. in_jscript P (a0 + &n) (@q. x IN dyho (a0 + &n) q) /\
        ~(in_jscript P (a0 + &(SUC n)) (@q. x IN dyho (a0 + &(SUC n)) q))`
   STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPEC
      `\n. in_jscript P (a0 + &n) (@q. x IN dyho (a0 + &n) q)` NUM_BOUNDARY)
        THEN
    BETA_TAC THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `num_of_int(bT - a0)` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(@q. x IN dyho (a0 + &n) q) div &2 = (@q. x IN dyho (a0 + &(SUC n)) q)`
   ASSUME_TAC THENL
   [MP_TAC(SPECL
      [`a0 + &(SUC n):int`;
       `(@q. x IN dyho (a0 + &n) q) div &2`;
       `(@q. x IN dyho (a0 + &(SUC n)) q)`; `x:real`] DYHO_POINT_UNIQUE) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    REWRITE_TAC[XCELL_IN] THEN
    SUBGOAL_THEN `a0 + &(SUC n):int = (a0 + &n) + &1` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM INT_OF_NUM_SUC] THEN INT_ARITH_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC DYHO_POINT_PARENT THEN REWRITE_TAC[XCELL_IN];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`a0 + &n:int`; `(@q. x IN dyho (a0 + &n) q)`] THEN
  REWRITE_TAC[XCELL_IN; in_kcover] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(a0 + &n) + &1:int = a0 + &(SUC n)` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM INT_OF_NUM_SUC] THEN INT_ARITH_TAC;
    ASM_REWRITE_TAC[]]);;

(* l_K bookkeeping: a cover cell dyho a p has measure 2 zpow a (= 2^{-l_K} with
   l_K = --a).  Trivial from DYHO_MEASURE;
     the entry point for the a-ii count. *)
let KCOVER_MEASURE = prove
 (`!P:(int#int#int)->bool a p. in_kcover P a p ==> real_measure(dyho a p) = &2
   zpow a`,
  REWRITE_TAC[DYHO_MEASURE]);;

(* Fremlin 286L(a-ii) MEASURE engine: any finite family of cover cells       *)
(* (indexed by their (a,p) pairs) all contained in a bounded measurable B    *)
(* has total measure <= mu B, since distinct cover cells are DISJOINT        *)
(* (KCOVER_DISJOINT). Applied with B = Ihat_tau (length 7 mu I_tau) to bound *)
(* sum of coarse cover-cell measures.                                        *)
let KCOVER_MEASURE_SUM_LE = prove
 (`!P:(int#int#int)->bool S B.
      FINITE S /\ real_measurable B /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap)) /\
      (!ap. ap IN S ==> dyho (FST ap) (SND ap) SUBSET B)
      ==> sum (IMAGE (\ap. dyho (FST ap) (SND ap)) S) (\c. real_measure c)
          <= real_measure B`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC DISJOINT_CELLS_MEASURE_SUM_LE THEN
  ASM_SIMP_TAC[FINITE_IMAGE] THEN REPEAT CONJ_TAC THEN
  REWRITE_TAC[FORALL_IN_IMAGE] THENL
   [X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN REWRITE_TAC[DYHO_MEASURABLE];
    X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN ASM_SIMP_TAC[];
    REWRITE_TAC[IMP_CONJ; RIGHT_FORALL_IMP_THM; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[FORALL_IN_IMAGE] THEN
    X_GEN_TAC `aq:int#int` THEN DISCH_TAC THEN DISCH_TAC THEN
    MP_TAC(SPECL [`P:(int#int#int)->bool`; `FST(ap:int#int)`;
      `FST(aq:int#int)`;
                  `SND(ap:int#int)`; `SND(aq:int#int)`] KCOVER_DISJOINT) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_SIMP_TAC[]]);;

(* --- 286L(a-ii) geometric containment: coarse cover cells sit in Ihat_tau  *)
(* ---                                                                       *)

(* Diameter of a tripled dyadic cell: any two of its points are < 3*2^k      *)
(* apart.                                                                    *)
let DYHO_STAR_DIAM = prove
 (`!k n x y. x IN dyho_star k n /\ y IN dyho_star k n
             ==> abs(x - y) < &3 * &2 zpow k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho_star; IN_ELIM_THM] THEN
  REWRITE_TAC[REAL_SUB_RDISTRIB; REAL_ADD_RDISTRIB; REAL_MUL_LID] THEN
  REAL_ARITH_TAC);;

(* A point of a dyadic cell is < 2^k from the cell midpoint.                 *)
let DYHO_MID_DIST = prove
 (`!k n z. z IN dyho k n ==> abs(z - dyho_mid k n) < &2 zpow k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; dyho_mid; IN_ELIM_THM] THEN
  REWRITE_TAC[REAL_ADD_RDISTRIB; REAL_MUL_LID] THEN
  REAL_ARITH_TAC);;

(* If the parent-triple of cover cell dyho a p meets I_tau = dyho (--kt) nt  *)
(* (and                                                                      *)
(* mu K = 2^a <= mu I_tau = 2^{--kt}), every point of the cover cell is      *)
(* within                                                                    *)
(* 7 mu I_tau of x_tau. Triangle: |y - x_tau| <= |y - z| + |z - x_tau| where *)
(* y, z share the parent-triple (length 6*2^a <= 6*2^{--kt}) and z in I_tau. *)
let KCOVER_STAR_MEETS_ITAU_CONTAIN = prove
 (`!a p kt nt.
      &2 zpow a <= &2 zpow (--kt) /\
      ~(dyho_star (a + &1) (p div &2) INTER dyho (--kt) nt = {})
      ==> !y. y IN dyho a p
              ==> abs(y - dyho_mid (--kt) nt) <= &7 * &2 zpow (--kt)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `z:real` STRIP_ASSUME_TAC)) THEN
  X_GEN_TAC `y:real` THEN DISCH_TAC THEN
  SUBGOAL_THEN `y IN dyho_star (a + &1) (p div &2)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:int`; `p:int`] DYHO_SUBSET_STAR) THEN
    MP_TAC(ISPECL [`a:int`; `p:int`] DYHO_STAR_PARENT) THEN ASM SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`a + &1:int`; `p div &2`; `y:real`;
    `z:real`] DYHO_STAR_DIAM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`--kt:int`; `nt:int`; `z:real`] DYHO_MID_DIST) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `&2 zpow (a + &1) = &2 * &2 zpow a` ASSUME_TAC THENL
   [SIMP_TAC[REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ; REAL_ZPOW_1] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* 286L(e) step b (adjacency): if x lies in Ktilde = dyho(a+1) q, and        *)
(* dyho(a+1) m (=                                                            *)
(* I_ups, same scale) meets Ktilde* = dyho_star(a+1) q (witnessed by z),     *)
(* then x is within                                                          *)
(* (3/2) mu I_ups of the centre x_ups = dyho_mid(a+1) m. Same-scale          *)
(* overlap-when-tripled                                                      *)
(* forces q-1 <= m <= q+1 (from z's two membership bounds, cancelling        *)
(* 2^{a+1} > 0 and                                                           *)
(* rounding to integers), then x in [q, q+1) t and x_ups in [(q-1/2),        *)
(* (q+3/2)] t give the                                                       *)
(* (3/2)t bound.  This is the geometric heart of the G_K weight lower bound. *)
let GK_ADJACENCY = prove
 (`!a q m x z:real.
     x IN dyho (a + &1) q /\ z IN dyho (a + &1) m /\ z IN dyho_star (a + &1) q
     ==> abs(x - dyho_mid (a + &1) m) <= &3 / &2 * &2 zpow (a + &1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; dyho_star; dyho_mid; IN_ELIM_THM] THEN
  SUBGOAL_THEN `&0 < &2 zpow (a + &1)` MP_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[int_add_th; int_of_num_th] THEN STRIP_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `real_of_int m < real_of_int q + &2 /\
     real_of_int q - &1 < real_of_int m + &1`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN
       `real_of_int m * &2 zpow (a + &1) < (real_of_int q + &2) * &2 zpow (a +
        &1)`
        MP_TAC THENL [ASM_REAL_ARITH_TAC; ASM_SIMP_TAC[REAL_LT_RMUL_EQ]];
      SUBGOAL_THEN
        `(real_of_int q - &1) * &2 zpow (a + &1) < (real_of_int m + &1) * &2
        zpow (a + &1)`
        MP_TAC THENL [ASM_REAL_ARITH_TAC; ASM_SIMP_TAC[REAL_LT_RMUL_EQ]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `real_of_int q - &1 <= real_of_int m /\
     real_of_int m <= real_of_int q + &1`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`real_of_int m < real_of_int q + &2`;
       `real_of_int q - &1 < real_of_int m + &1`] THEN
    REWRITE_TAC[GSYM ROI_1; REAL_OF_INT_CLAUSES; GSYM int_lt; GSYM int_le] THEN
      INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(real_of_int q + &1) * &2 zpow (a + &1) <= (real_of_int m + &2) * &2 zpow
    (a + &1) /\
                (real_of_int m - &1) * &2 zpow (a + &1) <= real_of_int q * &2
                  zpow (a + &1)`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC REAL_LE_RMUL THEN
     ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* Tile form of GK_ADJACENCY (destructured through tile_k/tile_I/tile_xmid). *)
let GK_ADJACENCY_TILE = prove
 (`!(ups:int#int#int) a q x z.
     tile_k ups = --(a + &1) /\
     x IN dyho (a + &1) q /\ z IN tile_I ups /\ z IN dyho_star (a + &1) q
     ==> abs(x - tile_xmid ups) <= &3 / &2 * &2 zpow (--(tile_k ups))`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC [`ku:int`; `mu:int`; `nu:int`; `a:int`; `q:int`;
    `x:real`; `z:real`] THEN
  REWRITE_TAC[tile_k; tile_I; tile_xmid] THEN STRIP_TAC THEN
  SUBGOAL_THEN `ku:int = --(a + &1)` SUBST_ALL_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[INT_NEG_NEG]) THEN REWRITE_TAC[INT_NEG_NEG] THEN
  MP_TAC(ISPECL [`a:int`; `q:int`; `mu:int`; `x:real`;
    `z:real`] GK_ADJACENCY) THEN
  ASM_REWRITE_TAC[]);;

(* Bridge (uses the tree property + maximality): the parent-triple of a      *)
(* coarse                                                                    *)
(* cover cell DOES meet I_tau. in_kcover gives ~in_jscript(parent), i.e.     *)
(* some                                                                      *)
(* sigma in P with I_sigma SUBSET parent*; the tree property I_sigma SUBSET  *)
(* I_tau                                                                     *)
(* plus I_sigma nonempty force parent* INTER I_tau nonempty.                 *)
let KCOVER_PARENT_MEETS_ITAU = prove
 (`!P:(int#int#int)->bool a p kt nt.
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      &2 zpow (a + &1) <= &2 zpow (--kt) /\
      in_kcover P a p
      ==> ~(dyho_star (a + &1) (p div &2) INTER dyho (--kt) nt = {})`,
  REPEAT GEN_TAC THEN REWRITE_TAC[in_kcover] THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[in_jscript]) THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:int#int#int` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?w:real. w IN tile_I s` (X_CHOOSE_TAC `w:real`) THENL
   [SPEC_TAC(`s:int#int#int`,`s:int#int#int`) THEN
    REWRITE_TAC[FORALL_PAIR_THM; tile_I] THEN MESON_TAC[DYHO_NONEMPTY];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN EXISTS_TAC `w:real` THEN
  CONJ_TAC THENL
   [ASM SET_TAC[];
    FIRST_X_ASSUM(MP_TAC o SPEC `s:int#int#int`) THEN ASM_REWRITE_TAC[] THEN
    ASM SET_TAC[]]);;

(* 286L(a-ii) containment: a coarse cover cell (mu K <= mu I_tau)            *)
(* lies inside the closed interval Ihat_tau = [x_tau - 7 mu I_tau, x_tau + 7 *)
(* mu I_tau]. Composes the geometric containment with the parent-meets-I_tau *)
(* bridge.                                                                   *)
let KCOVER_SUBSET_IHAT = prove
 (`!P:(int#int#int)->bool a p kt nt.
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      &2 zpow (a + &1) <= &2 zpow (--kt) /\
      in_kcover P a p
      ==> dyho a p SUBSET
          real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                        dyho_mid (--kt) nt + &7 * &2 zpow (--kt)]`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN
  X_GEN_TAC `y:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`a:int`; `p:int`; `kt:int`; `nt:int`]
     KCOVER_STAR_MEETS_ITAU_CONTAIN) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&2 zpow (a + &1)` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ZPOW2_MONOE THEN INT_ARITH_TAC;
      MATCH_MP_TAC KCOVER_PARENT_MEETS_ITAU THEN
      MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`] THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[] THEN
    REAL_ARITH_TAC]);;

(* 286L(a-ii) TOTAL MEASURE bound: the coarse cover cells (those with mu K   *)
(* <=                                                                        *)
(* mu I_tau, i.e. 2^{a+1} <= 2^{--kt}) have total measure <= 14 mu I_tau.    *)
(* All lie                                                                   *)
(* in Ihat_tau (KCOVER_SUBSET_IHAT), are disjoint (KCOVER_DISJOINT, inside   *)
(* KCOVER_MEASURE_SUM_LE), and mu Ihat = 14*2^{--kt}. Fremlin's sharp 7      *)
(* becomes                                                                   *)
(* 14 by the crude closed-interval route; immaterial (C7 = some finite       *)
(* constant).                                                                *)
(* This is the S in CELL_SUM_BOUND_ABSTRACT for the alpha0 outer cover-sum.  *)
let KCOVER_COARSE_MEASURE_BOUND = prove
 (`!P:(int#int#int)->bool S kt nt.
      FINITE S /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap) /\
                        &2 zpow (FST ap + &1) <= &2 zpow (--kt))
      ==> sum (IMAGE (\ap. dyho (FST ap) (SND ap)) S) (\c. real_measure c)
          <= &14 * &2 zpow (--kt)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`; `S:(int#int)->bool`;
     `real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                    dyho_mid (--kt) nt + &7 * &2 zpow (--kt)]`]
     KCOVER_MEASURE_SUM_LE) THEN
  SUBGOAL_THEN
   `real_measure(real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                               dyho_mid (--kt) nt + &7 * &2 zpow (--kt)])
    = &14 * &2 zpow (--kt)`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN
    SUBGOAL_THEN `&0 < &2 zpow (--kt)` MP_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL] THEN CONJ_TAC THEN
  X_GEN_TAC `ap:int#int` THEN DISCH_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `ap:int#int`) THEN ASM_SIMP_TAC[];
    MATCH_MP_TAC KCOVER_SUBSET_IHAT THEN
    MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`] THEN
    ASM_SIMP_TAC[] THEN FIRST_X_ASSUM(MP_TAC o SPEC `ap:int#int`) THEN
    ASM_SIMP_TAC[]]);;

(* --- 286L(a-iv) per-level count: coarse levels have <= 14 cover cells each *)
(* ---                                                                       *)

(* General parent-meets-I_tau bridge (NO coarse/fine hypothesis needed): for *)
(* ANY                                                                       *)
(* cover cell, the tree property + maximality force the parent-triple to     *)
(* meet                                                                      *)
(* I_tau.  (The coarseness hyp in KCOVER_PARENT_MEETS_ITAU was unnecessary.) *)
let KCOVER_PARENT_MEETS_ITAU_GEN = prove
 (`!P:(int#int#int)->bool a p kt nt.
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\ in_kcover P a p
      ==> ~(dyho_star (a + &1) (p div &2) INTER dyho (--kt) nt = {})`,
  REPEAT GEN_TAC THEN REWRITE_TAC[in_kcover] THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[in_jscript]) THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:int#int#int` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?w:real. w IN tile_I s` (X_CHOOSE_TAC `w:real`) THENL
   [SPEC_TAC(`s:int#int#int`,`s:int#int#int`) THEN
    REWRITE_TAC[FORALL_PAIR_THM; tile_I] THEN
      MESON_TAC[DYHO_NONEMPTY]; ALL_TAC] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN EXISTS_TAC `w:real` THEN
  CONJ_TAC THENL
   [ASM SET_TAC[];
    FIRST_X_ASSUM(MP_TAC o SPEC `s:int#int#int`) THEN ASM_REWRITE_TAC[] THEN
    ASM SET_TAC[]]);;

(* Unconditional triangle bound: y in cover cell + parent-triple meets I_tau *)
(* => abs(y - x_tau) <= 6*2^a + 2^{--kt} (no scale comparison).              *)
let KCOVER_STAR_TRIANGLE = prove
 (`!a p kt nt. ~(dyho_star (a + &1) (p div &2) INTER dyho (--kt) nt = {})
      ==> !y. y IN dyho a p
              ==> abs(y - dyho_mid (--kt) nt) <= &6 * &2 zpow a + &2 zpow
                (--kt)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:real` STRIP_ASSUME_TAC) THEN
  X_GEN_TAC `y:real` THEN DISCH_TAC THEN
  SUBGOAL_THEN `y IN dyho_star (a + &1) (p div &2)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:int`; `p:int`] DYHO_SUBSET_STAR) THEN
    MP_TAC(ISPECL [`a:int`; `p:int`] DYHO_STAR_PARENT) THEN
      ASM SET_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`a + &1:int`; `p div &2`; `y:real`;
    `z:real`] DYHO_STAR_DIAM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`--kt:int`; `nt:int`; `z:real`] DYHO_MID_DIST) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `&2 zpow (a + &1) = &2 * &2 zpow a` ASSUME_TAC THENL
   [SIMP_TAC[REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ; REAL_ZPOW_1] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* Coarse containment: a cover cell at least as large as I_tau (2^{--kt} <=  *)
(* 2^a) lies within 7*2^a of x_tau.                                          *)
let KCOVER_SUBSET_IHAT_COARSE = prove
 (`!P:(int#int#int)->bool a p kt nt.
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      &2 zpow (--kt) <= &2 zpow a /\ in_kcover P a p
      ==> dyho a p SUBSET
          real_interval[dyho_mid (--kt) nt - &7 * &2 zpow a,
                        dyho_mid (--kt) nt + &7 * &2 zpow a]`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN
  X_GEN_TAC `y:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`a:int`; `p:int`; `kt:int`;
    `nt:int`] KCOVER_STAR_TRIANGLE) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC KCOVER_PARENT_MEETS_ITAU_GEN THEN
    MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[] THEN
    ASM_REAL_ARITH_TAC]);;

(* 286L(a-iv) per-level MEASURE bound: cover cells at a fixed coarse scale a *)
(* (2^{--kt} <= 2^a, i.e. level l = --a < k_tau) have total measure <=       *)
(* 14*2^a.                                                                   *)
(* Each such cell has measure 2^a, so this bounds their COUNT by 14 -- a     *)
(* uniform                                                                   *)
(* per-level bound (Fremlin's exact 3 is not needed; any constant gives      *)
(* alpha1                                                                    *)
(* convergence). Same measure engine (disjoint cover cells in a 14*2^a       *)
(* interval).                                                                *)
let KCOVER_LEVEL_MEASURE_BOUND = prove
 (`!P:(int#int#int)->bool S a kt nt.
      FINITE S /\ &2 zpow (--kt) <= &2 zpow a /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!q. q IN S ==> in_kcover P a q)
      ==> sum (IMAGE (\q. dyho a q) S) (\c. real_measure c) <= &14 * &2 zpow
        a`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_measure(real_interval[dyho_mid (--kt) nt - &7 * &2 zpow a,
                                         dyho_mid (--kt) nt + &7 * &2 zpow a])`
                                           THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC DISJOINT_CELLS_MEASURE_SUM_LE THEN
    ASM_SIMP_TAC[FINITE_IMAGE; REAL_MEASURABLE_REAL_INTERVAL] THEN
    REPEAT CONJ_TAC THEN REWRITE_TAC[FORALL_IN_IMAGE] THENL
     [X_GEN_TAC `q:int` THEN DISCH_TAC THEN REWRITE_TAC[DYHO_MEASURABLE];
      X_GEN_TAC `q:int` THEN DISCH_TAC THEN
      MATCH_MP_TAC KCOVER_SUBSET_IHAT_COARSE THEN
      MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`] THEN ASM_SIMP_TAC[];
      REWRITE_TAC[IMP_CONJ; RIGHT_FORALL_IMP_THM; FORALL_IN_IMAGE] THEN
      X_GEN_TAC `q1:int` THEN DISCH_TAC THEN REWRITE_TAC[FORALL_IN_IMAGE] THEN
      X_GEN_TAC `q2:int` THEN DISCH_TAC THEN DISCH_TAC THEN
      MP_TAC(SPECL [`P:(int#int#int)->bool`; `a:int`; `a:int`;
                    `q1:int`; `q2:int`] KCOVER_DISJOINT) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_SIMP_TAC[]];
    REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN
    SUBGOAL_THEN `&0 < &2 zpow a` MP_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REAL_ARITH_TAC]);;

(* --- 286L alpha0/alpha1 assembly: the cover -> ALPHA_SCALE bridge ---      *)

(* A cover cell's index-span M = 2^{a+k} at tile-scale --k is >= 1 (k >=     *)
(* --a).                                                                     *)
let ZPOW_SPAN_POS = prove
 (`!a k M:int. --k <= a /\ &2 zpow (a + k) = real_of_int M ==> &1 <= M`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `real_of_int (&1) <= real_of_int M` MP_TAC THENL
   [REWRITE_TAC[int_of_num_th] THEN
    UNDISCH_TAC `&2 zpow (a + k) = real_of_int M` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    GEN_REWRITE_TAC LAND_CONV [GSYM(ISPEC `&2` REAL_ZPOW_0)] THEN
    MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC;
    REWRITE_TAC[GSYM int_le]]);;

(* "outside the span [Q, Q+M)" as a disjunction (needs M >= 1; Q = p*M       *)
(* abstracted).                                                              *)
let SPAN_DISJ_EQV = INT_ARITH
  `!Q M nI:int. Q + M <= nI \/ nI <= Q - &1 <=>
                ~(&1 <= M /\ Q <= nI /\ nI < Q + M)`;;

(* THE cover -> ALPHA_SCALE bridge: in_jscript P a p forces every            *)
(* same-or-finer-                                                            *)
(* scale tile (k,nI,nJ) of P (k >= --a, i.e. mu I_sigma <= mu K) to have its *)
(* I-index                                                                   *)
(* nI OUTSIDE the cover cell's own span [p*M, p*M+M), M = 2^{a+k}. This is   *)
(* exactly                                                                   *)
(* the "q+M <= FST(SND s) \/ FST(SND s) <= q-1" hypothesis of                *)
(* CARLESON_ALPHA_SCALE.                                                     *)
(* Proof: if nI were inside the span, DYHO_SUBCELL_IFF gives I_sigma SUBSET  *)
(* dyho a p                                                                  *)
(* SUBSET dyho_star a p = K*, contradicting in_jscript (K in Cal J).         *)
let JSCRIPT_TILE_OUTSIDE_SPAN = prove
 (`!P:(int#int#int)->bool a p k nI nJ M.
      in_jscript P a p /\ (k,nI,nJ) IN P /\ --k <= a /\
      &2 zpow (a + k) = real_of_int M
      ==> (p * M + M <= nI \/ nI <= p * M - &1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= (M:int)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:int`; `k:int`; `M:int`] ZPOW_SPAN_POS) THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[SPAN_DISJ_EQV] THEN
  UNDISCH_TAC `in_jscript (P:(int#int#int)->bool) a p` THEN
  REWRITE_TAC[in_jscript] THEN
  DISCH_THEN(MP_TAC o SPEC `(k,nI,nJ):int#int#int`) THEN
  ASM_REWRITE_TAC[tile_k; tile_I] THEN
  SUBGOAL_THEN `&2 zpow (--k) <= &2 zpow a` (fun th -> REWRITE_TAC[th]) THENL
   [MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT `(b ==> a) ==> (~a ==> ~b)`) THEN DISCH_TAC THEN
  MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `dyho a p` THEN
  REWRITE_TAC[DYHO_SUBSET_STAR] THEN
  MP_TAC(ISPECL [`--k:int`; `a:int`; `M:int`; `p:int`;
    `nI:int`] DYHO_SUBCELL_IFF) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ASM_INT_ARITH_TAC;
      SUBGOAL_THEN `a - --k = a + k:int` SUBST1_TAC THENL
       [INT_ARITH_TAC; ASM_REWRITE_TAC[]]];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

(* in_kcover form of the bridge (directly usable at the CARLESON_ALPHA_SCALE *)
(* call                                                                      *)
(* site): a cover cell dyho a p and any tile s IN P at scale k (k >= --a)    *)
(* have s's                                                                  *)
(* I-index FST(SND s) outside the span [p*M, p*M+M), M = 2^{a+k}. in_kcover  *)
(* =>                                                                        *)
(* in_jscript, then JSCRIPT_TILE_OUTSIDE_SPAN on the destructured tile.      *)
let KCOVER_TILE_OUTSIDE_SPAN = prove
 (`!P:(int#int#int)->bool a p k s M.
      in_kcover P a p /\ s IN P /\ tile_k s = k /\ --k <= a /\
      &2 zpow (a + k) = real_of_int M
      ==> (p * M + M <= FST(SND s) \/ FST(SND s) <= p * M - &1)`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_k; in_kcover] THEN REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`P:(int#int#int)->bool`; `a:int`; `p:int`;
                `p1:int`; `p1':int`; `p2:int`;
                  `M:int`] JSCRIPT_TILE_OUTSIDE_SPAN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC);;

(* --- 286L(d) alpha1: the TIGHT offset bound (via the TRIPLED cell Kstar)   *)
(* ---                                                                       *)
(* alpha1 (W1: mu K > mu I_tau) sums the per-scale bound over INFINITELY     *)
(* many coarse                                                               *)
(* cover levels l_K < k_tau, so the loose "offset >= 0" of alpha0 is not     *)
(* enough: the                                                               *)
(* geometric series in the coarse index would diverge. Fremlin's tight       *)
(* per-scale                                                                 *)
(* bound (286L(c-i)) carries a factor (1 + 2^{k-l})^{-2} = (1+N)^{-2} with N *)
(* the offset                                                                *)
(* of the tile's I-index from the cover cell's span; N >= M = 2^{a+k},       *)
(* because the tile                                                          *)
(* escapes the TRIPLED cell K* (not just K). These lemmas establish that     *)
(* tight offset.                                                             *)

(* A tile whose I-index nI lies in the TRIPLED span [(p-1)M,(p+2)M) has      *)
(* I_sigma =                                                                 *)
(* dyho(--k) nI contained in the tripled cover cell K* = dyho_star a p.      *)
(* (Endpoint                                                                 *)
(* arithmetic: 2^a = M 2^{-k}, and (p-1)M <= nI, nI+1 <= (p+2)M scale up to  *)
(* the K*                                                                    *)
(* edges.) This is the containment that in_jscript forbids for same-or-finer *)
(* tiles.                                                                    *)
let DYHO_STAR_SUBCELL = prove
 (`!a k M p nI:int.
     --k <= a /\ &2 zpow (a + k) = real_of_int M /\
     (p - &1) * M <= nI /\ nI < (p + &2) * M
     ==> dyho (--k) nI SUBSET dyho_star a p`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[dyho; dyho_star; SUBSET; IN_ELIM_THM] THEN
  SUBGOAL_THEN `&2 zpow a = real_of_int M * &2 zpow (--k)` ASSUME_TAC THENL
   [UNDISCH_TAC `&2 zpow (a + k) = real_of_int M` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    SUBGOAL_THEN
      `~(&2 =
       &0)` (fun th -> REWRITE_TAC[GSYM(MATCH_MP REAL_ZPOW_ADD th)]) THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    AP_TERM_TAC THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&0 < &2 zpow (--k)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `real_of_int ((p - &1) * M) <= real_of_int nI /\
                real_of_int nI + &1 <= real_of_int ((p + &2) * M)`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [ASM_REWRITE_TAC[GSYM int_le];
      REWRITE_TAC[GSYM ROI_1; REAL_OF_INT_CLAUSES; GSYM int_le] THEN
        ASM_INT_ARITH_TAC];
    ALL_TAC] THEN
  X_GEN_TAC `x:real` THEN STRIP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
     EXISTS_TAC `real_of_int nI * &2 zpow (--k)` THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(real_of_int p - &1) * real_of_int M * &2 zpow --k =
                  real_of_int ((p - &1) * M) * &2 zpow (--k)` SUBST1_TAC THENL
     [REWRITE_TAC[ROI_MUL; int_sub_th; ROI_1] THEN
       CONV_TAC REAL_RING; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LE_RMUL_EQ];
    MATCH_MP_TAC REAL_LTE_TRANS THEN
      EXISTS_TAC `(real_of_int nI + &1) * &2 zpow (--k)` THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(real_of_int p + &2) * real_of_int M * &2 zpow --k =
                    real_of_int ((p + &2) * M) * &2 zpow (--k)` SUBST1_TAC
                      THENL
       [REWRITE_TAC[ROI_MUL; int_add_th] THEN
        SUBGOAL_THEN `real_of_int(&2) = &2` SUBST1_TAC THENL
         [REWRITE_TAC[int_of_num_th]; CONV_TAC REAL_RING];
        ALL_TAC] THEN
      ASM_SIMP_TAC[REAL_LE_RMUL_EQ]]]);;

(* in_jscript forbids any same-or-finer tile (k,nI,nJ) in P (k >= --a) from  *)
(* having                                                                    *)
(* I_sigma inside the tripled cover cell K* = dyho_star a p. (SPEC the       *)
(* in_jscript                                                                *)
(* condition, discharge its scale side-condition 2^{-k} <= 2^a via           *)
(* ZPOW2_MONOE.)                                                             *)
let JSCRIPT_TILE_NOTSUBSET = prove
 (`!P:(int#int#int)->bool a p k nI nJ.
     in_jscript P a p /\ (k,nI,nJ) IN P /\ --k <= a
     ==> ~(dyho (--k) nI SUBSET dyho_star a p)`,
  REPEAT STRIP_TAC THEN
  UNDISCH_TAC `in_jscript (P:(int#int#int)->bool) a p` THEN
  REWRITE_TAC[in_jscript] THEN
  DISCH_THEN(MP_TAC o SPEC `(k,nI,nJ):int#int#int`) THEN
  ASM_REWRITE_TAC[tile_k; tile_I] THEN
  SUBGOAL_THEN `&2 zpow (--k) <= &2 zpow a` ASSUME_TAC THENL
   [MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* Combine: a same-or-finer tile's I-index nI is OUTSIDE the tripled span,   *)
(* i.e.                                                                      *)
(* nI < (p-1)M \/ (p+2)M <= nI. (If nI were inside, DYHO_STAR_SUBCELL would  *)
(* put                                                                       *)
(* I_sigma in K*, contradicting JSCRIPT_TILE_NOTSUBSET. The final integer    *)
(* step is a                                                                 *)
(* pure tautology, proved in a CLEAN context to avoid real-assumption        *)
(* INT_ARITH poison.)                                                        *)
let JSCRIPT_SPAN_NEG = prove
 (`!P:(int#int#int)->bool a p k nI nJ M.
     in_jscript P a p /\ (k,nI,nJ) IN P /\ --k <= a /\
     &2 zpow (a + k) = real_of_int M
     ==> ~((p - &1) * M <= nI /\ nI < (p + &2) * M)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`P:(int#int#int)->bool`; `a:int`; `p:int`; `k:int`; `nI:int`;
    `nJ:int`]
     JSCRIPT_TILE_NOTSUBSET) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`a:int`; `k:int`; `M:int`; `p:int`;
    `nI:int`] DYHO_STAR_SUBCELL) THEN
  ASM_REWRITE_TAC[]);;

let JSCRIPT_TILE_OFFSET_TIGHT = prove
 (`!P:(int#int#int)->bool a p k nI nJ M.
     in_jscript P a p /\ (k,nI,nJ) IN P /\ --k <= a /\
     &2 zpow (a + k) = real_of_int M
     ==> nI < (p - &1) * M \/ (p + &2) * M <= nI`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`P:(int#int#int)->bool`; `a:int`; `p:int`; `k:int`; `nI:int`;
    `nJ:int`;
                `M:int`] JSCRIPT_SPAN_NEG) THEN
  ASM_REWRITE_TAC[] THEN POP_ASSUM_LIST(K ALL_TAC) THEN INT_ARITH_TAC);;

(* in_kcover form usable at the CARLESON_ALPHA_SCALE_TIGHT call site: the    *)
(* loose span-                                                               *)
(* exclusion disjunction (q + M <= nI \/ nI <= q - 1, q = pM) AND the TIGHT  *)
(* offset lower                                                              *)
(* bound N = M on the signed distance to the span. From                      *)
(* JSCRIPT_TILE_OFFSET_TIGHT:                                                *)
(* nI < (p-1)M gives (q-1)-nI >= M; (p+2)M <= nI gives nI-(q+M) >= M. Both   *)
(* branches of                                                               *)
(* the offset "if" are >= M. (Products p*M expanded to p*M-M, p*M+2M so      *)
(* INT_ARITH sees                                                            *)
(* the offsets linearly; M >= 1 from ZPOW_SPAN_POS.)                         *)
let KCOVER_TILE_OFFSET_TIGHT = prove
 (`!P:(int#int#int)->bool a p k s M.
     in_kcover P a p /\ s IN P /\ tile_k s = k /\ --k <= a /\
     &2 zpow (a + k) = real_of_int M
     ==> (p * M + M <= FST(SND s) \/ FST(SND s) <= p * M - &1) /\
         M <= (if p * M + M <= FST(SND s) then FST(SND s) - (p * M + M)
               else (p * M - &1) - FST(SND s))`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_k; in_kcover] THEN REPEAT GEN_TAC THEN
    STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= (M:int) /\ (p1' < (p - &1) * M \/ (p + &2) * M <= p1')`
    MP_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`a:int`; `k:int`; `M:int`] ZPOW_SPAN_POS) THEN
       ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`P:(int#int#int)->bool`; `a:int`; `p:int`; `k:int`;
        `p1':int`; `p2:int`;
                    `M:int`] JSCRIPT_TILE_OFFSET_TIGHT) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      UNDISCH_TAC `p1,p1',p2 IN (P:(int#int#int)->bool)` THEN
      UNDISCH_TAC `p1 = (k:int)` THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REWRITE_TAC[]];
    POP_ASSUM_LIST(K ALL_TAC) THEN
    REWRITE_TAC[INT_ARITH `(p - &1) * M = p * M - M`;
      INT_ARITH `(p + &2) * M = p * M + &2 * M`] THEN
    DISCH_THEN(CONJUNCTS_THEN ASSUME_TAC) THEN CONJ_TAC THENL
     [ASM_INT_ARITH_TAC;
      COND_CASES_TAC THEN ASM_INT_ARITH_TAC]]);;

(* num_of_int helpers for the tight bound's offset N (a :num). For M >= 0,   *)
(* &(num_of_                                                                 *)
(* int M) = real_of_int M (so the tight bound's inv((1+&N)^2) with N =       *)
(* num_of_int M                                                              *)
(* rewrites to inv((1+2^{a+k})^2)); and num_of_int is monotone on the        *)
(* nonnegatives.                                                             *)
let ROI_NUM_OF_INT = prove
 (`!M:int. &0 <= M ==> &(num_of_int M) = real_of_int M`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `M:int` INT_OF_NUM_OF_INT) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [SYM th]) THEN
  REWRITE_TAC[int_of_num_th]);;

let NUM_OF_INT_LE = prove
 (`!a b:int. &0 <= a /\ a <= b ==> num_of_int a <= num_of_int b`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= (b:int)` ASSUME_TAC THENL
    [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM INT_OF_NUM_LE] THEN
  ASM_SIMP_TAC[INT_OF_NUM_OF_INT] THEN ASM_REWRITE_TAC[]);;

(* --- 286Gd assembly: two-sided integer weight sum sum_{n in S} w(y-n) <= 2 *)
(* ---                                                                       *)

(* A positive integer gap gives a num offset >= 1.                           *)
let NUM_OF_INT_GE1 = prove
 (`!n m:int. m < n ==> 1 <= num_of_int(n - m)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `n - m:int` INT_OF_NUM_OF_INT) THEN
  ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `p = num_of_int(n - m)` THEN DISCH_TAC THEN
  SUBGOAL_THEN `&1 <= &p:int` MP_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC;
    REWRITE_TAC[INT_OF_NUM_LE] THEN ARITH_TAC]);;

(* Every real has an integer within 1/2 (m = floor(y + 1/2)).                *)
let NEAREST_INT = prove
 (`!y:real. ?m:int. abs(y - real_of_int m) <= &1 / &2`,
  GEN_TAC THEN
  MP_TAC(ISPEC `y + &1 / &2` FLOOR) THEN STRIP_TAC THEN
  EXISTS_TAC `int_of_real(floor(y + &1 / &2))` THEN
  SUBGOAL_THEN
    `real_of_int(int_of_real(floor(y + &1 / &2))) = floor(y + &1 / &2)`
    SUBST1_TAC THENL
   [REWRITE_TAC[GSYM int_rep] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* Trichotomy split of a finite integer-indexed sum at m: n < m, n = m, n >  *)
(* m.                                                                        *)
let SUM_INT_TRICHOTOMY = prove
 (`!(S:int->bool) (f:int->real) m. FINITE S
     ==> sum S f = sum {n | n IN S /\ n < m} f + sum {n | n IN S /\ n = m} f +
                   sum {n | n IN S /\ m < n} f`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `FINITE {n:int | n IN S /\ n < m} /\ FINITE {n:int | n IN S /\ n = m} /\
    FINITE {n:int | n IN S /\ m < n}` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC FINITE_RESTRICT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `DISJOINT {n:int | n IN S /\ n = m} {n | n IN S /\ m < n}` ASSUME_TAC THENL
   [REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM; NOT_IN_EMPTY] THEN
    X_GEN_TAC `n:int` THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT {n:int | n IN S /\ n < m}
             ({n | n IN S /\ n = m} UNION {n | n IN S /\ m < n})` ASSUME_TAC
               THENL
   [REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_UNION; IN_ELIM_THM;
     NOT_IN_EMPTY] THEN
    X_GEN_TAC `n:int` THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `S = {n:int | n IN S /\ n < m} UNION ({n | n IN S /\ n = m} UNION {n | n IN
     S /\ m < n})`
   (fun th -> GEN_REWRITE_TAC (LAND_CONV o RATOR_CONV o RAND_CONV) [th]) THENL
   [REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM] THEN X_GEN_TAC `n:int` THEN
    EQ_TAC THENL [DISCH_TAC THEN ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC;
                  STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`f:int->real`; `{n:int | n IN S /\ n < m}`;
                 `{n:int | n IN S /\ n = m} UNION {n | n IN S /\ m < n}`]
                   SUM_UNION) THEN
  ASM_SIMP_TAC[FINITE_UNION] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`f:int->real`; `{n:int | n IN S /\ n = m}`;
                 `{n:int | n IN S /\ m < n}`] SUM_UNION) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

(* The n > m piece: reindex n |-> num_of_int(n-m) into offsets >= 1, then    *)
(* CW_ONESIDE_                                                               *)
(* SUM (left shift r - &j). SUM_IMAGE injectivity from num_of_int being 1-1  *)
(* on the                                                                    *)
(* positive gaps; the summand equality via ROI_NUM_OF_INT (& num_of_int =    *)
(* real_of_int).                                                             *)
let CW_TWOSIDE_RIGHT = prove
 (`!(S:int->bool) m r. FINITE S /\ abs r <= &1 / &2
     ==> sum {n | n IN S /\ m < n} (\n. cw(r - real_of_int(n - m))) <= &1 /
       &2`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `sum {n:int | n IN S /\ m < n} (\n. cw(r - real_of_int(n - m))) =
    sum (IMAGE (\n:int. num_of_int(n - m)) {n | n IN S /\ m < n}) (\j. cw(r -
      &j))`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN
    MP_TAC(ISPECL [`\n:int. num_of_int(n - m)`; `\j:num. cw(r - &j)`;
                   `{n:int | n IN S /\ m < n}`] SUM_IMAGE) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN MAP_EVERY X_GEN_TAC [`a:int`; `b:int`] THEN
       STRIP_TAC THEN
      MP_TAC(ISPEC `a - m:int` INT_OF_NUM_OF_INT) THEN ANTS_TAC THENL
        [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      MP_TAC(ISPEC `b - m:int` INT_OF_NUM_OF_INT) THEN ANTS_TAC THENL
        [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      REPEAT DISCH_TAC THEN
      SUBGOAL_THEN `a - m:int = b - m` MP_TAC THENL
       [FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC LAND_CONV [SYM th]) THEN
        FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC RAND_CONV [SYM th]) THEN
          ASM_REWRITE_TAC[];
        INT_ARITH_TAC];
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF] THEN
      MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `n:int` THEN
        REWRITE_TAC[IN_ELIM_THM] THEN
      STRIP_TAC THEN REWRITE_TAC[] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
      MATCH_MP_TAC ROI_NUM_OF_INT THEN ASM_INT_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC CW_ONESIDE_SUM THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_IMAGE THEN ASM_SIMP_TAC[FINITE_RESTRICT];
    REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM] THEN
    X_GEN_TAC `n:int` THEN STRIP_TAC THEN
    MATCH_MP_TAC NUM_OF_INT_GE1 THEN ASM_REWRITE_TAC[]]);;

(* The n < m piece: reindex n |-> num_of_int(m-n), CW_ONESIDE_SUM_R (right   *)
(* shift r + &j), since r - real_of_int(n-m) = r + real_of_int(m-n).         *)
let CW_TWOSIDE_LEFT = prove
 (`!(S:int->bool) m r. FINITE S /\ abs r <= &1 / &2
     ==> sum {n | n IN S /\ n < m} (\n. cw(r - real_of_int(n - m))) <= &1 /
       &2`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `sum {n:int | n IN S /\ n < m} (\n. cw(r - real_of_int(n - m))) =
    sum (IMAGE (\n:int. num_of_int(m - n)) {n | n IN S /\ n < m}) (\j. cw(r +
      &j))`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN
    MP_TAC(ISPECL [`\n:int. num_of_int(m - n)`; `\j:num. cw(r + &j)`;
                   `{n:int | n IN S /\ n < m}`] SUM_IMAGE) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN MAP_EVERY X_GEN_TAC [`a:int`; `b:int`] THEN
       STRIP_TAC THEN
      MP_TAC(ISPEC `m - a:int` INT_OF_NUM_OF_INT) THEN ANTS_TAC THENL
        [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      MP_TAC(ISPEC `m - b:int` INT_OF_NUM_OF_INT) THEN ANTS_TAC THENL
        [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      REPEAT DISCH_TAC THEN
      SUBGOAL_THEN `m - a:int = m - b` MP_TAC THENL
       [FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC LAND_CONV [SYM th]) THEN
        FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC RAND_CONV [SYM th]) THEN
          ASM_REWRITE_TAC[];
        INT_ARITH_TAC];
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF] THEN
      MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `n:int` THEN
        REWRITE_TAC[IN_ELIM_THM] THEN
      STRIP_TAC THEN REWRITE_TAC[] THEN
      SUBGOAL_THEN `&(num_of_int(m - n)) = real_of_int(m - n)` SUBST1_TAC THENL
       [MATCH_MP_TAC ROI_NUM_OF_INT THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
      AP_TERM_TAC THEN REWRITE_TAC[int_sub_th] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC CW_ONESIDE_SUM_R THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_IMAGE THEN ASM_SIMP_TAC[FINITE_RESTRICT];
    REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM] THEN
    X_GEN_TAC `n:int` THEN STRIP_TAC THEN
    MATCH_MP_TAC NUM_OF_INT_GE1 THEN ASM_REWRITE_TAC[]]);;

(* 286Gd: sum_{n in S} w(y - n) <= 2 for any finite integer set S. Nearest   *)
(* integer m                                                                 *)
(* (NEAREST_INT); trichotomy split (SUM_INT_TRICHOTOMY); left/right pieces   *)
(* <= 1/2 each                                                               *)
(* (CW_TWOSIDE_LEFT/RIGHT); the n = m singleton term w(y-m) <= 1 (CW_LE_1).  *)
(* This is                                                                   *)
(* the pointwise engine for v2 in alpha2 (286L f-iii): sum over the          *)
(* half-integer grid.                                                        *)
let CW_INTEGER_SHIFT_SUM = prove
 (`!(S:int->bool) y. FINITE S ==> sum S (\n. cw(y - real_of_int n)) <= &2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `y:real` NEAREST_INT) THEN DISCH_THEN(X_CHOOSE_TAC `m:int`) THEN
  ASM_SIMP_TAC[SUM_INT_TRICHOTOMY] THEN
  SUBGOAL_THEN
   `!n:int. cw(y - real_of_int n) = cw((y - real_of_int m) - real_of_int(n -
     m))`
   (fun th -> ONCE_REWRITE_TAC[th]) THENL
   [GEN_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[int_sub_th] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `l <= &1 / &2 /\ mid <= &1 /\ r <= &1 / &2 ==> l +
    mid + r <= &2`) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CW_TWOSIDE_LEFT THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[INT_SUB_REFL; int_of_num_th; REAL_SUB_RZERO] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `sum {m:int} (\x. cw(y - real_of_int m))` THEN CONJ_TAC THENL
     [MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
      REWRITE_TAC[FINITE_SING] THEN CONJ_TAC THENL
       [REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_SING] THEN SIMP_TAC[];
        REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
          REWRITE_TAC[CW_POS]];
      REWRITE_TAC[SUM_SING] THEN REWRITE_TAC[CW_LE_1]];
    MATCH_MP_TAC CW_TWOSIDE_RIGHT THEN ASM_REWRITE_TAC[]]);;

(* Chebyshev / Markov (measure from a lower-bounded integral): if c <= f on  *)
(* a                                                                         *)
(* measurable set A and f is integrable there, then c * mu A <= int_A f.     *)
(* (int_A c =                                                                *)
(* c mu A via has_real_measure = (\x.1) has_real_integral (mu A);            *)
(* REAL_INTEGRAL_LE.)                                                        *)
(* 286L(e) step 6: on E cap g^-1[J_ups] cap K the weight w_ups >= w(3/2)/(2  *)
(* mu K), so                                                                 *)
(* (w(3/2)/2 mu K) mu(...) <= int w_ups <= gamma', giving mu(...) <= 2       *)
(* gamma' mu K/w(3/2).                                                       *)
let CHEBYSHEV_MEASURE = prove
 (`!A f c. real_measurable A /\ f real_integrable_on A /\ (!x. x IN A ==> c <=
   f x)
     ==> c * real_measure A <= real_integral A f`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `((\x. &1) has_real_integral (real_measure A)) A` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM has_real_measure] THEN
    ASM_REWRITE_TAC[HAS_REAL_MEASURE_REAL_MEASURABLE_REAL_MEASURE];
      ALL_TAC] THEN
  SUBGOAL_THEN
    `c * real_measure A = real_integral A (\x. c * &1)` SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_LMUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_INTEGRABLE THEN
    EXISTS_TAC `real_measure A` THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN REWRITE_TAC[REAL_MUL_RID] THEN
    ASM_SIMP_TAC[]]);;

(* Dual of CHEBYSHEV_MEASURE: if f <= M on a measurable set A and f is       *)
(* integrable there,                                                         *)
(* then int_A f <= M mu A. (int_A M = M mu A via has_real_measure = (\x.1)   *)
(* has_real_                                                                 *)
(* integral (mu A); REAL_INTEGRAL_LE.) This is the per-cell step int_{G_K}   *)
(* v2 <= (2 C1                                                               *)
(* gamma) mu G_K in the alpha2 int-v2 layer.                                 *)
let INTEGRAL_LE_BOUND_MEASURE = prove
 (`!A f M. real_measurable A /\ f real_integrable_on A /\ (!x. x IN A ==> f x
   <= M)
     ==> real_integral A f <= M * real_measure A`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `((\x. &1) has_real_integral (real_measure A)) A` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM has_real_measure] THEN
    ASM_REWRITE_TAC[HAS_REAL_MEASURE_REAL_MEASURABLE_REAL_MEASURE];
      ALL_TAC] THEN
  SUBGOAL_THEN
    `M * real_measure A = real_integral A (\x. M * &1)` SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_LMUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_INTEGRABLE THEN
    EXISTS_TAC `real_measure A` THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN REWRITE_TAC[REAL_MUL_RID] THEN
      ASM_SIMP_TAC[]]);;

(* --- 286D toolkit (abstract measure theory, no Carleson dependence): the   *)
(* Markov/Chebyshev level-set bound + integrability of a nonneg measurable   *)
(* function on a measurable subset. Used for the 286U(b) a.e.-finiteness of  *)
(* the                                                                       *)
(* window family: from int_E Ahat_m f <= C sqrt muE (all finite-measure E),  *)
(* the                                                                       *)
(* sup sup_m Ahat_m f is finite a.e. (Fremlin 286D). ---                     *)

(* g restricted to the level set is measurable via the univ-restrict bridge. *)
let REAL_INTEGRABLE_ON_NONNEG_INTER = prove
 (`!(g:real->real) A L.
     real_measurable A /\ real_lebesgue_measurable L /\
     g real_measurable_on A /\ g real_integrable_on A /\
     (!x. x IN A ==> &0 <= g x)
     ==> (g:real->real) real_integrable_on (L INTER A)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM REAL_INTEGRABLE_RESTRICT_INTER] THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `g:real->real` THEN REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `(g:real->real) real_measurable_on (L INTER A)` MP_TAC THENL
     [MATCH_MP_TAC REAL_MEASURABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
      EXISTS_TAC `A:real->bool` THEN ASM_REWRITE_TAC[INTER_SUBSET] THEN
      MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN
      ASM_SIMP_TAC[REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE];
      ONCE_REWRITE_TAC[GSYM REAL_MEASURABLE_ON_UNIV] THEN
      MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real` THEN
      REWRITE_TAC[IN_INTER] THEN
      ASM_CASES_TAC `(x:real) IN A` THEN ASM_CASES_TAC `(x:real) IN L` THEN
      ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
    SUBGOAL_THEN `&0 <= (g:real->real) x` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    COND_CASES_TAC THEN ASM_REAL_ARITH_TAC]);;

let REAL_INTEGRABLE_ON_NONNEG_MEASURABLE_SUBSET = prove
 (`!(g:real->real) A L.
     real_measurable A /\ real_lebesgue_measurable L /\ L SUBSET A /\
     g real_measurable_on A /\ g real_integrable_on A /\
     (!x. x IN A ==> &0 <= g x)
     ==> (g:real->real) real_integrable_on L`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `L:real->bool = L INTER A` (fun th -> ONCE_REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[SET_RULE `L SUBSET A ==> L = L INTER A`]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRABLE_ON_NONNEG_INTER THEN ASM_REWRITE_TAC[]);;

(* A measurable-subset bound in the form needed below.                       *)
let MK_LEBMEAS_SUBSET = prove
 (`!s t. real_lebesgue_measurable s /\ real_measurable t /\ s SUBSET t
         ==> real_measurable s`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_MEASURABLE_MEASURABLE] THEN
  MATCH_MP_TAC MEASURABLE_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `IMAGE lift t` THEN
  ASM_REWRITE_TAC[GSYM REAL_LEBESGUE_MEASURABLE;
    GSYM REAL_MEASURABLE_MEASURABLE] THEN
  MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[]);;

(* The level-set identity A INTER {y | k < g y} = superlevel of g.chi_A.     *)
let MK_LEVEL_ID = prove
 (`!(g:real->real) A k. &0 < k
     ==> A INTER {y | k < g y} = {y | (\x. if x IN A then g x else &0) y > k}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
  GEN_TAC THEN REWRITE_TAC[real_gt] THEN COND_CASES_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC);;

(* Markov/Chebyshev level-set measure bound: k*mu(A INTER {g>k}) <= int_A g  *)
(* <= D.                                                                     *)
let CARLESON_LEVEL_MARKOV_M = prove
 (`!(G:num->real->real) A D c m.
     real_measurable A /\ &0 < c /\
     (G m) real_measurable_on (:real) /\ (G m) real_integrable_on A /\
     (!x. x IN A ==> &0 <= G m x) /\ real_integral A (G m) <= D
     ==> real_measurable (A INTER {y | c < (G:num->real->real) m y}) /\
         c * real_measure (A INTER {y | c < G m y}) <= D`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `real_lebesgue_measurable {y | c < (G:num->real->real) m y}`
   ASSUME_TAC THENL
   [MP_TAC(ISPEC `(G:num->real->real) m`
       REAL_MEASURABLE_ON_PREIMAGE_HALFSPACE_GT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `c:real`) THEN
    REWRITE_TAC[real_gt];
    ALL_TAC] THEN
  SUBGOAL_THEN `real_measurable (A INTER {y | c < (G:num->real->real) m y})`
   ASSUME_TAC THENL
   [MATCH_MP_TAC MK_LEBMEAS_SUBSET THEN EXISTS_TAC `A:real->bool` THEN
    ASM_REWRITE_TAC[INTER_SUBSET] THEN
    MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN
    ASM_SIMP_TAC[REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(G:num->real->real) m real_integrable_on (A INTER {y | c < G m y})`
   ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[INTER_COMM] THEN
    MP_TAC(ISPECL [`(G:num->real->real) m`; `A:real->bool`;
                   `{y | c < (G:num->real->real) m y}`]
      REAL_INTEGRABLE_ON_NONNEG_INTER) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`A INTER {y | c < (G:num->real->real) m y}`;
    `(G:num->real->real) m`;
                 `c:real`] CHEBYSHEV_MEASURE) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_INTER; IN_ELIM_THM] THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `i <= D ==> c * m <= i ==> c * m <= D`) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral A ((G:num->real->real) m)` THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN
  ASM_REWRITE_TAC[INTER_SUBSET] THEN
  X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_INTER] THEN STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* 286D level-union bound: for an increasing nonneg sequence G with int_A (G *)
(* m)<=D uniformly, the union over m of the level sets A INTER {c<G m} has   *)
(* measure <=D/c. Per-m via CARLESON_LEVEL_MARKOV_M; nested increasing (G m  *)
(* up) -> HAS_REAL_ MEASURE_NESTED_UNIONS gives measurability +              *)
(* mu(UNION)=lim mu <= D/c (REALLIM_ UBOUND). ---                            *)
let CARLESON_UK_MEASURE = prove
 (`!(G:num->real->real) A D c.
     real_measurable A /\ &0 < c /\ &0 <= D /\
     (!m. (G m) real_measurable_on (:real) /\ (G m) real_integrable_on A /\
          (!x. x IN A ==> &0 <= G m x) /\ real_integral A (G m) <= D) /\
     (!m x. x IN A ==> G m x <= G (SUC m) x)
     ==> real_measurable (UNIONS { A INTER {y | c < G m y} | m IN (:num) }) /\
         real_measure (UNIONS { A INTER {y | c < G m y} | m IN (:num) }) <= D /
           c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!m. real_measurable (A INTER {y | c < (G:num->real->real) m y}) /\
        real_measure (A INTER {y | c < G m y}) <= D / c`
   ASSUME_TAC THENL
   [GEN_TAC THEN
    MP_TAC(ISPECL [`G:num->real->real`; `A:real->bool`; `D:real`; `c:real`;
      `m:num`]
      CARLESON_LEVEL_MARKOV_M) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m. (A INTER {y | c < (G:num->real->real) m y}) SUBSET
        (A INTER {y | c < G (SUC m) y})`
   ASSUME_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[SUBSET; IN_INTER; IN_ELIM_THM] THEN
    X_GEN_TAC `y:real` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `(G:num->real->real) m y` THEN
    ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\m:num. (A:real->bool) INTER {y | c < (G:num->real->real) m
    y}`;
                 `D / c:real`] HAS_REAL_MEASURE_NESTED_UNIONS) THEN
  REWRITE_TAC[] THEN ASM_SIMP_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPEC `sequentially` REALLIM_UBOUND) THEN
  EXISTS_TAC `\m. real_measure (A INTER {y | c < (G:num->real->real) m y})`
    THEN
  ASM_REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY; EVENTUALLY_SEQUENTIALLY] THEN
  EXISTS_TAC `0` THEN ASM_SIMP_TAC[]);;

(* 286D bad-set = INTERS over k of the level-unions U_k = UNIONS_m A INTER   *)
(* {&k+&1 < G m}. (y in bad set <=> y in A and for all k some G m y exceeds  *)
(* &k+&1                                                                     *)
(* <=> y in every U_k.) Extensional membership form from                     *)
(* INTERS_GSPEC/IN_UNIONS. ---                                               *)
let CARLESON_BADSET_INTERS_ID = prove
 (`!(G:num->real->real) A.
     {y | y IN A /\ !k. ?m. &k + &1 < (G:num->real->real) m y} =
     INTERS { UNIONS { A INTER {y | &k + &1 < G m y} | m IN (:num) } | k IN
       (:num) }`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; INTERS_GSPEC; IN_ELIM_THM; IN_UNIV; IN_UNIONS;
    IN_INTER] THEN
  X_GEN_TAC `y:real` THEN EQ_TAC THENL
   [STRIP_TAC THEN X_GEN_TAC `k:num` THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `k:num`) THEN
    DISCH_THEN(X_CHOOSE_TAC `m:num`) THEN
    EXISTS_TAC `A INTER {y | &k + &1 < (G:num->real->real) m y}` THEN
    CONJ_TAC THENL
     [EXISTS_TAC `m:num` THEN GEN_TAC THEN REWRITE_TAC[IN_INTER; IN_ELIM_THM];
      ASM_REWRITE_TAC[IN_INTER; IN_ELIM_THM]];
    DISCH_TAC THEN
    SUBGOAL_THEN `y IN A /\ !k. ?m. &k + &1 < (G:num->real->real) m y`
      (fun th -> ACCEPT_TAC th) THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `0`) THEN
      DISCH_THEN(X_CHOOSE_THEN `t:real->bool` STRIP_ASSUME_TAC) THEN
      FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `y:real` th)) THEN
        ASM_REWRITE_TAC[] THEN
      SIMP_TAC[];
      X_GEN_TAC `k:num` THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `k:num`) THEN
      DISCH_THEN(X_CHOOSE_THEN `t:real->bool` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `m:num` THEN
      FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `y:real` th)) THEN
        ASM_REWRITE_TAC[] THEN
      SIMP_TAC[]]]);;

(* s <= D/(&k+&1) for all k, with s,D >= 0 => s = 0 (D/(&k+&1) -> 0).        *)
let LE_DIV_LIM_ZERO = prove
 (`!s D. &0 <= s /\ &0 <= D /\ (!k. s <= D / (&k + &1)) ==> s = &0`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(REAL_ARITH `&0 <= s /\ s <= &0 ==> s = &0`) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPEC `sequentially` REALLIM_LBOUND) THEN
  MAP_EVERY EXISTS_TAC [`\k:num. D * inv(&k + &1)`] THEN
  REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY; EVENTUALLY_SEQUENTIALLY] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(SPEC `D:real` (MATCH_MP REALLIM_LMUL (SPEC `&1`
     REALLIM_1_OVER_N_OFFSET))) THEN
    SIMP_TAC[REAL_MUL_RZERO];
    EXISTS_TAC `0` THEN X_GEN_TAC `k:num` THEN DISCH_TAC THEN
    ASM_REWRITE_TAC[GSYM real_div]]);;

(* --- 286D (Fremlin mt286.tex 303-342): a.e.-finiteness of the sup.  For an *)
(* increasing nonneg sequence G with int_A (G m) <= D uniformly, the "sup =  *)
(* inf"                                                                      *)
(* bad set {y in A : !k. ?m. &k+&1 < G m y} is negligible. bad = INTERS_k    *)
(* U_k                                                                       *)
(* (CARLESON_BADSET_INTERS_ID), measurable (COUNTABLE_INTERS of the U_k),    *)
(* and                                                                       *)
(* mu(bad) <= mu(U_k) <= D/(&k+&1) for every k (CARLESON_UK_MEASURE), so     *)
(* mu(bad)=0                                                                 *)
(* (LE_DIV_LIM_ZERO); negligible via REAL_MEASURABLE_REAL_MEASURE_EQ_0.      *)
(* Instantiate                                                               *)
(* G := Ahat_(&m) f_1 to get the a.e.-finiteness the 286U(b) domination      *)
(* needs. ---                                                                *)
let CARLESON_SUP_AE_FINITE = prove
 (`!(G:num->real->real) A D.
     real_measurable A /\ &0 <= D /\
     (!m. (G m) real_measurable_on (:real) /\ (G m) real_integrable_on A /\
          (!x. x IN A ==> &0 <= G m x) /\ real_integral A (G m) <= D) /\
     (!m x. x IN A ==> G m x <= G (SUC m) x)
     ==> real_negligible {y | y IN A /\ !k. ?m. &k + &1 < (G:num->real->real) m
       y}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!k. real_measurable (UNIONS { A INTER {y | &k + &1 < (G:num->real->real) m
     y} | m IN (:num) }) /\
        real_measure (UNIONS { A INTER {y | &k + &1 < (G:num->real->real) m y}
          | m IN (:num) })
          <= D / (&k + &1)`
   ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC CARLESON_UK_MEASURE THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[CARLESON_BADSET_INTERS_ID] THEN
  SUBGOAL_THEN
   `real_measurable (INTERS { UNIONS { A INTER {y | &k + &1 <
     (G:num->real->real) m y} | m IN (:num) } | k IN (:num) })`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_COUNTABLE_INTERS THEN GEN_TAC THEN
     ASM_SIMP_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(fun th -> REWRITE_TAC[GSYM(MATCH_MP
    REAL_MEASURABLE_REAL_MEASURE_EQ_0 th)]) THEN
  MATCH_MP_TAC LE_DIV_LIM_ZERO THEN EXISTS_TAC `D:real` THEN
  ASM_SIMP_TAC[REAL_MEASURE_POS_LE] THEN
  X_GEN_TAC `k:num` THEN MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_measure (UNIONS { A INTER {y | &k + &1 < (G:num->real->real)
    m y} | m IN (:num) })` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURE_SUBSET THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[];
      MATCH_MP_TAC(SET_RULE `(?k. u = f k) ==> INTERS {f k | k IN (:num)}
        SUBSET u`) THEN
      EXISTS_TAC `k:num` THEN REFL_TAC];
    ASM_SIMP_TAC[]]);;

(* Sum/integral interchange (generic, tile-agnostic; reused by alpha2 int-v2 *)
(* and                                                                       *)
(* alpha3 int-v3). A finite family of integrals of g s over regions Bs s     *)
(* SUBSET G                                                                  *)
(* equals the single integral over G of the pointwise sum of the             *)
(* zero-extended                                                             *)
(* integrands. Each zero-extension is integrable on G by REAL_INTEGRABLE_ON_ *)
(* SUPERSET (it vanishes off Bs s), and equals g s on Bs s                   *)
(* (REAL_INTEGRABLE_EQ);                                                     *)
(* REAL_INTEGRAL_SUM interchanges, REAL_INTEGRAL_RESTRICT collapses each     *)
(* term.                                                                     *)
let SUM_INTEGRAL_RESTRICT_INTERCHANGE = prove
 (`!(A:B->bool) (G:real->bool) (Bs:B->real->bool) (g:B->real->real).
     FINITE A /\ real_measurable G /\
     (!s. s IN A ==> Bs s SUBSET G /\ (g s) real_integrable_on (Bs s))
     ==> sum A (\s. real_integral (Bs s) (g s)) =
         real_integral G (\x. sum A (\s. if x IN Bs s then g s x else &0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!s. s IN A
        ==> (\x. if x IN Bs s then (g:B->real->real) s x else &0)
            real_integrable_on G`
   ASSUME_TAC THENL
   [X_GEN_TAC `s:B` THEN DISCH_TAC THEN
    MATCH_MP_TAC REAL_INTEGRABLE_ON_SUPERSET THEN
    EXISTS_TAC `Bs (s:B):real->bool` THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `x:real` THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[];
      MATCH_MP_TAC REAL_INTEGRABLE_EQ THEN
      EXISTS_TAC `(g:B->real->real) s` THEN
      CONJ_TAC THENL
       [X_GEN_TAC `x:real` THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
        ASM_SIMP_TAC[]]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\s:B. (\x. if x IN Bs s then (g:B->real->real) s x else &0)`;
    `G:real->bool`; `A:B->bool`] REAL_INTEGRAL_SUM) THEN
  ASM_SIMP_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `s:B` THEN DISCH_TAC THEN BETA_TAC THEN
  CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_INTEGRAL_RESTRICT THEN
    ASM_SIMP_TAC[]);;

(* Sum-of-integrals <= D mu G (generic). Interchange (above) turns the       *)
(* finite sum                                                                *)
(* of region-integrals into one integral over G of the pointwise sum; if     *)
(* that                                                                      *)
(* pointwise sum is <= D on G then INTEGRAL_LE_BOUND_MEASURE gives <= D mu   *)
(* G. This                                                                   *)
(* is the |alpha_j| <= (2 C1 gamma) mu G_K engine (D = 2 C1 gamma from       *)
(* V2_POINTWISE_                                                             *)
(* COLLAPSE, G = G_K).                                                       *)
let SUM_INTEGRAL_LE_MEASURE = prove
 (`!(A:B->bool) (G:real->bool) (Bs:B->real->bool) (g:B->real->real) D.
     FINITE A /\ real_measurable G /\
     (!s. s IN A ==> Bs s SUBSET G /\ (g s) real_integrable_on (Bs s)) /\
     (!x. x IN G ==> sum A (\s. if x IN Bs s then g s x else &0) <= D)
     ==> sum A (\s. real_integral (Bs s) (g s)) <= D * real_measure G`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`A:B->bool`; `G:real->bool`; `Bs:B->real->bool`;
                 `g:B->real->real`] SUM_INTEGRAL_RESTRICT_INTERCHANGE) THEN
  ASM_SIMP_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC INTEGRAL_LE_BOUND_MEASURE THEN ASM_SIMP_TAC[] THEN
  MATCH_MP_TAC REAL_INTEGRABLE_SUM THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `s:B` THEN DISCH_TAC THEN
  MATCH_MP_TAC REAL_INTEGRABLE_ON_SUPERSET THEN
  EXISTS_TAC `Bs (s:B):real->bool` THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `x:real` THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
    ASM_SIMP_TAC[];
    MATCH_MP_TAC REAL_INTEGRABLE_EQ THEN
    EXISTS_TAC `(g:B->real->real) s` THEN
    CONJ_TAC THENL
     [X_GEN_TAC `x:real` THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[]]]);;

(* Termwise piece of the cover-integral bound: sum_{IMAGE G K} int_s v <=    *)
(* sum_{IMAGE G K}                                                           *)
(* D mu s (each int_{G c} v <= D mu(G c) by INTEGRAL_LE_BOUND_MEASURE).      *)
let SUM_COVER_INTEGRAL_LE = prove
 (`!(G:A->(real->bool)) (K:A->bool) v II.
     FINITE K /\
     (!c c'. c IN K /\ c' IN K /\ G c = G c' ==> c = c') /\
     (!c. c IN K ==> v real_integrable_on (G c) /\ G c SUBSET II) /\
     (!c c'. c IN K /\ c' IN K /\ ~(c = c') ==> real_negligible (G c INTER G
       c')) /\
     v real_integrable_on II /\ (!x. &0 <= v x)
     ==> sum K (\c. real_integral (G c) v) <= real_integral II v`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`v:real->real`; `\s:real->bool. real_integral s v`;
                 `IMAGE (G:A->(real->bool)) K`] HAS_REAL_INTEGRAL_UNIONS) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[FINITE_IMAGE] THEN CONJ_TAC THENL
     [REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `c:A` THEN DISCH_TAC THEN
      MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN ASM_SIMP_TAC[];
      REWRITE_TAC[IMP_CONJ; RIGHT_FORALL_IMP_THM; FORALL_IN_IMAGE] THEN
      X_GEN_TAC `c:A` THEN DISCH_TAC THEN REWRITE_TAC[FORALL_IN_IMAGE] THEN
      X_GEN_TAC `c':A` THEN DISCH_TAC THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o check(fun t -> is_forall(concl t) &&
        (can (find_term (fun tm -> tm = `real_negligible`)) (concl t)))) THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN
    `v real_integrable_on (UNIONS (IMAGE (G:A->(real->bool)) K))`
     ASSUME_TAC THENL
   [ASM_MESON_TAC[HAS_REAL_INTEGRAL_INTEGRABLE]; ALL_TAC] THEN
  SUBGOAL_THEN `sum K (\c. real_integral ((G:A->(real->bool)) c) v) =
                real_integral (UNIONS (IMAGE G K)) v` SUBST1_TAC THENL
   [FIRST_X_ASSUM(fun th -> if can (find_term (fun tm -> tm =
     `has_real_integral`)) (concl th)
                            then SUBST1_TAC(MATCH_MP REAL_INTEGRAL_UNIQUE th)
                              else NO_TAC) THEN
    MATCH_MP_TAC EQ_SYM THEN
    MP_TAC(ISPECL [`G:A->(real->bool)`; `\s:real->bool. real_integral s v`;
      `K:A->bool`]
      SUM_IMAGE) THEN
    ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th; o_DEF]); ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[UNIONS_SUBSET; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN ASM_SIMP_TAC[];
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    ASM_SIMP_TAC[]]);;


(* --- 286L(e) G_K weight-lower-bound bricks (toward mu G_K <= 2 gamma' mu   *)
(* K/w(3/2)) ---                                                             *)

(* 286L(e) step 4 (raw): if x is within (3/2) mu I_s of the tile centre x_s, *)
(* then                                                                      *)
(* w_s(x) = cw_tile s x >= 2^{k_s} w(3/2). (cw_tile s x = 2^{k_s}            *)
(* cw(2^{k_s}(x-x_s)),                                                       *)
(* and |2^{k_s}(x-x_s)| <= 2^{k_s}(3/2)2^{-k_s} = 3/2, so cw(...) >= cw(3/2) *)
(* by antitone.)                                                             *)
let CWTILE_LOWER_NEAR = prove
 (`!(s:int#int#int) x.
     abs(x - tile_xmid s) <= &3 / &2 * &2 zpow (--(tile_k s))
     ==> &2 zpow (tile_k s) * cw(&3 / &2) <= cw_tile s x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cw_tile] THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
  MATCH_MP_TAC CW_ANTITONE THEN
  SUBGOAL_THEN
    `abs(&2 zpow (tile_k s) * (x - tile_xmid s)) <= &3 / &2` MP_TAC THENL
   [REWRITE_TAC[REAL_ABS_MUL] THEN
    SUBGOAL_THEN
      `abs(&2 zpow (tile_k s)) = &2 zpow (tile_k s)` SUBST1_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `&2 zpow (tile_k s) * (&3 / &2 * &2 zpow (--(tile_k s)))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE];
      SUBGOAL_THEN `&2 zpow (tile_k s) * (&3 / &2 * &2 zpow (--(tile_k s))) =
                    &3 / &2 * (&2 zpow (tile_k s) * &2 zpow (--(tile_k s)))`
        SUBST1_TAC THENL
       [REWRITE_TAC[REAL_MUL_AC]; ALL_TAC] THEN
      REWRITE_TAC[REAL_ZPOW_NEG] THEN
      ASM_SIMP_TAC[REAL_MUL_RINV; REAL_LT_IMP_NZ] THEN REAL_ARITH_TAC];
    SUBGOAL_THEN `abs(&3 / &2) = &3 / &2` SUBST1_TAC THENL
     [REAL_ARITH_TAC; REAL_ARITH_TAC]]);;

(* Same, expressed via mu K: if mu I_ups = 2 mu K (2^{-k_ups} = 2*2^a, mu K  *)
(* = 2^a) and                                                                *)
(* |x - x_ups| <= (3/2) mu I_ups, then w_ups(x) >= w(3/2)/(2 mu K).          *)
(* (2^{k_ups} =                                                              *)
(* 1/(2*2^a).)                                                               *)
let CWTILE_LOWER_ON_K = prove
 (`!(ups:int#int#int) x a:int.
     &2 zpow (--(tile_k ups)) = &2 * &2 zpow a /\
     abs(x - tile_xmid ups) <= &3 / &2 * &2 zpow (--(tile_k ups))
     ==> cw(&3 / &2) / (&2 * &2 zpow a) <= cw_tile ups x`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`ups:int#int#int`; `x:real`] CWTILE_LOWER_NEAR) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(REAL_ARITH `a = b ==> b <= c ==> a <= c`) THEN
  SUBGOAL_THEN `&2 zpow (tile_k ups) = inv(&2 * &2 zpow a)` SUBST1_TAC THENL
   [FIRST_X_ASSUM(SUBST1_TAC o SYM o
      check(fun th -> lhs(concl th) = `&2 zpow (--(tile_k ups))`)) THEN
    REWRITE_TAC[REAL_ZPOW_NEG; REAL_INV_INV];
    REWRITE_TAC[real_div] THEN REAL_ARITH_TAC]);;

(* 286L(e) step b+4 bundled: for the interpolated upsilon (k_ups = -(a+1),   *)
(* tile_le sig                                                               *)
(* ups, I_sig SUBSET Ktilde* = dyho_star(a+1)(p div 2)), the weight w_ups is *)
(* >=                                                                        *)
(* w(3/2)/(2*2^a) EVERYWHERE on the cover cell K = dyho a p. For x in K      *)
(* SUBSET Ktilde                                                             *)
(* (DYHO_PARENT), GK_ADJACENCY_TILE (witness z in I_sig SUBSET I_ups, z in   *)
(* Ktilde-star)                                                              *)
(* gives |x-x_ups| <= (3/2) mu I_ups, then CWTILE_LOWER_ON_K.                *)
let GK_WEIGHT_ON_K = prove
 (`!(ups:int#int#int) (sig:int#int#int) a p x.
     tile_k ups = --(a + &1) /\ tile_le sig ups /\
     tile_I sig SUBSET dyho_star (a + &1) (p div &2) /\
     x IN dyho a p
     ==> cw(&3 / &2) / (&2 * &2 zpow a) <= cw_tile ups x`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CWTILE_LOWER_ON_K THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[INT_NEG_NEG] THEN
    SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`; REAL_ZPOW_1] THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?z:real. z IN tile_I sig` (X_CHOOSE_TAC `z:real`) THENL
   [REWRITE_TAC[MEMBER_NOT_EMPTY] THEN
    SPEC_TAC(`sig:int#int#int`,`sig:int#int#int`) THEN
    REWRITE_TAC[FORALL_PAIR_THM; tile_I] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN MESON_TAC[DYHO_NONEMPTY];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`ups:int#int#int`; `a:int`; `p div &2:int`; `x:real`;
    `z:real`]
    GK_ADJACENCY_TILE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`a:int`; `p:int`] DYHO_PARENT) THEN ASM SET_TAC[];
    UNDISCH_TAC `tile_le sig ups` THEN REWRITE_TAC[tile_le] THEN ASM SET_TAC[];
    ASM SET_TAC[]]);;

(* 286L(e) steps 4+6 combined: if w_ups >= w(3/2)/(2 mu K) on a measurable   *)
(* set A and                                                                 *)
(* int_A w_ups <= gamma', then mu A <= 2 mu K gamma'/w(3/2).                 *)
(* CWTILE_LOWER_ON_K feeds                                                   *)
(* the pointwise bound; CHEBYSHEV_MEASURE (c = w(3/2)/(2 mu K)) gives the    *)
(* measure.                                                                  *)
let GK_INNER_MEASURE = prove
 (`!A (ups:int#int#int) a:int gam.
     real_measurable A /\ cw_tile ups real_integrable_on A /\
     (!x. x IN A ==> cw(&3 / &2) / (&2 * &2 zpow a) <= cw_tile ups x) /\
     real_integral A (cw_tile ups) <= gam
     ==> real_measure A <= &2 * &2 zpow a * gam / cw(&3 / &2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 * &2 zpow a /\ &0 < cw(&3 / &2)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC];
      REWRITE_TAC[CW_POS]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`A:real->bool`; `cw_tile ups`;
    `cw(&3 / &2) / (&2 * &2 zpow a)`]
    CHEBYSHEV_MEASURE) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&0 < cw(&3 / &2) / (&2 * &2 zpow a)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[REAL_LT_DIV]; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral A (cw_tile ups) / (cw(&3 / &2) / (&2 * &2 zpow a))`
    THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN
     `real_integral A (cw_tile ups) / (cw(&3 / &2) / (&2 * &2 zpow a)) =
      (&2 * &2 zpow a) / cw(&3 / &2) * real_integral A (cw_tile ups)`
      SUBST1_TAC THENL
     [MAP_EVERY UNDISCH_TAC [`&0 < &2 * &2 zpow a`; `&0 < cw(&3 / &2)`] THEN
      CONV_TAC REAL_FIELD; ALL_TAC] THEN
    SUBGOAL_THEN `&2 * &2 zpow a * gam / cw(&3 / &2) =
                  (&2 * &2 zpow a) / cw(&3 / &2) * gam` SUBST1_TAC THENL
     [CONV_TAC REAL_FIELD; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_DIV THEN ASM_SIMP_TAC[REAL_LT_IMP_LE];
      ASM_REWRITE_TAC[]]]);;

(* --- 286L(c-ii) alpha0 OUTER skeleton ---                                  *)
(* Fremlin's alpha0 = sum_{K coarse} sum_{sigma: muI<=muK} |alpha_sK|. The   *)
(* OUTER                                                                     *)
(* layer: given a per-cover-cell bound g(K) <= D mu(K) (from the inner       *)
(* geometric                                                                 *)
(* scale-sum, D = 2 C1 energy mass), the total over coarse cover cells is    *)
(* bounded                                                                   *)
(* D * 14 mu I_tau via CELL_SUM_BOUND_ABSTRACT + the a-ii                    *)
(* KCOVER_COARSE_MEASURE_                                                    *)
(* BOUND. (The inner g(K) <= D mu(K) is the per-cell geometric layer, wired  *)
(* later.)                                                                   *)
let ALPHA_CELL_GEOM_SUM = prove
 (`!A:(int#int#int)->bool g a C.
      FINITE A /\ &0 <= C /\
      (!s. s IN A ==> --a <= tile_k s) /\
      (!k. sum {s | s IN A /\ tile_k s = k} g <= C * inv(&2 zpow k))
      ==> sum A g <= (&2 * C) * real_measure(dyho a p)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[DYHO_MEASURE] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 * C * inv(&2 zpow (--a))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC ABSTRACT_SCALE_GEOM_SUM THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `tile_k:int#int#int->int` THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_ZPOW_NEG; REAL_INV_INV] THEN REAL_ARITH_TAC]);;

let SCHWARTZ_BOUND_POS = prove
 (`!(g:real->complex) k B. (!x. abs x pow k * norm(g x) <= B) ==> &0 <= B`,
  REPEAT STRIP_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `&1`) THEN
  MP_TAC(ISPEC `(g:real->complex) (&1)` NORM_POS_LE) THEN
  REWRITE_TAC[REAL_ABS_NUM; REAL_POW_ONE; REAL_MUL_LID] THEN REAL_ARITH_TAC);;

(* A Schwartz function's amplitude is dominated by C * (cw)^2 (=             *)
(* C/(1+|u|)^6):                                                             *)
(* from the k=0..6 decay bounds, (1+|u|)^6 |h(u)| <= sum C(6,j) B_j. This is *)
(* the                                                                       *)
(* SQUARED-weight bound of Fremlin 286E(c) (|phi(x)| <= C1 w(x)^2, the       *)
(* second                                                                    *)
(* entry of the min); needed for the 286L(c-i) kernel estimate, where one    *)
(* factor                                                                    *)
(* of w_sigma is pulled out as sup_K w_sigma and the other integrated        *)
(* against the                                                               *)
(* mass.  Same shape as SCHWARTZ_CW_DOMINATION but degree 6.                 *)
let SCHWARTZ_CW_SQ_DOMINATION = prove
 (`!h:real->complex. schwartz h ==> ?C. &0 <= C /\ !u. norm(h u) <= C * (cw u)
   pow 2`,
  GEN_TAC THEN REWRITE_TAC[schwartz] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num->real->complex` STRIP_ASSUME_TAC) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B0:real` o SPECL [`0`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B1:real` o SPECL [`1`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B2:real` o SPECL [`2`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B3:real` o SPECL [`3`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B4:real` o SPECL [`4`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B5:real` o SPECL [`5`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B6:real` o SPECL [`6`; `0`]) THEN
  SUBGOAL_THEN
    `&0 <= B0 /\ &0 <= B1 /\ &0 <= B2 /\ &0 <= B3 /\ &0 <= B4 /\ &0 <= B5 /\ &0
    <= B6`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC SCHWARTZ_BOUND_POS THEN
     ASM_MESON_TAC[]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `(d:num->real->complex) 0 = h`]) THEN
  EXISTS_TAC `B0 + &6 * B1 + &15 * B2 + &20 * B3 + &15 * B4 + &6 * B5 + B6`
    THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `u:real` THEN REWRITE_TAC[cw] THEN
  SUBGOAL_THEN `&0 < (&1 + abs u) pow 3` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `(&1 / (&1 + abs u) pow 3) pow 2 =
     &1 / (&1 + abs u) pow 6` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_POW_DIV; REAL_POW_ONE; GSYM REAL_POW_POW] THEN
    REWRITE_TAC[ARITH_RULE `6 = 3 * 2`; REAL_POW_POW]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < (&1 + abs u) pow 6` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ; REAL_ARITH `x * &1 / y = x / y`] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 6 * norm((h:real->complex) x) <=
      B6`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 5 * norm((h:real->complex) x) <=
      B5`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 4 * norm((h:real->complex) x) <=
      B4`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 3 * norm((h:real->complex) x) <=
      B3`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 2 * norm((h:real->complex) x) <=
      B2`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 1 * norm((h:real->complex) x) <=
      B1`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 0 * norm((h:real->complex) x) <=
      B0`)) THEN
  REWRITE_TAC[real_pow; REAL_MUL_LID; REAL_POW_1] THEN
  SUBGOAL_THEN `(&1 + abs u) pow 6 =
     &1 + &6 * abs u + &15 * abs u pow 2 + &20 * abs u pow 3 +
     &15 * abs u pow 4 + &6 * abs u pow 5 + abs u pow 6` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_POW_2] THEN CONV_TAC REAL_RING; ALL_TAC] THEN
  MP_TAC(ISPEC `(h:real->complex) u` NORM_POS_LE) THEN
  REWRITE_TAC[REAL_POW_2] THEN REAL_ARITH_TAC);;

(* A Schwartz function's AMPLITUDE is dominated by C cw: from the k=0,1,2,3  *)
(* decay bounds, (1+|u|)^3 |h(u)| <= B0 + 3B1 + 3B2 + B3.                    *)
let SCHWARTZ_CW_DOMINATION = prove
 (`!h:real->complex. schwartz h ==> ?C. &0 <= C /\ !u. norm(h u) <= C * cw u`,
  GEN_TAC THEN REWRITE_TAC[schwartz] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num->real->complex` STRIP_ASSUME_TAC) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B0:real` o SPECL [`0`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B1:real` o SPECL [`1`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B2:real` o SPECL [`2`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B3:real` o SPECL [`3`; `0`]) THEN
  SUBGOAL_THEN
    `&0 <= B0 /\ &0 <= B1 /\ &0 <= B2 /\ &0 <= B3` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC SCHWARTZ_BOUND_POS THEN
     ASM_MESON_TAC[]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `(d:num->real->complex) 0 = h`]) THEN
  EXISTS_TAC `B0 + &3 * B1 + &3 * B2 + B3` THEN CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `u:real` THEN REWRITE_TAC[cw] THEN
  SUBGOAL_THEN `&0 < (&1 + abs u) pow 3` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ; REAL_ARITH `x * &1 / y = x / y`] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 3 * norm((h:real->complex) x) <=
      B3`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 2 * norm((h:real->complex) x) <=
      B2`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 1 * norm((h:real->complex) x) <=
      B1`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:real` o
    check (fun th -> concl th = `!x. abs x pow 0 * norm((h:real->complex) x) <=
      B0`)) THEN
  REWRITE_TAC[real_pow; REAL_MUL_LID; REAL_POW_1] THEN
  SUBGOAL_THEN `(&1 + abs u) pow 3 =
     &1 + &3 * abs u + &3 * abs u * abs u + abs u * abs u * abs u` SUBST1_TAC
       THENL
   [REWRITE_TAC[REAL_POW_2] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPEC `(h:real->complex) u` NORM_POS_LE) THEN
  REWRITE_TAC[REAL_POW_2] THEN REAL_ARITH_TAC);;

(* Concrete base test function: |carleson_phi u| <= C1 cw u.                 *)
let CARLESON_PHI_CW = prove
 (`?C1. &0 <= C1 /\ !u. norm(carleson_phi u) <= C1 * cw u`,
  MATCH_MP_TAC SCHWARTZ_CW_DOMINATION THEN
    REWRITE_TAC[CARLESON_PHI_SCHWARTZ]);;

(* M6 tent-domination (Fremlin 286Ge): |carleson_phi u| <= C1 cw1 u.  On     *)
(* [-3,3] cw1 = cw(3) (const) and phi is bounded (SCHWARTZ_BOUNDED), so take *)
(* C1 large; off [-3,3] cw1 = cw and CARLESON_PHI_CW applies.  Constant      *)
(* Ca + B/cw(3).  Feeds the (h)(vi) kernel domination gg = cw1(3 2^m .).     *)
let CARLESON_PHI_CW1 = prove
 (`?C1. &0 <= C1 /\ !u. norm(carleson_phi u) <= C1 * cw1 u`,
  MP_TAC CARLESON_PHI_CW THEN
  DISCH_THEN(X_CHOOSE_THEN `Ca:real` STRIP_ASSUME_TAC) THEN
  MP_TAC(MATCH_MP SCHWARTZ_BOUNDED CARLESON_PHI_SCHWARTZ) THEN
  DISCH_THEN(X_CHOOSE_TAC `B:real`) THEN
  EXISTS_TAC `Ca + B / cw(&3)` THEN
  SUBGOAL_THEN `&0 < cw(&3)` ASSUME_TAC THENL
   [REWRITE_TAC[CW_POS]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= B` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `norm(carleson_phi(&0))` THEN
    ASM_REWRITE_TAC[NORM_POS_LE]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_ADD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_DIV THEN ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
  X_GEN_TAC `u:real` THEN
  ASM_CASES_TAC `abs u <= &3` THENL
   [SUBGOAL_THEN `cw1 u = cw(&3)` SUBST1_TAC THENL
     [REWRITE_TAC[cw1] THEN
       MATCH_MP_TAC(REAL_ARITH `a <= b ==> min a b = a`) THEN
      MATCH_MP_TAC CW_ANTITONE THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `B:real` THEN
      ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[REAL_ADD_RDISTRIB] THEN
    ASM_SIMP_TAC[REAL_DIV_RMUL; REAL_LT_IMP_NZ] THEN
    MATCH_MP_TAC(REAL_ARITH `&0 <= a ==> B <= a + B`) THEN
    MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE];
    SUBGOAL_THEN `cw1 u = cw u` SUBST1_TAC THENL
     [REWRITE_TAC[cw1] THEN
       MATCH_MP_TAC(REAL_ARITH `b <= a ==> min a b = b`) THEN
      MATCH_MP_TAC CW_ANTITONE THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `Ca * cw u` THEN
      ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[CW_POS; REAL_LT_IMP_LE] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(REAL_ARITH `&0 <= b ==> Ca <= Ca + b`) THEN
      MATCH_MP_TAC REAL_LE_DIV THEN ASM_SIMP_TAC[REAL_LT_IMP_LE];
      MP_TAC(SPEC `u:real` CW_POS) THEN REAL_ARITH_TAC]]);;

(* SQUARED-weight base bound: |carleson_phi u| <= C1 (cw u)^2 (=             *)
(* C1/(1+|u|)^6).                                                            *)
(* Fremlin 286E(c) second min-entry.  Feeds the 286L(c-i) kernel estimate.   *)
let CARLESON_PHI_CW_SQ = prove
 (`?C1. &0 <= C1 /\ !u. norm(carleson_phi u) <= C1 * (cw u) pow 2`,
  MATCH_MP_TAC SCHWARTZ_CW_SQ_DOMINATION THEN
    REWRITE_TAC[CARLESON_PHI_SCHWARTZ]);;

(* Amplitude scaling of phi_sigma: |phi_sigma s phi x| =                     *)
(* 2^(k/2)|phi(2^k(x-x_s))|.                                                 *)
let PHISIG_NORM_PW = prove
 (`!(s:int#int#int) (phi:real->complex) x.
     norm(phi_sigma s phi x) =
     sqrt(&2 zpow (tile_k s)) * norm(phi(&2 zpow (tile_k s) * (x - tile_xmid
       s)))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[phi_sigma; phimst] THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `norm(cexp(ii * Cx(tile_ymid s) * Cx x)) = &1` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM CX_MUL; NORM_CEXP_II]; ALL_TAC] THEN
  SUBGOAL_THEN
    `abs(sqrt(&2 zpow (tile_k s))) = sqrt(&2 zpow (tile_k s))` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC SQRT_POS_LE THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_LID]);;

(* 286E(c-iii), tile form: |phi_sigma s carleson_phi x| <= C1 2^(-k/2)       *)
(* w_sigma(x).                                                               *)
let PHISIG_CW = prove
 (`?C1. &0 <= C1 /\ !(s:int#int#int) x.
     norm(phi_sigma s carleson_phi x) <= C1 * inv(sqrt(&2 zpow (tile_k s))) *
       cw_tile s x`,
  MP_TAC CARLESON_PHI_CW THEN
  DISCH_THEN(X_CHOOSE_THEN `C1:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `x:real`] THEN
  REWRITE_TAC[PHISIG_NORM_PW; cw_tile] THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `C1 * inv(sqrt(&2 zpow (tile_k s))) * &2 zpow (tile_k s) *
      cw (&2 zpow (tile_k s) * (x - tile_xmid s)) =
    sqrt(&2 zpow (tile_k s)) * (C1 * cw(&2 zpow (tile_k s) * (x - tile_xmid
      s)))`
   SUBST1_TAC THENL
   [SUBGOAL_THEN `inv(sqrt(&2 zpow (tile_k s))) * &2 zpow (tile_k s) =
                  sqrt(&2 zpow (tile_k s))` MP_TAC THENL
     [REWRITE_TAC[REAL_ARITH `!s t:real. inv s * t = t / s`] THEN
      MATCH_MP_TAC REAL_DIV_SQRT THEN
        ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
    CONV_TAC REAL_RING; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LE THEN
     ASM_SIMP_TAC[REAL_LT_IMP_LE]; ASM_REWRITE_TAC[]]);;

(* 286E(c-iii), tile form, SQUARED entry:  |phi_sigma s carleson_phi x| <=   *)
(* C1 2^(-3k/2) w_sigma(x)^2. From CARLESON_PHI_CW_SQ (base squared bound)   *)
(* via                                                                       *)
(* PHISIG_NORM_PW: norm(phi_s x) = sqrt(2^k) norm(carleson_phi(2^k(x-x_s)))  *)
(* <=                                                                        *)
(* sqrt(2^k) C1 (cw(2^k(x-x_s)))^2; and cw_tile s x = 2^k cw(2^k(x-x_s)) so  *)
(* (cw_tile)^2 = 2^{2k}(cw..)^2, giving sqrt(2^k) = inv(sqrt(2^k))^3 2^{2k}, *)
(* i.e.                                                                      *)
(* the 2^{-3k/2} coefficient.  The (c-i) kernel estimate's entry point.      *)
let PHISIG_CW_SQ = prove
 (`?C1. &0 <= C1 /\ !(s:int#int#int) x.
     norm(phi_sigma s carleson_phi x) <=
     C1 * inv(sqrt(&2 zpow (tile_k s))) pow 3 * (cw_tile s x) pow 2`,
  MP_TAC CARLESON_PHI_CW_SQ THEN
  DISCH_THEN(X_CHOOSE_THEN `C1:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `x:real`] THEN
  REWRITE_TAC[PHISIG_NORM_PW; cw_tile] THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `p = &2 zpow (tile_k s)` THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sqrt(p) * (C1 * (cw (p * (x - tile_xmid s))) pow 2)` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[SQRT_POS_LE; REAL_LT_IMP_LE];
    ALL_TAC] THEN
  ABBREV_TAC `cu = cw (p * (x - tile_xmid s))` THEN
  MATCH_MP_TAC REAL_EQ_IMP_LE THEN
  SUBGOAL_THEN `&0 < sqrt p /\ sqrt p pow 2 = p` STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[SQRT_POS_LT; SQRT_POW_2; REAL_LT_IMP_LE]; ALL_TAC] THEN
  REWRITE_TAC[REAL_POW_MUL] THEN
  MATCH_MP_TAC(REAL_FIELD
   `&0 < r /\ r pow 2 = p
    ==> r * (C1 * cu pow 2) = C1 * inv(r) pow 3 * (p pow 2 * cu pow 2)`) THEN
  ASM_REWRITE_TAC[]);;

(* 286L(f-iii) per-tile bound: |(f|phi_sigma) phi_sigma(x)| <= C1 energy mu  *)
(* I_sigma                                                                   *)
(* w_sigma(x) for sigma in P. Combines ENERGY_IP_BOUND (|(f|phi_s)| <=       *)
(* inv(sqrt 2^k)                                                             *)
(* energy) and PHISIG_CW (|phi_s(x)| <= C1 inv(sqrt 2^k) w_s(x)) by          *)
(* REAL_LE_MUL2; the                                                         *)
(* two inv(sqrt 2^k) factors multiply to inv(2^k) = mu I_sigma. This is the  *)
(* summand of                                                                *)
(* v2, whose scale-k slice sums (via 286Gd) to <= 2 C1 energy.               *)
let IP_PHI_BOUND = prove
 (`?C1. &0 <= C1 /\ !(f:real->complex) (P:(int#int#int)->bool) sigma x.
     FINITE P /\ sigma IN P
     ==> norm(carleson_ip f sigma * phi_sigma sigma carleson_phi x)
         <= C1 * energy_f f P * inv(&2 zpow (tile_k sigma)) * cw_tile sigma x`,
  X_CHOOSE_THEN
    `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PB")) PHISIG_CW THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  REWRITE_TAC[COMPLEX_NORM_MUL] THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k sigma)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < sqrt(&2 zpow (tile_k sigma))` ASSUME_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(energy_f (f:real->complex) P * inv(sqrt(&2 zpow (tile_k
    sigma)))) *
              (C1 * inv(sqrt(&2 zpow (tile_k sigma))) * cw_tile sigma x)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL2 THEN REWRITE_TAC[NORM_POS_LE] THEN
     REPEAT CONJ_TAC THENL
     [REWRITE_TAC[GSYM real_div] THEN ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
      ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
      MP_TAC(ISPECL [`f:real->complex`; `P:(int#int#int)->bool`;
        `sigma:int#int#int`]
        ENERGY_IP_BOUND) THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[]];
    SUBGOAL_THEN
     `(energy_f (f:real->complex) P * inv(sqrt(&2 zpow (tile_k sigma)))) *
      (C1 * inv(sqrt(&2 zpow (tile_k sigma))) * cw_tile sigma x) =
      C1 * energy_f f P * (inv(sqrt(&2 zpow (tile_k sigma))) * inv(sqrt(&2 zpow
        (tile_k sigma)))) *
      cw_tile sigma x` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_MUL_AC]; ALL_TAC] THEN
    SUBGOAL_THEN
     `inv(sqrt(&2 zpow (tile_k sigma))) * inv(sqrt(&2 zpow (tile_k sigma))) =
      inv(&2 zpow (tile_k sigma))` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM REAL_INV_MUL] THEN AP_TERM_TAC THEN
      REWRITE_TAC[GSYM REAL_POW_2] THEN MATCH_MP_TAC SQRT_POW_2 THEN
      ASM_SIMP_TAC[REAL_LT_IMP_LE];
      REWRITE_TAC[REAL_LE_REFL]]]);;

(* The scale-collapse identity: inv(2^{k_s}) w_s(x) = cw(2^{k_s} x - (nI_s + *)
(* 1/2)).                                                                    *)
(* (cw_tile s x = 2^{k_s} cw(2^{k_s}(x-x_s)), x_s = (nI_s+1/2) 2^{-k_s}.)    *)
(* This puts the                                                             *)
(* v2 summand onto the half-integer grid so 286Gd (CW_INTEGER_SHIFT_SUM)     *)
(* applies.                                                                  *)
let CW_TILE_SHIFT_ID = prove
 (`!(k:int) nI nJ x.
     inv(&2 zpow k) * cw_tile (k,nI,nJ) x = cw(&2 zpow k * x - (real_of_int nI
       + &1 / &2))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cw_tile; tile_k; tile_xmid; dyho_mid] THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_ASSOC] THEN
  SUBGOAL_THEN `inv(&2 zpow k) * &2 zpow k = &1` SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_MUL_LINV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_LID] THEN AP_TERM_TAC THEN
  REWRITE_TAC[REAL_ZPOW_NEG] THEN
  MP_TAC(ASSUME `&0 < &2 zpow k`) THEN CONV_TAC REAL_FIELD);;

(* 286L(f-iii): v2's scale-k slice bound. For a finite tile set A (all       *)
(* tile_k = k, and                                                           *)
(* distinct I-indices FST(SND .) -- 286L(a-i): same-scale tiles of P have    *)
(* distinct                                                                  *)
(* centres) contained in P, sum_{s in A} |(f|phi_s) phi_s(x)| <= 2 C1        *)
(* energy_f f P.                                                             *)
(* Termwise IP_PHI_BOUND (C1 energy inv(2^k) w_s), then sum inv(2^k) w_s =   *)
(* sum cw(2^k x -                                                            *)
(* (nI_s+1/2)) (CW_TILE_SHIFT_ID), reindexed over the distinct I-indices to  *)
(* CW_INTEGER_                                                               *)
(* SHIFT_SUM <= 2. This bounds Fremlin's v2 pointwise (the single collapsed  *)
(* scale k).                                                                 *)
let V2_SLICE_BOUND = prove
 (`?C1. &0 <= C1 /\ !(f:real->complex) (P:(int#int#int)->bool)
   (A:(int#int#int)->bool) k x.
     FINITE P /\ FINITE A /\ A SUBSET P /\
     (!s. s IN A ==> tile_k s = k) /\
     (!s t. s IN A /\ t IN A /\ FST(SND s) = FST(SND t) ==> s = t)
     ==> sum A (\s. norm(carleson_ip f s * phi_sigma s carleson_phi x)) <= &2 *
       C1 * energy_f f P`,
  X_CHOOSE_THEN
    `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "IPB")) IP_PHI_BOUND THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC
   [`f:real->complex`; `P:(int#int#int)->bool`; `A:(int#int#int)->bool`;
     `k:int`; `x:real`] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P` ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS]; ALL_TAC] THEN
  SUBGOAL_THEN
    `sum A (\s. inv(&2 zpow k) * cw_tile s x) <= &2` ASSUME_TAC THENL
   [SUBGOAL_THEN
     `sum A (\s. inv(&2 zpow k) * cw_tile s x) =
      sum (IMAGE (\s:int#int#int. FST(SND s)) A)
          (\n. cw((&2 zpow k * x - &1 / &2) - real_of_int n))`
     SUBST1_TAC THENL
     [SUBGOAL_THEN
       `sum A (\s. inv(&2 zpow k) * cw_tile s x) =
        sum A (\s. cw(&2 zpow k * x - (real_of_int(FST(SND s)) + &1 / &2)))`
       SUBST1_TAC THENL
       [MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
         REWRITE_TAC[] THEN
        SUBGOAL_THEN `k = tile_k (s:int#int#int)` SUBST1_TAC THENL
         [CONV_TAC SYM_CONV THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
        SPEC_TAC(`s:int#int#int`,`s:int#int#int`) THEN
          REWRITE_TAC[FORALL_PAIR_THM] THEN
        REWRITE_TAC[tile_k; CW_TILE_SHIFT_ID];
        ALL_TAC] THEN
      CONV_TAC SYM_CONV THEN
      MP_TAC(ISPECL [`\s:int#int#int. FST(SND s)`;
                     `\n:int. cw((&2 zpow k * x - &1 / &2) - real_of_int n)`;
                     `A:(int#int#int)->bool`] SUM_IMAGE) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
         FIRST_X_ASSUM MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF] THEN
        MATCH_MP_TAC SUM_EQ THEN REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN
        AP_TERM_TAC THEN REAL_ARITH_TAC];
      MATCH_MP_TAC CW_INTEGER_SHIFT_SUM THEN
      MATCH_MP_TAC FINITE_IMAGE THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum A (\s. (C1 * energy_f (f:real->complex) P) * (inv(&2 zpow k)
    * cw_tile s x))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN
      `(C1 * energy_f (f:real->complex) P) * (inv(&2 zpow k) * cw_tile s x) =
                  C1 * energy_f f P * inv(&2 zpow k) * cw_tile s x` SUBST1_TAC
                    THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `k = tile_k (s:int#int#int)` SUBST1_TAC THENL
     [CONV_TAC SYM_CONV THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
    USE_THEN "IPB" (MP_TAC o SPECL
      [`f:real->complex`; `P:(int#int#int)->bool`; `s:int#int#int`;
        `x:real`]) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[SUM_LMUL] THEN
  SUBGOAL_THEN
    `&2 * C1 * energy_f (f:real->complex) P = (C1 * energy_f f P) * &2`
    SUBST1_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[];
    GEN_REWRITE_TAC LAND_CONV [GSYM SUM_LMUL] THEN ASM_REWRITE_TAC[]]);;

(* 286L(c-i) SINGLE-PAIR KERNEL ESTIMATE (the mass half). On a set S         *)
(* contained                                                                 *)
(* in E cap h^-1[J_sigma], with the tile weight bounded by Mw >= 0 there,    *)
(* the                                                                       *)
(* integral of |phi_sigma| is <= C1 2^{-3k/2} Mw mass_Eh(P). Chains the four *)
(* base                                                                      *)
(* bricks: PHISIG_CW_SQ (|phi_s| <= C1 2^{-3k/2} w_s^2, pointwise, so        *)
(* int|phi_s|                                                                *)
(* <= C1 2^{-3k/2} int w_s^2), CWTILE_SQ_INT_LE (int_S w_s^2 <= Mw int_S     *)
(* w_s),                                                                     *)
(* REAL_INTEGRAL_SUBSET_LE (int_S w_s <= int_{E cap h^-1[J_s]} w_s, since S  *)
(* is a                                                                      *)
(* subset and w_s > 0), MASS_TERM_LE (that <= mass_Eh). Mw becomes sup_K     *)
(* w_sigma                                                                   *)
(* = 2^{k} w(2^{k} rho(x_s,K)) at the alpha0/alpha1 call site (the geometry  *)
(* step).                                                                    *)
let CARLESON_KERNEL_CI = prove
 (`?C1. &0 <= C1 /\ !(sigma:int#int#int) S E h (P:(int#int#int)->bool) Mw.
    sigma IN P /\ &0 <= Mw /\
    S SUBSET {x | x IN E /\ h x IN tile_J sigma} /\
    (!x. x IN S ==> cw_tile sigma x <= Mw) /\
    (\x. norm(phi_sigma sigma carleson_phi x)) real_integrable_on S /\
    (\x. (cw_tile sigma x) pow 2) real_integrable_on S /\
    cw_tile sigma real_integrable_on S /\
    (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
    ==> real_integral S (\x. norm(phi_sigma sigma carleson_phi x))
        <= C1 * inv(sqrt(&2 zpow (tile_k sigma))) pow 3 * Mw * mass_Eh E h P`,
  MP_TAC PHISIG_CW_SQ THEN
  DISCH_THEN(X_CHOOSE_THEN `C1:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `cc = C1 * inv(sqrt(&2 zpow (tile_k (sigma:int#int#int)))) pow 3`
    THEN
  SUBGOAL_THEN `&0 <= cc` ASSUME_TAC THENL
   [EXPAND_TAC "cc" THEN MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_POW_LE THEN REWRITE_TAC[REAL_LE_INV_EQ] THEN
    MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
    MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `C1 * inv(sqrt(&2 zpow (tile_k (sigma:int#int#int)))) pow 3 * Mw * mass_Eh
      E h P =
     cc * (Mw * mass_Eh E h P)`
    SUBST1_TAC THENL [EXPAND_TAC "cc" THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `cc * real_integral S (\x. (cw_tile (sigma:int#int#int) x) pow 2)`
    THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
      `cc * real_integral S (\x. (cw_tile (sigma:int#int#int) x) pow 2) =
       real_integral S (\x. cc * (cw_tile sigma x) pow 2)`
      SUBST1_TAC THENL
     [MATCH_MP_TAC(GSYM REAL_INTEGRAL_LMUL) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_INTEGRAL_LE THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `x:real` THEN DISCH_TAC THEN EXPAND_TAC "cc" THEN
      REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `Mw * real_integral S (cw_tile (sigma:int#int#int))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CWTILE_SQ_INT_LE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral {x | x IN E /\ h x IN tile_J (sigma:int#int#int)}
    (cw_tile sigma)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN ASM_REWRITE_TAC[] THEN
    REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
      REWRITE_TAC[CW_TILE_POS];
    MATCH_MP_TAC MASS_TERM_LE THEN ASM_REWRITE_TAC[]]);;

(* 286L(c-i) kernel estimate in the DISTANCE form.  Instantiating CARLESON_  *)
(* KERNEL_CI's abstract Mw with the geometric bound Mw = 2^{k} cw(2^{k} rho) *)
(* (CWTILE_DIST_BOUND, valid when every x in S is at distance >= rho from    *)
(* x_sigma)                                                                  *)
(* and simplifying inv(sqrt(2^k))^3 * 2^k = inv(sqrt(2^k)) gives Fremlin's   *)
(* exact                                                                     *)
(* factor 2 of (c-i): int_S |phi_sigma| <= C1 2^{-k/2} w(2^{k} rho)          *)
(* mass_Eh(P).                                                               *)
let CARLESON_KERNEL_RHO = prove
 (`?C1. &0 <= C1 /\ !(sigma:int#int#int) S E h (P:(int#int#int)->bool) rho.
    sigma IN P /\ &0 <= rho /\
    S SUBSET {x | x IN E /\ h x IN tile_J sigma} /\
    (!x. x IN S ==> rho <= abs(x - tile_xmid sigma)) /\
    (\x. norm(phi_sigma sigma carleson_phi x)) real_integrable_on S /\
    (\x. (cw_tile sigma x) pow 2) real_integrable_on S /\
    cw_tile sigma real_integrable_on S /\
    (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
    ==> real_integral S (\x. norm(phi_sigma sigma carleson_phi x))
        <= C1 * inv(sqrt(&2 zpow (tile_k sigma))) *
           cw(&2 zpow (tile_k sigma) * rho) * mass_Eh E h P`,
  MP_TAC CARLESON_KERNEL_CI THEN
  DISCH_THEN(X_CHOOSE_THEN `C1:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k (sigma:int#int#int))` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `C1 * inv(sqrt(&2 zpow (tile_k (sigma:int#int#int)))) pow 3 *
              (&2 zpow (tile_k sigma) * cw(&2 zpow (tile_k sigma) * rho)) *
              mass_Eh E h P` THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN
      ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
      REWRITE_TAC[CW_POS];
      X_GEN_TAC `x:real` THEN DISCH_TAC THEN
      MATCH_MP_TAC CWTILE_DIST_BOUND THEN ASM_SIMP_TAC[]];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    SUBGOAL_THEN
      `sqrt(&2 zpow (tile_k (sigma:int#int#int))) pow 2 =
       &2 zpow (tile_k sigma) /\
                  &0 < sqrt(&2 zpow (tile_k sigma))` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC SQRT_POW_2 THEN ASM_SIMP_TAC[REAL_LT_IMP_LE];
        MATCH_MP_TAC SQRT_POS_LT THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    MATCH_MP_TAC(REAL_FIELD
     `&0 < r /\ r pow 2 = p
      ==> C1 * inv(r) pow 3 * (p * c) * m = C1 * inv(r) * c * m`) THEN
    ASM_REWRITE_TAC[]]);;

(* 286L(c-i) bridge: the norm of the LOCALIZED complex integral of phi_sigma *)
(* over                                                                      *)
(* a set S is <= the real integral of |phi_sigma| there. Connects the        *)
(* lproduct-                                                                 *)
(* style vector integral (integral (IMAGE lift S) (\z. phi_sigma .. (drop    *)
(* z))) --                                                                   *)
(* which is how the alpha_{sigma K} term int_{E cap h^-1[J_s^r] cap K}       *)
(* phi_sigma                                                                 *)
(* appears -- to the real_integral that CARLESON_KERNEL_RHO bounds.  Via the *)
(* library ABSOLUTELY_INTEGRABLE_LE (norm(int f) <= drop(int |f|)) +         *)
(* REAL_INTEGRAL.                                                            *)
let NORM_PHISIG_LOCAL_LE = prove
 (`!(sigma:int#int#int) S.
     (\x. norm(phi_sigma sigma carleson_phi x)) real_integrable_on S /\
     (\z. phi_sigma sigma carleson_phi (drop z)) absolutely_integrable_on
       (IMAGE lift S)
     ==> norm(integral (IMAGE lift S) (\z. phi_sigma sigma carleson_phi (drop
       z)))
         <= real_integral S (\x. norm(phi_sigma sigma carleson_phi x))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP REAL_INTEGRAL) THEN
  DISCH_THEN(fun th -> GEN_REWRITE_TAC RAND_CONV [th]) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `drop(integral (IMAGE lift S)
     (\z. lift(norm(phi_sigma sigma carleson_phi (drop z)))))` THEN
  CONJ_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_LE) THEN
    REWRITE_TAC[];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[o_DEF]]);;

(* 286L(c-i) SINGLE-PAIR ESTIMATE (Fremlin's exact per-pair bound). For the  *)
(* tile                                                                      *)
(* localized integral alpha_{sigma K} = (f|phi_sigma) * int_{E cap           *)
(* h^-1[J_s^r]                                                               *)
(* cap K} phi_sigma (here S = that localized set, so the integral is over    *)
(* IMAGE                                                                     *)
(* lift S), with every point of S at distance >= rho from x_sigma:           *)
(*   norm(alpha_{sigma K}) <= C1 2^{-k} w(2^{k} rho) energy_f(P) mass_Eh(P). *)
(* Assembles the whole (c-i) chain: COMPLEX_NORM_MUL splits the product;     *)
(* COEFF_LE_ENERGY_HALF bounds the coefficient by 2^{-k/2} energy;           *)
(* NORM_PHISIG_                                                              *)
(* LOCAL_LE + CARLESON_KERNEL_RHO bound the localized integral by C1         *)
(* 2^{-k/2}                                                                  *)
(* w(2^k rho) mass; REAL_LE_MUL2 multiplies, and inv(sqrt(2^k))^2 = inv(2^k) *)
(* via                                                                       *)
(* REAL_FIELD gives the 2^{-k}. This is the atom the alpha0/alpha1 sums add  *)
(* up.                                                                       *)
let CARLESON_ALPHA_PAIR = prove
 (`?C1. &0 <= C1 /\ !(f:real->complex) (sigma:int#int#int) S E h
   (P:(int#int#int)->bool) rho.
    FINITE P /\ sigma IN P /\ &0 <= rho /\
    S SUBSET {x | x IN E /\ h x IN tile_J sigma} /\
    (!x. x IN S ==> rho <= abs(x - tile_xmid sigma)) /\
    (\x. norm(phi_sigma sigma carleson_phi x)) real_integrable_on S /\
    (\x. (cw_tile sigma x) pow 2) real_integrable_on S /\
    cw_tile sigma real_integrable_on S /\
    (\z. phi_sigma sigma carleson_phi (drop z)) absolutely_integrable_on (IMAGE
      lift S) /\
    (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
    ==> norm(carleson_ip f sigma *
             integral (IMAGE lift S) (\z. phi_sigma sigma carleson_phi (drop
               z)))
        <= C1 * inv(&2 zpow (tile_k sigma)) * cw(&2 zpow (tile_k sigma) * rho)
          *
           energy_f f P * mass_Eh E h P`,
  MP_TAC CARLESON_KERNEL_RHO THEN
  DISCH_THEN(X_CHOOSE_THEN `C1:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN REWRITE_TAC[COMPLEX_NORM_MUL] THEN
  SUBGOAL_THEN `&0 < &2 zpow (tile_k (sigma:int#int#int))` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < sqrt(&2 zpow (tile_k (sigma:int#int#int))) /\
                sqrt(&2 zpow (tile_k sigma)) pow 2 = &2 zpow (tile_k sigma)`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LT THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC SQRT_POW_2 THEN ASM_SIMP_TAC[REAL_LT_IMP_LE]]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(inv(sqrt(&2 zpow (tile_k (sigma:int#int#int)))) * energy_f f P)
    *
              (C1 * inv(sqrt(&2 zpow (tile_k sigma))) *
               cw(&2 zpow (tile_k sigma) * rho) * mass_Eh E h P)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL2 THEN REWRITE_TAC[NORM_POS_LE] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC COEFF_LE_ENERGY_HALF THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `real_integral S (\x. norm(phi_sigma sigma carleson_phi x))`
        THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC NORM_PHISIG_LOCAL_LE THEN ASM_REWRITE_TAC[];
        FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    MATCH_MP_TAC(REAL_FIELD
     `&0 < r /\ r pow 2 = p
      ==> (inv(r) * g) * (C1 * inv(r) * c * m) = C1 * inv(p) * c * g * m`) THEN
    ASM_REWRITE_TAC[]]);;

(* 286L alpha0/alpha1 PER-TILE EDGE-FORM BOUND. For a scale-k tile (k,nI,nJ) *)
(* in P                                                                      *)
(* whose spatial index nI lies OUTSIDE the cover cell's index-span [q, q+M)  *)
(* (guard                                                                    *)
(* q+M<=nI \/ nI<=q-1), and a localized set S contained in E cap             *)
(* h^-1[J_sigma] AND                                                         *)
(* in the cover-cell interval [q 2^{-k}, (q+M) 2^{-k}):                      *)
(*   norm((f|phi_sigma) int_{IMAGE lift S} phi_sigma)                        *)
(*     <= C1 2^{-k} cw(&(nearest-edge offset) + 1/2) energy_f(P) mass_Eh(P). *)
(* Specializes CARLESON_ALPHA_PAIR at rho = (&edgeoff + 1/2) 2^{-k}:         *)
(* TILE_DIST_TO_                                                             *)
(* CELL supplies rho <= dist(x, x_sigma) for x in S; 2^k rho = &edgeoff+1/2  *)
(* folds                                                                     *)
(* cw(2^k rho) = cw(&edgeoff+1/2). This is the per-tile hypothesis of        *)
(* ALPHA_SCALE_                                                              *)
(* BOUND_ABSTRACT (with f a = the alpha norm, g a = edgeoff, B = C1 2^{-k}   *)
(* energy mass).                                                             *)
let CARLESON_ALPHA_EDGE = prove
 (`?C1. &0 <= C1 /\ !(f:real->complex) (k:int) (nI:int) (nJ:int) S E h
   (P:(int#int#int)->bool) q M.
    FINITE P /\ (k,nI,nJ) IN P /\ (q + M <= nI \/ nI <= q - &1) /\
    S SUBSET {x | x IN E /\ h x IN tile_J (k,nI,nJ)} /\
    S SUBSET {x | real_of_int q * &2 zpow (--k) <= x /\ x < real_of_int (q + M)
      * &2 zpow (--k)} /\
    (\x. norm(phi_sigma (k,nI,nJ) carleson_phi x)) real_integrable_on S /\
    (\x. (cw_tile (k,nI,nJ) x) pow 2) real_integrable_on S /\
    cw_tile (k,nI,nJ) real_integrable_on S /\
    (\z. phi_sigma (k,nI,nJ) carleson_phi (drop z)) absolutely_integrable_on
      (IMAGE lift S) /\
    (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
    ==> norm(carleson_ip f (k,nI,nJ) *
             integral (IMAGE lift S) (\z. phi_sigma (k,nI,nJ) carleson_phi
               (drop z)))
        <= C1 * inv(&2 zpow k) *
           cw(&(num_of_int(if q + M <= nI then nI - (q + M) else (q - &1) -
             nI)) + &1 / &2) *
           energy_f f P * mass_Eh E h P`,
  MP_TAC CARLESON_ALPHA_PAIR THEN
  DISCH_THEN(X_CHOOSE_THEN
    `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PAIR"))) THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC
   [`f:real->complex`;`k:int`;`nI:int`;`nJ:int`;`S:real->bool`;`E:real->bool`;
    `h:real->real`;`P:(int#int#int)->bool`;`q:int`;`M:int`] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  ABBREV_TAC `eo = num_of_int(if q + M <= nI then nI - (q + M) else (q - &1) -
    nI)` THEN
  USE_THEN "PAIR" (fun th -> MP_TAC(SPECL
    [`f:real->complex`; `(k,nI,nJ):int#int#int`; `S:real->bool`;
      `E:real->bool`;
     `h:real->real`; `P:(int#int#int)->bool`;
       `(&eo + &1 / &2) * inv(&2 zpow k)`] th)) THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[tile_k] THEN
  SUBGOAL_THEN `&2 zpow k * (&eo + &1 / &2) * inv(&2 zpow k) = &eo + &1 / &2`
    (fun th -> REWRITE_TAC[th]) THENL
   [MATCH_MP_TAC(REAL_FIELD `&0 < p ==> p * (e * inv p) = e`) THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; REWRITE_TAC[REAL_LE_INV_EQ] THEN
       ASM_SIMP_TAC[REAL_LT_IMP_LE]];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN REWRITE_TAC[tile_xmid] THEN
    SUBGOAL_THEN
      `&0 <= (if q + M <= nI then nI - (q + M) else (q - &1) - nI):int`
      ASSUME_TAC THENL
     [FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th -> is_disj(concl th))) THEN
      COND_CASES_TAC THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
      `&eo = real_of_int(if q + M <= nI then nI - (q + M) else (q - &1) - nI)`
      SUBST1_TAC THENL
     [EXPAND_TAC "eo" THEN
       ASM_MESON_TAC[INT_OF_NUM_OF_INT; int_of_num_th]; ALL_TAC] THEN
    MP_TAC(ISPECL [`k:int`; `q:int`; `M:int`; `nI:int`;
      `x:real`] TILE_DIST_TO_CELL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `S SUBSET {x | real_of_int q * &2 zpow (--k) <= x /\
                                 x < real_of_int (q + M) * &2 zpow (--k)}` THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
      DISCH_THEN(MP_TAC o SPEC `x:real`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[GSYM real_div] THEN ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN
    REAL_ARITH_TAC]);;

(* Tile-INDEXED reformulation of CARLESON_ALPHA_EDGE: the same per-tile edge *)
(* bound stated with a single tile index s (so tile_k s appears in the       *)
(* exponent                                                                  *)
(* and FST(SND s) is the tile's I-index), instead of the destructured        *)
(* (k,nI,nJ).                                                                *)
(* Proved by destructuring s ONCE at the top via FORALL_PAIR_THM and         *)
(* applying                                                                  *)
(* CARLESON_ALPHA_EDGE. This is the convenient form for summing over a tree. *)
let CARLESON_ALPHA_EDGE_TILE = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) (s:int#int#int) S E h (P:(int#int#int)->bool) q M.
    FINITE P /\ s IN P /\ (q + M <= FST(SND s) \/ FST(SND s) <= q - &1) /\
    S SUBSET {x | x IN E /\ h x IN tile_J s} /\
    S SUBSET {x | real_of_int q * &2 zpow (--(tile_k s)) <= x /\
                  x < real_of_int (q + M) * &2 zpow (--(tile_k s))} /\
    (\x. norm(phi_sigma s carleson_phi x)) real_integrable_on S /\
    (\x. (cw_tile s x) pow 2) real_integrable_on S /\
    cw_tile s real_integrable_on S /\
    (\z. phi_sigma s carleson_phi (drop z)) absolutely_integrable_on (IMAGE
      lift S) /\
    (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
    ==> norm(carleson_ip f s *
             integral (IMAGE lift S) (\z. phi_sigma s carleson_phi (drop z)))
        <= C1 * inv(&2 zpow (tile_k s)) *
           cw(&(num_of_int(if q + M <= FST(SND s) then FST(SND s) - (q + M)
                           else (q - &1) - FST(SND s))) + &1 / &2) *
           energy_f f P * mass_Eh E h P`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "EDGE"))
    CARLESON_ALPHA_EDGE THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[FORALL_PAIR_THM; tile_k; tile_J; FST; SND] THEN
  MAP_EVERY X_GEN_TAC
   [`f:real->complex`; `k:int`; `nI:int`; `nJ:int`;
    `S:real->bool`; `E:real->bool`; `h:real->real`; `P:(int#int#int)->bool`;
    `q:int`; `M:int`] THEN
  STRIP_TAC THEN
  USE_THEN "EDGE" (MP_TAC o SPECL
   [`f:real->complex`; `k:int`; `nI:int`; `nJ:int`; `S:real->bool`;
    `E:real->bool`; `h:real->real`; `P:(int#int#int)->bool`; `q:int`;
      `M:int`]) THEN
  REWRITE_TAC[tile_J] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[FORALL_PAIR_THM; tile_J] THEN ASM_REWRITE_TAC[]);;

(* 286L alpha0/alpha1 PER-SCALE bound (the concrete tile-counting assembly). *)
(* For a same-scale-k tree subset A of P whose tiles all lie OUTSIDE the     *)
(* cover                                                                     *)
(* cell's index-span [q,q+M) (nI >= q+M or nI <= q-1), the sum over A of the *)
(* per-tile alpha norms is bounded by C1 2^{-k} energy mass. The             *)
(* nearest-edge                                                              *)
(* offset map is <= 2-to-1 (TILE_OFFSET_FIBER_CARD), the per-tile factor is  *)
(* the                                                                       *)
(* edge bound (CARLESON_ALPHA_EDGE_TILE), and the cw-tail collapses to <= 1  *)
(* via                                                                       *)
(* ALPHA_SCALE_BOUND_ABSTRACT at N = 0 (so the tail sum 1/(1+&0)^2 = 1). The *)
(* single 2^{-k} factor is what drives the geometric series over k in        *)
(* alpha0/1.                                                                 *)
let CARLESON_ALPHA_SCALE = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) (k:int) E h (P:(int#int#int)->bool) A u q M
    (Sc:(int#int#int)->real->bool).
      FINITE P /\ ~(P = {}) /\ FINITE A /\ A SUBSET P /\ &0 <= M /\
      (!s. s IN A ==> tile_k s = k /\ tile_le s u) /\
      (!s. s IN A ==> (q + M <= FST(SND s) \/ FST(SND s) <= q - &1)) /\
      (!s. s IN A ==>
        (Sc s) SUBSET {x | x IN E /\ h x IN tile_J s} /\
        (Sc s) SUBSET {x | real_of_int q * &2 zpow (--k) <= x /\
                           x < real_of_int (q + M) * &2 zpow (--k)} /\
        (\x. norm(phi_sigma s carleson_phi x)) real_integrable_on (Sc s) /\
        (\x. (cw_tile s x) pow 2) real_integrable_on (Sc s) /\
        cw_tile s real_integrable_on (Sc s) /\
        (\z. phi_sigma s carleson_phi (drop z)) absolutely_integrable_on (IMAGE
          lift (Sc s))) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum A (\s. norm(carleson_ip f s *
                          integral (IMAGE lift (Sc s))
                                   (\z. phi_sigma s carleson_phi (drop z))))
          <= C1 * inv(&2 zpow k) * energy_f f P * mass_Eh E h P`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "TILE"))
    CARLESON_ALPHA_EDGE_TILE THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P /\ &0 <= mass_Eh E h P`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS] THEN MATCH_MP_TAC MASS_EH_POS THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\s. num_of_int(if q + M <= FST(SND s) then FST(SND s) - (q +
    M)
                                 else (q - &1) - FST(SND(s:int#int#int)))`;
                 `A:(int#int#int)->bool`] UPPER_BOUND_FINITE_SET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `Mup:num`) THEN
  MP_TAC(ISPECL
   [`A:(int#int#int)->bool`;
    `\s. norm(carleson_ip f s *
              integral (IMAGE lift ((Sc:(int#int#int)->real->bool) s))
                       (\z. phi_sigma s carleson_phi (drop z)))`;
    `\s. num_of_int(if q + M <= FST(SND s) then FST(SND s) - (q + M)
                    else (q - &1) - FST(SND(s:int#int#int)))`;
    `C1 * inv(&2 zpow k) * energy_f (f:real->complex) P * mass_Eh E h P`;
    `0`;
    `Mup:num`] ALPHA_SCALE_BOUND_ABSTRACT) THEN
  REWRITE_TAC[REAL_ARITH `(&1 + &0) pow 2 = &1`; REAL_DIV_1; REAL_MUL_RID] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [REPEAT(MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC) THEN
    ASM_REWRITE_TAC[REAL_LE_INV_EQ] THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
      REAL_ARITH_TAC;
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    SUBGOAL_THEN `tile_k (s:int#int#int) = k` ASSUME_TAC THENL
     [ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(C1 * inv(&2 zpow k) * energy_f (f:real->complex) P * mass_Eh E h P) *
      cw(&(num_of_int(if q + M <= FST(SND(s:int#int#int)) then FST(SND s) - (q
        + M)
                      else (q - &1) - FST(SND s))) + &1 / &2) =
      C1 * inv(&2 zpow k) *
      cw(&(num_of_int(if q + M <= FST(SND s) then FST(SND s) - (q + M)
                      else (q - &1) - FST(SND s))) + &1 / &2) *
      energy_f f P * mass_Eh E h P`
     SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    USE_THEN
      "TILE" (fun th -> MATCH_MP_TAC(REWRITE_RULE[ASSUME `tile_k
      (s:int#int#int) = k`]
      (SPECL [`f:real->complex`; `s:int#int#int`;
        `(Sc:(int#int#int)->real->bool) s`;
              `E:real->bool`; `h:real->real`; `P:(int#int#int)->bool`; `q:int`;
                `M:int`] th))) THEN
    ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
    CONJ_TAC THENL [ARITH_TAC; ASM_SIMP_TAC[]];
    GEN_TAC THEN MATCH_MP_TAC TILE_OFFSET_FIBER_CARD THEN
    MAP_EVERY EXISTS_TAC [`k:int`; `u:int#int#int`] THEN ASM_REWRITE_TAC[]]);;

(* 286L alpha1 TIGHT per-scale bound. Same as CARLESON_ALPHA_SCALE but with  *)
(* an                                                                        *)
(* OFFSET LOWER BOUND N <= edgeoff(s) for every tile s in A (in 286L: N =    *)
(* 2^{k-l_K}                                                                 *)
(* because I_sigma NOT-SUBSET K* puts sigma at scaled distance >= mu K =     *)
(* 2^{k-l}                                                                   *)
(* from the cover cell), yielding the (1+&N)^{-2} DECAY factor. This factor  *)
(* is                                                                        *)
(* ESSENTIAL for alpha1: alpha1 sums over infinitely many coarse levels l <  *)
(* k_tau,                                                                    *)
(* and Fremlin's 2^{-k}(1+2^{k-l})^{-2} <= 2^{-3k} 2^{2l} decay (from THIS   *)
(* lemma at                                                                  *)
(* N=2^{k-l}) is what makes the sum over l converge. The loose N=0           *)
(* CARLESON_ALPHA_                                                           *)
(* SCALE (no decay) DIVERGES for alpha1. Proof: REAL_LE_TRANS through        *)
(* ALPHA_SCALE_                                                              *)
(* BOUND_ABSTRACT at general N (= B/(1+&N)^2), the extra range-lower-bound   *)
(* N<=g s                                                                    *)
(* supplied by the new hypothesis; then reassociate.                         *)
let CARLESON_ALPHA_SCALE_TIGHT = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) (k:int) E h (P:(int#int#int)->bool) A u q M N
    (Sc:(int#int#int)->real->bool).
      FINITE P /\ ~(P = {}) /\ FINITE A /\ A SUBSET P /\ &0 <= M /\
      (!s. s IN A ==> tile_k s = k /\ tile_le s u) /\
      (!s. s IN A ==> (q + M <= FST(SND s) \/ FST(SND s) <= q - &1)) /\
      (!s. s IN A ==> N <= num_of_int(if q + M <= FST(SND s) then FST(SND s) -
        (q + M)
                                      else (q - &1) - FST(SND s))) /\
      (!s. s IN A ==>
        (Sc s) SUBSET {x | x IN E /\ h x IN tile_J s} /\
        (Sc s) SUBSET {x | real_of_int q * &2 zpow (--k) <= x /\
                           x < real_of_int (q + M) * &2 zpow (--k)} /\
        (\x. norm(phi_sigma s carleson_phi x)) real_integrable_on (Sc s) /\
        (\x. (cw_tile s x) pow 2) real_integrable_on (Sc s) /\
        cw_tile s real_integrable_on (Sc s) /\
        (\z. phi_sigma s carleson_phi (drop z)) absolutely_integrable_on (IMAGE
          lift (Sc s))) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum A (\s. norm(carleson_ip f s *
                          integral (IMAGE lift (Sc s))
                                   (\z. phi_sigma s carleson_phi (drop z))))
          <= C1 * inv(&2 zpow k) * inv((&1 + &N) pow 2) * energy_f f P *
            mass_Eh E h P`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "TILE"))
    CARLESON_ALPHA_EDGE_TILE THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P /\ &0 <= mass_Eh E h P`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS] THEN MATCH_MP_TAC MASS_EH_POS THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\s. num_of_int(if q + M <= FST(SND s) then FST(SND s) - (q +
    M)
                                 else (q - &1) - FST(SND(s:int#int#int)))`;
                 `A:(int#int#int)->bool`] UPPER_BOUND_FINITE_SET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `Mup:num`) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(C1 * inv(&2 zpow k) * energy_f (f:real->complex) P * mass_Eh E h
    P) *
              &1 / (&1 + &N) pow 2` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`A:(int#int#int)->bool`;
      `\s. norm(carleson_ip f s *
                integral (IMAGE lift ((Sc:(int#int#int)->real->bool) s))
                         (\z. phi_sigma s carleson_phi (drop z)))`;
      `\s. num_of_int(if q + M <= FST(SND s) then FST(SND s) - (q + M)
                      else (q - &1) - FST(SND(s:int#int#int)))`;
      `C1 * inv(&2 zpow k) * energy_f (f:real->complex) P * mass_Eh E h P`;
      `N:num`;
      `Mup:num`] ALPHA_SCALE_BOUND_ABSTRACT) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC) THEN
      ASM_REWRITE_TAC[REAL_LE_INV_EQ] THEN
      MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
        REAL_ARITH_TAC;
      X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
      SUBGOAL_THEN `tile_k (s:int#int#int) = k` ASSUME_TAC THENL
       [ASM_SIMP_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `(C1 * inv(&2 zpow k) * energy_f (f:real->complex) P * mass_Eh E h P) *
        cw(&(num_of_int(if q + M <= FST(SND(s:int#int#int)) then FST(SND s) -
          (q + M)
                        else (q - &1) - FST(SND s))) + &1 / &2) =
        C1 * inv(&2 zpow k) *
        cw(&(num_of_int(if q + M <= FST(SND s) then FST(SND s) - (q + M)
                        else (q - &1) - FST(SND s))) + &1 / &2) *
        energy_f f P * mass_Eh E h P`
       SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
      USE_THEN
        "TILE" (fun th -> MATCH_MP_TAC(REWRITE_RULE[ASSUME `tile_k
        (s:int#int#int) = k`]
        (SPECL [`f:real->complex`; `s:int#int#int`;
          `(Sc:(int#int#int)->real->bool) s`;
                `E:real->bool`; `h:real->real`; `P:(int#int#int)->bool`;
                  `q:int`; `M:int`] th))) THEN
      ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
      X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
      CONJ_TAC THENL [ASM_SIMP_TAC[]; ASM_SIMP_TAC[]];
      GEN_TAC THEN MATCH_MP_TAC TILE_OFFSET_FIBER_CARD THEN
      MAP_EVERY EXISTS_TAC [`k:int`; `u:int#int#int`] THEN ASM_REWRITE_TAC[]];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN REWRITE_TAC[real_div; REAL_MUL_LID] THEN
    REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* 286G(d) pointwise core: the shifted weight is <= 8 w(beta) on a           *)
(* half-line.                                                                *)
(* (The full self-convolution INT w(a x+b) w(x) dx <= C2 w(b) then splits    *)
(* the                                                                       *)
(* integral at x = -(1+b)/2a using this bound on the right piece.)           *)
(* ------------------------------------------------------------------------- *)

(* If (1+b)/2 <= 1+|y| (b>=0), then w(y) <= 8 w(b).  w(y)=1/(1+|y|)^3, and   *)
(* ((1+b)/2)^3 = (1+b)^3/8, so 8 w(b) = 1/((1+b)/2)^3 >= 1/(1+|y|)^3.        *)
let CW_LE_8 = prove
 (`!y b. &0 <= b /\ (&1 + b) / &2 <= &1 + abs y ==> cw y <= &8 * cw b`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cw] THEN
  SUBGOAL_THEN `abs b = b` SUBST1_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &1 + abs y /\ &0 < &1 + b` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MP_TAC(ISPEC `y:real` REAL_ABS_POS) THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `&8 * &1 / (&1 + b) pow 3 = &1 / ((&1 + b)/ &2) pow 3` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_POW_DIV] THEN
    SUBGOAL_THEN `~((&1 + b) pow 3 = &0)` MP_TAC THENL
     [MATCH_MP_TAC REAL_POW_NZ THEN
       ASM_REAL_ARITH_TAC; CONV_TAC REAL_FIELD]; ALL_TAC] THEN
  REWRITE_TAC[REAL_ARITH `&1 / x = inv x`] THEN MATCH_MP_TAC REAL_LE_INV2 THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_POW_LE2 THEN ASM_REAL_ARITH_TAC]);;

(* 286G(d)(ii) pointwise: 0<a<=1, b>=0, x >= -(1+b)/(2a) ==> w(a x+b) <= 8   *)
(* w(b).                                                                     *)
let WEIGHT_SHIFT_BOUND = prove
 (`!a b x. &0 < a /\ a <= &1 /\ &0 <= b /\ --((&1 + b) / (&2 * a)) <= x
     ==> cw(a * x + b) <= &8 * cw b`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CW_LE_8 THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `--((&1 + b) / &2) <= a * x` ASSUME_TAC THENL
   [SUBGOAL_THEN `a * (--((&1 + b) / (&2 * a))) <= a * x` MP_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      SUBGOAL_THEN
        `a * (--((&1 + b) / (&2 * a))) = --((&1 + b) / &2)` SUBST1_TAC THENL
       [SUBGOAL_THEN `~(a = &0)` MP_TAC THENL
         [ASM_REAL_ARITH_TAC; CONV_TAC REAL_FIELD];
        REAL_ARITH_TAC]]; ALL_TAC] THEN
  SUBGOAL_THEN `a * x + b <= abs(a * x + b)` MP_TAC THENL
   [REWRITE_TAC[REAL_ABS_LE]; ASM_REAL_ARITH_TAC]);;

(* Affine-image integral of the weight:  INT_R w(a x + b) dx = 1/a  (a > 0). *)
(* Change of variables from CW_FULL via HAS_REAL_INTEGRAL_AFFINITY_UNIV;     *)
(* this                                                                      *)
(* is the "INT w(a x+b) = 1/a" step used in the 286G(d) convolution          *)
(* estimate.                                                                 *)
let CW_AFFINE_INTEGRAL = prove
 (`!a b. &0 < a ==> ((\x. cw(a * x + b)) has_real_integral (inv a)) (:real)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`cw`; `&1`; `a:real`;
    `b:real`] HAS_REAL_INTEGRAL_AFFINITY_UNIV) THEN
  ASM_SIMP_TAC[CW_FULL; REAL_LT_IMP_NZ; REAL_MUL_RID] THEN
  SUBGOAL_THEN `abs a = a` SUBST1_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286G(d)(i) left-piece scalar bound:  (1/a) w((1+b)/(2a)) <= 8 w(b).       *)
(* (In the convolution's left piece, INT_{-inf}^{-gamma} w(x)w(ax+b) <=      *)
(*  w(gamma) INT w(ax+b) = w(gamma)/a = (1/a) w((1+b)/2a) <= 8 w(b).)        *)
(* ------------------------------------------------------------------------- *)

(* Polynomial core: d(1+b)^2 <= 4(1+d)^3 when (1+b)/2 <= d (so               *)
(* (1+b)^2<=4d^2,                                                            *)
(* d(1+b)^2 <= 4d^3 <= 4(1+d)^3).                                            *)
let CW_POLY_CORE = prove
 (`!d b. &0 <= b /\ &0 < d /\ (&1 + b) / &2 <= d
     ==> d * (&1 + b) pow 2 <= &4 * (&1 + d) pow 3`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&4 * d pow 3` THEN CONJ_TAC THENL
   [SUBGOAL_THEN `&4 * d pow 3 = d * (&2 * d) pow 2` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_POW_MUL; REAL_POW_2] THEN
       CONV_TAC REAL_RING; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; MATCH_MP_TAC REAL_POW_LE2 THEN
       ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [REAL_ARITH_TAC; MATCH_MP_TAC REAL_POW_LE2 THEN ASM_REAL_ARITH_TAC]);;

(* Abstracted form: (2d/(1+b)) w-profile(d) <= 8 w-profile(b).  Common       *)
(* denominator (1+b)^3(1+d)^3 + REAL_LE_DIV2_EQ reduces to 2*CW_POLY_CORE.   *)
let CW_SCALE_LEFT_ABS = prove
 (`!d b. &0 <= b /\ &0 < d /\ (&1 + b) / &2 <= d
     ==> (&2 * d / (&1 + b)) * (&1 / (&1 + d) pow 3) <= &8 * (&1 / (&1 + b) pow
       3)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &1 + b /\ &0 < &1 + d` STRIP_ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(&1 + b = &0) /\ ~(&1 + d = &0)` STRIP_ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(&2 * d / (&1 + b)) * (&1 / (&1 + d) pow 3) =
    (&2 * d * (&1 + b) pow 2) / ((&1 + b) pow 3 * (&1 + d) pow 3)`
   SUBST1_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`~(&1 + b = &0)`; `~(&1 + d = &0)`] THEN
     CONV_TAC REAL_FIELD;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&8 * (&1 / (&1 + b) pow 3) =
    (&8 * (&1 + d) pow 3) / ((&1 + b) pow 3 * (&1 + d) pow 3)`
   SUBST1_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`~(&1 + b = &0)`; `~(&1 + d = &0)`] THEN
     CONV_TAC REAL_FIELD;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < (&1 + b) pow 3 * (&1 + d) pow 3` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THEN MATCH_MP_TAC REAL_POW_LT THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_DIV2_EQ] THEN
  MP_TAC(ISPECL [`d:real`; `b:real`] CW_POLY_CORE) THEN ASM_REWRITE_TAC[] THEN
  REAL_ARITH_TAC);;

(* Concrete: (1/a) w((1+b)/(2a)) <= 8 w(b) (0<a<=1, b>=0). d := (1+b)/(2a),  *)
(* then 2d/(1+b) = 1/a.                                                      *)
let CW_SCALE_LEFT = prove
 (`!a b. &0 < a /\ a <= &1 /\ &0 <= b
     ==> inv a * cw((&1 + b) / (&2 * a)) <= &8 * cw b`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`(&1 + b) / (&2 * a)`; `b:real`] CW_SCALE_LEFT_ABS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_DIV THEN ASM_REAL_ARITH_TAC;
      ASM_SIMP_TAC[REAL_LE_RDIV_EQ; REAL_ARITH `&0 < a ==> &0 < &2 * a`] THEN
      SUBGOAL_THEN `(&1 + b) / &2 * (&2 * a) = (&1 + b) * a` SUBST1_TAC THENL
       [UNDISCH_TAC `&0 < a` THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
      GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  REWRITE_TAC[cw] THEN
  SUBGOAL_THEN `abs((&1 + b) / (&2 * a)) = (&1 + b) / (&2 * a) /\ abs b = b`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN REWRITE_TAC[REAL_ABS_REFL] THENL
     [MATCH_MP_TAC REAL_LE_DIV THEN
       ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN AP_THM_TAC THEN
    AP_TERM_TAC THEN
  SUBGOAL_THEN `&2 * (&1 + b) / (&2 * a) / (&1 + b) = inv a` SUBST1_TAC THENL
   [SUBGOAL_THEN `~(&1 + b = &0)` MP_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    UNDISCH_TAC `&0 < a` THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  REFL_TAC);;

(* cw antitone on the negative side: x < -g (g >= 0) ==> cw x <= cw g.       *)
let CW_ANTITONE_NEG = prove
 (`!x g. &0 <= g /\ x < --g ==> cw x <= cw g`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CW_ANTITONE THEN
  SUBGOAL_THEN `abs g = g` SUBST1_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* 286G(d) POINTWISE convolution bound, valid on ALL of R (cleaner than      *)
(* Fremlin's half-line split): at each x, either x >= -gamma (right, w(a     *)
(* x+b) <= 8 w(b)) or x < -gamma (left, w(x) <= w(gamma)); both RHS terms >= *)
(* 0.                                                                        *)
let CW_CONV_PTWISE = prove
 (`!a b x. &0 < a /\ a <= &1 /\ &0 <= b
     ==> cw x * cw(a * x + b)
         <= &8 * cw b * cw x + cw((&1 + b) / (&2 * a)) * cw(a * x + b)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `&0 <= &8 * cw b * cw x /\ &0 <= cw((&1 + b) / (&2 * a)) * cw(a * x + b)`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; MATCH_MP_TAC REAL_LE_MUL THEN
         SIMP_TAC[CW_POS; REAL_LT_IMP_LE]];
      MATCH_MP_TAC REAL_LE_MUL THEN
        SIMP_TAC[CW_POS; REAL_LT_IMP_LE]]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= (&1 + b) / (&2 * a)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_DIV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `--((&1 + b) / (&2 * a)) <= x` THENL
   [MP_TAC(ISPECL [`a:real`;`b:real`;`x:real`] WEIGHT_SHIFT_BOUND) THEN
     ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `cw x * cw(a * x + b) <= &8 * cw b * cw x` MP_TAC THENL
     [ONCE_REWRITE_TAC[REAL_ARITH `&8 * cw b * cw x = cw x * &8 * cw b`] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN
        ASM_SIMP_TAC[CW_POS; REAL_LT_IMP_LE]; ALL_TAC] THEN
    ASM_REAL_ARITH_TAC;
    SUBGOAL_THEN `cw x <= cw((&1 + b) / (&2 * a))` ASSUME_TAC THENL
     [MATCH_MP_TAC CW_ANTITONE_NEG THEN ASM_REWRITE_TAC[] THEN
       ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `cw x * cw(a * x + b) <= cw((&1 + b) / (&2 * a)) * cw(a * x + b)` MP_TAC
       THENL
     [MATCH_MP_TAC REAL_LE_RMUL THEN
       ASM_SIMP_TAC[CW_POS; REAL_LT_IMP_LE]; ALL_TAC] THEN
    ASM_REAL_ARITH_TAC]);;

(* The weight is continuous (hence measurable): cw x = 1/(1+|x|)^3,          *)
(* denominator                                                               *)
(* never zero.  Needed for the product integrability in the convolution.     *)
(* The product w(x) w(a x+b) is integrable on R: measurable (continuous) and *)
(* bounded by the integrable w(x) (since w(a x+b) <= 1).                     *)
let CW_PROD_INTEGRABLE = prove
 (`!a b. (\x. cw x * cw(a * x + b)) real_integrable_on (:real)`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `cw` THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
    MP_TAC(BETA_RULE(ISPECL [`cw`; `(\x. cw(a * x + b))`;
      `(:real)`] REAL_CONTINUOUS_ON_MUL)) THEN
    DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[CW_CONTINUOUS; CW_SHIFT_CONTINUOUS];
    MATCH_MP_TAC HAS_REAL_INTEGRAL_INTEGRABLE THEN EXISTS_TAC `&1` THEN
    REWRITE_TAC[CW_FULL];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MP_TAC(SPEC `x:real` CW_POS) THEN MP_TAC(SPEC `a * x + b:real` CW_POS) THEN
    MP_TAC(SPEC `a * x + b:real` CW_LE_1) THEN STRIP_TAC THEN STRIP_TAC THEN
      STRIP_TAC THEN
    SUBGOAL_THEN
      `abs(cw x * cw(a * x + b)) = cw x * cw(a * x + b)` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC REAL_LE_MUL THEN
       ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC]);;

(* The integral of the CW_CONV_PTWISE right-hand side:  INT [8w(b)w(x) +     *)
(* w(gamma)w(a x+b)] = 8 w(b) + w(gamma)/a.                                  *)
let CW_CONV_RHS_INTEGRAL = prove
 (`!a b. &0 < a
     ==> ((\x. &8 * cw b * cw x + cw((&1 + b) / (&2 * a)) * cw(a * x + b))
          has_real_integral (&8 * cw b + cw((&1 + b) / (&2 * a)) * inv a))
            (:real)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC HAS_REAL_INTEGRAL_ADD THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`\x. cw b * cw x`; `cw b * &1`; `(:real)`;
     `&8`] HAS_REAL_INTEGRAL_LMUL) THEN
    REWRITE_TAC[REAL_ARITH `&8 * cw b * cw x = &8 * (cw b * cw x)`;
               REAL_ARITH `&8 * cw b * &1 = &8 * cw b`] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MP_TAC(ISPECL [`cw`; `&1`; `(:real)`; `cw b`] HAS_REAL_INTEGRAL_LMUL) THEN
    REWRITE_TAC[CW_FULL];
    MATCH_MP_TAC HAS_REAL_INTEGRAL_LMUL THEN
      ASM_SIMP_TAC[CW_AFFINE_INTEGRAL]]);;

(* 286G(d): the weight SELF-CONVOLUTION bound INT_R w(x) w(a x+b) dx <= 16   *)
(* w(b)                                                                      *)
(* for 0 < a <= 1, b >= 0 (C2 = 16). Integrate the whole-line pointwise      *)
(* bound                                                                     *)
(* CW_CONV_PTWISE (REAL/HAS_REAL_INTEGRAL_LE) and evaluate the RHS integral  *)
(* (CW_CONV_RHS_INTEGRAL); the w(gamma)/a term is <= 8 w(b) by               *)
(* CW_SCALE_LEFT.                                                            *)
let CW_CONVOLUTION = prove
 (`!a b. &0 < a /\ a <= &1 /\ &0 <= b
     ==> real_integral (:real) (\x. cw x * cw(a * x + b)) <= &16 * cw b`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&8 * cw b + cw((&1 + b) / (&2 * a)) * inv a` THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`\x. cw x * cw(a * x + b)`;
       `\x. &8 * cw b * cw x + cw((&1 + b) / (&2 * a)) * cw(a * x + b)`;
       `(:real)`;
       `real_integral (:real) (\x. cw x * cw(a * x + b))`;
       `&8 * cw b + cw((&1 + b) / (&2 * a)) * inv a`] HAS_REAL_INTEGRAL_LE)
         THEN
    ASM_SIMP_TAC[GSYM REAL_INTEGRABLE_INTEGRAL; CW_PROD_INTEGRABLE;
      CW_CONV_RHS_INTEGRAL] THEN
    DISCH_THEN MATCH_MP_TAC THEN REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(REWRITE_RULE[] (SPEC_ALL CW_CONV_PTWISE)) THEN
      ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`a:real`; `b:real`] CW_SCALE_LEFT) THEN
      ASM_REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[REAL_ARITH `cw((&1 + b) / (&2 * a)) * inv a =
                                 inv a * cw((&1 + b) / (&2 * a))`] THEN
    REAL_ARITH_TAC]);;

(* Reflection identity for the convolution integrand (w even, x |-> -x):     *)
(*   INT w(x)w(a x+b) = INT w(x)w(a x + -b).                                 *)
let CW_CONV_REFLECT = prove
 (`!a b. real_integral (:real) (\x. cw x * cw(a * x + b)) =
         real_integral (:real) (\x. cw x * cw(a * x + --b))`,
  REPEAT GEN_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [GSYM REAL_INTEGRAL_REFLECT_UNIV] THEN
  AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real` THEN
    REWRITE_TAC[] THEN
  GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [CW_EVEN] THEN
  AP_TERM_TAC THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM CW_EVEN] THEN
  AP_TERM_TAC THEN REAL_ARITH_TAC);;

(* 286G(d) for ALL real beta (C2 = 16): reduce b<0 to -b>0 by                *)
(* CW_CONV_REFLECT, with cw b = cw(-b).                                      *)
let CW_CONVOLUTION_GEN = prove
 (`!a b. &0 < a /\ a <= &1
     ==> real_integral (:real) (\x. cw x * cw(a * x + b)) <= &16 * cw b`,
  REPEAT STRIP_TAC THEN DISJ_CASES_TAC(REAL_ARITH `&0 <= b \/ &0 <= --b`) THENL
   [ASM_SIMP_TAC[CW_CONVOLUTION];
    ONCE_REWRITE_TAC[CW_CONV_REFLECT] THEN
    SUBGOAL_THEN `cw b = cw(--b)` SUBST1_TAC THENL
     [REWRITE_TAC[CW_EVEN]; ALL_TAC] THEN
    ASM_SIMP_TAC[CW_CONVOLUTION]]);;

(* ------------------------------------------------------------------------- *)
(* Hermite-Hadamard lower bound (for 286G(b)): a convex integrable function  *)
(* on [a,b] has INT_[a,b] f >= f(midpoint)*(b-a).  Proved by the midpoint-   *)
(* reflection: 2 INT f = INT [f(x)+f(a+b-x)] >= INT 2 f(m) = 2 f(m)(b-a).    *)
(* ------------------------------------------------------------------------- *)

(* Reflection about the midpoint maps [a,b] to itself.                       *)
let REAL_REFLECT_IMAGE_INTERVAL = prove
 (`!a b. IMAGE (\x. inv(-- &1) * (x - (a + b))) (real_interval[a,b]) =
   real_interval[a,b]`,
  REPEAT GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL] THEN
  X_GEN_TAC `y:real` THEN REWRITE_TAC[REAL_INV_NEG; REAL_INV_1] THEN
    EQ_TAC THENL
   [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    STRIP_TAC THEN EXISTS_TAC `a + b - y:real` THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]]);;

(* INT_[a,b] f = INT_[a,b] f(a+b-x) (midpoint reflection, via affinity       *)
(* m=-1).                                                                    *)
let HAS_REAL_INTEGRAL_MIDREFLECT = prove
 (`!f i a b. (f has_real_integral i) (real_interval[a,b])
     ==> ((\x. f(a + b - x)) has_real_integral i) (real_interval[a,b])`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPECL [`--(&1):real`; `a + b:real`] o MATCH_MP
    (REWRITE_RULE[IMP_CONJ] HAS_REAL_INTEGRAL_AFFINITY)) THEN
  REWRITE_TAC[REAL_ARITH `~(--(&1) = &0)`; REAL_REFLECT_IMAGE_INTERVAL] THEN
  REWRITE_TAC[REAL_ABS_NEG; REAL_ABS_NUM; REAL_INV_1; REAL_MUL_LID] THEN
  REWRITE_TAC[REAL_ARITH `--(&1) * x + (a + b) = a + b - x`]);;

(* Midpoint convexity:  f convex, m+t, m-t in s ==> 2 f(m) <= f(m+t)+f(m-t). *)
let CW_MIDPOINT_CONVEX = prove
 (`!f s m t. f real_convex_on s /\ (m + t) IN s /\ (m - t) IN s
     ==> &2 * f m <= f(m + t) + f(m - t)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`m + t:real`; `m - t:real`; `&1 / &2`;
    `&1 / &2`] o
    REWRITE_RULE[real_convex_on]) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&1 / &2 * (m + t) + &1 / &2 * (m - t) = m` SUBST1_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN REAL_ARITH_TAC);;

let REFLSUM_INTEGRABLE = prove
 (`!f a b. f real_integrable_on (real_interval[a,b])
     ==> (\x. f x + f(a + b - x)) real_integrable_on (real_interval[a,b])`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_INTEGRABLE_ADD THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC HAS_REAL_INTEGRAL_INTEGRABLE THEN
    EXISTS_TAC `real_integral (real_interval[a,b]) f` THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_MIDREFLECT THEN
      ASM_SIMP_TAC[REAL_INTEGRABLE_INTEGRAL]]);;

let REFLSUM_INTEGRAL = prove
 (`!f a b. a <= b /\ f real_integrable_on (real_interval[a,b])
     ==> real_integral (real_interval[a,b]) (\x. f x + f(a + b - x)) =
         &2 * real_integral (real_interval[a,b]) f`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `((\x. f x + f(a + b - x)) has_real_integral
      (real_integral (real_interval[a,b]) f + real_integral
        (real_interval[a,b]) f))
      (real_interval[a,b])` MP_TAC THENL
   [MATCH_MP_TAC HAS_REAL_INTEGRAL_ADD THEN CONJ_TAC THENL
     [ASM_SIMP_TAC[REAL_INTEGRABLE_INTEGRAL];
      MATCH_MP_TAC HAS_REAL_INTEGRAL_MIDREFLECT THEN
        ASM_SIMP_TAC[REAL_INTEGRABLE_INTEGRAL]];
    ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN REAL_ARITH_TAC);;

let HERMITE_HADAMARD_LOWER = prove
 (`!f a b. a <= b /\ f real_convex_on (real_interval[a,b]) /\
           f real_integrable_on (real_interval[a,b])
     ==> f((a + b) / &2) * (b - a) <= real_integral (real_interval[a,b]) f`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(REAL_ARITH `&2 * (fm * ba) <= &2 * q ==> fm * ba <= q`) THEN
  ASM_SIMP_TAC[GSYM REFLSUM_INTEGRAL] THEN
  SUBGOAL_THEN `&2 * f((a + b) / &2) * (b - a) =
                real_integral (real_interval[a,b]) (\x. &2 * f((a + b) / &2))`
                  SUBST1_TAC THENL
   [ASM_SIMP_TAC[REAL_INTEGRAL_CONST] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC HAS_REAL_INTEGRAL_INTEGRABLE THEN
    EXISTS_TAC `(&2 * f((a + b) / &2)) * (b - a)` THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_CONST THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REFLSUM_INTEGRABLE THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`f:real->real`; `real_interval[a,b]`; `(a + b) / &2`;
      `x - (a + b) / &2`]
      CW_MIDPOINT_CONVEX) THEN
    ASM_REWRITE_TAC[IN_REAL_INTERVAL;
      REAL_ARITH `(a + b) / &2 + (x - (a + b) / &2) = x`;
      REAL_ARITH `(a + b) / &2 - (x - (a + b) / &2) = a + b - x`] THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REAL_ARITH_TAC]]);;

(* Convexity template: \x. C inv((p + q x)^3) is convex on any [a,b] where   *)
(* p + q x > 0 (C >= 0).  Second derivative C*12*inv((p+q x)^5)*q^2 >= 0     *)
(* (REAL_CONVEX_ON_SECOND_DERIVATIVE).  This is the engine for w_sigma being *)
(* convex on an interval missing x_sigma (286G(b)).                          *)
let INV_CUBE_CONVEX = prove
 (`!C p q a b. &0 <= C /\ a < b /\ (!x. a <= x /\ x <= b ==> &0 < p + q * x)
     ==> (\x. C * inv((p + q * x) pow 3)) real_convex_on (real_interval[a,b])`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`(\x. C * inv((p + q * x) pow 3)):real->real`;
    `(\x. C * (-- &3 * inv((p + q * x) pow 4) * q)):real->real`;
    `(\x. C * (&12 * inv((p + q * x) pow 5) * q * q)):real->real`;
    `real_interval[a,b]`] REAL_CONVEX_ON_SECOND_DERIVATIVE) THEN
  REWRITE_TAC[IS_REALINTERVAL_INTERVAL] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `c:real` THEN
      REWRITE_TAC[EXTENSION; IN_REAL_INTERVAL; IN_SING; NOT_FORALL_THM] THEN
      ASM_CASES_TAC `c = a:real` THENL
       [EXISTS_TAC `b:real` THEN ASM_REAL_ARITH_TAC;
        EXISTS_TAC `a:real` THEN ASM_REAL_ARITH_TAC];
      X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
      SUBGOAL_THEN `&0 < p + q * x` ASSUME_TAC THENL
        [ASM_SIMP_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC HAS_REAL_DERIVATIVE_ATREAL_WITHIN THEN REAL_DIFF_TAC THEN
      SUBGOAL_THEN `~(p + q * x = &0)` MP_TAC THENL
       [ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN CONV_TAC REAL_FIELD;
      X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
      SUBGOAL_THEN `&0 < p + q * x` ASSUME_TAC THENL
        [ASM_SIMP_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC HAS_REAL_DERIVATIVE_ATREAL_WITHIN THEN REAL_DIFF_TAC THEN
      SUBGOAL_THEN `~(p + q * x = &0)` MP_TAC THENL
       [ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN CONV_TAC REAL_FIELD];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    SUBGOAL_THEN `&0 < p + q * x` ASSUME_TAC THENL
      [ASM_SIMP_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[REAL_LE_SQUARE] THEN
    REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_POW_LE THEN
      ASM_REAL_ARITH_TAC]);;

(* --- 286Gd building blocks (toward the two-sided weight sum sum_n w(x-n)   *)
(* <= 2) ---                                                                 *)

(* cw is convex on any unit interval [c,c+1] on the positive half-line (c >= *)
(* 0): there cw x = 1/(1+x)^3 = the INV_CUBE_CONVEX template (C=1, p=1, q=1, *)
(* 1+x > 0).                                                                 *)
let CWTILE_CONVEX_RIGHT = prove
 (`!(s:int#int#int) a b. a < b /\ tile_xmid s <= a
     ==> cw_tile s real_convex_on (real_interval[a,b])`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_CONVEX_ON_EQ THEN
  EXISTS_TAC `\x. &2 zpow (tile_k s) *
                  inv(((&1 - &2 zpow (tile_k s) * tile_xmid s) + &2 zpow
                    (tile_k s) * x) pow 3)` THEN
  REWRITE_TAC[IS_REALINTERVAL_INTERVAL] THEN CONJ_TAC THENL
   [X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    REWRITE_TAC[cw_tile; cw] THEN
    SUBGOAL_THEN `abs(&2 zpow (tile_k s) * (x - tile_xmid s)) =
                  &2 zpow (tile_k s) * (x - tile_xmid s)` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC REAL_LE_MUL THEN
       CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
         REAL_ARITH_TAC;
        ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
    REWRITE_TAC[REAL_ARITH `&1 / x = inv x`] THEN AP_TERM_TAC THEN
      AP_TERM_TAC THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    MATCH_MP_TAC INV_CUBE_CONVEX THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      X_GEN_TAC `x:real` THEN STRIP_TAC THEN
      SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
       [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
        `(&1 - &2 zpow (tile_k s) * tile_xmid s) + &2 zpow (tile_k s) * x =
                    &1 + &2 zpow (tile_k s) * (x - tile_xmid s)` SUBST1_TAC
                      THENL
       [REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `&0 <= &2 zpow (tile_k s) * (x - tile_xmid s)` MP_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
         ASM_REAL_ARITH_TAC;
        REAL_ARITH_TAC]]]);;

let CWTILE_CONVEX_LEFT = prove
 (`!(s:int#int#int) a b. a < b /\ b <= tile_xmid s
     ==> cw_tile s real_convex_on (real_interval[a,b])`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_CONVEX_ON_EQ THEN
  EXISTS_TAC `\x. &2 zpow (tile_k s) *
                  inv(((&1 + &2 zpow (tile_k s) * tile_xmid s) + (--(&2 zpow
                    (tile_k s))) * x) pow 3)` THEN
  REWRITE_TAC[IS_REALINTERVAL_INTERVAL] THEN CONJ_TAC THENL
   [X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    REWRITE_TAC[cw_tile; cw] THEN
    SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `abs(&2 zpow (tile_k s) * (x - tile_xmid s)) =
                  --(&2 zpow (tile_k s) * (x - tile_xmid s))` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ARITH `abs y = --y <=> y <= &0`] THEN
      ONCE_REWRITE_TAC[REAL_ARITH `y * z <= &0 <=> &0 <= y * (--z)`] THEN
      MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
        ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[REAL_ARITH `&1 / x = inv x`] THEN AP_TERM_TAC THEN
      AP_TERM_TAC THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    MATCH_MP_TAC INV_CUBE_CONVEX THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      X_GEN_TAC `x:real` THEN STRIP_TAC THEN
      SUBGOAL_THEN `&0 < &2 zpow (tile_k s)` ASSUME_TAC THENL
       [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
        `(&1 + &2 zpow (tile_k s) * tile_xmid s) + (--(&2 zpow (tile_k s))) * x
         =
                    &1 + &2 zpow (tile_k s) * (tile_xmid s - x)` SUBST1_TAC
                      THENL
       [REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `&0 <= &2 zpow (tile_k s) * (tile_xmid s - x)` MP_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
         ASM_REAL_ARITH_TAC;
        REAL_ARITH_TAC]]]);;
let CWTILE_CONTINUOUS = prove
 (`!(s:int#int#int). cw_tile s real_continuous_on (:real)`,
  GEN_TAC THEN
  SUBGOAL_THEN `cw_tile s =
     (\x. &2 zpow (tile_k s) * cw(&2 zpow (tile_k s) * x + (--(&2 zpow (tile_k
       s) * tile_xmid s))))`
    SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; cw_tile] THEN GEN_TAC THEN AP_TERM_TAC THEN
     AP_TERM_TAC THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(BETA_RULE(ISPECL [`\x:real. &2 zpow (tile_k s)`;
     `\x. cw(&2 zpow (tile_k s) * x + (--(&2 zpow (tile_k s) * tile_xmid s)))`;
       `(:real)`]
     REAL_CONTINUOUS_ON_MUL)) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON_CONST; CW_SHIFT_CONTINUOUS]);;

let CWTILE_INTEGRABLE = prove
 (`!(s:int#int#int) a b. cw_tile s real_integrable_on (real_interval[a,b])`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC REAL_INTEGRABLE_CONTINUOUS THEN
  MATCH_MP_TAC REAL_CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real)` THEN
  REWRITE_TAC[CWTILE_CONTINUOUS; SUBSET_UNIV]);;

(* 286Gc for cw_tile: on an interval [a,b] lying on ONE side of x_s, the     *)
(* tile                                                                      *)
(* weight integral is at least its midpoint value times the length -- the    *)
(* midpoint-rule underestimate for the convex w_sigma. Instantiate the       *)
(* existing HERMITE_HADAMARD_LOWER at f := cw_tile s (convex via             *)
(* CWTILE_CONVEX_                                                            *)
(* RIGHT/LEFT, integrable via CWTILE_INTEGRABLE). The 286Gc input to the     *)
(* 286Gg                                                                     *)
(* integral kernel bound (int_{I_tau} w_sigma >= w_sigma(x_tau) muI_tau).    *)
let CWTILE_BOUNDS = prove
 (`!s x. &0 <= cw_tile s x /\ cw_tile s x <= &2 zpow tile_k s`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cw_tile] THEN
  SUBGOAL_THEN `&0 < &2 zpow tile_k s` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPEC `&2 zpow tile_k s * (x - tile_xmid s)` CW_POS) THEN
  MP_TAC(SPEC `&2 zpow tile_k s * (x - tile_xmid s)` CW_LE_1) THEN
  STRIP_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC]);;

(* A constant is real-integrable on any real-measurable set (c * the &1      *)
(* integrand).                                                               *)
let REAL_INTEGRABLE_ON_CONST_MEASURABLE = prove
 (`!c s. real_measurable s ==> (\x:real. c) real_integrable_on s`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\x:real. &1`; `c:real`;
    `s:real->bool`] REAL_INTEGRABLE_LMUL) THEN
  ASM_REWRITE_TAC[REAL_MUL_RID; GSYM REAL_MEASURABLE]);;

let CWTILE_INTEGRABLE_MEASURABLE = prove
 (`!s Sc. real_measurable Sc ==> cw_tile s real_integrable_on Sc`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\x. &2 zpow tile_k s):real->real` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
      REWRITE_TAC[CWTILE_CONTINUOUS];
    MATCH_MP_TAC REAL_INTEGRABLE_ON_CONST_MEASURABLE THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN DISCH_TAC THEN
    MP_TAC(SPECL [`s:int#int#int`; `x:real`] CWTILE_BOUNDS) THEN
      REAL_ARITH_TAC]);;

(* 286J part(b): int_A w_tau <= C mu A when w_tau <= C on the measurable set *)
(* A.                                                                        *)
(* REAL_INTEGRAL_LE against the constant C (int_A C = C mu A via             *)
(* has_real_measure                                                          *)
(* + HAS_REAL_INTEGRAL_LMUL); cw_tile integrable on A by CWTILE_INTEGRABLE_  *)
(* MEASURABLE.  Bounds the peak/annulus terms of the R = union_k R_k decomp. *)
let CWTILE_INTEGRAL_LE_MEASURE = prove
 (`!s A C. real_measurable A /\ &0 <= C /\ (!x. x IN A ==> cw_tile s x <= C)
     ==> real_integral A (cw_tile s) <= C * real_measure A`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `((\x:real. C) has_real_integral (C * real_measure A)) A` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\x:real. &1`; `real_measure A`; `A:real->bool`; `C:real`]
       HAS_REAL_INTEGRAL_LMUL) THEN
    ASM_SIMP_TAC[GSYM has_real_measure; GSYM HAS_REAL_MEASURE_MEASURE] THEN
    REWRITE_TAC[REAL_MUL_RID]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral A (\x:real. C)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN ASM_REWRITE_TAC[];
      ASM_MESON_TAC[real_integrable_on];
      ASM_SIMP_TAC[]];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286J part(b): the two product bounds for the annulus decomposition of     *)
(* int_{E cap g^-1[J_tau]} w_tau. (i) peak: int_A w_tau <= muJ_tau mu A on   *)
(* any                                                                       *)
(* measurable A.  (ii) annulus: on A avoiding I^(k)_tau, int_A w_tau <=      *)
(* (1+2^{k-1})^{-3} muJ_tau mu A = 2^{k_tau} cw(2^{k-1}) mu A.               *)
(* ------------------------------------------------------------------------- *)
let CWTILE_INTEGRAL_LE_MUJ_MEASURE = prove
 (`!tau A. real_measurable A
     ==> real_integral A (cw_tile tau) <= &2 zpow (tile_k tau) * real_measure
       A`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CWTILE_INTEGRAL_LE_MEASURE THEN
  ASM_REWRITE_TAC[CWTILE_LE_MUJ] THEN
  MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC);;

let CWTILE_INTEGRAL_ANNULUS_BOUND = prove
 (`!tau k A.
     real_measurable A /\ (!x. x IN A ==> ~(x IN tile_Idil tau k))
     ==> real_integral A (cw_tile tau) <=
         (&2 zpow (tile_k tau) * cw (&2 zpow (&k - &1))) * real_measure A`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CWTILE_INTEGRAL_LE_MEASURE THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_IMP_LE THEN REWRITE_TAC[CW_POS]];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    MATCH_MP_TAC CWTILE_OUTSIDE_IDIL_BOUND THEN ASM_SIMP_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286J part(b) K-truncated integral bound (Fremlin mt286.tex 862-870).  For *)
(* measurable S: int_{S cap I^(K)_tau} w_tau <= muJ_tau mu(S cap I^(0)) +    *)
(* sum_{k<K} cw(2^{k-1}) muJ_tau mu(S cap I^(k+1)). Induction on K; step     *)
(* splits                                                                    *)
(* S cap I^(K+1) = (S cap I^(K)) U annulus, annulus avoids I^(K) so the      *)
(* annulus                                                                   *)
(* bound applies + mu(annulus) <= mu(S cap I^(K+1)). Feeds monotone          *)
(* convergence                                                               *)
(* (TILE_IDIL_EXHAUSTS) to Fremlin's int_{E cap g^-1[J_tau]} w_tau series.   *)
(* ------------------------------------------------------------------------- *)
let CWTILE_KTRUNC_BOUND = prove
 (`!tau S. real_measurable S
     ==> !K. real_integral (S INTER tile_Idil tau K) (cw_tile tau) <=
             &2 zpow (tile_k tau) * real_measure (S INTER tile_Idil tau 0) +
             sum {k | k < K} (\k. &2 zpow (tile_k tau) * cw (&2 zpow (&k - &1))
               *
                    real_measure (S INTER tile_Idil tau (k+1)))`,
  GEN_TAC THEN GEN_TAC THEN DISCH_TAC THEN INDUCT_TAC THENL
   [SUBGOAL_THEN `{k | k < 0} = {}` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY; LT]; ALL_TAC] THEN
    REWRITE_TAC[SUM_CLAUSES; REAL_ADD_RID] THEN
    MATCH_MP_TAC CWTILE_INTEGRAL_LE_MUJ_MEASURE THEN
    MATCH_MP_TAC REAL_MEASURABLE_INTER THEN
      ASM_REWRITE_TAC[TILE_IDIL_MEASURABLE];
    ALL_TAC] THEN
  ABBREV_TAC `ANN = (S INTER tile_Idil tau (SUC K)) DIFF tile_Idil tau K` THEN
  SUBGOAL_THEN
    `S INTER tile_Idil tau (SUC K) = (S INTER tile_Idil tau K) UNION ANN`
      ASSUME_TAC THENL
   [EXPAND_TAC "ANN" THEN
    MP_TAC(ISPECL [`tau:int#int#int`; `K:num`; `SUC K`] TILE_IDIL_MONO) THEN
    ANTS_TAC THENL [ARITH_TAC; ALL_TAC] THEN ASM SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (S INTER tile_Idil tau (SUC K)) (cw_tile tau) =
    real_integral (S INTER tile_Idil tau K) (cw_tile tau) +
    real_integral ANN (cw_tile tau)` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_UNION THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN
      MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN
      MATCH_MP_TAC REAL_MEASURABLE_INTER THEN
        ASM_REWRITE_TAC[TILE_IDIL_MEASURABLE];
      MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN
      MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN EXPAND_TAC "ANN" THEN
      MATCH_MP_TAC REAL_MEASURABLE_DIFF THEN
      ASM_SIMP_TAC[TILE_IDIL_MEASURABLE; REAL_MEASURABLE_INTER];
      EXPAND_TAC "ANN" THEN
      MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `{}:real->bool` THEN
      REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY] THEN ASM SET_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `{k | k < SUC K} = K INSERT {k | k < K}` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INSERT; IN_ELIM_THM] THEN
     ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[SUM_CLAUSES; FINITE_NUMSEG_LT; IN_ELIM_THM; LT_REFL] THEN
  MATCH_MP_TAC(REAL_ARITH
   `iK <= b + s /\ ann <= kt ==> iK + ann <= b + kt + s`) THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(&2 zpow (tile_k tau) * cw (&2 zpow (&K - &1))) * real_measure
    ANN` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CWTILE_INTEGRAL_ANNULUS_BOUND THEN CONJ_TAC THENL
     [EXPAND_TAC "ANN" THEN MATCH_MP_TAC REAL_MEASURABLE_DIFF THEN
      ASM_SIMP_TAC[TILE_IDIL_MEASURABLE; REAL_MEASURABLE_INTER];
      EXPAND_TAC "ANN" THEN REWRITE_TAC[IN_DIFF] THEN
        MESON_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LT_IMP_LE THEN REWRITE_TAC[CW_POS]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURE_SUBSET THEN REPEAT CONJ_TAC THENL
   [EXPAND_TAC "ANN" THEN MATCH_MP_TAC REAL_MEASURABLE_DIFF THEN
    ASM_SIMP_TAC[TILE_IDIL_MEASURABLE; REAL_MEASURABLE_INTER];
    ASM_SIMP_TAC[TILE_IDIL_MEASURABLE; REAL_MEASURABLE_INTER];
    EXPAND_TAC "ANN" THEN REWRITE_TAC[ADD1] THEN ASM SET_TAC[]]);;

(* helper: int_S (if x in A then w else 0) = int_{S cap A} w (ETA_AX         *)
(* collapses the RESTRICT_INTER eta-expanded integrand).                     *)
let CWTILE_RESTRICT_INTER_EQ = prove
 (`!tau A S. real_integral S (\x. if x IN A then cw_tile tau x else &0) =
             real_integral (S INTER A) (cw_tile tau)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[REAL_INTEGRAL_RESTRICT_INTER; ETA_AX] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[INTER_COMM]);;

(* 286J part(b) monotone-convergence limit: int_{S cap I^(K)_tau} w_tau ->   *)
(* int_S w_tau as K->inf, for measurable S.  REAL_DOMINATED_CONVERGENCE with *)
(* f_K = w_tau restricted to I^(K)_tau, dominated by w_tau, converging       *)
(* pointwise                                                                 *)
(* (each x eventually in I^(K) by TILE_IDIL_EXHAUSTS + TILE_IDIL_MONO).      *)
let CWTILE_KTRUNC_LIMIT = prove
 (`!tau S. real_measurable S
     ==> ((\K. real_integral (S INTER tile_Idil tau K) (cw_tile tau))
          ---> real_integral S (cw_tile tau)) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\K x. if x IN tile_Idil tau K then cw_tile tau x else &0`;
    `cw_tile tau`; `cw_tile tau`;
      `S:real->bool`] REAL_DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[CWTILE_RESTRICT_INTER_EQ] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [GEN_TAC THEN REWRITE_TAC[REAL_INTEGRABLE_RESTRICT_INTER; ETA_AX] THEN
      MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN
      ONCE_REWRITE_TAC[INTER_COMM] THEN
      MATCH_MP_TAC REAL_MEASURABLE_INTER THEN
        ASM_REWRITE_TAC[TILE_IDIL_MEASURABLE];
      MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN ASM_REWRITE_TAC[];
      REPEAT STRIP_TAC THEN COND_CASES_TAC THEN
      MP_TAC(SPECL [`tau:int#int#int`; `x:real`] CW_TILE_POS) THEN
        REAL_ARITH_TAC;
      X_GEN_TAC `x:real` THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`tau:int#int#int`; `x:real`] TILE_IDIL_EXHAUSTS) THEN
      DISCH_THEN(X_CHOOSE_TAC `K0:num`) THEN
      MATCH_MP_TAC REALLIM_EVENTUALLY THEN
      REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `K0:num` THEN
      X_GEN_TAC `K:num` THEN DISCH_TAC THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `~(x IN tile_Idil tau K)` THEN REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`tau:int#int#int`; `K0:num`; `K:num`] TILE_IDIL_MONO) THEN
      ASM_REWRITE_TAC[] THEN ASM SET_TAC[]];
    SIMP_TAC[]]);;


(* ========================================================================= *)
(* 286J part (b) contrapositive (Fremlin mt286.tex 871-883, the "either ...  *)
(* or ..." step, run as: if the peak term < gam/8 and every annulus falls    *)
(* below its R_{k+1} threshold, then int_{E cap g^-1[J_tau]} w_tau <=        *)
(* gam/4).                                                                   *)
(* First the K-truncated bound <= gam/4 (KTRUNC_BOUND + ANNULUS_TERM_BOUND + *)
(* SUM_ZPOW_QUARTER), then pass K->inf (KTRUNC_LIMIT + REALLIM_UBOUND).      *)
(* ========================================================================= *)

(* K-truncated: int_{S cap I^(K)} w_tau <= gam/4 under the smallness hyps.   *)
let CWTILE_KTRUNC_LE_QUARTER = prove
 (`!tau S gam K. real_measurable S /\ &0 <= gam /\
     &2 zpow (tile_k tau) * real_measure (S INTER tile_Idil tau 0) <= gam / &8
       /\
     (!k. &2 zpow (tile_k tau) * real_measure (S INTER tile_Idil tau (k+1))
          <= &2 zpow (&2 * &k - &7) * gam)
     ==> real_integral (S INTER tile_Idil tau K) (cw_tile tau) <= gam / &4`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`tau:int#int#int`; `S:real->bool`] CWTILE_KTRUNC_BOUND) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 zpow (tile_k tau) * real_measure (S INTER tile_Idil tau 0) +
    sum {k | k < K} (\k. &2 zpow (tile_k tau) * cw (&2 zpow (&k - &1)) *
                    real_measure (S INTER tile_Idil tau (k+1)))` THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `gam / &8 + sum {k | k < K} (\k. &2 zpow (--(&k) - &4) * gam)`
    THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_ADD2 THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SUM_LE THEN REWRITE_TAC[FINITE_NUMSEG_LT; IN_ELIM_THM] THEN
    X_GEN_TAC `k:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[REAL_ARITH `a * b * c = b * (a * c):real`] THEN
    MATCH_MP_TAC CWTILE_ANNULUS_TERM_BOUND THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_MEASURE_POS_LE THEN
        MATCH_MP_TAC REAL_MEASURABLE_INTER THEN
          ASM_REWRITE_TAC[TILE_IDIL_MEASURABLE]];
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[SUM_RMUL] THEN
    MATCH_MP_TAC(REAL_ARITH `s * gam <= gam / &8 ==> gam/ &8 + s * gam <= gam /
      &4`) THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(&1 / &8) * gam` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[SUM_ZPOW_QUARTER];
      REAL_ARITH_TAC]]);;

(* the limit: int_S w_tau <= gam/4 (REALLIM_UBOUND on KTRUNC_LIMIT).         *)
let CWTILE_MASS_SMALL = prove
 (`!tau S gam. real_measurable S /\ &0 <= gam /\
     &2 zpow (tile_k tau) * real_measure (S INTER tile_Idil tau 0) <= gam / &8
       /\
     (!k. &2 zpow (tile_k tau) * real_measure (S INTER tile_Idil tau (k+1))
          <= &2 zpow (&2 * &k - &7) * gam)
     ==> real_integral S (cw_tile tau) <= gam / &4`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(ISPEC `sequentially` REALLIM_UBOUND) THEN
  EXISTS_TAC `\K. real_integral (S INTER tile_Idil tau K) (cw_tile tau)` THEN
  ASM_SIMP_TAC[CWTILE_KTRUNC_LIMIT; TRIVIAL_LIMIT_SEQUENTIALLY] THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
  X_GEN_TAC `K:num` THEN DISCH_TAC THEN
  MATCH_MP_TAC CWTILE_KTRUNC_LE_QUARTER THEN ASM_REWRITE_TAC[]);;


(* ========================================================================= *)
(* 286J part (b) R_k dichotomy (Fremlin mt286.tex 846-883): if the region    *)
(* integral exceeds gam/4 (as it does for every tau in the greedy R, by the  *)
(* witness), then muJ_tau mu(S cap I^(m)_tau) >= 2^{2m-9} gam for some m --  *)
(* i.e.                                                                      *)
(* tau in R_m. Contrapositive of CWTILE_MASS_SMALL: if no such m then the    *)
(* peak                                                                      *)
(* term (m=0) is < 2^{-9}gam <= gam/8 and every annulus (m=k+1) is <         *)
(* 2^{2k-7}                                                                  *)
(* gam, so int_S w_tau <= gam/4, contradiction.                              *)
(* ========================================================================= *)
let CWTILE_MASS_DICHOTOMY = prove
 (`!tau S gam. real_measurable S /\ &0 <= gam /\
     gam / &4 < real_integral S (cw_tile tau)
     ==> ?m. &2 zpow (&2 * &m - &9) * gam
             <= &2 zpow (tile_k tau) * real_measure (S INTER tile_Idil tau m)`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `?m. &2 zpow (&2 * &m - &9) * gam
             <= &2 zpow (tile_k tau) * real_measure (S INTER tile_Idil tau m)`
               THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[NOT_EXISTS_THM; REAL_NOT_LE]) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `real_integral S (cw_tile tau) <= gam / &4` MP_TAC THENL
   [MATCH_MP_TAC CWTILE_MASS_SMALL THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [(* peak: 2^{k_tau} mu(S cap I^0) <= gam/8                              *)
      FIRST_X_ASSUM(MP_TAC o SPEC `0`) THEN
      SUBGOAL_THEN `&2 * &0 - &9 = --(&9):int` SUBST1_TAC THENL
       [INT_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC(REAL_ARITH `t <= gam/ &8 ==> a < t ==> a <= gam/ &8`) THEN
      ONCE_REWRITE_TAC[REAL_ARITH `&2 zpow (--(&9)) * gam = gam * &2 zpow
        (--(&9))`] THEN
      GEN_REWRITE_TAC RAND_CONV [REAL_ARITH `gam / &8 = gam * (&1 / &8)`] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[REAL_ZPOW_NEG; REAL_ZPOW_NUM] THEN
        CONV_TAC REAL_RAT_REDUCE_CONV;
      (* annulus: !k. 2^{k_tau} mu(S cap I^(k+1)) <= 2^{2k-7} gam            *)
      X_GEN_TAC `k:num` THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `k + 1`) THEN
      MATCH_MP_TAC(REAL_ARITH `t = u ==> a < t ==> a <= u`) THEN
      AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
      REWRITE_TAC[GSYM INT_OF_NUM_ADD] THEN INT_ARITH_TAC];
    ASM_REAL_ARITH_TAC]);;


(* ========================================================================= *)
(* Helpers for 286J(c): a finite int-image set is bounded above; hence a     *)
(* finite nonempty family has a scale-maximal member.                        *)
(* ========================================================================= *)
(* ========================================================================= *)
(* Integer order theory: a non-empty integer predicate bounded above has a   *)
(* MAXIMAL element. (INT_WOP applied to y |-> P(b - y): the least such y >=  *)
(* 0                                                                         *)
(* gives the greatest b - y.)  Needed for 286K a-i: on each achievable tree  *)
(* value the root scales k_tau are bounded above (TREE_KBOUND), so a         *)
(* maximal-                                                                  *)
(* scale representative exists.                                              *)
(* ========================================================================= *)
let INT_HAS_MAX = prove
 (`!P b:int. (?x. P x) /\ (!x. P x ==> x <= b)
     ==> ?m. P m /\ (!x. P x ==> x <= m)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(INST [`\y:int. P(b - y):bool`,`P:int->bool`] INT_WOP) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN `?z:int. &0 <= z /\ P(b - z)` (fun th -> REWRITE_TAC[th]) THENL
   [EXISTS_TAC `b - x:int` THEN
    SUBGOAL_THEN `x:int <= b` ASSUME_TAC THENL [ASM_SIMP_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[INT_ARITH `b - (b - x):int = x`] THEN
      ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y0:int` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `b - y0:int` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:int` THEN DISCH_TAC THEN
  SUBGOAL_THEN `z:int <= b` ASSUME_TAC THENL [ASM_SIMP_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `b - z:int`) THEN
  ASM_SIMP_TAC[INT_ARITH `b - (b - z):int = z`] THEN ASM_INT_ARITH_TAC);;

let INT_FINITE_BOUNDED = prove
 (`!S:int->bool. FINITE S ==> ?b. !x. x IN S ==> x <= b`,
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
   [EXISTS_TAC `&0:int` THEN REWRITE_TAC[NOT_IN_EMPTY];
    REPEAT STRIP_TAC THEN EXISTS_TAC `if b:int < x then x else b` THEN
    REWRITE_TAC[IN_INSERT] THEN X_GEN_TAC `y:int` THEN STRIP_TAC THENL
     [ASM_REWRITE_TAC[] THEN COND_CASES_TAC THEN ASM_INT_ARITH_TAC;
      FIRST_X_ASSUM(MP_TAC o SPEC `y:int`) THEN ASM_REWRITE_TAC[] THEN
      COND_CASES_TAC THEN ASM_INT_ARITH_TAC]]);;

let SCALE_MAX_ELEMENT = prove
 (`!(sc:A->int) S. FINITE S /\ ~(S = {})
     ==> ?m. m IN S /\ (!t. t IN S ==> sc t <= sc m)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `a:A` o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY])
    THEN
  MP_TAC(ISPEC `IMAGE (sc:A->int) S` INT_FINITE_BOUNDED) THEN
  ASM_SIMP_TAC[FINITE_IMAGE] THEN
  DISCH_THEN(X_CHOOSE_TAC `b:int`) THEN
  MP_TAC(ISPECL [`\y:int. y IN IMAGE (sc:A->int) S`; `b:int`] INT_HAS_MAX) THEN
  BETA_TAC THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN
      EXISTS_TAC `sc(a:A):int` THEN EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `M:int` STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC o
                GEN_REWRITE_RULE I [IN_IMAGE]) THEN
  EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `t:A` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `sc(t:A):int`) THEN
  REWRITE_TAC[IN_IMAGE] THEN
  ANTS_TAC THENL [EXISTS_TAC `t:A` THEN
    ASM_REWRITE_TAC[]; ASM_INT_ARITH_TAC]);;

(* ========================================================================= *)
(* GREEDY CAPTURE (Fremlin 286J(c) q-map, abstract).  Given a finite S, a    *)
(* SYMMETRIC "meet" relation mt, and a scale sc, there is a subfamily M of S *)
(* that is pairwise NON-meeting, together with a capture map q : S -> M such *)
(* that every s in S meets its root q s, and sc(q s) >= sc s (the root is at *)
(* least as coarse). This is Fremlin's q with M = {q j : j <= n} = the       *)
(* roots.                                                                    *)
(* Proof: strong induction on CARD S. Pick a scale-MAXIMAL m in S            *)
(* (coarsest);                                                               *)
(* it becomes a root. Split S into A = { s : s meets m } (captured by m) and *)
(* B = S \ A (never meets m).  Recurse on B (smaller: m in A so B PSUBSET S) *)
(* to get MB pairwise-non-meeting + qB.  Set M = m INSERT MB, and q s = m if *)
(* s in A else qB s. Pairwise-non-meeting: MB members don't meet (IH); m     *)
(* does                                                                      *)
(* not meet any MB member (MB SUBSET B, and B members don't meet m).         *)
(* Coarseness:                                                               *)
(* for s in A, sc(q s) = sc m >= sc s by maximality; for s in B, IH.         *)
(* ========================================================================= *)
let GREEDY_CAPTURE_N = prove
 (`!n (mt:A->A->bool) (sc:A->int) S.
     CARD S = n /\ FINITE S /\ (!a b. mt a b ==> mt b a) /\ (!a. mt a a)
     ==> ?M q. M SUBSET S /\
               (!s. s IN S ==> q s IN M) /\
               (!m. m IN M ==> m IN S) /\
               (!s. s IN S ==> mt s (q s) /\ sc s <= sc(q s)) /\
               (!m1 m2. m1 IN M /\ m2 IN M /\ ~(m1 = m2) ==> ~mt m1 m2)`,
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  MAP_EVERY X_GEN_TAC [`mt:A->A->bool`; `sc:A->int`; `S:A->bool`] THEN
  STRIP_TAC THEN
  ASM_CASES_TAC `S:A->bool = {}` THENL
   [EXISTS_TAC `{}:A->bool` THEN EXISTS_TAC `(\s:A. s):A->A` THEN
    ASM_REWRITE_TAC[NOT_IN_EMPTY; EMPTY_SUBSET];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`sc:A->int`; `S:A->bool`] SCALE_MAX_ELEMENT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC `B = {s:A | s IN S /\ ~(mt:A->A->bool) s m}` THEN
  SUBGOAL_THEN `FINITE(B:A->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "B" THEN MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `S:A->bool` THEN ASM_REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
    MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~((m:A) IN B)` ASSUME_TAC THENL
   [EXPAND_TAC "B" THEN REWRITE_TAC[IN_ELIM_THM] THEN
     ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(B:A->bool) SUBSET S` ASSUME_TAC THENL
   [EXPAND_TAC "B" THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
     MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `CARD(B:A->bool) < n` ASSUME_TAC THENL
   [EXPAND_TAC "n" THEN MATCH_MP_TAC CARD_PSUBSET THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[PSUBSET] THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[]; ASM_MESON_TAC[]]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `CARD(B:A->bool)`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`mt:A->A->bool`; `sc:A->int`; `B:A->bool`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `MB:A->bool`
    (X_CHOOSE_THEN `qB:A->A` STRIP_ASSUME_TAC)) THEN
  EXISTS_TAC `(m:A) INSERT MB` THEN
  EXISTS_TAC `\s:A. if (mt:A->A->bool) s m then m else (qB:A->A) s` THEN
  REWRITE_TAC[IN_INSERT] THEN REPEAT CONJ_TAC THENL
   [(* M SUBSET S                                                            *)
    REWRITE_TAC[SUBSET; IN_INSERT] THEN X_GEN_TAC `x:A` THEN STRIP_TAC THENL
     [ASM_REWRITE_TAC[]; ASM_MESON_TAC[SUBSET]];
    (* q s IN M                                                              *)
    X_GEN_TAC `s:A` THEN DISCH_TAC THEN COND_CASES_TAC THENL
     [REWRITE_TAC[]; DISJ2_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
      EXPAND_TAC "B" THEN ASM_REWRITE_TAC[IN_ELIM_THM]];
    (* m IN M ==> m IN S                                                     *)
    X_GEN_TAC `x:A` THEN STRIP_TAC THENL
     [ASM_REWRITE_TAC[]; ASM_MESON_TAC[SUBSET]];
    (* mt s (q s) /\ sc s <= sc(q s)                                         *)
    X_GEN_TAC `s:A` THEN DISCH_TAC THEN COND_CASES_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_SIMP_TAC[];
      SUBGOAL_THEN `(s:A) IN B` ASSUME_TAC THENL
       [EXPAND_TAC "B" THEN ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
      ASM_SIMP_TAC[]];
    (* pairwise non-meeting: m does not meet any MB member (MB SUBSET B, B   *)
    (* members don't meet m, mt symmetric); MB members pairwise don't (IH).  *)
    SUBGOAL_THEN `!x:A. x IN MB ==> ~(mt:A->A->bool) m x` ASSUME_TAC THENL
     [X_GEN_TAC `x:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(x:A) IN B` ASSUME_TAC THENL
       [ASM_MESON_TAC[SUBSET]; ALL_TAC] THEN
      UNDISCH_TAC `(x:A) IN B` THEN EXPAND_TAC "B" THEN
      REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
        ASM_MESON_TAC[]; ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`m1:A`; `m2:A`] THEN STRIP_TAC THEN
    ASM_MESON_TAC[]]);;

(* Corollary: drop the CARD parameter (Fremlin's q-map on a finite family).  *)
let GREEDY_CAPTURE = prove
 (`!(mt:A->A->bool) (sc:A->int) S.
     FINITE S /\ (!a b. mt a b ==> mt b a) /\ (!a. mt a a)
     ==> ?M q. M SUBSET S /\
               (!s. s IN S ==> q s IN M) /\
               (!m. m IN M ==> m IN S) /\
               (!s. s IN S ==> mt s (q s) /\ sc s <= sc(q s)) /\
               (!m1 m2. m1 IN M /\ m2 IN M /\ ~(m1 = m2) ==> ~mt m1 m2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`CARD(S:A->bool)`; `mt:A->A->bool`; `sc:A->int`; `S:A->bool`]
    GREEDY_CAPTURE_N) THEN
  ASM_REWRITE_TAC[]);;


(* ========================================================================= *)
(* 286J(c) geometry.  Two facts feeding the Vitali q-map measure bound       *)
(* (Fremlin mt286.tex 915-934).                                              *)
(* ========================================================================= *)

(* base-2 zpow is additive (unconditional; the general REAL_ZPOW_ADD carries *)
(* a ~(x=&0) side condition).                                                *)
let ZPOW2_ADD = prove
 (`!a b:int. &2 zpow a * &2 zpow b = &2 zpow (a + b)`,
  SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ]);;

(* Fremlin's I^(k)_{tau_l} SUBSET I^(k+2)_{tau_{q(l)}} (line 915): if the    *)
(* two k-dilates MEET and t is at least as coarse as s (tile_k t <= tile_k   *)
(* s, so I^(k)_t is at least as wide), then I^(k)_s sits inside the          *)
(* 4x-widened I^(k+2)_t. Half-widths h_s = 2^(k-k_s-1) <= h_t = 2^(k-k_t-1); *)
(* for y in I^(k)_s and a meet-point p, |y-x_t| <= |y-x_s|+|x_s-p|+|p-x_t| < *)
(* 2 h_s + h_t <= 3 h_t < 4 h_t = half-width of I^(k+2)_t.                   *)
let RK_GAMMUI_BRIDGE = prove
 (`!ktau (k:num) gam M.
     &2 zpow (&2 * &k - &9) * gam <= &2 zpow ktau * M
     ==> gam * &2 zpow (--ktau) <= &2 zpow (&9 - &2 * &k) * M`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`&2 zpow (--ktau) * &2 zpow (&9 - &2 * &k)`;
                 `&2 zpow (&2 * &k - &9) * gam`;
                   `&2 zpow ktau * M`] REAL_LE_LMUL) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THEN
      MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(&2 zpow (--ktau) * &2 zpow (&9 - &2 * &k)) * &2 zpow (&2 * &k - &9) * gam
     =
    gam * &2 zpow (--ktau) /\
    (&2 zpow (--ktau) * &2 zpow (&9 - &2 * &k)) * &2 zpow ktau * M =
    &2 zpow (&9 - &2 * &k) * M`
   (fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [ONCE_REWRITE_TAC[REAL_ARITH `(a * b) * c * gam = gam * (a * (b * c)):real`]
     THEN
    REWRITE_TAC[ZPOW2_ADD] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
      INT_ARITH_TAC;
    ONCE_REWRITE_TAC[REAL_ARITH `(a * b) * c * M = b * (a * c) * M:real`] THEN
    REWRITE_TAC[ZPOW2_ADD] THEN
    SUBGOAL_THEN `--ktau + ktau = &0:int` SUBST1_TAC THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_ZPOW_0; REAL_MUL_LID]]);;


(* ========================================================================= *)
(* 286J(c) measure bricks.                                                   *)
(* ========================================================================= *)

(* Sum of measures of a pairwise-disjoint finite family of measurable        *)
(* subsets of a measurable E is at most muE (mu(UNIONS)=sum via              *)
(* DISJOINT_UNIONS_IMAGE, UNIONS SUBSET E monotone).                         *)
let SUM_MEASURE_DISJOINT_LE = prove
 (`!(f:A->real->bool) S E.
     FINITE S /\ real_measurable E /\
     (!x. x IN S ==> real_measurable (f x) /\ (f x) SUBSET E) /\
     (!x y. x IN S /\ y IN S /\ ~(x = y) ==> DISJOINT (f x) (f y))
     ==> sum S (\x. real_measure (f x)) <= real_measure E`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:A->real->bool`; `S:A->bool`]
    REAL_MEASURE_DISJOINT_UNIONS_IMAGE) THEN
  ASM_SIMP_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_MEASURE_SUBSET THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_UNIONS THEN
    ASM_SIMP_TAC[FINITE_IMAGE; FORALL_IN_IMAGE];
    ASM_REWRITE_TAC[];
    REWRITE_TAC[UNIONS_SUBSET; FORALL_IN_IMAGE] THEN ASM_SIMP_TAC[]]);;



(* ========================================================================= *)
(* 286J(c) ABSTRACT per-k bound (Fremlin mt286.tex 927-934). Given the       *)
(* greedy                                                                    *)
(* capture data -- roots M SUBSET Rk, capture map q:Rk->M -- and the         *)
(* geometric                                                                 *)
(* + measure facts (each I_t inside the coarse container Ione4(q t); the I_t *)
(* pairwise disjoint; each container measure = 2^{k+2} muI_m; the R_k        *)
(* threshold                                                                 *)
(* gam muI_m <= 2^{9-2k} muS_m; the S_m pairwise disjoint subsets of E), we  *)
(* get                                                                       *)
(*   gam * sum_{Rk} muI  <=  2^{11-k} muE.                                   *)
(* Chain: regroup sum_{Rk} muI = sum_{M} sum_{fiber} muI [SUM_GROUP]; per    *)
(* fiber                                                                     *)
(* <= muIone4(q=m) = 2^{k+2} muI_m [SUM_MEASURE_DISJOINT_LE]; so gam*sum <=  *)
(* 2^{k+2} sum_M gam muI_m <= 2^{k+2} 2^{9-2k} sum_M muS_m <=                *)
(* 2^{k+2}2^{9-2k}muE.                                                       *)
(* ========================================================================= *)
let CARLESON_RK_MEASURE_ABSTRACT = prove
 (`!(Rk:A->bool) (M:A->bool) (q:A->A) (Ione:A->real->bool)
   (Ione4:A->real->bool)
    (Sset:A->real->bool) (muI:A->real) (k:num) gam E.
     FINITE Rk /\ real_measurable E /\ &0 <= gam /\
     (!t. t IN Rk ==> q t IN M) /\ M SUBSET Rk /\
     (!t. t IN Rk ==> Ione t SUBSET Ione4 (q t)) /\
     (!t1 t2. t1 IN Rk /\ t2 IN Rk /\ q t1 = q t2 /\ ~(t1 = t2)
              ==> DISJOINT (Ione t1) (Ione t2)) /\
     (!t. t IN Rk ==> real_measurable (Ione t) /\ real_measure(Ione t) = muI t)
       /\
     (!m. m IN M ==> real_measurable(Ione4 m) /\
                     real_measure(Ione4 m) = &2 zpow (&k + &2) * muI m) /\
     (!m. m IN M ==> gam * muI m <= &2 zpow (&9 - &2 * &k) * real_measure(Sset
       m)) /\
     (!m. m IN M ==> real_measurable(Sset m) /\ Sset m SUBSET E) /\
     (!m1 m2. m1 IN M /\ m2 IN M /\ ~(m1 = m2) ==> DISJOINT (Sset m1) (Sset
       m2))
     ==> gam * sum Rk muI <= &2 zpow (&11 - &k) * real_measure E`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`q:A->A`; `muI:A->real`; `Rk:A->bool`;
    `M:A->bool`] SUM_GROUP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN
     ASM_SIMP_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  (* per-fiber: sum {t | q t = m} muI <= 2^{k+2} muI m                       *)
  SUBGOAL_THEN
   `!m:A. m IN M ==> sum {x:A | x IN Rk /\ q x = m} muI
                     <= &2 zpow (&k + &2) * muI m`
   ASSUME_TAC THENL
   [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `real_measure(Ione4(m:A)) = &2 zpow (&k + &2) * muI m`
     (SUBST1_TAC o SYM) THENL [ASM_SIMP_TAC[]; ALL_TAC] THEN
    (* first: the measure-form fiber bound (matches SUM_MEASURE_DISJOINT_LE) *)
    SUBGOAL_THEN
     `sum {x:A | x IN Rk /\ q x = m} (\x. real_measure(Ione x:real->bool))
      <= real_measure(Ione4(m:A))`
     MP_TAC THENL
     [MATCH_MP_TAC SUM_MEASURE_DISJOINT_LE THEN
      ASM_SIMP_TAC[FINITE_RESTRICT] THEN CONJ_TAC THENL
       [X_GEN_TAC `t:A` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
        CONJ_TAC THENL
         [ASM_SIMP_TAC[];
          FIRST_X_ASSUM(SUBST1_TAC o SYM o
            check(fun th -> is_eq(concl th) &&
                            rand(concl th) = `m:A`)) THEN
          FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
        MAP_EVERY X_GEN_TAC [`t1:A`; `t2:A`] THEN REWRITE_TAC[IN_ELIM_THM] THEN
        STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[]];
      ALL_TAC] THEN
    (* convert the summand muI -> real_measure o Ione via SUM_EQ             *)
    MATCH_MP_TAC(REAL_ARITH `s = s2 ==> s2 <= b ==> s <= b`) THEN
    MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `t:A` THEN
    REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  (* gam * sum_M fiber <= gam * sum_M 2^{k+2} muI m                          *)
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `gam * sum M (\m:A. &2 zpow (&k + &2) * muI m)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SUM_LE THEN CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `Rk:A->bool` THEN
      ASM_REWRITE_TAC[]; ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* regroup gam * sum_M 2^{k+2} muI = 2^{k+2} * (gam * sum_M muI)           *)
  REWRITE_TAC[SUM_LMUL] THEN
  (* key: gam * sum_M muI <= 2^{9-2k} muE                                    *)
  SUBGOAL_THEN
    `gam * sum M (muI:A->real) <= &2 zpow (&9 - &2 * &k) * real_measure E`
   ASSUME_TAC THENL
   [REWRITE_TAC[GSYM SUM_LMUL] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `sum M (\m:A. &2 zpow (&9 - &2 * &k) * real_measure(Sset m))`
      THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUM_LE THEN CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `Rk:A->bool` THEN
        ASM_REWRITE_TAC[]; ASM_SIMP_TAC[]];
      REWRITE_TAC[SUM_LMUL] THEN MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
        MATCH_MP_TAC SUM_MEASURE_DISJOINT_LE THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `Rk:A->bool` THEN
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  (* gam * 2^{k+2} * sum muI = 2^{k+2} * (gam * sum muI) <= 2^{k+2} 2^{9-2k} *)
  (* muE                                                                     *)
  SUBGOAL_THEN `gam * &2 zpow (&k + &2) * sum M (muI:A->real) =
                &2 zpow (&k + &2) * (gam * sum M muI)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_MUL_AC]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 zpow (&k + &2) * (&2 zpow (&9 - &2 * &k) * real_measure E)`
    THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
    REWRITE_TAC[REAL_MUL_ASSOC; ZPOW2_ADD] THEN
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    AP_TERM_TAC THEN INT_ARITH_TAC]);;


(* ========================================================================= *)
(* 286J(c) base-interval containment (Fremlin mt286.tex 915-916), valid for  *)
(* ALL k >= 0 (Fremlin's R_k has k in N, so the m=0 / R_0 case must be       *)
(* covered                                                                   *)
(* -- TILE_I_SUBSET_IDIL needs k >= 1, so we prove the composed containment  *)
(* I_t SUBSET I^(k+2)_r directly from the level-k meet, using the base       *)
(* band).                                                                    *)
(* ========================================================================= *)

(* y in the base cell I_t is within half its width of the centre x_t.        *)
let TILE_I_BAND = prove
 (`!(a:int) (b:int) (c:int) y.
     y IN tile_I(a,b,c) ==> abs(y - tile_xmid(a,b,c)) <= &2 zpow (--a - &1)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[tile_I; tile_xmid; dyho; dyho_mid; IN_ELIM_THM] THEN
    STRIP_TAC THEN
  SUBGOAL_THEN `&2 zpow (--a) = &2 zpow (--a - &1) * &2` ASSUME_TAC THENL
   [SIMP_TAC[REAL_ZPOW_SUB; REAL_OF_NUM_EQ; ARITH_EQ; REAL_ZPOW_1] THEN
    CONV_TAC REAL_FIELD; ALL_TAC] THEN
  ABBREV_TAC `P = &2 zpow (--a)` THEN ABBREV_TAC `H = &2 zpow (--a - &1)` THEN
  SUBGOAL_THEN
    `(real_of_int b + &1 / &2) * P = real_of_int b * P + H` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* tile-form of the band (t as an abstract tile).                            *)
let TILE_I_BAND_TILE = prove
 (`!(t:int#int#int) y.
     y IN tile_I t ==> abs(y - tile_xmid t) <= &2 zpow (--(tile_k t) - &1)`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!a b c. P((a,b,c):int#int#int)) ==> (!s. P s)`) THEN
  REWRITE_TAC[tile_k; TILE_I_BAND]);;

(* Base containment for ALL k: level-k meet + coarser root r => I_t SUBSET   *)
(* I^(k+2)_r. half-widths: base of I_t is 2^{-k_t-1} <= 2^{k-k_t-1} (the     *)
(* level-k                                                                   *)
(* half-width, k>=0); the meet + coarser gives centres within 2h_r; target   *)
(* 2^{k+2-k_r-1}=4 h_r absorbs 2h_t + h_r <= 3 h_r.                          *)
let TILE_I_SUBSET_IDIL4_ALLK = prove
 (`!(t:int#int#int) (r:int#int#int) k.
     tile_k r <= tile_k t /\ ~(tile_Idil t k INTER tile_Idil r k = {})
     ==> tile_I t SUBSET tile_Idil r (k + 2)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [GSYM MEMBER_NOT_EMPTY]) THEN
  REWRITE_TAC[IN_INTER; tile_Idil; IN_ELIM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:real` STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `y:real` THEN DISCH_TAC THEN
  REWRITE_TAC[tile_Idil; IN_ELIM_THM] THEN
  (* base band on y: |y - x_t| <= 2^{-k_t-1}                                 *)
  SUBGOAL_THEN
    `abs(y - tile_xmid t) <= &2 zpow (--(tile_k t) - &1)` MP_TAC THENL
   [ASM_SIMP_TAC[TILE_I_BAND_TILE]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* half-width facts: 2^{-k_t-1} <= 2^{k-k_t-1}, 2^{k-k_t-1} <= 2^{k-k_r-1} *)
  SUBGOAL_THEN `&2 zpow (--(tile_k t) - &1) <= &2 zpow (&k - tile_k t - &1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ZPOW2_MONOE THEN INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow (&k - tile_k t - &1) <= &2 zpow (&k - tile_k r - &1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  (* target half-width = 4 * 2^{k-k_r-1}                                     *)
  SUBGOAL_THEN `&2 zpow (&(k + 2) - tile_k r - &1) =
                &4 * &2 zpow (&k - tile_k r - &1)`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM INT_OF_NUM_ADD] THEN
    SUBGOAL_THEN `(&k + &2) - tile_k r - &1 = (&k - tile_k r - &1) + &2:int`
     SUBST1_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
    SIMP_TAC[REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ] THEN
    REWRITE_TAC[REAL_ZPOW_NUM] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

let CWTILE_SQ_INTEGRABLE_MEASURABLE = prove
 (`!s Sc. real_measurable Sc ==> (\x. (cw_tile s x) pow 2) real_integrable_on
   Sc`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\x. (&2 zpow tile_k s) pow 2):real->real` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_POW THEN
      REWRITE_TAC[ETA_AX; CWTILE_CONTINUOUS];
    MATCH_MP_TAC REAL_INTEGRABLE_ON_CONST_MEASURABLE THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[REAL_ABS_POW] THEN
    MATCH_MP_TAC REAL_POW_LE2 THEN
    MP_TAC(SPECL [`s:int#int#int`; `x:real`] CWTILE_BOUNDS) THEN
      REAL_ARITH_TAC]);;

let CWTILE_MIDPOINT_LOWER = prove
 (`!(s:int#int#int) a b. a < b /\ (tile_xmid s <= a \/ b <= tile_xmid s)
     ==> cw_tile s ((a + b) / &2) * (b - a) <=
         real_integral (real_interval[a,b]) (cw_tile s)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC HERMITE_HADAMARD_LOWER THEN
  ASM_SIMP_TAC[REAL_LT_IMP_LE; CWTILE_INTEGRABLE] THENL
   [MATCH_MP_TAC CWTILE_CONVEX_RIGHT THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC CWTILE_CONVEX_LEFT THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286G(e), analytic crux: the cross-tile weight correlation.                *)
(*                                                                           *)
(* When k_sigma <= k_tau, the whole-line correlation of the two tile weight  *)
(* profiles is controlled by the larger (coarser) weight sampled at the      *)
(* finer tile's centre:  INT_R w_sigma w_tau <= 16 w_sigma(x_tau).           *)
(* Via the change of variables u = 2^k_tau (x - x_tau), this reduces to the  *)
(* convolution bound CW_CONVOLUTION_GEN with contraction alpha = 2^(k_s-k_t) *)
(* in (0,1] and offset beta = 2^k_s (x_tau - x_sigma).                       *)
(* ------------------------------------------------------------------------- *)

let SCALE_INV_ID = prove
 (`!ks kt iI. ~(kt = &0) ==> (ks * kt) * (inv kt * iI) = ks * iI`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `kt:real` REAL_MUL_RINV) THEN ASM_REWRITE_TAC[] THEN
  CONV_TAC REAL_RING);;
let CW_CROSS_ABSTRACT = prove
 (`!ks kt xs xt.
     &0 < ks /\ &0 < kt /\ ks <= kt
     ==> real_integral (:real)
           (\x. (ks * cw(ks * (x - xs))) * (kt * cw(kt * (x - xt))))
         <= &16 * (ks * cw(ks * (xt - xs)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`ks * inv kt:real`;
    `ks * (xt - xs):real`] CW_CONVOLUTION_GEN) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[REAL_LT_INV_EQ];
      SUBGOAL_THEN `ks * inv kt <= kt * inv kt` MP_TAC THENL
       [MATCH_MP_TAC REAL_LE_RMUL THEN
         ASM_SIMP_TAC[REAL_LE_INV_EQ; REAL_LT_IMP_LE];
        ASM_SIMP_TAC[REAL_MUL_RINV; REAL_LT_IMP_NZ]]];
    DISCH_TAC] THEN
  ABBREV_TAC `iI = real_integral (:real)
       (\x. cw x * cw((ks * inv kt) * x + ks * (xt - xs)))` THEN
  SUBGOAL_THEN
   `((\x. cw x * cw((ks * inv kt) * x + ks * (xt - xs))) has_real_integral iI)
     (:real)`
   ASSUME_TAC THENL
   [EXPAND_TAC "iI" THEN
    MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN REWRITE_TAC[CW_PROD_INTEGRABLE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((\x. cw(kt * (x - xt)) * cw(ks * (x - xs))) has_real_integral (inv kt *
     iI)) (:real)`
   ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(\x. (\y:real. cw y * cw((ks * inv kt) * y + ks * (xt - xs)))
           (kt * x + --(kt * xt)))
      = (\x. cw(kt * (x - xt)) * cw(ks * (x - xs)))`
     (fun th -> SUBST1_TAC(SYM th)) THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN BETA_TAC THEN X_GEN_TAC `x:real` THEN
      BINOP_TAC THENL
       [AP_TERM_TAC THEN REAL_ARITH_TAC;
        AP_TERM_TAC THEN MAP_EVERY UNDISCH_TAC [`&0 < kt`] THEN
          CONV_TAC REAL_FIELD];
      ALL_TAC] THEN
    SUBGOAL_THEN `inv kt * iI = inv(abs kt) * iI` SUBST1_TAC THENL
     [ASM_SIMP_TAC[REAL_ARITH `&0 < kt ==> abs kt = kt`]; ALL_TAC] THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_AFFINITY_UNIV THEN
      ASM_SIMP_TAC[REAL_LT_IMP_NZ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (:real)
       (\x. (ks * cw(ks * (x - xs))) * (kt * cw(kt * (x - xt))))
    = (ks * kt) * (inv kt * iI)` SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
    SUBGOAL_THEN
     `(\x. (ks * cw(ks * (x - xs))) * (kt * cw(kt * (x - xt))))
      = (\x. (ks * kt) * (cw(kt * (x - xt)) * cw(ks * (x - xs))))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC HAS_REAL_INTEGRAL_LMUL THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[SCALE_INV_ID; REAL_LT_IMP_NZ] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `ks * &16 * cw (ks * (xt - xs))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE];
    REAL_ARITH_TAC]);;

let CWTILE_CROSS = prove
 (`!(s:int#int#int) (t:int#int#int).
     tile_k s <= tile_k t
     ==> real_integral (:real) (\x. cw_tile s x * cw_tile t x)
         <= &16 * cw_tile s (tile_xmid t)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[cw_tile] THEN
  MP_TAC(SPECL
    [`&2 zpow tile_k s`; `&2 zpow tile_k t`;
     `tile_xmid s`; `tile_xmid t`] CW_CROSS_ABSTRACT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
      MATCH_MP_TAC ZPOW2_MONOE THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286G(e), the inner-product form: the cross-tile CORRELATION of the tile   *)
(* test functions. This is the analytic keystone 286I/286J/286L all rest on. *)
(*                                                                           *)
(*   |(phi_sigma | phi_tau)| <= C 2^(-k_s/2) 2^(-k_t/2) w_sigma(x_tau)       *)
(* (when k_s <= k_t).                                                        *)
(*                                                                           *)
(* Route: norm(INT phi_s cnj phi_t) <= INT norm(phi_s) norm(phi_t)           *)
(* (INTEGRAL_NORM_BOUND_INTEGRAL) <= C1^2 2^(-k_s/2) 2^(-k_t/2) INT w_s w_t  *)
(* (PHISIG_CW pointwise, twice) <= C1^2 2^(-k_s/2) 2^(-k_t/2) 16 w_s(x_t)    *)
(* (CWTILE_CROSS).  The 2^(k_t/2) INT_{I_t} w_s form Fremlin states then     *)
(* follows at the mass/energy stage via CWTILE_MIDPOINT_LOWER (286G b).      *)
(* ------------------------------------------------------------------------- *)

(* phi_sigma of the concrete base test function is Schwartz.                 *)
let PHISIG_CARLESON_SCHWARTZ = prove
 (`!(s:int#int#int). schwartz (phi_sigma s carleson_phi)`,
  GEN_TAC THEN MATCH_MP_TAC PHISIG_SCHWARTZ THEN
    REWRITE_TAC[CARLESON_PHI_SCHWARTZ]);;

(* The phi_sigma Sc-conditions (i, iv) of CARLESON_ALPHA_SCALE.  phi_sigma s *)
(* carleson_phi is Schwartz (PHISIG_CARLESON_SCHWARTZ), hence continuous and *)
(* bounded                                                                   *)
(* (SCHWARTZ_CONT / SCHWARTZ_BOUNDED); so norm(phi_sigma) is                 *)
(* real-integrable, and                                                      *)
(* phi_sigma itself is absolutely integrable, on any real-measurable Sc.     *)
(* Same                                                                      *)
(* bounded-measurable route as cw_tile (must come AFTER                      *)
(* PHISIG_CARLESON_SCHWARTZ).                                                *)
let PHISIG_NORM_INTEGRABLE_MEASURABLE = prove
 (`!s Sc. real_measurable Sc
      ==> (\x. norm(phi_sigma s carleson_phi x)) real_integrable_on Sc`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `phi_sigma s carleson_phi` SCHWARTZ_BOUNDED) THEN
  REWRITE_TAC[PHISIG_CARLESON_SCHWARTZ] THEN
  DISCH_THEN(X_CHOOSE_TAC `B:real`) THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\x. B):real->real` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
    REWRITE_TAC[IMAGE_LIFT_UNIV; REAL_CONTINUOUS_ON; o_DEF] THEN
    REWRITE_TAC[IMAGE_LIFT_UNIV] THEN
    MATCH_MP_TAC CONTINUOUS_ON_LIFT_NORM_COMPOSE THEN
    MP_TAC(ISPEC `phi_sigma s carleson_phi` SCHWARTZ_CONT) THEN
    REWRITE_TAC[PHISIG_CARLESON_SCHWARTZ];
    MATCH_MP_TAC REAL_INTEGRABLE_ON_CONST_MEASURABLE THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN DISCH_TAC THEN ASM_SIMP_TAC[REAL_ABS_NORM]]);;

let PHISIG_ABS_INTEGRABLE_MEASURABLE = prove
 (`!s Sc. real_measurable Sc
      ==> (\z. phi_sigma s carleson_phi (drop z)) absolutely_integrable_on
          (IMAGE lift Sc)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `phi_sigma s carleson_phi` SCHWARTZ_BOUNDED) THEN
  REWRITE_TAC[PHISIG_CARLESON_SCHWARTZ] THEN
  DISCH_THEN(X_CHOOSE_TAC `B:real`) THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC `(\z:real^1. lift B)` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_MEASURABLE_SUBSET THEN
     EXISTS_TAC `(:real^1)` THEN
    REWRITE_TAC[SUBSET_UNIV; GSYM REAL_MEASURABLE_MEASURABLE] THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    MP_TAC(ISPEC `phi_sigma s carleson_phi` SCHWARTZ_CONT) THEN
    REWRITE_TAC[PHISIG_CARLESON_SCHWARTZ];
    REWRITE_TAC[INTEGRABLE_ON_CONST] THEN DISJ2_TAC THEN
    ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE];
    X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN ASM_REWRITE_TAC[LIFT_DROP]]);;

(* --- 286L Sc-domain MEASURABILITY (the last prerequisite for the Sc-conds) *)
(* ---                                                                       *)

(* The preimage h^-1[dyho k n] of a dyadic interval under a measurable h is  *)
(* real-lebesgue-measurable. dyho k n = {y | c <= y < d}, so the preimage is *)
(* the                                                                       *)
(* INTER of two halfspace preimages (h x >= c) and (h x < d).                *)
let H_PREIMAGE_DYHO_LEBESGUE = prove
 (`!(h:real->real) k n. h real_measurable_on (:real)
      ==> real_lebesgue_measurable {x | h x IN dyho k n}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN
  SUBGOAL_THEN
   `{x | real_of_int n * &2 zpow k <= (h:real->real) x /\
         h x < (real_of_int n + &1) * &2 zpow k} =
    {x | (h:real->real) x >= real_of_int n * &2 zpow k} INTER
    {x | (h:real->real) x < (real_of_int n + &1) * &2 zpow k}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN GEN_TAC THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN
  CONJ_TAC THEN FIRST_ASSUM MP_TAC THENL
   [REWRITE_TAC[REAL_MEASURABLE_ON_PREIMAGE_HALFSPACE_GE] THEN
    DISCH_THEN(ACCEPT_TAC o SPEC `real_of_int n * &2 zpow k`);
    REWRITE_TAC[REAL_MEASURABLE_ON_PREIMAGE_HALFSPACE_LT] THEN
    DISCH_THEN(ACCEPT_TAC o SPEC `(real_of_int n + &1) * &2 zpow k`)]);;

(* THE Sc-domain measurability: Sc = {x | x IN E /\ h x IN tile_J s} INTER   *)
(* dyho a p is real-measurable, given E real-lebesgue-measurable and h       *)
(* real-measurable. Sc SUBSET dyho a p is bounded; Sc = E INTER h^-1[tile_J  *)
(* s] INTER dyho a p is a triple INTER of lebesgue-measurable sets; bounded  *)
(* + lebesgue => measurable.                                                 *)
let SC_MEASURABLE = prove
 (`!(h:real->real) E s a p.
      real_lebesgue_measurable E /\ h real_measurable_on (:real)
      ==> real_measurable ({x | x IN E /\ h x IN tile_J s} INTER dyho a p)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `real_bounded ({x | x IN E /\
     (h:real->real) x IN tile_J s} INTER dyho a p)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_BOUNDED_SUBSET THEN
    EXISTS_TAC `real_interval[real_of_int p * &2 zpow a,
                              (real_of_int p + &1) * &2 zpow a]` THEN
    REWRITE_TAC[REAL_BOUNDED_REAL_INTERVAL] THEN
    REWRITE_TAC[SUBSET; IN_INTER; dyho; IN_ELIM_THM; IN_REAL_INTERVAL] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM REAL_LEBESGUE_MEASURABLE_IFF_MEASURABLE] THEN
  SUBGOAL_THEN
   `{x | x IN E /\ (h:real->real) x IN tile_J s} INTER dyho a p =
    (E INTER {x | (h:real->real) x IN tile_J s}) INTER dyho a p`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
     MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN ASM_REWRITE_TAC[] THEN
    SPEC_TAC(`s:int#int#int`,`s:int#int#int`) THEN
    REWRITE_TAC[FORALL_PAIR_THM; tile_J] THEN REPEAT GEN_TAC THEN
    MATCH_MP_TAC H_PREIMAGE_DYHO_LEBESGUE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
    REWRITE_TAC[DYHO_MEASURABLE]]);;

(* General Sc-measurability with an arbitrary dyadic frequency interval dyho *)
(* kk nn                                                                     *)
(* (the alpha_sK domain uses the RIGHT HALF tile_Jr, a dyho-cell --          *)
(* SC_MEASURABLE                                                             *)
(* above is stated for tile_J).  Same bounded + triple-lebesgue-INTER route. *)
let SC_MEASURABLE_DYHO = prove
 (`!(h:real->real) E kk nn a p.
      real_lebesgue_measurable E /\ h real_measurable_on (:real)
      ==> real_measurable ({x | x IN E /\ h x IN dyho kk nn} INTER dyho a p)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `real_bounded ({x | x IN E /\
     (h:real->real) x IN dyho kk nn} INTER dyho a p)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_BOUNDED_SUBSET THEN
    EXISTS_TAC `real_interval[real_of_int p * &2 zpow a,
                              (real_of_int p + &1) * &2 zpow a]` THEN
    REWRITE_TAC[REAL_BOUNDED_REAL_INTERVAL] THEN
    REWRITE_TAC[SUBSET; IN_INTER; dyho; IN_ELIM_THM; IN_REAL_INTERVAL] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM REAL_LEBESGUE_MEASURABLE_IFF_MEASURABLE] THEN
  SUBGOAL_THEN
   `{x | x IN E /\ (h:real->real) x IN dyho kk nn} INTER dyho a p =
    (E INTER {x | (h:real->real) x IN dyho kk nn}) INTER dyho a p`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
     MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC H_PREIMAGE_DYHO_LEBESGUE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
    REWRITE_TAC[DYHO_MEASURABLE]]);;

(* tile_Jr corollary: the right-half domain is measurable.                   *)
let SC_MEASURABLE_JR = prove
 (`!(h:real->real) E s a p.
      real_lebesgue_measurable E /\ h real_measurable_on (:real)
      ==> real_measurable ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p)`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_Jr] THEN REPEAT STRIP_TAC THEN
  MATCH_MP_TAC SC_MEASURABLE_DYHO THEN ASM_REWRITE_TAC[]);;

(* --- K1 (finite-cover reduction) foundational bricks ---                   *)
(* K1a: phi_sigma is absolutely integrable on the lift of ANY real-lebesgue- *)
(* measurable set (even unbounded / infinite-measure), since phi_sigma is    *)
(* Schwartz hence L^1 on the whole line (SCHWARTZ_ABSINT) and a lebesgue-    *)
(* measurable subset of an absolutely-integrable domain inherits it. This is *)
(* the                                                                       *)
(* unbounded-region companion to PHISIG_ABS_INTEGRABLE_MEASURABLE (which     *)
(* needs                                                                     *)
(* FINITE measure). Needed so the full-region tile integral int_{E cap       *)
(* h^-1[Jr]}                                                                 *)
(* phi_s makes sense and admits the countable cover-decomposition.           *)
let PHISIG_ABSINT_LEBESGUE = prove
 (`!s Sc. real_lebesgue_measurable Sc
      ==> (\z. phi_sigma s carleson_phi (drop z)) absolutely_integrable_on
        (IMAGE lift Sc)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `(:real^1)` THEN
  REWRITE_TAC[SUBSET_UNIV] THEN CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_ABSINT THEN
     REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    ASM_REWRITE_TAC[GSYM REAL_LEBESGUE_MEASURABLE]]);;

(* K1b: the full tile region {x | x IN E /\ h x IN tile_Jr s} is             *)
(* real-lebesgue- measurable (E leb-meas INTER the h-preimage of the dyadic  *)
(* cell tile_Jr).                                                            *)
let REGION_LEBESGUE = prove
 (`!(E:real->bool) (h:real->real) s.
      real_lebesgue_measurable E /\ h real_measurable_on (:real)
      ==> real_lebesgue_measurable {x | x IN E /\ h x IN tile_Jr s}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `k:int` (X_CHOOSE_THEN
    `sn:int#int` SUBST1_TAC)) THEN
  MP_TAC(ISPEC `sn:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `nI:int` (X_CHOOSE_THEN `nJ:int` SUBST1_TAC)) THEN
  REWRITE_TAC[tile_Jr] THEN
  SUBGOAL_THEN
   `{x | x IN E /\ (h:real->real) x IN dyho (k - &1) (&2 * nJ + &1)} =
    E INTER {x | h x IN dyho (k - &1) (&2 * nJ + &1)}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC H_PREIMAGE_DYHO_LEBESGUE THEN ASM_REWRITE_TAC[]);;

(* K1c: the cover-index set {(a,p) | in_kcover P a p} is COUNTABLE (a subset *)
(* of int#int), and the cover cells UNION to the whole line (covering,       *)
(* KCOVER_EXISTS). These feed the countable cover-decomposition int_{region} *)
(* phi = lim of the finite partial covers (INTEGRAL_COUNTABLE_UNIONS_ALT)    *)
(* used in K1's limit-passing.                                               *)
let KCOVER_INDEX_COUNTABLE = prove
 (`!P:(int#int#int)->bool. COUNTABLE {ap:int#int | in_kcover P (FST ap) (SND
   ap)}`,
  GEN_TAC THEN MATCH_MP_TAC COUNTABLE_SUBSET THEN
  EXISTS_TAC `(:int#int)` THEN REWRITE_TAC[SUBSET_UNIV] THEN
  REWRITE_TAC[GSYM CROSS_UNIV] THEN MATCH_MP_TAC COUNTABLE_CROSS THEN
  REWRITE_TAC[INT_COUNTABLE]);;

let KCOVER_UNIONS_UNIV = prove
 (`!P:(int#int#int)->bool. FINITE P /\ ~(P = {})
     ==> UNIONS {dyho (FST ap) (SND ap) | ap IN {ap:int#int | in_kcover P (FST
       ap) (SND ap)}}
         = (:real)`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[EXTENSION; IN_UNIV; IN_UNIONS; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real` THEN
  MP_TAC(ISPEC `P:(int#int#int)->bool` KCOVER_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `x:real`) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int` (X_CHOOSE_THEN
    `q:int` STRIP_ASSUME_TAC)) THEN
  EXISTS_TAC `dyho a q` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `(a:int,q:int)` THEN REWRITE_TAC[IN_ELIM_THM] THEN
  ASM_REWRITE_TAC[]);;

(* 286L(e) near-complete: the inner set E cap h^-1[J_ups] cap K has measure  *)
(* <=                                                                        *)
(* 2 * 2^a * mass/w(3/2) = 2 gamma' mu K/w(3/2). Assembles GK_WEIGHT_ON_K    *)
(* (w_ups >=                                                                 *)
(* w(3/2)/(2*2^a) on K), MASS_TERM_LE_GEN (int_{E cap h^-1[J_ups]} w_ups <=  *)
(* mass), the                                                                *)
(* subset step int_A <= int_full (REAL_INTEGRAL_SUBSET_LE, cw_tile > 0),     *)
(* SC_MEASURABLE +                                                           *)
(* CWTILE_INTEGRABLE_MEASURABLE (A measurable + w_ups integrable), via       *)
(* GK_INNER_MEASURE.                                                         *)
let GK_INNER_MEASURE_BOUND = prove
 (`!(ups:int#int#int) (sig:int#int#int) E h P a p.
     tile_k ups = --(a + &1) /\ tile_le sig ups /\ sig IN P /\
     tile_I sig SUBSET dyho_star (a + &1) (p div &2) /\
     real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> real_measure ({x | x IN E /\ h x IN tile_J ups} INTER dyho a p)
         <= &2 * &2 zpow a * mass_Eh E h P / cw(&3 / &2)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC GK_INNER_MEASURE THEN EXISTS_TAC `ups:int#int#int` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC SC_MEASURABLE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN
      MATCH_MP_TAC SC_MEASURABLE THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_INTER; IN_ELIM_THM] THEN
      STRIP_TAC THEN
    MATCH_MP_TAC GK_WEIGHT_ON_K THEN
    MAP_EVERY EXISTS_TAC [`sig:int#int#int`; `p:int`] THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral {x | x IN E /\ h x IN tile_J ups} (cw_tile ups)`
      THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN REPEAT CONJ_TAC THENL
       [SET_TAC[];
        MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN
          MATCH_MP_TAC SC_MEASURABLE THEN
        ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[];
        REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
          REWRITE_TAC[CW_TILE_POS]];
      MATCH_MP_TAC MASS_TERM_LE_GEN THEN EXISTS_TAC `sig:int#int#int` THEN
      ASM_REWRITE_TAC[]]]);;

(* 286L(e) at the COVER level (stated purely from in_kcover): for a cover    *)
(* cell dyho a p                                                             *)
(* whose parent is coarser than tau (W2 case 2^{a+1} <= 2^{-k_tau}, i.e. 2   *)
(* mu K <=                                                                   *)
(* mu I_tau), with tau a lower bound of P (tile_le s tau for all s in P),    *)
(* there is an                                                               *)
(* interpolated upsilon whose inner set E cap h^-1[J_ups] cap K has measure  *)
(* <= 2 gamma'                                                               *)
(* mu K/w(3/2). Wraps KCOVER_PARENT_WITNESS (sigma) + GK_UPSILON (upsilon) + *)
(* GK_INNER_MEASURE_BOUND. This is the G_K-measure input to the alpha2 int   *)
(* v2 estimate.                                                              *)
let GK_MEASURE_BOUND_STRONG = prove
 (`!(P:(int#int#int)->bool) E h a p tau.
     in_kcover P a p /\ (!s. s IN P ==> tile_le s tau) /\
     &2 zpow (a + &1) <= &2 zpow (--(tile_k tau)) /\
     real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> ?ups. tile_le ups tau /\ tile_k ups = --(a + &1) /\
               real_measure ({x | x IN E /\ h x IN tile_J ups} INTER dyho a p)
               <= &2 * &2 zpow a * mass_Eh E h P / cw(&3 / &2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`; `a:int`;
    `p:int`] KCOVER_PARENT_WITNESS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN
    `sig:int#int#int` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`; `a:int`; `p:int`; `sig:int#int#int`;
    `tau:int#int#int`]
    GK_UPSILON) THEN
  ASM_SIMP_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN
    `ups:int#int#int` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `ups:int#int#int` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC GK_INNER_MEASURE_BOUND THEN
  EXISTS_TAC `sig:int#int#int` THEN ASM_REWRITE_TAC[]);;

(* --- 286L(c) alpha0 CAPSTONE: the per-scale cover-cell bound ---           *)
(* Instantiates CARLESON_ALPHA_SCALE at the cover cell dyho a p (in_kcover P *)
(* a p)                                                                      *)
(* with q = p*M, M = 2^{a+k}, Sc s = E cap h^-1[J_s^r] cap dyho a p. Every   *)
(* ALPHA_                                                                    *)
(* SCALE hypothesis is discharged from the cover: outside-span               *)
(* (KCOVER_TILE_OUTSIDE_                                                     *)
(* SPAN), Sc SUBSET tile_J-domain (TILE_JR_SUBSET_J), Sc SUBSET k-span =     *)
(* dyho a p                                                                  *)
(* (DYHO_SPAN_INTERVAL), 4 integrability (SC_MEASURABLE_JR + the             *)
(* *_INTEGRABLE_                                                             *)
(* MEASURABLE lemmas); the cw_tile-on-h^-1[J_t] hyp is threaded. Gives the   *)
(* per-scale                                                                 *)
(* C1 2^{-k} energy mass feeding ALPHA_CELL_GEOM_SUM.                        *)
let ALPHA_CELL_PER_SCALE = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) k E h (P:(int#int#int)->bool) a p u M.
      FINITE P /\ ~(P = {}) /\ in_kcover P a p /\ --k <= a /\
      &2 zpow (a + k) = real_of_int M /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum {s | s IN P /\ tile_k s = k /\ tile_le s u}
              (\s. norm(carleson_ip f s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                     dyho a p))
                            (\z. phi_sigma s carleson_phi (drop z))))
          <= C1 * inv(&2 zpow k) * energy_f f P * mass_Eh E h P`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "AS"))
    CARLESON_ALPHA_SCALE THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= (M:int)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:int`; `k:int`; `M:int`] ZPOW_SPAN_POS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
    ALL_TAC] THEN
  USE_THEN "AS" (MP_TAC o BETA_RULE o ISPECL
   [`f:real->complex`; `k:int`; `E:real->bool`; `h:real->real`;
    `P:(int#int#int)->bool`;
    `{s | s IN P /\ tile_k s = k /\ tile_le s u}`;
    `u:int#int#int`; `p * M:int`; `M:int`;
    `\s:int#int#int. {x | x IN E /\ h x IN tile_Jr s} INTER dyho a p`]) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[FINITE_RESTRICT];
      SET_TAC[];
      MP_TAC(INT_ARITH `&1 <= (M:int) ==> &0 <= M`) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      SIMP_TAC[];
      X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`P:(int#int#int)->bool`; `a:int`; `p:int`; `k:int`;
                     `s:int#int#int`; `M:int`] KCOVER_TILE_OUTSIDE_SPAN) THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
       [MP_TAC(ISPEC `s:int#int#int` TILE_JR_SUBSET_J) THEN SET_TAC[];
        MP_TAC(ISPECL [`a:int`; `p:int`; `k:int`;
          `M:int`] DYHO_SPAN_INTERVAL) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        SET_TAC[];
        MATCH_MP_TAC PHISIG_NORM_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC CWTILE_SQ_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC PHISIG_ABS_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[]];
      ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* --- 286L(c-i) alpha1: the TIGHT per-scale-slice bound ---                 *)
(* Fremlin 286L(c-i): for a cover cell dyho a p and scale k, the scale-k     *)
(* slice of the                                                              *)
(* cell tile-set has alpha-sum <= C1 2^{-k}(1+2^{k-l})^{-2} energy mass, l = *)
(* l_K = -a.                                                                 *)
(* Here (1+2^{k-l})^{-2} = inv((1+M)^2), M = 2^{a+k} the cell's index span,  *)
(* because the                                                               *)
(* tile escapes the TRIPLED cell so its offset N >= M. Same skeleton as      *)
(* ALPHA_CELL_                                                               *)
(* PER_SCALE (instantiate at q = pM, Sc s = E cap h^-1[Jr_s] cap dyho a p)   *)
(* but calling                                                               *)
(* CARLESON_ALPHA_SCALE_TIGHT with N = num_of_int M and discharging BOTH the *)
(* span-                                                                     *)
(* exclusion (KCOVER_TILE_OFFSET_TIGHT part 1) and the offset lower bound N  *)
(* <= num_of_                                                                *)
(* int(offset) (part 2 + NUM_OF_INT_LE); the conclusion's inv((1+&N)^2)      *)
(* rewrites to                                                               *)
(* inv((1+real_of_int M)^2) via ROI_NUM_OF_INT. This extra inv((1+M)^2) =    *)
(* 2^{-2(a+k)}                                                               *)
(* decay is what makes the alpha1 double geometric series (over coarse       *)
(* levels a AND                                                              *)
(* scales k) converge -- the alpha0 loose bound would DIVERGE over the       *)
(* coarse levels.                                                            *)
let ALPHA_CELL_PER_SCALE_TIGHT = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) k E h (P:(int#int#int)->bool) a p u M.
      FINITE P /\ ~(P = {}) /\ in_kcover P a p /\ --k <= a /\
      &2 zpow (a + k) = real_of_int M /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum {s | s IN P /\ tile_k s = k /\ tile_le s u}
              (\s. norm(carleson_ip f s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                     dyho a p))
                            (\z. phi_sigma s carleson_phi (drop z))))
          <= C1 * inv(&2 zpow k) * inv((&1 + real_of_int M) pow 2) *
             energy_f f P * mass_Eh E h P`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "AST"))
    CARLESON_ALPHA_SCALE_TIGHT THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= (M:int)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:int`; `k:int`; `M:int`] ZPOW_SPAN_POS) THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&(num_of_int M) = real_of_int M` ASSUME_TAC THENL
   [MATCH_MP_TAC ROI_NUM_OF_INT THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  USE_THEN "AST" (MP_TAC o BETA_RULE o ISPECL
   [`f:real->complex`; `k:int`; `E:real->bool`; `h:real->real`;
    `P:(int#int#int)->bool`;
    `{s | s IN P /\ tile_k s = k /\ tile_le s u}`;
    `u:int#int#int`; `p * M:int`; `M:int`; `num_of_int M`;
    `\s:int#int#int. {x | x IN E /\ h x IN tile_Jr s} INTER dyho a p`]) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[FINITE_RESTRICT];
      SET_TAC[];
      MP_TAC(INT_ARITH `&1 <= (M:int) ==> &0 <= M`) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      SIMP_TAC[];
      X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`P:(int#int#int)->bool`; `a:int`; `p:int`; `k:int`;
                     `s:int#int#int`; `M:int`] KCOVER_TILE_OFFSET_TIGHT) THEN
      ASM_REWRITE_TAC[] THEN SIMP_TAC[];
      X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
      MATCH_MP_TAC NUM_OF_INT_LE THEN CONJ_TAC THENL
       [ASM_INT_ARITH_TAC;
        MP_TAC(ISPECL [`P:(int#int#int)->bool`; `a:int`; `p:int`; `k:int`;
                       `s:int#int#int`; `M:int`] KCOVER_TILE_OFFSET_TIGHT) THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]];
      X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
       [MP_TAC(ISPEC `s:int#int#int` TILE_JR_SUBSET_J) THEN SET_TAC[];
        MP_TAC(ISPECL [`a:int`; `p:int`; `k:int`;
          `M:int`] DYHO_SPAN_INTERVAL) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        SET_TAC[];
        MATCH_MP_TAC PHISIG_NORM_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC CWTILE_SQ_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC PHISIG_ABS_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[]];
      ASM_REWRITE_TAC[]];
    UNDISCH_TAC `&(num_of_int M) = real_of_int M` THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_THEN ACCEPT_TAC]);;

(* 286L(d) alpha1 per-scale-slice in CUBIC form: fold TIGHT_DECAY_BOUND into *)
(* ALPHA_CELL_                                                               *)
(* PER_SCALE_TIGHT to replace inv(2^k) inv((1+M)^2) by inv(2^{2a}) inv(8^k). *)
(* The                                                                       *)
(* inv(2^{2a}) factor is CONSTANT in k (pulls out of the coming k-sum);      *)
(* inv(8^k) is the                                                           *)
(* cubic tail summed over k >= k_tau by ABSTRACT_SCALE_GEOM_SUM8.            *)
let ALPHA_CELL1_PERSCALE_BOUND = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) k E h (P:(int#int#int)->bool) a p u M.
      FINITE P /\ ~(P = {}) /\ in_kcover P a p /\ --k <= a /\
      &2 zpow (a + k) = real_of_int M /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum {s | s IN P /\ tile_k s = k /\ tile_le s u}
              (\s. norm(carleson_ip f s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                     dyho a p))
                            (\z. phi_sigma s carleson_phi (drop z))))
          <= (C1 * energy_f f P * mass_Eh E h P * inv(&2 zpow (&2 * a))) *
            inv(&8 zpow k)`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PST"))
    ALPHA_CELL_PER_SCALE_TIGHT THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= (M:int)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`a:int`; `k:int`; `M:int`] ZPOW_SPAN_POS) THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P /\ &0 <= mass_Eh E h P`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS] THEN MATCH_MP_TAC MASS_EH_POS THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `C1 * inv(&2 zpow k) * inv((&1 + real_of_int M) pow 2) *
              energy_f (f:real->complex) P * mass_Eh E h P` THEN
  CONJ_TAC THENL
   [USE_THEN "PST" (MP_TAC o ISPECL
     [`f:real->complex`; `k:int`; `E:real->bool`; `h:real->real`;
      `P:(int#int#int)->bool`; `a:int`; `p:int`; `u:int#int#int`;
        `M:int`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(C1 * energy_f (f:real->complex) P * mass_Eh E h P * inv(&2 zpow (&2 * a)))
     *
    inv(&8 zpow k) =
    C1 * inv(&2 zpow k) *
    (inv(&2 zpow (&2 * a)) * inv(&2 zpow (&2 * k))) *
    energy_f f P * mass_Eh E h P`
   SUBST1_TAC THENL
   [SUBGOAL_THEN
     `inv(&8 zpow k) = inv(&2 zpow k) * inv(&2 zpow (&2 * k))` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM REAL_INV_MUL] THEN AP_TERM_TAC THEN
      SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
      SUBGOAL_THEN `k + &2 * k = &3 * k:int` SUBST1_TAC THENL
       [INT_ARITH_TAC; ALL_TAC] THEN REWRITE_TAC[ZPOW_2_3];
      ALL_TAC] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[REAL_ARITH
   `a * e * m <= b * e * m <=> (e * m) * a <= (e * m) * b`] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC TIGHT_DECAY_BOUND THEN ASM_REWRITE_TAC[]);;

(* --- 286L(c-ii) alpha0: chaining the per-scale bound over scales, per      *)
(* cover cell ---                                                            *)

(* A cover-cell scale span M = 2^{a+k} (k >= --a) is an integer >= 1:        *)
(* witness for k.                                                            *)
let SPAN_INT_EXISTS = prove
 (`!a k:int. --k <= a ==> ?M:int. &2 zpow (a + k) = real_of_int M`,
  REPEAT STRIP_TAC THEN MP_TAC(SPEC `a + k:int` DYADIC_SCALE_INT) THEN
  ANTS_TAC THENL [ASM_INT_ARITH_TAC;
    DISCH_THEN(X_CHOOSE_THEN `M:int` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `M:int` THEN
    ASM_REWRITE_TAC[]]);;

(* ~(--k<=a) => the scale-k slice of the cell tile-set is empty (--a<=k <=>  *)
(* --k<=a).                                                                  *)
let SPAN_INT_EMPTY = prove
 (`!a k:int. ~(--k <= a) ==> ~(--a <= k)`, INT_ARITH_TAC);;

(* Monotonicity: the scale-k slice sum <= the ALPHA_SCALE tile-set sum       *)
(* (nonneg terms).                                                           *)
let SUM_SLICE_LE = prove
 (`!(f:real->complex) E h P a p k u.
     FINITE (P:(int#int#int)->bool)
     ==> sum {s | s IN {s | s IN P /\ tile_le s u /\ --a <= tile_k s} /\ tile_k
       s = k}
             (\s. norm(carleson_ip f s *
                  integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                    dyho a p))
                           (\z. phi_sigma s carleson_phi (drop z))))
         <= sum {s | s IN P /\ tile_k s = k /\ tile_le s u}
             (\s. norm(carleson_ip f s *
                  integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                    dyho a p))
                           (\z. phi_sigma s carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC SUM_SUBSET THEN
  ASM_SIMP_TAC[FINITE_RESTRICT] THEN
  REWRITE_TAC[IN_DIFF; IN_ELIM_THM] THEN CONJ_TAC THEN GEN_TAC THEN
    STRIP_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o check (is_neg o concl)) THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[NORM_POS_LE]]);;

(* Per-scale-slice bound: for a cover cell dyho a p, the scale-k slice of    *)
(* its tile-set                                                              *)
(* has alpha-sum <= C1 energy mass * 2^{-k}. k >= --a: reduce to             *)
(* ALPHA_CELL_PER_SCALE                                                      *)
(* (SUM_SLICE_LE + SPAN_INT_EXISTS witness); k < --a: the slice is empty     *)
(* (SPAN_INT_EMPTY), sum 0 <= RHS.                                           *)
let ALPHA_CELL_PERSCALE_BOUND = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) a p u k.
      FINITE P /\ ~(P = {}) /\ in_kcover P a p /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      &0 <= energy_f f P /\ &0 <= mass_Eh E h P
      ==> sum {s | s IN {s | s IN P /\ tile_le s u /\ --a <= tile_k s} /\
        tile_k s = k}
              (\s. norm(carleson_ip f s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                     dyho a p))
                            (\z. phi_sigma s carleson_phi (drop z))))
          <= (C1 * energy_f f P * mass_Eh E h P) * inv(&2 zpow k)`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PS"))
    ALPHA_CELL_PER_SCALE THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `--(k:int) <= a` THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `C1 * inv(&2 zpow k) * energy_f (f:real->complex) P * mass_Eh E
      h P` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC
        `sum {s | s IN P /\ tile_k s = k /\ tile_le s u}
             (\s. norm(carleson_ip (f:real->complex) s *
                  integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                    dyho a p))
                           (\z. phi_sigma s carleson_phi (drop z))))` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC SUM_SLICE_LE THEN ASM_REWRITE_TAC[];
        SUBGOAL_THEN
          `?M:int. &2 zpow (a + k) =
           real_of_int M` (X_CHOOSE_TAC `M:int`) THENL
         [MATCH_MP_TAC SPAN_INT_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "PS" (MP_TAC o ISPECL
         [`f:real->complex`; `k:int`; `E:real->bool`; `h:real->real`;
          `P:(int#int#int)->bool`; `a:int`; `p:int`; `u:int#int#int`;
            `M:int`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN MATCH_ACCEPT_TAC]];
      REAL_ARITH_TAC];
    SUBGOAL_THEN
     `{s | s IN {s | s IN P /\ tile_le s u /\ --a <= tile_k s} /\ tile_k s = k}
       = {}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
      X_GEN_TAC `s:int#int#int` THEN
      FIRST_ASSUM(ASSUME_TAC o MATCH_MP SPAN_INT_EMPTY) THEN
      STRIP_TAC THEN UNDISCH_TAC `--a <= tile_k (s:int#int#int)` THEN
        ASM_REWRITE_TAC[];
      REWRITE_TAC[SUM_CLAUSES] THEN
      MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
         [ASM_REWRITE_TAC[]; MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[]];
        REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
        MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC]]]);;

(* 286L(d) alpha1 per-scale-slice (CUBIC, nested-set form for the geom       *)
(* engine): the                                                              *)
(* scale-k slice of the cover cell's tile-set <= (C1 E mass inv(2^{2a}))     *)
(* inv(8^k). Same                                                            *)
(* case split as ALPHA_CELL_PERSCALE_BOUND (k>=--a: SUM_SLICE_LE +           *)
(* ALPHA_CELL1_PERSCALE_                                                     *)
(* BOUND; k<--a: empty slice via SPAN_INT_EMPTY), but the CUBIC 8^k RHS.     *)
let ALPHA_CELL1_PERSCALE_SLICE = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) a p u k.
      FINITE P /\ ~(P = {}) /\ in_kcover P a p /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      &0 <= energy_f f P /\ &0 <= mass_Eh E h P
      ==> sum {s | s IN {s | s IN P /\ tile_le s u /\ --a <= tile_k s} /\
        tile_k s = k}
              (\s. norm(carleson_ip f s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                     dyho a p))
                            (\z. phi_sigma s carleson_phi (drop z))))
          <= (C1 * energy_f f P * mass_Eh E h P * inv(&2 zpow (&2 * a))) *
            inv(&8 zpow k)`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PB"))
    ALPHA_CELL1_PERSCALE_BOUND THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `--(k:int) <= a` THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC
      `sum {s | s IN P /\ tile_k s = k /\ tile_le s u}
           (\s. norm(carleson_ip (f:real->complex) s *
                integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                  dyho a p))
                         (\z. phi_sigma s carleson_phi (drop z))))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUM_SLICE_LE THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN
        `?M:int. &2 zpow (a + k) = real_of_int M` (X_CHOOSE_TAC `M:int`) THENL
       [MATCH_MP_TAC SPAN_INT_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "PB" (MP_TAC o ISPECL
       [`f:real->complex`; `k:int`; `E:real->bool`; `h:real->real`;
        `P:(int#int#int)->bool`; `a:int`; `p:int`; `u:int#int#int`;
          `M:int`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN MATCH_ACCEPT_TAC]];
    SUBGOAL_THEN
     `{s | s IN {s | s IN P /\ tile_le s u /\ --a <= tile_k s} /\ tile_k s = k}
       = {}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
      X_GEN_TAC `s:int#int#int` THEN
      FIRST_ASSUM(ASSUME_TAC o MATCH_MP SPAN_INT_EMPTY) THEN
      STRIP_TAC THEN UNDISCH_TAC `--a <= tile_k (s:int#int#int)` THEN
        ASM_REWRITE_TAC[];
      REWRITE_TAC[SUM_CLAUSES] THEN
      MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REPEAT(MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC) THEN
        ASM_REWRITE_TAC[REAL_LE_INV_EQ] THEN
        MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
          REAL_ARITH_TAC;
        REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
        MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC]]]);;

(* 286L(d) alpha1 PER-CELL total: for a cover cell (coarser than tau, so     *)
(* W1), the whole                                                            *)
(* cell tile-set alpha-sum <= (8/7) C1 E mass inv(2^{2a}) inv(8^{k_tau}).    *)
(* Cubic geometric                                                           *)
(* engine ABSTRACT_SCALE_GEOM_SUM8 at sc = tile_k, LOWER BOUND L = tile_k u  *)
(* = k_tau (from                                                             *)
(* tile_le s u => tile_k u <= tile_k s, TILE_LE_SCALE -- k_tau is            *)
(* INDEPENDENT of the cover                                                  *)
(* level a, the key to the outer coarse-level sum). Fed by                   *)
(* ALPHA_CELL1_PERSCALE_SLICE.                                               *)
let ALPHA_CELL1_GEOM_SUM = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) a p u.
      FINITE P /\ ~(P = {}) /\ in_kcover P a p /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum {s | s IN P /\ tile_le s u /\ --a <= tile_k s}
              (\s. norm(carleson_ip f s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                     dyho a p))
                            (\z. phi_sigma s carleson_phi (drop z))))
          <= (&8 / &7) * (C1 * energy_f f P * mass_Eh E h P * inv(&2 zpow (&2 *
            a))) *
             inv(&8 zpow (tile_k u))`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PS"))
    ALPHA_CELL1_PERSCALE_SLICE THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P /\ &0 <= mass_Eh E h P`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS] THEN MATCH_MP_TAC MASS_EH_POS THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC ABSTRACT_SCALE_GEOM_SUM8 THEN
  EXISTS_TAC `tile_k:int#int#int->int` THEN
  ASM_SIMP_TAC[FINITE_RESTRICT] THEN
  CONJ_TAC THENL
   [REPEAT(MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC) THEN
    ASM_REWRITE_TAC[REAL_LE_INV_EQ] THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
      REAL_ARITH_TAC;
    GEN_TAC THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    MATCH_MP_TAC TILE_LE_SCALE THEN ASM_REWRITE_TAC[]]);;

(* 286L(c-ii) alpha0 per-cell total: the whole cover-cell tile-set alpha-sum *)
(* is bounded                                                                *)
(* 2 C1 energy mass * mu(dyho a p). ALPHA_CELL_GEOM_SUM (geometric over k >= *)
(* --a) fed                                                                  *)
(* by ALPHA_CELL_PERSCALE_BOUND. This is Fremlin's per-K quantity g(K) <= D  *)
(* mu K.                                                                     *)
let ALPHA_CELL_TOTAL = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) a p u.
      FINITE P /\ ~(P = {}) /\ in_kcover P a p /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum {s | s IN P /\ tile_le s u /\ --a <= tile_k s}
              (\s. norm(carleson_ip f s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                     dyho a p))
                            (\z. phi_sigma s carleson_phi (drop z))))
          <= (&2 * C1 * energy_f f P * mass_Eh E h P) * real_measure (dyho a
            p)`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PB"))
    ALPHA_CELL_PERSCALE_BOUND THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P /\ &0 <= mass_Eh E h P`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS] THEN MATCH_MP_TAC MASS_EH_POS THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(&2 * C1 * energy_f (f:real->complex) P * mass_Eh E h P) * real_measure
     (dyho a p)
    = (&2 * (C1 * energy_f f P * mass_Eh E h P)) * real_measure (dyho a p)`
   SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC ALPHA_CELL_GEOM_SUM THEN
  REPEAT CONJ_TAC THEN
  FIRST
   [MATCH_MP_TAC FINITE_RESTRICT THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[]; MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[IN_ELIM_THM] THEN
    X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    (GEN_TAC THEN
     USE_THEN "PB" (MP_TAC o ISPECL
       [`f:real->complex`; `E:real->bool`; `h:real->real`;
        `P:(int#int#int)->bool`; `a:int`; `p:int`; `u:int#int#int`;
          `k:int`]) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN MATCH_ACCEPT_TAC])]);;

(* Two Schwartz functions pair to an integrable product f cnj g:  f is a     *)
(* bounded measurable factor, cnj g is absolutely integrable.                *)
let SCHWARTZ_CNJ_PRODUCT_INTEGRABLE = prove
 (`!(f:real->complex) (g:real->complex). schwartz f /\ schwartz g
     ==> (\z:real^1. f(drop z) * cnj(g(drop z))) integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MP_TAC(ISPECL
    [`(*):complex->complex->complex`;
     `\z:real^1. f(drop z):complex`;
     `\z:real^1. cnj(g(drop z)):complex`;
     `(:real^1)`] ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  REWRITE_TAC[BILINEAR_COMPLEX_MUL] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_MEASURABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    ASM_SIMP_TAC[SCHWARTZ_ABSINT]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(MATCH_MP SCHWARTZ_BOUNDED (ASSUME `schwartz (f:real->complex)`))
     THEN
    DISCH_THEN(X_CHOOSE_TAC `B:real`) THEN
    REWRITE_TAC[BOUNDED_POS] THEN EXISTS_TAC `abs B + &1` THEN
    REWRITE_TAC[FORALL_IN_IMAGE; IN_UNIV] THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    X_GEN_TAC `z:real^1` THEN
    MP_TAC(SPEC `drop(z:real^1)` (ASSUME `!x. norm((f:real->complex) x) <= B`))
      THEN
    REAL_ARITH_TAC;
    SUBGOAL_THEN
      `(\z:real^1. cnj((g:real->complex)(drop z))) =
       cnj o (\z:real^1. g(drop z))`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_LINEAR THEN
    ASM_SIMP_TAC[SCHWARTZ_ABSINT; LINEAR_CNJ]]);;

(* The product norm(phi_s) norm(phi_t) is integrable (both in L^2, Hoelder). *)
let PHISIG_NORMPROD_INTEGRABLE = prove
 (`!(s:int#int#int) (t:int#int#int).
     (\z. lift(norm(phi_sigma s carleson_phi (drop z)) *
               norm(phi_sigma t carleson_phi (drop z)))) integrable_on
                 (:real^1)`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`(:real^1)`; `&2`; `&2`;
     `\z:real^1. phi_sigma s carleson_phi (drop z)`;
     `\z:real^1. phi_sigma t carleson_phi (drop z)`] LSPACE_INTEGRABLE_PRODUCT)
       THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  REWRITE_TAC[REAL_ARITH `&0 < &2`; REAL_ARITH `inv(&2) + inv(&2) = &1`] THEN
  CONJ_TAC THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
  REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]);;

(* Pointwise: norm(phi_s x) norm(phi_t x) <= C1^2 2^(-k_s/2) 2^(-k_t/2)      *)
(* w_s(x) w_t(x)  (PHISIG_CW = 286E(c-iii) multiplied in each factor).       *)
let PHISIG_PROD_CW = prove
 (`?C1. &0 <= C1 /\ !(s:int#int#int) (t:int#int#int) x.
     norm(phi_sigma s carleson_phi x) * norm(phi_sigma t carleson_phi x)
     <= (C1 * C1) * (inv(sqrt(&2 zpow (tile_k s))) * inv(sqrt(&2 zpow (tile_k
       t)))) *
        (cw_tile s x * cw_tile t x)`,
  MP_TAC PHISIG_CW THEN DISCH_THEN(X_CHOOSE_THEN
    `C1:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT GEN_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(C1 * inv(sqrt(&2 zpow (tile_k s))) * cw_tile s x) *
              (C1 * inv(sqrt(&2 zpow (tile_k t))) * cw_tile t x)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL2 THEN ASM_REWRITE_TAC[NORM_POS_LE]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_EQ_IMP_LE THEN CONV_TAC REAL_RING);;

(* The weight product w_s w_t is real-integrable on R: measurable            *)
(* (continuous), dominated by the integrable (2^ks 2^kt) w_t (since          *)
(* 0<=w_s<=1).                                                               *)
let CW_PROD_INTEGRABLE_ABSTRACT = prove
 (`!ks kt xs xt. &0 < ks /\ &0 < kt
     ==> (\x. (ks * cw(ks * (x - xs))) * (kt * cw(kt * (x - xt))))
       real_integrable_on (:real)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `\x. (ks * kt) * cw(kt * (x - xt))` THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
    SUBGOAL_THEN
     `(\x. (ks * cw(ks * (x - xs))) * (kt * cw(kt * (x - xt)))) =
      (\x. (ks * cw(ks * x + (--(ks * xs)))) * (kt * cw(kt * x + (--(kt *
        xt)))))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REPEAT(AP_THM_TAC ORELSE AP_TERM_TAC ORELSE BINOP_TAC) THEN
      TRY(AP_TERM_TAC THEN REAL_ARITH_TAC) THEN REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_MUL THEN CONJ_TAC THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_LMUL THEN REWRITE_TAC[CW_SHIFT_CONTINUOUS];
    REWRITE_TAC[] THEN MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
    SUBGOAL_THEN
      `(\x. cw(kt * (x - xt))) =
       (\x. cw(kt * x + (--(kt * xt))))` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
       REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[real_integrable_on] THEN EXISTS_TAC `inv kt:real` THEN
    MATCH_MP_TAC CW_AFFINE_INTEGRAL THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN `&0 <= ks * cw(ks * (x - xs)) /\ ks * cw(ks * (x - xs)) <= ks`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
        MP_TAC(SPEC `ks * (x - xs):real` CW_POS) THEN REAL_ARITH_TAC;
        GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
        MATCH_MP_TAC REAL_LE_LMUL THEN
          ASM_SIMP_TAC[REAL_LT_IMP_LE; CW_LE_1]]; ALL_TAC] THEN
    SUBGOAL_THEN `&0 <= kt * cw(kt * (x - xt))` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
      MP_TAC(SPEC `kt * (x - xt):real` CW_POS) THEN
        REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `abs((ks * cw(ks * (x - xs))) * (kt * cw(kt * (x - xt)))) =
      (ks * cw(ks * (x - xs))) * (kt * cw(kt * (x - xt)))`
     SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC REAL_LE_MUL THEN
       ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `ks * (kt * cw(kt * (x - xt)))` THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_EQ_IMP_LE THEN CONV_TAC REAL_RING]]);;

let CWTILE_PROD_INTEGRABLE = prove
 (`!(s:int#int#int) (t:int#int#int).
     (\x. cw_tile s x * cw_tile t x) real_integrable_on (:real)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cw_tile] THEN
  MATCH_MP_TAC CW_PROD_INTEGRABLE_ABSTRACT THEN
  CONJ_TAC THEN MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC);;

(* real^1 <-> real bridge for the weight product integral.                   *)
let CWTILE_PROD_INTEGRAL_BRIDGE = prove
 (`!(s:int#int#int) (t:int#int#int).
     integral (:real^1) (\z. lift(cw_tile s (drop z) * cw_tile t (drop z))) =
     lift(real_integral (:real) (\x. cw_tile s x * cw_tile t x))`,
  REPEAT GEN_TAC THEN
  MP_TAC(MATCH_MP REAL_INTEGRAL (SPECL [`s:int#int#int`;
    `t:int#int#int`] CWTILE_PROD_INTEGRABLE)) THEN
  REWRITE_TAC[IMAGE_LIFT_UNIV] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[LIFT_DROP; o_DEF]);;

let CWTILE_PROD_LIFT_INTEGRABLE = prove
 (`!(s:int#int#int) (t:int#int#int).
     (\z:real^1. lift(cw_tile s (drop z) * cw_tile t (drop z))) integrable_on
       (:real^1)`,
  REPEAT GEN_TAC THEN
  MP_TAC(SPECL [`s:int#int#int`; `t:int#int#int`] CWTILE_PROD_INTEGRABLE) THEN
  REWRITE_TAC[REAL_INTEGRABLE_ON; IMAGE_LIFT_UNIV; o_DEF]);;

let CWTILE_PROD_CMUL_LIFT_INTEGRABLE = prove
 (`!(s:int#int#int) (t:int#int#int) c.
     (\z:real^1. lift(c * (cw_tile s (drop z) * cw_tile t (drop z))))
       integrable_on (:real^1)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. lift(c * (cw_tile s (drop z) * cw_tile t (drop z)))) =
    (\z:real^1. c % lift(cw_tile s (drop z) * cw_tile t (drop z)))`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; LIFT_CMUL]; ALL_TAC] THEN
  MATCH_MP_TAC INTEGRABLE_CMUL THEN REWRITE_TAC[CWTILE_PROD_LIFT_INTEGRABLE]);;

let CWTILE_PROD_CMUL_BRIDGE = prove
 (`!(s:int#int#int) (t:int#int#int) c.
     c * real_integral (:real) (\x. cw_tile s x * cw_tile t x)
     = drop(integral (:real^1)
         (\z. lift(c * (cw_tile s (drop z) * cw_tile t (drop z)))))`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. lift(c * (cw_tile s (drop z) * cw_tile t (drop z)))) =
    (\z:real^1. c % lift(cw_tile s (drop z) * cw_tile t (drop z)))`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; LIFT_CMUL]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\z:real^1. lift(cw_tile s (drop z) * cw_tile t (drop z))`;
                 `c:real`; `(:real^1)`] INTEGRAL_CMUL) THEN
  REWRITE_TAC[CWTILE_PROD_LIFT_INTEGRABLE] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[DROP_CMUL; CWTILE_PROD_INTEGRAL_BRIDGE; LIFT_DROP]);;

(* The correlation with the weight-integral on the right (pre-CWTILE_CROSS). *)
let PHISIG_CORR_WEIGHT = prove
 (`?C. &0 <= C /\ !(s:int#int#int) (t:int#int#int).
     norm(integral (:real^1)
       (\z. phi_sigma s carleson_phi (drop z) * cnj(phi_sigma t carleson_phi
         (drop z))))
     <= (C * (inv(sqrt(&2 zpow (tile_k s))) * inv(sqrt(&2 zpow (tile_k t))))) *
        real_integral (:real) (\x. cw_tile s x * cw_tile t x)`,
  MP_TAC PHISIG_PROD_CW THEN DISCH_THEN(X_CHOOSE_THEN
    `C1:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C1 * C1:real` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `drop(integral (:real^1)
     (\z. lift(norm(phi_sigma s carleson_phi (drop z)) *
               norm(phi_sigma t carleson_phi (drop z)))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRAL_NORM_BOUND_INTEGRAL THEN
    REWRITE_TAC[PHISIG_NORMPROD_INTEGRABLE] THEN CONJ_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_CNJ_PRODUCT_INTEGRABLE THEN
      REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
      REWRITE_TAC[LIFT_DROP; COMPLEX_NORM_MUL; COMPLEX_NORM_CNJ;
        REAL_LE_REFL]];
    ALL_TAC] THEN
  REWRITE_TAC[CWTILE_PROD_CMUL_BRIDGE] THEN
  MATCH_MP_TAC INTEGRAL_DROP_LE THEN
  REWRITE_TAC[PHISIG_NORMPROD_INTEGRABLE;
    CWTILE_PROD_CMUL_LIFT_INTEGRABLE] THEN
  REWRITE_TAC[IN_UNIV] THEN GEN_TAC THEN REWRITE_TAC[LIFT_DROP] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`s:int#int#int`; `t:int#int#int`;
    `drop(x:real^1)`]) THEN
  REWRITE_TAC[REAL_MUL_ASSOC]);;

(* 286G(e): the cross-tile correlation inner-product bound.                  *)
let PHISIG_CROSS_CORRELATION = prove
 (`?C. &0 <= C /\ !(s:int#int#int) (t:int#int#int). tile_k s <= tile_k t
     ==> norm(integral (:real^1)
           (\z. phi_sigma s carleson_phi (drop z) * cnj(phi_sigma t
             carleson_phi (drop z))))
         <= (C * (inv(sqrt(&2 zpow (tile_k s))) * inv(sqrt(&2 zpow (tile_k
           t))))) *
            cw_tile s (tile_xmid t)`,
  MP_TAC PHISIG_CORR_WEIGHT THEN DISCH_THEN(X_CHOOSE_THEN
    `C:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `&16 * C` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(C * (inv(sqrt(&2 zpow (tile_k s))) * inv(sqrt(&2 zpow (tile_k
    t))))) *
              real_integral (:real) (\x. cw_tile s x * cw_tile t x)` THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `&0 <= C * inv (sqrt (&2 zpow tile_k s)) * inv (sqrt (&2 zpow tile_k t))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC REAL_LE_MUL THEN
    REWRITE_TAC[REAL_LE_INV_EQ] THEN CONJ_TAC THEN
      MATCH_MP_TAC SQRT_POS_LE THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(C * inv (sqrt (&2 zpow tile_k s)) * inv (sqrt (&2 zpow tile_k
    t))) *
              (&16 * cw_tile s (tile_xmid t))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[CWTILE_CROSS];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN CONV_TAC REAL_RING]);;

(* ------------------------------------------------------------------------- *)
(* Toward 286J: the 286G(b) TILE form -- the sampled weight at the finer     *)
(* tile's centre, times mu(I_tau), lower-bounds the weight's integral over   *)
(* I_tau.  This is how Fremlin passes from the pointwise w_sigma(x_tau) form *)
(* of 286G(e) to his INT_{I_tau} w_sigma form: with the I_tau (same J, hence *)
(* same k) disjoint, sum_tau INT_{I_tau} w_sigma <= INT_R w_sigma = 1.       *)
(* ------------------------------------------------------------------------- *)

(* The half-open dyadic cell and its closure differ by (at most) two points, *)
(* so the tile weight integrates to the same value over either.              *)
let CWTILE_INTEGRAL_DYHO_CLOSED = prove
 (`!(s:int#int#int) k n.
     real_integral (dyho k n) (cw_tile s) =
     real_integral (real_interval[real_of_int n * &2 zpow k,
                                  (real_of_int n + &1) * &2 zpow k]) (cw_tile
                                    s)`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC REAL_INTEGRAL_SPIKE_SET THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN
  EXISTS_TAC `{real_of_int n * &2 zpow k, (real_of_int n + &1) * &2 zpow k}`
    THEN
  CONJ_TAC THENL
   [REWRITE_TAC[REAL_NEGLIGIBLE_INSERT; REAL_NEGLIGIBLE_SING];
    REWRITE_TAC[dyho; real_interval; SUBSET; IN_UNION; IN_DIFF; IN_ELIM_THM;
                IN_INSERT; NOT_IN_EMPTY] THEN REAL_ARITH_TAC]);;

(* 286G(b), tile form: w_sigma(x_tau) mu(I_tau) <= INT_{I_tau} w_sigma, when *)
(* the centre x_sigma lies outside the open cell I_tau (so w_sigma is convex *)
(* there and Hermite-Hadamard applies).  mu(I_tau) = 2^(-k_tau).             *)
let CWTILE_TILE_I_MIDPOINT = prove
 (`!(s:int#int#int) (kt:int) (nIt:int) (nJt:int).
     (tile_xmid s <= real_of_int nIt * &2 zpow (--kt) \/
      (real_of_int nIt + &1) * &2 zpow (--kt) <= tile_xmid s)
     ==> cw_tile s (tile_xmid (kt,nIt,nJt)) * (&2 zpow (--kt))
         <= real_integral (tile_I (kt,nIt,nJt)) (cw_tile s)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[tile_I; tile_xmid; dyho_mid; CWTILE_INTEGRAL_DYHO_CLOSED] THEN
  ABBREV_TAC `a = real_of_int nIt * &2 zpow (--kt)` THEN
  ABBREV_TAC `b = (real_of_int nIt + &1) * &2 zpow (--kt)` THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(real_of_int nIt + &1 / &2) * &2 zpow (--kt) = (a + b) / &2 /\
                &2 zpow (--kt) = b - a`
   (CONJUNCTS_THEN SUBST1_TAC) THENL
   [MAP_EVERY EXPAND_TAC ["a"; "b"] THEN CONJ_TAC THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC CWTILE_MIDPOINT_LOWER THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&0 < &2 zpow (--kt)` MP_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY EXPAND_TAC ["a"; "b"] THEN REAL_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* 286Gg: the integral kernel bound.  For distinct spatial cells with        *)
(* k_s <= k_t,  |<phi_s|phi_t>| <= C3 sqrt(muI_s) sqrt(muJ_t) int_{I_t} w_s. *)
(* sqrt(muI_s) = inv(sqrt 2^ks), sqrt(muJ_t) = sqrt 2^kt.  Combines the      *)
(* pointwise PHISIG_CROSS_CORRELATION with 286Gc CWTILE_TILE_I_MIDPOINT      *)
(* (whose                                                                    *)
(* one-sidedness hypothesis is supplied by TILE_ONESIDE_ENDPOINTS) via the   *)
(* algebraic reshaping GG_RESHAPE.                                           *)
(* ------------------------------------------------------------------------- *)

let PHISIG_286GG = prove
 (`?C3. &0 <= C3 /\
   !(ks:int) nIs nJs (kt:int) nIt nJt. ks <= kt /\
      ~(tile_I (ks,nIs,nJs) = tile_I (kt,nIt,nJt))
     ==> norm(integral (:real^1)
           (\z. phi_sigma (ks,nIs,nJs) carleson_phi (drop z) *
                cnj(phi_sigma (kt,nIt,nJt) carleson_phi (drop z))))
         <= C3 * inv(sqrt(&2 zpow ks)) * sqrt(&2 zpow kt) *
            real_integral (tile_I (kt,nIt,nJt)) (cw_tile (ks,nIs,nJs))`,
  MP_TAC PHISIG_CROSS_CORRELATION THEN
  DISCH_THEN(X_CHOOSE_THEN `C:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C:real` THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(C * (inv(sqrt(&2 zpow (tile_k (ks,nIs,nJs)))) *
                    inv(sqrt(&2 zpow (tile_k (kt,nIt,nJt)))))) *
              cw_tile (ks,nIs,nJs) (tile_xmid (kt,nIt,nJt))` THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN REWRITE_TAC[tile_k] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[tile_k] THEN
    ONCE_REWRITE_TAC[REAL_RING
     `(C * inv a * inv b) * w = (C * inv a) * (inv b * w):real`] THEN
    ONCE_REWRITE_TAC[REAL_RING
     `C * inv a * b * i = (C * inv a) * (b * i):real`] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
      MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC GG_RESHAPE THEN CONJ_TAC THENL
     [SIMP_TAC[REAL_LT_IMP_LE; CW_TILE_POS]; ALL_TAC] THEN
    MP_TAC(ISPECL [`(ks,nIs,nJs):int#int#int`; `kt:int`; `nIt:int`; `nJt:int`]
      CWTILE_TILE_I_MIDPOINT) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    REWRITE_TAC[tile_xmid] THEN
    MP_TAC(ISPECL [`--kt:int`; `--ks:int`; `nIt:int`; `nIs:int`]
      TILE_ONESIDE_ENDPOINTS) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [ASM_INT_ARITH_TAC;
        REWRITE_TAC[GSYM tile_I] THEN
        ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN ASM_REWRITE_TAC[]];
      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    POP_ASSUM MP_TAC THEN REWRITE_TAC[tile_I]]);;

(* ------------------------------------------------------------------------- *)
(* Tile geometry for 286J's same-frequency-interval sum: J_sigma = J_tau     *)
(* forces k_sigma = k_tau, and distinct tiles with a common J have DISJOINT  *)
(* spatial intervals I.  (Grounded in dyadic-cell injectivity DYHO_INJ.)     *)
(* ------------------------------------------------------------------------- *)

(* Base 2 dilation is strictly monotone, hence injective, in the exponent.   *)
let ZPOW2_INJ = prove
 (`!k1 k2:int. &2 zpow k1 = &2 zpow k2 ==> k1 = k2`,
  REPEAT GEN_TAC THEN
  DISJ_CASES_THEN MP_TAC (INT_ARITH `k1:int = k2 \/ k1 < k2 \/ k2 < k1`) THENL
   [DISCH_TAC THEN ASM_REWRITE_TAC[];
    STRIP_TAC THEN DISCH_TAC THENL
     [MP_TAC(SPECL [`k1:int`;`k2:int`] ZPOW2_MONOE_LT);
      MP_TAC(SPECL [`k2:int`;`k1:int`] ZPOW2_MONOE_LT)] THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC]);;

(* Dyadic cells: equal length forces equal scale; then equal cells force     *)
(* equal index (else they would be disjoint yet share their left endpoint).  *)
let DYHO_EQ_IMP_SCALE = prove
 (`!k1 n1 k2 n2. dyho k1 n1 = dyho k2 n2 ==> k1 = k2`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC ZPOW2_INJ THEN
  MP_TAC(SPECL [`k1:int`; `n1:int`] DYHO_MEASURE) THEN
  MP_TAC(SPECL [`k2:int`; `n2:int`] DYHO_MEASURE) THEN
  ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC);;

let DYHO_INJ = prove
 (`!k1 n1 k2 n2. dyho k1 n1 = dyho k2 n2 ==> k1 = k2 /\ n1 = n2`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `k1:int = k2` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[DYHO_EQ_IMP_SCALE]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `n1:int = n2` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`k2:int`;`n1:int`;`n2:int`] DYHO_DISJOINT_SAMESCALE) THEN
  ASM_REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `real_of_int n1 * &2 zpow k2`) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`k2:int`; `n1:int`] DYHO_NONEMPTY) THEN
  ASM_REWRITE_TAC[]);;

(* --- 286L(c-ii) alpha0 FULL BOUND: summed over all coarse cover cells ---  *)
(* Fremlin's |alpha0| <= (7/2) C1 gamma gamma' mu I_tau, here as the crude   *)
(* constant                                                                  *)
(* 2*14 = 28: sum over the cover family S (index pairs) of each cover cell's *)
(* alpha-sum                                                                 *)
(* <= 2 C1 energy mass * 14 * 2^{-kt} = 2 C1 energy mass * mu Ihat_tau.      *)
(* Composes                                                                  *)
(* ALPHA_CELL_TOTAL (per cover cell: g(K) <= 2 C1 E M mu K) over S via       *)
(* SUM_LE + SUM_                                                             *)
(* LMUL, then the a-ii KCOVER_COARSE_MEASURE_BOUND (sum mu K <= 14 mu I_tau) *)
(* after                                                                     *)
(* reindexing sum_S mu(cell ap) = sum over IMAGE-cell-S (SUM_IMAGE +         *)
(* DYHO_INJ).                                                                *)
let KCOVER_SUBSET_IHAT_WIDE = prove
 (`!P:(int#int#int)->bool a p kt nt.
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      &2 zpow a <= &2 zpow (--kt) /\ in_kcover P a p
      ==> dyho a p SUBSET
          real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                        dyho_mid (--kt) nt + &7 * &2 zpow (--kt)]`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN
  X_GEN_TAC `y:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`a:int`; `p:int`; `kt:int`;
    `nt:int`] KCOVER_STAR_MEETS_ITAU_CONTAIN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC KCOVER_PARENT_MEETS_ITAU_GEN THEN
    MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[] THEN
      REAL_ARITH_TAC]);;

(* Total measure of the coarse cover cells (l_K >= kt) <= 14 * 2^{-kt}. Same *)
(* engine as KCOVER_COARSE_MEASURE_BOUND but with the relaxed 2^a <=         *)
(* 2^{-kt}.                                                                  *)
let KCOVER_COARSE_MEASURE_BOUND_WIDE = prove
 (`!P:(int#int#int)->bool S kt nt.
      FINITE S /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap) /\
                        &2 zpow (FST ap) <= &2 zpow (--kt))
      ==> sum (IMAGE (\ap. dyho (FST ap) (SND ap)) S) (\c. real_measure c)
          <= &14 * &2 zpow (--kt)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`; `S:(int#int)->bool`;
     `real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                    dyho_mid (--kt) nt + &7 * &2 zpow (--kt)]`]
     KCOVER_MEASURE_SUM_LE) THEN
  SUBGOAL_THEN
   `real_measure(real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                               dyho_mid (--kt) nt + &7 * &2 zpow (--kt)])
    = &14 * &2 zpow (--kt)`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN
    SUBGOAL_THEN `&0 < &2 zpow (--kt)` MP_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
       REAL_ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL] THEN CONJ_TAC THEN
  X_GEN_TAC `ap:int#int` THEN DISCH_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `ap:int#int`) THEN ASM_SIMP_TAC[];
    MATCH_MP_TAC KCOVER_SUBSET_IHAT_WIDE THEN
    MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`] THEN
    ASM_SIMP_TAC[] THEN FIRST_X_ASSUM(MP_TAC o SPEC `ap:int#int`) THEN
      ASM_SIMP_TAC[]]);;

(* alpha0 TOTAL, boundary-inclusive: gate 2^{FST ap} <= 2^{-kt} (l_K >= kt). *)
(* Identical to ALPHA0_TOTAL but over the wider cover, via KCOVER_COARSE_    *)
(* MEASURE_BOUND_WIDE (ALPHA_CELL_TOTAL is gate-free, so applies at l_K =    *)
(* kt).                                                                      *)
let ALPHA0_TOTAL_WIDE = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) S kt nt u.
      FINITE P /\ ~(P = {}) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      FINITE S /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap) /\
                        &2 zpow (FST ap) <= &2 zpow (--kt))
      ==> sum S (\ap. sum {s | s IN P /\ tile_le s u /\ --(FST ap) <= tile_k s}
                          (\s. norm(carleson_ip f s *
                               integral (IMAGE lift ({x | x IN E /\ h x IN
                                 tile_Jr s} INTER
                                         dyho (FST ap) (SND ap)))
                                        (\z. phi_sigma s carleson_phi (drop
                                          z)))))
          <= (&2 * C1 * energy_f f P * mass_Eh E h P) * (&14 * &2 zpow
            (--kt))`,
  X_CHOOSE_THEN
    `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "CT"))
     ALPHA_CELL_TOTAL THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P /\ &0 <= mass_Eh E h P`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS] THEN MATCH_MP_TAC MASS_EH_POS THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum S (\ap. (&2 * C1 * energy_f (f:real->complex) P * mass_Eh E h
    P) *
                          real_measure (dyho (FST ap) (SND ap)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    USE_THEN "CT" (MP_TAC o ISPECL
     [`f:real->complex`; `E:real->bool`; `h:real->real`;
       `P:(int#int#int)->bool`;
      `FST(ap:int#int)`; `SND(ap:int#int)`; `u:int#int#int`]) THEN
    ANTS_TAC THENL [ASM_SIMP_TAC[]; DISCH_THEN MATCH_ACCEPT_TAC];
    ONCE_REWRITE_TAC[SUM_LMUL] THEN MATCH_MP_TAC REAL_LE_LMUL THEN
      CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC) THEN
      ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
      SUBGOAL_THEN
       `sum S (\ap. real_measure (dyho (FST ap) (SND ap))) =
        sum (IMAGE (\ap:int#int. dyho (FST ap) (SND ap)) S) (\c. real_measure
          c)`
       SUBST1_TAC THENL
       [MATCH_MP_TAC EQ_SYM THEN
        MP_TAC(ISPECL [`\ap:int#int. dyho (FST ap) (SND ap)`;
                       `\c:real->bool. real_measure c`;
                         `S:(int#int)->bool`] SUM_IMAGE) THEN
        ANTS_TAC THENL
         [REWRITE_TAC[FORALL_PAIR_THM] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
          FIRST_X_ASSUM(MP_TAC o MATCH_MP DYHO_INJ) THEN SIMP_TAC[PAIR_EQ];
          REWRITE_TAC[o_DEF]];
        ALL_TAC] THEN
      MATCH_MP_TAC KCOVER_COARSE_MEASURE_BOUND_WIDE THEN
      MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`; `nt:int`] THEN
        ASM_REWRITE_TAC[]]]);;

(* --- 286L(d) alpha1 FULL BOUND: summed over the W1 cover ---               *)

(* 286L(a-iv) COUNT form: at most 14 cover cells at a fixed level m. Each    *)
(* cover cell                                                                *)
(* dyho m q has measure 2^m and they are distinct (DYHO_INJ) so CARD S =     *)
(* CARD(IMAGE                                                                *)
(* (dyho m) S); the measure sum = CARD * 2^m <= 14 * 2^m                     *)
(* (KCOVER_LEVEL_MEASURE_BOUND),                                             *)
(* cancel 2^m > 0. (Fremlin's sharp a-iv count is 3; our 14 is cruder,       *)
(* immaterial.)                                                              *)
(* DYHO_INJ supplies the required injectivity for CARD_IMAGE_INJ.            *)
let KCOVER_LEVEL_CARD = prove
 (`!P:(int#int#int)->bool S m kt nt.
      FINITE S /\ &2 zpow (--kt) <= &2 zpow m /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!q. q IN S ==> in_kcover P m q)
      ==> &(CARD S) <= &14`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow m` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `CARD (IMAGE (\q. dyho m q) S) = CARD (S:int->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC CARD_IMAGE_INJ THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`q1:int`; `q2:int`] THEN REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o MATCH_MP DYHO_INJ) THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&(CARD (S:int->bool)) * &2 zpow m <= &14 * &2 zpow m` MP_TAC THENL
   [MP_TAC(ISPECL [`P:(int#int#int)->bool`; `S:int->bool`; `m:int`; `kt:int`;
     `nt:int`]
      KCOVER_LEVEL_MEASURE_BOUND) THEN
    ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(REAL_ARITH `a = b ==> a <= c ==> b <= c`) THEN
    SUBGOAL_THEN
     `sum (IMAGE (\q. dyho m q) S) (\c. real_measure c) =
      sum (IMAGE (\q. dyho m q) S) (\c. &2 zpow m)` SUBST1_TAC THENL
     [MATCH_MP_TAC SUM_EQ THEN REWRITE_TAC[FORALL_IN_IMAGE] THEN
      X_GEN_TAC `q:int` THEN DISCH_TAC THEN
        REWRITE_TAC[DYHO_MEASURE]; ALL_TAC] THEN
    SIMP_TAC[SUM_CONST; FINITE_IMAGE; ASSUME `FINITE(S:int->bool)`] THEN
    ASM_REWRITE_TAC[REAL_MUL_SYM];
    ASM_SIMP_TAC[REAL_LE_RMUL_EQ]]);;

(* Per-level count for the alpha1 coarse-level sum: <=14 cover cells at each *)
(* level m.                                                                  *)
(* Projects the fiber {ap IN S | FST ap = m} (pairs) to its SND-indices      *)
(* (injective,                                                               *)
(* since FST is fixed) then KCOVER_LEVEL_CARD. Empty fiber => CARD 0. The    *)
(* 2^{-kt}<=2^m                                                              *)
(* side-condition of KCOVER_LEVEL_CARD comes from a witness cell in the      *)
(* (nonempty) fiber.                                                         *)
let ALPHA1_LEVEL_COUNT = prove
 (`!P:(int#int#int)->bool S kt nt m.
      FINITE S /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap) /\
                        &2 zpow (--kt) < &2 zpow (FST ap))
      ==> &(CARD {ap | ap IN S /\ FST ap = m}) <= &14`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `{ap:int#int | ap IN S /\ FST ap = m} = {}` THENL
   [ASM_REWRITE_TAC[CARD_CLAUSES] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow (--kt) <= &2 zpow m` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
    DISCH_THEN(X_CHOOSE_THEN `ap:int#int` STRIP_ASSUME_TAC) THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `ap:int#int`) THEN ASM_REWRITE_TAC[] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD {ap:int#int | ap IN S /\ FST ap = m} =
    CARD (IMAGE SND {ap:int#int | ap IN S /\ FST ap = m})` SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARD_IMAGE_INJ THEN
    ASM_SIMP_TAC[FINITE_RESTRICT] THEN
    REWRITE_TAC[FORALL_PAIR_THM; IN_ELIM_THM] THEN
    MAP_EVERY X_GEN_TAC [`p1:int`; `p2:int`; `p1':int`; `p2':int`] THEN
    REWRITE_TAC[PAIR_EQ] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC KCOVER_LEVEL_CARD THEN
  MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`; `m:int`; `kt:int`;
    `nt:int`] THEN
  ASM_SIMP_TAC[FINITE_IMAGE; FINITE_RESTRICT] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM; FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC [`aa:int`; `pp:int`] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `(aa,pp):int#int`) THEN ASM_REWRITE_TAC[] THEN
    SIMP_TAC[]);;

(* The alpha1 constant-collapse identity: inv(8^kt) inv(4^{-kt+1}) = inv(4)  *)
(* 2^{-kt}                                                                   *)
(* (both sides = 2^{-kt-2}). With the (8/7)(14)(4/3) prefactor this gives    *)
(* 16/3. All                                                                 *)
(* via 8^kt = 2^{3kt}, 4^{-kt+1} = 2^{2(-kt+1)} (ZPOW_2_3/ZPOW_2_2), combine *)
(* exponents.                                                                *)
let ZPOW_ALPHA1_ARITH = prove
 (`!kt:int. inv(&8 zpow kt) * inv(&4 zpow (--kt + &1)) = inv(&4) * &2 zpow
   (--kt)`,
  GEN_TAC THEN
  SUBGOAL_THEN `&8 zpow kt = &2 zpow (&3 * kt)` SUBST1_TAC THENL
   [REWRITE_TAC[ZPOW_2_3]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&4 zpow (--kt + &1) = &2 zpow (&2 * (--kt + &1))` SUBST1_TAC THENL
   [REWRITE_TAC[ZPOW_2_2]; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_INV_MUL] THEN
  SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
  SUBGOAL_THEN `inv(&4) = &2 zpow (-- &2)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_NEG; REAL_ZPOW_POW] THEN
     CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
  REWRITE_TAC[GSYM REAL_ZPOW_NEG] THEN AP_TERM_TAC THEN INT_ARITH_TAC);;

(* THE FULL alpha1 bound (Fremlin 286L(d)): sum over the W1 cover (cells     *)
(* with mu K >                                                               *)
(* mu I_tau, i.e. 2^{-kt} < 2^{FST ap}) of each cover cell's alpha-sum <=    *)
(* (16/3) C1                                                                 *)
(* energy mass 2^{-kt} = (16/3) C1 gamma gamma' mu I_tau (Fremlin's sharp    *)
(* 8/7; 16/3                                                                 *)
(* immaterial). DOUBLE geometric: per cell g(a,p) <= (8/7) C1 E mass         *)
(* inv(4^a) inv(8^kt)                                                        *)
(* (ALPHA_CELL1_GEOM_SUM, cubic k-sum), then sum over cover levels a         *)
(* (quadratic, <=14                                                          *)
(* cells/level via ALPHA1_LEVEL_COUNT) with LEVEL_WEIGHTED_SUM_LE: sum       *)
(* inv(4^{FST ap})                                                           *)
(* <= 14 (4/3) inv(4^{-kt+1}); collapse via ZPOW_ALPHA1_ARITH. W1 level      *)
(* bound -kt+1 <=                                                            *)
(* FST ap from ZPOW2_LT_REV on 2^{-kt} < 2^{FST ap}.                         *)
let ALPHA1_TOTAL = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) S kt nt u.
      FINITE P /\ ~(P = {}) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET tile_I u) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      tile_k u = kt /\ FINITE S /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap) /\
                        &2 zpow (--kt) < &2 zpow (FST ap))
      ==> sum S (\ap. sum {s | s IN P /\ tile_le s u /\ --(FST ap) <= tile_k s}
                          (\s. norm(carleson_ip f s *
                               integral (IMAGE lift ({x | x IN E /\ h x IN
                                 tile_Jr s} INTER
                                         dyho (FST ap) (SND ap)))
                                        (\z. phi_sigma s carleson_phi (drop
                                          z)))))
          <= C1 * energy_f f P * mass_Eh E h P * &2 zpow (--kt)`,
  X_CHOOSE_THEN `Cg:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "CG"))
    ALPHA_CELL1_GEOM_SUM THEN
  EXISTS_TAC `&16 / &3 * Cg` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P /\ &0 <= mass_Eh E h P`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS] THEN MATCH_MP_TAC MASS_EH_POS THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum S (\ap:int#int. ((&8 / &7) * (Cg * energy_f (f:real->complex) P *
     mass_Eh E h P *
                             inv(&8 zpow kt))) * inv(&4 zpow (FST ap)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    USE_THEN "CG" (MP_TAC o ISPECL
     [`f:real->complex`; `E:real->bool`; `h:real->real`;
       `P:(int#int#int)->bool`;
      `FST(ap:int#int)`; `SND(ap:int#int)`; `u:int#int#int`]) THEN
    ANTS_TAC THENL [ASM_SIMP_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(REAL_ARITH `a = b ==> x <= a ==> x <= b`) THEN
    ASM_REWRITE_TAC[GSYM ZPOW_2_2] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SUM_LMUL] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `((&8 / &7) * (Cg * energy_f (f:real->complex) P * mass_Eh E h P * inv(&8
     zpow kt))) *
    (&14 * (&4 / &3) * inv(&4 zpow (--kt + &1)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC) THEN
      ASM_REWRITE_TAC[REAL_LE_INV_EQ] THEN TRY REAL_ARITH_TAC THEN
      MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
        REAL_ARITH_TAC;
      MP_TAC(ISPECL [`S:(int#int)->bool`; `FST:int#int->int`; `--kt + &1:int`;
        `&14:real`]
        LEVEL_WEIGHTED_SUM_LE) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
         [REAL_ARITH_TAC;
          X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN
          FIRST_X_ASSUM(MP_TAC o SPEC `ap:int#int`) THEN ASM_REWRITE_TAC[] THEN
            STRIP_TAC THEN
          SUBGOAL_THEN `(--kt:int) < FST(ap:int#int)` MP_TAC THENL
           [MATCH_MP_TAC ZPOW2_LT_REV THEN ASM_REWRITE_TAC[]; INT_ARITH_TAC];
          X_GEN_TAC `m:int` THEN
          MATCH_MP_TAC ALPHA1_LEVEL_COUNT THEN
          MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`; `kt:int`;
            `nt:int`] THEN
          ASM_REWRITE_TAC[]];
        DISCH_THEN MATCH_ACCEPT_TAC]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_EQ_IMP_LE THEN
  ONCE_REWRITE_TAC[REAL_ARITH
   `((&8 / &7) * (Cg * e * m * i8)) * (&14 * (&4 / &3) * i4) =
    (Cg * e * m) * ((&8 / &7) * &14 * (&4 / &3)) * (i8 * i4)`] THEN
  REWRITE_TAC[ZPOW_ALPHA1_ARITH] THEN REAL_ARITH_TAC);;

(* 286J geometry: same frequency interval => same height.                    *)
let TILE_J_EQ_IMP_K = prove
 (`!(s:int#int#int) (t:int#int#int). tile_J s = tile_J t ==> tile_k s = tile_k
   t`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_J; tile_k] THEN
  REPEAT GEN_TAC THEN DISCH_THEN(MP_TAC o MATCH_MP DYHO_INJ) THEN
  SIMP_TAC[]);;

(* 286J geometry: distinct tiles sharing a frequency interval have disjoint  *)
(* I.                                                                        *)
let TILE_SAMEJ_DISTINCT_DISJOINT_I = prove
 (`!(s:int#int#int) (t:int#int#int).
     ~(s = t) /\ tile_J s = tile_J t ==> DISJOINT (tile_I s) (tile_I t)`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_J; tile_I; PAIR_EQ] THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  STRIP_TAC THEN
  MP_TAC(SPECL [`ks:int`;`nJs:int`;`kt:int`;`nJt:int`] DYHO_INJ) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `~(nIs:int = nIt)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o check (is_neg o concl)) THEN ASM_REWRITE_TAC[] THEN
    INT_ARITH_TAC; ALL_TAC] THEN
  UNDISCH_TAC `ks:int = kt` THEN DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
  MATCH_MP_TAC DYHO_DISJOINT_SAMESCALE THEN ASM_REWRITE_TAC[]);;

(* 286Fc geometry, half 1: for coarser-scale s (ks<kt), if J^r_s meets J^r_t *)
(* then                                                                      *)
(* J^r_s SUBSET J^r_t (laminar; the coarser contains the finer).             *)
(* DYHO_TRICHOTOMY                                                           *)
(* gives 3 cases: J^r_s SUBSET J^r_t (=goal), the reverse (impossible,       *)
(* DYHO_SUBSET_                                                              *)
(* SCALE forces kt-1<=ks-1 vs ks<kt), or disjoint (contradicts the meet).    *)
(* Use                                                                       *)
(* REPEAT_TCL DISJ_CASES_THEN for a deterministic 3-branch split (a plain    *)
(* STRIP_TAC                                                                 *)
(* auto-closes the =goal disjunct in some contexts but not others -> flaky   *)
(* count).                                                                   *)
let JR_NEST_LT = prove
 (`!ks kt nJs nJt.
     ks < kt /\ ~(dyho (ks - &1) (&2 * nJs + &1) INTER dyho (kt - &1) (&2 * nJt
       + &1) = {})
     ==> dyho (ks - &1) (&2 * nJs + &1) SUBSET dyho (kt - &1) (&2 * nJt + &1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`ks - &1:int`; `&2 * nJs + &1:int`; `kt - &1:int`;
                 `&2 * nJt + &1:int`] DYHO_TRICHOTOMY) THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [FIRST_ASSUM ACCEPT_TAC;
    FIRST_X_ASSUM(MP_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN ASM_INT_ARITH_TAC;
    FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[GSYM DISJOINT]) THEN
    ASM_MESON_TAC[DISJOINT]]);;

(* 286Fc geometry, half 2: with J^r_s SUBSET J^r_t (ks<kt), the LEFT half    *)
(* J^l_s                                                                     *)
(* also lands in J^r_t. Span 2^{kt-ks} = 2 M' is even (ZPOW_POS_EVEN_INT2),  *)
(* so                                                                        *)
(* the DYHO_SUBCELL_IFF index bound (2 nJt+1) 2M' <= 2 nJs+1 is even<=odd,   *)
(* giving                                                                    *)
(* (2 nJt+1) 2M' <= 2 nJs (ODD_PROD_HALF_LE) -- i.e. J^l_s (index 2 nJs)     *)
(* sits in                                                                   *)
(* the same coarse cell J^r_t. Linear/forward proof (a SUBGOAL_THEN..THENL   *)
(* here                                                                      *)
(* trips seqapply; MATCH_MP the discreteness ks<kt ==> 1<=kt-ks needs a :int *)
(* hint).                                                                    *)
let JL_IN_JR_LT = prove
 (`!ks kt nJs nJt.
     ks < kt /\ dyho (ks - &1) (&2 * nJs + &1) SUBSET dyho (kt - &1) (&2 * nJt
       + &1)
     ==> dyho (ks - &1) (&2 * nJs) SUBSET dyho (kt - &1) (&2 * nJt + &1)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_THEN `M':int` STRIP_ASSUME_TAC o
    MATCH_MP ZPOW_POS_EVEN_INT2 o MATCH_MP (INT_ARITH `ks:int < kt ==> &1 <= kt
      - ks`)) THEN
  MP_TAC(ISPECL [`ks - &1:int`; `kt - &1:int`; `&2 * M':int`;
    `&2 * nJt + &1:int`;
                 `&2 * nJs + &1:int`] DYHO_SUBCELL_IFF) THEN
  SUBST1_TAC(INT_ARITH `(kt - &1) - (ks - &1):int = kt - ks`) THEN
  ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`ks - &1:int`; `kt - &1:int`; `&2 * M':int`;
    `&2 * nJt + &1:int`;
                 `&2 * nJs:int`] DYHO_SUBCELL_IFF) THEN
  SUBST1_TAC(INT_ARITH `(kt - &1) - (ks - &1):int = kt - ks`) THEN
  ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ODD_PROD_HALF_LE THEN ASM_REWRITE_TAC[]; ASM_INT_ARITH_TAC]);;

(* 286Fc J^l-disjointness, directional (ks<kt): meeting J^r + different      *)
(* scales                                                                    *)
(* => disjoint J^l.  J^r_s SUBSET J^r_t (JR_NEST_LT), J^l_s SUBSET J^r_t     *)
(* (JL_IN_JR_LT), and J^l_t is disjoint from its sibling J^r_t               *)
(* (DYHO_DISJOINT_                                                           *)
(* SAMESCALE at scale kt-1), so J^l_s cap J^l_t SUBSET J^r_t cap J^l_t =     *)
(* empty.                                                                    *)
let TILE_JL_DISJOINT_LT = prove
 (`!ks kt nJs nJt.
     ks < kt /\ ~(dyho (ks - &1) (&2 * nJs + &1) INTER dyho (kt - &1) (&2 * nJt
       + &1) = {})
     ==> dyho (ks - &1) (&2 * nJs) INTER dyho (kt - &1) (&2 * nJt) = {}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`ks:int`; `kt:int`; `nJs:int`; `nJt:int`] JR_NEST_LT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`ks:int`; `kt:int`; `nJs:int`; `nJt:int`] JL_IN_JR_LT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`kt - &1:int`; `&2 * nJt:int`; `&2 * nJt + &1:int`]
    DYHO_DISJOINT_SAMESCALE) THEN
  ANTS_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[DISJOINT] THEN ASM SET_TAC[]);;

(* Symmetric version: k_s <> k_t (either order) => J^l disjoint.             *)
let TILE_JL_DISJOINT = prove
 (`!ks kt nJs nJt.
     ~(ks = kt) /\ ~(dyho (ks - &1) (&2 * nJs + &1) INTER dyho (kt - &1) (&2 *
       nJt + &1) = {})
     ==> dyho (ks - &1) (&2 * nJs) INTER dyho (kt - &1) (&2 * nJt) = {}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ks:int < kt \/ kt < ks` DISJ_CASES_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC; ALL_TAC] THENL
   [MATCH_MP_TAC TILE_JL_DISJOINT_LT THEN ASM_REWRITE_TAC[];
    ONCE_REWRITE_TAC[INTER_COMM] THEN
    MATCH_MP_TAC TILE_JL_DISJOINT_LT THEN ASM_REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[INTER_COMM] THEN ASM_REWRITE_TAC[]]);;

(* The right frequency-half is nonempty.                                     *)
let TILE_JR_NONEMPTY = prove
 (`!s:int#int#int. ~(tile_Jr s = {})`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_Jr; GSYM MEMBER_NOT_EMPTY] THEN
  MESON_TAC[DYHO_NONEMPTY]);;

(* 286L (i) frequency-nesting: for two tree tiles s, s' <=_r tau at scales   *)
(* k_s <= k_s', the right-halves nest J^r_s SUBSET J^r_s'.  (tile_Jr(k,.) =  *)
(* dyho(k-1)(.) so the FINER scale k_s' gives the LONGER right-half; both    *)
(* contain                                                                   *)
(* J^r_tau so they meet, and DYHO_MEET_NEST closes it.)  This makes          *)
(* {s <=_r tau : g(x) IN J^r_s} an UP-SET in k_s -- the structural fact      *)
(* behind                                                                    *)
(* Fremlin's "g(x) IN J^r_sigma iff k_sigma >= m" threshold in part (i).     *)
let TILE_TREE_JR_NEST = prove
 (`!s s' tau. tile_ler s tau /\ tile_ler s' tau /\ tile_k s <= tile_k s'
              ==> tile_Jr s SUBSET tile_Jr s'`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
   [`ks:int`;`nIs:int`;`nJs:int`; `ks':int`;`nIs':int`;`nJs':int`;
    `kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_ler; tile_Jr; tile_k] THEN STRIP_TAC THEN
  MATCH_MP_TAC DYHO_MEET_NEST THEN CONJ_TAC THENL
   [UNDISCH_TAC `(ks:int) <= ks'` THEN INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[DISJOINT; GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
  MP_TAC(ISPEC `(kt:int,nIt:int,nJt:int)` TILE_JR_NONEMPTY) THEN
  REWRITE_TAC[tile_Jr; GSYM MEMBER_NOT_EMPTY] THEN
  DISCH_THEN(X_CHOOSE_TAC `y:real`) THEN EXISTS_TAC `y:real` THEN
  CONJ_TAC THENL
   [UNDISCH_TAC `dyho (kt - &1) (&2 * nJt + &1) SUBSET dyho (ks - &1) (&2 * nJs
     + &1)` THEN
    REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    UNDISCH_TAC `dyho (kt - &1) (&2 * nJt + &1) SUBSET dyho (ks' - &1) (&2 *
      nJs' + &1)` THEN
    REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* M4 (A-tree): the tile-tree containments feeding the step-(iv) band hyps.  *)
(* For sigma <=_r tau (so J^r_tau SUBSET J^r_sigma, k_tau <= k_sigma) and    *)
(* J_tau SUBSET Jhat = dyho m nhat (the length-2^m containing interval):     *)
(* KEEP (k_sigma <= m): J^l_sigma SUBSET Jhat (feeds PHISIG_CPSI_KEEP_GEOM); *)
(* KILL (k_sigma > m): Jhat SUBSET J^r_sigma (feeds the sharp-support kill). *)
(* All via DYHO_MEET_NEST at the shared cell J^r_tau (TILE_JR_NONEMPTY).     *)
(* ------------------------------------------------------------------------- *)

(* J^l_sigma SUBSET J_sigma (left half in parent; DYHO_PARENT at p = 2 nJ).  *)
let TILE_JL_SUBSET_J = prove
 (`!s:int#int#int. tile_Jl s SUBSET tile_J s`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!k nI nJ. P (k,nI,nJ)) ==> (!s. P s)`) THEN
  MAP_EVERY X_GEN_TAC [`k:int`;`nI:int`;`nJ:int`] THEN
  REWRITE_TAC[tile_J; tile_Jl] THEN
  MP_TAC(ISPECL [`k - &1:int`; `&2 * nJ:int`] DYHO_PARENT) THEN
  SUBGOAL_THEN `(k - &1) + &1:int = k` SUBST1_TAC THENL
    [INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(&2 * nJ) div &2 = nJ:int` SUBST1_TAC THENL
    [INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[]);;

(* J_sigma SUBSET Jhat when k_sigma <= m: J_sigma (scale k_sigma) meets Jhat *)
(* (scale m) at the shared J^r_tau, and is finer, so DYHO_MEET_NEST.         *)
let TILE_TREE_J_IN_JHAT = prove
 (`!(s:int#int#int) (tau:int#int#int) m nhat.
     tile_ler s tau /\ tile_J tau SUBSET dyho m nhat /\ tile_k s <= m
     ==> tile_J s SUBSET dyho m nhat`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!k nI nJ tau m nhat. P (k,nI,nJ) tau m nhat)
    ==> (!s tau m nhat. P s tau m nhat)`) THEN
  MAP_EVERY X_GEN_TAC [`k:int`;`nI:int`;`nJ:int`] THEN REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ler")
   (CONJUNCTS_THEN2 (LABEL_TAC "jh") (LABEL_TAC "km"))) THEN
  REWRITE_TAC[tile_J] THEN MATCH_MP_TAC DYHO_MEET_NEST THEN CONJ_TAC THENL
   [USE_THEN "km" MP_TAC THEN REWRITE_TAC[tile_k] THEN
     INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `tile_Jr tau SUBSET dyho m nhat` (LABEL_TAC "jr_jh") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `tile_J tau` THEN
    CONJ_TAC THENL [REWRITE_TAC[TILE_JR_SUBSET_J]; USE_THEN
      "jh" ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `tile_Jr tau SUBSET dyho k nJ` (LABEL_TAC "jr_j") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `tile_Jr (k,nI,nJ)` THEN
     CONJ_TAC THENL
     [USE_THEN "ler" MP_TAC THEN REWRITE_TAC[tile_ler] THEN SIMP_TAC[];
      REWRITE_TAC[tile_Jr] THEN
        MATCH_ACCEPT_TAC DYHO_JR_SUBSET_J]; ALL_TAC] THEN
  MP_TAC(ISPEC `tau:int#int#int` TILE_JR_NONEMPTY) THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    DISCH_THEN(X_CHOOSE_TAC `x:real`) THEN
  REWRITE_TAC[SET_RULE `~DISJOINT s t <=> ?x. x IN s /\ x IN t`] THEN
  EXISTS_TAC `x:real` THEN CONJ_TAC THENL
   [USE_THEN "jr_j" MP_TAC THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    USE_THEN "jr_jh" MP_TAC THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* KEEP tree containment: J^l_sigma SUBSET Jhat (via J^l_sigma SUBSET        *)
(* J_sigma SUBSET Jhat).                                                     *)
let TILE_TREE_JHAT_KEEP = prove
 (`!(s:int#int#int) (tau:int#int#int) m nhat.
     tile_ler s tau /\ tile_J tau SUBSET dyho m nhat /\ tile_k s <= m
     ==> tile_Jl s SUBSET dyho m nhat`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC SUBSET_TRANS THEN
  EXISTS_TAC `tile_J s` THEN REWRITE_TAC[TILE_JL_SUBSET_J] THEN
  MATCH_MP_TAC TILE_TREE_J_IN_JHAT THEN
  EXISTS_TAC `tau:int#int#int` THEN ASM_REWRITE_TAC[]);;

(* KILL tree containment: Jhat SUBSET J^r_sigma when k_sigma > m. Jhat       *)
(* (scale                                                                    *)
(* m) meets J^r_sigma (scale k_sigma-1 >= m) at the shared J^r_tau, Jhat     *)
(* finer.                                                                    *)
let TILE_TREE_JHAT_KILL = prove
 (`!(s:int#int#int) (tau:int#int#int) m nhat.
     tile_ler s tau /\ tile_J tau SUBSET dyho m nhat /\ m < tile_k s
     ==> dyho m nhat SUBSET tile_Jr s`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!k nI nJ tau m nhat. P (k,nI,nJ) tau m nhat)
    ==> (!s tau m nhat. P s tau m nhat)`) THEN
  MAP_EVERY X_GEN_TAC [`k:int`;`nI:int`;`nJ:int`] THEN REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ler")
   (CONJUNCTS_THEN2 (LABEL_TAC "jh") (LABEL_TAC "km"))) THEN
  REWRITE_TAC[tile_Jr] THEN MATCH_MP_TAC DYHO_MEET_NEST THEN CONJ_TAC THENL
   [USE_THEN "km" MP_TAC THEN REWRITE_TAC[tile_k] THEN
     INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `tile_Jr tau SUBSET dyho m nhat` (LABEL_TAC "jr_jh") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `tile_J tau` THEN
    CONJ_TAC THENL [REWRITE_TAC[TILE_JR_SUBSET_J]; USE_THEN
      "jh" ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
    `tile_Jr tau SUBSET dyho (k - &1) (&2 * nJ + &1)` (LABEL_TAC "jr_jr") THENL
   [USE_THEN "ler" MP_TAC THEN REWRITE_TAC[tile_ler; tile_Jr] THEN
     SIMP_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC `tau:int#int#int` TILE_JR_NONEMPTY) THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    DISCH_THEN(X_CHOOSE_TAC `x:real`) THEN
  REWRITE_TAC[SET_RULE `~DISJOINT s t <=> ?x. x IN s /\ x IN t`] THEN
  EXISTS_TAC `x:real` THEN CONJ_TAC THENL
   [USE_THEN "jr_jh" MP_TAC THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    USE_THEN "jr_jr" MP_TAC THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* M4 (A-tree) capstones: the tree-level per-tile step-(iv) identities.      *)
(* Given sigma <=_r tau and J_tau SUBSET Jhat = dyho m nhat, the KEEP/KILL   *)
(* pointwise identities hold with anchor yhat = dyho_mid m nhat (midpoint of *)
(* Jhat).  These are the direct inputs to step (B) (the transform identity). *)
(* ------------------------------------------------------------------------- *)

(* KILL band (Fremlin (h)(iii) arithmetic): for z in the sharp support       *)
(* [tile_ymid s +- (1/5)2^k], the anchor dyho_mid m nhat is >= (3/5)2^m      *)
(* away. From dyho m nhat SUBSET tile_Jr s (DYHO_SUBSET_ENDPOINTS at scales  *)
(* m, k-1 gives (2nJ+1)2^{k-1} <= nhat 2^m, i.e. Jhat's left edge >=         *)
(* J^r_sigma's), and 2^k = 2*2^{k-1} >= 2*2^m; the (1/20)2^k + (1/2)2^m >=   *)
(* (3/5)2^m closes it.                                                       *)
let TILE_TREE_KILL_BAND = prove
 (`!(s:int#int#int) m nhat.
     dyho m nhat SUBSET tile_Jr s /\ m < tile_k s
     ==> (!z. tile_ymid s - &1 / &5 * &2 zpow (tile_k s) <= z /\
              z <= tile_ymid s + &1 / &5 * &2 zpow (tile_k s)
              ==> &3 * &2 zpow m / &5 <= abs(z - dyho_mid m nhat))`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!k nI nJ m nhat. P (k,nI,nJ) m nhat) ==> (!s m nhat. P s m nhat)`) THEN
  MAP_EVERY X_GEN_TAC [`k:int`;`nI:int`;`nJ:int`;`m:int`;`nhat:int`] THEN
  REWRITE_TAC[tile_Jr; tile_ymid; tile_k] THEN STRIP_TAC THEN
  X_GEN_TAC `z:real` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`m:int`; `k - &1:int`; `nhat:int`; `&2 * nJ + &1:int`]
    DYHO_SUBSET_ENDPOINTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1) THEN DISCH_TAC THEN
  REWRITE_TAC[dyho_mid] THEN
  MP_TAC(ISPEC `k:int` ZPOWK_HALF) THEN
  MP_TAC(ISPECL [`m:int`; `k - &1:int`] ZPOW2_MONOE) THEN
  ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 zpow m /\ &0 < &2 zpow (k - &1)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[dyho_mid; int_add_th; int_mul_th;
    int_of_num_th]) THEN
  REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC);;

(* KEEP tree identity: sigma <=_r tau /\ J_tau SUBSET Jhat /\ k_sigma <= m   *)
(* ==> phihat_sigma * cpsi(m, midpt Jhat) = phihat_sigma.                    *)
(* TILE_TREE_JHAT_KEEP                                                       *)
(* (J^l_sigma SUBSET Jhat) then PHISIG_CPSI_KEEP_GEOM.                       *)
let PHISIG_CPSI_KEEP_TREE = prove
 (`!(s:int#int#int) (tau:int#int#int) m nhat y.
     tile_ler s tau /\ tile_J tau SUBSET dyho m nhat /\ tile_k s <= m
     ==> fourier (phi_sigma s carleson_phi) y * cpsi m (dyho_mid m nhat) y =
         fourier (phi_sigma s carleson_phi) y`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC PHISIG_CPSI_KEEP_GEOM THEN
  MATCH_MP_TAC TILE_TREE_JHAT_KEEP THEN
  EXISTS_TAC `tau:int#int#int` THEN ASM_REWRITE_TAC[]);;

(* KILL tree identity: sigma <=_r tau /\ J_tau SUBSET Jhat /\ m < k_sigma    *)
(* ==> phihat_sigma * cpsi(m, midpt Jhat) = 0. TILE_TREE_JHAT_KILL (Jhat     *)
(* SUBSET                                                                    *)
(* J^r_sigma) then TILE_TREE_KILL_BAND (the band) then                       *)
(* PHISIG_CPSI_KILL_CLOSED.                                                  *)
let PHISIG_CPSI_KILL_TREE = prove
 (`!(s:int#int#int) (tau:int#int#int) m nhat y.
     tile_ler s tau /\ tile_J tau SUBSET dyho m nhat /\ m < tile_k s
     ==> fourier (phi_sigma s carleson_phi) y * cpsi m (dyho_mid m nhat) y =
         Cx(&0)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC PHISIG_CPSI_KILL_CLOSED THEN
  MATCH_MP_TAC TILE_TREE_KILL_BAND THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC TILE_TREE_JHAT_KILL THEN
  EXISTS_TAC `tau:int#int#int` THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* M4 STEP (B) = Fremlin 286(h)(iv)/(v) transform identity: gt_m^ = cpsi     *)
(* gt^.                                                                      *)
(* For the m-cutoff tree sub-sum gt_m (only tiles with k_sigma <= m) and the *)
(* full tree sum ftilde = gt, with J_tau SUBSET Jhat = dyho m nhat:          *)
(*   fourier(gt_m) y = cpsi m (dyho_mid m nhat) y * fourier(gt) y.           *)
(* FTILDE_FHAT pushes both transforms onto the tiles; VSUM_COMPLEX_LMUL      *)
(* pulls                                                                     *)
(* cpsi into the full sum; VSUM_SUPERSET drops the k>m terms (KILL_TREE = 0) *)
(* and VSUM_EQ keeps the k<=m terms (KEEP_TREE: phihat*cpsi = phihat).       *)
let FTILDE_CPSI_FHAT = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau m nhat y.
     FINITE P /\ tile_J tau SUBSET dyho m nhat
     ==> fourier (\x. vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
                          (\s. c s * phi_sigma s carleson_phi x)) y =
         cpsi m (dyho_mid m nhat) y *
         fourier (\x. vsum {s | s IN P /\ tile_ler s tau}
                          (\s. c s * phi_sigma s carleson_phi x)) y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `FINITE {s:int#int#int | s IN P /\ tile_ler s tau /\ tile_k s <= m} /\
    FINITE {s:int#int#int | s IN P /\ tile_ler s tau}`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC FINITE_RESTRICT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[FTILDE_FHAT] THEN
  ASM_SIMP_TAC[GSYM VSUM_COMPLEX_LMUL] THEN
  CONV_TAC SYM_CONV THEN MATCH_MP_TAC EQ_TRANS THEN
  EXISTS_TAC
   `vsum {s:int#int#int | s IN P /\ tile_ler s tau /\ tile_k s <= m}
         (\x. cpsi m (dyho_mid m nhat) y * c x * fourier (phi_sigma x
           carleson_phi) y)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC VSUM_SUPERSET THEN CONJ_TAC THENL
     [SET_TAC[];
      X_GEN_TAC `s:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN
        STRIP_TAC THEN
      BETA_TAC THEN
      SUBGOAL_THEN `m < tile_k s` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o check (is_neg o concl)) THEN
        ASM_REWRITE_TAC[] THEN INT_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `fourier (phi_sigma s carleson_phi) y * cpsi m (dyho_mid m nhat) y =
         Cx(&0)`
       MP_TAC THENL
       [MATCH_MP_TAC PHISIG_CPSI_KILL_TREE THEN
         EXISTS_TAC `tau:int#int#int` THEN
        ASM_REWRITE_TAC[];
        REWRITE_TAC[COMPLEX_VEC_0] THEN CONV_TAC COMPLEX_RING]];
    MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN
    REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN BETA_TAC THEN
    SUBGOAL_THEN
     `fourier (phi_sigma s carleson_phi) y * cpsi m (dyho_mid m nhat) y =
      fourier (phi_sigma s carleson_phi) y`
     MP_TAC THENL
     [MATCH_MP_TAC PHISIG_CPSI_KEEP_TREE THEN EXISTS_TAC `tau:int#int#int` THEN
      ASM_REWRITE_TAC[];
      CONV_TAC COMPLEX_RING]]);;

(* Tile-level restatement of TILE_JL_DISJOINT (on tile_Jr/tile_Jl/tile_k).   *)
let TILE_JL_DISJOINT_T = prove
 (`!(s:int#int#int) (t:int#int#int).
     ~(tile_k s = tile_k t) /\ ~(tile_Jr s INTER tile_Jr t = {})
     ==> tile_Jl s INTER tile_Jl t = {}`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_Jr; tile_Jl; tile_k] THEN REWRITE_TAC[TILE_JL_DISJOINT]);;

(* ------------------------------------------------------------------------- *)
(* 286Fc / 286E(b-iv): TREE FREQUENCY ORTHOGONALITY.  Two tree tiles s, t    *)
(* (both <=_r tau, so J^r_tau SUBSET J^r_s cap J^r_t is nonempty) at         *)
(* DIFFERENT                                                                 *)
(* scales (k_s <> k_t) have ORTHOGONAL test functions, because their left    *)
(* frequency-halves J^l are disjoint (TILE_JL_DISJOINT_T) and phi_sigma^ is  *)
(* supported in J^l (PHISIG_CARLESON_ORTHO_JL).  This is the fact that makes *)
(* the alpha3 off-diagonal-J block VANISH on the tree, so ||g~||_2^2 reduces *)
(* to                                                                        *)
(* the diagonal-J block (CARLESON_DIAGBLOCK_LE).                             *)
(* ------------------------------------------------------------------------- *)
let PHISIG_TREE_ORTHO = prove
 (`!(s:int#int#int) (t:int#int#int) tau.
     tile_ler s tau /\ tile_ler t tau /\ ~(tile_k s = tile_k t)
     ==> integral (:real^1)
           (\z. phi_sigma s carleson_phi (drop z) *
                cnj(phi_sigma t carleson_phi (drop z))) = Cx(&0)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC PHISIG_CARLESON_ORTHO_JL THEN
  REWRITE_TAC[DISJOINT] THEN
  MATCH_MP_TAC TILE_JL_DISJOINT_T THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
  MP_TAC(ISPEC `tau:int#int#int` TILE_JR_NONEMPTY) THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  DISCH_THEN(X_CHOOSE_TAC `y:real`) THEN EXISTS_TAC `y:real` THEN
  RULE_ASSUM_TAC(REWRITE_RULE[tile_ler]) THEN ASM SET_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Tile frequency intervals are nonempty (dyho always contains its left      *)
(* edge).                                                                    *)
(* ------------------------------------------------------------------------- *)
let TILE_J_NONEMPTY = prove
 (`!s:int#int#int. ~(tile_J s = {})`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_J; GSYM MEMBER_NOT_EMPTY] THEN
  MESON_TAC[DYHO_NONEMPTY]);;


(* ========================================================================= *)
(* 286J(c) tile helpers.  The product-meet relation mt s t = "the k-dilates  *)
(* meet AND the frequency cells meet" is what GREEDY_CAPTURE consumes; it is *)
(* symmetric + reflexive, and its negation forces the g^-1[J] cap I^(k)      *)
(* region                                                                    *)
(* products to be disjoint (Fremlin mt286.tex 936-940).                      *)
(* ========================================================================= *)

(* dyho cells are nonempty (their left endpoint n*2^k lies in [n             *)
(* 2^k,(n+1)2^k)).                                                           *)

(* the tile centre lies in every dilate (|x_s - x_s| = 0 < half-width).      *)
let TILE_XMID_IN_IDIL = prove
 (`!s:int#int#int k. tile_xmid s IN tile_Idil s k`,
  REWRITE_TAC[tile_Idil; IN_ELIM_THM; REAL_SUB_REFL; REAL_ABS_NUM] THEN
  REPEAT GEN_TAC THEN MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC);;

(* the frequency cell tile_J s is a dyho, hence nonempty.                    *)

(* product-meet is symmetric.                                                *)
let TILE_PRODMEET_SYM = prove
 (`!k s t:int#int#int.
     (~(tile_Idil s k INTER tile_Idil t k = {}) /\
      ~(tile_J s INTER tile_J t = {}))
     ==> (~(tile_Idil t k INTER tile_Idil s k = {}) /\
          ~(tile_J t INTER tile_J s = {}))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[INTER_COMM] THEN SIMP_TAC[]);;

(* product-meet is reflexive (centre in the dilate; J nonempty).             *)
let TILE_PRODMEET_REFL = prove
 (`!k s:int#int#int.
     ~(tile_Idil s k INTER tile_Idil s k = {}) /\
     ~(tile_J s INTER tile_J s = {})`,
  REPEAT GEN_TAC THEN REWRITE_TAC[INTER_IDEMPOT] THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `tile_xmid s` THEN REWRITE_TAC[TILE_XMID_IN_IDIL];
    REWRITE_TAC[TILE_J_NONEMPTY]]);;

(* ~mt s t => the region products g^-1[J] cap I^(k) are disjoint. Either the *)
(* I^(k)'s are disjoint (kills the I^(k)-factor) or the J's are disjoint (no *)
(* x                                                                         *)
(* has h x in both J's).  (Fremlin lines 936-940: product tiles disjoint =>  *)
(* g^-1[J_l] cap I^(k)_l disjoint from g^-1[J_m] cap I^(k)_m.)               *)
let TILE_PRODMEET_SSET_DISJOINT = prove
 (`!(E:real->bool) (h:real->real) k s t:int#int#int.
     ~(~(tile_Idil s k INTER tile_Idil t k = {}) /\
       ~(tile_J s INTER tile_J t = {}))
     ==> DISJOINT ({x | x IN E /\ h x IN tile_J s} INTER tile_Idil s k)
                  ({x | x IN E /\ h x IN tile_J t} INTER tile_Idil t k)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[DE_MORGAN_THM] THEN STRIP_TAC THEN
  POP_ASSUM MP_TAC THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM; NOT_IN_EMPTY] THEN
  MESON_TAC[]);;

(* J-nesting for the alpha2/alpha3 G_K containment (Fremlin 286L step c).    *)
(* Two                                                                       *)
(* tiles both above tau (J_tau SUBSET both) with k_s <= k_ups nest forward:  *)
(* J_s SUBSET J_ups. Since J_tau (nonempty) sits in both dyho's, DYHO_NEST   *)
(* at any                                                                    *)
(* shared point (the left edge of J_tau) gives the coarser-scale             *)
(* containment.                                                              *)
let TILE_J_SUBSET_TILE_J = prove
 (`!(s:int#int#int) ups tau.
     tile_J tau SUBSET tile_J s /\ tile_J tau SUBSET tile_J ups /\
     tile_k s <= tile_k ups
     ==> tile_J s SUBSET tile_J ups`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
   [`ks:int`;`nIs:int`;`nJs:int`;`ku:int`;`nIu:int`;`nJu:int`;
    `kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_J; tile_k] THEN STRIP_TAC THEN
  MATCH_MP_TAC DYHO_NEST THEN
  EXISTS_TAC `real_of_int nJt * &2 zpow kt` THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
  FIRST_X_ASSUM(MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  REWRITE_TAC[DYHO_NONEMPTY]);;

(* Hence the RIGHT half J^r_s also lands inside J_ups (J^r_s SUBSET J_s      *)
(* SUBSET                                                                    *)
(* J_ups).  This is the step-c containment that puts the W2 per-tile regions *)
(* E cap h^-1[J^r_s] cap K inside the single cell E cap h^-1[J_ups] cap K =  *)
(* G_K,                                                                      *)
(* so SUM_INTEGRAL_LE_MEASURE (over the common domain G_K) applies.          *)
let TILE_JR_SUBSET_TILE_J = prove
 (`!(s:int#int#int) ups tau.
     tile_J tau SUBSET tile_J s /\ tile_J tau SUBSET tile_J ups /\
     tile_k s <= tile_k ups
     ==> tile_Jr s SUBSET tile_J ups`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `tile_J (s:int#int#int)` THEN
  REWRITE_TAC[TILE_JR_SUBSET_J] THEN
  MATCH_MP_TAC TILE_J_SUBSET_TILE_J THEN
  EXISTS_TAC `tau:int#int#int` THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286L(f-i): the J^r frequency-disjointness gate for the W2 (alpha2) sum.   *)
(* If sigma has the coarser frequency scale (k_sig <= k_ups - 1) and J_tau   *)
(* is                                                                        *)
(* included in J_sig (true for every sig >= tau in P) while J^r_tau is NOT   *)
(* included in J^r_ups (true for every ups NOT in the tree T_tau), then the  *)
(* right halves J^r_sig, J^r_ups are disjoint.  Proof: J^r_sig SUBSET J_sig  *)
(* (TILE_JR_SUBSET_J); if J^r_sig, J^r_ups met at y then y IN J_sig, and     *)
(* since k_sig <= k_ups - 1 = scale(J^r_ups) the laminar nesting DYHO_NEST   *)
(* forces J_sig SUBSET J^r_ups, whence J^r_tau SUBSET J_tau SUBSET J_sig     *)
(* SUBSET J^r_ups, contradicting the tree hypothesis.                        *)
(* ------------------------------------------------------------------------- *)
let TILE_JR_FREQ_DISJOINT = prove
 (`!(sig:int#int#int) (ups:int#int#int) tau.
     tile_J tau SUBSET tile_J sig /\ ~(tile_Jr tau SUBSET tile_Jr ups) /\
     tile_k sig <= tile_k ups - &1
     ==> tile_Jr sig INTER tile_Jr ups = {}`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
   [`ks:int`;`nIs:int`;`nJs:int`;`ku:int`;`nIu:int`;`nJu:int`;
    `kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_J; tile_Jr; tile_k] THEN STRIP_TAC THEN
  REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `y:real` THEN STRIP_TAC THEN
  SUBGOAL_THEN `y IN dyho ks nJs` ASSUME_TAC THENL
   [MP_TAC(ISPEC `(ks:int,nIs:int,nJs:int)` TILE_JR_SUBSET_J) THEN
    REWRITE_TAC[tile_Jr; tile_J; SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `dyho ks nJs SUBSET dyho (ku - &1) (&2 * nJu + &1)` ASSUME_TAC THENL
   [MATCH_MP_TAC DYHO_NEST THEN EXISTS_TAC `y:real` THEN ASM_REWRITE_TAC[] THEN
    ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
    `dyho (kt - &1) (&2 * nJt + &1) SUBSET dyho (ku - &1) (&2 * nJu + &1)`
    (fun th -> ASM_MESON_TAC[th; TILE_JR_SUBSET_J; tile_J; tile_Jr;
                             SUBSET_TRANS]) THEN
  MP_TAC(ISPEC `(kt:int,nIt:int,nJt:int)` TILE_JR_SUBSET_J) THEN
  REWRITE_TAC[tile_Jr; tile_J] THEN ASM SET_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286L(f-ii): the single-scale collapse. Two W2 tiles sigma, sigma' -- each *)
(* below tau (tile_le, true for every member of P) but outside the tree      *)
(* T_tau                                                                     *)
(* (~tile_ler .. tau, the W2 defining condition) -- whose right frequency-   *)
(* halves J^r share a common point t must have the SAME scale. Hence, for    *)
(* any                                                                       *)
(* fixed x, all W2 tiles sigma with h(x) IN J^r_sigma collapse to one        *)
(* frequency                                                                 *)
(* scale k, so v2(x) is a single-scale sum and V2_SLICE_BOUND applies.       *)
(* Proof: the tile order unfolds tile_le/tile_ler to J_tau SUBSET J_s and    *)
(* ~(J^r_tau SUBSET J^r_s); TILE_JR_FREQ_DISJOINT (applied both              *)
(* orientations)                                                             *)
(* then rules out k_s <= k_s'-1 and k_s' <= k_s-1, forcing k_s = k_s'.       *)
(* ------------------------------------------------------------------------- *)
let TILE_JR_COLLAPSE = prove
 (`!s s' tau t.
     tile_le s tau /\ tile_le s' tau /\
     ~(tile_ler s tau) /\ ~(tile_ler s' tau) /\
     t IN tile_Jr s /\ t IN tile_Jr s'
     ==> tile_k s = tile_k s'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `tile_J tau SUBSET tile_J s /\ tile_J tau SUBSET tile_J s' /\
                ~(tile_Jr tau SUBSET tile_Jr s) /\
                ~(tile_Jr tau SUBSET tile_Jr s')`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[tile_le; tile_ler]) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(INT_ARITH `~(a:int <= b - &1) /\ ~(b <= a - &1) ==> a = b`) THEN
  CONJ_TAC THEN DISCH_TAC THENL
   [MP_TAC(ISPECL [`s:int#int#int`; `s':int#int#int`; `tau:int#int#int`]
       TILE_JR_FREQ_DISJOINT);
    MP_TAC(ISPECL [`s':int#int#int`; `s:int#int#int`; `tau:int#int#int`]
       TILE_JR_FREQ_DISJOINT)] THEN
  ASM_REWRITE_TAC[] THEN ASM SET_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* W2-slice structure: for a set A of W2 tiles all sharing a common          *)
(* frequency                                                                 *)
(* point t in their J^r, the collapse (TILE_JR_COLLAPSE) forces one common   *)
(* scale k, and same-scale tree tiles have distinct I-indices                *)
(* (TILE_TREE_FST_SND_INJ) so FST o SND is injective on A. These are exactly *)
(* the two hypotheses V2_SLICE_BOUND needs.  Packaged so the pointwise v2    *)
(* bound below applies without re-deriving them.                              *)
(* ------------------------------------------------------------------------- *)
let TILE_JR_SLICE_INJ = prove
 (`!A tau t.
     (!s. s IN A ==> tile_le s tau /\ ~(tile_ler s tau) /\ t IN tile_Jr s)
     ==> (!u1 u2. u1 IN A /\ u2 IN A /\ FST(SND u1) = FST(SND(u2:int#int#int))
                  ==> u1 = u2) /\
         (?k. !s. s IN A ==> tile_k s = k)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `A:(int#int#int)->bool = {}` THENL
   [CONJ_TAC THENL
     [ASM_REWRITE_TAC[NOT_IN_EMPTY];
      EXISTS_TAC `&0:int` THEN ASM_REWRITE_TAC[NOT_IN_EMPTY]];
    ALL_TAC] THEN
  FIRST_X_ASSUM(fun th -> ASSUME_TAC th) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `s0:int#int#int` o
    REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
  SUBGOAL_THEN `!s. s IN A ==> tile_k s = tile_k (s0:int#int#int)`
    ASSUME_TAC THENL
   [X_GEN_TAC `s1:int#int#int` THEN DISCH_TAC THEN
    MATCH_MP_TAC TILE_JR_COLLAPSE THEN
    MAP_EVERY EXISTS_TAC [`tau:int#int#int`; `t:real`] THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `s1:int#int#int` th) THEN
                            MP_TAC(SPEC `s0:int#int#int` th)) THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`u1:int#int#int`; `u2:int#int#int`] THEN
     STRIP_TAC THEN
    MP_TAC(ISPECL [`A:(int#int#int)->bool`; `tile_k (s0:int#int#int)`;
                   `tau:int#int#int`; `u1:int#int#int`; `u2:int#int#int`]
                  TILE_TREE_FST_SND_INJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `r:int#int#int` THEN DISCH_TAC THEN
      CONJ_TAC THENL
       [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN ASM_REWRITE_TAC[];
        FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `r:int#int#int` th)) THEN
        ASM_SIMP_TAC[]];
      DISCH_THEN ACCEPT_TAC];
    EXISTS_TAC `tile_k (s0:int#int#int)` THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286L(f-ii)+(f-iii): the pointwise v2 bound.  For any finite slice A of W2 *)
(* tiles (each tile_le tau, outside T_tau, and with t = h(x) in J^r) the     *)
(* correlation sum sum_A |(f|phi_s) phi_s(x)| <= 2 C1 energy_f f P -- the    *)
(* collapse to one scale (TILE_JR_SLICE_INJ) reduces it to the single-scale  *)
(* V2_SLICE_BOUND.  This is the pointwise engine of |alpha2| <= int v2.      *)
(* ------------------------------------------------------------------------- *)
let V2_POINTWISE_COLLAPSE = prove
 (`?C1. &0 <= C1 /\
    !f P A tau t x.
        FINITE P /\ FINITE A /\ A SUBSET P /\
        (!s. s IN A ==> tile_le s tau /\ ~(tile_ler s tau) /\ t IN tile_Jr s)
        ==> sum A (\s. norm(carleson_ip f s * phi_sigma s carleson_phi x))
            <= &2 * C1 * energy_f f P`,
  X_CHOOSE_TAC `C1:real` V2_SLICE_BOUND THEN EXISTS_TAC `C1:real` THEN
  POP_ASSUM STRIP_ASSUME_TAC THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P` ASSUME_TAC THENL
   [MATCH_MP_TAC ENERGY_F_POS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`A:(int#int#int)->bool`; `tau:int#int#int`; `t:real`]
                TILE_JR_SLICE_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `k:int`)) THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
   [`f:real->complex`; `P:(int#int#int)->bool`; `A:(int#int#int)->bool`;
    `k:int`; `x:real`]) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Per-tile "move the norm inside the integral" brick for the |alpha2| <=    *)
(* int v2 step.  norm(cip . int_{lift A} phi) = |cip| norm(int phi) <=       *)
(* |cip| int_A |phi| = int_A (|cip| |phi|), for measurable A.  The complex   *)
(* norm-of-integral bound is INTEGRAL_NORM_BOUND_INTEGRAL (norm(int f) <=    *)
(* drop(int g) when norm(f) <= drop g); the real_integral / vector integral  *)
(* bridge is REAL_INTEGRAL (integrability from PHISIG_NORM_INTEGRABLE_       *)
(* MEASURABLE) and REAL_INTEGRABLE_ON (for the dominating g).  This is the   *)
(* per-summand step; summing over the W2 slice + V2_POINTWISE_COLLAPSE gives *)
(* the pointwise v2 <= 2 C1 gamma inside int_{G_K}.                          *)
(* ------------------------------------------------------------------------- *)
let PHISIG_NORM_INTEGRAL_BOUND = prove
 (`!(f:real->complex) s A.
     real_measurable A
     ==> norm(carleson_ip f s *
              integral (IMAGE lift A) (\z. phi_sigma s carleson_phi (drop z)))
         <= real_integral A
              (\x. norm(carleson_ip f s) * norm(phi_sigma s carleson_phi x))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[COMPLEX_NORM_MUL] THEN
  SUBGOAL_THEN
   `real_integral A
     (\x. norm(carleson_ip f s) * norm(phi_sigma s carleson_phi x)) =
    norm(carleson_ip (f:real->complex) s) *
    real_integral A (\x. norm(phi_sigma s carleson_phi x))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LMUL THEN
    MATCH_MP_TAC PHISIG_NORM_INTEGRABLE_MEASURABLE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [REWRITE_TAC[NORM_POS_LE]; ALL_TAC] THEN
  MP_TAC(ISPECL [`s:int#int#int`; `A:real->bool`]
                PHISIG_NORM_INTEGRABLE_MEASURABLE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  ASM_SIMP_TAC[REAL_INTEGRAL] THEN
  MATCH_MP_TAC INTEGRAL_NORM_BOUND_INTEGRAL THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MP_TAC(ISPECL [`s:int#int#int`; `A:real->bool`]
                  PHISIG_ABS_INTEGRABLE_MEASURABLE) THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[REAL_INTEGRABLE_ON]) THEN
    REWRITE_TAC[];
    REWRITE_TAC[o_DEF; LIFT_DROP; NORM_LIFT] THEN X_GEN_TAC `z:real^1` THEN
    DISCH_TAC THEN REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The pointwise cap for the alpha2 int-v2 bound, packaged exactly as        *)
(* SUM_INTEGRAL_LE_MEASURE consumes it.  For x IN G_K the tiles s of the W2  *)
(* slice whose region {y | h y IN J^r_s} INTER K contains x all have h(x) IN *)
(* J^r_s -- a common-frequency slice at t = h(x) -- so their summed          *)
(* |cip.phi|                                                                 *)
(* is <= 2 C1 gamma by V2_POINTWISE_COLLAPSE.  SUM_RESTRICT_SET rewrites the *)
(* indicator-sum over A as the plain sum over {s IN A | x IN region s}, on   *)
(* which V2_POINTWISE_COLLAPSE (with A := that set) applies.                 *)
(* ------------------------------------------------------------------------- *)
let V2_POINTWISE_CAP = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) (P:(int#int#int)->bool) A tau E h a p x.
      FINITE P /\ FINITE A /\ A SUBSET P /\
      (!s. s IN A ==> tile_le s tau /\ ~(tile_ler s tau))
      ==> sum A (\s. if x IN {y | y IN E /\ h y IN tile_Jr s} INTER dyho a p
                     then norm(carleson_ip f s) *
                          norm(phi_sigma s carleson_phi x)
                     else &0)
          <= &2 * C1 * energy_f f P`,
  X_CHOOSE_TAC `C1:real` V2_POINTWISE_COLLAPSE THEN EXISTS_TAC `C1:real` THEN
  POP_ASSUM STRIP_ASSUME_TAC THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  REWRITE_TAC[GSYM COMPLEX_NORM_MUL] THEN
  REWRITE_TAC[GSYM SUM_RESTRICT_SET] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
   [`f:real->complex`; `P:(int#int#int)->bool`;
    `{s | s IN A /\ x IN {y | y IN E /\ h y IN tile_Jr s} INTER dyho a p}`;
    `tau:int#int#int`; `(h:real->real) x`; `x:real`]) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MATCH_MP_TAC FINITE_RESTRICT THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
      X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
      FIRST_ASSUM(MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `s:int#int#int` THEN
      GEN_REWRITE_TAC (LAND_CONV) [IN_ELIM_THM] THEN
      REWRITE_TAC[IN_INTER; IN_ELIM_THM] THEN STRIP_TAC THEN
      SUBGOAL_THEN `tile_le s tau /\ ~(tile_ler (s:int#int#int) tau)`
        STRIP_ASSUME_TAC THENL
       [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]]];
    DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* 286L alpha2 PER-CELL bound (abstract in the enclosing set G). The sum     *)
(* over                                                                      *)
(* a W2 slice A of the tile correlations norm(cip.INT_{E cap h^-1[J^r_s] cap *)
(* K}                                                                        *)
(* phi_s) is <= 2 C1 gamma mu G, provided every per-tile region sits inside  *)
(* a                                                                         *)
(* single measurable G (in the application G = G_K, via                      *)
(* TILE_JR_SUBSET_TILE_J).                                                   *)
(* Chain: per-tile PHISIG_NORM_INTEGRAL_BOUND (norm(cip.INT) <= int_region   *)
(* |cip||phi|) under SUM_LE, then SUM_INTEGRAL_LE_MEASURE (interchange +     *)
(* measure)                                                                  *)
(* with the pointwise cap V2_POINTWISE_CAP (2 C1 gamma).  This is the alpha2 *)
(* measure-theoretic core, ready to instantiate G := G_K and sum over the    *)
(* cover.                                                                    *)
(* ------------------------------------------------------------------------- *)
let ALPHA2_CELL_ABSTRACT = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) (P:(int#int#int)->bool) A tau E h a p G.
      FINITE P /\ FINITE A /\ A SUBSET P /\ real_measurable G /\
      (!s. s IN A ==> tile_le s tau /\ ~(tile_ler s tau) /\
           ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p) SUBSET G) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real)
      ==> sum A (\s. norm(carleson_ip f s *
              integral (IMAGE lift
                ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p))
                (\z. phi_sigma s carleson_phi (drop z))))
          <= (&2 * C1 * energy_f f P) * real_measure G`,
  X_CHOOSE_TAC `C1:real` V2_POINTWISE_CAP THEN EXISTS_TAC `C1:real` THEN
  POP_ASSUM STRIP_ASSUME_TAC THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum A (\s. real_integral
      ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p)
      (\x. norm(carleson_ip (f:real->complex) s) *
           norm(phi_sigma s carleson_phi x)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN BETA_TAC THEN
    MATCH_MP_TAC PHISIG_NORM_INTEGRAL_BOUND THEN
    MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`A:(int#int#int)->bool`; `G:real->bool`;
    `\s:int#int#int. {x | x IN E /\ h x IN tile_Jr s} INTER dyho a p`;
    `\s:int#int#int x. norm(carleson_ip (f:real->complex) s) *
                       norm(phi_sigma s carleson_phi x)`;
    `&2 * C1 * energy_f (f:real->complex) P`] SUM_INTEGRAL_LE_MEASURE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN CONJ_TAC THENL
       [FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `s:int#int#int` th)) THEN
        ASM_SIMP_TAC[];
        MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
        MATCH_MP_TAC PHISIG_NORM_INTEGRABLE_MEASURABLE THEN
        MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[]];
      X_GEN_TAC `x:real` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPECL
       [`f:real->complex`; `P:(int#int#int)->bool`; `A:(int#int#int)->bool`;
        `tau:int#int#int`; `E:real->bool`; `h:real->real`; `a:int`; `p:int`;
        `x:real`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
        FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `s:int#int#int` th)) THEN
        ASM_SIMP_TAC[];
        REWRITE_TAC[]]];
    DISCH_THEN(fun th -> MATCH_MP_TAC REAL_LE_TRANS THEN
                         EXISTS_TAC (rand(concl th)) THEN
                         CONJ_TAC THENL [MATCH_ACCEPT_TAC th; ALL_TAC]) THEN
    REWRITE_TAC[REAL_LE_REFL]]);;

(* ------------------------------------------------------------------------- *)
(* 286L alpha2 PER-CELL bound (concrete G_K).  Instantiates ALPHA2_CELL_     *)
(* ABSTRACT at G := G_K = E cap h^-1[J_ups] cap dyho a p (ups from           *)
(* GK_MEASURE_                                                               *)
(* BOUND_STRONG, tile_le ups tau, k_ups = -(a+1)) and chains its measure     *)
(* bound.                                                                    *)
(* The W2 tile set is {s IN P | tile_le s tau /\ ~tile_ler s tau /\ k_s <    *)
(* -a}                                                                       *)
(* (s below tau, outside T_tau, coarser than l_K = -a).  Each region E cap   *)
(* h^-1[J^r_s] cap K lands in G_K via TILE_JR_SUBSET_TILE_J (J^r_s SUBSET    *)
(* J_ups:                                                                    *)
(* J_tau SUBSET J_s,J_ups from tile_le, and k_s < -a i.e. k_s <= -a-1 =      *)
(* k_ups).                                                                   *)
(* Result: per-cell alpha2 sum <= (2 C1 energy)(2 2^a mass/w(3/2)).          *)
(* NB G_K measurability uses SC_MEASURABLE (full tile_J ups), NOT            *)
(* SC_MEASURABLE_                                                            *)
(* JR (that is for the per-tile RIGHT-half regions).                         *)
(* ------------------------------------------------------------------------- *)
let ALPHA2_CELL = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) (P:(int#int#int)->bool) tau E h a p.
      FINITE P /\ in_kcover P a p /\ (!s. s IN P ==> tile_le s tau) /\
      &2 zpow (a + &1) <= &2 zpow (--(tile_k tau)) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum {s | s IN P /\ tile_le s tau /\ ~(tile_ler s tau) /\
                   tile_k s < --a}
              (\s. norm(carleson_ip f s *
                   integral (IMAGE lift
                     ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p))
                     (\z. phi_sigma s carleson_phi (drop z))))
          <= (&2 * C1 * energy_f f P) *
             (&2 * &2 zpow a * mass_Eh E h P / cw(&3 / &2))`,
  X_CHOOSE_TAC `C1:real` ALPHA2_CELL_ABSTRACT THEN EXISTS_TAC `C1:real` THEN
  POP_ASSUM(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ABS")) THEN
  ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`; `E:real->bool`; `h:real->real`;
                 `a:int`; `p:int`;
                   `tau:int#int#int`] GK_MEASURE_BOUND_STRONG) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ups:int#int#int` STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(&2 * C1 * energy_f (f:real->complex) P) *
              real_measure ({x | x IN E /\ h x IN tile_J ups} INTER dyho a p)`
                THEN
  CONJ_TAC THENL
   [USE_THEN "ABS" (MP_TAC o SPECL
     [`f:real->complex`; `P:(int#int#int)->bool`;
      `{s | s IN P /\ tile_le s tau /\ ~(tile_ler s tau) /\ tile_k s < --a}`;
      `tau:int#int#int`; `E:real->bool`; `h:real->real`; `a:int`; `p:int`;
      `{x | x IN E /\ h x IN tile_J ups} INTER dyho a p`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_RESTRICT THEN ASM_REWRITE_TAC[];
        SET_TAC[];
        MATCH_MP_TAC SC_MEASURABLE THEN ASM_REWRITE_TAC[];
        X_GEN_TAC `s:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN
        STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC(SET_RULE
         `(!x. x IN A ==> x IN B) ==> (A INTER C) SUBSET (B INTER C)`) THEN
        X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[] THEN
        MP_TAC(ISPECL [`s:int#int#int`; `ups:int#int#int`; `tau:int#int#int`]
                      TILE_JR_SUBSET_TILE_J) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THENL
           [UNDISCH_TAC `tile_le s tau` THEN REWRITE_TAC[tile_le] THEN
             SIMP_TAC[];
            UNDISCH_TAC `tile_le ups tau` THEN REWRITE_TAC[tile_le] THEN
              SIMP_TAC[];
            ASM_INT_ARITH_TAC];
          REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[]]];
      REWRITE_TAC[]];
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[ENERGY_F_POS] THEN
        REAL_ARITH_TAC];
      ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* 286L alpha2 TOTAL: the whole W2 correlation sum over the cover.  Sums     *)
(* ALPHA2_CELL over the cover cells ap IN S (each l_K > k_tau, i.e. 2^{a+1}  *)
(* <=                                                                        *)
(* 2^{-k_tau}), factoring the s-independent (2 C1 energy)(2 mass/w(3/2)) out *)
(* (SUM_LMUL) and collapsing sum_{ap} 2^{FST ap} = sum mu(dyho(FST ap)(SND   *)
(* ap))                                                                      *)
(* <= 14 2^{-k_tau} (KCOVER_COARSE_MEASURE_BOUND, 286L a-iii; SUM_IMAGE      *)
(* reindex                                                                   *)
(* via DYHO_INJ). Result |alpha2| <= 28 C1 energy mass 2^{-k_tau}/w(3/2),    *)
(* the                                                                       *)
(* 28/w(3/2) C7-summand. Same outer-sum skeleton as                          *)
(* ALPHA0_TOTAL/ALPHA1_TOTAL,                                                *)
(* with the W2 tile-set restriction (tile_k s < --FST ap, i.e. k_s < l_K).   *)
(* NB the ~(P={}) hypothesis is needed for MASS_EH_POS (mass >= 0); without  *)
(* it                                                                        *)
(* an undischarged ~(P={}) subgoal surfaces downstream as a spurious         *)
(* MATCH_MP_                                                                 *)
(* TAC "No match".                                                           *)
(* ------------------------------------------------------------------------- *)
let ALPHA2_TOTAL = prove
 (`?C1. &0 <= C1 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) S kt nt tau.
      FINITE P /\ ~(P = {}) /\ tile_k tau = kt /\
      (!s. s IN P ==> tile_le s tau) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      FINITE S /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap) /\
                        &2 zpow (FST ap + &1) <= &2 zpow (--kt))
      ==> sum S (\ap. sum {s | s IN P /\ tile_le s tau /\ ~(tile_ler s tau) /\
                               tile_k s < --(FST ap)}
                          (\s. norm(carleson_ip f s *
                               integral (IMAGE lift ({x | x IN E /\ h x IN
                                 tile_Jr s} INTER
                                         dyho (FST ap) (SND ap)))
                                        (\z. phi_sigma s carleson_phi (drop
                                          z)))))
          <= ((&2 * C1 * energy_f f P) * (&2 * mass_Eh E h P / cw(&3 / &2))) *
             (&14 * &2 zpow (--kt))`,
  X_CHOOSE_THEN
    `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "CELL")) ALPHA2_CELL THEN
  EXISTS_TAC `C1:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P /\ &0 <= mass_Eh E h P`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[ENERGY_F_POS] THEN MATCH_MP_TAC MASS_EH_POS THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum S (\ap. ((&2 * C1 * energy_f (f:real->complex) P) *
                 (&2 * mass_Eh E h P / cw(&3 / &2))) *
                real_measure (dyho (FST ap) (SND ap)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    REWRITE_TAC[DYHO_MEASURE] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `(&2 * C1 * energy_f (f:real->complex) P) *
                (&2 * &2 zpow (FST(ap:int#int)) * mass_Eh E h P / cw(&3 / &2))`
                  THEN
    CONJ_TAC THENL
     [USE_THEN "CELL" (MP_TAC o ISPECL
       [`f:real->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
        `E:real->bool`; `h:real->real`; `FST(ap:int#int)`;
          `SND(ap:int#int)`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `ap:int#int`) THEN ASM_SIMP_TAC[];
        DISCH_THEN ACCEPT_TAC];
      REAL_ARITH_TAC];
    ONCE_REWRITE_TAC[SUM_LMUL] THEN MATCH_MP_TAC REAL_LE_LMUL THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
         [REAL_ARITH_TAC;
          MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC];
        MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
         [REAL_ARITH_TAC;
          MATCH_MP_TAC REAL_LE_DIV THEN ASM_SIMP_TAC[REAL_LT_IMP_LE; CW_POS]]];
      SUBGOAL_THEN
       `sum S (\ap. real_measure (dyho (FST ap) (SND ap))) =
        sum (IMAGE (\ap:int#int. dyho (FST ap) (SND ap)) S) (\c. real_measure
          c)`
       SUBST1_TAC THENL
       [MATCH_MP_TAC EQ_SYM THEN
        MP_TAC(ISPECL [`\ap:int#int. dyho (FST ap) (SND ap)`;
                       `\c:real->bool. real_measure c`;
                         `S:(int#int)->bool`] SUM_IMAGE) THEN
        ANTS_TAC THENL
         [REWRITE_TAC[FORALL_PAIR_THM] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
          FIRST_X_ASSUM(MP_TAC o MATCH_MP DYHO_INJ) THEN SIMP_TAC[PAIR_EQ];
          REWRITE_TAC[o_DEF]];
        ALL_TAC] THEN
      MATCH_MP_TAC KCOVER_COARSE_MEASURE_BOUND THEN
      MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`; `nt:int`] THEN
        ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* 286J's per-column analytic bound: for a finite tile set with pairwise     *)
(* disjoint spatial intervals I, the weights integrate additively over their *)
(* union, so sum_tau INT_{I_tau} w_sigma = INT_{UNION I_tau} w_sigma <=      *)
(* INT_R w_sigma = 1.  (In 286J, the tau ranging over a fixed frequency      *)
(* interval J have disjoint I -- TILE_SAMEJ_DISTINCT_DISJOINT_I.)            *)
(* ------------------------------------------------------------------------- *)

(* The tile weight is integrable on any (half-open) spatial cell I_tau.      *)
let CWTILE_INTEGRABLE_TILE_I = prove
 (`!(s:int#int#int) (t:int#int#int). cw_tile s real_integrable_on (tile_I t)`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_I] THEN
  MP_TAC(ISPECL
   [`cw_tile (ks,nIs,nJs)`;
    `real_interval[real_of_int nIt * &2 zpow (--kt),
                   (real_of_int nIt + &1) * &2 zpow (--kt)]`;
    `dyho (--kt) nIt`] REAL_INTEGRABLE_SPIKE_SET) THEN
  REWRITE_TAC[CWTILE_INTEGRABLE] THEN DISCH_THEN MATCH_MP_TAC THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN
  EXISTS_TAC `{real_of_int nIt * &2 zpow (--kt),
               (real_of_int nIt + &1) * &2 zpow (--kt)}` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[REAL_NEGLIGIBLE_INSERT; REAL_NEGLIGIBLE_SING];
    REWRITE_TAC[dyho; real_interval; SUBSET; IN_UNION; IN_DIFF; IN_ELIM_THM;
                IN_INSERT; NOT_IN_EMPTY] THEN REAL_ARITH_TAC]);;

(* When the added cell is disjoint from all others, it meets their union in  *)
(* {}.                                                                       *)
let TILE_I_INTER_UNIONS_EMPTY = prove
 (`!(x:int#int#int) (P:(int#int#int)->bool).
     ~(x IN P) /\
     (!t1 t2. t1 IN x INSERT P /\ t2 IN x INSERT P /\ ~(t1 = t2)
              ==> DISJOINT (tile_I t1) (tile_I t2))
     ==> tile_I x INTER UNIONS (IMAGE tile_I P) = {}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!w:int#int#int. w IN P ==> DISJOINT (tile_I x) (tile_I w)`
   ASSUME_TAC THENL
   [X_GEN_TAC `w:int#int#int` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`x:int#int#int`; `w:int#int#int`]) THEN
    ASM_REWRITE_TAC[IN_INSERT] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_UNIONS; IN_IMAGE; NOT_IN_EMPTY] THEN
  X_GEN_TAC `y:real` THEN
  REWRITE_TAC[TAUT `~(a /\ b) <=> a ==> ~b`] THEN DISCH_TAC THEN
  REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `u:real->bool` THEN
  REWRITE_TAC[DE_MORGAN_THM; TAUT `~(a /\ b) <=> a ==> ~b`] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:int#int#int` STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `w:int#int#int`) THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[DISJOINT; IN_INTER; NOT_IN_EMPTY]);;

(* Finite additivity of the tile weight over a disjoint family of cells I.   *)
let CWTILE_HAS_INTEGRAL_UNIONS = prove
 (`!(sig:int#int#int) (P:(int#int#int)->bool).
     FINITE P /\
     (!t1 t2. t1 IN P /\ t2 IN P /\ ~(t1 = t2) ==> DISJOINT (tile_I t1) (tile_I
       t2))
     ==> (cw_tile sig has_real_integral
          sum P (\t. real_integral (tile_I t) (cw_tile sig)))
         (UNIONS (IMAGE tile_I P))`,
  GEN_TAC THEN REWRITE_TAC[IMP_CONJ] THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN
  CONJ_TAC THENL
   [REWRITE_TAC[SUM_CLAUSES; IMAGE_CLAUSES; UNIONS_0; HAS_REAL_INTEGRAL_EMPTY];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:int#int#int`; `P:(int#int#int)->bool`] THEN
  STRIP_TAC THEN DISCH_TAC THEN
  ASM_SIMP_TAC[SUM_CLAUSES; IMAGE_CLAUSES; UNIONS_INSERT] THEN
  MATCH_MP_TAC HAS_REAL_INTEGRAL_UNION THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN
     REWRITE_TAC[CWTILE_INTEGRABLE_TILE_I];
    FIRST_X_ASSUM(MATCH_MP_TAC o
      check (fun th -> is_imp(concl th) || is_forall(concl th))) THEN
    ASM_MESON_TAC[IN_INSERT];
    ASM_SIMP_TAC[TILE_I_INTER_UNIONS_EMPTY; REAL_NEGLIGIBLE_EMPTY]]);;

(* 286J per-column bound: sum_tau INT_{I_tau} w_sigma <= INT_R w_sigma = 1.  *)
let CWTILE_SUM_DISJOINT_I_LE_1 = prove
 (`!(sig:int#int#int) (P:(int#int#int)->bool).
     FINITE P /\
     (!t1 t2. t1 IN P /\ t2 IN P /\ ~(t1 = t2) ==> DISJOINT (tile_I t1) (tile_I
       t2))
     ==> sum P (\t. real_integral (tile_I t) (cw_tile sig)) <= &1`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`cw_tile sig`; `UNIONS (IMAGE (tile_I:(int#int#int)->real->bool) P)`;
    `(:real)`;
    `sum P (\t. real_integral (tile_I t) (cw_tile sig))`; `&1`]
   HAS_REAL_INTEGRAL_SUBSET_LE) THEN
  REWRITE_TAC[SUBSET_UNIV] THEN
  ASM_SIMP_TAC[CWTILE_HAS_INTEGRAL_UNIONS; CW_TILE_FULL] THEN
  MP_TAC(SPEC `sig:int#int#int` CW_TILE_POS) THEN
  MESON_TAC[REAL_LT_IMP_LE]);;

(* ------------------------------------------------------------------------- *)
(* The tile-centre lies in its own spatial cell; hence for two distinct      *)
(* tiles                                                                     *)
(* sharing a frequency interval (whose cells are disjoint) the centre of one *)
(* is outside the other's cell -- the side condition CWTILE_MIDPOINT_TILE_I  *)
(* (286G b) needs to apply Hermite-Hadamard over that cell.                  *)
(* ------------------------------------------------------------------------- *)

let TILE_XMID_IN_I = prove
 (`!(s:int#int#int). tile_xmid s IN tile_I s`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC [`k:int`;`nI:int`;`nJ:int`] THEN
  REWRITE_TAC[tile_xmid; tile_I; dyho_mid; dyho; IN_ELIM_THM] THEN
  SUBGOAL_THEN `&0 < &2 zpow (--k)` MP_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* 286G(b), tile form keyed on the geometric side condition x_sigma NOTIN    *)
(* I_t:                                                                      *)
(* w_sigma(x_tau) mu(I_tau) <= INT_{I_tau} w_sigma. (mu(I_tau) =             *)
(* 2^(-k_tau).)                                                              *)
let CWTILE_MIDPOINT_TILE_I = prove
 (`!(s:int#int#int) (t:int#int#int). ~(tile_xmid s IN tile_I t)
     ==> cw_tile s (tile_xmid t) * (&2 zpow (--(tile_k t)))
         <= real_integral (tile_I t) (cw_tile s)`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_k] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`(ks,nIs,nJs):int#int#int`; `kt:int`; `nIt:int`; `nJt:int`]
    CWTILE_TILE_I_MIDPOINT) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  POP_ASSUM MP_TAC THEN
  REWRITE_TAC[tile_I; tile_xmid; dyho; IN_ELIM_THM; DE_MORGAN_THM;
              REAL_NOT_LE; REAL_NOT_LT] THEN
  REAL_ARITH_TAC);;

(* For distinct tiles with a common frequency interval, one centre is        *)
(* outside the other's cell (the cells are disjoint,                         *)
(* TILE_SAMEJ_DISTINCT_DISJOINT_I).                                          *)
let TILE_XMID_NOT_IN_OTHER_I = prove
 (`!(s:int#int#int) (t:int#int#int). ~(s = t) /\ tile_J s = tile_J t
     ==> ~(tile_xmid s IN tile_I t)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`s:int#int#int`;
    `t:int#int#int`] TILE_SAMEJ_DISTINCT_DISJOINT_I) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `s:int#int#int` TILE_XMID_IN_I) THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286J, off-diagonal correlation: for two distinct tiles sharing a          *)
(* frequency                                                                 *)
(* interval, |(phi_s | phi_t)| <= C INT_{I_t} w_sigma, and the column-sum    *)
(* over                                                                      *)
(* all such t is <= C.  These assemble the pointwise correlation (286Ge),    *)
(* the 286G(b) midpoint bound, and the disjoint-cell weight sum.             *)
(* ------------------------------------------------------------------------- *)

(* inv(sqrt 2^k)^2 = 2^(-k):  the k_s = k_t collapse of 286Ge's prefactor.   *)
let INV_SQRT_ZPOW_SQ = prove
 (`!k:int. inv(sqrt(&2 zpow k)) * inv(sqrt(&2 zpow k)) = &2 zpow (--k)`,
  GEN_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_INV_MUL; GSYM REAL_POW_2] THEN
  ASM_SIMP_TAC[SQRT_POW_2; REAL_LT_IMP_LE; REAL_ZPOW_NEG]);;

(* The correlation is symmetric in modulus: |(phi_s|phi_t)| =                *)
(* |(phi_t|phi_s)|                                                           *)
(* (lproduct s f g = cnj(lproduct s g f), and cnj preserves norm).  Used to  *)
(* symmetrize 286J's double sum after the AM-GM step.                        *)
let PHISIG_CORR_SYM = prove
 (`!(s:int#int#int) (t:int#int#int).
     norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop z) *
                                  cnj(phi_sigma t carleson_phi (drop z)))) =
     norm(integral (:real^1) (\z. phi_sigma t carleson_phi (drop z) *
                                  cnj(phi_sigma s carleson_phi (drop z))))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[GSYM lproduct] THEN
  MP_TAC(ISPECL [`(:real^1)`; `\z:real^1. phi_sigma s carleson_phi (drop z)`;
                 `\z:real^1. phi_sigma t carleson_phi (drop z)`] LPRODUCT_SYM)
                   THEN
  REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_CNJ_PRODUCT_INTEGRABLE THEN
    REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[COMPLEX_NORM_CNJ]);;

(* Scale-order-free cross-correlation bound: the 286G(e) estimate holds for  *)
(* EVERY                                                                     *)
(* tile pair (not just k_s <= k_t) once the weight is symmetrised to         *)
(* w_s(x_t) +                                                                *)
(* w_t(x_s). For k_s <= k_t, PHISIG_CROSS_CORRELATION gives the w_s(x_t)     *)
(* term                                                                      *)
(* (w_t(x_s) >= 0 is slack); for k_t <= k_s, swap the correlation by         *)
(* PHISIG_CORR_SYM and use the w_t(x_s) term. A convenient per-pair kernel   *)
(* with no                                                                   *)
(* scale-casing, used inside the 286L tree estimate. (It does NOT by itself  *)
(* give a                                                                    *)
(* convergent global double-sum bound for arbitrary P -- see                 *)
(* CARLESON_BLOCK_SPLIT.)                                                    *)
let PHISIG_CORR_TERM_LE = prove
 (`?C. &0 <= C /\ !(s:int#int#int) (t:int#int#int). ~(s = t) /\ tile_J s =
   tile_J t
     ==> norm(integral (:real^1)
           (\z. phi_sigma s carleson_phi (drop z) * cnj(phi_sigma t
             carleson_phi (drop z))))
         <= C * real_integral (tile_I t) (cw_tile s)`,
  MP_TAC PHISIG_CROSS_CORRELATION THEN
  DISCH_THEN(X_CHOOSE_THEN `C:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `tile_k s = tile_k t` ASSUME_TAC THENL
   [MATCH_MP_TAC TILE_J_EQ_IMP_K THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(C * (inv(sqrt(&2 zpow (tile_k s))) * inv(sqrt(&2 zpow (tile_k
    t))))) *
              cw_tile s (tile_xmid t)` THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[INT_LE_REFL]; ALL_TAC] THEN
  FIRST_ASSUM SUBST1_TAC THEN REWRITE_TAC[INV_SQRT_ZPOW_SQ] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `C * (cw_tile s (tile_xmid t) * &2 zpow (--(tile_k t)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_EQ_IMP_LE THEN CONV_TAC REAL_RING;
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CWTILE_MIDPOINT_TILE_I THEN
    MATCH_MP_TAC TILE_XMID_NOT_IN_OTHER_I THEN ASM_REWRITE_TAC[]]);;

(* Column-sum:  sum_{t in P, J_t = J_s, t<>s} |(phi_s | phi_t)| <= C.        *)
let PHISIG_COLSUM_LE = prove
 (`?C. &0 <= C /\ !(s:int#int#int) (P:(int#int#int)->bool). FINITE P
     ==> sum {t | t IN P /\ tile_J t = tile_J s /\ ~(t = s)}
             (\t. norm(integral (:real^1)
                    (\z. phi_sigma s carleson_phi (drop z) *
                         cnj(phi_sigma t carleson_phi (drop z)))))
         <= C`,
  MP_TAC PHISIG_CORR_TERM_LE THEN
  DISCH_THEN(X_CHOOSE_THEN `C:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `P:(int#int#int)->bool`] THEN
    DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum {t | t IN P /\ tile_J t = tile_J s /\ ~(t = s)}
                  (\t. C * real_integral (tile_I t) (cw_tile s))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN
    ASM_SIMP_TAC[FINITE_RESTRICT; IN_ELIM_THM] THEN
    REPEAT STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SUM_LMUL] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CWTILE_SUM_DISJOINT_I_LE_1 THEN
    ASM_SIMP_TAC[FINITE_RESTRICT] THEN
    REWRITE_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
    MATCH_MP_TAC TILE_SAMEJ_DISTINCT_DISJOINT_I THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286J diagonal term: (phi_sigma | phi_sigma) = ||phi_sigma||_2^2 = a fixed *)
(* constant (the tile map preserves the L^2 norm, PHISIG_CARLESON_L2).  This *)
(* is the sigma = tau contribution to 286J's column sum.                     *)
(* ------------------------------------------------------------------------- *)

(* norm(phi_sigma)^2 is integrable (Schwartz).                               *)
let PHISIG_CARLESON_NORMSQ_INT = prove
 (`!(s:int#int#int).
     (\x:real^1. lift(norm(phi_sigma s carleson_phi (drop x)) pow 2))
       integrable_on (:real^1)`,
  GEN_TAC THEN MATCH_MP_TAC SCHWARTZ_NORMSQ_INTEGRABLE THEN
  REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]);;

(* The weighted-integral value is the (sigma-independent) squared L^2 norm.  *)
let PHISIG_DIAG_INTSQ = prove
 (`!(s:int#int#int).
     abs(drop(integral (:real^1) (\x. lift(norm(phi_sigma s carleson_phi (drop
       x)) pow 2))))
     = (lnorm (:real^1) (&2) (\z. carleson_phi (drop z))) rpow &2`,
  GEN_TAC THEN
  MP_TAC(ISPECL [`(:real^1)`; `&2`;
    `\z:real^1. phi_sigma s carleson_phi (drop z)`]
    LNORM_RPOW) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_L2 THEN
       REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  BETA_TAC THEN REWRITE_TAC[GSYM RPOW_POW] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
  SUBGOAL_THEN `lnorm (:real^1) (&2) (\z. phi_sigma s carleson_phi (drop z)) =
                lnorm (:real^1) (&2) (\z. carleson_phi (drop z))`
   SUBST1_TAC THENL [REWRITE_TAC[PHISIG_CARLESON_L2]; ALL_TAC] THEN
  REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC RPOW_POS_LE THEN
  MATCH_MP_TAC LNORM_POS_LE THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
  REWRITE_TAC[CARLESON_PHI_SCHWARTZ]);;

(* The diagonal self-correlation is a fixed nonnegative constant D.          *)
let PHISIG_DIAG_CONST = prove
 (`?D. &0 <= D /\ !(s:int#int#int).
       norm(integral (:real^1)
         (\z. phi_sigma s carleson_phi (drop z) * cnj(phi_sigma s carleson_phi
           (drop z))))
       = D`,
  EXISTS_TAC `(lnorm (:real^1) (&2) (\z. carleson_phi (drop z))) rpow &2` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC RPOW_POS_LE THEN MATCH_MP_TAC LNORM_POS_LE THEN
    MATCH_MP_TAC SCHWARTZ_L2 THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
    ALL_TAC] THEN
  GEN_TAC THEN
  SUBGOAL_THEN
   `integral (:real^1)
     (\z. phi_sigma s carleson_phi (drop z) * cnj(phi_sigma s carleson_phi
       (drop z))) =
    lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                       (\z. phi_sigma s carleson_phi (drop z))`
   SUBST1_TAC THENL [REWRITE_TAC[lproduct]; ALL_TAC] THEN
  MP_TAC(MATCH_MP (BETA_RULE(ISPECL
    [`(:real^1)`;
      `\z:real^1. phi_sigma s carleson_phi (drop z)`] LPRODUCT_SELF))
    (SPEC `s:int#int#int` PHISIG_CARLESON_NORMSQ_INT)) THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[COMPLEX_NORM_CX; PHISIG_DIAG_INTSQ]);;

(* 286J inner column factor: sum_{t in P, J_t = J_s} |(phi_s | phi_t)| <=    *)
(* C3.                                                                       *)
(* Split the diagonal t = s (value D, PHISIG_DIAG_CONST) from the            *)
(* off-diagonal                                                              *)
(* (bound C, PHISIG_COLSUM_LE); C3 = C + D.                                  *)
let PHISIG_INNER_FACTOR_LE = prove
 (`?C3. &0 <= C3 /\ !(s:int#int#int) (P:(int#int#int)->bool). FINITE P
     ==> sum {t | t IN P /\ tile_J t = tile_J s}
             (\t. norm(integral (:real^1)
                    (\z. phi_sigma s carleson_phi (drop z) *
                         cnj(phi_sigma t carleson_phi (drop z)))))
         <= C3`,
  MP_TAC PHISIG_COLSUM_LE THEN DISCH_THEN(X_CHOOSE_THEN
    `C:real` STRIP_ASSUME_TAC) THEN
  MP_TAC PHISIG_DIAG_CONST THEN DISCH_THEN(X_CHOOSE_THEN
    `D:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C + D:real` THEN CONJ_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `P:(int#int#int)->bool`] THEN
    DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum ({t | t IN P /\ tile_J t = tile_J s /\ ~(t = s)} UNION {s})
                  (\t. norm(integral (:real^1)
                    (\z. phi_sigma s carleson_phi (drop z) *
                         cnj(phi_sigma t carleson_phi (drop z)))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
    ASM_SIMP_TAC[FINITE_UNION; FINITE_RESTRICT; FINITE_SING] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_UNION; IN_SING] THEN MESON_TAC[];
      REWRITE_TAC[IN_UNION; IN_ELIM_THM; IN_DIFF] THEN REPEAT STRIP_TAC THEN
      REWRITE_TAC[NORM_POS_LE]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `sum ({t | t IN P /\ tile_J t = tile_J s /\ ~(t = s)} UNION {s})
        (\t. norm(integral (:real^1)
               (\z. phi_sigma s carleson_phi (drop z) *
                    cnj(phi_sigma t carleson_phi (drop z))))) =
    sum {t | t IN P /\ tile_J t = tile_J s /\ ~(t = s)}
        (\t. norm(integral (:real^1)
               (\z. phi_sigma s carleson_phi (drop z) *
                    cnj(phi_sigma t carleson_phi (drop z))))) +
    sum {s}
        (\t. norm(integral (:real^1)
               (\z. phi_sigma s carleson_phi (drop z) *
                    cnj(phi_sigma t carleson_phi (drop z)))))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC SUM_UNION THEN
    ASM_SIMP_TAC[FINITE_RESTRICT; FINITE_SING] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM; IN_SING;
      NOT_IN_EMPTY] THEN
    MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[SUM_SING] THEN
  MATCH_MP_TAC(REAL_ARITH `a <= C /\ b = D ==> a + b <= C + D`) THEN
  ASM_SIMP_TAC[]);;

(* 286J inner reduction: summing the column bound against any nonnegative    *)
(* weight a_s^2 gives  sum_s a_s^2 (sum_{t:J_t=J_s} |(phi_s|phi_t)|) <=      *)
(* C3 sum_s a_s^2. (Termwise REAL_LE_LMUL by PHISIG_INNER_FACTOR_LE,         *)
(* a_s^2>=0.)                                                                *)
let PHISIG_286J_STEP3 = prove
 (`?C3. &0 <= C3 /\ !(a:(int#int#int)->real) (P:(int#int#int)->bool). FINITE P
     ==> sum P (\s. (a s) pow 2 *
                    sum {t | t IN P /\ tile_J t = tile_J s}
                        (\t. norm(integral (:real^1)
                               (\z. phi_sigma s carleson_phi (drop z) *
                                    cnj(phi_sigma t carleson_phi (drop z))))))
         <= C3 * sum P (\s. (a s) pow 2)`,
  MP_TAC PHISIG_INNER_FACTOR_LE THEN
  DISCH_THEN(X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`a:(int#int#int)->real`; `P:(int#int#int)->bool`] THEN
    DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum P (\s. ((a:(int#int#int)->real) s) pow 2 * C3)` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REWRITE_TAC[REAL_LE_POW_2]; ASM_SIMP_TAC[]];
    REWRITE_TAC[SUM_RMUL] THEN MATCH_MP_TAC REAL_EQ_IMP_LE THEN
      REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* 286J, the first inequality:  the finite double sum over frequency-matched *)
(* tile pairs is controlled by the diagonal l^2 mass.                        *)
(*   sum_{(s,t) in PxP, J_s=J_t} a_s |(phi_s|phi_t)| a_t <= C3 sum_s a_s^2.  *)
(* Fremlin's proof: AM-GM symmetrization + the column bound (286Ge/286Gb).   *)
(* ------------------------------------------------------------------------- *)

(* Weighted AM-GM: u K v <= 1/2 (u^2 K + v^2 K) for K >= 0. (K(u-v)^2 >= 0.) *)
let AMGM_WEIGHTED = prove
 (`!u v K:real. &0 <= K ==> u * K * v <= &1 / &2 * (u pow 2 * K + v pow 2 *
   K)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= K * (u - v) pow 2` MP_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
  MP_TAC(REAL_RING
   `K * (u - v) pow 2 = (u pow 2 * K + v pow 2 * K) - &2 * (u * K * v)`) THEN
  REAL_ARITH_TAC);;

(* Symmetrization swap for the a_t^2-weighted double sum (SUM_SUM_RESTRICT   *)
(* on the symmetric relation J_s = J_t, then the correlation is              *)
(* |.|-symmetric).                                                           *)
let PHISIG_286J_YSWAP = prove
 (`!(a:(int#int#int)->real) (P:(int#int#int)->bool). FINITE P
     ==> sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s}
                       (\t. (a t) pow 2 *
                            norm(integral (:real^1)
                              (\z. phi_sigma s carleson_phi (drop z) *
                                   cnj(phi_sigma t carleson_phi (drop z))))))
       = sum P (\t. (a t) pow 2 *
                    sum {s | s IN P /\ tile_J s = tile_J t}
                        (\s. norm(integral (:real^1)
                               (\z. phi_sigma t carleson_phi (drop z) *
                                    cnj(phi_sigma s carleson_phi (drop
                                      z))))))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
    [`\x y:int#int#int. tile_J y = tile_J x`;
     `\s t:int#int#int. (a t) pow 2 *
        norm(integral (:real^1)
          (\z. phi_sigma s carleson_phi (drop z) *
               cnj(phi_sigma t carleson_phi (drop z))))`;
     `P:(int#int#int)->bool`; `P:(int#int#int)->bool`] SUM_SUM_RESTRICT)) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
  REWRITE_TAC[SUM_LMUL] THEN AP_TERM_TAC THEN
  SUBGOAL_THEN `{x | x IN P /\ tile_J t = tile_J x} =
                {s | s IN P /\ tile_J s = tile_J t}` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  REWRITE_TAC[PHISIG_CORR_SYM]);;

(* The a_s^2-weighted half of the symmetrized double sum (diagonal weight).  *)
let PHISIG_286J_XBOUND = prove
 (`?C3. &0 <= C3 /\ !(a:(int#int#int)->real) (P:(int#int#int)->bool). FINITE P
     ==> sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s}
                       (\t. (a s) pow 2 *
                            norm(integral (:real^1)
                              (\z. phi_sigma s carleson_phi (drop z) *
                                   cnj(phi_sigma t carleson_phi (drop z))))))
         <= C3 * sum P (\s. (a s) pow 2)`,
  MP_TAC PHISIG_286J_STEP3 THEN DISCH_THEN(X_CHOOSE_THEN
    `C3:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`a:(int#int#int)->real`; `P:(int#int#int)->bool`] THEN
    DISCH_TAC THEN
  SUBGOAL_THEN
   `!s:int#int#int. sum {t | t IN P /\ tile_J t = tile_J s}
                       (\t. (a s) pow 2 *
                            norm(integral (:real^1)
                              (\z. phi_sigma s carleson_phi (drop z) *
                                   cnj(phi_sigma t carleson_phi (drop z))))) =
                    (a s) pow 2 * sum {t | t IN P /\ tile_J t = tile_J s}
                       (\t. norm(integral (:real^1)
                              (\z. phi_sigma s carleson_phi (drop z) *
                                   cnj(phi_sigma t carleson_phi (drop z)))))`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN REWRITE_TAC[SUM_LMUL]; ALL_TAC] THEN
  ASM_SIMP_TAC[]);;

(* The a_t^2-weighted half, reduced to the diagonal one via the swap.        *)
let PHISIG_286J_YBOUND = prove
 (`?C3. &0 <= C3 /\ !(a:(int#int#int)->real) (P:(int#int#int)->bool). FINITE P
     ==> sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s}
                       (\t. (a t) pow 2 *
                            norm(integral (:real^1)
                              (\z. phi_sigma s carleson_phi (drop z) *
                                   cnj(phi_sigma t carleson_phi (drop z))))))
         <= C3 * sum P (\s. (a s) pow 2)`,
  MP_TAC PHISIG_286J_STEP3 THEN DISCH_THEN(X_CHOOSE_THEN
    `C3:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`a:(int#int#int)->real`; `P:(int#int#int)->bool`] THEN
    DISCH_TAC THEN
  ASM_SIMP_TAC[PHISIG_286J_YSWAP]);;

(* 286J first inequality (all-real form).                                    *)
let PHISIG_286J_BILINEAR = prove
 (`?C3. &0 <= C3 /\ !(a:(int#int#int)->real) (P:(int#int#int)->bool). FINITE P
     ==> sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s}
                       (\t. a s *
                            norm(integral (:real^1)
                              (\z. phi_sigma s carleson_phi (drop z) *
                                   cnj(phi_sigma t carleson_phi (drop z)))) * a
                                     t))
         <= C3 * sum P (\s. (a s) pow 2)`,
  MP_TAC PHISIG_286J_XBOUND THEN DISCH_THEN(X_CHOOSE_THEN
    `C3:real` STRIP_ASSUME_TAC) THEN
  MP_TAC PHISIG_286J_YBOUND THEN DISCH_THEN(X_CHOOSE_THEN
    `C3':real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `&1 / &2 * (C3 + C3')` THEN CONJ_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`a:(int#int#int)->real`; `P:(int#int#int)->bool`] THEN
    DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s}
       (\t. &1 / &2 * ((a s) pow 2 *
              norm(integral (:real^1)
                (\z. phi_sigma s carleson_phi (drop z) *
                     cnj(phi_sigma t carleson_phi (drop z)))) +
            (a t) pow 2 *
              norm(integral (:real^1)
                (\z. phi_sigma s carleson_phi (drop z) *
                     cnj(phi_sigma t carleson_phi (drop z)))))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC SUM_LE THEN ASM_SIMP_TAC[FINITE_RESTRICT] THEN
    X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC AMGM_WEIGHTED THEN REWRITE_TAC[NORM_POS_LE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s}
       (\t. &1 / &2 * ((a s) pow 2 *
              norm(integral (:real^1)
                (\z. phi_sigma s carleson_phi (drop z) *
                     cnj(phi_sigma t carleson_phi (drop z)))) +
            (a t) pow 2 *
              norm(integral (:real^1)
                (\z. phi_sigma s carleson_phi (drop z) *
                     cnj(phi_sigma t carleson_phi (drop z)))))))
    = &1 / &2 * (sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s}
                       (\t. (a s) pow 2 *
                            norm(integral (:real^1)
                              (\z. phi_sigma s carleson_phi (drop z) *
                                   cnj(phi_sigma t carleson_phi (drop z)))))) +
                 sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s}
                       (\t. (a t) pow 2 *
                            norm(integral (:real^1)
                              (\z. phi_sigma s carleson_phi (drop z) *
                                   cnj(phi_sigma t carleson_phi (drop z)))))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ADD_LDISTRIB] THEN
    ASM_SIMP_TAC[SUM_ADD; FINITE_RESTRICT] THEN REWRITE_TAC[SUM_LMUL] THEN
    ASM_SIMP_TAC[GSYM SUM_ADD; FINITE_RESTRICT] THEN
      REWRITE_TAC[REAL_ADD_LDISTRIB];
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH
   `X <= C3 * S /\ Y <= C3' * S
    ==> &1 / &2 * (X + Y) <= (&1 / &2 * (C3 + C3')) * S`) THEN
  ASM_SIMP_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286J, the Bessel identity for the second inequality:                      *)
(*   (f | sum_s (f|phi_s) phi_s) = sum_s |(f|phi_s)|^2.                      *)
(* Combined with Cauchy-Schwarz this gives sum_s |(f|phi_s)|^2 <=            *)
(* ||sum_s (f|phi_s) phi_s||_2 ||f||_2.                                      *)
(* ------------------------------------------------------------------------- *)

(* Per-term:  (f | (f|phi_s) phi_s) = |(f|phi_s)|^2.                         *)
let CARLESON_IP_SELFTERM = prove
 (`!(f:real->complex) (s:int#int#int).
     (\z:real^1. f(drop z) * cnj(phi_sigma s carleson_phi (drop z)))
       integrable_on (:real^1)
     ==> lproduct (:real^1) (\z. f(drop z))
                  (\z. carleson_ip f s * phi_sigma s carleson_phi (drop z)) =
         Cx(norm(carleson_ip f s) pow 2)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[LPRODUCT_RMUL] THEN
  REWRITE_TAC[carleson_ip; CX_POW; COMPLEX_MUL_CNJ]);;

(* The Bessel identity itself (finite tile set P).                           *)
let CARLESON_BESSEL_IP = prove
 (`!(f:real->complex) (P:(int#int#int)->bool).
     FINITE P /\
     (!s. s IN P ==> (\z:real^1. f(drop z) * cnj(phi_sigma s carleson_phi (drop
       z)))
                     integrable_on (:real^1))
     ==> lproduct (:real^1) (\z. f(drop z))
           (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop
             z))) =
         Cx(sum P (\s. norm(carleson_ip f s) pow 2))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
    [`(:real^1)`; `\z:real^1. (f:real->complex)(drop z)`;
     `\(s:int#int#int) (z:real^1). carleson_ip f s * phi_sigma s carleson_phi
       (drop z)`;
     `P:(int#int#int)->bool`] LPRODUCT_RSUM) THEN
  BETA_TAC THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(\x. (f:real->complex)(drop x) * cnj(carleson_ip f s * phi_sigma s
       carleson_phi (drop x))) =
      (\x. cnj(carleson_ip f s) * (f(drop x) * cnj(phi_sigma s carleson_phi
        (drop x))))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; CNJ_MUL] THEN
       CONV_TAC COMPLEX_RING; ALL_TAC] THEN
    MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `!s:int#int#int. s IN P ==>
      lproduct (:real^1) (\z. f(drop z))
        (\z. carleson_ip f s * phi_sigma s carleson_phi (drop z)) =
      Cx(norm(carleson_ip f s) pow 2)`
   (fun th -> ASM_SIMP_TAC[th; VSUM_CX]) THEN
  X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  MATCH_MP_TAC CARLESON_IP_SELFTERM THEN ASM_SIMP_TAC[]);;

(* The reconstruction sum sum_s (f|phi_s) phi_s lies in L^2 (finite sum of   *)
(* complex-scalar multiples of the Schwartz phi_s).                          *)
let CARLESON_RECON_L2 = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop z)))
         IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC LSPACE_VSUM THEN
  ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
  X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN
  MATCH_MP_TAC SCHWARTZ_L2 THEN
    REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]);;

(* 286J, the second inequality:  sum_s |(f|phi_s)|^2 <=                      *)
(* ||f||_2 ||sum_s (f|phi_s) phi_s||_2. (Bessel identity + Cauchy-Schwarz,   *)
(* using that the diagonal l^2 mass is real and nonnegative.)                *)
let CARLESON_286J_SECOND = prove
 (`!(f:real->complex) (P:(int#int#int)->bool).
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ FINITE P
     ==> sum P (\s. norm(carleson_ip f s) pow 2)
         <= lnorm (:real^1) (&2) (\z. f(drop z)) *
            lnorm (:real^1) (&2)
              (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop
                z)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!s:int#int#int. (\z:real^1. f(drop z) * cnj(phi_sigma s carleson_phi (drop
     z)))
                    integrable_on (:real^1)`
   ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
    REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `sum P (\s. norm(carleson_ip f s) pow 2) =
    norm(lproduct (:real^1) (\z. f(drop z))
          (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop
            z))))`
   SUBST1_TAC THENL
   [ASM_SIMP_TAC[CARLESON_BESSEL_IP; COMPLEX_NORM_CX] THEN
    CONV_TAC SYM_CONV THEN REWRITE_TAC[REAL_ABS_REFL] THEN
    MATCH_MP_TAC SUM_POS_LE THEN REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
  MATCH_MP_TAC LPRODUCT_CAUCHY_SCHWARZ THEN
  ASM_SIMP_TAC[CARLESON_RECON_L2] THEN
  MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
  ASM_SIMP_TAC[CARLESON_RECON_L2]);;

(* ------------------------------------------------------------------------- *)
(* Toward 286K(b): expanding the L^2 pairing of the reconstruction sum       *)
(* g = sum_s (f|phi_s) phi_s against itself.  The OUTER expansion peels the  *)
(* first argument's sum (LPRODUCT_LSUM + LPRODUCT_LMUL).                     *)
(* ------------------------------------------------------------------------- *)

(* Integrability of phi_s cnj(g) and (c_s phi_s) cnj(g) (both L^2 factors).  *)
let CARLESON_PHISIG_RECON_INT = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (s:int#int#int).
     FINITE P /\ (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> (\z:real^1. phi_sigma s carleson_phi (drop z) *
                     cnj(vsum P (\t. carleson_ip f t * phi_sigma t carleson_phi
                       (drop z))))
         integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_L2 THEN
     REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC CARLESON_RECON_L2 THEN
      ASM_REWRITE_TAC[]]);;

let CARLESON_SCALPHISIG_RECON_INT = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (s:int#int#int).
     FINITE P /\ (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> (\z:real^1. (carleson_ip f s * phi_sigma s carleson_phi (drop z)) *
                     cnj(vsum P (\t. carleson_ip f t * phi_sigma t carleson_phi
                       (drop z))))
         integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
    REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC CARLESON_RECON_L2 THEN
      ASM_REWRITE_TAC[]]);;

(* (g | g) = sum_s (f|phi_s) (phi_s | g),  g = sum_s (f|phi_s) phi_s.        *)
let CARLESON_NORMSQ_OUTER = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P /\ (\z. f(drop z)) IN
   lspace (:real^1) (&2)
     ==> lproduct (:real^1)
           (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop
             z)))
           (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop
             z))) =
         vsum P (\s. carleson_ip f s *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
             (\z. vsum P (\t. carleson_ip f t * phi_sigma t carleson_phi (drop
               z))))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
    [`(:real^1)`;
     `\(s:int#int#int) (z:real^1). carleson_ip f s * phi_sigma s carleson_phi
       (drop z)`;
     `\z:real^1. vsum P (\t. carleson_ip f t * phi_sigma t carleson_phi (drop
       z))`;
     `P:(int#int#int)->bool`] LPRODUCT_LSUM)) THEN
  ASM_SIMP_TAC[CARLESON_SCALPHISIG_RECON_INT] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  MATCH_MP_TAC LPRODUCT_LMUL THEN ASM_SIMP_TAC[CARLESON_PHISIG_RECON_INT]);;

(* Integrability of phi_s cnj((f|phi_t) phi_t), both L^2.                    *)
let CARLESON_PHISIG_SCALPHISIG_INT = prove
 (`!(f:real->complex) (s:int#int#int) (t:int#int#int).
     (\z:real^1. phi_sigma s carleson_phi (drop z) *
                 cnj(carleson_ip f t * phi_sigma t carleson_phi (drop z)))
     integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_L2 THEN
     REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
    REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]]);;

(* INNER expansion:  (phi_s | g) = sum_t cnj(f|phi_t) (phi_s | phi_t).       *)
let CARLESON_NORMSQ_INNER = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (s:int#int#int). FINITE P
     ==> lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
           (\z. vsum P (\t. carleson_ip f t * phi_sigma t carleson_phi (drop
             z))) =
         vsum P (\t. cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
    [`(:real^1)`;
     `\z:real^1. phi_sigma s carleson_phi (drop z)`;
     `\(t:int#int#int) (z:real^1). carleson_ip f t * phi_sigma t carleson_phi
       (drop z)`;
     `P:(int#int#int)->bool`] LPRODUCT_RSUM)) THEN
  ASM_SIMP_TAC[CARLESON_PHISIG_SCALPHISIG_INT] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  MATCH_MP_TAC LPRODUCT_RMUL THEN BETA_TAC THEN
  MATCH_MP_TAC SCHWARTZ_CNJ_PRODUCT_INTEGRABLE THEN
  REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]);;

(* 286K(b) expansion: ||g||_2^2 pairing = sum_s sum_t (f|phi_s) cnj(f|phi_t) *)
(* (phi_s | phi_t). (Fremlin: alpha^2 = sum_{s,t}                            *)
(* (f|phi_s)(phi_s|phi_t)(phi_t|f).)                                         *)
let CARLESON_NORMSQ_DOUBLE = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P /\ (\z. f(drop z)) IN
   lspace (:real^1) (&2)
     ==> lproduct (:real^1)
           (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop
             z)))
           (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop
             z))) =
         vsum P (\s. vsum P (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_NORMSQ_OUTER] THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  ASM_SIMP_TAC[CARLESON_NORMSQ_INNER] THEN
  ASM_SIMP_TAC[GSYM VSUM_COMPLEX_LMUL] THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
  CONV_TAC COMPLEX_RING);;

(* ------------------------------------------------------------------------- *)
(* 286K(b), the diagonal (J_s = J_t) block bound.  Taking norms termwise     *)
(* (triangle) and applying 286J (PHISIG_286J_BILINEAR) bounds the frequency- *)
(* matched block by C3 sum_s |(f|phi_s)|^2 -- Fremlin's "first term <= C3    *)
(* alpha".                                                                   *)
(* ------------------------------------------------------------------------- *)

(* Termwise triangle bound reducing the complex block to the all-real 286J   *)
(* sum.                                                                      *)
let CARLESON_DIAGBLOCK_TRIANGLE = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> norm(vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
                carleson_ip f s * cnj(carleson_ip f t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))
         <= sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s} (\t.
                norm(carleson_ip f s) *
                norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop z)
                  *
                                             cnj(phi_sigma t carleson_phi (drop
                                               z)))) *
                norm(carleson_ip f t)))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum P (\s. norm(vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
                carleson_ip f s * cnj(carleson_ip f t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))`
                                     THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC VSUM_NORM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[REAL_LE_REFL];
    MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC VSUM_NORM_LE THEN ASM_SIMP_TAC[FINITE_RESTRICT] THEN
    X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CNJ; lproduct] THEN
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN REWRITE_TAC[REAL_MUL_AC]]);;

(* The block bound proper:  ||diagonal block|| <= C3 sum_s |(f|phi_s)|^2.    *)
let CARLESON_DIAGBLOCK_LE = prove
 (`?C3. &0 <= C3 /\ !(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> norm(vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
                carleson_ip f s * cnj(carleson_ip f t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))
         <= C3 * sum P (\s. norm(carleson_ip f s) pow 2)`,
  MP_TAC PHISIG_286J_BILINEAR THEN
  DISCH_THEN(X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`f:real->complex`; `P:(int#int#int)->bool`] THEN
    DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s} (\t.
                norm(carleson_ip f s) *
                norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop z)
                  *
                                             cnj(phi_sigma t carleson_phi (drop
                                               z)))) *
                norm(carleson_ip f t)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CARLESON_DIAGBLOCK_TRIANGLE THEN ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(MP_TAC o SPECL [`\s:int#int#int. norm(carleson_ip f s)`;
                                  `P:(int#int#int)->bool`]) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286L (off-diagonal): the block over frequency-DISTINCT tile pairs (J_t /= *)
(* J_s) -- the complement of the 286J diagonal.  Its norm reduces (termwise  *)
(* triangle, exactly as CARLESON_DIAGBLOCK_TRIANGLE) to the real double sum  *)
(*   sum_s sum_{t: J_t/=J_s} |(f|phi_s)| |<phi_s,phi_t>| |(f|phi_t)|,        *)
(* which the 286G(e) cross-correlation decay + the maximal-cover Schur       *)
(* argument                                                                  *)
(* then bound.  This is the entry point of the W0..W3 estimate.              *)
let CARLESON_OFFBLOCK_TRIANGLE = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> norm(vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
                carleson_ip f s * cnj(carleson_ip f t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))
         <= sum P (\s. sum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
                norm(carleson_ip f s) *
                norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop z)
                  *
                                             cnj(phi_sigma t carleson_phi (drop
                                               z)))) *
                norm(carleson_ip f t)))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum P (\s. norm(vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
                carleson_ip f s * cnj(carleson_ip f t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))`
                                     THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC VSUM_NORM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[REAL_LE_REFL];
    MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC VSUM_NORM_LE THEN ASM_SIMP_TAC[FINITE_RESTRICT] THEN
    X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CNJ; lproduct] THEN
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN REWRITE_TAC[REAL_MUL_AC]]);;

(* Substituting the scale-order-free correlation bound                       *)
(* (PHISIG_CROSS_CORR_SYM)                                                   *)
(* into the off-diagonal real sum replaces the abstract |<phi_s,phi_t>| by   *)
(* the                                                                       *)
(* explicit weight kernel inv(2^{k_s/2}) inv(2^{k_t/2}) (w_s(x_t)+w_t(x_s)). *)
(* The off-diagonal sum is now PURELY GEOMETRIC. Termwise: multiply the      *)
(* per-pair                                                                  *)
(* correlation bound by the nonnegative coefficients |(f|phi_s)|,            *)
(* |(f|phi_t)|                                                               *)
(* (normalise both sides to (|a_s| |a_t|) * factor via REAL_MUL_AC, then     *)
(* REAL_LE_                                                                  *)
(* LMUL on the nonneg |a_s||a_t|), summed by SUM_LE twice + SUM_LMUL.        *)
let CARLESON_BLOCK_SPLIT = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> vsum P (\s. vsum P (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))) =
         vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))) +
         vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `vsum P (\s:int#int#int. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
           carleson_ip (f:real->complex) s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))) +
    vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))) =
    vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))) +
                vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))))`
   SUBST1_TAC THENL
   [ASM_SIMP_TAC[VSUM_ADD]; ALL_TAC] THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`;
    `\t:int#int#int. tile_J t = tile_J s`;
     `\t. carleson_ip (f:real->complex) s * cnj(carleson_ip f t) *
          lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                             (\z. phi_sigma t carleson_phi (drop z))`;
     `\t. carleson_ip (f:real->complex) s * cnj(carleson_ip f t) *
          lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                             (\z. phi_sigma t carleson_phi (drop z))`]
                               VSUM_CASES) THEN
  ASM_REWRITE_TAC[COND_ID] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[]);;

(* Assembly (valid for ANY finite P): the Gram double-sum norm is <= C3*mass *)
(* +                                                                         *)
(* norm(off-diagonal block). norm-triangle on CARLESON_BLOCK_SPLIT +         *)
(* DIAGBLOCK_LE.                                                             *)
(* This is a TRUE reduction, but it does NOT by itself finish 286K: the      *)
(* off-diagonal                                                              *)
(* norm is only controllable on stopping-time TREES (see                     *)
(* CARLESON_BLOCK_SPLIT note),                                               *)
(* where the ENERGY bound replaces a (false, for general P) global C7*mass   *)
(* bound.                                                                    *)
(* Kept as a reusable identity; the actual 286K/286L endgame runs on         *)
(* ENERGY_DECOMP                                                             *)
(* trees + the single-tree energy x mass factorization (286L), not on this   *)
(* line.                                                                     *)
let CARLESON_NORMSQ_DOUBLE_LE = prove
 (`?C3. &0 <= C3 /\ !(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> norm(vsum P (\s. vsum P (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))))
         <= C3 * sum P (\s. norm(carleson_ip f s) pow 2) +
            norm(vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
              carleson_ip f s * cnj(carleson_ip f t) *
              lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                 (\z. phi_sigma t carleson_phi (drop z)))))`,
  MP_TAC CARLESON_DIAGBLOCK_LE THEN
  DISCH_THEN(X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`f:real->complex`; `P:(int#int#int)->bool`] THEN
    DISCH_TAC THEN
  ASM_SIMP_TAC[CARLESON_BLOCK_SPLIT] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `norm(vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
              carleson_ip (f:real->complex) s * cnj(carleson_ip f t) *
              lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                 (\z. phi_sigma t carleson_phi (drop z))))) +
              norm(vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
              carleson_ip f s * cnj(carleson_ip f t) *
              lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                 (\z. phi_sigma t carleson_phi (drop z)))))`
                                   THEN
  CONJ_TAC THENL
   [REWRITE_TAC[NORM_TRIANGLE];
    MATCH_MP_TAC REAL_LE_ADD2 THEN ASM_SIMP_TAC[REAL_LE_REFL]]);;

(* ------------------------------------------------------------------------- *)
(* 286L(g): the alpha3 ENERGY / L^2 input.  For a TREE (all tiles <=_r tau), *)
(* the reconstruction g~ = sum ip_s phi_s has ||g~||_2^2 <= C3 gamma^2       *)
(* 2^{-k_tau}.  The off-diagonal-J block of ||g~||_2^2 VANISHES on the tree  *)
(* (286Fc: different-scale tree tiles are orthogonal, PHISIG_TREE_ORTHO), so *)
(* only the diagonal-J block survives (<= C3 sum|ip|^2,                      *)
(* CARLESON_DIAGBLOCK_LE),                                                   *)
(* and sum_{tree}|ip|^2 <= gamma^2 2^{-k_tau} (FTILDE_ENERGY_SUM).           *)
(* ------------------------------------------------------------------------- *)
let CARLESON_DIAGBLOCK_TRIANGLE_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool). FINITE P
     ==> norm(vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
                c s * cnj(c t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))
         <= sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s} (\t.
                norm(c s) *
                norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop z)
                  *
                                             cnj(phi_sigma t carleson_phi (drop
                                               z)))) *
                norm(c t)))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum P (\s. norm(vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
                (c:(int#int#int)->complex) s * cnj(c t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))`
                                     THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC VSUM_NORM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[REAL_LE_REFL];
    MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC VSUM_NORM_LE THEN ASM_SIMP_TAC[FINITE_RESTRICT] THEN
    X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CNJ; lproduct] THEN
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN REWRITE_TAC[REAL_MUL_AC]]);;

let CARLESON_DIAGBLOCK_LE_C = prove
 (`?C3. &0 <= C3 /\ !(c:(int#int#int)->complex) (P:(int#int#int)->bool). FINITE
   P
     ==> norm(vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
                c s * cnj(c t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))
         <= C3 * sum P (\s. norm(c s) pow 2)`,
  MP_TAC PHISIG_286J_BILINEAR THEN
  DISCH_THEN(X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`c:(int#int#int)->complex`;
    `P:(int#int#int)->bool`] THEN DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum P (\s. sum {t | t IN P /\ tile_J t = tile_J s} (\t.
                norm((c:(int#int#int)->complex) s) *
                norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop z)
                  *
                                             cnj(phi_sigma t carleson_phi (drop
                                               z)))) *
                norm(c t)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CARLESON_DIAGBLOCK_TRIANGLE_C THEN ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(MP_TAC o SPECL [`\s:int#int#int.
      norm((c:(int#int#int)->complex) s)`;
                                  `P:(int#int#int)->bool`]) THEN
    ASM_REWRITE_TAC[]]);;

let CARLESON_BLOCK_SPLIT_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool). FINITE P
     ==> vsum P (\s. vsum P (\t.
           c s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))) =
         vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
           c s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))) +
         vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
           c s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `vsum P (\s:int#int#int. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
           (c:(int#int#int)->complex) s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))) +
    vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
           c s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))) =
    vsum P (\s. vsum {t | t IN P /\ tile_J t = tile_J s} (\t.
           c s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))) +
                vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
           c s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))))`
   SUBST1_TAC THENL
   [ASM_SIMP_TAC[VSUM_ADD]; ALL_TAC] THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`;
    `\t:int#int#int. tile_J t = tile_J s`;
     `\t. (c:(int#int#int)->complex) s * cnj(c t) *
          lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                             (\z. phi_sigma t carleson_phi (drop z))`;
     `\t. (c:(int#int#int)->complex) s * cnj(c t) *
          lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                             (\z. phi_sigma t carleson_phi (drop z))`]
                               VSUM_CASES) THEN
  ASM_REWRITE_TAC[COND_ID] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[]);;

let FTILDE_OFFBLOCK_ZERO_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau.
     FINITE P /\ (!s. s IN P ==> tile_ler s tau)
     ==> vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)}
                         (\t. c s * cnj(c t) *
                              lproduct (:real^1) (\z. phi_sigma s carleson_phi
                                (drop z))
                                                 (\z. phi_sigma t carleson_phi
                                                   (drop z)))) = vec 0`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC VSUM_EQ_0 THEN
  X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC VSUM_EQ_0 THEN X_GEN_TAC `t:int#int#int` THEN
  REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
  SUBGOAL_THEN `lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)) =
                                     Cx(&0)`
    (fun th -> REWRITE_TAC[th; COMPLEX_MUL_RZERO; COMPLEX_VEC_0]) THEN
  REWRITE_TAC[lproduct] THEN MATCH_MP_TAC PHISIG_TREE_ORTHO THEN
  EXISTS_TAC `tau:int#int#int` THEN ASM_SIMP_TAC[] THEN
  DISCH_TAC THEN UNDISCH_TAC `~(tile_J t = tile_J s)` THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC TILE_TREE_SAMESCALE_J THEN EXISTS_TAC `tau:int#int#int` THEN
  ASM_SIMP_TAC[TILE_LER_IMP_LE]);;

let FTILDE_DOUBLE_LE_C = prove
 (`?C3. &0 <= C3 /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau.
      FINITE P /\ (!s. s IN P ==> tile_ler s tau)
      ==> norm(vsum P (\s. vsum P (\t.
            c s * cnj(c t) *
            lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                               (\z. phi_sigma t carleson_phi (drop z)))))
          <= C3 * sum P (\s. norm(c s) pow 2)`,
  X_CHOOSE_THEN
    `C3:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "DB"))
    CARLESON_DIAGBLOCK_LE_C THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`c:(int#int#int)->complex`;
    `P:(int#int#int)->bool`] CARLESON_BLOCK_SPLIT_C) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`;
    `tau:int#int#int`] FTILDE_OFFBLOCK_ZERO_C) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VECTOR_ADD_RID] THEN USE_THEN "DB" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]);;

let CARLESON_NORMSQ_REAL = prove
 (`!(f:real->complex) (P:(int#int#int)->bool).
     FINITE P /\ (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> Cx(drop(integral (:real^1)
            (\z. lift(norm(vsum P (\s. carleson_ip f s * phi_sigma s
              carleson_phi (drop z))) pow 2)))) =
         vsum P (\s. vsum P (\t. carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC EQ_TRANS THEN
  EXISTS_TAC
   `lproduct (:real^1)
      (\z. vsum P (\s. carleson_ip (f:real->complex) s * phi_sigma s
        carleson_phi (drop z)))
      (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop z)))`
        THEN
  CONJ_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC LPRODUCT_SELF THEN
    MP_TAC(ISPECL [`f:real->complex`;
      `P:(int#int#int)->bool`] CARLESON_RECON_L2) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[lspace; IN_ELIM_THM; RPOW_POW] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC CARLESON_NORMSQ_DOUBLE THEN ASM_REWRITE_TAC[]]);;

(* 286L(g), integral form: ||g~||_2^2 = INT_R |g~|^2 <= C3 gamma^2           *)
(* 2^{-k_tau}                                                                *)
(* for the tree g~ = sum_{s <=_r tau} ip_s phi_s. The integral (nonneg real) *)
(* equals                                                                    *)
(* Re/norm of the double sum (CARLESON_NORMSQ_REAL), which FTILDE_L2 bounds. *)
(* This is the ||g~||_2^2 bound used by the alpha3 Cauchy-Schwarz step.       *)
let SCHWARTZ_ZERO = prove
 (`schwartz (\x:real. Cx(&0))`,
  REWRITE_TAC[schwartz] THEN EXISTS_TAC `\n:num x:real. Cx(&0)` THEN
  REWRITE_TAC[FUN_EQ_THM] THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[GSYM COMPLEX_VEC_0; HAS_VECTOR_DERIVATIVE_CONST];
    REPEAT GEN_TAC THEN EXISTS_TAC `&0` THEN
    REWRITE_TAC[COMPLEX_NORM_0; REAL_MUL_RZERO; REAL_LE_REFL]]);;

let SCHWARTZ_VSUM = prove
 (`!(g:A->real->complex) s. FINITE s /\ (!a. a IN s ==> schwartz(g a))
     ==> schwartz(\x. vsum s (\a. g a x))`,
  GEN_TAC THEN REWRITE_TAC[IMP_CONJ] THEN
    MATCH_MP_TAC FINITE_INDUCT_STRONG THEN
  REWRITE_TAC[VSUM_CLAUSES; ETA_AX; FORALL_IN_INSERT] THEN CONJ_TAC THENL
   [DISCH_THEN(K ALL_TAC) THEN REWRITE_TAC[COMPLEX_VEC_0; SCHWARTZ_ZERO];
    MAP_EVERY X_GEN_TAC [`e:A`; `s:A->bool`] THEN
    REPEAT STRIP_TAC THEN ASM_SIMP_TAC[VSUM_CLAUSES] THEN
    MATCH_MP_TAC SCHWARTZ_ADD THEN ASM_SIMP_TAC[ETA_AX]]);;

let QUADRATIC_NONNEG_DISC = prove
 (`!A B C. &0 <= A /\ &0 <= C /\ (!y. &0 <= A * y pow 2 + &2 * B * y + C)
     ==> B pow 2 <= A * C`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `A = &0` THENL
   [SUBGOAL_THEN `B = &0` ASSUME_TAC THENL
     [MATCH_MP_TAC(REAL_ARITH `~(&0 < abs B) ==> B = &0`) THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `--(C + &1) / (&2 * B):real`) THEN
      ASM_REWRITE_TAC[REAL_MUL_LZERO; REAL_ADD_LID] THEN
      ASM_SIMP_TAC[REAL_FIELD `&0 < abs B ==> &2 * B * --(C + &1) / (&2 * B) +
        C = --(&1)`] THEN
      REAL_ARITH_TAC;
      ASM_REWRITE_TAC[REAL_MUL_LZERO] THEN
      REWRITE_TAC[REAL_ARITH `&0 pow 2 = &0`; REAL_LE_REFL]];
    SUBGOAL_THEN `&0 < A` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `--B / A:real`) THEN
    ASM_SIMP_TAC[REAL_FIELD
     `&0 < A ==> A * (--B / A) pow 2 + &2 * B * --B / A + C = C - B pow 2 / A`]
       THEN
    DISCH_TAC THEN SUBGOAL_THEN `B pow 2 / A <= C` MP_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN REWRITE_TAC[REAL_MUL_SYM]]);;

(* int_A (v - t)^2 as a quadratic in t.                                      *)
let INTEGRAL_SHIFT_SQ_EXPAND = prove
 (`!(v:real->real) A t.
     real_measurable A /\ v real_integrable_on A /\ (\x. v x pow 2)
       real_integrable_on A
     ==> real_integral A (\x. (v x - t) pow 2) =
         real_integral A (\x. v x pow 2) - &2 * t * real_integral A v +
         t pow 2 * real_measure A`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x. ((v:real->real) x - t) pow 2) =
    (\x. (v x pow 2 + (-- &2 * t) * v x) + t pow 2 * &1)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x. (v:real->real) x pow 2 + (-- &2 * t) * v x) real_integrable_on A`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_ADD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(\x. t pow 2 * &1) real_integrable_on A` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
    ASM_SIMP_TAC[CONST_INTEGRABLE_MEASURABLE]; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_INTEGRAL_ADD; REAL_INTEGRABLE_LMUL; REAL_INTEGRAL_LMUL;
               CONST_INTEGRABLE_MEASURABLE] THEN
  REAL_ARITH_TAC);;

(* (v - t)^2 is integrable on A.                                             *)
let INTEGRABLE_SHIFT_SQ = prove
 (`!(v:real->real) A t.
     real_measurable A /\ v real_integrable_on A /\ (\x. v x pow 2)
       real_integrable_on A
     ==> (\x. (v x - t) pow 2) real_integrable_on A`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x. ((v:real->real) x - t) pow 2) =
    (\x. (v x pow 2 + (-- &2 * t) * v x) + t pow 2 * &1)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRABLE_ADD THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_ADD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
    ASM_SIMP_TAC[CONST_INTEGRABLE_MEASURABLE]]);;

let REAL_INTEGRAL_CS_MEASURE = prove
 (`!(v:real->real) A.
     real_measurable A /\ v real_integrable_on A /\
     (\x. v x pow 2) real_integrable_on A /\ (!x. &0 <= v x)
     ==> real_integral A v <=
         sqrt(real_measure A) * sqrt(real_integral A (\x. v x pow 2))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= real_measure A` ASSUME_TAC THENL
   [ASM_SIMP_TAC[REAL_MEASURE_POS_LE]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 <= real_integral A (\x. (v:real->real) x pow 2)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[] THEN
    REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= real_integral A (v:real->real)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral A (v:real->real) pow 2 <=
    real_measure A * real_integral A (\x. v x pow 2)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL
      [`real_measure A`; `--(real_integral A (v:real->real))`;
       `real_integral A (\x. (v:real->real) x pow 2)`] QUADRATIC_NONNEG_DISC)
         THEN
    ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
     [X_GEN_TAC `t:real` THEN
      SUBGOAL_THEN
       `real_measure A * t pow 2 + &2 * (--(real_integral A (v:real->real))) *
         t +
        real_integral A (\x. v x pow 2) =
        real_integral A (\x. (v x - t) pow 2)`
       SUBST1_TAC THENL
       [ASM_SIMP_TAC[INTEGRAL_SHIFT_SQ_EXPAND] THEN
         REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC REAL_INTEGRAL_POS THEN
      ASM_SIMP_TAC[INTEGRABLE_SHIFT_SQ] THEN
      REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_LE_POW_2];
      REWRITE_TAC[REAL_POW_NEG; ARITH] THEN DISCH_TAC THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sqrt(real_integral A (v:real->real) pow 2)` THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[POW_2_SQRT; REAL_LE_REFL]; ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM SQRT_MUL] THEN MATCH_MP_TAC SQRT_MONO_LE THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The coefficient-general NORMSQ + maximal-function chain, culminating in   *)
(* the                                                                       *)
(* zeta-ready FTILDE_MAX_L2_NORM_C. For gt = sum_{tree} c_s phi_s (any       *)
(* complex                                                                   *)
(* c), the H-L maximal function gt-star satisfies ||gt-star||_2 <= sqrt(8    *)
(* C3)                                                                       *)
(* sqrt(sum|c_s|^2). Instantiating c_s = zeta_s (f|phi_s) with |zeta_s|=1    *)
(* gives                                                                     *)
(* sum|c_s|^2 = sum|(f|phi_s)|^2, so the bound is the same as the no-phase   *)
(* case;                                                                     *)
(* this is the version alpha3 (i)/(h) actually consume (Fremlin's gt carries *)
(* the                                                                       *)
(* unimodular phases zeta_s). Every lemma below is a verbatim c-for-(f|phi)  *)
(* copy                                                                      *)
(* of its no-phase counterpart (the chain is coefficient-opaque).            *)
(* ------------------------------------------------------------------------- *)

let CARLESON_RECON_L2_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool). FINITE P
     ==> (\z. vsum P (\s. c s * phi_sigma s carleson_phi (drop z)))
         IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC LSPACE_VSUM THEN
  ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
  X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN
  MATCH_MP_TAC SCHWARTZ_L2 THEN
    REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]);;

let CARLESON_PHISIG_RECON_INT_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) (s:int#int#int). FINITE
   P
     ==> (\z:real^1. phi_sigma s carleson_phi (drop z) *
                     cnj(vsum P (\t. c t * phi_sigma t carleson_phi (drop z))))
         integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_L2 THEN
     REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC CARLESON_RECON_L2_C THEN
      ASM_REWRITE_TAC[]]);;

let CARLESON_SCALPHISIG_RECON_INT_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) (s:int#int#int). FINITE
   P
     ==> (\z:real^1. (c s * phi_sigma s carleson_phi (drop z)) *
                     cnj(vsum P (\t. c t * phi_sigma t carleson_phi (drop z))))
         integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
    REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC CARLESON_RECON_L2_C THEN
      ASM_REWRITE_TAC[]]);;

let CARLESON_PHISIG_SCALPHISIG_INT_C = prove
 (`!(c:(int#int#int)->complex) (s:int#int#int) (t:int#int#int).
     (\z:real^1. phi_sigma s carleson_phi (drop z) *
                 cnj(c t * phi_sigma t carleson_phi (drop z)))
     integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_L2 THEN
     REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
    REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]]);;

let CARLESON_NORMSQ_OUTER_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool). FINITE P
     ==> lproduct (:real^1)
           (\z. vsum P (\s. c s * phi_sigma s carleson_phi (drop z)))
           (\z. vsum P (\s. c s * phi_sigma s carleson_phi (drop z))) =
         vsum P (\s. c s *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
             (\z. vsum P (\t. c t * phi_sigma t carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
    [`(:real^1)`;
     `\(s:int#int#int) (z:real^1). (c:(int#int#int)->complex) s * phi_sigma s
       carleson_phi (drop z)`;
     `\z:real^1. vsum P (\t. (c:(int#int#int)->complex) t * phi_sigma t
       carleson_phi (drop z))`;
     `P:(int#int#int)->bool`] LPRODUCT_LSUM)) THEN
  ASM_SIMP_TAC[CARLESON_SCALPHISIG_RECON_INT_C] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  MATCH_MP_TAC LPRODUCT_LMUL THEN ASM_SIMP_TAC[CARLESON_PHISIG_RECON_INT_C]);;

let CARLESON_NORMSQ_INNER_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) (s:int#int#int). FINITE
   P
     ==> lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
           (\z. vsum P (\t. c t * phi_sigma t carleson_phi (drop z))) =
         vsum P (\t. cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
    [`(:real^1)`;
     `\z:real^1. phi_sigma s carleson_phi (drop z)`;
     `\(t:int#int#int) (z:real^1). (c:(int#int#int)->complex) t * phi_sigma t
       carleson_phi (drop z)`;
     `P:(int#int#int)->bool`] LPRODUCT_RSUM)) THEN
  ASM_SIMP_TAC[CARLESON_PHISIG_SCALPHISIG_INT_C] THEN DISCH_THEN
    SUBST1_TAC THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  MATCH_MP_TAC LPRODUCT_RMUL THEN BETA_TAC THEN
  MATCH_MP_TAC SCHWARTZ_CNJ_PRODUCT_INTEGRABLE THEN
  REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]);;

let CARLESON_NORMSQ_DOUBLE_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool). FINITE P
     ==> lproduct (:real^1)
           (\z. vsum P (\s. c s * phi_sigma s carleson_phi (drop z)))
           (\z. vsum P (\s. c s * phi_sigma s carleson_phi (drop z))) =
         vsum P (\s. vsum P (\t.
           c s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_NORMSQ_OUTER_C] THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  ASM_SIMP_TAC[CARLESON_NORMSQ_INNER_C] THEN
  ASM_SIMP_TAC[GSYM VSUM_COMPLEX_LMUL] THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
  CONV_TAC COMPLEX_RING);;

let CARLESON_NORMSQ_REAL_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool). FINITE P
     ==> Cx(drop(integral (:real^1)
            (\z. lift(norm(vsum P (\s. c s * phi_sigma s carleson_phi (drop
              z))) pow 2)))) =
         vsum P (\s. vsum P (\t. c s * cnj(c t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC EQ_TRANS THEN
  EXISTS_TAC
   `lproduct (:real^1)
      (\z. vsum P (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi
        (drop z)))
      (\z. vsum P (\s. c s * phi_sigma s carleson_phi (drop z)))` THEN
  CONJ_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC LPRODUCT_SELF THEN
    MP_TAC(ISPECL [`c:(int#int#int)->complex`;
      `P:(int#int#int)->bool`] CARLESON_RECON_L2_C) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[lspace; IN_ELIM_THM; RPOW_POW] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC CARLESON_NORMSQ_DOUBLE_C THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286K part (b): the H_j estimate atoms.                                    *)
(*                                                                           *)
(* Fremlin's H_j = sum_{sigma in P'_j} (sum_{tau in P', J_sig SUBSET         *)
(* J^l_tau}                                                                  *)
(* |<phi_sig|phi_tau><phi_tau|f>|)^2 <= 2 C3^2 C4 gam^2 muI_tauj.  These are *)
(* the pure arithmetic/structural building blocks; the tile-geometry (tree   *)
(* disjointness a-iii, per-scale weight-tail 286Gh) is supplied at instant-  *)
(* iation.  Layers: (1) termwise product via PHISIG_286GG*COEFF collapse     *)
(* (sqrt2^kt sqrt(2^-kt)=1); (2) inner tau-sum <= (C3 gam) inv(sqrt2^ks)     *)
(* int_II w via SUM_COVER_INTEGRAL_LE; (3) outer squaring; (4) scale-regroup *)
(* by k_sigma + geometric collapse (SUM_INV_ZPOW_GE_SCALED) -> 2 C4 2^-L.    *)
(* ------------------------------------------------------------------------- *)

(* J_sigma SUBSET J^l_tau ==> k_sigma <= k_tau (sigma coarser-or-equal       *)
(* scale).                                                                   *)
let TILE_JL_SUBSET_KLE = prove
 (`!(s:int#int#int) t. tile_J s SUBSET tile_Jl t ==> tile_k s <= tile_k t`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!ks nIs nJs kt nIt nJt.
        P ((ks,nIs,nJs):int#int#int) ((kt,nIt,nJt):int#int#int))
    ==> (!s t. P s t)`) THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_J; tile_Jl; tile_k] THEN
  DISCH_THEN(MP_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN INT_ARITH_TAC);;

(* Layer 1: termwise product bound.  PHISIG_286GG * COEFF_LE_ENERGY_MASS     *)
(* collapse via sqrt2^kt sqrt(2^-kt)=1 (SQRT_ZPOW_NEG_MUL).                  *)
let HJ_TERM_ARITH = prove
 (`!C3 gam ks kt A B W:real.
     &0 <= C3 /\ &0 <= gam /\ &0 <= A /\ &0 <= B /\ &0 <= W /\
     A <= C3 * inv(sqrt(&2 zpow ks)) * sqrt(&2 zpow kt) * W /\
     B <= gam * sqrt(&2 zpow (--kt))
     ==> A * B <= (C3 * gam) * inv(sqrt(&2 zpow ks)) * W`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(C3 * inv(sqrt(&2 zpow ks)) * sqrt(&2 zpow kt) * W) *
              (gam * sqrt(&2 zpow (--kt)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL2 THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    MP_TAC(SPEC `kt:int` SQRT_ZPOW_NEG_MUL) THEN CONV_TAC REAL_RING]);;

(* Layer 2: inner tau-sum bound (structural).  termwise HJ_TERM_ARITH +      *)
(* SUM_LE + SUM_LMUL + SUM_COVER_INTEGRAL_LE (the disjoint-cover integral).  *)
let HJ_INNER_SUM = prove
 (`!(C3:real) gam ks (kf:int#int#int->int) (Ai:(int#int#int)->real)
     (Bi:(int#int#int)->real) (G:(int#int#int)->(real->bool)) v II
     (S:(int#int#int)->bool).
     &0 <= C3 /\ &0 <= gam /\ FINITE S /\
     (!t. t IN S ==> &0 <= Ai t) /\ (!t. t IN S ==> &0 <= Bi t) /\
     (!t. t IN S ==> Ai t <= C3 * inv(sqrt(&2 zpow ks)) *
                            sqrt(&2 zpow (kf t)) * real_integral (G t) v) /\
     (!t. t IN S ==> Bi t <= gam * sqrt(&2 zpow (--(kf t)))) /\
     (!t. t IN S ==> v real_integrable_on (G t) /\ G t SUBSET II) /\
     (!t t'. t IN S /\ t' IN S /\ G t = G t' ==> t = t') /\
     (!t t'. t IN S /\ t' IN S /\ ~(t = t')
             ==> real_negligible (G t INTER G t')) /\
     v real_integrable_on II /\ (!x. &0 <= v x)
     ==> sum S (\t. Ai t * Bi t)
         <= (C3 * gam) * inv(sqrt(&2 zpow ks)) * real_integral II v`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum S (\t. (C3 * gam) * inv(sqrt(&2 zpow ks)) *
                         real_integral ((G:(int#int#int)->(real->bool)) t) v)`
                           THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC HJ_TERM_ARITH THEN
    EXISTS_TAC `(kf:int#int#int->int) t` THEN
    ASM_SIMP_TAC[] THEN
    MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_SIMP_TAC[];
    REWRITE_TAC[SUM_LMUL] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
        MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
        MATCH_MP_TAC SUM_COVER_INTEGRAL_LE THEN ASM_REWRITE_TAC[]]]]);;

(* Squaring core: (C inv(sqrt2^k) R)^2 = C^2 2^-k R^2 (INV_SQRT_ZPOW_SQ).    *)
let HJ_SQ_ARITH = prove
 (`!C k R:real.
     ((C:real) * inv(sqrt(&2 zpow k)) * R) pow 2
     = (C pow 2) * (&2 zpow (--k)) * (R pow 2)`,
  REPEAT GEN_TAC THEN MP_TAC(SPEC `k:int` INV_SQRT_ZPOW_SQ) THEN
  CONV_TAC REAL_RING);;

(* Layer 3: outer sum with squaring.  monotone REAL_POW_LE2 + HJ_SQ_ARITH.   *)
let HJ_OUTER_SQ = prove
 (`!(C3:real) gam (kf:(int#int#int)->int) (inr:(int#int#int)->real)
     (R:(int#int#int)->real) (Sp:(int#int#int)->bool).
     &0 <= C3 /\ &0 <= gam /\ FINITE Sp /\
     (!s. s IN Sp ==> &0 <= inr s) /\ (!s. s IN Sp ==> &0 <= R s) /\
     (!s. s IN Sp ==> inr s <= (C3 * gam) * inv(sqrt(&2 zpow (kf s))) * R s)
     ==> sum Sp (\s. (inr s) pow 2)
         <= (C3 * gam) pow 2 *
            sum Sp (\s. (&2 zpow (--(kf s))) * (R s) pow 2)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[GSYM SUM_LMUL] THEN
  MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `((C3 * gam) * inv(sqrt(&2 zpow (kf(s:int#int#int)))) * R s) pow
    2` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_POW_LE2 THEN ASM_SIMP_TAC[];
    REWRITE_TAC[HJ_SQ_ARITH; REAL_LE_REFL]]);;

(* Weight-tail-integral <= its full integral: R^2 <= R when 0<=R<=1.         *)
let SQ_LE_SELF = prove
 (`!R:real. &0 <= R /\ R <= &1 ==> R pow 2 <= R`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_POW_2] THEN
  GEN_REWRITE_TAC (RAND_CONV) [GSYM REAL_MUL_RID] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[]);;

(* Layer 4: scale-regroup by k_sigma + geometric collapse. R^2<=R            *)
(* (SQ_LE_SELF)                                                              *)
(* + SUM_GROUP into scale-groups + per-scale weight-tail bound (286Gh, <=    *)
(* C4) +                                                                     *)
(* SUM_INV_ZPOW_GE_SCALED (sum_{k>=L} c 2^-k <= 2c 2^-L).                    *)
let HJ_SCALE_COLLAPSE = prove
 (`!(kf:(int#int#int)->int) (R:(int#int#int)->real) (Sp:(int#int#int)->bool)
     (C4:real) (L:int).
     FINITE Sp /\ &0 <= C4 /\
     (!s. s IN Sp ==> &0 <= R s /\ R s <= &1) /\
     (!s. s IN Sp ==> L <= kf s) /\
     (!k. sum {s | s IN Sp /\ kf s = k} R <= C4)
     ==> sum Sp (\s. (&2 zpow (--(kf s))) * (R s) pow 2)
         <= &2 * C4 * inv(&2 zpow L)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum Sp (\s. (&2 zpow (--(kf(s:int#int#int)))) * R s)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
      MATCH_MP_TAC SQ_LE_SELF THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`kf:(int#int#int)->int`;
                 `\s:int#int#int. (&2 zpow (--(kf s))) * R s`;
                 `Sp:(int#int#int)->bool`; `IMAGE (kf:(int#int#int)->int) Sp`]
        SUM_GROUP) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (IMAGE (kf:(int#int#int)->int) Sp)
                  (\k. C4 * inv(&2 zpow k))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_SIMP_TAC[FINITE_IMAGE] THEN
    X_GEN_TAC `k:int` THEN REWRITE_TAC[IN_IMAGE] THEN DISCH_TAC THEN
      REWRITE_TAC[] THEN
    REWRITE_TAC[SUM_LMUL; REAL_ZPOW_NEG] THEN
    GEN_REWRITE_TAC (RAND_CONV) [REAL_MUL_SYM] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
       REAL_ARITH_TAC;
      ASM_SIMP_TAC[]];
    MATCH_MP_TAC SUM_INV_ZPOW_GE_SCALED THEN
    ASM_SIMP_TAC[FINITE_IMAGE] THEN
    REWRITE_TAC[FORALL_IN_IMAGE] THEN ASM_SIMP_TAC[]]);;

(* H_j composite: chains HJ_OUTER_SQ + HJ_SCALE_COLLAPSE into the exact      *)
(* Fremlin shape sum_{sig in P'_j} (inner sig)^2 <= (C3 gam)^2 (2 C4 2^-L).  *)
(* With L=k_tauj and the per-sig inner bound from HJ_INNER_SUM, this is      *)
(* H_j <= 2 C3^2 C4 gam^2 muI_tauj (muI_tauj = 2^-L).                        *)
let HJ_FULL_BOUND = prove
 (`!(C3:real) gam (kf:(int#int#int)->int) (inr:(int#int#int)->real)
     (R:(int#int#int)->real) (Sp:(int#int#int)->bool) (C4:real) (L:int).
     &0 <= C3 /\ &0 <= gam /\ FINITE Sp /\ &0 <= C4 /\
     (!s. s IN Sp ==> &0 <= inr s) /\
     (!s. s IN Sp ==> &0 <= R s /\ R s <= &1) /\
     (!s. s IN Sp ==> inr s <= (C3 * gam) * inv(sqrt(&2 zpow (kf s))) * R s) /\
     (!s. s IN Sp ==> L <= kf s) /\
     (!k. sum {s | s IN Sp /\ kf s = k} R <= C4)
     ==> sum Sp (\s. (inr s) pow 2)
         <= (C3 * gam) pow 2 * (&2 * C4 * inv(&2 zpow L))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(C3 * gam) pow 2 *
              sum Sp (\s. (&2 zpow (--(kf(s:int#int#int)))) * (R s) pow 2)`
                THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC HJ_OUTER_SQ THEN ASM_SIMP_TAC[];
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REWRITE_TAC[REAL_LE_POW_2];
      MATCH_MP_TAC HJ_SCALE_COLLAPSE THEN ASM_SIMP_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* 286K(a-iii) spatial-interval disjointness -- the clean geometric core.    *)
(* Two dyadic cells I_a = dyho a p (finer, a<=b) and I_b = dyho b q: if I_a  *)
(* is                                                                        *)
(* NOT contained in I_b, they are DISJOINT. (Dyadic laminarity DYHO_TRICHOT- *)
(* OMY: I_b inside I_a needs a=b [DYHO_SUBSET_SCALE] then q=p                *)
(* [DYHO_SAMESCALE_                                                          *)
(* SUBSET_EQ], putting I_a inside I_b -- contra.) Fremlin uses this (with    *)
(* the                                                                       *)
(* stopping-time-supplied ~(I_sig SUBSET I_tauj)) to conclude I_sig, I_tauj  *)
(* disjoint, hence the H_j interval-cover disjointness.                      *)
(* ------------------------------------------------------------------------- *)
let DYHO_FINER_NOT_SUBSET_DISJOINT = prove
 (`!a b p q:int.
     a <= b /\ ~(dyho a p SUBSET dyho b q)
     ==> DISJOINT (dyho a p) (dyho b q)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`a:int`; `p:int`; `b:int`; `q:int`] DYHO_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `a:int = b` ASSUME_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  UNDISCH_TAC `~(dyho a p SUBSET dyho b q)` THEN REWRITE_TAC[] THEN
  UNDISCH_TAC `dyho b q SUBSET dyho a p` THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o MATCH_MP DYHO_SAMESCALE_SUBSET_EQ) THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[SUBSET_REFL]);;

(* Tile-level a-iii: sigma finer-or-equal spatial (k_tauj <= k_sig) with     *)
(* I_sig NOT SUBSET I_tauj ==> I_sig, I_tauj disjoint.                       *)
(* DYHO_FINER_NOT_SUBSET_                                                    *)
(* DISJOINT at the tile exponents (--k_sig <= --k_tauj since k_tauj <=       *)
(* k_sig).                                                                   *)
let TILE_I_FINER_NOT_SUBSET_DISJOINT = prove
 (`!(sig:int#int#int) (tauj:int#int#int).
     tile_k tauj <= tile_k sig /\ ~(tile_I sig SUBSET tile_I tauj)
     ==> DISJOINT (tile_I sig) (tile_I tauj)`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!ks nIs nJs kt nIt nJt.
        P ((ks,nIs,nJs):int#int#int) ((kt,nIt,nJt):int#int#int))
    ==> (!s t. P s t)`) THEN
  MAP_EVERY X_GEN_TAC
   [`ksig:int`;`nIsig:int`;`nJsig:int`;`ktj:int`;`nItj:int`;`nJtj:int`] THEN
  REWRITE_TAC[tile_I; tile_k] THEN STRIP_TAC THEN
  MATCH_MP_TAC DYHO_FINER_NOT_SUBSET_DISJOINT THEN
  ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC);;

(* Tree L^2 bound for a general coefficient c (the zeta-carrying             *)
(* reconstruction).                                                          *)
let FTILDE_L2_NORM_C = prove
 (`?C3. &0 <= C3 /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau. FINITE P
      ==> drop(integral (:real^1)
            (\z. lift(norm(vsum {s | s IN P /\ tile_ler s tau}
                           (\s. c s * phi_sigma s carleson_phi (drop z))) pow
                             2)))
          <= C3 * sum {s | s IN P /\ tile_ler s tau} (\s. norm(c s) pow 2)`,
  X_CHOOSE_THEN
    `C3:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "DBL")) FTILDE_DOUBLE_LE_C
    THEN
  EXISTS_TAC `C3:real` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `norm(vsum {s | s IN P /\ tile_ler s tau}
     (\s. vsum {s | s IN P /\ tile_ler s tau} (\t.
       (c:(int#int#int)->complex) s * cnj(c t) *
       lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                          (\z. phi_sigma t carleson_phi (drop z)))))` THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`c:(int#int#int)->complex`;
     `{s | s IN P /\ tile_ler s tau}`]
      CARLESON_NORMSQ_REAL_C) THEN
    ASM_SIMP_TAC[FINITE_RESTRICT] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[COMPLEX_NORM_CX; REAL_ABS_LE];
    USE_THEN "DBL" (MP_TAC o SPECL
      [`c:(int#int#int)->complex`; `{s | s IN P /\ tile_ler s tau}`;
        `tau:int#int#int`]) THEN
    ASM_SIMP_TAC[FINITE_RESTRICT] THEN REWRITE_TAC[IN_ELIM_THM] THEN
    DISCH_THEN MATCH_MP_TAC THEN MESON_TAC[]]);;

let FTILDE_SCHWARTZ_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau. FINITE P
     ==> schwartz(\x. vsum {s | s IN P /\ tile_ler s tau}
                          (\s. c s * phi_sigma s carleson_phi x))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC SCHWARTZ_VSUM THEN
  ASM_SIMP_TAC[FINITE_RESTRICT; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
  BETA_TAC THEN MATCH_MP_TAC SCHWARTZ_CMUL THEN REWRITE_TAC[ETA_AX] THEN
  MATCH_MP_TAC PHISIG_SCHWARTZ THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ]);;

(* M4 brick: the m-truncated tree reconstruction gt_m = sum over the         *)
(* sub-tree                                                                  *)
(* s IN P, s <=_r tau, tile_k s <= m of c_s phi_sigma (Fremlin 286(h)) is    *)
(* Schwartz -- same argument as FTILDE_SCHWARTZ_C, the index set being a     *)
(* further finite restriction, for general complex coefficients c_s.        *)
let GTM_SCHWARTZ = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau m. FINITE P
     ==> schwartz(\x. vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
                          (\s. c s * phi_sigma s carleson_phi x))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC SCHWARTZ_VSUM THEN
  ASM_SIMP_TAC[FINITE_RESTRICT; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
  BETA_TAC THEN MATCH_MP_TAC SCHWARTZ_CMUL THEN REWRITE_TAC[ETA_AX] THEN
  MATCH_MP_TAC PHISIG_SCHWARTZ THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ]);;

(* M4 STEP (C), transform side: (gt * psicheck)^ = sqrt2pi * gt_m^           *)
(* everywhere.                                                               *)
(* 283M FOURIER_CONVOLUTION gives (gt*psicheck)^ = sqrt2pi gt^ psicheck^;    *)
(* PSICHECK_FOURIER: psicheck^ = cpsi; FTILDE_CPSI_FHAT (step B): gt_m^ =    *)
(* cpsi                                                                      *)
(* gt^.  So (gt*psicheck)^ = sqrt2pi gt^ cpsi = sqrt2pi gt_m^.  This is the  *)
(* analytic heart of gt_m = (1/sqrt2pi)(gt*psicheck); the                    *)
(* everywhere-equality                                                       *)
(* of the FUNCTIONS themselves then follows by Fourier injectivity once      *)
(* convol gt psicheck is known Schwartz (CONVOL_SCHWARTZ, next).             *)
let FTILDE_CONVOL_FHAT = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau m nhat w.
     FINITE P /\ tile_J tau SUBSET dyho m nhat
     ==> fourier (convol (\x. vsum {s | s IN P /\ tile_ler s tau}
                                   (\s. c s * phi_sigma s carleson_phi x))
                         (psicheck (&3 * &2 zpow m) (dyho_mid m nhat)
                           carleson_phi)) w =
         Cx(sqrt(&2 * pi)) *
         fourier (\x. vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
                          (\s. c s * phi_sigma s carleson_phi x)) w`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\x. vsum {s | s IN P /\ tile_ler s tau}
              (\s. c s * phi_sigma s carleson_phi x)`;
    `psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi`;
    `w:real`] FOURIER_CONVOLUTION) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC PSICHECK_SCHWARTZ THEN
      REWRITE_TAC[CARLESON_PHI_SCHWARTZ] THEN
      MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC]];
    DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[PSICHECK_FOURIER] THEN
  MP_TAC(ISPECL [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`;
                 `tau:int#int#int`; `m:int`; `nhat:int`;
                   `w:real`] FTILDE_CPSI_FHAT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_MUL_AC]);;

(* M4 STEP (C) COMPLETE = Fremlin 286(h)(v): gt_m = (1/sqrt2pi)(gt *         *)
(* psicheck)                                                                 *)
(* as an EVERYWHERE equality (here in the form convol gt psicheck = sqrt2pi  *)
(* gt_m). CONVOL_SCHWARTZ_EQ (the Fourier-uniqueness bridge) instantiated at *)
(* cf=gt, cg=psicheck, gtm=gt_m; the same-transform hypothesis is exactly    *)
(* FTILDE_CONVOL_FHAT. Schwartzness: FTILDE_SCHWARTZ_C (gt),                 *)
(* PSICHECK_SCHWARTZ                                                         *)
(* (psicheck), GTM_SCHWARTZ (gt_m).                                          *)
let FTILDE_CONVOL_EQ = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau m nhat x.
     FINITE P /\ tile_J tau SUBSET dyho m nhat
     ==> convol (\x. vsum {s | s IN P /\ tile_ler s tau}
                          (\s. c s * phi_sigma s carleson_phi x))
                (psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi) x =
         Cx(sqrt(&2 * pi)) *
         vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
              (\s. c s * phi_sigma s carleson_phi x)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\x. vsum {s | s IN P /\ tile_ler s tau}
              (\s. c s * phi_sigma s carleson_phi x)`;
    `psicheck (&3 * &2 zpow m) (dyho_mid m nhat) carleson_phi`;
    `\x. vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
              (\s. c s * phi_sigma s carleson_phi x)`]
   CONVOL_SCHWARTZ_EQ) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC PSICHECK_SCHWARTZ THEN
        REWRITE_TAC[CARLESON_PHI_SCHWARTZ] THEN
      MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC];
      MATCH_MP_TAC GTM_SCHWARTZ THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN MATCH_MP_TAC FTILDE_CONVOL_FHAT THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(MP_TAC o SPEC `x:real`) THEN BETA_TAC THEN SIMP_TAC[]]);;

(* ========================================================================= *)
(* CARLESON_GTILDE_MAXIMAL = Fremlin 286L part (h) [(vi) concrete].  The     *)
(* m-cutoff tree sub-sum gt_m (= vsum over s <=_r tau with tile_k s <= m) is *)
(* pointwise dominated by Cgm times the Hardy-Littlewood maximal function of *)
(* the full tree sum g~, at ANY x' within 2^{-m} of x.  This is the deepest  *)
(* analytic ingredient of the alpha3 (W3, sigma <=_r tau) correlation        *)
(* estimate:                                                                 *)
(* it converts the m-scale local reconstruction into a maximal-function      *)
(* bound                                                                     *)
(* that the 286A H-L L^2 theorem then controls. Cgm = C1 int cw1 / sqrt2pi   *)
(* is                                                                        *)
(* m-INDEPENDENT (the 2^m dilation cancels, CW1_DILATE_INTEGRAL_VALUE).      *)
(* Assembled by instantiating GTM_MAXIMAL_ABSTRACT with the everywhere       *)
(* convolution identity FTILDE_CONVOL_EQ (gt_m = (1/sqrt2pi) gt * psicheck)  *)
(* and the tent domination CARLESON_PHI_CW1 (|phi| <= C1 cw1).               *)
(* ========================================================================= *)
let CARLESON_GTILDE_MAXIMAL = prove
 (`?Cgm. &0 <= Cgm /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau m nhat x x'.
      FINITE P /\ tile_J tau SUBSET dyho m nhat /\
      &0 < &2 zpow m /\ abs(x - x') <= &2 zpow(--m)
      ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
                    (\s. c s * phi_sigma s carleson_phi x))
          <= Cgm * hl_maximal (\z. norm(vsum {s | s IN P /\ tile_ler s tau}
                                          (\s. c s * phi_sigma s carleson_phi
                                            z))) x'`,
  X_CHOOSE_THEN `C1:real` STRIP_ASSUME_TAC CARLESON_PHI_CW1 THEN
  EXISTS_TAC `C1 * real_integral (:real) cw1 / sqrt(&2 * pi)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_DIV THEN REWRITE_TAC[CW1_INTEGRAL_POS] THEN
    MATCH_MP_TAC SQRT_POS_LE THEN MP_TAC PI_POS THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\z. vsum {s | s IN P /\ tile_ler s tau}
              (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi z)`;
    `vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
          (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi x)`;
    `m:int`; `nhat:int`; `x:real`; `x':real`;
      `C1:real`] GTM_MAXIMAL_ABSTRACT) THEN
  BETA_TAC THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`;
                   `tau:int#int#int`; `m:int`; `nhat:int`;
                     `x:real`] FTILDE_CONVOL_EQ) THEN
    ASM_REWRITE_TAC[]]);;

(* Two tiny arithmetic/norm rules used by GTM_DIFF_BOUND, stated             *)
(* context-free (NORM_ARITH / REAL_ARITH break on the nonlinear              *)
(* Cgm*hl_maximal atoms once the big tile assumptions are in scope, so       *)
(* factor them out).                                                         *)
let NORM_SUB_TRIANGLE_ADD = prove
 (`!a b:complex. norm(a - b) <= norm a + norm b`, REPEAT GEN_TAC THEN
   CONV_TAC NORM_ARITH);;

(* 286L (h) -> (i) difference form: the two-scale telescoped cutoff sub-sum  *)
(* g~_{m2} - g~_{m1} (= Fremlin's g~_{l_L-1} - g~_{m-1} at m1=m-1, m2=l_L-1) *)
(* is                                                                        *)
(* bounded by 2 Cgm g~*(x') whenever x' is within 2^{-m1},2^{-m2} of x.  Two *)
(* applications of CARLESON_GTILDE_MAXIMAL (triangle inequality). This is    *)
(* the                                                                       *)
(* pointwise engine of part (i): v3(x) collapses to such a difference, so    *)
(* v3(x) <= 2 Cgm g~*(x').                                                   *)
let SCALE_BAND_MEM = prove
 (`!m1 m2 P tau x.
     m1 <= m2
     ==> ((x IN P /\ tile_ler x tau /\ m1 < tile_k x /\ tile_k x <= m2) <=>
          (x IN P /\ tile_ler x tau /\ tile_k x <= m2) /\
          ~(x IN P /\ tile_ler x tau /\ tile_k x <= m1))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `(x:int#int#int) IN P` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `tile_ler x tau` THEN ASM_REWRITE_TAC[] THEN
    ASM_INT_ARITH_TAC);;

(* The scale-band vsum equals the difference of the two cutoff sub-sums      *)
(* g~_{m2} - g~_{m1} (VSUM_DIFF on the set-difference SCALE_BAND_MEM).       *)
let VSUM_SCALE_BAND = prove
 (`!(c:(int#int#int)->complex) P tau m1 m2 x.
     FINITE P /\ m1 <= m2
     ==> vsum {s | s IN P /\ tile_ler s tau /\ m1 < tile_k s /\ tile_k s <= m2}
              (\s. c s * phi_sigma s carleson_phi x) =
         vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m2}
              (\s. c s * phi_sigma s carleson_phi x) -
         vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m1}
              (\s. c s * phi_sigma s carleson_phi x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `{s | s IN P /\ tile_ler s tau /\ m1 < tile_k s /\ tile_k s <= m2} =
    {s | s IN P /\ tile_ler s tau /\ tile_k s <= m2} DIFF
    {s | s IN P /\ tile_ler s tau /\ tile_k s <= m1}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_DIFF; IN_ELIM_THM] THEN GEN_TAC THEN
    MATCH_MP_TAC SCALE_BAND_MEM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC VSUM_DIFF THEN CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_RESTRICT THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC]);;

(* 286L (i) SCALE-BAND MAXIMAL BOUND: any tree scale-band {m1 < k_s <= m2}   *)
(* sub-sum (= Fremlin's v3(x) after the g(x) IN J^r_s <=> k_s >= m collapse, *)
(* with m1 = m-1, m2 = l_L-1) is dominated by 2 Cgm g~*(x'), for x' within   *)
(* 2^{-m1},2^{-m2} of x. = VSUM_SCALE_BAND (band = difference) +             *)
(* GTM_DIFF_BOUND (difference <= 2 Cgm gstar).                               *)
let TILE_SET_MIN_SCALE = prove
 (`!(A:(int#int#int)->bool). FINITE A ==> ~(A = {})
     ==> ?s0. s0 IN A /\ (!s. s IN A ==> tile_k s0 <= tile_k s)`,
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
   [SIMP_TAC[]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`e:int#int#int`; `A:(int#int#int)->bool`] THEN
  STRIP_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `A:(int#int#int)->bool = {}` THENL
   [EXISTS_TAC `e:int#int#int` THEN
     ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN
    REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[INT_LE_REFL];
    FIRST_X_ASSUM(MP_TAC o check(is_imp o concl)) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `s1:int#int#int` STRIP_ASSUME_TAC) THEN
    ASM_CASES_TAC `tile_k e <= tile_k (s1:int#int#int)` THENL
     [EXISTS_TAC `e:int#int#int` THEN ASM_REWRITE_TAC[IN_INSERT] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[INT_LE_REFL] THEN
      MATCH_MP_TAC INT_LE_TRANS THEN EXISTS_TAC `tile_k (s1:int#int#int)` THEN
      ASM_SIMP_TAC[];
      EXISTS_TAC `s1:int#int#int` THEN ASM_REWRITE_TAC[IN_INSERT] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
       [ASM_INT_ARITH_TAC; ASM_SIMP_TAC[]]]]);;

(* 286L (i) SLICE = BAND: the W3 pointwise slice {s <=_r tau : k_s < lL,     *)
(* g(x) IN                                                                   *)
(* J^r_s} (nonempty case) equals a scale-band {s <=_r tau : m <= k_s < lL},  *)
(* m = its                                                                   *)
(* min scale. Forward: m is the min. Backward: from the min element s0 (with *)
(* g(x) IN J^r_s0) and TILE_TREE_JR_NEST (J^r_s0 SUBSET J^r_s since k_s0 <=  *)
(* k_s),                                                                     *)
(* g(x) IN J^r_s. This is the g(x) IN J^r_sigma <=> k_sigma >= m collapse of *)
(* Fremlin                                                                   *)
(* part (i), reducing v3(x) to a scale-band sum that V3_BAND_BOUND controls. *)
let V3_SLICE_IS_BAND = prove
 (`!(P:(int#int#int)->bool) tau lL y.
     FINITE P /\
     ~({s | s IN P /\ tile_ler s tau /\ tile_k s < lL /\ y IN tile_Jr s} = {})
     ==> ?m. m <= lL - &1 /\
             {s | s IN P /\ tile_ler s tau /\ tile_k s < lL /\ y IN tile_Jr s}
               =
             {s | s IN P /\ tile_ler s tau /\ m <= tile_k s /\ tile_k s < lL}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `{s | s IN P /\ tile_ler s tau /\ tile_k s < lL /\ y IN tile_Jr
    s}`
    TILE_SET_MIN_SCALE) THEN
  ANTS_TAC THENL [ASM_SIMP_TAC[FINITE_RESTRICT]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s0:int#int#int` MP_TAC) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
  EXISTS_TAC `tile_k (s0:int#int#int)` THEN CONJ_TAC THENL
   [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN X_GEN_TAC `s:int#int#int` THEN
  EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `s:int#int#int`) THEN
    ASM_REWRITE_TAC[IN_ELIM_THM];
    MP_TAC(ISPECL [`s0:int#int#int`; `s:int#int#int`; `tau:int#int#int`]
      TILE_TREE_JR_NEST) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* Reindex the half-open scale-band {m <= k_s < lL} to the V3_BAND_BOUND     *)
(* form {m-1 < k_s <= lL-1} (integer discreteness).                          *)
let SCALE_BAND_REINDEX = prove
 (`!(P:(int#int#int)->bool) tau m lL.
     {s | s IN P /\ tile_ler s tau /\ m <= tile_k s /\ tile_k s < lL} =
     {s | s IN P /\ tile_ler s tau /\ m - &1 < tile_k s /\ tile_k s <= lL -
       &1}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN
  GEN_TAC THEN EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_INT_ARITH_TAC);;

(* A cutoff sub-sum BELOW k_tau is empty (tree tiles have k_s >= k_tau,      *)
(* TILE_LER_SCALE), so it vanishes. Handles the lower cutoff g~_{m-1} when   *)
(* the                                                                       *)
(* min band-scale m equals k_tau (m-1 < k_tau).                              *)
let GTM_CUTOFF_EMPTY = prove
 (`!(c:(int#int#int)->complex) P tau m1 x.
     m1 < tile_k tau
     ==> vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m1}
              (\s. c s * phi_sigma s carleson_phi x) = vec 0`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `{s | s IN P /\ tile_ler s tau /\ tile_k s <= m1} = {}` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
    X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`s:int#int#int`; `tau:int#int#int`] TILE_LER_SCALE) THEN
    ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC;
    REWRITE_TAC[VSUM_CLAUSES]]);;

(* J_tau sits in a length-2^m dyadic interval for any m >= k_tau             *)
(* (DYHO_COARSEN); supplies CARLESON_GTILDE_MAXIMAL's dyho-containment       *)
(* witness without threading it.                                             *)
let TILE_J_COARSEN_EXISTS = prove
 (`!tau m. tile_k tau <= m ==> ?nhat. tile_J tau SUBSET dyho m nhat`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[tile_k; tile_J] THEN DISCH_TAC THEN
  EXISTS_TAC `p2 div &2 pow num_of_int (m - p1)` THEN
  MATCH_MP_TAC DYHO_COARSEN THEN ASM_REWRITE_TAC[]);;

(* Single-cutoff maximal bound needing only k_tau <= m: norm(g~_m(x)) <= Cgm *)
(* g~*(x')                                                                   *)
(* for |x-x'| <= 2^{-m}. = CARLESON_GTILDE_MAXIMAL with the dyho witness     *)
(* supplied                                                                  *)
(* internally (TILE_J_COARSEN_EXISTS).                                       *)
let GTM_CUTOFF_COARSEN = prove
 (`?Cgm. &0 <= Cgm /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau m x x'.
      FINITE P /\ tile_k tau <= m /\ abs(x - x') <= &2 zpow(--m)
      ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
                    (\s. c s * phi_sigma s carleson_phi x))
          <= Cgm * hl_maximal (\z. norm(vsum {s | s IN P /\ tile_ler s tau}
                                        (\s. c s * phi_sigma s carleson_phi
                                          z))) x'`,
  X_CHOOSE_THEN `Cgm:real` STRIP_ASSUME_TAC CARLESON_GTILDE_MAXIMAL THEN
  EXISTS_TAC `Cgm:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`tau:int#int#int`; `m:int`] TILE_J_COARSEN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `nhat:int`) THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `nhat:int` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC);;

(* 286L (i) v3 POINTWISE BOUND: the W3 pointwise slice sum -- {s <=_r tau :  *)
(* k_s < lL,                                                                 *)
(* x IN J^r_s} weighted by c_s phi_s(x) -- is <= 2 Cgm g~*(x) at the point x *)
(* itself.                                                                   *)
(* This is Fremlin's v3(x) <= C1 g~*(x') at x'=x (|x-x|=0). Route: nonempty  *)
(* slice =                                                                   *)
(* scale-band {m <= k_s < lL} (V3_SLICE_IS_BAND, up-set via                  *)
(* TILE_TREE_JR_NEST) =                                                      *)
(* reindexed {m-1 < k_s <= lL-1} = g~_{lL-1} - g~_{m-1} (VSUM_SCALE_BAND);   *)
(* triangle +                                                                *)
(* two GTM_CUTOFF bounds (COARSEN when m-1 >= k_tau, else the cutoff is      *)
(* EMPTY). The                                                               *)
(* positivity 0 <= Cgm g~* is bootstrapped from the lL-1 cutoff bound (norm  *)
(* >= 0), so                                                                 *)
(* the conditional HL_MAXIMAL_POS is not needed.                             *)
let AVG_OVER_CELL = prove
 (`!vx (K:real) g L.
     &0 < real_measure L /\ real_measurable L /\ g real_integrable_on L /\
     (!x'. x' IN L ==> vx <= K * g x')
     ==> vx <= (K / real_measure L) * real_integral L g`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `vx * real_measure L <= K * real_integral L g` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral L (\x'. K * g x')` THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`L:real->bool`;
       `vx:real`] CONST_INTEGRABLE_MEASURABLE) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC (LAND_CONV) [GSYM th]) THEN
      MATCH_MP_TAC REAL_INTEGRAL_LE THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[REAL_INTEGRAL_LMUL; REAL_LE_REFL]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(K / real_measure L) * real_integral L g =
                (K * real_integral L g) / real_measure L` SUBST1_TAC THENL
   [MP_TAC(MATCH_MP REAL_LT_IMP_NZ (ASSUME `&0 < real_measure L`)) THEN
    CONV_TAC REAL_FIELD; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ]);;

(* V3_POINTWISE with the MEMBERSHIP point y DECOUPLED from the eval point x  *)
(* (and the                                                                  *)
(* maximal point x').  In the (j) integral layer the W3-slice indicator is   *)
(* chi{h(x) IN J^r_s} -- membership at h(x), the summand phi_s evaluated at  *)
(* x -- so                                                                   *)
(* the slice's y = h(x) differs from x. V3_SLICE_IS_BAND already takes an    *)
(* arbitrary                                                                 *)
(* y, so the proof is verbatim V3_POINTWISE_GEN with y in the slice.         *)
let V3_POINTWISE_HGEN = prove
 (`?Cgm. &0 <= Cgm /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau lL x x' y.
      FINITE P /\ tile_k tau < lL /\ abs(x - x') <= &2 zpow(--(lL - &1))
      ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < lL /\ y IN
        tile_Jr s}
                    (\s. c s * phi_sigma s carleson_phi x))
          <= &2 * Cgm * hl_maximal (\z. norm(vsum {s | s IN P /\ tile_ler s
            tau}
                                          (\s. c s * phi_sigma s carleson_phi
                                            z))) x'`,
  X_CHOOSE_THEN `Cgm:real` STRIP_ASSUME_TAC GTM_CUTOFF_COARSEN THEN
  EXISTS_TAC `Cgm:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  ABBREV_TAC `H = hl_maximal (\z. norm(vsum {s | s IN P /\ tile_ler s tau}
                              (\s. (c:(int#int#int)->complex) s * phi_sigma s
                                carleson_phi z))) x'` THEN
  SUBGOAL_THEN
   `norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= lL - &1}
              (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi x))
                <= Cgm * H`
   ASSUME_TAC THENL
   [EXPAND_TAC "H" THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= Cgm * H` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= lL - &1}
              (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi x))`
                THEN
    ASM_REWRITE_TAC[NORM_POS_LE]; ALL_TAC] THEN
  ASM_CASES_TAC
   `{s | s IN P /\ tile_ler s tau /\ tile_k s < lL /\ y IN tile_Jr s} = {}`
     THENL
   [ASM_REWRITE_TAC[VSUM_CLAUSES; NORM_0] THEN
    REWRITE_TAC[REAL_ARITH `&2 * a = a + a`] THEN MATCH_MP_TAC REAL_LE_ADD THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`; `tau:int#int#int`; `lL:int`;
    `y:real`]
    V3_SLICE_IS_BAND) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN
    `m:int` (CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC)) THEN
  ONCE_REWRITE_TAC[SCALE_BAND_REINDEX] THEN
  MP_TAC(ISPECL [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`;
    `tau:int#int#int`;
                 `m - &1:int`; `lL - &1:int`; `x:real`] VSUM_SCALE_BAND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= lL - &1}
              (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi x))
                +
    norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m - &1}
              (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi x))`
                THEN
  CONJ_TAC THENL [REWRITE_TAC[NORM_SUB_TRIANGLE_ADD]; ALL_TAC] THEN
  REWRITE_TAC[REAL_ARITH `&2 * a = a + a`] THEN
  MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    ASM_CASES_TAC `tile_k tau <= m - &1` THENL
     [MP_TAC(ISPECL
        [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`;
          `tau:int#int#int`;
         `m - &1:int`; `x:real`; `x':real`]
        (CONJUNCT2(ASSUME `&0 <= Cgm /\
          (!(c:(int#int#int)->complex) P tau m x x'.
             FINITE P /\ tile_k tau <= m /\ abs(x - x') <= &2 zpow(--m)
             ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <= m}
                    (\s. c s * phi_sigma s carleson_phi x)) <=
                 Cgm * hl_maximal (\z. norm(vsum {s | s IN P /\ tile_ler s tau}
                          (\s. c s * phi_sigma s carleson_phi z))) x')`))) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC REAL_LE_TRANS THEN
        EXISTS_TAC `&2 zpow(--(lL - &1))` THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC;
        EXPAND_TAC "H" THEN DISCH_THEN(fun th -> ASM_REWRITE_TAC[th])];
      MP_TAC(ISPECL [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`;
                     `tau:int#int#int`; `m - &1:int`;
                       `x:real`] GTM_CUTOFF_EMPTY) THEN
      ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[NORM_0] THEN
        ASM_REWRITE_TAC[]]]);;

(* alpha3 (j) CELL CORE (abstract): the norm of a finite vsum of             *)
(* tile-integrals over                                                       *)
(* per-tile regions region_s SUBSET G is <= int_G Kfun, given the POINTWISE  *)
(* cap                                                                       *)
(* norm(vsum(if x IN region_s then ff_s x else 0)) <= Kfun x on G. This is   *)
(* the                                                                       *)
(* cancellation-preserving |alpha3-cell| <= int_G v3 step (UNLIKE alpha2's   *)
(* sum-of-                                                                   *)
(* norms). Route: INTEGRAL_RESTRICT rewrites each int_{region_s} ff_s =      *)
(* int_G(if..                                                                *)
(* then ff_s else 0) (region_s SUBSET G), INTEGRAL_VSUM pulls the vsum       *)
(* inside                                                                    *)
(* (INTEGRABLE_RESTRICT for each restricted integrand),                      *)
(* INTEGRAL_NORM_BOUND_INTEGRAL                                              *)
(* bounds norm(int vsum) <= int norm(vsum) <= int_G Kfun (the cap;           *)
(* REAL_INTEGRABLE_ON                                                        *)
(* bridges Kfun to the vector integrand lift o Kfun o drop). In the          *)
(* application                                                               *)
(* ff_s = \x. c_s phi_sigma_s(x), region_s = {x IN E | h x IN J^r_s} INTER   *)
(* dyho a p,                                                                 *)
(* Kfun = 2 Cgm g~*(x') (V3_POINTWISE_HGEN, membership y = h x).             *)
let ALPHA3_CELL_CORE = prove
 (`!(A:(int#int#int)->bool) (ff:(int#int#int)->real->complex) region G Kfun.
     FINITE A /\
     (!s. s IN A ==> region s SUBSET G /\
          (\z. ff s (drop z)) integrable_on (IMAGE lift (region s))) /\
     Kfun real_integrable_on G /\
     (!x. x IN G ==> norm(vsum A (\s. if x IN region s then ff s x else
       Cx(&0))) <= Kfun x)
     ==> norm(vsum A (\s. integral (IMAGE lift (region s)) (\z. ff s (drop
       z))))
         <= real_integral G Kfun`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!s. s IN A ==>
      integral (IMAGE lift (region s)) (\z. (ff:(int#int#int)->real->complex) s
        (drop z)) =
      integral (IMAGE lift G) (\z. if drop z IN region s then ff s (drop z)
        else vec 0)`
   (fun th -> ASM_SIMP_TAC[th]) THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`\z. (ff:(int#int#int)->real->complex) s (drop z)`;
                   `IMAGE lift (region(s:int#int#int))`;
                     `IMAGE lift G`] INTEGRAL_RESTRICT) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[SUBSET; IN_IMAGE_LIFT_DROP] THEN ASM SET_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[IN_IMAGE_LIFT_DROP] THEN DISCH_THEN(SUBST1_TAC o GSYM) THEN
      REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!s. s IN A ==>
      (\z. if drop z IN region s then (ff:(int#int#int)->real->complex) s (drop
        z) else vec 0)
      integrable_on (IMAGE lift G)`
   ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`\z. (ff:(int#int#int)->real->complex) s (drop z)`;
                   `IMAGE lift (region(s:int#int#int))`;
                     `IMAGE lift G`] INTEGRABLE_RESTRICT) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[SUBSET; IN_IMAGE_LIFT_DROP] THEN ASM SET_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[IN_IMAGE_LIFT_DROP] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\s z. if drop z IN region s then (ff:(int#int#int)->real->complex) s (drop
     z) else vec 0`;
    `IMAGE lift G`; `A:(int#int#int)->bool`] INTEGRAL_VSUM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o GSYM) THEN
  ASM_SIMP_TAC[REAL_INTEGRAL] THEN
  MATCH_MP_TAC INTEGRAL_NORM_BOUND_INTEGRAL THEN
  REWRITE_TAC[o_DEF] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_VSUM THEN ASM_REWRITE_TAC[];
    UNDISCH_TAC `Kfun real_integrable_on G` THEN
    REWRITE_TAC[REAL_INTEGRABLE_ON; o_DEF];
    X_GEN_TAC `z:real^1` THEN REWRITE_TAC[IN_IMAGE_LIFT_DROP; LIFT_DROP] THEN
      DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `drop(z:real^1)`) THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(REAL_ARITH `a = b ==> a <= K ==> b <= K`) THEN
    AP_TERM_TAC THEN MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN
    DISCH_TAC THEN REWRITE_TAC[] THEN COND_CASES_TAC THEN
      REWRITE_TAC[COMPLEX_VEC_0]]);;

(* Two points of one dyadic cell dyho a p are within 2^{a+1} (each < 2^a     *)
(* from the mid,                                                             *)
(* DYHO_MID_DIST; triangle). = the |x-x'| <= 2^{-(lL-1)} = 2^{a+1} (lL=-a)   *)
(* that                                                                      *)
(* V3_POINTWISE_HGEN needs for x, x' both in the cover cell L = dyho a p.    *)
let DYHO_PAIR_DIST = prove
 (`!a p x y. x IN dyho a p /\ y IN dyho a p ==> abs(x - y) <= &2 zpow(a + &1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`a:int`; `p:int`; `x:real`] DYHO_MID_DIST) THEN
    ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`a:int`; `p:int`; `y:real`] DYHO_MID_DIST) THEN
    ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&2 zpow(a + &1) = &2 * &2 zpow a` SUBST1_TAC THENL
   [SIMP_TAC[REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ; REAL_ZPOW_1] THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* alpha3 (i) CONSTANT cell cap: for x, x' both in the cover cell dyho a p   *)
(* (lL = -a),                                                                *)
(* the W3 slice sum at eval x, membership h(x), is <= 2 Cgm g~*(x'). =       *)
(* V3_POINTWISE_                                                             *)
(* HGEN with |x-x'| <= 2^{a+1} (DYHO_PAIR_DIST). Holds for ALL x' in the     *)
(* cell, so                                                                  *)
(* AVG_OVER_CELL then averages to the constant (2Cgm/muK) int_K g~* cap the  *)
(* (j) layer                                                                 *)
(* (ALPHA3_CELL_CORE) consumes.                                              *)
let V3_CELL_PTWISE = prove
 (`?Cgm. &0 <= Cgm /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau a p x x' h.
      FINITE P /\ tile_k tau < --a /\ x IN dyho a p /\ x' IN dyho a p
      ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --a /\
        (h:real->real) x IN tile_Jr s}
                    (\s. c s * phi_sigma s carleson_phi x))
          <= &2 * Cgm * hl_maximal (\w. norm(vsum {s | s IN P /\ tile_ler s
            tau}
                                          (\s. c s * phi_sigma s carleson_phi
                                            w))) x'`,
  X_CHOOSE_THEN
    `Cgm:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PW"))
     V3_POINTWISE_HGEN THEN
  EXISTS_TAC `Cgm:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  USE_THEN "PW" (MP_TAC o SPECL
   [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
    `--a:int`; `x:real`; `x':real`; `(h:real->real) x`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `&2 zpow (--(--a - &1)) = &2 zpow (a + &1)` SUBST1_TAC THENL
     [AP_TERM_TAC THEN INT_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`a:int`; `p:int`; `x:real`; `x':real`] DYHO_PAIR_DIST) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[]]);;

let FTILDE_MAX_L2_C = prove
 (`?C3. &0 <= C3 /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau. FINITE P
      ==> (\x. hl_maximal
                (\x. norm(vsum {s | s IN P /\ tile_ler s tau}
                          (\s. c s * phi_sigma s carleson_phi x))) x pow 2)
          real_integrable_on (:real) /\
          real_integral (:real)
            (\x. hl_maximal
                  (\x. norm(vsum {s | s IN P /\ tile_ler s tau}
                            (\s. c s * phi_sigma s carleson_phi x))) x pow 2)
          <= &8 * C3 * sum {s | s IN P /\ tile_ler s tau} (\s. norm(c s) pow
            2)`,
  X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC FTILDE_L2_NORM_C THEN
  EXISTS_TAC `C3:real` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC
   `G = \x. vsum {s | s IN P /\ tile_ler s tau}
                 (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi
                   x)` THEN
  SUBGOAL_THEN `schwartz (G:real->complex)` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x. abs(norm((G:real->complex) x))) real_integrable_on (:real) /\
    (\x. norm((G:real->complex) x) pow 2) real_integrable_on (:real) /\
    (?M. !x. abs(norm((G:real->complex) x)) <= M)`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[REAL_ABS_NORM; REAL_INTEGRABLE_ON; o_DEF; IMAGE_LIFT_UNIV;
       LIFT_DROP] THEN
      MP_TAC(MATCH_MP SCHWARTZ_ABSINT (ASSUME `schwartz (G:real->complex)`))
        THEN
      REWRITE_TAC[absolutely_integrable_on] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[o_DEF]) THEN REWRITE_TAC[NORM_LIFT];
      REWRITE_TAC[REAL_INTEGRABLE_ON; o_DEF; IMAGE_LIFT_UNIV; LIFT_DROP] THEN
      REWRITE_TAC[MATCH_MP SCHWARTZ_NORMSQ_INTEGRABLE (ASSUME `schwartz
        (G:real->complex)`)];
      REWRITE_TAC[REAL_ABS_NORM] THEN
      MATCH_MP_TAC SCHWARTZ_BOUNDED THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPEC `\x. norm((G:real->complex) x)` HARDY_LITTLEWOOD_MAXIMAL_L2)
    THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `M:real` THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x. norm(vsum {s | s IN P /\ tile_ler s tau}
              (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi x)))
                =
    (\x. norm((G:real->complex) x))`
   ASSUME_TAC THENL [EXPAND_TAC "G" THEN REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&8 * real_integral (:real) (\x. norm((G:real->complex) x) pow 2)`
    THEN
  CONJ_TAC THENL
   [FIRST_ASSUM(fun th -> ACCEPT_TAC(BETA_RULE th));
    REWRITE_TAC[REAL_ARITH `&8 * C3 * a = &8 * (C3 * a)`] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
      [REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `real_integral (:real) (\x. norm((G:real->complex) x) pow 2) =
      drop(integral (:real^1) (\z. lift(norm(G(drop z)) pow 2)))`
     SUBST1_TAC THENL
     [ASM_SIMP_TAC[REAL_INTEGRAL; o_DEF; IMAGE_LIFT_UNIV; LIFT_DROP];
       ALL_TAC] THEN
    EXPAND_TAC "G" THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let SCHWARTZ_HLMAX_INTEGRABLE = prove
 (`!(G:real->complex) A. schwartz G /\ real_measurable A
     ==> hl_maximal (\x. norm(G x)) real_integrable_on A`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `M:real` o MATCH_MP SCHWARTZ_BOUNDED) THEN
  SUBGOAL_THEN
    `(\t. abs(norm((G:real->complex) t))) real_integrable_on (:real)`
    ASSUME_TAC THENL
   [REWRITE_TAC[REAL_ABS_NORM; REAL_INTEGRABLE_ON; o_DEF; IMAGE_LIFT_UNIV;
     LIFT_DROP] THEN
    MP_TAC(MATCH_MP SCHWARTZ_ABSINT (ASSUME `schwartz (G:real->complex)`)) THEN
    REWRITE_TAC[absolutely_integrable_on] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[o_DEF]) THEN
      REWRITE_TAC[NORM_LIFT]; ALL_TAC] THEN
  SUBGOAL_THEN
    `hl_maximal (\x. norm((G:real->complex) x)) real_measurable_on A`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC HL_MAXIMAL_MEASURABLE THEN EXISTS_TAC `M:real` THEN
    BETA_TAC THEN CONJ_TAC THENL
      [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[REAL_ABS_NORM]]; ALL_TAC] THEN
  SUBGOAL_THEN `(\x. M) real_integrable_on A` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_ON_CONST_MEASURABLE THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!x. abs(hl_maximal (\x. norm((G:real->complex) x)) x) <= (\x. M) x`
    ASSUME_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`\x. norm((G:real->complex) x)`; `M:real`;
      `x:real`] HL_MAXIMAL_POS) THEN
    ANTS_TAC THENL [BETA_TAC THEN ASM_REWRITE_TAC[REAL_ABS_NORM]; ALL_TAC] THEN
    MP_TAC(ISPECL [`\x. norm((G:real->complex) x)`;
      `M:real`] HL_MAXIMAL_BOUNDED) THEN
    ANTS_TAC THENL [BETA_TAC THEN ASM_REWRITE_TAC[REAL_ABS_NORM]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real`) THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\x. M):real->real` THEN ASM_REWRITE_TAC[]);;

(* alpha3 (i) CELL CAP (constant): for x in the cover cell dyho a p, the W3  *)
(* slice sum                                                                 *)
(* is <= (2Cgm / mu(dyho a p)) int_{dyho a p} g~* -- a CONSTANT in x (no     *)
(* x-dependence).                                                            *)
(* = AVG_OVER_CELL averaging V3_CELL_PTWISE over x' in the cell; g~*         *)
(* integrable there                                                          *)
(* (SCHWARTZ_HLMAX_INTEGRABLE o FTILDE_SCHWARTZ_C), mu > 0 (DYHO_MEASURE).   *)
(* The constant                                                              *)
(* value is exactly the Kfun needed by the (j) integral layer                *)
(* ALPHA3_CELL_CORE.                                                         *)
let V3_CELL_CAP = prove
 (`?Cgm. &0 <= Cgm /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau a p x h.
      FINITE P /\ tile_k tau < --a /\ x IN dyho a p
      ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --a /\
        (h:real->real) x IN tile_Jr s}
                    (\s. c s * phi_sigma s carleson_phi x))
          <= ((&2 * Cgm) / real_measure(dyho a p)) *
             real_integral (dyho a p)
               (\z. hl_maximal (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                                          (\s. c s * phi_sigma s carleson_phi
                                            w))) z)`,
  X_CHOOSE_THEN
    `Cgm:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "PT"))
     V3_CELL_PTWISE THEN
  EXISTS_TAC `Cgm:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MATCH_MP_TAC AVG_OVER_CELL THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[DYHO_MEASURE] THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
     REAL_ARITH_TAC;
    REWRITE_TAC[DYHO_MEASURABLE];
    ONCE_REWRITE_TAC[ETA_AX] THEN
    MATCH_MP_TAC SCHWARTZ_HLMAX_INTEGRABLE THEN
      REWRITE_TAC[DYHO_MEASURABLE] THEN
    MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `x':real` THEN DISCH_TAC THEN BETA_TAC THEN
    ONCE_REWRITE_TAC[REAL_MUL_ASSOC] THEN
    USE_THEN "PT" (MP_TAC o REWRITE_RULE[REAL_MUL_ASSOC] o SPECL
     [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
      `a:int`; `p:int`; `x:real`; `x':real`]) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* Three set-equalities for V3_CAP_REGION's region-slice reduction (proven   *)
(* by pure                                                                   *)
(* ASM_REWRITE + TAUT -- MESON runs away "Too deep" on these set-builders).  *)
(* h is the                                                                  *)
(* FREE global (matching V3_CELL_CAP); do NOT bind it (a bound var gets      *)
(* primed by STRIP).                                                         *)
let V3CAP_SET1 = prove
 (`!P tau a p x E h. x IN dyho a p ==>
   {s | s IN {s | s IN P /\ tile_ler s tau /\ tile_k s < --a} /\
        x IN {y | y IN E /\ h y IN tile_Jr s} INTER dyho a p} =
   {s | s IN P /\ tile_ler s tau /\ tile_k s < --a /\ x IN E /\ h x IN tile_Jr
     s}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_INTER] THEN
  X_GEN_TAC `s:int#int#int` THEN ASM_REWRITE_TAC[] THEN CONV_TAC TAUT);;

let V3CAP_SET2 = prove
 (`!P tau a x E. x IN E ==>
   {s | s IN P /\ tile_ler s tau /\ tile_k s < --a /\ x IN E /\ h x IN tile_Jr
     s} =
   {s | s IN P /\ tile_ler s tau /\ tile_k s < --a /\ h x IN tile_Jr s}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN
    ASM_REWRITE_TAC[]);;

let V3CAP_SET3 = prove
 (`!P tau a x E. ~(x IN E) ==>
   {s:int#int#int | s IN P /\ tile_ler s tau /\ tile_k s < --a /\ x IN E /\ h x
     IN tile_Jr s} = {}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
  GEN_TAC THEN ASM_REWRITE_TAC[]);;

(* alpha3 (j) REGION-slice cap: the if-region form of V3_CELL_CAP. For x in  *)
(* the cover                                                                 *)
(* cell dyho a p, norm(vsum{W3-tiles}(if x IN region_s                       *)
(* [E-cap-hinv-Jr-cap-cell] then                                             *)
(* c_s phi_s x else 0)) <= (2Cgm/muK) int_K g~* (the CONSTANT cap).          *)
(* VSUM_RESTRICT_SET                                                         *)
(* (after GSYM COMPLEX_VEC_0 so else = vec 0) flattens the if-vsum to the    *)
(* slice; V3CAP_                                                             *)
(* SET1 reduces the region membership (x in dyho a p); ASM_CASES x IN E: x   *)
(* IN E -> V3CAP_                                                            *)
(* SET2 + V3_CELL_CAP, else -> V3CAP_SET3 empty + positivity from            *)
(* V3_CELL_CAP's norm>=0.                                                    *)
(* This is exactly the pointwise cap ALPHA3_CELL_CORE consumes.              *)
let V3_CAP_REGION = prove
 (`?Cgm. &0 <= Cgm /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau E h a p x.
      FINITE P /\ tile_k tau < --a /\ x IN dyho a p
      ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --a}
                    (\s. if x IN {y | y IN E /\ h y IN tile_Jr s} INTER dyho a
                      p
                         then c s * phi_sigma s carleson_phi x else Cx(&0)))
          <= ((&2 * Cgm) / real_measure(dyho a p)) *
             real_integral (dyho a p)
               (\z. hl_maximal (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                                          (\s. c s * phi_sigma s carleson_phi
                                            w))) z)`,
  X_CHOOSE_THEN
    `Cgm:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "CAP")) V3_CELL_CAP THEN
  EXISTS_TAC `Cgm:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  REWRITE_TAC[GSYM COMPLEX_VEC_0] THEN REWRITE_TAC[GSYM VSUM_RESTRICT_SET] THEN
  FIRST_ASSUM(SUBST1_TAC o MATCH_MP (SPEC_ALL V3CAP_SET1)) THEN
  ASM_CASES_TAC `x IN (E:real->bool)` THENL
   [FIRST_ASSUM(SUBST1_TAC o MATCH_MP (SPEC_ALL V3CAP_SET2)) THEN
    USE_THEN "CAP" (MP_TAC o SPECL
     [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
      `a:int`; `p:int`; `x:real`]) THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
    FIRST_ASSUM(SUBST1_TAC o MATCH_MP (SPEC_ALL V3CAP_SET3)) THEN
    REWRITE_TAC[VSUM_CLAUSES; NORM_0] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --a /\ h
      x IN tile_Jr s}
                          (\s. (c:(int#int#int)->complex) s * phi_sigma s
                            carleson_phi x))` THEN
    REWRITE_TAC[NORM_POS_LE] THEN
    USE_THEN "CAP" (MP_TAC o SPECL
     [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
      `a:int`; `p:int`; `x:real`]) THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]]);;

let SCHWARTZ_HLMAX_SQ_INTEGRABLE = prove
 (`!(G:real->complex) A. schwartz G /\ real_measurable A
     ==> (\x. hl_maximal (\x. norm(G x)) x pow 2) real_integrable_on A`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `M:real` o MATCH_MP SCHWARTZ_BOUNDED) THEN
  SUBGOAL_THEN
    `(\t. abs(norm((G:real->complex) t))) real_integrable_on (:real)`
    ASSUME_TAC THENL
   [REWRITE_TAC[REAL_ABS_NORM; REAL_INTEGRABLE_ON; o_DEF; IMAGE_LIFT_UNIV;
     LIFT_DROP] THEN
    MP_TAC(MATCH_MP SCHWARTZ_ABSINT (ASSUME `schwartz (G:real->complex)`)) THEN
    REWRITE_TAC[absolutely_integrable_on] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[o_DEF]) THEN
      REWRITE_TAC[NORM_LIFT]; ALL_TAC] THEN
  SUBGOAL_THEN
    `hl_maximal (\x. norm((G:real->complex) x)) real_measurable_on A`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC HL_MAXIMAL_MEASURABLE THEN EXISTS_TAC `M:real` THEN
    BETA_TAC THEN CONJ_TAC THENL
      [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[REAL_ABS_NORM]]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\x. M pow 2):real->real` THEN REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
   [ONCE_REWRITE_TAC[REAL_POW_2] THEN MATCH_MP_TAC REAL_MEASURABLE_ON_MUL THEN
    ASM_REWRITE_TAC[ETA_AX];
    MATCH_MP_TAC REAL_INTEGRABLE_ON_CONST_MEASURABLE THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `abs(hl_maximal (\x. norm((G:real->complex) x)) x pow 2) =
                  hl_maximal (\x. norm(G x)) x pow 2`
      SUBST1_TAC THENL
        [REWRITE_TAC[REAL_ABS_REFL; REAL_LE_POW_2]; ALL_TAC] THEN
    MP_TAC(ISPECL [`\x. norm((G:real->complex) x)`; `M:real`;
      `x:real`] HL_MAXIMAL_POS) THEN
    ANTS_TAC THENL [BETA_TAC THEN ASM_REWRITE_TAC[REAL_ABS_NORM]; ALL_TAC] THEN
    MP_TAC(ISPECL [`\x. norm((G:real->complex) x)`;
      `M:real`] HL_MAXIMAL_BOUNDED) THEN
    ANTS_TAC THENL [BETA_TAC THEN ASM_REWRITE_TAC[REAL_ABS_NORM]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real`) THEN BETA_TAC THEN DISCH_TAC THEN
      DISCH_TAC THEN
    MP_TAC(ISPECL [`2`; `hl_maximal (\x. norm((G:real->complex) x)) x`;
      `M:real`] REAL_POW_LE2) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;
let FTILDE_MAX_INT_CS_C = prove
 (`!(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau A. FINITE P /\
   real_measurable A
     ==> real_integral A (hl_maximal (\x. norm(vsum {s | s IN P /\ tile_ler s
       tau}
                                                    (\s. c s * phi_sigma s
                                                      carleson_phi x))))
         <= sqrt(real_measure A) *
            sqrt(real_integral A (\x. hl_maximal (\x. norm(vsum {s | s IN P /\
              tile_ler s tau}
                                                    (\s. c s * phi_sigma s
                                                      carleson_phi x))) x pow
                                                       2))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `G = \x. vsum {s | s IN P /\ tile_ler s tau}
                          (\s. (c:(int#int#int)->complex) s * phi_sigma s
                            carleson_phi x)` THEN
  SUBGOAL_THEN `schwartz (G:real->complex)` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x. norm(vsum {s | s IN P /\ tile_ler s tau}
              (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi x)))
                =
    (\x. norm((G:real->complex) x))`
   ASSUME_TAC THENL [EXPAND_TAC "G" THEN REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`hl_maximal (\x. norm((G:real->complex) x))`;
    `A:real->bool`] REAL_INTEGRAL_CS_MEASURE) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC SCHWARTZ_HLMAX_INTEGRABLE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC SCHWARTZ_HLMAX_SQ_INTEGRABLE THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN
      FIRST_ASSUM(X_CHOOSE_TAC `M:real` o MATCH_MP SCHWARTZ_BOUNDED) THEN
    MATCH_MP_TAC HL_MAXIMAL_POS THEN EXISTS_TAC `M:real` THEN BETA_TAC THEN
      CONJ_TAC THENL
     [REWRITE_TAC[REAL_ABS_NORM; REAL_INTEGRABLE_ON; o_DEF; IMAGE_LIFT_UNIV;
       LIFT_DROP] THEN
      MP_TAC(MATCH_MP SCHWARTZ_ABSINT (ASSUME `schwartz (G:real->complex)`))
        THEN
      REWRITE_TAC[absolutely_integrable_on] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[o_DEF]) THEN REWRITE_TAC[NORM_LIFT];
      ASM_REWRITE_TAC[REAL_ABS_NORM]]]);;

(* ------------------------------------------------------------------------- *)
(* alpha3 (j) capstone: for the tree reconstruction gt = sum_{tree} c_s      *)
(* phi_s                                                                     *)
(* and any measurable A, int_A gt-star <= sqrt(mu A) sqrt(8 C B) whenever    *)
(* sum|c_s|^2 <= B.  FTILDE_MAX_L2_B first bounds int_R (gt-star)^2 <= 8 C B *)
(* (FTILDE_MAX_L2_C + monotonicity); ALPHA3_MAXIMAL_BOUND then chains the    *)
(* continuous Cauchy step (FTILDE_MAX_INT_CS_C) with int_A (gt-star)^2 <=    *)
(* int_R (gt-star)^2 (REAL_INTEGRAL_SUBSET_LE) and monotone sqrt. With A =   *)
(* Ihat,                                                                     *)
(* mu A = 7 2^{-k_tau}, B = energy^2 2^{-k_tau} (FTILDE_ENERGY_SUM at c=zeta *)
(* ip),                                                                      *)
(* this is Fremlin's int_Ihat gt-star <= sqrt(7 muI_tau) sqrt(8 C3) energy   *)
(* 2^{-k_tau/2}, the analytic heart of the alpha3 (j) bound.                 *)
(* ------------------------------------------------------------------------- *)

let FTILDE_MAX_L2_B = prove
 (`?C. &0 <= C /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau B. FINITE P /\
      sum {s | s IN P /\ tile_ler s tau} (\s. norm(c s) pow 2) <= B
      ==> real_integral (:real)
            (\x. hl_maximal (\x. norm(vsum {s | s IN P /\ tile_ler s tau}
                                          (\s. c s * phi_sigma s carleson_phi
                                            x))) x pow 2)
          <= &8 * C * B`,
  X_CHOOSE_THEN
    `C3:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "MAX"))
     FTILDE_MAX_L2_C THEN
  EXISTS_TAC `C3:real` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&8 * C3 * sum {s | s IN P /\ tile_ler s tau} (\s.
    norm((c:(int#int#int)->complex) s) pow 2)` THEN
  CONJ_TAC THENL
   [USE_THEN "MAX" (MP_TAC o SPECL
      [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`;
        `tau:int#int#int`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[]]]);;

let ALPHA3_MAXIMAL_BOUND = prove
 (`?C. &0 <= C /\
    !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau A B.
      FINITE P /\ real_measurable A /\
      sum {s | s IN P /\ tile_ler s tau} (\s. norm(c s) pow 2) <= B
      ==> real_integral A (hl_maximal (\x. norm(vsum {s | s IN P /\ tile_ler s
        tau}
                                                    (\s. c s * phi_sigma s
                                                      carleson_phi x))))
          <= sqrt(real_measure A) * sqrt(&8 * C * B)`,
  X_CHOOSE_THEN
    `C3:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "B")) FTILDE_MAX_L2_B THEN
  X_CHOOSE_THEN
    `C4:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "MAX"))
     FTILDE_MAX_L2_C THEN
  EXISTS_TAC `C3:real` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sqrt(real_measure A) *
    sqrt(real_integral A
       (\x. hl_maximal
         (\x. norm(vsum {s | s IN P /\ tile_ler s tau}
                         (\s. (c:(int#int#int)->complex) s *
                              phi_sigma s carleson_phi x))) x pow 2))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC FTILDE_MAX_INT_CS_C THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_MEASURE_POS_LE THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC SQRT_MONO_LE THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `real_integral (:real)
       (\x. hl_maximal
         (\x. norm(vsum {s | s IN P /\ tile_ler s tau}
                         (\s. (c:(int#int#int)->complex) s *
                              phi_sigma s carleson_phi x))) x pow 2)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN REWRITE_TAC[SUBSET_UNIV] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_HLMAX_SQ_INTEGRABLE THEN REWRITE_TAC[ETA_AX] THEN
      CONJ_TAC THENL [MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN
        ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "MAX" (MP_TAC o SPECL
        [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`;
          `tau:int#int#int`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_LE_POW_2]];
    USE_THEN "B" (MP_TAC o SPECL
      [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
        `B:real`]) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Tile-order J-monotonicity.  If sigma >=_r tau (tile_ler s tau) and sigma  *)
(* is the finer scale (k_tau <= k_s) then J_tau SUBSET J_s.  Proof: from     *)
(* J^r_tau SUBSET J^r_sigma (tile_ler) and J^r_tau nonempty                  *)
(* (TILE_JR_NONEMPTY)                                                        *)
(* pick y in J^r_tau; then y IN J_tau and y IN J_sigma (TILE_JR_SUBSET_J),   *)
(* so                                                                        *)
(* J_tau, J_sigma meet, and with k_tau <= k_s the laminar nesting DYHO_MEET_ *)
(* NEST forces J_tau SUBSET J_sigma. This is the containment the alpha3 cell *)
(* (ALPHA3_CELL) feeds to TILE_JR_SUBSET_TILE_J.                             *)
(* ------------------------------------------------------------------------- *)
let TILE_LER_J_SUBSET = prove
 (`!(s:int#int#int) tau.
     tile_ler s tau /\ tile_k tau <= tile_k s
     ==> tile_J tau SUBSET tile_J s`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
   [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_ler; tile_J; tile_Jr; tile_k] THEN STRIP_TAC THEN
  MATCH_MP_TAC DYHO_MEET_NEST THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPEC `(kt:int,nIt:int,nJt:int)` TILE_JR_NONEMPTY) THEN
  REWRITE_TAC[tile_Jr; GSYM MEMBER_NOT_EMPTY] THEN
  DISCH_THEN(X_CHOOSE_TAC `y:real`) THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY;
              NOT_FORALL_THM; NOT_IMP] THEN
  EXISTS_TAC `y:real` THEN CONJ_TAC THENL
   [MP_TAC(ISPEC `(kt:int,nIt:int,nJt:int)` TILE_JR_SUBSET_J) THEN
    REWRITE_TAC[tile_Jr; tile_J; SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPEC `(ks:int,nIs:int,nJs:int)` TILE_JR_SUBSET_J) THEN
    REWRITE_TAC[tile_Jr; tile_J; SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    UNDISCH_TAC `dyho (kt - &1) (&2 * nJt + &1) SUBSET
                 dyho (ks - &1) (&2 * nJs + &1)` THEN
    REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286L alpha3 CELL: the concrete per-cell W3 bound. For a single cover cell *)
(* dyho a p (level l_K = -a, coarser than tau: k_tau < -a) with the          *)
(* auxiliary                                                                 *)
(* tile ups at scale k_ups = -(a+1), the norm of the vector sum of the tile  *)
(* integrals over the right-half cells is <= the constant cell cap (from     *)
(* V3_CAP_REGION) times mu(G_K).  This is ALPHA3_CELL_CORE instantiated with *)
(* ff_s = \x. c_s phi_sigma_s, region_s = {x IN E | h x IN J^r_s} INTER      *)
(* dyho,                                                                     *)
(* G = {x IN E | h x IN J_ups} INTER dyho, and Kfun = the V3_CELL_CAP        *)
(* constant.                                                                 *)
(* The four ANTS: FINITE (FINITE_RESTRICT); per-tile region SUBSET G_K       *)
(* (TILE_JR_SUBSET_TILE_J via TILE_LER_J_SUBSET + tile_le ups ->             *)
(* J_tau<=J_ups)                                                             *)
(* + region-integ (INTEGRABLE_COMPLEX_LMUL o                                 *)
(* PHISIG_ABS_INTEGRABLE_MEASURABLE);                                        *)
(* Kfun real_integrable (CONST_INTEGRABLE_MEASURABLE); pointwise cap         *)
(* (V3_CAP_REGION).  Unlike alpha2's sum-of-norms, the sum stays INSIDE the  *)
(* norm -- the cancellation-preserving form the maximal bound needs.         *)
(* ------------------------------------------------------------------------- *)
let ALPHA3_CELL = prove
 (`?Cgm. &0 <= Cgm /\
   !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau E h a p ups.
      FINITE P /\ (!s. s IN P ==> tile_le s tau) /\ tile_k tau < --a /\
      tile_le ups tau /\ tile_k ups = --(a + &1) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real)
      ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --a}
                    (\s. c s * integral (IMAGE lift
                        ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p))
                        (\z. phi_sigma s carleson_phi (drop z)))) <=
          (((&2 * Cgm) / real_measure(dyho a p)) *
           real_integral (dyho a p)(\z. hl_maximal
              (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                             (\s. c s * phi_sigma s carleson_phi w))) z)) *
          real_measure ({x | x IN E /\ h x IN tile_J ups} INTER dyho a p)`,
  X_CHOOSE_THEN `Cgm:real` (LABEL_TAC "CR") V3_CAP_REGION THEN
  EXISTS_TAC `Cgm:real` THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `real_measurable ({x | x IN E /\ h x IN tile_J ups} INTER dyho a p)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC SC_MEASURABLE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `real_integral ({x | x IN E /\ h x IN tile_J ups} INTER dyho a p)
      (\x. (&2 * Cgm) / real_measure (dyho a p) *
           real_integral (dyho a p)
             (\z. hl_maximal
                    (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                                   (\s. c s * phi_sigma s carleson_phi w)))
                                     z))` THEN
  CONJ_TAC THENL
   [ALL_TAC;
    ASM_SIMP_TAC[CONST_INTEGRABLE_MEASURABLE; REAL_LE_REFL]] THEN
  SUBGOAL_THEN
   `!s:int#int#int. (\z. phi_sigma s carleson_phi (drop z)) integrable_on
        IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p)`
   (LABEL_TAC "INTG") THENL
   [GEN_TAC THEN MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC PHISIG_ABS_INTEGRABLE_MEASURABLE THEN
    MATCH_MP_TAC SC_MEASURABLE_JR THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM INTEGRAL_COMPLEX_LMUL] THEN
  MP_TAC(ISPECL
   [`{s | s IN P /\ tile_ler s tau /\ tile_k s < --a}`;
    `\(s:int#int#int) (x:real). c s * phi_sigma s carleson_phi x`;
    `\s:int#int#int. {x | x IN E /\ h x IN tile_Jr s} INTER dyho a p`;
    `{x | x IN E /\ h x IN tile_J ups} INTER dyho a p`;
    `\x:real. (&2 * Cgm) / real_measure (dyho a p) *
       real_integral (dyho a p)
         (\z. hl_maximal
                (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                               (\s. c s * phi_sigma s carleson_phi w))) z)`]
   ALPHA3_CELL_CORE) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_RESTRICT THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `s:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(SET_RULE
       `(!x. x IN A ==> x IN B) ==> (A INTER C) SUBSET (B INTER C)`) THEN
      X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`s:int#int#int`; `ups:int#int#int`; `tau:int#int#int`]
                    TILE_JR_SUBSET_TILE_J) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC TILE_LER_J_SUBSET THEN ASM_REWRITE_TAC[] THEN
          MATCH_MP_TAC TILE_LER_SCALE THEN ASM_REWRITE_TAC[];
          UNDISCH_TAC `tile_le ups tau` THEN REWRITE_TAC[tile_le] THEN
            SIMP_TAC[];
          ASM_INT_ARITH_TAC];
        REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[]];
      MP_TAC(SPEC `s:int#int#int` (ASSUME
        `!s. (\z. phi_sigma s carleson_phi (drop z)) integrable_on
             IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p)`))
               THEN
      DISCH_THEN(MP_TAC o SPEC `(c:(int#int#int)->complex) s` o
                 MATCH_MP INTEGRABLE_COMPLEX_LMUL) THEN
      REWRITE_TAC[]];
    ASM_SIMP_TAC[CONST_INTEGRABLE_MEASURABLE];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    USE_THEN "CR" (MP_TAC o SPECL
     [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
      `E:real->bool`; `h:real->real`; `a:int`; `p:int`;
        `x:real`] o CONJUNCT2) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `x IN {x | x IN E /\ h x IN tile_J ups} INTER dyho a p` THEN
      REWRITE_TAC[IN_INTER] THEN SIMP_TAC[];
      REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* The alpha3 cell mass-fold arithmetic (abstract).  With gk (= mu G_K) <=   *)
(* 2 t m / w (the GK_MEASURE_BOUND_STRONG bound, t = mu K = 2^a, m = mass, w *)
(* =                                                                         *)
(* w(3/2)) the per-cell factor (2 Cgm / t) mu G_K collapses to 4 Cgm m / w   *)
(* --                                                                        *)
(* the 2^a cancels 1/mu K -- giving a CELL-INDEPENDENT constant.             *)
(* ------------------------------------------------------------------------- *)
let GTM_CELL_ARITH = prove
 (`!Cgm Iv gk t m w.
     &0 <= Cgm /\ &0 <= Iv /\ &0 <= m /\ &0 < t /\ &0 < w /\
     gk <= &2 * t * m / w
     ==> ((&2 * Cgm) / t * Iv) * gk <= ((&4 * Cgm) * m / w) * Iv`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `((&2 * Cgm) / t * Iv) * (&2 * t * m / w)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_DIV THEN
    ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    SUBGOAL_THEN `~(t = &0) /\ ~(w = &0)` STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN
    ONCE_REWRITE_TAC[REAL_ARITH
     `(((&2 * Cgm) / t * Iv) * &2 * t * m / w):real =
      (&2 * Cgm) * (t * inv t) * (&2 * Iv * m / w)`] THEN
    ASM_SIMP_TAC[REAL_MUL_RINV; REAL_MUL_RID] THEN REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* 286L alpha3 CELL, mass form.  Folds GK_MEASURE_BOUND_STRONG (mu G_K <=    *)
(* 2 * 2^a * mass / w(3/2)) into ALPHA3_CELL: the 2^a in the G_K measure     *)
(* bound                                                                     *)
(* cancels the 1/mu K = 1/2^a in the cell cap, leaving the CELL-INDEPENDENT  *)
(* constant 4 Cgm mass / w(3/2) times int_K g~* (g~* the H-L maximal fn of   *)
(* the                                                                       *)
(* tree reconstruction gt = sum_{tree} c_s phi_s). This is the               *)
(* per-cover-cell                                                            *)
(* summand ALPHA3_TOTAL adds over the maximal cover.  Requires ~(P={}) (for  *)
(* MASS_EH_POS) and in_kcover P a p (for mu K = 2^a via KCOVER_MEASURE).     *)
(* ------------------------------------------------------------------------- *)
let ALPHA3_CELL_MASS = prove
 (`?Cgm. &0 <= Cgm /\
   !(c:(int#int#int)->complex) (P:(int#int#int)->bool) tau E h a p.
      FINITE P /\ ~(P = {}) /\ in_kcover P a p /\ (!s. s IN P ==> tile_le s
        tau) /\
      tile_k tau < --a /\ real_lebesgue_measurable E /\
      h real_measurable_on (:real) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --a}
                    (\s. c s * integral (IMAGE lift
                        ({x | x IN E /\ h x IN tile_Jr s} INTER dyho a p))
                        (\z. phi_sigma s carleson_phi (drop z)))) <=
          ((&4 * Cgm) * mass_Eh E h P / cw(&3 / &2)) *
           real_integral (dyho a p)(\z. hl_maximal
              (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                             (\s. c s * phi_sigma s carleson_phi w))) z)`,
  X_CHOOSE_THEN `Cgm:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "CELL"))
    ALPHA3_CELL THEN
  EXISTS_TAC `Cgm:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  ABBREV_TAC
   `G = \x. vsum {s | s IN P /\ tile_ler s tau}
                 (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi
                   x)` THEN
  SUBGOAL_THEN `schwartz (G:real->complex)` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow (a + &1) <= &2 zpow (--(tile_k tau))` ASSUME_TAC THENL
   [MATCH_MP_TAC ZPOW2_MONOE THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`; `E:real->bool`; `h:real->real`;
                 `a:int`; `p:int`;
                   `tau:int#int#int`] GK_MEASURE_BOUND_STRONG) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ups:int#int#int` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `real_integral (dyho a p)(\z. hl_maximal
       (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                      (\s. (c:(int#int#int)->complex) s * phi_sigma s
                        carleson_phi w))) z) =
    real_integral (dyho a p)(\z. hl_maximal (\w. norm((G:real->complex) w)) z)`
   SUBST1_TAC THENL
   [AP_TERM_TAC THEN ABS_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN ABS_TAC THEN
    AP_TERM_TAC THEN EXPAND_TAC "G" THEN REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `(((&2 * Cgm) / real_measure(dyho a p)) *
     real_integral (dyho a p)(\z. hl_maximal (\w. norm((G:real->complex) w))
       z)) *
    real_measure ({x | x IN E /\ h x IN tile_J ups} INTER dyho a p)` THEN
  CONJ_TAC THENL
   [USE_THEN "CELL" (MP_TAC o SPECL
     [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
      `E:real->bool`; `h:real->real`; `a:int`; `p:int`;
        `ups:int#int#int`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXPAND_TAC "G" THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= mass_Eh E h (P:(int#int#int)->bool)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`E:real->bool`;`h:real->real`;`P:(int#int#int)->bool`]
      MASS_EH_POS) THEN
    ANTS_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 zpow a` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `real_measure (dyho a p) = &2 zpow a` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`P:(int#int#int)->bool`;`a:int`;`p:int`] KCOVER_MEASURE)
     THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `M:real` o MATCH_MP SCHWARTZ_BOUNDED) THEN
  SUBGOAL_THEN
    `(\x. abs(norm((G:real->complex) x))) real_integrable_on (:real)`
   ASSUME_TAC THENL
   [REWRITE_TAC[REAL_ABS_NORM; REAL_INTEGRABLE_ON; o_DEF; IMAGE_LIFT_UNIV;
     LIFT_DROP] THEN
    MP_TAC(MATCH_MP SCHWARTZ_ABSINT (ASSUME `schwartz (G:real->complex)`)) THEN
    REWRITE_TAC[absolutely_integrable_on] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[o_DEF]) THEN REWRITE_TAC[NORM_LIFT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= real_integral (dyho a p)(\z. hl_maximal (\w. norm((G:real->complex)
     w)) z)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_POS THEN CONJ_TAC THENL
     [ONCE_REWRITE_TAC[ETA_AX] THEN
      MATCH_MP_TAC SCHWARTZ_HLMAX_INTEGRABLE THEN
        ASM_REWRITE_TAC[DYHO_MEASURABLE];
      X_GEN_TAC `z:real` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
      MATCH_MP_TAC HL_MAXIMAL_POS THEN EXISTS_TAC `M:real` THEN
      CONJ_TAC THENL
       [MP_TAC(ASSUME `(\x. abs(norm((G:real->complex) x))) real_integrable_on
         (:real)`) THEN
        REWRITE_TAC[REAL_ABS_NORM];
        ASM_REWRITE_TAC[REAL_ABS_NORM]]];
    ALL_TAC] THEN
  MATCH_MP_TAC GTM_CELL_ARITH THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `&3 / &2` CW_POS) THEN REAL_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* 286L alpha3 COVER SUM. Sums ALPHA3_CELL_MASS over the maximal cover cells *)
(* ap IN S (each with l_K = -FST ap > k_tau, i.e. 2^{FST ap+1} <=            *)
(* 2^{-k_tau}):                                                              *)
(*   sum_{ap} norm(vsum {W3-slice tiles at ap}(c_s int_{region} phi_s))      *)
(*     <= (4 C1 mass/w(3/2)) * int_Ihat_tau g~*,                             *)
(* g~* = H-L maximal of gt = sum_{tree} c_s phi_s, Ihat_tau = [x_tau +- 7    *)
(* 2^{-k_tau}].  Route: SUM_LE bounds each cell by ALPHA3_CELL_MASS (c :=    *)
(* carleson_ip f; the k_tau < -FST ap gate from 2^{FST ap+1}<=2^{-k_tau} via *)
(* ZPOW2_LE_REV); SUM_LMUL pulls the cell-independent 4 C1 mass/w out;       *)
(* SUM_COVER_INTEGRAL_LE (G c = dyho(FST c)(SND c)) bounds sum int_K g~* <=  *)
(* int_Ihat g~* -- its 6 hyps: FINITE S, dyho-injectivity                    *)
(* (DYHO_INJ+PAIR_EQ),                                                       *)
(* per-cell g~*-integrable (SCHWARTZ_HLMAX_INTEGRABLE) + dyho SUBSET Ihat    *)
(* (KCOVER_SUBSET_IHAT), pairwise dyho INTER dyho = {} (KCOVER_DISJOINT +    *)
(* REAL_NEGLIGIBLE_EMPTY), g~* integrable on Ihat (real_interval), g~* >= 0  *)
(* (HL_MAXIMAL_POS).  This is the alpha3 (j) cover assembly; ALPHA3_MAXIMAL_ *)
(* BOUND then bounds int_Ihat g~* by sqrt(mu Ihat) sqrt(8 C3 energy^2        *)
(* 2^{-ktau}).                                                               *)
(* ------------------------------------------------------------------------- *)
let ALPHA3_COVER_SUM_C = prove
 (`?C1. &0 <= C1 /\
   !(c:(int#int#int)->complex) E h (P:(int#int#int)->bool) S kt nt tau.
      FINITE P /\ ~(P = {}) /\ tile_k tau = kt /\
      (!s. s IN P ==> tile_le s tau) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      FINITE S /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap) /\
                        &2 zpow (FST ap + &1) <= &2 zpow (--kt))
      ==> sum S (\ap. norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <
        --(FST ap)}
                          (\s. c s *
                               integral (IMAGE lift ({x | x IN E /\ h x IN
                                 tile_Jr s} INTER
                                         dyho (FST ap) (SND ap)))
                                        (\z. phi_sigma s carleson_phi (drop
                                          z)))))
          <= ((&4 * C1) * mass_Eh E h P / cw(&3 / &2)) *
             real_integral
               (real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                              dyho_mid (--kt) nt + &7 * &2 zpow (--kt)])
               (\z. hl_maximal (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                          (\s. c s * phi_sigma s carleson_phi w))) z)`,
  X_CHOOSE_THEN `Cgm:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "CM"))
    ALPHA3_CELL_MASS THEN
  EXISTS_TAC `Cgm:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  ABBREV_TAC
   `Gs = \w. vsum {s | s IN P /\ tile_ler s tau}
                  (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi
                    w)` THEN
  SUBGOAL_THEN `schwartz (Gs:real->complex)` ASSUME_TAC THENL
   [EXPAND_TAC "Gs" THEN MATCH_MP_TAC FTILDE_SCHWARTZ_C THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum S (\ap. ((&4 * Cgm) * mass_Eh E h P / cw(&3 / &2)) *
                real_integral (dyho (FST ap) (SND ap))
                  (\z. hl_maximal (\w. norm((Gs:real->complex) w)) z))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN `in_kcover P (FST(ap:int#int)) (SND ap) /\
                  &2 zpow (FST ap + &1) <= &2 zpow (--kt)` STRIP_ASSUME_TAC
                    THENL
     [FIRST_X_ASSUM(fun th -> if is_forall(concl th) &&
         can (find_term (fun tm -> tm = `in_kcover`)) (concl th) &&
         not(can (find_term (fun tm -> tm = `phi_sigma`)) (concl th))
         then MATCH_MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBST1_TAC(SYM(ASSUME
     `(\w. vsum {s | s IN P /\ tile_ler s tau}
                (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi
                  w)) = Gs`)) THEN
    CONV_TAC(DEPTH_CONV BETA_CONV) THEN
    USE_THEN "CM" (MP_TAC o SPECL
     [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
      `E:real->bool`; `h:real->real`; `FST(ap:int#int)`;
        `SND(ap:int#int)`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`FST(ap:int#int) + &1`; `--kt:int`] ZPOW2_LE_REV) THEN
      ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral
      (real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                     dyho_mid (--kt) nt + &7 * &2 zpow (--kt)])
      (\z. hl_maximal (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
             (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi w)))
               z) =
    real_integral
      (real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                     dyho_mid (--kt) nt + &7 * &2 zpow (--kt)])
      (\z. hl_maximal (\w. norm((Gs:real->complex) w)) z)`
   SUBST1_TAC THENL
   [AP_TERM_TAC THEN ABS_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN ABS_TAC THEN
    AP_TERM_TAC THEN EXPAND_TAC "Gs" THEN REWRITE_TAC[]; ALL_TAC] THEN
  ONCE_REWRITE_TAC[SUM_LMUL] THEN MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
      MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
       [MATCH_MP_TAC MASS_EH_POS THEN ASM_REWRITE_TAC[];
        MP_TAC(SPEC `&3 / &2` CW_POS) THEN REAL_ARITH_TAC]];
    ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `M:real` o MATCH_MP SCHWARTZ_BOUNDED) THEN
  SUBGOAL_THEN
    `(\x. abs(norm((Gs:real->complex) x))) real_integrable_on (:real)`
   ASSUME_TAC THENL
   [REWRITE_TAC[REAL_ABS_NORM; REAL_INTEGRABLE_ON; o_DEF; IMAGE_LIFT_UNIV;
     LIFT_DROP] THEN
    MP_TAC(MATCH_MP SCHWARTZ_ABSINT (ASSUME `schwartz (Gs:real->complex)`))
      THEN
    REWRITE_TAC[absolutely_integrable_on] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[o_DEF]) THEN REWRITE_TAC[NORM_LIFT];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\ap:int#int. dyho (FST ap) (SND ap)`; `S:(int#int)->bool`;
    `\z. hl_maximal (\w. norm((Gs:real->complex) w)) z`;
    `real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                   dyho_mid (--kt) nt + &7 * &2 zpow (--kt)]`]
   SUM_COVER_INTEGRAL_LE) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    REWRITE_TAC[FORALL_PAIR_THM] THEN
    MAP_EVERY X_GEN_TAC [`a1:int`;`p1:int`;`a2:int`;`p2:int`] THEN
    REWRITE_TAC[] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o MATCH_MP DYHO_INJ) THEN SIMP_TAC[PAIR_EQ];
    X_GEN_TAC `cc:int#int` THEN DISCH_TAC THEN CONJ_TAC THENL
     [ONCE_REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC SCHWARTZ_HLMAX_INTEGRABLE THEN
      ASM_REWRITE_TAC[DYHO_MEASURABLE];
      MATCH_MP_TAC KCOVER_SUBSET_IHAT THEN
      MAP_EVERY EXISTS_TAC [`P:(int#int#int)->bool`] THEN
        ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `cc:int#int` o
        check(fun th -> is_forall(concl th) &&
          can (find_term (fun tm -> tm = `in_kcover`)) (concl th) &&
          not(can (find_term (fun tm -> tm = `phi_sigma`)) (concl th)))) THEN
      ASM_SIMP_TAC[]];
    MAP_EVERY X_GEN_TAC [`cc:int#int`; `cc':int#int`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `dyho (FST(cc:int#int)) (SND cc) INTER dyho (FST(cc':int#int)) (SND cc') =
       {}`
     (fun th -> REWRITE_TAC[th; REAL_NEGLIGIBLE_EMPTY]) THEN
    REWRITE_TAC[GSYM DISJOINT] THEN MATCH_MP_TAC KCOVER_DISJOINT THEN
    EXISTS_TAC `P:(int#int#int)->bool` THEN REPEAT CONJ_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `cc:int#int`) THEN ASM_SIMP_TAC[];
      FIRST_X_ASSUM(MP_TAC o SPEC `cc':int#int`) THEN ASM_SIMP_TAC[];
      DISCH_TAC THEN FIRST_X_ASSUM(MP_TAC o MATCH_MP DYHO_INJ) THEN
      UNDISCH_TAC `~(cc:int#int = cc')` THEN
      MP_TAC(ISPEC `cc:int#int` PAIR_SURJECTIVE) THEN
      DISCH_THEN(X_CHOOSE_THEN `a1:int` (X_CHOOSE_THEN
        `p1:int` SUBST1_TAC)) THEN
      MP_TAC(ISPEC `cc':int#int` PAIR_SURJECTIVE) THEN
      DISCH_THEN(X_CHOOSE_THEN `a2:int` (X_CHOOSE_THEN
        `p2:int` SUBST1_TAC)) THEN
      REWRITE_TAC[PAIR_EQ] THEN INT_ARITH_TAC];
    ONCE_REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC SCHWARTZ_HLMAX_INTEGRABLE THEN
    ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
    X_GEN_TAC `z:real` THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC HL_MAXIMAL_POS THEN EXISTS_TAC `M:real` THEN
    CONJ_TAC THENL
     [MP_TAC(ASSUME `(\x. abs(norm((Gs:real->complex) x))) real_integrable_on
       (:real)`) THEN
      REWRITE_TAC[REAL_ABS_NORM];
      ASM_REWRITE_TAC[REAL_ABS_NORM]]]);;

(* ------------------------------------------------------------------------- *)
(* ALPHA3_TOTAL_C: zeta-general alpha3 total.  Same collapse as ALPHA3_TOTAL *)
(* but with arbitrary c whose norm matches carleson_ip f (phase-invariance), *)
(* so the energy input sum norm(c s)^2 = sum norm(ip s)^2 <= energy^2        *)
(* 2^{-kt}.                                                                  *)
(* This is the W3-block bound the k-assembly needs (W3 keeps the zeta        *)
(* phase).                                                                   *)
(* ------------------------------------------------------------------------- *)
let ALPHA3_TOTAL_C = prove
 (`?C1 C3. &0 <= C1 /\ &0 <= C3 /\
   !(c:(int#int#int)->complex) (f:real->complex) E h (P:(int#int#int)->bool) S
     kt nt tau.
      FINITE P /\ ~(P = {}) /\ tile_k tau = kt /\
      (!s. s IN P ==> tile_le s tau) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      (!s. norm(c s) = norm(carleson_ip f s)) /\
      FINITE S /\
      (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap) /\
                        &2 zpow (FST ap + &1) <= &2 zpow (--kt))
      ==> sum S (\ap. norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <
        --(FST ap)}
                          (\s. c s *
                               integral (IMAGE lift ({x | x IN E /\ h x IN
                                 tile_Jr s} INTER
                                         dyho (FST ap) (SND ap)))
                                        (\z. phi_sigma s carleson_phi (drop
                                          z)))))
          <= ((&4 * C1) * mass_Eh E h P / cw(&3 / &2)) *
             (sqrt(&112 * C3) * energy_f f P * &2 zpow (--kt))`,
  X_CHOOSE_THEN `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "CV"))
    ALPHA3_COVER_SUM_C THEN
  X_CHOOSE_THEN `C3:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "MX"))
    ALPHA3_MAXIMAL_BOUND THEN
  MAP_EVERY EXISTS_TAC [`C1:real`; `C3:real`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `((&4 * C1) * mass_Eh E h P / cw(&3 / &2)) *
    real_integral
      (real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                     dyho_mid (--kt) nt + &7 * &2 zpow (--kt)])
      (\z. hl_maximal (\w. norm(vsum {s | s IN P /\ tile_ler s tau}
                 (\s. (c:(int#int#int)->complex) s * phi_sigma s carleson_phi
                   w))) z)` THEN
  CONJ_TAC THENL
   [USE_THEN "CV" (MP_TAC o SPECL
     [`c:(int#int#int)->complex`; `E:real->bool`; `h:real->real`;
       `P:(int#int#int)->bool`; `S:(int#int)->bool`;
      `kt:int`; `nt:int`; `tau:int#int#int`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
      MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
       [MATCH_MP_TAC MASS_EH_POS THEN ASM_REWRITE_TAC[];
        MP_TAC(SPEC `&3 / &2` CW_POS) THEN REAL_ARITH_TAC]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sqrt(real_measure(real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                                    dyho_mid (--kt) nt + &7 * &2 zpow (--kt)]))
                                      *
    sqrt(&8 * C3 * ((energy_f (f:real->complex) P) pow 2 * &2 zpow (--kt)))`
      THEN
  CONJ_TAC THENL
   [ONCE_REWRITE_TAC[ETA_AX] THEN
    USE_THEN "MX" (MP_TAC o SPECL
     [`c:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
      `real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                     dyho_mid (--kt) nt + &7 * &2 zpow (--kt)]`;
      `(energy_f (f:real->complex) P) pow 2 * &2 zpow (--kt)`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL] THEN
      SUBST1_TAC(SYM(ASSUME `tile_k tau = kt`)) THEN
      SUBGOAL_THEN
       `sum {s | s IN P /\ tile_ler s tau} (\s. norm((c:(int#int#int)->complex)
         s) pow 2) =
        sum {s | s IN P /\ tile_ler s tau} (\s. norm(carleson_ip
          (f:real->complex) s) pow 2)`
       SUBST1_TAC THENL
       [MATCH_MP_TAC SUM_EQ THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC FTILDE_ENERGY_SUM THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_MUL_ASSOC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `real_measure(real_interval[dyho_mid (--kt) nt - &7 * &2 zpow (--kt),
                               dyho_mid (--kt) nt + &7 * &2 zpow (--kt)])
    = &14 * &2 zpow (--kt)`
   SUBST1_TAC THENL
   [REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN
    SUBGOAL_THEN `&0 < &2 zpow (--kt)` MP_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `sqrt(&14 * &2 zpow (--kt)) *
    sqrt(&8 * C3 * ((energy_f (f:real->complex) P) pow 2 * &2 zpow (--kt))) =
    sqrt(&112 * C3) * energy_f f P * &2 zpow (--kt)`
   (fun th -> REWRITE_TAC[th; REAL_LE_REFL]) THEN
  SUBGOAL_THEN `&0 <= &2 zpow (--kt) /\ &0 <= energy_f (f:real->complex) P`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      MATCH_MP_TAC ENERGY_F_POS THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[GSYM SQRT_MUL] THEN
  SUBGOAL_THEN
   `(&14 * &2 zpow (--kt)) * &8 * C3 * ((energy_f (f:real->complex) P) pow 2 *
     &2 zpow (--kt)) =
    (&112 * C3) * (energy_f f P * &2 zpow (--kt)) pow 2`
   SUBST1_TAC THENL
   [REWRITE_TAC[REAL_POW_MUL] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[SQRT_MUL] THEN AP_TERM_TAC THEN
  MATCH_MP_TAC POW_2_SQRT THEN MATCH_MP_TAC REAL_LE_MUL THEN
    ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286L(k) assembly brick 1: the abstract 4-way combination. If the 286L LHS *)
(* is bounded by |a0|+|a1|+|a2|+|a3| and each |a_j| <= C_j * base, then it   *)
(* is                                                                        *)
(* bounded by (C0+C1+C2+C3) * base -- so C7 is taken as the sum of the four  *)
(* alpha-total constants (the 286L theorem is EXISTS C7, so no need to match *)
(* Fremlin's exact 7/2 + 8/7 + 28/w(3/2) + 4 sqrt(14 C3)/w(3/2) closed       *)
(* form).                                                                    *)
(* ------------------------------------------------------------------------- *)
let INTEGRAL_UNIONS_FINITE_C = prove
 (`!(ff:real^1->complex) (D:(real^1->bool)->bool).
     FINITE D /\
     (!s. s IN D ==> ff integrable_on s) /\
     (!s s'. s IN D /\ s' IN D /\ ~(s = s') ==> negligible (s INTER s'))
     ==> integral (UNIONS D) ff = vsum D (\s. integral s ff)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC INTEGRAL_UNIQUE THEN
  MATCH_MP_TAC HAS_INTEGRAL_UNIONS THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `s:real^1->bool` THEN DISCH_TAC THEN
  ASM_SIMP_TAC[GSYM INTEGRABLE_INTEGRAL]);;

(* K2 core: cover-decomposition of a tile integral over a FINITE             *)
(* disjoint-ish                                                              *)
(* cover. integral region ff = vsum_{c in S} integral(region INTER Gc c) ff. *)
let COMPLEX_UNIT_PHASE = prove
 (`!z:complex. ?w. norm w = &1 /\ w * z = Cx(norm z)`,
  GEN_TAC THEN ASM_CASES_TAC `z = Cx(&0)` THENL
   [EXISTS_TAC `Cx(&1)` THEN
    ASM_REWRITE_TAC[COMPLEX_NORM_CX; COMPLEX_MUL_RZERO; COMPLEX_NORM_0] THEN
    CONV_TAC REAL_RAT_REDUCE_CONV;
    EXISTS_TAC `cnj z / Cx(norm z)` THEN CONJ_TAC THENL
     [REWRITE_TAC[COMPLEX_NORM_DIV; COMPLEX_NORM_CNJ; COMPLEX_NORM_CX;
       REAL_ABS_NORM] THEN
      MATCH_MP_TAC REAL_DIV_REFL THEN ASM_REWRITE_TAC[COMPLEX_NORM_ZERO];
      REWRITE_TAC[complex_div] THEN
      ONCE_REWRITE_TAC[COMPLEX_RING `(a * b) * c = (c * a) * b:complex`] THEN
      REWRITE_TAC[GSYM complex_div] THEN ASM_SIMP_TAC[COMPLEX_MUL_CNJ] THEN
      REWRITE_TAC[GSYM CX_POW; complex_div; GSYM CX_INV; GSYM CX_MUL] THEN
      AP_TERM_TAC THEN
        MATCH_MP_TAC(REAL_FIELD `~(n = &0) ==> n pow 2 * inv n = n`) THEN
      ASM_REWRITE_TAC[COMPLEX_NORM_ZERO]]]);;

(* Cx pulls out of a finite vsum.                                            *)
let VSUM_CX_PULL = prove
 (`!f (P:A->bool). FINITE P ==> vsum P (\s. Cx(f s)) = Cx(sum P f)`,
  GEN_TAC THEN MATCH_MP_TAC FINITE_INDUCT_STRONG THEN
  SIMP_TAC[VSUM_CLAUSES; SUM_CLAUSES] THEN
  REWRITE_TAC[GSYM CX_ADD; COMPLEX_VEC_0; CX_DEF]);;

let ZETA_REALIFY = prove
 (`!(P:A->bool) (z:A->complex).
     FINITE P
     ==> ?w. (!s. norm(w s) = &1) /\
             sum P (\s. norm(z s)) = norm(vsum P (\s. w s * z s))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(GEN `s:A` (ISPEC `(z:A->complex) s` COMPLEX_UNIT_PHASE)) THEN
  REWRITE_TAC[SKOLEM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A->complex` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `w:A->complex` THEN ASM_REWRITE_TAC[] THEN
  ASM_SIMP_TAC[VSUM_CX_PULL] THEN REWRITE_TAC[COMPLEX_NORM_CX] THEN
  CONV_TAC SYM_CONV THEN REWRITE_TAC[REAL_ABS_REFL] THEN
  MATCH_MP_TAC SUM_POS_LE THEN REWRITE_TAC[NORM_POS_LE]);;

(* ------------------------------------------------------------------------- *)
(* 286L(b) 4-way norm-block split: for a finite index set partitioned into 4 *)
(* pairwise-disjoint blocks W0,W1,W2,W3, the norm of the whole vsum is       *)
(* bounded                                                                   *)
(* by the sum of the four block norms. = Fremlin's |sum_{P x K}| <=          *)
(* |a0|+|a1|+                                                                *)
(* |a2|+|a3| step (each a_j = the W_j double-sum), keeping every block as a  *)
(* norm-of-sum -- crucially W3 stays norm(vsum{W3}) matching ALPHA3_TOTAL    *)
(* (an                                                                       *)
(* early sum-of-norms flatten of W3 would reverse the alpha3 inequality).    *)
(* VSUM_UNION collapses the 4-fold union; NORM_TRIANGLE thrice.              *)
(* ------------------------------------------------------------------------- *)
let S_DICHOTOMY_SPLIT = prove
 (`!(S:(int#int)->bool) kt (g:(int#int)->real).
     FINITE S
     ==> sum S g =
         sum {ap | ap IN S /\ &2 zpow (FST ap) <= &2 zpow (--kt)} g +
         sum {ap | ap IN S /\ &2 zpow (--kt) < &2 zpow (FST ap)} g`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`g:(int#int)->real`;
    `{ap:int#int | ap IN S /\ &2 zpow (FST ap) <= &2 zpow (--kt)}`;
    `{ap:int#int | ap IN S /\ &2 zpow (--kt) < &2 zpow (FST ap)}`] SUM_UNION)
      THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[FINITE_RESTRICT] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM; NOT_IN_EMPTY] THEN
    GEN_TAC THEN REAL_ARITH_TAC;
    DISCH_THEN(SUBST1_TAC o SYM) THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM] THEN
      X_GEN_TAC `ap:int#int` THEN
    ASM_CASES_TAC `(ap:int#int) IN S` THEN ASM_REWRITE_TAC[] THEN
      REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* 286L(k) W0+W1 bridge: the combined alpha0 + alpha1 sum-of-norms bound.    *)
(* Summed over the WHOLE cover S, the W0/W1 tile-slice {tile_le s tau /\     *)
(* --FST ap <= tile_k s} (the l_K >= k_s "coarse-relative" tiles) is bounded *)
(* by the S-dichotomy split into S>= (l_K >= kt, -> ALPHA0_TOTAL_WIDE) and   *)
(* S< (l_K < kt, -> ALPHA1_TOTAL, which needs tile_k tau = kt). Both use the *)
(* SUM-of-norms shape (the zeta unimodular phase washes out, |zeta|=1), so   *)
(* the bare carleson_ip f is correct here.  The combined constant is         *)
(* 28*C0 + C1 (C0 the WIDE-alpha0 constant, C1 the alpha1 constant); the     *)
(* algebra (2*C0*e*m)*14*t + C1*e*m*t = (28*C0+C1)*e*m*t is a REAL_RING      *)
(* identity (nonlinear in C0/C1/e/m, so not REAL_ARITH).                     *)
(* ------------------------------------------------------------------------- *)
let W01_BRIDGE = prove
 (`?C. &0 <= C /\
   !(f:real->complex) E h (P:(int#int#int)->bool) S kt nt tau.
      FINITE P /\ ~(P = {}) /\ tile_k tau = kt /\
      (!s. s IN P ==> tile_le s tau) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      FINITE S /\ (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap))
      ==> sum S (\ap. sum {s | s IN P /\ tile_le s tau /\ --(FST ap) <= tile_k
        s}
                          (\s. norm(carleson_ip f s *
                               integral (IMAGE lift ({x | x IN E /\ h x IN
                                 tile_Jr s} INTER
                                         dyho (FST ap) (SND ap)))
                                        (\z. phi_sigma s carleson_phi (drop
                                          z)))))
          <= C * energy_f f P * mass_Eh E h P * &2 zpow (--kt)`,
  X_CHOOSE_THEN
    `C0:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "A0"))
     ALPHA0_TOTAL_WIDE THEN
  X_CHOOSE_THEN
    `C1:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "A1")) ALPHA1_TOTAL THEN
  EXISTS_TAC `&28 * C0 + C1` THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`S:(int#int)->bool`; `kt:int`;
    `\ap. sum {s | s IN P /\ tile_le s tau /\ --(FST ap) <= tile_k s}
              (\s. norm(carleson_ip (f:real->complex) s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                             dyho (FST ap) (SND ap)))
                            (\z. phi_sigma s carleson_phi (drop z))))`]
   S_DICHOTOMY_SPLIT) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `(&2 * C0 * energy_f (f:real->complex) P * mass_Eh E h P) * &14 * &2 zpow
     (--kt) +
    C1 * energy_f (f:real->complex) P * mass_Eh E h P * &2 zpow (--kt)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THENL
     [USE_THEN "A0" (MP_TAC o SPECL
        [`f:real->complex`; `E:real->bool`; `h:real->real`;
         `P:(int#int#int)->bool`;
         `{ap:int#int | ap IN S /\ &2 zpow (FST ap) <= &2 zpow (--kt)}`;
         `kt:int`; `nt:int`; `tau:int#int#int`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
         [ASM_MESON_TAC[tile_le];
          ASM_SIMP_TAC[FINITE_RESTRICT];
          REWRITE_TAC[IN_ELIM_THM] THEN ASM_MESON_TAC[]];
        DISCH_TAC THEN FIRST_X_ASSUM ACCEPT_TAC];
      USE_THEN "A1" (MP_TAC o SPECL
        [`f:real->complex`; `E:real->bool`; `h:real->real`;
         `P:(int#int#int)->bool`;
         `{ap:int#int | ap IN S /\ &2 zpow (--kt) < &2 zpow (FST ap)}`;
         `kt:int`; `nt:int`; `tau:int#int#int`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
         [ASM_MESON_TAC[tile_le];
          ASM_SIMP_TAC[FINITE_RESTRICT];
          REWRITE_TAC[IN_ELIM_THM] THEN ASM_MESON_TAC[]];
        DISCH_TAC THEN FIRST_X_ASSUM ACCEPT_TAC]];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN CONV_TAC REAL_RING]);;

(* ------------------------------------------------------------------------- *)
(* 286L(k) W2 bridge: the W2 block (sigma NOT in the tree T_tau, mu K < mu   *)
(* I_s)                                                                      *)
(* summed over the WHOLE cover S.  The W2 tile-slice {tile_le s tau /\       *)
(* ~tile_ler s tau /\ tile_k s < --FST ap} is EMPTY on cells failing the     *)
(* alpha2                                                                    *)
(* gate 2^{FSTap+1}<=2^{-kt} (there --FST ap <= kt <= tile_k s,              *)
(* contradicting                                                             *)
(* tile_k s < --FST ap by the tree scale TILE_LE_SCALE), so SUM_SUPERSET     *)
(* collapses S to the gated subset, on which ALPHA2_TOTAL applies.  Sum-of-  *)
(* norms (the zeta phase washes out), so BARE carleson_ip f. C = 56          *)
(* C2/cw(3/2).                                                               *)
(* ------------------------------------------------------------------------- *)
let W2_BRIDGE = prove
 (`?C. &0 <= C /\
   !(f:real->complex) E h (P:(int#int#int)->bool) S kt nt tau.
      FINITE P /\ ~(P = {}) /\ tile_k tau = kt /\
      (!s. s IN P ==> tile_le s tau) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      FINITE S /\ (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap))
      ==> sum S (\ap. sum {s | s IN P /\ tile_le s tau /\ ~(tile_ler s tau) /\
                               tile_k s < --(FST ap)}
                          (\s. norm(carleson_ip f s *
                               integral (IMAGE lift ({x | x IN E /\ h x IN
                                 tile_Jr s} INTER
                                         dyho (FST ap) (SND ap)))
                                        (\z. phi_sigma s carleson_phi (drop
                                          z)))))
          <= C * energy_f f P * mass_Eh E h P * &2 zpow (--kt)`,
  X_CHOOSE_THEN
    `C2:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "A2")) ALPHA2_TOTAL THEN
  EXISTS_TAC `&56 * C2 / cw(&3 / &2)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
       [ASM_REAL_ARITH_TAC; MP_TAC(SPEC `&3 / &2` CW_POS) THEN
         REAL_ARITH_TAC]];
    ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\ap. sum {s | s IN P /\ tile_le s tau /\ ~(tile_ler s tau) /\
                   tile_k s < --(FST(ap:int#int))}
              (\s. norm(carleson_ip (f:real->complex) s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                             dyho (FST ap) (SND ap)))
                            (\z. phi_sigma s carleson_phi (drop z))))`;
    `{ap:int#int | ap IN S /\ &2 zpow (FST ap + &1) <= &2 zpow (--kt)}`;
    `S:(int#int)->bool`]
   SUM_SUPERSET) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
      X_GEN_TAC `ap:int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
      REWRITE_TAC[] THEN MATCH_MP_TAC SUM_EQ_0 THEN
        X_GEN_TAC `s:int#int#int` THEN
      REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
      SUBGOAL_THEN `--(FST(ap:int#int)) <= kt` ASSUME_TAC THENL
       [SUBGOAL_THEN `&2 zpow (--kt) < &2 zpow (FST(ap:int#int) + &1)`
         (MP_TAC o MATCH_MP ZPOW2_LT_REV) THENL
         [ASM_MESON_TAC[REAL_NOT_LE]; INT_ARITH_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `tile_k tau <= tile_k(s:int#int#int)` MP_TAC THENL
       [MATCH_MP_TAC TILE_LE_SCALE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_INT_ARITH_TAC];
    DISCH_THEN SUBST1_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `((&2 * C2 * energy_f (f:real->complex) P) * (&2 * mass_Eh E h P / cw(&3 /
     &2))) *
    (&14 * &2 zpow (--kt))` THEN
  CONJ_TAC THENL
   [USE_THEN "A2" (MP_TAC o SPECL
     [`f:real->complex`; `E:real->bool`; `h:real->real`;
      `P:(int#int#int)->bool`;
      `{ap:int#int | ap IN S /\ &2 zpow (FST ap + &1) <= &2 zpow (--kt)}`;
      `kt:int`; `nt:int`; `tau:int#int#int`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
       [ASM_SIMP_TAC[FINITE_RESTRICT];
        REWRITE_TAC[IN_ELIM_THM] THEN ASM_MESON_TAC[]];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_EQ_IMP_LE THEN
  MP_TAC(SPEC `&3 / &2` CW_POS) THEN CONV_TAC REAL_FIELD);;

(* ------------------------------------------------------------------------- *)
(* 286L(k) W3 bridge: the W3 block (sigma IN the tree T_tau, mu K < mu I_s)  *)
(* summed over the WHOLE cover S.  Like W2 but the W3-slice keeps the        *)
(* NORM-OF-SUM (cancellation), so it uses the zeta-general ALPHA3_TOTAL_C    *)
(* with                                                                      *)
(* the arbitrary coefficient c (whose norm matches carleson_ip f -- the      *)
(* unimodular phase absorbed into c).  Off-gate the W3-slice vsum is empty   *)
(* (VSUM over {} -> 0, norm 0), SUM_SUPERSET collapses to the gated subset.  *)
(* C = 4 C1 sqrt(112 C3)/cw(3/2).  h is kept FREE (matches ALPHA3_TOTAL_C).  *)
(* ------------------------------------------------------------------------- *)
let W3_BRIDGE = prove
 (`?C. &0 <= C /\
   !(c:(int#int#int)->complex) (f:real->complex) E h (P:(int#int#int)->bool) S
     kt nt tau.
      FINITE P /\ ~(P = {}) /\ tile_k tau = kt /\
      (!s. s IN P ==> tile_le s tau) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      (!s. norm(c s) = norm(carleson_ip f s)) /\
      FINITE S /\ (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap))
      ==> sum S (\ap. norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <
        --(FST ap)}
                          (\s. c s *
                               integral (IMAGE lift ({x | x IN E /\ h x IN
                                 tile_Jr s} INTER
                                         dyho (FST ap) (SND ap)))
                                        (\z. phi_sigma s carleson_phi (drop
                                          z)))))
          <= C * energy_f f P * mass_Eh E h P * &2 zpow (--kt)`,
  X_CHOOSE_THEN `C1:real` (X_CHOOSE_THEN `C3:real`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "A3"))))
    ALPHA3_TOTAL_C THEN
  EXISTS_TAC `(&4 * C1) * sqrt(&112 * C3) / cw(&3 / &2)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
      MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
       [MATCH_MP_TAC SQRT_POS_LE THEN ASM_REAL_ARITH_TAC;
        MP_TAC(SPEC `&3 / &2` CW_POS) THEN REAL_ARITH_TAC]];
    ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\ap. norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <
     --(FST(ap:int#int))}
              (\s. (c:(int#int#int)->complex) s *
                   integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                             dyho (FST ap) (SND ap)))
                            (\z. phi_sigma s carleson_phi (drop z))))`;
    `{ap:int#int | ap IN S /\ &2 zpow (FST ap + &1) <= &2 zpow (--kt)}`;
    `S:(int#int)->bool`]
   SUM_SUPERSET) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
      X_GEN_TAC `ap:int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
      REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `~(&2 zpow (FST(ap:int#int) + &1) <= &2 zpow (--kt))` ASSUME_TAC THENL
       [UNDISCH_TAC `~((ap:int#int) IN S /\ &2 zpow (FST ap + &1) <= &2 zpow
         (--kt))` THEN
        UNDISCH_TAC `(ap:int#int) IN S` THEN CONV_TAC TAUT;
        ALL_TAC] THEN
      SUBGOAL_THEN `--(FST(ap:int#int)) <= kt` ASSUME_TAC THENL
       [UNDISCH_TAC `~(&2 zpow (FST(ap:int#int) + &1) <= &2 zpow (--kt))` THEN
        REWRITE_TAC[REAL_NOT_LE] THEN
        DISCH_THEN(MP_TAC o MATCH_MP ZPOW2_LT_REV) THEN INT_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `{s | s IN P /\ tile_ler s tau /\ tile_k s < --(FST(ap:int#int))} = {}`
       (fun th -> REWRITE_TAC[th; VSUM_CLAUSES; NORM_0]) THEN
      REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
      X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
      SUBGOAL_THEN `tile_k tau <= tile_k(s:int#int#int)` MP_TAC THENL
       [MATCH_MP_TAC TILE_LE_SCALE THEN MATCH_MP_TAC TILE_LER_IMP_LE THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_INT_ARITH_TAC];
    DISCH_THEN SUBST1_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `((&4 * C1) * mass_Eh E (h:real->real) P / cw(&3 / &2)) *
    (sqrt(&112 * C3) * energy_f (f:real->complex) P * &2 zpow (--kt))` THEN
  CONJ_TAC THENL
   [USE_THEN "A3" (MP_TAC o ISPECL
     [`c:(int#int#int)->complex`; `f:real->complex`; `E:real->bool`;
      `h:real->real`; `P:(int#int#int)->bool`;
      `{ap:int#int | ap IN S /\ &2 zpow (FST ap + &1) <= &2 zpow (--kt)}`;
      `kt:int`; `nt:int`; `tau:int#int#int`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
       [ASM_SIMP_TAC[FINITE_RESTRICT];
        X_GEN_TAC `ap2:int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN
          STRIP_TAC THEN
        ASM_REWRITE_TAC[] THEN
        FIRST_X_ASSUM(fun th -> if is_forall(concl th) &&
           can (find_term (fun tm -> tm = `in_kcover`)) (concl th) &&
           not(can (find_term (fun tm -> tm = `phi_sigma`)) (concl th))
           then MATCH_MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[]];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_EQ_IMP_LE THEN
  MP_TAC(SPEC `&3 / &2` CW_POS) THEN CONV_TAC REAL_FIELD);;

(* ------------------------------------------------------------------------- *)
(* 286L(k) wiring brick: the complex-vsum W-partition split (analog of       *)
(* W_SUM_SPLIT).  Splits an inner tile-vsum over {s in P | tile_le s tau}    *)
(* into the W01 slice (--a<=tile_k s), W2 slice (tile_k s<--a /\ ~tile_ler), *)
(* and W3 slice (tile_k s<--a /\ tile_ler), via the W_TRICHOTOMY partition + *)
(* VSUM_UNION (twice).                                                       *)
(* ------------------------------------------------------------------------- *)
let VSUM_W_SPLIT = prove
 (`!(P:(int#int#int)->bool) tau a (g:(int#int#int)->complex).
     FINITE P
     ==> vsum {s | s IN P /\ tile_le s tau} g =
         vsum {s | s IN P /\ tile_le s tau /\ --a <= tile_k s} g +
         vsum {s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ ~(tile_ler s
           tau)} g +
         vsum {s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ tile_ler s tau}
           g`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `{s | s IN P /\ tile_le s tau} =
    {s | s IN P /\ tile_le s tau /\ --a <= tile_k s} UNION
    ({s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ ~(tile_ler s tau)} UNION
     {s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ tile_ler s tau})`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM] THEN
    X_GEN_TAC `s:int#int#int` THEN
    MP_TAC(INT_ARITH `--a <= tile_k s \/ tile_k s < --a`) THEN
    MAP_EVERY ASM_CASES_TAC
     [`s IN (P:(int#int#int)->bool)`; `tile_le s tau`; `tile_ler s tau`;
      `--a <= tile_k s`] THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ALL_TAC] THEN
  W(fun (asl,w) -> MP_TAC(PART_MATCH (lhs o rand) VSUM_UNION (lhs w))) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `P:(int#int#int)->bool` THEN
      ASM_REWRITE_TAC[] THEN SET_TAC[];
      MATCH_MP_TAC FINITE_UNION_IMP THEN CONJ_TAC THEN
      MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `P:(int#int#int)->bool` THEN
      ASM_REWRITE_TAC[] THEN SET_TAC[];
      REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_UNION; IN_ELIM_THM;
        NOT_IN_EMPTY] THEN
      GEN_TAC THEN INT_ARITH_TAC];
    DISCH_THEN SUBST1_TAC] THEN
  AP_TERM_TAC THEN
  MP_TAC(ISPECL
   [`g:(int#int#int)->complex`;
    `{s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ ~(tile_ler s tau)}`;
    `{s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ tile_ler s tau}`]
   VSUM_UNION) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `P:(int#int#int)->bool` THEN
      ASM_REWRITE_TAC[] THEN SET_TAC[];
      MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `P:(int#int#int)->bool` THEN
      ASM_REWRITE_TAC[] THEN SET_TAC[];
      REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_ELIM_THM;
        NOT_IN_EMPTY] THEN
      GEN_TAC THEN MESON_TAC[]];
    DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286L(k) wiring brick: the per-cover-cell 3-way bound.  For a FIXED cover  *)
(* cell (parametrized by a = FST ap) and coefficient c whose norm matches    *)
(* carleson_ip f, the norm of the whole inner tile-vsum is bounded by the    *)
(* W01                                                                       *)
(* sum-of-norms + W2 sum-of-norms + W3 norm-of-sum -- the three shapes the   *)
(* bridges consume.  Route: rewrite vsum P = vsum{tile_le} (tree hyp);       *)
(* VSUM_W_SPLIT; fold the W3 slice {tile_le/\tk<-a/\ler}={ler/\tk<-a} via    *)
(* TILE_LER_IMP_LE; NORM_TRIANGLE twice; VSUM_NORM on the W01/W2 blocks +    *)
(* phase-invariance norm(c s)=norm(cf s) inside the sums.                    *)
(* ------------------------------------------------------------------------- *)
let L286_PER_AP_GEN = prove
 (`!(c:(int#int#int)->complex) (cf:(int#int#int)->complex)
   (P:(int#int#int)->bool) tau a wf.
      FINITE P /\ (!s. s IN P ==> tile_le s tau) /\
      (!s. norm(c s) = norm(cf s))
      ==> norm(vsum P (\s. c s * wf s))
          <= sum {s | s IN P /\ tile_le s tau /\ --a <= tile_k s}
                 (\s. norm(cf s * wf s)) +
             sum {s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ ~(tile_ler s
               tau)}
                 (\s. norm(cf s * wf s)) +
             norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --a}
                       (\s. c s * wf s))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `vsum P (\s. (c:(int#int#int)->complex) s * wf s) =
    vsum {s | s IN P /\ tile_le s tau /\ --a <= tile_k s} (\s. c s * wf s) +
    vsum {s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ ~(tile_ler s tau)}
         (\s. c s * wf s) +
    vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --a} (\s. c s * wf s)`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`P:(int#int#int)->bool`; `tau:int#int#int`; `a:int`;
                   `\s. (c:(int#int#int)->complex) s * wf s`] VSUM_W_SPLIT)
                     THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `{s | s IN P /\ tile_le s tau} = P` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `{s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ tile_ler s tau} =
      {s | s IN P /\ tile_ler s tau /\ tile_k s < --a}`
     (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN
    EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[TILE_LER_IMP_LE];
    ALL_TAC] THEN
  W(fun (asl,ww) -> MP_TAC(PART_MATCH lhand NORM_TRIANGLE (lhand ww))) THEN
  MATCH_MP_TAC(REAL_ARITH
   `na <= na' /\ nbc <= nb' + nc'
    ==> (x <= na + nbc ==> x <= na' + nb' + nc')`) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `sum {s | s IN P /\ tile_le s tau /\ --a <= tile_k s}
                    (\s. norm((c:(int#int#int)->complex) s * wf s))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC VSUM_NORM THEN ASM_SIMP_TAC[FINITE_RESTRICT];
      MATCH_MP_TAC REAL_EQ_IMP_LE THEN MATCH_MP_TAC SUM_EQ THEN
      X_GEN_TAC `s:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN
        STRIP_TAC THEN
      REWRITE_TAC[COMPLEX_NORM_MUL] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  W(fun (asl,ww) -> MP_TAC(PART_MATCH lhand NORM_TRIANGLE (lhand ww))) THEN
  MATCH_MP_TAC(REAL_ARITH `nb <= nb' ==> (x <= nb + nc ==> x <= nb' + nc)`)
    THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum {s | s IN P /\ tile_le s tau /\ tile_k s < --a /\ ~(tile_ler
    s tau)}
                  (\s. norm((c:(int#int#int)->complex) s * wf s))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC VSUM_NORM THEN ASM_SIMP_TAC[FINITE_RESTRICT];
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN MATCH_MP_TAC SUM_EQ THEN
    X_GEN_TAC `s:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL] THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286L(k) ABSTRACT k-assembly.  Given a unit phase w with the ZETA-realify  *)
(* identity, and the three W-block bounds B01/B2/B3, the 286L LHS (sum_s     *)
(* norm(cf_s * vsum_S wf)) is bounded by B01 + B2 + B3. All terms stay       *)
(* compact                                                                   *)
(* (wf s ap), so no giant-lambda slowdown. Route: rewrite LHS via realify -> *)
(* norm(vsum_s w_s cf_s vsum_S wf); pull w inside (VSUM_COMPLEX_LMUL);       *)
(* VSUM_SWAP                                                                 *)
(* (ap outside); VSUM_NORM_LE with the per-ap 3-way L286_PER_AP_GEN bound;   *)
(* SUM_ADD split into the three block-sums; REAL_LE_ADD2.                    *)
(* ------------------------------------------------------------------------- *)
let CARLESON_286L_ABSTRACT = prove
 (`!(cf:(int#int#int)->complex) (w:(int#int#int)->complex)
     (wf:(int#int#int)->(int#int)->complex) (P:(int#int#int)->bool)
       (S:(int#int)->bool)
     tau (a0:(int#int)->int) B01 B2 B3.
      FINITE P /\ FINITE S /\ (!s. s IN P ==> tile_le s tau) /\
      (!s. norm(w s) = &1) /\
      sum P (\s. norm(cf s * vsum S (\ap. wf s ap))) =
      norm(vsum P (\s. w s * (cf s * vsum S (\ap. wf s ap)))) /\
      sum S (\ap. sum {s | s IN P /\ tile_le s tau /\ --(a0 ap) <= tile_k s}
                      (\s. norm(cf s * wf s ap))) <= B01 /\
      sum S (\ap. sum {s | s IN P /\ tile_le s tau /\ tile_k s < --(a0 ap) /\
        ~(tile_ler s tau)}
                      (\s. norm(cf s * wf s ap))) <= B2 /\
      sum S (\ap. norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s < --(a0
        ap)}
                            (\s. (w s * cf s) * wf s ap))) <= B3
      ==> sum P (\s. norm(cf s * vsum S (\ap. wf s ap))) <= B01 + B2 + B3`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(fun th ->
    if is_eq(concl th) && can (find_term (fun t -> t = `norm:complex->real`))
      (rand(concl th))
    then ONCE_REWRITE_TAC[th] else NO_TAC) THEN
  SUBGOAL_THEN
   `vsum P (\s. (w:(int#int#int)->complex) s * (cf s * vsum S (\ap. wf s ap)))
     =
    vsum P (\s. vsum S (\ap. (w s * cf s) *
      (wf:(int#int#int)->(int#int)->complex) s ap))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[COMPLEX_MUL_ASSOC] THEN
    MP_TAC(ISPECL [`(w:(int#int#int)->complex) s * cf s`;
                   `\ap. (wf:(int#int#int)->(int#int)->complex) s ap`;
                   `S:(int#int)->bool`] VSUM_COMPLEX_LMUL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\s ap. ((w:(int#int#int)->complex) s * cf s) *
                         (wf:(int#int#int)->(int#int)->complex) s ap`;
                 `P:(int#int#int)->bool`; `S:(int#int)->bool`] VSUM_SWAP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum (S:(int#int)->bool) (\(ap:int#int).
       sum {s | s IN P /\ tile_le s tau /\ --((a0:(int#int)->int) ap) <= tile_k
         s}
           (\s. norm((cf:(int#int#int)->complex) s *
                 (wf:(int#int#int)->(int#int)->complex) s ap)) +
       (sum {s | s IN P /\ tile_le s tau /\ tile_k s < --((a0:(int#int)->int)
         ap) /\
                ~(tile_ler s tau)}
            (\s. norm(cf s * wf s ap)) +
        norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <
          --((a0:(int#int)->int) ap)}
                  (\s. ((w:(int#int#int)->complex) s * cf s) * wf s ap))))`
                    THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC VSUM_NORM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MP_TAC(ISPECL
     [`\s. (w:(int#int#int)->complex) s * cf s`;
      `cf:(int#int#int)->complex`; `P:(int#int#int)->bool`; `tau:int#int#int`;
      `(a0:(int#int)->int) ap`;
      `\s. (wf:(int#int#int)->(int#int)->complex) s ap`] L286_PER_AP_GEN) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [GEN_TAC THEN REWRITE_TAC[COMPLEX_NORM_MUL] THEN
       ASM_REWRITE_TAC[REAL_MUL_LID];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\(ap:int#int). sum {s | s IN P /\ tile_le s tau /\ --((a0:(int#int)->int)
     ap) <= tile_k s}
              (\s. norm((cf:(int#int#int)->complex) s *
                    (wf:(int#int#int)->(int#int)->complex) s ap))`;
    `\(ap:int#int).
          sum {s | s IN P /\ tile_le s tau /\ tile_k s < --((a0:(int#int)->int)
            ap) /\
                   ~(tile_ler s tau)}
              (\s. norm((cf:(int#int#int)->complex) s * wf s ap)) +
          norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <
            --((a0:(int#int)->int) ap)}
                    (\s. ((w:(int#int#int)->complex) s * cf s) * wf s ap))`;
    `S:(int#int)->bool`] SUM_ADD) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL
   [`\(ap:int#int). sum {s | s IN P /\ tile_le s tau /\ tile_k s <
     --((a0:(int#int)->int) ap) /\
                   ~(tile_ler s tau)}
              (\s. norm((cf:(int#int#int)->complex) s * wf s ap))`;
    `\(ap:int#int). norm(vsum {s | s IN P /\ tile_ler s tau /\ tile_k s <
      --((a0:(int#int)->int) ap)}
                    (\s. ((w:(int#int#int)->complex) s * cf s) * wf s ap))`;
    `S:(int#int)->bool`] SUM_ADD) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC(REAL_ARITH `a <= x /\ b <= y /\ c <= z ==> a + b + c <= x + y +
    z`) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* CARLESON_286L_FINITE: the finite-cover (post-K2) form of Fremlin 286L.    *)
(* The 286L correlation LHS -- with the tile integral over the FULL region   *)
(* already expanded as vsum_{ap in S} int_{region cap dyho ap} (K2) -- is    *)
(* bounded by C7 * energy * mass * 2^{-kt}. Instantiates                     *)
(* CARLESON_286L_ABSTRACT                                                    *)
(* (cf := carleson_ip f, wf := the cover-cell integral, w from ZETA_REALIFY, *)
(* a0 := FST, B0j := Cj*energy*mass*2^{-kt}), discharging the ANTS: realify  *)
(* (ZETA), B01 (W01_BRIDGE), B2 (W2_BRIDGE, after a slice-conjunct reorder   *)
(* to                                                                        *)
(* ~ler-before-tile_k<), B3 (W3_BRIDGE, c = w_s*carleson_ip f s,             *)
(* BETA-reduced).                                                            *)
(* C7 = Cw + Cv + Cz (the three W-block constants).  This is the k-assembly  *)
(* endgame: only K1 (infinite-cover -> finite S) remains for the full 286L.  *)
(* ------------------------------------------------------------------------- *)
let CARLESON_286L_FINITE = prove
 (`?C7. &0 <= C7 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) S kt nt tau.
      FINITE P /\ ~(P = {}) /\ tile_k tau = kt /\
      (!s. s IN P ==> tile_le s tau) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      FINITE S /\ (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap))
      ==> sum P (\s. norm(carleson_ip f s *
                          vsum S (\ap. integral (IMAGE lift
                                ({x | x IN E /\ h x IN tile_Jr s} INTER dyho
                                  (FST ap) (SND ap)))
                                (\z. phi_sigma s carleson_phi (drop z)))))
          <= C7 * energy_f f P * mass_Eh E h P * &2 zpow (--kt)`,
  X_CHOOSE_THEN
    `Cw:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "BW01")) W01_BRIDGE THEN
  X_CHOOSE_THEN
    `Cv:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "BW2")) W2_BRIDGE THEN
  X_CHOOSE_THEN
    `Cz:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "BW3")) W3_BRIDGE THEN
  EXISTS_TAC `Cw + Cv + Cz:real` THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`;
                 `\s. carleson_ip (f:real->complex) s *
                      vsum S (\(ap:int#int). integral (IMAGE lift
                            ({x | x IN E /\ h x IN tile_Jr s} INTER dyho (FST
                              ap) (SND ap)))
                            (\z. phi_sigma s carleson_phi (drop z)))`]
    ZETA_REALIFY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:(int#int#int)->complex` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!s. norm((w:(int#int#int)->complex) s * carleson_ip (f:real->complex) s) =
        norm(carleson_ip f s)`
   ASSUME_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[COMPLEX_NORM_MUL] THEN
     ASM_REWRITE_TAC[REAL_MUL_LID];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`carleson_ip (f:real->complex)`; `w:(int#int#int)->complex`;
    `\s (ap:int#int). integral (IMAGE lift
          ({x | x IN E /\ h x IN tile_Jr s} INTER dyho (FST ap) (SND ap)))
          (\z. phi_sigma s carleson_phi (drop z))`;
    `P:(int#int#int)->bool`; `S:(int#int)->bool`; `tau:int#int#int`;
    `FST:(int#int)->int`;
    `Cw * energy_f (f:real->complex) P * mass_Eh E h P * &2 zpow (--kt)`;
    `Cv * energy_f (f:real->complex) P * mass_Eh E h P * &2 zpow (--kt)`;
    `Cz * energy_f (f:real->complex) P * mass_Eh E h P * &2 zpow (--kt)`]
   CARLESON_286L_ABSTRACT) THEN
  REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_X_ASSUM(fun th -> if is_eq(concl th) &&
        can (find_term (fun t -> t = `norm:complex->real`)) (rand(concl th))
        then MP_TAC th else NO_TAC) THEN
      CONV_TAC(DEPTH_CONV BETA_CONV) THEN REWRITE_TAC[COMPLEX_MUL_ASSOC] THEN
      DISCH_THEN ACCEPT_TAC;
      USE_THEN "BW01" (MP_TAC o SPECL
        [`f:real->complex`; `E:real->bool`; `h:real->real`;
          `P:(int#int#int)->bool`;
         `S:(int#int)->bool`; `kt:int`; `nt:int`; `tau:int#int#int`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN
        ACCEPT_TAC];
      SUBGOAL_THEN
       `!ap:int#int.
          {s | s IN P /\ tile_le s tau /\ tile_k s < --(FST ap) /\ ~(tile_ler s
            tau)} =
          {s:int#int#int | s IN P /\ tile_le s tau /\ ~(tile_ler s tau) /\
                           tile_k s < --(FST ap)}`
       (fun th -> REWRITE_TAC[th]) THENL
       [GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN
         CONV_TAC TAUT;
        ALL_TAC] THEN
      USE_THEN "BW2" (MP_TAC o SPECL
        [`f:real->complex`; `E:real->bool`; `h:real->real`;
          `P:(int#int#int)->bool`;
         `S:(int#int)->bool`; `kt:int`; `nt:int`; `tau:int#int#int`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN
        ACCEPT_TAC];
      USE_THEN "BW3" (MP_TAC o CONV_RULE(DEPTH_CONV BETA_CONV) o SPECL
        [`\s. (w:(int#int#int)->complex) s * carleson_ip (f:real->complex) s`;
         `f:real->complex`; `E:real->bool`; `h:real->real`;
           `P:(int#int#int)->bool`;
         `S:(int#int)->bool`; `kt:int`; `nt:int`; `tau:int#int#int`]) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN
        ACCEPT_TAC]];
    SUBGOAL_THEN
     `(Cw + Cv + Cz) * energy_f (f:real->complex) P * mass_Eh E h P * &2 zpow
       (--kt) =
      Cw * energy_f f P * mass_Eh E h P * &2 zpow (--kt) +
      Cv * energy_f f P * mass_Eh E h P * &2 zpow (--kt) +
      Cz * energy_f f P * mass_Eh E h P * &2 zpow (--kt)`
     SUBST1_TAC THENL [CONV_TAC REAL_RING; DISCH_THEN ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* K1: the finite-cover reduction that upgrades CARLESON_286L_FINITE to the  *)
(* full-region 286L that 286M consumes.  The tile integral over the FULL     *)
(* region E cap g^-1[Jr_s] equals the LIMIT of its integrals over the finite *)
(* partial covers UNIONS(enum[0..n]) of the (countable) maximal cover Cal K, *)
(* and each finite-partial-cover integral is the vsum of the piecewise       *)
(* integrals over region INTER dyho(cover cell). Passing                     *)
(* CARLESON_286L_FINITE                                                      *)
(* (whose RHS is uniform in the finite S) to the limit then gives the full   *)
(* 286L.                                                                     *)
(* ------------------------------------------------------------------------- *)

(* Set-algebra helper: IMAGE lift commutes with the region-cover union.      *)
let LIFT_REGION_COVER_UNIONS = prove
 (`!(region:real->bool) (g:A->real->bool) (Iset:A->bool).
     UNIONS {IMAGE lift (region INTER g m) | m IN Iset} =
     IMAGE lift (region INTER UNIONS {g m | m IN Iset})`,
  REPEAT GEN_TAC THEN REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `z:real^1` THEN
  REWRITE_TAC[UNIONS_GSPEC; IN_IMAGE; IN_INTER; IN_ELIM_THM] THEN
  MESON_TAC[]);;

(* K1d: per-sigma, the full-region tile integral is the sequential limit of  *)
(* the finite-partial-cover integrals. Via INTEGRAL_COUNTABLE_UNIONS_ALT     *)
(* with                                                                      *)
(* s m = IMAGE lift(region_s INTER dyho(enum m)); the covering hypothesis    *)
(* UNIONS(cover) = R collapses region_s INTER R = region_s.                  *)
let REGION_INTEGRAL_LIMIT = prove
 (`!(f:real->complex) E (h:real->real) s enum.
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      UNIONS {dyho (FST(enum m)) (SND(enum m)) | m IN (:num)} = (:real)
      ==> ((\n. integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                    UNIONS {dyho (FST(enum m)) (SND(enum m)) | m IN 0..n}))
                    (\z. phi_sigma s carleson_phi (drop z)))
           --> integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                    (\z. phi_sigma s carleson_phi (drop z))) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`(\z. phi_sigma s carleson_phi (drop z)):real^1->complex`;
    `\m. IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
             dyho (FST((enum:num->int#int) m)) (SND(enum m)))`]
   INTEGRAL_COUNTABLE_UNIONS_ALT) THEN
  REWRITE_TAC[LIFT_REGION_COVER_UNIONS] THEN
  ASM_REWRITE_TAC[INTER_UNIV] THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC PHISIG_ABSINT_LEBESGUE THEN
      MATCH_MP_TAC REGION_LEBESGUE THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN REWRITE_TAC[GSYM REAL_LEBESGUE_MEASURABLE] THEN
      MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
       [MATCH_MP_TAC REGION_LEBESGUE THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
        REWRITE_TAC[DYHO_MEASURABLE]]];
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]);;

(* Distinct cover cells give disjoint region-pieces (region INTER dyho).     *)
let KCOVER_PIECE_DISJOINT = prove
 (`!P (region:real->bool) ap aq.
     in_kcover P (FST ap) (SND ap) /\ in_kcover P (FST aq) (SND aq) /\ ~(ap =
       aq)
     ==> (region INTER dyho (FST ap) (SND ap)) INTER
         (region INTER dyho (FST aq) (SND aq)) = {}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `~(dyho (FST(ap:int#int)) (SND ap) = dyho (FST(aq:int#int)) (SND aq))`
  ASSUME_TAC THENL
   [DISCH_TAC THEN FIRST_X_ASSUM(STRIP_ASSUME_TAC o MATCH_MP DYHO_INJ) THEN
    UNDISCH_TAC `~(ap:int#int = aq)` THEN REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[GSYM PAIR] THEN ASM_REWRITE_TAC[PAIR_EQ];
    MP_TAC(ISPECL [`P:(int#int#int)->bool`; `FST(ap:int#int)`;
      `FST(aq:int#int)`;
                   `SND(ap:int#int)`; `SND(aq:int#int)`] KCOVER_DISJOINT) THEN
    ASM_REWRITE_TAC[DISJOINT] THEN SET_TAC[]]);;

(* K1e reindex: the vsum over the IMAGE family collapses (via VSUM_IMAGE_    *)
(* NONZERO) to a vsum over the index set S, because distinct cover pairs     *)
(* give disjoint pieces, so any collision forces an empty piece with zero    *)
(* integral.                                                                 *)
let REGION_VSUM_REINDEX = prove
 (`!(E:real->bool) (hh:real->real) t (P:(int#int#int)->bool)
   (S:(int#int)->bool).
     real_lebesgue_measurable E /\ hh real_measurable_on (:real) /\
     FINITE S /\ (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap))
     ==> vsum (IMAGE (\ap. IMAGE lift ({x | x IN E /\ hh x IN tile_Jr t} INTER
                   dyho (FST ap) (SND ap))) S)
              (\s. integral s (\z. phi_sigma t carleson_phi (drop z)))
         = vsum S (\ap. integral (IMAGE lift ({x | x IN E /\ hh x IN tile_Jr t}
           INTER
                   dyho (FST ap) (SND ap)))
                  (\z. phi_sigma t carleson_phi (drop z)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\s:real^1->bool. integral s (\z. phi_sigma t carleson_phi (drop z))`;
    `\ap. IMAGE lift ({x | x IN E /\ hh x IN tile_Jr t} INTER
             dyho (FST ap) (SND ap))`;
    `S:(int#int)->bool`] VSUM_IMAGE_NONZERO) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`ap:int#int`; `aq:int#int`] THEN
    REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `({x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST(ap:int#int)) (SND ap))
       INTER
      ({x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST(aq:int#int)) (SND aq))
        = {}`
     ASSUME_TAC THENL
     [MATCH_MP_TAC KCOVER_PIECE_DISJOINT THEN
      EXISTS_TAC `P:(int#int#int)->bool` THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `{x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST(ap:int#int)) (SND ap) =
      {x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST(aq:int#int)) (SND aq)`
     ASSUME_TAC THENL
     [ASM_MESON_TAC[INJECTIVE_IMAGE; LIFT_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE lift ({x | x IN E /\ hh x IN tile_Jr t} INTER dyho
       (FST(ap:int#int)) (SND ap)) = {}`
     (fun th -> REWRITE_TAC[th; INTEGRAL_EMPTY]) THEN
    REWRITE_TAC[IMAGE_EQ_EMPTY] THEN
    UNDISCH_TAC
     `({x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST(ap:int#int)) (SND ap))
       INTER
      ({x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST(aq:int#int)) (SND aq))
        = {}` THEN
    ASM_REWRITE_TAC[INTER_IDEMPOT] THEN SIMP_TAC[];
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]]);;

(* K1e core: over a FINITE cover S of cover pairs, the finite-partial-cover  *)
(* tile integral = vsum over S of the piecewise integrals region INTER dyho. *)
(* = INTEGRAL_UNIONS_FINITE_C (finite pairwise-negligible union) + REINDEX.  *)
let REGION_FINITE_DECOMP = prove
 (`!(E:real->bool) (hh:real->real) t (P:(int#int#int)->bool)
   (S:(int#int)->bool).
     real_lebesgue_measurable E /\ hh real_measurable_on (:real) /\
     FINITE S /\ (!ap. ap IN S ==> in_kcover P (FST ap) (SND ap))
     ==> integral (IMAGE lift ({x | x IN E /\ hh x IN tile_Jr t} INTER
                   UNIONS {dyho (FST ap) (SND ap) | ap IN S}))
                  (\z. phi_sigma t carleson_phi (drop z))
         = vsum S (\ap. integral (IMAGE lift ({x | x IN E /\ hh x IN tile_Jr t}
           INTER
                   dyho (FST ap) (SND ap)))
                  (\z. phi_sigma t carleson_phi (drop z)))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[GSYM LIFT_REGION_COVER_UNIONS] THEN
    REWRITE_TAC[SIMPLE_IMAGE] THEN
  W(MP_TAC o PART_MATCH (lhs o rand) INTEGRAL_UNIONS_FINITE_C o lhs o snd) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[FINITE_IMAGE] THEN CONJ_TAC THENL
     [REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `ap:int#int` THEN
       DISCH_TAC THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC PHISIG_ABSINT_LEBESGUE THEN
      MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
       [MATCH_MP_TAC REGION_LEBESGUE THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
        REWRITE_TAC[DYHO_MEASURABLE]];
      REWRITE_TAC[IMP_CONJ; RIGHT_FORALL_IMP_THM; FORALL_IN_IMAGE] THEN
      X_GEN_TAC `ap:int#int` THEN DISCH_TAC THEN
        REWRITE_TAC[FORALL_IN_IMAGE] THEN
      X_GEN_TAC `aq:int#int` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(ap:int#int = aq)` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `({x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST(ap:int#int)) (SND
         ap)) INTER
        ({x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST(aq:int#int)) (SND
          aq)) = {}`
       ASSUME_TAC THENL
       [MATCH_MP_TAC KCOVER_PIECE_DISJOINT THEN
        EXISTS_TAC `P:(int#int#int)->bool` THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `IMAGE lift ({x | x IN E /\ hh x IN tile_Jr t} INTER dyho
         (FST(ap:int#int)) (SND ap)) INTER
        IMAGE lift ({x | x IN E /\ hh x IN tile_Jr t} INTER dyho
          (FST(aq:int#int)) (SND aq)) =
        IMAGE lift (({x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST ap) (SND
          ap)) INTER
                    ({x | x IN E /\ hh x IN tile_Jr t} INTER dyho (FST aq) (SND
                      aq)))`
       SUBST1_TAC THENL
       [MATCH_MP_TAC(GSYM IMAGE_INTER_INJ) THEN REWRITE_TAC[LIFT_EQ];
        ASM_REWRITE_TAC[IMAGE_CLAUSES; NEGLIGIBLE_EMPTY]]];
    DISCH_THEN SUBST1_TAC THEN
    MP_TAC(ISPECL [`E:real->bool`; `hh:real->real`; `t:int#int#int`;
                   `P:(int#int#int)->bool`; `S:(int#int)->bool`]
      REGION_VSUM_REINDEX) THEN
    ASM_REWRITE_TAC[]]);;

(* Limit-inheritance: a sequential limit inherits a uniform upper bound.     *)
let SEQ_LE_LIMIT = prove
 (`!(gg:num->real) l b. (gg ---> l) sequentially /\ (!n. gg n <= b) ==> l <=
   b`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`sequentially`; `gg:num->real`; `l:real`; `b:real`]
    REALLIM_UBOUND) THEN
  ASM_REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY; EVENTUALLY_SEQUENTIALLY] THEN
  EXISTS_TAC `0` THEN ASM_SIMP_TAC[]);;

(* The cover-cell family reindexes cleanly through enum, over any index set  *)
(* J.                                                                        *)
let COVER_ENUM_REINDEX = prove
 (`!(enum:num->int#int) (J:num->bool).
     {dyho (FST ap) (SND ap) | ap IN IMAGE enum J} =
     {dyho (FST(enum m)) (SND(enum m)) | m IN J}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[SIMPLE_IMAGE; GSYM IMAGE_o; o_DEF]);;

(* K1e limit: for finite P, the sum of norms over the finite-partial-cover   *)
(* tile                                                                      *)
(* integrals converges to the sum over the full-region tile integrals.  Via  *)
(* REALLIM_SUM over P; each summand converges by                             *)
(* LIM_COMPLEX_LMUL(REGION_INTEGRAL_                                         *)
(* LIMIT) + LIM_NORM + TENDSTO_REAL.                                         *)
let SUM_NORM_REGION_LIMIT = prove
 (`!(cf:(int#int#int)->complex) E (h:real->real) (P:(int#int#int)->bool) enum.
      FINITE P /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      UNIONS {dyho (FST(enum m)) (SND(enum m)) | m IN (:num)} = (:real)
      ==> ((\n. sum P (\s. norm(cf s *
                integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                     UNIONS {dyho (FST(enum m)) (SND(enum m)) | m IN 0..n}))
                     (\z. phi_sigma s carleson_phi (drop z)))))
           ---> sum P (\s. norm(cf s *
                integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z))))) sequentially`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REALLIM_SUM THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  REWRITE_TAC[TENDSTO_REAL; o_DEF] THEN
  MATCH_MP_TAC LIM_NORM THEN
  MATCH_MP_TAC LIM_COMPLEX_LMUL THEN
  MP_TAC(ISPECL [`(\x. Cx(&0)):real->complex`; `E:real->bool`; `h:real->real`;
                 `s:int#int#int`;
                   `enum:num->int#int`] REGION_INTEGRAL_LIMIT) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* CARLESON_286L (full-region form; Fremlin 286L).  The correlation sum over *)
(* the tree P, with the tile integrals taken over the FULL region            *)
(* E cap g^-1[Jr_s] (unbounded), is bounded by C7 * energy * mass * 2^{-kt}. *)
(* This is what 286M consumes.  Upgrades CARLESON_286L_FINITE (finite S) to  *)
(* the infinite maximal cover via the K1 finite-reduction: enumerate the     *)
(* cover-index set (COUNTABLE_AS_IMAGE), decompose each full-region integral *)
(* as                                                                        *)
(* the limit of finite-partial-cover integrals (REGION_INTEGRAL_LIMIT),      *)
(* which                                                                     *)
(* each split as a vsum over the finite cover (REGION_FINITE_DECOMP) bounded *)
(* uniformly by CARLESON_286L_FINITE, and inherit the bound in the limit     *)
(* (SEQ_LE_LIMIT + SUM_NORM_REGION_LIMIT).                                   *)
(* ------------------------------------------------------------------------- *)
let CARLESON_286L = prove
 (`?C7. &0 <= C7 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) kt nt tau.
      FINITE P /\ ~(P = {}) /\ tile_k tau = kt /\
      (!s. s IN P ==> tile_le s tau) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!s. s IN P ==> tile_I s SUBSET dyho (--kt) nt) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum P (\s. norm(carleson_ip f s *
                integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z))))
          <= C7 * energy_f f P * mass_Eh E h P * &2 zpow (--kt)`,
  X_CHOOSE_THEN `C7:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "FIN"))
    CARLESON_286L_FINITE THEN
  EXISTS_TAC `C7:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `~({ap:int#int | in_kcover P (FST ap) (SND ap)} = {})` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MP_TAC(ISPEC `P:(int#int#int)->bool` KCOVER_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `&0`) THEN
    DISCH_THEN(X_CHOOSE_THEN `a:int` (X_CHOOSE_THEN
      `q:int` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `(a:int,q:int)` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?enum. {ap:int#int | in_kcover P (FST ap) (SND ap)} = IMAGE enum (:num)`
   (X_CHOOSE_TAC `enum:num->int#int`) THENL
   [MATCH_MP_TAC COUNTABLE_AS_IMAGE THEN
    ASM_REWRITE_TAC[KCOVER_INDEX_COUNTABLE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `UNIONS {dyho (FST(enum m)) (SND(enum m)) | m IN (:num)} = (:real)`
   ASSUME_TAC THENL
   [MP_TAC(ISPEC `P:(int#int#int)->bool` KCOVER_UNIONS_UNIV) THEN
    ASM_REWRITE_TAC[COVER_ENUM_REINDEX];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m:num. in_kcover P (FST(enum m)) (SND(enum m))`
   ASSUME_TAC THENL
   [GEN_TAC THEN
    UNDISCH_TAC `{ap:int#int | in_kcover P (FST ap) (SND ap)} = IMAGE enum
      (:num)` THEN
    REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_IMAGE; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPEC `(enum:num->int#int) m`) THEN
    REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `m:num` THEN REFL_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC SEQ_LE_LIMIT THEN
  EXISTS_TAC
   `\n. sum P (\s. norm(carleson_ip (f:real->complex) s *
          integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
               UNIONS {dyho (FST(enum m)) (SND(enum m)) | m IN 0..n}))
               (\z. phi_sigma s carleson_phi (drop z))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_NORM_REGION_LIMIT THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `n:num` THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `!s:int#int#int.
        integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
             UNIONS {dyho (FST(enum m)) (SND(enum m)) | m IN 0..n}))
             (\z. phi_sigma s carleson_phi (drop z)) =
        vsum (IMAGE enum (0..n))
          (\ap. integral (IMAGE lift ({x | x IN E /\ h x IN tile_Jr s} INTER
                dyho (FST ap) (SND ap)))
                (\z. phi_sigma s carleson_phi (drop z)))`
     (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN
      MP_TAC(ISPECL [`E:real->bool`; `h:real->real`; `s:int#int#int`;
                     `P:(int#int#int)->bool`;
                       `IMAGE (enum:num->int#int) (0..n)`]
        REGION_FINITE_DECOMP) THEN
      REWRITE_TAC[COVER_ENUM_REINDEX] THEN
      ANTS_TAC THENL
       [ASM_SIMP_TAC[FINITE_IMAGE; FINITE_NUMSEG] THEN
        REWRITE_TAC[FORALL_IN_IMAGE] THEN ASM_REWRITE_TAC[];
        DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC];
      ALL_TAC] THEN
    USE_THEN "FIN" (MP_TAC o SPECL
      [`f:real->complex`; `E:real->bool`; `h:real->real`;
        `P:(int#int#int)->bool`;
       `IMAGE (enum:num->int#int) (0..n)`; `kt:int`; `nt:int`;
         `tau:int#int#int`]) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[FINITE_IMAGE; FINITE_NUMSEG] THEN
      REWRITE_TAC[FORALL_IN_IMAGE] THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC]]);;

(* ========================================================================= *)
(* Fremlin 286M-286V: mass and energy budgets and the analytic endgame.      *)
(* ========================================================================= *)

(* The 286J mass-budget as a predicate on (f,E,h,C5): if mass_Eh E h P <=    *)
(* gam^2                                                                     *)
(* then a finite R0 removes enough that gam^2 sum_R0 muI <= C5 and the       *)
(* residual                                                                  *)
(* mass mass_Eh(P\R0+) <= gam^2/4. (Fremlin 286J with muE<=1 already         *)
(* applied.)                                                                 *)
let carleson_mass_budget = new_definition
 `carleson_mass_budget (f:real->complex) E (h:real->real) C5 <=>
    !P gam. FINITE P /\ &0 < gam /\
            (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
              /\
            mass_Eh E h P <= gam pow 2
            ==> ?R0. FINITE R0 /\
                     gam pow 2 * sum R0 (\t. &2 zpow (--(tile_k t))) <= C5 /\
                     (~(P DIFF tile_upset R0 = {})
                      ==> mass_Eh E h (P DIFF tile_upset R0) <= gam pow 2 /
                        &4)`;;

(* The 286K energy-budget as a predicate on (f,C6): energy_f f P <= gam      *)
(* yields a finite R1 with gam^2 sum_R1 muI <= C6 and energy_f(P\R1+) <=     *)
(* gam/2.                                                                    *)
let carleson_energy_budget = new_definition
 `carleson_energy_budget (f:real->complex) C6 <=>
    !P gam. FINITE P /\ &0 < gam /\ energy_f f P <= gam
            ==> ?R1. FINITE R1 /\
                     gam pow 2 * sum R1 (\t. &2 zpow (--(tile_k t))) <= C6 /\
                     energy_f f (P DIFF tile_upset R1) <= gam / &2`;;

(* energy of the empty tile-set is 0 (sup of the all-zero index set).        *)
let ENERGY_F_EMPTY = prove
 (`!f:real->complex. energy_f f {} = &0`,
  GEN_TAC THEN REWRITE_TAC[energy_f] THEN
  SUBGOAL_THEN `!t:int#int#int. {s | s IN {} /\ tile_ler s t} = {}`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN REWRITE_TAC[NOT_IN_EMPTY; EMPTY_GSPEC]; ALL_TAC] THEN
  REWRITE_TAC[SUM_CLAUSES; SQRT_0; REAL_MUL_RZERO] THEN
  SUBGOAL_THEN
    `{&0 | t:int#int#int | t IN (:int#int#int)} = {&0}` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_SING; IN_UNIV] THEN
    GEN_TAC THEN EQ_TAC THENL
     [STRIP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]];
    REWRITE_TAC[SUP_SING]]);;

(* 286M part (a): the single COMBINE step from the two budget predicates.    *)
(* Given both budgets, and sqrt(mass) + energy of P both <= gam, produce R   *)
(* with the combined budget gam^2 sum_R muI <= C5+C6, energy(P\R+)<=gam/2,   *)
(* and (guarded by nonemptiness, since mass_Eh is a sup)                     *)
(* sqrt(mass(P\R+))<=gam/2. The mass guard dodges the empty-sup: when P\R+   *)
(* empties, the iteration stops.                                             *)
let CARLESON_286M_STEP = prove
 (`!(f:real->complex) E (h:real->real) P gam C5 C6.
     carleson_mass_budget f E h C5 /\ carleson_energy_budget f C6 /\
     FINITE P /\ &0 < gam /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
     ~(P = {}) /\
     sqrt(mass_Eh E h P) <= gam /\ energy_f f P <= gam
     ==> ?R. FINITE R /\
             gam pow 2 * sum R (\t. &2 zpow (--(tile_k t))) <= C5 + C6 /\
             energy_f f (P DIFF tile_upset R) <= gam / &2 /\
             (~(P DIFF tile_upset R = {})
              ==> sqrt(mass_Eh E h (P DIFF tile_upset R)) <= gam / &2)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[carleson_mass_budget; carleson_energy_budget] THEN STRIP_TAC THEN
  SUBGOAL_THEN `mass_Eh E h P <= gam pow 2` ASSUME_TAC THENL
   [SUBGOAL_THEN `&0 <= mass_Eh E h P` ASSUME_TAC THENL
     [MATCH_MP_TAC MASS_EH_POS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `mass_Eh E h P = sqrt(mass_Eh E h P) pow 2` SUBST1_TAC THENL
     [ASM_SIMP_TAC[SQRT_POW_2]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_POW_LE2 THEN ASM_SIMP_TAC[SQRT_POS_LE];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`P:(int#int#int)->bool`; `gam:real`] o
    check (fun th -> can (find_term (fun t -> t = `mass_Eh`)) (concl th) &&
                     is_forall(concl th))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `R0:(int#int#int)->bool` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
    `energy_f (f:real->complex) (P DIFF tile_upset R0) <= gam` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
     EXISTS_TAC `energy_f (f:real->complex) P` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ENERGY_MONO THEN ASM_REWRITE_TAC[] THEN
    SET_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`P DIFF tile_upset R0:(int#int#int)->bool`;
    `gam:real`] o
    check (fun th -> can (find_term (fun t -> t = `energy_f`)) (concl th) &&
                     is_forall(concl th))) THEN
  ASM_SIMP_TAC[FINITE_DIFF] THEN
  DISCH_THEN(X_CHOOSE_THEN `R1:(int#int#int)->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `R0 UNION R1:(int#int#int)->bool` THEN
  REWRITE_TAC[FINITE_UNION] THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `gam pow 2 * (sum R0 (\t. &2 zpow (--(tile_k t))) +
                             sum R1 (\t:int#int#int. &2 zpow (--(tile_k t))))`
                               THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
      MATCH_MP_TAC SUM_UNION_LE_POS THEN ASM_REWRITE_TAC[] THEN
      REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_LE_INV_EQ] THEN
      MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
      REWRITE_TAC[REAL_ADD_LDISTRIB] THEN MATCH_MP_TAC REAL_LE_ADD2 THEN
      ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[TILE_UPSET_UNION_DIFF];
    DISCH_TAC THEN
    SUBGOAL_THEN `~(P DIFF tile_upset R0 = {})` ASSUME_TAC THENL
     [UNDISCH_TAC `~(P DIFF tile_upset (R0 UNION R1) = {})` THEN
      REWRITE_TAC[TILE_UPSET_UNION_DIFF] THEN SET_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `mass_Eh E h (P DIFF tile_upset R0) <= gam pow 2 / &4`
     ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `sqrt(gam pow 2 / &4)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SQRT_MONO_LE THEN
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `mass_Eh E h (P DIFF tile_upset R0)` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MASS_MONO THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[TILE_UPSET_UNION_DIFF] THEN SET_TAC[];
      SUBGOAL_THEN `gam pow 2 / &4 = (gam / &2) pow 2` SUBST1_TAC THENL
       [REWRITE_TAC[REAL_POW_DIV] THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
      MATCH_MP_TAC REAL_EQ_IMP_LE THEN MATCH_MP_TAC POW_2_SQRT THEN
      ASM_REAL_ARITH_TAC]]);;

(* tile_I tau is a dyho cell at scale --(tile_k tau) (its spatial index).    *)
let TILE_I_AS_DYHO = prove
 (`!tau:int#int#int. ?nt. tile_I tau = dyho (--(tile_k tau)) nt`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!k nI nJ. P ((k,nI,nJ):int#int#int)) ==> (!s. P s)`) THEN
  MAP_EVERY X_GEN_TAC [`k:int`;`nI:int`;`nJ:int`] THEN
  REWRITE_TAC[tile_I; tile_k] THEN EXISTS_TAC `nI:int` THEN REWRITE_TAC[]);;

(* 286M part (b), per-tree bound.  For the tree T_tau = {sigma in P :        *)
(* tile_le sigma tau} (sigma at-or-above tau), the correlation sum is        *)
(*   <= C7 * energy_f f P * mass_Eh E h P * 2^(-k_tau).                      *)
(* CARLESON_286L at (f, T_tau, k_tau, nI_tau, tau) bounds by the T_tau       *)
(* energy/mass;                                                              *)
(* ENERGY_MONO/MASS_MONO (T_tau SUBSET P) lift to P. Empty tree: LHS = 0 <=  *)
(* RHS.                                                                      *)
let CARLESON_286M_TREE = prove
 (`?C7. &0 <= C7 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) (tau:int#int#int).
      FINITE P /\ ~(P = {}) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum {s | s IN P /\ tile_le s tau}
            (\s. norm(carleson_ip f s *
                integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z))))
          <= C7 * energy_f f P * mass_Eh E h P * &2 zpow (--(tile_k tau))`,
  X_CHOOSE_THEN `C7:real` STRIP_ASSUME_TAC CARLESON_286L THEN
  EXISTS_TAC `C7:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC
   [`f:real->complex`; `E:real->bool`; `h:real->real`; `P:(int#int#int)->bool`;
    `tau:int#int#int`] THEN STRIP_TAC THEN
  ABBREV_TAC `Tt = {s:int#int#int | s IN P /\ tile_le s tau}` THEN
  SUBGOAL_THEN `FINITE(Tt:(int#int#int)->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "Tt" THEN ASM_SIMP_TAC[FINITE_RESTRICT]; ALL_TAC] THEN
  SUBGOAL_THEN `(Tt:(int#int#int)->bool) SUBSET P` ASSUME_TAC THENL
   [EXPAND_TAC "Tt" THEN SET_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `Tt:(int#int#int)->bool = {}` THENL
   [ASM_REWRITE_TAC[SUM_CLAUSES] THEN
    REPEAT(MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC) THENL
     [ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[ENERGY_F_POS];
      MATCH_MP_TAC MASS_EH_POS THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  X_CHOOSE_TAC `nt:int` (SPEC `tau:int#int#int` TILE_I_AS_DYHO) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `C7 * energy_f f (Tt:(int#int#int)->bool) * mass_Eh E h Tt *
    &2 zpow (--(tile_k tau))` THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPECL
      [`f:real->complex`; `E:real->bool`; `h:real->real`;
        `Tt:(int#int#int)->bool`;
       `tile_k(tau:int#int#int)`; `nt:int`; `tau:int#int#int`] o
      check(is_forall o concl)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [EXPAND_TAC "Tt" THEN REWRITE_TAC[IN_ELIM_THM] THEN SIMP_TAC[];
        X_GEN_TAC `s:int#int#int` THEN EXPAND_TAC "Tt" THEN
        REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
        MATCH_MP_TAC SUBSET_TRANS THEN
          EXISTS_TAC `tile_I(tau:int#int#int)` THEN
        CONJ_TAC THENL
         [UNDISCH_TAC `tile_le (s:int#int#int) tau` THEN
          REWRITE_TAC[tile_le] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[SUBSET_REFL]]];
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    SUBGOAL_THEN
      `energy_f f (Tt:(int#int#int)->bool) <= energy_f f P` ASSUME_TAC THENL
     [MATCH_MP_TAC ENERGY_MONO THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `mass_Eh E h (Tt:(int#int#int)->bool) <= mass_Eh E h P` ASSUME_TAC THENL
     [MATCH_MP_TAC MASS_MONO THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `&0 <= energy_f f (Tt:(int#int#int)->bool)` ASSUME_TAC THENL
     [ASM_SIMP_TAC[ENERGY_F_POS]; ALL_TAC] THEN
    SUBGOAL_THEN `&0 <= mass_Eh E h (Tt:(int#int#int)->bool)` ASSUME_TAC THENL
     [MATCH_MP_TAC MASS_EH_POS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_MUL2 THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
        REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
      REAL_ARITH_TAC]]);;

(* 286M part (b), single-level bound. The tiles removed at one stopping-time *)
(* level are P cap R+ (= P INTER tile_upset R); their correlation sum is     *)
(*   <= sum_{tau in R} C7 * energy_f f P * mass_Eh E h P * 2^(-k_tau).       *)
(* Cover P cap R+ by the trees {sigma in P : tile_le sigma tau} (tau in R):  *)
(* SUM_SUBSET (nonneg, subset) -> SUM_UNIONS_LE_SUM -> SUM_LE +              *)
(* CARLESON_286M_TREE.                                                       *)
let CARLESON_286M_LEVEL = prove
 (`?C7. &0 <= C7 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) R.
      FINITE P /\ ~(P = {}) /\ FINITE R /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
      ==> sum (P INTER tile_upset R)
            (\s. norm(carleson_ip f s *
                integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z))))
          <= sum R (\tau. C7 * energy_f f P * mass_Eh E h P *
                          &2 zpow (--(tile_k tau)))`,
  X_CHOOSE_THEN `C7:real` STRIP_ASSUME_TAC CARLESON_286M_TREE THEN
  EXISTS_TAC `C7:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC
   [`f:real->complex`; `E:real->bool`; `h:real->real`; `P:(int#int#int)->bool`;
    `R:(int#int#int)->bool`] THEN
  STRIP_TAC THEN
  ABBREV_TAC
   `phi = \s. norm(carleson_ip (f:real->complex) s *
                integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z)))` THEN
  SUBGOAL_THEN `!s:int#int#int. &0 <= phi s` ASSUME_TAC THENL
   [EXPAND_TAC "phi" THEN REWRITE_TAC[NORM_POS_LE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `P INTER tile_upset R SUBSET
    UNIONS (IMAGE (\tau. {s:int#int#int | s IN P /\ tile_le s tau}) R)`
   ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; tile_upset; IN_ELIM_THM; IN_UNIONS;
     IN_IMAGE] THEN
    REPEAT STRIP_TAC THEN
    EXISTS_TAC `{s:int#int#int | s IN P /\ tile_le s t}` THEN
    CONJ_TAC THENL
     [EXISTS_TAC `t:int#int#int` THEN
       REWRITE_TAC[]; REWRITE_TAC[IN_ELIM_THM]] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(UNIONS (IMAGE (\tau. {s:int#int#int | s IN P /\ tile_le s tau}) R))`
   ASSUME_TAC THENL
   [REWRITE_TAC[FINITE_UNIONS; FORALL_IN_IMAGE] THEN
    ASM_SIMP_TAC[FINITE_IMAGE; FINITE_RESTRICT]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum (UNIONS (IMAGE (\tau. {s:int#int#int | s IN P /\ tile_le s tau}) R))
        (phi:(int#int#int)->real)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_SUBSET THEN REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[FINITE_INTER];
      ASM_REWRITE_TAC[];
      X_GEN_TAC `x:int#int#int` THEN REWRITE_TAC[IN_DIFF] THEN ASM SET_TAC[];
      X_GEN_TAC `x:int#int#int` THEN DISCH_TAC THEN ASM_REWRITE_TAC[]];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC
     `sum R (\tau. sum {s:int#int#int | s IN P /\ tile_le s tau}
                       (phi:(int#int#int)->real))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUM_UNIONS_LE_SUM THEN
      ASM_SIMP_TAC[FINITE_RESTRICT]; ALL_TAC] THEN
    MATCH_MP_TAC SUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `tau:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    EXPAND_TAC "phi" THEN ASM_SIMP_TAC[]]);;

(* 286M part (b): after M stopping-time steps at gam=2^k, the residual P'    *)
(* has                                                                       *)
(* energy/mass down by 2^-M and the removed part is bounded by the geometric *)
(* partial sum.  Induction on the step-count M (no explicit sequence).       *)
let M286_STEPS = prove
 (`?C7. &0 <= C7 /\
   !M (f:real->complex) E h (P:(int#int#int)->bool) C5 C6 k.
      carleson_mass_budget f E h C5 /\ carleson_energy_budget f C6 /\
      &0 <= C5 /\ &0 <= C6 /\ FINITE P /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      energy_f f P <= &2 pow k /\ sqrt(mass_Eh E h P) <= &2 pow k
      ==> ?P'. P' SUBSET P /\ FINITE P' /\
               energy_f f P' <= &2 pow k * inv(&2) pow M /\
               (~(P' = {}) ==> sqrt(mass_Eh E h P') <= &2 pow k * inv(&2) pow
                 M) /\
               sum (P DIFF P')
                 (\s. norm(carleson_ip f s *
                     integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                          (\z. phi_sigma s carleson_phi (drop z))))
               <= C7 * (C5 + C6) *
                  sum {n | n < M} (\n. min (&2 pow k * inv(&2) pow n)
                                           (inv(&2 pow k) * &2 pow n))`,
  X_CHOOSE_THEN `C7:real` STRIP_ASSUME_TAC CARLESON_286M_LEVEL THEN
  EXISTS_TAC `C7:real` THEN ASM_REWRITE_TAC[] THEN INDUCT_TAC THENL
   [REPEAT STRIP_TAC THEN EXISTS_TAC `P:(int#int#int)->bool` THEN
    ASM_REWRITE_TAC[SUBSET_REFL; DIFF_EQ_EMPTY; SUM_CLAUSES; real_pow;
                    REAL_MUL_RID; CONJUNCT1 LT; EMPTY_GSPEC] THEN
    REWRITE_TAC[REAL_MUL_RZERO; REAL_LE_REFL];
    ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
   [`f:real->complex`; `E:real->bool`; `h:real->real`; `P:(int#int#int)->bool`;
    `C5:real`; `C6:real`; `k:num`] o
   check(fun th -> is_forall(concl th) &&
     can (find_term (fun tm -> tm = `carleson_mass_budget`)) (concl th))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `P1:(int#int#int)->bool` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `sum {n | n < SUC M} (\n. min (&2 pow k * inv(&2) pow n) (inv(&2 pow k) * &2
     pow n))
    = sum {n | n < M} (\n. min (&2 pow k * inv(&2) pow n) (inv(&2 pow k) * &2
      pow n))
      + min (&2 pow k * inv(&2) pow M) (inv(&2 pow k) * &2 pow M)`
   ASSUME_TAC THENL
   [SUBGOAL_THEN `{n | n < SUC M} = M INSERT {n | n < M}` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_INSERT; IN_ELIM_THM] THEN
       ARITH_TAC; ALL_TAC] THEN
    SIMP_TAC[SUM_CLAUSES; FINITE_NUMSEG_LT; IN_ELIM_THM; LT_REFL] THEN
    REWRITE_TAC[REAL_ADD_AC]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= &2 pow k * inv(&2) pow M` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THEN MATCH_MP_TAC REAL_POW_LE THEN
    TRY(MATCH_MP_TAC REAL_LE_INV) THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= inv(&2 pow k) * &2 pow M` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THEN
    TRY(MATCH_MP_TAC REAL_LE_INV) THEN MATCH_MP_TAC REAL_POW_LE THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 <= min (&2 pow k * inv(&2) pow M) (inv(&2 pow k) * &2 pow M)`
   ASSUME_TAC THENL [ASM_REWRITE_TAC[REAL_LE_MIN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&2 pow k * inv(&2) pow (SUC M) = (&2 pow k * inv(&2) pow M) / &2`
   ASSUME_TAC THENL
   [REWRITE_TAC[real_pow] THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  ASM_CASES_TAC `P1:(int#int#int)->bool = {}` THENL
   [(* P1 = {} : residual empty, removed part = P DIFF P1, extra term nonneg *)
    EXISTS_TAC `P1:(int#int#int)->bool` THEN
    ASM_REWRITE_TAC[EMPTY_SUBSET; FINITE_EMPTY] THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[ENERGY_F_EMPTY] THEN
      MATCH_MP_TAC REAL_LE_DIV THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `C7 * (C5 + C6) *
        sum {n | n < M} (\n. min (&2 pow k * inv(&2) pow n) (inv(&2 pow k) * &2
          pow n))` THEN
      CONJ_TAC THENL
       [FIRST_X_ASSUM(fun th -> if is_imp(concl th) then ALL_TAC else NO_TAC)
         THEN
        UNDISCH_TAC `sum (P DIFF P1)
          (\s. norm(carleson_ip f s *
              integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                   (\z. phi_sigma s carleson_phi (drop z))))
          <= C7 * (C5 + C6) *
             sum {n | n < M} (\n. min (&2 pow k * inv(&2) pow n) (inv(&2 pow k)
               * &2 pow n))` THEN
        ASM_REWRITE_TAC[DIFF_EMPTY];
        REWRITE_TAC[REAL_ADD_LDISTRIB] THEN
        MATCH_MP_TAC(REAL_ARITH `&0 <= e ==> x <= x + e`) THEN
        MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LE_ADD]]];
    (* P1 nonempty : apply STEP at gam = 2^k (1/2)^M                         *)
  SUBGOAL_THEN
    `sqrt(mass_Eh E h P1) <= &2 pow k * inv(&2) pow M` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MATCH_MP_TAC o check(fun th -> is_imp(concl th) &&
      can (find_term (fun tm -> tm = `mass_Eh`)) (concl th))) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 pow k * inv(&2) pow M` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_MUL THEN REWRITE_TAC[REAL_LT_POW2] THEN
    MATCH_MP_TAC REAL_POW_LT THEN MATCH_MP_TAC REAL_LT_INV THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`f:real->complex`; `E:real->bool`; `h:real->real`;
     `P1:(int#int#int)->bool`;
    `&2 pow k * inv(&2) pow M`; `C5:real`; `C6:real`] CARLESON_286M_STEP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `R:(int#int#int)->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `P1 DIFF tile_upset R:(int#int#int)->bool` THEN
  SUBGOAL_THEN
    `(P1 DIFF tile_upset R:(int#int#int)->bool) SUBSET P` ASSUME_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `P1:(int#int#int)->bool` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `FINITE(P1 DIFF tile_upset R:(int#int#int)->bool)` ASSUME_TAC THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `P:(int#int#int)->bool` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `P DIFF (P1 DIFF tile_upset R) =
    (P DIFF P1) UNION (P1 INTER tile_upset R)` SUBST1_TAC THENL
   [ASM SET_TAC[]; ALL_TAC] THEN
  W(MP_TAC o PART_MATCH (lhand o rand) SUM_UNION o lhand o snd) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[FINITE_DIFF; FINITE_INTER] THEN
    REWRITE_TAC[DISJOINT] THEN ASM SET_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[REAL_ADD_LDISTRIB] THEN
  MATCH_MP_TAC REAL_LE_ADD2 THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum R (\tau. C7 * energy_f f P1 * mass_Eh E h P1 *
                          &2 zpow (--(tile_k tau)))` THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPECL
      [`f:real->complex`; `E:real->bool`; `h:real->real`;
        `P1:(int#int#int)->bool`;
       `R:(int#int#int)->bool`] o
      check(fun th -> is_forall(concl th) &&
        can (find_term (fun tm -> tm = `tile_upset`)) (concl th))) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[SUM_LMUL] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `C7 * ((C5 + C6) * min (inv(&2 pow k * inv(&2) pow M))
                                      (&2 pow k * inv(&2) pow M))` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MATCH_MP_TAC LEVEL_PROD_BOUND THEN REPEAT CONJ_TAC THENL
       [ASM_SIMP_TAC[ENERGY_F_POS];
        MATCH_MP_TAC MASS_EH_POS THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC SUM_POS_LE THEN REWRITE_TAC[REAL_LE_INV_EQ] THEN
        REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC MASS_LE_1 THEN ASM_REWRITE_TAC[];
        SUBGOAL_THEN
          `mass_Eh E h P1 = sqrt(mass_Eh E h P1) pow 2` SUBST1_TAC THENL
         [MATCH_MP_TAC(GSYM SQRT_POW_2) THEN MATCH_MP_TAC MASS_EH_POS THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MATCH_MP_TAC REAL_POW_LE2 THEN CONJ_TAC THENL
         [MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC MASS_EH_POS THEN
           ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[]];
        ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]];
      SUBGOAL_THEN
       `min (inv (&2 pow k * inv (&2) pow M)) (&2 pow k * inv (&2) pow M) =
        min (&2 pow k * inv (&2) pow M) (inv (&2 pow k) * &2 pow M)`
       SUBST1_TAC THENL
       [GEN_REWRITE_TAC (RAND_CONV) [REAL_MIN_SYM] THEN
        AP_THM_TAC THEN AP_TERM_TAC THEN
        REWRITE_TAC[REAL_INV_MUL; REAL_INV_INV; GSYM REAL_POW_INV;
          REAL_INV_POW];
        REWRITE_TAC[REAL_LE_REFL]]]]]);;


(* Archimedean choice for the 286M finish: for finite P, eventually          *)
(* 2^k(1/2)^M                                                                *)
(* is below energy_f f {sigma} for EVERY nonzero-coefficient sigma in P      *)
(* (there                                                                    *)
(* are finitely many, with a positive minimum energy). Feeds the finish: the *)
(* M-step residual then has all coefficients zero, so its correlation sum is *)
(* 0.                                                                        *)
let M286_ARCH = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) k.
     FINITE P
     ==> ?M. !s. s IN P /\ ~(carleson_ip f s = Cx(&0))
                 ==> &2 pow k * inv(&2) pow M < energy_f f {s}`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `Pnz = {s:int#int#int | s IN P /\ ~(carleson_ip f s = Cx(&0))}`
    THEN
  SUBGOAL_THEN `FINITE(Pnz:(int#int#int)->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "Pnz" THEN ASM_SIMP_TAC[FINITE_RESTRICT]; ALL_TAC] THEN
  ASM_CASES_TAC `Pnz:(int#int#int)->bool = {}` THENL
   [EXISTS_TAC `0` THEN X_GEN_TAC `s:int#int#int` THEN
    UNDISCH_TAC `Pnz:(int#int#int)->bool = {}` THEN EXPAND_TAC "Pnz" THEN
    REWRITE_TAC[EXTENSION; NOT_IN_EMPTY; IN_ELIM_THM] THEN
    DISCH_THEN(MP_TAC o SPEC `s:int#int#int`) THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `!s. s IN Pnz ==> &0 < energy_f (f:real->complex) {s}` ASSUME_TAC THENL
   [X_GEN_TAC `s:int#int#int` THEN EXPAND_TAC "Pnz" THEN
     REWRITE_TAC[IN_ELIM_THM] THEN
    STRIP_TAC THEN REWRITE_TAC[ENERGY_SING] THEN MATCH_MP_TAC REAL_LT_MUL THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LT THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      REWRITE_TAC[NORM_POS_LT; COMPLEX_VEC_0] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ABBREV_TAC `e0 = inf (IMAGE (\s. energy_f (f:real->complex) {s}) Pnz)` THEN
  SUBGOAL_THEN `&0 < e0` ASSUME_TAC THENL
   [EXPAND_TAC "e0" THEN
    MP_TAC(ISPEC `IMAGE (\s. energy_f (f:real->complex) {s}) Pnz` INF_FINITE)
      THEN
    ASM_SIMP_TAC[FINITE_IMAGE; IMAGE_EQ_EMPTY] THEN
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `s0:int#int#int` STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPEC `&2 pow k / e0` REAL_ARCH_POW2) THEN
  DISCH_THEN(X_CHOOSE_TAC `M:num`) THEN EXISTS_TAC `M:num` THEN
  X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
  MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `e0:real` THEN CONJ_TAC THENL
   [SUBGOAL_THEN `&0 < &2 pow M` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
      `&2 pow k * inv(&2) pow M = &2 pow k / &2 pow M` SUBST1_TAC THENL
     [REWRITE_TAC[real_div; REAL_POW_INV]; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LT_LDIV_EQ] THEN
    UNDISCH_TAC `&2 pow k / e0 < &2 pow M` THEN
    ASM_SIMP_TAC[REAL_LT_LDIV_EQ] THEN REAL_ARITH_TAC;
    EXPAND_TAC "e0" THEN
    MP_TAC(ISPEC `IMAGE (\s. energy_f (f:real->complex) {s}) Pnz` INF_FINITE)
      THEN
    ASM_SIMP_TAC[FINITE_IMAGE; IMAGE_EQ_EMPTY] THEN
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN REWRITE_TAC[FORALL_IN_IMAGE] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    UNDISCH_TAC `{s:int#int#int | s IN P /\ ~(carleson_ip f s = Cx(&0))} = Pnz`
      THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[IN_ELIM_THM] THEN
      ASM_REWRITE_TAC[]]);;

(* CARLESON_286M for finite P: sum over P of |<f|phi>* int| <= C8*(C5+C6),   *)
(* C8=4C7. M286_STEPS after M steps + M286_ARCH pick M so residual coeffs    *)
(* all vanish (sum_{P'}=0) + TWO_SIDED_MIN_GEOM bounds the geometric partial *)
(* sum by 4.                                                                 *)
let CARLESON_286M_FINITE = prove
 (`?C8. &0 <= C8 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) C5 C6 k.
      carleson_mass_budget f E h C5 /\ carleson_energy_budget f C6 /\
      &0 <= C5 /\ &0 <= C6 /\ FINITE P /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real) /\
      energy_f f P <= &2 pow k /\ sqrt(mass_Eh E h P) <= &2 pow k
      ==> sum P (\s. norm(carleson_ip f s *
                integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z))))
          <= C8 * (C5 + C6)`,
  X_CHOOSE_THEN `C7:real` STRIP_ASSUME_TAC M286_STEPS THEN
  EXISTS_TAC `&4 * C7` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`; `P:(int#int#int)->bool`;
    `k:num`] M286_ARCH) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `M:num`) THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
   [`M:num`; `f:real->complex`; `E:real->bool`; `h:real->real`;
     `P:(int#int#int)->bool`;
    `C5:real`; `C6:real`; `k:num`] o check(is_forall o concl)) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `P':(int#int#int)->bool` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `sum P' (\s. norm(carleson_ip (f:real->complex) s *
                integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z)))) = &0`
   ASSUME_TAC THENL
   [MATCH_MP_TAC SUM_EQ_0 THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    BETA_TAC THEN
    SUBGOAL_THEN `carleson_ip (f:real->complex) s = Cx(&0)`
     (fun th -> REWRITE_TAC[th; COMPLEX_MUL_LZERO; COMPLEX_NORM_0]) THEN
    REWRITE_TAC[GSYM COMPLEX_NORM_ZERO] THEN
    MATCH_MP_TAC(REAL_ARITH `~(&0 < n) /\ &0 <= n ==> n = &0`) THEN
    REWRITE_TAC[NORM_POS_LE] THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `&2 pow k * inv(&2) pow M < energy_f (f:real->complex) {s}` MP_TAC THENL
     [FIRST_X_ASSUM(MATCH_MP_TAC o check(fun th -> is_forall(concl th) &&
        can (find_term (fun tm -> tm = `energy_f`)) (concl th))) THEN
      CONJ_TAC THENL
       [ASM_MESON_TAC[SUBSET];
        REWRITE_TAC[GSYM COMPLEX_NORM_ZERO] THEN ASM_REAL_ARITH_TAC];
      SUBGOAL_THEN
        `energy_f (f:real->complex) {s} <= energy_f f P'` MP_TAC THENL
       [MATCH_MP_TAC ENERGY_MONO THEN
         ASM_REWRITE_TAC[SING_SUBSET]; ALL_TAC] THEN
      ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `P = (P DIFF P') UNION P':(int#int#int)->bool` SUBST1_TAC THENL
   [ASM SET_TAC[]; ALL_TAC] THEN
  W(MP_TAC o PART_MATCH (lhand o rand) SUM_UNION o lhand o snd) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[FINITE_DIFF] THEN REWRITE_TAC[DISJOINT] THEN SET_TAC[];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[REAL_ADD_RID] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `C7 * (C5 + C6) *
    sum {n | n < M} (\n. min (&2 pow k * inv(&2) pow n) (inv(&2 pow k) * &2 pow
      n))` THEN
  CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `sum {n | n < M} (\n. min (&2 pow k * inv(&2) pow n) (inv(&2 pow k) * &2 pow
     n))
    <= &4`
   ASSUME_TAC THENL
   [MATCH_MP_TAC TWO_SIDED_MIN_GEOM THEN
     REWRITE_TAC[FINITE_NUMSEG_LT]; ALL_TAC] THEN
  SUBGOAL_THEN `(&4 * C7) * (C5 + C6) = (C7 * (C5 + C6)) * &4` SUBST1_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_ASSOC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ASM_REWRITE_TAC[]]);;

(* 286M part (c): the Lacey-Thiele lemma for the FULL tile set. For any      *)
(* finite                                                                    *)
(* P (whence for the whole countable Q, taking sups), the correlation sum is *)
(* <= C8*(C5+C6) -- no energy/mass normalization hypothesis: each finite P   *)
(* picks                                                                     *)
(* its own k with energy_f f P <= 2^k and sqrt(mass_Eh E h P) <= 2^k (energy *)
(* is                                                                        *)
(* finite by ENERGY_LE, mass <= 1 by MASS_LE_1, so REAL_ARCH_POW2 supplies   *)
(* k).                                                                       *)
let CARLESON_286M = prove
 (`?C8. &0 <= C8 /\
   !(f:real->complex) E h (P:(int#int#int)->bool) C5 C6.
      carleson_mass_budget f E h C5 /\ carleson_energy_budget f C6 /\
      &0 <= C5 /\ &0 <= C6 /\ FINITE P /\
      (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
      real_lebesgue_measurable E /\ h real_measurable_on (:real)
      ==> sum P (\s. norm(carleson_ip f s *
                integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z))))
          <= C8 * (C5 + C6)`,
  X_CHOOSE_THEN `C8:real` STRIP_ASSUME_TAC CARLESON_286M_FINITE THEN
  EXISTS_TAC `C8:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `P:(int#int#int)->bool = {}` THENL
   [ASM_REWRITE_TAC[SUM_CLAUSES] THEN MATCH_MP_TAC REAL_LE_MUL THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?k:num. energy_f (f:real->complex) P <= &2 pow k /\
            sqrt(mass_Eh E h P) <= &2 pow k` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPEC `energy_f (f:real->complex) P + sqrt(mass_Eh E h P)`
     REAL_ARCH_POW2) THEN
    DISCH_THEN(X_CHOOSE_TAC `k:num`) THEN EXISTS_TAC `k:num` THEN
    SUBGOAL_THEN `&0 <= energy_f (f:real->complex) P` ASSUME_TAC THENL
     [ASM_SIMP_TAC[ENERGY_F_POS]; ALL_TAC] THEN
    SUBGOAL_THEN `&0 <= sqrt(mass_Eh E h P)` ASSUME_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC MASS_EH_POS THEN
       ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
   [`f:real->complex`; `E:real->bool`; `h:real->real`; `P:(int#int#int)->bool`;
    `C5:real`; `C6:real`; `k:num`] o check(is_forall o concl)) THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* 286N (Fremlin): drop the muE<=1, ||f||=1 normalization from 286M via the  *)
(* dilation sigma |-> sigma* = (k_sigma+kk, nI, nJ).  Foundational pieces.   *)
(* ========================================================================= *)

(* Tile-star scaling arithmetic: sigma* = (k+kk, nI, nJ) shifts the scale by *)
(* kk, dilating the spatial midpoint by 2^-kk and the frequency midpoint by  *)
(* 2^kk (and mJ = 2^k by 2^kk).                                              *)
let STARARITH = prove
 (`!(kk:int) k nI nJ.
    &2 zpow (tile_k (k + kk, nI, nJ)) = &2 zpow kk * &2 zpow (tile_k(k,nI,nJ))
      /\
    tile_xmid (k + kk, nI, nJ) = &2 zpow (--kk) * tile_xmid(k,nI,nJ) /\
    tile_ymid (k + kk, nI, nJ) = &2 zpow kk * tile_ymid(k,nI,nJ)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_k; tile_xmid; tile_ymid; dyho_mid] THEN
  SUBGOAL_THEN
   `&2 zpow (k + kk) = &2 zpow kk * &2 zpow k /\
    &2 zpow (--(k + kk)) = &2 zpow (--kk) * &2 zpow (--k) /\
    &2 zpow ((k + kk) - &1) = &2 zpow kk * &2 zpow (k - &1)`
   STRIP_ASSUME_TAC THENL
   [SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ] THEN
    REPEAT CONJ_TAC THEN AP_TERM_TAC THEN INT_ARITH_TAC;
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[REAL_MUL_AC]]);;

(* Two REAL_FIELD arithmetic facts (universally quantified so MATCH_MP_TAC   *)
(* can instantiate them to the abbreviated local constants).                 *)
let ARGEQ_LEMMA = prove
 (`!A B M x x0. A * B = &1 /\ &0 < A
     ==> (A * M) * (x - B * x0):real = M * (A * x - x0)`,
  REPEAT GEN_TAC THEN CONV_TAC REAL_FIELD);;

let SQRTEQ_LEMMA = prove
 (`!A B M. A * B = &1 /\ &0 < A ==> M:real = B * (A * M)`,
  REPEAT GEN_TAC THEN CONV_TAC REAL_FIELD);;

(* The phi dilation identity (Fremlin 286N core):  phi_sigma(2^kk x) =       *)
(* 2^{-kk/2} phi_{sigma*}(x)  where sigma* = (k+kk, nI, nJ).                 *)
let PHISIG_DILATE = prove
 (`!(phi:real->complex) kk k nI nJ x.
     phi_sigma (k,nI,nJ) phi (&2 zpow kk * x) =
     Cx(sqrt(&2 zpow (--kk))) * phi_sigma (k + kk, nI, nJ) phi x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[phi_sigma; phimst] THEN
  MP_TAC(SPECL [`kk:int`;`k:int`;`nI:int`;`nJ:int`] STARARITH) THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `A = &2 zpow kk` THEN ABBREV_TAC `B = &2 zpow (--kk)` THEN
  ABBREV_TAC `M = &2 zpow (tile_k(k,nI,nJ))` THEN
  ABBREV_TAC `y0 = tile_ymid(k,nI,nJ)` THEN
    ABBREV_TAC `x0 = tile_xmid(k,nI,nJ)` THEN
  SUBGOAL_THEN `&0 < A /\ &0 < B` STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A"; "B"] THEN CONJ_TAC THEN
     MATCH_MP_TAC REAL_ZPOW_LT THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `A * B = &1` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["A"; "B"] THEN
    SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ; INT_ADD_RINV;
      REAL_ZPOW_0];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(A * M) * (x - B * x0):real = M * (A * x - x0)` SUBST1_TAC THENL
   [MATCH_MP_TAC ARGEQ_LEMMA THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `sqrt M = sqrt B * sqrt(A * M)` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM SQRT_MUL] THEN AP_TERM_TAC THEN
    MATCH_MP_TAC SQRTEQ_LEMMA THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `Cx(A * y0) * Cx x = Cx y0 * Cx(A * x)` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[CX_MUL; COMPLEX_MUL_AC]);;

(* ========================================================================= *)
(* 286N dilation infrastructure (Fremlin 286N: drop muE<=1, ||f||=1 via the  *)
(* tile permutation sigma|->sigma* + the L^2 dilation                        *)
(* ftilde(x)=2^{kk/2}f(2^{kk}x)).                                            *)
(* ========================================================================= *)

(* Measurability preserved under affine reparametrization on the line.  The  *)
(* approximating sequence g_n(cz+b) is continuous and converges off the      *)
(* affine                                                                    *)
(* preimage of the negligible exceptional set (negligible: linear image +    *)
(* translation).                                                             *)
let MEASURABLE_ON_DILATE = prove
 (`!(f:real^1->real^N) c b. ~(c = &0) /\ f measurable_on (:real^1)
     ==> (\z. f(c % z + b)) measurable_on (:real^1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[measurable_on; IN_UNIV] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (X_CHOOSE_THEN `k:real^1->bool` (X_CHOOSE_THEN `g:num->real^1->real^N`
      STRIP_ASSUME_TAC))) THEN
  EXISTS_TAC `IMAGE (\z:real^1. inv c % (z - b)) k` THEN
  EXISTS_TAC `\n z. (g:num->real^1->real^N) n (c % z + b)` THEN
  REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\z:real^1. inv c % (z - b)) =
      (\y. (--(inv c % b)) + y) o (\z. inv c % z)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN GEN_TAC THEN
      REWRITE_TAC[VECTOR_SUB_LDISTRIB] THEN VECTOR_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[IMAGE_o] THEN MATCH_MP_TAC NEGLIGIBLE_TRANSLATION THEN
    MATCH_MP_TAC NEGLIGIBLE_LINEAR_IMAGE THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[linear] THEN CONJ_TAC THEN VECTOR_ARITH_TAC;
    GEN_TAC THEN
    SUBGOAL_THEN
      `(\z:real^1. g (n:num) (c % z + b)) =
       (g n:real^1->real^N) o (\z. c % z + b)`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
     [SIMP_TAC[CONTINUOUS_ON_ADD; CONTINUOUS_ON_CMUL; CONTINUOUS_ON_ID;
       CONTINUOUS_ON_CONST];
      ASM_MESON_TAC[CONTINUOUS_ON_SUBSET; SUBSET_UNIV]];
    X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `c % x + b:real^1`) THEN
    ANTS_TAC THENL
     [DISCH_TAC THEN
       UNDISCH_TAC `~(x IN IMAGE (\z:real^1. inv c % (z - b)) k)` THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `c % x + b:real^1` THEN
        ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `inv c % ((c % x + b) - b):real^1 = (inv c * c) % x` SUBST1_TAC THENL
       [VECTOR_ARITH_TAC; ALL_TAC] THEN
      ASM_SIMP_TAC[REAL_MUL_LINV; VECTOR_MUL_LID];
      REWRITE_TAC[]]]);;

(* The normalized dilate has the same L^2 norm-square integral (Jacobian     *)
(* 2^{-kk} cancels the sqrt(c)^2 = c prefactor).                             *)
let L2_DILATE_NORMSQ = prove
 (`!(ff:real^1->complex) c. &0 < c /\
     (\z. lift(norm(ff z) pow 2)) integrable_on (:real^1)
     ==> integral (:real^1)
           (\z. lift(norm(Cx(sqrt c) * ff(c % z)) pow 2)) =
         integral (:real^1) (\z. lift(norm(ff z) pow 2))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `gg = \z:real^1. lift(norm((ff:real^1->complex) z) pow 2)` THEN
  SUBGOAL_THEN
   `(\z:real^1. lift(norm(Cx(sqrt c) * (ff:real^1->complex)(c % z)) pow 2)) =
    (\z. c % (gg:real^1->real^1) (c % z + vec 0))`
   SUBST1_TAC THENL
   [EXPAND_TAC "gg" THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN
    REWRITE_TAC[VECTOR_ADD_RID] THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX; REAL_POW_MUL] THEN
    REWRITE_TAC[GSYM LIFT_CMUL] THEN AP_TERM_TAC THEN
    SUBGOAL_THEN `abs(sqrt c) pow 2 = c` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_POW2_ABS] THEN MATCH_MP_TAC SQRT_POW_2 THEN
      ASM_REAL_ARITH_TAC;
      REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(gg:real^1->real^1) integrable_on (:real^1)` ASSUME_TAC THENL
   [EXPAND_TAC "gg" THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[INTEGRAL_CMUL; INTEGRABLE_DILATE_UNIV; REAL_LT_IMP_NZ] THEN
  ASM_SIMP_TAC[INTEGRAL_DILATE_UNIV; REAL_LT_IMP_NZ] THEN
  REWRITE_TAC[VECTOR_MUL_ASSOC] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < c ==> abs c = c`; REAL_MUL_RINV;
    REAL_LT_IMP_NZ;
               VECTOR_MUL_LID]);;

(* Hence the normalized dilate stays in L^2.                                 *)
let L2_DILATE_LSPACE = prove
 (`!(ff:real^1->complex) c. &0 < c /\ ff IN lspace (:real^1) (&2)
     ==> (\z. Cx(sqrt c) * ff(c % z)) IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lspace; IN_ELIM_THM] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[lspace; IN_ELIM_THM; RPOW_POW]) THEN
  FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC) THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`\z:real^1. Cx(sqrt c)`;
     `\z:real^1. (ff:real^1->complex)(c % z)`;
                   `(:real^1)`] MEASURABLE_ON_COMPLEX_MUL) THEN
    REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    REWRITE_TAC[MEASURABLE_ON_CONST] THEN
    SUBGOAL_THEN
      `(\z:real^1. (ff:real^1->complex)(c % z)) = (\z. ff(c % z + vec 0))`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; VECTOR_ADD_RID]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_ON_DILATE THEN ASM_SIMP_TAC[REAL_LT_IMP_NZ];
    REWRITE_TAC[RPOW_POW] THEN
    SUBGOAL_THEN
     `(\z:real^1. lift(norm(Cx(sqrt c) * (ff:real^1->complex)(c % z)) pow 2)) =
      (\z. c % (\w. lift(norm(ff w) pow 2)) (c % z + vec 0))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN
      REWRITE_TAC[VECTOR_ADD_RID; COMPLEX_NORM_MUL; COMPLEX_NORM_CX;
        REAL_POW_MUL] THEN
      REWRITE_TAC[GSYM LIFT_CMUL] THEN AP_TERM_TAC THEN
      SUBGOAL_THEN `abs(sqrt c) pow 2 = c` SUBST1_TAC THENL
       [REWRITE_TAC[REAL_POW2_ABS] THEN MATCH_MP_TAC SQRT_POW_2 THEN
         ASM_REAL_ARITH_TAC;
        REWRITE_TAC[]];
      ALL_TAC] THEN
    MATCH_MP_TAC INTEGRABLE_CMUL THEN MATCH_MP_TAC INTEGRABLE_DILATE_UNIV THEN
    ASM_SIMP_TAC[REAL_LT_IMP_NZ]]);;

(* ========================================================================= *)
(* 286N core: the Carleson coefficient is dilation-invariant under the tile  *)
(* permutation sigma |-> sigma* = (k+kk, nI, nJ) paired with the L^2         *)
(* dilation                                                                  *)
(* ftilde(x) = 2^{kk/2} f(2^{kk} x): (f | phi_sigma) = (ftilde |             *)
(* phi_sigstar).                                                             *)
(* ========================================================================= *)

(* scalar Jacobian identity: 2^{kk} * sqrt(2^{-kk}) = sqrt(2^{kk}). Both     *)
(* sides                                                                     *)
(* nonneg with equal squares (2^kk)^2 2^-kk = 2^kk (uses 2^kk 2^-kk = 1).    *)
let ZPOW_JAC_SQRT = prove
 (`!kk:int. &2 zpow kk * sqrt(&2 zpow (--kk)) = sqrt(&2 zpow kk)`,
  GEN_TAC THEN CONV_TAC SYM_CONV THEN MATCH_MP_TAC SQRT_UNIQUE THEN
  SUBGOAL_THEN `&0 < &2 zpow kk /\ &0 < &2 zpow (--kk)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE; SQRT_POS_LE];
    REWRITE_TAC[REAL_POW_MUL] THEN
      ASM_SIMP_TAC[SQRT_POW_2; REAL_LT_IMP_LE] THEN
    SUBGOAL_THEN `&2 zpow kk * &2 zpow (--kk) = &1` (fun th -> MP_TAC th) THENL
     [SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ; INT_ADD_RINV;
       REAL_ZPOW_0];
      CONV_TAC REAL_RING]]);;

(* 286N core dilation invariance of the Carleson coefficient.                *)
(*   (f | phi_(k,nI,nJ)) = (ftilde | phi_(k+kk,nI,nJ))  where                *)
(*   ftilde(x) = 2^{kk/2} f(2^{kk} x).                                       *)
(* carleson_ip = integral f*cnj(phi_sigma); change of variables x = 2^kk u   *)
(* (INTEGRAL_DILATE_UNIV, Jacobian inv 2^kk) + PHISIG_DILATE (phi_sigma(2^kk *)
(* u)                                                                        *)
(* = 2^{-kk/2} phi_sigstar(u)) + ZPOW_JAC_SQRT collapses the scalars.        *)
let CARLESON_IP_DILATE = prove
 (`!(f:real->complex) kk k nI nJ.
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> carleson_ip f (k,nI,nJ) =
         carleson_ip (\x. Cx(sqrt(&2 zpow kk)) * f(&2 zpow kk * x)) (k + kk,
           nI, nJ)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_ip; lproduct] THEN
  SUBGOAL_THEN `&0 < &2 zpow kk` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x. (Cx (sqrt (&2 zpow kk)) * (f:real->complex) (&2 zpow kk * drop x)) *
         cnj (phi_sigma (k + kk,nI,nJ) carleson_phi (drop x))) =
    (\x. Cx(&2 zpow kk) *
         (\u. f(drop u) * cnj(phi_sigma (k,nI,nJ) carleson_phi (drop u)))
              (&2 zpow kk % x))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
     REWRITE_TAC[DROP_CMUL] THEN
    MP_TAC(SPECL [`carleson_phi`; `kk:int`; `k:int`; `nI:int`; `nJ:int`;
      `drop x`]
      PHISIG_DILATE) THEN
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[CNJ_MUL; CNJ_CX] THEN
    SUBGOAL_THEN `Cx(sqrt(&2 zpow kk)) =
                  Cx(&2 zpow kk) * Cx(sqrt(&2 zpow (--kk)))` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
      ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN
        REWRITE_TAC[ZPOW_JAC_SQRT]; ALL_TAC] THEN
    CONV_TAC COMPLEX_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\u:real^1. (f:real->complex)(drop u) * cnj(phi_sigma (k,nI,nJ)
     carleson_phi (drop u)))
    integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SCHWARTZ_L2 THEN
      REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x:real^1. (f:real->complex)(drop(&2 zpow kk % x)) *
               cnj(phi_sigma (k,nI,nJ) carleson_phi (drop(&2 zpow kk % x))))
    integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL
      [`\u:real^1. (f:real->complex)(drop u) * cnj(phi_sigma (k,nI,nJ)
        carleson_phi (drop u))`;
       `&2 zpow kk`; `vec 0:real^1`] INTEGRABLE_DILATE_UNIV) THEN
    ASM_SIMP_TAC[REAL_LT_IMP_NZ; VECTOR_ADD_RID];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\x:real^1. (f:real->complex)(drop(&2 zpow kk % x)) *
               cnj(phi_sigma (k,nI,nJ) carleson_phi (drop(&2 zpow kk % x)))`;
    `(:real^1)`; `Cx(&2 zpow kk)`] INTEGRAL_COMPLEX_LMUL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL
   [`\u:real^1. (f:real->complex)(drop u) * cnj(phi_sigma (k,nI,nJ)
     carleson_phi (drop u))`;
    `&2 zpow kk`; `vec 0:real^1`] INTEGRAL_DILATE_UNIV) THEN
  ASM_SIMP_TAC[REAL_LT_IMP_NZ; VECTOR_ADD_RID] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_CMUL] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < c ==> abs c = c`] THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC; GSYM CX_MUL] THEN
  ASM_SIMP_TAC[REAL_MUL_RINV; REAL_LT_IMP_NZ] THEN
  REWRITE_TAC[COMPLEX_MUL_LID; CX_MUL]);;

(* ========================================================================= *)
(* 286N: dyadic-cell dilation. dyho(a+c) n = 2^c-dilate of dyho a n; hence   *)
(* the                                                                       *)
(* tile frequency-cells scale under sigma |-> sigma* = (k+kk, nI, nJ):       *)
(*   tile_J  sigma* = 2^kk-dilate of tile_J  sigma,                          *)
(*   tile_Jr sigma* = 2^kk-dilate of tile_Jr sigma.                          *)
(* ========================================================================= *)

let DYHO_DILATE = prove
 (`!a c n. dyho (a + c) n = IMAGE (\x:real. &2 zpow c * x) (dyho a n)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow c` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[dyho; EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN GEN_TAC THEN
  ASM_SIMP_TAC[REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH_EQ] THEN
  EQ_TAC THEN STRIP_TAC THENL
   [EXISTS_TAC `x / &2 zpow c` THEN
    ASM_SIMP_TAC[REAL_DIV_LMUL; REAL_LT_IMP_NZ; REAL_LE_RDIV_EQ;
      REAL_LT_LDIV_EQ] THEN
    ONCE_REWRITE_TAC[REAL_ARITH `(a * b) * c:real = c * a * b`] THEN
    ASM_SIMP_TAC[REAL_LE_LMUL_EQ; REAL_LT_LMUL_EQ] THEN ASM_REAL_ARITH_TAC;
    ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    ONCE_REWRITE_TAC[REAL_ARITH `a * b * c:real = c * a * b`] THEN
    ASM_SIMP_TAC[REAL_LT_LMUL_EQ; REAL_LE_LMUL_EQ]]);;

let TILE_JR_STAR = prove
 (`!kk k nI nJ. tile_Jr (k + kk, nI, nJ) =
                IMAGE (\y:real. &2 zpow kk * y) (tile_Jr (k,nI,nJ))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_Jr] THEN
  SUBGOAL_THEN `(k + kk) - &1:int = (k - &1) + kk` SUBST1_TAC THENL
   [INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[DYHO_DILATE]);;

let TILE_JR_STAR_MEM = prove
 (`!kk k nI nJ w. (&2 zpow kk * w) IN tile_Jr (k + kk, nI, nJ) <=> w IN tile_Jr
   (k,nI,nJ)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[TILE_JR_STAR; IN_IMAGE] THEN
  SUBGOAL_THEN `&0 < &2 zpow kk` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  EQ_TAC THENL
   [STRIP_TAC THEN
    SUBGOAL_THEN `w:real = x` (fun th -> ASM_REWRITE_TAC[th]) THEN
    MATCH_MP_TAC REAL_EQ_LCANCEL_IMP THEN EXISTS_TAC `&2 zpow kk` THEN
    ASM_SIMP_TAC[REAL_LT_IMP_NZ];
    DISCH_TAC THEN EXISTS_TAC `w:real` THEN ASM_REWRITE_TAC[]]);;

let REGION_STAR = prove
 (`!(E:real->bool) (h:real->real) kk k nI nJ.
     {y | y IN E /\ h y IN tile_Jr (k,nI,nJ)} =
     IMAGE (\x. &2 zpow kk * x)
       {x | (&2 zpow kk * x) IN E /\
            (&2 zpow kk * h(&2 zpow kk * x)) IN tile_Jr (k + kk, nI, nJ)}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[TILE_JR_STAR_MEM] THEN
  SUBGOAL_THEN `&0 < &2 zpow kk` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN X_GEN_TAC `y:real` THEN
  EQ_TAC THEN STRIP_TAC THENL
   [EXISTS_TAC `y / &2 zpow kk` THEN
    ASM_SIMP_TAC[REAL_DIV_LMUL; REAL_LT_IMP_NZ];
    ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286N: integral over a c-dilated set.  int_{IMAGE (c%) T} Ff = c * int_T   *)
(* Ff(c%z)  for c>0.  (Set version of INTEGRAL_DILATE_UNIV, from             *)
(* HAS_INTEGRAL_AFFINITY at m=inv c, translation 0.)  Feeds the 286N region- *)
(* integral dilation.                                                        *)
(* ========================================================================= *)
let INTEGRAL_DILATE_SET = prove
 (`!(Ff:real^1->complex) a (Tset:real^1->bool).
     &0 < a /\ (\z. Ff(a % z)) integrable_on Tset
     ==> integral (IMAGE (\z:real^1. a % z) Tset) Ff = Cx a * integral Tset
       (\z. Ff(a % z))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\z:real^1. (Ff:real^1->complex)(a % z)`;
                 `integral Tset (\z:real^1. (Ff:real^1->complex)(a % z))`;
                 `Tset:real^1->bool`; `inv(a:real)`;
                   `vec 0:real^1`] HAS_INTEGRAL_AFFINITY) THEN
  ASM_SIMP_TAC[REAL_LT_IMP_NZ; REAL_INV_EQ_0; VECTOR_MUL_RZERO; VECTOR_ADD_RID;
    VECTOR_NEG_0] THEN
  ANTS_TAC THENL [MATCH_MP_TAC INTEGRABLE_INTEGRAL THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[VECTOR_MUL_ASSOC] THEN
  ASM_SIMP_TAC[REAL_MUL_RINV; REAL_LT_IMP_NZ; VECTOR_MUL_LID;
    REAL_INV_INV] THEN
  REWRITE_TAC[DIMINDEX_1; REAL_POW_1; REAL_ABS_INV] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < a ==> abs a = a`; REAL_INV_INV] THEN
  DISCH_THEN(MP_TAC o MATCH_MP INTEGRAL_UNIQUE) THEN
  REWRITE_TAC[ETA_AX; COMPLEX_CMUL] THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

(* ========================================================================= *)
(* 286N: phi_sigma is absolutely integrable on ANY lebesgue-measurable       *)
(* region                                                                    *)
(* (not just finite-measure ones). phi_sigma carleson_phi is Schwartz, hence *)
(* absolutely integrable on the whole line (SCHWARTZ_ABSINT); restrict to    *)
(* any                                                                       *)
(* lebesgue-measurable subset (ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_ *)
(* SUBSET). The unbounded-region companion of                                *)
(* PHISIG_ABS_INTEGRABLE_MEASURABLE.                                         *)
(* ========================================================================= *)
let PHISIG_ABS_INTEGRABLE_LEBESGUE = prove
 (`!s Sc. real_lebesgue_measurable Sc
      ==> (\z. phi_sigma s carleson_phi (drop z)) absolutely_integrable_on
        (IMAGE lift Sc)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `(:real^1)` THEN REWRITE_TAC[SUBSET_UNIV] THEN CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_ABSINT THEN
     REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ];
    ASM_MESON_TAC[REAL_LEBESGUE_MEASURABLE]]);;

(* ------------------------------------------------------------------------- *)
(* 286N region-integral dilation: int_{sigma-region for (E,h)} phi_sigma     *)
(* = sqrt(2^kk) * int_{sigma*-region for the dilated data} phi_sigma*.       *)
(* Chains REGION_STAR (region set-id) + lift-dilation commute + INTEGRAL_    *)
(* DILATE_SET (Jacobian 2^kk) + PHISIG_DILATE (phi_sigma(2^kk .) = 2^{-kk/2} *)
(* phi_sigstar) + ZPOW_JAC_SQRT (2^kk sqrt(2^-kk)=sqrt(2^kk)).               *)
(* ------------------------------------------------------------------------- *)
let REGION_INTEGRAL_STAR = prove
 (`!(E:real->bool) (h:real->real) kk k nI nJ.
     real_lebesgue_measurable {x | (&2 zpow kk * x) IN E /\
            (&2 zpow kk * h(&2 zpow kk * x)) IN tile_Jr (k + kk, nI, nJ)}
     ==> integral (IMAGE lift {y | y IN E /\ h y IN tile_Jr (k,nI,nJ)})
           (\z. phi_sigma (k,nI,nJ) carleson_phi (drop z)) =
         Cx(sqrt(&2 zpow kk)) *
         integral (IMAGE lift {x | (&2 zpow kk * x) IN E /\
            (&2 zpow kk * h(&2 zpow kk * x)) IN tile_Jr (k + kk, nI, nJ)})
           (\z. phi_sigma (k + kk, nI, nJ) carleson_phi (drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow kk` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REGION_STAR] THEN
  ABBREV_TAC `Rstar = {x | (&2 zpow kk * x) IN E /\
            (&2 zpow kk * h(&2 zpow kk * x)) IN tile_Jr (k + kk, nI, nJ)}` THEN
  SUBGOAL_THEN
   `IMAGE lift (IMAGE (\x:real. &2 zpow kk * x) Rstar) =
    IMAGE (\z:real^1. &2 zpow kk % z) (IMAGE lift Rstar)`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM IMAGE_o; o_DEF] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REWRITE_TAC[o_THM; LIFT_CMUL]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\z:real^1. phi_sigma (k,nI,nJ) carleson_phi (drop z)`;
    `&2 zpow kk`; `IMAGE lift Rstar`] INTEGRAL_DILATE_SET) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `(\z:real^1. phi_sigma (k,nI,nJ) carleson_phi (drop (&2 zpow kk % z))) =
    (\z. Cx(sqrt(&2 zpow (--kk))) * phi_sigma (k + kk, nI, nJ) carleson_phi
      (drop z))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN
     REWRITE_TAC[DROP_CMUL] THEN
    REWRITE_TAC[PHISIG_DILATE]; ALL_TAC] THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC PHISIG_ABS_INTEGRABLE_LEBESGUE THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
   [`\z:real^1. phi_sigma (k + kk, nI, nJ) carleson_phi (drop z)`;
    `IMAGE lift Rstar`;
      `Cx(sqrt(&2 zpow (--kk)))`] INTEGRAL_COMPLEX_LMUL)) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC PHISIG_ABS_INTEGRABLE_LEBESGUE THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC; GSYM CX_MUL; ZPOW_JAC_SQRT]);;

(* ========================================================================= *)
(* 286N per-term dilation (COMBINES CARLESON_IP_DILATE +                     *)
(* REGION_INTEGRAL_STAR):                                                    *)
(* the 286M summand for sigma over (f,E,h) = sqrt(2^kk) * the summand for    *)
(* sigma* over the dilated data (ftilde, Etilde, htilde). The |ip| factor is *)
(* invariant (CARLESON_IP_DILATE); the |int| factor carries sqrt(2^kk)       *)
(* (REGION_INTEGRAL_STAR); a nonneg real scalar pulls out of the norm.       *)
(* ========================================================================= *)
let CARLESON_TERM_DILATE = prove
 (`!(f:real->complex) E (h:real->real) kk k nI nJ.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     real_lebesgue_measurable {x | (&2 zpow kk * x) IN E /\
            (&2 zpow kk * h(&2 zpow kk * x)) IN tile_Jr (k + kk, nI, nJ)}
     ==> norm(carleson_ip f (k,nI,nJ) *
              integral (IMAGE lift {y | y IN E /\ h y IN tile_Jr (k,nI,nJ)})
                (\z. phi_sigma (k,nI,nJ) carleson_phi (drop z))) =
         sqrt(&2 zpow kk) *
         norm(carleson_ip (\x. Cx(sqrt(&2 zpow kk)) * f(&2 zpow kk * x)) (k +
           kk, nI, nJ) *
              integral (IMAGE lift {x | (&2 zpow kk * x) IN E /\
                 (&2 zpow kk * h(&2 zpow kk * x)) IN tile_Jr (k + kk, nI, nJ)})
                (\z. phi_sigma (k + kk, nI, nJ) carleson_phi (drop z)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`f:real->complex`; `kk:int`; `k:int`; `nI:int`;
    `nJ:int`] CARLESON_IP_DILATE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(SPECL [`E:real->bool`; `h:real->real`; `kk:int`; `k:int`; `nI:int`;
    `nJ:int`]
    REGION_INTEGRAL_STAR) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_MUL_AC] THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `abs(sqrt(&2 zpow kk)) = sqrt(&2 zpow kk)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC SQRT_POS_LE THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_AC]);;

(* ========================================================================= *)
(* 286N: the tile permutation sigma |-> sigma* = (k+kk, nI, nJ) is a         *)
(* bijection                                                                 *)
(* of the tile universe :int#int#int, so the tile-sum reindexes.             *)
(* ========================================================================= *)

let TILE_STAR_INJ = prove
 (`!(kk:int) s t:int#int#int.
     (\u:int#int#int. (FST u + kk, FST(SND u), SND(SND u))) s =
     (\u. (FST u + kk, FST(SND u), SND(SND u))) t ==> s = t`,
  GEN_TAC THEN REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC [`a:int`;`b:int`;`c:int`;`d:int`;`e:int`;`g:int`] THEN
  REWRITE_TAC[PAIR_EQ] THEN STRIP_TAC THEN
  REPEAT CONJ_TAC THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o check (fun th -> can (find_term (fun tm -> tm =
    `kk:int`)) (concl th))) THEN
  INT_ARITH_TAC);;

let TILE_STAR_SUM_REINDEX = prove
 (`!(g:(int#int#int)->real) (P:(int#int#int)->bool) kk.
     sum (IMAGE (\u:int#int#int. (FST u + kk, FST(SND u), SND(SND u))) P) g =
     sum P (\s. g((FST s + kk, FST(SND s), SND(SND s))))`,
  REPEAT GEN_TAC THEN
  W(MP_TAC o PART_MATCH (lhand o rand) SUM_IMAGE o lhand o snd) THEN
  ANTS_TAC THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC TILE_STAR_INJ THEN
     EXISTS_TAC `kk:int` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]);;

(* ========================================================================= *)
(* 286N core sum-dilation identity: the whole 286M correlation sum for       *)
(* (f,E,h) over a finite tile set P equals sqrt(2^kk) times the sum for the  *)
(* dilated data (ftilde x = sqrt(2^kk) f(2^kk x), Etilde = 2^-kk E, htilde x *)
(* =                                                                         *)
(* 2^kk h(2^kk x)) over the star-shifted tiles s* = (k+kk,nI,nJ). Termwise   *)
(* via                                                                       *)
(* CARLESON_TERM_DILATE (each summand scales by sqrt(2^kk), tile s -> star   *)
(* s); the                                                                   *)
(* per-s real_lebesgue_measurable side-condition is supplied as a            *)
(* hypothesis.                                                               *)
(* This is the reusable heart of 286N (drop the muE<=1, ||f||=1              *)
(* normalization).                                                           *)
(* ========================================================================= *)
let CARLESON_SUM_DILATE = prove
 (`!f E h kk P.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ FINITE P /\
     (!s. s IN P ==> real_lebesgue_measurable
        {x | &2 zpow kk * x IN E /\
             &2 zpow kk * h (&2 zpow kk * x) IN
             tile_Jr (FST s + kk, FST(SND s), SND(SND s))})
     ==> sum P (\s. norm(carleson_ip f s *
                 integral (IMAGE lift {y | y IN E /\ h y IN tile_Jr s})
                      (\z. phi_sigma s carleson_phi (drop z))))
         = sqrt(&2 zpow kk) *
           sum P (\s. norm(carleson_ip (\x. Cx(sqrt(&2 zpow kk)) * f(&2 zpow kk
             * x))
                       (FST s + kk, FST(SND s), SND(SND s)) *
              integral (IMAGE lift
                {x | &2 zpow kk * x IN E /\
                     &2 zpow kk * h (&2 zpow kk * x) IN
                     tile_Jr (FST s + kk, FST(SND s), SND(SND s))})
                (\z. phi_sigma (FST s + kk, FST(SND s), SND(SND s))
                       carleson_phi (drop z))))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM SUM_LMUL] THEN
  MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN
  MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `k:int` (X_CHOOSE_THEN
    `rs:int#int` SUBST_ALL_TAC)) THEN
  MP_TAC(ISPEC `rs:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `nI:int` (X_CHOOSE_THEN
    `nJ:int` SUBST_ALL_TAC)) THEN
  REWRITE_TAC[FST; SND] THEN
  MATCH_MP_TAC CARLESON_TERM_DILATE THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `(k,nI,nJ):int#int#int`) THEN
  ASM_REWRITE_TAC[FST; SND]);;

(* ========================================================================= *)
(* 286K off-diagonal Gram structure: the frequency-cell J-ordering           *)
(* dichotomy.                                                                *)
(* If two tiles have overlapping left-half J-cells (so <phi_s|phi_t> may be  *)
(* nonzero, 286E b-iii) but distinct J-cells, then one J-cell sits inside    *)
(* the                                                                       *)
(* other's LEFT half:  J_s SUBSET J^l_t  OR  J_t SUBSET J^l_s.  (Dyadic      *)
(* laminarity DYHO_TRICHOTOMY on the J^l pair + finer-inside-coarser         *)
(* DYHO_NEST.)                                                               *)
(* ========================================================================= *)

(* dyadic left child: dyho(k-1)(2n) [= left half] is inside its parent dyho  *)
(* k n                                                                       *)
let DYHO_LEFT_CHILD = prove
 (`!k n. dyho (k - &1) (&2 * n) SUBSET dyho k n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; SUBSET; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real` THEN REWRITE_TAC[int_mul_th; int_of_num_th] THEN
  SIMP_TAC[REAL_ZPOW_SUB; REAL_OF_NUM_EQ; ARITH_EQ; REAL_ZPOW_1] THEN
  SUBGOAL_THEN `&0 < &2 zpow k` MP_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[real_div] THEN CONV_TAC REAL_FIELD);;

(* Jl_s SUBSET Jl_t with distinct J-cells forces the scale strict ks < kt.   *)
let JLSUBSET_KSLT = prove
 (`dyho (ks - &1) (&2 * nJs) SUBSET dyho (kt - &1) (&2 * nJt) /\
   ~(dyho ks nJs = dyho kt nJt) ==> ks:int < kt`,
  STRIP_TAC THEN FIRST_ASSUM(MP_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN
    DISCH_TAC THEN
  ASM_CASES_TAC `ks:int = kt` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    SUBGOAL_THEN `nJs:int = nJt` (fun th -> ASM_MESON_TAC[th]) THEN
    MP_TAC(ISPECL [`kt - &1:int`; `&2 * nJt:int`;
      `&2 * nJs:int`] DYHO_SAMESCALE_SUBSET_EQ) THEN
    ASM_REWRITE_TAC[] THEN INT_ARITH_TAC;
    ASM_INT_ARITH_TAC]);;

(* the branch step: Jl_s SUBSET Jl_t (distinct J) ==> J_s SUBSET Jl_t.       *)
let JL_LIFT_TO_J = prove
 (`dyho (ks - &1) (&2 * nJs) SUBSET dyho (kt - &1) (&2 * nJt) /\
   ~(dyho ks nJs = dyho kt nJt) ==> dyho ks nJs SUBSET dyho (kt - &1) (&2 *
     nJt)`,
  STRIP_TAC THEN
  SUBGOAL_THEN `ks:int < kt` ASSUME_TAC THENL
    [ASM_MESON_TAC[JLSUBSET_KSLT]; ALL_TAC] THEN
  MATCH_MP_TAC DYHO_NEST THEN
  EXISTS_TAC `real_of_int (&2 * nJs) * &2 zpow (ks - &1)` THEN
  REPEAT CONJ_TAC THENL
   [ASM_INT_ARITH_TAC;
    MP_TAC(ISPECL [`ks:int`; `nJs:int`] DYHO_LEFT_CHILD) THEN
      REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[DYHO_NONEMPTY];
    FIRST_X_ASSUM(fun th -> if can (find_term (fun tm -> tm = `kt - &1:int`))
      (concl th) &&
                               (not(is_neg(concl th))) then MP_TAC th else
                                 NO_TAC) THEN
    REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[DYHO_NONEMPTY]]);;

(* the dichotomy, in raw dyho form.                                          *)
let DYHO_JL_OFFDIAG_DICHOTOMY = prove
 (`!ks kt nJs nJt.
     ~(dyho ks nJs = dyho kt nJt) /\
     ~(DISJOINT (dyho (ks - &1) (&2 * nJs)) (dyho (kt - &1) (&2 * nJt)))
     ==> dyho ks nJs SUBSET dyho (kt - &1) (&2 * nJt) \/
         dyho kt nJt SUBSET dyho (ks - &1) (&2 * nJs)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`ks - &1:int`; `&2 * nJs:int`; `kt - &1:int`;
    `&2 * nJt:int`] DYHO_TRICHOTOMY) THEN
  STRIP_TAC THENL
   [DISJ1_TAC THEN MATCH_MP_TAC JL_LIFT_TO_J THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN MATCH_MP_TAC JL_LIFT_TO_J THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL [ASM_REWRITE_TAC[]; CONV_TAC SYM_CONV THEN
      ASM_REWRITE_TAC[]];
    ASM_MESON_TAC[]]);;

(* tile-form dichotomy: distinct J-cells with overlapping left-halves are    *)
(* J^l-nested one way or the other.  Feeds the 286K off-diagonal Gram block  *)
(* split into the J_s SUBSET J^l_t and J_t SUBSET J^l_s sub-blocks.          *)
let TILE_JL_OFFDIAG_DICHOTOMY = prove
 (`!s t:int#int#int.
     ~(tile_J s = tile_J t) /\ ~(DISJOINT (tile_Jl s) (tile_Jl t))
     ==> tile_J s SUBSET tile_Jl t \/ tile_J t SUBSET tile_Jl s`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
  MP_TAC(ISPEC `t:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN
  MP_TAC(ISPEC `y':int#int` PAIR_SURJECTIVE) THEN
  MP_TAC(ISPEC `y:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
  REWRITE_TAC[tile_J; tile_Jl; DYHO_JL_OFFDIAG_DICHOTOMY]);;

(* ========================================================================= *)
(* 286K H_j inner (per-sigma) sum, in TILE form.  For a fixed sigma and a    *)
(* finite tile-set Tt of "coarser" tiles (k_sigma <= k_t, distinct I-cells)  *)
(* whose I-cells form a pairwise-negligible cover inside II, the inner sum   *)
(*   sum_t |<phi_sigma|phi_t>| * |<f|phi_t>|                                 *)
(* is <= (C3 gam) inv(sqrt 2^{k_sigma}) int_II w_sigma.  Instantiates the    *)
(* abstract HJ_INNER_SUM with Ai=|<phi_s|phi_t>| (PHISIG_286GG_TILE),        *)
(* Bi=|ip_t|                                                                 *)
(* (COEFF_LE_ENERGY_MASS), G=tile_I, v=cw_tile sigma.                        *)
(* ========================================================================= *)

(* tile-form of 286Gg (cross-correlation kernel bound), stated on sigma,t.   *)
let PHISIG_286GG_TILE = prove
 (`?C3. &0 <= C3 /\
   !(s:int#int#int) (t:int#int#int). tile_k s <= tile_k t /\ ~(tile_I s =
     tile_I t)
     ==> norm(integral (:real^1)
           (\z. phi_sigma s carleson_phi (drop z) *
                cnj(phi_sigma t carleson_phi (drop z))))
         <= C3 * inv(sqrt(&2 zpow (tile_k s))) * sqrt(&2 zpow (tile_k t)) *
            real_integral (tile_I t) (cw_tile s)`,
  X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC PHISIG_286GG THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `t:int#int#int`] THEN
  MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
  MP_TAC(ISPEC `t:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
  MP_TAC(ISPEC `y':int#int` PAIR_SURJECTIVE) THEN
  MP_TAC(ISPEC `y:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
  REWRITE_TAC[tile_k] THEN ASM_REWRITE_TAC[]);;

let HJ_INNER_TILE = prove
 (`?C3. &0 <= C3 /\
   !(f:real->complex) sigma (Tt:(int#int#int)->bool) (P:(int#int#int)->bool)
     gam II.
      &0 <= gam /\ FINITE Tt /\ FINITE P /\ energy_f f P <= gam /\
      (!t. t IN Tt ==> t IN P) /\
      (!t. t IN Tt ==> tile_k sigma <= tile_k t /\ ~(tile_I sigma = tile_I t))
        /\
      (!t. t IN Tt ==> tile_I t SUBSET II) /\
      (!t t'. t IN Tt /\ t' IN Tt /\ tile_I t = tile_I t' ==> t = t') /\
      (!t t'. t IN Tt /\ t' IN Tt /\ ~(t = t') ==> real_negligible (tile_I t
        INTER tile_I t')) /\
      (!t. t IN Tt ==> cw_tile sigma real_integrable_on tile_I t) /\
      cw_tile sigma real_integrable_on II
      ==> sum Tt (\t. norm(integral (:real^1)
                (\z. phi_sigma sigma carleson_phi (drop z) *
                     cnj(phi_sigma t carleson_phi (drop z)))) *
                norm(carleson_ip f t))
          <= (C3 * gam) * inv(sqrt(&2 zpow (tile_k sigma))) *
             real_integral II (cw_tile sigma)`,
  X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC PHISIG_286GG_TILE THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`C3:real`; `gam:real`; `tile_k sigma`; `tile_k:(int#int#int)->int`;
    `\t. norm(integral (:real^1)
           (\z. phi_sigma sigma carleson_phi (drop z) *
                cnj(phi_sigma t carleson_phi (drop z))))`;
    `\t. norm(carleson_ip (f:real->complex) t)`;
    `tile_I:(int#int#int)->(real->bool)`; `cw_tile sigma`; `II:real->bool`;
    `Tt:(int#int#int)->bool`] HJ_INNER_SUM) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      REWRITE_TAC[NORM_POS_LE];
      REWRITE_TAC[NORM_POS_LE];
      X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th -> can (find_term (fun tm ->
        tm = `real_integral`)) (concl th))) THEN
      ASM_SIMP_TAC[];
      X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
      MATCH_MP_TAC COEFF_LE_ENERGY_MASS THEN
        EXISTS_TAC `P:(int#int#int)->bool` THEN
      ASM_SIMP_TAC[];
      ASM_SIMP_TAC[];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[];
      ASM_REWRITE_TAC[];
      GEN_TAC THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN REWRITE_TAC[CW_TILE_POS]];
    REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286K off-diagonal block Cauchy-Schwarz reduction.  For any nonneg inr,    *)
(*   sum_s |<f|phi_s>| * inr_s <= sqrt(delta_f f P) * sqrt(sum_s inr_s^2).   *)
(* (Fremlin: sum_sigma |<f|phi_sigma>|(inner tau-sum) <= sqrt(alpha)         *)
(* sqrt(H).)                                                                 *)
(* SUM_CAUCHY_SCHWARZ on (|ip_s|, inr_s) + sqrt-monotone + SQRT_MUL.         *)
(* ========================================================================= *)
let OFFBLOCK_CS = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) (inr:(int#int#int)->real).
     FINITE P /\ (!s. s IN P ==> &0 <= inr s)
     ==> sum P (\s. norm(carleson_ip f s) * inr s)
         <= sqrt(delta_f f P) * sqrt(sum P (\s. inr s pow 2))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`;
    `\s. norm(carleson_ip (f:real->complex) s)`;
                 `inr:(int#int#int)->real`] SUM_CAUCHY_SCHWARZ) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  REWRITE_TAC[delta_f] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sqrt(sum P (\s. norm(carleson_ip (f:real->complex) s) pow 2) *
                   sum P (\s. inr s pow 2))` THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN `sum P (\s. norm(carleson_ip (f:real->complex) s) * inr s) =
                  sqrt((sum P (\s. norm(carleson_ip f s) * inr s)) pow 2)`
                    SUBST1_TAC THENL
     [CONV_TAC SYM_CONV THEN MATCH_MP_TAC POW_2_SQRT THEN
      MATCH_MP_TAC SUM_POS_LE THEN
        ASM_SIMP_TAC[REAL_LE_MUL; NORM_POS_LE]; ALL_TAC] THEN
    MATCH_MP_TAC SQRT_MONO_LE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SQRT_MUL; REAL_LE_REFL]]);;

(* ========================================================================= *)
(* 286K H_j square-sum (per-tree), abstract form. Given, for each sigma in a *)
(* finite tree Sp, a nonneg inner-sum value bounded by (C3 gam) inv(sqrt     *)
(* 2^ks)                                                                     *)
(* R sigma with R sigma in [0,1] (R sigma = int_{II sigma} w_sigma, supplied *)
(* by                                                                        *)
(* HJ_INNER_TILE at the use site), all scales >= L, per-scale weight-tail    *)
(* <=C4:                                                                     *)
(*   sum_sigma (inner-sum)^2 <= (C3 gam)^2 * 2 C4 * inv(2^L).                *)
(* Just MATCH_MP_TAC HJ_FULL_BOUND with inr = the inner tau-sum, R = the     *)
(* weight                                                                    *)
(* integral, kf = tile_k. (The per-sigma inner bound is left as a hypothesis *)
(* so                                                                        *)
(* the H_j square-sum is decoupled from the HJ_INNER_TILE geometry.)         *)
(* ========================================================================= *)
let HJ_TILE_BOUND = prove
 (`!(f:real->complex) (Sp:(int#int#int)->bool)
     (Tt:(int#int#int)->((int#int#int)->bool)) (II:(int#int#int)->(real->bool))
     gam (C4:real) (L:int) (C3:real).
      &0 <= C3 /\ &0 <= gam /\ &0 <= C4 /\ FINITE Sp /\
      (!sigma. sigma IN Sp ==>
          &0 <= sum (Tt sigma) (\t. norm(integral (:real^1)
                  (\z. phi_sigma sigma carleson_phi (drop z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                  norm(carleson_ip f t)) /\
          &0 <= real_integral (II sigma) (cw_tile sigma) /\
          real_integral (II sigma) (cw_tile sigma) <= &1 /\
          sum (Tt sigma) (\t. norm(integral (:real^1)
                  (\z. phi_sigma sigma carleson_phi (drop z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                  norm(carleson_ip f t)) <=
            (C3 * gam) * inv(sqrt(&2 zpow (tile_k sigma))) *
            real_integral (II sigma) (cw_tile sigma) /\
          L <= tile_k sigma) /\
      (!k. sum {sigma | sigma IN Sp /\ tile_k sigma = k}
               (\sigma. real_integral (II sigma) (cw_tile sigma)) <= C4)
      ==> sum Sp (\sigma. (sum (Tt sigma) (\t. norm(integral (:real^1)
                  (\z. phi_sigma sigma carleson_phi (drop z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                  norm(carleson_ip f t))) pow 2)
          <= (C3 * gam) pow 2 * (&2 * C4 * inv(&2 zpow L))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(BETA_RULE(ISPECL
   [`C3:real`; `gam:real`; `tile_k:(int#int#int)->int`;
    `\sigma. sum (Tt sigma) (\t. norm(integral (:real^1)
                  (\z. phi_sigma sigma carleson_phi (drop z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                  norm(carleson_ip (f:real->complex) t))`;
    `\sigma. real_integral (II sigma) (cw_tile sigma)`;
    `Sp:(int#int#int)->bool`; `C4:real`; `L:int`] HJ_FULL_BOUND)) THEN
  REPEAT CONJ_TAC THEN
  TRY(ASM_REWRITE_TAC[] THEN NO_TAC) THEN
  TRY(X_GEN_TAC `sigma:int#int#int` THEN DISCH_TAC THEN ASM_SIMP_TAC[] THEN
    NO_TAC));;
(* ========================================================================= *)
(* 286K Gram-bound closing arithmetic.  From the block estimates alpha^2 <=  *)
(* C3 alpha (diagonal) + 2 off (the two symmetric off-diagonal blocks) with  *)
(* off <= 2 C3 sqrt(2 C4) alpha, conclude alpha <= C3 + 4 C3 sqrt(2 C4) =    *)
(* C6/4.                                                                     *)
(* (alpha = delta_f f P' = sum|<f|phi>|^2.)  GRAM_ALPHA_BOUND with K = C6/4. *)
(* ========================================================================= *)

let LNORM2_SQ = prove
 (`!(g:real^1->complex). g IN lspace (:real^1) (&2)
     ==> (lnorm (:real^1) (&2) g) pow 2 = drop(integral (:real^1) (\x.
       lift(norm(g x) pow 2)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`(:real^1)`; `&2`; `g:real^1->complex`] LNORM_RPOW) THEN
  ASM_REWRITE_TAC[REAL_ARITH `~(&2 = &0)`] THEN
  REWRITE_TAC[RPOW_POW] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM; RPOW_POW]);;


(* ========================================================================= *)
(* 286N brick: the L^2 norm is invariant under the L^2 dilation              *)
(* f |-> (\z. sqrt(c) f(c z)).  (Fremlin 286N: ||ftilde||_2 = ||f||_2 with   *)
(* ftilde(x) = 2^{k/2} f(2^k x).) lnorm^2 = int norm^2 (LNORM2_SQ), which is *)
(* dilation-invariant (L2_DILATE_NORMSQ); then a^2 = b^2 with a,b >= 0.      *)
(* ========================================================================= *)
let LNORM_DILATE_EQ = prove
 (`!ff c. &0 < c /\ ff IN lspace (:real^1) (&2)
     ==> lnorm (:real^1) (&2) (\z. Cx(sqrt c) * ff (c % z)) = lnorm (:real^1)
       (&2) ff`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z. Cx(sqrt c) * ff (c % z)) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[L2_DILATE_LSPACE]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z. lift(norm((ff:real^1->complex) z) pow 2)) integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(:real^1)`; `&2`;
     `ff:real^1->complex`] LSPACE_IMP_INTEGRABLE) THEN
    ASM_REWRITE_TAC[RPOW_POW]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_POW_EQ THEN EXISTS_TAC `2` THEN
  REWRITE_TAC[ARITH_EQ] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC LNORM_POS_LE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC LNORM_POS_LE THEN ASM_REWRITE_TAC[];
    ASM_SIMP_TAC[LNORM2_SQ] THEN AP_TERM_TAC THEN
    MP_TAC(ISPECL [`ff:real^1->complex`; `c:real`] L2_DILATE_NORMSQ) THEN
    ASM_REWRITE_TAC[] THEN SIMP_TAC[]]);;


(* ========================================================================= *)
(* 286N assembly bricks (Fremlin mt286.tex 1879-1936).                       *)
(* ========================================================================= *)

(* dilation-preimage as an image, and its measure (c > 0).                   *)
let DILATE_PREIMAGE_IMAGE = prove
 (`!(E:real->bool) c. ~(c = &0) ==> {x | c * x IN E} = IMAGE (\x. inv c * x)
   E`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_IMAGE] THEN
  X_GEN_TAC `y:real` THEN EQ_TAC THENL
   [DISCH_TAC THEN EXISTS_TAC `c * y:real` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `~(c = &0)` THEN CONV_TAC REAL_FIELD;
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `c * inv c * x' = x':real` SUBST1_TAC THENL
     [UNDISCH_TAC `~(c = &0)` THEN CONV_TAC REAL_FIELD; ASM_REWRITE_TAC[]]]);;

let DILATE_PREIMAGE_MEASURE = prove
 (`!(E:real->bool) c. &0 < c /\ real_measurable E
     ==> real_measurable {x | c * x IN E} /\
         real_measure {x | c * x IN E} = inv c * real_measure E`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`E:real->bool`; `c:real`] DILATE_PREIMAGE_IMAGE) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[REAL_MEASURABLE_SCALING];
    ASM_SIMP_TAC[REAL_MEASURE_SCALING] THEN
    SUBGOAL_THEN `abs(inv c) = inv c` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_INV] THEN AP_TERM_TAC THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[]]]);;

(* the CARLESON_SUM_DILATE ftilde (real-mult form) IS the %-dilation         *)
(* composed with drop (bridges to L2_DILATE_LSPACE / LNORM_DILATE_EQ).       *)
let FTILDE_DROP_EQ = prove
 (`!(f:real->complex) c. &0 < c
     ==> (\z. (\x. Cx(sqrt c) * f(c * x))(drop z)) =
         (\z. Cx(sqrt c) * (\w. f(drop w))(c % z))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN
  REWRITE_TAC[DROP_CMUL]);;

(* a lower integer-power witness: for m > 0 there is k with 2^k < m.         *)
let ZPOW2_LOWER = prove
 (`!m. &0 < m ==> ?k:int. &2 zpow k < m`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`inv m:real`; `&0:int`] ZPOW2_ARCH) THEN
  DISCH_THEN(X_CHOOSE_THEN `b:int` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `--b:int` THEN REWRITE_TAC[REAL_ZPOW_NEG] THEN
  SUBGOAL_THEN `&0 < &2 zpow b` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `inv(&2 zpow b) < inv(inv m)` MP_TAC THENL
   [MATCH_MP_TAC REAL_LT_INV2 THEN ASM_REWRITE_TAC[REAL_LT_INV_EQ];
    ASM_SIMP_TAC[REAL_INV_INV]]);;

(* Fremlin's k with 2^{k-1} < muF <= 2^k, in the bracket form muF <= 2^k <=  *)
(* 2 muF.                                                                    *)
let POW2_BRACKET = prove
 (`!m. &0 < m ==> ?k:int. m <= &2 zpow k /\ &2 zpow k <= &2 * m`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`m:real`; `&0:int`] ZPOW2_ARCH) THEN
  DISCH_THEN(X_CHOOSE_THEN `b:int` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPEC `m:real` ZPOW2_LOWER) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:int` ASSUME_TAC) THEN
  SUBGOAL_THEN `a:int < b` ASSUME_TAC THENL
   [MATCH_MP_TAC ZPOW2_LT_REV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(INST [`\j:int. m <= &2 zpow (a + j)`,`P:int->bool`] INT_WOP) THEN
  BETA_TAC THEN
  SUBGOAL_THEN
    `?x:int. &0 <= x /\ m <= &2 zpow (a + x)` (fun th -> REWRITE_TAC[th]) THENL
   [EXISTS_TAC `b - a:int` THEN CONJ_TAC THENL
     [ASM_INT_ARITH_TAC;
      SUBGOAL_THEN `a + (b - a):int = b` SUBST1_TAC THENL
       [INT_ARITH_TAC; ASM_SIMP_TAC[REAL_LT_IMP_LE]]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `j0:int` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `a + j0:int` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `j0 = &0:int` THENL
   [UNDISCH_TAC `&2 zpow a < m` THEN ASM_REWRITE_TAC[INT_ADD_RID] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(m <= &2 zpow (a + (j0 - &1)))` ASSUME_TAC THENL
   [DISCH_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `j0 - &1:int`) THEN
    ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `&2 zpow (a + j0) = &2 * &2 zpow (a + (j0 - &1))` SUBST1_TAC THENL
   [SUBGOAL_THEN `a + j0:int = (a + (j0 - &1)) + &1` SUBST1_TAC THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[GSYM ZPOW2_ADD; REAL_ZPOW_1] THEN REAL_ARITH_TAC;
    ASM_REAL_ARITH_TAC]);;


(* 286N brick: g |-> (\x. c g(c x)) preserves real_measurable_on (c > 0).    *)
(* Bridges to the real^1 MEASURABLE_ON_DILATE via the lift/drop unfolding of *)
(* real_measurable_on; the SUM_DILATE side-condition needs gtilde            *)
(* measurable.                                                               *)
let REAL_MEASURABLE_ON_DILATE_MUL = prove
 (`!(h:real->real) c. &0 < c /\ h real_measurable_on (:real)
     ==> (\x. c * h(c * x)) real_measurable_on (:real)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_MEASURABLE_ON_LMUL THEN
  REWRITE_TAC[real_measurable_on] THEN
  SUBGOAL_THEN
   `lift o (\x. (h:real->real)(c * x)) o drop = (\z. (lift o h o drop)(c % z))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; DROP_CMUL; LIFT_DROP]; ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE lift (:real) = (:real^1)` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN
     MESON_TAC[LIFT_DROP]; ALL_TAC] THEN
  MP_TAC(ISPECL [`lift o (h:real->real) o drop`; `c:real`; `vec 0:real^1`]
    MEASURABLE_ON_DILATE) THEN
  ASM_REWRITE_TAC[VECTOR_ADD_RID] THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    UNDISCH_TAC `(h:real->real) real_measurable_on (:real)` THEN
    REWRITE_TAC[real_measurable_on] THEN
    SUBGOAL_THEN
      `IMAGE lift (:real) = (:real^1)` (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN MESON_TAC[LIFT_DROP];
    SIMP_TAC[]]);;

(* the norm-square integral of sum ip phi is integrable (it is in L^2).      *)
let RECON_NORMSQ_INTEGRABLE = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> (\x. lift(norm(vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi
       (drop x))) pow 2))
         integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;
    `P:(int#int#int)->bool`] CARLESON_RECON_L2) THEN
  ASM_REWRITE_TAC[lspace; IN_ELIM_THM] THEN
  DISCH_THEN(MP_TAC o CONJUNCT2) THEN REWRITE_TAC[RPOW_POW]);;

let GRAM_NORM_EQ = prove
 (`!(f:real->complex) (P:(int#int#int)->bool).
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ FINITE P
     ==> norm(vsum P (\s. vsum P (\t. carleson_ip f s * cnj(carleson_ip f t) *
             lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                (\z. phi_sigma t carleson_phi (drop z)))))
         = (lnorm (:real^1) (&2)
             (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi (drop
               z)))) pow 2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;
    `P:(int#int#int)->bool`] CARLESON_NORMSQ_REAL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MP_TAC(ISPEC `\z. vsum P (\s. carleson_ip (f:real->complex) s * phi_sigma s
    carleson_phi (drop z))`
    LNORM2_SQ) THEN
  ASM_SIMP_TAC[CARLESON_RECON_L2] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_NORM_CX; REAL_ABS_REFL] THEN
  MATCH_MP_TAC INTEGRAL_DROP_POS THEN
  ASM_SIMP_TAC[RECON_NORMSQ_INTEGRABLE; LIFT_DROP; REAL_LE_POW_2]);;

let DELTA_SQ_LE_GRAM = prove
 (`!(f:real->complex) (P:(int#int#int)->bool).
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ FINITE P /\
     lnorm (:real^1) (&2) (\z. f(drop z)) <= &1
     ==> (delta_f f P) pow 2
         <= norm(vsum P (\s. vsum P (\t. carleson_ip f s * cnj(carleson_ip f t)
           *
             lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                (\z. phi_sigma t carleson_phi (drop z)))))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[GRAM_NORM_EQ] THEN REWRITE_TAC[delta_f] THEN
  MP_TAC(ISPECL [`f:real->complex`;
    `P:(int#int#int)->bool`] CARLESON_286J_SECOND) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(lnorm (:real^1) (&2) (\z. f(drop z)) *
               lnorm (:real^1) (&2)
                 (\z. vsum P (\s. carleson_ip f s * phi_sigma s carleson_phi
                   (drop z)))) pow 2` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_POW_LE2 THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[delta_f] THEN MATCH_MP_TAC SUM_POS_LE THEN
      REWRITE_TAC[REAL_LE_POW_2];
    REWRITE_TAC[REAL_POW_MUL] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_LID] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_POW_1_LE THEN CONJ_TAC THENL
       [MATCH_MP_TAC LNORM_POS_LE THEN ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]];
      REWRITE_TAC[REAL_LE_POW_2]]]);;

(* ========================================================================= *)
(* 286K off-diagonal routing. The off-diagonal Gram block norm is bounded by *)
(* sum_s |<f|phi_s>| * inr_s, where inr_s = sum_{t in P, J_t<>J_s}           *)
(* |<phi_s|phi_t>| * |<f|phi_t>| is the (combined-direction) H_j inner sum.  *)
(* CARLESON_OFFBLOCK_TRIANGLE (norm(offdiag) <= sum_s sum_t                  *)
(* |ip_s||<..>||ip_t|)                                                       *)
(* + SUM_LMUL (pull |ip_s| out of the inner t-sum).                          *)
(* ========================================================================= *)
let OFFDIAG_LE_INR = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> norm(vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
                carleson_ip f s * cnj(carleson_ip f t) *
                lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                   (\z. phi_sigma t carleson_phi (drop z)))))
         <= sum P (\s. norm(carleson_ip f s) *
                sum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
                     norm(integral (:real^1) (\z. phi_sigma s carleson_phi
                       (drop z) *
                                                  cnj(phi_sigma t carleson_phi
                                                    (drop z)))) *
                     norm(carleson_ip f t)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;
    `P:(int#int#int)->bool`] CARLESON_OFFBLOCK_TRIANGLE) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(REAL_ARITH `a = b ==> x <= a ==> x <= b`) THEN
  MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  REWRITE_TAC[GSYM SUM_LMUL] THEN MATCH_MP_TAC SUM_EQ THEN
  X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    REAL_ARITH_TAC);;

(* ========================================================================= *)
(* 286K Gram-bound roof (combined-inr form).  From alpha^2 <= C3 alpha + off *)
(* and off <= sqrt(alpha) sqrt(K alpha) (= the OFFBLOCK_CS output with the   *)
(* H_j                                                                       *)
(* square-sum K), conclude alpha <= C3 + sqrt K.  The off-diagonal handling  *)
(* uses the COMBINED inr (all J_t<>J_s) so there is a single off term (no    *)
(* factor-2 sub-block split); the constant C3+sqrt K is a valid C6/4 -- 286M *)
(* only needs SOME C6.                                                       *)
(* ========================================================================= *)
let GRAM_COMBINE_SQRT = prove
 (`!alpha C3 K off.
     &0 <= alpha /\ &0 <= C3 /\ &0 <= K /\
     alpha pow 2 <= C3 * alpha + off /\
     off <= sqrt(alpha) * sqrt(K * alpha)
     ==> alpha <= C3 + sqrt K`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 <= sqrt K /\
                sqrt alpha * sqrt(K * alpha) = sqrt K * alpha /\
                (C3 + sqrt K) * alpha = C3 * alpha + sqrt K * alpha`
   STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[SQRT_POS_LE; REAL_ADD_RDISTRIB] THEN
    REWRITE_TAC[SQRT_MUL] THEN
    ONCE_REWRITE_TAC[REAL_ARITH `sa * sK * sa2 = sK * (sa * sa2):real`] THEN
    ASM_SIMP_TAC[GSYM REAL_POW_2; SQRT_POW_2]; ALL_TAC] THEN
  MATCH_MP_TAC GRAM_ALPHA_BOUND THEN
  ASM_SIMP_TAC[REAL_LE_ADD; SQRT_POS_LE] THEN
  ASM_REAL_ARITH_TAC);;

(* ========================================================================= *)
(* 286K a-iii disjointness, same-J case (pure geometry). Distinct tiles with *)
(* the SAME frequency cell J have DISJOINT spatial cells I: J_s=J_t fixes k  *)
(* and                                                                       *)
(* nJ (DYHO_INJ), so s<>t forces nI_s<>nI_t, and same-scale dyadic I-cells   *)
(* with                                                                      *)
(* different index are disjoint (DYHO_DISJOINT_SAMESCALE). This is the       *)
(* trivial                                                                   *)
(* half of Fremlin's a-iii "distinct P'-tiles with meeting J^l have disjoint *)
(* I";                                                                       *)
(* the different-J half needs the stopping-time ordering (first remark).     *)
(* ========================================================================= *)
let AIII_SAMEJ_DISJOINT = prove
 (`!s t:int#int#int. ~(s = t) /\ tile_J s = tile_J t ==> DISJOINT (tile_I s)
   (tile_I t)`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_J; tile_I] THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP DYHO_INJ) THEN
  FIRST_X_ASSUM(fun th -> if concl th = `ks:int = kt` then SUBST_ALL_TAC th
    else NO_TAC) THEN
  MATCH_MP_TAC DYHO_DISJOINT_SAMESCALE THEN
  FIRST_X_ASSUM(MP_TAC o check(fun th -> is_neg(concl th))) THEN
  REWRITE_TAC[PAIR_EQ] THEN ASM_REWRITE_TAC[] THEN INT_ARITH_TAC);;

(* ========================================================================= *)
(* 286K a-iii FIRST-remark geometric core.  Given the stopping-time fact     *)
(* ~(tile_ler sigma tauj) [Fremlin: sigma NOT >= tau_j], the J^r-nesting     *)
(* J^r_tauj SUBSET J^r_sigma, and the scale order k_tauj <= k_sigma, the     *)
(* I-cells                                                                   *)
(* are disjoint.  (~tile_ler with the J^r-nesting forces ~(I_sigma SUBSET    *)
(* I_tauj), then TILE_I_FINER_NOT_SUBSET_DISJOINT.)  This isolates the pure  *)
(* geometry; the stopping-time construction supplies ~tile_ler + the         *)
(* J^r-nesting.                                                              *)
(* ========================================================================= *)
let ENERGY_TREE_FAMILY_FINITE = prove
 (`!(P:(int#int#int)->bool). FINITE P
     ==> FINITE {tile_tree P tau | tau IN (:int#int#int)}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `{A:(int#int#int)->bool | A SUBSET P}` THEN
  ASM_SIMP_TAC[FINITE_POWERSET] THEN
  REWRITE_TAC[SUBSET; FORALL_IN_GSPEC; IN_ELIM_THM; IN_UNIV] THEN
  X_GEN_TAC `tau:int#int#int` THEN
  REWRITE_TAC[tile_tree; SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

(* ========================================================================= *)
(* 286K a-iii FIRST-remark core, Fremlin-faithful J-ORDER version. Fremlin's *)
(* order is tau <= sigma  <=>  J_tau SUBSET J_sigma /\ I_sigma SUBSET I_tau  *)
(* (286F), so our tile_le sigma tauj = (tauj <= sigma in Fremlin) uses the J *)
(* cell (not J^r). The FIRST remark deduces I disjoint from "sigma NOT >=    *)
(* tauj"                                                                     *)
(* (~tile_le sigma tauj) TOGETHER WITH J_tauj SUBSET J_sigma [from J_tauj    *)
(* SUBSET                                                                    *)
(* J^l_sigma SUBSET J_sigma]: these force ~(I_sigma SUBSET I_tauj), then     *)
(* TILE_I_FINER_NOT_SUBSET_DISJOINT (k_tauj <= k_sigma).                     *)
(* (AIII_FIRST_CORE @earlier used tile_ler/J^r -- a true but NOT directly    *)
(* usable                                                                    *)
(* sibling, since J_tauj SUBSET J_sigma does NOT give J^r_tauj SUBSET        *)
(* J^r_sigma.)                                                               *)
(* ========================================================================= *)
let AIII_FIRST_CORE_LE = prove
 (`!sigma tauj:int#int#int.
     ~(tile_le sigma tauj) /\ tile_J tauj SUBSET tile_J sigma /\
     tile_k tauj <= tile_k sigma
     ==> DISJOINT (tile_I sigma) (tile_I tauj)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC TILE_I_FINER_NOT_SUBSET_DISJOINT THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  UNDISCH_TAC `~(tile_le sigma tauj)` THEN REWRITE_TAC[tile_le] THEN
  ASM_REWRITE_TAC[]);;


(* ========================================================================= *)
(* 286J(c) within-fiber disjointness (Fremlin mt286.tex 919-923).  The base  *)
(* intervals of two distinct greedy-R members that share a common coarser    *)
(* root                                                                      *)
(* (both finer in space, both meeting the root's frequency cell) are         *)
(* disjoint.                                                                 *)
(* ========================================================================= *)

(* tile_le is antisymmetric: I and J each determine the tile's (k,index) via *)
(* DYHO_INJ, so mutual <= forces equality.                                   *)
let TILE_LE_ANTISYM = prove
 (`!s t:int#int#int. tile_le s t /\ tile_le t s ==> s = t`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!a b c a' b' c'. P((a,b,c):int#int#int) ((a',b',c'):int#int#int))
    ==> (!s t. P s t)`) THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_le; tile_I; tile_J] THEN
  REWRITE_TAC[GSYM SUBSET_ANTISYM_EQ] THEN STRIP_TAC THEN
  SUBGOAL_THEN `dyho (--a) b = dyho (--a') b' /\ dyho a c = dyho a' c'`
   MP_TAC THENL [ASM_REWRITE_TAC[GSYM SUBSET_ANTISYM_EQ]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN (STRIP_ASSUME_TAC o MATCH_MP DYHO_INJ)) THEN
  REWRITE_TAC[PAIR_EQ] THEN ASM_INT_ARITH_TAC);;

(* the greedy minimal-witness R is an antichain: distinct members are        *)
(* tile_le-incomparable (else minimality + antisymmetry collapse them).      *)
let CARLESON_JR_ANTICHAIN = prove
 (`!E h c P r1 r2:int#int#int.
     r1 IN carleson_jR E h c P /\ r2 IN carleson_jR E h c P /\ ~(r1 = r2)
     ==> ~(tile_le r1 r2)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_jR; IN_ELIM_THM] THEN STRIP_TAC THEN
  DISCH_TAC THEN
  UNDISCH_TAC `~(r1:int#int#int = r2)` THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC TILE_LE_ANTISYM THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `r2:int#int#int` o
    check(fun th -> is_forall(concl th) && free_in `r1:int#int#int` (concl
      th))) THEN
  ASM_REWRITE_TAC[]);;

(* frequency-cell nesting reflects the scale order (J = dyho tile_k).        *)
let TILE_J_SUBSET_SCALE = prove
 (`!s t:int#int#int. tile_J s SUBSET tile_J t ==> tile_k s <= tile_k t`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!a b c a' b' c'. P((a,b,c):int#int#int)((a',b',c'):int#int#int))
    ==> (!s t. P s t)`) THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_J; tile_k] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`a:int`;`c:int`;`a':int`;`c':int`] DYHO_SUBSET_SCALE) THEN
  ASM_REWRITE_TAC[]);;

(* antichain + nested J => disjoint I (via AIII_FIRST_CORE_LE).              *)
let TILE_ANTICHAIN_JNEST_DISJOINT = prove
 (`!s t:int#int#int. ~(tile_le t s) /\ tile_J s SUBSET tile_J t
     ==> DISJOINT (tile_I t) (tile_I s)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC AIII_FIRST_CORE_LE THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC TILE_J_SUBSET_SCALE THEN
    ASM_REWRITE_TAC[]);;

(* frequency cells are laminar (dyho trichotomy).                            *)
let TILE_J_TRICHOTOMY = prove
 (`!s t:int#int#int.
     tile_J s SUBSET tile_J t \/ tile_J t SUBSET tile_J s \/
     DISJOINT (tile_J s) (tile_J t)`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!a1 b1 c1 a2 b2 c2. P((a1,b1,c1):int#int#int)((a2,b2,c2):int#int#int))
    ==> (!s t. P s t)`) THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_J; DYHO_TRICHOTOMY]);;

(* meeting frequency cells are comparable (drop the disjoint case).          *)
let TILE_J_MEET_COMPARABLE = prove
 (`!s t:int#int#int. ~(tile_J s INTER tile_J t = {})
     ==> tile_J s SUBSET tile_J t \/ tile_J t SUBSET tile_J s`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`s:int#int#int`;`t:int#int#int`] TILE_J_TRICHOTOMY) THEN
  REWRITE_TAC[DISJOINT] THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

(* a coarser (smaller-scale) frequency cell that meets is contained.         *)
let TILE_J_MEET_COARSER_SUBSET = prove
 (`!m t:int#int#int. tile_k m <= tile_k t /\ ~(tile_J m INTER tile_J t = {})
     ==> tile_J m SUBSET tile_J t`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!a1 b1 c1 a2 b2 c2. P((a1,b1,c1):int#int#int)((a2,b2,c2):int#int#int))
    ==> (!m t. P m t)`) THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_J; tile_k] THEN STRIP_TAC THEN
  MATCH_MP_TAC DYHO_MEET_NEST THEN ASM_REWRITE_TAC[DISJOINT]);;

(* THE within-fiber disjointness: two distinct antichain members, both finer *)
(* than a common root m (k_m <= k_ti) and both meeting m's frequency cell,   *)
(* have                                                                      *)
(* disjoint base intervals. Both J_ti include J_m (COARSER_SUBSET), so they  *)
(* share                                                                     *)
(* the nonempty J_m hence meet hence are comparable (MEET_COMPARABLE); then  *)
(* the                                                                       *)
(* antichain (incomparable in tile_le) forces I-disjointness                 *)
(* (ANTICHAIN_JNEST).                                                        *)
let TILE_FIBER_I_DISJOINT = prove
 (`!m t1 t2:int#int#int.
     tile_k m <= tile_k t1 /\ tile_k m <= tile_k t2 /\
     ~(tile_J t1 INTER tile_J m = {}) /\ ~(tile_J t2 INTER tile_J m = {}) /\
     ~(tile_le t1 t2) /\ ~(tile_le t2 t1)
     ==> DISJOINT (tile_I t1) (tile_I t2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `tile_J m SUBSET tile_J t1` ASSUME_TAC THENL
   [MATCH_MP_TAC TILE_J_MEET_COARSER_SUBSET THEN ASM_REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[INTER_COMM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `tile_J m SUBSET tile_J t2` ASSUME_TAC THENL
   [MATCH_MP_TAC TILE_J_MEET_COARSER_SUBSET THEN ASM_REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[INTER_COMM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(tile_J t1 INTER tile_J t2 = {})` ASSUME_TAC THENL
   [MP_TAC(ISPEC `m:int#int#int` TILE_J_NONEMPTY) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN ASM SET_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`t1:int#int#int`;`t2:int#int#int`] TILE_J_MEET_COMPARABLE)
    THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [ONCE_REWRITE_TAC[DISJOINT_SYM] THEN
    MATCH_MP_TAC TILE_ANTICHAIN_JNEST_DISJOINT THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC TILE_ANTICHAIN_JNEST_DISJOINT THEN ASM_REWRITE_TAC[]]);;


(* ========================================================================= *)
(* region measurability with a tile dilate (companion of SC_MEASURABLE,      *)
(* whose                                                                     *)
(* second factor is a dyho cell): {x in E : h x in J_s} cap I^(k)_s is       *)
(* bounded                                                                   *)
(* (inside the interval I^(k)_s) + a triple INTER of lebesgue-measurable     *)
(* sets.                                                                     *)
(* ========================================================================= *)
let SC_IDIL_MEASURABLE = prove
 (`!(h:real->real) E s k.
      real_lebesgue_measurable E /\ h real_measurable_on (:real)
      ==> real_measurable ({x | x IN E /\ h x IN tile_J s} INTER tile_Idil s
        k)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `real_bounded ({x | x IN E /\ (h:real->real) x IN tile_J s} INTER tile_Idil
     s k)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_BOUNDED_SUBSET THEN
    EXISTS_TAC `tile_Idil s k` THEN
    REWRITE_TAC[TILE_IDIL_INTERVAL; REAL_BOUNDED_REAL_INTERVAL; INTER_SUBSET];
    ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM REAL_LEBESGUE_MEASURABLE_IFF_MEASURABLE] THEN
  SUBGOAL_THEN
   `{x | x IN E /\ (h:real->real) x IN tile_J s} INTER tile_Idil s k =
    (E INTER {x | (h:real->real) x IN tile_J s}) INTER tile_Idil s k`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
     MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN ASM_REWRITE_TAC[] THEN
    SPEC_TAC(`s:int#int#int`,`s:int#int#int`) THEN
    REWRITE_TAC[FORALL_PAIR_THM; tile_J] THEN REPEAT GEN_TAC THEN
    MATCH_MP_TAC H_PREIMAGE_DYHO_LEBESGUE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
    REWRITE_TAC[TILE_IDIL_MEASURABLE]]);;

(* tile-form of tile_I measurability (the base cell of any abstract tile).   *)
let TILE_I_MEASURABLE_TILE = prove
 (`!s:int#int#int. real_measurable(tile_I s)`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!a b c. P((a,b,c):int#int#int)) ==> (!s. P s)`) THEN
  REWRITE_TAC[TILE_I_MEASURABLE]);;

(* ========================================================================= *)
(* 286J(c) CONCRETE per-k tile bound (Fremlin mt286.tex 898-940). For a      *)
(* finite                                                                    *)
(* antichain Rk of tiles, each satisfying the R_k threshold                  *)
(*   2^{2k-9} gam <= 2^{k_t} mu({x in E : h x in J_t} cap I^(k)_t),          *)
(* the greedy q-map (GREEDY_CAPTURE, product-meet + coarsest-first in        *)
(* --tile_k)                                                                 *)
(* gives a product-disjoint root set M, and CARLESON_RK_MEASURE_ABSTRACT     *)
(* yields                                                                    *)
(*   gam * sum_{t in Rk} muI_t <= 2^{11-k} muE.                              *)
(* Discharge legs: base-containment TILE_I_SUBSET_IDIL4_ALLK; within-fiber   *)
(* disjointness TILE_FIBER_I_DISJOINT (q coarser + product-J-meet + Rk       *)
(* antichain);                                                               *)
(* container measure ZPOW2_ADD; threshold RK_GAMMUI_BRIDGE; region           *)
(* measurability                                                             *)
(* SC_IDIL_MEASURABLE; root-region disjointness TILE_PRODMEET_SSET_DISJOINT. *)
(* ========================================================================= *)
let CARLESON_RK_TILE = prove
 (`!(Rk:(int#int#int)->bool) (E:real->bool) (h:real->real) (k:num) gam.
     FINITE Rk /\ &0 <= gam /\
     real_lebesgue_measurable E /\ real_measurable E /\
     h real_measurable_on (:real) /\
     (!t1 t2. t1 IN Rk /\ t2 IN Rk /\ ~(t1 = t2) ==> ~(tile_le t1 t2)) /\
     (!t. t IN Rk
          ==> &2 zpow (&2 * &k - &9) * gam
              <= &2 zpow (tile_k t) *
                 real_measure ({x | x IN E /\ h x IN tile_J t} INTER tile_Idil
                   t k))
     ==> gam * sum Rk (\t. &2 zpow (--(tile_k t)))
         <= &2 zpow (&11 - &k) * real_measure E`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\s t:int#int#int. ~(tile_Idil s k INTER tile_Idil t k = {}) /\
                       ~(tile_J s INTER tile_J t = {})`;
    `\t:int#int#int. --(tile_k t)`;
    `Rk:(int#int#int)->bool`] GREEDY_CAPTURE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`u:int#int#int`; `v:int#int#int`] THEN BETA_TAC THEN
      DISCH_TAC THEN MATCH_MP_TAC TILE_PRODMEET_SYM THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN BETA_TAC THEN REWRITE_TAC[TILE_PRODMEET_REFL]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `M:(int#int#int)->bool`
    (X_CHOOSE_THEN `q:(int#int#int)->(int#int#int)` MP_TAC)) THEN
  BETA_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL
   [`Rk:(int#int#int)->bool`; `M:(int#int#int)->bool`;
    `q:(int#int#int)->(int#int#int)`;
    `tile_I:(int#int#int)->real->bool`;
    `\t:int#int#int. tile_Idil t (k + 2)`;
    `\t:int#int#int. {x | x IN E /\ h x IN tile_J t} INTER tile_Idil t k`;
    `\t:int#int#int. &2 zpow (--(tile_k t))`;
    `k:num`; `gam:real`; `E:real->bool`] CARLESON_RK_MEASURE_ABSTRACT) THEN
  BETA_TAC THEN ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  REPEAT CONJ_TAC THENL
   [(* leg 1: tile_I t SUBSET tile_Idil (q t) (k+2)                          *)
    X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
    MATCH_MP_TAC TILE_I_SUBSET_IDIL4_ALLK THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `t:int#int#int` o
      check(fun th -> free_in `q:(int#int#int)->(int#int#int)` (concl th)))
        THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN CONJ_TAC THENL
     [POP_ASSUM MP_TAC THEN INT_ARITH_TAC; ASM_REWRITE_TAC[]];
    (* leg 2: within-fiber base-I disjoint                                   *)
    MAP_EVERY X_GEN_TAC [`t1:int#int#int`; `t2:int#int#int`] THEN
      STRIP_TAC THEN
    MATCH_MP_TAC TILE_FIBER_I_DISJOINT THEN
    EXISTS_TAC `q(t1:int#int#int):int#int#int` THEN
    SUBGOAL_THEN
     `(~(tile_Idil t1 k INTER tile_Idil (q t1) k = {}) /\
       ~(tile_J t1 INTER tile_J (q t1) = {})) /\
      --tile_k t1 <= --tile_k (q(t1:int#int#int))` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(~(tile_Idil t2 k INTER tile_Idil (q t2) k = {}) /\
       ~(tile_J t2 INTER tile_J (q t2) = {})) /\
      --tile_k t2 <= --tile_k (q(t2:int#int#int))` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [POP_ASSUM MP_TAC THEN POP_ASSUM MP_TAC THEN INT_ARITH_TAC;
      FIRST_X_ASSUM(SUBST1_TAC o check(fun th -> is_eq(concl th))) THEN
      POP_ASSUM MP_TAC THEN POP_ASSUM MP_TAC THEN INT_ARITH_TAC;
      ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(fun th -> SUBST1_TAC th ORELSE SUBST1_TAC(SYM th)) THEN
      ASM_REWRITE_TAC[];
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    (* leg 3: tile_I measurable + measure                                    *)
    X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN CONJ_TAC THENL
     [REWRITE_TAC[TILE_I_MEASURABLE_TILE];
      SPEC_TAC(`t:int#int#int`,`u:int#int#int`) THEN
      MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
       `(!a b c. P((a,b,c):int#int#int)) ==> (!s. P s)`) THEN
      REWRITE_TAC[TILE_I_MEASURE; tile_k]];
    (* leg 4: Ione4 measurable + measure = 2^{k+2} muI                       *)
    X_GEN_TAC `m:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[TILE_IDIL_MEASURABLE; TILE_IDIL_MEASURE] THEN
    SUBGOAL_THEN `&(k + 2) - tile_k m = (&k + &2) + (--(tile_k m)):int`
     SUBST1_TAC THENL
     [REWRITE_TAC[GSYM INT_OF_NUM_ADD] THEN INT_ARITH_TAC;
      REWRITE_TAC[ZPOW2_ADD]];
    (* leg 5: threshold gam muI <= 2^{9-2k} muSset via RK_GAMMUI_BRIDGE      *)
    X_GEN_TAC `m:int#int#int` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(m:int#int#int) IN Rk` ASSUME_TAC THENL
     [ASM_MESON_TAC[SUBSET]; ALL_TAC] THEN
    MATCH_MP_TAC RK_GAMMUI_BRIDGE THEN
    UNDISCH_TAC
     `!t. t IN Rk ==> &2 zpow (&2 * &k - &9) * gam <= &2 zpow (tile_k t) *
                   real_measure ({x | x IN E /\ h x IN tile_J t} INTER
                     tile_Idil t k)` THEN
    DISCH_THEN(MP_TAC o SPEC `m:int#int#int`) THEN ASM_REWRITE_TAC[];
    (* leg 6: Sset measurable + SUBSET E                                     *)
    X_GEN_TAC `m:int#int#int` THEN DISCH_TAC THEN CONJ_TAC THENL
     [MATCH_MP_TAC SC_IDIL_MEASURABLE THEN ASM_REWRITE_TAC[]; SET_TAC[]];
    (* leg 7: Sset pairwise disjoint on M                                    *)
    MAP_EVERY X_GEN_TAC [`m1:int#int#int`; `m2:int#int#int`] THEN
      STRIP_TAC THEN
    MATCH_MP_TAC TILE_PRODMEET_SSET_DISJOINT THEN
    UNDISCH_TAC
     `!m1 m2. m1 IN M /\ m2 IN M /\ ~(m1 = m2)
       ==> ~(~(tile_Idil m1 k INTER tile_Idil m2 k = {}) /\
             ~(tile_J m1 INTER tile_J m2 = {}))` THEN
    DISCH_THEN(MP_TAC o SPECL [`m1:int#int#int`; `m2:int#int#int`]) THEN
    ASM_REWRITE_TAC[]]);;


(* ========================================================================= *)
(* 286J(d): the geometric k-sum (Fremlin mt286.tex 944-950). gamma sum_R muI *)
(* = sum_k gamma sum_{R_k} muI <= sum_k 2^{11-k} muE <= 2^12 muE.            *)
(* ========================================================================= *)

(* 2^{11-k} as reals (k:num) = 2^11 * (1/2)^k.                               *)
let ZPOW_11_MINUS_K = prove
 (`!k:num. &2 zpow (&11 - &k) = &2 pow 11 * inv(&2) pow k`,
  GEN_TAC THEN SIMP_TAC[REAL_ZPOW_SUB; REAL_OF_NUM_EQ; ARITH_EQ] THEN
  REWRITE_TAC[REAL_ZPOW_NUM; real_div; REAL_INV_POW; GSYM REAL_POW_INV]);;

(* the abstract k-sum: a finite family R, a level assignment kof, per-level  *)
(* bounds                                                                    *)
(* gamma sum_{t in R, kof t = k} muI <= 2^{11-k} muE, gives the geometric    *)
(* total                                                                     *)
(* gamma sum_R muI <= 2^12 muE. Regroup by kof-fibers (SUM_IMAGE_GEN), bound *)
(* each                                                                      *)
(* by the hypothesis, and collapse the geometric series                      *)
(* (SUM_HALF_POW_SCALED_LE                                                   *)
(* with c = 2^11 muE, giving <= 2 c = 2^12 muE).                             *)
let CARLESON_KSUM_GEOM = prove
 (`!(R:A->bool) (kof:A->num) (muI:A->real) gam E.
     FINITE R /\ &0 <= gam /\ &0 <= E /\ (!t. t IN R ==> &0 <= muI t) /\
     (!k. gam * sum {t | t IN R /\ kof t = k} muI <= &2 zpow (&11 - &k) * E)
     ==> gam * sum R muI <= &2 pow 12 * E`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`kof:A->num`; `muI:A->real`; `R:A->bool`] SUM_IMAGE_GEN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[GSYM SUM_LMUL] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (IMAGE (kof:A->num) R) (\k. &2 zpow (&11 - &k) * E)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN ASM_SIMP_TAC[FINITE_IMAGE] THEN
    REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    REWRITE_TAC[SUM_LMUL] THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ZPOW_11_MINUS_K] THEN
  SUBGOAL_THEN
   `sum (IMAGE (kof:A->num) R) (\k. (&2 pow 11 * inv (&2) pow k) * E) =
    sum (IMAGE (kof:A->num) R) (\k. (&2 pow 11 * E) * inv (&2) pow k)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC SUM_EQ THEN REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 * (&2 pow 11 * E)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC SUM_HALF_POW_SCALED_LE THEN ASM_SIMP_TAC[FINITE_IMAGE] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_POW_LE THEN REAL_ARITH_TAC;
    REWRITE_TAC[REAL_ARITH `&2 * (&2 pow 11 * E) = (&2 * &2 pow 11) * E`] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC REAL_RAT_REDUCE_CONV]);;


(* ========================================================================= *)
(* every witness-set member (hence every greedy-R member) carries a large    *)
(* region integral (Fremlin's sigma' with int_{E cap g^-1[J]} w > gamma/4).  *)
(* ========================================================================= *)
let CARLESON_JWITSET_REGION_INTEGRAL = prove
 (`!E h c P t:int#int#int.
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t}) /\
     t IN carleson_jwitset E h c P
     ==> c < real_integral {x | x IN E /\ h x IN tile_J t} (cw_tile t)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_jwitset; IN_ELIM_THM] THEN
  STRIP_TAC THEN
  FIRST_X_ASSUM(fun th -> ASSUME_TAC(SYM th) ORELSE ASSUME_TAC th) THEN
  MP_TAC(ISPECL [`E:real->bool`;`h:real->real`;`c:real`;`sigma:int#int#int`]
    CARLESON_JWIT_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[]);;

let CARLESON_JR_SUBSET_WITSET = prove
 (`!E h c P:(int#int#int)->bool.
     carleson_jR E h c P SUBSET carleson_jwitset E h c P`,
  REWRITE_TAC[carleson_jR; SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

(* a real-lebesgue-measurable subset of a finite-measure set is measurable   *)
(* (the region E cap g^-1[J] need not be bounded, but it sits inside E).     *)
let REAL_MEASURABLE_LEBMEAS_SUBSET = prove
 (`!s t. real_lebesgue_measurable s /\ real_measurable t /\ s SUBSET t
         ==> real_measurable s`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_MEASURABLE_MEASURABLE] THEN
  MATCH_MP_TAC MEASURABLE_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `IMAGE lift t` THEN
  ASM_REWRITE_TAC[GSYM REAL_LEBESGUE_MEASURABLE;
    GSYM REAL_MEASURABLE_MEASURABLE] THEN
  MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[]);;

(* RK_TILE with the frequency map h existentially bundled in the hypotheses, *)
(* so MATCH_MP_TAC determines Rk/E/k/gam from the conclusion and h is        *)
(* supplied via EXISTS_TAC (a plain ISPECL is blocked when the instantiation *)
(* mentions goal- context variables).                                        *)
let CARLESON_RK_TILE_EX = prove
 (`!(Rk:(int#int#int)->bool) (E:real->bool) (k:num) gam.
     FINITE Rk /\ &0 <= gam /\
     real_lebesgue_measurable E /\ real_measurable E /\
     (?h. h real_measurable_on (:real) /\
          (!t1 t2. t1 IN Rk /\ t2 IN Rk /\ ~(t1 = t2) ==> ~(tile_le t1 t2)) /\
          (!t. t IN Rk ==> &2 zpow (&2 * &k - &9) * gam <= &2 zpow (tile_k t) *
                 real_measure ({x | x IN E /\ h x IN tile_J t} INTER tile_Idil
                   t k)))
     ==> gam * sum Rk (\t. &2 zpow (--(tile_k t)))
         <= &2 zpow (&11 - &k) * real_measure E`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC CARLESON_RK_TILE THEN
  EXISTS_TAC `h:real->real` THEN ASM_REWRITE_TAC[]);;

(* geometric k-sum with an EXISTENTIAL level assignment in the hypothesis,   *)
(* so it is applied by MATCH_MP_TAC (no KFUN to instantiate; supply via      *)
(* EXISTS_TAC).                                                              *)
let KSUM_GEOM_EX = prove
 (`!(RR:(int#int#int)->bool) (WT:(int#int#int)->real) gg EE.
     FINITE RR /\ &0 <= gg /\ &0 <= EE /\ (!t. t IN RR ==> &0 <= WT t) /\
     (?KFUN. !k. gg * sum {t | t IN RR /\ KFUN t = k} WT <= &2 zpow (&11 - &k)
       * EE)
     ==> gg * sum RR WT <= &2 pow 12 * EE`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC CARLESON_KSUM_GEOM THEN
  EXISTS_TAC `KFUN:(int#int#int)->num` THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* 286J(c)+(d) COMBINED: the greedy-R measure budget gam^2 sum_R muI <= 2^12 *)
(* muE                                                                       *)
(* (Fremlin mt286.tex 896-950), R = carleson_jR at threshold gam^2/4.        *)
(* MATCH_MP_TAC                                                              *)
(* KSUM_GEOM_EX; supply the level assignment KFUN t = a dichotomy witness;   *)
(* per fiber                                                                 *)
(* CARLESON_RK_TILE. All terms spelled out (no ABBREV/SKOLEM --              *)
(* context-bound R/kof                                                       *)
(* block ISPECL of the tile lemmas).                                         *)
(* ========================================================================= *)
let CARLESON_JR_BUDGET = prove
 (`!(f:real->complex) E h P gam.
     FINITE P /\ &0 < gam /\
     real_lebesgue_measurable E /\ real_measurable E /\
     h real_measurable_on (:real) /\
     (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
     ==> gam pow 2 *
         sum (carleson_jR E h (gam pow 2 / &4) P) (\t. &2 zpow (--(tile_k t)))
         <= &2 pow 12 * real_measure E`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC KSUM_GEOM_EX THEN REPEAT CONJ_TAC THENL
   [ASM_SIMP_TAC[CARLESON_JR_FINITE];
    REWRITE_TAC[REAL_LE_POW_2];
    MATCH_MP_TAC REAL_MEASURE_POS_LE THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `t:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[REAL_LE_INV_EQ] THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  EXISTS_TAC
   `\t:int#int#int. @m. &2 zpow (&2 * &m - &9) * (gam pow 2)
                        <= &2 zpow (tile_k t) *
                           real_measure ({x | x IN E /\ h x IN tile_J t}
                                         INTER tile_Idil t m)` THEN
  X_GEN_TAC `k:num` THEN CONV_TAC(ONCE_DEPTH_CONV BETA_CONV) THEN
  MATCH_MP_TAC CARLESON_RK_TILE_EX THEN
  ASM_REWRITE_TAC[REAL_LE_POW_2] THEN CONJ_TAC THENL
   [(* FINITE fiber                                                          *)
    MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `carleson_jR E h (gam pow 2 / &4) P` THEN
    ASM_SIMP_TAC[CARLESON_JR_FINITE] THEN
    REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN SIMP_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `h:real->real` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* antichain                                                             *)
    MAP_EVERY X_GEN_TAC [`t1:int#int#int`; `t2:int#int#int`] THEN
    REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    MATCH_MP_TAC CARLESON_JR_ANTICHAIN THEN
    MAP_EVERY EXISTS_TAC
     [`E:real->bool`; `h:real->real`; `gam pow 2 / &4`;
      `P:(int#int#int)->bool`] THEN
    ASM_REWRITE_TAC[];
    (* R_k threshold: the SELECT value satisfies the threshold and equals k  *)
    X_GEN_TAC `t:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN
    CONV_TAC SELECT_CONV THEN
    ABBREV_TAC `g2 = gam pow 2` THEN
    MATCH_MP_TAC CWTILE_MASS_DICHOTOMY THEN
    REWRITE_TAC[REAL_LE_POW_2] THEN CONJ_TAC THENL
     [(* region measurable: lebesgue-measurable subset of finite-measure E   *)
      MATCH_MP_TAC REAL_MEASURABLE_LEBMEAS_SUBSET THEN
      EXISTS_TAC `E:real->bool` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `{x | x IN E /\ (h:real->real) x IN tile_J t} SUBSET E /\
        real_lebesgue_measurable {x | x IN E /\ (h:real->real) x IN tile_J t}`
       (fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THENL
       [SET_TAC[];
        SUBGOAL_THEN `{x | x IN E /\ (h:real->real) x IN tile_J t} =
          (E INTER {x | (h:real->real) x IN tile_J t})` SUBST1_TAC THENL
         [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
           MESON_TAC[]; ALL_TAC] THEN
        MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN ASM_REWRITE_TAC[] THEN
        SPEC_TAC(`t:int#int#int`,`t:int#int#int`) THEN
        REWRITE_TAC[FORALL_PAIR_THM; tile_J] THEN REPEAT GEN_TAC THEN
        MATCH_MP_TAC H_PREIMAGE_DYHO_LEBESGUE THEN ASM_REWRITE_TAC[]];
      (* gam^2/4 < int region: R member witness                              *)
      MATCH_MP_TAC CARLESON_JWITSET_REGION_INTEGRAL THEN
      EXISTS_TAC `P:(int#int#int)->bool` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`E:real->bool`;`h:real->real`;`gam pow 2 / &4`;
                     `P:(int#int#int)->bool`] CARLESON_JR_SUBSET_WITSET) THEN
      ASM SET_TAC[]]]);;


(* ========================================================================= *)
(* 286J (Fremlin's mass lemma), C5 = 2^12.  The greedy R = carleson_jR at    *)
(* threshold gam^2/4 gives the mass budget: for finite P with mass_Eh <=     *)
(* gam^2,                                                                    *)
(* the extracted R^+ removes the heavy tiles (mass residual <= gam^2/4,      *)
(* CARLESON_JMASS_BOUND) while gam^2 sum_R muI <= 2^12 muE <= 2^12 (muE <=   *)
(* 1,                                                                        *)
(* CARLESON_JR_BUDGET).  This discharges the carleson_mass_budget interface  *)
(* consumed by 286M.                                                         *)
(* ========================================================================= *)
let CARLESON_286J = prove
 (`?C5. &0 <= C5 /\
        !(f:real->complex) E h.
           real_lebesgue_measurable E /\ real_measurable E /\
           real_measure E <= &1 /\ h real_measurable_on (:real)
           ==> carleson_mass_budget f E h C5`,
  EXISTS_TAC `&2 pow 12` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_POW_LE THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[carleson_mass_budget] THEN
  MAP_EVERY X_GEN_TAC [`P:(int#int#int)->bool`; `gam:real`] THEN STRIP_TAC THEN
  EXISTS_TAC `carleson_jR E h (gam pow 2 / &4) P` THEN
  REPEAT CONJ_TAC THENL
   [ASM_SIMP_TAC[CARLESON_JR_FINITE];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `&2 pow 12 * real_measure E` THEN CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_JR_BUDGET THEN ASM_REWRITE_TAC[];
      GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC REAL_POW_LE THEN REAL_ARITH_TAC];
    MATCH_MP_TAC CARLESON_JMASS_BOUND THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286K a-iii DIFFERENT-J disjointness (Fremlin second remark, non-same-J    *)
(* case).                                                                    *)
(* Skeleton: given J_sigma SUBSET J^l_tau [one branch of the                 *)
(* meeting-dichotomy],                                                       *)
(* sigma's tree-root rho (tile_ler sigma rho), and the STOPPING-TIME fact    *)
(* ~(tile_le tau rho) [tau not above sigma's root], the spatial cells are    *)
(* disjoint.  Chains: tile_ler->tile_le (TILE_LER_IMP_LE) gives J_rho SUBSET *)
(* J_sigma SUBSET J^l_tau SUBSET J_tau, k_rho<=k_tau;                        *)
(* AIII_FIRST_CORE_LE(tau,rho)                                               *)
(* gives DISJOINT I_tau I_rho; AIII_DIFFJ_STEP lifts to DISJOINT I_sigma     *)
(* I_tau                                                                     *)
(* (via I_sigma SUBSET I_rho).                                               *)
(* ========================================================================= *)

let AIII_DIFFJ_STEP = prove
 (`!sigma tau rho:int#int#int.
     tile_le sigma rho /\ DISJOINT (tile_I tau) (tile_I rho)
     ==> DISJOINT (tile_I sigma) (tile_I tau)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_le] THEN STRIP_TAC THEN
  REWRITE_TAC[DISJOINT] THEN
  MP_TAC(ASSUME `DISJOINT (tile_I tau) (tile_I rho)`) THEN
    REWRITE_TAC[DISJOINT] THEN
  MP_TAC(ASSUME `tile_I sigma SUBSET tile_I rho`) THEN SET_TAC[]);;

let AIII_DIFFJ_BRANCH = prove
 (`!sigma tau rho:int#int#int.
     tile_J sigma SUBSET tile_Jl tau /\ tile_ler sigma rho /\ ~(tile_le tau
       rho)
     ==> DISJOINT (tile_I sigma) (tile_I tau)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP TILE_LER_IMP_LE) THEN
  SUBGOAL_THEN `tile_J rho SUBSET tile_J tau` ASSUME_TAC THENL
   [MP_TAC(ISPEC `tau:int#int#int` TILE_JL_SUBSET_J) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[tile_le]) THEN ASM SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `tile_k rho <= tile_k tau` ASSUME_TAC THENL
   [MATCH_MP_TAC TILE_JL_SUBSET_KLE THEN
    RULE_ASSUM_TAC(REWRITE_RULE[tile_le]) THEN ASM SET_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC AIII_DIFFJ_STEP THEN EXISTS_TAC `rho:int#int#int` THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC AIII_FIRST_CORE_LE THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* 286K a-i scale bound: every member of a down-cone tree has scale >= the   *)
(* root's scale. sigma IN tile_tree P tau (= tile_ler sigma tau) => k_tau <= *)
(* k_sigma (TILE_LER_SCALE). Hence on any NON-EMPTY achievable tree value A, *)
(* the root scales k_tau are bounded above by min_{sigma in A} k_sigma -- so *)
(* a                                                                         *)
(* MAXIMAL-scale representative exists (Fremlin 286K a-i R~).                *)
(* ========================================================================= *)
let TREE_KBOUND = prove
 (`!P tau sigma:int#int#int. sigma IN tile_tree P tau ==> tile_k tau <= tile_k
   sigma`,
  REWRITE_TAC[tile_tree; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[TILE_LER_SCALE]);;


(* ------------------------------------------------------------------------- *)
(* 286K(a-iii) y-ordering geometry.  Fremlin's leftmost-selection point      *)
(* y_sigma is the MIDPOINT of the FULL interval J_sigma (distinct from       *)
(* tile_ymid, the lower-quartile y^l_sigma used for the phase in phi_sigma). *)
(* y_sigma = dyho_mid k nJ = the LEFT endpoint of J^r_sigma =                *)
(* dyho(k-1)(2nJ+1),                                                         *)
(* so y_sigma lies in J^r_sigma (hence in J_sigma).  The a-iii step derives  *)
(* y_{tau_j} < y_{tau_l} from y_{tau_j} in J^l_sigma and y_{tau_l} in        *)
(* J^r_sigma                                                                 *)
(* (the left half of any dyadic interval is entirely below its right half).  *)
(* This y-ordering forces j < l in the greedy sequence, hence sigma in P_l   *)
(* SUBSET P_{j+1}, hence sigma NOT in {tau_j}+ -- the ordering fact a-iii    *)
(* uses.                                                                     *)
(* ------------------------------------------------------------------------- *)

let tile_yfull = new_definition
 `tile_yfull (k:int,nI:int,nJ:int) = dyho_mid k nJ`;;

(* 2 zpow k = 2 * 2 zpow (k-1): the scale-halving used to relate J and       *)
(* J^l/J^r.                                                                  *)
let ZPOW_HALVE = prove
 (`!k:int. &2 zpow k = &2 * &2 zpow (k - &1)`,
  GEN_TAC THEN
  GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [INT_ARITH `k:int = (k - &1) + &1`]
    THEN
  SIMP_TAC[REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH] THEN
  REWRITE_TAC[REAL_ZPOW_1] THEN REAL_ARITH_TAC);;

(* dyho_mid k nJ = (2nJ+1) * 2^(k-1) = the left endpoint of                  *)
(* dyho(k-1)(2nJ+1).                                                         *)
let DYHO_MID_JR_EDGE = prove
 (`!k nJ:int. dyho_mid k nJ = real_of_int (&2 * nJ + &1) * &2 zpow (k - &1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho_mid] THEN
    SUBST1_TAC(SPEC `k:int` ZPOW_HALVE) THEN
  SUBGOAL_THEN
    `real_of_int (&2 * nJ + &1) = &2 * real_of_int nJ + &1` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_OF_INT_CLAUSES]; ALL_TAC] THEN
  ABBREV_TAC `z = &2 zpow (k - &1)` THEN CONV_TAC REAL_RING);;

(* y_sigma lies in the RIGHT half-interval J^r_sigma (it is its left         *)
(* endpoint).                                                                *)
let TILE_YFULL_IN_JR = prove
 (`!s:int#int#int. tile_yfull s IN tile_Jr s`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_yfull; tile_Jr; DYHO_MID_JR_EDGE] THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN
  SUBGOAL_THEN `&0 < &2 zpow (p1 - &1)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]);;

(* hence y_sigma lies in J_sigma (J^r_sigma SUBSET J_sigma).                 *)
let TILE_YFULL_IN_J = prove
 (`!s:int#int#int. tile_yfull s IN tile_J s`,
  GEN_TAC THEN MP_TAC(ISPEC `s:int#int#int` TILE_YFULL_IN_JR) THEN
  MP_TAC(ISPEC `s:int#int#int` TILE_JR_SUBSET_J) THEN SET_TAC[]);;

(* The left half J^l_sigma is entirely to the left of the right half         *)
(* J^r_sigma.                                                                *)
let TILE_JL_LT_JR = prove
 (`!s:int#int#int a b. a IN tile_Jl s /\ b IN tile_Jr s ==> a < b`,
  REWRITE_TAC[FORALL_PAIR_THM; tile_Jl; tile_Jr; dyho; IN_ELIM_THM] THEN
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow (p1 - &1)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `real_of_int (&2 * p2 + &1) = real_of_int(&2 * p2) + &1`
   (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THENL
   [REWRITE_TAC[REAL_OF_INT_CLAUSES] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* 286K(a-iii) y-ordering: if J_{tj} SUBSET J^l_sigma (tau_j's interval lies *)
(* in                                                                        *)
(* sigma's left half) and sigma <=_r tau_l (so J^r_{tl} SUBSET J^r_sigma),   *)
(* then                                                                      *)
(* y_{tj} < y_{tl}.  This is Fremlin's y_{tau_j} < y_{tau_l}.                *)
let TILE_YFULL_ORDER = prove
 (`!sig tj tl:int#int#int.
     tile_J tj SUBSET tile_Jl sig /\ tile_ler sig tl
     ==> tile_yfull tj < tile_yfull tl`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC TILE_JL_LT_JR THEN
  EXISTS_TAC `sig:int#int#int` THEN CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o CONJUNCT1 o REWRITE_RULE[tile_ler]) THEN
    MP_TAC(ISPEC `tj:int#int#int` TILE_YFULL_IN_J) THEN ASM SET_TAC[];
    FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o REWRITE_RULE[tile_ler]) THEN
    MP_TAC(ISPEC `tl:int#int#int` TILE_YFULL_IN_JR) THEN ASM SET_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286K(a-i) the finite representative set R~. For every tau with P cap      *)
(* T_tau                                                                     *)
(* nonempty there is a tau' in R~ with the SAME tree P cap T_tau' and        *)
(* k_{tau'}                                                                  *)
(* >= k_tau (max scale). This lets the R_j selection-set test on the FINITE  *)
(* R~                                                                        *)
(* control the sup over ALL tau (Fremlin's a-ii stopping bound energy(P_n)<= *)
(* gam/2 is a max over R~).                                                  *)
(* ------------------------------------------------------------------------- *)

(* per-value max-scale representative existence (INT_HAS_MAX over the scales *)
(* of tiles sharing the tree-value; bounded above by any member's scale,     *)
(* TREE_KBOUND).                                                             *)
let TREE_MAXSCALE_REP = prove
 (`!P t0:int#int#int. FINITE P /\ ~(tile_tree P t0 = {})
     ==> ?tau. tile_tree P tau = tile_tree P t0 /\
               (!s. tile_tree P s = tile_tree P t0 ==> tile_k s <= tile_k
                 tau)`,
  REPEAT STRIP_TAC THEN UNDISCH_TAC `~(tile_tree P (t0:int#int#int) = {})` THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    DISCH_THEN(X_CHOOSE_TAC `sig0:int#int#int`) THEN
  MP_TAC(ISPECL [`\k:int. ?t:int#int#int. tile_tree P t = tile_tree P t0 /\
    tile_k t = k`;
                 `tile_k (sig0:int#int#int)`] INT_HAS_MAX) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [EXISTS_TAC `tile_k (t0:int#int#int)` THEN
       EXISTS_TAC `t0:int#int#int` THEN REWRITE_TAC[];
      ALL_TAC] THEN
    X_GEN_TAC `k:int` THEN DISCH_THEN(X_CHOOSE_THEN
      `t:int#int#int` STRIP_ASSUME_TAC) THEN
    FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC TREE_KBOUND THEN EXISTS_TAC `P:(int#int#int)->bool` THEN
      ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `km:int` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `t:int#int#int` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `tile_k (s:int#int#int)`) THEN
  ANTS_TAC THENL [EXISTS_TAC `s:int#int#int` THEN
    ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]]);;

(* the representative tile for a tree-value (SELECT of the max-scale rep).   *)
let carleson_rep = new_definition
 `carleson_rep P A = @tau:int#int#int. tile_tree P tau = A /\
                       (!s. tile_tree P s = A ==> tile_k s <= tile_k tau)`;;

(* R~ = image of carleson_rep over the finite family of achievable           *)
(* tree-values.                                                              *)
let carleson_Rtilde = new_definition
 `carleson_Rtilde P = IMAGE (carleson_rep P) {tile_tree P t | t IN
   (:int#int#int)}`;;

let CARLESON_RTILDE_FINITE = prove
 (`!P:(int#int#int)->bool. FINITE P ==> FINITE (carleson_Rtilde P)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Rtilde] THEN
  MATCH_MP_TAC FINITE_IMAGE THEN ASM_SIMP_TAC[ENERGY_TREE_FAMILY_FINITE]);;

(* rep spec: for a nonempty tree-value the rep achieves it with maximal      *)
(* scale.                                                                    *)
let CARLESON_REP_SPEC = prove
 (`!P t0:int#int#int. FINITE P /\ ~(tile_tree P t0 = {})
     ==> tile_tree P (carleson_rep P (tile_tree P t0)) = tile_tree P t0 /\
         (!s. tile_tree P s = tile_tree P t0
              ==> tile_k s <= tile_k (carleson_rep P (tile_tree P t0)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[carleson_rep] THEN
  CONV_TAC SELECT_CONV THEN ASM_SIMP_TAC[TREE_MAXSCALE_REP]);;

(* R~ representative property: a nonempty tree of tau is matched by a tau'   *)
(* in R~ with the same tree and k_{tau'} >= k_tau (the rep itself is that    *)
(* tau').                                                                    *)
let CARLESON_RTILDE_REP = prove
 (`!P tau:int#int#int. FINITE P /\ ~(tile_tree P tau = {})
     ==> ?taup. taup IN carleson_Rtilde P /\
                tile_tree P taup = tile_tree P tau /\
                tile_k tau <= tile_k taup`,
  REPEAT STRIP_TAC THEN
  EXISTS_TAC `carleson_rep P (tile_tree P (tau:int#int#int))` THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`;
    `tau:int#int#int`] CARLESON_REP_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[carleson_Rtilde; IN_IMAGE] THEN
    EXISTS_TAC `tile_tree P (tau:int#int#int)` THEN REWRITE_TAC[] THEN
    REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `tau:int#int#int` THEN
    REWRITE_TAC[IN_UNIV];
    FIRST_X_ASSUM MATCH_MP_TAC THEN REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286K(a-ii) greedy stopping-time sequence: definitions + structural facts. *)
(* Fremlin chooses tau_0,tau_1,... and P_0,P_1,... with P_0=P; R_j = the     *)
(* tiles                                                                     *)
(* in the finite representative set Rt whose tree still carries >= 1/4 gam^2 *)
(* muI energy; tau_j = the leftmost-y member of R_j; P_{j+1}=P_j\{tau_j}+;   *)
(* stop                                                                      *)
(* when R_j empties. We model P_j as ITER j (carleson_estep ...) P; estep is *)
(* the identity once R_j is empty (making the recursion total).              *)
(* ------------------------------------------------------------------------- *)

(* R_j = {tau in Rt : 1/4 gam^2 muI_tau <= Delta_f(P_j cap T_tau)} (Q =      *)
(* P_j).                                                                     *)
let carleson_Rset = new_definition
 `carleson_Rset (f:real->complex) gam Rt Q =
    {tau | tau IN Rt /\
           &1 / &4 * gam pow 2 * &2 zpow (--(tile_k tau)) <=
           delta_f f (tile_tree Q tau)}`;;

(* leftmost-y root of R_j (Fremlin: member of R_j with y_tau as far left as  *)
(* possible).  SELECT; well-defined when R_j is finite and non-empty.        *)
let carleson_eroot = new_definition
 `carleson_eroot (f:real->complex) gam Rt Q =
    @tau. tau IN carleson_Rset f gam Rt Q /\
          (!s. s IN carleson_Rset f gam Rt Q ==> tile_yfull tau <= tile_yfull
            s)`;;

(* one greedy step: if R_j empty, stop (identity); else remove {root_j}+.    *)
let carleson_estep = new_definition
 `carleson_estep (f:real->complex) gam Rt Q =
    if carleson_Rset f gam Rt Q = {}
    then Q else Q DIFF tile_upset {carleson_eroot f gam Rt Q}`;;

(* R_j SUBSET Rt (so R_j is finite when Rt is).                              *)
let CARLESON_RSET_SUBSET = prove
 (`!f gam Rt Q. carleson_Rset f gam Rt Q SUBSET Rt`,
  REWRITE_TAC[carleson_Rset; SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

(* estep shrinks the tile-set (P_{j+1} SUBSET P_j).                          *)
let CARLESON_ESTEP_SUBSET = prove
 (`!f gam Rt Q. carleson_estep f gam Rt Q SUBSET Q`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_estep] THEN
  COND_CASES_TAC THEN REWRITE_TAC[SUBSET_REFL] THEN SET_TAC[]);;

(* the leftmost-y root exists in R_j and is leftmost, when Rt finite, R_j    *)
(* nonempty.                                                                 *)
let CARLESON_EROOT_SPEC = prove
 (`!f gam Rt Q. FINITE Rt /\ ~(carleson_Rset f gam Rt Q = {})
     ==> carleson_eroot f gam Rt Q IN carleson_Rset f gam Rt Q /\
         (!s. s IN carleson_Rset f gam Rt Q
              ==> tile_yfull (carleson_eroot f gam Rt Q) <= tile_yfull s)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[carleson_eroot] THEN
  CONV_TAC SELECT_CONV THEN ABBREV_TAC `RJ = carleson_Rset f gam Rt Q` THEN
  SUBGOAL_THEN `FINITE(RJ:(int#int#int)->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "RJ" THEN MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `Rt:(int#int#int)->bool` THEN
      ASM_REWRITE_TAC[CARLESON_RSET_SUBSET]; ALL_TAC] THEN
  MP_TAC(ISPEC `IMAGE (tile_yfull:int#int#int->real) RJ` INF_FINITE) THEN
  ASM_SIMP_TAC[FINITE_IMAGE; IMAGE_EQ_EMPTY; FORALL_IN_IMAGE] THEN
  REWRITE_TAC[IN_IMAGE] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN
    `tau:int#int#int` STRIP_ASSUME_TAC) ASSUME_TAC) THEN
  EXISTS_TAC `tau:int#int#int` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `s:int#int#int`) THEN ASM_REWRITE_TAC[]);;

(* the down-cone tree of tau is contained in the up-set {tau}+               *)
(* (tile_ler=>tile_le).                                                      *)
let TILE_TREE_SUBSET_UPSET = prove
 (`!Q tau:int#int#int. tile_tree Q tau SUBSET tile_upset {tau}`,
  REWRITE_TAC[tile_tree; tile_upset; SUBSET; IN_ELIM_THM; IN_SING] THEN
  REPEAT STRIP_TAC THEN EXISTS_TAC `tau:int#int#int` THEN
    ASM_SIMP_TAC[TILE_LER_IMP_LE]);;

(* STRICT shrink: when gam>0, Rt finite and R_j nonempty, estep drops at     *)
(* least                                                                     *)
(* the (nonempty) tree of the root -- so P_{j+1} is a PROPER subset of P_j.  *)
(* The                                                                       *)
(* termination driver: the induction cannot run forever on a finite P.       *)
let CARLESON_ESTEP_PSUBSET = prove
 (`!f gam Rt Q. &0 < gam /\ FINITE Rt /\ ~(carleson_Rset f gam Rt Q = {})
     ==> carleson_estep f gam Rt Q PSUBSET Q`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[PSUBSET] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[carleson_estep] THEN COND_CASES_TAC THEN
    ASM_REWRITE_TAC[SUBSET_REFL] THEN SET_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `rt = carleson_eroot f gam Rt Q` THEN
  MP_TAC(ISPECL
    [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
     `Q:(int#int#int)->bool`]
    CARLESON_EROOT_SPEC) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o CONJUNCT1) THEN
  REWRITE_TAC[carleson_Rset; IN_ELIM_THM] THEN STRIP_TAC THEN
  SUBGOAL_THEN `~(tile_tree Q (rt:int#int#int) = {})` MP_TAC THENL
   [DISCH_TAC THEN
    UNDISCH_TAC `&1 / &4 * gam pow 2 * &2 zpow (--tile_k rt) <=
                 delta_f f (tile_tree Q (rt:int#int#int))` THEN
    ASM_REWRITE_TAC[delta_f; SUM_CLAUSES] THEN REWRITE_TAC[REAL_NOT_LE] THEN
    MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC]];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  DISCH_THEN(X_CHOOSE_TAC `sig:int#int#int`) THEN
  SUBGOAL_THEN `(sig:int#int#int) IN Q` ASSUME_TAC THENL
   [UNDISCH_TAC `(sig:int#int#int) IN tile_tree Q rt` THEN
    REWRITE_TAC[tile_tree; IN_ELIM_THM] THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(sig:int#int#int) IN tile_upset {rt}` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`Q:(int#int#int)->bool`;
     `rt:int#int#int`] TILE_TREE_SUBSET_UPSET) THEN
    REWRITE_TAC[SUBSET] THEN DISCH_THEN(MP_TAC o SPEC `sig:int#int#int`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_TAC THEN
  UNDISCH_TAC `carleson_estep f gam Rt Q = Q` THEN
  REWRITE_TAC[carleson_estep] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[EXTENSION] THEN DISCH_THEN(MP_TAC o SPEC `sig:int#int#int`) THEN
  ASM_REWRITE_TAC[IN_DIFF]);;

(* R_j is ANTITONE in Q: a smaller tile-set gives a smaller selection set.   *)
(* Q' SUBSET Q (Q finite) ==> R_j(Q') SUBSET R_j(Q). Since P_{j+1} SUBSET    *)
(* P_j,                                                                      *)
(* this gives R_{j+1} SUBSET R_j -- Fremlin's "R_{j+1} SUBSET R_j for every  *)
(* j".                                                                       *)
(* (Delta_f monotone in the tree, which is monotone in the tile-set.)        *)
let CARLESON_RSET_ANTITONE = prove
 (`!f gam Rt Q Q'. FINITE Q /\ Q' SUBSET Q
     ==> carleson_Rset f gam Rt Q' SUBSET carleson_Rset f gam Rt Q`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Rset; SUBSET; IN_ELIM_THM] THEN
  X_GEN_TAC `tau:int#int#int` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `delta_f f (tile_tree Q' (tau:int#int#int))` THEN
    ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC DELTA_MONO THEN CONJ_TAC THENL
   [ASM_MESON_TAC[TILE_TREE_FINITE];
    MATCH_MP_TAC TILE_TREE_MONO_SET THEN ASM_REWRITE_TAC[]]);;

(* single-step leftmost-y monotonicity: if R_j nonempty AND R_{j+1} (=R_j at *)
(* a                                                                         *)
(* subset Q') nonempty and R_{j+1} SUBSET R_j, the leftmost-y root cannot    *)
(* move                                                                      *)
(* left. root(Q') in R_j+1 SUBSET R_j and root(Q) is leftmost in R_j. This   *)
(* is                                                                        *)
(* Fremlin's "y_{tau_{j+1}} >= y_{tau_j}".                                   *)
let CARLESON_EROOT_MONO_STEP = prove
 (`!f gam Rt Q Q'.
     FINITE Rt /\
     ~(carleson_Rset f gam Rt Q = {}) /\ ~(carleson_Rset f gam Rt Q' = {}) /\
     carleson_Rset f gam Rt Q' SUBSET carleson_Rset f gam Rt Q
     ==> tile_yfull (carleson_eroot f gam Rt Q)
          <= tile_yfull (carleson_eroot f gam Rt Q')`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
    [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
     `Q:(int#int#int)->bool`]
    CARLESON_EROOT_SPEC) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o CONJUNCT2) THEN
  DISCH_THEN(MP_TAC o SPEC `carleson_eroot f gam Rt Q'`) THEN
  ANTS_TAC THENL
   [FIRST_X_ASSUM(MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    MP_TAC(ISPECL
      [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
       `Q':(int#int#int)->bool`]
      CARLESON_EROOT_SPEC) THEN ASM_REWRITE_TAC[] THEN SIMP_TAC[];
    SIMP_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The greedy SEQUENCE P_n = ITER n (estep) P, the root/piece/selection at   *)
(* stage n, and the index-monotone root-y -- the combinatorial backbone of   *)
(* 286K(a-iii)'s ordering. Fremlin's y_{tau_{j+1}} >= y_{tau_j} chained:     *)
(* over                                                                      *)
(* active stages (R_n nonempty) the leftmost-y roots are non-decreasing, so  *)
(* y_{tau_j} < y_{tau_l} forces j < l -- placing sigma (in P_l) inside       *)
(* P_{j+1}.                                                                  *)
(* ------------------------------------------------------------------------- *)

(* P_n = the n-th stage of the greedy recursion (identity once R_n empties). *)
let carleson_Pseq = new_definition
 `carleson_Pseq (f:real->complex) gam Rt P n = ITER n (carleson_estep f gam Rt)
   P`;;

let CARLESON_PSEQ_0 = prove
 (`!f gam Rt P. carleson_Pseq f gam Rt P 0 = P`,
  REWRITE_TAC[carleson_Pseq; ITER]);;

let CARLESON_PSEQ_SUC = prove
 (`!f gam Rt P n. carleson_Pseq f gam Rt P (SUC n) =
                  carleson_estep f gam Rt (carleson_Pseq f gam Rt P n)`,
  REWRITE_TAC[carleson_Pseq; ITER]);;

let CARLESON_PSEQ_STEP_SUBSET = prove
 (`!f gam Rt P n. carleson_Pseq f gam Rt P (SUC n) SUBSET carleson_Pseq f gam
   Rt P n`,
  REWRITE_TAC[CARLESON_PSEQ_SUC; CARLESON_ESTEP_SUBSET]);;

let CARLESON_PSEQ_MONO = prove
 (`!f gam Rt P m n. m <= n
     ==> carleson_Pseq f gam Rt P n SUBSET carleson_Pseq f gam Rt P m`,
  REPEAT GEN_TAC THEN REWRITE_TAC[LE_EXISTS] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num` SUBST1_TAC) THEN
  SPEC_TAC(`d:num`,`d:num`) THEN INDUCT_TAC THEN
  REWRITE_TAC[ADD_CLAUSES; SUBSET_REFL] THEN
  MATCH_MP_TAC SUBSET_TRANS THEN
  EXISTS_TAC `carleson_Pseq f gam Rt P (m + d)` THEN
  ASM_REWRITE_TAC[ADD_SUC; CARLESON_PSEQ_STEP_SUBSET]);;

let CARLESON_PSEQ_SUBSET_P = prove
 (`!f gam Rt P n. carleson_Pseq f gam Rt P n SUBSET P`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL
    [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
     `P:(int#int#int)->bool`;
    `0`;`n:num`] CARLESON_PSEQ_MONO) THEN
  REWRITE_TAC[LE_0; CARLESON_PSEQ_0]);;

let CARLESON_PSEQ_FINITE = prove
 (`!f gam Rt P n. FINITE P ==> FINITE(carleson_Pseq f gam Rt P n)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `P:(int#int#int)->bool` THEN
    ASM_REWRITE_TAC[CARLESON_PSEQ_SUBSET_P]);;

(* root at stage n; extracted piece P'_n = P_n cap T_{tau_n}; selection R_n. *)
let carleson_rootseq = new_definition
 `carleson_rootseq (f:real->complex) gam Rt P n =
    carleson_eroot f gam Rt (carleson_Pseq f gam Rt P n)`;;
let carleson_piece = new_definition
 `carleson_piece (f:real->complex) gam Rt P n =
    tile_tree (carleson_Pseq f gam Rt P n) (carleson_rootseq f gam Rt P n)`;;
let carleson_Rseq = new_definition
 `carleson_Rseq (f:real->complex) gam Rt P n =
    carleson_Rset f gam Rt (carleson_Pseq f gam Rt P n)`;;

(* R_{n+1} SUBSET R_n, and R_n SUBSET R_m for m<=n.                          *)
let CARLESON_RSEQ_ANTITONE = prove
 (`!f gam Rt P n. FINITE P
     ==> carleson_Rseq f gam Rt P (SUC n) SUBSET carleson_Rseq f gam Rt P n`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Rseq] THEN
  MATCH_MP_TAC CARLESON_RSET_ANTITONE THEN
  ASM_SIMP_TAC[CARLESON_PSEQ_FINITE; CARLESON_PSEQ_STEP_SUBSET]);;

let CARLESON_RSEQ_MONO = prove
 (`!f gam Rt P m n. FINITE P /\ m <= n
     ==> carleson_Rseq f gam Rt P n SUBSET carleson_Rseq f gam Rt P m`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_Rseq] THEN STRIP_TAC THEN
  MATCH_MP_TAC CARLESON_RSET_ANTITONE THEN
  ASM_SIMP_TAC[CARLESON_PSEQ_FINITE] THEN
  MATCH_MP_TAC CARLESON_PSEQ_MONO THEN ASM_REWRITE_TAC[]);;

(* R_n nonempty => R_j nonempty for all j<=n (the active stages form a       *)
(* prefix).                                                                  *)
let CARLESON_RSEQ_NONEMPTY_DOWN = prove
 (`!f gam Rt P n j. FINITE P /\ j <= n /\ ~(carleson_Rseq f gam Rt P n = {})
     ==> ~(carleson_Rseq f gam Rt P j = {})`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
    [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
     `P:(int#int#int)->bool`;
    `j:num`;`n:num`] CARLESON_RSEQ_MONO) THEN
  ASM_REWRITE_TAC[] THEN ASM SET_TAC[]);;

(* single-step index-monotone root-y (over active stages).                   *)
let CARLESON_ROOTSEQ_MONO_STEP = prove
 (`!f gam Rt P n. FINITE Rt /\ FINITE P /\ ~(carleson_Rseq f gam Rt P (SUC n) =
   {})
     ==> tile_yfull (carleson_rootseq f gam Rt P n)
          <= tile_yfull (carleson_rootseq f gam Rt P (SUC n))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_rootseq] THEN
  MATCH_MP_TAC CARLESON_EROOT_MONO_STEP THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `~(carleson_Rseq f gam Rt P (SUC n) = {})` MP_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[carleson_Rseq; GSYM CARLESON_PSEQ_SUC] THEN DISCH_TAC THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
      `P:(int#int#int)->bool`;`n:num`]
      CARLESON_RSEQ_ANTITONE) THEN ASM_REWRITE_TAC[carleson_Rseq] THEN
    UNDISCH_TAC `~(carleson_Rset f gam Rt (carleson_Pseq f gam Rt P (SUC n)) =
      {})` THEN
    REWRITE_TAC[GSYM CARLESON_PSEQ_SUC] THEN SET_TAC[];
    MP_TAC(ISPECL
      [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
       `P:(int#int#int)->bool`;`n:num`]
      CARLESON_RSEQ_ANTITONE) THEN ASM_REWRITE_TAC[carleson_Rseq]]);;

(* full index-monotone root-y: m<=n, R_n nonempty => y_{tau_m}<=y_{tau_n}.   *)
(* Fremlin's "y_{tau_{j+1}} >= y_{tau_j}", chained. Contrapositive:          *)
(* y_{tau_j}<                                                                *)
(* y_{tau_l} => j<l -- the ordering a-iii uses to put sigma in P_l SUBSET    *)
(* P_{j+1}.                                                                  *)
let CARLESON_ROOTSEQ_MONO = prove
 (`!f gam Rt P m n. FINITE Rt /\ FINITE P /\ m <= n /\
     ~(carleson_Rseq f gam Rt P n = {})
     ==> tile_yfull (carleson_rootseq f gam Rt P m)
          <= tile_yfull (carleson_rootseq f gam Rt P n)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[LE_EXISTS] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `d:num` SUBST_ALL_TAC) THEN
  UNDISCH_TAC `~(carleson_Rseq f gam Rt P (m + d) = {})` THEN
  SPEC_TAC(`d:num`,`d:num`) THEN INDUCT_TAC THEN
  REWRITE_TAC[ADD_CLAUSES; REAL_LE_REFL] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `tile_yfull (carleson_rootseq f gam Rt P (m + d))` THEN
    CONJ_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN
    MP_TAC(ISPECL
      [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
       `P:(int#int#int)->bool`;
      `SUC(m + d):num`;`m + d:num`] CARLESON_RSEQ_NONEMPTY_DOWN) THEN
    ASM_REWRITE_TAC[LE] THEN DISCH_THEN MATCH_MP_TAC THEN DISJ2_TAC THEN
      ARITH_TAC;
    MATCH_MP_TAC CARLESON_ROOTSEQ_MONO_STEP THEN
    ASM_REWRITE_TAC[ADD_SUC]]);;

(* ------------------------------------------------------------------------- *)
(* 286K(a-iii) the ORDERING fact [star]: for sigma in the extracted piece    *)
(* P'_l                                                                      *)
(* (root tau_l) and an earlier active root tau_j whose interval J_{tau_j}    *)
(* lies                                                                      *)
(* in the LEFT half J^l_sigma, sigma is NOT >= tau_j (~tile_le sigma tau_j). *)
(* Sole sequence-dependent input to a-iii's disjointness (rest is geometry:  *)
(* AIII_SAMEJ_DISJOINT + AIII_DIFFJ_BRANCH).                                 *)
(* ------------------------------------------------------------------------- *)

(* when R_j nonempty, P_{j+1} = P_j \ {root}+, so membership excludes the    *)
(* root+.                                                                    *)
let CARLESON_ESTEP_EXCLUDES_ROOT = prove
 (`!f gam Rt P n sigma.
     ~(carleson_Rseq f gam Rt P n = {}) /\
     sigma IN carleson_Pseq f gam Rt P (SUC n)
     ==> ~(tile_le sigma (carleson_rootseq f gam Rt P n))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[CARLESON_PSEQ_SUC; carleson_rootseq; carleson_estep] THEN
  REWRITE_TAC[GSYM carleson_Rseq] THEN COND_CASES_TAC THEN
    ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[IN_DIFF; tile_upset; IN_ELIM_THM; IN_SING] THEN MESON_TAC[]);;

(* sigma in piece n => sigma in P_n.                                         *)
let CARLESON_PIECE_IN_PSEQ = prove
 (`!f gam Rt P n sigma. sigma IN carleson_piece f gam Rt P n
     ==> sigma IN carleson_Pseq f gam Rt P n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_piece; tile_tree; IN_ELIM_THM] THEN
    SIMP_TAC[]);;

(* sigma in piece n => sigma <=_r root_n (it is in the root's down-cone      *)
(* tree).                                                                    *)
let CARLESON_PIECE_LER_ROOT = prove
 (`!f gam Rt P n sigma. sigma IN carleson_piece f gam Rt P n
     ==> tile_ler sigma (carleson_rootseq f gam Rt P n)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_piece; tile_tree; IN_ELIM_THM] THEN
    SIMP_TAC[]);;

(* THE ORDERING FACT [star]. Chain: sigma in piece l => tile_ler sigma       *)
(* tau_l;                                                                    *)
(* TILE_YFULL_ORDER => y_{tau_j} < y_{tau_l}; ROOTSEQ_MONO contrapositive => *)
(* j<l;                                                                      *)
(* PSEQ_MONO => sigma in P_{j+1}; ESTEP_EXCLUDES_ROOT => ~(tile_le sigma     *)
(* tau_j).                                                                   *)
let CARLESON_AIII_ORDER = prove
 (`!f gam Rt P j l sigma.
     FINITE Rt /\ FINITE P /\
     sigma IN carleson_piece f gam Rt P l /\
     ~(carleson_Rseq f gam Rt P l = {}) /\
     ~(carleson_Rseq f gam Rt P j = {}) /\
     tile_J (carleson_rootseq f gam Rt P j) SUBSET tile_Jl sigma
     ==> ~(tile_le sigma (carleson_rootseq f gam Rt P j))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP CARLESON_PIECE_LER_ROOT) THEN
  SUBGOAL_THEN `tile_yfull (carleson_rootseq f gam Rt P j)
                 < tile_yfull (carleson_rootseq f gam Rt P l)` ASSUME_TAC THENL
   [MATCH_MP_TAC TILE_YFULL_ORDER THEN
    EXISTS_TAC `sigma:int#int#int` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `j:num < l` ASSUME_TAC THENL
   [MP_TAC(ISPECL
     [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
      `P:(int#int#int)->bool`;
      `l:num`;`j:num`] CARLESON_ROOTSEQ_MONO) THEN
    ASM_CASES_TAC `j:num < l` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `l:num <= j` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC CARLESON_ESTEP_EXCLUDES_ROOT THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL
    [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
     `P:(int#int#int)->bool`;
    `SUC j`;`l:num`] CARLESON_PSEQ_MONO) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
  MATCH_MP_TAC CARLESON_PIECE_IN_PSEQ THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286K(a-ii) TERMINATION: the greedy induction stops (some R_n empties).    *)
(* While stages 0..n-1 are all active, each strictly shrinks the finite P    *)
(* (via                                                                      *)
(* CARLESON_ESTEP_PSUBSET), so CARD P_n + n <= CARD P; hence R_n is nonempty *)
(* for                                                                       *)
(* at most CARD P stages -- Fremlin's "the induction must stop at a finite   *)
(* stage".                                                                   *)
(* ------------------------------------------------------------------------- *)

let CARLESON_PSEQ_CARD_DECR = prove
 (`!f gam Rt P n. &0 < gam /\ FINITE Rt /\ FINITE P
     ==> (!j. j < n ==> ~(carleson_Rseq f gam Rt P j = {}))
         ==> CARD(carleson_Pseq f gam Rt P n) + n <= CARD P`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPEC_TAC(`n:num`,`n:num`) THEN
    INDUCT_TAC THENL
   [REWRITE_TAC[CARLESON_PSEQ_0; ADD_CLAUSES; LE_REFL]; ALL_TAC] THEN
     DISCH_TAC THEN
  SUBGOAL_THEN `~(carleson_Rseq f gam Rt P n = {})` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN REWRITE_TAC[LT] THEN
    DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `CARD(carleson_Pseq f gam Rt P n) + n <= CARD P` ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN GEN_TAC THEN DISCH_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `CARD(carleson_Pseq f gam Rt P (SUC n)) < CARD(carleson_Pseq f gam Rt P n)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC CARD_PSUBSET THEN CONJ_TAC THENL
     [REWRITE_TAC[CARLESON_PSEQ_SUC] THEN
       MATCH_MP_TAC CARLESON_ESTEP_PSUBSET THEN
      ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `~(carleson_Rseq f gam Rt P n = {})` THEN
      REWRITE_TAC[carleson_Rseq]; ASM_SIMP_TAC[CARLESON_PSEQ_FINITE]];
    ASM_ARITH_TAC]);;

(* SOME stage has empty selection set (the induction stops). By              *)
(* contradiction:                                                            *)
(* if all R_n nonempty, CARD_DECR at n=CARD P+1 gives CARD P_{..}+(CARD      *)
(* P+1)<=                                                                    *)
(* CARD P, impossible.                                                       *)
let CARLESON_RSEQ_STOPS = prove
 (`!f gam Rt P. &0 < gam /\ FINITE Rt /\ FINITE P
     ==> ?n. carleson_Rseq f gam Rt P n = {}`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `?n. carleson_Rseq f gam Rt P n = {}` THEN
    ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[NOT_EXISTS_THM]) THEN DISCH_TAC THEN
  MP_TAC(ISPECL
    [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
     `P:(int#int#int)->bool`;
    `SUC(CARD(P:(int#int#int)->bool))`] CARLESON_PSEQ_CARD_DECR) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* 286K(a-ii) STOPPING energy bound: at a stage where R_N empties, the       *)
(* residual                                                                  *)
(* energy_f f P_N <= gam/2.  The finite R~ selection test controls ALL tiles *)
(* (via the representative property CARLESON_RTILDE_REP), so                 *)
(* ENERGY_THRESHOLD                                                          *)
(* applies.  This is Fremlin's a-ii closing display energy_f(P_n) <= gam/2.  *)
(* ------------------------------------------------------------------------- *)

(* tile_tree restricted to a subset.                                         *)
let TILE_TREE_RESTRICT = prove
 (`!P Q t:int#int#int. Q SUBSET P ==> tile_tree Q t = tile_tree P t INTER Q`,
  REPEAT STRIP_TAC THEN SUBGOAL_THEN
    `Q:(int#int#int)->bool = P INTER Q` SUBST1_TAC THENL
   [ASM SET_TAC[]; ALL_TAC] THEN REWRITE_TAC[TILE_TREE_INTER] THEN
  SUBGOAL_THEN `(P INTER Q:(int#int#int)->bool) = Q` SUBST1_TAC THENL
   [ASM SET_TAC[]; REFL_TAC]);;

(* equal trees on P give equal trees on any subset Q.                        *)
let TILE_TREE_EQ_RESTRICT = prove
 (`!P Q s t:int#int#int. Q SUBSET P /\ tile_tree P s = tile_tree P t
     ==> tile_tree Q s = tile_tree Q t`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[TILE_TREE_RESTRICT] THEN
    ASM_REWRITE_TAC[]);;

(* tile_tree monotone in the tile-set.                                       *)
let TILE_TREE_SUBSET_MONO = prove
 (`!P Q t:int#int#int. Q SUBSET P ==> tile_tree Q t SUBSET tile_tree P t`,
  REWRITE_TAC[tile_tree; SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

(* per-tile energy threshold at the stopping stage (Rt = R~, R_N = {}).      *)
let CARLESON_STOP_TILE_THRESHOLD = prove
 (`!f gam P N tau:int#int#int.
     &0 < gam /\ FINITE P /\
     carleson_Rset f gam (carleson_Rtilde P)
       (carleson_Pseq f gam (carleson_Rtilde P) P N) = {}
     ==> &2 zpow (tile_k tau) *
         delta_f f (tile_tree (carleson_Pseq f gam (carleson_Rtilde P) P N)
           tau)
         <= (gam / &2) pow 2`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `PN = carleson_Pseq f gam (carleson_Rtilde P) P N` THEN
  SUBGOAL_THEN `(PN:(int#int#int)->bool) SUBSET P` ASSUME_TAC THENL
   [EXPAND_TAC "PN" THEN REWRITE_TAC[CARLESON_PSEQ_SUBSET_P]; ALL_TAC] THEN
  ASM_CASES_TAC `tile_tree (PN:(int#int#int)->bool) tau = {}` THENL
   [ASM_REWRITE_TAC[delta_f; SUM_CLAUSES; REAL_MUL_RZERO; REAL_LE_POW_2];
     ALL_TAC] THEN
  SUBGOAL_THEN `~(tile_tree P (tau:int#int#int) = {})` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`P:(int#int#int)->bool`; `PN:(int#int#int)->bool`;
     `tau:int#int#int`]
      TILE_TREE_SUBSET_MONO) THEN ASM_REWRITE_TAC[] THEN
        ASM SET_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`;
    `tau:int#int#int`] CARLESON_RTILDE_REP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `taup:int#int#int` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `delta_f f (tile_tree PN (taup:int#int#int))
      < &1 / &4 * gam pow 2 * &2 zpow (--(tile_k taup))` ASSUME_TAC THENL
   [MP_TAC(ASSUME `carleson_Rset f gam (carleson_Rtilde P) PN = {}`) THEN
    REWRITE_TAC[EXTENSION; NOT_IN_EMPTY; carleson_Rset; IN_ELIM_THM] THEN
    DISCH_THEN(MP_TAC o SPEC `taup:int#int#int`) THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `tile_tree (PN:(int#int#int)->bool) tau =
     tile_tree PN taup` SUBST1_TAC THENL
   [MATCH_MP_TAC TILE_TREE_EQ_RESTRICT THEN
     EXISTS_TAC `P:(int#int#int)->bool` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 zpow (tile_k taup) * delta_f f (tile_tree PN
    (taup:int#int#int))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_RMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC ZPOW2_MONOE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[DELTA_POS]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&2 zpow (tile_k taup) * (&1 / &4 * gam pow 2 * &2 zpow (--(tile_k
    taup)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      ASM_SIMP_TAC[REAL_LT_IMP_LE]];
    REWRITE_TAC[REAL_ZPOW_NEG] THEN
    SUBGOAL_THEN `&0 < &2 zpow (tile_k taup)` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
    ABBREV_TAC `z = &2 zpow (tile_k (taup:int#int#int))` THEN
    SUBGOAL_THEN
      `z * (&1 / &4 * gam pow 2 * inv z) = &1 / &4 * gam pow 2 * (z * inv z)`
     SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `z * inv z = &1` SUBST1_TAC THENL
     [MATCH_MP_TAC REAL_MUL_RINV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_MUL_RID] THEN CONV_TAC REAL_FIELD]);;

(* Fremlin's a-ii stopping bound: energy_f f P_N <= gam/2 at a stopping      *)
(* stage.                                                                    *)
let CARLESON_STOP_ENERGY = prove
 (`!f gam P N. &0 < gam /\ FINITE P /\
     carleson_Rset f gam (carleson_Rtilde P)
       (carleson_Pseq f gam (carleson_Rtilde P) P N) = {}
     ==> energy_f f (carleson_Pseq f gam (carleson_Rtilde P) P N) <= gam / &2`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC ENERGY_THRESHOLD THEN
  CONJ_TAC THENL [ASM_SIMP_TAC[CARLESON_PSEQ_FINITE]; ALL_TAC] THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  GEN_TAC THEN MATCH_MP_TAC CARLESON_STOP_TILE_THRESHOLD THEN
    ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286K(a-iii) the full disjointness over the extracted set P'.  The least   *)
(* stopping stage N (num MINIMAL), the extracted tile-set P' = UNIONS of the *)
(* active pieces, the root set R = active roots, and the a-iii disjointness: *)
(* distinct sigma,tau in P' with J^l meeting => I_sigma, I_tau disjoint.     *)
(* ------------------------------------------------------------------------- *)

(* least stopping stage N (R_N = {}, all earlier active).                    *)
let carleson_stopN = new_definition
 `carleson_stopN f gam P = minimal n. carleson_Rseq f gam (carleson_Rtilde P) P
   n = {}`;;

let CARLESON_STOPN_SPEC = prove
 (`!f gam P. &0 < gam /\ FINITE P
     ==> carleson_Rseq f gam (carleson_Rtilde P) P (carleson_stopN f gam P) =
       {} /\
         (!j. j < carleson_stopN f gam P
              ==> ~(carleson_Rseq f gam (carleson_Rtilde P) P j = {}))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[carleson_stopN] THEN
  MP_TAC(ISPEC `\n. carleson_Rseq f gam (carleson_Rtilde P) P n = {}` MINIMAL)
    THEN
  BETA_TAC THEN
  SUBGOAL_THEN
    `?n. carleson_Rseq f gam (carleson_Rtilde P) P n = {}` MP_TAC THENL
   [MATCH_MP_TAC CARLESON_RSEQ_STOPS THEN ASM_SIMP_TAC[CARLESON_RTILDE_FINITE];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN MESON_TAC[]]);;

(* extracted tile-set P' = union of the active pieces; root set R = active   *)
(* roots.                                                                    *)
let carleson_Pextract = new_definition
 `carleson_Pextract f gam P =
    UNIONS (IMAGE (carleson_piece f gam (carleson_Rtilde P) P)
                  {j | j < carleson_stopN f gam P})`;;
let carleson_Rextract = new_definition
 `carleson_Rextract f gam P =
    IMAGE (carleson_rootseq f gam (carleson_Rtilde P) P)
          {j | j < carleson_stopN f gam P}`;;

let CARLESON_PEXTRACT_MEM = prove
 (`!f gam P sigma. sigma IN carleson_Pextract f gam P <=>
     ?j. j < carleson_stopN f gam P /\
         sigma IN carleson_piece f gam (carleson_Rtilde P) P j`,
  REPEAT GEN_TAC THEN
    REWRITE_TAC[carleson_Pextract; UNIONS_IMAGE; IN_ELIM_THM]);;

let CARLESON_ACTIVE_RSEQ = prove
 (`!f gam P j. &0 < gam /\ FINITE P /\ j < carleson_stopN f gam P
     ==> ~(carleson_Rseq f gam (carleson_Rtilde P) P j = {})`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`]
    CARLESON_STOPN_SPEC) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o CONJUNCT2) THEN
  DISCH_THEN(MP_TAC o SPEC `j:num`) THEN ASM_REWRITE_TAC[]);;

(* diffj core: sigma,tau in P', J_sigma SUBSET J^l_tau ==> DISJOINT I_sigma  *)
(* I_tau. sigma in piece j (root tau_j); J_{tau_j} SUBSET J_sigma SUBSET     *)
(* J^l_tau; tau in piece m; CARLESON_AIII_ORDER (on tau) gives ~tile_le tau  *)
(* tau_j; AIII_DIFFJ_BRANCH.                                                 *)
let CARLESON_AIII_DIFFJ = prove
 (`!f gam P sigma tau. &0 < gam /\ FINITE P /\
     sigma IN carleson_Pextract f gam P /\ tau IN carleson_Pextract f gam P /\
     tile_J sigma SUBSET tile_Jl tau
     ==> DISJOINT (tile_I sigma) (tile_I tau)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[CARLESON_PEXTRACT_MEM] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `m:num` STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `j:num` STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC AIII_DIFFJ_BRANCH THEN
  EXISTS_TAC `carleson_rootseq f gam (carleson_Rtilde P) P j` THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC CARLESON_PIECE_LER_ROOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC CARLESON_AIII_ORDER THEN EXISTS_TAC `m:num` THEN
  ASM_SIMP_TAC[CARLESON_RTILDE_FINITE; CARLESON_ACTIVE_RSEQ] THEN
  MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `tile_J sigma` THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `tile_ler sigma (carleson_rootseq f gam (carleson_Rtilde P) P j)`
     MP_TAC THENL
   [MATCH_MP_TAC CARLESON_PIECE_LER_ROOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o MATCH_MP TILE_LER_IMP_LE) THEN
  REWRITE_TAC[tile_le] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* full a-iii: distinct sigma,tau in P' with J^l meeting ==> DISJOINT I.     *)
(* J_sigma=                                                                  *)
(* J_tau -> AIII_SAMEJ; else TILE_JL_OFFDIAG_DICHOTOMY -> WLOG diffj (2      *)
(* symmetric).                                                               *)
let CARLESON_AIII_DISJOINT = prove
 (`!f gam P sigma tau. &0 < gam /\ FINITE P /\
     sigma IN carleson_Pextract f gam P /\ tau IN carleson_Pextract f gam P /\
     ~(sigma = tau) /\ ~DISJOINT (tile_Jl sigma) (tile_Jl tau)
     ==> DISJOINT (tile_I sigma) (tile_I tau)`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `tile_J sigma = tile_J tau` THENL
   [MATCH_MP_TAC AIII_SAMEJ_DISJOINT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`sigma:int#int#int`;
    `tau:int#int#int`] TILE_JL_OFFDIAG_DICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [MATCH_MP_TAC CARLESON_AIII_DIFFJ THEN
    MAP_EVERY EXISTS_TAC [`f:real->complex`; `gam:real`;
      `P:(int#int#int)->bool`] THEN
    ASM_REWRITE_TAC[];
    ONCE_REWRITE_TAC[DISJOINT_SYM] THEN
    MATCH_MP_TAC CARLESON_AIII_DIFFJ THEN
    MAP_EVERY EXISTS_TAC [`f:real->complex`; `gam:real`;
      `P:(int#int#int)->bool`] THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286K(a-ii) TELESCOPE: the iterated estep removals collapse -- P_N = P     *)
(* DIFF                                                                      *)
(* tile_upset(active roots).  At the least stop stage this is P DIFF R+ (R = *)
(* Rextract), so CARLESON_STOP_ENERGY becomes Fremlin's residual energy      *)
(* bound                                                                     *)
(* energy_f f (P DIFF R+) <= gam/2.                                          *)
(* ------------------------------------------------------------------------- *)

let NUMSEG_LT_SUC = prove
 (`!N. {j | j < SUC N} = N INSERT {j | j < N}`,
  GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_INSERT; IN_ELIM_THM] THEN ARITH_TAC);;

let IMAGE_NUMSEG_LT_SUC = prove
 (`!g N. IMAGE g {j | j < SUC N} = (g N) INSERT IMAGE g {j | j < N}`,
  REWRITE_TAC[NUMSEG_LT_SUC; IMAGE_CLAUSES]);;

let TILE_UPSET_INSERT = prove
 (`!a R. tile_upset (a INSERT R) = tile_upset {a} UNION tile_upset R`,
  REWRITE_TAC[tile_upset; EXTENSION; IN_UNION; IN_ELIM_THM; IN_INSERT;
    NOT_IN_EMPTY] THEN
  MESON_TAC[]);;

let TILE_UPSET_EMPTY = prove
 (`tile_upset {} = {}`,
  REWRITE_TAC[tile_upset; NOT_IN_EMPTY; EMPTY_GSPEC]);;

let SET_DIFF_DIFF_UNION = prove
 (`!P A r. P DIFF A DIFF (r UNION {}) = P DIFF (r UNION A)`, SET_TAC[]);;

(* clean per-step identity (R_N nonempty), keeping P_N opaque.               *)
let CARLESON_PSEQ_STEP_ACTIVE = prove
 (`!f gam Rt P N. ~(carleson_Rseq f gam Rt P N = {})
     ==> carleson_Pseq f gam Rt P (SUC N) =
         carleson_Pseq f gam Rt P N DIFF tile_upset {carleson_rootseq f gam Rt
           P N}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[CARLESON_PSEQ_SUC; carleson_estep; carleson_rootseq] THEN
  COND_CASES_TAC THENL
   [UNDISCH_TAC `~(carleson_Rseq f gam Rt P N = {})` THEN
     ASM_REWRITE_TAC[carleson_Rseq];
    REWRITE_TAC[]]);;

(* the telescope over any N with all stages 0..N-1 active.                   *)
let CARLESON_PSEQ_TELESCOPE = prove
 (`!f gam Rt P N. FINITE Rt
     ==> (!j. j < N ==> ~(carleson_Rset f gam Rt (carleson_Pseq f gam Rt P j) =
       {}))
         ==> carleson_Pseq f gam Rt P N =
             P DIFF tile_upset (IMAGE (carleson_rootseq f gam Rt P) {j | j <
               N})`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN SPEC_TAC(`N:num`,`N:num`) THEN
    INDUCT_TAC THENL
   [DISCH_TAC THEN REWRITE_TAC[CARLESON_PSEQ_0] THEN
    SUBGOAL_THEN `{j | j < 0} = {}:num->bool` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY; LT]; ALL_TAC] THEN
    REWRITE_TAC[IMAGE_CLAUSES; TILE_UPSET_EMPTY; DIFF_EMPTY]; ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `carleson_Pseq f gam Rt P N =
    P DIFF tile_upset (IMAGE (carleson_rootseq f gam Rt P) {j | j < N})`
      (LABEL_TAC "IH") THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN GEN_TAC THEN DISCH_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(carleson_Rseq f gam Rt P N = {})` ASSUME_TAC THENL
   [REWRITE_TAC[carleson_Rseq] THEN FIRST_X_ASSUM(MP_TAC o SPEC `N:num`) THEN
    REWRITE_TAC[LT] THEN DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP CARLESON_PSEQ_STEP_ACTIVE th])
    THEN
  USE_THEN "IH" SUBST1_TAC THEN
  REWRITE_TAC[IMAGE_NUMSEG_LT_SUC] THEN
    ONCE_REWRITE_TAC[TILE_UPSET_INSERT] THEN
  REWRITE_TAC[TILE_UPSET_EMPTY; SET_DIFF_DIFF_UNION]);;

(* specialize to the least stop stage N: P_N = P DIFF tile_upset(Rextract).  *)
let CARLESON_PEXTRACT_DIFF = prove
 (`!f gam P. &0 < gam /\ FINITE P
     ==> carleson_Pseq f gam (carleson_Rtilde P) P (carleson_stopN f gam P) =
         P DIFF tile_upset (carleson_Rextract f gam P)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Rextract] THEN
  MP_TAC(ISPECL [`f:real->complex`; `gam:real`; `carleson_Rtilde P`;
    `P:(int#int#int)->bool`;
      `carleson_stopN f gam P`] CARLESON_PSEQ_TELESCOPE) THEN
  ASM_SIMP_TAC[CARLESON_RTILDE_FINITE] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`]
    CARLESON_STOPN_SPEC) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o CONJUNCT2) THEN
    REWRITE_TAC[carleson_Rseq]);;

(* Fremlin's residual energy bound: energy_f f (P DIFF R+) <= gam/2.         *)
let CARLESON_RESIDUAL_ENERGY = prove
 (`!f gam P. &0 < gam /\ FINITE P
     ==> energy_f f (P DIFF tile_upset (carleson_Rextract f gam P)) <= gam /
       &2`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`]
    CARLESON_PEXTRACT_DIFF) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC CARLESON_STOP_ENERGY THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`]
    CARLESON_STOPN_SPEC) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o CONJUNCT1) THEN
    REWRITE_TAC[carleson_Rseq]);;

(* ------------------------------------------------------------------------- *)
(* 286K piece disjointness: the extracted pieces P'_j = P_j cap T_{tau_j} at *)
(* distinct active stages are pairwise disjoint (P'_j SUBSET P_j \ P_{j+1}). *)
(* Needed for delta_f f P' = sum_j delta_f f (P'_j) (DELTA_UNIONS), the      *)
(* measure                                                                   *)
(* budget gam^2 sum_R muI <= 4 delta.                                        *)
(* ------------------------------------------------------------------------- *)

(* piece_j SUBSET P_j \ P_{j+1} (stage j active).                            *)
let CARLESON_PIECE_SUBSET_DIFF = prove
 (`!f gam Rt P j. ~(carleson_Rseq f gam Rt P j = {})
     ==> carleson_piece f gam Rt P j SUBSET
         (carleson_Pseq f gam Rt P j DIFF carleson_Pseq f gam Rt P (SUC j))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP CARLESON_PSEQ_STEP_ACTIVE th])
    THEN
  MATCH_MP_TAC(SET_RULE `s SUBSET a /\ s SUBSET u ==> s SUBSET (a DIFF (a DIFF
    u))`) THEN
  CONJ_TAC THENL
   [REWRITE_TAC[carleson_piece; TILE_TREE_SUBSET];
    REWRITE_TAC[carleson_piece] THEN
    MP_TAC(ISPECL [`carleson_Pseq f gam Rt P j`;
      `carleson_rootseq f gam Rt P j`]
      TILE_TREE_SUBSET_UPSET) THEN REWRITE_TAC[]]);;

(* pieces at distinct active stages are disjoint (j<l; symmetric handled at  *)
(* use).                                                                     *)
let CARLESON_PIECE_DISJOINT = prove
 (`!f gam Rt P j l. j < l /\ ~(carleson_Rseq f gam Rt P j = {})
     ==> DISJOINT (carleson_piece f gam Rt P j) (carleson_piece f gam Rt P l)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
    [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
     `P:(int#int#int)->bool`;`j:num`]
    CARLESON_PIECE_SUBSET_DIFF) THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL
    [`f:real->complex`;`gam:real`;`Rt:(int#int#int)->bool`;
     `P:(int#int#int)->bool`;
    `SUC j`;`l:num`] CARLESON_PSEQ_MONO) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`carleson_Pseq f gam Rt P l`; `carleson_rootseq f gam Rt P l`]
    TILE_TREE_SUBSET) THEN REWRITE_TAC[GSYM carleson_piece] THEN
  REPEAT STRIP_TAC THEN REWRITE_TAC[DISJOINT] THEN ASM SET_TAC[]);;

(* per-root energy lower bound: at an active stage j the root tau_j is in    *)
(* R_j, so                                                                   *)
(* 1/4 gam^2 muI_{tau_j} <= Delta_f(piece_j).  Feeds the measure budget      *)
(* gam^2 sum_R muI <= 4 delta_f f P'.                                        *)
let CARLESON_ROOT_ENERGY_LB = prove
 (`!f gam P j. &0 < gam /\ FINITE P /\ j < carleson_stopN f gam P
     ==> &1 / &4 * gam pow 2 *
         &2 zpow (--(tile_k (carleson_rootseq f gam (carleson_Rtilde P) P j)))
         <= delta_f f (carleson_piece f gam (carleson_Rtilde P) P j)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`carleson_Rtilde P`;
    `carleson_Pseq f gam (carleson_Rtilde P) P j`] CARLESON_EROOT_SPEC) THEN
  SUBGOAL_THEN
    `~(carleson_Rseq f gam (carleson_Rtilde P) P j = {})` MP_TAC THENL
   [MATCH_MP_TAC CARLESON_ACTIVE_RSEQ THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[carleson_Rseq] THEN DISCH_TAC THEN
  ASM_SIMP_TAC[CARLESON_RTILDE_FINITE] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1) THEN
  REWRITE_TAC[carleson_Rset; IN_ELIM_THM; GSYM carleson_rootseq;
    GSYM carleson_piece] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* delta over a disjoint IMAGE-indexed family = sum over indices: delta_f f  *)
(* (UNIONS(IMAGE g II)) = sum_{i in II} delta_f f (g i), for a finite index  *)
(* set II with the g i finite, nonempty, and pairwise disjoint (nonemptiness *)
(* gives g injective on II, so DELTA_UNIONS's set-sum becomes the            *)
(* index-sum).                                                               *)
let DELTA_UNIONS_IMAGE = prove
 (`!(f:real->complex) (g:num->(int#int#int)->bool) II.
     FINITE II /\ (!i. i IN II ==> FINITE (g i)) /\ (!i. i IN II ==> ~(g i =
       {})) /\
     (!i j. i IN II /\ j IN II /\ ~(i = j) ==> DISJOINT (g i) (g j))
     ==> delta_f f (UNIONS (IMAGE g II)) = sum II (\i. delta_f f (g i))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;
    `IMAGE (g:num->(int#int#int)->bool) II`] DELTA_UNIONS) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[FINITE_IMAGE; FORALL_IN_IMAGE] THEN
    REWRITE_TAC[IMP_CONJ; RIGHT_FORALL_IMP_THM; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `a:num` THEN DISCH_TAC THEN X_GEN_TAC `b:num` THEN DISCH_TAC THEN
    DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`g:num->(int#int#int)->bool`;
    `\A:(int#int#int)->bool. delta_f f A`;
    `II:num->bool`] SUM_IMAGE) THEN
  ANTS_TAC THENL
   [MAP_EVERY X_GEN_TAC [`a:num`; `b:num`] THEN STRIP_TAC THEN
    GEN_REWRITE_TAC I [TAUT `p <=> ~ ~p`] THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`a:num`;`b:num`]) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[DISJOINT_EMPTY_REFL; MEMBER_NOT_EMPTY];
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]]);;

(* ------------------------------------------------------------------------- *)
(* 286K measure budget: gam^2 sum_{Rextract} muI <= 4 delta_f f Pextract.    *)
(* The numerator of Fremlin's budget gam^2 sum_R muI <= C6 (with             *)
(* delta<=C6/4).                                                             *)
(* ------------------------------------------------------------------------- *)

(* piece_j is FINITE (SUBSET P).                                             *)
let CARLESON_PIECE_FINITE = prove
 (`!f gam Rt P j. FINITE P ==> FINITE (carleson_piece f gam Rt P j)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_piece] THEN
  MATCH_MP_TAC TILE_TREE_FINITE THEN ASM_SIMP_TAC[CARLESON_PSEQ_FINITE]);;

(* piece_j nonempty when j<N: delta_f f (piece_j) >= 1/4 gam^2 2^{-k} > 0.   *)
let CARLESON_PIECE_NONEMPTY = prove
 (`!f gam P j. &0 < gam /\ FINITE P /\ j < carleson_stopN f gam P
     ==> ~(carleson_piece f gam (carleson_Rtilde P) P j = {})`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`;`j:num`]
    CARLESON_ROOT_ENERGY_LB) THEN
  ASM_REWRITE_TAC[delta_f; SUM_CLAUSES] THEN
  MATCH_MP_TAC(REAL_ARITH `&0 < a ==> ~(a <= &0)`) THEN
  MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
   [REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC]]);;

(* delta_f f Pextract = sum_{j<N} delta_f f (piece_j) (pieces disjoint).     *)
let CARLESON_DELTA_PEXTRACT = prove
 (`!f gam P. &0 < gam /\ FINITE P
     ==> delta_f f (carleson_Pextract f gam P) =
         sum {j | j < carleson_stopN f gam P}
             (\j. delta_f f (carleson_piece f gam (carleson_Rtilde P) P j))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Pextract] THEN
  MATCH_MP_TAC DELTA_UNIONS_IMAGE THEN
  REWRITE_TAC[FINITE_NUMSEG_LT; IN_ELIM_THM] THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN ASM_SIMP_TAC[CARLESON_PIECE_FINITE];
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      MATCH_MP_TAC CARLESON_PIECE_NONEMPTY THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`a:num`;`b:num`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `a:num < b \/ b < a` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      MATCH_MP_TAC CARLESON_PIECE_DISJOINT THEN
        ASM_SIMP_TAC[CARLESON_ACTIVE_RSEQ];
      ONCE_REWRITE_TAC[DISJOINT_SYM] THEN
      MATCH_MP_TAC CARLESON_PIECE_DISJOINT THEN
        ASM_SIMP_TAC[CARLESON_ACTIVE_RSEQ]]]);;

(* THE MEASURE BUDGET: gam^2 sum_{Rextract} 2^{-k} <= 4 delta_f f Pextract.  *)
(* SUM_IMAGE_LE (Rextract = IMAGE rootseq) reduces to sum_{j<N}; per term    *)
(* CARLESON_ROOT_ENERGY_LB x4; DELTA_PEXTRACT collapses the piece-sum.       *)
let CARLESON_MEASURE_BUDGET = prove
 (`!f gam P. &0 < gam /\ FINITE P
     ==> gam pow 2 * sum (carleson_Rextract f gam P) (\t. &2 zpow (--(tile_k
       t)))
         <= &4 * delta_f f (carleson_Pextract f gam P)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `gam pow 2 * sum {j | j < carleson_stopN f gam P}
    (\j. &2 zpow (--(tile_k (carleson_rootseq f gam (carleson_Rtilde P) P
      j))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
    REWRITE_TAC[carleson_Rextract] THEN
    MP_TAC(ISPECL [`carleson_rootseq f gam (carleson_Rtilde P) P`;
      `\t:int#int#int. &2 zpow (--(tile_k t))`;
        `{j | j < carleson_stopN f gam P}`]
      SUM_IMAGE_LE) THEN
    REWRITE_TAC[FINITE_NUMSEG_LT; o_DEF] THEN DISCH_THEN MATCH_MP_TAC THEN
    REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[CARLESON_DELTA_PEXTRACT] THEN
  REWRITE_TAC[GSYM SUM_LMUL] THEN MATCH_MP_TAC SUM_LE THEN
  REWRITE_TAC[FINITE_NUMSEG_LT; IN_ELIM_THM] THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`;`j:num`]
    CARLESON_ROOT_ENERGY_LB) THEN
  ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* 286K(b) GRAM ROOF: given the H_j square-sum bound (sum_s inr_s^2 <= K     *)
(* alpha)                                                                    *)
(* as a hypothesis, delta_f f P <= C3 + sqrt K.  Wires the banked backbone:  *)
(* DELTA_SQ_LE_GRAM (alpha^2<=norm Gram) + CARLESON_NORMSQ_DOUBLE_LE (norm   *)
(* Gram                                                                      *)
(* <=C3 alpha + norm offdiag) + OFFDIAG_LE_INR + OFFBLOCK_CS +               *)
(* GRAM_COMBINE_SQRT.                                                        *)
(* inr_s = the off-diagonal weight-kernel row sum over {t in P, J_t<>J_s}.   *)
(* ------------------------------------------------------------------------- *)

(* Leg 1: alpha^2 <= C3 alpha + norm(offdiag).                               *)
let CARLESON_GRAM_LEG1 = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) C3.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ FINITE P /\
     lnorm (:real^1) (&2) (\z. f(drop z)) <= &1 /\
     (!f' P'. FINITE P' ==> norm(vsum P' (\s. vsum P' (\t.
           carleson_ip f' s * cnj(carleson_ip f' t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))))
         <= C3 * sum P' (\s. norm(carleson_ip f' s) pow 2) +
            norm(vsum P' (\s. vsum {t | t IN P' /\ ~(tile_J t = tile_J s)} (\t.
              carleson_ip f' s * cnj(carleson_ip f' t) *
              lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                 (\z. phi_sigma t carleson_phi (drop z))))))
     ==> (delta_f f P) pow 2 <= C3 * delta_f f P +
         norm(vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
              carleson_ip f s * cnj(carleson_ip f t) *
              lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                 (\z. phi_sigma t carleson_phi (drop z)))))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `norm(vsum P (\s. vsum P (\t.
           carleson_ip f s * cnj(carleson_ip f t) *
           lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                              (\z. phi_sigma t carleson_phi (drop z)))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC DELTA_SQ_LE_GRAM THEN ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(MP_TAC o SPECL [`f:real->complex`;
      `P:(int#int#int)->bool`]) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[GSYM delta_f]]);;

(* Leg 2: norm(offdiag) <= sqrt(alpha) sqrt(K alpha).                        *)
let CARLESON_ROW_MEETING = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) s. FINITE P
     ==> sum {t | t IN P /\ ~(tile_J t = tile_J s)}
             (\t. norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop
               z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                         norm(carleson_ip f t))
         = sum {t | t IN P /\ ~(tile_J t = tile_J s) /\ ~DISJOINT (tile_Jl s)
           (tile_Jl t)}
             (\t. norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop
               z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                         norm(carleson_ip f t))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC SUM_SUPERSET THEN
  CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN GEN_TAC THEN STRIP_TAC THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `t:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN
    `DISJOINT (tile_Jl s) (tile_Jl (t:int#int#int))` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `integral (:real^1) (\z. phi_sigma s carleson_phi (drop z) *
                       cnj(phi_sigma t carleson_phi (drop z))) = Cx(&0)`
   (fun th -> REWRITE_TAC[th; COMPLEX_NORM_0; REAL_MUL_LZERO]) THEN
  MATCH_MP_TAC PHISIG_CARLESON_ORTHO_JL THEN ASM_REWRITE_TAC[]);;

(* meeting set SUBSET block2 UNION block3 (forward dichotomy                 *)
(* TILE_JL_OFFDIAG_                                                          *)
(* DICHOTOMY).  block2 = {J_s SUBSET J^l_t}, block3 = {J_t SUBSET J^l_s}.    *)
let CARLESON_MEETING_SUBSET = prove
 (`!(P:(int#int#int)->bool) s.
     {t | t IN P /\ ~(tile_J t = tile_J s) /\ ~DISJOINT (tile_Jl s) (tile_Jl
       t)} SUBSET
     {t | t IN P /\ tile_J s SUBSET tile_Jl t} UNION {t | t IN P /\ tile_J t
       SUBSET tile_Jl s}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[SUBSET; IN_UNION; IN_ELIM_THM] THEN
  X_GEN_TAC `t:int#int#int` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`s:int#int#int`;
    `t:int#int#int`] TILE_JL_OFFDIAG_DICHOTOMY) THEN
  REWRITE_TAC[SUBSET] THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* the row split: inr_s <= inr2_s + inr3_s (ROW_MEETING = drop kernel-0      *)
(* terms; SUM_SUBSET_SIMPLE via MEETING_SUBSET; SUM_UNION_LE_POS; all terms  *)
(* nonneg).                                                                  *)
let CARLESON_ROW_SPLIT = prove
 (`!(f:real->complex) (P:(int#int#int)->bool) s. FINITE P
     ==> sum {t | t IN P /\ ~(tile_J t = tile_J s)}
             (\t. norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop
               z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                         norm(carleson_ip f t))
         <= sum {t | t IN P /\ tile_J s SUBSET tile_Jl t}
                (\t. norm(integral (:real^1) (\z. phi_sigma s carleson_phi
                  (drop z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                         norm(carleson_ip f t)) +
            sum {t | t IN P /\ tile_J t SUBSET tile_Jl s}
                (\t. norm(integral (:real^1) (\z. phi_sigma s carleson_phi
                  (drop z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                         norm(carleson_ip f t))`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[CARLESON_ROW_MEETING] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum ({t | t IN P /\ tile_J s SUBSET tile_Jl t} UNION
                   {t | t IN P /\ tile_J t SUBSET tile_Jl s})
             (\t. norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop
               z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                         norm(carleson_ip f t))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
    ASM_SIMP_TAC[CARLESON_MEETING_SUBSET; FINITE_UNION; FINITE_RESTRICT] THEN
    REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_MUL THEN
      REWRITE_TAC[NORM_POS_LE];
    MATCH_MP_TAC SUM_UNION_LE_POS THEN
    ASM_SIMP_TAC[FINITE_RESTRICT] THEN
    REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_MUL THEN
      REWRITE_TAC[NORM_POS_LE]]);;

(* ------------------------------------------------------------------------- *)
(* 286K(b) GRAM ROOF v2 (Fremlin-faithful): takes the off-diagonal bound     *)
(* norm(offdiag) <= sqrt(alpha) sqrt(K alpha) DIRECTLY as hypothesis (not    *)
(* via                                                                       *)
(* the combined-inr sum inr^2<=K alpha, which would need the structureless   *)
(* block-3 rows).  Fremlin bounds norm offdiag = block2-DS + block3-DS =     *)
(* 2*block2-DS by the double-sum swap symmetry, each block <= sqrt(alpha)    *)
(* sqrt                                                                      *)
(* (8C3^2C4 alpha), so K = 32C3^2C4. Roof = DELTA_SQ_LE_GRAM +               *)
(* NORMSQ_DOUBLE_LE                                                          *)
(* (CARLESON_GRAM_LEG1) + GRAM_COMBINE_SQRT.                                 *)
(* ------------------------------------------------------------------------- *)
let CARLESON_GRAM_BUDGET2 = prove
 (`?C3. &0 <= C3 /\
   !(f:real->complex) (P:(int#int#int)->bool) K.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ FINITE P /\
     lnorm (:real^1) (&2) (\z. f(drop z)) <= &1 /\ &0 <= K /\
     norm(vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
              carleson_ip f s * cnj(carleson_ip f t) *
              lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                 (\z. phi_sigma t carleson_phi (drop z)))))
       <= sqrt(delta_f f P) * sqrt(K * delta_f f P)
     ==> delta_f f P <= C3 + sqrt K`,
  X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC CARLESON_NORMSQ_DOUBLE_LE THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MATCH_MP_TAC GRAM_COMBINE_SQRT THEN
  EXISTS_TAC `norm(vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
              carleson_ip f s * cnj(carleson_ip f t) *
              lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                 (\z. phi_sigma t carleson_phi (drop z)))))`
                                   THEN
  ASM_REWRITE_TAC[DELTA_POS] THEN
  MATCH_MP_TAC CARLESON_GRAM_LEG1 THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Abstract double-sum swap over a relation-restricted inner index, for a    *)
(* SYMMETRIC summand g: sum_s sum_{t in P, R s t} g s t = sum_s sum_{t in P, *)
(* R t s} g s t. This is Fremlin's "Similarly" for the two off-diagonal      *)
(* J-blocks                                                                  *)
(* (block-2 R s t = J_s SUBSET J^l_t; block-3 R t s = J_t SUBSET J^l_s)      *)
(* applied                                                                   *)
(* to the swap-symmetric weight |ip_s| |<phi_s|phi_t>| |ip_t|.               *)
(* SUM_RESTRICT_SET                                                          *)
(* + SUM_SWAP + the g-symmetry.                                              *)
(* ------------------------------------------------------------------------- *)
let SUM_DOUBLE_SWAP_REL = prove
 (`!(P:A->bool) (g:A->A->real) R. FINITE P /\ (!x y. g x y = g y x)
     ==> sum P (\s. sum {t | t IN P /\ R s t} (\t. g s t))
         = sum P (\s. sum {t | t IN P /\ R t s} (\t. g s t))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[SUM_RESTRICT_SET] THEN
  W(fun (asl,w) -> MP_TAC(ISPECL [`\s t:A. if R s t then (g:A->A->real) s t
    else &0`;
                                  `P:A->bool`; `P:A->bool`] SUM_SWAP)) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `s:A` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  MATCH_MP_TAC SUM_EQ THEN X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

(* block3-weighted = block2-weighted (SUM_DOUBLE_SWAP_REL on the             *)
(* swap-symmetric weight norm(ip_s) norm(<phi_s|phi_t>) norm(ip_t), R s t =  *)
(* J_s SUBSET J^l_t).                                                        *)
let CARLESON_BLOCK_SYM = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> sum P (\s. norm(carleson_ip f s) *
                    sum {t | t IN P /\ tile_J s SUBSET tile_Jl t}
                        (\t. norm(integral (:real^1) (\z. phi_sigma s
                          carleson_phi (drop z) *
                                  cnj(phi_sigma t carleson_phi (drop z)))) *
                                    norm(carleson_ip f t)))
         = sum P (\s. norm(carleson_ip f s) *
                    sum {t | t IN P /\ tile_J t SUBSET tile_Jl s}
                        (\t. norm(integral (:real^1) (\z. phi_sigma s
                          carleson_phi (drop z) *
                                  cnj(phi_sigma t carleson_phi (drop z)))) *
                                    norm(carleson_ip f t)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM SUM_LMUL] THEN
  MP_TAC(ISPECL [`P:(int#int#int)->bool`;
    `\s t:int#int#int. norm(carleson_ip f s) *
        (norm(integral (:real^1) (\z. phi_sigma s carleson_phi (drop z) *
                  cnj(phi_sigma t carleson_phi (drop z)))) * norm(carleson_ip f
                    t))`;
    `\s t:int#int#int. tile_J s SUBSET tile_Jl t`] SUM_DOUBLE_SWAP_REL) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT GEN_TAC THEN
    MP_TAC(ISPECL [`x:int#int#int`;`y:int#int#int`] PHISIG_CORR_SYM) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REAL_ARITH_TAC;
    DISCH_THEN SUBST1_TAC THEN REFL_TAC]);;

(* norm(offdiag) <= 2 * block2-weighted. OFFDIAG_LE_INR + ROW_SPLIT          *)
(* (inr<=inr2+                                                               *)
(* inr3) + CARLESON_BLOCK_SYM (block3=block2). Fremlin's 2*block2 from       *)
(* "Similarly".                                                              *)
let CARLESON_OFFDIAG_2BLOCK = prove
 (`!(f:real->complex) (P:(int#int#int)->bool). FINITE P
     ==> norm(vsum P (\s. vsum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
              carleson_ip f s * cnj(carleson_ip f t) *
              lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                                 (\z. phi_sigma t carleson_phi (drop z)))))
         <= &2 * sum P (\s. norm(carleson_ip f s) *
                    sum {t | t IN P /\ tile_J s SUBSET tile_Jl t}
                        (\t. norm(integral (:real^1) (\z. phi_sigma s
                          carleson_phi (drop z) *
                                  cnj(phi_sigma t carleson_phi (drop z)))) *
                                    norm(carleson_ip f t)))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum P (\s. norm(carleson_ip f s) *
                sum {t | t IN P /\ ~(tile_J t = tile_J s)} (\t.
                     norm(integral (:real^1) (\z. phi_sigma s carleson_phi
                       (drop z) *
                                                  cnj(phi_sigma t carleson_phi
                                                    (drop z)))) *
                     norm(carleson_ip f t)))` THEN
  CONJ_TAC THENL [MATCH_MP_TAC OFFDIAG_LE_INR THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum P (\s. norm(carleson_ip f s) * sum {t | t IN P /\ tile_J s
    SUBSET tile_Jl t} (\t. norm(integral (:real^1) (\z. phi_sigma s
    carleson_phi (drop z) * cnj(phi_sigma t carleson_phi (drop z)))) *
    norm(carleson_ip f t))) + sum P (\s. norm(carleson_ip f s) * sum {t | t IN
    P /\ tile_J t SUBSET tile_Jl s} (\t. norm(integral (:real^1) (\z. phi_sigma
    s carleson_phi (drop z) * cnj(phi_sigma t carleson_phi (drop z)))) *
    norm(carleson_ip f t)))` THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[GSYM SUM_ADD] THEN MATCH_MP_TAC SUM_LE THEN
     ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM REAL_ADD_LDISTRIB] THEN MATCH_MP_TAC REAL_LE_LMUL THEN
    REWRITE_TAC[NORM_POS_LE] THEN MATCH_MP_TAC CARLESON_ROW_SPLIT THEN
      ASM_REWRITE_TAC[];
    ABBREV_TAC `A = sum P (\s. norm(carleson_ip f s) * sum {t | t IN P /\
      tile_J s SUBSET tile_Jl t} (\t. norm(integral (:real^1) (\z. phi_sigma s
      carleson_phi (drop z) * cnj(phi_sigma t carleson_phi (drop z)))) *
      norm(carleson_ip f t)))` THEN
    ABBREV_TAC `B = sum P (\s. norm(carleson_ip f s) * sum {t | t IN P /\
      tile_J t SUBSET tile_Jl s} (\t. norm(integral (:real^1) (\z. phi_sigma s
      carleson_phi (drop z) * cnj(phi_sigma t carleson_phi (drop z)))) *
      norm(carleson_ip f t)))` THEN
    SUBGOAL_THEN `A:real = B` (fun th -> REWRITE_TAC[th] THEN
      REAL_ARITH_TAC) THEN
    MAP_EVERY EXPAND_TAC ["A";"B"] THEN MATCH_MP_TAC CARLESON_BLOCK_SYM THEN
      ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* 286K(b) H_j a-iii COVER: for sigma in piece_j (root tau_j) and t in an    *)
(* active                                                                    *)
(* piece_m with J_sigma SUBSET J^l_t (block-2 inner index), the fine tile's  *)
(* interval I_t is disjoint from the root's interval I_{tau_j}. Fremlin      *)
(* (mt286.                                                                   *)
(* tex 1108-1112): J_{tau_j} SUBSET J_sigma SUBSET J^l_t, so the a-iii first *)
(* remark on (t,tau_j) gives I_t cap I_{tau_j} = empty. Chain:               *)
(* PIECE_LER_ROOT                                                            *)
(* (J_{tau_j} SUBSET J_sigma) + SUBSET_TRANS + CARLESON_AIII_ORDER (~tile_le *)
(* t                                                                         *)
(* tau_j) + AIII_FIRST_CORE_LE. So I_t SUBSET R\I_{tau_j} = the H_j cover    *)
(* II.                                                                       *)
(* ------------------------------------------------------------------------- *)
let CARLESON_TREE_COVER = prove
 (`!f gam P j m sigma t. &0 < gam /\ FINITE P /\
     j < carleson_stopN f gam P /\ m < carleson_stopN f gam P /\
     sigma IN carleson_piece f gam (carleson_Rtilde P) P j /\
     t IN carleson_piece f gam (carleson_Rtilde P) P m /\
     tile_J sigma SUBSET tile_Jl t
     ==> DISJOINT (tile_I t) (tile_I (carleson_rootseq f gam (carleson_Rtilde
       P) P j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `tile_J (carleson_rootseq f gam (carleson_Rtilde P) P j) SUBSET tile_J
    sigma` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`carleson_Rtilde
     P`;`P:(int#int#int)->bool`;`j:num`;`sigma:int#int#int`]
     CARLESON_PIECE_LER_ROOT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o MATCH_MP TILE_LER_IMP_LE) THEN
    REWRITE_TAC[tile_le] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `tile_J (carleson_rootseq f gam (carleson_Rtilde P) P j) SUBSET tile_Jl t`
    ASSUME_TAC THENL
   [ASM_MESON_TAC[SUBSET_TRANS]; ALL_TAC] THEN
  MATCH_MP_TAC AIII_FIRST_CORE_LE THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CARLESON_AIII_ORDER THEN EXISTS_TAC `m:num` THEN
    ASM_SIMP_TAC[CARLESON_RTILDE_FINITE; CARLESON_ACTIVE_RSEQ];
    ASM_MESON_TAC[TILE_JL_SUBSET_J; SUBSET_TRANS];
    MATCH_MP_TAC TILE_JL_SUBSET_KLE THEN ASM_REWRITE_TAC[]]);;

(* 286K(b) H_j pairwise-negligibility: distinct t,t' in P' whose J^l both    *)
(* contain                                                                   *)
(* J_sigma (so J^l_t meets J^l_t') have negligible I-overlap. Fremlin        *)
(* mt286.tex                                                                 *)
(* 1108-1112 (I_tau, I_tau' disjoint). ~DISJOINT(J^l_t)(J^l_t') from the     *)
(* shared                                                                    *)
(* nonempty J_sigma + CARLESON_AIII_DISJOINT + empty set negligible.         *)
let CARLESON_TREE_PAIRWISE = prove
 (`!f gam P sigma t t'. &0 < gam /\ FINITE P /\
     t IN carleson_Pextract f gam P /\ t' IN carleson_Pextract f gam P /\
     ~(t = t') /\ tile_J sigma SUBSET tile_Jl t /\ tile_J sigma SUBSET tile_Jl
       t'
     ==> real_negligible (tile_I t INTER tile_I t')`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~DISJOINT (tile_Jl t) (tile_Jl t')` ASSUME_TAC THENL
   [MP_TAC(ISPEC `sigma:int#int#int` TILE_J_NONEMPTY) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
      DISCH_THEN(X_CHOOSE_TAC `y:real`) THEN
    REWRITE_TAC[DISJOINT; GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
      EXISTS_TAC `y:real` THEN
    CONJ_TAC THENL
     [UNDISCH_TAC `tile_J sigma SUBSET tile_Jl t` THEN REWRITE_TAC[SUBSET] THEN
      DISCH_THEN(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `tile_J sigma SUBSET tile_Jl t'` THEN
        REWRITE_TAC[SUBSET] THEN
      DISCH_THEN(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (tile_I t) (tile_I t')` MP_TAC THENL
   [MATCH_MP_TAC CARLESON_AIII_DISJOINT THEN
    MAP_EVERY EXISTS_TAC [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`]
      THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[DISJOINT] THEN DISCH_THEN SUBST1_TAC THEN
      REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY]]);;

(* strict scale J_s SUBSET J^l_t ==> k_s < k_t (J^l is a PROPER half, so the *)
(* strict form of TILE_JL_SUBSET_KLE; DYHO_SUBSET_SCALE on dyho k_s SUBSET   *)
(* dyho                                                                      *)
(* (k_t-1)).  And same spatial interval forces same scale (TILE_I_MEASURE +  *)
(* ZPOW2_INJ). Together: J_s SUBSET J^l_t ==> ~(I_s = I_t) [k_s<k_t vs       *)
(* k_s=k_t].                                                                 *)
let TILE_JL_SUBSET_KLT = prove
 (`!(s:int#int#int) t. tile_J s SUBSET tile_Jl t ==> tile_k s < tile_k t`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!ks nIs nJs kt nIt nJt. P ((ks,nIs,nJs):int#int#int)
     ((kt,nIt,nJt):int#int#int))
    ==> (!s t. P s t)`) THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_J; tile_Jl; tile_k] THEN
  DISCH_THEN(MP_TAC o MATCH_MP DYHO_SUBSET_SCALE) THEN INT_ARITH_TAC);;

let TILE_I_EQ_SCALE = prove
 (`!(s:int#int#int) t. tile_I s = tile_I t ==> tile_k s = tile_k t`,
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!ks nIs nJs kt nIt nJt. P ((ks,nIs,nJs):int#int#int)
     ((kt,nIt,nJt):int#int#int))
    ==> (!s t. P s t)`) THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`] THEN
  REWRITE_TAC[tile_k] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`ks:int`;`nIs:int`;`nJs:int`] TILE_I_MEASURE) THEN
  MP_TAC(ISPECL [`kt:int`;`nIt:int`;`nJt:int`] TILE_I_MEASURE) THEN
  ASM_REWRITE_TAC[] THEN REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `&2 zpow (--ks) = &2 zpow (--kt)` MP_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o MATCH_MP ZPOW2_INJ) THEN INT_ARITH_TAC);;

(* Pextract SUBSET P (each piece SUBSET its stage SUBSET P) + FINITE.  Feeds *)
(* energy_f f Pextract <= gam via ENERGY_MONO, an HJ_INNER_TILE hypothesis.  *)
let CARLESON_PEXTRACT_SUBSET = prove
 (`!f gam P. carleson_Pextract f gam P SUBSET P`,
  REPEAT GEN_TAC THEN
    REWRITE_TAC[carleson_Pextract; UNIONS_SUBSET; FORALL_IN_IMAGE] THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN REWRITE_TAC[carleson_piece] THEN
  MATCH_MP_TAC SUBSET_TRANS THEN
  EXISTS_TAC `carleson_Pseq f gam (carleson_Rtilde P) P j` THEN
  REWRITE_TAC[TILE_TREE_SUBSET; CARLESON_PSEQ_SUBSET_P]);;

let CARLESON_PEXTRACT_FINITE = prove
 (`!f gam P. FINITE P ==> FINITE (carleson_Pextract f gam P)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `P:(int#int#int)->bool` THEN
    ASM_REWRITE_TAC[CARLESON_PEXTRACT_SUBSET]);;

(* 286K(b) H_j geometric sub-atoms for the HJ_INNER_TILE instantiation:      *)
(* - if I_t is disjoint from a dyadic cell dyho(--k)nI = [nI                 *)
(* 2^{--k},(nI+1)2^{--k}),                                                   *)
(* then I_t sits in the CLOSED complement half-lines (the SUBTILE_TAIL_SUM   *)
(* set);                                                                     *)
(*  - the tile centre x_sigma lies in its own interval I_sigma;              *)
(* - cw_tile sigma is integrable on the complement half-lines when x_sigma   *)
(* is                                                                        *)
(* between the two cut points (CWTILE_TAIL_COMPLEMENT gives                  *)
(* has_real_integral).                                                       *)
(* ------------------------------------------------------------------------- *)

(* TILE_XMID_IN_I (tile centre lies in its own interval) is proved above.    *)

let CWTILE_COMPL_INTEGRABLE = prove
 (`!(sigma:int#int#int) alpha gm.
     alpha <= tile_xmid sigma /\ tile_xmid sigma <= gm /\ alpha < gm
     ==> cw_tile sigma real_integrable_on ({x | x <= alpha} UNION {x | gm <=
       x})`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[real_integrable_on] THEN
  EXISTS_TAC `&1 / (&2 * (&1 + &2 zpow (tile_k sigma) * (tile_xmid sigma -
    alpha)) pow 2) +
              &1 / (&2 * (&1 + &2 zpow (tile_k sigma) * (gm - tile_xmid sigma))
                pow 2)` THEN
  MATCH_MP_TAC CWTILE_TAIL_COMPLEMENT THEN ASM_REWRITE_TAC[]);;

(* cw_tile sigma integrable on R\I_r when x_sigma IN I_r: I_r=dyho[a,b), its *)
(* complement {x<a}U{b<=x} differs from the CWTILE_COMPL_INTEGRABLE closed   *)
(* set {x<=a}U{b<=x} by the null point {a} (REAL_INTEGRABLE_SPIKE_SET).      *)
let CARLESON_II_INTEGRABLE = prove
 (`!sigma r:int#int#int. tile_xmid sigma IN tile_I r
     ==> cw_tile sigma real_integrable_on ((:real) DIFF tile_I r)`,
  GEN_TAC THEN
  MATCH_MP_TAC(MESON[PAIR_SURJECTIVE]
   `(!kr nIr nJr. P ((kr,nIr,nJr):int#int#int)) ==> (!r. P r)`) THEN
  MAP_EVERY X_GEN_TAC [`kr:int`;`nIr:int`;`nJr:int`] THEN
  REWRITE_TAC[tile_I; dyho; IN_ELIM_THM] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`cw_tile sigma`;
     `{x | x <= real_of_int nIr * &2 zpow (--kr)} UNION {x | (real_of_int nIr +
       &1) * &2 zpow (--kr) <= x}`;
     `(:real) DIFF {x | real_of_int nIr * &2 zpow (--kr) <= x /\ x <
       (real_of_int nIr + &1) * &2 zpow (--kr)}`]
    REAL_INTEGRABLE_SPIKE_SET) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN
    EXISTS_TAC `{real_of_int nIr * &2 zpow (--kr)}` THEN
    REWRITE_TAC[REAL_NEGLIGIBLE_SING; SUBSET; IN_UNION; IN_DIFF; IN_UNIV;
      IN_ELIM_THM; IN_SING] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  MATCH_MP_TAC CWTILE_COMPL_INTEGRABLE THEN
  SUBGOAL_THEN `&0 < &2 zpow (--kr)` MP_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* 286K(b) H_j per-sigma inr2 bound: for sigma in piece_j (root tau_j), the  *)
(* block-2 inner sum inr2_sigma <= (C3 gam) inv(sqrt 2^{k_sigma})            *)
(* int_{R\I_{tau_j}} w_sigma. HJ_INNER_TILE with Tt={t in P': J_sigma SUBSET *)
(* J^l_t}, II=R\I_{tau_j}; the 9 hyps discharge from the banked atoms:       *)
(* FINITE (PEXTRACT_FINITE), k_sig<=k_t (TILE_JL_ SUBSET_KLE) /\             *)
(* ~(I_sig=I_t) (KLT+I_EQ_SCALE), I_t SUBSET II (TREE_COVER), I-inj          *)
(* (AIII_DISJOINT+TILE_XMID_IN_I), pairwise-neg (TREE_PAIRWISE), cw integ on *)
(* I_t (CWTILE_INTEGRABLE_TILE_I) and on II (CARLESON_II_INTEGRABLE), energy *)
(* (PEXTRACT).                                                               *)
let CARLESON_INR2_BOUND = prove
 (`?C3. &0 <= C3 /\
   !f gam0 P j gam sigma.
     &0 < gam0 /\ FINITE P /\ j < carleson_stopN f gam0 P /\ &0 <= gam /\
     energy_f f (carleson_Pextract f gam0 P) <= gam /\
     sigma IN carleson_piece f gam0 (carleson_Rtilde P) P j
     ==> sum {t | t IN carleson_Pextract f gam0 P /\ tile_J sigma SUBSET
       tile_Jl t}
             (\t. norm(integral (:real^1) (\z. phi_sigma sigma carleson_phi
               (drop z) *
                       cnj(phi_sigma t carleson_phi (drop z)))) *
                         norm(carleson_ip f t))
         <= (C3 * gam) * inv(sqrt(&2 zpow (tile_k sigma))) *
            real_integral ((:real) DIFF tile_I (carleson_rootseq f gam0
              (carleson_Rtilde P) P j))
                          (cw_tile sigma)`,
  X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC HJ_INNER_TILE THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `tile_I sigma
     SUBSET tile_I (carleson_rootseq f gam0 (carleson_Rtilde P) P j)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`f:real->complex`;`gam0:real`;`carleson_Rtilde
     P`;`P:(int#int#int)->bool`;`j:num`;`sigma:int#int#int`]
     CARLESON_PIECE_LER_ROOT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o MATCH_MP TILE_LER_IMP_LE) THEN
    REWRITE_TAC[tile_le] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `tile_xmid sigma IN tile_I (carleson_rootseq f gam0 (carleson_Rtilde P) P
     j)`
   ASSUME_TAC THENL
   [MP_TAC(ISPEC `sigma:int#int#int` TILE_XMID_IN_I) THEN
     ASM SET_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
   [`f:real->complex`; `sigma:int#int#int`;
    `{t | t IN carleson_Pextract f gam0 P /\ tile_J sigma SUBSET tile_Jl t}`;
    `carleson_Pextract f gam0 P`; `gam:real`;
    `(:real) DIFF tile_I (carleson_rootseq f gam0 (carleson_Rtilde P) P j)`])
      THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_ELIM_THM] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `carleson_Pextract f gam0 P` THEN
    ASM_SIMP_TAC[CARLESON_PEXTRACT_FINITE; SUBSET; IN_ELIM_THM];
    ASM_SIMP_TAC[CARLESON_PEXTRACT_FINITE];
    SIMP_TAC[IN_ELIM_THM];
    X_GEN_TAC `t:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC TILE_JL_SUBSET_KLE THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      MP_TAC(ISPECL [`sigma:int#int#int`;`t:int#int#int`] TILE_JL_SUBSET_KLT)
        THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`sigma:int#int#int`;`t:int#int#int`] TILE_I_EQ_SCALE) THEN
      ASM_REWRITE_TAC[] THEN INT_ARITH_TAC];
    X_GEN_TAC `t:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `m:num` STRIP_ASSUME_TAC o
      REWRITE_RULE[CARLESON_PEXTRACT_MEM]) THEN
    MP_TAC(ISPECL
      [`f:real->complex`;`gam0:real`;`P:(int#int#int)->bool`;`j:num`;`m:num`;
       `sigma:int#int#int`;`t:int#int#int`] CARLESON_TREE_COVER) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[DISJOINT] THEN SET_TAC[];
    MAP_EVERY X_GEN_TAC [`t:int#int#int`;`t':int#int#int`] THEN
    REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    GEN_REWRITE_TAC I [TAUT `p <=> ~ ~p`] THEN DISCH_TAC THEN
    SUBGOAL_THEN `~DISJOINT (tile_Jl t) (tile_Jl t')` ASSUME_TAC THENL
     [MP_TAC(ISPEC `sigma:int#int#int` TILE_J_NONEMPTY) THEN
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
        DISCH_THEN(X_CHOOSE_TAC `y:real`) THEN
      REWRITE_TAC[DISJOINT; GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
        EXISTS_TAC `y:real` THEN
      CONJ_TAC THENL
       [UNDISCH_TAC `tile_J sigma SUBSET tile_Jl t` THEN
         REWRITE_TAC[SUBSET] THEN
        DISCH_THEN(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[];
        UNDISCH_TAC `tile_J sigma SUBSET tile_Jl t'` THEN
          REWRITE_TAC[SUBSET] THEN
        DISCH_THEN(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MP_TAC(ISPECL
      [`f:real->complex`;`gam0:real`;`P:(int#int#int)->bool`;`t:int#int#int`;
       `t':int#int#int`] CARLESON_AIII_DISJOINT) THEN
    ASM_REWRITE_TAC[DISJOINT] THEN
    MP_TAC(ISPEC `t:int#int#int` TILE_XMID_IN_I) THEN ASM SET_TAC[];
    MAP_EVERY X_GEN_TAC [`t:int#int#int`;`t':int#int#int`] THEN
    REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    MATCH_MP_TAC CARLESON_TREE_PAIRWISE THEN
    MAP_EVERY EXISTS_TAC
      [`f:real->complex`;`gam0:real`;`P:(int#int#int)->bool`;
       `sigma:int#int#int`] THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[CWTILE_INTEGRABLE_TILE_I];
    MATCH_MP_TAC CARLESON_II_INTEGRABLE THEN ASM_REWRITE_TAC[]]);;

(* cw_tile depends only on the (frequency-scale, spatial-index) pair (k,nI), *)
(* not                                                                       *)
(* the frequency-index nJ (cw_tile s x = 2^k cw(2^k(x - x_s)), x_s =         *)
(* dyho_mid(--k)                                                             *)
(* nI). Lets the per-scale H_j sum (d-scale) reindex sigma -> its spatial    *)
(* sub-cell                                                                  *)
(* of I_{tau_j} (SUBTILE_TAIL_SUM uses a fixed nJ).                          *)
let CW_TILE_NJ_INDEP = prove
 (`!k nI nJ nJ'. cw_tile (k,nI,nJ) = cw_tile (k,nI,nJ')`,
  REPEAT GEN_TAC THEN REWRITE_TAC[FUN_EQ_THM; cw_tile; tile_k; tile_xmid]);;

(* in an a-iii-disjoint same-scale tile set, the spatial index nI is         *)
(* injective:                                                                *)
(* same nI (+ same k) => same I => (disjoint => equal or empty; nonempty) => *)
(* same                                                                      *)
(* tile.  The SELECT-uniqueness the d-scale reindex (SUM_LE_INCLUDED) needs. *)
let TILE_NI_UNIQUE = prove
 (`!S k. (!sig. sig IN S ==> tile_k sig = k) /\
     (!s s'. s IN S /\ s' IN S /\ ~(s = s') ==> DISJOINT (tile_I s) (tile_I
       s'))
     ==> !s s'. s IN S /\ s' IN S /\ FST(SND s) = FST(SND s') ==> s = s'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  GEN_REWRITE_TAC I [TAUT `p <=> ~ ~p`] THEN DISCH_TAC THEN
  SUBGOAL_THEN `tile_I s = tile_I s'` ASSUME_TAC THENL
   [SUBGOAL_THEN `tile_k s = tile_k s'` MP_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `a0:int` (X_CHOOSE_THEN
      `a1:int#int` SUBST_ALL_TAC)) THEN
    MP_TAC(ISPEC `a1:int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `a1a:int` (X_CHOOSE_THEN
      `a1b:int` SUBST_ALL_TAC)) THEN
    MP_TAC(ISPEC `s':int#int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `b0:int` (X_CHOOSE_THEN
      `b1:int#int` SUBST_ALL_TAC)) THEN
    MP_TAC(ISPEC `b1:int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `b1a:int` (X_CHOOSE_THEN
      `b1b:int` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[tile_I; tile_k] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[FST; SND]) THEN
    DISCH_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`s:int#int#int`;`s':int#int#int`]) THEN
  ASM_REWRITE_TAC[DISJOINT; GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
  EXISTS_TAC `tile_xmid s':real` THEN REWRITE_TAC[TILE_XMID_IN_I]);;

(* scale relation 2^{--kt} = N 2^{--k} when 2^{k-kt}=N (spatial cell = N     *)
(* sub-cells).                                                               *)
let ZPOW_SCALE_REL = prove
 (`!k kt N. &2 zpow (k - kt) = &N ==> &2 zpow (--kt) = &N * &2 zpow (--k)`,
  REPEAT STRIP_TAC THEN FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN
  SUBGOAL_THEN
    `&2 zpow (k - kt) * &2 zpow (--k) = &2 zpow ((k - kt) + (--k))` SUBST1_TAC
    THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_ZPOW_ADD THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  AP_TERM_TAC THEN INT_ARITH_TAC);;

(* the scale-k sub-cell at offset j (index N*nIt+j) has its midpoint inside  *)
(* the                                                                       *)
(* coarse cell I_{(kt,nIt,.)} = [nIt 2^{--kt},(nIt+1)2^{--kt}), for j < N.   *)
(* Feeds                                                                     *)
(* CWTILE_COMPL_INTEGRABLE (x_subcell between the cut points) in the d-scale *)
(* nonneg                                                                    *)
(* leg.                                                                      *)
let TILE_SUBCELL_MID_IN = prove
 (`!k kt N nIt j:num. &2 zpow (k - kt) = &N /\ j < N
     ==> real_of_int nIt * &2 zpow (--kt) <= dyho_mid (--k) (&N * nIt + &j) /\
         dyho_mid (--k) (&N * nIt + &j) <= (real_of_int nIt + &1) * &2 zpow
           (--kt)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[dyho_mid] THEN
  FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP ZPOW_SCALE_REL th]) THEN
  SUBGOAL_THEN
    `real_of_int (&N * nIt + &j) = &N * real_of_int nIt + &j` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_OF_INT_CLAUSES]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 zpow (--k)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&j <= &N - &1` ASSUME_TAC THENL
   [SUBGOAL_THEN `j + 1 <= N` MP_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_LE; GSYM REAL_OF_NUM_ADD] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `z = &2 zpow (--k)` THEN ABBREV_TAC `p = real_of_int nIt` THEN
  CONJ_TAC THEN
  ONCE_REWRITE_TAC[REAL_ARITH
   `p * &N * z = (p * &N) * z /\ (&N * p + (&j + &1 / &2)) * z = (&N * p + (&j
     + &1 / &2)) * z /\
    (p + &1) * &N * z = ((p + &1) * &N) * z`] THEN
  MATCH_MP_TAC REAL_LE_RMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
    ASM_REAL_ARITH_TAC);;

(* 2^{k-kt}=&N with kt<=k forces N>=1 (2^nonneg >= 1 = 2^0, ZPOW2_MONOE).    *)
let ONE_LE_N_FROM_ZPOW = prove
 (`!k kt N:num. &2 zpow (k - kt) = &N /\ kt <= k ==> 1 <= N`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`&0:int`; `k - kt:int`] ZPOW2_MONOE) THEN
  ASM_SIMP_TAC[INT_ARITH `kt <= k ==> &0 <= k - kt:int`; REAL_ZPOW_0] THEN
  ASM_REWRITE_TAC[REAL_OF_NUM_LE]);;

(* the sub-cell offset num_of_int(nIs - N*nIt) lands in 0..N-1 when the      *)
(* spatial index nIs is in the coarse block [N*nIt, N*nIt+N).                *)
let TILE_SUBCELL_OFFSET_IN = prove
 (`!nIs nIt N:num.
     &N * nIt <= nIs /\ nIs < &N * nIt + &N /\
     &(num_of_int (nIs - &N * nIt)) = nIs - &N * nIt /\ 1 <= N
     ==> num_of_int (nIs - &N * nIt) IN (0..N-1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN CONJ_TAC THENL
   [ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM INT_OF_NUM_LE] THEN
  MP_TAC(ISPECL [`1`;`N:num`] INT_OF_NUM_SUB) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC);;

(* TILE_LE_SUBCELL_INDEX with the &N-factor on the LEFT of the               *)
(* multiplication (matching CARLESON_PERSCALE_TAIL's sub-cell offset         *)
(* arithmetic).                                                              *)
let TILE_LE_SUBCELL_INDEX_FLIP = prove
 (`!k kt nIs nJs nIt nJt N:num.
     tile_le (k,nIs,nJs) (kt,nIt,nJt) /\ kt <= k /\ &2 zpow (k - kt) = &N
     ==> &N * nIt <= nIs /\ nIs < &N * nIt + &N`,
  REPEAT STRIP_TAC THENL
   [MP_TAC(ISPECL
     [`k:int`;`kt:int`;`nIs:int`;`nJs:int`;`nIt:int`;`nJt:int`;`&N:int`]
      TILE_LE_SUBCELL_INDEX) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[REAL_OF_INT_CLAUSES]; ALL_TAC] THEN
    REWRITE_TAC[INT_RING `nIt * &N:int = &N * nIt`] THEN STRIP_TAC THEN
    FIRST_ASSUM ACCEPT_TAC;
    MP_TAC(ISPECL
      [`k:int`;`kt:int`;`nIs:int`;`nJs:int`;`nIt:int`;`nJt:int`;`&N:int`]
      TILE_LE_SUBCELL_INDEX) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[REAL_OF_INT_CLAUSES]; ALL_TAC] THEN
    REWRITE_TAC[INT_RING `nIt * &N:int = &N * nIt`] THEN STRIP_TAC THEN
    FIRST_ASSUM ACCEPT_TAC]);;

(* 286K(b) H_j d-scale: for a finite a-iii-disjoint set S of scale-k tiles   *)
(* all                                                                       *)
(* tile_le-below tau, the sum over S of int_{R\I_tau} w_sig is <= 1. Reindex *)
(* each sig to its spatial sub-cell offset in I_tau (SUM_LE_INCLUDED), then  *)
(* the per-scale sub-cell tail sum is <= 1 (CARLESON_SUBTILE_TAIL_SUM).      *)
let CARLESON_PERSCALE_TAIL = prove
 (`!S tau k N. FINITE S /\ &2 zpow (k - tile_k tau) = &N /\ tile_k tau <= k /\
     (!sig. sig IN S ==> tile_le sig tau /\ tile_k sig = k) /\
     (!s s'. s IN S /\ s' IN S /\ ~(s = s') ==> DISJOINT (tile_I s) (tile_I
       s'))
     ==> sum S (\sig. real_integral
                  ({x | x <= real_of_int (FST(SND tau)) * &2 zpow (--(tile_k
                    tau))} UNION
                   {x | (real_of_int (FST(SND tau)) + &1) * &2 zpow (--(tile_k
                     tau)) <= x})
                  (cw_tile sig))
         <= &1`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `tau:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `kt:int` (X_CHOOSE_THEN
    `rest:int#int` SUBST_ALL_TAC)) THEN
  MP_TAC(ISPEC `rest:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `nIt:int` (X_CHOOSE_THEN
    `nJt:int` SUBST_ALL_TAC)) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[tile_k]) THEN REWRITE_TAC[tile_k; FST; SND] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (0..N-1) (\j. real_integral
       ({x | x <= real_of_int nIt * &2 zpow (--kt)} UNION
        {x | (real_of_int nIt + &1) * &2 zpow (--kt) <= x})
       (cw_tile (k, &N * nIt + &j, nJt)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE_INCLUDED THEN
    EXISTS_TAC `\j:num. @sig:int#int#int. sig IN S /\ FST(SND sig) = &N * nIt +
      &j` THEN
    ASM_REWRITE_TAC[FINITE_NUMSEG] THEN CONJ_TAC THENL
     [X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_NUMSEG] THEN STRIP_TAC THEN
      MATCH_MP_TAC REAL_INTEGRAL_POS THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC CWTILE_COMPL_INTEGRABLE THEN
        REWRITE_TAC[tile_xmid; tile_k] THEN
        MP_TAC(ISPECL [`k:int`;`kt:int`;`N:num`;`nIt:int`;`j:num`]
          TILE_SUBCELL_MID_IN) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN
          MP_TAC(ISPECL [`k:int`;`kt:int`;`N:num`] ONE_LE_N_FROM_ZPOW) THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC; ALL_TAC] THEN
        STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `&0 < &2 zpow (--kt)` MP_TAC THENL
         [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
        REAL_ARITH_TAC;
        REPEAT STRIP_TAC THEN
        MP_TAC(SPECL [`(k, &N * nIt + &j, nJt):int#int#int`;
          `x:real`] CW_TILE_POS) THEN
        REAL_ARITH_TAC];
      X_GEN_TAC `sig:int#int#int` THEN DISCH_TAC THEN
      SUBGOAL_THEN `&N * nIt <= FST(SND(sig:int#int#int)) /\
                    FST(SND sig) < &N * nIt + &N` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPEC `sig:int#int#int` PAIR_SURJECTIVE) THEN
        DISCH_THEN(X_CHOOSE_THEN `ks:int` (X_CHOOSE_THEN
          `rs:int#int` SUBST_ALL_TAC)) THEN
        MP_TAC(ISPEC `rs:int#int` PAIR_SURJECTIVE) THEN
        DISCH_THEN(X_CHOOSE_THEN `nIs:int` (X_CHOOSE_THEN
          `nJs:int` SUBST_ALL_TAC)) THEN
        REWRITE_TAC[FST; SND] THEN
        SUBGOAL_THEN
          `tile_le (ks,nIs,nJs) (kt,nIt,nJt) /\ tile_k (ks,nIs,nJs) = k`
         MP_TAC THENL
         [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        REWRITE_TAC[tile_k] THEN
        DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC SUBST_ALL_TAC) THEN
        MP_TAC(ISPECL
          [`k:int`;`kt:int`;`nIs:int`;`nJs:int`;`nIt:int`;`nJt:int`;`N:num`]
          TILE_LE_SUBCELL_INDEX_FLIP) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      EXISTS_TAC `num_of_int (FST(SND(sig:int#int#int)) - &N * nIt)` THEN
      SUBGOAL_THEN `&(num_of_int (FST(SND(sig:int#int#int)) - &N * nIt)) =
                    FST(SND sig) - &N * nIt` ASSUME_TAC THENL
       [MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC TILE_SUBCELL_OFFSET_IN THEN ASM_REWRITE_TAC[] THEN
        MP_TAC(ISPECL [`k:int`;`kt:int`;`N:num`] ONE_LE_N_FROM_ZPOW) THEN
        ASM_REWRITE_TAC[];
        SUBGOAL_THEN
          `&N * nIt + FST(SND(sig:int#int#int)) - &N * nIt = FST(SND sig)`
         ASSUME_TAC THENL [INT_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[REAL_OF_INT_CLAUSES] THEN
        ASM_REWRITE_TAC[INT_ARITH `&N * nIt + (x - &N * nIt):int = x`] THEN
        MATCH_MP_TAC SELECT_UNIQUE THEN X_GEN_TAC `w:int#int#int` THEN
        REWRITE_TAC[] THEN EQ_TAC THENL
         [STRIP_TAC THEN
           MP_TAC(ISPECL [`S:(int#int#int)->bool`; `k:int`]
             TILE_NI_UNIQUE) THEN
          ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
          DISCH_THEN(MP_TAC o SPECL [`w:int#int#int`; `sig:int#int#int`]) THEN
          ASM_REWRITE_TAC[];
          DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]];
        ASM_REWRITE_TAC[INT_ARITH `&N * nIt + (x - &N * nIt):int = x`] THEN
        MP_TAC(ISPEC `sig:int#int#int` PAIR_SURJECTIVE) THEN
        DISCH_THEN(X_CHOOSE_THEN `ks:int` (X_CHOOSE_THEN
          `rs:int#int` SUBST_ALL_TAC)) THEN
        MP_TAC(ISPEC `rs:int#int` PAIR_SURJECTIVE) THEN
        DISCH_THEN(X_CHOOSE_THEN `nIs:int` (X_CHOOSE_THEN
          `nJs:int` SUBST_ALL_TAC)) THEN
        REWRITE_TAC[FST; SND] THEN
        SUBGOAL_THEN
          `tile_le (ks,nIs,nJs) (kt,nIt,nJt) /\ tile_k (ks,nIs,nJs) = k`
         MP_TAC THENL
         [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        REWRITE_TAC[tile_k] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) SUBST_ALL_TAC) THEN
        SUBST1_TAC(ISPECL [`k:int`;`nIs:int`;`nJs:int`;`nJt:int`]
          CW_TILE_NJ_INDEP) THEN
        REWRITE_TAC[REAL_LE_REFL]]];
    MATCH_MP_TAC CARLESON_SUBTILE_TAIL_SUM THEN ASM_REWRITE_TAC[]]);;

(* Per-summand: the weight integral over the closed-ray complement pair      *)
(* equals the integral over (:real) DIFF tile_I tau (they differ by the      *)
(* single left endpoint {nIt*2^-kt}, negligible; REAL_INTEGRAL_SPIKE_SET).   *)
let CW_TILE_INTEGRAL_RAYS_EQ_DIFF = prove
 (`!sigma kt nIt nJt:int.
     real_integral
        ({x | x <= real_of_int nIt * &2 zpow (--kt)} UNION
         {x | (real_of_int nIt + &1) * &2 zpow (--kt) <= x}) (cw_tile sigma) =
     real_integral ((:real) DIFF tile_I (kt,nIt,nJt)) (cw_tile sigma)`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC REAL_INTEGRAL_SPIKE_SET THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN
  EXISTS_TAC `{real_of_int nIt * &2 zpow (--kt)}` THEN
  REWRITE_TAC[REAL_NEGLIGIBLE_SING] THEN
  REWRITE_TAC[tile_I; dyho; SUBSET; IN_UNION; IN_DIFF; IN_UNIV; IN_ELIM_THM;
    IN_SING] THEN REAL_ARITH_TAC);;

(* CARLESON_PERSCALE_TAIL in the set-difference region form (:real) DIFF     *)
(* tile_I tau, matching the region used by HJ_INNER_TILE /                   *)
(* CARLESON_INR2_BOUND (286Gh).                                              *)
let CARLESON_PERSCALE_TAIL_DIFF = prove
 (`!S tau k N. FINITE S /\ &2 zpow (k - tile_k tau) = &N /\ tile_k tau <= k /\
     (!sig. sig IN S ==> tile_le sig tau /\ tile_k sig = k) /\
     (!s s'. s IN S /\ s' IN S /\ ~(s = s') ==> DISJOINT (tile_I s) (tile_I
       s'))
     ==> sum S (\sig. real_integral ((:real) DIFF tile_I tau) (cw_tile sig)) <=
       &1`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPEC `tau:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `kt:int` (X_CHOOSE_THEN
    `rest:int#int` SUBST1_TAC)) THEN
  MP_TAC(ISPEC `rest:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `nIt:int` (X_CHOOSE_THEN `nJt:int` SUBST1_TAC)) THEN
  REWRITE_TAC[GSYM CW_TILE_INTEGRAL_RAYS_EQ_DIFF] THEN
  REWRITE_TAC[tile_k] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`S:(int#int#int)->bool`; `(kt,nIt,nJt):int#int#int`; `k:int`;
    `N:num`]
    CARLESON_PERSCALE_TAIL) THEN
  ASM_REWRITE_TAC[tile_k; FST; SND]);;

(* A nonneg-exponent power of 2 is a natural number: 2^{k-kt} = &N (kt <=    *)
(* k).                                                                       *)
let ZPOW2_SCALE_IS_NUM = prove
 (`!k kt:int. kt <= k ==> ?N:num. &2 zpow (k - kt) = &N`,
  REPEAT STRIP_TAC THEN EXISTS_TAC `2 EXP (num_of_int(k - kt))` THEN
  SUBGOAL_THEN `&0:int <= k - kt` ASSUME_TAC THENL
    [ASM_INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_POW] THEN
  SUBGOAL_THEN `k - kt = &(num_of_int(k - kt)):int` SUBST1_TAC THENL
   [ASM_SIMP_TAC[INT_OF_NUM_OF_INT]; ALL_TAC] THEN
  REWRITE_TAC[REAL_ZPOW_NUM; NUM_OF_INT_OF_NUM; REAL_OF_NUM_POW]);;

(* 286Gh with C4:=1, in tree form: for a finite set Pk of tiles all          *)
(* tile_le-below                                                             *)
(* a common root u (tile_k u <= k) and all of scale k, the weight-tail sum   *)
(* sum_{Pk} int_{R\I_u} w_sigma <= 1. The a-iii-style spatial disjointness   *)
(* that                                                                      *)
(* CARLESON_PERSCALE_TAIL_DIFF needs is FREE from tree geometry: same-scale  *)
(* tree                                                                      *)
(* tiles below u are nI-injective (TILE_TREE_FST_SND_INJ), so distinct tiles *)
(* have                                                                      *)
(* distinct nI, hence disjoint scale-(-k) cells (DYHO_DISJOINT_SAMESCALE).   *)
(* This                                                                      *)
(* is the per-scale budget hypothesis of HJ_TILE_BOUND (with C4 = 1).        *)
let TILE_TREE_PERSCALE_LE1 = prove
 (`!Pk u k.
     FINITE Pk /\ tile_k u <= k /\
     (!s. s IN Pk ==> tile_le s u /\ tile_k s = k)
     ==> sum Pk (\sigma. real_integral ((:real) DIFF tile_I u) (cw_tile sigma))
       <= &1`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`k:int`; `tile_k(u:int#int#int)`] ZPOW2_SCALE_IS_NUM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN
  MP_TAC(ISPECL [`Pk:(int#int#int)->bool`; `u:int#int#int`; `k:int`; `N:num`]
    CARLESON_PERSCALE_TAIL_DIFF) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MAP_EVERY X_GEN_TAC [`s:int#int#int`; `s':int#int#int`] THEN STRIP_TAC THEN
  MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `ks:int` (X_CHOOSE_THEN
    `rs:int#int` SUBST_ALL_TAC)) THEN
  MP_TAC(ISPEC `rs:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `nIs:int` (X_CHOOSE_THEN
    `nJs:int` SUBST_ALL_TAC)) THEN
  MP_TAC(ISPEC `s':int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `ks':int` (X_CHOOSE_THEN
    `rs':int#int` SUBST_ALL_TAC)) THEN
  MP_TAC(ISPEC `rs':int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `nIs':int` (X_CHOOSE_THEN
    `nJs':int` SUBST_ALL_TAC)) THEN
  SUBGOAL_THEN `ks:int = k /\ ks':int = k` STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `(ks',nIs',nJs'):int#int#int` th) THEN
      MP_TAC(SPEC `(ks,nIs,nJs):int#int#int` th)) THEN
    ASM_REWRITE_TAC[tile_k] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(nIs:int = nIs')` ASSUME_TAC THENL
   [DISCH_TAC THEN
     UNDISCH_TAC `~((ks,nIs,nJs):int#int#int = (ks',nIs',nJs'))` THEN
    REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`Pk:(int#int#int)->bool`; `k:int`; `u:int#int#int`;
      `(ks,nIs,nJs):int#int#int`; `(ks',nIs',nJs'):int#int#int`]
      TILE_TREE_FST_SND_INJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[FST; SND] THEN
      GEN_TAC THEN DISCH_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `r:int#int#int`) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[tile_I] THEN
  MATCH_MP_TAC DYHO_DISJOINT_SAMESCALE THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* 286K H_j square-sum for ONE piece P'_j (Fremlin's H_j <= 2 C3^2 gam^2     *)
(* muI_tauj, with C4 := 1).  Instantiates the abstract HJ_TILE_BOUND at:     *)
(*   Sp = carleson_piece (the tree P'_j),                                    *)
(*   II sigma = (:real) DIFF tile_I root  (root = carleson_rootseq = tau_j), *)
(*   Tt sigma = {t in P' | J_sigma SUBSET J^l_t}  (the H_j inner tau-set),   *)
(*   C4 = 1  (per-scale weight-tail budget, TILE_TREE_PERSCALE_LE1),         *)
(*   L = tile_k root,                                                        *)
(* inr sigma bound = CARLESON_INR2_BOUND (the deep per-sigma 286Gg           *)
(* estimate).                                                                *)
(* The 5 per-sigma HJ hypotheses: inner-sum>=0 (SUM_POS_LE); R sigma>=0      *)
(* (REAL_INTEGRAL_POS + CARLESON_II_INTEGRABLE, x_sigma in I_root since      *)
(* sigma tile_le root); R sigma<=1 (CW_TILE_SUBSET_LE_1); the INR2 bound;    *)
(* L<=k_sigma (TILE_LE_SCALE).  Per-scale: TILE_TREE_PERSCALE_LE1 (disjoint- *)
(* ness FREE from tree nI-injectivity), empty-slice sum=0 handled            *)
(* separately.                                                               *)
(* C3 is threaded from CARLESON_INR2_BOUND's witness (same constant).        *)
(* ========================================================================= *)
let CARLESON_HJ_PIECE = prove
 (`?C3. &0 <= C3 /\
    !f gam0 P j gam.
       &0 < gam0 /\ FINITE P /\ j < carleson_stopN f gam0 P /\
       &0 <= gam /\ energy_f f (carleson_Pextract f gam0 P) <= gam
       ==> sum (carleson_piece f gam0 (carleson_Rtilde P) P j)
             (\sigma. (sum {t | t IN carleson_Pextract f gam0 P /\
                               tile_J sigma SUBSET tile_Jl t}
                  (\t. norm(integral (:real^1)
                        (\z. phi_sigma sigma carleson_phi (drop z) *
                             cnj(phi_sigma t carleson_phi (drop z)))) *
                       norm(carleson_ip f t))) pow 2)
           <= (C3 * gam) pow 2 *
              (&2 * &1 * inv(&2 zpow (tile_k (carleson_rootseq f gam0
                (carleson_Rtilde P) P j))))`,
  X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC CARLESON_INR2_BOUND THEN
  EXISTS_TAC `C3:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`f:real->complex`;
    `carleson_piece f gam0 (carleson_Rtilde P) P j`;
    `\sigma:int#int#int. {t | t IN carleson_Pextract f gam0 P /\ tile_J sigma
      SUBSET tile_Jl t}`;
    `\sigma:int#int#int. (:real) DIFF tile_I (carleson_rootseq f gam0
      (carleson_Rtilde P) P j)`;
    `gam:real`; `&1:real`;
    `tile_k (carleson_rootseq f gam0 (carleson_Rtilde P) P j)`;
    `C3:real`] HJ_TILE_BOUND) THEN
  REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[REAL_POS];
      ASM_REWRITE_TAC[REAL_POS];
      REAL_ARITH_TAC;
      MATCH_MP_TAC CARLESON_PIECE_FINITE THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN DISCH_TAC THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC SUM_POS_LE THEN REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN
        MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[NORM_POS_LE];
        SUBGOAL_THEN
         `cw_tile sigma real_integrable_on
          ((:real) DIFF tile_I (carleson_rootseq f gam0 (carleson_Rtilde P) P
            j))`
         ASSUME_TAC THENL
         [MATCH_MP_TAC CARLESON_II_INTEGRABLE THEN
          MP_TAC(ISPECL [`f:real->complex`;`gam0:real`;`carleson_Rtilde P`;
            `P:(int#int#int)->bool`;`j:num`;`sigma:int#int#int`]
              CARLESON_PIECE_LER_ROOT) THEN
          ASM_REWRITE_TAC[] THEN
            DISCH_THEN(MP_TAC o MATCH_MP TILE_LER_IMP_LE) THEN
          REWRITE_TAC[tile_le] THEN STRIP_TAC THEN
          FIRST_X_ASSUM(MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          REWRITE_TAC[TILE_XMID_IN_I]; ALL_TAC] THEN
        MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[] THEN
        REPEAT STRIP_TAC THEN
        MP_TAC(SPECL [`sigma:int#int#int`; `x:real`] CW_TILE_POS) THEN
          REAL_ARITH_TAC;
        MATCH_MP_TAC CW_TILE_SUBSET_LE_1 THEN
        MATCH_MP_TAC CARLESON_II_INTEGRABLE THEN
        MP_TAC(ISPECL [`f:real->complex`;`gam0:real`;`carleson_Rtilde P`;
          `P:(int#int#int)->bool`;`j:num`;`sigma:int#int#int`]
            CARLESON_PIECE_LER_ROOT) THEN
        ASM_REWRITE_TAC[] THEN
          DISCH_THEN(MP_TAC o MATCH_MP TILE_LER_IMP_LE) THEN
        REWRITE_TAC[tile_le] THEN STRIP_TAC THEN
        FIRST_X_ASSUM(MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[TILE_XMID_IN_I];
        FIRST_X_ASSUM(fun th ->
          if is_forall(concl th) &&
             (let b = snd(strip_forall(concl th)) in is_imp b)
          then MP_TAC(SPECL
            [`f:real->complex`;`gam0:real`;`P:(int#int#int)->bool`;
            `j:num`;`gam:real`;`sigma:int#int#int`] th) else NO_TAC) THEN
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC TILE_LE_SCALE THEN
        MP_TAC(ISPECL [`f:real->complex`;`gam0:real`;`carleson_Rtilde P`;
          `P:(int#int#int)->bool`;`j:num`;`sigma:int#int#int`]
            CARLESON_PIECE_LER_ROOT) THEN
        ASM_REWRITE_TAC[] THEN
          DISCH_THEN(ACCEPT_TAC o MATCH_MP TILE_LER_IMP_LE)];
      X_GEN_TAC `kk:int` THEN
      ASM_CASES_TAC `{sigma | sigma IN carleson_piece f gam0 (carleson_Rtilde
        P) P j /\
                              tile_k sigma = kk} = {}` THENL
       [ASM_REWRITE_TAC[SUM_CLAUSES] THEN REAL_ARITH_TAC; ALL_TAC] THEN
      MP_TAC(ISPECL
       [`{sigma | sigma IN carleson_piece f gam0 (carleson_Rtilde P) P j /\
                  tile_k sigma = kk}`;
        `carleson_rootseq f gam0 (carleson_Rtilde P) P j`; `kk:int`]
       TILE_TREE_PERSCALE_LE1) THEN
      DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_RESTRICT THEN
         MATCH_MP_TAC CARLESON_PIECE_FINITE THEN
        ASM_REWRITE_TAC[];
        FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
        REWRITE_TAC[IN_ELIM_THM] THEN
        DISCH_THEN(X_CHOOSE_THEN `s0:int#int#int` STRIP_ASSUME_TAC) THEN
        FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN MATCH_MP_TAC TILE_LE_SCALE THEN
        MP_TAC(ISPECL [`f:real->complex`;`gam0:real`;`carleson_Rtilde P`;
          `P:(int#int#int)->bool`;`j:num`;`s0:int#int#int`]
            CARLESON_PIECE_LER_ROOT) THEN
        ASM_REWRITE_TAC[] THEN
          DISCH_THEN(ACCEPT_TAC o MATCH_MP TILE_LER_IMP_LE);
        X_GEN_TAC `s:int#int#int` THEN REWRITE_TAC[IN_ELIM_THM] THEN
          STRIP_TAC THEN
        ASM_REWRITE_TAC[] THEN
        MP_TAC(ISPECL [`f:real->complex`;`gam0:real`;`carleson_Rtilde P`;
          `P:(int#int#int)->bool`;`j:num`;`s:int#int#int`]
            CARLESON_PIECE_LER_ROOT) THEN
        ASM_REWRITE_TAC[] THEN
          DISCH_THEN(ACCEPT_TAC o MATCH_MP TILE_LER_IMP_LE)]];
    REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286K(b) (d1)+(d3): the H_j accumulation sum_{s in P'} inr2_s^2 <= 8 C3^2  *)
(* d,                                                                        *)
(* d = delta_f f P'.  Partition P' over pieces (SUM_UNIONS_IMAGE_DISJOINT),  *)
(* bound each piece-sum by CARLESON_HJ_PIECE, collapse the constant and use  *)
(* the                                                                       *)
(* root measure budget gam^2 sum 2^{-k_root} <= 4 delta.                     *)
(* ========================================================================= *)

(* Generic: sum over a disjoint IMAGE family = sum of the per-index sums.    *)
let SUM_UNIONS_IMAGE_DISJOINT = prove
 (`!(h:A->real) (g:num->A->bool) II.
     FINITE II /\ (!i. i IN II ==> FINITE (g i)) /\ (!i. i IN II ==> ~(g i =
       {})) /\
     (!i j. i IN II /\ j IN II /\ ~(i = j) ==> DISJOINT (g i) (g j))
     ==> sum (UNIONS (IMAGE g II)) h = sum II (\i. sum (g i) h)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:A->real`;
    `IMAGE (g:num->A->bool) II`] SUM_UNIONS_NONZERO) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[FINITE_IMAGE; FORALL_IN_IMAGE] THEN
    MAP_EVERY X_GEN_TAC [`t1:A->bool`;`t2:A->bool`;`x:A`] THEN
    REWRITE_TAC[IN_IMAGE] THEN STRIP_TAC THEN
    SUBGOAL_THEN `~(x':num = x'')` ASSUME_TAC THENL
     [DISCH_TAC THEN UNDISCH_TAC `~(t1:A->bool = t2)` THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`x':num`;`x'':num`]) THEN
      ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
    UNDISCH_TAC `x:A IN t1` THEN UNDISCH_TAC `x:A IN t2` THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`g:num->A->bool`; `\A:A->bool. sum A (h:A->real)`;
    `II:num->bool`]
    SUM_IMAGE) THEN
  ANTS_TAC THENL
   [MAP_EVERY X_GEN_TAC [`a:num`; `b:num`] THEN STRIP_TAC THEN
    GEN_REWRITE_TAC I [TAUT `p <=> ~ ~p`] THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`a:num`;`b:num`]) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[DISJOINT; INTER_IDEMPOT] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `b:num`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[o_DEF] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[]);;

(* Root measure budget in index-sum form: gam^2 sum_{j<N} 2^{-k_root_j} <= 4 *)
(* d.                                                                        *)
let CARLESON_ROOT_MEASURE_BUDGET = prove
 (`!f gam P. &0 < gam /\ FINITE P
     ==> gam pow 2 * sum {j | j < carleson_stopN f gam P}
             (\j. &2 zpow (--(tile_k (carleson_rootseq f gam (carleson_Rtilde
               P) P j))))
         <= &4 * delta_f f (carleson_Pextract f gam P)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_DELTA_PEXTRACT] THEN
  REWRITE_TAC[GSYM SUM_LMUL] THEN MATCH_MP_TAC SUM_LE THEN
  REWRITE_TAC[FINITE_NUMSEG_LT; IN_ELIM_THM] THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`;`j:num`]
    CARLESON_ROOT_ENERGY_LB) THEN
  ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC);;

(* Arithmetic core: (2 (C3 gam)^2) S <= 8 C3^2 d given gam^2 S <= 4d,        *)
(* S,d>=0.                                                                   *)
let INR2_TAIL_ARITH = prove
 (`!C3 gam S d:real. &0 <= C3 /\ &0 <= gam /\
     gam pow 2 * S <= &4 * d /\ &0 <= S /\ &0 <= d
     ==> (&2 * (C3 * gam) pow 2) * S <= &8 * C3 pow 2 * d`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(&2 * (C3 * gam) pow 2) * S = (&2 * C3 pow 2) * (gam pow 2 * S)`
   SUBST1_TAC THENL [CONV_TAC REAL_RING; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(&2 * C3 pow 2) * (&4 * d)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[REAL_LE_POW_2] THEN
      REAL_ARITH_TAC;
    REWRITE_TAC[REAL_ARITH `(&2*C3sq)*(&4*d) = &8*C3sq*d`] THEN
      REAL_ARITH_TAC]);;

(* Leg-2 collapse: sum_{j<N} (C3 gam)^2 (2*1*inv 2^{k_j}) <= 8 C3^2 d.       *)
let CARLESON_HJ_SUM_ARITH = prove
 (`!C3 gam (kf:num->int) N d.
     &0 <= C3 /\ &0 <= gam /\ &0 <= d /\
     gam pow 2 * sum {j | j < N} (\j. &2 zpow (--(kf j))) <= &4 * d
     ==> sum {j | j < N} (\j. (C3 * gam) pow 2 * (&2 * &1 * inv(&2 zpow (kf
       j))))
         <= &8 * C3 pow 2 * d`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_MUL_RID; GSYM REAL_ZPOW_NEG] THEN
  REWRITE_TAC[REAL_ARITH `(C3 * gam) pow 2 * &2 * z = (&2 * (C3*gam) pow 2) *
    z`] THEN
  REWRITE_TAC[SUM_LMUL] THEN
  REWRITE_TAC[REAL_ARITH `(&2 * (C3 * gam) pow 2) * &1 * S = (&2 * (C3 * gam)
    pow 2) * S`] THEN
  MP_TAC(ISPECL [`C3:real`;`gam:real`;
    `sum {j | j < N} (\j. &2 zpow (--((kf:num->int) j)))`;
      `d:real`] INR2_TAIL_ARITH) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MATCH_MP_TAC SUM_POS_LE THEN REWRITE_TAC[FINITE_NUMSEG_LT; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_ZPOW_LE THEN REAL_ARITH_TAC);;

(* THE MISSING LINK: sum over P' of the block-2 row-sum^2 <= 8 C3^2 delta_f  *)
(* P'.                                                                       *)
let CARLESON_INR2_SUMSQ = prove
 (`?C3. &0 <= C3 /\
    !f gam P.
       &0 < gam /\ FINITE P /\ energy_f f P <= gam
       ==> sum (carleson_Pextract f gam P)
             (\sigma. (sum {t | t IN carleson_Pextract f gam P /\
                               tile_J sigma SUBSET tile_Jl t}
                  (\t. norm(integral (:real^1)
                        (\z. phi_sigma sigma carleson_phi (drop z) *
                             cnj(phi_sigma t carleson_phi (drop z)))) *
                       norm(carleson_ip f t))) pow 2)
           <= &8 * C3 pow 2 * delta_f f (carleson_Pextract f gam P)`,
  X_CHOOSE_THEN `C3:real` STRIP_ASSUME_TAC CARLESON_HJ_PIECE THEN
  EXISTS_TAC `C3:real` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`]
    THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `energy_f f (carleson_Pextract f gam P) <= gam` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
     EXISTS_TAC `energy_f f (P:(int#int#int)->bool)` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ENERGY_MONO THEN
    ASM_REWRITE_TAC[CARLESON_PEXTRACT_SUBSET]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\sigma. (sum {t | t IN carleson_Pextract f gam P /\ tile_J sigma SUBSET
     tile_Jl t}
                  (\t. norm(integral (:real^1)
                        (\z. phi_sigma sigma carleson_phi (drop z) *
                             cnj(phi_sigma t carleson_phi (drop z)))) *
                       norm(carleson_ip f t))) pow 2`;
    `carleson_piece f gam (carleson_Rtilde P) P`;
    `{j | j < carleson_stopN f gam P}`] SUM_UNIONS_IMAGE_DISJOINT) THEN
  REWRITE_TAC[GSYM carleson_Pextract] THEN
  ANTS_TAC THENL
   [REWRITE_TAC[FINITE_NUMSEG_LT; IN_ELIM_THM] THEN REPEAT CONJ_TAC THENL
     [X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      MATCH_MP_TAC CARLESON_PIECE_FINITE THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      MATCH_MP_TAC CARLESON_PIECE_NONEMPTY THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`a:num`;`b:num`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `a:num < b \/ b < a` STRIP_ASSUME_TAC THENL
       [ASM_ARITH_TAC;
        MATCH_MP_TAC CARLESON_PIECE_DISJOINT THEN
          ASM_SIMP_TAC[CARLESON_ACTIVE_RSEQ];
        ONCE_REWRITE_TAC[DISJOINT_SYM] THEN
        MATCH_MP_TAC CARLESON_PIECE_DISJOINT THEN
          ASM_SIMP_TAC[CARLESON_ACTIVE_RSEQ]]];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum {j | j < carleson_stopN f gam P}
    (\j. (C3 * gam) pow 2 * &2 * &1 *
         inv(&2 zpow (tile_k (carleson_rootseq f gam (carleson_Rtilde P) P
           j))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE THEN REWRITE_TAC[FINITE_NUMSEG_LT; IN_ELIM_THM] THEN
    X_GEN_TAC `j:num` THEN DISCH_TAC THEN
    FIRST_ASSUM(fun th ->
      if is_forall(concl th) && (length(fst(strip_forall(concl th))) = 5)
      then MP_TAC(SPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`;
        `j:num`;`gam:real`] th) else NO_TAC) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[REAL_LT_IMP_LE]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  MP_TAC(BETA_RULE(ISPECL [`C3:real`; `gam:real`;
    `\j. tile_k (carleson_rootseq f gam (carleson_Rtilde P) P j)`;
    `carleson_stopN f gam P`;
    `delta_f f (carleson_Pextract f gam P)`] CARLESON_HJ_SUM_ARITH)) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[DELTA_POS] THEN CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC;
    MP_TAC(ISPECL [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`]
      CARLESON_ROOT_MEASURE_BUDGET) THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286K(b) FINAL GRAM BOUND: delta_f f Pextract <= C6/4. Chains              *)
(* OFFDIAG_2BLOCK                                                            *)
(* (offdiag <= 2 sum|ip|inr2) + OFFBLOCK_CS (<= 2 sqrt(d) sqrt(sum inr2^2))  *)
(* +                                                                         *)
(* CARLESON_INR2_SUMSQ (sum inr2^2 <= 8 Cb^2 d) -> offdiag <= sqrt(d)        *)
(* sqrt(32                                                                   *)
(* Cb^2 d), then CARLESON_GRAM_BUDGET2 (K=32 Cb^2) -> d <= Ca + sqrt(32      *)
(* Cb^2).                                                                    *)
(* ========================================================================= *)

(* sqrt arithmetic: 2 sqrt(d) sqrt(X) <= sqrt(d) sqrt(32 C^2 d) when X<=8C^2 *)
(* d.                                                                        *)
let GRAM_SQRT_COLLAPSE = prove
 (`!d C X. &0 <= d /\ &0 <= C /\ &0 <= X /\ X <= &8 * C pow 2 * d
     ==> &2 * sqrt d * sqrt X <= sqrt d * sqrt((&32 * C pow 2) * d)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&2 * sqrt d * sqrt X = sqrt d * sqrt(&4 * X)` SUBST1_TAC THENL
   [REWRITE_TAC[SQRT_MUL] THEN
    SUBGOAL_THEN `sqrt(&4) = &2` SUBST1_TAC THENL
     [SUBGOAL_THEN `&4 = &2 pow 2` SUBST1_TAC THENL
       [REAL_ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[POW_2_SQRT_ABS] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SQRT_MONO_LE_EQ] THEN ASM_REAL_ARITH_TAC]);;

(* THE GRAM BOUND for Pextract. C6 = 4(Ca + sqrt(32 Cb^2)) is a valid budget *)
(* constant (286M needs SOME C6).                                            *)
let CARLESON_GRAM_DELTA = prove
 (`?C6. &0 <= C6 /\
    !f gam P.
       (\z. f(drop z)) IN lspace (:real^1) (&2) /\
       lnorm (:real^1) (&2) (\z. f(drop z)) <= &1 /\
       &0 < gam /\ FINITE P /\ energy_f f P <= gam
       ==> delta_f f (carleson_Pextract f gam P) <= C6 / &4`,
  X_CHOOSE_THEN `Ca:real` STRIP_ASSUME_TAC CARLESON_GRAM_BUDGET2 THEN
  X_CHOOSE_THEN `Cb:real` STRIP_ASSUME_TAC CARLESON_INR2_SUMSQ THEN
  EXISTS_TAC `&4 * (Ca + sqrt(&32 * Cb pow 2))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_ADD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_LE_MUL THEN
    REWRITE_TAC[REAL_LE_POW_2] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`]
    THEN
  STRIP_TAC THEN
  SUBGOAL_THEN
    `(&4 * (Ca + sqrt(&32 * Cb pow 2))) / &4 = Ca + sqrt(&32 * Cb pow 2)`
   SUBST1_TAC THENL [CONV_TAC REAL_FIELD; ALL_TAC] THEN
  (* apply GRAM_BUDGET2 at P' = Pextract, K = 32 Cb^2                        *)
  FIRST_X_ASSUM(fun th ->
    if is_forall(concl th) &&
       (let b = snd(strip_forall(concl th)) in
        is_imp b && free_in `sqrt` (snd(dest_imp b)))
    then MP_TAC(SPECL [`f:real->complex`; `carleson_Pextract f gam P`;
      `&32 * Cb pow 2`] th) else NO_TAC) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_PEXTRACT_FINITE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[REAL_LE_POW_2] THEN
        REAL_ARITH_TAC;
      (* the offdiag <= sqrt(d) sqrt(32 Cb^2 d) bound                        *)
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `&2 * sum (carleson_Pextract f gam P)
        (\s. norm(carleson_ip f s) *
             sum {t | t IN carleson_Pextract f gam P /\ tile_J s SUBSET tile_Jl
               t}
                 (\t. norm(integral (:real^1)
                       (\z. phi_sigma s carleson_phi (drop z) *
                            cnj(phi_sigma t carleson_phi (drop z)))) *
                      norm(carleson_ip f t)))` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC CARLESON_OFFDIAG_2BLOCK THEN
        MATCH_MP_TAC CARLESON_PEXTRACT_FINITE THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `&2 * sqrt(delta_f f (carleson_Pextract f gam P)) *
        sqrt(sum (carleson_Pextract f gam P)
          (\s. (sum {t | t IN carleson_Pextract f gam P /\ tile_J s SUBSET
            tile_Jl t}
                 (\t. norm(integral (:real^1)
                       (\z. phi_sigma s carleson_phi (drop z) *
                            cnj(phi_sigma t carleson_phi (drop z)))) *
                      norm(carleson_ip f t))) pow 2))` THEN
      CONJ_TAC THENL
       [REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN MATCH_MP_TAC REAL_LE_LMUL THEN
        CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
        MP_TAC(ISPECL [`f:real->complex`; `carleson_Pextract f gam P`;
          `\s. sum {t | t IN carleson_Pextract f gam P /\ tile_J s SUBSET
            tile_Jl t}
                 (\t. norm(integral (:real^1)
                       (\z. phi_sigma s carleson_phi (drop z) *
                            cnj(phi_sigma t carleson_phi (drop z)))) *
                      norm(carleson_ip f t))` ] OFFBLOCK_CS) THEN
        REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC CARLESON_PEXTRACT_FINITE THEN
           ASM_REWRITE_TAC[]; ALL_TAC] THEN
        X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
        MATCH_MP_TAC SUM_POS_LE THEN REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN
        MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[NORM_POS_LE]; ALL_TAC] THEN
      MATCH_MP_TAC GRAM_SQRT_COLLAPSE THEN
      ASM_REWRITE_TAC[DELTA_POS] THEN CONJ_TAC THENL
       [MATCH_MP_TAC SUM_POS_LE THEN REPEAT STRIP_TAC THEN
         REWRITE_TAC[REAL_LE_POW_2];
        FIRST_X_ASSUM(fun th ->
          if is_forall(concl th) && (length(fst(strip_forall(concl th))) = 3)
          then MP_TAC(SPECL
            [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`] th)
          else NO_TAC) THEN
        ASM_REWRITE_TAC[]]];
    DISCH_TAC THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `Ca + sqrt(&32 * Cb pow 2)` THEN
    ASM_REWRITE_TAC[REAL_LE_REFL]]);;

(* ========================================================================= *)
(* 286K (energy stopping-time budget), FULLY PROVED.  For f in L^2 with      *)
(* ||f||_2 <= 1, the energy budget predicate holds with C6 = 4(Ca + sqrt(32  *)
(* Cb^2)) (Ca from the Gram roof GRAM_BUDGET2, Cb from the H_j square-sum    *)
(* INR2_SUMSQ).  R1 = carleson_Rextract (the greedy-extracted roots): the    *)
(* measure leg gam^2 sum_R1 2^{-k} <= 4 delta_f Pextract <= 4(C6/4) = C6     *)
(* [CARLESON_MEASURE_BUDGET + CARLESON_GRAM_DELTA]; the residual-energy leg  *)
(* energy(P DIFF R1^+) <= gam/2 [CARLESON_RESIDUAL_ENERGY].  This closes the *)
(* energy budget that 286M (CARLESON_286M_STEP) consumes as a hypothesis.    *)
(* ========================================================================= *)
let CARLESON_286K = prove
 (`?C6. &0 <= C6 /\
    !f. (\z. f(drop z)) IN lspace (:real^1) (&2) /\
        lnorm (:real^1) (&2) (\z. f(drop z)) <= &1
        ==> carleson_energy_budget f C6`,
  X_CHOOSE_THEN `C6:real` STRIP_ASSUME_TAC CARLESON_GRAM_DELTA THEN
  EXISTS_TAC `C6:real` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `f:real->complex` THEN STRIP_TAC THEN
  REWRITE_TAC[carleson_energy_budget] THEN
  MAP_EVERY X_GEN_TAC [`P:(int#int#int)->bool`;`gam:real`] THEN STRIP_TAC THEN
  EXISTS_TAC `carleson_Rextract f gam P` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[carleson_Rextract] THEN MATCH_MP_TAC FINITE_IMAGE THEN
    REWRITE_TAC[FINITE_NUMSEG_LT];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `&4 * delta_f f (carleson_Pextract f gam P)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_MEASURE_BUDGET THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&4 * C6 / &4` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC; ALL_TAC] THEN
      FIRST_X_ASSUM(fun th ->
        if is_forall(concl th) && (length(fst(strip_forall(concl th))) = 3)
        then MP_TAC(SPECL
          [`f:real->complex`;`gam:real`;`P:(int#int#int)->bool`] th)
        else NO_TAC) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC CARLESON_RESIDUAL_ENERGY THEN ASM_REWRITE_TAC[]]);;


(* ========================================================================= *)
(* 286M with both budget hypotheses DISCHARGED (via CARLESON_286J mass +     *)
(* CARLESON_286K energy).  For f in L^2 with ||f||_2 <= 1, E measurable with *)
(* muE <= 1, and any measurable g:R->R, the linearized tile-operator sum is  *)
(* bounded by an ABSOLUTE constant C = C8 (C5 + C6). This is the             *)
(* unconditional                                                             *)
(* form 286N applies to the normalized "tilde" functions. (h is free,        *)
(* matching                                                                  *)
(* CARLESON_286M / carleson_mass_budget.)                                    *)
(* ========================================================================= *)
let CARLESON_286M_CONCRETE = prove
 (`?C. &0 <= C /\
       !(f:real->complex) E h P.
          (\z. f(drop z)) IN lspace (:real^1) (&2) /\
          lnorm (:real^1) (&2) (\z. f(drop z)) <= &1 /\
          real_lebesgue_measurable E /\ real_measurable E /\
          real_measure E <= &1 /\
          h real_measurable_on (:real) /\ FINITE P /\
          (!t. cw_tile t real_integrable_on {x | x IN E /\ h x IN tile_J t})
          ==> sum P (\s. norm(carleson_ip f s *
                   integral (IMAGE lift {x | x IN E /\ h x IN tile_Jr s})
                        (\z. phi_sigma s carleson_phi (drop z))))
              <= C`,
  X_CHOOSE_THEN `C8:real` STRIP_ASSUME_TAC CARLESON_286M THEN
  X_CHOOSE_THEN `C5:real` STRIP_ASSUME_TAC CARLESON_286J THEN
  X_CHOOSE_THEN `C6:real` STRIP_ASSUME_TAC CARLESON_286K THEN
  EXISTS_TAC `C8 * (C5 + C6):real` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MATCH_MP_TAC o check(fun th ->
    can (find_term (fun t -> t = `C8:real`)) (concl th))) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [FIRST_X_ASSUM(MATCH_MP_TAC o check(fun th ->
      can (find_term (fun t -> t = `carleson_mass_budget`)) (concl th))) THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(MATCH_MP_TAC o check(fun th ->
      can (find_term (fun t -> t = `carleson_energy_budget`)) (concl th))) THEN
    ASM_REWRITE_TAC[]]);;


(* ========================================================================= *)
(* 286N (Fremlin mt286.tex 1871-1937), finite-P form.  For each measurable g *)
(* and measurable FF, and each f in L^2 with ||f||_2 <= 1 and 0 < muFF, the  *)
(* linearized tile-operator sum is <= C9 sqrt(muFF), C9 = C sqrt2 (C the     *)
(* 286M                                                                      *)
(* constant at the dilated frequency map).  [C9 quantified after g,FF -- the *)
(* 286M constant carries a free h, so its h-uniformity is not exposed; this  *)
(* form is sufficient for 286O, which fixes g,FF per application.]           *)
(* Method: pick k with muFF <= 2^k <= 2 muFF (POW2_BRACKET);                 *)
(* CARLESON_SUM_DILATE                                                       *)
(* + TILE_STAR_SUM_REINDEX give the sum = sqrt(2^k) sum_{star P}(tilde       *)
(* summand);                                                                 *)
(* CARLESON_286M_CONCRETE at h := gtilde(x)=2^k g(2^k x), FFtilde the 2^-k   *)
(* dilate                                                                    *)
(* (muFFtilde <= 1 via DILATE_PREIMAGE_MEASURE, ||ftilde||=||f|| via         *)
(* LNORM_DILATE_                                                             *)
(* EQ) bounds it by C; sqrt(2^k) <= sqrt(2 muFF).                            *)
(* ========================================================================= *)
let CARLESON_286N = prove
 (`?C9. &0 <= C9 /\
     !(g:real->real) FF (f:real->complex) P.
        (\z. f(drop z)) IN lspace (:real^1) (&2) /\
        lnorm (:real^1) (&2) (\z. f(drop z)) <= &1 /\
        g real_measurable_on (:real) /\ real_measurable FF /\
        &0 < real_measure FF /\ FINITE P /\
        (!t. cw_tile t real_integrable_on {x | x IN FF /\ g x IN tile_J t})
        ==> sum P (\s. norm(carleson_ip f s *
                 integral (IMAGE lift {x | x IN FF /\ g x IN tile_Jr s})
                      (\z. phi_sigma s carleson_phi (drop z))))
            <= C9 * sqrt(real_measure FF)`,
  X_CHOOSE_THEN `C:real` STRIP_ASSUME_TAC CARLESON_286M_CONCRETE THEN
  EXISTS_TAC `C * sqrt(&2)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SQRT_POS_LE THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`g:real->real`; `FF:real->bool`] THEN
  MP_TAC(ISPEC `real_measure FF` POW2_BRACKET) THEN
  ASM_CASES_TAC `&0 < real_measure FF` THENL
   [ALL_TAC;
    REPEAT STRIP_TAC THEN ASM_MESON_TAC[]] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:int` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT STRIP_TAC THEN
  (* per-term dilation + side-condition                                      *)
  MP_TAC(ISPECL [`f:real->complex`; `FF:real->bool`; `g:real->real`; `k:int`;
                 `P:(int#int#int)->bool`] CARLESON_SUM_DILATE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `{x | &2 zpow k * x IN FF /\
           &2 zpow k * g (&2 zpow k * x) IN tile_Jr (FST s + k,SND s)} =
      {x | &2 zpow k * x IN FF} INTER
      {x | (\y. &2 zpow k * g(&2 zpow k * y)) x IN tile_Jr (FST s + k,SND s)}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
      MP_TAC(ISPECL [`FF:real->bool`;
        `&2 zpow k`] DILATE_PREIMAGE_MEASURE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
      SUBGOAL_THEN `(FST s + k, SND s):int#int#int =
                    (FST s + k, FST(SND s), SND(SND s))` SUBST1_TAC THENL
       [REWRITE_TAC[PAIR]; ALL_TAC] THEN
      REWRITE_TAC[tile_Jr] THEN BETA_TAC THEN
      MATCH_MP_TAC H_PREIMAGE_DYHO_LEBESGUE THEN
      MATCH_MP_TAC REAL_MEASURABLE_ON_DILATE_MUL THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  (* reindex the star-sum                                                    *)
  SUBGOAL_THEN
   `sum P (\s. norm(carleson_ip (\x. Cx (sqrt (&2 zpow k)) * f (&2 zpow k * x))
       (FST s + k,FST (SND s),SND (SND s)) *
       integral (IMAGE lift
         {x | &2 zpow k * x IN FF /\ &2 zpow k * g (&2 zpow k * x) IN tile_Jr
           (FST s + k,FST (SND s),SND (SND s))})
       (\z. phi_sigma (FST s + k,FST (SND s),SND (SND s)) carleson_phi (drop
         z)))) =
    sum (IMAGE (\u:int#int#int. FST u + k,FST (SND u),SND (SND u)) P)
     (\u. norm(carleson_ip (\x. Cx (sqrt (&2 zpow k)) * f (&2 zpow k * x)) u *
       integral (IMAGE lift
         {x | &2 zpow k * x IN FF /\ &2 zpow k * g (&2 zpow k * x) IN tile_Jr
           u})
       (\z. phi_sigma u carleson_phi (drop z))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[TILE_STAR_SUM_REINDEX]; ALL_TAC] THEN
  (* bound sqrt(2^k) sum <= sqrt(2^k) C <= (C sqrt2) sqrt(muFF)              *)
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `sqrt(&2 zpow k) * C` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_ZPOW_LE THEN
       REAL_ARITH_TAC;
      ALL_TAC] THEN
    (* sum_{star P}(tilde summand) <= C via CARLESON_286M_CONCRETE (h =      *)
    (* gtilde)                                                               *)
    SUBGOAL_THEN
     `!u:int#int#int. {x | &2 zpow k * x IN FF /\ &2 zpow k * g (&2 zpow k * x)
       IN tile_Jr u} =
          {x | x IN {y | &2 zpow k * y IN FF} /\ &2 zpow k * g (&2 zpow k * x)
            IN tile_Jr u}`
     (LABEL_TAC "RE") THENL
     [GEN_TAC THEN REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `x:real` THEN
      REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
    USE_THEN "RE" (fun th -> ONCE_REWRITE_TAC[th]) THEN
    FIRST_ASSUM(fun th -> if is_forall(concl th) &&
                             can (find_term (fun t->t=`carleson_ip`))(concl th)
                          then MATCH_MP_TAC (BETA_RULE th) else NO_TAC) THEN
    REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [(* ftilde in L^2                                                       *)
      SUBGOAL_THEN `(\z. Cx (sqrt (&2 zpow k)) * f (&2 zpow k * drop z)) =
                    (\z. Cx(sqrt(&2 zpow k)) * (\w. f(drop w))(&2 zpow k % z))`
       SUBST1_TAC THENL
       [MP_TAC(ISPECL [`f:real->complex`; `&2 zpow k`] FTILDE_DROP_EQ) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC L2_DILATE_LSPACE THEN ASM_REWRITE_TAC[];
      (* ||ftilde|| <= 1                                                     *)
      SUBGOAL_THEN `(\z. Cx (sqrt (&2 zpow k)) * f (&2 zpow k * drop z)) =
                    (\z. Cx(sqrt(&2 zpow k)) * (\w. f(drop w))(&2 zpow k % z))`
       SUBST1_TAC THENL
       [MP_TAC(ISPECL [`f:real->complex`; `&2 zpow k`] FTILDE_DROP_EQ) THEN
        ASM_REWRITE_TAC[] THEN SIMP_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`\w. (f:real->complex)(drop w)`;
        `&2 zpow k`] LNORM_DILATE_EQ) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[];
      (* FFtilde lebesgue-measurable                                         *)
      MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
      MP_TAC(ISPECL [`FF:real->bool`;
        `&2 zpow k`] DILATE_PREIMAGE_MEASURE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      (* FFtilde measurable                                                  *)
      MP_TAC(ISPECL [`FF:real->bool`;
        `&2 zpow k`] DILATE_PREIMAGE_MEASURE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      (* muFFtilde <= 1                                                      *)
      MP_TAC(ISPECL [`FF:real->bool`;
        `&2 zpow k`] DILATE_PREIMAGE_MEASURE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT2 th]) THEN
      MATCH_MP_TAC REAL_LE_LCANCEL_IMP THEN EXISTS_TAC `&2 zpow k` THEN
      ASM_REWRITE_TAC[REAL_MUL_ASSOC] THEN
      SUBGOAL_THEN `&2 zpow k * inv(&2 zpow k) = &1` SUBST1_TAC THENL
       [MATCH_MP_TAC REAL_MUL_RINV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_REWRITE_TAC[REAL_MUL_LID; REAL_MUL_RID];
      (* gtilde measurable                                                   *)
      MATCH_MP_TAC REAL_MEASURABLE_ON_DILATE_MUL THEN ASM_REWRITE_TAC[];
      (* FINITE (star P)                                                     *)
      MATCH_MP_TAC FINITE_IMAGE THEN ASM_REWRITE_TAC[];
      (* integrability of cw_tile on tilde-regions                           *)
      X_GEN_TAC `t:int#int#int` THEN
      MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN
      MATCH_MP_TAC REAL_MEASURABLE_LEBMEAS_SUBSET THEN
      EXISTS_TAC `{y | &2 zpow k * y IN FF}` THEN REPEAT CONJ_TAC THENL
       [SUBGOAL_THEN
         `{x | x IN {y | &2 zpow k * y IN FF} /\ &2 zpow k * g (&2 zpow k * x)
           IN tile_J t} =
          {y | &2 zpow k * y IN FF} INTER
          {x | (\w. &2 zpow k * g(&2 zpow k * w)) x IN tile_J t}`
         SUBST1_TAC THENL
         [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM]; ALL_TAC] THEN
        MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
          MP_TAC(ISPECL [`FF:real->bool`;
            `&2 zpow k`] DILATE_PREIMAGE_MEASURE) THEN
          ANTS_TAC THENL
            [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
          SUBGOAL_THEN
            `t:int#int#int = (FST t, FST(SND t), SND(SND t))` SUBST1_TAC THENL
           [REWRITE_TAC[PAIR]; ALL_TAC] THEN
          REWRITE_TAC[tile_J] THEN BETA_TAC THEN
          MATCH_MP_TAC H_PREIMAGE_DYHO_LEBESGUE THEN
          MATCH_MP_TAC REAL_MEASURABLE_ON_DILATE_MUL THEN ASM_REWRITE_TAC[]];
        MP_TAC(ISPECL [`FF:real->bool`;
          `&2 zpow k`] DILATE_PREIMAGE_MEASURE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
        REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]]];
    (* final arithmetic sqrt(2^k) C <= (C sqrt2) sqrt(muFF)                  *)
    SUBGOAL_THEN `(C * sqrt(&2)) * sqrt(real_measure FF) =
                  (sqrt(&2) * sqrt(real_measure FF)) * C` SUBST1_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM SQRT_MUL] THEN
    MP_TAC(ISPECL [`&2 zpow k`; `&2 * real_measure FF`] SQRT_MONO_LE) THEN
    ASM_REWRITE_TAC[]]);;


