(* ========================================================================= *)
(* Fremlin 246K (factor-4 sign trick) -- toward the deep 286P tile bound.    *)
(* ========================================================================= *)

(* ========================================================================= *)
(* Fremlin 246K (factor-4 sign trick), toward 286P.  For w abs-integrable on *)
(* measurable E, there is measurable F' SUBSET E with int_E|w| <= 4|int_F'   *)
(* w|.                                                                       *)
(* ========================================================================= *)

(* Subregion {x IN E | c <= (w x)$k} is measurable (w abs-int on meas E,     *)
(* 1<=k<=2).                                                                 *)
let K246_SUBREGION_GE = prove
 (`!(w:real^1->complex) E c k.
     w absolutely_integrable_on E /\ measurable E /\ 1 <= k /\ k <= 2
     ==> measurable {x:real^1 | x IN E /\ c <= (w x)$k}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MEASURABLE_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `E:real^1->bool` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ALL_TAC; SET_TAC[]] THEN
  SUBGOAL_THEN `{x:real^1 | x IN E /\ c <= (w x)$k} =
    {x | (\y. if y IN E then (w:real^1->complex) y else vec 0) x $ k >= c}
      INTER E` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM; real_ge] THEN
    GEN_TAC THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC TAUT; ALL_TAC] THEN
  MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\x:real^1. if x IN E then (w:real^1->complex) x else vec 0)
     measurable_on (:real^1)` MP_TAC THENL
     [ONCE_REWRITE_TAC[GSYM MEASURABLE_ON_UNIV] THEN
       REWRITE_TAC[MEASURABLE_ON_UNIV] THEN
      MATCH_MP_TAC INTEGRABLE_IMP_MEASURABLE THEN
      REWRITE_TAC[INTEGRABLE_RESTRICT] THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[MEASURABLE_ON_PREIMAGE_HALFSPACE_COMPONENT_GE] THEN
    DISCH_THEN(MP_TAC o SPECL [`c:real`; `k:num`]) THEN
    ASM_REWRITE_TAC[DIMINDEX_2];
    MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN ASM_REWRITE_TAC[]]);;

(* Companion: subregion {x IN E | (w x)$k <= c} is measurable.               *)
let K246_SUBREGION_LE = prove
 (`!(w:real^1->complex) E c k.
     w absolutely_integrable_on E /\ measurable E /\ 1 <= k /\ k <= 2
     ==> measurable {x:real^1 | x IN E /\ (w x)$k <= c}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MEASURABLE_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `E:real^1->bool` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ALL_TAC; SET_TAC[]] THEN
  SUBGOAL_THEN `{x:real^1 | x IN E /\ (w x)$k <= c} =
    {x | (\y. if y IN E then (w:real^1->complex) y else vec 0) x $ k <= c}
      INTER E` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
    GEN_TAC THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC TAUT; ALL_TAC] THEN
  MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\x:real^1. if x IN E then (w:real^1->complex) x else vec 0)
     measurable_on (:real^1)` MP_TAC THENL
     [ONCE_REWRITE_TAC[GSYM MEASURABLE_ON_UNIV] THEN
       REWRITE_TAC[MEASURABLE_ON_UNIV] THEN
      MATCH_MP_TAC INTEGRABLE_IMP_MEASURABLE THEN
      REWRITE_TAC[INTEGRABLE_RESTRICT] THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[MEASURABLE_ON_PREIMAGE_HALFSPACE_COMPONENT_LE] THEN
    DISCH_THEN(MP_TAC o SPECL [`c:real`; `k:num`]) THEN
    ASM_REWRITE_TAC[DIMINDEX_2];
    MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN ASM_REWRITE_TAC[]]);;

(* Positive-part component identity: (int_{SP} w)$k = int_E max((w x)$k, 0), *)
(* SP={(w x)$k>=0}.                                                          *)
let K246_SP_COMPONENT = prove
 (`!(w:real^1->complex) E k.
     w absolutely_integrable_on E /\ measurable E /\ 1 <= k /\ k <= 2
     ==> (integral {x | x IN E /\ &0 <= (w x)$k} w)$k =
         drop(integral E (\x. lift(max ((w x)$k) (&0))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(w:real^1->complex) absolutely_integrable_on {x | x IN E /\ &0 <= (w
    x)$k}` ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
    EXISTS_TAC `E:real^1->bool` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN GEN_TAC THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[];
      MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN
      MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`; `&0:real`;
        `k:num`] K246_SUBREGION_GE) THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ASM_SIMP_TAC[INTEGRAL_COMPONENT; ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE] THEN
  AP_TERM_TAC THEN
  SUBGOAL_THEN
   `integral E (\x:real^1. lift(max ((w x)$k) (&0))) =
    integral E (\x. if x IN {x | x IN E /\ &0 <= (w x)$k} then
      lift((w:real^1->complex) x$k) else vec 0)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN COND_CASES_TAC THENL
     [AP_TERM_TAC THEN POP_ASSUM MP_TAC THEN REAL_ARITH_TAC;
      REWRITE_TAC[GSYM LIFT_NUM] THEN AP_TERM_TAC THEN POP_ASSUM MP_TAC THEN
        REAL_ARITH_TAC]; ALL_TAC] THEN
  REWRITE_TAC[INTEGRAL_RESTRICT_INTER] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN GEN_TAC THEN
    CONV_TAC TAUT);;

(* Negative-part companion: -(int_{SN} w)$k = int_E max(-(w x)$k, 0), SN={(w *)
(* x)$k<=0}.                                                                 *)
let K246_SN_COMPONENT = prove
 (`!(w:real^1->complex) E k.
     w absolutely_integrable_on E /\ measurable E /\ 1 <= k /\ k <= 2
     ==> --((integral {x | x IN E /\ (w x)$k <= &0} w)$k) =
         drop(integral E (\x. lift(max (--((w x)$k)) (&0))))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\x. --((w:real^1->complex) x)`; `E:real^1->bool`;
    `k:num`] K246_SP_COMPONENT) THEN
  ASM_SIMP_TAC[ABSOLUTELY_INTEGRABLE_NEG; VECTOR_NEG_COMPONENT] THEN
  REWRITE_TAC[REAL_ARITH `&0 <= --u <=> u <= &0`] THEN
  SUBGOAL_THEN
   `integral {x | x IN E /\ (w x)$k <= &0} (\x. --((w:real^1->complex) x)) =
    --(integral {x | x IN E /\ (w x)$k <= &0} w)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC INTEGRAL_NEG THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
    EXISTS_TAC `E:real^1->bool` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN GEN_TAC THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[];
      MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN
      MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`; `&0:real`;
        `k:num`] K246_SUBREGION_LE) THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[VECTOR_NEG_COMPONENT]);;

(* lift of a component of an abs-integrable complex fn is abs-integrable     *)
(* (clean, no free :N).                                                      *)
let K246_LIFT_COMPONENT_ABSINT = prove
 (`!(w:real^1->complex) E k.
     w absolutely_integrable_on E /\ 1 <= k /\ k <= 2
     ==> (\x:real^1. lift((w x)$k)) absolutely_integrable_on E`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(INST_TYPE [`:2`,`:N`] ABSOLUTELY_INTEGRABLE_LIFT_COMPONENT) THEN
  ASM_REWRITE_TAC[DIMINDEX_2]);;

(* abs = pos-part + neg-part, as an integral identity.                       *)
let K246_ABS_SPLIT = prove
 (`!(w:real^1->complex) E k.
     w absolutely_integrable_on E /\ measurable E /\ 1 <= k /\ k <= 2
     ==> integral E (\x. lift(abs((w x)$k))) =
         integral E (\x. lift(max ((w x)$k) (&0))) + integral E (\x. lift(max
           (--((w x)$k)) (&0)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(((w:real^1->complex) x)$k)) absolutely_integrable_on E`
    ASSUME_TAC THENL
   [MATCH_MP_TAC K246_LIFT_COMPONENT_ABSINT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(&0)) absolutely_integrable_on E` ASSUME_TAC THENL
   [REWRITE_TAC[LIFT_NUM; ABSOLUTELY_INTEGRABLE_0]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(--(((w:real^1->complex) x)$k))) absolutely_integrable_on
    E` ASSUME_TAC THENL
   [REWRITE_TAC[LIFT_NEG] THEN MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NEG THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(max (((w:real^1->complex) x)$k) (&0)))
    absolutely_integrable_on E` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\x:real^1. ((w:real^1->complex) x)$k`; `\x:real^1. &0`;
     `E:real^1->bool`]
      ABSOLUTELY_INTEGRABLE_MAX_1) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(max (--(((w:real^1->complex) x)$k)) (&0)))
    absolutely_integrable_on E` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\x:real^1. --(((w:real^1->complex) x)$k)`; `\x:real^1. &0`;
     `E:real^1->bool`]
      ABSOLUTELY_INTEGRABLE_MAX_1) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\x:real^1. lift(max (((w:real^1->complex) x)$k) (&0))`;
                 `\x:real^1. lift(max (--(((w:real^1->complex) x)$k)) (&0))`;
                   `E:real^1->bool`]
    INTEGRAL_ADD) THEN
  ASM_SIMP_TAC[ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[GSYM LIFT_ADD] THEN AP_TERM_TAC THEN REAL_ARITH_TAC);;

(* per-component bound: int_E |w$k| <= norm(int_{SP} w) + norm(int_{SN} w).  *)
let K246_COMPONENT_BOUND = prove
 (`!(w:real^1->complex) E k.
     w absolutely_integrable_on E /\ measurable E /\ 1 <= k /\ k <= 2
     ==> drop(integral E (\x. lift(abs((w x)$k))))
         <= norm(integral {x | x IN E /\ &0 <= (w x)$k} w) +
            norm(integral {x | x IN E /\ (w x)$k <= &0} w)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`;
    `k:num`] K246_ABS_SPLIT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[DROP_ADD] THEN
  MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`;
    `k:num`] K246_SP_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`;
    `k:num`] K246_SN_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THENL
   [MATCH_MP_TAC(REAL_ARITH `abs a <= b ==> a <= b`) THEN
    MATCH_ACCEPT_TAC COMPONENT_LE_NORM;
    MATCH_MP_TAC(REAL_ARITH `abs a <= b ==> --a <= b`) THEN
    MATCH_ACCEPT_TAC COMPONENT_LE_NORM]);;

(* norm bounded by sum of |components|, integrated.                          *)
let K246_NORM_COMPONENTS = prove
 (`!(w:real^1->complex) E.
     w absolutely_integrable_on E /\ measurable E
     ==> drop(integral E (\x. lift(norm(w x))))
         <= drop(integral E (\x. lift(abs((w x)$1)))) + drop(integral E (\x.
           lift(abs((w x)$2))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(norm((w:real^1->complex) x))) absolutely_integrable_on E`
    ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(abs(((w:real^1->complex) x)$1))) absolutely_integrable_on
    E` ASSUME_TAC THENL
   [SUBGOAL_THEN `(\x:real^1. lift(abs(((w:real^1->complex) x)$1))) =
                  (\x. lift(norm(lift(((w:real^1->complex) x)$1))))` SUBST1_TAC
                    THENL
     [REWRITE_TAC[FUN_EQ_THM; NORM_LIFT]; ALL_TAC] THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
    MATCH_MP_TAC K246_LIFT_COMPONENT_ABSINT THEN
      ASM_REWRITE_TAC[ARITH]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(abs(((w:real^1->complex) x)$2))) absolutely_integrable_on
    E` ASSUME_TAC THENL
   [SUBGOAL_THEN `(\x:real^1. lift(abs(((w:real^1->complex) x)$2))) =
                  (\x. lift(norm(lift(((w:real^1->complex) x)$2))))` SUBST1_TAC
                    THENL
     [REWRITE_TAC[FUN_EQ_THM; NORM_LIFT]; ALL_TAC] THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
    MATCH_MP_TAC K246_LIFT_COMPONENT_ABSINT THEN
      ASM_REWRITE_TAC[ARITH]; ALL_TAC] THEN
  REWRITE_TAC[GSYM DROP_ADD] THEN
  MP_TAC(ISPECL [`\x:real^1. lift(abs(((w:real^1->complex) x)$1))`;
                 `\x:real^1. lift(abs(((w:real^1->complex) x)$2))`;
                   `E:real^1->bool`] INTEGRAL_ADD) THEN
  ASM_SIMP_TAC[ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC INTEGRAL_DROP_LE THEN
  ASM_SIMP_TAC[ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE] THEN CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_ADD THEN
     ASM_SIMP_TAC[ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE]; ALL_TAC] THEN
  X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[LIFT_DROP; DROP_ADD] THEN
  MP_TAC(ISPEC `(w:real^1->complex) x` COMPLEX_NORM_LE_RE_IM) THEN
  REWRITE_TAC[RE_DEF; IM_DEF] THEN REAL_ARITH_TAC);;

(* 246K (factor-4 sign trick): for w abs-int on measurable E, there is a     *)
(* measurable                                                                *)
(* F' SUBSET E with int_E |w| <= 4 |int_F' w|. Pick F' = argmax over the 4   *)
(* subregions                                                                *)
(* {Re>=0},{Re<=0},{Im>=0},{Im<=0} of |int_subregion w|.                     *)
let K246_SIGN_TRICK = prove
 (`!(w:real^1->complex) E.
     w absolutely_integrable_on E /\ measurable E
     ==> ?F'. measurable F' /\ F' SUBSET E /\
              drop(integral E (\x. lift(norm(w x)))) <= &4 * norm(integral F'
                w)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `drop(integral E (\x. lift(norm((w:real^1->complex) x)))) <=
    (norm(integral {x | x IN E /\ &0 <= (w x)$1} w) + norm(integral {x | x IN E
      /\ (w x)$1 <= &0} w)) +
    (norm(integral {x | x IN E /\ &0 <= (w x)$2} w) + norm(integral {x | x IN E
      /\ (w x)$2 <= &0} w))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `drop(integral E (\x. lift(abs(((w:real^1->complex) x)$1)))) +
                drop(integral E (\x. lift(abs(((w:real^1->complex) x)$2))))`
                  THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC K246_NORM_COMPONENTS THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THEN
        MATCH_MP_TAC K246_COMPONENT_BOUND THEN
      ASM_REWRITE_TAC[ARITH]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `measurable {x:real^1 | x IN E /\ &0 <= ((w:real^1->complex) x)$1} /\
    measurable {x:real^1 | x IN E /\ ((w:real^1->complex) x)$1 <= &0} /\
    measurable {x:real^1 | x IN E /\ &0 <= ((w:real^1->complex) x)$2} /\
    measurable {x:real^1 | x IN E /\ ((w:real^1->complex) x)$2 <= &0}`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`; `&0:real`;
       `1`] K246_SUBREGION_GE);
      MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`; `&0:real`;
        `1`] K246_SUBREGION_LE);
      MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`; `&0:real`;
        `2`] K246_SUBREGION_GE);
      MP_TAC(ISPECL [`w:real^1->complex`; `E:real^1->bool`; `&0:real`;
        `2`] K246_SUBREGION_LE)] THEN
    ASM_REWRITE_TAC[ARITH]; ALL_TAC] THEN
  MP_TAC(REAL_ARITH
   `!n1 n2 n3 n4 s:real.
       s <= (n1 + n2) + (n3 + n4)
       ==> s <= &4 * n1 \/ s <= &4 * n2 \/ s <= &4 * n3 \/ s <= &4 * n4`) THEN
  DISCH_THEN(MP_TAC o ISPECL
   [`norm(integral {x | x IN E /\ &0 <= ((w:real^1->complex) x)$1} w)`;
    `norm(integral {x | x IN E /\ ((w:real^1->complex) x)$1 <= &0} w)`;
    `norm(integral {x | x IN E /\ &0 <= ((w:real^1->complex) x)$2} w)`;
    `norm(integral {x | x IN E /\ ((w:real^1->complex) x)$2 <= &0} w)`;
    `drop(integral E (\x. lift(norm((w:real^1->complex) x))))`]) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [EXISTS_TAC `{x:real^1 | x IN E /\ &0 <= ((w:real^1->complex) x)$1}`;
    EXISTS_TAC `{x:real^1 | x IN E /\ ((w:real^1->complex) x)$1 <= &0}`;
    EXISTS_TAC `{x:real^1 | x IN E /\ &0 <= ((w:real^1->complex) x)$2}`;
    EXISTS_TAC `{x:real^1 | x IN E /\ ((w:real^1->complex) x)$2 <= &0}`] THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
  GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]);;


(* ========================================================================= *)
(* 286O(a) (Fremlin mt286.tex 1939-2005): the frequency bump theta_z.  For a *)
(* tile s with z in the right half J^r_s and y in the left half J^l_s, the   *)
(* value is phi-hat(2^{-k_s}(y - y^l_s))^2 (y^l_s = tile_ymid s, the lower   *)
(* quartile); zero if no such tile.  The qualifying tiles at distinct scales *)
(* have disjoint left-halves so at most one term is nonzero, and the sup     *)
(* below                                                                     *)
(* equals Fremlin's sum.  Elementary properties: 0 <= theta_z(y) <= 1, and   *)
(* theta_z(y) = 0 for y >= z.                                                *)
(* ========================================================================= *)
let carleson_theta = new_definition
 `carleson_theta z y =
    sup ({ Re(fourier carleson_phi (&2 zpow (--(tile_k s)) * (y - tile_ymid
      s))) pow 2
         | s | z IN tile_Jr s /\ y IN tile_Jl s } UNION {&0})`;;

(* Re(fourier carleson_phi) takes values in [0,1] (the 286Eb bump).          *)
let CARLESON_PHI_RE_BOUNDS = prove
 (`!t. &0 <= Re(fourier carleson_phi t) /\ Re(fourier carleson_phi t) <= &1`,
  GEN_TAC THEN MP_TAC carleson_phi THEN STRIP_TAC THEN CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `t:real` o
      check(fun th -> can (find_term (fun tm -> tm = `&1 / &6`)) (concl th)))
        THEN
    COND_CASES_TAC THEN REAL_ARITH_TAC;
    FIRST_X_ASSUM(MP_TAC o SPEC `t:real` o
      check(fun th -> can (find_term (fun tm -> tm = `&1 / &5`)) (concl th)))
        THEN
    COND_CASES_TAC THEN REAL_ARITH_TAC]);;

let CARLESON_THETA_TERM_BOUNDS = prove
 (`!t. &0 <= Re(fourier carleson_phi t) pow 2 /\
       Re(fourier carleson_phi t) pow 2 <= &1`,
  GEN_TAC THEN REWRITE_TAC[REAL_LE_POW_2] THEN MATCH_MP_TAC REAL_POW_1_LE THEN
  REWRITE_TAC[CARLESON_PHI_RE_BOUNDS]);;

(* 286Oa: 0 <= theta_z(y) <= 1.                                              *)
let CARLESON_THETA_BOUNDS = prove
 (`!z y. &0 <= carleson_theta z y /\ carleson_theta z y <= &1`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta] THEN
  SUBGOAL_THEN
   `!x. x IN ({ Re(fourier carleson_phi (&2 zpow (--(tile_k s)) * (y -
     tile_ymid s))) pow 2
              | s | z IN tile_Jr s /\ y IN tile_Jl s } UNION {&0})
        ==> &0 <= x /\ x <= &1`
   ASSUME_TAC THENL
   [REWRITE_TAC[IN_UNION; IN_SING; IN_ELIM_THM] THEN
    X_GEN_TAC `w:real` THEN STRIP_TAC THENL
     [ASM_MESON_TAC[CARLESON_THETA_TERM_BOUNDS]; ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_SUP THEN MAP_EVERY EXISTS_TAC [`&1`; `&0`] THEN
    REWRITE_TAC[IN_UNION; IN_SING; REAL_LE_REFL] THEN
    X_GEN_TAC `w:real` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `w:real`) THEN
    ASM_REWRITE_TAC[IN_UNION; IN_SING] THEN REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `&0` THEN
      REWRITE_TAC[IN_UNION; IN_SING];
      X_GEN_TAC `w:real` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `w:real`) THEN ASM_REWRITE_TAC[] THEN
      REAL_ARITH_TAC]]);;

(* 286Oa: theta_z(y) = 0 for y >= z (left half is strictly below the right   *)
(* half).                                                                    *)
let CARLESON_THETA_SUPPORT = prove
 (`!z y. z <= y ==> carleson_theta z y = &0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_theta] THEN
  SUBGOAL_THEN
   `{ Re(fourier carleson_phi (&2 zpow (--(tile_k s)) * (y - tile_ymid s))) pow
     2
    | s | z IN tile_Jr s /\ y IN tile_Jl s } = {}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
    X_GEN_TAC `w:real` THEN REWRITE_TAC[NOT_EXISTS_THM] THEN
    X_GEN_TAC `s:int#int#int` THEN STRIP_TAC THEN
    SUBGOAL_THEN `y:real < z` MP_TAC THENL
     [MATCH_MP_TAC TILE_JL_LT_JR THEN ASM_MESON_TAC[]; ASM_REAL_ARITH_TAC];
    REWRITE_TAC[UNION_EMPTY; SUP_SING]]);;

(* ------------------------------------------------------------------------- *)
(* R2 foundation (Fremlin 286O-a-i): the theta_z sup is achieved by a SINGLE *)
(* scale.  Any two tiles s,t both witnessing (z in Jr, y in Jl) must share   *)
(* the scale k (TILE_JL_DISJOINT: different scales with overlapping right-   *)
(* halves have disjoint left-halves, but z is in both Jr and y in both Jl)   *)
(* and, at a fixed scale, share nJ (DYHO_DISJOINT_SAMESCALE on the           *)
(* right-half                                                                *)
(* dyadic cells).  Hence all contributing tiles have the same tile_k and     *)
(* tile_ymid, so the same psi-value, and the sup collapses to that value.    *)
(* This is the HOL form of "theta_z = sum_{k in M} psi_k" (the psi_k being   *)
(* disjoint-supported, only one contributes at each y).                      *)
(* ------------------------------------------------------------------------- *)

(* Two witnessing tiles share the scale k.                                   *)
let CARLESON_THETA_SINGLE_SCALE = prove
 (`!(s:int#int#int) (t:int#int#int) z y.
     z IN tile_Jr s /\ y IN tile_Jl s /\ z IN tile_Jr t /\ y IN tile_Jl t
     ==> tile_k s = tile_k t`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`;`z:real`;
     `y:real`] THEN
  REWRITE_TAC[tile_Jr; tile_Jl; tile_k] THEN STRIP_TAC THEN
  ASM_CASES_TAC `ks:int = kt` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`ks:int`;`kt:int`;`nJs:int`;`nJt:int`] TILE_JL_DISJOINT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `z:real` THEN ASM_REWRITE_TAC[IN_INTER]; ALL_TAC] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  EXISTS_TAC `y:real` THEN ASM_REWRITE_TAC[IN_INTER]);;

(* Two right-halves at the same scale containing z share nJ.                 *)
let CARLESON_THETA_SINGLE_NJ = prove
 (`!(k:int) (nIs:int) (nJs:int) (nIt:int) (nJt:int) z.
     z IN tile_Jr (k,nIs,nJs) /\ z IN tile_Jr (k,nIt,nJt) ==> nJs = nJt`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_Jr] THEN STRIP_TAC THEN
  MP_TAC(SPECL [`k - &1:int`; `&2 * nJs + &1:int`; `&2 * nJt + &1:int`]
    DYHO_DISJOINT_SAMESCALE) THEN
  ASM_CASES_TAC `&2 * nJs + &1:int = &2 * nJt + &1` THENL
   [POP_ASSUM MP_TAC THEN INT_ARITH_TAC;
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[DISJOINT] THEN ASM SET_TAC[]]);;

(* Two witnessing tiles share tile_k AND tile_ymid (hence the same           *)
(* psi-value).                                                               *)
let CARLESON_THETA_TILE_EQ = prove
 (`!(s:int#int#int) (t:int#int#int) z y.
     z IN tile_Jr s /\ y IN tile_Jl s /\ z IN tile_Jr t /\ y IN tile_Jl t
     ==> tile_k s = tile_k t /\ tile_ymid s = tile_ymid t`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
    [`ks:int`;`nIs:int`;`nJs:int`;`kt:int`;`nIt:int`;`nJt:int`;`z:real`;
     `y:real`] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `ks:int = kt` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(ks,nIs,nJs):int#int#int`; `(kt,nIt,nJt):int#int#int`;
     `z:real`; `y:real`]
      CARLESON_THETA_SINGLE_SCALE) THEN ASM_REWRITE_TAC[tile_k]; ALL_TAC] THEN
  SUBGOAL_THEN `nJs:int = nJt` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`kt:int`; `nIs:int`; `nJs:int`; `nIt:int`; `nJt:int`;
     `z:real`]
      CARLESON_THETA_SINGLE_NJ) THEN
    ASM_REWRITE_TAC[tile_Jr] THEN DISCH_THEN MATCH_MP_TAC THEN
    UNDISCH_TAC `z IN tile_Jr (ks,nIs,nJs)` THEN
      ASM_REWRITE_TAC[tile_Jr]; ALL_TAC] THEN
  ASM_REWRITE_TAC[tile_k; tile_ymid]);;

(* theta_z(y) = the psi-value of ANY witnessing tile s0 (the sup collapses   *)
(* to a                                                                      *)
(* single term).  psi-value = Re(phihat(2^{-k}(y - ymid)))^2.                *)
let CARLESON_THETA_VALUE = prove
 (`!(s0:int#int#int) z y.
     z IN tile_Jr s0 /\ y IN tile_Jl s0
     ==> carleson_theta z y =
         Re(fourier carleson_phi (&2 zpow (--(tile_k s0)) * (y - tile_ymid
           s0))) pow 2`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_theta] THEN
  MATCH_MP_TAC SUP_UNIQUE THEN X_GEN_TAC `c:real` THEN
  REWRITE_TAC[IN_UNION; IN_SING; IN_ELIM_THM] THEN EQ_TAC THENL
   [DISCH_THEN MATCH_MP_TAC THEN DISJ1_TAC THEN
    EXISTS_TAC `s0:int#int#int` THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN X_GEN_TAC `x:real` THEN
    DISCH_THEN(DISJ_CASES_THEN2 (X_CHOOSE_THEN
      `s1:int#int#int` STRIP_ASSUME_TAC) ASSUME_TAC) THENL
     [SUBGOAL_THEN `tile_k s1 = tile_k s0 /\ tile_ymid s1 = tile_ymid s0`
       (fun th -> ASM_REWRITE_TAC[th]) THEN
      MATCH_MP_TAC CARLESON_THETA_TILE_EQ THEN
      MAP_EVERY EXISTS_TAC [`z:real`; `y:real`] THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `Re(fourier carleson_phi (&2 zpow (--(tile_k s0)) * (y -
        tile_ymid s0))) pow 2` THEN
      ASM_REWRITE_TAC[REAL_LE_POW_2]]]);;

(* Complement of CARLESON_THETA_VALUE: theta_z(y) = 0 when NO tile witnesses *)
(* (z in Jr_s, y in Jl_s). Together with CARLESON_THETA_VALUE this is the    *)
(* full                                                                      *)
(* dichotomy: theta_z(y) is either the (unique-scale) witnessing psi-value   *)
(* or 0 --                                                                   *)
(* the pointwise "theta_z = sum_k psi_k with <=1 nonzero term" of Fremlin    *)
(* 286O-a-i.                                                                 *)
let carleson_psi = new_definition
 `carleson_psi (z:real) (k:int) (y:real) =
    if (?nJ:int. z IN tile_Jr(k,&0,nJ) /\ y IN tile_Jl(k,&0,nJ))
    then Re(fourier carleson_phi
         (&2 zpow (--k) *
          (y - tile_ymid(k, &0, (@nJ. z IN tile_Jr(k,&0,nJ) /\ y IN
            tile_Jl(k,&0,nJ)))))) pow 2
    else &0`;;

(* When a scale-k tile (k,nI,nJ) witnesses (z in Jr, y in Jl), carleson_psi  *)
(* z k y equals theta_z y (both = that tile's psi-value;                     *)
(* CARLESON_THETA_VALUE + SINGLE_NJ pin the SELECT'd nJ, tile_ymid           *)
(* nI-independent).                                                          *)
let CARLESON_PSI_THETA = prove
 (`!(k:int) nI nJ z y.
     z IN tile_Jr(k,nI,nJ) /\ y IN tile_Jl(k,nI,nJ)
     ==> carleson_psi z k y = carleson_theta z y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`(k,nI,nJ):int#int#int`; `z:real`;
    `y:real`] CARLESON_THETA_VALUE) THEN
  ASM_REWRITE_TAC[tile_k] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[carleson_psi] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[tile_Jr; tile_Jl]) THEN
  SUBGOAL_THEN
    `?nJ':int. z IN dyho(k - &1)(&2 * nJ' + &1) /\ y IN dyho(k - &1)(&2 * nJ')`
   ASSUME_TAC THENL
   [EXISTS_TAC `nJ:int` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[tile_Jr; tile_Jl] THEN
  ABBREV_TAC `nJ0 = @nJ':int. z IN dyho(k - &1)(&2 * nJ' + &1) /\ y IN dyho(k -
    &1)(&2 * nJ')` THEN
  SUBGOAL_THEN
    `z IN dyho(k - &1)(&2 * nJ0 + &1) /\ y IN dyho(k - &1)(&2 * nJ0)`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "nJ0" THEN CONV_TAC SELECT_CONV THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `nJ0:int = nJ` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`k:int`; `&0:int`; `nJ0:int`; `nI:int`; `nJ:int`; `z:real`]
      CARLESON_THETA_SINGLE_NJ) THEN
    REWRITE_TAC[tile_Jr] THEN DISCH_THEN MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[tile_ymid]);;

(* carleson_psi z k y = 0 when scale k has no witnessing tile.               *)
let CARLESON_PSI_ZERO = prove
 (`!(k:int) z y.
     (!nJ:int. ~(z IN tile_Jr(k,&0,nJ) /\ y IN tile_Jl(k,&0,nJ)))
     ==> carleson_psi z k y = &0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_psi] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  POP_ASSUM(X_CHOOSE_TAC `nJ:int`) THEN ASM_MESON_TAC[]);;

(* R2c linchpin: the per-scale bumps carleson_psi z (.) y have DISJOINT      *)
(* support                                                                   *)
(* across scales -- at each y at most one scale k gives a nonzero value. If  *)
(* two                                                                       *)
(* scales k, k' both give nonzero psi, both have a witnessing tile (z in Jr, *)
(* y in                                                                      *)
(* Jl), so CARLESON_THETA_SINGLE_SCALE forces k = k'. This makes the         *)
(* scale-sum                                                                 *)
(* sum_k carleson_psi z k y a "sum with <=1 nonzero term" (= theta_z y).     *)
let CARLESON_PSI_DISJOINT = prove
 (`!z y k k'.
     ~(carleson_psi z k y = &0) /\ ~(carleson_psi z k' y = &0) ==> k = k'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_psi] THEN
  REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `nJ':int` STRIP_ASSUME_TAC o
    check (fun th -> is_exists(concl th) && can (find_term (fun t -> t =
      `k':int`)) (concl th))) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `nJ:int` STRIP_ASSUME_TAC o
    check (fun th -> is_exists(concl th))) THEN
  MP_TAC(ISPECL [`(k,&0,nJ):int#int#int`; `(k',&0,nJ'):int#int#int`; `z:real`;
    `y:real`]
    CARLESON_THETA_SINGLE_SCALE) THEN
  ASM_REWRITE_TAC[tile_k]);;

(* R2c per-term dichotomy: each carleson_psi z k y is EITHER 0 OR the full   *)
(* theta_z y.                                                                *)
(* (Nonzero => the if-guard's witnessing tile exists => CARLESON_PSI_THETA.) *)
(* With                                                                      *)
(* CARLESON_PSI_DISJOINT (<=1 nonzero) this shows every finite partial sum   *)
(* of the                                                                    *)
(* carleson_psi z (.) y is either 0 or theta_z y, hence bounded by theta_z y *)
(* <= 1.                                                                     *)
let CARLESON_PSI_CASES = prove
 (`!z k y. carleson_psi z k y = &0 \/ carleson_psi z k y = carleson_theta z y`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `carleson_psi z k y = &0` THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISJ2_TAC THEN
  FIRST_X_ASSUM MP_TAC THEN REWRITE_TAC[carleson_psi] THEN
  COND_CASES_TAC THEN REWRITE_TAC[] THEN
  POP_ASSUM(X_CHOOSE_THEN `nJ:int` STRIP_ASSUME_TAC) THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`k:int`; `&0:int`; `nJ:int`; `z:real`;
    `y:real`] CARLESON_PSI_THETA) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[carleson_psi] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

(* Abstract: the sum of a finite family whose values lie in {0, v} and which *)
(* has                                                                       *)
(* AT MOST ONE nonzero term is either 0 or v. (Restrict to the support -- a  *)
(* set of                                                                    *)
(* cardinality <= 1 -- via SUM_SUPPORT; empty support => 0, singleton {a} => *)
(* f a=v.)                                                                   *)
let SUM_ATMOST_ONE_VALUE = prove
 (`!(f:A->real) v s. FINITE s /\
     (!i. i IN s ==> f i = &0 \/ f i = v) /\
     (!i j. i IN s /\ j IN s /\ ~(f i = &0) /\ ~(f j = &0) ==> i = j)
     ==> sum s f = &0 \/ sum s f = v`,
  REPEAT STRIP_TAC THEN
  ONCE_REWRITE_TAC[GSYM SUM_SUPPORT] THEN
  REWRITE_TAC[support; NEUTRAL_REAL_ADD] THEN
  ASM_CASES_TAC `{x:A | x IN s /\ ~(f x = &0)} = {}` THENL
   [ASM_REWRITE_TAC[SUM_CLAUSES]; ALL_TAC] THEN
  DISJ2_TAC THEN
  SUBGOAL_THEN
    `?a:A. {x:A | x IN s /\ ~(f x = &0)} = {a}` STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN EXISTS_TAC `x:A` THEN
    REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_SING] THEN
    X_GEN_TAC `w:A` THEN EQ_TAC THENL
     [STRIP_TAC THEN FIRST_X_ASSUM(MATCH_MP_TAC o
        check(fun th -> is_forall(concl th))) THEN ASM_MESON_TAC[];
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ASM_REWRITE_TAC[SUM_SING] THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP
    (SET_RULE `{x | x IN s /\ ~(f x = &0)} = {a} ==> a IN s /\ ~(f a = &0)`))
      THEN
  ASM_MESON_TAC[]);;

(* Every finite partial sum of the per-scale bumps carleson_psi z (.) y is 0 *)
(* or                                                                        *)
(* theta_z y (SUM_ATMOST_ONE_VALUE with CARLESON_PSI_CASES [each 0 or        *)
(* theta_z] +                                                                *)
(* CARLESON_PSI_DISJOINT [<=1 nonzero]). Hence bounded by theta_z y <= 1 --  *)
(* the                                                                       *)
(* pointwise value + DCT domination for the R2c/d scale-sum.                 *)
let CARLESON_PSI_PARTIAL = prove
 (`!z y (s:int->bool). FINITE s
     ==> sum s (\k. carleson_psi z k y) = &0 \/
         sum s (\k. carleson_psi z k y) = carleson_theta z y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\k:int. carleson_psi z k y`; `carleson_theta z y`;
    `s:int->bool`]
    SUM_ATMOST_ONE_VALUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [X_GEN_TAC `k:int` THEN DISCH_TAC THEN REWRITE_TAC[CARLESON_PSI_CASES];
    MAP_EVERY X_GEN_TAC [`k:int`; `k':int`] THEN STRIP_TAC THEN
    MATCH_MP_TAC CARLESON_PSI_DISJOINT THEN
    MAP_EVERY EXISTS_TAC [`z:real`; `y:real`] THEN ASM_REWRITE_TAC[]]);;

(* When theta_z y <> 0 the sup-set is nonempty, so some tile witnesses (z in *)
(* Jr, y in Jl); its scale k gives carleson_psi z k y = theta_z y (nonzero). *)
let CARLESON_THETA_WITNESS = prove
 (`!z y. ~(carleson_theta z y = &0)
         ==> ?k. carleson_psi z k y = carleson_theta z y /\ ~(carleson_psi z k
           y = &0)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o CONV_RULE(RAND_CONV(REWRITE_CONV[carleson_theta]))) THEN
  ASM_CASES_TAC `{ Re(fourier carleson_phi (&2 zpow (--(tile_k s)) * (y -
    tile_ymid s))) pow 2
    | s | z IN tile_Jr s /\ y IN tile_Jl s } = {}` THENL
   [ASM_REWRITE_TAC[UNION_EMPTY; SUP_SING]; ALL_TAC] THEN
  POP_ASSUM(MP_TAC o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:real` (X_CHOOSE_THEN
    `s0:int#int#int` STRIP_ASSUME_TAC)) THEN
  DISCH_TAC THEN
  MP_TAC(ISPEC `s0:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `k0:int` (X_CHOOSE_THEN
    `p0:int#int` SUBST_ALL_TAC)) THEN
  MP_TAC(ISPEC `p0:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `nI0:int` (X_CHOOSE_THEN
    `nJ0:int` SUBST_ALL_TAC)) THEN
  EXISTS_TAC `k0:int` THEN
  SUBGOAL_THEN
    `carleson_psi z k0 y =
     carleson_theta z y` (fun th -> ASM_REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`k0:int`; `nI0:int`; `nJ0:int`; `z:real`;
    `y:real`] CARLESON_PSI_THETA) THEN
  ASM_REWRITE_TAC[tile_k]);;

(* A finite partial sum with a single distinguished nonzero term k0 equals   *)
(* that term (all others vanish by CARLESON_PSI_DISJOINT; SUM_SUPERSET onto  *)
(* {k0}).                                                                    *)
let CARLESON_PSI_SUM_SINGLE = prove
 (`!z y (s:int->bool) k0. FINITE s /\ k0 IN s /\ ~(carleson_psi z k0 y = &0)
     ==> sum s (\k. carleson_psi z k y) = carleson_psi z k0 y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\k:int. carleson_psi z k y`; `{k0:int}`;
    `s:int->bool`] SUM_SUPERSET) THEN
  REWRITE_TAC[SUM_SING] THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[SING_SUBSET; IN_SING] THEN
    X_GEN_TAC `k:int` THEN STRIP_TAC THEN REWRITE_TAC[] THEN
    ASM_CASES_TAC `carleson_psi z k y = &0` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `k:int = k0` (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC CARLESON_PSI_DISJOINT THEN
    MAP_EVERY EXISTS_TAC [`z:real`; `y:real`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[]]);;

(* R2c POINTWISE CONVERGENCE (Fremlin 286O-a-i "theta_z = sum_k psi_k"): the *)
(* finite                                                                    *)
(* scale-partial-sums converge to theta_z y. Eventually constant: if theta_z *)
(* y = 0                                                                     *)
(* all sums are 0 (PSI_PARTIAL); else the unique witnessing scale k0         *)
(* (CARLESON_THETA_                                                          *)
(* WITNESS) satisfies abs k0 <= K for K large, and the sum picks up exactly  *)
(* that term                                                                 *)
(* (CARLESON_PSI_SUM_SINGLE) = theta_z y.  REALLIM_EVENTUALLY.               *)
let CARLESON_PSI_SUM_LIMIT = prove
 (`!z y. ((\K. sum {k:int | abs k <= &K} (\k. carleson_psi z k y))
          ---> carleson_theta z y) sequentially`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC REALLIM_EVENTUALLY THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN
  ASM_CASES_TAC `carleson_theta z y = &0` THENL
   [EXISTS_TAC `0` THEN X_GEN_TAC `K:num` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`z:real`; `y:real`;
      `{k:int | abs k <= &K}`] CARLESON_PSI_PARTIAL) THEN
    ASM_REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP CARLESON_THETA_WITNESS) THEN
  DISCH_THEN(X_CHOOSE_THEN `k0:int` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `num_of_int(abs k0)` THEN X_GEN_TAC `K:num` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`z:real`; `y:real`; `{k:int | abs k <= &K}`;
    `k0:int`] CARLESON_PSI_SUM_SINGLE) THEN
  ASM_REWRITE_TAC[CFOURIER_INDEX_FINITE; IN_ELIM_THM] THEN
  ANTS_TAC THENL
   [SUBGOAL_THEN `abs k0 = &(num_of_int(abs k0))` SUBST1_TAC THENL
     [MATCH_MP_TAC(GSYM INT_OF_NUM_OF_INT) THEN INT_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[INT_OF_NUM_LE] THEN ASM_ARITH_TAC;
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286Q(a,b) (Fremlin mt286.tex 2361-2417): the affine-reparametrised bump   *)
(* theta'_{z alpha beta}(y) = theta_{alpha z + beta}(alpha y + beta).  Its   *)
(* elementary properties (values in [0,1]; zero for y >= z when alpha>0)     *)
(* follow                                                                    *)
(* directly from those of carleson_theta.  [The 286Q(c) kernel bound         *)
(* 2pi|(h-hat x theta')^v| <= D_{1/alpha} A M_beta D_alpha h and the Borel   *)
(* measurability (286Qa) are deferred with the tile operator A / 286O(b).]   *)
(* ========================================================================= *)
let carleson_theta' = new_definition
 `carleson_theta' z alpha beta y =
    carleson_theta (alpha * z + beta) (alpha * y + beta)`;;

let CARLESON_THETA'_BOUNDS = prove
 (`!z alpha beta y. &0 <= carleson_theta' z alpha beta y /\
                    carleson_theta' z alpha beta y <= &1`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta'; CARLESON_THETA_BOUNDS]);;

let CARLESON_THETA'_SUPPORT = prove
 (`!z alpha beta y. &0 < alpha /\ z <= y ==> carleson_theta' z alpha beta y =
   &0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  MATCH_MP_TAC CARLESON_THETA_SUPPORT THEN
  MATCH_MP_TAC REAL_LE_ADD2 THEN REWRITE_TAC[REAL_LE_REFL] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC);;

(* ========================================================================= *)
(* 286R-e: dyadic scale-invariance theta_{2z}(2y) = theta_z(y) (Fremlin      *)
(* mt286.tex 2567-2607). Doubling z, y AND the dyadic scale k together       *)
(* leaves                                                                    *)
(* both tile membership (Jr/Jl) and the phihat window value 2^{-k}(y-ymid)   *)
(* invariant, so the sup-of-windows theta is unchanged. This is the building *)
(* block for 286R-f (g(2a,.)=g(a,.)) toward the averaged bump thetatilde.    *)
(* ========================================================================= *)

(* &2 zpow k = &2 * &2 zpow (k-1).                                           *)
let ZPOW2_PRED = prove
 (`!k:int. &2 zpow k = &2 * &2 zpow (k - &1)`,
  GEN_TAC THEN
  SUBGOAL_THEN
    `k:int = (k - &1) + &1` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
    [th]) THENL
   [INT_ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
  REWRITE_TAC[REAL_ZPOW_1] THEN REAL_ARITH_TAC);;

(* 2x in dyho(k+1)n <=> x in dyho k n.                                       *)
let CARLESON_DYHO_SCALE2 = prove
 (`!k n x. (&2 * x) IN dyho (k + &1) n <=> x IN dyho k n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN
  SUBGOAL_THEN
    `&0 < &2 zpow k /\ &2 zpow (k + &1) =
     &2 * &2 zpow k` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
      SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
      REWRITE_TAC[REAL_ZPOW_1] THEN REAL_ARITH_TAC]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC);;

(* tile Jr/Jl membership scaling (k+1 form), via DYHO_SCALE2 with scale-args *)
(* normalized.                                                               *)
let CARLESON_TILE_JR_SCALE2 = prove
 (`!k nI nJ z. (&2 * z) IN tile_Jr(k + &1,nI,nJ) <=> z IN tile_Jr(k,nI,nJ)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_Jr] THEN
  SUBGOAL_THEN
    `dyho ((k + &1) - &1) (&2 * nJ + &1) = dyho ((k - &1) + &1) (&2 * nJ + &1)`
    SUBST1_TAC THENL
   [AP_THM_TAC THEN AP_TERM_TAC THEN INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[CARLESON_DYHO_SCALE2]);;

let CARLESON_TILE_JL_SCALE2 = prove
 (`!k nI nJ y. (&2 * y) IN tile_Jl(k + &1,nI,nJ) <=> y IN tile_Jl(k,nI,nJ)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_Jl] THEN
  SUBGOAL_THEN
    `dyho ((k + &1) - &1) (&2 * nJ) = dyho ((k - &1) + &1) (&2 * nJ)`
    SUBST1_TAC THENL
   [AP_THM_TAC THEN AP_TERM_TAC THEN INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[CARLESON_DYHO_SCALE2]);;

(* PRED-indexed forms (2z in Jr(k,..) <=> z in Jr(k-1,..)) for the bijection *)
(* forward leg.                                                              *)
let CARLESON_TILE_JR_SCALE2P = prove
 (`!k nI nJ z. (&2 * z) IN tile_Jr(k,nI,nJ) <=> z IN tile_Jr(k - &1,nI,nJ)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
    `tile_Jr(k,nI,nJ) = tile_Jr((k - &1) + &1,nI,nJ)` SUBST1_TAC THENL
   [AP_TERM_TAC THEN REWRITE_TAC[PAIR_EQ] THEN INT_ARITH_TAC;
    REWRITE_TAC[CARLESON_TILE_JR_SCALE2]]);;

let CARLESON_TILE_JL_SCALE2P = prove
 (`!k nI nJ y. (&2 * y) IN tile_Jl(k,nI,nJ) <=> y IN tile_Jl(k - &1,nI,nJ)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
    `tile_Jl(k,nI,nJ) = tile_Jl((k - &1) + &1,nI,nJ)` SUBST1_TAC THENL
   [AP_TERM_TAC THEN REWRITE_TAC[PAIR_EQ] THEN INT_ARITH_TAC;
    REWRITE_TAC[CARLESON_TILE_JL_SCALE2]]);;

(* dyho_mid k n = 2 * dyho_mid (k-1) n.                                      *)
let DYHO_MID_PRED = prove
 (`!k n. dyho_mid k n = &2 * dyho_mid (k - &1) n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho_mid] THEN
  SUBGOAL_THEN `&2 zpow k = &2 * &2 zpow (k - &1)` SUBST1_TAC THENL
   [SUBGOAL_THEN
     `k:int = (k - &1) + &1` (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
     [th]) THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
    REWRITE_TAC[REAL_ZPOW_1] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* &2 zpow(--k) = inv 2 * &2 zpow(--(k-1)).                                  *)
let ZPOW_NEG_PRED = prove
 (`!k:int. &2 zpow (--k) = inv(&2) * &2 zpow (--(k - &1))`,
  GEN_TAC THEN
  SUBGOAL_THEN `--k:int = --(k - &1) + (-- &1)` SUBST1_TAC THENL
   [INT_ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
  REWRITE_TAC[REAL_ZPOW_NEG; REAL_ZPOW_1] THEN REAL_ARITH_TAC);;

let ZPOW_NEG_SUCC = prove
 (`!k:int. &2 zpow (--(k + &1)) = inv(&2) * &2 zpow (--k)`,
  GEN_TAC THEN SUBGOAL_THEN `--(k + &1):int = --k + (-- &1)` SUBST1_TAC THENL
   [INT_ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
  REWRITE_TAC[REAL_ZPOW_NEG; REAL_ZPOW_1] THEN REAL_ARITH_TAC);;

(* phihat-argument scale-invariance (PRED form): value@(2y,scale k) =        *)
(* value@(y,scale k-1).                                                      *)
let CARLESON_TILE_ARG_SCALE2P = prove
 (`!k nI nJ y.
     &2 zpow (--(tile_k(k,nI,nJ))) * (&2 * y - tile_ymid(k,nI,nJ))
     = &2 zpow (--(tile_k(k - &1,nI,nJ))) * (y - tile_ymid(k - &1,nI,nJ))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_k; tile_ymid] THEN
  GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV) [DYHO_MID_PRED] THEN
  GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [ZPOW_NEG_PRED] THEN
  CONV_TAC REAL_FIELD);;

(* +1 form of ARG (backward leg): value@(2y,scale k+1) = value@(y,scale k).  *)
let CARLESON_TILE_ARG_SCALE2 = prove
 (`!k nI nJ y.
     &2 zpow (--(tile_k(k + &1,nI,nJ))) * (&2 * y - tile_ymid(k + &1,nI,nJ))
     = &2 zpow (--(tile_k(k,nI,nJ))) * (y - tile_ymid(k,nI,nJ))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_k; tile_ymid] THEN
  SUBGOAL_THEN
    `dyho_mid ((k + &1) - &1) (&2 * nJ) =
     dyho_mid k (&2 * nJ)` SUBST1_TAC THENL
   [AP_THM_TAC THEN AP_TERM_TAC THEN INT_ARITH_TAC; ALL_TAC] THEN
  GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV) [DYHO_MID_PRED] THEN
  GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [ZPOW_NEG_SUCC] THEN
  CONV_TAC REAL_FIELD);;

(* 286R-e MAIN: theta_{2z}(2y) = theta_z(y). Sup-sets coincide via           *)
(* (k,nI,nJ)<->(k+1,nI,nJ).                                                  *)
let CARLESON_THETA_SCALE2 = prove
 (`!z y. carleson_theta (&2 * z) (&2 * y) = carleson_theta z y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta] THEN
  AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN X_GEN_TAC `c:real` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:int#int#int` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `k:int` (X_CHOOSE_THEN
      `r:int#int` SUBST_ALL_TAC)) THEN
    MP_TAC(ISPEC `r:int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `nI:int` (X_CHOOSE_THEN
      `nJ:int` SUBST_ALL_TAC)) THEN
    EXISTS_TAC `(k - &1, nI, nJ):int#int#int` THEN
    RULE_ASSUM_TAC(REWRITE_RULE[CARLESON_TILE_JR_SCALE2P;
      CARLESON_TILE_JL_SCALE2P]) THEN
    ASM_REWRITE_TAC[GSYM CARLESON_TILE_ARG_SCALE2P];
    DISCH_THEN(X_CHOOSE_THEN `s:int#int#int` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `k:int` (X_CHOOSE_THEN
      `r:int#int` SUBST_ALL_TAC)) THEN
    MP_TAC(ISPEC `r:int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `nI:int` (X_CHOOSE_THEN
      `nJ:int` SUBST_ALL_TAC)) THEN
    EXISTS_TAC `(k + &1, nI, nJ):int#int#int` THEN
    ASM_REWRITE_TAC[CARLESON_TILE_JR_SCALE2; CARLESON_TILE_JL_SCALE2] THEN
    REWRITE_TAC[CARLESON_TILE_ARG_SCALE2] THEN ASM_REWRITE_TAC[]]);;

(* 286R-e COROLLARY: theta'_{z,2a,2b}(y) = theta'_{z,a,b}(y).                *)
let CARLESON_THETA'_SCALE2 = prove
 (`!z a b y. carleson_theta' z (&2 * a) (&2 * b) y = carleson_theta' z a b y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  SUBGOAL_THEN `(&2 * a) * z + &2 * b = &2 * (a * z + b) /\
                (&2 * a) * y + &2 * b = &2 * (a * y + b)`
    (fun th -> REWRITE_TAC[th]) THENL
   [CONJ_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[CARLESON_THETA_SCALE2]);;

(* ========================================================================= *)
(* 286R-b-i FOUNDATIONS (Fremlin mt286.tex 2437-2488): the beta-periodicity  *)
(* theta'_{z,a,beta+2^l}(y) = theta'_{z,a,beta}(y). Adding 2^l to beta       *)
(* shifts                                                                    *)
(* the witnessing tile's nJ-index by q = 2^{l-k} (an integer since k <= l),  *)
(* leaving both membership (Jr/Jl) and the phihat window value invariant.    *)
(* These are the dyadic-shift + window-support bricks; the k<=l gate (from   *)
(* the                                                                       *)
(* phihat support) and the theta-shift assembly build on them.               *)
(* ========================================================================= *)

(* H1: dyho cell translation by c widths. x + c*2^k in dyho k (n+c) <=> x in *)
(* dyho k n.                                                                 *)
let DYHO_SHIFT = prove
 (`!k n c x. (x + real_of_int c * &2 zpow k) IN dyho k (n + c) <=> x IN dyho k
   n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN
  REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES] THEN
  MP_TAC(ISPECL [`&2`; `k:int`] REAL_ZPOW_LT) THEN
    REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
  DISCH_TAC THEN REAL_ARITH_TAC);;

(* H2: dyho_mid translation.                                                 *)
let DYHO_MID_SHIFT = prove
 (`!k n c. dyho_mid k (n + c) = dyho_mid k n + real_of_int c * &2 zpow k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho_mid] THEN
  REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES] THEN REAL_ARITH_TAC);;

(* H3: tile_Jr under nJ-shift by q. Z + 2q*2^(k-1) in Jr(k,nI,nJ+q) <=> Z in *)
(* Jr(k,nI,nJ).                                                              *)
let TILE_JR_NJSHIFT = prove
 (`!k nI nJ q Z. (Z + real_of_int(&2 * q) * &2 zpow (k - &1)) IN
   tile_Jr(k,nI,nJ + q)
                 <=> Z IN tile_Jr(k,nI,nJ)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_Jr] THEN
  SUBGOAL_THEN
    `dyho (k - &1) (&2 * (nJ + q) + &1) =
     dyho (k - &1) ((&2 * nJ + &1) + &2 * q)`
    SUBST1_TAC THENL
   [AP_TERM_TAC THEN INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[DYHO_SHIFT]);;

let TILE_JL_NJSHIFT = prove
 (`!k nI nJ q Y. (Y + real_of_int(&2 * q) * &2 zpow (k - &1)) IN
   tile_Jl(k,nI,nJ + q)
                 <=> Y IN tile_Jl(k,nI,nJ)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_Jl] THEN
  SUBGOAL_THEN
    `dyho (k - &1) (&2 * (nJ + q)) = dyho (k - &1) ((&2 * nJ) + &2 * q)`
    SUBST1_TAC THENL
   [AP_TERM_TAC THEN INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[DYHO_SHIFT]);;

(* H4: tile_ymid under nJ-shift.                                             *)
let TILE_YMID_NJSHIFT = prove
 (`!k nI nJ q. tile_ymid(k,nI,nJ + q)
               = tile_ymid(k,nI,nJ) + real_of_int(&2 * q) * &2 zpow (k - &1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_ymid] THEN
  SUBGOAL_THEN
    `dyho_mid (k - &1) (&2 * (nJ + q)) =
     dyho_mid (k - &1) ((&2 * nJ) + &2 * q)`
    SUBST1_TAC THENL
   [AP_TERM_TAC THEN INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[DYHO_MID_SHIFT]);;

(* H5: for k <= L, the nJ-shift q = 2^(L-k) gives point-shift 2q*2^(k-1) =   *)
(* 2^L.                                                                      *)
let REAL_OF_INT_2POW = prove
 (`!n:num. real_of_int((&2:int) pow n) = &2 pow n`,
  GEN_TAC THEN REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES] THEN
    REWRITE_TAC[REAL_OF_INT_CLAUSES]);;

let REAL_ZPOW_ADD_2 = prove
 (`!m n:int. &2 zpow (m + n) = &2 zpow m * &2 zpow n`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC REAL_ZPOW_ADD THEN REAL_ARITH_TAC);;

let ZPOW_SHIFT_EXISTS = prove
 (`!k L:int. k <= L
   ==> ?q:int. real_of_int(&2 * q) * &2 zpow (k - &1) = &2 zpow L`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `n = num_of_int(L - k)` THEN
  SUBGOAL_THEN `(&n:int) = L - k` ASSUME_TAC THENL
   [EXPAND_TAC "n" THEN MATCH_MP_TAC INT_OF_NUM_OF_INT THEN
     ASM_INT_ARITH_TAC; ALL_TAC] THEN
  EXISTS_TAC `(&2:int) pow n` THEN
  REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES; REAL_OF_INT_2POW] THEN
  SUBGOAL_THEN `&2 * &2 pow n = &2 pow (n + 1)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_POW_ADD; REAL_POW_1] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_ZPOW_NUM] THEN
  REWRITE_TAC[GSYM REAL_ZPOW_ADD_2] THEN
  AP_TERM_TAC THEN
  REWRITE_TAC[GSYM INT_OF_NUM_ADD] THEN ASM_INT_ARITH_TAC);;

(* the phihat window value is shift-invariant under the (nJ+q,               *)
(* point+2q*2^(k-1)) move.                                                   *)
let TILE_ARG_NJSHIFT = prove
 (`!k nI nJ q Y.
     &2 zpow (--(tile_k(k,nI,nJ + q))) * ((Y + real_of_int(&2 * q) * &2 zpow (k
       - &1)) - tile_ymid(k,nI,nJ + q))
     = &2 zpow (--(tile_k(k,nI,nJ))) * (Y - tile_ymid(k,nI,nJ))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_k] THEN
  REWRITE_TAC[TILE_YMID_NJSHIFT] THEN
  AP_TERM_TAC THEN REAL_ARITH_TAC);;

(* H8a: window nonzero => phihat argument in [-1/5,1/5] (contrapositive of   *)
(* PHI support).                                                             *)
let CARLESON_WINDOW_SUPP = prove
 (`!t. ~(Re(fourier carleson_phi t) pow 2 = &0) ==> abs t <= &1 / &5`,
  GEN_TAC THEN GEN_REWRITE_TAC I [GSYM CONTRAPOS_THM] THEN
  REWRITE_TAC[REAL_NOT_LE] THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `fourier carleson_phi t = Cx(&0)` (fun th -> REWRITE_TAC[th; RE_CX]) THENL
   [MATCH_MP_TAC CARLESON_PHI_FHAT_SUPPORT THEN ASM_REAL_ARITH_TAC;
    CONV_TAC REAL_RING]);;

(* ========================================================================= *)
(* 286R-b-i: the k<=l gate (Fremlin mt286.tex 2451-2457). A nonzero window   *)
(* at                                                                        *)
(* (Z,Y) with witness tile (k,nI,nJ) forces 2^k <= 20(Z-Y): Z in Jr gives    *)
(* Z >= (2nJ+1)2^(k-1); window!=0 gives |2^{-k}(Y-ymid)|<=1/5 so Y <=        *)
(* 2^k(nJ+9/20); hence Z-Y >= 2^k/20. Then l = floor(log2(20 a(z-y))) bounds *)
(* every such k (CARLESON_GATE_L_EXISTS), so q = 2^{l-k} in                  *)
(* ZPOW_SHIFT_EXISTS                                                         *)
(* is a genuine integer.                                                     *)
(* ========================================================================= *)

(* the pure real-arithmetic 1/20-gap core.                                   *)
let CARLESON_GATE_ARITH = prove
 (`!w m Z Y:real. &0 < w /\ (&2 * m + &1) * w <= Z /\
                  abs(Y - (&2 * m + &1 / &2) * w) <= (&2 * w) / &5
   ==> &2 * w <= &20 * (Z - Y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `Y <= (&2 * m + &1 / &2) * w + (&2 * w) / &5` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN ASM_REAL_ARITH_TAC);;

(* 2^(-k) = inv(2*2^(k-1)).                                                  *)
let ZPOW_NEG_HALF = prove
 (`!k:int. &2 zpow (--k) = inv(&2 * &2 zpow (k - &1))`,
  GEN_TAC THEN REWRITE_TAC[REAL_ZPOW_NEG] THEN AP_TERM_TAC THEN
  GEN_REWRITE_TAC (LAND_CONV) [ZPOW2_PRED] THEN REFL_TAC);;

(* inv(2w)*p <= 1/5 /\ 0<w ==> p <= 2w/5.                                    *)
let WSUPP_DIV = prove
 (`!w p:real. &0 < w /\ inv(&2 * w) * p <= &1 / &5 ==> p <= (&2 * w) / &5`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 * w` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:real`; `&1 / &5`; `&2 * w`] REAL_LE_LDIV_EQ) THEN
    ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `p / (&2 * w) = inv(&2 * w) * p` SUBST1_TAC THENL
   [REWRITE_TAC[real_div] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC);;

(* window nonzero => |Y - ymid| <= 2*2^(k-1)/5 (= 2^k/5).                    *)
let CARLESON_WSUPP_ABS = prove
 (`!k nI nJ Y.
     ~(Re(fourier carleson_phi (&2 zpow (--(tile_k(k,nI,nJ))) * (Y -
       tile_ymid(k,nI,nJ)))) pow 2 = &0) /\
     &0 < &2 zpow (k - &1)
     ==> abs(Y - (&2 * real_of_int nJ + &1 / &2) * &2 zpow (k - &1)) <= (&2 *
       &2 zpow (k - &1)) / &5`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP CARLESON_WINDOW_SUPP) THEN
  REWRITE_TAC[tile_k; tile_ymid; dyho_mid; int_add_th; int_mul_th;
    int_of_num_th] THEN
  REWRITE_TAC[ZPOW_NEG_HALF; REAL_ABS_MUL; REAL_ABS_INV] THEN
  SUBGOAL_THEN `abs(&2) = &2 /\ abs(&2 zpow (k - &1)) = &2 zpow (k - &1)`
    (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[REAL_ABS_NUM] THEN REWRITE_TAC[REAL_ABS_REFL] THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_TAC THEN MATCH_MP_TAC WSUPP_DIV THEN ASM_REWRITE_TAC[] THEN
  ONCE_REWRITE_TAC[REAL_ABS_SUB] THEN ASM_REWRITE_TAC[]);;

(* H8-tile: nonzero window at (Z,Y) with witness (k,nI,nJ) => 2^k <=         *)
(* 20(Z-Y).                                                                  *)
let CARLESON_TILE_GATE = prove
 (`!k nI nJ Z Y.
     Z IN tile_Jr(k,nI,nJ) /\
     ~(Re(fourier carleson_phi (&2 zpow (--(tile_k(k,nI,nJ))) * (Y -
       tile_ymid(k,nI,nJ)))) pow 2 = &0)
     ==> &2 zpow k <= &20 * (Z - Y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 zpow (k - &1)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  GEN_REWRITE_TAC (RATOR_CONV o RAND_CONV) [ZPOW2_PRED] THEN
  MATCH_MP_TAC CARLESON_GATE_ARITH THEN EXISTS_TAC `real_of_int nJ` THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [UNDISCH_TAC `Z IN tile_Jr(k,nI,nJ)` THEN
    REWRITE_TAC[tile_Jr; dyho; IN_ELIM_THM; int_add_th; int_mul_th;
      int_of_num_th] THEN
    STRIP_TAC THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC CARLESON_WSUPP_ABS THEN EXISTS_TAC `nI:int` THEN
      ASM_REWRITE_TAC[]]);;

(* zpow strict monotonicity contrapositive: 2^k < 2^m ==> k < m.             *)
let ZPOW2_LT_MONO = prove
 (`!k m:int. &2 zpow k < &2 zpow m ==> k < m`,
  REPEAT GEN_TAC THEN GEN_REWRITE_TAC I [GSYM CONTRAPOS_THM] THEN
  REWRITE_TAC[INT_NOT_LT; REAL_NOT_LT] THEN DISCH_TAC THEN
  MATCH_MP_TAC ZPOW2_MONOE THEN ASM_REWRITE_TAC[]);;

(* H8-L: the l-construction. For X>0 there is an integer L bounding every k  *)
(* with                                                                      *)
(* 2^k <= X. (l = floor(log2 X); any L with X < 2^(L+1) works, via           *)
(* REAL_ARCH_SIMPLE                                                          *)
(* + N < 2^N.)                                                               *)
let CARLESON_GATE_L_EXISTS = prove
 (`!X:real. &0 < X ==> ?L:int. !k:int. &2 zpow k <= X ==> k <= L`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `X:real` REAL_ARCH_SIMPLE) THEN
  DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN
  EXISTS_TAC `&N:int` THEN X_GEN_TAC `k:int` THEN DISCH_TAC THEN
  REWRITE_TAC[INT_LE_LT] THEN DISJ1_TAC THEN
  MATCH_MP_TAC ZPOW2_LT_MONO THEN
  REWRITE_TAC[REAL_ZPOW_NUM] THEN
  MP_TAC(SPEC `N:num` LT_POW2_REFL) THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_LT; REAL_OF_NUM_POW] THEN
  ASM_REAL_ARITH_TAC);;

(* ========================================================================= *)
(* 286R-b-i H7 core: the gated theta-shift value-transfer. If theta(Z)(Y)<>0 *)
(* and every nonzero-window witness of (Z,Y) has scale k <= L, then adding   *)
(* 2^L                                                                       *)
(* to both points preserves theta: theta(Z+2^L)(Y+2^L) = theta(Z)(Y).  The   *)
(* witness tile (k,nI,nJ) [k<=L via the gate] shifts to (k,nI,nJ+q),         *)
(* q=2^{l-k},                                                                *)
(* which witnesses (Z+2^L,Y+2^L) with the SAME phihat window value.          *)
(* ========================================================================= *)

(* theta Z Y <> 0 yields an actual witnessing tile with nonzero window       *)
(* value. (Any witness's value = theta Z Y by CARLESON_THETA_VALUE, hence <> *)
(* 0.)                                                                       *)
let THETA_TILE_WITNESS = prove
 (`!Z Y. ~(carleson_theta Z Y = &0)
   ==> ?k nI nJ. Z IN tile_Jr(k,nI,nJ) /\ Y IN tile_Jl(k,nI,nJ) /\
                 ~(Re(fourier carleson_phi (&2 zpow (--(tile_k(k,nI,nJ))) * (Y
                   - tile_ymid(k,nI,nJ)))) pow 2 = &0)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o CONV_RULE(RAND_CONV(REWRITE_CONV[carleson_theta]))) THEN
  ASM_CASES_TAC `{ Re(fourier carleson_phi (&2 zpow (--(tile_k s)) * (Y -
    tile_ymid s))) pow 2
    | s | Z IN tile_Jr s /\ Y IN tile_Jl s } = {}` THENL
   [ASM_REWRITE_TAC[UNION_EMPTY; SUP_SING]; ALL_TAC] THEN
  POP_ASSUM(MP_TAC o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:real` (X_CHOOSE_THEN
    `s0:int#int#int` STRIP_ASSUME_TAC)) THEN DISCH_TAC THEN
  MP_TAC(ISPEC `s0:int#int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `k0:int` (X_CHOOSE_THEN
    `p0:int#int` SUBST_ALL_TAC)) THEN
  MP_TAC(ISPEC `p0:int#int` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `nI0:int` (X_CHOOSE_THEN
    `nJ0:int` SUBST_ALL_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`k0:int`;`nI0:int`;`nJ0:int`] THEN
    ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`(k0,nI0,nJ0):int#int#int`; `Z:real`;
    `Y:real`] CARLESON_THETA_VALUE) THEN
  ASM_REWRITE_TAC[tile_k] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    ASM_REWRITE_TAC[]);;

(* forward value-transfer: theta(Z)(Y)<>0 + (nonzero witness scale <= L) ==> *)
(* theta(Z+2^L)(Y+2^L) = theta(Z)(Y).                                        *)
let THETA_SHIFT_TRANSFER = prove
 (`!Z Y L.
     ~(carleson_theta Z Y = &0) /\
     (!k nI nJ. Z IN tile_Jr(k,nI,nJ) /\ Y IN tile_Jl(k,nI,nJ) /\
                ~(Re(fourier carleson_phi (&2 zpow (--(tile_k(k,nI,nJ))) * (Y -
                  tile_ymid(k,nI,nJ)))) pow 2 = &0)
                ==> k <= L)
     ==> carleson_theta (Z + &2 zpow L) (Y + &2 zpow L) = carleson_theta Z Y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP THETA_TILE_WITNESS) THEN
  DISCH_THEN(X_CHOOSE_THEN `k:int` (X_CHOOSE_THEN `nI:int` (X_CHOOSE_THEN
    `nJ:int` STRIP_ASSUME_TAC))) THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`k:int`;`nI:int`;`nJ:int`]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`k:int`;`L:int`] ZPOW_SHIFT_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `q:int`) THEN
  SUBGOAL_THEN
   `carleson_theta Z Y =
    Re(fourier carleson_phi (&2 zpow (--k) * (Y - tile_ymid(k,nI,nJ)))) pow 2`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`(k,nI,nJ):int#int#int`; `Z:real`;
     `Y:real`] CARLESON_THETA_VALUE) THEN
    ASM_REWRITE_TAC[tile_k]; ALL_TAC] THEN
  SUBGOAL_THEN
   `carleson_theta (Z + &2 zpow L) (Y + &2 zpow L) =
    Re(fourier carleson_phi (&2 zpow (--k) * ((Y + &2 zpow L) -
      tile_ymid(k,nI,nJ + q)))) pow 2`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`(k,nI,nJ + q):int#int#int`; `Z + &2 zpow L`;
     `Y + &2 zpow L`] CARLESON_THETA_VALUE) THEN
    REWRITE_TAC[tile_k] THEN DISCH_THEN MATCH_MP_TAC THEN
    MP_TAC(SPECL [`k:int`;`nI:int`;`nJ:int`;`q:int`;`Z:real`] TILE_JR_NJSHIFT)
      THEN
    MP_TAC(SPECL [`k:int`;`nI:int`;`nJ:int`;`q:int`;`Y:real`] TILE_JL_NJSHIFT)
      THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  MP_TAC(SPECL [`k:int`;`nI:int`;`nJ:int`;`q:int`;`Y:real`] TILE_ARG_NJSHIFT)
    THEN
  REWRITE_TAC[tile_k] THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC);;

(* down-transfer (mirror of THETA_SHIFT_TRANSFER): theta(Z+2^L)(Y+2^L)<>0 +  *)
(* (nonzero witness of the shifted point has scale k<=L) ==> theta(Z)(Y) =   *)
(* theta(Z+2^L)(Y+2^L).  Witness (k,nI,nJ) of the shifted point maps DOWN to *)
(* (k,nI,nJ-q) witnessing (Z,Y) with the same window value.                  *)
let THETA_SHIFT_TRANSFER_DOWN = prove
 (`!Z Y L.
     ~(carleson_theta (Z + &2 zpow L) (Y + &2 zpow L) = &0) /\
     (!k nI nJ. (Z + &2 zpow L) IN tile_Jr(k,nI,nJ) /\ (Y + &2 zpow L) IN
       tile_Jl(k,nI,nJ) /\
                ~(Re(fourier carleson_phi (&2 zpow (--(tile_k(k,nI,nJ))) * ((Y
                  + &2 zpow L) - tile_ymid(k,nI,nJ)))) pow 2 = &0)
                ==> k <= L)
     ==> carleson_theta Z Y = carleson_theta (Z + &2 zpow L) (Y + &2 zpow L)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o MATCH_MP THETA_TILE_WITNESS) THEN
  DISCH_THEN(X_CHOOSE_THEN `k:int` (X_CHOOSE_THEN `nI:int` (X_CHOOSE_THEN
    `nJ:int` STRIP_ASSUME_TAC))) THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`k:int`;`nI:int`;`nJ:int`]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`k:int`;`L:int`] ZPOW_SHIFT_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `q:int`) THEN
  SUBGOAL_THEN
   `carleson_theta (Z + &2 zpow L) (Y + &2 zpow L) =
    Re(fourier carleson_phi (&2 zpow (--k) * ((Y + &2 zpow L) -
      tile_ymid(k,nI,nJ)))) pow 2`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`(k,nI,nJ):int#int#int`; `Z + &2 zpow L`;
     `Y + &2 zpow L`] CARLESON_THETA_VALUE) THEN
    ASM_REWRITE_TAC[tile_k]; ALL_TAC] THEN
  SUBGOAL_THEN
   `carleson_theta Z Y =
    Re(fourier carleson_phi (&2 zpow (--k) * (Y - tile_ymid(k,nI,nJ - q)))) pow
      2`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`(k,nI,nJ - q):int#int#int`; `Z:real`;
     `Y:real`] CARLESON_THETA_VALUE) THEN
    REWRITE_TAC[tile_k] THEN DISCH_THEN MATCH_MP_TAC THEN
    MP_TAC(SPECL [`k:int`;`nI:int`;`nJ - q:int`;`q:int`;`Z:real`]
      TILE_JR_NJSHIFT) THEN
    MP_TAC(SPECL [`k:int`;`nI:int`;`nJ - q:int`;`q:int`;`Y:real`]
      TILE_JL_NJSHIFT) THEN
    SUBGOAL_THEN `(nJ:int) - q + q = nJ` (fun th -> REWRITE_TAC[th]) THENL
     [INT_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  MP_TAC(SPECL [`k:int`;`nI:int`;`nJ - q:int`;`q:int`;`Y:real`]
    TILE_ARG_NJSHIFT) THEN
  SUBGOAL_THEN `(nJ:int) - q + q = nJ` (fun th -> REWRITE_TAC[th]) THENL
   [INT_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[tile_k] THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC);;

(* full shift-equality: theta(Z+2^L)(Y+2^L) = theta(Z)(Y), given L bounds    *)
(* every nonzero-window witnessing scale of BOTH points (4-way case-split on *)
(* the two thetas being zero; nonzero side handled by the up/down transfer). *)
let CARLESON_THETA_SHIFT_2L = prove
 (`!Z Y L.
     (!k nI nJ. Z IN tile_Jr(k,nI,nJ) /\ Y IN tile_Jl(k,nI,nJ) /\
                ~(Re(fourier carleson_phi (&2 zpow (--(tile_k(k,nI,nJ))) * (Y -
                  tile_ymid(k,nI,nJ)))) pow 2 = &0)
                ==> k <= L) /\
     (!k nI nJ. (Z + &2 zpow L) IN tile_Jr(k,nI,nJ) /\ (Y + &2 zpow L) IN
       tile_Jl(k,nI,nJ) /\
                ~(Re(fourier carleson_phi (&2 zpow (--(tile_k(k,nI,nJ))) * ((Y
                  + &2 zpow L) - tile_ymid(k,nI,nJ)))) pow 2 = &0)
                ==> k <= L)
     ==> carleson_theta (Z + &2 zpow L) (Y + &2 zpow L) = carleson_theta Z Y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_CASES_TAC `carleson_theta Z Y = &0` THENL
   [ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `carleson_theta (Z + &2 zpow L) (Y + &2 zpow L) = &0` THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`Z:real`; `Y:real`; `L:int`] THETA_SHIFT_TRANSFER_DOWN) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SYM) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC THETA_SHIFT_TRANSFER THEN ASM_REWRITE_TAC[]]);;

(* 286R-b-i (Fremlin mt286.tex 2437-2488): the beta-periodicity of theta'.   *)
(* For y<z, a>0, there is an integer L (= floor log2(20 a(z-y))) such that   *)
(* shifting                                                                  *)
(* beta by 2^L leaves theta' unchanged, for every beta.  The gate L is beta- *)
(* independent because (a z+b)-(a y+b) = a(z-y) does not involve b.          *)
let CARLESON_THETA'_PERIOD = prove
 (`!z a y. &0 < a /\ y < z
   ==> ?L:int. !b. carleson_theta' z a (b + &2 zpow L) y = carleson_theta' z a
     b y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPEC `&20 * a * (z - y)` CARLESON_GATE_L_EXISTS) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `L:int`) THEN EXISTS_TAC `L:int` THEN GEN_TAC THEN
  REWRITE_TAC[carleson_theta'] THEN
  SUBGOAL_THEN `a * z + (b + &2 zpow L) = (a * z + b) + &2 zpow L /\
                a * y + (b + &2 zpow L) = (a * y + b) + &2 zpow L`
    (fun th -> REWRITE_TAC[th]) THENL [CONJ_TAC THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC CARLESON_THETA_SHIFT_2L THEN CONJ_TAC THEN
  MAP_EVERY X_GEN_TAC [`k:int`;`nI:int`;`nJ:int`] THEN STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THENL
   [MP_TAC(SPECL [`k:int`;`nI:int`;`nJ:int`;`(a * z + b):real`;`(a * y +
     b):real`]
       CARLESON_TILE_GATE) THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    MP_TAC(SPECL [`k:int`;`nI:int`;`nJ:int`;`(a * z + b) + &2 zpow L`;`(a * y +
      b) + &2 zpow L`]
       CARLESON_TILE_GATE) THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC]);;

(* ========================================================================= *)
(* 286R-(b-ii): the B.Levi / Cesaro-average limit                            *)
(* g(alpha,y,z) = lim_{b->inf} (1/b) int_0^b theta'_{z,alpha,beta}(y) dbeta  *)
(* is defined (Fremlin mt286.tex 2490-2518).  We prove the general fact: for *)
(* a nonnegative p-periodic locally-integrable f, the Cesaro average         *)
(* (1/b) int_0^b f  converges to the mean (1/p) int_0^p f as b -> +inf.      *)
(* Fremlin's squeeze: with gamma = (1/p) int_0^p f = (1/(p m)) int_0^{p m} f *)
(* (by periodicity), for p m <= b <= p(m+1) one has                          *)
(*   (m/(m+1)) gamma <= (1/b) int_0^b f <= ((m+1)/m) gamma,                  *)
(* both approaching gamma.  Instantiated at p = 2^l (the beta-period from    *)
(* CARLESON_THETA'_PERIOD) this gives 286R-(b-ii).                           *)
(* ========================================================================= *)

(* n/(n+1) -> 1 and (n+1)/n -> 1                                             *)
let SEQ_N_OVER_SUC = prove
 (`((\n. &n / (&n + &1)) ---> &1) sequentially`,
  MP_TAC(ISPECL [`sequentially`; `\n. &1 - inv(&n + &1)`; `\n. &n / (&n + &1)`;
    `&1`]
    REALLIM_TRANSFORM_EVENTUALLY) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
    REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC(REAL_FIELD `&0 <= y ==> y / (y + &1) = &1 - inv(y + &1)`) THEN
    REWRITE_TAC[REAL_POS];
    MP_TAC(ISPECL [`sequentially`; `\n:num. &1`; `\n. inv(&n + &1)`; `&1`;
      `&0`]
      REALLIM_SUB) THEN
    REWRITE_TAC[REALLIM_CONST; REALLIM_1_OVER_N_OFFSET; REAL_SUB_RZERO;
      ETA_AX]]);;

let SEQ_SUC_OVER_N = prove
 (`((\n. (&n + &1) / &n) ---> &1) sequentially`,
  MP_TAC(ISPECL [`sequentially`; `\n. &1 + inv(&n)`; `\n. (&n + &1) / &n`;
    `&1`]
    REALLIM_TRANSFORM_EVENTUALLY) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `1` THEN
    REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC(REAL_FIELD `&0 < y ==> (y + &1) / y = &1 + inv(y)`) THEN
    REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC;
    MP_TAC(ISPECL [`sequentially`; `\n:num. &1`; `\n. inv(&n)`; `&1`; `&0`]
      REALLIM_ADD) THEN
    REWRITE_TAC[REALLIM_CONST; REALLIM_1_OVER_N; REAL_ADD_RID; ETA_AX]]);;

(* monotonicity of the integral over [0,.] for a nonnegative integrand       *)
let INT_0_MONO = prove
 (`!f u v. &0 <= u /\ u <= v /\ (!x. &0 <= f x) /\
           (!a b. f real_integrable_on real_interval[a,b])
           ==> real_integral (real_interval[&0,u]) f <= real_integral
             (real_interval[&0,v]) f`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN
    ASM_REAL_ARITH_TAC);;

(* the shift int_c^{c+p} f = int_0^p f(.+c) via HAS_REAL_INTEGRAL_AFFINITY   *)
let REAL_INTEGRAL_SHIFT = prove
 (`!f c p. f real_integrable_on real_interval[c,c + p]
   ==> real_integral (real_interval[c,c + p]) f = real_integral
     (real_interval[&0,p]) (\b. f(b + c))`,
  REPEAT STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o MATCH_MP REAL_INTEGRABLE_INTEGRAL) THEN
  DISCH_THEN(MP_TAC o SPECL [`&1`; `c:real`] o MATCH_MP
    (REWRITE_RULE[TAUT `a /\ b ==> c <=> a ==> b ==> c`]
      HAS_REAL_INTEGRAL_AFFINITY)) THEN
  REWRITE_TAC[REAL_ARITH `~(&1 = &0)`; REAL_MUL_LID; REAL_INV_1;
    REAL_ABS_NUM] THEN
  SUBGOAL_THEN
    `IMAGE (\x. x - c) (real_interval[c,c + p]) = real_interval[&0,p]`
    SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL] THEN
     X_GEN_TAC `t:real` THEN EQ_TAC THENL
     [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      STRIP_TAC THEN EXISTS_TAC `t + c:real` THEN
        ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN REFL_TAC);;

(* period iteration f(b + n p) = f b                                         *)
let PERIOD_ITERATE = prove
 (`!f p. (!b. f(b + p) = f b) ==> !n b. f(b + &n * p) = f b`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN INDUCT_TAC THEN
  REWRITE_TAC[REAL_MUL_LZERO; REAL_ADD_RID; GSYM REAL_OF_NUM_SUC] THEN
  X_GEN_TAC `b:real` THEN
  SUBGOAL_THEN `b + (&n + &1) * p = (b + &n * p) + p` SUBST1_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN ASM_REWRITE_TAC[]);;

(* int_0^{n p} f = n int_0^p f for p-periodic integrable f                   *)
let PERIOD_INTEGRAL_MULTIPLE = prove
 (`!f p. &0 < p /\ (!b. f(b + p) = f b) /\ (!u v. f real_integrable_on
   real_interval[u,v])
   ==> !n. real_integral (real_interval[&0,&n * p]) f = &n * real_integral
     (real_interval[&0,p]) f`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN INDUCT_TAC THEN
  REWRITE_TAC[REAL_MUL_LZERO; GSYM REAL_OF_NUM_SUC] THENL
   [SIMP_TAC[REAL_INTEGRAL_NULL; REAL_LE_REFL]; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (real_interval[&0,(&n + &1) * p]) f =
    real_integral (real_interval[&0,&n * p]) f +
    real_integral (real_interval[&n * p,(&n + &1) * p]) f`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_INTEGRAL_COMBINE THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
      ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `(&n + &1) * p = (&n * p) + p` (fun th -> ONCE_REWRITE_TAC[th]) THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`f:real->real`; `&n * p`; `p:real`] REAL_INTEGRAL_SHIFT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `(\b. (f:real->real)(b + &n * p)) = f` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real` THEN
    MP_TAC(ISPECL [`f:real->real`; `p:real`] PERIOD_ITERATE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* gamma = (1/(p m)) int_0^{p m} f  = (1/p) int_0^p f  for m >= 1            *)
let PERIOD_AVG_MULTIPLE = prove
 (`!f p. &0 < p /\ (!b. f(b + p) = f b) /\ (!u v. f real_integrable_on
   real_interval[u,v])
   ==> !m. 1 <= m
       ==> inv(p * &m) * real_integral (real_interval[&0,&m * p]) f =
           inv p * real_integral (real_interval[&0,p]) f`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`f:real->real`; `p:real`] PERIOD_INTEGRAL_MULTIPLE) THEN
  ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[SPEC `m:num` th]) THEN
  SUBGOAL_THEN `~(p = &0) /\ ~(&m = &0)` MP_TAC THENL
   [CONJ_TAC THENL [ASM_REAL_ARITH_TAC;
     REWRITE_TAC[REAL_OF_NUM_EQ] THEN ASM_ARITH_TAC]; ALL_TAC] THEN
  CONV_TAC REAL_FIELD);;

(* auxiliary division bounds for the sandwich                                *)
let INV_SUC_LE_DIV = prove
 (`&0 < b /\ &0 < &m + &1 /\ &0 < p /\ b <= (&m + &1) * p ==> inv (&m + &1) <=
   p / b`,
  STRIP_TAC THEN ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `inv(&m + &1) * ((&m + &1) * p)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN
     ASM_SIMP_TAC[REAL_LE_INV_EQ; REAL_LT_IMP_LE];
    ASM_SIMP_TAC[REAL_MUL_ASSOC; REAL_MUL_LINV; REAL_LT_IMP_NZ; REAL_MUL_LID;
      REAL_LE_REFL]]);;

let DIV_LE_INV_M = prove
 (`&0 < b /\ &0 < &m /\ &0 < p /\ &m * p <= b ==> p / b <= inv (&m)`,
  STRIP_TAC THEN ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `inv(&m) * (&m * p)` THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[REAL_MUL_ASSOC; REAL_MUL_LINV; REAL_LT_IMP_NZ; REAL_MUL_LID;
     REAL_LE_REFL];
    MATCH_MP_TAC REAL_LE_LMUL THEN
      ASM_SIMP_TAC[REAL_LE_INV_EQ; REAL_LT_IMP_LE]]);;

(* the two-sided sandwich for p m <= b <= p(m+1), m >= 1                     *)
let PERIOD_AVG_SANDWICH = prove
 (`!f p m b. &0 < p /\ 1 <= m /\ (!x. &0 <= f x) /\
             (!u v. f real_integrable_on real_interval[u,v]) /\
             (!b. f(b + p) = f b) /\
             &m * p <= b /\ b <= (&m + &1) * p
   ==> (&m / (&m + &1)) * (inv p * real_integral (real_interval[&0,p]) f)
         <= inv b * real_integral (real_interval[&0,b]) f /\
       inv b * real_integral (real_interval[&0,b]) f
         <= ((&m + &1) / &m) * (inv p * real_integral (real_interval[&0,p])
           f)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `G = inv p * real_integral (real_interval[&0,p]) f` THEN
  SUBGOAL_THEN `&0 < b` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `&m * p` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_LT_MUL THEN
    ASM_REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 < &m /\ &0 < &m + &1 /\ ~(&m = &0) /\ ~(&m + &1 = &0)` STRIP_ASSUME_TAC
    THENL
   [REWRITE_TAC[REAL_OF_NUM_LT; REAL_OF_NUM_EQ] THEN
     ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `real_integral (real_interval[&0,&m * p]) f =
     (p * &m) * G` ASSUME_TAC THENL
   [MP_TAC(SPECL [`f:real->real`; `p:real`] PERIOD_AVG_MULTIPLE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "G" THEN
    SUBGOAL_THEN `~(p * &m = &0)` MP_TAC THENL
     [REWRITE_TAC[REAL_ENTIRE; DE_MORGAN_THM] THEN CONJ_TAC THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  SUBGOAL_THEN
    `real_integral (real_interval[&0,(&m + &1) * p]) f = (p * (&m + &1)) * G`
    ASSUME_TAC THENL
   [MP_TAC(SPECL [`f:real->real`; `p:real`] PERIOD_AVG_MULTIPLE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `m + 1`) THEN
    ANTS_TAC THENL [ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN EXPAND_TAC "G" THEN
    SUBGOAL_THEN `~(p * (&m + &1) = &0)` MP_TAC THENL
     [REWRITE_TAC[REAL_ENTIRE; DE_MORGAN_THM] THEN CONJ_TAC THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(&m + &1) * p = p * (&m + &1)` SUBST1_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= G` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `inv b * real_integral (real_interval[&0,&m * p]) f` THEN
      CONJ_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[REAL_ARITH `inv b * (p * &m) * G = (&m * G) * (p / b)`;
                  REAL_ARITH `&m / (&m + &1) * G = (&m * G) * inv(&m + &1)`]
                    THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
         ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC INV_SUC_LE_DIV THEN ASM_REWRITE_TAC[]];
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC INT_0_MONO THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC]];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `inv b * real_integral (real_interval[&0,(&m + &1) * p]) f` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC INT_0_MONO THEN ASM_REWRITE_TAC[] THEN
          ASM_REAL_ARITH_TAC];
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[REAL_ARITH `inv b * (p * (&m + &1)) * G = ((&m + &1) * G) *
        (p / b)`;
                  REAL_ARITH `(&m + &1) / &m * G = ((&m + &1) * G) * inv(&m)`]
                    THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
         ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC DIV_LE_INV_M THEN ASM_REWRITE_TAC[]]]]);;

(* the floor block: for b > 0 there is m with p m <= b < p (m+1)             *)
let CESARO_BLOCK_EXISTS = prove
 (`!p b:real. &0 < p /\ &0 < b ==> ?m. &m * p <= b /\ b < (&m + &1) * p`,
  REPEAT STRIP_TAC THEN MP_TAC(SPEC `(b:real) / p` FLOOR_POS) THEN
  ANTS_TAC THENL [ASM_SIMP_TAC[REAL_LE_DIV; REAL_LT_IMP_LE]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `m:num`) THEN EXISTS_TAC `m:num` THEN
  MP_TAC(SPEC `(b:real) / p` FLOOR) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  ASM_SIMP_TAC[GSYM REAL_LE_RDIV_EQ; GSYM REAL_LT_LDIV_EQ]);;

(* the squeeze glue                                                          *)
let CESARO_SQUEEZE = prove
 (`!A G e r1 r2.
     r1 <= A /\ A <= r2 /\ abs(r1 - G) < e /\ abs(r2 - G) < e ==> abs(A - G) <
       e`,
  REAL_ARITH_TAC);;

(* THE Cesaro-mean limit: nonnegative p-periodic locally-integrable f =>     *)
(* (1/b) int_0^b f -> (1/p) int_0^p f as b -> +inf. [Fremlin 286R-b-ii]      *)
let PERIODIC_CESARO_LIMIT = prove
 (`!f p. &0 < p /\ (!x. &0 <= f x) /\
         (!u v. f real_integrable_on real_interval[u,v]) /\
         (!b. f(b + p) = f b)
   ==> ((\b. inv b * real_integral (real_interval[&0,b]) f)
        ---> inv p * real_integral (real_interval[&0,p]) f) at_posinfinity`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `G = inv p * real_integral (real_interval[&0,p]) f` THEN
  SUBGOAL_THEN `&0 <= G` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((\m. (&m / (&m + &1)) * G) ---> G) sequentially /\
                ((\m. ((&m + &1) / &m) * G) ---> G) sequentially`
                  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [GSYM REAL_MUL_LID] THEN
    MATCH_MP_TAC REALLIM_RMUL THENL
     [ACCEPT_TAC SEQ_N_OVER_SUC; ACCEPT_TAC SEQ_SUC_OVER_N]; ALL_TAC] THEN
  REWRITE_TAC[REALLIM_AT_POSINFINITY] THEN X_GEN_TAC `e:real` THEN
    DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REALLIM_SEQUENTIALLY]) THEN
  DISCH_THEN(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `M2:num`) THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REALLIM_SEQUENTIALLY]) THEN
  DISCH_THEN(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `M1:num`) THEN
  EXISTS_TAC `(&(M1 + M2) + &1) * p + &1` THEN
  X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < b` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LTE_TRANS THEN
     EXISTS_TAC `(&(M1 + M2) + &1) * p + &1` THEN
    ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(REAL_ARITH `&0 <= x ==> &0 < x + &1`) THEN
    MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`p:real`; `b:real`] CESARO_BLOCK_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `1 <= m /\ M1 <= m /\ M2 <= m` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ARITH_RULE `!M1 M2 m:num. M1 + M2 < m ==> 1 <= m /\ M1 <= m /\
     M2 <= m`) THEN
    SUBGOAL_THEN `(&(M1 + M2) + &1) * p < (&m + &1) * p` MP_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_LT_RMUL_EQ] THEN
    REWRITE_TAC[REAL_ARITH `&(M1 + M2) + &1 < &m + &1 <=> &(M1 + M2) < &m`]
      THEN
    REWRITE_TAC[REAL_OF_NUM_LT]; ALL_TAC] THEN
  MP_TAC(SPECL [`f:real->real`; `p:real`; `m:num`;
    `b:real`] PERIOD_AVG_SANDWICH) THEN
  ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC CESARO_SQUEEZE THEN
  EXISTS_TAC `&m / (&m + &1) * G` THEN
  EXISTS_TAC `(&m + &1) / &m * G` THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]);;

(* --- Cesaro change-of-variable engine (feeds 286R-(d)/(f)/(g))             *)
(* -------------                                                             *)
(* The (1/b)-average kills boundary terms: shifting/rescaling the window of  *)
(* a                                                                         *)
(* bounded nonnegative integrand leaves the Cesaro limit unchanged.          *)

(* int_c^{b+c} f = int_0^b f + (int_b^{b+c} f - int_0^c f)  for c>=0, b>0.   *)
let CESARO_SPLIT_ID = prove
 (`!f b c. &0 <= c /\ &0 < b /\ (!u v. f real_integrable_on real_interval[u,v])
   ==> real_integral (real_interval[c,b + c]) f =
       real_integral (real_interval[&0,b]) f +
       (real_integral (real_interval[b,b + c]) f - real_integral
         (real_interval[&0,c]) f)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `real_integral (real_interval[&0,c]) f + real_integral (real_interval[c,b +
     c]) f =
    real_integral (real_interval[&0,b + c]) f`
   (fun th -> MP_TAC th) THENL
   [MATCH_MP_TAC REAL_INTEGRAL_COMBINE THEN ASM_REWRITE_TAC[] THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (real_interval[&0,b]) f + real_integral (real_interval[b,b +
     c]) f =
    real_integral (real_interval[&0,b + c]) f`
   (fun th -> MP_TAC th) THENL
   [MATCH_MP_TAC REAL_INTEGRAL_COMBINE THEN ASM_REWRITE_TAC[] THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* 0 <= int_a^{a+c} f <= c  for 0<=f<=1, c>=0.                               *)
let CESARO_BOUNDARY_BOUND = prove
 (`!f a c. &0 <= c /\ (!x. &0 <= f x) /\ (!x. f x <= &1) /\
           (!u v. f real_integrable_on real_interval[u,v])
   ==> &0 <= real_integral (real_interval[a,a + c]) f /\
       real_integral (real_interval[a,a + c]) f <= c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[] THEN
    REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral (real_interval[a,a + c]) (\x. &1)` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_LE THEN
       ASM_REWRITE_TAC[REAL_INTEGRABLE_CONST] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[REAL_INTEGRAL_CONST;
        REAL_ARITH `&0 <= c ==> a <= a + c`] THEN
      REAL_ARITH_TAC]]);;

(* inv b ---> 0 as b ---> +inf.                                              *)
let REALLIM_INV_POSINF = prove
 (`((\b. inv b) ---> &0) at_posinfinity`,
  REWRITE_TAC[REALLIM_AT_POSINFINITY] THEN X_GEN_TAC `e:real` THEN
    DISCH_TAC THEN
  EXISTS_TAC `&1 / e + &1` THEN X_GEN_TAC `x:real` THEN
    REWRITE_TAC[real_ge] THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < &1 / e` ASSUME_TAC THENL
    [ASM_SIMP_TAC[REAL_LT_DIV; REAL_LT_01]; ALL_TAC] THEN
  ABBREV_TAC `d = &1 / e` THEN
  SUBGOAL_THEN `d < x` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < x` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_SUB_RZERO] THEN
    ASM_SIMP_TAC[REAL_ABS_INV; REAL_ARITH `&0 < y ==> abs y = y`] THEN
  MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `inv(d:real)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LT_INV2 THEN ASM_REWRITE_TAC[];
    EXPAND_TAC "d" THEN ASM_SIMP_TAC[REAL_INV_DIV] THEN ASM_REAL_ARITH_TAC]);;

(* the boundary contribution inv b * (int_b^{b+c} - int_0^c) ---> 0.         *)
let CESARO_BOUNDARY_NULL = prove
 (`!f c. &0 <= c /\ (!x. &0 <= f x) /\ (!x. f x <= &1) /\
         (!u v. f real_integrable_on real_interval[u,v])
   ==> ((\b. inv b * (real_integral (real_interval[b,b + c]) f -
                      real_integral (real_interval[&0,c]) f)) ---> &0)
                        at_posinfinity`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`at_posinfinity`;
    `\b. inv b * (real_integral (real_interval[b,b + c]) f -
                  real_integral (real_interval[&0,c]) f)`;
    `\b:real. c * inv b`] REALLIM_NULL_COMPARISON) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[EVENTUALLY_AT_POSINFINITY] THEN EXISTS_TAC `&1` THEN
      X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN DISCH_TAC THEN
        BETA_TAC THEN
      REWRITE_TAC[REAL_ABS_MUL] THEN
      SUBGOAL_THEN `abs(inv b) = inv b` SUBST1_TAC THENL
       [REWRITE_TAC[REAL_ABS_INV; REAL_ABS_REFL] THEN
         MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
        ALL_TAC] THEN
      GEN_REWRITE_TAC RAND_CONV [REAL_MUL_SYM] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      MP_TAC(SPECL [`f:real->real`;`b:real`;`c:real`] CESARO_BOUNDARY_BOUND)
        THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(SPECL [`f:real->real`;`&0`;`c:real`] CESARO_BOUNDARY_BOUND) THEN
      ASM_REWRITE_TAC[REAL_ADD_LID] THEN REAL_ARITH_TAC;
      SUBGOAL_THEN `&0 = c * &0` SUBST1_TAC THENL
        [REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC REALLIM_LMUL THEN MP_TAC REALLIM_INV_POSINF THEN
        REWRITE_TAC[ETA_AX]];
    DISCH_THEN ACCEPT_TAC]);;

(* 286R-(d) engine: the c-shifted Cesaro average has the same limit (c>=0).  *)
let CESARO_SHIFT_INVARIANT = prove
 (`!f c L. &0 <= c /\
     (!x. &0 <= f x) /\ (!x. f x <= &1) /\ (!u v. f real_integrable_on
       real_interval[u,v]) /\
     ((\b. inv b * real_integral (real_interval[&0,b]) f) ---> L)
       at_posinfinity
     ==> ((\b. inv b * real_integral (real_interval[c,b + c]) f) ---> L)
       at_posinfinity`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REALLIM_TRANSFORM_EVENTUALLY THEN
  EXISTS_TAC `\b. inv b * real_integral (real_interval[&0,b]) f +
                  inv b * (real_integral (real_interval[b,b + c]) f -
                           real_integral (real_interval[&0,c]) f)` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_AT_POSINFINITY] THEN EXISTS_TAC `&1` THEN
    X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN DISCH_TAC THEN
      BETA_TAC THEN
    MP_TAC(SPECL [`f:real->real`;`b:real`;`c:real`] CESARO_SPLIT_ID) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN REAL_ARITH_TAC;
    GEN_REWRITE_TAC LAND_CONV [GSYM REAL_ADD_RID] THEN
    MATCH_MP_TAC REALLIM_ADD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CESARO_BOUNDARY_NULL THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* Sine-kernel Riemann-Lebesgue reduction (DINI's TEST, general form). For a *)
(* fixed x, if the localized kernel H(u) = ((f(x+u)+f(x-u)) - 2 f x)/u is    *)
(* (absolutely) integrable on [0,pi], then the discrete sine-kernel integral *)
(*    int_0^pi sin((n+1/2)u) H(u) du -> 0    as n -> inf                     *)
(* by Riemann-Lebesgue.  Proof: extend H by zero to R (RESTRICT_UNIV), apply *)
(* RIEMANN_LEBESGUE_RLINE (continuous a -> +inf), then specialise            *)
(* a := &n + 1/2 via the shifted-sequential limit helper.                    *)
(*                                                                           *)
(* CAUTION (route note): the Dini hypothesis "H_x integrable a.e." is a      *)
(* SUFFICIENT-but-not-necessary convergence test; it FAILS on positive-      *)
(* measure sets for general L^2 f, so it is NOT the route to Carleson (were  *)
(* it, a.e. convergence would be elementary).  The honest Carleson-level     *)
(* target is the OSCILLATORY sine-kernel limit itself (no integrability of   *)
(* H_x assumed -- the sin((n+1/2)u) cancels the 1/u singularity), which by   *)
(* FOURIER_SUM_LIMIT_SINE_PART is EQUIVALENT to s_n(x) -> f(x).  So the true *)
(* remaining input is CARLESON_286V_FROM_SINEKERNEL's hypothesis; the Dini   *)
(* form below is retained only as a general-purpose lemma / sanity check.    *)
(* ========================================================================= *)

let REALLIM_POSINFINITY_SEQ_SHIFT = prove
 (`!g l. (g ---> l) at_posinfinity
         ==> ((\n. g(&n + &1 / &2)) ---> l) sequentially`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[REALLIM_AT_POSINFINITY; REALLIM_SEQUENTIALLY] THEN
  DISCH_TAC THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:real` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPEC `b:real` REAL_ARCH_SIMPLE) THEN
  DISCH_THEN(X_CHOOSE_THEN `N:num` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `N:num` THEN X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `&n + &1 / &2`) THEN
  REWRITE_TAC[real_ge] THEN ANTS_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&N:real` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&n:real` THEN
    ASM_SIMP_TAC[REAL_OF_NUM_LE] THEN REAL_ARITH_TAC;
    REWRITE_TAC[]]);;

let CARLESON_286V_FROM_SINEKERNEL = prove
 (`!f. f square_integrable_on real_interval[--pi,pi] /\
       (!x. f(x + &2 * pi) = f x) /\
       (?s. real_negligible s /\
            !x. ~(x IN s)
                ==> ((\n. real_integral (real_interval[&0,pi])
                            (\u. sin((&n + &1 / &2) * u) *
                                 ((f(x + u) + f(x - u)) - &2 * f x) / u))
                     ---> &0) sequentially)
       ==> ?s. real_negligible s /\
               !x. ~(x IN s)
                   ==> ((\n. sum(0..n) (\k. fourier_coefficient f k *
                                            trigonometric_set k x))
                        ---> f x) sequentially`,
  GEN_TAC THEN STRIP_TAC THEN
  EXISTS_TAC `s:real->bool` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `x:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `x:real`; `(f:real->real) x`; `pi`]
    FOURIER_SUM_LIMIT_SINE_PART) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC SQUARE_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
      ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
      MP_TAC PI_POS THEN REAL_ARITH_TAC;
      REAL_ARITH_TAC];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real`) THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286V descent, LOCAL-INTEGRABILITY (Dini) form: combining the RL reduction *)
(* with the periodic descent, Fourier-series a.e. convergence follows from   *)
(* the a.e. absolute integrability on [0,pi] of H_x(u) = ((f(x+u)+f(x-u))    *)
(* - 2 f x)/u.  NOTE: this is a corollary via DINI's test, NOT the Carleson  *)
(* route -- the Dini hypothesis is too strong (fails a.e. for general L^2).  *)
(* The actual remaining CARLESON_THEOREM input is the weaker OSCILLATORY     *)
(* sine-kernel hypothesis of CARLESON_286V_FROM_SINEKERNEL (the honest       *)
(* target of the 286O-286U maximal-operator tower).  Kept as a general       *)
(* convergence-test corollary.                                               *)
(* ========================================================================= *)

let SUP_SEQ_SUPERLEVEL = prove
 (`!(Ff:num->real->real) x a.
     (?B. !n. Ff n x <= B)
     ==> (a < sup {Ff n x | n IN (:num)} <=> ?n. a < Ff n x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `sup {Ff n x | n IN (:num)} <= a <=> (!n. (Ff:num->real->real) n x <= a)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`{(Ff:num->real->real) n x | n IN (:num)}`; `a:real`]
       REAL_SUP_LE_EQ) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
         MESON_TAC[IN_UNIV];
        EXISTS_TAC `B:real` THEN REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN
        ASM_REWRITE_TAC[]];
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN DISCH_THEN SUBST1_TAC THEN
        REFL_TAC];
    EQ_TAC THENL
     [DISCH_TAC THEN REWRITE_TAC[GSYM NOT_FORALL_THM; GSYM REAL_NOT_LT] THEN
      ASM_MESON_TAC[REAL_NOT_LT];
      STRIP_TAC THEN ASM_MESON_TAC[REAL_NOT_LT; REAL_LTE_TRANS]]]);;

(* Superlevel set of the sup = point in the countable union of superlevel    *)
(* sets.                                                                     *)
let SUP_MEM_UNIONS = prove
 (`!(Ff:num->real->real) a x.
     (?B. !n. Ff n x <= B)
     ==> (sup {Ff n x | n IN (:num)} > a <=>
          x IN UNIONS {{x | Ff n x > a} | n IN (:num)})`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[real_gt] THEN
  MP_TAC(ISPECL [`Ff:num->real->real`; `x:real`;
    `a:real`] SUP_SEQ_SUPERLEVEL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[IN_UNIONS; EXISTS_IN_GSPEC; IN_UNIV; IN_ELIM_THM; real_gt]);;

(* A pointwise-bounded-above countable sup of measurable functions is        *)
(* measurable.                                                               *)
let REAL_MEASURABLE_ON_SUP = prove
 (`!(Ff:num->real->real).
     (!n. Ff n real_measurable_on (:real)) /\
     (!x. ?B. !n. Ff n x <= B)
     ==> (\x. sup {Ff n x | n IN (:num)}) real_measurable_on (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_MEASURABLE_ON_PREIMAGE_HALFSPACE_GT] THEN
  X_GEN_TAC `a:real` THEN
  SUBGOAL_THEN
   `{x | sup {(Ff:num->real->real) n x | n IN (:num)} > a} =
    UNIONS {{x | Ff n x > a} | n IN (:num)}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN X_GEN_TAC `x:real` THEN
    MP_TAC(ISPECL [`Ff:num->real->real`; `a:real`;
      `x:real`] SUP_MEM_UNIONS) THEN
    ASM_REWRITE_TAC[IN_ELIM_THM];
    MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_COUNTABLE_UNIONS THEN CONJ_TAC THENL
     [REWRITE_TAC[SIMPLE_IMAGE] THEN MATCH_MP_TAC COUNTABLE_IMAGE THEN
      REWRITE_TAC[NUM_COUNTABLE];
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `n:num` THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN
      REWRITE_TAC[REAL_MEASURABLE_ON_PREIMAGE_HALFSPACE_GT] THEN
      DISCH_THEN(ACCEPT_TAC o SPEC `a:real`)]]);;

(* pure sequence-level superlevel fact (domain-free cousin of SUP_SEQ_       *)
(* SUPERLEVEL, whose x:real is incidental): for a bounded-above real         *)
(* sequence, a < sup <=> some member exceeds a.                              *)
let SUP_SEQ_SUPERLEVEL_PURE = prove
 (`!(s:num->real) a. (?B. !n. s n <= B)
     ==> (a < sup {s n | n IN (:num)} <=> ?n. a < s n)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `sup {(s:num->real) n | n IN (:num)} <= a <=> (!n. s n <= a)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`{(s:num->real) n | n IN (:num)}`;
     `a:real`] REAL_SUP_LE_EQ) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
         MESON_TAC[IN_UNIV];
        EXISTS_TAC `B:real` THEN REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN
          ASM_REWRITE_TAC[]];
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN DISCH_THEN SUBST1_TAC THEN
        REFL_TAC];
    EQ_TAC THENL
     [DISCH_TAC THEN REWRITE_TAC[GSYM NOT_FORALL_THM; GSYM REAL_NOT_LT] THEN
      ASM_MESON_TAC[REAL_NOT_LT];
      STRIP_TAC THEN ASM_MESON_TAC[REAL_NOT_LT; REAL_LTE_TRANS]]]);;

(* The R^M analog of REAL_MEASURABLE_ON_SUP (which is R^1-only): a           *)
(* pointwise-                                                                *)
(* bounded-above countable sup of measurable real-valued functions on R^M is *)
(* measurable.  Superlevel of the sup = countable union of the members'      *)
(* superlevels (SUP_SEQ_SUPERLEVEL_PURE), each lebesgue_measurable. Feeds    *)
(* the                                                                       *)
(* joint (a,b,w)-measurability of the tile-sup theta' kernel (S6 keystone).  *)
let MEASURABLE_ON_SUP_MULTI = prove
 (`!(Ff:num->real^M->real).
     (!n. (\x. lift(Ff n x)) measurable_on (:real^M)) /\
     (!x. ?B. !n. Ff n x <= B)
     ==> (\x. lift(sup {Ff n x | n IN (:num)})) measurable_on (:real^M)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[MEASURABLE_ON_PREIMAGE_HALFSPACE_COMPONENT_GT] THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `k = 1` SUBST_ALL_TAC THENL
   [UNDISCH_TAC `k <= dimindex(:1)` THEN UNDISCH_TAC `1 <= k` THEN
    REWRITE_TAC[DIMINDEX_1] THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM drop; LIFT_DROP] THEN
  SUBGOAL_THEN
   `{x:real^M | sup {(Ff:num->real^M->real) n x | n IN (:num)} > a} =
    UNIONS {{x | Ff n x > a} | n IN (:num)}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_UNIONS; EXISTS_IN_GSPEC; IN_UNIV; IN_ELIM_THM;
     real_gt] THEN
    X_GEN_TAC `x:real^M` THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real^M`) THEN
    DISCH_THEN(MP_TAC o SPEC `a:real` o MATCH_MP SUP_SEQ_SUPERLEVEL_PURE) THEN
    REWRITE_TAC[IN_UNIV];
    MATCH_MP_TAC LEBESGUE_MEASURABLE_COUNTABLE_UNIONS THEN CONJ_TAC THENL
     [REWRITE_TAC[SIMPLE_IMAGE] THEN MATCH_MP_TAC COUNTABLE_IMAGE THEN
      REWRITE_TAC[NUM_COUNTABLE];
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `n:num` THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN
      REWRITE_TAC[MEASURABLE_ON_PREIMAGE_HALFSPACE_COMPONENT_GT] THEN
      DISCH_THEN(MP_TAC o SPECL [`a:real`; `1`]) THEN
      REWRITE_TAC[DIMINDEX_1; LE_REFL; LIFT_DROP; GSYM drop; real_gt]]]);;

(* --- LSC (lower-semicontinuity) route to measurability of a sup over an    *)
(* arbitrary (possibly uncountable) index set of continuous functions.  This *)
(* is what 286T(a) actually needs for Ahat_n (sup over the uncountable       *)
(* window                                                                    *)
(* set {-n<=a<=b<=n}); the countable-sup lemma above is the sequential       *)
(* cousin.                                                                   *)
(* Chain: open superlevels ==> measurable; continuous ==> open superlevel;   *)
(* sup                                                                       *)
(* superlevel = union of superlevels (bounded above) ==> open (union of      *)
(* opens). ---                                                               *)

(* Open superlevels of a function make it measurable (LSC => Borel).         *)
let REAL_MEASURABLE_ON_LSC = prove
 (`!f:real->real. (!a. real_open {x | f x > a}) ==> f real_measurable_on
   (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_MEASURABLE_ON_PREIMAGE_HALFSPACE_GT] THEN
  ASM_SIMP_TAC[REAL_LEBESGUE_MEASURABLE_OPEN]);;

(* The superlevel set of a continuous function is open.                      *)
let REAL_OPEN_SUPERLEVEL_CONTINUOUS = prove
 (`!g:real->real a. (!x. g real_continuous atreal x) ==> real_open {y | g y >
   a}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_OPEN; OPEN_CONTAINS_BALL] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM] THEN X_GEN_TAC `y:real` THEN
  DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN
  REWRITE_TAC[real_continuous_atreal] THEN
  DISCH_THEN(fun th -> MP_TAC(SPEC `(g:real->real) y - a` th)) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `d:real` THEN ASM_REWRITE_TAC[SUBSET; IN_BALL] THEN
  REWRITE_TAC[IN_IMAGE; IN_ELIM_THM] THEN
  X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN EXISTS_TAC `drop z` THEN
  REWRITE_TAC[LIFT_DROP] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `drop z`) THEN
  SUBGOAL_THEN `abs(drop z - y) < d` (fun th -> SIMP_TAC[th]) THENL
   [FIRST_X_ASSUM MP_TAC THEN REWRITE_TAC[DIST_1; LIFT_DROP] THEN
     REAL_ARITH_TAC;
    REWRITE_TAC[real_gt] THEN ASM_REAL_ARITH_TAC]);;

(* a < sup over a nonempty bounded-above index set <=> some member exceeds   *)
(* a.                                                                        *)
let SUP_SET_SUPERLEVEL = prove
 (`!(g:A->real->real) t x a.
     ~(t = {}) /\ (?B. !i. i IN t ==> g i x <= B)
     ==> (a < sup {g i x | i IN t} <=> ?i. i IN t /\ a < g i x)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `i0:A` o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
  SUBGOAL_THEN
   `sup {(g:A->real->real) i x | i IN t} <= a <=> (!i. i IN t ==> g i x <= a)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`{(g:A->real->real) i x | i IN t}`;
     `a:real`] REAL_SUP_LE_EQ) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
        MAP_EVERY EXISTS_TAC [`(g:A->real->real) i0 x`; `i0:A`] THEN
          ASM_REWRITE_TAC[];
        EXISTS_TAC `B:real` THEN REWRITE_TAC[FORALL_IN_GSPEC] THEN
          ASM_REWRITE_TAC[]];
      REWRITE_TAC[FORALL_IN_GSPEC] THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC];
    ALL_TAC] THEN
  EQ_TAC THEN REWRITE_TAC[GSYM REAL_NOT_LE] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP; REAL_NOT_LE] THEN MESON_TAC[]);;

(* Two-bar (two-argument) version: c < sup over a nonempty bounded-above     *)
(* two-bar                                                                   *)
(* family {g a b | a,b | P a b} iff some member exceeds c.  Needed for the   *)
(* carleson_gamma sup (indexed by the window pair (a,b)). ---                *)
let SUP_2BAR_SUPERLEVEL = prove
 (`!(g:A->B->real) P c.
     (?a b. P a b) /\ (?M. !a b. P a b ==> g a b <= M)
     ==> (c < sup {g a b | a,b | P a b} <=> ?a b. P a b /\ c < g a b)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `sup {(g:A->B->real) a b | a,b | P a b} <= c <=> (!a b. P a b ==> g a b <=
     c)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`{(g:A->B->real) a b | a,b | P a b}`;
     `c:real`] REAL_SUP_LE_EQ) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN ASM_MESON_TAC[];
        EXISTS_TAC `M:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN
        REPEAT STRIP_TAC THEN ASM_SIMP_TAC[]];
      REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN SUBST1_TAC THEN
      REWRITE_TAC[] THEN MESON_TAC[]];
    EQ_TAC THEN REWRITE_TAC[GSYM REAL_NOT_LE] THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[NOT_FORALL_THM; NOT_IMP; REAL_NOT_LE] THEN MESON_TAC[]]);;

(* Sup over a nonempty index set of continuous functions, pointwise bounded  *)
(* above, is measurable.                                                     *)
let REAL_MEASURABLE_ON_SUP_CONTINUOUS = prove
 (`!(g:A->real->real) t.
     (!i. i IN t ==> (!x. (g i) real_continuous atreal x)) /\
     (!x. ?B. !i. i IN t ==> g i x <= B) /\ ~(t = {})
     ==> (\x. sup {g i x | i IN t}) real_measurable_on (:real)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_MEASURABLE_ON_LSC THEN
  X_GEN_TAC `a:real` THEN REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `{x | sup {(g:A->real->real) i x | i IN t} > a} =
    UNIONS {{y | g i y > a} | i IN t}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN X_GEN_TAC `x:real` THEN
    REWRITE_TAC[IN_UNIONS; EXISTS_IN_GSPEC; IN_ELIM_THM] THEN
    MP_TAC(ISPECL [`g:A->real->real`; `t:A->bool`; `x:real`; `a:real`]
      SUP_SET_SUPERLEVEL) THEN
    ASM_REWRITE_TAC[real_gt];
    MATCH_MP_TAC REAL_OPEN_UNIONS THEN
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC REAL_OPEN_SUPERLEVEL_CONTINUOUS THEN
    GEN_TAC THEN REWRITE_TAC[ETA_AX] THEN ASM_SIMP_TAC[]]);;

(* --- The 286T maximal operator (Fremlin 286T): sup over a<=b of the        *)
(* normalised truncated Fourier-integral modulus. ---                        *)
let carleson_Ahat = new_definition
 `carleson_Ahat (f:real->complex) (y:real) =
    sup { inv(sqrt(&2 * pi)) *
          norm(integral (IMAGE lift (real_interval[a,b]))
                 (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
        | a <= b }`;;

(* --- carleson_Ahat >= 0 (guarded form): where the truncated-integral       *)
(* family                                                                    *)
(* is bounded above (Af(y) finite), the sup is nonneg -- the a=b term is >=  *)
(* 0                                                                         *)
(* and witnesses the sup. NB Fremlin's Af maps to [0,+inf]; the HOL real sup *)
(* is junk on the null set where the family is unbounded, so nonnegativity   *)
(* is                                                                        *)
(* stated under the boundedness hypothesis (always available where it        *)
(* matters:                                                                  *)
(* 286T gives int_F Af finite, hence Af finite a.e.). ---                    *)
let CARLESON_AHAT_POS = prove
 (`!(f:real->complex) y.
      (?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <= B)
      ==> &0 <= carleson_Ahat f y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Ahat] THEN
  MP_TAC(ISPECL
   [`{ inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))
     | a <= b }`;
    `&0:real`;
    `B:real`;
    `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[y,y]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
              x)))`]
   REAL_LE_SUP) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`y:real`; `y:real`] THEN REWRITE_TAC[REAL_LE_REFL];
    MATCH_MP_TAC REAL_LE_MUL THEN
    SIMP_TAC[REAL_LE_INV_EQ; NORM_POS_LE; SQRT_POS_LE; REAL_LE_MUL; REAL_POS;
             PI_POS_LE; REAL_LT_IMP_LE];
    X_GEN_TAC `w:real` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_SIMP_TAC[]]);;

(* --- 286U(a) existence criterion (Fremlin mt286.tex 2960-2975): the        *)
(* abstract                                                                  *)
(* Cauchy test for the improper truncated-integral limit.  If the truncated  *)
(* integrals II a b (= (1/sqrt2pi) int_[a,b] e^{-ixy}f, but stated           *)
(* abstractly)                                                               *)
(* are "tail-Cauchy" -- for each e>0 some symmetric window [-N,N] captures   *)
(* all                                                                       *)
(* wider windows within e -- then the symmetric sequence II(-n)(n)           *)
(* converges.                                                                *)
(* This is exactly Fremlin's "inf_n gamma_n(y)=0 ==> g(y) defined"; pure     *)
(* completeness of C (CONVERGENT_EQ_CAUCHY), no dependence on the 286T       *)
(* bound. ---                                                                *)
let CARLESON_286U_CAUCHY = prove
 (`!(II:real->real->complex).
     (!e. &0 < e ==> ?N. &0 <= N /\
          !a b. a <= --N /\ N <= b ==> norm(II a b - II (--N) N) <= e)
     ==> ?z. ((\n. II (--(&n)) (&n)) --> z) sequentially`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ISPEC `\n. (II:real->real->complex) (--(&n)) (&n)`
    CONVERGENT_EQ_CAUCHY] THEN
  REWRITE_TAC[cauchy] THEN
  X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e / &3`) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN
    `N:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "H"))) THEN
  MP_TAC(ISPEC `N:real` REAL_ARCH_SIMPLE) THEN
  DISCH_THEN(X_CHOOSE_TAC `M:num`) THEN
  EXISTS_TAC `M:num` THEN
  MAP_EVERY X_GEN_TAC [`p:num`; `q:num`] THEN REWRITE_TAC[GE] THEN
    STRIP_TAC THEN
  REWRITE_TAC[] THEN
  MP_TAC(ISPECL
   [`(II:real->real->complex) (--(&p)) (&p)`;
    `(II:real->real->complex) (--(&q)) (&q)`;
    `(II:real->real->complex) (--N) N`; `e:real`]
   (NORM_ARITH
    `!sp sq c e.
       &0 < e /\ norm(sp - c) <= e / &3 /\ norm(sq - c) <= e / &3
       ==> dist(sp:complex,sq) < e`)) THEN
  ANTS_TAC THENL [ALL_TAC; REWRITE_TAC[]] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THEN USE_THEN "H" MATCH_MP_TAC THEN
  REWRITE_TAC[REAL_LE_NEG2] THEN REPEAT CONJ_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&M:real` THEN
  ASM_REWRITE_TAC[REAL_OF_NUM_LE] THEN ASM_ARITH_TAC);;

(* --- 286U(a) symmetric real limit: the same tail-Cauchy hypothesis gives   *)
(* the                                                                       *)
(* symmetric REAL-parameter net (\a. II(-a) a) -> z at_posinfinity (not just *)
(* the integer sequence).  This is the exact shape Fremlin 286V consumes:    *)
(* g(y) = lim_{a->inf} (1/sqrt2pi) int_{-a}^a e^{-ixy}. Proof: z from        *)
(* CARLESON_                                                                 *)
(* 286U_CAUCHY, then for x>=N a 3-eps triangle (window [-x,x] vs [-N,N] vs a *)
(* sequence point n0=K+Mn beyond both K and N) closes dist(II(-x)x,z)<e. --- *)
let CARLESON_286U_SYMLIM = prove
 (`!(II:real->real->complex).
     (!e. &0 < e ==> ?N. &0 <= N /\
          !a b. a <= --N /\ N <= b ==> norm(II a b - II (--N) N) <= e)
     ==> ?z. ((\a. II (--a) a) --> z) at_posinfinity`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `z:complex` o MATCH_MP CARLESON_286U_CAUCHY) THEN
  EXISTS_TAC `z:complex` THEN
  REWRITE_TAC[LIM_AT_POSINFINITY] THEN
  X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `e / &3` o check(fun th -> is_forall(concl th)))
    THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN
    `N:real` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "H"))) THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [LIM_SEQUENTIALLY]) THEN
  DISCH_THEN(MP_TAC o SPEC `e / &3`) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `K:num` (LABEL_TAC "Kseq")) THEN
  MP_TAC(ISPEC `N:real` REAL_ARCH_SIMPLE) THEN
  DISCH_THEN(X_CHOOSE_TAC `Mn:num`) THEN
  EXISTS_TAC `N:real` THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[real_ge] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `N <= &(K + Mn)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&Mn:real` THEN
    ASM_REWRITE_TAC[REAL_OF_NUM_LE] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `dist((II:real->real->complex) (-- &(K+Mn)) (&(K+Mn)),z) < e / &3`
   ASSUME_TAC THENL
   [USE_THEN "Kseq" (MP_TAC o SPEC `K + Mn:num`) THEN
    REWRITE_TAC[LE_ADD] THEN BETA_TAC THEN REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `norm((II:real->real->complex) (--(&(K+Mn))) (&(K+Mn)) - II (--N) N) <= e /
     &3`
   ASSUME_TAC THENL
   [USE_THEN "H" MATCH_MP_TAC THEN ASM_REWRITE_TAC[REAL_LE_NEG2]; ALL_TAC] THEN
  SUBGOAL_THEN `norm((II:real->real->complex) (--x) x - II (--N) N) <= e / &3`
   ASSUME_TAC THENL
   [USE_THEN "H" MATCH_MP_TAC THEN ASM_REWRITE_TAC[REAL_LE_NEG2]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(II:real->real->complex) (--x) x`;
    `(II:real->real->complex) (--(&(K+Mn))) (&(K+Mn))`;
    `(II:real->real->complex) (--N) N`; `z:complex`; `e:real`]
   (NORM_ARITH
    `!sx sk c z e.
       norm(sx - c) <= e / &3 /\ norm(sk - c) <= e / &3 /\ dist(sk:complex,z) <
         e / &3
       ==> dist(sx:complex,z) < e`)) THEN
  ASM_REWRITE_TAC[]);;

(* --- 286V sinc bridge (Fremlin mt286.tex 3078): the Fourier transform of   *)
(* the                                                                       *)
(* truncated exponential h_ax(y) = e^{ixy} chi_[-a,a](y) is the sinc kernel  *)
(* hat-h_ax(t) = (1/sqrt2pi) 2 sin((x-t)a)/(x-t).  This is the exact factor  *)
(* converting <g|h_ax> = <f_2|hat-h_ax> into (2/sqrt2pi) int                 *)
(* sin((x-t)a)/(x-t)f.                                                       *)
(* Reduces the fourier integral over (:real^1) to CEXP_INTERVAL_INTEGRAL via *)
(* INTEGRAL_RESTRICT_UNIV (indicator = interval) after fusing the two        *)
(* cexp's. ---                                                               *)
let CARLESON_TRUNC_AS_FOURIER = prove
 (`!(f:real->complex) a b z.
     integral (IMAGE lift (real_interval[a,b]))
       (\x. cexp(--(ii * Cx(drop z) * Cx(drop x))) * f(drop x)) =
     Cx(sqrt(&2 * pi)) *
     fourier (\x. if x IN real_interval[a,b] then (f:real->complex) x else
       Cx(&0)) (drop z)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[fourier] THEN
  SUBGOAL_THEN
   `integral (:real^1)
      (\x. cexp(--(ii * Cx(drop z) * Cx(drop x))) *
           (if drop x IN real_interval[a,b] then (f:real->complex)(drop x) else
             Cx(&0))) =
    integral (IMAGE lift (real_interval[a,b]))
      (\x. cexp(--(ii * Cx(drop z) * Cx(drop x))) * f(drop x))`
   ASSUME_TAC THENL
   [GEN_REWRITE_TAC (RAND_CONV) [GSYM INTEGRAL_RESTRICT_UNIV] THEN
    REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN MATCH_MP_TAC INTEGRAL_EQ THEN
    X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[IN_INTERVAL_1; IN_REAL_INTERVAL; LIFT_DROP] THEN
    COND_CASES_TAC THEN REWRITE_TAC[COMPLEX_MUL_RZERO; COMPLEX_VEC_0];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `~(Cx(sqrt(&2 * pi)) = Cx(&0))` MP_TAC THENL
   [REWRITE_TAC[CX_INJ] THEN MATCH_MP_TAC REAL_LT_IMP_NZ THEN
    MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN REAL_ARITH_TAC;
    CONV_TAC COMPLEX_FIELD]);;

let CARLESON_TRUNC_FOURIER_CONTINUOUS = prove
 (`!(f:real->complex) a b.
     (\z. f(drop z)) absolutely_integrable_on (:real^1)
     ==> (\z:real^1. integral (IMAGE lift (real_interval[a,b]))
                (\x. cexp(--(ii * Cx(drop z) * Cx(drop x))) * f(drop x)))
         continuous_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[CARLESON_TRUNC_AS_FOURIER] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_LMUL THEN
  MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN
  BETA_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. if drop z IN real_interval[a,b] then (f:real->complex)(drop z)
     else Cx(&0)) =
    (\z:real^1. if z IN interval[lift a, lift b] then f(drop z) else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real^1` THEN
    REWRITE_TAC[IN_INTERVAL_1; IN_REAL_INTERVAL; LIFT_DROP; COMPLEX_VEC_0];
    ALL_TAC] THEN
  REWRITE_TAC[ABSOLUTELY_INTEGRABLE_RESTRICT_UNIV] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
  EXISTS_TAC `(:real^1)` THEN ASM_REWRITE_TAC[SUBSET_UNIV]);;

(* --- 286T(a) window continuity: each truncated-window modulus              *)
(* y |-> inv(sqrt2pi) norm(int_[a,b] e^{-ixy}f) is real-continuous in the    *)
(* frequency y (for f absolutely integrable). This is the per-window         *)
(* hypothesis                                                                *)
(* that REAL_MEASURABLE_ON_SUP_CONTINUOUS needs for Ahat = sup over windows. *)
(* Chain: CARLESON_TRUNC_FOURIER_CONTINUOUS (complex integral continuous in  *)
(* y)                                                                        *)
(* -> lift-norm compose -> real_continuous_atreal; scalar via                *)
(* REAL_CONTINUOUS_                                                          *)
(* LMUL.                                                                     *)
let CARLESON_AHAT_WINDOW_CONTINUOUS = prove
 (`!(f:real->complex) a b y.
     (\z. f(drop z)) absolutely_integrable_on (:real^1)
     ==> (\y. inv(sqrt(&2 * pi)) *
              norm(integral (IMAGE lift (real_interval[a,b]))
                     (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))))
         real_continuous atreal y`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_CONTINUOUS_LMUL THEN
  REWRITE_TAC[REAL_CONTINUOUS_CONTINUOUS_ATREAL; o_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_LIFT_NORM_COMPOSE THEN
  MP_TAC(ISPECL [`f:real->complex`; `a:real`; `b:real`]
    CARLESON_TRUNC_FOURIER_CONTINUOUS) THEN
  ASM_REWRITE_TAC[] THEN
  SIMP_TAC[CONTINUOUS_ON_EQ_CONTINUOUS_AT; OPEN_UNIV; IN_UNIV]);;

(* --- 286U(b) gamma_n window-difference continuity: y |-> inv(sqrt2pi) norm *)
(* (int_[a,b] e^{-ixy}f - int_[-n,n] e^{-ixy}f) is real-continuous in y.     *)
(* This                                                                      *)
(* is the per-window hypothesis for gamma_n measurability (gamma_n = sup     *)
(* over the                                                                  *)
(* window-difference family, each continuous).  Same chain as CARLESON_AHAT_ *)
(* WINDOW_CONTINUOUS but with CONTINUOUS_SUB on the two truncated integrals. *)
(* ---                                                                       *)
let CARLESON_AHAT_REINDEX = prove
 (`!(f:real->complex) y.
     carleson_Ahat f y =
     sup { (\p. inv(sqrt(&2 * pi)) *
                norm(integral (IMAGE lift (real_interval[FST p,SND p]))
                       (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))) p
         | p IN {p:real#real | FST p <= SND p} }`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_Ahat] THEN
  AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
  REWRITE_TAC[EXISTS_IN_GSPEC; IN_ELIM_THM] THEN
  EQ_TAC THEN STRIP_TAC THENL
   [EXISTS_TAC `(a:real,b:real)` THEN ASM_REWRITE_TAC[FST; SND];
    MAP_EVERY EXISTS_TAC [`FST(p:real#real)`; `SND(p:real#real)`] THEN
    ASM_REWRITE_TAC[]]);;

(* --- 286T(a): the Carleson maximal operator Ahat f is real-measurable,     *)
(* given                                                                     *)
(* it is pointwise bounded above (a.e.-finiteness -- honest per the [0,inf]  *)
(* framing: off the null set where Af=+inf, and there the 286T integral      *)
(* bound                                                                     *)
(* supplies finiteness).  Assembles CARLESON_AHAT_REINDEX + per-window       *)
(* continuity (CARLESON_AHAT_WINDOW_CONTINUOUS) + REAL_MEASURABLE_ON_SUP_    *)
(* CONTINUOUS. ---                                                           *)
let CARLESON_AHAT_MEASURABLE = prove
 (`!(f:real->complex).
     (\z. f(drop z)) absolutely_integrable_on (:real^1) /\
     (!y. ?B. !a b. a <= b
             ==> inv(sqrt(&2 * pi)) *
                 norm(integral (IMAGE lift (real_interval[a,b]))
                        (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <=
                          B)
     ==> (carleson_Ahat f) real_measurable_on (:real)`,
  GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `carleson_Ahat f =
    (\y. sup { (\p. inv(sqrt(&2 * pi)) *
                norm(integral (IMAGE lift (real_interval[FST p,SND p]))
                       (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                         (f:real->complex)(drop x)))) p
             | p IN {p:real#real | FST p <= SND p} })`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[CARLESON_AHAT_REINDEX];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_SUP_CONTINUOUS THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `p:real#real` THEN
     DISCH_TAC THEN
    X_GEN_TAC `y:real` THEN BETA_TAC THEN
    MP_TAC(ISPECL [`f:real->complex`; `FST(p:real#real)`; `SND(p:real#real)`;
      `y:real`]
      CARLESON_AHAT_WINDOW_CONTINUOUS) THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `y:real` THEN
    FIRST_X_ASSUM(X_CHOOSE_TAC `B:real` o SPEC `y:real`) THEN
    EXISTS_TAC `B:real` THEN
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `p:real#real` THEN
      DISCH_TAC THEN
    BETA_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`FST(p:real#real)`; `SND(p:real#real)`] o
      check(fun th -> is_forall(concl th) &&
                      can (find_term (fun t -> t = `B:real`)) (concl th))) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    EXISTS_TAC `(&0,&0):real#real` THEN REWRITE_TAC[FST; SND; REAL_LE_REFL]]);;

(* --- 286U(b) domination atom: each truncated-window modulus is <= Ahat f y *)
(* (given the family bounded above). This is the "each tail is an f_1-window *)
(* <= Ahat f_1" step of Fremlin's gamma_n <= 2 Ahat f_1 (mt286.tex           *)
(* 3006-3010).                                                               *)
(* Member-<=-sup via REAL_LE_SUP (explicit ISPECL with fresh comprehension   *)
(* vars                                                                      *)
(* a'',b'' to avoid clashing with the goal's a,b). ---                       *)
let CARLESON_AHAT_WINDOW_LE = prove
 (`!(f:real->complex) y a b.
     a <= b /\
     (?B. !a' b'. a' <= b' ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a',b']))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <= B)
     ==> inv(sqrt(&2 * pi)) *
         norm(integral (IMAGE lift (real_interval[a,b]))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
         <= carleson_Ahat f y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[carleson_Ahat] THEN
  MP_TAC(ISPECL
   [`{ inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a'',b'']))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))
     | a'' <= b'' }`;
    `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
              x)))`;
    `B:real`;
    `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
              x)))`]
   REAL_LE_SUP) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_REFL];
    REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_SIMP_TAC[]]);;

(* --- 286U(b) difference-of-windows identity: for [-n,n] SUBSET [a,b], the  *)
(* gamma_n difference int_[a,b] e^{-ixy}f - int_[-n,n] e^{-ixy}f collapses   *)
(* to a                                                                      *)
(* SINGLE f_1-window integral int_[a,b] e^{-ixy}f_1, where f_1 = f off       *)
(* [-n,n],                                                                   *)
(* 0 on it (Fremlin's f_1 = f - f.chi[-n,n]). Integrand rewrite e*f_1 = e*f  *)
(* -                                                                         *)
(* (chi[-n,n]-restricted e*f) + INTEGRAL_SUB + INTEGRAL_RESTRICT;            *)
(* integrability                                                             *)
(* via FOURIER_MODULATION_ABSINT (@fourier_inversion.ml) on subintervals.    *)
(* ---                                                                       *)
let carleson_gamma = new_definition
 `carleson_gamma (f:real->complex) n y =
    sup { inv(sqrt(&2 * pi)) *
          norm(integral (IMAGE lift (real_interval[a,b]))
                 (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)) -
               integral (IMAGE lift (real_interval[--n,n]))
                 (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
        | a,b | a <= --n /\ n <= b }`;;

(* --- 286U(b) gamma_n measurability: y |-> carleson_gamma f n y is real-    *)
(* measurable, given &0<=n and the window-difference family bounded above at *)
(* each y (a.e.-finiteness of gamma_n). LSC route (REAL_MEASURABLE_ON_LSC):  *)
(* the                                                                       *)
(* superlevel set [gamma_n y > c] = UNIONS over window pairs (a,b) of the    *)
(* sets                                                                      *)
(* diff(a,b,y)>c} (SUP_2BAR_SUPERLEVEL), each open (REAL_OPEN_SUPERLEVEL_    *)
(* CONTINUOUS + CARLESON_GAMMA_WINDOW_CONTINUOUS), union open                *)
(* (REAL_OPEN_UNIONS). ---                                                   *)
let CARLESON_LSPACE2_LOCAL_ABSINT = prove
 (`!(f:real->complex) a b.
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> (\z. f(drop z)) absolutely_integrable_on (IMAGE lift
       (real_interval[a,b]))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[GSYM LSPACE_1] THEN
  MATCH_MP_TAC LSPACE_MONO THEN EXISTS_TAC `&2:real` THEN
  REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC LSPACE_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV; IMAGE_LIFT_REAL_INTERVAL;
                    LEBESGUE_MEASURABLE_INTERVAL];
    REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN REAL_ARITH_TAC]);;

(* L^2 truncated-integral continuity in the frequency y (compact window)     *)
let CARLESON_TRUNC_FOURIER_CONTINUOUS_L2 = prove
 (`!(f:real->complex) a b.
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> (\z:real^1. integral (IMAGE lift (real_interval[a,b]))
                (\x. cexp(--(ii * Cx(drop z) * Cx(drop x))) * f(drop x)))
         continuous_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[CARLESON_TRUNC_AS_FOURIER] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_LMUL THEN
  MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN
  BETA_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. if drop z IN real_interval[a,b] then (f:real->complex)(drop z)
     else Cx(&0)) =
    (\z:real^1. if z IN interval[lift a, lift b] then f(drop z) else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real^1` THEN
    REWRITE_TAC[IN_INTERVAL_1; IN_REAL_INTERVAL; LIFT_DROP; COMPLEX_VEC_0];
    ALL_TAC] THEN
  REWRITE_TAC[ABSOLUTELY_INTEGRABLE_RESTRICT_UNIV] THEN
  REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
  MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN ASM_REWRITE_TAC[]);;

(* L^2 gamma_n window-difference continuity                                  *)
let FOURIER_MODULATION_ABSINT_ON = prove
 (`!(f:real->complex) d s.
     measurable s /\ (\z. f(drop z)) absolutely_integrable_on s
     ==> (\y. cexp(--(ii * Cx d * Cx(drop y))) * f(drop y))
       absolutely_integrable_on s`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`( * ):complex->complex->complex`;
                 `\y:real^1. cexp(--(ii * Cx d * Cx(drop y)))`;
                 `\y:real^1. (f:real->complex)(drop y)`; `s:real^1->bool`]
    ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT) THEN
  ASM_REWRITE_TAC[BILINEAR_COMPLEX_MUL] THEN DISCH_THEN MATCH_MP_TAC THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_MEASURABLE_SUBSET THEN
     EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    SUBGOAL_THEN `(\y:real^1. cexp(--(ii * Cx d * Cx(drop y)))) =
                  cexp o (\y. --((ii * Cx d) * Cx(drop y)))`
     SUBST1_TAC THENL [REWRITE_TAC[o_DEF; COMPLEX_MUL_ASSOC]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_CEXP] THEN
    MATCH_MP_TAC CONTINUOUS_ON_NEG THEN
      MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
      MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN
    REWRITE_TAC[CONTINUOUS_ON_ID];
    REWRITE_TAC[bounded; FORALL_IN_IMAGE] THEN EXISTS_TAC `&1` THEN
    X_GEN_TAC `y:real^1` THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `--(ii * Cx d * Cx(drop y)) = ii * Cx(--(d * drop y))` SUBST1_TAC THENL
     [REWRITE_TAC[CX_NEG; CX_MUL] THEN SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[NORM_CEXP_II] THEN REAL_ARITH_TAC]);;

(* L^2 window-difference collapse.                                           *)
let CARLESON_WINDOW_DIFF_L2 = prove
 (`!(f:real->complex) y n a b.
     a <= --n /\ n <= b /\
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> integral (IMAGE lift (real_interval[a,b]))
           (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                (if abs(drop x) <= n then Cx(&0) else f(drop x))) =
         integral (IMAGE lift (real_interval[a,b]))
           (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)) -
         integral (IMAGE lift (real_interval[--n,n]))
           (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
  SUBGOAL_THEN
   `(\x:real^1. cexp(--(ii * Cx y * Cx(drop x))) *
        (if abs(drop x) <= n then Cx(&0) else (f:real->complex)(drop x))) =
    (\x:real^1. (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)) x -
        (if x IN interval[lift(--n),lift n]
         then (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)) x else vec
           0))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real^1` THEN
    REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP] THEN
    REWRITE_TAC[REAL_ARITH `--n <= drop w /\ drop w <= n <=> abs(drop w) <= n`]
      THEN
    COND_CASES_TAC THEN
    REWRITE_TAC[COMPLEX_MUL_RZERO; COMPLEX_SUB_RZERO; COMPLEX_VEC_0] THEN
    SIMPLE_COMPLEX_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x:real^1. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x))
    integrable_on interval[lift a, lift b]`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
    MATCH_MP_TAC FOURIER_MODULATION_ABSINT_ON THEN
    REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL] THEN
    REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
    MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `interval[lift(--n),lift n] SUBSET interval[lift a, lift b]`
   ASSUME_TAC THENL
   [REWRITE_TAC[SUBSET_INTERVAL_1; LIFT_DROP] THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x:real^1. if x IN interval[lift(--n),lift n]
         then cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x) else
           vec 0)
    integrable_on interval[lift a, lift b]`
   ASSUME_TAC THENL
   [ASM_SIMP_TAC[INTEGRABLE_RESTRICT] THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
    MATCH_MP_TAC FOURIER_MODULATION_ABSINT_ON THEN
    REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL] THEN
    REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
    MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  W(MP_TAC o PART_MATCH (lhs o rand) INTEGRAL_SUB o lhand o snd) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  AP_TERM_TAC THEN MATCH_MP_TAC INTEGRAL_RESTRICT THEN ASM_REWRITE_TAC[]);;

(* f_1 = f off [-n,n] stays in L^2 (LSPACE_SUB + TRUNC_IN_LSPACE).           *)
let CARLESON_TRUNC_LSPACE2 = prove
 (`!(f:real->complex) n.
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> (\z. if abs(drop z) <= n then Cx(&0) else f(drop z))
         IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. if abs(drop z) <= n then Cx(&0) else (f:real->complex)(drop z))
     =
    (\z:real^1. f(drop z) -
        (if z IN interval[lift(--n),lift n] then f(drop z) else vec 0))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real^1` THEN
    REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP;
      REAL_ARITH `--n <= drop w /\ drop w <= n <=> abs(drop w) <= n`] THEN
    COND_CASES_TAC THEN
    REWRITE_TAC[COMPLEX_SUB_RZERO; COMPLEX_VEC_0] THEN CONV_TAC COMPLEX_RING;
    ALL_TAC] THEN
  MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_POS] THEN
  MATCH_MP_TAC TRUNC_IN_LSPACE THEN
  ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`; LEBESGUE_MEASURABLE_INTERVAL]);;

(* L^2 gamma_n <= Ahat f_1 (sup over the window differences).                *)
let GAMMA_N_LE_AHAT_L2 = prove
 (`!(f:real->complex) y n.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ &0 <= n /\
     (?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                         (if abs(drop x) <= n then Cx(&0) else f(drop x)))) <=
                           B)
     ==> sup { inv(sqrt(&2 * pi)) *
               norm(integral (IMAGE lift (real_interval[a,b]))
                      (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)) -
                    integral (IMAGE lift (real_interval[--n,n]))
                      (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
             | a,b | a <= --n /\ n <= b }
         <= carleson_Ahat (\t. if abs t <= n then Cx(&0) else f t) y`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `B:real`))) THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC
     `inv(sqrt(&2 * pi)) *
      norm(integral (IMAGE lift (real_interval[--n,n]))
             (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x))
               -
           integral (IMAGE lift (real_interval[--n,n]))
             (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))` THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC [`--n:real`; `n:real`] THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[IN_ELIM_THM] THEN
    X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
      `b:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`f:real->complex`; `y:real`; `n:real`; `a:real`; `b:real`]
      CARLESON_WINDOW_DIFF_L2) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    MP_TAC(ISPECL
     [`\t. if abs t <= n then Cx(&0) else (f:real->complex) t`;
      `y:real`; `a:real`; `b:real`] CARLESON_AHAT_WINDOW_LE) THEN
    REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      EXISTS_TAC `B:real` THEN ASM_REWRITE_TAC[]]]);;

(* L^2 carleson_gamma <= Ahat f_1 (named form).                              *)
let CARLESON_GAMMA_LE_AHAT_L2 = prove
 (`!(f:real->complex) y n.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ &0 <= n /\
     (?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                         (if abs(drop x) <= n then Cx(&0) else f(drop x)))) <=
                           B)
     ==> carleson_gamma f n y
         <= carleson_Ahat (\t. if abs t <= n then Cx(&0) else f t) y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_gamma] THEN
  MATCH_ACCEPT_TAC GAMMA_N_LE_AHAT_L2);;

(* L^2 lower bound e*muF <= int_F Ahat f_1 (Chebyshev via the pointwise      *)
(* bound).                                                                   *)
let carleson_Ahat_trunc = new_definition
 `carleson_Ahat_trunc (f:real->complex) (n:real) (y:real) =
    sup { inv(sqrt(&2 * pi)) *
          norm(integral (IMAGE lift (real_interval[a,b]))
                 (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
        | a,b | --n <= a /\ a <= b /\ b <= n }`;;

(* Each compact window integral (|y|-modulated) is bounded in norm by the    *)
(* full-interval integral of |f| (cexp unimodular + monotonicity of int|.|). *)
let CARLESON_TRUNC_WINDOW_LE_INT = prove
 (`!(f:real->complex) n y a b.
     --n <= a /\ a <= b /\ b <= n /\
     (\z. f(drop z)) absolutely_integrable_on (IMAGE lift
       (real_interval[--n,n]))
     ==> norm(integral (IMAGE lift (real_interval[a,b]))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
         <= drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
           lift(norm(f(drop x)))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (f:real->complex)(drop z)) absolutely_integrable_on
    (IMAGE lift (real_interval[a,b]))`
   ASSUME_TAC THENL
   [REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `IMAGE lift (real_interval[--n,n])` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; SUBSET_INTERVAL_1; LIFT_DROP] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `drop(integral (IMAGE lift (real_interval[a,b])) (\x.
    lift(norm((f:real->complex)(drop x)))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRAL_NORM_BOUND_INTEGRAL THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC FOURIER_MODULATION_ABSINT_ON THEN
      ASM_REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
        REWRITE_TAC[LIFT_DROP; COMPLEX_NORM_MUL] THEN
      MATCH_MP_TAC REAL_LE_TRANS THEN
        EXISTS_TAC `&1 * norm((f:real->complex)(drop w))` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
        SUBGOAL_THEN
          `--(ii * Cx y * Cx(drop w)) =
           ii * Cx(--(y * drop w))` SUBST1_TAC THENL
         [REWRITE_TAC[CX_NEG; CX_MUL] THEN
           SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[NORM_CEXP_II] THEN REAL_ARITH_TAC;
        REWRITE_TAC[REAL_MUL_LID; REAL_LE_REFL]]];
    MATCH_MP_TAC INTEGRAL_SUBSET_DROP_LE THEN
    REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[SUBSET_INTERVAL_1; LIFT_DROP] THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      ASM_REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      ASM_REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL];
      X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
        REWRITE_TAC[LIFT_DROP; NORM_POS_LE]]]);;

(* Ahat_n f is a genuine finite sup: bounded above by (1/sqrt2pi)            *)
(* int_[-n,n]|f|,                                                            *)
(* UNCONDITIONALLY (only f loc-L^1 on [-n,n]). No ?B / a.e.-finiteness       *)
(* needed.                                                                   *)
let CARLESON_AHAT_TRUNC_FINITE = prove
 (`!(f:real->complex) n y.
     &0 <= n /\
     (\z. f(drop z)) absolutely_integrable_on (IMAGE lift
       (real_interval[--n,n]))
     ==> carleson_Ahat_trunc f n y
         <= inv(sqrt(&2 * pi)) *
            drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
              lift(norm(f(drop x)))))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Ahat_trunc] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[--n,n]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`;
      `--n:real`; `n:real`] THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
      `b:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
      MP_TAC PI_POS THEN REAL_ARITH_TAC;
      MATCH_MP_TAC CARLESON_TRUNC_WINDOW_LE_INT THEN ASM_REWRITE_TAC[]]]);;

(* Per-window L^2 continuity in y (single compact window [a,b]): the norm of *)
(* the                                                                       *)
(* truncated modulated integral is real-continuous.  = CARLESON_AHAT_WINDOW_ *)
(* CONTINUOUS but under the L^2 hypothesis (via _CONTINUOUS_L2).             *)
let CARLESON_AHAT_WINDOW_CONTINUOUS_L2 = prove
 (`!(f:real->complex) a b y.
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> (\y. inv(sqrt(&2 * pi)) *
              norm(integral (IMAGE lift (real_interval[a,b]))
                     (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))))
         real_continuous atreal y`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_CONTINUOUS_LMUL THEN
  REWRITE_TAC[REAL_CONTINUOUS_CONTINUOUS_ATREAL; o_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_LIFT_NORM_COMPOSE THEN
  MP_TAC(ISPECL [`f:real->complex`; `a:real`; `b:real`]
    CARLESON_TRUNC_FOURIER_CONTINUOUS_L2) THEN
  ASM_REWRITE_TAC[] THEN
  SIMP_TAC[CONTINUOUS_ON_EQ_CONTINUOUS_AT; OPEN_UNIV; IN_UNIV]);;

(* Ahat_n f is real-measurable in y, UNCONDITIONALLY (LSC route: the         *)
(* compact-range sup of continuous window-moduli; bounded above by           *)
(* TRUNC_WINDOW_LE_INT so the sup is genuine, no ?B hypothesis).             *)
let CARLESON_AHAT_TRUNC_MEASURABLE = prove
 (`!(f:real->complex) n.
     &0 <= n /\
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> (\y. carleson_Ahat_trunc f n y) real_measurable_on (:real)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (f:real->complex)(drop z)) absolutely_integrable_on
    (IMAGE lift (real_interval[--n,n]))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_LSC THEN
  X_GEN_TAC `c:real` THEN REWRITE_TAC[carleson_Ahat_trunc] THEN
  SUBGOAL_THEN
   `{y | sup { inv(sqrt(&2 * pi)) *
               norm(integral (IMAGE lift (real_interval[a,b]))
                      (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                        (f:real->complex)(drop x)))
             | a,b | --n <= a /\ a <= b /\ b <= n } > c} =
    UNIONS { {y | inv(sqrt(&2 * pi)) *
               norm(integral (IMAGE lift (real_interval[a,b]))
                      (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                        (f:real->complex)(drop x))) > c}
           | a,b | --n <= a /\ a <= b /\ b <= n }`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_UNIONS; IN_ELIM_THM] THEN X_GEN_TAC `y:real` THEN
    REWRITE_TAC[real_gt] THEN
    MP_TAC(ISPECL
     [`\a b. inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                      (f:real->complex)(drop x)))`;
      `\a b. --n <= a /\ a <= b /\ b <= n`; `c:real`] SUP_2BAR_SUPERLEVEL) THEN
    REWRITE_TAC[] THEN ANTS_TAC THENL
     [CONJ_TAC THENL
       [MAP_EVERY EXISTS_TAC [`--n:real`; `n:real`] THEN ASM_REAL_ARITH_TAC;
        EXISTS_TAC
         `inv(sqrt(&2 * pi)) *
          drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
            lift(norm((f:real->complex)(drop x)))))` THEN
        MAP_EVERY X_GEN_TAC [`a:real`; `b:real`] THEN STRIP_TAC THEN
        MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
          MP_TAC PI_POS THEN REAL_ARITH_TAC;
          MATCH_MP_TAC CARLESON_TRUNC_WINDOW_LE_INT THEN ASM_REWRITE_TAC[]]];
      DISCH_THEN SUBST1_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
       `b:real` STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC
       `{u | c < inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx u * Cx(drop x))) *
                      (f:real->complex)(drop x)))}` THEN
      CONJ_TAC THENL
       [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN
         ASM_REWRITE_TAC[IN_ELIM_THM];
        ASM_REWRITE_TAC[IN_ELIM_THM]];
      DISCH_THEN(X_CHOOSE_THEN `t:real->bool` STRIP_ASSUME_TAC) THEN
      MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[]];
    MATCH_MP_TAC REAL_OPEN_UNIONS THEN
    REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `s:real->bool` THEN
    DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN `b:real` (CONJUNCTS_THEN2
       ASSUME_TAC SUBST1_TAC))) THEN
    MATCH_MP_TAC REAL_OPEN_SUPERLEVEL_CONTINUOUS THEN
    GEN_TAC THEN MATCH_MP_TAC CARLESON_AHAT_WINDOW_CONTINUOUS_L2 THEN
      ASM_REWRITE_TAC[]]);;

(* Ahat_n f y >= 0 (the [-n,n] window member is >= 0 and witnesses the sup). *)
let CARLESON_AHAT_TRUNC_POS = prove
 (`!(f:real->complex) n y.
     &0 <= n /\ (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> &0 <= carleson_Ahat_trunc f n y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (f:real->complex)(drop z)) absolutely_integrable_on
    (IMAGE lift (real_interval[--n,n]))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[carleson_Ahat_trunc] THEN
  MP_TAC(ISPECL
   [`{ inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))
     | a,b | --n <= a /\ a <= b /\ b <= n }`;
    `&0:real`;
    `inv(sqrt(&2 * pi)) *
     drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
       lift(norm((f:real->complex)(drop x)))))`;
    `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[--n,n]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
              x)))`]
   REAL_LE_SUP) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`--n:real`; `n:real`] THEN ASM_REWRITE_TAC[] THEN
    ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_LE_MUL THEN
    SIMP_TAC[REAL_LE_INV_EQ; NORM_POS_LE; SQRT_POS_LE; REAL_LE_MUL; REAL_POS;
             PI_POS_LE; REAL_LT_IMP_LE];
    X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
      `b:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
      MP_TAC PI_POS THEN REAL_ARITH_TAC;
      MATCH_MP_TAC CARLESON_TRUNC_WINDOW_LE_INT THEN ASM_REWRITE_TAC[]]]);;

(* Ahat_n f is increasing in n: the window range [-m,m] sits inside [-n,n]   *)
(* (m<=n), so the Ahat_m sup-set is a subset of the Ahat_n sup-set.          *)
let CARLESON_AHAT_TRUNC_MONO = prove
 (`!(f:real->complex) m n y.
     &0 <= m /\ m <= n /\ (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> carleson_Ahat_trunc f m y <= carleson_Ahat_trunc f n y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (f:real->complex)(drop z)) absolutely_integrable_on
    (IMAGE lift (real_interval[--n,n]))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[carleson_Ahat_trunc] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[--m,m]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`;
      `--m:real`; `m:real`] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
      `b:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL
     [`{ inv(sqrt(&2 * pi)) *
         norm(integral (IMAGE lift (real_interval[a',b']))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                  x)))
       | a',b' | --n <= a' /\ a' <= b' /\ b' <= n }`;
      `inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`;
      `inv(sqrt(&2 * pi)) *
       drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
         lift(norm((f:real->complex)(drop x)))))`;
      `inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`]
     REAL_LE_SUP) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
    REPEAT CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_LE_REFL];
      X_GEN_TAC `w':real` THEN
      DISCH_THEN(X_CHOOSE_THEN `a2:real` (X_CHOOSE_THEN
        `b2:real` STRIP_ASSUME_TAC)) THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
        MP_TAC PI_POS THEN REAL_ARITH_TAC;
        MATCH_MP_TAC CARLESON_TRUNC_WINDOW_LE_INT THEN ASM_REWRITE_TAC[]]]]);;

(* L^2 norm of the constant function 1 on a compact interval = sqrt(length). *)
let LNORM2_CONST1 = prove
 (`!a b. a <= b
     ==> lnorm (IMAGE lift (real_interval[a,b])) (&2) (\z:real^1. Cx(&1)) =
       sqrt(b - a)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lnorm] THEN
  REWRITE_TAC[COMPLEX_NORM_CX; REAL_ABS_NUM] THEN
  REWRITE_TAC[RPOW_ONE; LIFT_NUM] THEN
  SUBGOAL_THEN
   `integral (IMAGE lift (real_interval[a,b])) (\x:real^1. vec 1:real^1) =
     lift(b - a)`
   SUBST1_TAC THENL
   [REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; INTEGRAL_CONST] THEN
    ASM_SIMP_TAC[CONTENT_1; LIFT_DROP] THEN
    REWRITE_TAC[GSYM LIFT_NUM; GSYM LIFT_CMUL; REAL_MUL_RID];
    REWRITE_TAC[LIFT_DROP] THEN
    SUBGOAL_THEN `inv(&2) = &1 / &2` SUBST1_TAC THENL
     [REAL_ARITH_TAC;
      MATCH_MP_TAC RPOW_SQRT THEN ASM_REAL_ARITH_TAC]]);;

(* --- 286T(c) Cauchy-Schwarz window bound (Fremlin 2933): the modulated     *)
(* window                                                                    *)
(* integral over a compact [a,b] is <= sqrt(b-a) * ||g||_{L^2[a,b]}.  Route: *)
(* norm(int_[a,b] e^{-ixy}g) <= int_[a,b]|g| (cexp unimodular;               *)
(* INTEGRAL_NORM_BOUND)                                                      *)
(* = int_[a,b] |1|*|g| <= ||1||_{L^2} ||g||_{L^2} (HOELDER p=q=2),           *)
(* ||1||=sqrt(b-a).                                                          *)
let CARLESON_WINDOW_CAUCHY_SCHWARZ = prove
 (`!(g:real->complex) a b y.
     a <= b /\ (\z. g(drop z)) IN lspace (:real^1) (&2)
     ==> norm(integral (IMAGE lift (real_interval[a,b]))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * g(drop x)))
         <= sqrt(b - a) *
            lnorm (IMAGE lift (real_interval[a,b])) (&2) (\z. g(drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (g:real->complex)(drop z)) IN lspace (IMAGE lift (real_interval[a,b]))
     (&2)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC LSPACE_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV; IMAGE_LIFT_REAL_INTERVAL;
      LEBESGUE_MEASURABLE_INTERVAL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\z. (g:real->complex)(drop z)) absolutely_integrable_on (IMAGE lift
     (real_interval[a,b]))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `drop(integral (IMAGE lift (real_interval[a,b]))
                     (\x. lift(norm((g:real->complex)(drop x)))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `drop(integral (IMAGE lift (real_interval[a,b]))
                       (\x. lift(norm(cexp(--(ii * Cx y * Cx(drop x))) *
                         (g:real->complex)(drop x)))))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC INTEGRAL_NORM_BOUND_INTEGRAL THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC FOURIER_MODULATION_ABSINT_ON THEN
        ASM_REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL];
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
        MATCH_MP_TAC FOURIER_MODULATION_ABSINT_ON THEN
        ASM_REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL];
        REWRITE_TAC[LIFT_DROP; REAL_LE_REFL]];
      MATCH_MP_TAC REAL_EQ_IMP_LE THEN AP_TERM_TAC THEN
      MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
      REWRITE_TAC[COMPLEX_NORM_MUL] THEN
      SUBGOAL_THEN
        `--(ii * Cx y * Cx(drop w)) = ii * Cx(--(y * drop w))` SUBST1_TAC THENL
       [REWRITE_TAC[CX_NEG; CX_MUL] THEN
         SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[NORM_CEXP_II; REAL_MUL_LID]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`IMAGE lift (real_interval[a,b])`; `&2:real`; `&2:real`;
    `\z:real^1. Cx(&1)`; `\z:real^1. (g:real->complex)(drop z)`]
   HOELDER_INEQUALITY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
    CONJ_TAC THENL [CONV_TAC REAL_FIELD; ALL_TAC] THEN
    MATCH_MP_TAC LSPACE_CONST THEN
    REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL];
    ALL_TAC] THEN
  REWRITE_TAC[COMPLEX_NORM_CX; REAL_ABS_NUM; REAL_MUL_LID] THEN
  ASM_SIMP_TAC[LNORM2_CONST1]);;

(* L^2 norm on a compact subinterval is <= the L^2 norm on all of R          *)
(* (int_[a,b]|g|^2 <= int_R|g|^2, INTEGRAL_SUBSET_DROP_LE, then rpow         *)
(* monotone).                                                                *)
let LNORM2_SUBSET_UNIV = prove
 (`!(g:real->complex) a b.
     a <= b /\ (\z. g(drop z)) IN lspace (:real^1) (&2)
     ==> lnorm (IMAGE lift (real_interval[a,b])) (&2) (\z. g(drop z))
         <= lnorm (:real^1) (&2) (\z. g(drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (g:real->complex)(drop z)) IN lspace (IMAGE lift (real_interval[a,b]))
     (&2)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC LSPACE_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV; IMAGE_LIFT_REAL_INTERVAL;
      LEBESGUE_MEASURABLE_INTERVAL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x:real^1. lift(norm((g:real->complex)(drop x)) rpow (&2))) integrable_on
    (IMAGE lift (real_interval[a,b]))`
   ASSUME_TAC THENL
   [MP_TAC(SPEC_ALL(MATCH_MP LSPACE_IMP_INTEGRABLE
      (ASSUME `(\z. (g:real->complex)(drop z)) IN lspace (IMAGE lift
        (real_interval[a,b])) (&2)`))) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x:real^1. lift(norm((g:real->complex)(drop x)) rpow (&2))) integrable_on
     (:real^1)`
   ASSUME_TAC THENL
   [MP_TAC(SPEC_ALL(MATCH_MP LSPACE_IMP_INTEGRABLE
      (ASSUME `(\z. (g:real->complex)(drop z)) IN lspace (:real^1) (&2)`)))
        THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[lnorm] THEN
  MATCH_MP_TAC RPOW_LE2 THEN
  REWRITE_TAC[REAL_LE_INV_EQ; REAL_POS] THEN CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRAL_DROP_POS THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[LIFT_DROP] THEN REPEAT STRIP_TAC THEN
    MATCH_MP_TAC RPOW_POS_LE THEN REWRITE_TAC[NORM_POS_LE];
    MATCH_MP_TAC INTEGRAL_SUBSET_DROP_LE THEN
    ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    REWRITE_TAC[LIFT_DROP] THEN REPEAT STRIP_TAC THEN
    MATCH_MP_TAC RPOW_POS_LE THEN REWRITE_TAC[NORM_POS_LE]]);;

(* --- 286T(c) test-function comparison (Fremlin 2933-2934): Ahat_n f <=     *)
(* Ahat_n h                                                                  *)
(* + (sqrt(2n)/sqrt2pi) ||f-h||_2.  Split each window integral f = h + (f-h) *)
(* (INTEGRAL_ADD), NORM_TRIANGLE; the h-part <= Ahat_n h (member <= sup),    *)
(* the                                                                       *)
(* (f-h)-part <= sqrt(b-a) ||f-h||_{L^2[a,b]} <= sqrt(2n) ||f-h||_{L^2(R)}   *)
(* [CARLESON_WINDOW_CAUCHY_SCHWARZ + sqrt(b-a)<=sqrt(2n) +                   *)
(* LNORM2_SUBSET_UNIV]. ---                                                  *)
let CARLESON_AHAT_TRUNC_SUB_BOUND = prove
 (`!(f:real->complex) h n y.
     &0 <= n /\ (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (\z. h(drop z)) IN lspace (:real^1) (&2)
     ==> carleson_Ahat_trunc f n y
         <= carleson_Ahat_trunc h n y +
            inv(sqrt(&2 * pi)) * sqrt(&2 * n) * lnorm (:real^1) (&2) (\z.
              f(drop z) - h(drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z. (f:real->complex)(drop z) - h(drop z)) IN lspace (:real^1) (&2)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_POS]; ALL_TAC] THEN
  REWRITE_TAC[carleson_Ahat_trunc] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[--n,n]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`;
      `--n:real`; `n:real`] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
      `b:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `integral (IMAGE lift (real_interval[a,b]))
        (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x)) =
      integral (IMAGE lift (real_interval[a,b]))
        (\x. cexp(--(ii * Cx y * Cx(drop x))) * h(drop x)) +
      integral (IMAGE lift (real_interval[a,b]))
        (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f(drop x) - h(drop x)))`
     SUBST1_TAC THENL
     [SUBGOAL_THEN
       `(\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x)) =
        (\x. cexp(--(ii * Cx y * Cx(drop x))) * h(drop x) +
             cexp(--(ii * Cx y * Cx(drop x))) * (f(drop x) - h(drop x)))`
       SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
         CONV_TAC COMPLEX_RING; ALL_TAC] THEN
      MATCH_MP_TAC INTEGRAL_ADD THEN CONJ_TAC THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC FOURIER_MODULATION_ABSINT_ON THEN
      REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL] THEN
      REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
      MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC
     `inv(sqrt(&2 * pi)) *
      (norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (h:real->complex)(drop
                x))) +
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f(drop x) - h(drop
                x)))))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
        MP_TAC PI_POS THEN REAL_ARITH_TAC;
        REWRITE_TAC[NORM_TRIANGLE]];
      ALL_TAC] THEN
    REWRITE_TAC[REAL_ADD_LDISTRIB] THEN MATCH_MP_TAC REAL_LE_ADD2 THEN
    CONJ_TAC THENL
     [REWRITE_TAC[carleson_Ahat_trunc] THEN
      MP_TAC(ISPECL
       [`{ inv(sqrt(&2 * pi)) *
           norm(integral (IMAGE lift (real_interval[a',b']))
                  (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                    (h:real->complex)(drop x)))
         | a',b' | --n <= a' /\ a' <= b' /\ b' <= n }`;
        `inv(sqrt(&2 * pi)) *
         norm(integral (IMAGE lift (real_interval[a,b]))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * (h:real->complex)(drop
                  x)))`;
        `inv(sqrt(&2 * pi)) *
         drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
           lift(norm((h:real->complex)(drop x)))))`;
        `inv(sqrt(&2 * pi)) *
         norm(integral (IMAGE lift (real_interval[a,b]))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * (h:real->complex)(drop
                  x)))`]
       REAL_LE_SUP) THEN
      REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
      REPEAT CONJ_TAC THENL
       [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[REAL_LE_REFL];
        X_GEN_TAC `v:real` THEN
        DISCH_THEN(X_CHOOSE_THEN `a2:real` (X_CHOOSE_THEN
          `b2:real` STRIP_ASSUME_TAC)) THEN
        ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
          MP_TAC PI_POS THEN REAL_ARITH_TAC;
          MATCH_MP_TAC CARLESON_TRUNC_WINDOW_LE_INT THEN ASM_REWRITE_TAC[] THEN
          MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN ASM_REWRITE_TAC[]]];
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
        MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `sqrt(b - a) *
         lnorm (IMAGE lift (real_interval[a,b])) (&2) (\z.
           (f:real->complex)(drop z) - h(drop z))` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC CARLESON_WINDOW_CAUCHY_SCHWARZ THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_LE_MUL2 THEN REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC SQRT_POS_LE THEN ASM_REAL_ARITH_TAC;
          MATCH_MP_TAC SQRT_MONO_LE THEN ASM_REAL_ARITH_TAC;
          MATCH_MP_TAC LNORM_POS_LE THEN MATCH_MP_TAC LSPACE_SUBSET THEN
          EXISTS_TAC `(:real^1)` THEN
          ASM_REWRITE_TAC[SUBSET_UNIV; IMAGE_LIFT_REAL_INTERVAL;
            LEBESGUE_MEASURABLE_INTERVAL];
          MATCH_MP_TAC LNORM2_SUBSET_UNIV THEN ASM_REWRITE_TAC[]]]]]);;

(* --- 286T(c) n->infinity link: Ahat_n f <= Ahat f (compact window range is *)
(* a                                                                         *)
(* subset of all windows), UNDER the untruncated-family-bounded hyp (so Ahat *)
(* f is                                                                      *)
(* a genuine sup).  Member<=sup twice. ---                                   *)
let CARLESON_AHAT_TRUNC_LE = prove
 (`!(f:real->complex) n y.
     &0 <= n /\
     (?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <= B)
     ==> carleson_Ahat_trunc f n y <= carleson_Ahat f y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Ahat_trunc] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[--n,n]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`;
      `--n:real`; `n:real`] THEN
    REWRITE_TAC[REAL_LE_REFL] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
      `b:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[carleson_Ahat] THEN
    MP_TAC(ISPECL
     [`{ inv(sqrt(&2 * pi)) *
         norm(integral (IMAGE lift (real_interval[a',b']))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                  x)))
       | a',b' | a' <= b' }`;
      `inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`;
      `B:real`;
      `inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`]
     REAL_LE_SUP) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
    REPEAT CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_LE_REFL];
      X_GEN_TAC `v:real` THEN
      DISCH_THEN(X_CHOOSE_THEN `a2:real` (X_CHOOSE_THEN
        `b2:real` STRIP_ASSUME_TAC)) THEN
      ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]]]);;

(* --- 286T(c) monotone-convergence bridge: Ahat_m f y -> Ahat f y as m->inf *)
(* (m in N). Given the untruncated family bounded (Ahat f genuine sup): for  *)
(* e>0                                                                       *)
(* SUP_APPROACH gives a window [a,b] with term > Ahat f - e/2; that window   *)
(* sits in                                                                   *)
(* [-m,m] for m >= max(|a|,|b|) (REAL_ARCH_SIMPLE), so Ahat_m f >= term >    *)
(* Ahat f -                                                                  *)
(* e/2, and Ahat_m f <= Ahat f (CARLESON_AHAT_TRUNC_LE); hence |Ahat_m f -   *)
(* Ahat f|                                                                   *)
(* <= e/2 < e. ---                                                           *)
let CARLESON_AHAT_TRUNC_SUP = prove
 (`!(f:real->complex) y.
     (?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <= B)
     ==> ((\m. carleson_Ahat_trunc f (&m) y) ---> carleson_Ahat f y)
       sequentially`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL
   [`{ inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))
     | a,b | a <= b }`; `carleson_Ahat f y - e / &2`] SUP_APPROACH) THEN
  REWRITE_TAC[GSYM carleson_Ahat] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      MAP_EVERY EXISTS_TAC
       [`inv(sqrt(&2 * pi)) *
         norm(integral (IMAGE lift (real_interval[y,y]))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                  x)))`;
        `y:real`; `y:real`] THEN REWRITE_TAC[REAL_LE_REFL];
      EXISTS_TAC `B:real` THEN
        REWRITE_TAC[IN_ELIM_THM; LEFT_IMP_EXISTS_THM] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
        FIRST_X_ASSUM MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:real` STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM SUBST_ALL_TAC THEN
  MP_TAC(SPEC `max (abs a) (abs b)` REAL_ARCH_SIMPLE) THEN
  DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN EXISTS_TAC `N:num` THEN
  X_GEN_TAC `m:num` THEN DISCH_TAC THEN
  SUBGOAL_THEN `&N:real <= &m` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[REAL_OF_NUM_LE]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 <= &m /\ --(&m) <= a /\ a <= b /\ b <= &m` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `inv(sqrt(&2 * pi)) *
    norm(integral (IMAGE lift (real_interval[a,b]))
           (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x)))
    <= carleson_Ahat_trunc f (&m) y`
   ASSUME_TAC THENL
   [REWRITE_TAC[carleson_Ahat_trunc] THEN
    MP_TAC(ISPECL
     [`{ inv(sqrt(&2 * pi)) *
         norm(integral (IMAGE lift (real_interval[a',b']))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                  x)))
       | a',b' | --(&m) <= a' /\ a' <= b' /\ b' <= &m }`;
      `inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`;
      `B:real`;
      `inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))`]
     REAL_LE_SUP) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
    REPEAT CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_LE_REFL];
      X_GEN_TAC `v:real` THEN
      DISCH_THEN(X_CHOOSE_THEN `a2:real` (X_CHOOSE_THEN
        `b2:real` STRIP_ASSUME_TAC)) THEN
      ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `carleson_Ahat_trunc f (&m) y <= carleson_Ahat f y` ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_AHAT_TRUNC_LE THEN ASM_REWRITE_TAC[REAL_POS] THEN
    EXISTS_TAC `B:real` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* --- 286T(c) assembly (n->infinity, Fremlin 2946-2948): the UNtruncated    *)
(* bound                                                                     *)
(* int_F Ahat f <= C ||f||_2 sqrt muF follows from the TRUNCATED bounds      *)
(* int_F                                                                     *)
(* Ahat_m f <= C ||f||_2 sqrt muF (uniform in m, = 286P output for the       *)
(* compact-                                                                  *)
(* window operator) by MONOTONE CONVERGENCE. f_m = Ahat_m f is integrable on *)
(* F                                                                         *)
(* (threaded), increasing in m (CARLESON_AHAT_TRUNC_MONO), -> Ahat f a.e.    *)
(* (CARLESON                                                                 *)
(* _AHAT_TRUNC_SUP, needs Ahat f finite a.e. = the threaded                  *)
(* window-bound-a.e. hyp,                                                    *)
(* Fremlin 286D from the bound), with uniformly bounded integrals; so Ahat f *)
(* is                                                                        *)
(* integrable and int_F Ahat_m f -> int_F Ahat f, whose limit is <= the      *)
(* bound                                                                     *)
(* (REALLIM_UBOUND). This reduces CARLESON_286T_BOUND to the truncated bound *)
(* (whose engine is the DEEP 286O(b)/286P tile operator).  ---               *)
let CARLESON_286T_FROM_TRUNC = prove
 (`!(f:real->complex) FF C.
     &0 <= C /\ real_measurable FF /\ (\z. f(drop z)) IN lspace (:real^1) (&2)
       /\
     (?t. real_negligible t /\
          (!y. ~(y IN t) ==> ?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <= B))
                      /\
     (!m. (\y. carleson_Ahat_trunc f (&m) y) real_integrable_on FF /\
          real_integral FF (\y. carleson_Ahat_trunc f (&m) y)
            <= C * lnorm (:real^1) (&2) (\z. f(drop z)) * sqrt(real_measure
              FF))
     ==> carleson_Ahat f real_integrable_on FF /\
         real_integral FF (carleson_Ahat f)
           <= C * lnorm (:real^1) (&2) (\z. f(drop z)) * sqrt(real_measure
             FF)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (X_CHOOSE_THEN
        `t:real->bool` STRIP_ASSUME_TAC) ASSUME_TAC)))) THEN
  MP_TAC(ISPECL
   [`\m:num. (\y. carleson_Ahat_trunc f (&m) y)`;
    `carleson_Ahat f`; `FF:real->bool`]
   REAL_MONOTONE_CONVERGENCE_INCREASING_AE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [GEN_TAC THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`k:num`; `y:real`] THEN DISCH_TAC THEN
      MATCH_MP_TAC CARLESON_AHAT_TRUNC_MONO THEN
      ASM_REWRITE_TAC[REAL_POS; REAL_OF_NUM_LE] THEN ARITH_TAC;
      EXISTS_TAC `t:real->bool` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_DIFF] THEN STRIP_TAC THEN
      MATCH_MP_TAC CARLESON_AHAT_TRUNC_SUP THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[real_bounded; FORALL_IN_GSPEC; IN_UNIV] THEN
      EXISTS_TAC `abs(C * lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z))
        * sqrt(real_measure FF))` THEN
      X_GEN_TAC `k:num` THEN
      MATCH_MP_TAC(REAL_ARITH `&0 <= x /\ x <= b ==> abs x <= abs b`) THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_TRANS THEN
        EXISTS_TAC `real_integral FF (\y. &0)` THEN CONJ_TAC THENL
         [REWRITE_TAC[REAL_INTEGRAL_0; REAL_LE_REFL];
          MATCH_MP_TAC REAL_INTEGRAL_LE THEN
            ASM_REWRITE_TAC[REAL_INTEGRABLE_0] THEN
          X_GEN_TAC `y:real` THEN DISCH_TAC THEN
          MATCH_MP_TAC CARLESON_AHAT_TRUNC_POS THEN ASM_REWRITE_TAC[REAL_POS]];
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPEC `sequentially` REALLIM_UBOUND) THEN
  EXISTS_TAC `\m:num. real_integral FF (\y. carleson_Ahat_trunc f (&m) y)` THEN
  ASM_REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY; EVENTUALLY_SEQUENTIALLY] THEN
  EXISTS_TAC `0` THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* 286T(b): the Schwartz estimate and density transfer.                      *)
(*                                                                           *)
(* The deep analytic content of 286T is the Schwartz maximal bound           *)
(*   int_F carleson_Ahat h <= C10 ||h||_2 sqrt(muF)   (h a test function)    *)
(* [= Fremlin 286T(b), whose engine is 286P -> 286Q/R/S dilation-averaging]. *)
(* CARLESON_286T_SCHWARTZ is transferred to the general truncated bound      *)
(*   int_{[-M,M]} carleson_Ahat_trunc f n <= C10 ||f||_2 sqrt(2M)            *)
(* via 286T(c): Ahat_n f <= Ahat_n h + Cauchy-error (SUB_BOUND) + Schwartz   *)
(* density (284N).  This is exactly the H1 hypothesis of both CARLESON_286T_ *)
(* FROM_TRUNC and CARLESON_286U_EXISTS_FROM_BOUNDS. ---                      *)

(* Schwartz h: the window-integral family is uniformly bounded (h in L^1).   *)
let CARLESON_SCHWARTZ_WINDOW_BOUND = prove
 (`!(h:real->complex) y.
     schwartz h
     ==> ?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * h(drop x))) <= B`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP SCHWARTZ_ABSINT) THEN
  EXISTS_TAC `inv(sqrt(&2 * pi)) *
     drop(integral (:real^1) (\x. lift(norm((h:real->complex)(drop x)))))` THEN
  MAP_EVERY X_GEN_TAC [`a:real`; `b:real`] THEN DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
    MP_TAC PI_POS THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `drop(integral (IMAGE lift (real_interval[a,b])) (\x.
    lift(norm((h:real->complex)(drop x)))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRAL_NORM_BOUND_INTEGRAL THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC FOURIER_MODULATION_ABSINT_ON THEN
      REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL] THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
      EXISTS_TAC `(:real^1)` THEN
        ASM_REWRITE_TAC[SUBSET_UNIV; GSYM IMAGE_LIFT_REAL_INTERVAL];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
      EXISTS_TAC `(:real^1)` THEN
        ASM_REWRITE_TAC[SUBSET_UNIV; GSYM IMAGE_LIFT_REAL_INTERVAL];
      X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
      REWRITE_TAC[LIFT_DROP; COMPLEX_NORM_MUL] THEN
      SUBGOAL_THEN
        `--(ii * Cx y * Cx(drop w)) = ii * Cx(--(y * drop w))` SUBST1_TAC THENL
       [REWRITE_TAC[CX_NEG; CX_MUL] THEN
         SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[NORM_CEXP_II; REAL_MUL_LID; REAL_LE_REFL]];
    MATCH_MP_TAC INTEGRAL_SUBSET_DROP_LE THEN
    REWRITE_TAC[SUBSET_UNIV] THEN CONJ_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
      EXISTS_TAC `(:real^1)` THEN
        ASM_REWRITE_TAC[SUBSET_UNIV; GSYM IMAGE_LIFT_REAL_INTERVAL];
      CONJ_TAC THENL
       [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN ASM_REWRITE_TAC[];
        X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
          REWRITE_TAC[LIFT_DROP; NORM_POS_LE]]]]);;

(* Ahat_n h <= Ahat h for Schwartz h (compact windows subset all windows).   *)
let CARLESON_AHAT_TRUNC_SCHWARTZ_LE = prove
 (`!(h:real->complex) n y.
     &0 <= n /\ schwartz h
     ==> carleson_Ahat_trunc h n y <= carleson_Ahat h y`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CARLESON_AHAT_TRUNC_LE THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`h:real->complex`;
    `y:real`] CARLESON_SCHWARTZ_WINDOW_BOUND) THEN
  ASM_REWRITE_TAC[]);;

(* Ahat h is pointwise bounded by the loc-L^1 constant (Schwartz h).         *)
let CARLESON_AHAT_SCHWARTZ_BOUND = prove
 (`!(h:real->complex) y.
     schwartz h
     ==> carleson_Ahat h y <=
         inv(sqrt(&2 * pi)) * drop(integral (:real^1) (\x.
           lift(norm((h:real->complex)(drop x)))))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o MATCH_MP SCHWARTZ_ABSINT) THEN
  REWRITE_TAC[carleson_Ahat] THEN MATCH_MP_TAC REAL_SUP_LE THEN
  CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[y,y]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (h:real->complex)(drop
                x)))`;
      `y:real`; `y:real`] THEN REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
      `b:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
      MP_TAC PI_POS THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `drop(integral (IMAGE lift (real_interval[a,b])) (\x.
      lift(norm((h:real->complex)(drop x)))))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC INTEGRAL_NORM_BOUND_INTEGRAL THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC FOURIER_MODULATION_ABSINT_ON THEN
        REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL] THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real^1)` THEN
          ASM_REWRITE_TAC[SUBSET_UNIV; GSYM IMAGE_LIFT_REAL_INTERVAL];
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
        REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real^1)` THEN
          ASM_REWRITE_TAC[SUBSET_UNIV; GSYM IMAGE_LIFT_REAL_INTERVAL];
        X_GEN_TAC `w2:real^1` THEN DISCH_TAC THEN
        REWRITE_TAC[LIFT_DROP; COMPLEX_NORM_MUL] THEN
        SUBGOAL_THEN
          `--(ii * Cx y * Cx(drop w2)) =
           ii * Cx(--(y * drop w2))` SUBST1_TAC THENL
         [REWRITE_TAC[CX_NEG; CX_MUL] THEN
           SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[NORM_CEXP_II; REAL_MUL_LID; REAL_LE_REFL]];
      MATCH_MP_TAC INTEGRAL_SUBSET_DROP_LE THEN
      REWRITE_TAC[SUBSET_UNIV] THEN CONJ_TAC THENL
       [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
        REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_SUBINTERVAL THEN
        EXISTS_TAC `(:real^1)` THEN
          ASM_REWRITE_TAC[SUBSET_UNIV; GSYM IMAGE_LIFT_REAL_INTERVAL];
        CONJ_TAC THENL
         [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
          MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN ASM_REWRITE_TAC[];
          X_GEN_TAC `w2:real^1` THEN DISCH_TAC THEN
            REWRITE_TAC[LIFT_DROP; NORM_POS_LE]]]]]);;

(* Ahat h is integrable on any measurable set (measurable + bounded by       *)
(* const).                                                                   *)
let CARLESON_AHAT_SCHWARTZ_INTEGRABLE = prove
 (`!(h:real->complex) FF.
     schwartz h /\ real_measurable FF
     ==> (carleson_Ahat h) real_integrable_on FF`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `\y:real. inv(sqrt(&2 * pi)) *
     drop(integral (:real^1) (\x. lift(norm((h:real->complex)(drop x)))))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC CARLESON_AHAT_MEASURABLE THEN CONJ_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN MATCH_MP_TAC CARLESON_SCHWARTZ_WINDOW_BOUND THEN
        ASM_REWRITE_TAC[]];
    ONCE_REWRITE_TAC[GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
    ASM_REWRITE_TAC[GSYM REAL_MEASURABLE];
    X_GEN_TAC `y:real` THEN DISCH_TAC THEN
    SUBGOAL_THEN `&0 <= carleson_Ahat h y` ASSUME_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_POS THEN
      MATCH_MP_TAC CARLESON_SCHWARTZ_WINDOW_BOUND THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `carleson_Ahat h y <= inv(sqrt(&2 * pi)) *
        drop(integral (:real^1) (\x. lift(norm((h:real->complex)(drop x)))))`
     ASSUME_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_SCHWARTZ_BOUND THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REAL_ARITH_TAC]);;

(* ========================================================================= *)
(* Deep 286P tile-bound ladder (Fremlin mt286.tex 1939-2948): the tile       *)
(* operator A (286P) + the 286Q/R/S/T dilation-averaging reduction, one rung *)
(* at a time.  246K (the factor-4 sign trick, above) is the first sub-piece  *)
(* of 286P.                                                                  *)
(* ========================================================================= *)

(* Fremlin 286C: shift / modulation / dilation operators.                    *)
let carleson_modulate = new_definition
 `carleson_modulate a (f:real->complex) = \x. cexp(ii * Cx a * Cx x) * f x`;;
let carleson_dilate = new_definition
 `carleson_dilate a (f:real->complex) = \x. f(a * x)`;;

(* ========================================================================= *)
(* 286Q(c) FOURIER-ALGEBRA bricks (Fremlin mt286 2380-2416), toward the      *)
(* kernel                                                                    *)
(* bound 2pi|(hhat.theta')check| <= D_{1/a} A M_b D_a h.                     *)
(* ========================================================================= *)

(* (M_b D_a h)hat w = (1/a) hhat((w-b)/a).  M_b D_a h = D_a(M_{b/a} h) (the  *)
(* modulation frequency scales under dilation), then FOURIER_DILATION +      *)
(* FOURIER_MODULATION.                                                       *)
let CARLESON_MODDIL_FOURIER = prove
 (`!(h:real->complex) a b w. &0 < a /\
     (\x. cexp(--(ii * Cx (w/a) * Cx(drop x))) * (\u. cexp(ii * Cx(b/a) * Cx u)
       * h u)(drop x)) integrable_on (:real^1)
   ==> fourier (carleson_modulate b (carleson_dilate a h)) w
       = Cx(&1/a) * fourier h ((w - b)/a)`,
  REWRITE_TAC[carleson_modulate; carleson_dilate] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(\x. cexp(ii * Cx b * Cx x) * (h:real->complex)(a * x))
                = (\x. (\u. cexp(ii * Cx(b/a) * Cx u) * h u)(a * x))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[CX_MUL] THEN
    SUBGOAL_THEN `Cx(b/a) * Cx a = Cx b` (fun th -> MP_TAC th) THENL
     [REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
       ASM_SIMP_TAC[REAL_DIV_RMUL; REAL_LT_IMP_NZ];
      CONV_TAC SIMPLE_COMPLEX_ARITH]; ALL_TAC] THEN
  MP_TAC(SPECL [`\u. cexp(ii * Cx(b/a) * Cx u) * (h:real->complex) u`;
    `a:real`; `w:real`] FOURIER_DILATION) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[FOURIER_MODULATION] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    REAL_ARITH_TAC);;

(* The check-integrand identity: fourier h w * Cx(theta' z a b w) = Cx a *   *)
(* ((M_b                                                                     *)
(* D_a h)hat . Cx(theta_v)) at (a w+b), v = a z+b. Lets the check-integral   *)
(* become                                                                    *)
(* a dilation+shift of the (M_b D_a h) window (the y/a-evaluation of         *)
(* 286Q(c)).                                                                 *)
let CARLESON_Q286C_INTEGRAND = prove
 (`!(h:real->complex) z a b w. &0 < a /\
     (!w. (\x. cexp(--(ii * Cx (w/a) * Cx(drop x))) * (\u. cexp(ii * Cx(b/a) *
       Cx u) * h u)(drop x)) integrable_on (:real^1))
   ==> fourier h w * Cx(carleson_theta' z a b w)
       = Cx a * (fourier (carleson_modulate b (carleson_dilate a h)) (a*w+b) *
                 Cx(carleson_theta (a*z+b) (a*w+b)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  SUBGOAL_THEN
   `fourier (carleson_modulate b (carleson_dilate a (h:real->complex))) (a*w+b)
    = Cx(&1/a) * fourier h w`
   ASSUME_TAC THENL
   [MP_TAC(SPECL [`h:real->complex`; `a:real`; `b:real`;
     `a*w+b:real`] CARLESON_MODDIL_FOURIER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_FIELD `&0 < a ==> ((a*w+b) - b)/a = w`]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `Cx a * Cx(&1/a) = Cx(&1)` MP_TAC THENL
   [REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
    UNDISCH_TAC `&0 < a` THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  CONV_TAC COMPLEX_RING);;

(* 286Q(c) brick 3 (the specific check-integral change-of-variables): the    *)
(* transform                                                                 *)
(* of a dilated+shifted g. \w. g(a w+b) = \w. (S_b g)(a w), S_b g = \u.      *)
(* g(u+b); so                                                                *)
(* FOURIER_DILATION on S_b g + FOURIER_SHIFT on g give the 1/a Jacobian +    *)
(* e^{ibz/a}                                                                 *)
(* phase. (This is the affine COV specialised to the check-integral,         *)
(* expressed via                                                             *)
(* the operator laws rather than raw HAS_INTEGRAL_AFFINITY.)                 *)
let CARLESON_FOURIER_DILSHIFT = prove
 (`!(g:real->complex) a b z. &0 < a /\
     (\x. cexp(--(ii * Cx (z/a) * Cx(drop x))) * (\u. g(u + b))(drop x))
       integrable_on (:real^1) /\
     (\x. cexp(--(ii * Cx (z/a) * Cx(drop x))) * g(drop x)) integrable_on
       (:real^1)
   ==> fourier (\w. g(a * w + b)) z
       = Cx(&1/a) * cexp(ii * Cx b * Cx(z/a)) * fourier g (z/a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\w. (g:real->complex)(a * w + b)) = (\w. (\u. g(u + b))(a * w))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM]; ALL_TAC] THEN
  MP_TAC(SPECL [`\u. (g:real->complex)(u + b)`; `a:real`;
    `z:real`] FOURIER_DILATION) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(SPECL [`g:real->complex`; `b:real`; `z/a:real`] FOURIER_SHIFT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC]);;

(* ========================================================================= *)
(* 286O(a): the window function theta_z is Borel/Lebesgue measurable.  Since *)
(* theta_z(y) is a sup over the (countable) tile family of a continuous term *)
(* Re(phi-hat(2^{-k}(y-ymid)))^2 restricted to the dyadic left-half J^l, it  *)
(* is a countable sup of measurable functions, hence measurable. This is the *)
(* isolated gate on which the tile-operator sub-bricks below are             *)
(* conditioned.                                                              *)
(* ========================================================================= *)

(* The per-tile term y |-> Re(phi-hat(A(y-m)))^2 is real-continuous, hence   *)
(* real-measurable (phi-hat is continuous by CARLESON_PHI_SCHWARTZ; the      *)
(* affine reparametrisation and Re/square preserve continuity).              *)
let CARLESON_THETA_TERM_MEASURABLE = prove
 (`!(A:real) (m:real).
     (\y. Re(fourier carleson_phi (A * (y - m))) pow 2) real_measurable_on
       (:real)`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON; IMAGE_LIFT_UNIV; o_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_POW THEN
  REWRITE_TAC[RE_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
  SUBGOAL_THEN
   `(\z:real^1. fourier carleson_phi (A * (drop z - m))) =
    (\w:real^1. fourier carleson_phi (drop w)) o (\z:real^1. lift(A * (drop z -
      m)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [REWRITE_TAC[LIFT_CMUL; LIFT_SUB] THEN
    MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN MATCH_MP_TAC CONTINUOUS_ON_SUB THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
    SUBGOAL_THEN `(\z:real^1. lift(drop z)) = (\z:real^1. z)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; LIFT_DROP]; REWRITE_TAC[CONTINUOUS_ON_ID]];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN
      MATCH_MP_TAC SCHWARTZ_ABSINT THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
      REWRITE_TAC[SUBSET_UNIV]]]);;

(* The dyadic left-half tile_Jl s is real-measurable for any tile s.         *)
let TILE_JL_MEASURABLE = prove
 (`!s:int#int#int. real_measurable (tile_Jl s)`,
  GEN_TAC THEN
  MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPEC `y:int#int` PAIR_SURJECTIVE) THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[tile_Jl; DYHO_MEASURABLE]);;

(* Each member g_n of the enumerated tile family (with a sentinel n=0 slot   *)
(* forcing 0 into the family) is real-measurable: either the constant 0, or  *)
(* the per-tile term restricted to the measurable J^l (REAL_MEASURABLE_ON_   *)
(* RESTRICT).  The zt IN J^r condition is a y-independent proposition.       *)
let CARLESON_THETA_FAMILY_MEASURABLE = prove
 (`!(e:num->(int#int#int)) (zt:real) (n:num).
     (\y. if n = 0 then &0
          else if zt IN tile_Jr (e(n-1)) /\ y IN tile_Jl (e(n-1))
               then Re(fourier carleson_phi (&2 zpow (--(tile_k (e(n-1)))) * (y
                 - tile_ymid (e(n-1))))) pow 2
               else &0)
     real_measurable_on (:real)`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `n = 0` THEN ASM_REWRITE_TAC[REAL_MEASURABLE_ON_CONST] THEN
  ASM_CASES_TAC `zt IN tile_Jr ((e:num->int#int#int)(n-1))` THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_MEASURABLE_ON_RESTRICT THEN
    CONJ_TAC THENL
     [REWRITE_TAC[CARLESON_THETA_TERM_MEASURABLE];
      MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
      REWRITE_TAC[TILE_JL_MEASURABLE]];
    ASM_REWRITE_TAC[REAL_MEASURABLE_ON_CONST]]);;

(* Reconcile theta_z's set-sup (over qualifying tiles, UNION {0}) with a     *)
(* num-                                                                      *)
(* indexed sup over the enumerated family g_n.  The n=0 sentinel supplies 0; *)
(* n>=1 runs the enumeration e of the countable tile index set int#int#int.  *)
let CARLESON_THETA_SUP_RECONCILE = prove
 (`!(e:num->(int#int#int)) zt y.
     (:int#int#int) = IMAGE e (:num)
     ==> carleson_theta zt y =
         sup { (if n = 0 then &0
                else if zt IN tile_Jr (e(n-1)) /\ y IN tile_Jl (e(n-1))
                     then Re(fourier carleson_phi (&2 zpow (--(tile_k
                       (e(n-1)))) * (y - tile_ymid (e(n-1))))) pow 2
                     else &0)
              | n IN (:num) }`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[carleson_theta] THEN
    AP_TERM_TAC THEN
  CONV_TAC SYM_CONV THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_SING; IN_ELIM_THM; IN_UNIV] THEN
  X_GEN_TAC `w:real` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:num` SUBST1_TAC) THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    DISJ1_TAC THEN EXISTS_TAC `(e:num->int#int#int)(n-1)` THEN
      ASM_REWRITE_TAC[];
    STRIP_TAC THENL
     [SUBGOAL_THEN `?m. (e:num->int#int#int) m = s` STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(MP_TAC o AP_TERM `\u. (s:int#int#int) IN u`) THEN
        REWRITE_TAC[IN_UNIV; IN_IMAGE] THEN MESON_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `m + 1` THEN REWRITE_TAC[ADD_EQ_0; ARITH_EQ; ADD_SUB] THEN
      ASM_REWRITE_TAC[];
      EXISTS_TAC `0` THEN ASM_REWRITE_TAC[]]]);;

(* 286O(a): theta_z is real-measurable.  Enumerate the countable tile set,   *)
(* express theta_z as the num-sup of the family (bounded by 1 via CARLESON_  *)
(* THETA_TERM_BOUNDS), apply REAL_MEASURABLE_ON_SUP.                         *)
let CARLESON_THETA_MEASURABLE = prove
 (`!(zt:real). (\y. carleson_theta zt y) real_measurable_on (:real)`,
  GEN_TAC THEN
  SUBGOAL_THEN
    `?e:num->(int#int#int). (:int#int#int) =
     IMAGE e (:num)` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC COUNTABLE_AS_IMAGE THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM CROSS_UNIV] THEN MATCH_MP_TAC COUNTABLE_CROSS THEN
      REWRITE_TAC[INT_COUNTABLE; GSYM CROSS_UNIV] THEN
        MATCH_MP_TAC COUNTABLE_CROSS THEN
      REWRITE_TAC[INT_COUNTABLE];
      REWRITE_TAC[UNIV_NOT_EMPTY]]; ALL_TAC] THEN
  ASM_SIMP_TAC[CARLESON_THETA_SUP_RECONCILE] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_SUP THEN CONJ_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[CARLESON_THETA_FAMILY_MEASURABLE];
    GEN_TAC THEN EXISTS_TAC `&1` THEN GEN_TAC THEN
    COND_CASES_TAC THEN REWRITE_TAC[REAL_LE_01] THEN
    COND_CASES_TAC THEN REWRITE_TAC[REAL_LE_01] THEN
    REWRITE_TAC[CARLESON_THETA_TERM_BOUNDS]]);;

(* Lift 286O(a) to the complex-window form the tile operator needs:          *)
(* y |-> Cx(theta_z(drop y)) is measurable on R^1 (real-measurable composed  *)
(* with the continuous Cx o drop).                                           *)
let CARLESON_THETA_CX_MEASURABLE = prove
 (`!(zt:real). (\y:real^1. Cx(carleson_theta zt (drop y))) measurable_on
   (:real^1)`,
  GEN_TAC THEN
  SUBGOAL_THEN
   `(\y:real^1. Cx(carleson_theta zt (drop y))) =
    (\w. Cx(drop w)) o (\z. lift(carleson_theta zt (drop z)))`
   SUBST1_TAC THENL [REWRITE_TAC[o_DEF; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_COMPOSE_CONTINUOUS THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\z:real^1. lift(carleson_theta zt (drop z))) = lift o (\u.
     carleson_theta zt u) o drop`
      SUBST1_TAC THENL [REWRITE_TAC[o_DEF]; ALL_TAC] THEN
    REWRITE_TAC[GSYM IMAGE_LIFT_UNIV; GSYM real_measurable_on] THEN
    REWRITE_TAC[ETA_AX; CARLESON_THETA_MEASURABLE];
    MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN REWRITE_TAC[CONTINUOUS_ON_ID]]);;

(* ========================================================================= *)
(* 286R-(b-ii)/(c): the averaged bump g(alpha,y,z) and its bounds.           *)
(* g(alpha,y,z) = lim_{b->inf} (1/b) int_0^b theta'_{z,alpha,beta}(y) dbeta  *)
(* (Fremlin mt286.tex 2490-2531). Existence is PERIODIC_CESARO_LIMIT applied *)
(* to beta |-> theta'_{z,alpha,beta}(y): nonnegative (THETA'_BOUNDS), <=1,   *)
(* locally integrable (THETA'_BETA_INTEGRABLE = bounded + measurable), and   *)
(* 2^l-periodic (CARLESON_THETA'_PERIOD) when y<z, alpha>0.  For y>=z the    *)
(* integrand is identically 0 (THETA'_SUPPORT) so g=0.                       *)
(* ========================================================================= *)

(* {beta | c + beta IN dyho k n} is real-measurable (translate of a dyadic   *)
(* cell).                                                                    *)
let THETA_BETA_PREIMAGE = prove
 (`!c:real k n. real_measurable {beta | (c + beta) IN dyho k n}`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
    `{beta | (c + beta) IN dyho k n} = IMAGE (\x. (--c) + x) (dyho k n)`
    SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM] THEN X_GEN_TAC `b:real` THEN
    EQ_TAC THENL
     [DISCH_TAC THEN EXISTS_TAC `c + b:real` THEN
      CONJ_TAC THENL [REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
      DISCH_THEN(X_CHOOSE_THEN `x:real` STRIP_ASSUME_TAC) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `c + --c + x:real = x` (fun th -> ASM_REWRITE_TAC[th]) THEN
      REAL_ARITH_TAC]; ALL_TAC] THEN
  REWRITE_TAC[REAL_MEASURABLE_TRANSLATION; DYHO_MEASURABLE]);;

(* each per-tile term of theta', as a function of beta, is real-measurable.  *)
let THETA_BETA_FAMILY_MEASURABLE = prove
 (`!(e:num->(int#int#int)) (alpha:real) (y:real) (z:real) (n:num).
     (\beta. if n = 0 then &0
          else if (alpha * z + beta) IN tile_Jr (e(n-1)) /\ (alpha * y + beta)
            IN tile_Jl (e(n-1))
               then Re(fourier carleson_phi (&2 zpow (--(tile_k (e(n-1)))) *
                 ((alpha * y + beta) - tile_ymid (e(n-1))))) pow 2
               else &0)
     real_measurable_on (:real)`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `n = 0` THEN ASM_REWRITE_TAC[REAL_MEASURABLE_ON_CONST] THEN
  SUBGOAL_THEN
   `(\beta. if (alpha * z + beta) IN tile_Jr (e(n-1)) /\ (alpha * y + beta) IN
     tile_Jl (e(n-1))
            then Re(fourier carleson_phi (&2 zpow (--(tile_k (e(n-1)))) *
              ((alpha * y + beta) - tile_ymid (e(n-1))))) pow 2
            else &0) =
    (\beta. if beta IN {b | (alpha * z + b) IN tile_Jr (e(n-1)) /\ (alpha * y +
      b) IN tile_Jl (e(n-1))}
            then (\beta. Re(fourier carleson_phi (&2 zpow (--(tile_k (e(n-1))))
              * ((alpha * y + beta) - tile_ymid (e(n-1))))) pow 2) beta
            else &0)` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; IN_ELIM_THM]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\beta. Re(fourier carleson_phi (&2 zpow (--(tile_k (e(n-1)))) * ((alpha
       * y + beta) - tile_ymid (e(n-1))))) pow 2) =
      (\beta. Re(fourier carleson_phi (&2 zpow (--(tile_k (e(n-1)))) * (beta -
        (tile_ymid (e(n-1)) - alpha * y)))) pow 2)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_THM_TAC THEN
       AP_TERM_TAC THEN
      AP_TERM_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[CARLESON_THETA_TERM_MEASURABLE];
    MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
    SUBGOAL_THEN
     `{b | (alpha * z + b) IN tile_Jr (e(n-1)) /\ (alpha * y + b) IN tile_Jl
       (e(n-1))} =
      {b | (alpha * z + b) IN tile_Jr (e(n-1))} INTER {b | (alpha * y + b) IN
        tile_Jl (e(n-1))}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_MEASURABLE_INTER THEN
    MP_TAC(ISPEC `(e:num->int#int#int)(n-1)` PAIR_SURJECTIVE) THEN
      STRIP_TAC THEN
    MP_TAC(ISPEC `y':int#int` PAIR_SURJECTIVE) THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[tile_Jr; tile_Jl; THETA_BETA_PREIMAGE]]);;

(* reconcile theta(alpha z+beta)(alpha y+beta) with the num-sup of the       *)
(* family                                                                    *)
let THETA_BETA_SUP_RECONCILE = prove
 (`!(e:num->(int#int#int)) alpha y z beta.
     (:int#int#int) = IMAGE e (:num)
     ==> carleson_theta (alpha * z + beta) (alpha * y + beta) =
         sup { (if n = 0 then &0
                else if (alpha * z + beta) IN tile_Jr (e(n-1)) /\ (alpha * y +
                  beta) IN tile_Jl (e(n-1))
                     then Re(fourier carleson_phi (&2 zpow (--(tile_k
                       (e(n-1)))) * ((alpha * y + beta) - tile_ymid (e(n-1)))))
                        pow 2
                     else &0)
              | n IN (:num) }`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[carleson_theta] THEN
    AP_TERM_TAC THEN
  CONV_TAC SYM_CONV THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_SING; IN_ELIM_THM; IN_UNIV] THEN
  X_GEN_TAC `w:real` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:num` SUBST1_TAC) THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    DISJ1_TAC THEN EXISTS_TAC `(e:num->int#int#int)(n-1)` THEN
      ASM_REWRITE_TAC[];
    STRIP_TAC THENL
     [SUBGOAL_THEN `?m. (e:num->int#int#int) m = s` STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(MP_TAC o AP_TERM `\u. (s:int#int#int) IN u`) THEN
        REWRITE_TAC[IN_UNIV; IN_IMAGE] THEN MESON_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `m + 1` THEN REWRITE_TAC[ADD_EQ_0; ARITH_EQ; ADD_SUB] THEN
      ASM_REWRITE_TAC[];
      EXISTS_TAC `0` THEN ASM_REWRITE_TAC[]]]);;

(* theta'_{z,alpha,.}(y) is real-measurable in beta.                         *)
let THETA'_BETA_MEASURABLE = prove
 (`!alpha y z. (\beta. carleson_theta' z alpha beta y) real_measurable_on
   (:real)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  SUBGOAL_THEN
    `?e:num->(int#int#int). (:int#int#int) =
     IMAGE e (:num)` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC COUNTABLE_AS_IMAGE THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM CROSS_UNIV] THEN MATCH_MP_TAC COUNTABLE_CROSS THEN
      REWRITE_TAC[INT_COUNTABLE; GSYM CROSS_UNIV] THEN
        MATCH_MP_TAC COUNTABLE_CROSS THEN
      REWRITE_TAC[INT_COUNTABLE];
      REWRITE_TAC[UNIV_NOT_EMPTY]]; ALL_TAC] THEN
  ASM_SIMP_TAC[THETA_BETA_SUP_RECONCILE] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_SUP THEN CONJ_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[THETA_BETA_FAMILY_MEASURABLE];
    GEN_TAC THEN EXISTS_TAC `&1` THEN GEN_TAC THEN
    COND_CASES_TAC THEN REWRITE_TAC[REAL_LE_01] THEN
    COND_CASES_TAC THEN REWRITE_TAC[REAL_LE_01] THEN
    REWRITE_TAC[CARLESON_THETA_TERM_BOUNDS]]);;

(* theta'_{z,alpha,.}(y) is integrable on every bounded interval.            *)
let THETA'_BETA_INTEGRABLE = prove
 (`!alpha y z u v. (\beta. carleson_theta' z alpha beta y) real_integrable_on
   real_interval[u,v]`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\beta. &1):real->real` THEN REPEAT CONJ_TAC THENL
   [ONCE_REWRITE_TAC[GSYM REAL_MEASURABLE_ON_UNIV] THEN
    MATCH_MP_TAC REAL_MEASURABLE_ON_RESTRICT THEN
    REWRITE_TAC[THETA'_BETA_MEASURABLE] THEN
    MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
    REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
    REWRITE_TAC[REAL_INTEGRABLE_CONST];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
    MP_TAC(SPECL [`z:real`;`alpha:real`;`x:real`;`y:real`]
      CARLESON_THETA'_BOUNDS) THEN
    REAL_ARITH_TAC]);;

(* helper: reallim net f = l whenever the limit exists (nontrivial net).     *)
let REALLIM_REALLIM_EQ = prove
 (`!net:(A)net f l. ~(trivial_limit net) /\ (f ---> l) net ==> reallim net f =
   l`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[reallim] THEN
    MATCH_MP_TAC SELECT_UNIQUE THEN
  X_GEN_TAC `m:real` THEN REWRITE_TAC[] THEN EQ_TAC THEN DISCH_TAC THENL
   [MATCH_MP_TAC(ISPEC `net:(A)net` REALLIM_UNIQUE) THEN
    EXISTS_TAC `f:A->real` THEN ASM_REWRITE_TAC[];
    ASM_MESON_TAC[]]);;

(* the averaged bump.                                                        *)
let carleson_g = new_definition
 `carleson_g alpha y z =
    reallim at_posinfinity
      (\b. inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta'
        z alpha beta y))`;;

(* 286R-(b-ii): the Cesaro average of theta' converges (y<z, alpha>0).       *)
let CARLESON_G_CESARO = prove
 (`!alpha y z. &0 < alpha /\ y < z
   ==> ?L. ((\b. inv b * real_integral (real_interval[&0,b]) (\beta.
     carleson_theta' z alpha beta y))
            ---> L) at_posinfinity`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`z:real`;`alpha:real`;`y:real`] CARLESON_THETA'_PERIOD) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `L:int`) THEN
  EXISTS_TAC `inv(&2 zpow L) *
    real_integral (real_interval[&0,&2 zpow L]) (\beta. carleson_theta' z alpha
      beta y)` THEN
  MATCH_MP_TAC PERIODIC_CESARO_LIMIT THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC;
    GEN_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
    REWRITE_TAC[THETA'_BETA_INTEGRABLE];
    GEN_TAC THEN ASM_REWRITE_TAC[]]);;

(* periodic Cesaro lower bound (feeds 286R-h): f>=0 period-p with int_0^p f  *)
(* >= c*p forces the Cesaro average limit reallim (1/b) int_0^b f >= c.      *)
let PERIODIC_CESARO_LBOUND = prove
 (`!f p c. &0 < p /\ (!x. &0 <= f x) /\
           (!u v. f real_integrable_on real_interval[u,v]) /\
           (!b. f(b + p) = f b) /\
           c * p <= real_integral (real_interval[&0,p]) f
   ==> c <= reallim at_posinfinity
              (\b. inv b * real_integral (real_interval[&0,b]) f)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`f:real->real`; `p:real`] PERIODIC_CESARO_LIMIT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `reallim at_posinfinity (\b. inv b * real_integral (real_interval[&0,b]) f)
     =
    inv p * real_integral (real_interval[&0,p]) f`
   SUBST1_TAC THENL
   [MATCH_MP_TAC REALLIM_REALLIM_EQ THEN
     ASM_REWRITE_TAC[TRIVIAL_LIMIT_AT_POSINFINITY];
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `inv p * (c * p):real` THEN
      CONJ_TAC THENL
     [SUBGOAL_THEN
       `inv p * (c * p) =
        c:real` (fun th -> REWRITE_TAC[th; REAL_LE_REFL]) THEN
      UNDISCH_TAC `&0 < p` THEN CONV_TAC REAL_FIELD;
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN
         ASM_REAL_ARITH_TAC; ASM_REWRITE_TAC[]]]]);;

(* the averaged family converges TO carleson_g (y<z, alpha>0).               *)
let CARLESON_G_AVG_LIMIT = prove
 (`!alpha y z. &0 < alpha /\ y < z
   ==> ((\b. inv b * real_integral (real_interval[&0,b]) (\beta.
     carleson_theta' z alpha beta y))
        ---> carleson_g alpha y z) at_posinfinity`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`] CARLESON_G_CESARO) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `L:real`) THEN
  SUBGOAL_THEN `carleson_g alpha y z = L` SUBST1_TAC THENL
   [REWRITE_TAC[carleson_g] THEN MATCH_MP_TAC REALLIM_REALLIM_EQ THEN
    ASM_REWRITE_TAC[TRIVIAL_LIMIT_AT_POSINFINITY];
    ASM_REWRITE_TAC[]]);;

(* g = 0 for y >= z (the bump support is empty).                             *)
let CARLESON_G_TRIVIAL = prove
 (`!alpha y z. &0 < alpha /\ z <= y ==> carleson_g alpha y z = &0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_g] THEN
  MATCH_MP_TAC REALLIM_REALLIM_EQ THEN
    REWRITE_TAC[TRIVIAL_LIMIT_AT_POSINFINITY] THEN
  SUBGOAL_THEN
   `(\b. inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta' z
     alpha beta y)) =
    (\b. &0)` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    SUBGOAL_THEN
      `(\beta. carleson_theta' z alpha beta y) = (\beta. &0)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      MATCH_MP_TAC CARLESON_THETA'_SUPPORT THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_INTEGRAL_0; REAL_MUL_RZERO]];
    REWRITE_TAC[REALLIM_CONST]]);;

(* the averaged family lies in [0,1] for every b>0.                          *)
let CARLESON_G_AVG_BOUNDS = prove
 (`!alpha y z b. &0 < b
   ==> &0 <= inv b * real_integral (real_interval[&0,b]) (\beta.
     carleson_theta' z alpha beta y) /\
       inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta' z
         alpha beta y) <= &1`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `&0 <= real_integral (real_interval[&0,b]) (\beta. carleson_theta' z alpha
     beta y) /\
    real_integral (real_interval[&0,b]) (\beta. carleson_theta' z alpha beta y)
      <= b`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_POS THEN
      REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN
      REPEAT STRIP_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `real_integral (real_interval[&0,b]) (\beta. &1)` THEN
        CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INTEGRAL_LE THEN
        REWRITE_TAC[THETA'_BETA_INTEGRABLE; REAL_INTEGRABLE_CONST] THEN
        REPEAT STRIP_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
        ASM_SIMP_TAC[REAL_INTEGRAL_CONST; REAL_LT_IMP_LE] THEN
          ASM_REAL_ARITH_TAC]]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[REAL_LE_INV_EQ; REAL_LT_IMP_LE];
    SUBGOAL_THEN
     `inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta' z
       alpha beta y) <= inv b * b`
     MP_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN
       ASM_SIMP_TAC[REAL_LE_INV_EQ; REAL_LT_IMP_LE];
      ASM_SIMP_TAC[REAL_MUL_LINV; REAL_LT_IMP_NZ]]]);;

(* 286R-(c): 0 <= g <= 1.                                                    *)
let CARLESON_G_BOUNDS = prove
 (`!alpha y z. &0 < alpha ==> &0 <= carleson_g alpha y z /\ carleson_g alpha y
   z <= &1`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `(z:real) <= y` THENL
   [ASM_SIMP_TAC[CARLESON_G_TRIVIAL] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(y:real) < z` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`] CARLESON_G_AVG_LIMIT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPEC `at_posinfinity` REALLIM_LBOUND) THEN
    EXISTS_TAC `\b. inv b * real_integral (real_interval[&0,b]) (\beta.
      carleson_theta' z alpha beta y)` THEN
    ASM_REWRITE_TAC[TRIVIAL_LIMIT_AT_POSINFINITY;
      EVENTUALLY_AT_POSINFINITY] THEN
    EXISTS_TAC `&1` THEN X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN
      DISCH_TAC THEN
    MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`;`b:real`]
      CARLESON_G_AVG_BOUNDS) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC(ISPEC `at_posinfinity` REALLIM_UBOUND) THEN
    EXISTS_TAC `\b. inv b * real_integral (real_interval[&0,b]) (\beta.
      carleson_theta' z alpha beta y)` THEN
    ASM_REWRITE_TAC[TRIVIAL_LIMIT_AT_POSINFINITY;
      EVENTUALLY_AT_POSINFINITY] THEN
    EXISTS_TAC `&1` THEN X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN
      DISCH_TAC THEN
    MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`;`b:real`]
      CARLESON_G_AVG_BOUNDS) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[]]]);;

(* ========================================================================= *)
(* 286R-(d) translation-invariance and (g) scale-invariance of g.            *)
(* ========================================================================= *)

(* theta'_{z+gam,alpha,beta}(y+gam) = theta'_{z,alpha,beta+alpha*gam}(y).    *)
let THETA'_TRANSLATE = prove
 (`!z alpha beta y gam.
     carleson_theta' (z + gam) alpha beta (y + gam) =
     carleson_theta' z alpha (beta + alpha * gam) y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  SUBGOAL_THEN
    `alpha * (z + gam) + beta = alpha * z + beta + alpha * gam:real` SUBST1_TAC
    THENL
   [CONV_TAC REAL_RING; ALL_TAC] THEN
  SUBGOAL_THEN
    `alpha * (y + gam) + beta = alpha * y + beta + alpha * gam:real` SUBST1_TAC
    THENL
   [CONV_TAC REAL_RING; REFL_TAC]);;

(* the shifted-args average = the window-shifted average (c = alpha*gam).    *)
let CARLESON_G_SHIFT_AVG = prove
 (`!alpha y z gam b.
     inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta' (z +
       gam) alpha beta (y + gam)) =
     inv b * real_integral (real_interval[alpha * gam, alpha * gam + b])
       (\beta. carleson_theta' z alpha beta y)`,
  REPEAT GEN_TAC THEN AP_TERM_TAC THEN
  SUBGOAL_THEN
   `(\beta. carleson_theta' (z + gam) alpha beta (y + gam)) =
    (\beta. (\b. carleson_theta' z alpha b y) (beta + alpha * gam))` SUBST1_TAC
      THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[THETA'_TRANSLATE]; ALL_TAC] THEN
  CONV_TAC SYM_CONV THEN
  MP_TAC(SPECL [`\b. carleson_theta' z alpha b y`; `alpha * gam:real`;
    `b:real`] REAL_INTEGRAL_SHIFT) THEN
  REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN DISCH_THEN ACCEPT_TAC);;

(* 286R-(d), gamma >= 0: g(alpha,y+gam,z+gam) = g(alpha,y,z).                *)
let CARLESON_G_TRANSLATE_NONNEG = prove
 (`!alpha y z gam. &0 < alpha /\ y < z /\ &0 <= gam
   ==> carleson_g alpha (y + gam) (z + gam) = carleson_g alpha y z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`at_posinfinity`;
    `\b. inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta' (z
      + gam) alpha beta (y + gam))`;
    `carleson_g alpha (y + gam) (z + gam)`;
      `carleson_g alpha y z`] REALLIM_UNIQUE) THEN
  REWRITE_TAC[TRIVIAL_LIMIT_AT_POSINFINITY] THEN DISCH_THEN MATCH_MP_TAC THEN
    CONJ_TAC THENL
   [MP_TAC(SPECL [`alpha:real`;`y + gam:real`;`z + gam:real`]
     CARLESON_G_AVG_LIMIT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; REWRITE_TAC[]];
    ONCE_REWRITE_TAC[CARLESON_G_SHIFT_AVG] THEN
    GEN_REWRITE_TAC (RATOR_CONV o ONCE_DEPTH_CONV) [REAL_ADD_SYM] THEN
    MATCH_MP_TAC CESARO_SHIFT_INVARIANT THEN
    ASM_SIMP_TAC[REAL_LE_MUL; REAL_LT_IMP_LE] THEN
    REPEAT CONJ_TAC THENL
     [GEN_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
      GEN_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
      REWRITE_TAC[THETA'_BETA_INTEGRABLE];
      MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`] CARLESON_G_AVG_LIMIT) THEN
      ASM_REWRITE_TAC[]]]);;

(* 286R-(d), any gamma.                                                      *)
let CARLESON_G_TRANSLATE = prove
 (`!alpha y z gam. &0 < alpha /\ y < z
   ==> carleson_g alpha (y + gam) (z + gam) = carleson_g alpha y z`,
  REPEAT STRIP_TAC THEN
  DISJ_CASES_TAC(REAL_ARITH `&0 <= gam \/ &0 <= --gam`) THENL
   [MATCH_MP_TAC CARLESON_G_TRANSLATE_NONNEG THEN ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`alpha:real`;`y + gam:real`;`z + gam:real`;`--gam:real`]
      CARLESON_G_TRANSLATE_NONNEG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
      `(y + gam) + --gam:real = y /\ (z + gam) + --gam:real = z` (fun th ->
      REWRITE_TAC[th]) THENL
     [CONJ_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[SYM th])]);;

(* theta'_{gam*z,alpha,beta}(gam*y) = theta'_{z,alpha*gam,beta}(y).          *)
let THETA'_SCALE_ARG = prove
 (`!z alpha beta y gam.
     carleson_theta' (gam * z) alpha beta (gam * y) = carleson_theta' z (alpha
       * gam) beta y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta'; REAL_MUL_ASSOC]);;

(* 286R-(g): g(alpha, gam*y, gam*z) = g(alpha*gam, y, z).                    *)
let CARLESON_G_SCALE_ARG = prove
 (`!alpha y z gam. carleson_g alpha (gam * y) (gam * z) = carleson_g (alpha *
   gam) y z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_g] THEN
  AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[THETA'_SCALE_ARG]);;

(* ========================================================================= *)
(* 286R-(f) scale-doubling invariance g(2a,.)=g(a,.), and the                *)
(* carleson_thetatilde                                                       *)
(* definition (Fremlin mt286.tex 2611-2620, 2530).                           *)
(* ========================================================================= *)

(* int_0^{2c} f = 2 int_0^c (\x. f(2x)) for c>=0                             *)
(* (HAS_REAL_INTEGRAL_AFFINITY).                                             *)
let REAL_INTEGRAL_SCALE2 = prove
 (`!f c. &0 <= c /\ (!u v. f real_integrable_on real_interval[u,v])
   ==> real_integral (real_interval[&0,&2 * c]) f =
       &2 * real_integral (real_interval[&0,c]) (\x. f(&2 * x))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->real`;
    `real_interval[&0,&2 * c]`] REAL_INTEGRABLE_INTEGRAL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`&2`; `&0`] o MATCH_MP
    (REWRITE_RULE[TAUT `a /\ b ==> c <=> a ==> b ==> c`]
      HAS_REAL_INTEGRAL_AFFINITY)) THEN
  REWRITE_TAC[REAL_ARITH `~(&2 = &0)`; REAL_ADD_RID; REAL_ABS_NUM] THEN
  SUBGOAL_THEN
    `IMAGE (\x. inv(&2) * (x - &0)) (real_interval[&0,&2 * c]) =
    real_interval[&0,c]`
    SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL; REAL_SUB_RZERO] THEN
     X_GEN_TAC `t:real` THEN
    EQ_TAC THENL
     [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      STRIP_TAC THEN EXISTS_TAC `&2 * t` THEN CONJ_TAC THENL
       [REWRITE_TAC[REAL_ARITH `inv(&2) * &2 * t = t`]; ASM_REAL_ARITH_TAC]];
         ALL_TAC] THEN
  DISCH_THEN(MP_TAC o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REAL_ARITH_TAC);;

(* F ---> L at +inf  ==>  (\b. F(b/2)) ---> L at +inf.                       *)
let REALLIM_HALF_ARG = prove
 (`!F L. (F ---> L) at_posinfinity ==> ((\b. F(b / &2)) ---> L)
   at_posinfinity`,
  REPEAT GEN_TAC THEN REWRITE_TAC[REALLIM_AT_POSINFINITY] THEN
  DISCH_TAC THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `B:real`) THEN EXISTS_TAC `&2 * B` THEN
  X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN DISCH_TAC THEN
    BETA_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN REWRITE_TAC[real_ge] THEN
    ASM_REAL_ARITH_TAC);;

(* (1/b) int_0^b theta'_{z,2a,.}(y) = inv(b/2) int_0^{b/2}                   *)
(* theta'_{z,a,.}(y).                                                        *)
let CARLESON_G_SCALE2_AVG = prove
 (`!alpha y z b. &0 < b
   ==> inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta' z
     (&2 * alpha) beta y) =
       inv(b / &2) * real_integral (real_interval[&0,b / &2]) (\gm.
         carleson_theta' z alpha gm y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[real_div] THEN
  MP_TAC(SPECL [`\beta. carleson_theta' z (&2 * alpha) beta y`;
    `b * inv(&2)`] REAL_INTEGRAL_SCALE2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN
    ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&2 * (b * inv(&2)) = b` SUBST1_TAC THENL
    [CONV_TAC REAL_FIELD; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN CONV_TAC(DEPTH_CONV BETA_CONV) THEN
  SUBGOAL_THEN `(\x. carleson_theta' z (&2 * alpha) (&2 * x) y) =
                (\gm. carleson_theta' z alpha gm y)` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[CARLESON_THETA'_SCALE2]; ALL_TAC] THEN
  ABBREV_TAC `I2 = real_integral (real_interval[&0,b * inv(&2)]) (\gm.
    carleson_theta' z alpha gm y)` THEN
  SUBGOAL_THEN `~(b = &0)` MP_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  CONV_TAC REAL_FIELD);;

(* 286R-(f): g(2*alpha, y, z) = g(alpha, y, z) for alpha>0.                  *)
let CARLESON_G_SCALE2 = prove
 (`!alpha y z. &0 < alpha ==> carleson_g (&2 * alpha) y z = carleson_g alpha y
   z`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `(z:real) <= y` THENL
   [ASM_SIMP_TAC[CARLESON_G_TRIVIAL; REAL_ARITH `&0 < a ==> &0 < &2 * a`];
     ALL_TAC] THEN
  SUBGOAL_THEN `(y:real) < z` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`at_posinfinity`;
    `\b. inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta' z
      (&2 * alpha) beta y)`;
    `carleson_g (&2 * alpha) y z`; `carleson_g alpha y z`] REALLIM_UNIQUE) THEN
  REWRITE_TAC[TRIVIAL_LIMIT_AT_POSINFINITY] THEN DISCH_THEN MATCH_MP_TAC THEN
    CONJ_TAC THENL
   [MP_TAC(SPECL [`&2 * alpha`;`y:real`;`z:real`] CARLESON_G_AVG_LIMIT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; REWRITE_TAC[]];
    MATCH_MP_TAC REALLIM_TRANSFORM_EVENTUALLY THEN
    EXISTS_TAC `\b. (\c. inv c * real_integral (real_interval[&0,c]) (\gm.
      carleson_theta' z alpha gm y)) (b / &2)` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[EVENTUALLY_AT_POSINFINITY] THEN EXISTS_TAC `&1` THEN
      X_GEN_TAC `b:real` THEN REWRITE_TAC[real_ge] THEN DISCH_TAC THEN
        BETA_TAC THEN
      MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`;`b:real`]
        CARLESON_G_SCALE2_AVG) THEN
      ANTS_TAC THENL
        [ASM_REAL_ARITH_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])];
      MATCH_MP_TAC REALLIM_HALF_ARG THEN
      MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`] CARLESON_G_AVG_LIMIT) THEN
        ASM_REWRITE_TAC[]]]);;

(* carleson_thetatilde z y = int_1^2 (1/alpha) g(alpha,y,z) dalpha.          *)
let carleson_thetatilde = new_definition
 `carleson_thetatilde z y =
    real_integral (real_interval[&1,&2]) (\alpha. inv alpha * carleson_g alpha
      y z)`;;

(* ========================================================================= *)
(* Octave (log-)shift-invariance of int_gam^{2gam} (1/a) G(a) da for a       *)
(* function G with the doubling symmetry G(2a)=G(a) (a>0): the integral over *)
(* ANY octave [gam,2gam] equals the one over [1,2] (Fremlin 286R (e)-(g)).   *)
(* Elementary a=2x-affinity + split, measurable-friendly (no log             *)
(* substitution).                                                            *)
(* Integrability is required only on positive intervals (0<u), which is all  *)
(* we                                                                        *)
(* can supply for carleson_g (defined via a Cesaro limit that needs          *)
(* alpha>0).                                                                 *)
(* ========================================================================= *)

(* int_[2p,2q] inv a G da = int_[p,q] inv a G da  (0<p<=q).                  *)
let PARTIAL_DOUBLE = prove
 (`!G p q. &0 < p /\ p <= q /\
           (!a. &0 < a ==> G(&2 * a) = G a) /\
           (!u v. &0 < u ==> (\a. inv a * G a) real_integrable_on
             real_interval[u,v])
     ==> real_integral (real_interval[&2 * p,&2 * q]) (\a. inv a * G a) =
         real_integral (real_interval[p,q]) (\a. inv a * G a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `real_integral (real_interval[p,q]) (\x. inv(&2 * x) * G(&2 * x)) =
    inv(&2) * real_integral (real_interval[&2 * p,&2 * q]) (\a. inv a * G a)`
   (LABEL_TAC "str") THENL
   [MP_TAC(ISPECL [`\a. inv a * (G:real->real) a`;
                   `real_integral (real_interval[&2 * p,&2 * q]) (\a. inv a *
                     (G:real->real) a)`;
                   `&2 * p`; `&2 * q`; `&2`] HAS_REAL_INTEGRAL_STRETCH) THEN
    REWRITE_TAC[GSYM HAS_REAL_INTEGRAL_INTEGRAL] THEN
    SUBGOAL_THEN
      `(\a. inv a * G a) real_integrable_on real_interval[&2 * p,&2 * q]`
      (fun th -> REWRITE_TAC[th; REAL_ARITH `~(&2 = &0)`]) THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (\x. inv(&2) * x) (real_interval[&2 * p,&2 * q]) =
       real_interval[p,q]`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL] THEN
       X_GEN_TAC `t:real` THEN
      EQ_TAC THENL
       [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
        STRIP_TAC THEN EXISTS_TAC `&2 * t` THEN
        CONJ_TAC THENL [REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]];
      DISCH_THEN(MP_TAC o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN BETA_TAC THEN
      REWRITE_TAC[REAL_ABS_NUM]];
    SUBGOAL_THEN
     `real_integral (real_interval[p,q]) (\x. inv(&2) * inv x * G x) =
      inv(&2) * real_integral (real_interval[p,q]) (\a. inv a * G a)`
     (LABEL_TAC "lmul") THENL
     [MP_TAC(ISPECL [`\a. inv a * (G:real->real) a`; `inv(&2)`;
       `real_interval[p,q]`]
                    REAL_INTEGRAL_LMUL) THEN
      ANTS_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        MATCH_MP_TAC REAL_INTEGRAL_EQ THEN REWRITE_TAC[] THEN REAL_ARITH_TAC];
      SUBGOAL_THEN
       `real_integral (real_interval[p,q]) (\x. inv(&2 * x) * G(&2 * x)) =
        real_integral (real_interval[p,q]) (\x. inv(&2) * inv x * G x)`
       (LABEL_TAC "eq") THENL
       [MATCH_MP_TAC REAL_INTEGRAL_EQ THEN X_GEN_TAC `x:real` THEN
        REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `x:real` o
           check (fun t -> can (find_term (fun s -> s = `&2 * a`)) (concl t)))
             THEN
        ANTS_TAC THENL
         [ASM_REAL_ARITH_TAC;
          DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[REAL_INV_MUL] THEN
            REAL_ARITH_TAC];
        MATCH_MP_TAC(REAL_ARITH `inv(&2) * a = inv(&2) * b ==> a = b`) THEN
        USE_THEN "eq" (fun e -> USE_THEN "str" (fun s -> USE_THEN
          "lmul" (fun l ->
          REWRITE_TAC[GSYM s; GSYM l; e])))]]]);;

(* [1,2]-split case: for gam in [1,2], int_[gam,2gam] inv a G = int_[1,2]    *)
(* inv a G.                                                                  *)
let OCTAVE_INV_UNIT = prove
 (`!G gam. &1 <= gam /\ gam <= &2 /\
           (!a. &0 < a ==> G(&2 * a) = G a) /\
           (!u v. &0 < u ==> (\a. inv a * G a) real_integrable_on
             real_interval[u,v])
     ==> real_integral (real_interval[gam,&2 * gam]) (\a. inv a * G a) =
         real_integral (real_interval[&1,&2]) (\a. inv a * G a)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`G:real->real`; `&1:real`; `gam:real`] PARTIAL_DOUBLE) THEN
  ASM_REWRITE_TAC[REAL_MUL_RID; REAL_LT_01] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`\a. inv a * (G:real->real) a`; `gam:real`; `&2 * gam`; `&2`]
                REAL_INTEGRAL_COMBINE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC;
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\a. inv a * (G:real->real) a`; `&1:real`; `&2:real`;
    `gam:real`]
                REAL_INTEGRAL_COMBINE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC;
      FIRST_X_ASSUM MATCH_MP_TAC THEN REWRITE_TAC[REAL_LT_01]]; ALL_TAC] THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun t -> is_eq (concl t)))) THEN
  CONV_TAC REAL_ARITH);;

(* octave doubling equivalence PHI(2gam)=PHI(gam) (from PARTIAL_DOUBLE,      *)
(* p=gam,q=2gam).                                                            *)
let OCTAVE_DOUBLE_EQ = prove
 (`!G gam. &0 < gam /\
           (!a. &0 < a ==> G(&2 * a) = G a) /\
           (!u v. &0 < u ==> (\a. inv a * G a) real_integrable_on
             real_interval[u,v])
     ==> real_integral (real_interval[&2 * gam,&2 * (&2 * gam)]) (\a. inv a * G
       a) =
         real_integral (real_interval[gam,&2 * gam]) (\a. inv a * G a)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`G:real->real`; `gam:real`; `&2 * gam`] PARTIAL_DOUBLE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC);;

(* num-power ladder: PHI(2^n * gam) = PHI(gam).                              *)
let OCTAVE_POW2_LADDER = prove
 (`!G gam. &0 < gam /\
           (!a. &0 < a ==> G(&2 * a) = G a) /\
           (!u v. &0 < u ==> (\a. inv a * G a) real_integrable_on
             real_interval[u,v])
     ==> !n. real_integral (real_interval[&2 pow n * gam,&2 * (&2 pow n *
       gam)]) (\a. inv a * G a) =
             real_integral (real_interval[gam,&2 * gam]) (\a. inv a * G a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN INDUCT_TAC THENL
   [REWRITE_TAC[real_pow; REAL_MUL_LID];
    REWRITE_TAC[real_pow] THEN
    MP_TAC(ISPECL [`G:real->real`; `&2 pow n * gam`] OCTAVE_DOUBLE_EQ) THEN
    ASM_SIMP_TAC[REAL_LT_MUL; REAL_POW_LT; REAL_ARITH `&0 < &2`] THEN
    SUBGOAL_THEN `&2 * &2 pow n * gam = (&2 * &2 pow n) * gam` SUBST1_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

(* every gam>=1 is 2^n * delta with delta in [1,2).                          *)
let DYADIC_NORM_GE1 = prove
 (`!gam. &1 <= gam ==> ?n:num delta. &1 <= delta /\ delta < &2 /\ gam = &2 pow
   n * delta`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(ISPEC `gam:real` REAL_ARCH_POW2) THEN
  DISCH_THEN(X_CHOOSE_TAC `m:num`) THEN
  SUBGOAL_THEN `?n. gam < &2 pow n` (MP_TAC o ONCE_REWRITE_RULE[num_WOP]) THENL
   [EXISTS_TAC `m:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `1 <= n` ASSUME_TAC THENL
   [REWRITE_TAC[ARITH_RULE `1 <= n <=> ~(n = 0)`] THEN DISCH_TAC THEN
    UNDISCH_TAC `gam < &2 pow n` THEN ASM_REWRITE_TAC[real_pow] THEN
      ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n - 1`) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; REWRITE_TAC[REAL_NOT_LT] THEN DISCH_TAC] THEN
  MAP_EVERY EXISTS_TAC [`n - 1`; `gam / &2 pow (n - 1)`] THEN
  SUBGOAL_THEN `&0 < &2 pow (n - 1)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN ASM_REWRITE_TAC[REAL_MUL_LID];
    ASM_SIMP_TAC[REAL_LT_LDIV_EQ] THEN
    SUBGOAL_THEN `&2 * &2 pow (n - 1) = &2 pow n` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM(CONJUNCT2 real_pow)] THEN AP_TERM_TAC THEN
       ASM_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ASM_SIMP_TAC[REAL_DIV_LMUL; REAL_LT_IMP_NZ]]);;

(* every gam in (0,1) has 2^n * gam in [1,2).                                *)
let DYADIC_NORM_LT1 = prove
 (`!gam. &0 < gam /\ gam < &1 ==> ?n:num delta. &1 <= delta /\ delta < &2 /\ &2
   pow n * gam = delta`,
  GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `?n:num. &1 <= &2 pow n * gam` (MP_TAC o ONCE_REWRITE_RULE[num_WOP]) THENL
   [MP_TAC(SPEC `inv(gam:real)` REAL_ARCH_POW2) THEN
     DISCH_THEN(X_CHOOSE_TAC `m:num`) THEN
    EXISTS_TAC `m:num` THEN
    SUBGOAL_THEN `&1 = gam * inv gam` SUBST1_TAC THENL
     [CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_MUL_RINV THEN
       ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `gam * &2 pow m` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC];
      REWRITE_TAC[REAL_MUL_SYM] THEN REAL_ARITH_TAC]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `1 <= n` ASSUME_TAC THENL
   [REWRITE_TAC[ARITH_RULE `1 <= n <=> ~(n = 0)`] THEN DISCH_TAC THEN
    UNDISCH_TAC `&1 <= &2 pow n * gam` THEN
      ASM_REWRITE_TAC[real_pow; REAL_MUL_LID] THEN
    ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n - 1`) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; REWRITE_TAC[REAL_NOT_LE] THEN DISCH_TAC] THEN
  MAP_EVERY EXISTS_TAC [`n:num`; `&2 pow n * gam`] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&2 pow n * gam = &2 * (&2 pow (n - 1) * gam)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_MUL_ASSOC] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[GSYM(CONJUNCT2 real_pow)] THEN AP_TERM_TAC THEN ASM_ARITH_TAC;
    ASM_REAL_ARITH_TAC]);;

(* unified: every gam>0 is 2^n*delta OR 2^n*gam=delta, delta in [1,2).       *)
let DYADIC_NORM = prove
 (`!gam. &0 < gam
     ==> ?n:num delta. &1 <= delta /\ delta < &2 /\
                       (gam = &2 pow n * delta \/ &2 pow n * gam = delta)`,
  GEN_TAC THEN DISCH_TAC THEN ASM_CASES_TAC `gam < &1` THENL
   [MP_TAC(SPEC `gam:real` DYADIC_NORM_LT1) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN MAP_EVERY EXISTS_TAC [`n:num`; `delta:real`] THEN
      ASM_REWRITE_TAC[];
    MP_TAC(SPEC `gam:real` DYADIC_NORM_GE1) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    STRIP_TAC THEN MAP_EVERY EXISTS_TAC [`n:num`; `delta:real`] THEN
      ASM_REWRITE_TAC[]]);;

(* general-gam octave shift-invariance, generic G: int_[gam,2gam] =          *)
(* int_[1,2], gam>0.                                                         *)
let CARLESON_G_OCTAVE_ABSTRACT = prove
 (`!G gam. &0 < gam /\
           (!a. &0 < a ==> G(&2 * a) = G a) /\
           (!u v. &0 < u ==> (\a. inv a * G a) real_integrable_on
             real_interval[u,v])
     ==> real_integral (real_interval[gam,&2 * gam]) (\a. inv a * G a) =
         real_integral (real_interval[&1,&2]) (\a. inv a * G a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPEC `gam:real` DYADIC_NORM) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (X_CHOOSE_THEN
    `delta:real` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `real_integral (real_interval[delta,&2 * delta]) (\a. inv a * G a) =
    real_integral (real_interval[&1,&2]) (\a. inv a * G a)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC OCTAVE_INV_UNIT THEN ASM_REWRITE_TAC[] THEN
     ASM_REAL_ARITH_TAC;
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`G:real->real`; `delta:real`] OCTAVE_POW2_LADDER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `n:num`) THEN DISCH_THEN SUBST1_TAC THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC OCTAVE_INV_UNIT THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC;
    MP_TAC(ISPECL [`G:real->real`; `gam:real`] OCTAVE_POW2_LADDER) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `n:num`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      ASM_REWRITE_TAC[]]);;

(* the log-average integrand is nonnegative on [1,2].                        *)
let COUNTABLE_SHIFT_PREIMAGE = prove
 (`!c:real D. COUNTABLE D ==> COUNTABLE {beta | (c + beta) IN D}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC COUNTABLE_SUBSET THEN
  EXISTS_TAC `IMAGE (\d:real. d - c) D` THEN ASM_SIMP_TAC[COUNTABLE_IMAGE] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_IMAGE] THEN
  X_GEN_TAC `b:real` THEN DISCH_TAC THEN EXISTS_TAC `c + b:real` THEN
  CONJ_TAC THENL [REAL_ARITH_TAC; ASM_REWRITE_TAC[]]);;

(* the dyadic points {real_of_int n * 2^k} are countable.                    *)
let DYADIC_COUNTABLE = prove
 (`COUNTABLE (IMAGE (\(n,k). real_of_int n * &2 zpow k) (:int#int))`,
  MATCH_MP_TAC COUNTABLE_IMAGE THEN REWRITE_TAC[GSYM CROSS_UNIV] THEN
  MATCH_MP_TAC COUNTABLE_CROSS THEN REWRITE_TAC[INT_COUNTABLE]);;

(* ... hence negligible as a subset of R^1.                                  *)
let THETA_BAD_BETA_NEGLIGIBLE = prove
 (`!alpha y z. negligible
     (IMAGE lift {beta | (alpha * z + beta) IN (IMAGE (\(n,k). real_of_int n *
       &2 zpow k) (:int#int)) \/
                         (alpha * y + beta) IN (IMAGE (\(n,k). real_of_int n *
                           &2 zpow k) (:int#int))})`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC NEGLIGIBLE_COUNTABLE THEN
    MATCH_MP_TAC COUNTABLE_IMAGE THEN
  REWRITE_TAC[SET_RULE `{beta | P beta \/ Q beta} = {beta | P beta} UNION {beta
    | Q beta}`] THEN
  REWRITE_TAC[COUNTABLE_UNION] THEN CONJ_TAC THEN
  MATCH_MP_TAC COUNTABLE_SHIFT_PREIMAGE THEN REWRITE_TAC[DYADIC_COUNTABLE]);;


(* carleson_theta sups over (k,nJ) only -- nI is inert in tile_k/Jr/Jl/ymid. *)
(* This reindexing is the first structural brick toward theta's local        *)
(* continuity at non-dyadic points (the DCT-continuity route to              *)
(* alpha-measurability of g).                                                *)
let THETA_NODEP_NI = prove
 (`!z y. carleson_theta z y =
    sup ({ Re(fourier carleson_phi (&2 zpow (--k) * (y - dyho_mid (k - &1) (&2
      * nJ)))) pow 2
         | (k,nJ) | z IN dyho (k - &1) (&2 * nJ + &1) /\ y IN dyho (k - &1) (&2
           * nJ) } UNION {&0})`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta] THEN AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_SING; IN_ELIM_THM] THEN
  X_GEN_TAC `w:real` THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  EQ_TAC THEN STRIP_TAC THENL
   [MAP_EVERY EXISTS_TAC [`tile_k (s:int#int#int)`;
     `SND(SND(s:int#int#int))`] THEN
    SUBGOAL_THEN
      `tile_Jr (s:int#int#int) = dyho (tile_k s - &1) (&2 * SND(SND s) + &1) /\
                  tile_Jl (s:int#int#int) = dyho (tile_k s - &1) (&2 * SND(SND
                    s)) /\
                  tile_ymid (s:int#int#int) = dyho_mid (tile_k s - &1) (&2 *
                    SND(SND s))`
      (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th]) THEN
        ASM_REWRITE_TAC[th]) THEN
    MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `k:int` (X_CHOOSE_THEN
      `q:int#int` SUBST1_TAC)) THEN
    MP_TAC(ISPEC `q:int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `nI:int` (X_CHOOSE_THEN `nJ:int` SUBST1_TAC)) THEN
    REWRITE_TAC[tile_k; tile_ymid; tile_Jr; tile_Jl; SND];
    EXISTS_TAC `(k:int,(&0):int,nJ:int)` THEN
    ASM_REWRITE_TAC[tile_k; tile_ymid; tile_Jr; tile_Jl]]);;

(* each qualifying (k,nJ)-term is <= carleson_theta z y (a sup upper bound). *)
let THETA_TERM_LE = prove
 (`!z y k nJ. z IN dyho (k - &1) (&2 * nJ + &1) /\ y IN dyho (k - &1) (&2 * nJ)
   ==> Re(fourier carleson_phi (&2 zpow (--k) * (y - dyho_mid (k - &1) (&2 *
     nJ)))) pow 2
       <= carleson_theta z y`,
  REPEAT STRIP_TAC THEN GEN_REWRITE_TAC RAND_CONV [THETA_NODEP_NI] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  MAP_EVERY EXISTS_TAC [`&1`;
    `Re(fourier carleson_phi (&2 zpow (--k) * (y - dyho_mid (k - &1) (&2 *
      nJ)))) pow 2`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_UNION; IN_ELIM_THM] THEN DISJ1_TAC THEN
    MAP_EVERY EXISTS_TAC [`k:int`; `nJ:int`] THEN ASM_REWRITE_TAC[];
    REAL_ARITH_TAC;
    X_GEN_TAC `w:real` THEN REWRITE_TAC[IN_UNION; IN_ELIM_THM; IN_SING] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[CARLESON_THETA_TERM_BOUNDS; REAL_LE_01]]);;

(* k-band lower bound: a qualifying tile forces Z - Y < 2^k (Z,Y in adjacent *)
(* (k-1)-cells). With CARLESON_TILE_GATE (2^k <= 20(Z-Y), window nonzero)    *)
(* this                                                                      *)
(* pins k to a finite band Z-Y < 2^k <= 20(Z-Y): the finiteness making       *)
(* carleson_theta a max of finitely many continuous windows near a           *)
(* non-dyadic pt.                                                            *)
let THETA_JR_JL_KBAND_LO = prove
 (`!k nJ Z Y. Z IN dyho (k - &1) (&2 * nJ + &1) /\ Y IN dyho (k - &1) (&2 * nJ)
   ==> Z - Y < &2 zpow k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN STRIP_TAC THEN
  GEN_REWRITE_TAC (RAND_CONV) [ZPOW2_PRED] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[GSYM REAL_OF_INT_CLAUSES]) THEN
  ASM_REAL_ARITH_TAC);;

(* out-of-band qualifying tile has zero window (CARLESON_TILE_GATE           *)
(* contrapositive).                                                          *)
let THETA_OUTBAND_ZERO = prove
 (`!z y k nJ. z IN dyho (k - &1) (&2 * nJ + &1) /\ ~(&2 zpow k <= &20 * (z -
   y))
   ==> Re(fourier carleson_phi (&2 zpow (--k) * (y - dyho_mid (k - &1) (&2 *
     nJ)))) pow 2 = &0`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`k:int`;`(&0):int`;`nJ:int`;`z:real`;`y:real`]
    CARLESON_TILE_GATE) THEN
  REWRITE_TAC[tile_Jr; tile_k; tile_ymid] THEN
  ASM_CASES_TAC `Re(fourier carleson_phi (&2 zpow (--k) * (y - dyho_mid (k -
    &1) (&2 * nJ)))) pow 2 = &0` THEN
  ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC);;

(* carleson_theta as a sup RESTRICTED to the finite k-band                   *)
(* (Z-Y<2^k<=20(Z-Y)): out-of-band terms have zero window, so dropping them  *)
(* leaves the sup unchanged. This finite-band representation is the base for *)
(* theta's local continuity at non-dyadic points (B1, the DCT route to       *)
(* alpha-measurability of g).                                                *)
let THETA_BAND_SUP = prove
 (`!z y. carleson_theta z y =
    sup ({ Re(fourier carleson_phi (&2 zpow (--k) * (y - dyho_mid (k - &1) (&2
      * nJ)))) pow 2
         | (k,nJ) | z IN dyho (k - &1) (&2 * nJ + &1) /\ y IN dyho (k - &1) (&2
           * nJ) /\
                    &2 zpow k <= &20 * (z - y) } UNION {&0})`,
  REPEAT GEN_TAC THEN GEN_REWRITE_TAC LAND_CONV [THETA_NODEP_NI] THEN
    AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_SING; IN_ELIM_THM] THEN
  X_GEN_TAC `w:real` THEN EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
   [ASM_CASES_TAC `&2 zpow k <= &20 * (z - y)` THENL
     [DISJ1_TAC THEN MAP_EVERY EXISTS_TAC [`k:int`; `nJ:int`] THEN
       ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
        MP_TAC(SPECL [`z:real`;`y:real`;`k:int`;
                      `nJ:int`] THETA_OUTBAND_ZERO) THEN
      ASM_REWRITE_TAC[]];
    DISJ1_TAC THEN MAP_EVERY EXISTS_TAC [`k:int`; `nJ:int`] THEN
      ASM_REWRITE_TAC[]]);;

(* dyadic-cell interior stability: if x0 is STRICTLY interior to dyho k n,   *)
(* then any                                                                  *)
(* sequence converging to x0 eventually lands in dyho k n. This makes the    *)
(* tile                                                                      *)
(* memberships stable under the alpha-perturbation at a non-dyadic point --  *)
(* the                                                                       *)
(* mechanism behind theta's local continuity (B1).                           *)
let DYHO_INTERIOR_STABLE = prove
 (`!k n x0 (xseq:num->real).
     real_of_int n * &2 zpow k < x0 /\ x0 < (real_of_int n + &1) * &2 zpow k /\
     (xseq ---> x0) sequentially
     ==> eventually (\m. xseq m IN dyho k n) sequentially`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REALLIM_SEQUENTIALLY]) THEN
  DISCH_THEN(MP_TAC o SPEC `min (x0 - real_of_int n * &2 zpow k)
                               ((real_of_int n + &1) * &2 zpow k - x0)`) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN
  DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN EXISTS_TAC `N:num` THEN
  X_GEN_TAC `m:num` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[dyho; IN_ELIM_THM] THEN ASM_REAL_ARITH_TAC);;

(* window continuity: y |-> Re(fourier carleson_phi (A*(y-m)))^2 is          *)
(* continuous on R                                                           *)
(* (carleson_phi Schwartz => fourier continuous; compose), hence             *)
(* real_continuous                                                           *)
(* atreal every point, hence preserves sequential limits. The second B1      *)
(* continuity                                                                *)
(* ingredient (with DYHO_INTERIOR_STABLE) for theta's local continuity.      *)
let WINDOW_CONTINUOUS_ON = prove
 (`!A m. (\y. Re(fourier carleson_phi (A * (y - m))) pow 2) real_continuous_on
   (:real)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON; IMAGE_LIFT_UNIV; o_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_POW THEN
  REWRITE_TAC[RE_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
  SUBGOAL_THEN
   `(\z:real^1. fourier carleson_phi (A * (drop z - m))) =
    (\w:real^1. fourier carleson_phi (drop w)) o (\z:real^1. lift(A * (drop z -
      m)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [REWRITE_TAC[LIFT_CMUL; LIFT_SUB] THEN
    MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN MATCH_MP_TAC CONTINUOUS_ON_SUB THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
    SUBGOAL_THEN `(\z:real^1. lift(drop z)) = (\z:real^1. z)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; LIFT_DROP]; REWRITE_TAC[CONTINUOUS_ON_ID]];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN
      MATCH_MP_TAC SCHWARTZ_ABSINT THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
      REWRITE_TAC[SUBSET_UNIV]]]);;

let WINDOW_ATREAL = prove
 (`!A m y. (\y. Re(fourier carleson_phi (A * (y - m))) pow 2) real_continuous
   atreal y`,
  REPEAT GEN_TAC THEN
  MP_TAC(SPECL [`A:real`;`m:real`] WINDOW_CONTINUOUS_ON) THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON_EQ_CONTINUOUS_WITHIN] THEN
  DISCH_THEN(MP_TAC o SPEC `y:real`) THEN
    REWRITE_TAC[IN_UNIV; WITHINREAL_UNIV]);;

let WINDOW_REALLIM = prove
 (`!A m (yseq:num->real) y0. (yseq ---> y0) sequentially
   ==> ((\n. Re(fourier carleson_phi (A * (yseq n - m))) pow 2)
        ---> Re(fourier carleson_phi (A * (y0 - m))) pow 2) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\y. Re(fourier carleson_phi (A * (y - m))) pow 2`;
    `sequentially`; `yseq:num->real`;
      `y0:real`] REALLIM_REAL_CONTINUOUS_FUNCTION) THEN
  ASM_REWRITE_TAC[WINDOW_ATREAL] THEN REWRITE_TAC[]);;

(* At a non-dyadic point, dyho membership is STRICT interior (open cell).    *)
let DYHO_NONDYADIC_INTERIOR = prove
 (`!k n Z. Z IN dyho k n /\
           ~(Z IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int))
   ==> real_of_int n * &2 zpow k < Z /\ Z < (real_of_int n + &1) * &2 zpow k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[dyho; IN_ELIM_THM] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `~(Z = real_of_int n * &2 zpow k)` MP_TAC THENL
   [DISCH_TAC THEN
    UNDISCH_TAC `~(Z IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int))`
      THEN
    REWRITE_TAC[] THEN REWRITE_TAC[IN_IMAGE; IN_UNIV] THEN
    EXISTS_TAC `(n:int,k:int)` THEN ASM_REWRITE_TAC[];
    ASM_REAL_ARITH_TAC]);;

(* The affine curve b |-> aseq n * z + beta converges when aseq -> alpha.    *)
let CURVE_LIM = prove
 (`!aseq alpha z beta. (aseq ---> alpha) sequentially
   ==> ((\n. aseq n * z + beta) ---> alpha * z + beta) sequentially`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REALLIM_ADD THEN REWRITE_TAC[REALLIM_CONST] THEN
  MATCH_MP_TAC REALLIM_RMUL THEN ASM_REWRITE_TAC[]);;

(* Lower-semicontinuity of carleson_theta along the affine curve at a        *)
(* non-dyadic base point: eventually theta on the aseq-curve exceeds the     *)
(* base                                                                      *)
(* value minus eps.  The single active tile (k0,nI0,nJ0) stays a witness     *)
(* (memberships stable at an interior point) and its window value is         *)
(* continuous.                                                               *)
let ZPOW2_POSITIVE = prove
 (`!k:int. &0 < &2 zpow k`,
  GEN_TAC THEN MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC);;

let ZPOW_NEG_GATE = prove
 (`!c1 k:int. &0 < c1 /\ c1 < &2 zpow k ==> &2 zpow (--k) < inv c1`,
  REPEAT STRIP_TAC THEN SUBGOAL_THEN
    `&2 zpow (--k) = inv(&2 zpow k)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_NEG]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LT_INV2 THEN ASM_REWRITE_TAC[]);;

let ZPOW_BAND_FINITE = prove
 (`!c1 c2. &0 < c1 ==> FINITE {k:int | c1 < &2 zpow k /\ &2 zpow k <= c2}`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `&0 < c2` THENL
   [ALL_TAC;
    SUBGOAL_THEN
      `{k:int | c1 < &2 zpow k /\ &2 zpow k <= c2} = {}` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
       X_GEN_TAC `k:int` THEN
      MP_TAC(SPEC `k:int` ZPOW2_POSITIVE) THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[FINITE_EMPTY]]] THEN
  MP_TAC(SPEC `c2:real` CARLESON_GATE_L_EXISTS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `U:int` (LABEL_TAC "UB")) THEN
  MP_TAC(ISPEC `inv(c1:real)` CARLESON_GATE_L_EXISTS) THEN
    ASM_SIMP_TAC[REAL_LT_INV] THEN
  DISCH_THEN(X_CHOOSE_THEN `V:int` (LABEL_TAC "VB")) THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `{k:int | --V <= k /\ k <= U}` THEN
  REWRITE_TAC[FINITE_INT_SEG] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `k:int` THEN STRIP_TAC THEN
  SUBGOAL_THEN `&2 zpow (--k) <= inv c1` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_IMP_LE THEN MATCH_MP_TAC ZPOW_NEG_GATE THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `k:int <= U` ASSUME_TAC THENL
   [USE_THEN "UB" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `--k:int <= V` ASSUME_TAC THENL
   [USE_THEN "VB" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_INT_ARITH_TAC);;

(* At an interior point x0 of dyho k n, a sequence converging to x0          *)
(* eventually avoids every OTHER same-scale cell dyho k m (m<>n), by cell    *)
(* disjointness.                                                             *)
let SUP_FINITE_REALLIM = prove
 (`!(s:A->bool) f L.
     FINITE s /\ (!i. i IN s ==> ((\n. f (i:A) n) ---> L i) sequentially)
     ==> ((\n. sup ({f i n | i IN s} UNION {&0}))
          ---> sup ({L i | i IN s} UNION {&0})) sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `!(g:A->real) t:A->bool. {g i | i IN t} UNION {&0} = (&0) INSERT IMAGE g t`
    (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[SIMPLE_IMAGE; EXTENSION; IN_UNION; IN_INSERT; IN_SING;
     IN_IMAGE] THEN
    MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN X_GEN_TAC `eps:real` THEN
    DISCH_TAC THEN
  ASM_CASES_TAC `s:A->bool = {}` THENL
   [ASM_REWRITE_TAC[IMAGE_CLAUSES; SUP_SING; REAL_SUB_REFL; REAL_ABS_NUM] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eventually (\x:num. !a:A. a IN s ==> abs(f a x - L a) < eps / &2)
     sequentially`
   MP_TAC THENL
   [ASM_SIMP_TAC[EVENTUALLY_FORALL] THEN X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `i:A`) THEN
      ASM_REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN
    DISCH_THEN(MP_TAC o SPEC `eps / &2`) THEN
    ASM_SIMP_TAC[REAL_HALF; EVENTUALLY_SEQUENTIALLY]; ALL_TAC] THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN
  DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN EXISTS_TAC `N:num` THEN
  X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
  SUBGOAL_THEN
    `!(g:A->real). &0 <= sup ((&0) INSERT IMAGE g s)` (LABEL_TAC "NN") THENL
   [GEN_TAC THEN
    ASM_SIMP_TAC[REAL_LE_SUP_FINITE; FINITE_INSERT; FINITE_IMAGE;
      NOT_INSERT_EMPTY] THEN
    EXISTS_TAC `&0` THEN REWRITE_TAC[IN_INSERT; REAL_LE_REFL]; ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH
    `a <= b + e / &2 /\ b <= a + e / &2 /\ &0 < e ==> abs(a - b) < e`) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[REAL_SUP_LE_FINITE; FINITE_INSERT; FINITE_IMAGE;
     NOT_INSERT_EMPTY] THEN
    REWRITE_TAC[FORALL_IN_INSERT; FORALL_IN_IMAGE] THEN CONJ_TAC THENL
     [USE_THEN "NN" (MP_TAC o SPEC `L:A->real`) THEN ASM_REAL_ARITH_TAC;
      X_GEN_TAC `i:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
        `(L:A->real) i <= sup ((&0) INSERT IMAGE L s)` ASSUME_TAC THENL
       [ASM_SIMP_TAC[REAL_LE_SUP_FINITE; FINITE_INSERT; FINITE_IMAGE;
         NOT_INSERT_EMPTY] THEN
        EXISTS_TAC `(L:A->real) i` THEN CONJ_TAC THENL
         [REWRITE_TAC[IN_INSERT; IN_IMAGE] THEN DISJ2_TAC THEN
          EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[]; REWRITE_TAC[REAL_LE_REFL]];
        ALL_TAC] THEN
      SUBGOAL_THEN
        `abs((f:A->num->real) i n - L i) < eps / &2` ASSUME_TAC THENL
       [FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `i:A` th)) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REAL_ARITH_TAC];
    ASM_SIMP_TAC[REAL_SUP_LE_FINITE; FINITE_INSERT; FINITE_IMAGE;
      NOT_INSERT_EMPTY] THEN
    REWRITE_TAC[FORALL_IN_INSERT; FORALL_IN_IMAGE] THEN CONJ_TAC THENL
     [USE_THEN "NN" (MP_TAC o ISPEC `(\i. (f:A->num->real) i n):A->real`) THEN
       ASM_REAL_ARITH_TAC;
      X_GEN_TAC `j:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
        `(f:A->num->real) j n <= sup ((&0) INSERT IMAGE (\i. f (i:A) n) s)`
        ASSUME_TAC THENL
       [ASM_SIMP_TAC[REAL_LE_SUP_FINITE; FINITE_INSERT; FINITE_IMAGE;
         NOT_INSERT_EMPTY] THEN
        EXISTS_TAC `(f:A->num->real) j n` THEN CONJ_TAC THENL
         [REWRITE_TAC[IN_INSERT; IN_IMAGE] THEN DISJ2_TAC THEN
          EXISTS_TAC `j:A` THEN ASM_REWRITE_TAC[]; REWRITE_TAC[REAL_LE_REFL]];
        ALL_TAC] THEN
      SUBGOAL_THEN
        `abs((f:A->num->real) j n - L j) < eps / &2` ASSUME_TAC THENL
       [FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `j:A` th)) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REAL_ARITH_TAC]]);;

(* (i) the base qualifying set F of the k-band sup at (Z0,Y0), Y0<Z0, is     *)
(* FINITE. Each (k,nJ) in F has Z0-Y0 < 2^k <= 20(Z0-Y0) (KBAND_LO + gate),  *)
(* so k in the finite ZPOW_BAND_FINITE band; nJ is unique per k (Y0 in a     *)
(* unique even (k-1)-cell, DYHO_DISJOINT_SAMESCALE), so F is the image of    *)
(* the finite band.                                                          *)
let THETA_F_FINITE = prove
 (`!Z0 Y0. Y0 < Z0
   ==> FINITE {(k,nJ) | Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                        Y0 IN dyho (k - &1) (&2 * nJ) /\
                        &2 zpow k <= &20 * (Z0 - Y0)}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC
   `IMAGE (\k. (k, @nJ. Y0 IN dyho (k - &1) (&2 * nJ)))
          {k:int | Z0 - Y0 < &2 zpow k /\ &2 zpow k <= &20 * (Z0 - Y0)}` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_IMAGE THEN MATCH_MP_TAC ZPOW_BAND_FINITE THEN
    ASM_REAL_ARITH_TAC;
    REWRITE_TAC[SUBSET; FORALL_PAIR_THM; IN_ELIM_PAIR_THM; IN_IMAGE;
      IN_ELIM_THM] THEN
    MAP_EVERY X_GEN_TAC [`k:int`; `nJ:int`] THEN STRIP_TAC THEN
    EXISTS_TAC `k:int` THEN REWRITE_TAC[PAIR_EQ] THEN
    REPEAT CONJ_TAC THENL
     [CONV_TAC SYM_CONV THEN MATCH_MP_TAC SELECT_UNIQUE THEN
       X_GEN_TAC `m:int` THEN
      REWRITE_TAC[] THEN EQ_TAC THENL
       [DISCH_TAC THEN GEN_REWRITE_TAC I [TAUT `p <=> ~ ~p`] THEN
         DISCH_TAC THEN
        MP_TAC(ISPECL [`k - &1:int`;`&2 * m:int`;`&2 * nJ:int`]
          DYHO_DISJOINT_SAMESCALE) THEN
        ANTS_TAC THENL [ASM_INT_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
        DISCH_THEN(MP_TAC o SPEC `Y0:real`) THEN ASM_REWRITE_TAC[];
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]];
      MP_TAC(ISPECL [`k:int`;`nJ:int`;`Z0:real`;`Y0:real`]
        THETA_JR_JL_KBAND_LO) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]]);;

(* At a non-dyadic base, each qualifying tile has Z0,Y0 STRICTLY interior to *)
(* its two cells (open-cell membership at a non-dyadic point).               *)
let THETA_F_STRICT = prove
 (`!Z0 Y0 k nJ.
     Z0 IN dyho (k - &1) (&2 * nJ + &1) /\ Y0 IN dyho (k - &1) (&2 * nJ) /\
     ~(Z0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     ~(Y0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int))
     ==> real_of_int (&2 * nJ + &1) * &2 zpow (k - &1) < Z0 /\
         Z0 < (real_of_int (&2 * nJ + &1) + &1) * &2 zpow (k - &1) /\
         real_of_int (&2 * nJ) * &2 zpow (k - &1) < Y0 /\
         Y0 < (real_of_int (&2 * nJ) + &1) * &2 zpow (k - &1)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`k - &1:int`; `&2 * nJ:int`;
    `Y0:real`] DYHO_NONDYADIC_INTERIOR) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`k - &1:int`; `&2 * nJ + &1:int`;
    `Z0:real`] DYHO_NONDYADIC_INTERIOR) THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* A tile whose base cells contain Z0,Y0 in their interior stays a witness   *)
(* along the Zseq/Yseq curves: eventually its window <= theta(Zseq n)(Yseq   *)
(* n).                                                                       *)
let THETA_TERM_EVENTUAL_LE = prove
 (`!Zseq Yseq Z0 Y0 k nJ.
     (Zseq ---> Z0) sequentially /\ (Yseq ---> Y0) sequentially /\
     real_of_int (&2 * nJ + &1) * &2 zpow (k - &1) < Z0 /\
     Z0 < (real_of_int (&2 * nJ + &1) + &1) * &2 zpow (k - &1) /\
     real_of_int (&2 * nJ) * &2 zpow (k - &1) < Y0 /\
     Y0 < (real_of_int (&2 * nJ) + &1) * &2 zpow (k - &1)
     ==> eventually
          (\n. Re(fourier carleson_phi
                   (&2 zpow (--k) * (Yseq n - dyho_mid (k - &1) (&2 * nJ))))
                     pow 2
               <= carleson_theta (Zseq n) (Yseq n)) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`k - &1:int`; `&2 * nJ + &1:int`; `Z0:real`; `Zseq:num->real`]
    DYHO_INTERIOR_STABLE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`k - &1:int`; `&2 * nJ:int`; `Y0:real`; `Yseq:num->real`]
    DYHO_INTERIOR_STABLE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`sequentially`;
    `\n:num. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\ Yseq n IN dyho (k - &1)
      (&2 * nJ)`;
    `\n:num. Re(fourier carleson_phi
                 (&2 zpow (--k) * (Yseq n - dyho_mid (k - &1) (&2 * nJ)))) pow
                   2
             <= carleson_theta (Zseq n) (Yseq n)`] EVENTUALLY_MONO) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [X_GEN_TAC `n:num` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`Zseq (n:num):real`; `Yseq (n:num):real`; `k:int`; `nJ:int`]
      THETA_TERM_LE) THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[EVENTUALLY_AND]]);;

(* LOWER (LSC) half of the theta-continuity sandwich: eventually the sup     *)
(* over the FIXED base gated set F0 of the window at Yseq n is <= theta(Zseq *)
(* n)(Yseq n). Each F0-term qualifies eventually (THETA_TERM_EVENTUAL_LE via *)
(* THETA_F_STRICT); F0 finite (THETA_F_FINITE) so EVENTUALLY_FORALL; then    *)
(* REAL_SUP_LE (0<=theta for the {0} floor, CARLESON_THETA_BOUNDS).          *)
let DYHO_SAME_POINT_INDEX = prove
 (`!k a b x:real. x IN dyho k a /\ x IN dyho k b ==> a = b`,
  REPEAT STRIP_TAC THEN GEN_REWRITE_TAC I [TAUT `p <=> ~ ~p`] THEN
    DISCH_TAC THEN
  MP_TAC(ISPECL [`k:int`;`a:int`;`b:int`] DYHO_DISJOINT_SAMESCALE) THEN
  ASM_REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `x:real`) THEN ASM_REWRITE_TAC[]);;

(* k-localization: eventually any gated-qualifying tile at step n has 2^k in *)
(* (d0/2, 40 d0), d0=Z0-Y0>0. qual gives Zseq n-Yseq n < 2^k <= 20(Zseq      *)
(* n-Yseq n)                                                                 *)
(* (THETA_JR_JL_KBAND_LO); eventually Zseq n-Yseq n in (d0/2,2 d0)           *)
(* (REALLIM_SUB).                                                            *)
let THETA_QUAL_KLOCAL = prove
 (`!Zseq Yseq Z0 Y0.
     (Zseq ---> Z0) sequentially /\ (Yseq ---> Y0) sequentially /\ Y0 < Z0
     ==> eventually
          (\n. !k nJ. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
                      Yseq n IN dyho (k - &1) (&2 * nJ) /\
                      &2 zpow k <= &20 * (Zseq n - Yseq n)
                      ==> (Z0 - Y0) / &2 < &2 zpow k /\ &2 zpow k <= &40 * (Z0
                        - Y0))
          sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`sequentially`; `Zseq:num->real`; `Yseq:num->real`; `Z0:real`;
    `Y0:real`]
    REALLIM_SUB) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN
  DISCH_THEN(MP_TAC o SPEC `(Z0 - Y0) / &2`) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN
  DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN EXISTS_TAC `N:num` THEN
  X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
  MAP_EVERY X_GEN_TAC [`k:int`; `nJ:int`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`k:int`; `nJ:int`; `Zseq (n:num):real`; `Yseq (n:num):real`]
    THETA_JR_JL_KBAND_LO) THEN
  ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC);;

(* per-FIXED-k: eventually any qualifying tile at scale k lands its base     *)
(* cells in F0. Y0 in a unique cell m0 (DYHO_COVERS_POINT), Z0 in mZ;        *)
(* eventually Yseq,Zseq are in them, so a qual tile forces 2nJ=m0, 2nJ+1=mZ  *)
(* (DYHO_SAME_POINT_INDEX) hence Z0,Y0 in the (2nJ+1),(2nJ) cells; gate      *)
(* 2^k<=20 d0 by the no-boundary hyp + margin.                               *)
let THETA_QUAL_PERK_IN_F0 = prove
 (`!Zseq Yseq Z0 Y0 k.
     (Zseq ---> Z0) sequentially /\ (Yseq ---> Y0) sequentially /\ Y0 < Z0 /\
     ~(Z0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     ~(Y0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     ~(&2 zpow k = &20 * (Z0 - Y0))
     ==> eventually
          (\n. !nJ. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
                    Yseq n IN dyho (k - &1) (&2 * nJ) /\
                    &2 zpow k <= &20 * (Zseq n - Yseq n)
                    ==> Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                        Y0 IN dyho (k - &1) (&2 * nJ) /\
                        &2 zpow k <= &20 * (Z0 - Y0)) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`k - &1:int`; `Y0:real`] DYHO_COVERS_POINT) THEN
  DISCH_THEN(X_CHOOSE_TAC `m0:int`) THEN
  MP_TAC(ISPECL [`k - &1:int`; `Z0:real`] DYHO_COVERS_POINT) THEN
  DISCH_THEN(X_CHOOSE_TAC `mZ:int`) THEN
  MP_TAC(ISPECL [`k - &1:int`; `m0:int`; `Y0:real`;
    `Yseq:num->real`] DYHO_INTERIOR_STABLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`k - &1:int`;`m0:int`;`Y0:real`] DYHO_NONDYADIC_INTERIOR)
      THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`k - &1:int`; `mZ:int`; `Z0:real`;
    `Zseq:num->real`] DYHO_INTERIOR_STABLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`k - &1:int`;`mZ:int`;`Z0:real`] DYHO_NONDYADIC_INTERIOR)
      THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN
   `eventually (\n:num. &2 zpow k <= &20 * (Zseq n - Yseq n)
                        ==> &2 zpow k <= &20 * (Z0 - Y0)) sequentially`
   MP_TAC THENL
   [SUBGOAL_THEN `&2 zpow k < &20 * (Z0 - Y0) \/ &20 * (Z0 - Y0) < &2 zpow k`
     STRIP_ASSUME_TAC THENL
     [ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC ALWAYS_EVENTUALLY THEN REWRITE_TAC[] THEN
      REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC;
      MP_TAC(ISPECL [`sequentially`; `Zseq:num->real`; `Yseq:num->real`;
        `Z0:real`; `Y0:real`]
        REALLIM_SUB) THEN ASM_REWRITE_TAC[] THEN
          REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN
      DISCH_THEN(MP_TAC o SPEC `(&2 zpow k - &20 * (Z0 - Y0)) / &20`) THEN
      ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN
      DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN EXISTS_TAC `N:num` THEN
      X_GEN_TAC `n:num` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`sequentially`;
    `\n:num. (Yseq n IN dyho (k - &1) m0) /\ (Zseq n IN dyho (k - &1) mZ) /\
              (&2 zpow k <= &20 * (Zseq n - Yseq n)
               ==> &2 zpow k <= &20 * (Z0 - Y0))`;
    `\n:num. !nJ. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
                   Yseq n IN dyho (k - &1) (&2 * nJ) /\
                   &2 zpow k <= &20 * (Zseq n - Yseq n)
                   ==> Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                       Y0 IN dyho (k - &1) (&2 * nJ) /\
                       &2 zpow k <= &20 * (Z0 - Y0)`]
    EVENTUALLY_MONO) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [ALL_TAC;
    REWRITE_TAC[EVENTUALLY_AND] THEN ASM_REWRITE_TAC[]] THEN
  X_GEN_TAC `n:num` THEN STRIP_TAC THEN
  X_GEN_TAC `nJ:int` THEN STRIP_TAC THEN
  SUBGOAL_THEN `&2 * nJ:int = m0` ASSUME_TAC THENL
   [MATCH_MP_TAC DYHO_SAME_POINT_INDEX THEN
    MAP_EVERY EXISTS_TAC [`k - &1:int`; `Yseq (n:num):real`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `&2 * nJ + &1:int = mZ` ASSUME_TAC THENL
   [MATCH_MP_TAC DYHO_SAME_POINT_INDEX THEN
    MAP_EVERY EXISTS_TAC [`k - &1:int`; `Zseq (n:num):real`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[]; ASM_MESON_TAC[]; ASM_MESON_TAC[]]);;

(* the full USC containment: eventually every gated-qualifying tile at step  *)
(* n is in                                                                   *)
(* the base set F0. P1 (KLOCAL) localizes k to the finite band Kb; P2        *)
(* (PERK_IN_F0)                                                              *)
(* per k in Kb forces F0-membership; EVENTUALLY_FORALL over Kb + P1 combine. *)
let THETA_QUAL_IN_F0_EVENTUAL = prove
 (`!Zseq Yseq Z0 Y0.
     (Zseq ---> Z0) sequentially /\ (Yseq ---> Y0) sequentially /\ Y0 < Z0 /\
     ~(Z0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     ~(Y0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     (!k. ~(&2 zpow k = &20 * (Z0 - Y0)))
     ==> eventually
          (\n. !k nJ. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
                      Yseq n IN dyho (k - &1) (&2 * nJ) /\
                      &2 zpow k <= &20 * (Zseq n - Yseq n)
                      ==> Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                          Y0 IN dyho (k - &1) (&2 * nJ) /\
                          &2 zpow k <= &20 * (Z0 - Y0)) sequentially`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `Kb = {k:int | (Z0 - Y0) / &2 < &2 zpow k /\ &2 zpow k <= &40 *
    (Z0 - Y0)}` THEN
  SUBGOAL_THEN `FINITE (Kb:int->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "Kb" THEN MATCH_MP_TAC ZPOW_BAND_FINITE THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`Zseq:num->real`; `Yseq:num->real`; `Z0:real`;
    `Y0:real`] THETA_QUAL_KLOCAL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "P1") THEN
  SUBGOAL_THEN
   `!k:int. k IN Kb ==> eventually
      (\n. !nJ. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
                Yseq n IN dyho (k - &1) (&2 * nJ) /\
                &2 zpow k <= &20 * (Zseq n - Yseq n)
                ==> Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                    Y0 IN dyho (k - &1) (&2 * nJ) /\
                    &2 zpow k <= &20 * (Z0 - Y0)) sequentially`
   (LABEL_TAC "P2fam") THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC THETA_QUAL_PERK_IN_F0 THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eventually (\n:num. !k:int. k IN Kb ==> !nJ:int.
        Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
        Yseq n IN dyho (k - &1) (&2 * nJ) /\ &2 zpow k <= &20 * (Zseq n - Yseq
          n)
        ==> Z0 IN dyho (k - &1) (&2 * nJ + &1) /\ Y0 IN dyho (k - &1) (&2 * nJ)
          /\
            &2 zpow k <= &20 * (Z0 - Y0)) sequentially`
   (LABEL_TAC "P2") THENL
   [ASM_CASES_TAC `Kb:int->bool = {}` THEN
    ASM_REWRITE_TAC[NOT_IN_EMPTY; EVENTUALLY_TRUE] THEN
    MP_TAC(ISPECL [`sequentially`;
      `\k:int n:num. !nJ:int. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
             Yseq n IN dyho (k - &1) (&2 * nJ) /\ &2 zpow k <= &20 * (Zseq n -
               Yseq n)
             ==> Z0 IN dyho (k - &1) (&2 * nJ + &1) /\ Y0 IN dyho (k - &1) (&2
               * nJ) /\
                 &2 zpow k <= &20 * (Z0 - Y0)`;
      `Kb:int->bool`] EVENTUALLY_FORALL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "P2fam" ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`sequentially`;
    `\n:num. (!k nJ:int. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
                Yseq n IN dyho (k - &1) (&2 * nJ) /\ &2 zpow k <= &20 * (Zseq n
                  - Yseq n)
                ==> (Z0 - Y0) / &2 < &2 zpow k /\ &2 zpow k <= &40 * (Z0 - Y0))
                  /\
             (!k:int. k IN Kb ==> !nJ:int. Zseq n IN dyho (k - &1) (&2 * nJ +
               &1) /\
                Yseq n IN dyho (k - &1) (&2 * nJ) /\ &2 zpow k <= &20 * (Zseq n
                  - Yseq n)
                ==> Z0 IN dyho (k - &1) (&2 * nJ + &1) /\ Y0 IN dyho (k - &1)
                  (&2 * nJ) /\
                    &2 zpow k <= &20 * (Z0 - Y0))`;
    `\n:num. !k nJ:int. Zseq n IN dyho (k - &1) (&2 * nJ + &1) /\
                Yseq n IN dyho (k - &1) (&2 * nJ) /\ &2 zpow k <= &20 * (Zseq n
                  - Yseq n)
                ==> Z0 IN dyho (k - &1) (&2 * nJ + &1) /\ Y0 IN dyho (k - &1)
                  (&2 * nJ) /\
                    &2 zpow k <= &20 * (Z0 - Y0)`]
    EVENTUALLY_MONO) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [X_GEN_TAC `n:num` THEN STRIP_TAC THEN
    MAP_EVERY X_GEN_TAC [`k:int`; `nJ:int`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(k:int) IN Kb` ASSUME_TAC THENL
     [EXPAND_TAC "Kb" THEN REWRITE_TAC[IN_ELIM_THM] THEN
      FIRST_X_ASSUM(fun th -> MP_TAC(SPECL [`k:int`; `nJ:int`] th)) THEN
        ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `k:int` th)) THEN
      ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> MP_TAC(SPEC `nJ:int` th)) THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[EVENTUALLY_AND] THEN CONJ_TAC THENL
     [USE_THEN "P1" ACCEPT_TAC; USE_THEN "P2" ACCEPT_TAC]]);;

(* UPPER (USC) half of the theta-continuity sandwich: eventually theta(Zseq  *)
(* n)(Yseq n)                                                                *)
(* <= sup over F0 of the window at Yseq n.  theta = sup(bandset_n U {0})     *)
(* (THETA_BAND_SUP); bandset_n index SUBSET F0 eventually                    *)
(* (THETA_QUAL_IN_F0_EVENTUAL)                                               *)
(* so bandset_n's window-image SUBSET F0's window-image; REAL_SUP_LE_SUBSET. *)
let PAIR_SETBUILDER_EQ = prove
 (`!(f:int#int->real) P.
     { f kJ | kJ IN {(k,nJ) | P k nJ} } = { f (k,nJ) | (k,nJ) | P k nJ }`,
  REPEAT GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN
  X_GEN_TAC `w:real` THEN
  REWRITE_TAC[EXISTS_PAIR_THM; IN_ELIM_PAIR_THM; PAIR_EQ] THEN
  EQ_TAC THEN STRIP_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    MAP_EVERY EXISTS_TAC [`k:int`; `nJ:int`] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`k:int`; `nJ:int`] THEN ASM_REWRITE_TAC[]]);;

(* LOWER (LSC) half in the TWO-BAR form (matching THETA_BAND_SUP exactly):   *)
(* eventually sup_F0 win(Yseq n) <= carleson_theta(Zseq n)(Yseq n).          *)
let THETA_SUPF_LOWER2 = prove
 (`!Zseq Yseq Z0 Y0.
     (Zseq ---> Z0) sequentially /\ (Yseq ---> Y0) sequentially /\ Y0 < Z0 /\
     ~(Z0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     ~(Y0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int))
     ==> eventually
          (\n. sup ({ Re(fourier carleson_phi
                         (&2 zpow (--k) * (Yseq n - dyho_mid (k - &1) (&2 *
                           nJ)))) pow 2
                    | (k,nJ) | Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                               Y0 IN dyho (k - &1) (&2 * nJ) /\
                               &2 zpow k <= &20 * (Z0 - Y0) } UNION {&0})
               <= carleson_theta (Zseq n) (Yseq n)) sequentially`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC
   `F0 = {(k,nJ) | Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                   Y0 IN dyho (k - &1) (&2 * nJ) /\
                   &2 zpow k <= &20 * (Z0 - Y0)}` THEN
  SUBGOAL_THEN `FINITE (F0:int#int->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "F0" THEN MATCH_MP_TAC THETA_F_FINITE THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eventually
     (\n. !kJ:int#int. kJ IN F0
          ==> Re(fourier carleson_phi
                   (&2 zpow (--(FST kJ)) *
                    (Yseq n - dyho_mid (FST kJ - &1) (&2 * SND kJ)))) pow 2
               <= carleson_theta (Zseq n) (Yseq n)) sequentially`
   MP_TAC THENL
   [ASM_CASES_TAC `F0:int#int->bool = {}` THEN
    ASM_REWRITE_TAC[NOT_IN_EMPTY; EVENTUALLY_TRUE] THEN
    ASM_SIMP_TAC[EVENTUALLY_FORALL] THEN
    X_GEN_TAC `kJ:int#int` THEN EXPAND_TAC "F0" THEN
    SPEC_TAC(`kJ:int#int`,`kJ:int#int`) THEN REWRITE_TAC[FORALL_PAIR_THM] THEN
    MAP_EVERY X_GEN_TAC [`k:int`; `nJ:int`] THEN
    REWRITE_TAC[IN_ELIM_PAIR_THM; FST; SND] THEN STRIP_TAC THEN
    MATCH_MP_TAC THETA_TERM_EVENTUAL_LE THEN
    MAP_EVERY EXISTS_TAC [`Z0:real`; `Y0:real`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`Z0:real`;`Y0:real`;`k:int`;`nJ:int`] THETA_F_STRICT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] EVENTUALLY_MONO) THEN
  X_GEN_TAC `n:num` THEN REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC REAL_SUP_LE THEN
  CONJ_TAC THENL
   [SET_TAC[];
    REWRITE_TAC[FORALL_IN_UNION; IN_SING] THEN CONJ_TAC THENL
     [REWRITE_TAC[FORALL_IN_GSPEC; FORALL_PAIR_THM] THEN
      MAP_EVERY X_GEN_TAC [`k:int`;`nJ:int`] THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `(k:int,nJ:int)`) THEN
      EXPAND_TAC "F0" THEN REWRITE_TAC[IN_ELIM_PAIR_THM; FST; SND] THEN
      ASM_REWRITE_TAC[];
      GEN_TAC THEN DISCH_THEN SUBST1_TAC THEN
      REWRITE_TAC[CARLESON_THETA_BOUNDS]]]);;

(* UPPER (USC) half in the TWO-BAR form: eventually theta(Zseq n)(Yseq n) <= *)
(* sup_F0.                                                                   *)
let THETA_SUPF_UPPER2 = prove
 (`!Zseq Yseq Z0 Y0.
     (Zseq ---> Z0) sequentially /\ (Yseq ---> Y0) sequentially /\ Y0 < Z0 /\
     ~(Z0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     ~(Y0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     (!k. ~(&2 zpow k = &20 * (Z0 - Y0)))
     ==> eventually
          (\n. carleson_theta (Zseq n) (Yseq n)
               <= sup ({ Re(fourier carleson_phi
                            (&2 zpow (--k) * (Yseq n - dyho_mid (k - &1) (&2 *
                              nJ)))) pow 2
                       | (k,nJ) | Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                                  Y0 IN dyho (k - &1) (&2 * nJ) /\
                                  &2 zpow k <= &20 * (Z0 - Y0) } UNION {&0}))
          sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`Zseq:num->real`; `Yseq:num->real`; `Z0:real`; `Y0:real`]
    THETA_QUAL_IN_F0_EVENTUAL) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] EVENTUALLY_MONO) THEN
  X_GEN_TAC `n:num` THEN REWRITE_TAC[] THEN DISCH_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [THETA_BAND_SUP] THEN
  MATCH_MP_TAC REAL_SUP_LE_SUBSET THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `&0` THEN
    REWRITE_TAC[IN_UNION; IN_SING];
    REWRITE_TAC[SUBSET; FORALL_IN_UNION; IN_SING; FORALL_IN_GSPEC;
      FORALL_PAIR_THM] THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`k:int`; `nJ:int`] THEN STRIP_TAC THEN
      REWRITE_TAC[IN_UNION; IN_ELIM_THM] THEN DISJ1_TAC THEN
      REWRITE_TAC[EXISTS_PAIR_THM; PAIR_EQ] THEN
      MAP_EVERY EXISTS_TAC [`k:int`; `nJ:int`] THEN
      FIRST_X_ASSUM(fun th -> MP_TAC(SPECL [`k:int`; `nJ:int`] th)) THEN
      ASM_REWRITE_TAC[];
      GEN_TAC THEN DISCH_THEN SUBST1_TAC THEN
      REWRITE_TAC[IN_UNION; IN_SING]];
    EXISTS_TAC `&1` THEN
    REWRITE_TAC[FORALL_IN_UNION; IN_SING; FORALL_IN_GSPEC;
      FORALL_PAIR_THM] THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`a:int`; `b:int`] THEN STRIP_TAC THEN
      REWRITE_TAC[CARLESON_THETA_TERM_BOUNDS];
      GEN_TAC THEN DISCH_THEN SUBST1_TAC THEN REAL_ARITH_TAC]]);;

(* sandwich collapse (two-bar): eventually sup_F0 win(Yseq n) = theta(Zseq   *)
(* n)(Yseq n).                                                               *)
let THETA_EVENTUAL_SUPF_EQ2 = prove
 (`!Zseq Yseq Z0 Y0.
     (Zseq ---> Z0) sequentially /\ (Yseq ---> Y0) sequentially /\ Y0 < Z0 /\
     ~(Z0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     ~(Y0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     (!k. ~(&2 zpow k = &20 * (Z0 - Y0)))
     ==> eventually
          (\n. sup ({ Re(fourier carleson_phi
                         (&2 zpow (--k) * (Yseq n - dyho_mid (k - &1) (&2 *
                           nJ)))) pow 2
                    | (k,nJ) | Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                               Y0 IN dyho (k - &1) (&2 * nJ) /\
                               &2 zpow k <= &20 * (Z0 - Y0) } UNION {&0})
               = carleson_theta (Zseq n) (Yseq n)) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`Zseq:num->real`; `Yseq:num->real`; `Z0:real`;
    `Y0:real`] THETA_SUPF_UPPER2) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`Zseq:num->real`; `Yseq:num->real`; `Z0:real`;
    `Y0:real`] THETA_SUPF_LOWER2) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[IMP_IMP; GSYM EVENTUALLY_AND] THEN
  MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] EVENTUALLY_MONO) THEN
  X_GEN_TAC `n:num` THEN REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC(REAL_ARITH `a <= b /\ b <= a ==> a = b`) THEN
    ASM_REWRITE_TAC[]);;

(* 286R-c B1 MAIN: carleson_theta is continuous along any Zseq/Yseq -> a     *)
(* non-dyadic,                                                               *)
(* non-gate-boundary base (Y0<Z0). supseq = sup_F0 win(Yseq n): = theta on   *)
(* the curve                                                                 *)
(* eventually (EQ2), --> sup_F0 win(Y0) = theta(Z0,Y0) (SUP_FINITE_REALLIM + *)
(* BAND_SUP,                                                                 *)
(* PAIR_SETBUILDER_EQ bridging the one-bar SUP_FINITE output to the two-bar  *)
(* form).                                                                    *)
let THETA_REALLIM_NONDYADIC = prove
 (`!Zseq Yseq Z0 Y0.
     (Zseq ---> Z0) sequentially /\ (Yseq ---> Y0) sequentially /\ Y0 < Z0 /\
     ~(Z0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     ~(Y0 IN IMAGE (\(m,j). real_of_int m * &2 zpow j) (:int#int)) /\
     (!k. ~(&2 zpow k = &20 * (Z0 - Y0)))
     ==> ((\n. carleson_theta (Zseq n) (Yseq n)) ---> carleson_theta Z0 Y0)
         sequentially`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REALLIM_TRANSFORM_EVENTUALLY THEN
  EXISTS_TAC
   `\n:num. sup ({ Re(fourier carleson_phi
                     (&2 zpow (--k) * (Yseq n - dyho_mid (k - &1) (&2 * nJ))))
                       pow 2
                | (k,nJ) | Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                           Y0 IN dyho (k - &1) (&2 * nJ) /\
                           &2 zpow k <= &20 * (Z0 - Y0) } UNION {&0})` THEN
  REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`Zseq:num->real`; `Yseq:num->real`; `Z0:real`; `Y0:real`]
      THETA_EVENTUAL_SUPF_EQ2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  GEN_REWRITE_TAC (RATOR_CONV o ONCE_DEPTH_CONV) [THETA_BAND_SUP] THEN
  SUBGOAL_THEN
   `!Y:real. { Re(fourier carleson_phi
                  (&2 zpow (--k) * (Y - dyho_mid (k - &1) (&2 * nJ)))) pow 2
             | (k,nJ) | Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                        Y0 IN dyho (k - &1) (&2 * nJ) /\ &2 zpow k <= &20 * (Z0
                          - Y0) }
             = { Re(fourier carleson_phi
                     (&2 zpow (--(FST kJ)) * (Y - dyho_mid (FST kJ - &1) (&2 *
                       SND kJ)))) pow 2
               | kJ IN {(k,nJ) | Z0 IN dyho (k - &1) (&2 * nJ + &1) /\
                                 Y0 IN dyho (k - &1) (&2 * nJ) /\ &2 zpow k <=
                                   &20 * (Z0 - Y0)} }`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN
    MP_TAC(BETA_RULE(REWRITE_RULE[FST;SND](ISPECL
     [`\kJ:int#int. Re(fourier carleson_phi
          (&2 zpow (--(FST kJ)) * (Y - dyho_mid (FST kJ - &1) (&2 * SND kJ))))
            pow 2`;
      `\k nJ. Z0 IN dyho (k - &1) (&2 * nJ + &1) /\ Y0 IN dyho (k - &1) (&2 *
        nJ) /\
              &2 zpow k <= &20 * (Z0 - Y0)`] PAIR_SETBUILDER_EQ))) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]); ALL_TAC] THEN
  MATCH_MP_TAC SUP_FINITE_REALLIM THEN CONJ_TAC THENL
   [MATCH_MP_TAC THETA_F_FINITE THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `kJ:int#int` THEN DISCH_TAC THEN
    MATCH_MP_TAC WINDOW_REALLIM THEN ASM_REWRITE_TAC[]]);;

(* 286R-c DCT step 1: at a fixed beta with (alpha0 z+beta),(alpha0 y+beta)   *)
(* non-dyadic and alpha0 off the (countable) gate boundary, alpha |->        *)
(* carleson_theta' z alpha beta y is continuous along aseq -> alpha0         *)
(* (instantiate THETA_REALLIM_NONDYADIC at the affine curves via CURVE_LIM). *)
let THETA'_ALPHA_CONTINUOUS = prove
 (`!aseq alpha0 z y beta.
     (aseq ---> alpha0) sequentially /\ &0 < alpha0 /\ y < z /\
     ~((alpha0 * z + beta) IN IMAGE (\(n,k). real_of_int n * &2 zpow k)
       (:int#int)) /\
     ~((alpha0 * y + beta) IN IMAGE (\(n,k). real_of_int n * &2 zpow k)
       (:int#int)) /\
     (!k. ~(&2 zpow k = &20 * (alpha0 * (z - y))))
     ==> ((\m. carleson_theta' z (aseq m) beta y) ---> carleson_theta' z alpha0
       beta y)
         sequentially`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  MP_TAC(ISPECL
   [`(\m. aseq m * z + beta):num->real`; `(\m. aseq m * y + beta):num->real`;
    `alpha0 * z + beta:real`;
      `alpha0 * y + beta:real`] THETA_REALLIM_NONDYADIC) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CURVE_LIM THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC CURVE_LIM THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(REAL_ARITH `a < b ==> a + c < b + c`) THEN
    MATCH_MP_TAC REAL_LT_LMUL THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    GEN_TAC THEN
    SUBGOAL_THEN
     `&20 * ((alpha0 * z + beta) - (alpha0 * y + beta)) = &20 * (alpha0 * (z -
       y))`
     SUBST1_TAC THENL
     [REWRITE_TAC[REAL_SUB_LDISTRIB] THEN REAL_ARITH_TAC;
      ASM_REWRITE_TAC[]]]);;

(* ========================================================================= *)
(* Real-valued a.e. dominated convergence.  Mirrors the library              *)
(* REAL_DOMINATED_CONVERGENCE (realanalysis.ml) bridge but carries an        *)
(* explicit negligible exception set t (from the vector                      *)
(* DOMINATED_CONVERGENCE_AE,                                                 *)
(* integration.ml).  Powers the DCT-continuity route to alpha-measurability  *)
(* of carleson_g: A_n(alpha)=(1/n)int_0^n theta' dbeta is continuous in      *)
(* alpha                                                                     *)
(* off the countable gate set, the bad-beta null set being the exception t.  *)
(* ========================================================================= *)
let REAL_DOMINATED_CONVERGENCE_AE = prove
 (`!f:num->real->real g h s t.
        (!k. (f k) real_integrable_on s) /\ h real_integrable_on s /\
        real_negligible t /\
        (!k x. x IN s DIFF t ==> abs(f k x) <= h x) /\
        (!x. x IN s DIFF t ==> ((\k. f k x) ---> g x) sequentially)
        ==> g real_integrable_on s /\
            ((\k. real_integral s (f k)) ---> real_integral s g) sequentially`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[REAL_INTEGRABLE_ON; TENDSTO_REAL; real_negligible] THEN
  REWRITE_TAC[o_DEF] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`\n x. lift(f (n:num) (drop x))`;
                 `lift o g o drop`; `lift o h o drop`; `IMAGE lift s`;
                 `IMAGE lift t`] DOMINATED_CONVERGENCE_AE) THEN
  SUBGOAL_THEN `IMAGE lift s DIFF IMAGE lift t = IMAGE lift (s DIFF t)`
   SUBST1_TAC THENL [SET_TAC[LIFT_EQ]; ALL_TAC] THEN
  ASM_REWRITE_TAC[FORALL_IN_IMAGE; LIFT_DROP; o_DEF; NORM_LIFT] THEN
  SUBGOAL_THEN
   `!k:num. real_integral s (f k) =
            drop(integral (IMAGE lift s) (lift o f k o drop))`
   (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th]) THEN REWRITE_TAC[th])
  THENL
   [GEN_TAC THEN MATCH_MP_TAC REAL_INTEGRAL THEN
    ASM_REWRITE_TAC[REAL_INTEGRABLE_ON; o_DEF];
    ALL_TAC] THEN
  REWRITE_TAC[o_DEF; LIFT_DROP] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  ONCE_REWRITE_TAC[GSYM DROP_EQ] THEN REWRITE_TAC[LIFT_DROP] THEN
  CONV_TAC SYM_CONV THEN REWRITE_TAC[GSYM o_DEF] THEN
  MATCH_MP_TAC REAL_INTEGRAL THEN ASM_REWRITE_TAC[REAL_INTEGRABLE_ON; o_DEF]);;

(* ========================================================================= *)
(* 286R-c: alpha-measurability of carleson_g via the DCT-continuity route.   *)
(* The bump indicators theta'_{z,alpha,beta}(y) are jointly measurable and   *)
(* locally continuous in alpha at non-gate-boundary points (THETA'_ALPHA_    *)
(* CONTINUOUS); by dominated convergence the Cesaro-average A_n(alpha) =     *)
(* (1/n) int_0^n theta' dbeta is continuous in alpha off the countable gate  *)
(* set G = {alpha | ?k. 2^k = 20 alpha(z-y)}, hence measurable; and g = lim  *)
(* A_n                                                                       *)
(* everywhere, so g is measurable (Fremlin 286R-c, cites 251M+252P+261...).  *)
(* ========================================================================= *)

(* the gate set G = {alpha | ?k. 2^k = 20 alpha(z-y)} is negligible (y<z):   *)
(* G subset IMAGE (\k. 2^k/(20(z-y))) (:int), a countable image.             *)
let CARLESON_GATE_SET_NEGLIGIBLE = prove
 (`!y z. y < z
   ==> real_negligible {alpha | ?k:int. &2 zpow k = &20 * (alpha * (z - y))}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_NEGLIGIBLE_COUNTABLE THEN
  MATCH_MP_TAC COUNTABLE_SUBSET THEN
  EXISTS_TAC `IMAGE (\k:int. &2 zpow k / (&20 * (z - y))) (:int)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC COUNTABLE_IMAGE THEN REWRITE_TAC[INT_COUNTABLE];
    REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_IMAGE; IN_UNIV] THEN
    X_GEN_TAC `alpha:real` THEN DISCH_THEN(X_CHOOSE_TAC `k:int`) THEN
    EXISTS_TAC `k:int` THEN
    SUBGOAL_THEN `&0 < &20 * (z - y)` MP_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    POP_ASSUM MP_TAC THEN CONV_TAC REAL_FIELD]);;

(* real-valued sequential characterization of continuity on a set.           *)
let REAL_CONTINUOUS_ON_SEQUENTIALLY = prove
 (`!f s. f real_continuous_on s <=>
         !x a. a IN s /\ (!n. x n IN s) /\ (x ---> a) sequentially
               ==> ((\n. f(x n)) ---> f a) sequentially`,
  REPEAT GEN_TAC THEN
    REWRITE_TAC[REAL_CONTINUOUS_ON; CONTINUOUS_ON_SEQUENTIALLY] THEN
  EQ_TAC THEN DISCH_TAC THENL
   [MAP_EVERY X_GEN_TAC [`x:num->real`; `a:real`] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`lift o (x:num->real)`; `lift a`]) THEN
    ASM_REWRITE_TAC[o_DEF; IN_IMAGE_LIFT_DROP; LIFT_DROP; TENDSTO_REAL] THEN
    ANTS_TAC THENL
     [UNDISCH_TAC `((x:num->real) ---> a) sequentially` THEN
      REWRITE_TAC[TENDSTO_REAL; o_DEF];
      REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC [`x:num->real^1`; `a:real^1`] THEN
    REWRITE_TAC[IN_IMAGE_LIFT_DROP] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`drop o (x:num->real^1)`; `drop a`]) THEN
    ASM_REWRITE_TAC[o_DEF; LIFT_DROP] THEN
    ANTS_TAC THENL
     [REWRITE_TAC[TENDSTO_REAL; o_DEF; LIFT_DROP] THEN
      UNDISCH_TAC `((x:num->real^1) --> a) sequentially` THEN
      REWRITE_TAC[ETA_AX];
      REWRITE_TAC[TENDSTO_REAL; o_DEF; LIFT_DROP]]]);;

(* real measurability is invariant under on-set equality.                    *)
let REAL_MEASURABLE_ON_EQ = prove
 (`!f g s. (!x. x IN s ==> f x = g x) /\ f real_measurable_on s
           ==> g real_measurable_on s`,
  REPEAT GEN_TAC THEN REWRITE_TAC[real_measurable_on] THEN STRIP_TAC THEN
  MATCH_MP_TAC MEASURABLE_ON_EQ THEN
  EXISTS_TAC `lift o f o drop` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[FORALL_IN_IMAGE; o_DEF; LIFT_DROP] THEN ASM_SIMP_TAC[]);;

(* STEP 2a: the bare-integral limit (no inv(&n) factor). DCT with dominator  *)
(* 1.                                                                        *)
let CARLESON_AN_INTEGRAL_LIMIT = prove
 (`!n z y alpha0 aseq.
     &0 < alpha0 /\ y < z /\ (aseq ---> alpha0) sequentially /\
     (!k:int. ~(&2 zpow k = &20 * (alpha0 * (z - y))))
     ==> ((\m. real_integral (real_interval[&0,&n]) (\beta. carleson_theta' z
       (aseq m) beta y))
          ---> real_integral (real_interval[&0,&n]) (\beta. carleson_theta' z
            alpha0 beta y))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\(m:num) beta. carleson_theta' z (aseq m) beta y`;
    `\beta. carleson_theta' z alpha0 beta y`;
    `\beta:real. &1`;
    `real_interval[&0,&n]`;
    `{beta | (alpha0 * z + beta) IN (IMAGE (\(n,k). real_of_int n * &2 zpow k)
      (:int#int)) \/
             (alpha0 * y + beta) IN (IMAGE (\(n,k). real_of_int n * &2 zpow k)
               (:int#int))}`]
   REAL_DOMINATED_CONVERGENCE_AE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [GEN_TAC THEN REWRITE_TAC[THETA'_BETA_INTEGRABLE];
      REWRITE_TAC[REAL_INTEGRABLE_CONST];
      MP_TAC(SPECL [`alpha0:real`;`y:real`;`z:real`] THETA_BAD_BETA_NEGLIGIBLE)
        THEN
      REWRITE_TAC[real_negligible];
      MAP_EVERY X_GEN_TAC [`m:num`;`beta:real`] THEN DISCH_TAC THEN
      MP_TAC(SPECL [`z:real`;`aseq(m:num):real`;`beta:real`;`y:real`]
        CARLESON_THETA'_BOUNDS) THEN
      REAL_ARITH_TAC;
      X_GEN_TAC `beta:real` THEN
        REWRITE_TAC[IN_DIFF; IN_ELIM_THM; DE_MORGAN_THM] THEN
      STRIP_TAC THEN
      MATCH_MP_TAC THETA'_ALPHA_CONTINUOUS THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th))]);;

(* STEP 2b: the inv(&n)-scaled form A_n(aseq m) ---> A_n(alpha0).            *)
let CARLESON_AN_CONTINUOUS = prove
 (`!n z y alpha0 aseq.
     &0 < alpha0 /\ y < z /\ (aseq ---> alpha0) sequentially /\
     (!k:int. ~(&2 zpow k = &20 * (alpha0 * (z - y))))
     ==> ((\m. inv(&n) *
               real_integral (real_interval[&0,&n]) (\beta. carleson_theta' z
                 (aseq m) beta y))
          ---> inv(&n) *
               real_integral (real_interval[&0,&n]) (\beta. carleson_theta' z
                 alpha0 beta y))
         sequentially`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REALLIM_LMUL THEN
  MATCH_MP_TAC CARLESON_AN_INTEGRAL_LIMIT THEN ASM_REWRITE_TAC[]);;

(* STEP 3+4: alpha |-> A_n(alpha) is measurable on [1,2]. For y<z continuous *)
(* off                                                                       *)
(* the negligible gate G; for z<=y constantly 0 on [1,2] (alpha>=1>0).       *)
let CARLESON_AN_MEASURABLE = prove
 (`!n z y.
     (\alpha. inv(&n) *
              real_integral (real_interval[&0,&n]) (\beta. carleson_theta' z
                alpha beta y))
     real_measurable_on real_interval[&1,&2]`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `(z:real) <= y` THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_EQ THEN
     EXISTS_TAC `(\alpha. &0):real->real` THEN
    CONJ_TAC THENL
     [X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
       STRIP_TAC THEN
      SUBGOAL_THEN
        `(\beta. carleson_theta' z alpha beta y) =
         (\beta. &0)` SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
        MATCH_MP_TAC CARLESON_THETA'_SUPPORT THEN ASM_REWRITE_TAC[] THEN
          ASM_REAL_ARITH_TAC;
        REWRITE_TAC[REAL_INTEGRAL_0; REAL_MUL_RZERO]];
      REWRITE_TAC[REAL_MEASURABLE_ON_0]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:real) < z` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_CONTINUOUS_AE_IMP_MEASURABLE_ON_LEBESGUE_MEASURABLE_SUBSET
    THEN
  EXISTS_TAC `{alpha | ?k:int. &2 zpow k = &20 * (alpha * (z - y))}` THEN
  REWRITE_TAC[REAL_LEBESGUE_MEASURABLE_INTERVAL] THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_CONTINUOUS_ON_SEQUENTIALLY] THEN
    MAP_EVERY X_GEN_TAC [`aseq:num->real`; `alpha0:real`] THEN
    REWRITE_TAC[IN_DIFF; IN_REAL_INTERVAL; IN_ELIM_THM] THEN STRIP_TAC THEN
    MATCH_MP_TAC CARLESON_AN_CONTINUOUS THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      REWRITE_TAC[NOT_EXISTS_THM] THEN ASM_MESON_TAC[]];
    MATCH_MP_TAC CARLESON_GATE_SET_NEGLIGIBLE THEN ASM_REWRITE_TAC[]]);;

(* STEP 5: alpha |-> carleson_g alpha y z is measurable on [1,2] (286R-c). g *)
(* = lim_n A_n everywhere (CARLESON_G_AVG_LIMIT + integer subsequence for    *)
(* y<z; g=0 for z<=y); REAL_MEASURABLE_ON_LIMIT.                             *)
let CARLESON_G_ALPHA_MEASURABLE = prove
 (`!y z. (\alpha. carleson_g alpha y z) real_measurable_on
   real_interval[&1,&2]`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `(z:real) <= y` THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_EQ THEN
     EXISTS_TAC `(\alpha. &0):real->real` THEN
    REWRITE_TAC[REAL_MEASURABLE_ON_0] THEN
    X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
      STRIP_TAC THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARLESON_G_TRIVIAL THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:real) < z` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_LIMIT THEN
  MAP_EVERY EXISTS_TAC
   [`\n alpha. inv(&n) *
               real_integral (real_interval[&0,&n]) (\beta. carleson_theta' z
                 alpha beta y)`;
    `{}:real->bool`] THEN
  REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY; DIFF_EMPTY] THEN CONJ_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[CARLESON_AN_MEASURABLE];
    X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
      STRIP_TAC THEN
    MP_TAC(ISPECL
     [`\b. inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta'
       z alpha beta y)`;
      `carleson_g alpha y z`] REALLIM_POSINFINITY_SEQUENTIALLY) THEN
    REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC CARLESON_G_AVG_LIMIT THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC]);;

(* ========================================================================= *)
(* 286R-c tail + (d): carleson_thetatilde is well-defined in [0,1] and       *)
(* translation-invariant (Fremlin 286R).  The log-average integrand          *)
(* (1/alpha) g(alpha,y,z) is measurable (CARLESON_G_ALPHA_MEASURABLE x       *)
(* continuous 1/alpha) and bounded by 1 (1<=alpha, 0<=g<=1), hence           *)
(* integrable                                                                *)
(* on [1,2]; the value is in [0,1].                                          *)
(* ========================================================================= *)

(* the log-average integrand (1/alpha) g(alpha,y,z) is integrable on [1,2].  *)
let THETATILDE_INTEGRAND_INTEGRABLE = prove
 (`!y z. (\alpha. inv alpha * carleson_g alpha y z) real_integrable_on
   real_interval[&1,&2]`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\alpha. &1):real->real` THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MUL THEN
    REWRITE_TAC[CARLESON_G_ALPHA_MEASURABLE] THEN
    SUBGOAL_THEN `inv = (\x:real. inv x)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM];
      MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET THEN
      REWRITE_TAC[REAL_CLOSED_REAL_INTERVAL] THEN
      MATCH_MP_TAC REAL_CONTINUOUS_ON_INV THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON_ID; IN_REAL_INTERVAL] THEN
      REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC];
    REWRITE_TAC[REAL_INTEGRABLE_CONST];
    X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
      STRIP_TAC THEN
    MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`] CARLESON_G_BOUNDS) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; STRIP_TAC] THEN
    REWRITE_TAC[REAL_ABS_MUL] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&1 * &1` THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL2 THEN REWRITE_TAC[REAL_ABS_POS] THEN
      CONJ_TAC THENL
       [SUBGOAL_THEN `abs(inv alpha) = inv alpha` SUBST1_TAC THENL
         [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC REAL_LE_INV THEN
           ASM_REAL_ARITH_TAC;
          MATCH_MP_TAC REAL_INV_LE_1 THEN ASM_REAL_ARITH_TAC];
        ASM_REAL_ARITH_TAC];
      REAL_ARITH_TAC]]);;

(* thetatilde in [0,1].                                                      *)
let THETATILDE_TRANSLATE = prove
 (`!y z gam. y < z
   ==> carleson_thetatilde (z + gam) (y + gam) = carleson_thetatilde z y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_thetatilde] THEN
  MATCH_MP_TAC REAL_INTEGRAL_EQ THEN
  X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
  AP_TERM_TAC THEN MATCH_MP_TAC CARLESON_G_TRANSLATE THEN
    ASM_REWRITE_TAC[] THEN
  ASM_REAL_ARITH_TAC);;

(* ========================================================================= *)
(* 286R-c/g generalization: A_n, carleson_g measurable and (1/a)g integrable *)
(* on any positive interval [u,v] (0<u), not just [1,2].  Needed to feed the *)
(* octave shift-invariance (CARLESON_G_OCTAVE_ABSTRACT) on the subintervals  *)
(* [gam,2gam] arising in the 286R-g scale-invariance of thetatilde.          *)
(* Proofs are the [1,2] versions verbatim with 0<u supplying alpha>0.        *)
(* ========================================================================= *)

let CARLESON_AN_MEASURABLE_GEN = prove
 (`!n z y u v. &0 < u
     ==> (\alpha. inv(&n) *
                  real_integral (real_interval[&0,&n]) (\beta. carleson_theta'
                    z alpha beta y))
         real_measurable_on real_interval[u,v]`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `(z:real) <= y` THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_EQ THEN
     EXISTS_TAC `(\alpha. &0):real->real` THEN
    CONJ_TAC THENL
     [X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
       STRIP_TAC THEN
      SUBGOAL_THEN
        `(\beta. carleson_theta' z alpha beta y) =
         (\beta. &0)` SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
        MATCH_MP_TAC CARLESON_THETA'_SUPPORT THEN ASM_REWRITE_TAC[] THEN
          ASM_REAL_ARITH_TAC;
        REWRITE_TAC[REAL_INTEGRAL_0; REAL_MUL_RZERO]];
      REWRITE_TAC[REAL_MEASURABLE_ON_0]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:real) < z` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_CONTINUOUS_AE_IMP_MEASURABLE_ON_LEBESGUE_MEASURABLE_SUBSET
    THEN
  EXISTS_TAC `{alpha | ?k:int. &2 zpow k = &20 * (alpha * (z - y))}` THEN
  REWRITE_TAC[REAL_LEBESGUE_MEASURABLE_INTERVAL] THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_CONTINUOUS_ON_SEQUENTIALLY] THEN
    MAP_EVERY X_GEN_TAC [`aseq:num->real`; `alpha0:real`] THEN
    REWRITE_TAC[IN_DIFF; IN_REAL_INTERVAL; IN_ELIM_THM] THEN STRIP_TAC THEN
    MATCH_MP_TAC CARLESON_AN_CONTINUOUS THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      REWRITE_TAC[NOT_EXISTS_THM] THEN ASM_MESON_TAC[]];
    MATCH_MP_TAC CARLESON_GATE_SET_NEGLIGIBLE THEN ASM_REWRITE_TAC[]]);;

let CARLESON_G_ALPHA_MEASURABLE_GEN = prove
 (`!y z u v. &0 < u
     ==> (\alpha. carleson_g alpha y z) real_measurable_on real_interval[u,v]`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `(z:real) <= y` THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_EQ THEN
     EXISTS_TAC `(\alpha. &0):real->real` THEN
    REWRITE_TAC[REAL_MEASURABLE_ON_0] THEN
    X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
      STRIP_TAC THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARLESON_G_TRIVIAL THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:real) < z` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_LIMIT THEN
  MAP_EVERY EXISTS_TAC
   [`\n alpha. inv(&n) *
               real_integral (real_interval[&0,&n]) (\beta. carleson_theta' z
                 alpha beta y)`;
    `{}:real->bool`] THEN
  REWRITE_TAC[REAL_NEGLIGIBLE_EMPTY; DIFF_EMPTY] THEN CONJ_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC CARLESON_AN_MEASURABLE_GEN THEN
     ASM_REWRITE_TAC[];
    X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
      STRIP_TAC THEN
    MP_TAC(ISPECL
     [`\b. inv b * real_integral (real_interval[&0,b]) (\beta. carleson_theta'
       z alpha beta y)`;
      `carleson_g alpha y z`] REALLIM_POSINFINITY_SEQUENTIALLY) THEN
    REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC CARLESON_G_AVG_LIMIT THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC]);;

(* the a-iterate (\a. inv a * int_[0,n] theta') is real_integrable on [1,2]. *)
(* Analog of A_ITERATE_INTEGRABLE for the theta' kernel (feeds the w-outer   *)
(* side of                                                                   *)
(* MNF_FOURIER_BOX -- the inner (a,b)-box integral = Cx(n*Mn w)). Measurable *)
(* arm:                                                                      *)
(* int_[0,n] theta' measurable in a (CARLESON_AN_MEASURABLE * &n; n=0        *)
(* REAL_INTEGRAL_                                                            *)
(* NULL) times cont inv a; bound |inv a * int| <= n (inv a<=1 on [1,2],      *)
(* 0<=int<=n).                                                               *)
let THETA'_A_ITERATE_INTEGRABLE = prove
 (`!z0:real w:real n:num.
     (\a. inv a * real_integral (real_interval[&0,&n]) (\b. carleson_theta' z0
       a b w))
     real_integrable_on real_interval[&1,&2]`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\a. real_integral (real_interval[&0,&n]) (\b. carleson_theta' z0 a b w))
     real_measurable_on real_interval[&1,&2]`
   ASSUME_TAC THENL
   [ASM_CASES_TAC `n = 0` THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `(\a:real. real_integral (real_interval[&0,&0]) (\b. carleson_theta' z0
        a b w)) = (\a:real. &0)`
       SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
        MATCH_MP_TAC REAL_INTEGRAL_NULL THEN REWRITE_TAC[REAL_LE_REFL];
        REWRITE_TAC[REAL_MEASURABLE_ON_0]];
      MP_TAC(ISPECL [`n:num`; `z0:real`; `w:real`] CARLESON_AN_MEASURABLE) THEN
      DISCH_THEN(MP_TAC o SPEC `&n:real` o MATCH_MP REAL_MEASURABLE_ON_LMUL)
        THEN
      MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REWRITE_TAC[REAL_MUL_ASSOC] THEN
      ASM_SIMP_TAC[REAL_MUL_RINV; REAL_OF_NUM_EQ; REAL_MUL_LID]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\a:real. &n)` THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`\a:real. inv a`;
                   `\a:real. real_integral (real_interval[&0,&n]) (\b.
                     carleson_theta' z0 a b w)`;
                   `real_interval[&1,&2]`] REAL_MEASURABLE_ON_MUL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET THEN
    REWRITE_TAC[REAL_CLOSED_REAL_INTERVAL] THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_INV THEN
    REWRITE_TAC[REAL_CONTINUOUS_ON_ID; IN_REAL_INTERVAL] THEN
    REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[REAL_INTEGRABLE_CONST];
    X_GEN_TAC `a:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `&0 <= real_integral (real_interval[&0,&n]) (\b. carleson_theta' z0 a b w)
       /\
      real_integral (real_interval[&0,&n]) (\b. carleson_theta' z0 a b w) <=
        &n`
     STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INTEGRAL_POS THEN
         REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN
        REPEAT STRIP_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
        MATCH_MP_TAC REAL_LE_TRANS THEN
        EXISTS_TAC `real_integral (real_interval[&0,&n]) (\b:real. &1)` THEN
          CONJ_TAC THENL
         [MATCH_MP_TAC REAL_INTEGRAL_LE THEN
           REWRITE_TAC[THETA'_BETA_INTEGRABLE; REAL_INTEGRABLE_CONST] THEN
          REPEAT STRIP_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
          SIMP_TAC[REAL_INTEGRAL_CONST; REAL_ARITH `&0 <= &n`] THEN
            REAL_ARITH_TAC]];
      ALL_TAC] THEN
    REWRITE_TAC[REAL_ABS_MUL] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&1 * &n` THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL2 THEN REWRITE_TAC[REAL_ABS_POS] THEN
       REPEAT CONJ_TAC THENL
       [REWRITE_TAC[REAL_ABS_INV] THEN MATCH_MP_TAC REAL_LE_TRANS THEN
         EXISTS_TAC `abs(inv(&1))` THEN
        REWRITE_TAC[REAL_ABS_INV] THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_INV2 THEN
           ASM_REAL_ARITH_TAC; CONV_TAC REAL_RAT_REDUCE_CONV];
        ASM_REAL_ARITH_TAC];
      REWRITE_TAC[REAL_MUL_LID; REAL_LE_REFL]]]);;

(* (1/a) g integrable on [u,v], 0<u.                                         *)
let THETATILDE_INTEGRAND_INTEGRABLE_GEN = prove
 (`!y z u v. &0 < u
     ==> (\alpha. inv alpha * carleson_g alpha y z) real_integrable_on
       real_interval[u,v]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\alpha. inv u):real->real` THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MUL THEN
    ASM_SIMP_TAC[CARLESON_G_ALPHA_MEASURABLE_GEN] THEN
    SUBGOAL_THEN `inv = (\x:real. inv x)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM];
      MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET THEN
      REWRITE_TAC[REAL_CLOSED_REAL_INTERVAL] THEN
      MATCH_MP_TAC REAL_CONTINUOUS_ON_INV THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON_ID; IN_REAL_INTERVAL] THEN
      REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC];
    REWRITE_TAC[REAL_INTEGRABLE_CONST];
    X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
      STRIP_TAC THEN
    MP_TAC(SPECL [`alpha:real`;`y:real`;`z:real`] CARLESON_G_BOUNDS) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; STRIP_TAC] THEN
    REWRITE_TAC[REAL_ABS_MUL] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `abs(inv alpha) * &1` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[REAL_ABS_POS] THEN
       ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_MUL_RID] THEN
      SUBGOAL_THEN
        `abs(inv alpha) = inv alpha /\ abs(inv u) = inv u` (fun th ->
        REWRITE_TAC[th]) THENL
       [CONJ_TAC THEN REWRITE_TAC[REAL_ABS_REFL] THEN
         MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_LE_INV2 THEN ASM_REAL_ARITH_TAC]]]);;

(* ========================================================================= *)
(* 286R-g scale-invariance of thetatilde and the value thetatilde_z(y) =     *)
(* thetatilde_1(0) * indicator(y<z) (Fremlin 286R). PIECE 1 = affine         *)
(* stretch,                                                                  *)
(* PIECE 3 = scale value (via octave shift-invariance), then the full value. *)
(* ========================================================================= *)

(* PIECE 1 (affine alpha*gam substitution): int_[1,2] inv a *                *)
(* g(a,gam*y,gam*z) da =                                                     *)
(* int_[gam,2gam] inv a * g(a,y,z) da (gam>0). HAS_REAL_INTEGRAL_STRETCH +   *)
(* G-scale-arg.                                                              *)
let THETATILDE_STRETCH = prove
 (`!y z gam. &0 < gam
     ==> real_integral (real_interval[&1,&2]) (\alpha. inv alpha * carleson_g
       alpha (gam * y) (gam * z)) =
         real_integral (real_interval[gam,&2 * gam]) (\alpha. inv alpha *
           carleson_g alpha y z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(gam = &0)` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (real_interval[&1,&2]) (\x. inv(gam * x) * carleson_g (gam *
     x) y z) =
    inv(gam) * real_integral (real_interval[gam,&2 * gam]) (\a. inv a *
      carleson_g a y z)`
   (LABEL_TAC "str") THENL
   [MP_TAC(ISPECL [`\a. inv a * carleson_g a y z`;
                   `real_integral (real_interval[gam,&2 * gam]) (\a. inv a *
                     carleson_g a y z)`;
                   `gam:real`; `&2 * gam`;
                     `gam:real`] HAS_REAL_INTEGRAL_STRETCH) THEN
    REWRITE_TAC[GSYM HAS_REAL_INTEGRAL_INTEGRAL] THEN
    SUBGOAL_THEN
      `(\a. inv a * carleson_g a y z)
       real_integrable_on real_interval[gam,&2 * gam]`
      (fun th -> REWRITE_TAC[th]) THENL
     [MATCH_MP_TAC THETATILDE_INTEGRAND_INTEGRABLE_GEN THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `IMAGE (\x. inv gam * x) (real_interval[gam,&2 * gam]) =
       real_interval[&1,&2]`
     SUBST1_TAC THENL
     [SUBGOAL_THEN `~(real_interval[gam,&2 * gam] = {})` ASSUME_TAC THENL
       [REWRITE_TAC[REAL_INTERVAL_EQ_EMPTY; REAL_NOT_LT] THEN
         ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `&0 <= inv gam` ASSUME_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
        `inv gam * gam =
         &1 /\ inv gam * (&2 * gam) = &2` STRIP_ASSUME_TAC THENL
       [UNDISCH_TAC `~(gam = &0)` THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
      ASM_REWRITE_TAC[IMAGE_STRETCH_REAL_INTERVAL]; ALL_TAC] THEN
    SUBGOAL_THEN `abs gam = gam` SUBST1_TAC THENL
      [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o SYM o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN
      BETA_TAC THEN
    REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (real_interval[&1,&2]) (\x. inv(gam * x) * carleson_g (gam *
     x) y z) =
    inv(gam) * real_integral (real_interval[&1,&2]) (\alpha. inv alpha *
      carleson_g alpha (gam * y) (gam * z))`
   (LABEL_TAC "lmul") THENL
   [MP_TAC(ISPECL [`\alpha. inv alpha * carleson_g alpha (gam * y) (gam *
     z):real`; `inv(gam:real)`; `real_interval[&1,&2]`]
                  REAL_INTEGRAL_LMUL) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC THETATILDE_INTEGRAND_INTEGRABLE_GEN THEN
       REWRITE_TAC[REAL_LT_01];
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC REAL_INTEGRAL_EQ THEN X_GEN_TAC `x:real` THEN DISCH_TAC THEN
      REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `carleson_g (gam * x) y z = carleson_g (x * gam) y z` SUBST1_TAC THENL
       [AP_THM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
         REAL_ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[CARLESON_G_SCALE_ARG; REAL_INV_MUL] THEN
        REAL_ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `inv gam * real_integral (real_interval[&1,&2]) (\alpha. inv alpha *
     carleson_g alpha (gam * y) (gam * z)) =
    inv gam * real_integral (real_interval[gam,&2 * gam]) (\a. inv a *
      carleson_g a y z)`
   MP_TAC THENL
   [USE_THEN "str" (fun s -> USE_THEN "lmul" (fun l ->
      MP_TAC s THEN MP_TAC l THEN REAL_ARITH_TAC));
    REWRITE_TAC[REAL_EQ_MUL_LCANCEL; REAL_INV_EQ_0] THEN
    ASM_CASES_TAC `gam = &0` THENL [ASM_REAL_ARITH_TAC; ASM_REWRITE_TAC[]]]);;

(* PIECE 3 (286R-g value): thetatilde(gam*z)(gam*y) = thetatilde z y for     *)
(* gam>0.                                                                    *)
let THETATILDE_SCALE = prove
 (`!y z gam. &0 < gam
     ==> carleson_thetatilde (gam * z) (gam * y) = carleson_thetatilde z y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_thetatilde] THEN
  ASM_SIMP_TAC[THETATILDE_STRETCH] THEN
  MATCH_MP_TAC CARLESON_G_OCTAVE_ABSTRACT THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC CARLESON_G_SCALE2 THEN
     ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN MATCH_MP_TAC THETATILDE_INTEGRAND_INTEGRABLE_GEN THEN
    ASM_REWRITE_TAC[]]);;

(* 286R value: thetatilde_z(y) = thetatilde_1(0) for y<z, = 0 for y>=z. y<z: *)
(* translate (gam=-y) to thetatilde_{z-y}(0), then scale (gam=z-y) to        *)
(* thetatilde_1(0); y>=z: g=0 on [1,2] (alpha>=1>0) so the log-average       *)
(* vanishes.                                                                 *)
let CARLESON_THETATILDE_VALUE = prove
 (`!y z. carleson_thetatilde z y =
         if y < z then carleson_thetatilde (&1) (&0) else &0`,
  REPEAT GEN_TAC THEN COND_CASES_TAC THENL
   [SUBGOAL_THEN
     `carleson_thetatilde z y =
      carleson_thetatilde (z - y) (&0)` SUBST1_TAC THENL
     [MP_TAC(SPECL [`y:real`; `z:real`; `--y:real`] THETATILDE_TRANSLATE) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `z + --y = z - y /\ y + --y = &0` (fun th -> REWRITE_TAC[th]) THENL
       [CONJ_TAC THEN REAL_ARITH_TAC; DISCH_THEN(ACCEPT_TAC o SYM)];
      ALL_TAC] THEN
    MP_TAC(SPECL [`&0:real`; `&1:real`; `z - y:real`] THETATILDE_SCALE) THEN
    ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_MUL_RZERO; REAL_MUL_RID] THEN
      DISCH_THEN(ACCEPT_TAC o SYM);
    REWRITE_TAC[carleson_thetatilde] THEN
    SUBGOAL_THEN
     `real_integral (real_interval[&1,&2]) (\alpha. inv alpha * carleson_g
       alpha y z) =
      real_integral (real_interval[&1,&2]) (\alpha. &0)`
     SUBST1_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_EQ THEN
      X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
        STRIP_TAC THEN
      SUBGOAL_THEN `carleson_g alpha y z = &0` SUBST1_TAC THENL
       [MATCH_MP_TAC CARLESON_G_TRIVIAL THEN
        CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC];
        REWRITE_TAC[REAL_MUL_RZERO]];
      REWRITE_TAC[REAL_INTEGRAL_0]]]);;

(* ========================================================================= *)
(* 286R-(h): thetatilde_1(0) > 0. For 1<=alpha<7/6 and beta in the good band *)
(* [2m+1/6, 2m+5/6] (m in Z), the k=1 tile makes carleson_theta(alpha+beta)  *)
(* (beta) = phihat((beta-(2m+1/2))/2)^2 = 1 (window on |arg|<=1/6).  So      *)
(* g(alpha,0,1) >= 1/3 (good band = 2/3 of each period-2 cell), and          *)
(* thetatilde_1(0) >= (1/3) int_1^{7/6} 1/alpha > 0.                         *)
(* ========================================================================= *)

(* the (h) window: carleson_theta(alpha+beta)(beta) = 1 on the good band.    *)
let THETA_LOWER_WINDOW = prove
 (`!alpha m beta.
     &1 <= alpha /\ alpha < &7 / &6 /\
     &2 * real_of_int m + &1 / &6 <= beta /\ beta <= &2 * real_of_int m + &5 /
       &6
     ==> carleson_theta (alpha + beta) beta = &1`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(REAL_ARITH `&1 <= t /\ t <= &1 ==> t = &1`) THEN
  REWRITE_TAC[CARLESON_THETA_BOUNDS] THEN
  MP_TAC(SPECL [`alpha + beta:real`; `beta:real`; `&1:int`;
    `m:int`] THETA_TERM_LE) THEN
  REWRITE_TAC[INT_ARITH `(&1:int) - &1 = &0`] THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN
     REWRITE_TAC[dyho; IN_ELIM_THM; REAL_ZPOW_0; REAL_MUL_RID] THEN
    REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES] THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[dyho_mid; REAL_ZPOW_0; REAL_MUL_RID; REAL_ZPOW_NEG;
    REAL_ZPOW_1] THEN
  SUBGOAL_THEN
   `fourier carleson_phi (inv(&2) * (beta - (real_of_int (&2 * m) + &1 / &2)))
     = Cx(&1)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC CARLESON_PHI_FHAT_ONE THEN
    REWRITE_TAC[GSYM REAL_OF_INT_CLAUSES] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[RE_CX] THEN REAL_ARITH_TAC]);;

(* the same window at a nat cell index (theta' = carleson_theta on the       *)
(* diagonal).                                                                *)
let THETA'_LOWER_WINDOW_NUM = prove
 (`!alpha (N:num) beta. &1 <= alpha /\ alpha < &7 / &6 /\
    &2 * &N + &1 / &6 <= beta /\ beta <= &2 * &N + &5 / &6
    ==> carleson_theta' (&1) alpha beta (&0) = &1`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[carleson_theta'; REAL_MUL_RID; REAL_MUL_RZERO; REAL_ADD_LID] THEN
  MP_TAC(SPECL [`alpha:real`; `&N:int`; `beta:real`] THETA_LOWER_WINDOW) THEN
  REWRITE_TAC[int_of_num_th] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]);;

(* single cell: int_[2N,2N+2] theta'(1)(alpha)(.)(0) >= 2/3 (good band       *)
(* [2N+1/6,2N+5/6]).                                                         *)
let THETA'_CELL_LB = prove
 (`!alpha N. &1 <= alpha /\ alpha < &7 / &6
   ==> &2 / &3 <= real_integral (real_interval[&2 * &N, &2 * &N + &2])
                    (\beta. carleson_theta' (&1) alpha beta (&0))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral (real_interval[&2 * &N + &1 / &6, &2 * &N + &5 /
    &6])
                (\beta. carleson_theta' (&1) alpha beta (&0))` THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
     `real_integral (real_interval[&2 * &N + &1 / &6, &2 * &N + &5 / &6])
        (\beta. carleson_theta' (&1) alpha beta (&0)) =
      real_integral (real_interval[&2 * &N + &1 / &6, &2 * &N + &5 / &6])
        (\beta. &1)`
     SUBST1_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_EQ THEN X_GEN_TAC `beta:real` THEN
      REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
      MP_TAC(SPECL [`alpha:real`; `N:num`;
        `beta:real`] THETA'_LOWER_WINDOW_NUM) THEN
      ASM_REWRITE_TAC[];
      SIMP_TAC[REAL_INTEGRAL_CONST;
        REAL_ARITH `&2 * &N + &1 / &6 <= &2 * &N + &5 / &6`] THEN
      REAL_ARITH_TAC];
    MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN
    REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN REAL_ARITH_TAC;
      GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS]]]);;

(* band-counting: int_[0,2N] theta'(1)(alpha)(.)(0) >= N*(2/3) (each cell >= *)
(* 2/3).                                                                     *)
let GOOD_BAND_INTEGRAL_LB = prove
 (`!alpha. &1 <= alpha /\ alpha < &7 / &6
   ==> !N. &N * (&2 / &3) <=
           real_integral (real_interval[&0,&2 * &N])
             (\beta. carleson_theta' (&1) alpha beta (&0))`,
  GEN_TAC THEN STRIP_TAC THEN INDUCT_TAC THENL
   [REWRITE_TAC[REAL_MUL_LZERO; REAL_MUL_RZERO; REAL_INTEGRAL_REFL;
     REAL_LE_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (real_interval[&0,&2 * &(SUC N)]) (\beta. carleson_theta'
     (&1) alpha beta (&0)) =
    real_integral (real_interval[&0,&2 * &N]) (\beta. carleson_theta' (&1)
      alpha beta (&0)) +
    real_integral (real_interval[&2 * &N,&2 * &N + &2]) (\beta. carleson_theta'
      (&1) alpha beta (&0))`
   SUBST1_TAC THENL
   [SUBGOAL_THEN `&2 * &(SUC N) = &2 * &N + &2` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM REAL_OF_NUM_SUC] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC REAL_INTEGRAL_COMBINE THEN
    REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_SUC;
              REAL_ARITH `(&N + &1) * (&2 / &3) = &N * (&2 / &3) + &2 / &3`]
                THEN
  MATCH_MP_TAC REAL_LE_ADD2 THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC THETA'_CELL_LB THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286R-(h): the Cesaro mean thetatilde_1(0) is STRICTLY POSITIVE.           *)
(* g(alpha,0,1) >= 1/3 for alpha in [1,7/6) by the good-band count, whence   *)
(* thetatilde_1(0) = int_[1,2] (1/a) g >= (2/7)(1/8) > 0.  This positivity   *)
(* is what makes the 286T constant C10 = 3 C9 / (pi thetatilde_1(0)) finite. *)
(* ========================================================================= *)

(* Every int L is <= some num &n (so the beta-period 2 zpow L can be taken   *)
(* as a nonnegative power 2^n).                                              *)
let LE_INT_NUM = prove
 (`!L:int. ?n:num. L <= &n`,
  GEN_TAC THEN EXISTS_TAC `num_of_int(abs L)` THEN
  SUBGOAL_THEN `&(num_of_int(abs L)):int = abs L` SUBST1_TAC THENL
   [MATCH_MP_TAC INT_OF_NUM_OF_INT THEN INT_ARITH_TAC; INT_ARITH_TAC]);;

(* a single period P is also a period after any num multiple &j * P.         *)
let PERIODIC_MULTIPLE = prove
 (`!(f:real->real) P. (!b. f(b + P) = f b) ==> !j b. f(b + &j * P) = f b`,
  GEN_TAC THEN GEN_TAC THEN DISCH_TAC THEN INDUCT_TAC THEN
  ASM_REWRITE_TAC[REAL_MUL_LZERO; REAL_ADD_RID] THEN GEN_TAC THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_SUC] THEN
  SUBGOAL_THEN `b + (&j + &1) * P = (b + &j * P) + P` SUBST1_TAC THENL
   [REAL_ARITH_TAC; ASM_REWRITE_TAC[]]);;

(* num-valued restatement of CARLESON_THETA'_PERIOD: theta'(z)(a)(.)(y) has  *)
(* a period of the shape 2^n (n:num), obtained from the int period 2 zpow L  *)
(* by 2 zpow L = 2^{n-L} * 2 zpow L with L <= &n = 2^n via                   *)
(* PERIODIC_MULTIPLE.                                                        *)
let CARLESON_THETA'_PERIOD_NUM = prove
 (`!z a y. &0 < a /\ y < z
   ==> ?n:num. !b. carleson_theta' z a (b + &2 pow n) y = carleson_theta' z a b
     y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`z:real`; `a:real`; `y:real`] CARLESON_THETA'_PERIOD) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `L:int`) THEN
  MP_TAC(SPEC `L:int` LE_INT_NUM) THEN DISCH_THEN(X_CHOOSE_TAC `n:num`) THEN
  EXISTS_TAC `n:num` THEN GEN_TAC THEN
  SUBGOAL_THEN
    `&2 pow n = &(2 EXP (num_of_int(&n - L))) * &2 zpow L` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_POW; GSYM REAL_ZPOW_POW] THEN
    SUBGOAL_THEN `&(num_of_int(&n - L)):int = &n - L` SUBST1_TAC THENL
     [MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
    SIMP_TAC[GSYM REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
    AP_TERM_TAC THEN ASM_INT_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(BETA_RULE(ISPECL [`\b. carleson_theta' z a b y`;
    `&2 zpow L`] PERIODIC_MULTIPLE)) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`(2 EXP num_of_int (&n - L)):num`; `b:real`]) THEN
  REWRITE_TAC[]);;

(* 286R-(h) core: g(alpha,0,1) >= 1/3 for alpha in [1,7/6).  Cesaro lower    *)
(* bound at the even period p = 2 * 2^n (2^n = beta-period): int_0^p theta'  *)
(* >= (1/3) p is exactly GOOD_BAND_INTEGRAL_LB at N = 2^n (2*&N = p).        *)
let CARLESON_G_0_1_LOWER = prove
 (`!alpha. &1 <= alpha /\ alpha < &7 / &6 ==> &1 / &3 <= carleson_g alpha (&0)
   (&1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_g] THEN
  MP_TAC(SPECL [`&1:real`; `alpha:real`;
    `&0:real`] CARLESON_THETA'_PERIOD_NUM) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `n:num`) THEN
  MP_TAC(SPECL [`\beta. carleson_theta' (&1) alpha beta (&0)`;
                `&2 * &2 pow n`; `&1 / &3`] PERIODIC_CESARO_LBOUND) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_MUL THEN REWRITE_TAC[REAL_LT_POW2] THEN
       REAL_ARITH_TAC;
      GEN_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
      REWRITE_TAC[THETA'_BETA_INTEGRABLE];
      GEN_TAC THEN
      SUBGOAL_THEN
        `b + &2 * &2 pow n = (b + &2 pow n) + &2 pow n` SUBST1_TAC THENL
       [REAL_ARITH_TAC; ALL_TAC] THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`alpha:real`] GOOD_BAND_INTEGRAL_LB) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `2 EXP n`) THEN
      REWRITE_TAC[REAL_OF_NUM_POW] THEN REAL_ARITH_TAC];
    DISCH_THEN ACCEPT_TAC]);;

(* 286R-(h): thetatilde_1(0) > 0.  int_[1,2] (1/a) g >= int_[1,9/8] (1/a) g  *)
(* >= int_[1,9/8] (2/7) = (2/7)(1/8) > 0, using (1/a) >= 8/9 and g >= 1/3 on *)
(* [1,9/8] (subset of [1,7/6) so CARLESON_G_0_1_LOWER applies).              *)
let CARLESON_THETATILDE_1_0_POS = prove
 (`&0 < carleson_thetatilde (&1) (&0)`,
  REWRITE_TAC[carleson_thetatilde] THEN
  MATCH_MP_TAC REAL_LTE_TRANS THEN
  EXISTS_TAC `real_integral (real_interval[&1,&9 / &8]) (\alpha. inv alpha *
    carleson_g alpha (&0) (&1))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LTE_TRANS THEN
    EXISTS_TAC `real_integral (real_interval[&1,&9 / &8]) (\alpha. &2 / &7)`
      THEN
    CONJ_TAC THENL
     [SIMP_TAC[REAL_INTEGRAL_CONST; REAL_ARITH `&1 <= &9 / &8`] THEN
       REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRAL_LE THEN
      REWRITE_TAC[REAL_INTEGRABLE_CONST] THEN CONJ_TAC THENL
       [MATCH_MP_TAC THETATILDE_INTEGRAND_INTEGRABLE_GEN THEN
         REWRITE_TAC[REAL_LT_01];
        X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
          STRIP_TAC THEN
        MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(&8 / &9) * (&1 / &3)` THEN
        CONJ_TAC THENL
         [REAL_ARITH_TAC;
          MATCH_MP_TAC REAL_LE_MUL2 THEN REPEAT CONJ_TAC THENL
           [REAL_ARITH_TAC;
            REWRITE_TAC[REAL_LE_INV_EQ] THEN
            MATCH_MP_TAC(REAL_ARITH `&8 / &9 <= inv alpha ==> &8 / &9 <= inv
              alpha`) THEN
            MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `inv(&9 / &8)` THEN
            CONJ_TAC THENL
             [REAL_ARITH_TAC;
              MATCH_MP_TAC REAL_LE_INV2 THEN ASM_REAL_ARITH_TAC];
            REAL_ARITH_TAC;
            MATCH_MP_TAC CARLESON_G_0_1_LOWER THEN ASM_REAL_ARITH_TAC]]]];
    MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN REPEAT CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_REAL_INTERVAL] THEN REAL_ARITH_TAC;
      MATCH_MP_TAC THETATILDE_INTEGRAND_INTEGRABLE_GEN THEN
        REWRITE_TAC[REAL_LT_01];
      REWRITE_TAC[THETATILDE_INTEGRAND_INTEGRABLE];
      X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
        STRIP_TAC THEN
      MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REWRITE_TAC[REAL_LE_INV_EQ] THEN ASM_REAL_ARITH_TAC;
        MP_TAC(SPECL [`alpha:real`;`&0:real`;`&1:real`] CARLESON_G_BOUNDS) THEN
        ANTS_TAC THENL [ASM_REAL_ARITH_TAC; SIMP_TAC[]]]]]);;

(* The tile operator A (Fremlin 286P): Ah(x) = sup_z |2pi (hhat x theta_z)   *)
(* check(x)|. The inverse transform g check(x) = fourier g (--x)             *)
(* (FOURIER_REFLECT).                                                        *)
let carleson_A = new_definition
 `carleson_A (h:real->complex) (x:real) =
    sup { norm(Cx(&2 * pi) *
              fourier (\y. fourier h y * Cx(carleson_theta z y)) (--x))
        | z IN (:real) }`;;

(* Two auxiliary results for the CARLESON_286P tile operator.                *)
(* (286O(a) theta_z-measurability = CARLESON_THETA_CX_MEASURABLE discharges  *)
(* the measurability hypothesis). hhat * theta_z is L^1                      *)
(* (Schwartz transform x bounded                                             *)
(* measurable), and each tile-window is continuous.                          *)
let CARLESON_FHAT_THETA_ABSINT = prove
 (`!(h:real->complex) z.
     schwartz h
     ==> (\y. fourier h (drop y) * Cx(carleson_theta z (drop y)))
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `z:real` CARLESON_THETA_CX_MEASURABLE) THEN DISCH_TAC THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC `\y:real^1. lift(norm(fourier (h:real->complex) (drop y)))` THEN
    REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN CONJ_TAC THENL
     [MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
       ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[ABSOLUTELY_INTEGRABLE_MEASURABLE] THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
    MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
      ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real^1` THEN
      REWRITE_TAC[IN_UNIV; LIFT_DROP; COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
    MP_TAC(ISPECL [`z:real`; `drop(x:real^1)`] CARLESON_THETA_BOUNDS) THEN
      REAL_ARITH_TAC]);;

(* ---------------------------------------------------------------------     *)
(* 286Q(c) support: the modulated-dilated Schwartz function M_b D_a h is     *)
(* Schwartz (a<>0), and its theta-window (M_b D_a h)hat . Cx(theta v) is     *)
(* absolutely integrable -- the input to the 286Q kernel bound.              *)
(* ---------------------------------------------------------------------     *)

let CARLESON_SCHWARTZ_MODDIL = prove
 (`!(h:real->complex) a b. schwartz h /\ ~(a = &0)
   ==> schwartz (carleson_modulate b (carleson_dilate a h))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_modulate; carleson_dilate] THEN
  MATCH_MP_TAC SCHWARTZ_MODULATE THEN
  SUBGOAL_THEN
    `(\x. (h:real->complex)(a * x)) = (\x. h(&0 + a * x))` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ADD_LID]; ALL_TAC] THEN
  MATCH_MP_TAC SCHWARTZ_AFFINE THEN ASM_REWRITE_TAC[]);;

let CARLESON_MODDIL_WINDOW_ABSINT = prove
 (`!(h:real->complex) a b v. schwartz h /\ ~(a = &0)
   ==> (\w. fourier (carleson_modulate b (carleson_dilate a h)) (drop w) *
            Cx(carleson_theta v (drop w))) absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CARLESON_FHAT_THETA_ABSINT THEN
  MATCH_MP_TAC CARLESON_SCHWARTZ_MODDIL THEN ASM_REWRITE_TAC[]);;

let CARLESON_A_WINDOW_CONTINUOUS = prove
 (`!(h:real->complex) zt x.
     schwartz h
     ==> (\x. norm(Cx(&2 * pi) *
                  fourier (\y. fourier h y * Cx(carleson_theta zt y)) (--x)))
         real_continuous atreal x`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_CONTINUOUS_CONTINUOUS_ATREAL; o_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_LIFT_NORM_COMPOSE THEN
  MATCH_MP_TAC CONTINUOUS_COMPLEX_LMUL THEN
  SUBGOAL_THEN
   `(\w:real^1. fourier (\y. fourier (h:real->complex) y * Cx(carleson_theta zt
     y)) (--drop w)) =
    (\w:real^1. fourier (\y. fourier (h:real->complex) y * Cx(carleson_theta zt
      y)) (drop w)) o (\w. --w)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; DROP_NEG]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_AT_COMPOSE THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_NEG THEN
     REWRITE_TAC[CONTINUOUS_AT_ID]; ALL_TAC] THEN
  CONV_TAC(DEPTH_CONV BETA_CONV) THEN
  MP_TAC(ISPEC `\y. fourier (h:real->complex) y * Cx(carleson_theta zt y)`
    FOURIER_CONTINUOUS_ON) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[] THEN MATCH_MP_TAC CARLESON_FHAT_THETA_ABSINT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SIMP_TAC[CONTINUOUS_ON_EQ_CONTINUOUS_AT; OPEN_UNIV; IN_UNIV]);;

(* 286P(a) uniform (in z,x) modulus bound: |2pi (hhat x theta_z)check(x)| is *)
(* <= sqrt(2pi) int|hhat|, independent of z (because 0<=theta_z<=1).         *)
(* Supplies the                                                              *)
(* pointwise-bounded hypothesis for the sup-over-z measurability of Ah.      *)
let CARLESON_A_WINDOW_UNIFORM_BOUND = prove
 (`!(h:real->complex) z x.
     schwartz h
     ==> norm(Cx(&2 * pi) *
              fourier (\y. fourier h y * Cx(carleson_theta z y)) (--x))
         <= sqrt(&2 * pi) *
            drop(integral (:real^1) (\y. lift(norm(fourier (h:real->complex)
              (drop y)))))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`] CARLESON_FHAT_THETA_ABSINT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `abs(&2 * pi) = &2 * pi` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`\y. fourier (h:real->complex) y * Cx(carleson_theta z y)`;
    `--x:real`]
    FOURIER_BOUND) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MP_TAC(ISPECL [`( * ):complex->complex->complex`;
                     `\u:real^1. cexp(--(ii * Cx(--x) * Cx(drop u)))`;
                     `\u:real^1. fourier (h:real->complex) (drop u) *
                       Cx(carleson_theta z (drop u))`;
                     `(:real^1)`]
        ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT) THEN
      REWRITE_TAC[BILINEAR_COMPLEX_MUL] THEN BETA_TAC THEN DISCH_THEN
        MATCH_MP_TAC THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
        SUBGOAL_THEN
         `(\u:real^1. cexp(--(ii * Cx(--x) * Cx(drop u)))) =
          cexp o (\u. --((ii * Cx(--x)) * Cx(drop u)))`
         SUBST1_TAC THENL [REWRITE_TAC[o_DEF; COMPLEX_MUL_ASSOC]; ALL_TAC] THEN
        MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
          REWRITE_TAC[CONTINUOUS_ON_CEXP] THEN
        MATCH_MP_TAC CONTINUOUS_ON_NEG THEN
          MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN
        REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
          MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN
        REWRITE_TAC[CONTINUOUS_ON_ID];
        REWRITE_TAC[bounded; FORALL_IN_IMAGE] THEN EXISTS_TAC `&1` THEN
        X_GEN_TAC `u:real^1` THEN REWRITE_TAC[IN_UNIV] THEN
        SUBGOAL_THEN
          `--(ii * Cx(--x) * Cx(drop u)) =
           ii * Cx(--(--x * drop u))` SUBST1_TAC THENL
         [REWRITE_TAC[CX_NEG; CX_MUL] THEN
           SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[NORM_CEXP_II; REAL_LE_REFL];
        ASM_REWRITE_TAC[]];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `&0 < sqrt(&2 * pi)` ASSUME_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `(&2 * pi) * (&1 / sqrt(&2 * pi)) = sqrt(&2 * pi)` ASSUME_TAC THENL
   [MP_TAC(SPEC `&2 * pi` SQRT_POW_2) THEN
    ANTS_TAC THENL [MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
    POP_ASSUM MP_TAC THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sqrt(&2 * pi) *
              drop(integral (:real^1)
                (\y. lift(norm(fourier (h:real->complex) (drop y) *
                  Cx(carleson_theta z (drop y))))))` THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [SYM th])
     THEN
    REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN MATCH_MP_TAC REAL_LE_LMUL THEN
    CONJ_TAC THENL
     [MP_TAC PI_POS THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MP_TAC PI_POS THEN REAL_ARITH_TAC;
        ASM_REWRITE_TAC[REAL_MUL_ASSOC]]];
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC INTEGRAL_DROP_LE THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
        ASM_REWRITE_TAC[];
      X_GEN_TAC `y:real^1` THEN REWRITE_TAC[IN_UNIV; LIFT_DROP] THEN
      REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
      GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
      MP_TAC(ISPECL [`z:real`; `drop(y:real^1)`] CARLESON_THETA_BOUNDS) THEN
        REAL_ARITH_TAC]]);;

(* =====================================================================     *)
(* 286Q(c): the kernel bound.  For Schwartz h and a > 0,                     *)
(*   2pi |(hhat . theta'_{z,a,b})check(-y)| <= A(M_b D_a h)(y/a),            *)
(* where A = carleson_A is the (uncountable) sup-of-windows maximal          *)
(* operator.  This is Fremlin 286Q(c): the dilation-modulation of the        *)
(* theta'-kernel check-integral reduces (change of variables) to a single    *)
(* window of the maximal operator for the reparametrised M_b D_a h.          *)
(* Proof spine: rewrite the check-integrand (CARLESON_Q286C_INTEGRAND) as    *)
(* Cx a * (M_b D_a h)hat-window at (a w + b); pull Cx a (FOURIER_LMUL);      *)
(* apply the affine change of variables (CARLESON_FOURIER_DILSHIFT) to get   *)
(* Cx(1/a) cexp(..) fourier(window)(-(y/a)); the Jacobian x phase has unit   *)
(* modulus (CARLESON_JACOBIAN_UNIT), so 2pi|LHS| = 2pi|window(-(y/a))|,      *)
(* a single element of the A-sup-set (REAL_LE_SUP, bounded by 286P(a)        *)
(* CARLESON_A_WINDOW_UNIFORM_BOUND).                                         *)
(* =====================================================================     *)

(* The G-window and its b-shift are absolutely integrable, hence the cexp-   *)
(* twisted forms (the CARLESON_FOURIER_DILSHIFT hypotheses) are integrable.  *)
let CARLESON_MODDIL_WINDOW_SHIFT_ABSINT = prove
 (`!(h:real->complex) a b v c. schwartz h /\ ~(a = &0)
   ==> (\z:real^1. fourier (carleson_modulate b (carleson_dilate a h)) (drop z
     + c) *
                   Cx(carleson_theta v (drop z + c))) absolutely_integrable_on
                     (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. fourier (carleson_modulate b (carleson_dilate a
     (h:real->complex))) (drop z + c) *
                Cx(carleson_theta v (drop z + c)))
    = (\z:real^1. (\w:real^1. fourier (carleson_modulate b (carleson_dilate a
      h)) (drop w) *
                              Cx(carleson_theta v (drop w))) (lift c + z))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[DROP_ADD; LIFT_DROP] THEN
    REWRITE_TAC[REAL_ADD_SYM]; ALL_TAC] THEN
  REWRITE_TAC[ABSOLUTELY_INTEGRABLE_TRANSLATION; TRANSLATION_UNIV] THEN
  MATCH_MP_TAC CARLESON_MODDIL_WINDOW_ABSINT THEN ASM_REWRITE_TAC[]);;

let CARLESON_KERNEL_INTEG = prove
 (`!(h:real->complex) a b v d c. schwartz h /\ ~(a = &0)
  ==> (\x:real^1. cexp(--(ii * Cx d * Cx(drop x))) *
                  (fourier(carleson_modulate b (carleson_dilate a h))(drop x +
                    c) *
                   Cx(carleson_theta v (drop x + c)))) integrable_on
                     (:real^1)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MP_TAC(ISPECL [`\u. fourier(carleson_modulate b (carleson_dilate (a:real)
    (h:real->complex)))(u+c)*Cx(carleson_theta v (u+c))`;
    `d:real`] FOURIER_MODULATION_ABSINT) THEN
  ANTS_TAC THENL
   [BETA_TAC THEN MATCH_MP_TAC CARLESON_MODDIL_WINDOW_SHIFT_ABSINT THEN
     ASM_REWRITE_TAC[];
    DISCH_THEN(MP_TAC o BETA_RULE) THEN REWRITE_TAC[]]);;

(* M_{b/a} h transform-integrand integrable (all w): the hypothesis of       *)
(* CARLESON_Q286C_INTEGRAND.                                                 *)
let CARLESON_MOD_TRANSFORM_INTEG = prove
 (`!(h:real->complex) a b w. schwartz h
  ==> (\x:real^1. cexp(--(ii * Cx (w/a) * Cx(drop x))) *
                  (\u. cexp(ii * Cx(b/a) * Cx u) * h u)(drop x)) integrable_on
                    (:real^1)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MP_TAC(ISPECL [`\u. cexp(ii * Cx(b/a) * Cx u) * (h:real->complex) u`;
    `w/a:real`] FOURIER_MODULATION_ABSINT) THEN
  ANTS_TAC THENL
   [BETA_TAC THEN
    MP_TAC(ISPEC `\x. cexp(ii * Cx(b/a) * Cx x) * (h:real->complex) x`
      SCHWARTZ_ABSINT) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_MODULATE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[];
    REWRITE_TAC[]]);;

(* Affine image of the whole line is the whole line (nonzero scale).         *)
let CARLESON_AFFINITY_IMAGE_UNIV = prove
 (`!m c:real^1. ~(m = &0) ==> IMAGE (\x:real^1. m % x + c) (:real^1) =
   (:real^1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN
  X_GEN_TAC `y:real^1` THEN EXISTS_TAC `inv m % (y - c):real^1` THEN
  REWRITE_TAC[VECTOR_MUL_ASSOC] THEN ASM_SIMP_TAC[REAL_MUL_RINV] THEN
  VECTOR_ARITH_TAC);;

(* The dilated+shifted G-window \z. G(a z + b) is absolutely integrable.     *)
let CARLESON_MODDIL_WINDOW_DIL_ABSINT = prove
 (`!(h:real->complex) a b v. schwartz h /\ &0 < a
  ==> (\z:real^1. fourier(carleson_modulate b (carleson_dilate a h))(a * drop z
    + b) *
                  Cx(carleson_theta v (a * drop z + b)))
                    absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\z:real^1. fourier(carleson_modulate b (carleson_dilate a
     (h:real->complex)))(drop z) *
                Cx(carleson_theta v (drop z))`;
    `(:real^1)`; `a:real`; `lift b`] ABSOLUTELY_INTEGRABLE_AFFINITY) THEN
  ASM_SIMP_TAC[REAL_LT_IMP_NZ] THEN ANTS_TAC THENL
   [MATCH_MP_TAC CARLESON_MODDIL_WINDOW_ABSINT THEN
     ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN
  ASM_SIMP_TAC[CARLESON_AFFINITY_IMAGE_UNIV; REAL_INV_EQ_0;
    REAL_LT_IMP_NZ] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
  REWRITE_TAC[DROP_ADD; DROP_CMUL; LIFT_DROP]);;

(* Its cexp-twist is integrable: the FOURIER_LMUL side-condition.            *)
let CARLESON_DILWIN_LMUL_INTEG = prove
 (`!(h:real->complex) a b v y. schwartz h /\ &0 < a
  ==> (\x:real^1. cexp(--(ii * Cx(--y) * Cx(drop x))) *
        (\w. fourier(carleson_modulate b (carleson_dilate a h))(a * w + b) *
          Cx(carleson_theta v (a * w + b)))(drop x))
      integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN BETA_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MP_TAC(ISPECL [`\w. fourier(carleson_modulate b (carleson_dilate (a:real)
    (h:real->complex)))(a * w + b) * Cx(carleson_theta v (a * w + b))`;
    `--y:real`] FOURIER_MODULATION_ABSINT) THEN
  ANTS_TAC THENL
   [BETA_TAC THEN MATCH_MP_TAC CARLESON_MODDIL_WINDOW_DIL_ABSINT THEN
     ASM_REWRITE_TAC[];
    DISCH_THEN(MP_TAC o BETA_RULE) THEN REWRITE_TAC[]]);;

(* The unit modulus of the Jacobian (Cx a . Cx(1/a)) times the shift phase.  *)
let CARLESON_JACOBIAN_UNIT = prove
 (`!a b c. &0 < a ==> norm(Cx a) * norm(Cx(&1/a)) * norm(cexp(ii * Cx b * Cx
   c)) = &1`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `cexp(ii * Cx b * Cx c) = cexp(ii * Cx(b * c))` SUBST1_TAC THENL
   [AP_TERM_TAC THEN REWRITE_TAC[CX_MUL] THEN
     SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[NORM_CEXP_II; REAL_MUL_RID] THEN
  SUBGOAL_THEN
    `abs a = a /\ abs(&1/a) = &1/a` (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[REAL_ABS_REFL; REAL_LT_IMP_LE; REAL_LE_DIV; REAL_POS];
     ALL_TAC] THEN
  UNDISCH_TAC `&0 < a` THEN CONV_TAC REAL_FIELD);;

let CARLESON_NEG_DIV = prove
 (`!y a:real. (--y)/a = --(y/a)`,
  REWRITE_TAC[real_div] THEN REAL_ARITH_TAC);;

(* STEP 1: rewrite the theta'-check-integrand and pull the Cx a scalar out.  *)
let CARLESON_KERNEL_STEP1 = prove
 (`!(h:real->complex) z a b y. schwartz h /\ &0 < a
  ==> fourier(\w. fourier h w * Cx(carleson_theta' z a b w))(--y)
      = Cx a * fourier(\w. fourier(carleson_modulate b (carleson_dilate a
        h))(a*w+b) *
                           Cx(carleson_theta (a*z+b)(a*w+b)))(--y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\w. fourier (h:real->complex) w * Cx(carleson_theta' z a b w))
    = (\w. Cx a * (fourier(carleson_modulate b (carleson_dilate a h))(a*w+b) *
                   Cx(carleson_theta (a*z+b)(a*w+b))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real` THEN
    MATCH_MP_TAC CARLESON_Q286C_INTEGRAND THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      GEN_TAC THEN MATCH_MP_TAC CARLESON_MOD_TRANSFORM_INTEG THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\w. fourier(carleson_modulate b (carleson_dilate (a:real)
    (h:real->complex)))(a*w+b) *
                      Cx(carleson_theta (a*z+b)(a*w+b))`; `Cx a`;
                        `--y:real`] FOURIER_LMUL) THEN
  ANTS_TAC THENL
   [MP_TAC(ISPECL [`h:real->complex`;`a:real`;`b:real`;`(a:real)*z+b`;`y:real`]
     CARLESON_DILWIN_LMUL_INTEG) THEN
    ASM_REWRITE_TAC[] THEN BETA_TAC THEN REWRITE_TAC[];
    DISCH_THEN(fun th -> REWRITE_TAC[BETA_RULE th])]);;

(* STEP 2: the affine change of variables on the inner Fourier transform.    *)
let CARLESON_KERNEL_STEP2 = prove
 (`!(h:real->complex) z a b y. schwartz h /\ &0 < a
  ==> fourier(\w. fourier(carleson_modulate b (carleson_dilate a h))(a*w+b) *
                  Cx(carleson_theta (a*z+b)(a*w+b)))(--y)
      = Cx(&1/a) * cexp(ii * Cx b * Cx((--y)/a)) *
        fourier(\w'. fourier(carleson_modulate b (carleson_dilate a h)) w' *
                     Cx(carleson_theta (a*z+b) w'))((--y)/a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(a = &0)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN
  MP_TAC(SPECL
   [`\w'. fourier(carleson_modulate b (carleson_dilate (a:real)
     (h:real->complex))) w' *
          Cx(carleson_theta (a*z+b) w')`;
    `a:real`; `b:real`; `--y:real`] CARLESON_FOURIER_DILSHIFT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [MP_TAC(SPECL
     [`h:real->complex`;`a:real`;`b:real`;`(a:real)*z+b`;`((--y)/a):real`;
      `b:real`] CARLESON_KERNEL_INTEG) THEN
    ASM_REWRITE_TAC[] THEN BETA_TAC THEN REWRITE_TAC[];
    MP_TAC(SPECL
      [`h:real->complex`;`a:real`;`b:real`;`(a:real)*z+b`;`((--y)/a):real`;
       `&0`] CARLESON_KERNEL_INTEG) THEN
    ASM_REWRITE_TAC[REAL_ADD_RID] THEN BETA_TAC THEN
      REWRITE_TAC[REAL_ADD_RID]]);;

(* The combined norm identity: the Jacobian x phase drops out (unit          *)
(* modulus).                                                                 *)
let CARLESON_KERNEL_NORM_ID = prove
 (`!(h:real->complex) z a b y. schwartz h /\ &0 < a
  ==> &2 * pi * norm(fourier(\w. fourier h w * Cx(carleson_theta' z a b
    w))(--y))
      = &2 * pi * norm(fourier(\w'. fourier(carleson_modulate b
        (carleson_dilate a h)) w' *
                                    Cx(carleson_theta (a*z+b) w'))((--y)/a))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_KERNEL_STEP1; CARLESON_KERNEL_STEP2] THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[COMPLEX_NORM_MUL] THEN
  MP_TAC(SPECL [`a:real`; `b:real`;
    `((--y)/a):real`] CARLESON_JACOBIAN_UNIT) THEN
  ASM_REWRITE_TAC[] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `A * B * C * D = (A * B * C) * D:real`] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[REAL_MUL_LID]);;

(* Single-window sup-membership: 2pi|window(-(y/a))| <= A(M_b D_a h)(y/a).   *)
let CARLESON_KERNEL_SUP = prove
 (`!(h:real->complex) z a b y. schwartz h /\ &0 < a
  ==> &2 * pi * norm(fourier(\w'. fourier(carleson_modulate b (carleson_dilate
    a h)) w' *
                                  Cx(carleson_theta (a*z+b) w'))((--y)/a))
      <= carleson_A (carleson_modulate b (carleson_dilate a h)) (y/a)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_A] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  EXISTS_TAC
   `sqrt(&2 * pi) *
    drop(integral(:real^1)
      (\y'. lift(norm(fourier
         (carleson_modulate b (carleson_dilate a (h:real->complex)))
         (drop y')))))` THEN
  EXISTS_TAC `norm(Cx(&2 * pi) *
        fourier (\y'. fourier (carleson_modulate b (carleson_dilate a
          (h:real->complex))) y' * Cx(carleson_theta (a*z+b) y'))
          (--(y/a)))` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `(a:real)*z+b` THEN
     REWRITE_TAC[IN_UNIV];
    REWRITE_TAC[CARLESON_NEG_DIV; COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    SUBGOAL_THEN `abs(&2 * pi) = &2 * pi` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_REFL] THEN MP_TAC PI_POS THEN
       REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_MUL_ASSOC; REAL_LE_REFL];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `zz:real` THEN
    MP_TAC(SPECL [`carleson_modulate b (carleson_dilate a (h:real->complex))`;
      `zz:real`; `y/a:real`] CARLESON_A_WINDOW_UNIFORM_BOUND) THEN
    ASM_SIMP_TAC[CARLESON_SCHWARTZ_MODDIL; REAL_LT_IMP_NZ]]);;

(* 286Q(c): the kernel bound, assembled from NORM_ID + SUP.                  *)
let CARLESON_286Q_KERNEL = prove
 (`!(h:real->complex) z a b y. schwartz h /\ &0 < a
  ==> &2 * pi * norm(fourier(\w. fourier h w * Cx(carleson_theta' z a b
    w))(--y))
      <= carleson_A (carleson_modulate b (carleson_dilate a h)) (y/a)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_KERNEL_NORM_ID] THEN
  ASM_SIMP_TAC[CARLESON_KERNEL_SUP]);;

(* 286P(a) measurability: Ah = sup_z |v_z| is lower semi-continuous     *)
(* (each v_z continuous in x = CARLESON_A_WINDOW_CONTINUOUS) and pointwise   *)
(* bounded                                                                   *)
(* (CARLESON_A_WINDOW_UNIFORM_BOUND), so real-measurable by                  *)
(* REAL_MEASURABLE_ON_SUP_                                                   *)
(* CONTINUOUS.  This is Fremlin 286P's "Ah is Borel measurable, by 256Ma".   *)
let CARLESON_A_MEASURABLE = prove
 (`!(h:real->complex). schwartz h ==> (carleson_A h) real_measurable_on
   (:real)`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `carleson_A (h:real->complex) =
    (\x. sup { (\z. norm(Cx(&2 * pi) *
                         fourier (\y. fourier h y * Cx(carleson_theta z y))
                           (--x))) z
             | z IN (:real) })`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; carleson_A]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_SUP_CONTINUOUS THEN
  REWRITE_TAC[UNIV_NOT_EMPTY; IN_UNIV] THEN CONJ_TAC THENL
   [X_GEN_TAC `z:real` THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`h:real->complex`; `z:real`;
      `x:real`] CARLESON_A_WINDOW_CONTINUOUS) THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN
    EXISTS_TAC `sqrt(&2 * pi) *
                drop(integral (:real^1) (\y. lift(norm(fourier
                  (h:real->complex) (drop y)))))` THEN
    X_GEN_TAC `z:real` THEN REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`h:real->complex`; `z:real`;
      `x:real`] CARLESON_A_WINDOW_UNIFORM_BOUND) THEN
    ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286S infrastructure (Fremlin mt286.tex 2700-2823): the iterated dilation- *)
(* average operator Atilde h.  286S(b) rests on 286P applied to the          *)
(* modulated-dilated M_beta D_alpha h, with the scaling relations            *)
(*   ||M_b D_a h||_2 = (1/sqrt a) ||h||_2,   mu(a^-1 F) = (1/a) mu F,        *)
(* which make the per-(alpha,beta) slice integral 4C9||h||sqrt(muF)          *)
(* INDEPENDENT                                                               *)
(* of (alpha,beta) -- the a cancels exactly.  These are the S0-S3 bricks.    *)
(* ========================================================================= *)

(* S0: carleson_A h >= 0 (sup of norms over the nonempty bounded z-family).  *)
let CARLESON_A_POS = prove
 (`!(h:real->complex) x. schwartz h ==> &0 <= carleson_A h x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_A] THEN
  MATCH_MP_TAC REAL_LE_SUP THEN
  EXISTS_TAC `sqrt(&2 * pi) *
              drop(integral (:real^1) (\y. lift(norm(fourier (h:real->complex)
                (drop y)))))` THEN
  EXISTS_TAC `norm(Cx(&2 * pi) *
              fourier (\y. fourier h y * Cx(carleson_theta (&0) y)) (--x))`
                THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `&0:real` THEN
     REWRITE_TAC[IN_UNIV];
    REWRITE_TAC[NORM_POS_LE];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `z:real` THEN
    MP_TAC(ISPECL [`h:real->complex`; `z:real`;
      `x:real`] CARLESON_A_WINDOW_UNIFORM_BOUND) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* S0': carleson_A h is bounded by the uniform-bound constant (sup <=        *)
(* const).                                                                   *)
let CARLESON_A_UNIFORM_BOUND = prove
 (`!(h:real->complex) x. schwartz h
   ==> carleson_A h x <= sqrt(&2 * pi) * drop(integral (:real^1) (\y.
     lift(norm(fourier (h:real->complex) (drop y)))))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_A] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `norm(Cx(&2 * pi) * fourier (\y. fourier h y * Cx(carleson_theta
      (&0) y)) (--x))` THEN
    REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `&0:real` THEN
      REWRITE_TAC[IN_UNIV];
    REWRITE_TAC[FORALL_IN_GSPEC] THEN X_GEN_TAC `z:real` THEN
    MP_TAC(ISPECL [`h:real->complex`; `z:real`;
      `x:real`] CARLESON_A_WINDOW_UNIFORM_BOUND) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* S0'': carleson_A h integrable on any finite-measure set (bounded          *)
(* measurable).                                                              *)
let CARLESON_A_INTEGRABLE = prove
 (`!(h:real->complex) FF. schwartz h /\ real_measurable FF
     ==> (carleson_A h) real_integrable_on FF`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\x:real. sqrt(&2 * pi) * drop(integral (:real^1) (\y.
    lift(norm(fourier (h:real->complex) (drop y)))))):real->real` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_SIMP_TAC[SUBSET_UNIV; CARLESON_A_MEASURABLE];
    REWRITE_TAC[REAL_INTEGRABLE_ON] THEN REWRITE_TAC[o_DEF; LIFT_CMUL] THEN
    REWRITE_TAC[INTEGRABLE_ON_CONST] THEN DISJ2_TAC THEN
    ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`h:real->complex`; `x:real`] CARLESON_A_POS) THEN
    MP_TAC(ISPECL [`h:real->complex`; `x:real`] CARLESON_A_UNIFORM_BOUND) THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC]);;

(* S1: lnorm depends only on the pointwise norm of the integrand.            *)
let LNORM_NORM_EQ = prove
 (`!s p (f:real^1->complex) g. (!x. norm(f x) = norm(g x)) ==> lnorm s p f =
   lnorm s p g`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lnorm] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN ASM_REWRITE_TAC[]);;

(* S1: L^2 dilation scaling of the argument: ||h(a.)||_2 = (1/sqrt a)        *)
(* ||h||_2.                                                                  *)
let DILATE_ARG_LNORM = prove
 (`!(h:real->complex) a. &0 < a /\ (\z. h(drop z)) IN lspace (:real^1) (&2)
     ==> lnorm (:real^1) (&2) (\z. h(a * drop z)) =
         inv(sqrt a) * lnorm (:real^1) (&2) (\z. h(drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (h:real->complex)(a * drop z)) =
    (\z. inv(sqrt a) % (Cx(sqrt a) * (\w. h(drop w))(a % z)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN
    REWRITE_TAC[DROP_CMUL; COMPLEX_CMUL; GSYM CX_MUL; COMPLEX_MUL_ASSOC;
      GSYM CX_MUL] THEN
    SUBGOAL_THEN `inv(sqrt a) * sqrt a = &1` SUBST1_TAC THENL
     [MATCH_MP_TAC REAL_MUL_LINV THEN MATCH_MP_TAC REAL_LT_IMP_NZ THEN
      MATCH_MP_TAC SQRT_POS_LT THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[CX_MUL; COMPLEX_MUL_LID]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`(:real^1)`; `&2`;
    `\z. Cx(sqrt a) * (\w. (h:real->complex)(drop w))(a % z)`;
    `inv(sqrt a)`] LNORM_MUL) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_EQ; ARITH_EQ] THEN
    MATCH_MP_TAC L2_DILATE_LSPACE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`\w. (h:real->complex)(drop w)`;
    `a:real`] LNORM_DILATE_EQ) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `abs(inv(sqrt a)) = inv(sqrt a)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_INV] THEN AP_TERM_TAC THEN
     REWRITE_TAC[REAL_ABS_REFL] THEN
    MATCH_MP_TAC SQRT_POS_LE THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[]]);;

(* S1: modulation is a unit-modulus multiplier, so |M_b D_a h| = |D_a h|.    *)
let MODDIL_NORM = prove
 (`!(h:real->complex) a b z. norm(carleson_modulate b (carleson_dilate a h)
   (drop z)) = norm(h(a * drop z))`,
  REWRITE_TAC[carleson_modulate; carleson_dilate; COMPLEX_NORM_MUL] THEN
  REWRITE_TAC[GSYM CX_MUL; GSYM COMPLEX_MUL_ASSOC; NORM_CEXP_II;
    REAL_MUL_LID]);;

(* S1: ||M_b D_a h||_2 = (1/sqrt a) ||h||_2.                                 *)
let MODDIL_LNORM = prove
 (`!(h:real->complex) a b. &0 < a /\ (\z. h(drop z)) IN lspace (:real^1) (&2)
     ==> lnorm (:real^1) (&2) (\z. carleson_modulate b (carleson_dilate a h)
       (drop z)) =
         inv(sqrt a) * lnorm (:real^1) (&2) (\z. h(drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `lnorm (:real^1) (&2) (\z. carleson_modulate b (carleson_dilate a h) (drop
     z)) =
    lnorm (:real^1) (&2) (\z. (h:real->complex)(a * drop z))` SUBST1_TAC THENL
   [MATCH_MP_TAC LNORM_NORM_EQ THEN GEN_TAC THEN
     REWRITE_TAC[MODDIL_NORM]; ALL_TAC] THEN
  MATCH_MP_TAC DILATE_ARG_LNORM THEN ASM_REWRITE_TAC[]);;

(* S2: the D_{1/alpha} A M_beta D_alpha h kernel, a real >= 0.               *)
let carleson_amd = new_definition
 `carleson_amd (h:real->complex) alpha beta x =
    carleson_A (carleson_modulate beta (carleson_dilate alpha h)) (x /
      alpha)`;;

let AMD_NONNEG = prove
 (`!(h:real->complex) alpha beta x. schwartz h /\ &0 < alpha ==> &0 <=
   carleson_amd h alpha beta x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_amd] THEN
  MATCH_MP_TAC CARLESON_A_POS THEN
  MATCH_MP_TAC CARLESON_SCHWARTZ_MODDIL THEN
  ASM_SIMP_TAC[REAL_LT_IMP_NZ]);;

(* S3: change-of-variables on a general measurable set (from                 *)
(* HAS_INTEGRAL_AFFINITY                                                     *)
(* on IMAGE lift):  int_{IMAGE(a.)T} f-preimage form.                        *)
let HAS_REAL_INTEGRAL_DILATE_SET = prove
 (`!(f:real->real) a Tset i. &0 < a /\ (f has_real_integral i) (IMAGE (\x. a *
   x) Tset)
     ==> ((\x. f(a * x)) has_real_integral (inv a * i)) Tset`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[has_real_integral] THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[has_real_integral]) THEN
  DISCH_THEN(MP_TAC o SPECL [`a:real`; `vec 0:real^1`] o MATCH_MP
    (ONCE_REWRITE_RULE[IMP_CONJ] HAS_INTEGRAL_AFFINITY)) THEN
  ANTS_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[DIMINDEX_1; REAL_POW_1; VECTOR_MUL_RZERO; VECTOR_ADD_RID;
    VECTOR_NEG_0] THEN
  SUBGOAL_THEN
   `IMAGE (\x:real^1. inv a % x) (IMAGE lift (IMAGE (\x. a * x) Tset)) = IMAGE
     lift Tset`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM IMAGE_o; o_DEF] THEN
    SUBGOAL_THEN
      `(\x. inv a % lift (a * x)) = (\x:real. lift x)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `u:real` THEN
      REWRITE_TAC[LIFT_CMUL; VECTOR_MUL_ASSOC] THEN
      SUBGOAL_THEN `inv a * a = &1` SUBST1_TAC THENL
       [MATCH_MP_TAC REAL_MUL_LINV THEN ASM_REAL_ARITH_TAC;
        REWRITE_TAC[VECTOR_MUL_LID]];
      REWRITE_TAC[ETA_AX]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\x. (lift o f o drop) (a % x)) = lift o (\x. f (a * x)) o drop`
    SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN GEN_TAC THEN
     REWRITE_TAC[DROP_CMUL; LIFT_DROP];
    ALL_TAC] THEN
  SUBGOAL_THEN `inv(abs a) % lift i = lift(inv a * i)` SUBST1_TAC THENL
   [ASM_SIMP_TAC[REAL_ARITH `&0 < a ==> abs a = a`; LIFT_CMUL]; ALL_TAC] THEN
  REWRITE_TAC[]);;

let REAL_DIV_INV_MUL = prove
 (`!x a:real. x / a = inv a * x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[real_div] THEN REAL_ARITH_TAC);;

(* S3: int_F (D_{1/a}AM_bD_a h) = a * int_{a^-1 F} A(M_b D_a h).             *)
let AMD_INT_F_SUBST = prove
 (`!(h:real->complex) a b FF. schwartz h /\ &0 < a /\ real_measurable FF
   ==> real_integral FF (\x. carleson_amd h a b x) =
       a * real_integral (IMAGE (\x. inv a * x) FF)
             (carleson_A (carleson_modulate b (carleson_dilate a h)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_amd] THEN
  MP_TAC(ISPECL [`carleson_A (carleson_modulate b (carleson_dilate a
    (h:real->complex)))`;
                 `inv a:real`; `FF:real->bool`;
                 `real_integral (IMAGE (\x. inv a * x) FF) (carleson_A
                   (carleson_modulate b (carleson_dilate a
                    (h:real->complex))))`]
    HAS_REAL_INTEGRAL_DILATE_SET) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_INV THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN
      MATCH_MP_TAC CARLESON_A_INTEGRABLE THEN CONJ_TAC THENL
       [MATCH_MP_TAC CARLESON_SCHWARTZ_MODDIL THEN
         ASM_SIMP_TAC[REAL_LT_IMP_NZ];
        MATCH_MP_TAC REAL_MEASURABLE_SCALING THEN ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  REWRITE_TAC[REAL_INV_INV; REAL_DIV_INV_MUL] THEN
  DISCH_THEN(SUBST1_TAC o MATCH_MP REAL_INTEGRAL_UNIQUE) THEN REFL_TAC);;

let INV_SQRT_SQ = prove
 (`!a. &0 < a ==> inv(sqrt a) * inv(sqrt a) = inv a`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM REAL_INV_MUL] THEN AP_TERM_TAC THEN
  MP_TAC(SPEC `a:real` SQRT_POW_2) THEN ANTS_TAC THENL
   [ASM_REAL_ARITH_TAC; REWRITE_TAC[REAL_POW_2] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* S3 [286S(b) core]: the per-(alpha,beta) slice integral, INDEPENDENT of    *)
(* (a,b):                                                                    *)
(* int_F (D_{1/a}AM_bD_a h) <= 4C9 ||h||_2 sqrt(muF) -- the a cancels via    *)
(* the                                                                       *)
(* scaling a * (1/sqrt a) * sqrt(1/a) = 1. Takes 286P's bound as a           *)
(* hypothesis.                                                               *)
let AMD_INT_F_BOUND = prove
 (`!(h:real->complex) a b FF C9.
     schwartz h /\ &0 < a /\ real_measurable FF /\ &0 <= C9 /\
     (!(g:real->complex) GG. schwartz g /\ real_measurable GG
        ==> real_integral GG (carleson_A g)
            <= &4 * C9 * lnorm (:real^1) (&2) (\z. g(drop z)) *
              sqrt(real_measure GG))
   ==> real_integral FF (\x. carleson_amd h a b x)
       <= &4 * C9 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
         FF)`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[AMD_INT_F_SUBST] THEN
  SUBGOAL_THEN
   `real_integral (IMAGE (\x. inv a * x) FF)
      (carleson_A (carleson_modulate b (carleson_dilate a (h:real->complex))))
    <= &4 * C9 *
       lnorm (:real^1) (&2) (\z. carleson_modulate b (carleson_dilate a h)
         (drop z)) *
       sqrt(real_measure (IMAGE (\x. inv a * x) FF))`
   ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_SCHWARTZ_MODDIL THEN ASM_SIMP_TAC[REAL_LT_IMP_NZ];
      MATCH_MP_TAC REAL_MEASURABLE_SCALING THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `a * (&4 * C9 *
     lnorm (:real^1) (&2) (\z. carleson_modulate b (carleson_dilate a h) (drop
       z)) *
     sqrt(real_measure (IMAGE (\x. inv a * x) FF)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real->complex`; `a:real`; `b:real`] MODDIL_LNORM) THEN
  ANTS_TAC THENL [ASM_SIMP_TAC[SCHWARTZ_L2]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
    `real_measure (IMAGE (\x. inv a * x) FF) = inv a * real_measure FF`
    SUBST1_TAC THENL
   [ASM_SIMP_TAC[REAL_MEASURE_SCALING] THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[REAL_ABS_INV] THEN
    AP_TERM_TAC THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= real_measure FF` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_MEASURE_POS_LE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[SQRT_MUL; REAL_LE_INV_EQ; REAL_LT_IMP_LE] THEN
  MATCH_MP_TAC(REAL_ARITH `x = y ==> x <= y`) THEN
  SUBGOAL_THEN `sqrt(inv a) = inv(sqrt a)` SUBST1_TAC THENL
   [REWRITE_TAC[SQRT_INV]; ALL_TAC] THEN
  SUBGOAL_THEN `a * inv(sqrt a) * inv(sqrt a) = &1` MP_TAC THENL
   [MP_TAC(SPEC `a:real` INV_SQRT_SQ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN MATCH_MP_TAC REAL_MUL_RINV THEN
      ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  CONV_TAC REAL_RING);;

(* ========================================================================= *)
(* S5: the real-valued liminf-Fatou lemma (Fremlin's 286S(b) Fatou step).    *)
(* No pre-built real liminf-Fatou exists (library FATOU needs a supplied     *)
(* pointwise limit). Built here from the running infimum w_m = inf_{n>=m}    *)
(* f_n                                                                       *)
(* (increasing to liminf) via                                                *)
(* REAL_BEPPO_LEVI_MONOTONE_CONVERGENCE_INCREASING.                          *)
(* ========================================================================= *)

(* finite-tail inf is absolutely integrable (finite index set).              *)
let FINTAIL_INF_INTEGRABLE = prove
 (`!(f:num->real->real) s m k.
     (!n. (f n) absolutely_real_integrable_on s)
     ==> (\x. inf {f n x | n IN m..(m+k)}) absolutely_real_integrable_on s`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `!x. {f n x | n IN m..(m+k)} =
     IMAGE (\n. (f:num->real->real) n x) (m..(m+k))`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[SIMPLE_IMAGE]; ALL_TAC] THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_INF THEN
  REWRITE_TAC[FINITE_NUMSEG; NUMSEG_EMPTY; NOT_LT; LE_ADD] THEN
  REWRITE_TAC[ETA_AX] THEN ASM_REWRITE_TAC[]);;

let FINTAIL_INF_NONNEG = prove
 (`!(f:num->real->real) m k x. (!n. &0 <= f n x)
     ==> &0 <= inf {f n x | n IN m..(m+k)}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_INF THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM; FORALL_IN_GSPEC] THEN
  CONJ_TAC THENL
   [EXISTS_TAC `(f:num->real->real) m x` THEN EXISTS_TAC `m:num` THEN
    REWRITE_TAC[IN_NUMSEG; LE_REFL; LE_ADD];
    REWRITE_TAC[IN_NUMSEG] THEN REPEAT STRIP_TAC THEN ASM_SIMP_TAC[]]);;
let FINTAIL_INF_LE_HEAD = prove
 (`!(f:num->real->real) m k x. (!n. &0 <= f n x)
     ==> inf {f n x | n IN m..(m+k)} <= f m x`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC INF_LE_ELEMENT THEN CONJ_TAC THENL
   [EXISTS_TAC `&0:real` THEN REWRITE_TAC[FORALL_IN_GSPEC; IN_NUMSEG] THEN
    REPEAT STRIP_TAC THEN ASM_SIMP_TAC[];
    REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `m:num` THEN
    REWRITE_TAC[IN_NUMSEG; LE_REFL; LE_ADD]]);;

(* the finite-tail inf decreases to the infinite-tail inf as k -> inf.       *)
let RUNNING_INF_CONVERGES = prove
 (`!(f:num->real->real) m x.
     (!n. &0 <= f n x)
     ==> ((\k. inf {f n x | n IN m..(m+k)}) ---> inf {f n x | n >= m})
       sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `~({(f:num->real->real) n x | n >= m} = {}) /\
    (?b. !w. w IN {(f:num->real->real) n x | n >= m} ==> b <= w)`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      EXISTS_TAC `(f:num->real->real) m x` THEN EXISTS_TAC `m:num` THEN
      REWRITE_TAC[GE; LE_REFL];
      EXISTS_TAC `&0:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPEC `{(f:num->real->real) n x | n >= m}` INF) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `i = inf {(f:num->real->real) n x | n >= m}` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ilb") (LABEL_TAC "igt")) THEN
  SUBGOAL_THEN
    `!k. i <= inf {(f:num->real->real) n x | n IN m..(m+k)}` ASSUME_TAC THENL
   [X_GEN_TAC `k:num` THEN
    SUBGOAL_THEN `i = inf {(f:num->real->real) n x | n >= m}` SUBST1_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_INF_SUBSET THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      EXISTS_TAC `(f:num->real->real) m x` THEN EXISTS_TAC `m:num` THEN
      REWRITE_TAC[IN_NUMSEG; LE_REFL; LE_ADD];
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
      DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `n:num` THEN
      ASM_REWRITE_TAC[GE] THEN
      FIRST_X_ASSUM(MP_TAC o check (fun th -> can (find_term (fun t -> t =
        `(m:num)..(m+k)`)) (concl th))) THEN
      REWRITE_TAC[IN_NUMSEG] THEN ARITH_TAC;
      EXISTS_TAC `&0:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `?n0:num. n0 >= m /\
     (f:num->real->real) n0 x < i + e` STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[GSYM REAL_NOT_LE] THEN
    ONCE_REWRITE_TAC[MESON[] `(?n0. P n0 /\ ~Q n0) <=> ~(!n0. P n0 ==> Q n0)`]
      THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `i + e <= i` MP_TAC THENL
     [REMOVE_THEN "igt" MATCH_MP_TAC THEN
      REWRITE_TAC[IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
      DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
      ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN
      ASM_REWRITE_TAC[];
      ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `n0 - m:num` THEN X_GEN_TAC `k:num` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `inf {(f:num->real->real) n x | n IN m..(m+k)} <= f n0 x` ASSUME_TAC THENL
   [MATCH_MP_TAC INF_LE_ELEMENT THEN CONJ_TAC THENL
     [EXISTS_TAC `&0:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `n0:num` THEN
      REWRITE_TAC[IN_NUMSEG] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[GE]) THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `i <= inf {(f:num->real->real) n x | n IN m..(m+k)}` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_forall(concl th) &&
       can (find_term (fun t -> t = `(m:num)..(m+k)`)) (concl th)
       then MATCH_ACCEPT_TAC(SPEC `k:num` th) else NO_TAC);
    ALL_TAC] THEN
  MP_TAC(SPECL [`inf {(f:num->real->real) n x | n IN m..(m+k)}`;
               `i:real`; `e:real`; `(f:num->real->real) n0 x`]
    (REAL_ARITH `!w i e f0. i <= w /\ w <= f0 /\ f0 < i + e ==> abs(w - i) <
      e`)) THEN
  ASM_REWRITE_TAC[]);;

(* the infinite-tail inf w_m = inf_{n>=m} f_n is integrable (decreasing      *)
(* MCT).                                                                     *)
let RUNNING_INF_TAIL_INTEGRABLE = prove
 (`!(f:num->real->real) s m.
     (!n. (f n) absolutely_real_integrable_on s) /\
     (!n x. x IN s ==> &0 <= f n x)
     ==> (\x. inf {f n x | n >= m}) real_integrable_on s`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\k. (\x. inf {(f:num->real->real) n x | n IN m..(m+k)})`;
                 `\x. inf {(f:num->real->real) n x | n >= m}`; `s:real->bool`]
    REAL_MONOTONE_CONVERGENCE_DECREASING) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [X_GEN_TAC `k:num` THEN
      MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC FINTAIL_INF_INTEGRABLE THEN ASM_REWRITE_TAC[];
      REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_INF_SUBSET THEN
        REPEAT CONJ_TAC THENL
       [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
        EXISTS_TAC `(f:num->real->real) m x` THEN EXISTS_TAC `m:num` THEN
        REWRITE_TAC[IN_NUMSEG; LE_REFL; LE_ADD];
        REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
        DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
          EXISTS_TAC `n:num` THEN
        ASM_REWRITE_TAC[] THEN
        FIRST_X_ASSUM(MP_TAC o check(fun th -> can(find_term(fun
          t->t=`(m:num)..(m+k)`))(concl th))) THEN
        REWRITE_TAC[IN_NUMSEG] THEN ARITH_TAC;
        EXISTS_TAC `&0:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN
        REPEAT STRIP_TAC THEN ASM_SIMP_TAC[]];
      REPEAT STRIP_TAC THEN MATCH_MP_TAC RUNNING_INF_CONVERGES THEN
        ASM_SIMP_TAC[];
      REWRITE_TAC[real_bounded; FORALL_IN_GSPEC; IN_UNIV] THEN
      EXISTS_TAC `real_integral s ((f:num->real->real) m)` THEN
        X_GEN_TAC `k:num` THEN
      MATCH_MP_TAC(REAL_ARITH `&0 <= x /\ x <= b ==> abs x <= b`) THEN
        CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INTEGRAL_POS THEN CONJ_TAC THENL
         [MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
          MATCH_MP_TAC FINTAIL_INF_INTEGRABLE THEN ASM_REWRITE_TAC[];
          X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
          MATCH_MP_TAC FINTAIL_INF_NONNEG THEN ASM_SIMP_TAC[]];
        MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
          MATCH_MP_TAC FINTAIL_INF_INTEGRABLE THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
          ASM_REWRITE_TAC[ETA_AX];
          X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
          MATCH_MP_TAC FINTAIL_INF_LE_HEAD THEN ASM_SIMP_TAC[]]]];
    STRIP_TAC THEN ASM_REWRITE_TAC[]]);;

(* REAL_FATOU_LIMINF: f_n >= 0 integrable with int f_n <= B ==> the          *)
(* pointwise liminf (= lim of running infima) is integrable with integral <= *)
(* B.                                                                        *)
let REAL_FATOU_LIMINF = prove
 (`!(f:num->real->real) s B.
     (!n. (f n) absolutely_real_integrable_on s) /\
     (!n x. x IN s ==> &0 <= f n x) /\
     (!n. real_integral s (f n) <= B)
     ==> ?g k. real_negligible k /\
               (!x. x IN s DIFF k ==> ((\m. inf {f n x | n >= m}) ---> g x)
                 sequentially) /\
               g real_integrable_on s /\ real_integral s g <= B`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\m. (\x. inf {(f:num->real->real) n x | n >= m})`;
    `s:real->bool`]
    REAL_BEPPO_LEVI_MONOTONE_CONVERGENCE_INCREASING) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [GEN_TAC THEN MATCH_MP_TAC RUNNING_INF_TAIL_INTEGRABLE THEN
       ASM_REWRITE_TAC[];
      REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_INF_SUBSET THEN
        REPEAT CONJ_TAC THENL
       [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
        EXISTS_TAC `(f:num->real->real) (SUC k) x` THEN EXISTS_TAC `SUC k` THEN
        REWRITE_TAC[GE; LE_REFL];
        REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN X_GEN_TAC `w:real` THEN
        DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
          EXISTS_TAC `n:num` THEN
        ASM_REWRITE_TAC[] THEN UNDISCH_TAC `n >= SUC k` THEN ARITH_TAC;
        EXISTS_TAC `&0:real` THEN REWRITE_TAC[IN_ELIM_THM] THEN
        REPEAT STRIP_TAC THEN ASM_SIMP_TAC[]];
      REWRITE_TAC[real_bounded; FORALL_IN_GSPEC; IN_UNIV] THEN
      EXISTS_TAC `B:real` THEN X_GEN_TAC `k:num` THEN
      MATCH_MP_TAC(REAL_ARITH `&0 <= x /\ x <= B ==> abs x <= B`) THEN
        CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INTEGRAL_POS THEN CONJ_TAC THENL
         [MATCH_MP_TAC RUNNING_INF_TAIL_INTEGRABLE THEN ASM_REWRITE_TAC[];
          X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
          MATCH_MP_TAC REAL_LE_INF THEN
          REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM; FORALL_IN_GSPEC] THEN
          CONJ_TAC THENL
           [EXISTS_TAC `(f:num->real->real) k x` THEN EXISTS_TAC `k:num` THEN
            REWRITE_TAC[GE; LE_REFL];
            REPEAT STRIP_TAC THEN ASM_SIMP_TAC[]]];
        MATCH_MP_TAC REAL_LE_TRANS THEN
          EXISTS_TAC `real_integral s ((f:num->real->real) k)` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
           [MATCH_MP_TAC RUNNING_INF_TAIL_INTEGRABLE THEN ASM_REWRITE_TAC[];
            MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
              ASM_REWRITE_TAC[ETA_AX];
            X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
            MATCH_MP_TAC INF_LE_ELEMENT THEN CONJ_TAC THENL
             [EXISTS_TAC `&0:real` THEN REWRITE_TAC[FORALL_IN_GSPEC] THEN
              REPEAT STRIP_TAC THEN ASM_SIMP_TAC[];
              REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `k:num` THEN
                REWRITE_TAC[GE; LE_REFL]]];
          ASM_REWRITE_TAC[]]]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:real->real` (X_CHOOSE_THEN
    `kk:real->bool` STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`g:real->real`; `kk:real->bool`] THEN
    ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPEC `sequentially` REALLIM_UBOUND) THEN
  EXISTS_TAC `\m. real_integral s (\x. inf {(f:num->real->real) n x | n >= m})`
    THEN
  ASM_REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY; EVENTUALLY_SEQUENTIALLY] THEN
  EXISTS_TAC `0` THEN X_GEN_TAC `m:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral s ((f:num->real->real) m)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC RUNNING_INF_TAIL_INTEGRABLE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
        ASM_REWRITE_TAC[ETA_AX];
      X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
      MATCH_MP_TAC INF_LE_ELEMENT THEN CONJ_TAC THENL
       [EXISTS_TAC `&0:real` THEN REWRITE_TAC[FORALL_IN_GSPEC] THEN
        REPEAT STRIP_TAC THEN ASM_SIMP_TAC[];
        REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `m:num` THEN
          REWRITE_TAC[GE; LE_REFL]]];
    ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* S4: the iterated dilation-average operator (Fremlin 286S) and the log 2   *)
(* factor int_[1,2] (1/alpha) dalpha = log 2 used in the per-n integral      *)
(* bound.                                                                    *)
(* ========================================================================= *)

(* int_[1,2] (1/alpha) dalpha = log 2  (FTC with (log)' = inv).              *)
let INV_INTEGRAL_1_2_LOG2 = prove
 (`real_integral (real_interval[&1,&2]) (\a. inv a) = log(&2)`,
  MATCH_MP_TAC REAL_INTEGRAL_UNIQUE THEN
  SUBGOAL_THEN `log(&2) = log(&2) - log(&1)` SUBST1_TAC THENL
   [REWRITE_TAC[LOG_1] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_FUNDAMENTAL_THEOREM_OF_CALCULUS THEN
  REWRITE_TAC[REAL_ARITH `&1 <= &2`] THEN
  X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
  MATCH_MP_TAC HAS_REAL_DERIVATIVE_ATREAL_WITHIN THEN
  MATCH_MP_TAC HAS_REAL_DERIVATIVE_LOG THEN ASM_REAL_ARITH_TAC);;

(* the inner (alpha,beta) double integral of the D_{1/a}AM_bD_a h kernel (no *)
(* 1/n).                                                                     *)
let carleson_Sinner = new_definition
 `carleson_Sinner (h:real->complex) n x =
    real_integral (real_interval[&1,&2])
      (\alpha. inv alpha * real_integral (real_interval[&0,&n])
                 (\beta. carleson_amd h alpha beta x))`;;

(* the n-th dilation-average (1/n) int_1^2 (1/a) int_0^n (D_{1/a}AM_bD_a     *)
(* h)(x).                                                                    *)
let carleson_Aavg = new_definition
 `carleson_Aavg (h:real->complex) n x = inv(&n) * carleson_Sinner h n x`;;

(* carleson_Atilde h x = liminf_n Aavg h n x (Fremlin 286S: the iterated     *)
(* dilation-                                                                 *)
(* average operator). Encoded as the reallim of the running infima (matches  *)
(* the g of                                                                  *)
(* REAL_FATOU_LIMINF, which is how ATILDE_INT_F_BOUND = 286S(b) will be      *)
(* derived).                                                                 *)
let carleson_Atilde = new_definition
 `carleson_Atilde (h:real->complex) x =
    reallim sequentially (\m. inf {carleson_Aavg h n x | n >= m})`;;

(* multivariate LSC: a real^1-valued function with OPEN superlevels {x |     *)
(* drop(f x) > a}                                                            *)
(* is measurable_on the whole space. The R^M analogue of                     *)
(* REAL_MEASURABLE_ON_LSC, used to                                           *)
(* get 286S(a) joint measurability of (alpha,beta,x) |-> amd = sup_z         *)
(* (jointly-continuous).                                                     *)
let MEASURABLE_ON_LSC_MULTI = prove
 (`!(f:real^M->real^1). (!a. open {x | drop(f x) > a}) ==> f measurable_on
   (:real^M)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[MEASURABLE_ON_PREIMAGE_HALFSPACE_COMPONENT_GT] THEN
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `k = 1` SUBST_ALL_TAC THENL
   [UNDISCH_TAC `k <= dimindex(:1)` THEN UNDISCH_TAC `1 <= k` THEN
    REWRITE_TAC[DIMINDEX_1] THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM drop] THEN MATCH_MP_TAC LEBESGUE_MEASURABLE_OPEN THEN
  ASM_REWRITE_TAC[]);;

(* joint curve limit: aseq->a0, bseq->b0 ==> aseq*z+bseq -> a0*z+b0.         *)
let CX_SEQ_LIM = prove
 (`!(g:num->real) l. (g ---> l) sequentially ==> ((\m. Cx(g m)) --> Cx l)
   sequentially`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o ONCE_REWRITE_RULE[REALLIM_COMPLEX]) THEN
    REWRITE_TAC[o_DEF]);;

(* modulation-phase continuity: xseq ---> x0 ==> cexp(ii xseq_m w) -->       *)
(* cexp(ii x0 w).                                                            *)
let CEXP_SEQ_LIM = prove
 (`!(xseq:num->real) x0 w. (xseq ---> x0) sequentially
     ==> ((\m. cexp(ii * Cx(xseq m) * Cx w)) --> cexp(ii * Cx x0 * Cx w))
       sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`cexp`; `sequentially`; `\m:num. ii * Cx(xseq m) * Cx w`;
                 `ii * Cx x0 * Cx w`] LIM_CONTINUOUS_FUNCTION) THEN
  REWRITE_TAC[CONTINUOUS_AT_CEXP] THEN DISCH_THEN MATCH_MP_TAC THEN
  ONCE_REWRITE_TAC[COMPLEX_RING `ii * a * Cx w = (ii * Cx w) * a`] THEN
  MATCH_MP_TAC LIM_COMPLEX_LMUL THEN
  MATCH_MP_TAC CX_SEQ_LIM THEN ASM_REWRITE_TAC[]);;

(* a.e. joint (a,b,x)-convergence of the tile-window Fourier INTEGRAND       *)
(* (fixed w). For a.e.                                                       *)
(* w -- both (alpha0 z+beta0) [fixed] and (alpha0 w+beta0) non-dyadic + off  *)
(* gate -- the                                                               *)
(* integrand cexp(ii x w) hhat(w) theta'_{z a b}(w) converges jointly. For   *)
(* w<z the theta'                                                            *)
(* factor uses THETA'_JOINT_CONTINUOUS; for w>=z both sides vanish           *)
(* (CARLESON_THETA'_SUPPORT).                                                *)
(* This is the DCT input for the joint continuity of the window (286S(a)).   *)
let MEASURABLE_ON_AFFINE_INNER = prove
 (`!(ff:real^1->complex) c d. ~(c = &0) /\ ff measurable_on (:real^1)
     ==> (\w:real^1. ff(c % w + d)) measurable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(\w:real^1. (ff:real^1->complex)(c % w + d)) =
                ((\u. ff(u + d)) o (\w:real^1. c % w))` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_DEF]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\w:real^1. c % w`; `\u:real^1. (ff:real^1->complex)(u+d)`;
    `(:real^1)`]
    MEASURABLE_ON_LINEAR_IMAGE_EQ) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[linear] THEN CONJ_TAC THEN VECTOR_ARITH_TAC;
      REWRITE_TAC[VECTOR_MUL_LCANCEL] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
    `IMAGE (\w:real^1. c % w) (:real^1) = (:real^1)` SUBST1_TAC THENL
   [MATCH_MP_TAC SURJECTIVE_IMAGE_EQ THEN REWRITE_TAC[IN_UNIV] THEN
    X_GEN_TAC `y:real^1` THEN EXISTS_TAC `inv c % y:real^1` THEN
    REWRITE_TAC[VECTOR_MUL_ASSOC] THEN
      ASM_SIMP_TAC[REAL_MUL_RINV; VECTOR_MUL_LID];
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[MEASURABLE_ON_TRANSLATION_EQ] THEN
  SUBGOAL_THEN
    `(\u:real^1. (ff:real^1->complex)(u + d)) =
     (\u. ff(d + u))` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
     VECTOR_ARITH_TAC;
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[MEASURABLE_ON_TRANSLATION_EQ] THEN
  SUBGOAL_THEN
    `IMAGE (\x:real^1. d + x) (:real^1) = (:real^1)` SUBST1_TAC THENL
   [MATCH_MP_TAC SURJECTIVE_IMAGE_EQ THEN REWRITE_TAC[IN_UNIV] THEN
    X_GEN_TAC `y:real^1` THEN EXISTS_TAC `y - d:real^1` THEN VECTOR_ARITH_TAC;
    ASM_REWRITE_TAC[ETA_AX]]);;

(* hence theta'_{z a b}(.) is measurable in its last argument w (theta       *)
(* measurable in Y [CARLESON_THETA_CX_MEASURABLE] composed with the affine w *)
(* |-> a w+b).                                                               *)
let CARLESON_THETA'_W_CX_MEASURABLE = prove
 (`!z a b. ~(a = &0)
     ==> (\w:real^1. Cx(carleson_theta' z a b (drop w))) measurable_on
       (:real^1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  SUBGOAL_THEN
   `(\w:real^1. Cx(carleson_theta (a*z+b) (a * drop w + b))) =
    (\w:real^1. (\u:real^1. Cx(carleson_theta (a*z+b) (drop u))) (a % w + lift
      b))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[DROP_ADD; DROP_CMUL; LIFT_DROP];
    ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_AFFINE_INNER THEN
  ASM_REWRITE_TAC[CARLESON_THETA_CX_MEASURABLE]);;

(* the tile-window Fourier integrand hhat * Cx(theta'_{z a b}) is absolutely *)
(* integrable (measurable * bounded, dominated by |hhat|; the DCT L1/L2/L4   *)
(* input for WINDOW_JOINT_CONT).                                             *)
let CARLESON_FHAT_THETA'_ABSINT = prove
 (`!(h:real->complex) z a b. schwartz h /\ ~(a = &0)
     ==> (\y. fourier h (drop y) * Cx(carleson_theta' z a b (drop y)))
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`z:real`;`a:real`;`b:real`] CARLESON_THETA'_W_CX_MEASURABLE)
    THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC `\y:real^1. lift(norm(fourier (h:real->complex) (drop y)))` THEN
    REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN CONJ_TAC THENL
     [MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
       ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[ABSOLUTELY_INTEGRABLE_MEASURABLE] THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
    MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
      ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real^1` THEN
      REWRITE_TAC[IN_UNIV; LIFT_DROP; COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
    MP_TAC(ISPECL [`z:real`; `a:real`; `b:real`;
      `drop(x:real^1)`] CARLESON_THETA'_BOUNDS) THEN
    REAL_ARITH_TAC]);;

(* =================================================================         *)
(* S6 keystone foundation: joint 3D measurability of the tile-sup            *)
(* theta' kernel.  Mirrors CARLESON_THETA_MEASURABLE (1D) but on             *)
(* real^3 (a=p$1,b=p$2,w=p$3), using MEASURABLE_ON_SUP_MULTI for the         *)
(* countable tile sup.  This is what the box-Fubini step MNF_FOURIER_        *)
(* BOX needs to apply FUBINI_INTEGRAL_SWAP over the (a,b)-box x w-line.      *)
(* =================================================================         *)

(* single tile term Re(fhat(A(Y-m)))^2 with Y = a*w+b = p$1*p$3+p$2 is       *)
(* CONTINUOUS in (a,b,w), hence measurable on R^3.                           *)
let CARLESON_THETA_TERM3_MEASURABLE = prove
 (`!(A:real) (m:real).
     (\p:real^3. lift(Re(fourier carleson_phi (A * ((p$1 * p$3 + p$2) - m)))
       pow 2)) measurable_on (:real^3)`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  REWRITE_TAC[o_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_POW THEN
  REWRITE_TAC[RE_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
  SUBGOAL_THEN
   `(\p:real^3. fourier carleson_phi (A * ((p$1 * p$3 + p$2) - m))) =
    (\w:real^1. fourier carleson_phi (drop w)) o (\p:real^3. lift(A * ((p$1 *
      p$3 + p$2) - m)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [REWRITE_TAC[LIFT_CMUL] THEN MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
    REWRITE_TAC[LIFT_SUB] THEN MATCH_MP_TAC CONTINUOUS_ON_SUB THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
    REWRITE_TAC[LIFT_ADD] THEN MATCH_MP_TAC CONTINUOUS_ON_ADD THEN
      CONJ_TAC THENL
     [SUBGOAL_THEN
       `(\p:real^3. lift(p$1 * p$3)) = (\p:real^3. (p$1) % lift(p$3))`
       SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM; LIFT_CMUL]; ALL_TAC] THEN
      MATCH_MP_TAC CONTINUOUS_ON_MUL THEN CONJ_TAC THENL
       [REWRITE_TAC[o_DEF] THEN
        MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
          REWRITE_TAC[CONTINUOUS_ON_ID];
        MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
          REWRITE_TAC[CONTINUOUS_ON_ID]];
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
        REWRITE_TAC[CONTINUOUS_ON_ID]];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN
      MATCH_MP_TAC SCHWARTZ_ABSINT THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
      REWRITE_TAC[SUBSET_UNIV]]]);;

(* preimage of a dyadic half-open interval under a measurable map g:R^3->R   *)
(* is lebesgue_measurable (= closed-halfline preimage INTER open-halfline    *)
(* preimage, LEBESGUE_MEASURABLE_PREIMAGE_CLOSED/OPEN).                      *)
let DYHO_PREIMAGE_MEASURABLE = prove
 (`!(g:real^3->real) k n. (\p. lift(g p)) measurable_on (:real^3)
     ==> lebesgue_measurable {p:real^3 | g p IN dyho k n}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[dyho] THEN
  SUBGOAL_THEN
   `{p:real^3 | (g:real^3->real) p IN {x | real_of_int n * &2 zpow k <= x /\ x
     < (real_of_int n + &1) * &2 zpow k}} =
    {p | g p IN {x | real_of_int n * &2 zpow k <= x}} INTER
    {p | g p IN {x | x < (real_of_int n + &1) * &2 zpow k}}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
     MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`\p:real^3. lift((g:real^3->real) p)`;
                   `{x:real^1 | real_of_int n * &2 zpow k <= drop x}`]
                     LEBESGUE_MEASURABLE_PREIMAGE_CLOSED) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `{x:real^1 | real_of_int n * &2 zpow k <= drop x} = {x | x$1 >=
        real_of_int n * &2 zpow k}` SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM; real_ge; drop]; ALL_TAC] THEN
      REWRITE_TAC[CLOSED_HALFSPACE_COMPONENT_GE];
      MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
      REWRITE_TAC[EXTENSION; IN_ELIM_THM; LIFT_DROP]];
    MP_TAC(ISPECL [`\p:real^3. lift((g:real^3->real) p)`;
                   `{x:real^1 | drop x < (real_of_int n + &1) * &2 zpow k}`]
                     LEBESGUE_MEASURABLE_PREIMAGE_OPEN) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `{x:real^1 | drop x < (real_of_int n + &1) * &2 zpow k} = {x | x$1 <
        (real_of_int n + &1) * &2 zpow k}` SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM; drop]; ALL_TAC] THEN
      REWRITE_TAC[OPEN_HALFSPACE_COMPONENT_LT];
      MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
      REWRITE_TAC[EXTENSION; IN_ELIM_THM; LIFT_DROP]]]);;

(* the two tile-condition coordinate maps on R^3 (a=p$1,b=p$2,w=p$3) are     *)
(* measurable: Y = a*w+b = p$1*p$3+p$2 (bilinear), Z = a*z+b = p$1*z+p$2     *)
(* (affine, z a fixed real).                                                 *)
let YMAP3_MEASURABLE = prove
 (`(\p:real^3. lift(p$1 * p$3 + p$2)) measurable_on (:real^3)`,
  MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  REWRITE_TAC[LIFT_ADD] THEN MATCH_MP_TAC CONTINUOUS_ON_ADD THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\p:real^3. lift(p$1 * p$3)) = (\p:real^3. (p$1) % lift(p$3))` SUBST1_TAC
     THENL
     [REWRITE_TAC[FUN_EQ_THM; LIFT_CMUL]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_MUL THEN CONJ_TAC THENL
     [REWRITE_TAC[o_DEF] THEN
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
        REWRITE_TAC[CONTINUOUS_ON_ID];
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
        REWRITE_TAC[CONTINUOUS_ON_ID]];
    MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_ID]]);;

let ZMAP3_MEASURABLE = prove
 (`!z:real. (\p:real^3. lift(p$1 * z + p$2)) measurable_on (:real^3)`,
  GEN_TAC THEN MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  REWRITE_TAC[LIFT_ADD] THEN MATCH_MP_TAC CONTINUOUS_ON_ADD THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\p:real^3. lift(p$1 * z)) = (\p:real^3. z % lift(p$1))` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
       REWRITE_TAC[GSYM LIFT_CMUL] THEN
      AP_TERM_TAC THEN REWRITE_TAC[REAL_MUL_SYM];
      MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
        REWRITE_TAC[CONTINUOUS_ON_ID]];
    MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_ID]]);;

(* each enumerated tile-family member (a=p$1,b=p$2,w=p$3) is measurable on   *)
(* R^3: the n=0 sentinel is 0; n>0 is the continuous term restricted to the  *)
(* tile region {Z in Jr} INTER {Y in Jl} (both lebesgue_measurable           *)
(* preimages).                                                               *)
let CARLESON_THETA_FAMILY3_MEASURABLE = prove
 (`!(e:num->int#int#int) (z:real) (n:num).
     (\p:real^3. lift(if n = 0 then &0
          else if (p$1 * z + p$2) IN tile_Jr(e(n-1)) /\ (p$1 * p$3 + p$2) IN
            tile_Jl(e(n-1))
               then Re(fourier carleson_phi (&2 zpow(--tile_k(e(n-1))) * ((p$1
                 * p$3 + p$2) - tile_ymid(e(n-1))))) pow 2
               else &0)) measurable_on (:real^3)`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `n = 0` THEN
  ASM_REWRITE_TAC[LIFT_NUM; MEASURABLE_ON_0] THEN
  ABBREV_TAC `s = (e:num->int#int#int)(n-1)` THEN
  SUBGOAL_THEN
   `(\p:real^3. lift(if (p$1 * z + p$2) IN tile_Jr s /\ (p$1 * p$3 + p$2) IN
     tile_Jl s
               then Re(fourier carleson_phi (&2 zpow(--tile_k s) * ((p$1 * p$3
                 + p$2) - tile_ymid s))) pow 2
               else &0)) =
    (\p:real^3. if p IN ({p | (p$1 * z + p$2) IN tile_Jr s} INTER {p | (p$1 *
      p$3 + p$2) IN tile_Jl s})
                then lift(Re(fourier carleson_phi (&2 zpow(--tile_k s) * ((p$1
                  * p$3 + p$2) - tile_ymid s))) pow 2)
                else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[IN_INTER; IN_ELIM_THM] THEN
    COND_CASES_TAC THEN REWRITE_TAC[LIFT_NUM];
    ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
   [REWRITE_TAC[CARLESON_THETA_TERM3_MEASURABLE];
    MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `k0:int` (X_CHOOSE_THEN
      `rest:int#int` ASSUME_TAC)) THEN
    MP_TAC(ISPEC `rest:int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `nI0:int` (X_CHOOSE_THEN
      `nJ0:int` ASSUME_TAC)) THEN
    SUBGOAL_THEN `s = (k0:int,nI0:int,nJ0:int)` SUBST_ALL_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[tile_Jr; tile_Jl] THEN
    MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
     [MATCH_MP_TAC DYHO_PREIMAGE_MEASURABLE THEN REWRITE_TAC[ZMAP3_MEASURABLE];
      MATCH_MP_TAC DYHO_PREIMAGE_MEASURABLE THEN
        REWRITE_TAC[YMAP3_MEASURABLE]]]);;

(* CAPSTONE: the tile-sup kernel theta'_z(a,b,w) (a=p$1,b=p$2,w=p$3) is      *)
(* JOINTLY measurable on R^3.  theta'_z a b w = theta(a*z+b, a*w+b) is the   *)
(* countable tile-sup (CARLESON_THETA_SUP_RECONCILE) of the family members   *)
(* (CARLESON_THETA_FAMILY3_MEASURABLE), each in [0,1] (CARLESON_THETA_TERM_  *)
(* BOUNDS), so MEASURABLE_ON_SUP_MULTI applies.  This is the joint           *)
(* measurability the S6 box-Fubini keystone MNF_FOURIER_BOX needs.           *)
let CARLESON_THETA'_3D_MEASURABLE = prove
 (`!z:real. (\p:real^3. lift(carleson_theta' z (p$1) (p$2) (p$3)))
   measurable_on (:real^3)`,
  GEN_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  SUBGOAL_THEN
    `?e:num->(int#int#int). (:int#int#int) =
     IMAGE e (:num)` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC COUNTABLE_AS_IMAGE THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM CROSS_UNIV] THEN MATCH_MP_TAC COUNTABLE_CROSS THEN
      REWRITE_TAC[INT_COUNTABLE; GSYM CROSS_UNIV] THEN
        MATCH_MP_TAC COUNTABLE_CROSS THEN
      REWRITE_TAC[INT_COUNTABLE];
      REWRITE_TAC[UNIV_NOT_EMPTY]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\p:real^3. lift(carleson_theta (p$1 * z + p$2) (p$1 * p$3 + p$2))) =
    (\p:real^3. lift(sup {(if nn = 0 then &0
                else if (p$1 * z + p$2) IN tile_Jr (e(nn-1)) /\ (p$1 * p$3 +
                  p$2) IN tile_Jl (e(nn-1))
                     then Re(fourier carleson_phi (&2 zpow(--tile_k(e(nn-1))) *
                       ((p$1 * p$3 + p$2) - tile_ymid(e(nn-1))))) pow 2
                     else &0) | nn IN (:num)}))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    MATCH_MP_TAC CARLESON_THETA_SUP_RECONCILE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC
   `\nn p:real^3. (if nn = 0 then &0
                else if (p$1 * z + p$2) IN tile_Jr (e(nn-1)) /\ (p$1 * p$3 +
                  p$2) IN tile_Jl (e(nn-1))
                     then Re(fourier carleson_phi (&2 zpow(--tile_k(e(nn-1))) *
                       ((p$1 * p$3 + p$2) - tile_ymid(e(nn-1))))) pow 2
                     else &0)` MEASURABLE_ON_SUP_MULTI) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[CARLESON_THETA_FAMILY3_MEASURABLE];
    GEN_TAC THEN EXISTS_TAC `&1` THEN GEN_TAC THEN
    COND_CASES_TAC THEN REWRITE_TAC[REAL_LE_01] THEN
    COND_CASES_TAC THEN REWRITE_TAC[REAL_LE_01] THEN
    REWRITE_TAC[CARLESON_THETA_TERM_BOUNDS]]);;

(* ------------------------------------------------------------------------- *)
(* 2D (a,b)-measurability of the tile-sup theta' kernel at fixed w (inner    *)
(* affine Y=a*w+b).  Mirrors the 3D tower; feeds the 2D-box abs-int for the  *)
(* w-outer side of MNF_FOURIER_BOX.                                          *)
(* ------------------------------------------------------------------------- *)
let CARLESON_THETA_TERM2_MEASURABLE = prove
 (`!(A:real) (m:real) (w:real).
     (\p:real^2. lift(Re(fourier carleson_phi (A * ((p$1 * w + p$2) - m))) pow
       2)) measurable_on (:real^2)`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  REWRITE_TAC[o_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_POW THEN
  REWRITE_TAC[RE_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
  SUBGOAL_THEN
   `(\p:real^2. fourier carleson_phi (A * ((p$1 * w + p$2) - m))) =
    (\u:real^1. fourier carleson_phi (drop u)) o (\p:real^2. lift(A * ((p$1 * w
      + p$2) - m)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [REWRITE_TAC[LIFT_CMUL] THEN MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
    REWRITE_TAC[LIFT_SUB] THEN MATCH_MP_TAC CONTINUOUS_ON_SUB THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
    REWRITE_TAC[LIFT_ADD] THEN MATCH_MP_TAC CONTINUOUS_ON_ADD THEN
      CONJ_TAC THENL
     [SUBGOAL_THEN
       `(\p:real^2. lift(p$1 * w)) =
        (\p:real^2. w % lift(p$1))` SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
         REWRITE_TAC[GSYM LIFT_CMUL] THEN
        AP_TERM_TAC THEN REWRITE_TAC[REAL_MUL_SYM]; ALL_TAC] THEN
      MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
        REWRITE_TAC[CONTINUOUS_ON_ID];
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
        REWRITE_TAC[CONTINUOUS_ON_ID]];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN
      MATCH_MP_TAC SCHWARTZ_ABSINT THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
      REWRITE_TAC[SUBSET_UNIV]]]);;

(* preimage of dyho under a measurable g:R^2->R is lebesgue_measurable.      *)
let DYHO_PREIMAGE2_MEASURABLE = prove
 (`!(g:real^2->real) k n. (\p. lift(g p)) measurable_on (:real^2)
     ==> lebesgue_measurable {p:real^2 | g p IN dyho k n}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[dyho] THEN
  SUBGOAL_THEN
   `{p:real^2 | (g:real^2->real) p IN {x | real_of_int n * &2 zpow k <= x /\ x
     < (real_of_int n + &1) * &2 zpow k}} =
    {p | g p IN {x | real_of_int n * &2 zpow k <= x}} INTER
    {p | g p IN {x | x < (real_of_int n + &1) * &2 zpow k}}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
     MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`\p:real^2. lift((g:real^2->real) p)`;
                   `{x:real^1 | real_of_int n * &2 zpow k <= drop x}`]
                     LEBESGUE_MEASURABLE_PREIMAGE_CLOSED) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `{x:real^1 | real_of_int n * &2 zpow k <= drop x} = {x | x$1 >=
        real_of_int n * &2 zpow k}` SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM; real_ge; drop]; ALL_TAC] THEN
      REWRITE_TAC[CLOSED_HALFSPACE_COMPONENT_GE];
      MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
      REWRITE_TAC[EXTENSION; IN_ELIM_THM; LIFT_DROP]];
    MP_TAC(ISPECL [`\p:real^2. lift((g:real^2->real) p)`;
                   `{x:real^1 | drop x < (real_of_int n + &1) * &2 zpow k}`]
                     LEBESGUE_MEASURABLE_PREIMAGE_OPEN) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `{x:real^1 | drop x < (real_of_int n + &1) * &2 zpow k} = {x | x$1 <
        (real_of_int n + &1) * &2 zpow k}` SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM; drop]; ALL_TAC] THEN
      REWRITE_TAC[OPEN_HALFSPACE_COMPONENT_LT];
      MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
      REWRITE_TAC[EXTENSION; IN_ELIM_THM; LIFT_DROP]]]);;

(* 2D coordinate maps: Y = a*w+b = p$1*w+p$2 (w fixed), Z = a*z+b =          *)
(* p$1*z+p$2.                                                                *)
let YMAP2_MEASURABLE = prove
 (`!w:real. (\p:real^2. lift(p$1 * w + p$2)) measurable_on (:real^2)`,
  GEN_TAC THEN MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  REWRITE_TAC[LIFT_ADD] THEN MATCH_MP_TAC CONTINUOUS_ON_ADD THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\p:real^2. lift(p$1 * w)) = (\p:real^2. w % lift(p$1))` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
       REWRITE_TAC[GSYM LIFT_CMUL] THEN
      AP_TERM_TAC THEN REWRITE_TAC[REAL_MUL_SYM];
      MATCH_MP_TAC CONTINUOUS_ON_CMUL THEN
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
        REWRITE_TAC[CONTINUOUS_ON_ID]];
    MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_ID]]);;

let ZMAP2_MEASURABLE = prove
 (`!z:real. (\p:real^2. lift(p$1 * z + p$2)) measurable_on (:real^2)`,
  REWRITE_TAC[YMAP2_MEASURABLE]);;

(* each 2D tile-family member is measurable (n=0 sentinel 0; n>0 term        *)
(* restricted to the tile region {Z in Jr} INTER {Y in Jl}).                 *)
let CARLESON_THETA_FAMILY2_MEASURABLE = prove
 (`!(e:num->int#int#int) (z:real) (w:real) (n:num).
     (\p:real^2. lift(if n = 0 then &0
          else if (p$1 * z + p$2) IN tile_Jr(e(n-1)) /\ (p$1 * w + p$2) IN
            tile_Jl(e(n-1))
               then Re(fourier carleson_phi (&2 zpow(--tile_k(e(n-1))) * ((p$1
                 * w + p$2) - tile_ymid(e(n-1))))) pow 2
               else &0)) measurable_on (:real^2)`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `n = 0` THEN
  ASM_REWRITE_TAC[LIFT_NUM; MEASURABLE_ON_0] THEN
  ABBREV_TAC `s = (e:num->int#int#int)(n-1)` THEN
  SUBGOAL_THEN
   `(\p:real^2. lift(if (p$1 * z + p$2) IN tile_Jr s /\ (p$1 * w + p$2) IN
     tile_Jl s
               then Re(fourier carleson_phi (&2 zpow(--tile_k s) * ((p$1 * w +
                 p$2) - tile_ymid s))) pow 2
               else &0)) =
    (\p:real^2. if p IN ({p | (p$1 * z + p$2) IN tile_Jr s} INTER {p | (p$1 * w
      + p$2) IN tile_Jl s})
                then lift(Re(fourier carleson_phi (&2 zpow(--tile_k s) * ((p$1
                  * w + p$2) - tile_ymid s))) pow 2)
                else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[IN_INTER; IN_ELIM_THM] THEN
    COND_CASES_TAC THEN REWRITE_TAC[LIFT_NUM];
    ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
   [REWRITE_TAC[CARLESON_THETA_TERM2_MEASURABLE];
    MP_TAC(ISPEC `s:int#int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `k0:int` (X_CHOOSE_THEN
      `rest:int#int` ASSUME_TAC)) THEN
    MP_TAC(ISPEC `rest:int#int` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `nI0:int` (X_CHOOSE_THEN
      `nJ0:int` ASSUME_TAC)) THEN
    SUBGOAL_THEN `s = (k0:int,nI0:int,nJ0:int)` SUBST_ALL_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[tile_Jr; tile_Jl] THEN
    MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
     [MATCH_MP_TAC DYHO_PREIMAGE2_MEASURABLE THEN
       REWRITE_TAC[ZMAP2_MEASURABLE];
      MATCH_MP_TAC DYHO_PREIMAGE2_MEASURABLE THEN
        REWRITE_TAC[YMAP2_MEASURABLE]]]);;

(* CAPSTONE: theta'_z(a,b,w0) is measurable in (a,b) on R^2 (w0 fixed).      *)
let CARLESON_THETA'_2D_MEASURABLE = prove
 (`!z0:real w:real. (\p:real^2. lift(carleson_theta' z0 (p$1) (p$2) w))
   measurable_on (:real^2)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_theta'] THEN
  SUBGOAL_THEN
    `?e:num->(int#int#int). (:int#int#int) =
     IMAGE e (:num)` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC COUNTABLE_AS_IMAGE THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM CROSS_UNIV] THEN MATCH_MP_TAC COUNTABLE_CROSS THEN
      REWRITE_TAC[INT_COUNTABLE; GSYM CROSS_UNIV] THEN
        MATCH_MP_TAC COUNTABLE_CROSS THEN
      REWRITE_TAC[INT_COUNTABLE];
      REWRITE_TAC[UNIV_NOT_EMPTY]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\p:real^2. lift(carleson_theta (p$1 * z0 + p$2) (p$1 * w + p$2))) =
    (\p:real^2. lift(sup {(if nn = 0 then &0
                else if (p$1 * z0 + p$2) IN tile_Jr (e(nn-1)) /\ (p$1 * w +
                  p$2) IN tile_Jl (e(nn-1))
                     then Re(fourier carleson_phi (&2 zpow(--tile_k(e(nn-1))) *
                       ((p$1 * w + p$2) - tile_ymid(e(nn-1))))) pow 2
                     else &0) | nn IN (:num)}))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    MATCH_MP_TAC CARLESON_THETA_SUP_RECONCILE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC
   `\nn p:real^2. (if nn = 0 then &0
                else if (p$1 * z0 + p$2) IN tile_Jr (e(nn-1)) /\ (p$1 * w +
                  p$2) IN tile_Jl (e(nn-1))
                     then Re(fourier carleson_phi (&2 zpow(--tile_k(e(nn-1))) *
                       ((p$1 * w + p$2) - tile_ymid(e(nn-1))))) pow 2
                     else &0)` MEASURABLE_ON_SUP_MULTI) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[CARLESON_THETA_FAMILY2_MEASURABLE];
    GEN_TAC THEN EXISTS_TAC `&1` THEN GEN_TAC THEN
    COND_CASES_TAC THEN REWRITE_TAC[REAL_LE_01] THEN
    COND_CASES_TAC THEN REWRITE_TAC[REAL_LE_01] THEN
    REWRITE_TAC[CARLESON_THETA_TERM_BOUNDS]]);;

(* 2D Cx(inv a) measurable (a=p$1; a=0 hyperplane negligible).               *)
let CX_INVA2_MEASURABLE = prove
 (`(\p:real^2. Cx(inv(p$1))) measurable_on (:real^2)`,
  SUBGOAL_THEN
   `(\p:real^2. Cx(inv(p$1))) = (\v:real^1. Cx(drop v)) o (\p:real^2.
     lift(inv(p$1)))`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_COMPOSE_CONTINUOUS THEN
  REWRITE_TAC[CONTINUOUS_ON_CX_LIFT; LIFT_DROP; CONTINUOUS_ON_ID] THEN
  MATCH_MP_TAC MEASURABLE_ON_LIFT_INV THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_ID];
    REWRITE_TAC[IN_UNIV; NEGLIGIBLE_STANDARD_HYPERPLANE]]);;

(* Cx(theta'_zab w) measurable in (a,b) [compose lift-2D capstone with Cx o  *)
(* drop].                                                                    *)
let CX_THETA2_MEASURABLE = prove
 (`!z0:real w:real. (\p:real^2. Cx(carleson_theta' z0 (p$1) (p$2) w))
   measurable_on (:real^2)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\p:real^2. Cx(carleson_theta' z0 (p$1) (p$2) w)) =
    (\v:real^1. Cx(drop v)) o (\p:real^2. lift(carleson_theta' z0 (p$1) (p$2)
      w))`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_COMPOSE_CONTINUOUS THEN
  REWRITE_TAC[CARLESON_THETA'_2D_MEASURABLE; CONTINUOUS_ON_CX_LIFT; LIFT_DROP;
    CONTINUOUS_ON_ID]);;

(* box2d region on R^2 is lebesgue_measurable (=                             *)
(* interval[vector[1;0],vector[2;n]]).                                       *)
let TBOX_SHUFFLE_LINEAR = prove
 (`linear (\z:real^((1,1)finite_sum,1)finite_sum.
             vector[drop(fstcart(fstcart z)); drop(sndcart(fstcart z));
               drop(sndcart z)]:real^3) /\
   (!u v:real^((1,1)finite_sum,1)finite_sum.
      (\z. vector[drop(fstcart(fstcart z)); drop(sndcart(fstcart z));
        drop(sndcart z)]:real^3) u =
      (\z. vector[drop(fstcart(fstcart z)); drop(sndcart(fstcart z));
        drop(sndcart z)]:real^3) v ==> u = v)`,
  CONJ_TAC THENL
   [REWRITE_TAC[linear] THEN CONJ_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3] THEN
    SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VECTOR_3; DIMINDEX_3;
      ARITH] THEN
    REWRITE_TAC[FSTCART_ADD; SNDCART_ADD; FSTCART_CMUL; SNDCART_CMUL;
                DROP_ADD; DROP_CMUL] THEN REWRITE_TAC[VECTOR_3] THEN
                  REAL_ARITH_TAC;
    REPEAT GEN_TAC THEN REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `drop(fstcart(fstcart(u:real^((1,1)finite_sum,1)finite_sum))) =
       drop(fstcart(fstcart v)) /\
      drop(sndcart(fstcart u)) = drop(sndcart(fstcart v)) /\
      drop(sndcart u) = drop(sndcart v)`
     STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC) THEN
       REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3] THEN
      SIMP_TAC[]; ALL_TAC] THEN
    ONCE_REWRITE_TAC[PASTECART_EQ] THEN CONJ_TAC THENL
     [ONCE_REWRITE_TAC[PASTECART_EQ] THEN CONJ_TAC THEN
      ONCE_REWRITE_TAC[GSYM DROP_EQ] THEN ASM_REWRITE_TAC[];
      ONCE_REWRITE_TAC[GSYM DROP_EQ] THEN ASM_REWRITE_TAC[]]]);;

let TBOX_SHUFFLE_IMAGE = prove
 (`IMAGE (\z:real^((1,1)finite_sum,1)finite_sum.
             vector[drop(fstcart(fstcart z)); drop(sndcart(fstcart z));
               drop(sndcart z)]:real^3) (:real^((1,1)finite_sum,1)finite_sum) =
                (:real^3)`,
  MATCH_MP_TAC SURJECTIVE_IMAGE_EQ THEN REWRITE_TAC[IN_UNIV] THEN
  X_GEN_TAC `p:real^3` THEN
  EXISTS_TAC `pastecart (pastecart (lift((p:real^3)$1)) (lift(p$2)))
    (lift(p$3)):real^((1,1)finite_sum,1)finite_sum` THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART; LIFT_DROP] THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3] THEN
  CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[]);;

let TBOX_SHUFFLE = prove
 (`!hh:real^3->real^1.
     (hh o (\z:real^((1,1)finite_sum,1)finite_sum.
              vector[drop(fstcart(fstcart z)); drop(sndcart(fstcart z));
                drop(sndcart z)]:real^3))
       measurable_on (:real^((1,1)finite_sum,1)finite_sum)
     <=> hh measurable_on (:real^3)`,
  GEN_TAC THEN
  MP_TAC(ISPECL
   [`\z:real^((1,1)finite_sum,1)finite_sum.
        vector[drop(fstcart(fstcart z)); drop(sndcart(fstcart z));
          drop(sndcart z)]:real^3`;
    `hh:real^3->real^1`;
      `(:real^((1,1)finite_sum,1)finite_sum)`]
      MEASURABLE_ON_LINEAR_IMAGE_EQ_GEN) THEN
  REWRITE_TAC[TBOX_SHUFFLE_LINEAR; DIMINDEX_FINITE_SUM; DIMINDEX_1; DIMINDEX_3;
    ARITH] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[TBOX_SHUFFLE_IMAGE]);;

(* theta' kernel measurable on the iterated box type (via the capstone +     *)
(* the shuffle transfer). a=fstcart(fstcart z), b=sndcart(fstcart z),        *)
(* w=sndcart z.                                                              *)
let CARLESON_THETA'_TBOX_MEASURABLE = prove
 (`!z0:real. (\z:real^((1,1)finite_sum,1)finite_sum.
       lift(carleson_theta' z0 (drop(fstcart(fstcart z))) (drop(sndcart(fstcart
         z))) (drop(sndcart z))))
     measurable_on (:real^((1,1)finite_sum,1)finite_sum)`,
  GEN_TAC THEN
  MP_TAC(ISPEC `\p:real^3. lift(carleson_theta' z0 (p$1) (p$2) (p$3))`
    TBOX_SHUFFLE) THEN
  REWRITE_TAC[CARLESON_THETA'_3D_MEASURABLE] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM; o_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[VECTOR_3]);;

(* Cx(theta') measurable on the iterated box type (compose lift-theta'       *)
(* kernel with the continuous Cx o drop).                                    *)
let CARLESON_THETA'_TBOX_CX = prove
 (`!z0:real. (\z:real^((1,1)finite_sum,1)finite_sum.
       Cx(carleson_theta' z0 (drop(fstcart(fstcart z))) (drop(sndcart(fstcart
         z))) (drop(sndcart z))))
     measurable_on (:real^((1,1)finite_sum,1)finite_sum)`,
  GEN_TAC THEN
  SUBGOAL_THEN
   `(\z:real^((1,1)finite_sum,1)finite_sum.
       Cx(carleson_theta' z0 (drop(fstcart(fstcart z))) (drop(sndcart(fstcart
         z))) (drop(sndcart z)))) =
    (\v:real^1. Cx(drop v)) o (\z:real^((1,1)finite_sum,1)finite_sum.
       lift(carleson_theta' z0 (drop(fstcart(fstcart z))) (drop(sndcart(fstcart
         z))) (drop(sndcart z))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_COMPOSE_CONTINUOUS THEN
  REWRITE_TAC[CARLESON_THETA'_TBOX_MEASURABLE] THEN
  REWRITE_TAC[CONTINUOUS_ON_CX_LIFT; LIFT_DROP; CONTINUOUS_ON_ID]);;

(* w-projection Cx(drop(sndcart z)) continuous on the iterated box type.     *)
let WPROJ_CX_CONT = prove
 (`(\z:real^((1,1)finite_sum,1)finite_sum. Cx(drop(sndcart z))) continuous_on
   (:real^((1,1)finite_sum,1)finite_sum)`,
  REWRITE_TAC[CONTINUOUS_ON_CX_LIFT; LIFT_DROP] THEN
  MATCH_MP_TAC LINEAR_CONTINUOUS_ON THEN REWRITE_TAC[ETA_AX; LINEAR_SNDCART]);;

(* the modulated transform factor cexp(-i(-x)w)*fhat(w), w=drop(sndcart z),  *)
(* measurable on the iterated box type (continuous: cexp o linear, fhat o    *)
(* proj).                                                                    *)
let CEXPFHAT_W_MEASURABLE = prove
 (`!(h:real->complex) x. schwartz h
   ==> (\z:real^((1,1)finite_sum,1)finite_sum.
          cexp(--(ii * Cx(--x) * Cx(drop(sndcart z)))) * fourier h
            (drop(sndcart z)))
       measurable_on (:real^((1,1)finite_sum,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\z:real^((1,1)finite_sum,1)finite_sum. cexp(--(ii * Cx(--x) *
       Cx(drop(sndcart z))))) =
      cexp o (\z:real^((1,1)finite_sum,1)finite_sum. --(ii * Cx(--x) *
        Cx(drop(sndcart z))))`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_CEXP] THEN
    MATCH_MP_TAC CONTINUOUS_ON_NEG THEN
    ONCE_REWRITE_TAC[COMPLEX_RING `ii * Cx(--x) * w = (ii * Cx(--x)) * w`] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_LMUL THEN REWRITE_TAC[WPROJ_CX_CONT];
    SUBGOAL_THEN
     `(\z:real^((1,1)finite_sum,1)finite_sum. fourier h (drop(sndcart z))) =
      (\v:real^1. fourier h (drop v)) o (\z:real^((1,1)finite_sum,1)finite_sum.
        sndcart z)`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
     [REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC LINEAR_CONTINUOUS_ON THEN
       REWRITE_TAC[LINEAR_SNDCART];
      MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
      REWRITE_TAC[SUBSET_UNIV] THEN
      MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN MATCH_MP_TAC SCHWARTZ_ABSINT THEN
      ASM_REWRITE_TAC[]]]);;

(* the (a,b)-box region {1<=a<=2, 0<=b<=n} on the iterated box type is       *)
(* lebesgue_measurable (= (box2d) PCROSS (:real^1) for the w-factor).        *)
let TBOX_REGION_LMEAS = prove
 (`!n. lebesgue_measurable
     {z:real^((1,1)finite_sum,1)finite_sum |
        &1 <= drop(fstcart(fstcart z)) /\ drop(fstcart(fstcart z)) <= &2 /\
        &0 <= drop(sndcart(fstcart z)) /\ drop(sndcart(fstcart z)) <= &n}`,
  GEN_TAC THEN
  SUBGOAL_THEN
   `{z:real^((1,1)finite_sum,1)finite_sum |
        &1 <= drop(fstcart(fstcart z)) /\ drop(fstcart(fstcart z)) <= &2 /\
        &0 <= drop(sndcart(fstcart z)) /\ drop(sndcart(fstcart z)) <= &n} =
    ((interval[lift(&1),lift(&2)]) PCROSS (interval[lift(&0),lift(&n)])) PCROSS
      (:real^1)`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; FORALL_PASTECART; PASTECART_IN_PCROSS; IN_ELIM_THM;
                FSTCART_PASTECART; SNDCART_PASTECART; IN_INTERVAL_1; IN_UNIV;
                  LIFT_DROP] THEN
    REWRITE_TAC[CONJ_ACI];
    ALL_TAC] THEN
  REWRITE_TAC[LEBESGUE_MEASURABLE_PCROSS; LEBESGUE_MEASURABLE_UNIV;
    LEBESGUE_MEASURABLE_INTERVAL]);;

(* a = drop(fstcart(fstcart z)) is the z$1 coordinate (for the a=0           *)
(* hyperplane).                                                              *)
let TBOX_A_EQ_C1 = prove
 (`!z:real^((1,1)finite_sum,1)finite_sum. drop(fstcart(fstcart z)) = z$1`,
  GEN_TAC THEN REWRITE_TAC[drop] THEN
  SUBGOAL_THEN
    `fstcart(fstcart(z:real^((1,1)finite_sum,1)finite_sum))$1 = fstcart z$1`
    SUBST1_TAC THENL
   [MATCH_MP_TAC FSTCART_COMPONENT THEN
     REWRITE_TAC[DIMINDEX_1; LE_REFL]; ALL_TAC] THEN
  MATCH_MP_TAC FSTCART_COMPONENT THEN
  REWRITE_TAC[DIMINDEX_FINITE_SUM; DIMINDEX_1; ARITH]);;

(* Cx(inv a), a=drop(fstcart(fstcart z)), measurable on the iterated box     *)
(* type (a=0 hyperplane negligible via TBOX_A_EQ_C1 +                        *)
(* NEGLIGIBLE_STANDARD_HYPERPLANE).                                          *)
let TBOX_INVA_CX_MEASURABLE = prove
 (`(\z:real^((1,1)finite_sum,1)finite_sum. Cx(inv(drop(fstcart(fstcart z)))))
   measurable_on (:real^((1,1)finite_sum,1)finite_sum)`,
  SUBGOAL_THEN
   `(\z:real^((1,1)finite_sum,1)finite_sum. Cx(inv(drop(fstcart(fstcart z)))))
     =
    (\v:real^1. Cx(drop v)) o (\z:real^((1,1)finite_sum,1)finite_sum.
      lift(inv(drop(fstcart(fstcart z)))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_COMPOSE_CONTINUOUS THEN CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_LIFT_INV THEN CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
      SUBGOAL_THEN
       `(\z:real^((1,1)finite_sum,1)finite_sum. lift(drop(fstcart(fstcart z))))
         =
        (fstcart:real^(1,1)finite_sum->real^1) o
          (fstcart:real^((1,1)finite_sum,1)finite_sum->real^(1,1)finite_sum)`
       SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
      MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THEN
      MATCH_MP_TAC LINEAR_CONTINUOUS_ON THEN
        REWRITE_TAC[ETA_AX; LINEAR_FSTCART];
      REWRITE_TAC[IN_UNIV; TBOX_A_EQ_C1; NEGLIGIBLE_STANDARD_HYPERPLANE]];
    REWRITE_TAC[CONTINUOUS_ON_CX_LIFT; LIFT_DROP; CONTINUOUS_ON_ID]]);;

(* FULL box-restricted transform kernel measurable on the iterated Fubini    *)
(* type: Cx(inv a)*(cexp(-i(-x)w)*fhat(w))*Cx(theta'_zab w) restricted to    *)
(* the (a,b)-box. MEASURABLE_ON_RESTRICT (TBOX_REGION_LMEAS) +               *)
(* MEASURABLE_ON_COMPLEX_MUL x2 over the 3 factors (TBOX_INVA_CX /           *)
(* CEXPFHAT_W / CARLESON_THETA'_TBOX_CX).                                    *)
let MNF_KERNEL_BOX_MEAS = prove
 (`!(h:real->complex) z0 x n. schwartz h
   ==> (\z:real^((1,1)finite_sum,1)finite_sum.
          if &1 <= drop(fstcart(fstcart z)) /\ drop(fstcart(fstcart z)) <= &2
            /\
             &0 <= drop(sndcart(fstcart z)) /\ drop(sndcart(fstcart z)) <= &n
          then Cx(inv(drop(fstcart(fstcart z)))) *
               (cexp(--(ii * Cx(--x) * Cx(drop(sndcart z)))) * fourier h
                 (drop(sndcart z))) *
               Cx(carleson_theta' z0 (drop(fstcart(fstcart z)))
                 (drop(sndcart(fstcart z))) (drop(sndcart z)))
          else vec 0)
       measurable_on (:real^((1,1)finite_sum,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^((1,1)finite_sum,1)finite_sum.
       if &1 <= drop(fstcart(fstcart z)) /\ drop(fstcart(fstcart z)) <= &2 /\
          &0 <= drop(sndcart(fstcart z)) /\ drop(sndcart(fstcart z)) <= &n
       then Cx(inv(drop(fstcart(fstcart z)))) *
            (cexp(--(ii * Cx(--x) * Cx(drop(sndcart z)))) * fourier h
              (drop(sndcart z))) *
            Cx(carleson_theta' z0 (drop(fstcart(fstcart z)))
              (drop(sndcart(fstcart z))) (drop(sndcart z)))
       else vec 0) =
    (\z:real^((1,1)finite_sum,1)finite_sum.
       if z IN {z | &1 <= drop(fstcart(fstcart z)) /\ drop(fstcart(fstcart z))
         <= &2 /\
                    &0 <= drop(sndcart(fstcart z)) /\ drop(sndcart(fstcart z))
                      <= &n}
       then Cx(inv(drop(fstcart(fstcart z)))) *
            (cexp(--(ii * Cx(--x) * Cx(drop(sndcart z)))) * fourier h
              (drop(sndcart z))) *
            Cx(carleson_theta' z0 (drop(fstcart(fstcart z)))
              (drop(sndcart(fstcart z))) (drop(sndcart z)))
       else vec 0)`
   SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN
     REWRITE_TAC[TBOX_INVA_CX_MEASURABLE] THEN
    MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC CEXPFHAT_W_MEASURABLE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[CARLESON_THETA'_TBOX_CX]];
    REWRITE_TAC[TBOX_REGION_LMEAS]]);;

(* abstract: |cexp(-i a b)| = 1 (purely imaginary exponent; Re = 0 by        *)
(* REAL_ARITH on the complex_mul expansion -- robust, no fragile literal     *)
(* arithmetic form).                                                         *)
let CEXP_IMAG_NORM1 = prove
 (`!a b:real. norm(cexp(--(ii * Cx a * Cx b))) = &1`,
  REPEAT GEN_TAC THEN REWRITE_TAC[NORM_CEXP; RE_NEG] THEN
  SUBGOAL_THEN `Re(ii * Cx a * Cx b) = &0` SUBST1_TAC THENL
   [REWRITE_TAC[COMPLEX_MUL_ASSOC; GSYM CX_MUL] THEN
    REWRITE_TAC[ii; complex_mul; RE; IM; RE_CX; IM_CX] THEN REAL_ARITH_TAC;
    REWRITE_TAC[REAL_NEG_0; REAL_EXP_0]]);;

(* pointwise: norm of the box-restricted kernel <= norm(fhat(w))*1[box].     *)
(* |Cx(inv a)|<=1 (a in [1,2]), |cexp|=1, |Cx theta'|<=1                     *)
(* (CARLESON_THETA'_BOUNDS).                                                 *)
let MNF_KERNEL_NORM_BOUND = prove
 (`!(h:real->complex) z0 x n z:real^((1,1)finite_sum,1)finite_sum.
     norm((if &1 <= drop(fstcart(fstcart z)) /\ drop(fstcart(fstcart z)) <= &2
       /\
             &0 <= drop(sndcart(fstcart z)) /\ drop(sndcart(fstcart z)) <= &n
          then Cx(inv(drop(fstcart(fstcart z)))) *
               (cexp(--(ii * Cx(--x) * Cx(drop(sndcart z)))) * fourier h
                 (drop(sndcart z))) *
               Cx(carleson_theta' z0 (drop(fstcart(fstcart z)))
                 (drop(sndcart(fstcart z))) (drop(sndcart z)))
          else vec 0))
     <= norm(if &1 <= drop(fstcart(fstcart z)) /\ drop(fstcart(fstcart z)) <=
       &2 /\
                &0 <= drop(sndcart(fstcart z)) /\ drop(sndcart(fstcart z)) <=
                  &n
             then fourier h (drop(sndcart z)) else vec 0)`,
  REPEAT GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[NORM_0; REAL_LE_REFL] THEN
  POP_ASSUM STRIP_ASSUME_TAC THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX; CEXP_IMAG_NORM1] THEN
  REWRITE_TAC[REAL_MUL_LID] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `&1 * norm(fourier (h:real->complex)
    (drop(sndcart(z:real^((1,1)finite_sum,1)finite_sum)))) * &1` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL2 THEN REPEAT CONJ_TAC THENL
     [REWRITE_TAC[REAL_ABS_POS];
      MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `abs(inv(&1))` THEN
        CONJ_TAC THENL
       [ALL_TAC; CONV_TAC REAL_RAT_REDUCE_CONV] THEN
      REWRITE_TAC[REAL_ABS_INV] THEN MATCH_MP_TAC REAL_LE_INV2 THEN
        ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[NORM_POS_LE; REAL_ABS_POS];
      MATCH_MP_TAC REAL_LE_MUL2 THEN
        REWRITE_TAC[NORM_POS_LE; REAL_LE_REFL; REAL_ABS_POS] THEN
      MP_TAC(ISPECL
       [`z0:real`;
        `drop(fstcart(fstcart(z:real^((1,1)finite_sum,1)finite_sum)))`;
        `drop(sndcart(fstcart(z:real^((1,1)finite_sum,1)finite_sum)))`;
        `drop(sndcart(z:real^((1,1)finite_sum,1)finite_sum))`]
       CARLESON_THETA'_BOUNDS) THEN
      REAL_ARITH_TAC];
    REWRITE_TAC[REAL_MUL_LID; REAL_MUL_RID; REAL_LE_REFL]]);;

(* ------------------------------------------------------------------------- *)
(* S6 keystone step (b): box ABSOLUTE INTEGRABILITY of the transform kernel. *)
(* Reusable tensor lemma + box2d-measurability + the dominated abs-int.      *)
(* ------------------------------------------------------------------------- *)

(* general: g absint on the R^N (=w) factor, times the indicator of a        *)
(* measurable s in the R^M (=(a,b)) factor, is absint on the product.  Via   *)
(* FUBINI_TONELLI: measurable (RESTRICT of g o sndcart to s PCROSS UNIV);    *)
(* every                                                                     *)
(* slice absint (g or 0); slice-norm-integral = int|g| * indicator s,        *)
(* integrable.                                                               *)
let TENSOR_INDICATOR_L1_ABSINT = prove
 (`!(g:real^1->real^1) (s:real^(1,1)finite_sum->bool).
     g absolutely_integrable_on (:real^1) /\ measurable s
     ==> (\z:real^((1,1)finite_sum,1)finite_sum.
            if fstcart z IN s then g(sndcart z) else vec 0)
         absolutely_integrable_on (:real^((1,1)finite_sum,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC
   `\z:real^((1,1)finite_sum,1)finite_sum. if fstcart z IN s then
     (g:real^1->real^1)(sndcart z) else vec 0`
   FUBINI_TONELLI) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  ANTS_TAC THENL
   [SUBGOAL_THEN
     `(\z:real^((1,1)finite_sum,1)finite_sum. if fstcart z IN s then
       (g:real^1->real^1)(sndcart z) else vec 0) =
      (\z:real^((1,1)finite_sum,1)finite_sum. if z IN (s PCROSS (:real^1)) then
        (g(sndcart z)) else vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      ONCE_REWRITE_TAC[GSYM PASTECART_FST_SND] THEN
      REWRITE_TAC[PASTECART_IN_PCROSS; FSTCART_PASTECART; SNDCART_PASTECART;
        IN_UNIV] THEN
      REWRITE_TAC[PASTECART_FST_SND];
      ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
     [MATCH_MP_TAC MEASURABLE_ON_COMPOSE_SNDCART THEN
      ASM_MESON_TAC[ABSOLUTELY_INTEGRABLE_MEASURABLE];
      REWRITE_TAC[LEBESGUE_MEASURABLE_PCROSS; LEBESGUE_MEASURABLE_UNIV] THEN
      ASM_SIMP_TAC[MEASURABLE_IMP_LEBESGUE_MEASURABLE]];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> GEN_REWRITE_TAC I [th]) THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `{x:real^(1,1)finite_sum | ~((\y. if x IN s then (g:real^1->real^1) y else
       vec 0) absolutely_integrable_on (:real^1))} = {}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
      X_GEN_TAC `x:real^(1,1)finite_sum` THEN
        ASM_CASES_TAC `x IN (s:real^(1,1)finite_sum->bool)` THEN
      ASM_REWRITE_TAC[ABSOLUTELY_INTEGRABLE_0; ETA_AX];
      REWRITE_TAC[NEGLIGIBLE_EMPTY]];
    SUBGOAL_THEN
     `(\x. integral (:real^1) (\y. lift(norm(if x IN s then (g:real^1->real^1)
       y else vec 0)))) =
      (\x:real^(1,1)finite_sum. drop(integral (:real^1) (\y. lift(norm(g y))))
        % indicator s x)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; indicator] THEN GEN_TAC THEN COND_CASES_TAC THEN
      ASM_REWRITE_TAC[NORM_0; LIFT_NUM; INTEGRAL_0; VECTOR_MUL_RZERO] THEN
      REWRITE_TAC[GSYM DROP_EQ; DROP_CMUL; DROP_VEC; REAL_MUL_RID];
      ALL_TAC] THEN
    MATCH_MP_TAC INTEGRABLE_CMUL THEN
    REWRITE_TAC[ETA_AX; INTEGRABLE_ON_INDICATOR; INTER_UNIV] THEN
      ASM_REWRITE_TAC[]]);;

(* the box2d region {1<=a<=2, 0<=b<=n} in R^(1,1)fs is MEASURABLE (an        *)
(* interval).                                                                *)
let TBOX2D_MEASURABLE = prove
 (`!n. measurable {ab:real^(1,1)finite_sum |
        &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
        &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n}`,
  GEN_TAC THEN
  SUBGOAL_THEN
   `{ab:real^(1,1)finite_sum |
        &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
        &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n} =
    (interval[lift(&1),lift(&2)]) PCROSS (interval[lift(&0),lift(&n)])`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; FORALL_PASTECART; PASTECART_IN_PCROSS; IN_ELIM_THM;
                FSTCART_PASTECART; SNDCART_PASTECART; IN_INTERVAL_1;
                  LIFT_DROP] THEN
    CONV_TAC TAUT;
    REWRITE_TAC[MEASURABLE_PCROSS] THEN REPEAT DISJ2_TAC THEN
    REWRITE_TAC[MEASURABLE_INTERVAL]]);;

(* the box-restricted transform kernel is ABSOLUTELY INTEGRABLE on the       *)
(* iterated                                                                  *)
(* type: dominated by norm(fhat(w))*1[box] (MNF_KERNEL_NORM_BOUND), the      *)
(* dominator                                                                 *)
(* integrable via TENSOR_INDICATOR_L1_ABSINT (SCHWARTZ_FHAT_ABSINT on w-line *)
(* x                                                                         *)
(* the finite box2d).  Feeds FUBINI_INTEGRAL_SWAP for MNF_FOURIER_BOX.       *)
let MNF_KERNEL_BOX_ABSINT = prove
 (`!(h:real->complex) z0 x n. schwartz h
   ==> (\z:real^((1,1)finite_sum,1)finite_sum.
          if &1 <= drop(fstcart(fstcart z)) /\ drop(fstcart(fstcart z)) <= &2
            /\
             &0 <= drop(sndcart(fstcart z)) /\ drop(sndcart(fstcart z)) <= &n
          then Cx(inv(drop(fstcart(fstcart z)))) *
               (cexp(--(ii * Cx(--x) * Cx(drop(sndcart z)))) * fourier h
                 (drop(sndcart z))) *
               Cx(carleson_theta' z0 (drop(fstcart(fstcart z)))
                 (drop(sndcart(fstcart z))) (drop(sndcart z)))
          else vec 0)
       absolutely_integrable_on (:real^((1,1)finite_sum,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC
   `\z:real^((1,1)finite_sum,1)finite_sum.
       if fstcart z IN {ab:real^(1,1)finite_sum |
                          &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                          &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n}
       then lift(norm(fourier h (drop(sndcart z)))) else vec 0` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MNF_KERNEL_BOX_MEAS THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC TENSOR_INDICATOR_L1_ABSINT THEN CONJ_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
        ASM_REWRITE_TAC[];
      REWRITE_TAC[TBOX2D_MEASURABLE]];
    X_GEN_TAC `z:real^((1,1)finite_sum,1)finite_sum` THEN
      REWRITE_TAC[IN_UNIV] THEN
    MP_TAC(ISPECL [`h:real->complex`; `z0:real`; `x:real`; `n:num`;
      `z:real^((1,1)finite_sum,1)finite_sum`]
      MNF_KERNEL_NORM_BOUND) THEN
    REWRITE_TAC[IN_ELIM_THM; FSTCART_PASTECART; SNDCART_PASTECART] THEN
    MATCH_MP_TAC(REAL_ARITH `b = c ==> a <= b ==> a <= c`) THEN
    COND_CASES_TAC THEN
      REWRITE_TAC[NORM_0; LIFT_DROP; NORM_LIFT; DROP_VEC] THEN
    REWRITE_TAC[REAL_ABS_NORM]]);;

(* modulation by a plane wave cexp(ii t w) preserves absolute integrability  *)
(* (bounded                                                                  *)
(* measurable multiplier).  The L1-integrability input for the window DCT.   *)
let CEXP_MODULATE_ABSINT_GEN = prove
 (`!(g:real^1->complex) t. g absolutely_integrable_on (:real^1)
     ==> (\w:real^1. cexp(ii * Cx t * Cx(drop w)) * g w)
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`( * ):complex->complex->complex`;
                 `\w:real^1. cexp(ii * Cx t * Cx(drop w))`;
                   `g:real^1->complex`; `(:real^1)`]
    ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT) THEN
  ASM_REWRITE_TAC[BILINEAR_COMPLEX_MUL] THEN DISCH_THEN MATCH_MP_TAC THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    SUBGOAL_THEN `(\w:real^1. cexp(ii * Cx t * Cx(drop w))) =
                  cexp o (\w:real^1. (ii * Cx t) * Cx(drop w))` SUBST1_TAC
                    THENL
     [REWRITE_TAC[o_DEF; COMPLEX_MUL_ASSOC]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_CEXP] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_LMUL THEN
    MP_TAC(ISPECL [`\w:real^1. w`; `(:real^1)`] CONTINUOUS_ON_CX_DROP) THEN
    REWRITE_TAC[CONTINUOUS_ON_ID] THEN REWRITE_TAC[ETA_AX];
    REWRITE_TAC[bounded; FORALL_IN_IMAGE] THEN EXISTS_TAC `&1` THEN
    REWRITE_TAC[IN_UNIV; GSYM CX_MUL; NORM_CEXP_II; REAL_LE_REFL]]);;


(* WINDOW_INTEGRAL_LIM: the DCT integral-limit core. As (a,b,x) ->           *)
(* (a0,b0,x0), the                                                           *)
(* Fourier integral int cexp(ii x w) hhat(w) theta'_{z a b}(w) dw converges, *)
(* jointly.                                                                  *)
(* DOMINATED_CONVERGENCE_AE with envelope norm(fourier h), null set the      *)
(* dyadic+gate bad-w.                                                        *)
let NORM_SEQ_REALLIM = prove
 (`!(f:num->complex) l. (f --> l) sequentially ==> ((\m. norm(f m)) ---> norm
   l) sequentially`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[TENDSTO_REAL; o_DEF] THEN
  MATCH_MP_TAC LIM_NORM THEN ASM_REWRITE_TAC[]);;

(* fourier ff at frequency -x, exposing the +ii sign, keeping ff abstract    *)
(* (FOURIER_INV_NEG from fourier_transform.ml, with the constant folded).    *)
let FOURIER_AT_NEG = prove
 (`!(ff:real->complex) x. fourier ff (--x) =
     Cx(&1 / sqrt(&2 * pi)) * integral (:real^1) (\w. cexp(ii * Cx x * Cx(drop
       w)) * ff(drop w))`,
  REWRITE_TAC[CX_DIV; FOURIER_INV_NEG]);;

(* WINDOW_JOINT_CONT: the amd z-window                                       *)
(* 2pi*norm(fourier(hhat*theta_{zab})check(x)) is jointly                    *)
(* continuous in (a,b,x) (sequential form). From WINDOW_INTEGRAL_LIM via     *)
(* FOURIER_AT_NEG +                                                          *)
(* norm-continuity (NORM_SEQ_REALLIM) + the constant factor (REALLIM_LMUL).  *)
let FHAT_QUAD_ENVELOPE = prove
 (`!(h:real->complex). schwartz h
     ==> ?gamma. &0 <= gamma /\ !t. norm(fourier h t) <= gamma * inv(&1 + t pow
       2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FOURIER) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[schwartz] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num->real->complex` STRIP_ASSUME_TAC) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B0:real` o SPECL [`0`; `0`]) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `B2:real` o SPECL [`2`; `0`]) THEN
  EXISTS_TAC `abs B0 + abs B2` THEN
  CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `t:real` THEN
  SUBGOAL_THEN `fourier h t = (d:num->real->complex) 0 t` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(abs B0 + abs B2) * inv(&1 + t pow 2)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_DECAY_DOMINATION THEN CONJ_TAC THEN
     X_GEN_TAC `x:real` THENL
     [MP_TAC(SPEC `x:real` (ASSUME `!x. abs(x) pow 0 *
       norm((d:num->real->complex) 0 x) <= B0`)) THEN
      REAL_ARITH_TAC;
      MP_TAC(SPEC `x:real` (ASSUME `!x. abs(x) pow 2 *
        norm((d:num->real->complex) 0 x) <= B2`)) THEN
      REAL_ARITH_TAC];
    REWRITE_TAC[REAL_LE_REFL]]);;

(* Schwartz-specialized MODDIL closed form: (M_b D_a h)hat(w) = (1/a)        *)
(* hhat((w-b)/a).                                                            *)
let CARLESON_MODDIL_FHAT = prove
 (`!(h:real->complex) a b w. schwartz h /\ &0 < a
   ==> fourier (carleson_modulate b (carleson_dilate a h)) w = Cx(&1/a) *
     fourier h ((w - b)/a)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`h:real->complex`; `a:real`; `b:real`;
    `w:real`] CARLESON_MODDIL_FOURIER) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`h:real->complex`; `a:real`; `b:real`;
        `w:real`] CARLESON_MOD_TRANSFORM_INTEG) THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* fourier h continuous in its argument along a sequence (schwartz h).       *)
let FOURIER_ARG_SEQ_LIM = prove
 (`!(h:real->complex) tseq t0. schwartz h /\ (tseq ---> t0) sequentially
     ==> ((\m. fourier h (tseq m)) --> fourier h t0) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `t0:real`] FOURIER_CONTINUOUS_SEQ) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [GEN_TAC THEN MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MP_TAC(ISPECL [`h:real->complex`;
        `y':real`] FOURIER_MODULATION_ABSINT) THEN
      DISCH_THEN MATCH_MP_TAC THEN
      MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(MP_TAC o SPEC `tseq:num->real`) THEN ASM_REWRITE_TAC[]]);;

(* (a,b) |-> fourier(M_b D_a h)(y) continuous (pointwise y): via closed form *)
(* + FT arg-cont.                                                            *)
let MODDIL_FHAT_SEQ_LIM = prove
 (`!(h:real->complex) aseq bseq a0 b0 y.
     schwartz h /\ &0 < a0 /\ (!m. &0 < aseq m) /\
     (aseq ---> a0) sequentially /\ (bseq ---> b0) sequentially
     ==> ((\m. fourier (carleson_modulate (bseq m) (carleson_dilate (aseq m)
       h)) y)
          --> fourier (carleson_modulate b0 (carleson_dilate a0 h)) y)
            sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\m:num. fourier (carleson_modulate (bseq m) (carleson_dilate (aseq m) h))
     y) =
    (\m:num. Cx(&1/aseq m) * fourier h ((y - bseq m)/aseq m))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `m:num` THEN
    MATCH_MP_TAC CARLESON_MODDIL_FHAT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `fourier (carleson_modulate b0 (carleson_dilate a0 h)) y = Cx(&1/a0) *
     fourier h ((y - b0)/a0)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC CARLESON_MODDIL_FHAT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC LIM_COMPLEX_MUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC CX_SEQ_LIM THEN
    REWRITE_TAC[real_div; REAL_MUL_LID] THEN
    MATCH_MP_TAC REALLIM_INV THEN ASM_SIMP_TAC[REAL_LT_IMP_NZ];
    MATCH_MP_TAC FOURIER_ARG_SEQ_LIM THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REALLIM_DIV THEN ASM_SIMP_TAC[REAL_LT_IMP_NZ] THEN
    MATCH_MP_TAC REALLIM_SUB THEN ASM_REWRITE_TAC[REALLIM_CONST]]);;

(* FREMLIN integrand-limit (M_bD_a form, theta_zeta FIXED weight): pointwise *)
(* EVERY y.                                                                  *)
let FREMLIN_INTEGRAND_LIM = prove
 (`!(h:real->complex) zeta aseq bseq xseq a0 b0 x0 y.
     schwartz h /\ &0 < a0 /\ (!m. &0 < aseq m) /\
     (aseq ---> a0) sequentially /\ (bseq ---> b0) sequentially /\ (xseq --->
       x0) sequentially
     ==> ((\m. cexp(ii * Cx(xseq m / aseq m) * Cx y) *
               fourier (carleson_modulate (bseq m) (carleson_dilate (aseq m)
                 h)) y *
               Cx(carleson_theta zeta y))
          --> cexp(ii * Cx(x0 / a0) * Cx y) *
               fourier (carleson_modulate b0 (carleson_dilate a0 h)) y *
               Cx(carleson_theta zeta y)) sequentially`,
  REPEAT STRIP_TAC THEN
  ONCE_REWRITE_TAC[COMPLEX_RING `a * b * c = (a * b) * c:complex`] THEN
  MATCH_MP_TAC LIM_COMPLEX_MUL THEN REWRITE_TAC[LIM_CONST] THEN
  MATCH_MP_TAC LIM_COMPLEX_MUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC CEXP_SEQ_LIM THEN
    MATCH_MP_TAC REALLIM_DIV THEN ASM_SIMP_TAC[REAL_LT_IMP_NZ];
    MATCH_MP_TAC MODDIL_FHAT_SEQ_LIM THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286S(a) DCT DOMINATOR pieces. The integrand modulus <=                    *)
(* (1/a)|hhat((y-b)/a)|                                                      *)
(* (MODULUS_LE_INVA_FHAT), and along a convergent sequence                   *)
(* (a_m,b_m)->(a0,b0) the                                                    *)
(* a_m/b_m are GLOBALLY bounded (AMD_SEQ_GLOBAL_BOUNDS: alo<=a_m<=ahi,       *)
(* alo>0,                                                                    *)
(* |b_m|<=bhi), so the modulus is dominated for ALL m by an integrable       *)
(* envelope                                                                  *)
(* built from the shifted-scaled inverse square                              *)
(* (INV_SHIFT_SCALE_INTEGRABLE).                                             *)
(* ========================================================================= *)

(* integrand modulus <= (1/a) |hhat((y-b)/a)| (theta<=1, |cexp|=1).          *)
let MODULUS_LE_INVA_FHAT = prove
 (`!(h:real->complex) zeta a b x y. schwartz h /\ &0 < a
   ==> norm(cexp(ii * Cx(x/a) * Cx y) *
            fourier (carleson_modulate b (carleson_dilate a h)) y *
            Cx(carleson_theta zeta y))
       <= inv a * norm(fourier h ((y - b)/a))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_MODDIL_FHAT] THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  REWRITE_TAC[GSYM COMPLEX_MUL_ASSOC; GSYM CX_MUL; NORM_CEXP_II;
    REAL_MUL_LID] THEN
  SUBGOAL_THEN `abs(&1/a) = inv a` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_DIV; REAL_ABS_NUM; REAL_DIV_1] THEN
    ASM_SIMP_TAC[REAL_ARITH `&0 < a ==> abs a = a`; real_div; REAL_MUL_LID];
      ALL_TAC] THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `(i * n) * t = (i * n) * t:real`] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN
     ASM_SIMP_TAC[REAL_LE_INV_EQ; NORM_POS_LE; REAL_LT_IMP_LE];
    MP_TAC(SPECL [`zeta:real`; `y:real`] CARLESON_THETA_BOUNDS) THEN
      REAL_ARITH_TAC]);;

(* inverse-order swap helper (avoids an in-context EXISTS_TAC type snag).    *)
let INV_LE_INV_SWAP = prove
 (`!a K. &0 < a /\ &0 < K /\ inv a <= K ==> inv K <= a`,
  REPEAT STRIP_TAC THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM REAL_INV_INV] THEN
  MATCH_MP_TAC REAL_LE_INV2 THEN ASM_SIMP_TAC[REAL_LT_INV]);;

(* a convergent positive sequence is bounded below by a positive constant.   *)
let ASEQ_POS_LOWER = prove
 (`!aseq a0. &0 < a0 /\ (!m. &0 < aseq m) /\ (aseq ---> a0) sequentially
     ==> ?alo. &0 < alo /\ !m. alo <= aseq m`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `((\m. inv(aseq m)) ---> inv a0) sequentially` ASSUME_TAC THENL
   [MATCH_MP_TAC REALLIM_INV THEN ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP REAL_CONVERGENT_IMP_BOUNDED) THEN
  REWRITE_TAC[REAL_BOUNDED_POS; FORALL_IN_IMAGE; IN_UNIV] THEN
  DISCH_THEN(X_CHOOSE_THEN `K:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `inv(K:real)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LT_INV THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `m:num` THEN MATCH_MP_TAC INV_LE_INV_SWAP THEN
  ASM_SIMP_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `m:num`) THEN
  ASM_SIMP_TAC[REAL_ABS_INV; REAL_ARITH `&0 < a ==> abs a = a`]);;

(* global bounds for the (a_m,b_m) sequences: alo<=a_m<=ahi (alo>0),         *)
(* |b_m|<=bhi.                                                               *)
let AMD_SEQ_GLOBAL_BOUNDS = prove
 (`!aseq bseq a0 b0. &0 < a0 /\ (!m. &0 < aseq m) /\
     (aseq ---> a0) sequentially /\ (bseq ---> b0) sequentially
     ==> ?alo ahi bhi. &0 < alo /\
         (!m. alo <= aseq m /\ aseq m <= ahi /\ abs(bseq m) <= bhi)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`aseq:num->real`; `a0:real`] ASEQ_POS_LOWER) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN
    `alo:real` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
    `?ahi. !m. (aseq:num->real) m <= ahi` (X_CHOOSE_TAC `ahi:real`) THENL
   [FIRST_X_ASSUM(MP_TAC o MATCH_MP REAL_CONVERGENT_IMP_BOUNDED o
       check(fun th -> can (find_term (fun t -> t = `a0:real`)) (concl th)))
         THEN
    REWRITE_TAC[REAL_BOUNDED_POS; FORALL_IN_IMAGE; IN_UNIV] THEN
    DISCH_THEN(X_CHOOSE_THEN `Ma:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `Ma:real` THEN X_GEN_TAC `m:num` THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `m:num`) THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `?bhi. !m. abs((bseq:num->real) m) <= bhi` (X_CHOOSE_TAC `bhi:real`) THENL
   [FIRST_X_ASSUM(MP_TAC o MATCH_MP REAL_CONVERGENT_IMP_BOUNDED o
       check(fun th -> can (find_term (fun t -> t = `b0:real`)) (concl th)))
         THEN
    REWRITE_TAC[REAL_BOUNDED_POS; FORALL_IN_IMAGE; IN_UNIV] THEN
    DISCH_THEN(X_CHOOSE_THEN `Mb:real` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `Mb:real` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`alo:real`; `ahi:real`; `bhi:real`] THEN
  ASM_REWRITE_TAC[]);;

(* translate of INV_SQ integrable on the whole line (via vector              *)
(* INTEGRABLE_TRANSLATION).                                                  *)
let INV_SQ_TRANSLATE_INTEGRABLE = prove
 (`!d. (\y. inv(&1 + (y - d) pow 2)) real_integrable_on (:real)`,
  GEN_TAC THEN REWRITE_TAC[REAL_INTEGRABLE_ON; IMAGE_LIFT_UNIV; o_DEF] THEN
  MP_TAC(ISPECL [`\x:real^1. lift(inv(&1 + drop x pow 2))`; `(:real^1)`;
    `--(lift d)`]
    INTEGRABLE_TRANSLATION) THEN
  SUBGOAL_THEN
    `IMAGE (\x:real^1. --(lift d) + x) (:real^1) = (:real^1)` SUBST1_TAC THENL
   [MATCH_MP_TAC SURJECTIVE_IMAGE_EQ THEN REWRITE_TAC[IN_UNIV] THEN
    X_GEN_TAC `z:real^1` THEN EXISTS_TAC `z + lift d:real^1` THEN
      VECTOR_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[DROP_ADD; DROP_NEG; LIFT_DROP] THEN
  SUBGOAL_THEN `(\x:real^1. lift(inv(&1 + (drop x - d) pow 2))) =
                (\x:real^1. lift(inv(&1 + (--d + drop x) pow 2)))` SUBST1_TAC
                  THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC INV_SQ_REAL_INTEGRABLE THEN
  REWRITE_TAC[REAL_INTEGRABLE_ON; IMAGE_LIFT_UNIV; o_DEF]);;

(* comparison: inv(c+s^2) <= max(1,inv c) * inv(1+s^2), c>0.                 *)
let INV_C_LE_MAX_INV_SQ = prove
 (`!c s. &0 < c ==> inv(c + s pow 2) <= max (&1) (inv c) * inv(&1 + s pow 2)`,
  REPEAT STRIP_TAC THEN MP_TAC(SPEC `s:real` REAL_LE_POW_2) THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < &1 + s pow 2 /\ &0 < c + s pow 2` STRIP_ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `&1 <= c` THENL
   [SUBGOAL_THEN `inv c <= &1` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_INV_LE_1 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `max (&1) (inv c) = &1` SUBST1_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_MUL_LID] THEN MATCH_MP_TAC REAL_LE_INV2 THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    SUBGOAL_THEN `&1 <= inv c` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_INV_1_LE THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `max (&1) (inv c) = inv c` SUBST1_TAC THENL
     [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[GSYM REAL_INV_MUL] THEN MATCH_MP_TAC REAL_LE_INV2 THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_ADD_LDISTRIB; REAL_MUL_RID] THEN
      SUBGOAL_THEN `c * s pow 2 <= s pow 2` MP_TAC THENL
       [GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_LID] THEN
        MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      ASM_REAL_ARITH_TAC]]);;

(* the shifted-scaled inverse square is integrable on the whole line (c>0).  *)
let INV_SHIFT_SCALE_INTEGRABLE = prove
 (`!c d. &0 < c ==> (\y. inv(c + (y - d) pow 2)) real_integrable_on (:real)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `\y. max (&1) (inv c) * inv(&1 + (y - d) pow 2)` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
    MATCH_MP_TAC REAL_CONTINUOUS_ON_INV THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_CONTINUOUS_ON_ADD THEN
       REWRITE_TAC[REAL_CONTINUOUS_ON_CONST] THEN
      MATCH_MP_TAC REAL_CONTINUOUS_ON_POW THEN
      MATCH_MP_TAC REAL_CONTINUOUS_ON_SUB THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON_ID; REAL_CONTINUOUS_ON_CONST];
      X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_UNIV] THEN
      MP_TAC(SPEC `y - d:real` REAL_LE_POW_2) THEN ASM_REAL_ARITH_TAC];
    MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
      REWRITE_TAC[INV_SQ_TRANSLATE_INTEGRABLE];
    X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_UNIV] THEN
    SUBGOAL_THEN `&0 < c + (y - d) pow 2` ASSUME_TAC THENL
     [MP_TAC(SPEC `y - d:real` REAL_LE_POW_2) THEN
       ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[real_abs; REAL_LT_IMP_LE; REAL_LE_INV_EQ] THEN
    MP_TAC(ISPECL [`c:real`; `y - d:real`] INV_C_LE_MAX_INV_SQ) THEN
    ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 286S(a) DCT: the uniform (all-m) Poisson dominator bound + arithmetic     *)
(* helpers.  POISSON_UNIF_BOUND says the M_bD_a-window integrand modulus is  *)
(* dominated, for all a in [alo,ahi] and |b|<=bhi, by the b-free integrable  *)
(* envelope gamma*ahi*C*inv(alo^2+y^2) (C=2+(alo^2+2bhi^2)/alo^2), which     *)
(* feeds                                                                     *)
(* the core DOMINATED_CONVERGENCE for FREMLIN_WINDOW_INTEGRAL_LIM.           *)
(* ========================================================================= *)

(* uniform-in-b denominator comparison: alo^2+y^2 <= C*(alo^2+(y-b)^2),      *)
(* |b|<=bhi.                                                                 *)
let DENOM_UNIF_COMPARE = prove
 (`!alo bhi y b. &0 < alo /\ abs b <= bhi
   ==> alo pow 2 + y pow 2
       <= (&2 + (alo pow 2 + &2 * bhi pow 2) / alo pow 2) * (alo pow 2 + (y -
         b) pow 2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < alo pow 2` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `y pow 2 <= &2 * (y - b) pow 2 + &2 * b pow 2` ASSUME_TAC THENL
   [MP_TAC(SPEC `(y - b) - b:real` REAL_LE_POW_2) THEN
    MATCH_MP_TAC(REAL_ARITH
      `((y - b) - b) pow 2 = &2 * (y - b) pow 2 + &2 * b pow 2 - y pow 2
       ==> &0 <= ((y - b) - b) pow 2 ==> y pow 2 <= &2 * (y - b) pow 2 + &2 * b
         pow 2`) THEN
    CONV_TAC REAL_RING; ALL_TAC] THEN
  SUBGOAL_THEN `b pow 2 <= bhi pow 2` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM REAL_LE_SQUARE_ABS] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `(&2 + (alo pow 2 + &2 * bhi pow 2) / alo pow 2) * (alo pow 2 + (y - b) pow
     2)
                = &2 * (alo pow 2 + (y - b) pow 2)
                  + ((alo pow 2 + &2 * bhi pow 2)
                     + (alo pow 2 + &2 * bhi pow 2) / alo pow 2 * (y - b) pow
                       2)`
   SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ADD_RDISTRIB] THEN
    ASM_SIMP_TAC[REAL_FIELD `&0 < a ==> x / a * (a + w) = x + x / a * w`];
      ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 <= (alo pow 2 + &2 * bhi pow 2)/alo pow 2 * (y - b) pow 2`
     ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[REAL_LE_POW_2] THEN
    MATCH_MP_TAC REAL_LE_DIV THEN
    MP_TAC(SPEC `bhi:real` REAL_LE_POW_2) THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPEC `bhi:real` REAL_LE_POW_2) THEN
  MP_TAC(SPEC `y - b:real` REAL_LE_POW_2) THEN
  ASM_REAL_ARITH_TAC);;

(* Poisson form of the envelope: inv                                         *)
(* a*(gamma*inv(1+((y-b)/a)^2))=gamma*a*inv(a^2+(y-b)^2).                    *)
let INVA_ENVELOPE_POISSON = prove
 (`!a b y gam. &0 < a
   ==> inv a * (gam * inv(&1 + ((y - b)/a) pow 2)) = gam * a * inv(a pow 2 + (y
     - b) pow 2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < a pow 2` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&1 + ((y - b)/a) pow 2 =
     (a pow 2 + (y - b) pow 2) / a pow 2` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_POW_DIV] THEN
    MP_TAC(ASSUME `&0 < a pow 2`) THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  REWRITE_TAC[REAL_INV_DIV] THEN
  MP_TAC(ASSUME `&0 < a`) THEN MP_TAC(ASSUME `&0 < a pow 2`) THEN
  CONV_TAC REAL_FIELD);;

(* inverse-order swap: 0<d1/\0<d2/\0<c/\d2<=c*d1 ==> inv d1<=c*inv d2.       *)
let INV_LE_MUL_INV = prove
 (`!d1 d2 c. &0 < d1 /\ &0 < d2 /\ &0 < c /\ d2 <= c * d1 ==> inv d1 <= c * inv
   d2`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(d1 = &0) /\ ~(d2 = &0)` STRIP_ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `inv d1 <= c * inv d2 <=> inv d1 * (d1 * d2) <= (c * inv d2) * (d1 * d2)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC(GSYM REAL_LE_RMUL_EQ) THEN MATCH_MP_TAC REAL_LT_MUL THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(REAL_FIELD `~(d1 = &0) /\ ~(d2 = &0)
       ==> inv d1 * d1 * d2 = d2 /\ (c * inv d2) * d1 * d2 = c * d1`) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(CONJUNCTS_THEN SUBST1_TAC) THEN
  ASM_REWRITE_TAC[]);;

(* monotone denominator: 0<p/\p<=q/\0<=r ==> inv(q+r)<=inv(p+r).             *)
let INV_ADD_MONO = prove
 (`!p q r. &0 < p /\ p <= q /\ &0 <= r ==> inv(q + r) <= inv(p + r)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REAL_LE_INV2 THEN ASM_REAL_ARITH_TAC);;

(* POISSON_UNIF_BOUND: uniform (all-m via global bounds) modulus dominator.  *)
let POISSON_UNIF_BOUND = prove
 (`!(h:real->complex) zeta a b x y alo ahi bhi gam.
     schwartz h /\ &0 < alo /\ alo <= a /\ a <= ahi /\ abs b <= bhi /\
     &0 <= gam /\ (!t. norm(fourier h t) <= gam * inv(&1 + t pow 2))
     ==> norm(cexp(ii * Cx(x/a) * Cx y) *
              fourier (carleson_modulate b (carleson_dilate a h)) y *
              Cx(carleson_theta zeta y))
         <= gam * ahi * (&2 + (alo pow 2 + &2 * bhi pow 2) / alo pow 2) *
            inv(alo pow 2 + y pow 2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < a` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `inv a * norm(fourier h ((y - b)/a))` THEN CONJ_TAC THENL
   [MATCH_MP_TAC MODULUS_LE_INVA_FHAT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `inv a * (gam * inv(&1 + ((y - b)/a) pow 2)):real` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN
    ASM_SIMP_TAC[REAL_LE_INV_EQ; REAL_LT_IMP_LE]; ALL_TAC] THEN
  ASM_SIMP_TAC[INVA_ENVELOPE_POISSON] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `gam * ahi * inv(alo pow 2 + (y - b) pow 2):real` THEN
    CONJ_TAC THENL
   [SUBGOAL_THEN
     `&0 < alo pow 2 + (y - b) pow 2 /\ &0 < a pow 2 + (y - b) pow 2`
     STRIP_ASSUME_TAC THENL
     [MP_TAC(SPEC `y - b:real` REAL_LE_POW_2) THEN
       MP_TAC(SPECL [`alo:real`; `2`] REAL_POW_LT) THEN
      MP_TAC(SPECL [`a:real`; `2`] REAL_POW_LT) THEN
        ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
      [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `a * inv(alo pow 2 + (y - b) pow 2):real` THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC INV_ADD_MONO THEN REPEAT CONJ_TAC THENL
       [MP_TAC(SPECL [`alo:real`; `2`] REAL_POW_LT) THEN ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_POW_LE2 THEN ASM_REAL_ARITH_TAC;
        REWRITE_TAC[REAL_LE_POW_2]];
      MATCH_MP_TAC REAL_LE_RMUL THEN CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        REWRITE_TAC[REAL_LE_INV_EQ] THEN ASM_REAL_ARITH_TAC]]; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `alo:real` THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC INV_LE_MUL_INV THEN REPEAT CONJ_TAC THENL
   [MP_TAC(SPEC `y - b:real` REAL_LE_POW_2) THEN
     MP_TAC(SPECL [`alo:real`; `2`] REAL_POW_LT) THEN
    ASM_REAL_ARITH_TAC;
    MP_TAC(SPEC `y:real` REAL_LE_POW_2) THEN
      MP_TAC(SPECL [`alo:real`; `2`] REAL_POW_LT) THEN
    ASM_REAL_ARITH_TAC;
    MP_TAC(SPEC `bhi:real` REAL_LE_POW_2) THEN
      MP_TAC(SPECL [`alo:real`; `2`] REAL_POW_LT) THEN
    SUBGOAL_THEN `&0 <= (alo pow 2 + &2 * bhi pow 2) / alo pow 2` MP_TAC THENL
     [MATCH_MP_TAC REAL_LE_DIV THEN MP_TAC(SPEC `bhi:real` REAL_LE_POW_2) THEN
      MP_TAC(SPEC `alo:real` REAL_LE_POW_2) THEN
        ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REAL_ARITH_TAC;
    MP_TAC(ISPECL [`alo:real`; `bhi:real`; `y:real`;
      `b:real`] DENOM_UNIF_COMPARE) THEN
    ASM_REWRITE_TAC[]]);;

(* the b-free dominator K*inv(alo^2+y^2) is integrable on the whole line     *)
(* (alo>0).                                                                  *)
let DOMINATOR_VEC_INTEGRABLE = prove
 (`!K alo. &0 < alo
   ==> (\w:real^1. lift(K * inv(alo pow 2 + drop w pow 2))) integrable_on
     (:real^1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[LIFT_CMUL] THEN MATCH_MP_TAC INTEGRABLE_CMUL THEN
  SUBGOAL_THEN `&0 < alo pow 2` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(alo:real) pow 2`;
    `&0:real`] INV_SHIFT_SCALE_INTEGRABLE) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[REAL_INTEGRABLE_ON; IMAGE_LIFT_UNIV; o_DEF; REAL_SUB_RZERO;
    LIFT_DROP]);;

(* FREMLIN_WINDOW_INTEGRAL_LIM: the DCT integral-limit for Fremlin's window  *)
(* (theta_zeta a FIXED weight, hhat dilated). As (a_m,b_m,x_m)->(a0,b0,x0)   *)
(* [a0>0],                                                                   *)
(* int cexp(ii(x_m/a_m)y)(M_{b_m}D_{a_m}h)hat(y)theta_zeta(y) -> the         *)
(* a0/b0/x0 one.                                                             *)
(* Core DOMINATED_CONVERGENCE, EMPTY exceptional set (theta_zeta fixed =>    *)
(* pointwise                                                                 *)
(* everywhere via FREMLIN_INTEGRAND_LIM), uniform all-m dominator via        *)
(* AMD_SEQ_                                                                  *)
(* GLOBAL_BOUNDS + FHAT_QUAD_ENVELOPE + POISSON_UNIF_BOUND. The hardest      *)
(* 286S(a)                                                                   *)
(* brick.                                                                    *)
let FREMLIN_WINDOW_INTEGRAL_LIM = prove
 (`!(h:real->complex) (aseq:num->real) bseq xseq alpha0 beta0 x0 zeta.
     schwartz h /\ &0 < alpha0 /\
     (aseq ---> alpha0) sequentially /\ (bseq ---> beta0) sequentially /\
     (xseq ---> x0) sequentially /\ (!m. &0 < aseq m)
     ==> ((\m. integral (:real^1) (\w. cexp(ii * Cx(xseq m / aseq m) * Cx(drop
       w)) *
                    fourier (carleson_modulate (bseq m) (carleson_dilate (aseq
                      m) h)) (drop w) *
                    Cx(carleson_theta zeta (drop w))))
          --> integral (:real^1) (\w. cexp(ii * Cx(x0 / alpha0) * Cx(drop w)) *
                    fourier (carleson_modulate beta0 (carleson_dilate alpha0
                      h)) (drop w) *
                    Cx(carleson_theta zeta (drop w)))) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`aseq:num->real`; `bseq:num->real`; `alpha0:real`;
    `beta0:real`]
    AMD_SEQ_GLOBAL_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `alo:real` (X_CHOOSE_THEN `ahi:real`
    (X_CHOOSE_THEN `bhi:real` STRIP_ASSUME_TAC))) THEN
  MP_TAC(ISPEC `h:real->complex` FHAT_QUAD_ENVELOPE) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `gam:real` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL
   [`\(m:num) (w:real^1). cexp(ii * Cx(xseq m / aseq m) * Cx(drop w)) *
                fourier (carleson_modulate (bseq m) (carleson_dilate (aseq m)
                  h)) (drop w) *
                Cx(carleson_theta zeta (drop w))`;
    `\w:real^1. cexp(ii * Cx(x0 / alpha0) * Cx(drop w)) *
                fourier (carleson_modulate beta0 (carleson_dilate alpha0 h))
                  (drop w) *
                Cx(carleson_theta zeta (drop w))`;
    `\w:real^1. lift(gam * ahi * (&2 + (alo pow 2 + &2 * bhi pow 2) / alo pow
      2) *
                     inv(alo pow 2 + drop w pow 2))`;
    `(:real^1)`]
   DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [GEN_TAC THEN MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      SUBGOAL_THEN
       `(\w:real^1. cexp(ii * Cx(xseq (k:num) / aseq k) * Cx(drop w)) *
             fourier (carleson_modulate (bseq k) (carleson_dilate (aseq k) h))
               (drop w) *
             Cx(carleson_theta zeta (drop w))) =
        (\w:real^1. cexp(ii * Cx(xseq k / aseq k) * Cx(drop w)) *
             (\u:real^1. fourier (carleson_modulate (bseq k) (carleson_dilate
               (aseq k) h)) (drop u) *
                  Cx(carleson_theta zeta (drop u))) w)`
       SUBST1_TAC THENL
         [REWRITE_TAC[FUN_EQ_THM; COMPLEX_MUL_ASSOC]; ALL_TAC] THEN
      MATCH_MP_TAC CEXP_MODULATE_ABSINT_GEN THEN
      MATCH_MP_TAC CARLESON_MODDIL_WINDOW_ABSINT THEN
      ASM_SIMP_TAC[REAL_LT_IMP_NZ];
      SUBGOAL_THEN
       `(\w:real^1. lift(gam * ahi * (&2 + (alo pow 2 + &2 * bhi pow 2) / alo
         pow 2) *
                         inv(alo pow 2 + drop w pow 2))) =
        (\w:real^1. lift((gam * ahi * (&2 + (alo pow 2 + &2 * bhi pow 2) / alo
          pow 2)) *
                         inv(alo pow 2 + drop w pow 2)))`
       SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM; REAL_MUL_ASSOC]; ALL_TAC] THEN
      MATCH_MP_TAC DOMINATOR_VEC_INTEGRABLE THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`m:num`; `w:real^1`] THEN DISCH_TAC THEN
        BETA_TAC THEN
      REWRITE_TAC[LIFT_DROP] THEN
      MP_TAC(ISPECL [`h:real->complex`; `zeta:real`; `aseq(m:num):real`;
        `bseq(m:num):real`;
                     `xseq(m:num):real`; `drop(w:real^1)`; `alo:real`;
                       `ahi:real`;
                     `bhi:real`; `gam:real`] POISSON_UNIF_BOUND) THEN
      ASM_SIMP_TAC[];
      X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN BETA_TAC THEN
      MATCH_MP_TAC FREMLIN_INTEGRAND_LIM THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN REWRITE_TAC[]]);;

(* FREMLIN_WINDOW_JOINT_CONT: the amd z-window                               *)
(* V_zeta(a,b,x)=2pi*norm(fourier                                            *)
(* ((M_bD_a h)hat . theta_zeta)(-x/a)) is jointly sequentially continuous in *)
(* (a,b,x).                                                                  *)
(* Wraps FREMLIN_WINDOW_INTEGRAL_LIM via FOURIER_AT_NEG + NORM_SEQ_REALLIM + *)
(* REALLIM_LMUL (the 2pi/sqrt(2pi) constant). Fremlin's window: theta_zeta a *)
(* FIXED                                                                     *)
(* weight => NO dyadic gate; the correct object for the amd                  *)
(* sup-LSC/measurability.                                                    *)
let FREMLIN_WINDOW_JOINT_CONT = prove
 (`!(h:real->complex) (aseq:num->real) bseq xseq alpha0 beta0 x0 zeta.
     schwartz h /\ &0 < alpha0 /\
     (aseq ---> alpha0) sequentially /\ (bseq ---> beta0) sequentially /\
     (xseq ---> x0) sequentially /\ (!m. &0 < aseq m)
     ==> ((\m. &2 * pi * norm(fourier(\w. fourier (carleson_modulate (bseq m)
       (carleson_dilate (aseq m) h)) w *
                    Cx(carleson_theta zeta w))(--(xseq m / aseq m))))
          ---> &2 * pi * norm(fourier(\w. fourier (carleson_modulate beta0
            (carleson_dilate alpha0 h)) w *
                    Cx(carleson_theta zeta w))(--(x0 / alpha0))))
                      sequentially`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[FOURIER_AT_NEG] THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  REWRITE_TAC[REAL_MUL_ASSOC] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `(&2 * pi) * c * n = ((&2 * pi) * c) * n:real`]
    THEN
  MATCH_MP_TAC REALLIM_LMUL THEN
  MATCH_MP_TAC NORM_SEQ_REALLIM THEN
  MATCH_MP_TAC FREMLIN_WINDOW_INTEGRAL_LIM THEN ASM_REWRITE_TAC[]);;

(* unfolded amd sup-rep matching FREMLIN_WINDOW_JOINT_CONT's window          *)
(* (theta_zeta a                                                             *)
(* FIXED weight): amd h a b x = sup_zeta [2pi*norm(fourier((M_bD_a h)hat     *)
(* theta_zeta)                                                               *)
(* (-x/a))]. Directly carleson_A(M_bD_a h)(x/a) unfolded,                    *)
(* norm(Cx2pi*W)=2pi*norm W.                                                 *)
let CARLESON_AMD_SUP_WINDOW_UNFOLD = prove
 (`!(h:real->complex) a b x.
     carleson_amd h a b x =
     sup { &2 * pi * norm(fourier(\w. fourier (carleson_modulate b
       (carleson_dilate a h)) w *
                    Cx(carleson_theta zeta w))(--(x/a)))
         | zeta IN (:real) }`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `!zeta. norm(Cx(&2 * pi) *
               fourier(\y. fourier (carleson_modulate b (carleson_dilate a h))
                 y *
                    Cx(carleson_theta zeta y))(--(x/a)))
          = &2 * pi * norm(fourier(\w. fourier (carleson_modulate b
            (carleson_dilate a h)) w *
                    Cx(carleson_theta zeta w))(--(x/a)))`
   ASSUME_TAC THENL
   [GEN_TAC THEN
     REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX; REAL_ABS_MUL; REAL_ABS_NUM;
     REAL_ABS_PI] THEN
    MP_TAC PI_POS THEN REWRITE_TAC[REAL_MUL_ASSOC] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[carleson_amd; carleson_A] THEN AP_TERM_TAC THEN
  ASM_REWRITE_TAC[]);;

(* V_zeta as a real^3->real^1 function is continuous_on the open half-space  *)
(* {a>0}.                                                                    *)
(* Bridges FREMLIN_WINDOW_JOINT_CONT (sequential) to continuous_on via       *)
(* CONTINUOUS_ON_SEQUENTIALLY + componentwise limits                         *)
(* (LIM_COMPONENTWISE_REAL).                                                 *)
(* The (a,b,x) point is encoded as p:real^3 with p$1=a, p$2=b, p$3=x. This   *)
(* feeds                                                                     *)
(* the LSC/measurability of amd = sup_zeta V_zeta.                           *)
let VZETA_CONTINUOUS_ON = prove
 (`!(h:real->complex) zeta. schwartz h
   ==> (\p:real^3. lift(&2 * pi * norm(fourier(\w. fourier (carleson_modulate
     (p$2) (carleson_dilate (p$1) h)) w *
                    Cx(carleson_theta zeta w))(--(p$3 / p$1)))))
       continuous_on {p:real^3 | p$1 > &0}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[CONTINUOUS_ON_SEQUENTIALLY] THEN
  MAP_EVERY X_GEN_TAC [`xs:num->real^3`; `p:real^3`] THEN
  REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
  REWRITE_TAC[o_DEF] THEN REWRITE_TAC[GSYM LIFT_CMUL] THEN
  SUBGOAL_THEN
   `(\x. lift(&2 * pi * norm(fourier(\w. fourier (carleson_modulate
     ((xs:num->real^3) x$2) (carleson_dilate (xs x$1) h)) w *
                    Cx(carleson_theta zeta w))(--(xs x$3 / xs x$1)))))
    = (lift o (\x. &2 * pi * norm(fourier(\w. fourier (carleson_modulate
      ((xs:num->real^3) x$2) (carleson_dilate (xs x$1) h)) w *
                    Cx(carleson_theta zeta w))(--(xs x$3 / xs x$1)))))`
   SUBST1_TAC THENL [REWRITE_TAC[o_DEF]; ALL_TAC] THEN
  REWRITE_TAC[GSYM TENDSTO_REAL] THEN
  MP_TAC(ISPECL [`h:real->complex`; `\n. (xs:num->real^3) n$1`;
    `\n. (xs:num->real^3) n$2`;
                 `\n. (xs:num->real^3) n$3`; `(p:real^3)$1`; `(p:real^3)$2`;
                   `(p:real^3)$3`; `zeta:real`]
    FREMLIN_WINDOW_JOINT_CONT) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [LIM_COMPONENTWISE_REAL]) THEN
  REWRITE_TAC[DIMINDEX_3; GSYM tendsto_real_def] THEN
  DISCH_THEN(fun th -> MP_TAC(SPEC `1` th) THEN MP_TAC(SPEC `2` th) THEN
    MP_TAC(SPEC `3` th)) THEN
  REWRITE_TAC[ARITH] THEN REPEAT STRIP_TAC THEN
  ASM_REWRITE_TAC[GSYM real_gt]);;

(* single-V_zeta superlevel {p$1>0 /\ V_zeta p > c} is open in real^3        *)
(* (continuous on the open half-space {a>0} => open superlevel,              *)
(* CONTINUOUS_OPEN_PREIMAGE).                                                *)
let VZETA_SUPERLEVEL_OPEN = prove
 (`!(h:real->complex) zeta c. schwartz h
   ==> open {p:real^3 | p$1 > &0 /\
             &2 * pi * norm(fourier(\w. fourier (carleson_modulate (p$2)
               (carleson_dilate (p$1) h)) w *
                    Cx(carleson_theta zeta w))(--(p$3 / p$1))) > c}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\p:real^3. lift(&2 * pi * norm(fourier(\w. fourier (carleson_modulate
     (p$2) (carleson_dilate (p$1) h)) w *
                    Cx(carleson_theta zeta w))(--(p$3 / p$1))))`;
    `{p:real^3 | p$1 > &0}`;
      `{t:real^1 | t$1 > c}`] CONTINUOUS_OPEN_PREIMAGE) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[VZETA_CONTINUOUS_ON; OPEN_HALFSPACE_COMPONENT_GT];
     ALL_TAC] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM; GSYM drop; LIFT_DROP] THEN
  X_GEN_TAC `p:real^3` THEN REWRITE_TAC[CONJ_ACI]);;

(* amd sup-characterization: amd h a b x > c <=> some window value > c       *)
(* (a>0). From                                                               *)
(* CARLESON_AMD_SUP_WINDOW_UNFOLD + REAL_SUP_LE_EQ (nonempty + bounded by    *)
(* carleson_A's                                                              *)
(* uniform bound), negated.                                                  *)
let AMD_SUP_GT = prove
 (`!(h:real->complex) a b x c. schwartz h /\ &0 < a
   ==> (carleson_amd h a b x > c <=>
        ?zeta. &2 * pi * norm(fourier(\w. fourier (carleson_modulate b
          (carleson_dilate a h)) w *
                    Cx(carleson_theta zeta w))(--(x/a))) > c)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_AMD_SUP_WINDOW_UNFOLD] THEN
  REWRITE_TAC[real_gt] THEN
  MP_TAC(ISPECL
   [`{ &2 * pi * norm(fourier(\w. fourier (carleson_modulate b (carleson_dilate
     a h)) w *
                    Cx(carleson_theta zeta w))(--(x/a))) | zeta IN (:real)}`;
                      `c:real`]
    REAL_SUP_LE_EQ) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      EXISTS_TAC `&2 * pi * norm(fourier(\w. fourier (carleson_modulate b
        (carleson_dilate a h)) w *
                    Cx(carleson_theta (&0) w))(--(x/a)))` THEN
      EXISTS_TAC `&0:real` THEN REWRITE_TAC[IN_UNIV];
      EXISTS_TAC `sqrt(&2 * pi) *
                  drop(integral (:real^1) (\y. lift(norm(fourier
                    (carleson_modulate b (carleson_dilate a (h:real->complex)))
                     (drop y)))))` THEN
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `zeta:real` THEN
      MP_TAC(ISPECL [`carleson_modulate b (carleson_dilate a
        (h:real->complex))`; `zeta:real`; `(x/a):real`]
        CARLESON_A_WINDOW_UNIFORM_BOUND) THEN
      ANTS_TAC THENL
       [MATCH_MP_TAC CARLESON_SCHWARTZ_MODDIL THEN
         ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN
      REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX; REAL_ABS_MUL;
        REAL_ABS_NUM; REAL_ABS_PI] THEN
      REWRITE_TAC[real_div; REAL_NEG_LMUL; REAL_MUL_ASSOC]]; ALL_TAC] THEN
  DISCH_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [GSYM REAL_NOT_LE] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP; IN_ELIM_THM; IN_UNIV; REAL_NOT_LE] THEN
  MESON_TAC[]);;

(* AMD_JOINT_LSC: the amd kernel (real^3->real^1, junk 0 for a<=0) is        *)
(* measurable_on                                                             *)
(* (:real^3). amd = sup_zeta V_zeta, each V_zeta continuous on {a>0}, so amd *)
(* is LSC:                                                                   *)
(* c<0 => superlevel = everything (amd>=0); c>=0 => UNIONS_zeta of the open  *)
(* V_zeta-                                                                   *)
(* superlevels (AMD_SUP_GT + VZETA_SUPERLEVEL_OPEN). MEASURABLE_ON_LSC_MULTI *)
(* closes.                                                                   *)
let AMD_JOINT_LSC = prove
 (`!(h:real->complex). schwartz h
   ==> (\p:real^3. lift(if p$1 > &0 then carleson_amd h (p$1) (p$2) (p$3) else
     &0))
       measurable_on (:real^3)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MEASURABLE_ON_LSC_MULTI THEN
  X_GEN_TAC `c:real` THEN REWRITE_TAC[LIFT_DROP] THEN
  ASM_CASES_TAC `c < &0` THENL
   [SUBGOAL_THEN
     `{x:real^3 | (if x$1 > &0 then carleson_amd h (x$1) (x$2) (x$3) else &0) >
       c} = (:real^3)`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_UNIV] THEN
      X_GEN_TAC `p:real^3` THEN COND_CASES_TAC THEN REWRITE_TAC[real_gt] THENL
       [MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `&0` THEN
         ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC AMD_NONNEG THEN ASM_REWRITE_TAC[GSYM real_gt];
        ASM_REAL_ARITH_TAC];
      REWRITE_TAC[OPEN_UNIV]];
    SUBGOAL_THEN
     `{x:real^3 | (if x$1 > &0 then carleson_amd h (x$1) (x$2) (x$3) else &0) >
       c} =
      UNIONS { {p:real^3 | p$1 > &0 /\
               &2 * pi * norm(fourier(\w. fourier (carleson_modulate (p$2)
                 (carleson_dilate (p$1) h)) w *
                      Cx(carleson_theta zeta w))(--(p$3 / p$1))) > c}
             | zeta IN (:real) }`
     SUBST1_TAC THENL
     [REWRITE_TAC[UNIONS_GSPEC; EXTENSION; IN_ELIM_THM; IN_UNIV] THEN
      X_GEN_TAC `p:real^3` THEN COND_CASES_TAC THENL
       [MP_TAC(ISPECL [`h:real->complex`; `(p:real^3)$1`; `(p:real^3)$2`;
         `(p:real^3)$3`; `c:real`]
          AMD_SUP_GT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[GSYM real_gt]; ALL_TAC] THEN
        DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[real_gt] THEN ASM_REAL_ARITH_TAC];
      MATCH_MP_TAC OPEN_UNIONS THEN
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN
      X_GEN_TAC `zeta:real` THEN
      MATCH_MP_TAC VZETA_SUPERLEVEL_OPEN THEN ASM_REWRITE_TAC[]]]);;

(* ========================================================================= *)
(* 286S(b) box-Tonelli, step 1: transfer AMD_JOINT_LSC (measurable on        *)
(* real^3) to the                                                            *)
(* product type real^(1,2)finite_sum via the linear coordinate SHUFFLE g:    *)
(* g z = vector[sndcart z$1; sndcart z$2; fstcart z$1] (alpha=sndcart$1,     *)
(* beta=                                                                     *)
(* sndcart$2, x=fstcart$1). This is the joint measurability the Fubini swap  *)
(* needs.                                                                    *)
(* ========================================================================= *)

(* the coordinate shuffle g is linear + injective.                           *)
let MODDIL_FHAT_L1 = prove
 (`!(h:real->complex) a b. schwartz h /\ &0 < a
   ==> integral (:real^1) (\w. lift(norm(fourier (carleson_modulate b
     (carleson_dilate a h)) (drop w)))) =
       integral (:real^1) (\w. lift(norm(fourier h (drop w))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(a = &0)` ASSUME_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\w:real^1. lift(norm(fourier (carleson_modulate b (carleson_dilate a h))
     (drop w)))) =
    (\w:real^1. inv a % (\u:real^1. lift(norm(fourier h (drop u)))) (inv a % w
      + lift(--(b/a))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real^1` THEN
    ASM_SIMP_TAC[CARLESON_MODDIL_FHAT] THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    REWRITE_TAC[DROP_CMUL; DROP_ADD; LIFT_DROP; LIFT_CMUL] THEN
    SUBGOAL_THEN `abs(&1 / a) = inv a` SUBST1_TAC THENL
     [REWRITE_TAC[real_div; REAL_MUL_LID; REAL_ABS_INV] THEN
      ASM_SIMP_TAC[REAL_ARITH `&0 < a ==> abs a = a`]; ALL_TAC] THEN
    AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    UNDISCH_TAC `~(a = &0)` THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\u:real^1. lift(norm(fourier (h:real->complex) (drop u)))) integrable_on
    (:real^1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
    MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\w:real^1. (\u:real^1. lift (norm (fourier (h:real->complex) (drop u))))
                (inv a % w + lift (--(b / a)))) integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\u:real^1. lift(norm(fourier (h:real->complex) (drop u)))`;
                   `inv a:real`; `lift(--(b/a))`] INTEGRABLE_DILATE_UNIV) THEN
    ASM_SIMP_TAC[REAL_INV_EQ_0; REAL_LT_IMP_NZ]; ALL_TAC] THEN
  ASM_SIMP_TAC[INTEGRAL_CMUL] THEN
  MP_TAC(BETA_RULE(ISPECL [`\u:real^1. lift(norm(fourier (h:real->complex)
    (drop u)))`;
                 `inv a:real`; `lift(--(b/a))`] INTEGRAL_DILATE_UNIV)) THEN
  ASM_SIMP_TAC[REAL_INV_EQ_0; REAL_LT_IMP_NZ] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `inv(abs(inv a)) = a` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_INV; REAL_INV_INV] THEN
    ASM_SIMP_TAC[REAL_ARITH `&0 < a ==> abs a = a`]; ALL_TAC] THEN
  REWRITE_TAC[VECTOR_MUL_ASSOC] THEN
  ASM_SIMP_TAC[REAL_MUL_LINV; REAL_LT_IMP_NZ; VECTOR_MUL_LID]);;

(* Uniform constant bound on the amd kernel, independent of (a>0, b, x).     *)
let AMD_UNIF_BOUND = prove
 (`!(h:real->complex) a b x. schwartz h /\ &0 < a
   ==> carleson_amd h a b x
       <= sqrt(&2 * pi) * drop(integral (:real^1) (\y. lift(norm(fourier
         (h:real->complex) (drop y)))))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_amd] THEN
  MP_TAC(ISPECL [`carleson_modulate b (carleson_dilate a (h:real->complex))`;
    `x / a:real`]
    CARLESON_A_UNIFORM_BOUND) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC CARLESON_SCHWARTZ_MODDIL THEN
     ASM_SIMP_TAC[REAL_LT_IMP_NZ]; ALL_TAC] THEN
  ASM_SIMP_TAC[MODDIL_FHAT_L1]);;

(* ========================================================================= *)
(* Iterated-product measurability of the amd kernel, for the box-Tonelli     *)
(* swap.                                                                     *)
(* The type real^(1,(1,1)finite_sum)finite_sum = R x (R x R) lets BOTH the   *)
(* outer swap x <-> (alpha,beta) AND the inner alpha <-> beta split be       *)
(* direct                                                                    *)
(* finite_sum library Fubinis. We transfer AMD_JOINT_LSC (on real^3) along   *)
(* the                                                                       *)
(* linear+bijective coordinate shuffle                                       *)
(* g z = vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));          *)
(* drop(fstcart z)],                                                         *)
(* i.e. alpha=fstcart(sndcart z), beta=sndcart(sndcart z), x=fstcart z.      *)
(* ------------------------------------------------------------------------- *)
(* the iterated shuffle is linear + injective.                               *)
let AMDT_SHUFFLE_LINEAR = prove
 (`linear (\z:real^(1,(1,1)finite_sum)finite_sum.
             vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
               drop(fstcart z)]:real^3) /\
   (!u v:real^(1,(1,1)finite_sum)finite_sum.
      (\z. vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
        drop(fstcart z)]:real^3) u =
      (\z. vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
        drop(fstcart z)]:real^3) v ==> u = v)`,
  CONJ_TAC THENL
   [REWRITE_TAC[linear] THEN CONJ_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3] THEN
    SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VECTOR_3; DIMINDEX_3;
      ARITH] THEN
    REWRITE_TAC[FSTCART_ADD; SNDCART_ADD; FSTCART_CMUL; SNDCART_CMUL;
                DROP_ADD; DROP_CMUL] THEN REWRITE_TAC[VECTOR_3] THEN
                  REAL_ARITH_TAC;
    REPEAT GEN_TAC THEN REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `drop(fstcart(sndcart(u:real^(1,(1,1)finite_sum)finite_sum))) =
       drop(fstcart(sndcart v)) /\
      drop(sndcart(sndcart u)) = drop(sndcart(sndcart v)) /\
      drop(fstcart u) = drop(fstcart v)`
     STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC) THEN
       REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3] THEN
      SIMP_TAC[]; ALL_TAC] THEN
    ONCE_REWRITE_TAC[PASTECART_EQ] THEN CONJ_TAC THENL
     [ONCE_REWRITE_TAC[GSYM DROP_EQ] THEN ASM_REWRITE_TAC[];
      ONCE_REWRITE_TAC[PASTECART_EQ] THEN CONJ_TAC THEN
      ONCE_REWRITE_TAC[GSYM DROP_EQ] THEN ASM_REWRITE_TAC[]]]);;

(* image of UNIV under the (bijective) iterated shuffle is UNIV.             *)
let AMDT_SHUFFLE_IMAGE = prove
 (`IMAGE (\z:real^(1,(1,1)finite_sum)finite_sum.
             vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
               drop(fstcart z)]:real^3)
     (:real^(1,(1,1)finite_sum)finite_sum) = (:real^3)`,
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN X_GEN_TAC `p:real^3` THEN
  EXISTS_TAC
   `pastecart (lift((p:real^3)$3))
      (pastecart (lift((p:real^3)$1)) (lift((p:real^3)$2))
        :real^(1,1)finite_sum)
    :real^(1,(1,1)finite_sum)finite_sum` THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART; LIFT_DROP] THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3; LIFT_COMPONENT]);;

(* pre-specialized measurability bridge for the iterated shuffle (hh         *)
(* general).                                                                 *)
let MEAS_SHUFFLE_T = prove
 (`!hh:real^3->real^1.
     (hh o (\z:real^(1,(1,1)finite_sum)finite_sum.
              vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
                drop(fstcart z)]:real^3))
       measurable_on (:real^(1,(1,1)finite_sum)finite_sum)
     <=> hh measurable_on (:real^3)`,
  GEN_TAC THEN
  MP_TAC(ISPECL
   [`\z:real^(1,(1,1)finite_sum)finite_sum.
        vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
          drop(fstcart z)]:real^3`;
    `hh:real^3->real^1`;
      `(:real^(1,(1,1)finite_sum)finite_sum)`]
      MEASURABLE_ON_LINEAR_IMAGE_EQ_GEN) THEN
  REWRITE_TAC[AMDT_SHUFFLE_LINEAR; DIMINDEX_FINITE_SUM; DIMINDEX_1; DIMINDEX_3;
    ARITH] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[AMDT_SHUFFLE_IMAGE]);;

(* the amd kernel measurable on the ITERATED product type                    *)
(* real^(1,(1,1)fs)fs.                                                       *)
let AMDT_PROD_MEASURABLE = prove
 (`!(h:real->complex). schwartz h
   ==> (\z:real^(1,(1,1)finite_sum)finite_sum.
          lift(if drop(fstcart(sndcart z)) > &0
               then carleson_amd h (drop(fstcart(sndcart z)))
                                   (drop(sndcart(sndcart z))) (drop(fstcart z))
               else &0))
       measurable_on (:real^(1,(1,1)finite_sum)finite_sum)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^(1,(1,1)finite_sum)finite_sum.
       lift(if drop(fstcart(sndcart z)) > &0
            then carleson_amd h (drop(fstcart(sndcart z)))
                                (drop(sndcart(sndcart z))) (drop(fstcart z))
            else &0))
    = (\p:real^3. lift(if p$1 > &0 then carleson_amd h (p$1)(p$2)(p$3) else
      &0)) o
      (\z:real^(1,(1,1)finite_sum)finite_sum.
         vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
           drop(fstcart z)]:real^3)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN
     X_GEN_TAC `z:real^(1,(1,1)finite_sum)finite_sum` THEN
    REWRITE_TAC[VECTOR_3]; ALL_TAC] THEN
  REWRITE_TAC[MEAS_SHUFFLE_T] THEN
  MATCH_MP_TAC AMD_JOINT_LSC THEN ASM_REWRITE_TAC[]);;

(* the alpha-coordinate scalar drop(fstcart(sndcart z)) on the iterated      *)
(* type, and its inverse (with the negligible alpha=0 hyperplane), are       *)
(* measurable.                                                               *)
let AMDT_ALPHA_MEASURABLE = prove
 (`(\z:real^(1,(1,1)finite_sum)finite_sum. lift(drop(fstcart(sndcart z))))
   measurable_on (:real^(1,(1,1)finite_sum)finite_sum)`,
  REWRITE_TAC[LIFT_DROP; ETA_AX] THEN
  MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  MATCH_MP_TAC LINEAR_CONTINUOUS_ON THEN
  SUBGOAL_THEN
   `(\z:real^(1,(1,1)finite_sum)finite_sum. fstcart(sndcart z)) =
    (fstcart:real^(1,1)finite_sum->real^1) o
    (sndcart:real^(1,(1,1)finite_sum)finite_sum->real^(1,1)finite_sum)`
   SUBST1_TAC THENL [REWRITE_TAC[o_DEF]; ALL_TAC] THEN
  MATCH_MP_TAC LINEAR_COMPOSE THEN
    REWRITE_TAC[LINEAR_FSTCART; LINEAR_SNDCART]);;

(* alpha = drop(fstcart(sndcart z)) is exactly the z$2 coordinate.           *)
let AMDT_ALPHA_EQ_C2 = prove
 (`!z:real^(1,(1,1)finite_sum)finite_sum. drop(fstcart(sndcart z)) = z$2`,
  GEN_TAC THEN REWRITE_TAC[drop] THEN
  SUBGOAL_THEN
    `fstcart(sndcart(z:real^(1,(1,1)finite_sum)finite_sum))$1 = sndcart z$1`
    SUBST1_TAC THENL
   [MATCH_MP_TAC FSTCART_COMPONENT THEN
     REWRITE_TAC[DIMINDEX_1; LE_REFL]; ALL_TAC] THEN
  SUBGOAL_THEN
    `sndcart(z:real^(1,(1,1)finite_sum)finite_sum)$1 = z$(1 + dimindex(:1))`
    SUBST1_TAC THENL
   [MATCH_MP_TAC SNDCART_COMPONENT THEN
    REWRITE_TAC[DIMINDEX_FINITE_SUM; DIMINDEX_1; ARITH]; ALL_TAC] THEN
  REWRITE_TAC[DIMINDEX_1] THEN CONV_TAC NUM_REDUCE_CONV);;

(* the alpha-zero-set is the negligible standard hyperplane {z$2 = 0}.       *)
let AMDT_ALPHA_HYP_NEG = prove
 (`negligible {z:real^(1,(1,1)finite_sum)finite_sum | drop(fstcart(sndcart z))
   = &0}`,
  REWRITE_TAC[AMDT_ALPHA_EQ_C2; NEGLIGIBLE_STANDARD_HYPERPLANE]);;

(* inv(alpha) is measurable on the iterated type.                            *)
let AMDT_INV_ALPHA_MEASURABLE = prove
 (`(\z:real^(1,(1,1)finite_sum)finite_sum. lift(inv(drop(fstcart(sndcart z)))))
   measurable_on (:real^(1,(1,1)finite_sum)finite_sum)`,
  MATCH_MP_TAC MEASURABLE_ON_LIFT_INV THEN
  REWRITE_TAC[AMDT_ALPHA_MEASURABLE] THEN
  MP_TAC AMDT_ALPHA_HYP_NEG THEN MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_UNIV]);;

(* the box F x [1,2] x [0,n] on the iterated type is lebesgue_measurable     *)
(* (= lift-FF PCROSS interval-box, all factors measurable).                  *)
let CARLESON_BOX_MEASURABLE = prove
 (`!FF n. real_measurable FF
   ==> lebesgue_measurable
        {z:real^(1,(1,1)finite_sum)finite_sum |
           drop(fstcart z) IN FF /\
           &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
           &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `{z:real^(1,(1,1)finite_sum)finite_sum |
       drop(fstcart z) IN FF /\
       &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
       &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n} =
    (IMAGE lift FF) PCROSS
    ((interval[lift(&1),lift(&2)]) PCROSS (interval[lift(&0),lift(&n)]))`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; FORALL_PASTECART; PASTECART_IN_PCROSS; IN_ELIM_THM;
                FSTCART_PASTECART; SNDCART_PASTECART; IN_IMAGE_LIFT_DROP;
                  IN_INTERVAL_1] THEN
    REWRITE_TAC[LIFT_DROP] THEN CONV_TAC TAUT; ALL_TAC] THEN
  SUBGOAL_THEN `lebesgue_measurable(IMAGE lift FF)` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM REAL_LEBESGUE_MEASURABLE] THEN
    MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[LEBESGUE_MEASURABLE_PCROSS; LEBESGUE_MEASURABLE_INTERVAL]);;

(* the box-restricted (1/alpha)-weighted amd kernel is MEASURABLE (RESTRICT  *)
(* of the product inv(alpha)*amd to the lebesgue-measurable box).            *)
let AMDT_BOX_KERNEL_MEAS = prove
 (`!(h:real->complex) FF n. schwartz h /\ real_measurable FF
   ==> (\z:real^(1,(1,1)finite_sum)finite_sum.
          if drop(fstcart z) IN FF /\
             &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2
               /\
             &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n
          then lift(inv(drop(fstcart(sndcart z))) *
                    (if drop(fstcart(sndcart z)) > &0
                     then carleson_amd h (drop(fstcart(sndcart z)))
                                         (drop(sndcart(sndcart z)))
                                           (drop(fstcart z))
                     else &0))
          else vec 0)
       measurable_on (:real^(1,(1,1)finite_sum)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\z:real^(1,(1,1)finite_sum)finite_sum.
        lift(inv(drop(fstcart(sndcart z))) *
             (if drop(fstcart(sndcart z)) > &0
              then carleson_amd h (drop(fstcart(sndcart z)))
                                  (drop(sndcart(sndcart z))) (drop(fstcart z))
              else &0))`;
    `{z:real^(1,(1,1)finite_sum)finite_sum |
       drop(fstcart z) IN FF /\
       &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
       &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n}`]
   MEASURABLE_ON_RESTRICT) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_LIFT_MUL THEN
    REWRITE_TAC[AMDT_INV_ALPHA_MEASURABLE] THEN
    MP_TAC(ISPEC `h:real->complex` AMDT_PROD_MEASURABLE) THEN
      ASM_REWRITE_TAC[];
    MATCH_MP_TAC CARLESON_BOX_MEASURABLE THEN ASM_REWRITE_TAC[]]);;

(* the box kernel is ABSOLUTELY INTEGRABLE: dominated by the constant        *)
(* K = sqrt(2pi) int|hhat| on the finite-measure box (AMD_UNIF_BOUND, and    *)
(* inv(alpha)<=1 for alpha>=1); the dominator K % 1_box is integrable.       *)
let AMDT_BOX_ABSINT = prove
 (`!(h:real->complex) FF n. schwartz h /\ real_measurable FF
   ==> (\z:real^(1,(1,1)finite_sum)finite_sum.
          if drop(fstcart z) IN FF /\
             &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2
               /\
             &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n
          then lift(inv(drop(fstcart(sndcart z))) *
                    (if drop(fstcart(sndcart z)) > &0
                     then carleson_amd h (drop(fstcart(sndcart z)))
                                         (drop(sndcart(sndcart z)))
                                           (drop(fstcart z))
                     else &0))
          else vec 0)
       absolutely_integrable_on (:real^(1,(1,1)finite_sum)finite_sum)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `K = sqrt(&2 * pi) * drop(integral (:real^1) (\y.
    lift(norm(fourier (h:real->complex) (drop y)))))` THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC
   `\z:real^(1,(1,1)finite_sum)finite_sum.
       K % indicator
         {z:real^(1,(1,1)finite_sum)finite_sum |
            drop(fstcart z) IN FF /\
            &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
            &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n}
              z` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC AMDT_BOX_KERNEL_MEAS THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC INTEGRABLE_CMUL THEN REWRITE_TAC[ETA_AX] THEN
    REWRITE_TAC[INTEGRABLE_ON_INDICATOR; INTER_UNIV] THEN
    SUBGOAL_THEN
     `{z:real^(1,(1,1)finite_sum)finite_sum |
         drop(fstcart z) IN FF /\
         &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
         &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n} =
      (IMAGE lift FF) PCROSS
      ((interval[lift(&1),lift(&2)]) PCROSS (interval[lift(&0),lift(&n)]))`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; FORALL_PASTECART; PASTECART_IN_PCROSS;
       IN_ELIM_THM;
                  FSTCART_PASTECART; SNDCART_PASTECART; IN_IMAGE_LIFT_DROP;
                    IN_INTERVAL_1] THEN
      REWRITE_TAC[LIFT_DROP] THEN CONV_TAC TAUT; ALL_TAC] THEN
    SUBGOAL_THEN `measurable(IMAGE lift FF)` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE] THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[MEASURABLE_PCROSS; MEASURABLE_INTERVAL];
    X_GEN_TAC `z:real^(1,(1,1)finite_sum)finite_sum` THEN
      REWRITE_TAC[IN_UNIV] THEN
    REWRITE_TAC[indicator; IN_ELIM_THM; DROP_CMUL] THEN
    SUBGOAL_THEN `&0 <= K` ASSUME_TAC THENL
     [EXPAND_TAC "K" THEN MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC SQRT_POS_LE THEN MP_TAC PI_POS THEN REAL_ARITH_TAC;
        MATCH_MP_TAC INTEGRAL_DROP_POS THEN
        REWRITE_TAC[LIFT_DROP; NORM_POS_LE] THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
        MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
          ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    COND_CASES_TAC THEN
    ASM_REWRITE_TAC[NORM_0; DROP_VEC; REAL_MUL_RZERO; REAL_LE_REFL] THEN
    REWRITE_TAC[REAL_MUL_RID; NORM_LIFT] THEN
    SUBGOAL_THEN
      `drop(fstcart(sndcart(z:real^(1,(1,1)finite_sum)finite_sum))) > &0`
     ASSUME_TAC THENL [REWRITE_TAC[real_gt] THEN
       ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `&1 * carleson_amd h
      (drop(fstcart(sndcart(z:real^(1,(1,1)finite_sum)finite_sum))))
                      (drop(sndcart(sndcart z))) (drop(fstcart z))` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[REAL_ABS_MUL] THEN MATCH_MP_TAC REAL_LE_MUL2 THEN
      REWRITE_TAC[REAL_ABS_POS] THEN REPEAT CONJ_TAC THENL
       [REWRITE_TAC[REAL_ABS_INV] THEN MATCH_MP_TAC REAL_INV_LE_1 THEN
         ASM_REAL_ARITH_TAC;
        REWRITE_TAC[real_abs] THEN COND_CASES_TAC THEN
          REWRITE_TAC[REAL_LE_REFL] THEN
        POP_ASSUM MP_TAC THEN
        MP_TAC(ISPECL
         [`h:real->complex`;
          `drop(fstcart(sndcart(z:real^(1,(1,1)finite_sum)finite_sum)))`;
          `drop(sndcart(sndcart(z:real^(1,(1,1)finite_sum)finite_sum)))`;
          `drop(fstcart(z:real^(1,(1,1)finite_sum)finite_sum))`]
         AMD_NONNEG) THEN
        ASM_SIMP_TAC[GSYM real_gt] THEN REAL_ARITH_TAC];
      REWRITE_TAC[REAL_MUL_LID] THEN FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN
      MATCH_MP_TAC AMD_UNIF_BOUND THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC]]);;

(* Vector<->real bridge for an outer x-integral restricted to FF: the        *)
(* (:real^1)                                                                 *)
(* integral of (if drop x IN FF then lift(g(drop x)) else 0) is lift of the  *)
(* real_integral of g over FF. Reused when peeling the x-in-FF indicator in  *)
(* the                                                                       *)
(* box-Tonelli reassembly (SINNER_INT_F_SWAP).                               *)
let CARLESON_OUTER_REAL_BRIDGE = prove
 (`!(g:real->real) FF. (g real_integrable_on FF)
   ==> integral (:real^1) (\x. if drop x IN FF then lift(g(drop x)) else vec 0)
     =
       lift(real_integral FF g)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(SUBST1_TAC o MATCH_MP REAL_INTEGRAL) THEN
  REWRITE_TAC[LIFT_DROP] THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM INTEGRAL_RESTRICT_UNIV] THEN
  AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
  REWRITE_TAC[IN_IMAGE_LIFT_DROP; o_THM] THEN
  COND_CASES_TAC THEN REWRITE_TAC[]);;

(* Interval version of the vector<->real bridge (for peeling the a-in-[1,2]  *)
(* and b-in-[0,n] interval gates in the box-Tonelli reassembly).             *)
let CARLESON_INTERVAL_REAL_BRIDGE = prove
 (`!(g:real->real) c d. (g real_integrable_on real_interval[c,d])
   ==> integral (:real^1) (\t. if c <= drop t /\ drop t <= d then lift(g(drop
     t)) else vec 0) =
       lift(real_integral (real_interval[c,d]) g)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(SUBST1_TAC o MATCH_MP REAL_INTEGRAL) THEN
  REWRITE_TAC[LIFT_DROP] THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM INTEGRAL_RESTRICT_UNIV] THEN
  AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `t:real^1` THEN
  REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL; IN_IMAGE_LIFT_DROP;
    IN_REAL_INTERVAL; o_THM] THEN
  COND_CASES_TAC THEN REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Per-slice integrability of the amd kernel (needed for the box-Tonelli     *)
(* reassembly to connect to carleson_Sinner's nested-real-integral           *)
(* definition).                                                              *)
(* The b-slice b|->amd h a b xf is LSC (sup of the b-continuous windows),    *)
(* hence                                                                     *)
(* Borel measurable, and bounded by K (AMD_UNIF_BOUND), hence integrable on  *)
(* any                                                                       *)
(* finite interval.  Mirrors AMD_JOINT_LSC in 1D.                            *)
(* ------------------------------------------------------------------------- *)
(* each amd window is continuous in b (VZETA_CONTINUOUS_ON on the b-line).   *)
let WINDOW_BSLICE_CONT = prove
 (`!(h:real->complex) a x zeta. schwartz h /\ &0 < a
   ==> (\b. &2 * pi * norm(fourier(\w. fourier (carleson_modulate b
     (carleson_dilate a h)) w *
                    Cx(carleson_theta zeta w))(--(x/a)))) real_continuous_on
                      (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON; IMAGE_LIFT_UNIV] THEN
  SUBGOAL_THEN
   `(lift o (\b. &2 * pi * norm(fourier(\w. fourier (carleson_modulate b
     (carleson_dilate a h)) w *
                    Cx(carleson_theta zeta w))(--(x/a)))) o drop) =
    (\p:real^3. lift(&2 * pi * norm(fourier(\w. fourier (carleson_modulate
      (p$2) (carleson_dilate (p$1) h)) w *
                    Cx(carleson_theta zeta w))(--(p$3 / p$1))))) o (\t:real^1.
                      vector[a; drop t; x]:real^3)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN X_GEN_TAC `t:real^1` THEN
    REWRITE_TAC[VECTOR_3]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [ONCE_REWRITE_TAC[CONTINUOUS_ON_COMPONENTWISE_LIFT] THEN
    SIMP_TAC[DIMINDEX_3; FORALL_3; VECTOR_3] THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST; LIFT_DROP; CONTINUOUS_ON_ID];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
    EXISTS_TAC `{p:real^3 | p$1 > &0}` THEN CONJ_TAC THENL
     [MATCH_MP_TAC VZETA_CONTINUOUS_ON THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_ELIM_THM; VECTOR_3; IN_UNIV] THEN
      ASM_REWRITE_TAC[real_gt]]]);;

(* b-slice b|->amd h a b xf is real_measurable_on R (LSC via                 *)
(* WINDOW_BSLICE_CONT).                                                      *)
let AMD_BSLICE_MEASURABLE = prove
 (`!(h:real->complex) a xf. schwartz h /\ &0 < a
   ==> (\b. carleson_amd h a b xf) real_measurable_on (:real)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[real_measurable_on; IMAGE_LIFT_UNIV] THEN
  MATCH_MP_TAC MEASURABLE_ON_LSC_MULTI THEN
  X_GEN_TAC `c:real` THEN REWRITE_TAC[o_THM; LIFT_DROP] THEN
  ASM_CASES_TAC `c < &0` THENL
   [SUBGOAL_THEN
     `{x:real^1 | carleson_amd h a (drop x) xf > c} =
      (:real^1)` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_UNIV] THEN
      X_GEN_TAC `t:real^1` THEN REWRITE_TAC[real_gt] THEN
      MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `&0` THEN
        ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC AMD_NONNEG THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[OPEN_UNIV]];
    SUBGOAL_THEN
     `{x:real^1 | carleson_amd h a (drop x) xf > c} =
      UNIONS { {t:real^1 |
               &2 * pi * norm(fourier(\w. fourier (carleson_modulate (drop t)
                 (carleson_dilate a h)) w *
                      Cx(carleson_theta zeta w))(--(xf/a))) > c}
             | zeta IN (:real) }`
     SUBST1_TAC THENL
     [REWRITE_TAC[UNIONS_GSPEC; EXTENSION; IN_ELIM_THM; IN_UNIV] THEN
      X_GEN_TAC `t:real^1` THEN
      MP_TAC(ISPECL [`h:real->complex`; `a:real`; `drop(t:real^1)`; `xf:real`;
        `c:real`] AMD_SUP_GT) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC OPEN_UNIONS THEN
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN X_GEN_TAC `zeta:real` THEN
      MP_TAC(ISPECL [`h:real->complex`; `a:real`; `xf:real`;
        `zeta:real`] WINDOW_BSLICE_CONT) THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[REAL_CONTINUOUS_ON; IMAGE_LIFT_UNIV] THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `{t:real^1 |
          &2 * pi * norm(fourier(\w. fourier (carleson_modulate (drop t)
            (carleson_dilate a h)) w *
                 Cx(carleson_theta zeta w))(--(xf/a))) > c} =
        {t | t IN (:real^1) /\
             (lift o (\b. &2 * pi * norm(fourier(\w. fourier (carleson_modulate
               b (carleson_dilate a h)) w *
                 Cx(carleson_theta zeta w))(--(xf/a)))) o drop) t IN {u | drop
                   u > c}}`
       SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_UNIV; o_THM; LIFT_DROP];
         ALL_TAC] THEN
      MATCH_MP_TAC CONTINUOUS_OPEN_PREIMAGE THEN
      ASM_REWRITE_TAC[OPEN_UNIV; ETA_AX] THEN
      REWRITE_TAC[drop; OPEN_HALFSPACE_COMPONENT_GT]]]);;

(* b-slice integrable on any interval (measurable + bounded by K on finite   *)
(* meas).                                                                    *)
let AMD_BSLICE_INTEGRABLE = prove
 (`!(h:real->complex) a xf u v. schwartz h /\ &0 < a
   ==> (\b. carleson_amd h a b xf) real_integrable_on real_interval[u,v]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `(\b:real. sqrt(&2 * pi) *
     drop(integral (:real^1) (\y. lift(norm(fourier (h:real->complex) (drop
       y)))))):real->real` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN
    ASM_SIMP_TAC[SUBSET_UNIV; AMD_BSLICE_MEASURABLE;
      REAL_MEASURABLE_REAL_INTERVAL];
    REWRITE_TAC[REAL_INTEGRABLE_ON; o_DEF; LIFT_CMUL] THEN
    REWRITE_TAC[INTEGRABLE_ON_CONST] THEN DISJ2_TAC THEN
    REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE;
      REAL_MEASURABLE_REAL_INTERVAL];
    X_GEN_TAC `b:real` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`h:real->complex`; `a:real`; `b:real`;
      `xf:real`] AMD_UNIF_BOUND) THEN
    MP_TAC(ISPECL [`h:real->complex`; `a:real`; `b:real`;
      `xf:real`] AMD_NONNEG) THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC]);;

(* 2D joint (alpha,beta)-measurability of the amd kernel at fixed xf: for    *)
(* the fixed-x Step-C of the box-Tonelli (the (1,1)fs box integral of        *)
(* (1/a)amd). amd = sup_zeta of the (alpha,beta)-continuous windows          *)
(* (WINDOW_ABSLICE_CONT via VZETA_CONTINUOUS_ON o embedding), so LSC ->      *)
(* measurable (MEASURABLE_ON_LSC_MULTI). the (alpha,beta)-region {alpha>0}   *)
(* is open in R^2.                                                           *)
let ABREGION_OPEN = prove
 (`open {ab:real^(1,1)finite_sum | drop(fstcart ab) > &0}`,
  SUBGOAL_THEN
    `{ab:real^(1,1)finite_sum | drop(fstcart ab) > &0} =
    {ab:real^(1,1)finite_sum | ab$1 > &0}` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN AP_THM_TAC THEN
     AP_TERM_TAC THEN
    REWRITE_TAC[drop] THEN MATCH_MP_TAC FSTCART_COMPONENT THEN
      REWRITE_TAC[DIMINDEX_1; LE_REFL];
    REWRITE_TAC[OPEN_HALFSPACE_COMPONENT_GT]]);;

(* each amd window is jointly continuous in (alpha,beta) on {alpha>0} (2D).  *)
let WINDOW_ABSLICE_CONT = prove
 (`!(h:real->complex) xf zeta. schwartz h
   ==> (\ab:real^(1,1)finite_sum.
          lift(&2 * pi * norm(fourier(\w. fourier (carleson_modulate
            (drop(sndcart ab)) (carleson_dilate (drop(fstcart ab)) h)) w *
                    Cx(carleson_theta zeta w))(--(xf/(drop(fstcart ab)))))))
       continuous_on {ab:real^(1,1)finite_sum | drop(fstcart ab) > &0}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\ab:real^(1,1)finite_sum.
        lift(&2 * pi * norm(fourier(\w. fourier (carleson_modulate
          (drop(sndcart ab)) (carleson_dilate (drop(fstcart ab)) h)) w *
                    Cx(carleson_theta zeta w))(--(xf/(drop(fstcart ab))))))) =
    (\p:real^3. lift(&2 * pi * norm(fourier(\w. fourier (carleson_modulate
      (p$2) (carleson_dilate (p$1) h)) w *
                    Cx(carleson_theta zeta w))(--(p$3 / p$1))))) o
    (\ab:real^(1,1)finite_sum. vector[drop(fstcart ab); drop(sndcart ab);
      xf]:real^3)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN
     X_GEN_TAC `ab:real^(1,1)finite_sum` THEN
    REWRITE_TAC[VECTOR_3]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [ONCE_REWRITE_TAC[CONTINUOUS_ON_COMPONENTWISE_LIFT] THEN
    SIMP_TAC[DIMINDEX_3; FORALL_3; VECTOR_3] THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN CONJ_TAC THENL
     [SIMP_TAC[CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE; LINEAR_CONTINUOUS_ON;
       LINEAR_FSTCART; o_DEF; LIFT_DROP; ETA_AX];
      SIMP_TAC[CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE; LINEAR_CONTINUOUS_ON;
        LINEAR_SNDCART; o_DEF; LIFT_DROP; ETA_AX]];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN
    EXISTS_TAC `{p:real^3 | p$1 > &0}` THEN CONJ_TAC THENL
     [MATCH_MP_TAC VZETA_CONTINUOUS_ON THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_ELIM_THM; VECTOR_3]]]);;

(* hence each window's superlevel {alpha>0 /\ V_zeta > c} is open in R^2.    *)
let WINDOW_ABSLICE_SUPERLEVEL_OPEN = prove
 (`!(h:real->complex) xf zeta c. schwartz h
   ==> open {ab:real^(1,1)finite_sum | drop(fstcart ab) > &0 /\
               &2 * pi * norm(fourier(\w. fourier (carleson_modulate
                 (drop(sndcart ab)) (carleson_dilate (drop(fstcart ab)) h)) w *
                      Cx(carleson_theta zeta w))(--(xf/(drop(fstcart ab))))) >
                        c}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`(\ab:real^(1,1)finite_sum.
        lift(&2 * pi * norm(fourier(\w. fourier (carleson_modulate
          (drop(sndcart ab)) (carleson_dilate (drop(fstcart ab)) h)) w *
                    Cx(carleson_theta zeta w))(--(xf/(drop(fstcart ab)))))))`;
    `{ab:real^(1,1)finite_sum | drop(fstcart ab) > &0}`;
    `(:real^1)`;
      `{u:real^1 | drop u > c}`] CONTINUOUS_OPEN_IN_PREIMAGE_GEN) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[WINDOW_ABSLICE_CONT; SUBSET_UNIV] THEN
    REWRITE_TAC[SUBTOPOLOGY_UNIV; GSYM OPEN_IN; drop;
      OPEN_HALFSPACE_COMPONENT_GT]; ALL_TAC] THEN
  SUBGOAL_THEN
   `{x:real^(1,1)finite_sum | x IN {ab | drop(fstcart ab) > &0} /\
       (\ab:real^(1,1)finite_sum. lift(&2 * pi * norm(fourier(\w. fourier
         (carleson_modulate (drop(sndcart ab)) (carleson_dilate (drop(fstcart
         ab)) h)) w *
                    Cx(carleson_theta zeta w))(--(xf/(drop(fstcart ab))))))) x
                      IN {u | drop u > c}} =
    {ab:real^(1,1)finite_sum | drop(fstcart ab) > &0 /\
       &2 * pi * norm(fourier(\w. fourier (carleson_modulate (drop(sndcart ab))
         (carleson_dilate (drop(fstcart ab)) h)) w *
                    Cx(carleson_theta zeta w))(--(xf/(drop(fstcart ab))))) >
                      c}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; LIFT_DROP]; ALL_TAC] THEN
  REWRITE_TAC[OPEN_IN_OPEN] THEN
  DISCH_THEN(X_CHOOSE_THEN
    `t:real^(1,1)finite_sum->bool` STRIP_ASSUME_TAC) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC OPEN_INTER THEN
  ASM_REWRITE_TAC[ABREGION_OPEN]);;

(* 2D joint measurability of the amd kernel (junk 0 for alpha<=0).           *)
let AMD_ABSLICE_MEASURABLE = prove
 (`!(h:real->complex) xf. schwartz h
   ==> (\ab:real^(1,1)finite_sum.
          lift(if drop(fstcart ab) > &0
               then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) xf
                 else &0))
       measurable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MEASURABLE_ON_LSC_MULTI THEN
  X_GEN_TAC `c:real` THEN REWRITE_TAC[LIFT_DROP] THEN
  ASM_CASES_TAC `c < &0` THENL
   [SUBGOAL_THEN
     `{ab:real^(1,1)finite_sum | (if drop(fstcart ab) > &0
         then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) xf else &0)
           > c} = (:real^(1,1)finite_sum)`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_UNIV] THEN
      X_GEN_TAC `ab:real^(1,1)finite_sum` THEN COND_CASES_TAC THEN
        REWRITE_TAC[real_gt] THENL
       [MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `&0` THEN
         ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC AMD_NONNEG THEN ASM_REWRITE_TAC[GSYM real_gt];
        ASM_REAL_ARITH_TAC];
      REWRITE_TAC[OPEN_UNIV]];
    SUBGOAL_THEN
     `{ab:real^(1,1)finite_sum | (if drop(fstcart ab) > &0
         then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) xf else &0)
           > c} =
      UNIONS { {ab:real^(1,1)finite_sum | drop(fstcart ab) > &0 /\
               &2 * pi * norm(fourier(\w. fourier (carleson_modulate
                 (drop(sndcart ab)) (carleson_dilate (drop(fstcart ab)) h)) w *
                      Cx(carleson_theta zeta w))(--(xf/(drop(fstcart ab))))) >
                        c}
             | zeta IN (:real) }`
     SUBST1_TAC THENL
     [REWRITE_TAC[UNIONS_GSPEC; EXTENSION; IN_ELIM_THM; IN_UNIV] THEN
      X_GEN_TAC `ab:real^(1,1)finite_sum` THEN COND_CASES_TAC THENL
       [MP_TAC(ISPECL [`h:real->complex`;
         `drop(fstcart(ab:real^(1,1)finite_sum))`;
          `drop(sndcart(ab:real^(1,1)finite_sum))`; `xf:real`;
            `c:real`] AMD_SUP_GT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[GSYM real_gt]; ALL_TAC] THEN
        DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[real_gt] THEN ASM_REAL_ARITH_TAC];
      MATCH_MP_TAC OPEN_UNIONS THEN REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN
      X_GEN_TAC `zeta:real` THEN
      MATCH_MP_TAC WINDOW_ABSLICE_SUPERLEVEL_OPEN THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* The fixed-x (1,1)fs box kernel (1/a)amd on [1,2]x[0,n]: measurable + abs- *)
(* integrable. Feeds the fixed-x Step-C of the box-Tonelli (the (a,b)-double *)
(* integral of (1/a)amd at fixed xf = carleson_Sinner h n xf).               *)
(* ------------------------------------------------------------------------- *)
(* inv(alpha)=inv(drop(fstcart ab)) measurable on real^(1,1)fs.              *)
let INVA_ABSLICE_MEASURABLE = prove
 (`(\ab:real^(1,1)finite_sum. lift(inv(drop(fstcart ab)))) measurable_on
   (:real^(1,1)finite_sum)`,
  MATCH_MP_TAC MEASURABLE_ON_LIFT_INV THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    MATCH_MP_TAC LINEAR_CONTINUOUS_ON THEN
    SUBGOAL_THEN
      `(\ab:real^(1,1)finite_sum. lift(drop(fstcart ab))) =
      (fstcart:real^(1,1)finite_sum->real^1)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; LIFT_DROP]; ALL_TAC] THEN
    REWRITE_TAC[LINEAR_FSTCART];
    SUBGOAL_THEN
      `{ab:real^(1,1)finite_sum | ab IN (:real^(1,1)finite_sum) /\ drop
      (fstcart ab) = &0} =
                  {ab:real^(1,1)finite_sum | ab$1 = &0}` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_UNIV] THEN GEN_TAC THEN
      AP_THM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[drop] THEN
      MATCH_MP_TAC FSTCART_COMPONENT THEN REWRITE_TAC[DIMINDEX_1; LE_REFL];
      REWRITE_TAC[NEGLIGIBLE_STANDARD_HYPERPLANE]]]);;

(* the (1,1)fs box [1,2]x[0,n] is measurable (finite).                       *)
let ABBOX_MEASURABLE = prove
 (`!n. measurable {ab:real^(1,1)finite_sum |
           &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
           &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n}`,
  GEN_TAC THEN
  SUBGOAL_THEN
   `{ab:real^(1,1)finite_sum |
       &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
       &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n} =
    (interval[lift(&1),lift(&2)]) PCROSS (interval[lift(&0),lift(&n)])`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; FORALL_PASTECART; PASTECART_IN_PCROSS;
                IN_ELIM_THM; FSTCART_PASTECART; SNDCART_PASTECART;
                  IN_INTERVAL_1; LIFT_DROP] THEN
    REWRITE_TAC[CONJ_ACI];
    SIMP_TAC[MEASURABLE_PCROSS; MEASURABLE_INTERVAL]]);;

(* =================================================================         *)
(* real^(1,1)finite_sum <-> real^2 shuffle, to port the real^2 2D            *)
(* theta' measurability to the FUBINI-usable fs type (fstcart=a,             *)
(* sndcart=b), for the inner (a,b)-Fubini of the w-outer side.               *)
(* =================================================================         *)
let SHUF2_LINEAR = prove
 (`linear (\z:real^(1,1)finite_sum. vector[drop(fstcart z);
   drop(sndcart z)]:real^2) /\
   (!u v:real^(1,1)finite_sum. (\z. vector[drop(fstcart z);
     drop(sndcart z)]:real^2) u =
      (\z. vector[drop(fstcart z); drop(sndcart z)]:real^2) v ==> u = v)`,
  CONJ_TAC THENL
   [REWRITE_TAC[linear] THEN CONJ_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2] THEN
    SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VECTOR_2; DIMINDEX_2;
      ARITH] THEN
    REWRITE_TAC[FSTCART_ADD; SNDCART_ADD; FSTCART_CMUL; SNDCART_CMUL; DROP_ADD;
      DROP_CMUL] THEN
    REWRITE_TAC[VECTOR_2] THEN REAL_ARITH_TAC;
    REPEAT GEN_TAC THEN REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `drop(fstcart(u:real^(1,1)finite_sum)) = drop(fstcart v) /\ drop(sndcart
       u) = drop(sndcart v)`
     STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM MP_TAC THEN
       REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2] THEN
       SIMP_TAC[]; ALL_TAC] THEN
    ONCE_REWRITE_TAC[PASTECART_EQ] THEN CONJ_TAC THEN
    ONCE_REWRITE_TAC[GSYM DROP_EQ] THEN ASM_REWRITE_TAC[]]);;

let SHUF2_IMAGE = prove
 (`IMAGE (\z:real^(1,1)finite_sum. vector[drop(fstcart z);
   drop(sndcart z)]:real^2) (:real^(1,1)finite_sum) = (:real^2)`,
  MATCH_MP_TAC SURJECTIVE_IMAGE_EQ THEN REWRITE_TAC[IN_UNIV] THEN
  X_GEN_TAC `p:real^2` THEN
  EXISTS_TAC `pastecart (lift((p:real^2)$1)) (lift(p$2)):real^(1,1)finite_sum`
    THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART; LIFT_DROP] THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_2; FORALL_2; VECTOR_2] THEN
  CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[]);;

let SHUF2C = prove
 (`!hh:real^2->complex.
     (hh o (\z:real^(1,1)finite_sum. vector[drop(fstcart z);
       drop(sndcart z)]:real^2))
       measurable_on (:real^(1,1)finite_sum)
     <=> hh measurable_on (:real^2)`,
  GEN_TAC THEN
  MP_TAC(ISPECL
   [`\z:real^(1,1)finite_sum. vector[drop(fstcart z); drop(sndcart z)]:real^2`;
    `hh:real^2->complex`;
      `(:real^(1,1)finite_sum)`] MEASURABLE_ON_LINEAR_IMAGE_EQ_GEN) THEN
  REWRITE_TAC[SHUF2_LINEAR; DIMINDEX_FINITE_SUM; DIMINDEX_1; DIMINDEX_2;
    ARITH] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[SHUF2_IMAGE]);;

let CX_THETA2FS_MEASURABLE = prove
 (`!z0:real w:real. (\z:real^(1,1)finite_sum. Cx(carleson_theta' z0
   (drop(fstcart z)) (drop(sndcart z)) w))
    measurable_on (:real^(1,1)finite_sum)`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPEC `\p:real^2. Cx(carleson_theta' z0 (p$1) (p$2) w)` SHUF2C) THEN
  REWRITE_TAC[CX_THETA2_MEASURABLE] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM; o_THM] THEN GEN_TAC THEN REWRITE_TAC[VECTOR_2]);;

let CX_INVAFS_MEASURABLE = prove
 (`(\z:real^(1,1)finite_sum. Cx(inv(drop(fstcart z)))) measurable_on
   (:real^(1,1)finite_sum)`,
  MP_TAC(ISPEC `\p:real^2. Cx(inv(p$1))` SHUF2C) THEN
  REWRITE_TAC[CX_INVA2_MEASURABLE] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM; o_THM] THEN GEN_TAC THEN REWRITE_TAC[VECTOR_2]);;

let MNF_ABKERNEL_FS_ABSINT = prove
 (`!z0:real w:real n:num.
     (\ab:real^(1,1)finite_sum.
        if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
           &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
        then Cx(inv(drop(fstcart ab))) * Cx(carleson_theta' z0 (drop(fstcart
          ab)) (drop(sndcart ab)) w) else vec 0)
     absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC
   `\ab:real^(1,1)finite_sum.
       if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
          &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
       then lift(&1) else vec 0` THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\ab:real^(1,1)finite_sum.
        if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
           &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
        then Cx(inv(drop(fstcart ab))) * Cx(carleson_theta' z0 (drop(fstcart
          ab)) (drop(sndcart ab)) w) else vec 0) =
      (\ab:real^(1,1)finite_sum.
        if ab IN {ab:real^(1,1)finite_sum | &1 <= drop(fstcart ab) /\
          drop(fstcart ab) <= &2 /\
                     &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n}
        then Cx(inv(drop(fstcart ab))) * Cx(carleson_theta' z0 (drop(fstcart
          ab)) (drop(sndcart ab)) w) else vec 0)`
     SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
     [MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN
      REWRITE_TAC[CX_INVAFS_MEASURABLE; CX_THETA2FS_MEASURABLE];
      MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN
        REWRITE_TAC[ABBOX_MEASURABLE]];
    SUBGOAL_THEN
     `(\ab:real^(1,1)finite_sum. if &1 <= drop(fstcart ab) /\ drop(fstcart ab)
       <= &2 /\
          &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n then lift(&1) else
            vec 0) =
      (\ab:real^(1,1)finite_sum. if ab IN {ab:real^(1,1)finite_sum | &1 <=
        drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
          &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n} then lift(&1) else
            vec 0)`
     SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
    REWRITE_TAC[INTEGRABLE_RESTRICT_UNIV; INTEGRABLE_ON_CONST] THEN
      DISJ2_TAC THEN
    REWRITE_TAC[ABBOX_MEASURABLE];
    X_GEN_TAC `ab:real^(1,1)finite_sum` THEN REWRITE_TAC[IN_UNIV] THEN
      COND_CASES_TAC THEN
    REWRITE_TAC[NORM_0; NORM_LIFT; LIFT_DROP; DROP_VEC; REAL_ABS_NUM;
      REAL_LE_REFL] THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `abs(inv(drop(fstcart(ab:real^(1,1)finite_sum)))) * &1` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[REAL_ABS_POS] THEN
      MP_TAC(ISPECL [`z0:real`; `drop(fstcart(ab:real^(1,1)finite_sum))`;
        `drop(sndcart(ab:real^(1,1)finite_sum))`;
        `w:real`] CARLESON_THETA'_BOUNDS) THEN REAL_ARITH_TAC;
      REWRITE_TAC[REAL_MUL_RID] THEN MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `abs(inv(&1))` THEN CONJ_TAC THENL
       [REWRITE_TAC[REAL_ABS_INV] THEN MATCH_MP_TAC REAL_LE_INV2 THEN
         ASM_REAL_ARITH_TAC;
        CONV_TAC REAL_RAT_REDUCE_CONV]]]);;

(* the box-restricted (1/a)amd kernel at fixed xf is MEASURABLE on           *)
(* real^(1,1)fs. NB the box-lebesgue-measurable leg via                      *)
(* MEASURABLE_IMP_LEBESGUE_MEASURABLE (the indicator/GSYM                    *)
(* INTEGRABLE_ON_INDICATOR route TIMES OUT >150s here).                      *)
let AMD_ABBOX_KERNEL_MEAS = prove
 (`!(h:real->complex) n xf. schwartz h
   ==> (\ab:real^(1,1)finite_sum.
          if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
             &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
          then lift(inv(drop(fstcart ab)) *
                    (if drop(fstcart ab) > &0
                     then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab))
                       xf else &0))
          else vec 0)
       measurable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\ab:real^(1,1)finite_sum.
        lift(inv(drop(fstcart ab)) *
             (if drop(fstcart ab) > &0
              then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) xf else
                &0))`;
    `{ab:real^(1,1)finite_sum |
       &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
       &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n}`]
   MEASURABLE_ON_RESTRICT) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_LIFT_MUL THEN
    REWRITE_TAC[INVA_ABSLICE_MEASURABLE] THEN
    MP_TAC(ISPECL [`h:real->complex`; `xf:real`] AMD_ABSLICE_MEASURABLE) THEN
      ASM_REWRITE_TAC[];
    MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN
      REWRITE_TAC[ABBOX_MEASURABLE]]);;

(* 2D box kernel at fixed xf: (1/a)amd on [1,2]x[0,n], abs-integrable (const *)
(* domin).                                                                   *)
let AMD_ABBOX_ABSINT = prove
 (`!(h:real->complex) n xf. schwartz h
   ==> (\ab:real^(1,1)finite_sum.
          if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
             &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
          then lift(inv(drop(fstcart ab)) *
                    (if drop(fstcart ab) > &0
                     then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab))
                       xf else &0))
          else vec 0)
       absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `K = sqrt(&2 * pi) * drop(integral (:real^1) (\y.
    lift(norm(fourier (h:real->complex) (drop y)))))` THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC
   `\ab:real^(1,1)finite_sum.
       K % indicator
         {ab:real^(1,1)finite_sum |
            &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
            &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n} ab` THEN
  REPEAT CONJ_TAC THENL
   [ASM_SIMP_TAC[AMD_ABBOX_KERNEL_MEAS];
    MATCH_MP_TAC INTEGRABLE_CMUL THEN REWRITE_TAC[ETA_AX] THEN
    REWRITE_TAC[INTEGRABLE_ON_INDICATOR; INTER_UNIV] THEN
    REWRITE_TAC[GSYM MEASURABLE_INTEGRABLE; ABBOX_MEASURABLE];
    X_GEN_TAC `ab:real^(1,1)finite_sum` THEN REWRITE_TAC[IN_UNIV] THEN
    REWRITE_TAC[indicator; IN_ELIM_THM; DROP_CMUL] THEN
    SUBGOAL_THEN `&0 <= K` ASSUME_TAC THENL
     [EXPAND_TAC "K" THEN MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC SQRT_POS_LE THEN MP_TAC PI_POS THEN REAL_ARITH_TAC;
        MATCH_MP_TAC INTEGRAL_DROP_POS THEN
        REWRITE_TAC[LIFT_DROP; NORM_POS_LE] THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
        MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
          ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    COND_CASES_TAC THEN
    ASM_REWRITE_TAC[NORM_0; DROP_VEC; REAL_MUL_RZERO; REAL_LE_REFL] THEN
    REWRITE_TAC[REAL_MUL_RID; NORM_LIFT] THEN
    SUBGOAL_THEN `drop(fstcart(ab:real^(1,1)finite_sum)) > &0` ASSUME_TAC THENL
     [REWRITE_TAC[real_gt] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `&1 * carleson_amd h (drop(fstcart(ab:real^(1,1)finite_sum)))
                      (drop(sndcart ab)) xf` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[REAL_ABS_MUL] THEN MATCH_MP_TAC REAL_LE_MUL2 THEN
      REWRITE_TAC[REAL_ABS_POS] THEN REPEAT CONJ_TAC THENL
       [REWRITE_TAC[REAL_ABS_INV] THEN MATCH_MP_TAC REAL_INV_LE_1 THEN
         ASM_REAL_ARITH_TAC;
        REWRITE_TAC[real_abs] THEN COND_CASES_TAC THEN
          REWRITE_TAC[REAL_LE_REFL] THEN
        POP_ASSUM MP_TAC THEN
        MP_TAC(ISPECL [`h:real->complex`;
          `drop(fstcart(ab:real^(1,1)finite_sum))`;
                       `drop(sndcart(ab:real^(1,1)finite_sum))`;
                         `xf:real`] AMD_NONNEG) THEN
        ASM_SIMP_TAC[GSYM real_gt] THEN REAL_ARITH_TAC];
      REWRITE_TAC[REAL_MUL_LID] THEN FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN
      MATCH_MP_TAC AMD_UNIF_BOUND THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* Fixed-x Step-C of the box-Tonelli: the (a,b)-box integral of (1/a)amd at  *)
(* fixed xf equals carleson_Sinner h n xf. a-outer FUBINI_INTEGRAL on the    *)
(* box                                                                       *)
(* kernel (AMD_ABBOX_ABSINT) + inner b-gate pull +                           *)
(* CARLESON_INTERVAL_REAL_BRIDGE                                             *)
(* twice.  Feeds SIDE-A (int_FF Sinner) of SINNER_INT_F_SWAP.                *)
(* ------------------------------------------------------------------------- *)
(* the inner b-integral at fixed x (STEPC_INNER).                            *)
let STEPC_INNER = prove
 (`!(h:real->complex) n xf x. schwartz h
   ==> integral (:real^1)
         (\y. if &1 <= drop x /\ drop x <= &2 /\ &0 <= drop y /\ drop y <= &n
              then lift(inv(drop x) * (if drop x > &0 then carleson_amd h (drop
                x) (drop y) xf else &0))
              else vec 0) =
       (if &1 <= drop x /\ drop x <= &2
        then lift(inv(drop x) * real_integral (real_interval[&0,&n]) (\beta.
          carleson_amd h (drop x) beta xf))
        else vec 0)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THENL
   [SUBGOAL_THEN `drop x > &0` ASSUME_TAC THENL [REWRITE_TAC[real_gt] THEN
     ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`\b. inv(drop(x:real^1)) * carleson_amd h (drop x) b xf`;
      `&0:real`; `&n:real`] CARLESON_INTERVAL_REAL_BRIDGE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
      MATCH_MP_TAC AMD_BSLICE_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    AP_TERM_TAC THEN MATCH_MP_TAC REAL_INTEGRAL_LMUL THEN
    MATCH_MP_TAC AMD_BSLICE_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC;
    SUBGOAL_THEN
      `(\y:real^1. if &1 <= drop x /\ drop x <= &2 /\ &0 <= drop y /\
       drop y <= &n
              then lift(inv(drop x) * (if drop x > &0 then carleson_amd h (drop
                x) (drop y) xf else &0)) else vec 0) = (\y:real^1. vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN COND_CASES_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; REWRITE_TAC[INTEGRAL_0]]]);;

(* the a-iterate (\a. inv a * int_[0,n] amd) real_integrable on [1,2].       *)
(* Derived from AMD_ABBOX_ABSINT via FUBINI_ABSOLUTELY_INTEGRABLE (x-outer): *)
(* the box kernel's a-iterate = if 1<=a<=2 then lift(inv a*int amd) else 0   *)
(* (STEPC_INNER) is integrable on UNIV, hence its [1,2]-restriction (=raw fn *)
(* there) integrable.                                                        *)
let A_ITERATE_INTEGRABLE = prove
 (`!(h:real->complex) n xf. schwartz h /\ ~(n = 0)
   ==> (\alpha. inv alpha * real_integral (real_interval[&0,&n]) (\beta.
     carleson_amd h alpha beta xf))
       real_integrable_on real_interval[&1,&2]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_INTEGRABLE_EQ THEN
  EXISTS_TAC
   `\alpha. if &1 <= alpha /\ alpha <= &2
            then inv alpha * real_integral (real_interval[&0,&n]) (\beta.
              carleson_amd h alpha beta xf)
            else &0` THEN
  CONJ_TAC THENL
   [X_GEN_TAC `a:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRABLE_ON_SUBINTERVAL THEN
  EXISTS_TAC `(:real)` THEN REWRITE_TAC[SUBSET_UNIV] THEN
  REWRITE_TAC[REAL_INTEGRABLE_ON; IMAGE_LIFT_UNIV] THEN
  MP_TAC(ISPECL [`h:real->complex`; `n:num`; `xf:real`] AMD_ABBOX_ABSINT) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o MATCH_MP FUBINI_ABSOLUTELY_INTEGRABLE) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  ASM_SIMP_TAC[STEPC_INNER] THEN
  DISCH_THEN(MP_TAC o MATCH_MP HAS_INTEGRAL_INTEGRABLE o CONJUNCT2) THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM; o_THM] THEN X_GEN_TAC `a:real^1` THEN
  REWRITE_TAC[LIFT_DROP] THEN COND_CASES_TAC THEN REWRITE_TAC[LIFT_NUM]);;

(* Fixed-x Step-C: the (a,b)-box integral of (1/a)amd at fixed xf = Sinner h *)
(* n xf.                                                                     *)
let SINNER_FIXEDX = prove
 (`!(h:real->complex) n xf. schwartz h /\ ~(n = 0)
   ==> drop(integral (:real^(1,1)finite_sum)
         (\ab. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                  &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then lift(inv(drop(fstcart ab)) *
                    (if drop(fstcart ab) > &0
                     then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab))
                       xf else &0))
               else vec 0)) =
       carleson_Sinner h n xf`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Sinner] THEN
  MP_TAC(ISPECL [`h:real->complex`; `n:num`; `xf:real`] AMD_ABBOX_ABSINT) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> ONCE_REWRITE_TAC[MATCH_MP FUBINI_INTEGRAL th]) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  ASM_SIMP_TAC[STEPC_INNER] THEN
  MP_TAC(ISPECL [`\alpha. inv alpha * real_integral (real_interval[&0,&n])
    (\beta. carleson_amd h alpha beta xf)`;
                 `&1:real`; `&2:real`] CARLESON_INTERVAL_REAL_BRIDGE) THEN
  ANTS_TAC THENL [MATCH_MP_TAC A_ITERATE_INTEGRABLE THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[LIFT_DROP]);;

(* ------------------------------------------------------------------------- *)
(* Box-Tonelli SIDE-A: drop(int over the 3D box kernel K3) = int_FF Sinner.  *)
(* K3(z) = (1/a)amd restricted to FF x [1,2] x [0,n] (x=fstcart,             *)
(* (a,b)=sndcart).                                                           *)
(* ------------------------------------------------------------------------- *)
(* the amd x-slice is real_integrable on FF (a>0): carleson_A(moddil)(./a),  *)
(* HAS_REAL_INTEGRAL_DILATE_SET from CARLESON_A_INTEGRABLE on (1/a)FF.       *)
let AMD_XSLICE_INTEGRABLE = prove
 (`!(h:real->complex) a b FF. schwartz h /\ &0 < a /\ real_measurable FF
   ==> (\x. carleson_amd h a b x) real_integrable_on FF`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_amd] THEN
  SUBGOAL_THEN
   `(\x. carleson_A (carleson_modulate b (carleson_dilate a h)) (x / a)) =
    (\x. carleson_A (carleson_modulate b (carleson_dilate a (h:real->complex)))
      (inv a * x))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[real_div] THEN REWRITE_TAC[REAL_MUL_SYM]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`carleson_A (carleson_modulate b (carleson_dilate a (h:real->complex)))`;
    `inv a:real`; `FF:real->bool`;
    `real_integral (IMAGE (\x. inv a * x) FF)
       (carleson_A (carleson_modulate b (carleson_dilate a
         (h:real->complex))))`]
   HAS_REAL_INTEGRAL_DILATE_SET) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LT_INV THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_INTEGRABLE_INTEGRAL THEN
      MATCH_MP_TAC CARLESON_A_INTEGRABLE THEN CONJ_TAC THENL
       [MATCH_MP_TAC CARLESON_SCHWARTZ_MODDIL THEN
         ASM_SIMP_TAC[REAL_LT_IMP_NZ];
        MATCH_MP_TAC REAL_MEASURABLE_SCALING THEN ASM_REWRITE_TAC[]]];
    REWRITE_TAC[real_integrable_on] THEN MESON_TAC[]]);;

(* the x-slice of K3 at fixed x = if x IN FF then lift Sinner else 0         *)
(* (SINNER_FIXEDX).                                                          *)
let K3_XSLICE = prove
 (`!(h:real->complex) FF n x. schwartz h /\ ~(n = 0)
   ==> integral (:real^(1,1)finite_sum)
         (\ab. (\z:real^(1,(1,1)finite_sum)finite_sum.
                  if drop(fstcart z) IN FF /\
                     &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z))
                       <= &2 /\
                     &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z))
                       <= &n
                  then lift(inv(drop(fstcart(sndcart z))) *
                       (if drop(fstcart(sndcart z)) > &0
                        then carleson_amd h (drop(fstcart(sndcart z)))
                          (drop(sndcart(sndcart z))) (drop(fstcart z))
                        else &0))
                  else vec 0) (pastecart x ab)) =
       (if drop x IN FF then lift(carleson_Sinner h n (drop x)) else vec 0)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  COND_CASES_TAC THENL
   [MP_TAC(ISPECL [`h:real->complex`; `n:num`;
     `drop(x:real^1)`] SINNER_FIXEDX) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[LIFT_DROP];
    SUBGOAL_THEN
      `(\ab:real^(1,1)finite_sum. if drop x IN FF /\ &1 <= drop(fstcart ab) /\
      drop(fstcart ab) <= &2 /\
                     &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
                  then lift(inv(drop(fstcart ab)) * (if drop(fstcart ab) > &0
                    then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab))
                    (drop x) else &0)) else vec 0) = (\ab:real^(1,1)finite_sum.
                     vec 0)`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
       ASM_REWRITE_TAC[]; REWRITE_TAC[INTEGRAL_0]]]);;

(* Sinner is real_integrable on FF (via FUBINI x-outer of K3 + K3_XSLICE).   *)
let SINNER_INTEGRABLE_F = prove
 (`!(h:real->complex) FF n. schwartz h /\ real_measurable FF /\ ~(n = 0)
   ==> (\x. carleson_Sinner h n x) real_integrable_on FF`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x:real. if x IN FF then carleson_Sinner h n x else &0) real_integrable_on
     (:real)`
   MP_TAC THENL
   [REWRITE_TAC[REAL_INTEGRABLE_ON; IMAGE_LIFT_UNIV] THEN
    MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`;
      `n:num`] AMDT_BOX_ABSINT) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o MATCH_MP FUBINI_ABSOLUTELY_INTEGRABLE) THEN
    ASM_SIMP_TAC[K3_XSLICE] THEN
    DISCH_THEN(MP_TAC o MATCH_MP HAS_INTEGRAL_INTEGRABLE o CONJUNCT2) THEN
    MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM; o_THM] THEN X_GEN_TAC `x:real^1` THEN
    REWRITE_TAC[LIFT_DROP] THEN COND_CASES_TAC THEN REWRITE_TAC[LIFT_NUM];
    REWRITE_TAC[REAL_INTEGRABLE_RESTRICT_UNIV; ETA_AX]]);;

(* SIDE-A: drop(int over 3D box of K3) = int_FF Sinner.                      *)
let SIDE_A = prove
 (`!(h:real->complex) FF n. schwartz h /\ real_measurable FF /\ ~(n = 0)
   ==> drop(integral (:real^(1,(1,1)finite_sum)finite_sum)
         (\z. if drop(fstcart z) IN FF /\
                 &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <=
                   &2 /\
                 &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <=
                   &n
              then lift(inv(drop(fstcart(sndcart z))) *
                   (if drop(fstcart(sndcart z)) > &0
                    then carleson_amd h (drop(fstcart(sndcart z)))
                      (drop(sndcart(sndcart z))) (drop(fstcart z))
                    else &0))
              else vec 0)) =
       real_integral FF (\x. carleson_Sinner h n x)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`;
    `n:num`] AMDT_BOX_ABSINT) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> ONCE_REWRITE_TAC[MATCH_MP FUBINI_INTEGRAL th]) THEN
  ASM_SIMP_TAC[K3_XSLICE] THEN
  MP_TAC(ISPECL [`\x. carleson_Sinner h n x`;
    `FF:real->bool`] CARLESON_OUTER_REAL_BRIDGE) THEN
  ASM_SIMP_TAC[SINNER_INTEGRABLE_F] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[LIFT_DROP]);;

(* the K3 (a,b)-slice at fixed ab = if 1<=a<=2 /\ 0<=b<=n then lift(inv      *)
(* a*int_FF amd) else 0.                                                     *)
let K3_ABSLICE = prove
 (`!(h:real->complex) FF n ab. schwartz h /\ real_measurable FF
   ==> integral (:real^1)
         (\x. (\z:real^(1,(1,1)finite_sum)finite_sum.
                  if drop(fstcart z) IN FF /\
                     &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z))
                       <= &2 /\
                     &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z))
                       <= &n
                  then lift(inv(drop(fstcart(sndcart z))) *
                       (if drop(fstcart(sndcart z)) > &0
                        then carleson_amd h (drop(fstcart(sndcart z)))
                          (drop(sndcart(sndcart z))) (drop(fstcart z))
                        else &0))
                  else vec 0) (pastecart x ab)) =
       (if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\ &0 <=
         drop(sndcart ab) /\ drop(sndcart ab) <= &n
        then lift(inv(drop(fstcart ab)) * real_integral FF (\x. carleson_amd h
          (drop(fstcart ab)) (drop(sndcart ab)) x))
        else vec 0)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  COND_CASES_TAC THENL
   [SUBGOAL_THEN `drop(fstcart(ab:real^(1,1)finite_sum)) > &0` ASSUME_TAC THENL
     [REWRITE_TAC[real_gt] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `(\x:real^1. if drop x IN FF then lift(inv(drop(fstcart ab)) *
       carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) (drop x)) else vec
        0) =
      (\x:real^1. if drop x IN FF then lift((\xx. inv(drop(fstcart ab)) *
        carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) xx)(drop x)) else
         vec 0)`
     SUBST1_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`\xx. inv(drop(fstcart(ab:real^(1,1)finite_sum))) *
      carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) xx`;
      `FF:real->bool`] CARLESON_OUTER_REAL_BRIDGE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
      MATCH_MP_TAC AMD_XSLICE_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN AP_TERM_TAC THEN
      MATCH_MP_TAC REAL_INTEGRAL_LMUL THEN
    MATCH_MP_TAC AMD_XSLICE_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
      ASM_REAL_ARITH_TAC;
    SUBGOAL_THEN
      `(\x:real^1. if drop x IN FF /\ &1 <= drop(fstcart ab) /\ drop(fstcart
      ab) <= &2 /\
                      &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
                   then lift(inv(drop(fstcart ab)) * (if drop(fstcart ab) > &0
                     then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab))
                     (drop x) else &0)) else vec 0) = (\x:real^1. vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN COND_CASES_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; REWRITE_TAC[INTEGRAL_0]]]);;

(* KFF = the (a,b)-partial-integral of K3, absolutely_integrable on          *)
(* real^(1,1)fs.                                                             *)
(* = FUBINI_HAS_ABSOLUTE_INTEGRAL_ALT (2nd conjunct) on K3 + K3_ABSLICE.     *)
(* Gives                                                                     *)
(* int K3 = int KFF, and KFF is the (1/a)int_FF amd box kernel used to BOUND *)
(* drop(int K3) directly (no exact SIDE-B nesting needed for                 *)
(* AAVG_INT_F_BOUND).                                                        *)
let KFF_ABSINT = prove
 (`!(h:real->complex) FF n. schwartz h /\ real_measurable FF /\ ~(n = 0)
   ==> (\ab:real^(1,1)finite_sum.
          if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\ &0 <=
            drop(sndcart ab) /\ drop(sndcart ab) <= &n
          then lift(inv(drop(fstcart ab)) * real_integral FF (\x. carleson_amd
            h (drop(fstcart ab)) (drop(sndcart ab)) x))
          else vec 0) absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`;
    `n:num`] AMDT_BOX_ABSINT) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1 o CONJUNCT2 o MATCH_MP
    FUBINI_HAS_ABSOLUTE_INTEGRAL_ALT) THEN
  ASM_SIMP_TAC[K3_ABSLICE]);;

(* ------------------------------------------------------------------------- *)
(* The constant-dominator box kernel (1/a)*M on [1,2]x[0,n]: abs-integrable  *)
(* +                                                                         *)
(* its integral = M*log2*n. KFF <= this pointwise (int_FF amd <=             *)
(* 4C9||h||sqrt                                                              *)
(* by AMD_INT_F_BOUND), so drop(int K3) = drop(int KFF) <= M*log2*n bounds   *)
(* the                                                                       *)
(* box integral for AAVG_INT_F_BOUND -- NO exact SIDE-B nesting needed.      *)
(* ------------------------------------------------------------------------- *)
let DOM_BOX_ABSINT = prove
 (`!M n. (\ab:real^(1,1)finite_sum.
          if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\ &0 <=
            drop(sndcart ab) /\ drop(sndcart ab) <= &n
          then lift(inv(drop(fstcart ab)) * M) else vec 0)
       absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC `\ab:real^(1,1)finite_sum. abs M % indicator
         {ab:real^(1,1)finite_sum | &1 <= drop(fstcart ab) /\ drop(fstcart ab)
           <= &2 /\ &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n} ab` THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`\ab:real^(1,1)finite_sum. lift(inv(drop(fstcart ab)) * M)`;
      `{ab:real^(1,1)finite_sum | &1 <= drop(fstcart ab) /\ drop(fstcart ab) <=
        &2 /\ &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n}`]
        MEASURABLE_ON_RESTRICT) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
     [MATCH_MP_TAC MEASURABLE_ON_LIFT_MUL THEN
       REWRITE_TAC[INVA_ABSLICE_MEASURABLE] THEN
      REWRITE_TAC[MEASURABLE_ON_CONST];
      MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN
        REWRITE_TAC[ABBOX_MEASURABLE]];
    MATCH_MP_TAC INTEGRABLE_CMUL THEN REWRITE_TAC[ETA_AX] THEN
    REWRITE_TAC[INTEGRABLE_ON_INDICATOR; INTER_UNIV] THEN
    REWRITE_TAC[GSYM MEASURABLE_INTEGRABLE; ABBOX_MEASURABLE];
    X_GEN_TAC `ab:real^(1,1)finite_sum` THEN REWRITE_TAC[IN_UNIV] THEN
    REWRITE_TAC[indicator; IN_ELIM_THM; DROP_CMUL] THEN COND_CASES_TAC THEN
    ASM_REWRITE_TAC[NORM_0; DROP_VEC; REAL_MUL_RZERO; REAL_LE_REFL; NORM_LIFT;
      REAL_MUL_RID] THEN
    REWRITE_TAC[REAL_ABS_MUL; REAL_ABS_INV] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&1 * abs M` THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[REAL_ABS_POS] THEN
      MATCH_MP_TAC REAL_INV_LE_1 THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_MUL_LID; REAL_LE_REFL]]]);;

(* the inner b-integral of the const dominator at fixed a.                   *)
let DOM_INNER = prove
 (`!M n a. integral (:real^1)
         (\y. if &1 <= drop a /\ drop a <= &2 /\ &0 <= drop y /\ drop y <= &n
              then lift(inv(drop a) * M) else vec 0) =
       (if &1 <= drop a /\ drop a <= &2 then lift(inv(drop a) * M * &n) else
         vec 0)`,
  REPEAT GEN_TAC THEN COND_CASES_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`\b:real. inv(drop(a:real^1)) * M`; `&0:real`;
      `&n:real`] CARLESON_INTERVAL_REAL_BRIDGE) THEN
    REWRITE_TAC[REAL_INTEGRABLE_CONST] THEN DISCH_THEN SUBST1_TAC THEN
    AP_TERM_TAC THEN SIMP_TAC[REAL_INTEGRAL_CONST; REAL_POS] THEN
      REAL_ARITH_TAC;
    SUBGOAL_THEN
      `(\y:real^1. if &1 <= drop a /\ drop a <= &2 /\ &0 <= drop y /\ drop y <=
      &n then lift(inv(drop a) * M) else vec 0) = (\y:real^1. vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN COND_CASES_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; REWRITE_TAC[INTEGRAL_0]]]);;

(* inv integrable + the (M,n)-weighted inv integral value on [1,2].          *)
let INV_INTEGRABLE_1_2 = prove
 (`(\a. inv a) real_integrable_on real_interval[&1,&2]`,
  MATCH_MP_TAC REAL_INTEGRABLE_CONTINUOUS THEN
  MATCH_MP_TAC REAL_CONTINUOUS_ON_INV THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON_ID; IN_REAL_INTERVAL] THEN
    REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC);;

let INV_MN_INTEGRAL_1_2 = prove
 (`!M n. real_integral (real_interval[&1,&2]) (\a. inv a * M * &n) = M * &n *
   log(&2)`,
  REPEAT GEN_TAC THEN
  ONCE_REWRITE_TAC[REAL_ARITH `inv a * M * &n = (M * &n) * inv a`] THEN
  MP_TAC(ISPECL [`\a:real. inv a`; `(M:real) * &n`;
    `real_interval[&1,&2]`] REAL_INTEGRAL_LMUL) THEN
  REWRITE_TAC[INV_INTEGRABLE_1_2] THEN BETA_TAC THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[INV_INTEGRAL_1_2_LOG2] THEN
    REAL_ARITH_TAC);;

(* the constant-dominator box integral value = M*log2*n.                     *)
let DOM_BOX_INTEGRAL = prove
 (`!M n. drop(integral (:real^(1,1)finite_sum)
         (\ab. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\ &0 <=
           drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then lift(inv(drop(fstcart ab)) * M) else vec 0)) =
       M * log(&2) * &n`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`M:real`; `n:num`] DOM_BOX_ABSINT) THEN
  DISCH_THEN(fun th -> ONCE_REWRITE_TAC[MATCH_MP FUBINI_INTEGRAL th]) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  REWRITE_TAC[DOM_INNER] THEN
  SUBGOAL_THEN
    `(\a:real. inv a * M * &n) real_integrable_on real_interval[&1,&2]`
    ASSUME_TAC THENL
   [ONCE_REWRITE_TAC[REAL_ARITH `inv a * M * &n = (M * &n) * inv a`] THEN
    MP_TAC(ISPECL [`\a:real. inv a`; `(M:real) * &n`;
      `real_interval[&1,&2]`] REAL_INTEGRABLE_LMUL) THEN
    REWRITE_TAC[INV_INTEGRABLE_1_2] THEN BETA_TAC THEN
      REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\a:real. inv a * M * &n`; `&1:real`;
    `&2:real`] CARLESON_INTERVAL_REAL_BRIDGE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[BETA_RULE th]) THEN
  REWRITE_TAC[LIFT_DROP; INV_MN_INTEGRAL_1_2] THEN REAL_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* AAVG_INT_F_BOUND (Fremlin 286S(b) core): the n-th dilation-average        *)
(* integral                                                                  *)
(* bound int_F Aavg h n <= 4C9 log2 ||h||_2 sqrt(muF), from 286P (the ?C9    *)
(* tile                                                                      *)
(* bound hypothesis). Direct box domination -- NO exact SIDE-B nesting       *)
(* needed:                                                                   *)
(* int_F Aavg = (1/n)int_F Sinner = (1/n)drop(int K3) = (1/n)drop(int KFF)   *)
(* <= (1/n)*drop(int of inv(a)*M box) = (1/n)*M*log2*n = M*log2,             *)
(* M=4C9||h||sqrt.                                                           *)
(* ------------------------------------------------------------------------- *)
(* drop(int K3) = drop(int KFF) [FUBINI_INTEGRAL_ALT ab-outer + K3_ABSLICE]. *)
let SIDE_A_KFF = prove
 (`!(h:real->complex) FF n. schwartz h /\ real_measurable FF
   ==> integral (:real^(1,(1,1)finite_sum)finite_sum)
         (\z. if drop(fstcart z) IN FF /\
                 &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <=
                   &2 /\
                 &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <=
                   &n
              then lift(inv(drop(fstcart(sndcart z))) *
                   (if drop(fstcart(sndcart z)) > &0
                    then carleson_amd h (drop(fstcart(sndcart z)))
                      (drop(sndcart(sndcart z))) (drop(fstcart z))
                    else &0))
              else vec 0) =
       integral (:real^(1,1)finite_sum)
         (\ab. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\ &0 <=
           drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then lift(inv(drop(fstcart ab)) * real_integral FF (\x.
                 carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) x))
               else vec 0)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`;
    `n:num`] AMDT_BOX_ABSINT) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> ONCE_REWRITE_TAC[MATCH_MP FUBINI_INTEGRAL_ALT th]) THEN
  ASM_SIMP_TAC[K3_ABSLICE]);;

let AAVG_INT_F_BOUND = prove
 (`!(h:real->complex) FF n C9.
     schwartz h /\ real_measurable FF /\ ~(n = 0) /\ &0 <= C9 /\
     (!(g:real->complex) GG.
          schwartz g /\ real_measurable GG
          ==> real_integral GG (carleson_A g) <=
              &4 * C9 * lnorm (:real^1) (&2) (\z. g (drop z)) * sqrt
                (real_measure GG))
   ==> real_integral FF (\x. carleson_Aavg h n x) <=
       &4 * C9 * log(&2) * lnorm (:real^1) (&2) (\z. h (drop z)) *
         sqrt(real_measure FF)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `L = lnorm (:real^1) (&2) (\z. (h:real->complex) (drop z))` THEN
  ABBREV_TAC `S = sqrt(real_measure FF)` THEN
  ABBREV_TAC `M = &4 * C9 * L * S` THEN
  REWRITE_TAC[carleson_Aavg] THEN
  SUBGOAL_THEN
   `real_integral FF (\x. inv(&n) * carleson_Sinner h n x) =
    inv(&n) * real_integral FF (\x. carleson_Sinner h n x)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LMUL THEN MATCH_MP_TAC SINNER_INTEGRABLE_F THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`; `n:num`] SIDE_A) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  ASM_SIMP_TAC[SIDE_A_KFF] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `inv(&n) * (M * log(&2) * &n)` THEN CONJ_TAC THENL
   [ALL_TAC;
    SUBGOAL_THEN `inv(&n) * (M * log(&2) * &n) = M * log(&2)` SUBST1_TAC THENL
     [SUBGOAL_THEN `~(&n = &0)` MP_TAC THENL
       [REWRITE_TAC[REAL_OF_NUM_EQ] THEN
         ASM_REWRITE_TAC[]; CONV_TAC REAL_FIELD]; ALL_TAC] THEN
     MATCH_MP_TAC REAL_EQ_IMP_LE THEN EXPAND_TAC "M" THEN REAL_ARITH_TAC] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_INV THEN REWRITE_TAC[REAL_POS]; ALL_TAC] THEN
  MP_TAC(ISPECL [`M:real`; `n:num`] DOM_BOX_INTEGRAL) THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC INTEGRAL_DROP_LE THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC KFF_ABSINT THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    REWRITE_TAC[DOM_BOX_ABSINT];
    X_GEN_TAC `ab:real^(1,1)finite_sum` THEN REWRITE_TAC[IN_UNIV] THEN
    COND_CASES_TAC THEN REWRITE_TAC[DROP_VEC; REAL_LE_REFL; LIFT_DROP] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
      EXPAND_TAC "M" THEN
      MP_TAC(ISPECL [`h:real->complex`;
        `drop(fstcart(ab:real^(1,1)finite_sum))`;
        `drop(sndcart(ab:real^(1,1)finite_sum))`; `FF:real->bool`;
        `C9:real`] AMD_INT_F_BOUND) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_REAL_ARITH_TAC]]);;

(* =================================================================         *)
(* 286S(b) FINAL: Aavg nonneg/absint/all-n bound + Atilde liminf.            *)
(* SINNER_NONNEG, AAVG_NONNEG, AAVG_ABSINT, AAVG_INT_F_ALLN,                 *)
(* REALLIM_OF_CONVERGENT, ATILDE_INT_F_BOUND.                                *)
(* =================================================================         *)

(* Sinner h n x >= 0: it is int_[1,2] (1/a) int_[0,n] amd, all factors >=0.  *)
let SINNER_NONNEG = prove
 (`!(h:real->complex) n x. schwartz h /\ ~(n = 0) ==> &0 <= carleson_Sinner h n
   x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Sinner] THEN
  MATCH_MP_TAC REAL_INTEGRAL_POS THEN CONJ_TAC THENL
   [MATCH_MP_TAC A_ITERATE_INTEGRABLE THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `a:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRAL_POS THEN CONJ_TAC THENL
       [MATCH_MP_TAC AMD_BSLICE_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
         ASM_REAL_ARITH_TAC;
        X_GEN_TAC `b:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
          STRIP_TAC THEN
        MATCH_MP_TAC AMD_NONNEG THEN ASM_REWRITE_TAC[] THEN
          ASM_REAL_ARITH_TAC]]]);;

(* Aavg h n x >= 0 (handles n=0 giving 0).                                   *)
let AAVG_NONNEG = prove
 (`!(h:real->complex) n x. schwartz h ==> &0 <= carleson_Aavg h n x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Aavg] THEN
  ASM_CASES_TAC `n = 0` THENL
   [ASM_REWRITE_TAC[REAL_INV_0; REAL_MUL_LZERO; REAL_LE_REFL];
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN REWRITE_TAC[REAL_POS];
      MATCH_MP_TAC SINNER_NONNEG THEN ASM_REWRITE_TAC[]]]);;

(* Aavg h n absolutely_real_integrable on FF (n=0 -> const 0).               *)
let AAVG_ABSINT = prove
 (`!(h:real->complex) FF n. schwartz h /\ real_measurable FF
   ==> (\x. carleson_Aavg h n x) absolutely_real_integrable_on FF`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `n = 0` THENL
   [ASM_REWRITE_TAC[carleson_Aavg; REAL_INV_0; REAL_MUL_LZERO] THEN
    REWRITE_TAC[ABSOLUTELY_REAL_INTEGRABLE_0];
    REWRITE_TAC[carleson_Aavg] THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_LMUL THEN
    MATCH_MP_TAC NONNEGATIVE_ABSOLUTELY_REAL_INTEGRABLE THEN CONJ_TAC THENL
     [X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
      MATCH_MP_TAC SINNER_NONNEG THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC SINNER_INTEGRABLE_F THEN ASM_REWRITE_TAC[]]]);;

(* per-n integral bound (n=0 -> RHS>=0 trivially).                           *)
let AAVG_INT_F_ALLN = prove
 (`!(h:real->complex) FF n C9.
     schwartz h /\ real_measurable FF /\ &0 <= C9 /\
     (!(g:real->complex) GG.
          schwartz g /\ real_measurable GG
          ==> real_integral GG (carleson_A g) <=
              &4 * C9 * lnorm (:real^1) (&2) (\z. g (drop z)) * sqrt
                (real_measure GG))
   ==> real_integral FF (\x. carleson_Aavg h n x) <=
       &4 * C9 * log(&2) * lnorm (:real^1) (&2) (\z. h (drop z)) *
         sqrt(real_measure FF)`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `n = 0` THENL
   [ASM_REWRITE_TAC[carleson_Aavg; REAL_INV_0; REAL_MUL_LZERO] THEN
    REWRITE_TAC[REAL_INTEGRAL_0] THEN
    REPEAT(MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC) THENL
     [REAL_ARITH_TAC;
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC LOG_POS THEN REAL_ARITH_TAC;
      MATCH_MP_TAC LNORM_POS_LE THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
        ASM_REWRITE_TAC[];
      MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_MEASURE_POS_LE THEN
        ASM_REWRITE_TAC[]];
    MATCH_MP_TAC AAVG_INT_F_BOUND THEN ASM_REWRITE_TAC[]]);;

(* a convergent real sequence has reallim = its limit.                       *)
let REALLIM_OF_CONVERGENT = prove
 (`!f l. (f ---> l) sequentially ==> reallim sequentially f = l`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`sequentially`; `f:num->real`; `reallim sequentially f`;
    `l:real`] REALLIM_UNIQUE) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY] THEN
  REWRITE_TAC[reallim] THEN CONV_TAC SELECT_CONV THEN
  EXISTS_TAC `l:real` THEN ASM_REWRITE_TAC[]);;

(* 286S(b) conclusion: int_F Atilde h <= 4 C9 log2 ||h||_2 sqrt muF. Atilde  *)
(* = liminf_m Aavg h n; REAL_FATOU_LIMINF gives an a.e.-limit g with int_F g *)
(* <= liminf of the (uniformly-bounded) int_F Aavg; each of the latter <=    *)
(* the RHS by AAVG_INT_F_ALLN, and Atilde = g a.e. via                       *)
(* REALLIM_OF_CONVERGENT.                                                    *)
let ATILDE_INT_F_BOUND = prove
 (`!(h:real->complex) FF C9.
     schwartz h /\ real_measurable FF /\ &0 <= C9 /\
     (!(g:real->complex) GG. schwartz g /\ real_measurable GG
          ==> real_integral GG (carleson_A g) <= &4 * C9 * lnorm (:real^1) (&2)
            (\z. g (drop z)) * sqrt (real_measure GG))
   ==> real_integral FF (\x. carleson_Atilde h x) <=
       &4 * C9 * log(&2) * lnorm (:real^1) (&2) (\z. h (drop z)) *
         sqrt(real_measure FF)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `B = &4 * C9 * log(&2) * lnorm (:real^1) (&2) (\z.
    (h:real->complex) (drop z)) * sqrt(real_measure FF)` THEN
  MP_TAC(ISPECL [`carleson_Aavg (h:real->complex)`; `FF:real->bool`;
    `B:real`] REAL_FATOU_LIMINF) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [GEN_TAC THEN GEN_REWRITE_TAC (RATOR_CONV o RAND_CONV) [GSYM ETA_AX] THEN
      MATCH_MP_TAC AAVG_ABSINT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL
     [REPEAT GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC AAVG_NONNEG THEN
       ASM_REWRITE_TAC[];
      GEN_TAC THEN GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [GSYM ETA_AX] THEN
      EXPAND_TAC "B" THEN MATCH_MP_TAC AAVG_INT_F_ALLN THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:real->real` (X_CHOOSE_THEN
    `k:real->bool` STRIP_ASSUME_TAC)) THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral FF g` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_EQ_IMP_LE THEN
    MATCH_MP_TAC REAL_INTEGRAL_SPIKE THEN EXISTS_TAC `k:real->bool` THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_DIFF] THEN
      STRIP_TAC THEN
    BETA_TAC THEN REWRITE_TAC[carleson_Atilde] THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC REALLIM_OF_CONVERGENT THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_DIFF];
    ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* 256Mb interface for carleson_A (Fremlin 256M).                            *)
(* carleson_A h = sup over the UNCOUNTABLE z in R of the x-continuous        *)
(* windows                                                                   *)
(* carleson_v h z. By CM_MEASURABLE_SUP_COUNTABLE_REDUCTION                  *)
(* (= Fremlin's "there is a countable Psi with g = sup Psi", via LINDELOF)   *)
(* the                                                                       *)
(* sup equals one over a COUNTABLE nonempty index set for every x;           *)
(* enumerating                                                               *)
(* it as a sequence and invoking CMAXSEQ_SUP_INTEGRAL_LE (the running-max    *)
(* B.Levi                                                                    *)
(* monotone convergence) reduces int_F carleson_A h <= C to the finite-max   *)
(* integral bounds that 286N/286O(b) supply -- WITHOUT any upper-integral    *)
(* machinery. This is exactly Fremlin's 286P step "int_F Ah = sup over       *)
(* finite                                                                    *)
(* {z_0..z_n} of int_F max|v_{z_i}|".                                        *)
(* ========================================================================= *)

(* The tile-window modulus v_z(x) = |2pi (hhat x theta_z) check(x)|.         *)
let carleson_v = new_definition
 `carleson_v (h:real->complex) (z:real) (x:real) =
    norm(Cx(&2 * pi) *
         fourier (\y. fourier h y * Cx(carleson_theta z y)) (--x))`;;

(* carleson_v as a lambda (for MATCH against the window lemmas).             *)
let CARLESON_V_ALT = prove
 (`!(h:real->complex) z.
     carleson_v h z =
     (\x. norm(Cx(&2 * pi) * fourier (\y. fourier h y * Cx(carleson_theta z y))
       (--x)))`,
  REWRITE_TAC[FUN_EQ_THM; carleson_v]);;

(* carleson_v is nonnegative (a norm).                                       *)
let CARLESON_V_POS = prove
 (`!(h:real->complex) z x. &0 <= carleson_v h z x`,
  REWRITE_TAC[carleson_v; NORM_POS_LE]);;

(* Countable reduction of carleson_A: the uncountable sup over z in R equals *)
(* a sup over a COUNTABLE nonempty index set, for every x (256M via          *)
(* LINDELOF; uses only x-continuity of the windows, so theta_z's             *)
(* z-discontinuity is irrelevant, and carleson_A keeps its uncountable       *)
(* definition intact).                                                       *)
let CARLESON_A_COUNTABLE = prove
 (`!(h:real->complex).
     schwartz h
     ==> ?j. COUNTABLE j /\ ~(j = {}) /\
             (!x. carleson_A h x = sup {carleson_v h z x | z IN j})`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\z. carleson_v (h:real->complex) z`; `(:real)`]
    CM_MEASURABLE_SUP_COUNTABLE_REDUCTION) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [X_GEN_TAC `z:real` THEN DISCH_TAC THEN X_GEN_TAC `x:real` THEN
      REWRITE_TAC[CARLESON_V_ALT] THEN
      MATCH_MP_TAC CARLESON_A_WINDOW_CONTINUOUS THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `x:real` THEN
      EXISTS_TAC `sqrt(&2 * pi) *
                  drop(integral (:real^1) (\y. lift(norm(fourier
                    (h:real->complex) (drop y)))))` THEN
      X_GEN_TAC `z:real` THEN DISCH_TAC THEN REWRITE_TAC[carleson_v] THEN
      MATCH_MP_TAC CARLESON_A_WINDOW_UNIFORM_BOUND THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[UNIV_NOT_EMPTY]];
    DISCH_THEN(X_CHOOSE_THEN `j:real->bool` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `j:real->bool` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `x:real` THEN
    REWRITE_TAC[carleson_A] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `x:real`) THEN
    REWRITE_TAC[carleson_v; IN_UNIV]]);;

(* Reindexing: for j = IMAGE u (:num), the value-set {v z x | z in j} equals *)
(* {abs(v(u n) x) | n} (v >= 0), matching CMAXSEQ_SUP_INTEGRAL_LE's sup      *)
(* form.                                                                     *)
let CARLESON_V_SET_REINDEX = prove
 (`!(h:real->complex) u x.
     {carleson_v h z x | z IN IMAGE u (:num)} =
     {abs(carleson_v h (u n) x) | n IN (:num)}`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
    `!n:num. abs(carleson_v (h:real->complex) (u n) x) = carleson_v h (u n) x`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN REWRITE_TAC[REAL_ABS_REFL; CARLESON_V_POS]; ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_IMAGE; IN_UNIV] THEN
  MESON_TAC[]);;

(* 256Mb interface [KEY]: to bound int_F carleson_A h <= C it suffices that  *)
(* for                                                                       *)
(* EVERY enumeration u:num->real the windows are absolutely integrable on    *)
(* FF,                                                                       *)
(* uniformly bounded, and every finite running-max integral is <= C.  (The   *)
(* uniform "for every u" hypothesis is what the dilation-free 286N tile      *)
(* bound                                                                     *)
(* supplies for an arbitrary finite z-selection.)                            *)
let CARLESON_256MB_A = prove
 (`!(h:real->complex) FF C.
     schwartz h /\
     (!u:num->real. (!i. (\x. carleson_v h (u i) x)
       absolutely_real_integrable_on FF) /\
                    (?B. !i x. x IN FF ==> abs(carleson_v h (u i) x) <= B) /\
                    (!n. real_integral FF (cmaxseq (\i. carleson_v h (u i)) n)
                      <= C))
     ==> real_integral FF (carleson_A h) <= C`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `h:real->complex` CARLESON_A_COUNTABLE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `j:real->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPEC `j:real->bool` COUNTABLE_AS_IMAGE) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:num->real` SUBST_ALL_TAC) THEN
  SUBGOAL_THEN
   `real_integral FF (carleson_A (h:real->complex)) =
    real_integral FF (\x. sup {abs(carleson_v h (u n) x) | n IN (:num)})`
   SUBST1_TAC THENL
   [AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real` THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM CARLESON_V_SET_REINDEX];
    ALL_TAC] THEN
  MATCH_MP_TAC CMAXSEQ_SUP_INTEGRAL_LE THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:num->real`) THEN
  STRIP_TAC THEN
  EXISTS_TAC `B:real` THEN ASM_REWRITE_TAC[] THEN
  ASM_REWRITE_TAC[ETA_AX]);;

(* ------------------------------------------------------------------------- *)
(* Easy legs of the CARLESON_256MB_A hypothesis: the tile windows are        *)
(* absolutely integrable on any measurable FF (continuous + bounded) and     *)
(* uniformly bounded (0<=theta_z<=1 so |v_z|<=sqrt(2pi) int|hhat|).          *)
(* ------------------------------------------------------------------------- *)

(* Each window is absolutely real-integrable on a measurable FF (it is       *)
(* everywhere continuous, hence measurable, and bounded by a constant that   *)
(* is integrable on the finite-measure FF).                                  *)
let CARLESON_V_ABSINT = prove
 (`!(h:real->complex) z FF.
     schwartz h /\ real_measurable FF
     ==> (carleson_v h z) absolutely_real_integrable_on FF`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE
    THEN
  EXISTS_TAC `(\x:real. sqrt(&2 * pi) *
                   drop(integral (:real^1) (\y. lift(norm(fourier
                     (h:real->complex) (drop y))))))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
     EXISTS_TAC `(:real)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC CONTINUOUS_IMP_REAL_MEASURABLE_ON THEN
    SIMP_TAC[REAL_CONTINUOUS_ON_EQ_REAL_CONTINUOUS_AT; REAL_OPEN_UNIV;
      IN_UNIV] THEN
    X_GEN_TAC `x:real` THEN
    ONCE_REWRITE_TAC[CARLESON_V_ALT] THEN
    MATCH_MP_TAC CARLESON_A_WINDOW_CONTINUOUS THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_INTEGRABLE_ON_CONST_MEASURABLE THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    REWRITE_TAC[carleson_v; REAL_ABS_NORM] THEN
    MATCH_MP_TAC CARLESON_A_WINDOW_UNIFORM_BOUND THEN ASM_REWRITE_TAC[]]);;

(* Uniform (in z and x) bound on the window modulus.                         *)
let CARLESON_V_UNIF_BOUND = prove
 (`!(h:real->complex). schwartz h
     ==> ?B. !z x. abs(carleson_v h z x) <= B`,
  REPEAT STRIP_TAC THEN
  EXISTS_TAC `sqrt(&2 * pi) *
              drop(integral (:real^1) (\y. lift(norm(fourier (h:real->complex)
                (drop y)))))` THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_v; REAL_ABS_NORM] THEN
  MATCH_MP_TAC CARLESON_A_WINDOW_UNIFORM_BOUND THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* 286P(b-i): the argmax selector + 246K sign trick.  The complex window     *)
(* w_z(x) = 2pi (hhat x theta_z) check(x) (carleson_v = |w_z|); cargmax      *)
(* picks                                                                     *)
(* the least i<=n achieving the running max cmaxseq, so W(x) =               *)
(* w_{u(cargmax)}(x)                                                         *)
(* is Fremlin's sum_i w_i chi E_i collapsed to a single selected term, with  *)
(* norm(W(x)) = cmaxseq..n x = sup_{i<=n}|w_i(x)| = v(x).                    *)
(* ------------------------------------------------------------------------- *)

(* The complex tile window w_z(x) = 2pi (hhat x theta_z) check(x).           *)
let carleson_w = new_definition
 `carleson_w (h:real->complex) (z:real) (x:real) =
    Cx(&2 * pi) * fourier (\y. fourier h y * Cx(carleson_theta z y)) (--x)`;;

(* carleson_v z x = norm(carleson_w z x).                                    *)
let CARLESON_V_EQ_NORM_W = prove
 (`!(h:real->complex) z x. carleson_v h z x = norm(carleson_w h z x)`,
  REWRITE_TAC[carleson_v; carleson_w]);;

(* Argmax selector: the least index i<=n achieving the running max cmaxseq w *)
(* n.                                                                        *)
let cargmax = define
 `(cargmax (w:num->real->real) 0 x = 0) /\
  (cargmax w (SUC n) x =
     if cmaxseq w n x < abs(w (SUC n) x) then SUC n else cargmax w n x)`;;

(* cargmax w n x <= n.                                                       *)
let CARGMAX_LE = prove
 (`!(w:num->real->real) n x. cargmax w n x <= n`,
  GEN_TAC THEN INDUCT_TAC THEN GEN_TAC THEN REWRITE_TAC[cargmax] THENL
   [REWRITE_TAC[LE_REFL];
    COND_CASES_TAC THEN REWRITE_TAC[LE_REFL] THEN
    MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `n:num` THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC]);;

(* The selected term realizes the running max: |w (cargmax w n x) x| =       *)
(* cmaxseq.                                                                  *)
let CARGMAX_REALIZES = prove
 (`!(w:num->real->real) n x. abs(w (cargmax w n x) x) = cmaxseq w n x`,
  GEN_TAC THEN INDUCT_TAC THEN GEN_TAC THEN
  REWRITE_TAC[cargmax; cmaxseq] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `x:real`) THEN ASM_REAL_ARITH_TAC);;

(* The selected complex window W(x)=w_{u(cargmax)}(x) has norm = the running *)
(* max of the real family v_i = |w_i| = carleson_v h (u i). This is          *)
(* Fremlin's                                                                 *)
(* v = |sum_i w_i chi E_i| with the E_i-partition realized by cargmax.       *)
let CARLESON_W_SELECT_NORM = prove
 (`!(h:real->complex) u n x.
     norm(carleson_w h (u (cargmax (\i:num. carleson_v h (u i)) n x)) x) =
     cmaxseq (\i:num. carleson_v h (u i)) n x`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[GSYM CARLESON_V_EQ_NORM_W] THEN
  MP_TAC(ISPECL [`\i:num. carleson_v (h:real->complex) (u i)`; `n:num`;
    `x:real`]
    CARGMAX_REALIZES) THEN
  REWRITE_TAC[] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[REAL_ABS_REFL; CARLESON_V_POS]);;

(* The selected window as a function of x (Fremlin's sum_i w_i chi E_i, as   *)
(* one                                                                       *)
(* selector term).  carleson_wsel h u n = W_n where W_n(x) = w_{u(g x)}(x),  *)
(* g x = cargmax..x; it follows the same recursion as cargmax.               *)
let carleson_wsel = new_definition
 `carleson_wsel (h:real->complex) (u:num->real) (n:num) (x:real) =
    carleson_w h (u (cargmax (\i:num. carleson_v h (u i)) n x)) x`;;

(* Recursion for the selected window (base = w(u 0); SUC picks the larger).  *)
let CARLESON_WSEL_REC = prove
 (`(!(h:real->complex) u x. carleson_wsel h u 0 x = carleson_w h (u 0) x) /\
   (!(h:real->complex) u n x.
      carleson_wsel h u (SUC n) x =
        (if cmaxseq (\i:num. carleson_v h (u i)) n x < carleson_v h (u (SUC n))
          x
         then carleson_w h (u (SUC n)) x
         else carleson_wsel h u n x))`,
  CONJ_TAC THENL
   [REWRITE_TAC[carleson_wsel; cargmax];
    REWRITE_TAC[carleson_wsel] THEN REPEAT GEN_TAC THEN
      REWRITE_TAC[cargmax] THEN
    SUBGOAL_THEN
      `abs(carleson_v (h:real->complex) (u (SUC n)) x) =
       carleson_v h (u (SUC n)) x`
     SUBST1_TAC THENL
       [REWRITE_TAC[REAL_ABS_REFL; CARLESON_V_POS]; ALL_TAC] THEN
    COND_CASES_TAC THEN REWRITE_TAC[]]);;

(* R3 entry (286P E_i-partition): on the argmax cell {x | cargmax..x = i},   *)
(* the                                                                       *)
(* selected window carleson_wsel collapses to the single window carleson_w h *)
(* (u i)                                                                     *)
(* -- immediate from the carleson_wsel definition.                           *)
let CARLESON_WSEL_ON_CELL = prove
 (`!(h:real->complex) u n i x.
     cargmax (\i:num. carleson_v h (u i)) n x = i
     ==> carleson_wsel h u n x = carleson_w h (u i) x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_wsel] THEN ASM_REWRITE_TAC[]);;

(* Each fixed-z complex window is continuous on (:real^1) (fourier of an L^1 *)
(* fn).                                                                      *)
let CARLESON_W_CONTINUOUS = prove
 (`!(h:real->complex) z. schwartz h
     ==> (\x:real^1. carleson_w h z (drop x)) continuous_on (:real^1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_w] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_LMUL THEN
  SUBGOAL_THEN
   `(\x:real^1. fourier (\y. fourier (h:real->complex) y * Cx(carleson_theta z
     y)) (--drop x)) =
    (\x:real^1. fourier (\y. fourier (h:real->complex) y * Cx(carleson_theta z
      y)) (drop x)) o (\x. --x)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; DROP_NEG]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_NEG THEN REWRITE_TAC[CONTINUOUS_ON_ID];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    REWRITE_TAC[SUBSET_UNIV] THEN
    MP_TAC(ISPEC `\y. fourier (h:real->complex) y * Cx(carleson_theta z y)`
      FOURIER_CONTINUOUS_ON) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[] THEN MATCH_MP_TAC CARLESON_FHAT_THETA_ABSINT THEN
       ASM_REWRITE_TAC[];
      REWRITE_TAC[]]]);;

let CARLESON_W_MEASURABLE = prove
 (`!(h:real->complex) z. schwartz h
     ==> (\x:real^1. carleson_w h z (drop x)) measurable_on (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
  MATCH_MP_TAC CARLESON_W_CONTINUOUS THEN ASM_REWRITE_TAC[]);;

(* The complex tile window carleson_w h z is absolutely integrable on any    *)
(* measurable                                                                *)
(* region (continuous, CARLESON_W_CONTINUOUS, + uniformly bounded by         *)
(* sqrt(2pi) int|hhat|                                                       *)
(* on the finite-measure region, CARLESON_A_WINDOW_UNIFORM_BOUND). This      *)
(* supplies the                                                              *)
(* per-cell integrability the 286P(b) Fubini reindex                         *)
(* CARLESON_CELL_SUM_INTEGRAL needs.                                         *)
let CARLESON_V_LIFT_CONTINUOUS = prove
 (`!(h:real->complex) z. schwartz h
     ==> (\x:real^1. lift(carleson_v h z (drop x))) continuous_on (:real^1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[CARLESON_V_EQ_NORM_W] THEN
  MATCH_MP_TAC CONTINUOUS_ON_LIFT_NORM_COMPOSE THEN
  MATCH_MP_TAC CARLESON_W_CONTINUOUS THEN ASM_REWRITE_TAC[]);;

(* carleson_v h z real_continuous_on the whole line (for                     *)
(* CMAXSEQ_CONTINUOUS).                                                      *)
let CARLESON_V_REAL_CONTINUOUS_ON = prove
 (`!(h:real->complex) z. schwartz h ==> carleson_v h z real_continuous_on
   (:real)`,
  REPEAT STRIP_TAC THEN
  SIMP_TAC[REAL_CONTINUOUS_ON_EQ_REAL_CONTINUOUS_AT; REAL_OPEN_UNIV;
    IN_UNIV] THEN
  X_GEN_TAC `x:real` THEN ONCE_REWRITE_TAC[CARLESON_V_ALT] THEN
  MATCH_MP_TAC CARLESON_A_WINDOW_CONTINUOUS THEN ASM_REWRITE_TAC[]);;

(* Hence cmaxseq of the windows (lift form) is continuous on (:real^1).      *)
let CMAXSEQ_CARLESON_V_LIFT_CONTINUOUS = prove
 (`!(h:real->complex) u n. schwartz h
     ==> (\x:real^1. lift(cmaxseq (\i:num. carleson_v h (u i)) n (drop x)))
       continuous_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `cmaxseq (\i:num. carleson_v (h:real->complex) (u i)) n real_continuous_on
    (:real)`
   MP_TAC THENL
   [MATCH_MP_TAC CMAXSEQ_CONTINUOUS THEN GEN_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC CARLESON_V_REAL_CONTINUOUS_ON THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON; IMAGE_LIFT_UNIV; o_DEF]);;

(* The argmax-cell boundary is lebesgue-measurable (open superlevel of the   *)
(* continuous difference carleson_v(SUC n) - cmaxseq n).                     *)
let CARLESON_WSEL_PRED_MEASURABLE = prove
 (`!(h:real->complex) u n. schwartz h
     ==> lebesgue_measurable
           {x:real^1 | cmaxseq (\i:num. carleson_v h (u i)) n (drop x) <
                       carleson_v h (u (SUC n)) (drop x)}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC LEBESGUE_MEASURABLE_OPEN THEN
  SUBGOAL_THEN
   `{x:real^1 | cmaxseq (\i:num. carleson_v h (u i)) n (drop x) <
                carleson_v h (u (SUC n)) (drop x)} =
    {x:real^1 | (\w:real^1. lift(carleson_v h (u (SUC n)) (drop w)) -
                            lift(cmaxseq (\i:num. carleson_v h (u i)) n (drop
                              w))) x
                IN {y:real^1 | y$1 > &0}}`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN GEN_TAC THEN
    REWRITE_TAC[GSYM drop; DROP_SUB; LIFT_DROP; real_gt] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_OPEN_PREIMAGE_UNIV THEN
  REWRITE_TAC[OPEN_HALFSPACE_COMPONENT_GT] THEN
  GEN_TAC THEN MATCH_MP_TAC CONTINUOUS_SUB THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`h:real->complex`;
     `(u:num->real)(SUC n)`] CARLESON_V_LIFT_CONTINUOUS) THEN
    ASM_REWRITE_TAC[] THEN
    SIMP_TAC[CONTINUOUS_ON_EQ_CONTINUOUS_AT; OPEN_UNIV; IN_UNIV];
    MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`]
      CMAXSEQ_CARLESON_V_LIFT_CONTINUOUS) THEN
    ASM_REWRITE_TAC[] THEN
    SIMP_TAC[CONTINUOUS_ON_EQ_CONTINUOUS_AT; OPEN_UNIV; IN_UNIV]]);;

(* The selected window is measurable_on (:real^1) (induction on n,           *)
(* MEASURABLE_ON_ CASES at each argmax step).                                *)
let CARLESON_WSEL_MEASURABLE = prove
 (`!(h:real->complex) u n. schwartz h
     ==> (\x:real^1. carleson_wsel h u n (drop x)) measurable_on (:real^1)`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN DISCH_TAC THENL
   [SUBGOAL_THEN
     `(\x:real^1. carleson_wsel (h:real->complex) u 0 (drop x)) =
      (\x:real^1. carleson_w h (u 0) (drop x))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; CARLESON_WSEL_REC]; ALL_TAC] THEN
    MATCH_MP_TAC CARLESON_W_MEASURABLE THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN
     `(\x:real^1. carleson_wsel (h:real->complex) u (SUC n) (drop x)) =
      (\x:real^1. if cmaxseq (\i:num. carleson_v h (u i)) n (drop x) <
                     carleson_v h (u (SUC n)) (drop x)
                  then carleson_w h (u (SUC n)) (drop x)
                  else carleson_wsel h u n (drop x))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
       REWRITE_TAC[CARLESON_WSEL_REC]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_ON_CASES THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_WSEL_PRED_MEASURABLE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC CARLESON_W_MEASURABLE THEN ASM_REWRITE_TAC[];
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

(* The argmax cell {x | cargmax..drop x = i} is lebesgue-measurable          *)
(* (induction on n:                                                          *)
(* base cargmax 0 = 0 so cell = UNIV or {}; SUC n splits by the "new max"    *)
(* predicate                                                                 *)
(* superlevel CARLESON_WSEL_PRED_MEASURABLE -- i = SUC n gives that set      *)
(* directly                                                                  *)
(* (cargmax n <= n < SUC n so the else-branch never equals SUC n,            *)
(* CARGMAX_LE), else                                                         *)
(* its complement INTER the scale-n cell). Closes MESON-free (num            *)
(* COND-equality by                                                          *)
(* ARITH, never MESON with the heavy carleson_v context in scope). R3        *)
(* E_i-partition.                                                            *)
let CARLESON_CELL_MEASURABLE = prove
 (`!(h:real->complex) u n i. schwartz h ==>
     lebesgue_measurable {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n
       (drop x) = i}`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN GEN_TAC THEN DISCH_TAC THENL
   [REWRITE_TAC[cargmax] THEN
    ASM_CASES_TAC `i = 0` THEN ASM_REWRITE_TAC[] THENL
     [REWRITE_TAC[SET_RULE `{x | T} = (:real^1)`; LEBESGUE_MEASURABLE_UNIV];
      ASM_REWRITE_TAC[SET_RULE `{x | F} = {}`; LEBESGUE_MEASURABLE_EMPTY]];
    REWRITE_TAC[cargmax] THEN
    SUBGOAL_THEN
     `!x:real^1. abs(carleson_v h (u (SUC n)) (drop x)) = carleson_v h (u (SUC
       n)) (drop x)`
     (fun th -> REWRITE_TAC[th]) THENL
     [REWRITE_TAC[REAL_ABS_REFL; CARLESON_V_POS]; ALL_TAC] THEN
    ASM_CASES_TAC `i = SUC n` THEN ASM_REWRITE_TAC[] THENL
     [SUBGOAL_THEN
       `{x:real^1 | (if cmaxseq (\i:num. carleson_v h (u i)) n (drop x) <
         carleson_v h (u (SUC n)) (drop x)
                     then SUC n else cargmax (\i:num. carleson_v h (u i)) n
                       (drop x)) = SUC n} =
        {x | cmaxseq (\i:num. carleson_v h (u i)) n (drop x) < carleson_v h (u
          (SUC n)) (drop x)}`
       SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN X_GEN_TAC `x:real^1` THEN
        COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
        MP_TAC(ISPECL [`\i:num. carleson_v (h:real->complex) (u i)`; `n:num`;
          `drop(x:real^1)`] CARGMAX_LE) THEN
        ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC CARLESON_WSEL_PRED_MEASURABLE THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `{x:real^1 | (if cmaxseq (\i:num. carleson_v h (u i)) n (drop x) <
         carleson_v h (u (SUC n)) (drop x)
                     then SUC n else cargmax (\i:num. carleson_v h (u i)) n
                       (drop x)) = i} =
        ((:real^1) DIFF {x | cmaxseq (\i:num. carleson_v h (u i)) n (drop x) <
          carleson_v h (u (SUC n)) (drop x)})
        INTER {x | cargmax (\i:num. carleson_v h (u i)) n (drop x) = i}`
       SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_INTER; IN_DIFF; IN_UNIV; IN_ELIM_THM] THEN
        X_GEN_TAC `x:real^1` THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
        ASM_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
       [MATCH_MP_TAC LEBESGUE_MEASURABLE_DIFF THEN
        REWRITE_TAC[LEBESGUE_MEASURABLE_UNIV] THEN
        MATCH_MP_TAC CARLESON_WSEL_PRED_MEASURABLE THEN ASM_REWRITE_TAC[];
        ASM_SIMP_TAC[]]]]);;

(* The argmax selector g x = u(cargmax (\i. carleson_v h(u i)) n x) is a     *)
(* finite                                                                    *)
(* step function -- value u j on the (lebesgue-measurable) argmax cell       *)
(* {cargmax..=j},                                                            *)
(* j<=n, and those cells partition (:real) (CARGMAX_LE). So lift o g o drop  *)
(* = vsum_                                                                   *)
(* {j<=n} u j % indicator(cell j) is measurable                              *)
(* (MEASURABLE_ON_VSUM/CMUL/INDICATOR),                                      *)
(* i.e. g real_measurable_on (:real). This is the g-measurability            *)
(* side-condition of                                                         *)
(* CARLESON_WSEL_TILE_LIMIT (286P-b), needed by 286N_SCALED at the argmax    *)
(* selector.                                                                 *)
let CARLESON_G_SELECTOR_MEASURABLE = prove
 (`!(h:real->complex) u n. schwartz h
     ==> (\x. u(cargmax (\i:num. carleson_v h (u i)) n x)) real_measurable_on
       (:real)`,
  REPEAT STRIP_TAC THEN
    REWRITE_TAC[real_measurable_on; IMAGE_LIFT_UNIV; o_DEF] THEN
  SUBGOAL_THEN
   `(\x:real^1. lift(u(cargmax (\i:num. carleson_v (h:real->complex) (u i)) n
     (drop x)))) =
    (\x:real^1. vsum {j:num | j <= n}
       (\j. (u j) % indicator {z:real^1 | cargmax (\i:num. carleson_v h (u i))
         n (drop z) = j} x))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
    REWRITE_TAC[indicator; IN_ELIM_THM] THEN
    SUBGOAL_THEN
     `(\j. (u j) % (if cargmax (\i:num. carleson_v (h:real->complex) (u i)) n
       (drop x) = j
                    then vec 1 else vec 0):real^1) =
      (\j. if j = cargmax (\i:num. carleson_v (h:real->complex) (u i)) n (drop
        x)
           then lift(u (cargmax (\i:num. carleson_v h (u i)) n (drop x))) else
             vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `j:num` THEN
      COND_CASES_TAC THENL
       [FIRST_ASSUM(SUBST1_TAC o SYM) THEN
        REWRITE_TAC[VECTOR_MUL_RZERO; GSYM LIFT_NUM; GSYM LIFT_CMUL;
          REAL_MUL_RID];
        REWRITE_TAC[VECTOR_MUL_RZERO] THEN COND_CASES_TAC THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EQ_SYM_EQ]]; ALL_TAC] THEN
    REWRITE_TAC[VSUM_DELTA; IN_ELIM_THM; CARGMAX_LE];
    MATCH_MP_TAC MEASURABLE_ON_VSUM THEN REWRITE_TAC[FINITE_NUMSEG_LE] THEN
    X_GEN_TAC `j:num` THEN DISCH_TAC THEN MATCH_MP_TAC MEASURABLE_ON_CMUL THEN
    REWRITE_TAC[ETA_AX; MEASURABLE_ON_INDICATOR; INTER_UNIV] THEN
    ASM_SIMP_TAC[CARLESON_CELL_MEASURABLE]]);;

(* cw_tile integrability side-condition of CARLESON_WSEL_TILE_LIMIT          *)
(* (286P-b): for the                                                         *)
(* argmax selector g and measurable FF, cw_tile t is real-integrable on the  *)
(* g-preimage                                                                *)
(* {x IN FF | g x IN tile_J t}. That region = FF INTER {g x IN dyho...} is   *)
(* real-                                                                     *)
(* lebesgue-measurable (H_PREIMAGE_DYHO_LEBESGUE at the measurable g + FF    *)
(* meas), sits                                                               *)
(* inside FF (measurable), so real_measurable                                *)
(* (REAL_MEASURABLE_LEBMEAS_SUBSET) -> cw_tile                               *)
(* integrable (CWTILE_INTEGRABLE_MEASURABLE).  Mirrors the 286N cw_tile leg. *)
let CARLESON_G_CWTILE_INTEGRABLE = prove
 (`!(h:real->complex) u n FF t.
     schwartz h /\ real_measurable FF
     ==> cw_tile t real_integrable_on
           {x | x IN FF /\ (u(cargmax (\i:num. carleson_v h (u i)) n x)) IN
             tile_J t}`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CWTILE_INTEGRABLE_MEASURABLE THEN
  MATCH_MP_TAC REAL_MEASURABLE_LEBMEAS_SUBSET THEN
  EXISTS_TAC `FF:real->bool` THEN REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN
     `{x | x IN FF /\ (u(cargmax (\i:num. carleson_v (h:real->complex) (u i)) n
       x)) IN tile_J t} =
      FF INTER {x | (\y. u(cargmax (\i:num. carleson_v h (u i)) n y)) x IN
        tile_J t}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LEBESGUE_MEASURABLE_INTER THEN CONJ_TAC THENL
     [ASM_SIMP_TAC[REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE];
      SUBGOAL_THEN
        `t:int#int#int = (FST t, FST(SND t), SND(SND t))` SUBST1_TAC THENL
       [REWRITE_TAC[PAIR]; ALL_TAC] THEN
      REWRITE_TAC[tile_J] THEN BETA_TAC THEN
      MATCH_MP_TAC H_PREIMAGE_DYHO_LEBESGUE THEN
      MATCH_MP_TAC CARLESON_G_SELECTOR_MEASURABLE THEN ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[];
    REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]]);;

(* phi_sigma s carleson_phi is Schwartz, hence absolutely integrable on      *)
(* (:real^1),                                                                *)
(* hence integrable on any lebesgue-measurable subset of IMAGE lift FF (in   *)
(* particular                                                                *)
(* the argmax cell-pieces). This is the `ff integrable_on cell-piece`        *)
(* hypothesis                                                                *)
(* that CARLESON_CELL_SUM_INTEGRAL (the regroup-by-tile step of the          *)
(* tile-limit) needs                                                         *)
(* with ff = phi_sigma. (MATCH_MP_TAC can't unify the compound phi_sigma s   *)
(* carleson_                                                                 *)
(* phi against SCHWARTZ_ABSINT's `h`; use MP_TAC(ISPEC ...) forward.)        *)
let CARLESON_PHISIG_PIECE_INTEGRABLE = prove
 (`!(s:int#int#int) FF S.
     real_measurable FF /\ S SUBSET (IMAGE lift FF) /\ lebesgue_measurable S
     ==> (\z:real^1. phi_sigma s carleson_phi (drop z)) integrable_on S`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MP_TAC(ISPECL
   [`\z:real^1. phi_sigma s carleson_phi (drop z)`; `(:real^1)`;
     `S:real^1->bool`]
   ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MP_TAC(ISPEC `phi_sigma (s:int#int#int) carleson_phi` SCHWARTZ_ABSINT) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC PHISIG_SCHWARTZ THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
      REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* The argmax cells {x | cargmax..drop x = j}, j<=n, COVER (:real^1) --      *)
(* every point lands in the cell of its own cargmax value (which is <= n,    *)
(* CARGMAX_LE).                                                              *)
let CARLESON_CELL_DISJOINT = prove
 (`!(h:real->complex) u n j j'.
     ~(j = j')
     ==> {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n (drop x) = j} INTER
         {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n (drop x) = j'} =
           {}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM; NOT_IN_EMPTY] THEN
  X_GEN_TAC `x:real^1` THEN ASM_MESON_TAC[]);;

(* Cell-merge (the set-theoretic core of Fremlin 286P(b)'s                   *)
(* Fubini-over-counting): the                                                *)
(* argmax cells j (j<=n) whose selected value u j lies in V union exactly to *)
(* the                                                                       *)
(* selector-preimage F' INTER {x | u(cargmax..x) IN V}. On cell j the        *)
(* selector g x =                                                            *)
(* u(cargmax..x) = u j, so "u j in V" <=> "g x in V"; cells partition        *)
(* (CARGMAX_LE gives                                                         *)
(* the witnessing j<=n). This links the per-cell decomposition to the        *)
(* g^-1[Jr_sigma]                                                            *)
(* regions that CARLESON_286N bounds.                                        *)
let CARLESON_CELL_MERGE = prove
 (`!(h:real->complex) u n (F':real^1->bool) (V:real->bool).
     UNIONS (IMAGE (\j. F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u
       i)) n (drop x) = j})
                   {j | j <= n /\ u j IN V})
     = F' INTER {x:real^1 | (u (cargmax (\i:num. carleson_v h (u i)) n (drop
       x))) IN V}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[UNIONS_IMAGE; EXTENSION; IN_ELIM_THM; IN_INTER] THEN
  X_GEN_TAC `x:real^1` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `j:num` STRIP_ASSUME_TAC) THEN ASM_REWRITE_TAC[];
    STRIP_TAC THEN
    EXISTS_TAC `cargmax (\i:num. carleson_v (h:real->complex) (u i)) n (drop
      x)` THEN
    ASM_REWRITE_TAC[CARGMAX_LE]]);;

(* Integral-level Fubini reindex (the CORRECT 286P(b) route -- regroup by    *)
(* TILE not                                                                  *)
(* per-cell-norm-triangle): for any integrand ff integrable on each          *)
(* cell-piece, the                                                           *)
(* integral over the merged selector-preimage F' INTER g^-1[V] equals the    *)
(* sum over the                                                              *)
(* contributing cells (u j in V) of the per-piece integrals. CELL_MERGE      *)
(* (region union)                                                            *)
(* + HAS_INTEGRAL_UNIONS_IMAGE (sums over the INDEX set {j<=n /\ u j in V},  *)
(* pairwise cells                                                            *)
(* disjoint) + INTEGRAL_UNIQUE. This feeds one 286N call for the merged set. *)
let CARLESON_CELL_SUM_INTEGRAL = prove
 (`!(ff:real^1->complex) (h:real->complex) u n (F':real^1->bool)
   (V:real->bool).
     (!j. ff integrable_on (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h
       (u i)) n (drop x) = j}))
     ==> integral (F' INTER {x:real^1 | (u (cargmax (\i:num. carleson_v h (u
       i)) n (drop x))) IN V}) ff
         = vsum {j:num | j <= n /\ u j IN V}
              (\j. integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h
                (u i)) n (drop x) = j}) ff)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`; `F':real^1->bool`;
    `V:real->bool`] CARLESON_CELL_MERGE) THEN
  DISCH_THEN(fun th -> GEN_REWRITE_TAC (LAND_CONV o RATOR_CONV o RAND_CONV)
    [SYM th]) THEN
  MATCH_MP_TAC INTEGRAL_UNIQUE THEN
  MATCH_MP_TAC HAS_INTEGRAL_UNIONS_IMAGE THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `{j:num | j <= n}` THEN
    REWRITE_TAC[FINITE_NUMSEG_LE; SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
    X_GEN_TAC `j:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC INTEGRABLE_INTEGRAL THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[pairwise; IN_ELIM_THM] THEN
    MAP_EVERY X_GEN_TAC [`a:num`; `b:num`] THEN STRIP_TAC THEN
    MATCH_MP_TAC NEGLIGIBLE_SUBSET THEN
    EXISTS_TAC `{}:real^1->bool` THEN REWRITE_TAC[NEGLIGIBLE_EMPTY] THEN
    MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`; `a:num`;
      `b:num`] CARLESON_CELL_DISJOINT) THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[]]);;

(* The selected window is absolutely integrable on lift(FF) (measurable +    *)
(* bounded                                                                   *)
(* by the uniform-bound constant, integrable on the finite-measure FF). This *)
(* is                                                                        *)
(* the hypothesis K246_SIGN_TRICK consumes.                                  *)
let CARLESON_WSEL_ABSINT = prove
 (`!(h:real->complex) u n FF.
     schwartz h /\ real_measurable FF
     ==> (\x:real^1. carleson_wsel h u n (drop x)) absolutely_integrable_on
       (IMAGE lift FF)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `h:real->complex` CARLESON_V_UNIF_BOUND) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `B:real`) THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC `(\x:real^1. lift B)` THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`(\x:real^1. carleson_wsel (h:real->complex) u n (drop x))`;
                   `IMAGE lift (FF:real->bool)`; `(:real^1)`]
       MEASURABLE_ON_MEASURABLE_SUBSET) THEN
    DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[SUBSET_UNIV] THEN CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_WSEL_MEASURABLE THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE]];
    REWRITE_TAC[INTEGRABLE_ON_CONST] THEN DISJ2_TAC THEN
    ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE];
    X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN REWRITE_TAC[LIFT_DROP] THEN
    REWRITE_TAC[carleson_wsel; GSYM CARLESON_V_EQ_NORM_W] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL
     [`(u:num->real)(cargmax (\i:num. carleson_v (h:real->complex) (u i)) n
       (drop x))`;
      `drop(x:real^1)`]) THEN
    REAL_ARITH_TAC]);;

(* ========================================================================= *)
(* R3b (Fremlin 286P E_i-argmax partition, 2269-2290): the                   *)
(* cell-decomposition                                                        *)
(* of the selected-window integral. int_F' carleson_wsel = sum_{j<=n} int    *)
(* over                                                                      *)
(* (F' cap argmax-cell j) of carleson_w h(u j). Via                          *)
(* HAS_INTEGRAL_UNIONS_IMAGE                                                 *)
(* over the disjoint F'-restricted cells (which cover F', CELL_COVERS), each *)
(* piece contributing carleson_w h(u j) (WSEL_ON_CELL).                      *)
(* ========================================================================= *)

(* carleson_wsel restricted to a lebesgue-measurable subset of lift FF is    *)
(* integrable.                                                               *)
let CARLESON_WSEL_PIECE_INTEGRABLE = prove
 (`!(h:real->complex) u n FF S.
     schwartz h /\ real_measurable FF /\ S SUBSET (IMAGE lift FF) /\
       lebesgue_measurable S
     ==> (\x:real^1. carleson_wsel h u n (drop x)) integrable_on S`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `IMAGE lift FF` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC CARLESON_WSEL_ABSINT THEN ASM_REWRITE_TAC[]);;

(* The piece F' INTER cell j is lebesgue-measurable.                         *)
let CARLESON_WSEL_PIECE_LMEAS = prove
 (`!(h:real->complex) u n F' j.
     schwartz h /\ measurable F'
     ==> lebesgue_measurable
           (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n (drop
             x) = j})`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC LEBESGUE_MEASURABLE_INTER THEN
  ASM_SIMP_TAC[MEASURABLE_IMP_LEBESGUE_MEASURABLE; CARLESON_CELL_MEASURABLE]);;

(* Per-index: carleson_wsel has_integral (int of carleson_w) on the piece.   *)
(* wsel =                                                                    *)
(* carleson_w on the cell (WSEL_ON_CELL), so INTEGRAL_EQ rewrites the target *)
(* integral to                                                               *)
(* the wsel-integral, then INTEGRABLE_INTEGRAL (avoids the free y that       *)
(* MATCH_MP HAS_                                                             *)
(* INTEGRAL_SPIKE would leave).                                              *)
let CARLESON_WSEL_PIECE_HASINT = prove
 (`!(h:real->complex) u n FF F' j.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF)
     ==> ((\x:real^1. carleson_wsel h u n (drop x)) has_integral
          integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n
            (drop x) = j})
                   (\x. carleson_w h (u j) (drop x)))
         (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n (drop x)
           = j})`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n (drop
     x) = j})
             (\x. carleson_w h (u j) (drop x)) =
    integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n (drop
      x) = j})
             (\x. carleson_wsel h u n (drop x))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `x:real^1` THEN
    REWRITE_TAC[IN_INTER; IN_ELIM_THM] THEN STRIP_TAC THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARLESON_WSEL_ON_CELL THEN
      ASM_REWRITE_TAC[];
    MATCH_MP_TAC INTEGRABLE_INTEGRAL THEN
    MATCH_MP_TAC CARLESON_WSEL_PIECE_INTEGRABLE THEN
    EXISTS_TAC `FF:real->bool` THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [ASM SET_TAC[];
      MATCH_MP_TAC CARLESON_WSEL_PIECE_LMEAS THEN ASM_REWRITE_TAC[]]]);;

(* The F'-restricted argmax cells are pairwise negligible-intersecting.      *)
let CARLESON_WSEL_PIECES_PAIRWISE = prove
 (`!(h:real->complex) u n F'.
     pairwise (\a b. negligible ((F' INTER {x:real^1 | cargmax (\i:num.
       carleson_v h (u i)) n (drop x) = a}) INTER
                                 (F' INTER {x:real^1 | cargmax (\i:num.
                                   carleson_v h (u i)) n (drop x) = b})))
              {j:num | j <= n}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pairwise; IN_ELIM_THM] THEN
  MAP_EVERY X_GEN_TAC [`a:num`; `b:num`] THEN STRIP_TAC THEN
  MATCH_MP_TAC NEGLIGIBLE_SUBSET THEN
  EXISTS_TAC `{}:real^1->bool` THEN REWRITE_TAC[NEGLIGIBLE_EMPTY] THEN
  MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`; `a:num`;
    `b:num`] CARLESON_CELL_DISJOINT) THEN
  ASM_REWRITE_TAC[] THEN SET_TAC[]);;

(* The cell-decomposition [R3b KEY].  F' measurable SUBSET lift FF.          *)
let CARLESON_WSEL_REGION_DECOMP = prove
 (`!(h:real->complex) u n FF F'.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF)
     ==> integral F' (\x:real^1. carleson_wsel h u n (drop x)) =
         vsum {j:num | j <= n}
           (\j. integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u
             i)) n (drop x) = j})
                         (\x. carleson_w h (u j) (drop x)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `F' = UNIONS (IMAGE (\j:num. F' INTER {x:real^1 | cargmax (\i:num.
     carleson_v h (u i)) n (drop x) = j}) {j | j <= n})`
   ASSUME_TAC THENL
   [REWRITE_TAC[UNIONS_IMAGE; EXTENSION; IN_ELIM_THM; IN_INTER] THEN
    X_GEN_TAC `x:real^1` THEN EQ_TAC THENL
     [DISCH_TAC THEN
      EXISTS_TAC `cargmax (\i:num. carleson_v (h:real->complex) (u i)) n (drop
        x)` THEN
      ASM_REWRITE_TAC[CARGMAX_LE];
      STRIP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  GEN_REWRITE_TAC (LAND_CONV o RATOR_CONV o RAND_CONV)
   [ASSUME `F' = UNIONS (IMAGE (\j:num. F' INTER {x:real^1 | cargmax (\i:num.
     carleson_v h (u i)) n (drop x) = j}) {j | j <= n})`] THEN
  MP_TAC(ISPECL
   [`\x:real^1. carleson_wsel h u n (drop x)`;
    `\j:num. F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n (drop
      x) = j}`;
    `\j:num. integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u
      i)) n (drop x) = j})
                      (\x. carleson_w h (u j) (drop x))`;
    `{j:num | j <= n}`] HAS_INTEGRAL_UNIONS_IMAGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[FINITE_NUMSEG_LE] THEN CONJ_TAC THENL
     [X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
      MATCH_MP_TAC CARLESON_WSEL_PIECE_HASINT THEN
      EXISTS_TAC `FF:real->bool` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[CARLESON_WSEL_PIECES_PAIRWISE]];
    DISCH_THEN(fun th -> REWRITE_TAC[MATCH_MP INTEGRAL_UNIQUE th])]);;

(* R3e step 1: the norm of the selected-window integral is <= the sum over   *)
(* cells of the per-cell window-integral norms (triangle inequality          *)
(* VSUM_NORM on the cell-decomp). Reduces the tile-bound gate to bounding    *)
(* sum_j norm(int_{piece j} carleson_w h(u j)).                              *)
let CMAXSEQ_CARLESON_V_ABSINT = prove
 (`!(h:real->complex) u n FF.
     schwartz h /\ real_measurable FF
     ==> (cmaxseq (\i:num. carleson_v h (u i)) n) absolutely_real_integrable_on
       FF`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CMAXSEQ_ABSINT THEN
  GEN_TAC THEN REWRITE_TAC[] THEN MATCH_MP_TAC CARLESON_V_ABSINT THEN
  ASM_REWRITE_TAC[]);;

(* 286P(b-i) [Fremlin mt286.tex 2280-2285]: the 246K sign trick applied to   *)
(* the                                                                       *)
(* selected window.  For a finite selection u,n there is a measurable        *)
(* F' SUBSET lift(FF) with int_FF (sup_{i<=n}|v_{u i}|) <= 4 norm(int_F'     *)
(* W_n),                                                                     *)
(* where W_n = carleson_wsel (Fremlin's sum_i v_i chi E_i as one selector    *)
(* term).                                                                    *)
(* This isolates the whole remaining depth into bounding norm(int_F' W_n).   *)
let CARLESON_FINITEMAX_246K = prove
 (`!(h:real->complex) u n FF.
     schwartz h /\ real_measurable FF
     ==> ?F'. measurable F' /\ F' SUBSET IMAGE lift FF /\
              real_integral FF (cmaxseq (\i:num. carleson_v h (u i)) n) <=
              &4 * norm(integral F' (\x:real^1. carleson_wsel h u n (drop
                x)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`(\x:real^1. carleson_wsel (h:real->complex) u n (drop x))`;
                 `IMAGE lift (FF:real->bool)`] K246_SIGN_TRICK) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[CARLESON_WSEL_ABSINT; GSYM REAL_MEASURABLE_MEASURABLE];
     ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `F':real^1->bool` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `F':real^1->bool` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `real_integral FF (cmaxseq (\i:num. carleson_v (h:real->complex) (u i)) n) =
    drop(integral (IMAGE lift FF) (\x:real^1. lift(norm(carleson_wsel h u n
      (drop x)))))`
   (fun th -> ASM_REWRITE_TAC[th]) THENL
   [SUBGOAL_THEN
     `cmaxseq (\i:num. carleson_v (h:real->complex) (u i)) n real_integrable_on
       FF`
     ASSUME_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC CMAXSEQ_CARLESON_V_ABSINT THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[REAL_INTEGRAL] THEN
    AP_TERM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM; o_THM] THEN
    X_GEN_TAC `x:real^1` THEN AP_TERM_TAC THEN
    REWRITE_TAC[carleson_wsel] THEN REWRITE_TAC[CARLESON_W_SELECT_NORM];
    RULE_ASSUM_TAC(CONV_RULE(DEPTH_CONV BETA_CONV)) THEN ASM_REWRITE_TAC[]]);;

(* 286O(b) per-k spatial identity, elementary half (Fremlin mt286.tex        *)
(* 2139-2140):                                                               *)
(* over a lebesgue-measurable region R, the integral of a FINITE tile-sum    *)
(* equals                                                                    *)
(* the coefficient-weighted sum of phi_sigma integrals. Pure linearity of    *)
(* the                                                                       *)
(* integral over a finite vsum (INTEGRAL_VSUM), each phi_sigma integrable on *)
(* R                                                                         *)
(* (PHISIG_ABSINT_LEBESGUE).  The DEEP half -- that this sum converges to    *)
(* 2pi int_R (hhat theta_z)check -- is the remaining b-ii filter-limit work. *)
let CHI_MEASURABLE_ON = prove
 (`!(R:real^1->bool). measurable R
     ==> (\x. if x IN R then Cx(&1) else Cx(&0)) measurable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC MEASURABLE_ON_CASES THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `{x:real^1 | x IN R} = R` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[MEASURABLE_ON_CONST];
    REWRITE_TAC[MEASURABLE_ON_CONST]]);;

let INDICATOR_L2_UNIV = prove
 (`!(R:real^1->bool). measurable R
     ==> indicator R IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lspace; IN_ELIM_THM] THEN CONJ_TAC THENL
   [REWRITE_TAC[MEASURABLE_ON_INDICATOR] THEN
    ONCE_REWRITE_TAC[INTER_COMM] THEN REWRITE_TAC[INTER_UNIV] THEN
    MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN
     `(\x:real^1. lift(norm(indicator R x) rpow &2)) = indicator R`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; indicator] THEN X_GEN_TAC `x:real^1` THEN
      COND_CASES_TAC THENL
       [REWRITE_TAC[NORM_REAL; GSYM drop; DROP_VEC; REAL_ABS_NUM] THEN
        SIMP_TAC[RPOW_POW] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
          REWRITE_TAC[LIFT_NUM];
        REWRITE_TAC[NORM_0] THEN
        SIMP_TAC[RPOW_ZERO; REAL_OF_NUM_EQ; ARITH] THEN REWRITE_TAC[LIFT_NUM]];
      REWRITE_TAC[INTEGRABLE_ON_INDICATOR] THEN
      ONCE_REWRITE_TAC[INTER_COMM] THEN REWRITE_TAC[INTER_UNIV] THEN
      ASM_REWRITE_TAC[]]]);;

(* chi_R (Cx-valued) is in L^2 over the whole line (bounded by the real^1    *)
(* indicator L^2 majorant). This is the form FOURIER_L2_REP needs (lspace    *)
(* over                                                                      *)
(* (:real^1), not just over R).                                              *)
let CARLESON_CHI_L2_UNIV = prove
 (`!(R:real^1->bool). measurable R
     ==> (\x. if x IN R then Cx(&1) else Cx(&0)) IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`(:real^1)`; `&2`;
    `(\x. if x IN R then Cx(&1) else Cx(&0)):real^1->complex`;
    `indicator (R:real^1->bool)`] LSPACE_BOUNDED_MEASURABLE) THEN
  REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CHI_MEASURABLE_ON THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC INDICATOR_L2_UNIV THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN REWRITE_TAC[indicator] THEN
    COND_CASES_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_CX; COMPLEX_NORM_0; NORM_REAL; GSYM drop;
      DROP_VEC; NORM_0] THEN
    REAL_ARITH_TAC]);;

(* The abstract L^2 Fourier representative chi_R-hat of chi_R                *)
(* (FOURIER_L2_REP):                                                         *)
(* an L^2 function g with the rep property int g*h = int chi_R * fourier h   *)
(* and                                                                       *)
(* norm-preserving. This is the b-slot object PARSEVAL_L2_BILINEAR consumes  *)
(* in the                                                                    *)
(* 286O(b) spatial pairing 2pi <u|chi_R> = 2pi <uhat|chi_R-hat> (Fremlin     *)
(* 2130) --                                                                  *)
(* avoids the pointwise fourier chi_R (no L1capL2-Plancherel identification  *)
(* needed).                                                                  *)
let CARLESON_CHIHAT_REP = prove
 (`!(R:real^1->bool). measurable R
     ==> ?g. g IN lspace (:real^1) (&2) /\
             lnorm (:real^1) (&2) g = lnorm (:real^1) (&2) (\x. if x IN R then
               Cx(&1) else Cx(&0)) /\
             (!h. schwartz h
                  ==> integral (:real^1) (\z. g z * h(drop z)) =
                      integral (:real^1)
                        (\z. (if z IN R then Cx(&1) else Cx(&0)) * fourier h
                          (drop z)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `(\x. if x IN R then Cx(&1) else Cx(&0)):real^1->complex`
    FOURIER_L2_REP) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC CARLESON_CHI_L2_UNIV THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[]]);;

(* phi_sigma and its Fourier transform are both in L^2 (both Schwartz).      *)
let PHISIG_IN_LSPACE2 = prove
 (`!(s:int#int#int). (\z. phi_sigma s carleson_phi (drop z)) IN lspace
   (:real^1) (&2)`,
  GEN_TAC THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
  REWRITE_TAC[ETA_AX; PHISIG_CARLESON_SCHWARTZ]);;

let PHISIG_FOURIER_L2 = prove
 (`!(s:int#int#int). (\z. fourier (phi_sigma s carleson_phi) (drop z)) IN
   lspace (:real^1) (&2)`,
  GEN_TAC THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
  ONCE_REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC SCHWARTZ_FOURIER THEN
  REWRITE_TAC[PHISIG_CARLESON_SCHWARTZ]);;

(* int_R phi_sigma = lproduct phi_sigma chi_R (chi_R real, so cnj chi_R =    *)
(* chi_R; INTEGRAL_RESTRICT_UNIV turns the region integral into the          *)
(* chi_R-weighted one).                                                      *)
let CARLESON_PHISIG_REGION_LPRODUCT = prove
 (`!(s:int#int#int) (R:real^1->bool).
     integral R (\z. phi_sigma s carleson_phi (drop z)) =
     lproduct (:real^1) (\z. phi_sigma s carleson_phi (drop z))
                        (\x. if x IN R then Cx(&1) else Cx(&0))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[lproduct] THEN
  GEN_REWRITE_TAC LAND_CONV [GSYM INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN COND_CASES_TAC THEN
  REWRITE_TAC[CNJ_CX; COMPLEX_MUL_RID; COMPLEX_MUL_RZERO; COMPLEX_VEC_0]);;

(* ========================================================================= *)
(* 286O(b) entry bricks (Fremlin mt286.tex 2050-2073): the tile              *)
(* inner-product <h|phi_sigma> in Fourier / coefficient form. These start    *)
(* of the per-k tile identity 286O-b-ii, which consumes the 282-series 282L  *)
(* (fourier_series.ml, CFOURIER_CONVERGENCE_DIFFERENTIABLE) and 282Rb.       *)
(* ========================================================================= *)

(* Parseval bridge (Fremlin 2050-2052, "284O"): the tile inner-product       *)
(* equals                                                                    *)
(* the integral of the Fourier transforms. <h|phi_s> = int hhat *            *)
(* cnj(phihat_s).                                                            *)
let CARLESON_IP_FHAT = prove
 (`!(h:real->complex) s. schwartz h ==>
     carleson_ip h s =
     integral (:real^1)
       (\z. fourier h (drop z) * cnj(fourier (phi_sigma s carleson_phi) (drop
         z)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_ip; lproduct] THEN
  MATCH_MP_TAC PARSEVAL_SCHWARTZ_BILINEAR THEN
  ASM_SIMP_TAC[PHISIG_SCHWARTZ; CARLESON_PHI_SCHWARTZ]);;

(* carleson_ip is COMPLEX-linear in the function slot: <c*h|phi_s> =         *)
(* c<h|phi_s>                                                                *)
(* (LPRODUCT_LMUL, given integrability of the h*cnj(phi_sigma) pairing).     *)
(* With                                                                      *)
(* CARLESON_W_SCALE this is the algebra for the 286P normalization h ->      *)
(* h/||h||_2.                                                                *)
let CARLESON_IP_CMUL = prove
 (`!(h:real->complex) (c:complex) s.
     (\z. h(drop z) * cnj(phi_sigma s carleson_phi (drop z))) integrable_on
       (:real^1)
     ==> carleson_ip (\x. c * h x) s = c * carleson_ip h s`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_ip] THEN
  MP_TAC(ISPECL [`(:real^1)`; `\z. (h:real->complex)(drop z)`;
                 `\z. phi_sigma s carleson_phi (drop z)`;
                   `c:complex`] LPRODUCT_LMUL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
  REWRITE_TAC[]);;

(* Degenerate case for the 286P normalization: if ||h||_2 = 0 (h vanishes    *)
(* a.e.)                                                                     *)
(* then carleson_ip h s = 0 for every tile s.  The integrand h * cnj(phi_s)  *)
(* vanishes wherever h does, so its support sits inside the negligible set   *)
(* {h <> 0} (LNORM_EQ_0) and the integral is 0 (HAS_INTEGRAL_NEGLIGIBLE).    *)
(* This is                                                                   *)
(* the ||h||_2 = 0 branch of CARLESON_286N_SCALED (the ||h||_2-homogeneous   *)
(* 286N).                                                                    *)
let CARLESON_IP_LNORM_ZERO = prove
 (`!(h:real->complex) s. schwartz h /\ lnorm (:real^1) (&2) (\z. h(drop z)) =
   &0
     ==> carleson_ip h s = Cx(&0)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_ip; lproduct] THEN
  REWRITE_TAC[GSYM COMPLEX_VEC_0] THEN MATCH_MP_TAC INTEGRAL_UNIQUE THEN
  MATCH_MP_TAC HAS_INTEGRAL_NEGLIGIBLE THEN
  EXISTS_TAC `{z:real^1 | ~((h:real->complex)(drop z) = vec 0)}` THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`(:real^1)`; `&2`;
     `\z:real^1. (h:real->complex)(drop z)`] LNORM_EQ_0) THEN
    ASM_SIMP_TAC[SCHWARTZ_L2; REAL_OF_NUM_EQ; ARITH; IN_UNIV];
    REWRITE_TAC[IN_DIFF; IN_UNIV; IN_ELIM_THM] THEN X_GEN_TAC `z:real^1` THEN
    REWRITE_TAC[COMPLEX_VEC_0] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[COMPLEX_MUL_LZERO]]);;

(* The ||h||_2-homogeneous form of the uniform 286N (Fremlin's step-iv       *)
(* packaging):                                                               *)
(* for ANY schwartz h (no ||h||_2<=1 normalization), the tile-sum is bounded *)
(* by                                                                        *)
(* C9 * ||h||_2 * sqrt(muFF).  ||h||_2 = 0 branch: h vanishes a.e. so every  *)
(* carleson_ip h s = 0 (CARLESON_IP_LNORM_ZERO), sum = 0. ||h||_2 > 0        *)
(* branch:                                                                   *)
(* apply uniform CARLESON_286N to f = (1/||h||_2) h (which has ||f||_2 = 1,  *)
(* via                                                                       *)
(* LSPACE_CMUL + LNORM_MUL), pull the scalar out with CARLESON_IP_CMUL,      *)
(* rescale.                                                                  *)
(* This is the ONE 286N call that the 286P tile bound needs (f = h           *)
(* normalized).                                                              *)
let CARLESON_286N_SCALED = prove
 (`?C9. &0 <= C9 /\
     !(g:real->real) FF (h:real->complex) P.
        schwartz h /\ g real_measurable_on (:real) /\ real_measurable FF /\
        &0 < real_measure FF /\ FINITE P /\
        (!t. cw_tile t real_integrable_on {x | x IN FF /\ g x IN tile_J t})
        ==> sum P (\s. norm(carleson_ip h s *
                 integral (IMAGE lift {x | x IN FF /\ g x IN tile_Jr s})
                      (\z. phi_sigma s carleson_phi (drop z))))
            <= C9 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              FF)`,
  X_CHOOSE_THEN `C9:real` STRIP_ASSUME_TAC CARLESON_286N THEN
  EXISTS_TAC `C9:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`g:real->real`; `FF:real->bool`; `h:real->complex`;
                       `P:(int#int#int)->bool`] THEN
  STRIP_TAC THEN
  ASM_CASES_TAC `lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z)) = &0`
    THENL
   [ASM_REWRITE_TAC[REAL_MUL_LZERO; REAL_MUL_RZERO] THEN
    MATCH_MP_TAC REAL_EQ_IMP_LE THEN MATCH_MP_TAC SUM_EQ_0 THEN
    X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN `carleson_ip (h:real->complex) s = Cx(&0)` ASSUME_TAC THENL
     [MATCH_MP_TAC CARLESON_IP_LNORM_ZERO THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[COMPLEX_MUL_LZERO; COMPLEX_NORM_0];
    ABBREV_TAC `nh = lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z))` THEN
    SUBGOAL_THEN `&0 < nh` ASSUME_TAC THENL
     [SUBGOAL_THEN `&0 <= nh` MP_TAC THENL
       [EXPAND_TAC "nh" THEN MATCH_MP_TAC LNORM_POS_LE THEN
         ASM_SIMP_TAC[SCHWARTZ_L2];
        ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL
     [`g:real->real`; `FF:real->bool`;
      `\x. Cx(inv(nh:real)) * (h:real->complex) x`; `P:(int#int#int)->bool`] o
     check(is_forall o concl)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
       [SUBGOAL_THEN
         `(\z. Cx(inv(nh:real)) * (h:real->complex)(drop z)) =
          (\z. inv nh % (\w. (h:real->complex)(drop w)) z)`
         SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; COMPLEX_CMUL]; ALL_TAC] THEN
        MATCH_MP_TAC LSPACE_CMUL THEN ASM_SIMP_TAC[SCHWARTZ_L2];
        SUBGOAL_THEN
         `(\z. Cx(inv(nh:real)) * (h:real->complex)(drop z)) =
          (\z. inv nh % (\w. (h:real->complex)(drop w)) z)`
         SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; COMPLEX_CMUL]; ALL_TAC] THEN
        MP_TAC(ISPECL [`(:real^1)`; `&2`;
          `\z:real^1. (h:real->complex)(drop z)`; `inv(nh:real)`]
          LNORM_MUL) THEN
        ASM_SIMP_TAC[SCHWARTZ_L2; REAL_OF_NUM_EQ; ARITH] THEN DISCH_THEN
          SUBST1_TAC THEN
        REWRITE_TAC[REAL_ABS_INV] THEN SUBGOAL_THEN
          `abs(nh:real) = nh` SUBST1_TAC THENL
         [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
        ASM_SIMP_TAC[REAL_MUL_LINV; REAL_LT_IMP_NZ; REAL_LE_REFL]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!s. carleson_ip (\x. Cx(inv(nh:real)) * (h:real->complex) x) s =
          Cx(inv(nh:real)) * carleson_ip h s`
     (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN MATCH_MP_TAC CARLESON_IP_CMUL THEN
      MATCH_MP_TAC SCHWARTZ_CNJ_PRODUCT_INTEGRABLE THEN
      ASM_SIMP_TAC[ETA_AX; PHISIG_SCHWARTZ; CARLESON_PHI_SCHWARTZ];
        ALL_TAC] THEN
    REWRITE_TAC[GSYM COMPLEX_MUL_ASSOC; COMPLEX_NORM_MUL; COMPLEX_NORM_CX;
      REAL_ABS_INV] THEN
    SUBGOAL_THEN `abs(nh:real) = nh` SUBST1_TAC THENL
      [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[SUM_LMUL] THEN DISCH_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `(nh:real) * (C9 * sqrt(real_measure FF))` THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `(nh:real) *
        (inv nh * sum P (\s. norm(carleson_ip (h:real->complex) s) *
          norm(integral (IMAGE lift {x | x IN FF /\ g x IN tile_Jr s})
               (\z. phi_sigma s carleson_phi (drop z)))))` THEN
      CONJ_TAC THENL
       [ASM_SIMP_TAC[REAL_MUL_ASSOC; REAL_MUL_RINV; REAL_LT_IMP_NZ;
         REAL_MUL_LID; REAL_LE_REFL];
        MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
         [ASM_SIMP_TAC[REAL_LT_IMP_LE];
          ASM_SIMP_TAC[GSYM SUM_LMUL] THEN REWRITE_TAC[REAL_MUL_ASSOC] THEN
          ASM_REWRITE_TAC[]]];
      MATCH_MP_TAC REAL_EQ_IMP_LE THEN CONV_TAC REAL_RING]]);;

(* Tile-parameter arithmetic (Fremlin 2048): x_sigma * 2^{k} = n_I + 1/2, so *)
(* the modulation exponent x_s(z-y_s) becomes (n_I+1/2) t after z = 2^k t +  *)
(* y_s.                                                                      *)
let TILE_XMID_SCALE = prove
 (`!k nI nJ:int. tile_xmid(k,nI,nJ) * &2 zpow (tile_k(k,nI,nJ)) =
                 real_of_int nI + &1 / &2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_xmid; tile_k; dyho_mid] THEN
  SIMP_TAC[GSYM REAL_MUL_ASSOC; GSYM REAL_ZPOW_ADD; REAL_OF_NUM_EQ; ARITH] THEN
  REWRITE_TAC[INT_ARITH `--k + k:int = &0`; REAL_ZPOW_0] THEN
  CONV_TAC REAL_FIELD);;

(* cnj(phihat_sigma) for phi = carleson_phi (phihat real): the conjugate     *)
(* flips only the modulation sign (Fremlin 2054-2056, the phihat_sigma       *)
(* formula 286Eb).                                                           *)
let CARLESON_PHISIG_FHAT_CNJ = prove
 (`!(s:int#int#int) y.
     cnj(fourier (phi_sigma s carleson_phi) y) =
     Cx(&1 / sqrt(&2 zpow (tile_k s))) *
     cexp(ii * Cx(tile_xmid s) * Cx(y - tile_ymid s)) *
     fourier carleson_phi ((y - tile_ymid s) / &2 zpow (tile_k s))`,
  REPEAT GEN_TAC THEN
  ASM_SIMP_TAC[PHISIG_FHAT; CARLESON_PHI_SCHWARTZ] THEN
  REWRITE_TAC[CNJ_MUL; CNJ_CX; CNJ_CEXP] THEN
  MP_TAC(SPEC `(y - tile_ymid s) / &2 zpow (tile_k s)` (CONJUNCT1(CONJUNCT2
    carleson_phi))) THEN
  REWRITE_TAC[REAL_CNJ] THEN DISCH_THEN SUBST1_TAC THEN
  AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[CNJ_NEG; CNJ_MUL; CNJ_II; CNJ_CX] THEN CONV_TAC COMPLEX_RING);;

(* Pull a scalar Cx c out of a 4-fold product integral (used to extract the  *)
(* 1/sqrt(2^k) prefactor after the tile change of variables).                *)
let INTEGRAL_MID_CONST_PULL = prove
 (`!(A:real^1->complex) B C c.
     (\x. A x * B x * C x) integrable_on (:real^1)
     ==> integral (:real^1) (\x. A x * Cx c * B x * C x) =
         Cx c * integral (:real^1) (\x. A x * B x * C x)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC EQ_TRANS THEN
  EXISTS_TAC `integral (:real^1) (\x. Cx c * (A x * B x * C x))` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRAL_EQ THEN GEN_TAC THEN DISCH_TAC THEN
     CONV_TAC COMPLEX_RING;
    ASM_SIMP_TAC[INTEGRAL_COMPLEX_LMUL]]);;

(* cnj(phihat_sigma) evaluated at the dilated argument 2^k x + y_s: the tile *)
(* argument collapses ((2^k x + y_s - y_s)/2^k = x) and x_s * 2^k = n_I +    *)
(* 1/2 (TILE_XMID_SCALE), giving the clean modulation cexp(ii (n_I+1/2) x).  *)
let CARLESON_PHISIG_FHAT_CNJ_DILATE = prove
 (`!(k:int)(nI:int)(nJ:int) x.
     cnj(fourier (phi_sigma (k,nI,nJ) carleson_phi) (&2 zpow k * x +
       tile_ymid(k,nI,nJ))) =
     Cx(&1 / sqrt(&2 zpow k)) * cexp(ii * Cx(real_of_int nI + &1/ &2) * Cx x) *
     fourier carleson_phi x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[CARLESON_PHISIG_FHAT_CNJ] THEN
  REWRITE_TAC[tile_k] THEN
  SUBGOAL_THEN
    `(&2 zpow k * x + tile_ymid(k,nI,nJ)) - tile_ymid(k,nI,nJ) = &2 zpow k * x`
   SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(&2 zpow k * x) / &2 zpow k = x` SUBST1_TAC THENL
   [MP_TAC(ISPEC `(k,nI,nJ):int#int#int` PHISIG_SCALE_POS) THEN
     REWRITE_TAC[tile_k] THEN
    CONV_TAC REAL_FIELD; ALL_TAC] THEN
  AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  MP_TAC(ISPECL [`k:int`; `nI:int`; `nJ:int`] TILE_XMID_SCALE) THEN
  REWRITE_TAC[tile_k] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  REWRITE_TAC[CX_MUL] THEN CONV_TAC COMPLEX_RING);;

(* sqrt(2^k) * (Cx(1/sqrt(2^k)) * z) = z: the 2^k dilation Jacobian cancels  *)
(* the phi_sigma normalization; the Cx(sqrt)*Cx(1/sqrt)=1 fact fed to        *)
(* COMPLEX_RING.                                                             *)
let CARLESON_SQRT_SCALE_ID = prove
 (`!(k:int) (A:complex) B C.
     A * B * C = Cx(sqrt(&2 zpow k)) * (A * Cx(&1 / sqrt(&2 zpow k)) * B * C)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `Cx(sqrt(&2 zpow k)) * Cx(&1 / sqrt(&2 zpow k)) = Cx(&1)`
   MP_TAC THENL
   [REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
    SUBGOAL_THEN `&0 < sqrt(&2 zpow k)` MP_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LT THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      CONV_TAC REAL_FIELD]; ALL_TAC] THEN
  CONV_TAC COMPLEX_RING);;

(* The tile-substituted integrand (Fremlin 2059's g-integral) is integrable. *)
let CARLESON_IP_TARGET_INTEGRABLE = prove
 (`!(h:real->complex) (k:int) (nI:int) (nJ:int). schwartz h
   ==> (\t. fourier h (&2 zpow k * drop t + tile_ymid(k,nI,nJ)) *
            cexp(ii * Cx(real_of_int nI + &1/ &2) * Cx(drop t)) *
            fourier carleson_phi (drop t)) integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. fourier (h:real->complex) (drop z) *
         cnj(fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop z)))
           integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_CNJ_PRODUCT_INTEGRABLE THEN REWRITE_TAC[ETA_AX] THEN
    ASM_SIMP_TAC[SCHWARTZ_FOURIER; PHISIG_SCHWARTZ; CARLESON_PHI_SCHWARTZ];
      ALL_TAC] THEN
  ONCE_REWRITE_TAC[CARLESON_SQRT_SCALE_ID] THEN
  MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN
  MP_TAC(ISPECL
   [`(\z. fourier (h:real->complex) (drop z) *
         cnj(fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop
           z))):real^1->complex`;
    `&2 zpow k`; `lift(tile_ymid(k,nI,nJ))`] INTEGRABLE_DILATE_UNIV) THEN
  ASM_SIMP_TAC[REAL_LT_IMP_NZ; REAL_ZPOW_LT; REAL_ARITH `&0 < &2`] THEN
  REWRITE_TAC[DROP_ADD; DROP_CMUL; LIFT_DROP;
    CARLESON_PHISIG_FHAT_CNJ_DILATE]);;

(* Endgame scalar solve: from Cx(1/sqrt) TT = Cx(inv 2^k) SS recover SS =    *)
(* Cx(sqrt) TT (multiply by 2^k, use 2^k/sqrt(2^k)=sqrt(2^k), 2^k inv 2^k =  *)
(* 1).                                                                       *)
let CARLESON_IP_SCALE_SOLVE = prove
 (`!(k:int) TT SS. &0 < &2 zpow k /\
     Cx(&1 / sqrt(&2 zpow k)) * TT = Cx(inv(&2 zpow k)) * SS
     ==> SS = Cx(sqrt(&2 zpow k)) * TT`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < sqrt(&2 zpow k)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[SQRT_POS_LT]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o AP_TERM `(*) (Cx(&2 zpow k))`) THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC; GSYM CX_MUL] THEN
  SUBGOAL_THEN `&2 zpow k * &1 / sqrt(&2 zpow k) = sqrt(&2 zpow k) /\
                &2 zpow k * inv(&2 zpow k) = &1`
   (fun th -> REWRITE_TAC[th]) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPEC `&2 zpow k` SQRT_POW_2) THEN
       ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
      REWRITE_TAC[REAL_POW_2] THEN CONV_TAC REAL_FIELD;
      MATCH_MP_TAC REAL_MUL_RINV THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[COMPLEX_MUL_LID] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REFL_TAC);;

(* 286O(b), Fremlin 2059-2062: the tile inner product as a single-variable   *)
(* integral after the change of variables z = 2^k t + y_s. This is the entry *)
(* to the coefficient identification <h|phi_s> = 2^{k/2} 2pi c_{-n} (2070).  *)
let CARLESON_IP_SUBST = prove
 (`!(h:real->complex) (k:int) (nI:int) (nJ:int). schwartz h ==>
     carleson_ip h (k,nI,nJ) =
     Cx(sqrt(&2 zpow k)) *
     integral (:real^1)
       (\t. fourier h (&2 zpow k * drop t + tile_ymid(k,nI,nJ)) *
            cexp(ii * Cx(real_of_int nI + &1/ &2) * Cx(drop t)) *
            fourier carleson_phi (drop t))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_IP_FHAT] THEN
  MP_TAC(ISPECL
   [`(\z. fourier (h:real->complex) (drop z) *
         cnj(fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop
           z))):real^1->complex`;
    `&2 zpow k`; `lift(tile_ymid(k,nI,nJ))`] INTEGRAL_DILATE_UNIV) THEN
  SUBGOAL_THEN
   `(\z. fourier (h:real->complex) (drop z) *
         cnj(fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop z)))
           integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_CNJ_PRODUCT_INTEGRABLE THEN REWRITE_TAC[ETA_AX] THEN
    ASM_SIMP_TAC[SCHWARTZ_FOURIER; PHISIG_SCHWARTZ; CARLESON_PHI_SCHWARTZ];
      ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LT_IMP_NZ; REAL_ZPOW_LT; REAL_ARITH `&0 < &2`] THEN
  REWRITE_TAC[DROP_ADD; DROP_CMUL; LIFT_DROP;
    CARLESON_PHISIG_FHAT_CNJ_DILATE] THEN
  ASM_SIMP_TAC[INTEGRAL_MID_CONST_PULL; CARLESON_IP_TARGET_INTEGRABLE] THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < x ==> abs x = x`; COMPLEX_CMUL] THEN
  DISCH_TAC THEN MATCH_MP_TAC CARLESON_IP_SCALE_SOLVE THEN ASM_REWRITE_TAC[]);;

(* Restrict an R-integral of a function vanishing outside [-1/5,1/5] to      *)
(* [-pi,pi].                                                                 *)
let INTEGRAL_TRUNCATE_PIPI = prove
 (`!(G:real->complex).
     (!t. &1 / &5 < abs t ==> G t = Cx(&0)) /\
     (\t. G(drop t)) integrable_on (:real^1)
     ==> integral (:real^1) (\t. G(drop t)) =
         integral (IMAGE lift (real_interval[--pi,pi])) (\t. G(drop t))`,
  REPEAT STRIP_TAC THEN
  GEN_REWRITE_TAC RAND_CONV [GSYM INTEGRAL_RESTRICT_UNIV] THEN
  REWRITE_TAC[] THEN MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `t:real^1` THEN
    DISCH_TAC THEN
  REWRITE_TAC[IN_IMAGE_LIFT_DROP; IN_REAL_INTERVAL] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[COMPLEX_VEC_0] THEN
  FIRST_ASSUM(MATCH_MP_TAC o check (is_forall o concl)) THEN
  MP_TAC PI_APPROX_32 THEN ASM_REAL_ARITH_TAC);;

(* Cx(2pi) c_{-n}(g) = int_{[-pi,pi]} g(t) e^{i n t} dt (282A coefficient    *)
(* form).                                                                    *)
let CFOURIER_COEFF_INTEGRAL_ID = prove
 (`!(g:real->complex) (nI:int).
     Cx(&2 * pi) * cfourier_coeff g (--nI) =
     integral (IMAGE lift (real_interval[--pi,pi]))
       (\t. g(drop t) * cexp(ii * Cx(real_of_int nI) * Cx(drop t)))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cfourier_coeff] THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC; GSYM CX_MUL] THEN
  SUBGOAL_THEN `Cx((&2 * pi) * inv(&2 * pi)) = Cx(&1)` SUBST1_TAC THENL
   [AP_TERM_TAC THEN MP_TAC PI_POS THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  REWRITE_TAC[COMPLEX_MUL_LID] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `t:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[int_neg_th; CX_NEG] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  CONV_TAC COMPLEX_RING);;

(* The tile g-integrand hhat(c t + y) e^{i(n+1/2)t} phihat(t) splits as      *)
(* [hhat(c t + y) e^{it/2} phihat(t)] * e^{i n t} (the 282A base g times     *)
(* e^{int}).                                                                 *)
let CARLESON_G_EXPSPLIT = prove
 (`!(h:real->complex) c yy (nI:int) t.
     fourier h (c * t + yy) * cexp(ii * Cx(real_of_int nI + &1/ &2) * Cx t) *
     fourier carleson_phi t =
     (fourier h (c * t + yy) * cexp(ii * Cx(&1/ &2) * Cx t) * fourier
       carleson_phi t) *
     cexp(ii * Cx(real_of_int nI) * Cx t)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[GSYM CEXP_ADD] THEN
  SUBGOAL_THEN
   `ii * Cx(real_of_int nI + &1/ &2) * Cx t =
    (ii * Cx(&1/ &2) * Cx t) + (ii * Cx(real_of_int nI) * Cx t)`
   (fun th -> ONCE_REWRITE_TAC[th]) THENL
   [REWRITE_TAC[CX_ADD] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  REWRITE_TAC[CEXP_ADD] THEN CONV_TAC COMPLEX_RING);;

(* The tile base g vanishes off [-1/5,1/5] (phihat support).                 *)
let CARLESON_G_SUPPORT = prove
 (`!(h:real->complex) yy c t. &1 / &5 < abs t ==>
     fourier h (c * t + yy) * cexp(ii * Cx(&1/ &2) * Cx t) * fourier
       carleson_phi t = Cx(&0)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_PHI_FHAT_SUPPORT] THEN CONV_TAC COMPLEX_RING);;

(* Keystone: the product of a Schwartz function with a COMPACTLY-SUPPORTED   *)
(* Schwartz function is Schwartz. The product chain (LEIBNIZ_CHAIN) inherits *)
(* the                                                                       *)
(* compact support of the second factor (CHAIN_SUPPORT: derivatives of a     *)
(* compactly-supported smooth chain stay supported), so it is a smooth chain *)
(* of                                                                        *)
(* compact support, hence Schwartz (COMPACT_SUPPORT_SMOOTH_IMP_SCHWARTZ).    *)
let SCHWARTZ_CSUPP_MUL = prove
 (`!(f:real->complex) (g:real->complex) R.
     &0 <= R /\ schwartz f /\ schwartz g /\ (!x. R < abs x ==> g x = Cx(&0))
     ==> schwartz (\x. f x * g x)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `df:num->real->complex` STRIP_ASSUME_TAC o
    GEN_REWRITE_RULE I [schwartz]) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `dg:num->real->complex` STRIP_ASSUME_TAC o
    GEN_REWRITE_RULE I [schwartz]) THEN
  MP_TAC(ISPECL [`df:num->real->complex`;
    `dg:num->real->complex`] LEIBNIZ_CHAIN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:num->real->complex` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
    `(\x. (f:real->complex) x * (g:real->complex) x) =
     (p:num->real->complex) 0`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real` THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:num->real->complex`; `R:real`]
    COMPACT_SUPPORT_SMOOTH_IMP_SCHWARTZ) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  X_GEN_TAC `m:num` THEN X_GEN_TAC `x:real` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`p:num->real->complex`; `R:real`] CHAIN_SUPPORT) THEN
  ASM_REWRITE_TAC[real_gt] THEN ANTS_TAC THENL
   [X_GEN_TAC `y:real` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(g:real->complex) y = Cx(&0)` SUBST1_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN
       ASM_REWRITE_TAC[]; CONV_TAC COMPLEX_RING];
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC]);;

(* The tile base g(t) = hhat(2^k t + yy) e^{it/2} phihat(t) is itself        *)
(* SCHWARTZ: the first factor A(t)=hhat(2^k t+yy) is Schwartz (284C + affine *)
(* reparam), and B(t)=e^{it/2} phihat(t) is Schwartz (SCHWARTZ_MODULATE on   *)
(* 284C) AND compactly supported (phihat vanishes off [-1/5,1/5]);           *)
(* SCHWARTZ_CSUPP_MUL closes it. This gives (for free) the C^2 chain,        *)
(* integrability, decay AND periodicity g(pi)=g(-pi)=0, g'(pi)=g'(-pi)=0     *)
(* needed for the 282Rb coefficient summability.                             *)
let CARLESON_G_SCHWARTZ = prove
 (`!(h:real->complex) k yy. schwartz h ==>
     schwartz (\t. fourier h (&2 zpow k * t + yy) *
                   cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
   [`\t. fourier (h:real->complex) (&2 zpow k * t + yy)`;
    `\t. cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t`;
    `&1 / &5`] SCHWARTZ_CSUPP_MUL)) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [REAL_ARITH_TAC;
    SUBGOAL_THEN `(\t. fourier (h:real->complex) (&2 zpow k * t + yy)) =
                  (\t. fourier h (yy + &2 zpow k * t))` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
       REAL_ARITH_TAC;
      ALL_TAC] THEN
    MP_TAC(BETA_RULE(ISPECL [`fourier(h:real->complex)`; `&2 zpow k`;
      `yy:real`]
      SCHWARTZ_AFFINE)) THEN
    DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_FOURIER THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_LT_IMP_NZ THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
        REAL_ARITH_TAC];
    MP_TAC(BETA_RULE(ISPECL [`fourier carleson_phi`;
      `&1 / &2`] SCHWARTZ_MODULATE)) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC SCHWARTZ_FOURIER THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
    X_GEN_TAC `t:real` THEN DISCH_TAC THEN
    ASM_SIMP_TAC[CARLESON_PHI_FHAT_SUPPORT; COMPLEX_MUL_RZERO]]);;

(* The finite tile partial sum is in L^2: it is a finite (LSPACE_VSUM) sum   *)
(* of                                                                        *)
(* complex multiples (LSPACE_COMPLEX_LMUL) of the L^2 tile transforms        *)
(* (PHISIG_FOURIER_L2). This is hypothesis (i) of                            *)
(* LSPACE_DOMINATED_CONVERGENCE for                                          *)
(* the b-ii limit of 286O(b).                                                *)
let CARLESON_TILESUM_FOURIER_L2 = prove
 (`!(h:real->complex) k nJ N.
     (\z. vsum {nI:int | abs nI <= &N}
                (\nI. carleson_ip h (k,nI,nJ) *
                      fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop z)))
     IN lspace (:real^1) (&2)`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC LSPACE_VSUM THEN
  REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN
  CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  X_GEN_TAC `nI:int` THEN DISCH_TAC THEN
  MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN
  REWRITE_TAC[PHISIG_FOURIER_L2]);;

(* The b-ii dominator envelope is L^2: \z. C * phihat((z-yy)/2^k) is a       *)
(* constant                                                                  *)
(* multiple of an affine reparametrisation of the Schwartz function phihat,  *)
(* hence                                                                     *)
(* Schwartz, hence L^2. Since the finite tile sums are bounded pointwise by  *)
(* such                                                                      *)
(* an envelope (CFOURIER_PARTIAL_UNIF_BOUND * |phihat|, via                  *)
(* CARLESON_PERK_FINITE),                                                    *)
(* this is the L^2 dominator for LSPACE_DOMINATED_CONVERGENCE.               *)
let CARLESON_DOMINATOR_L2 = prove
 (`!(C:real) yy k.
     (\z. Cx(C) * fourier carleson_phi ((drop z - yy) / &2 zpow k))
     IN lspace (:real^1) (&2)`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN
  SUBGOAL_THEN `~(&2 zpow k = &0)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_IMP_NZ THEN
    MP_TAC(ISPECL [`&2`; `k:int`] REAL_ZPOW_LT) THEN ANTS_TAC THENL
     [REAL_ARITH_TAC; REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\z. fourier carleson_phi ((drop z - yy) / &2 zpow k)) =
    (\z:real^1. (\u. fourier carleson_phi (--(yy / &2 zpow k) + (inv(&2 zpow
      k)) * u)) (drop z))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
     AP_TERM_TAC THEN
    UNDISCH_TAC `~(&2 zpow k = &0)` THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  MATCH_MP_TAC SCHWARTZ_L2 THEN
  MP_TAC(BETA_RULE(ISPECL [`fourier carleson_phi`; `inv(&2 zpow k)`;
    `--(yy / &2 zpow k)`]
    SCHWARTZ_AFFINE)) THEN
  DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_FOURIER THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
    MATCH_MP_TAC REAL_LT_IMP_NZ THEN MATCH_MP_TAC REAL_LT_INV THEN
    MP_TAC(ISPECL [`&2`; `k:int`] REAL_ZPOW_LT) THEN ANTS_TAC THENL
     [REAL_ARITH_TAC; REWRITE_TAC[]]]);;

(* The tile base g(t) = hhat(2^k t + yy) e^{it/2} phihat(t) is vector-       *)
(* differentiable everywhere: a product of three vector-differentiable       *)
(* factors                                                                   *)
(* (fourier h o affine, cexp o linear, fourier phihat). Feeds                *)
(* VECTOR_DIFF_IMP_                                                          *)
(* REIM_DIFF to give the Re/Im differentiability hypotheses of the complex   *)
(* 282L.                                                                     *)
let CARLESON_G_DIFFERENTIABLE = prove
 (`!(h:real->complex) k yy a. schwartz h ==>
     (\z. fourier h (&2 zpow k * drop z + yy) *
          cexp(ii * Cx(&1/ &2) * Cx(drop z)) *
          fourier carleson_phi (drop z)) differentiable (at a)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC DIFFERENTIABLE_COMPLEX_MUL_AT THEN CONJ_TAC THENL
   [ASM_SIMP_TAC[FOURIER_SCHWARTZ_AFFINE_DIFF]; ALL_TAC] THEN
  MATCH_MP_TAC DIFFERENTIABLE_COMPLEX_MUL_AT THEN CONJ_TAC THENL
   [REWRITE_TAC[COMPLEX_MUL_ASSOC] THEN REWRITE_TAC[CEXP_LINEAR_DIFF];
    ASM_SIMP_TAC[FOURIER_SCHWARTZ_DIFFERENTIABLE; CARLESON_PHI_SCHWARTZ]]);;

(* 286O-b-ii limit (Fremlin 2099-2100): cfourier_partial g N u --> g u at an *)
(* interior u in (-pi,pi), where g(t)=hhat(2^k t+yy) e^{it/2} phihat(t).     *)
(* Feeds                                                                     *)
(* the tile-g differentiability (CARLESON_G_DIFFERENTIABLE) into the complex *)
(* 282L                                                                      *)
(* (CFOURIER_CONVERGENCE_INTERIOR_CX): differentiability everywhere gives    *)
(* both the                                                                  *)
(* Re/Im interior-differentiability and the Re/Im integrability hypotheses.  *)
let CARLESON_G_LIMIT = prove
 (`!(h:real->complex) k yy u. schwartz h /\ --pi < u /\ u < pi
     ==> ((\N. cfourier_partial
                 (\t. fourier h (&2 zpow k * t + yy) *
                      cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t) N
                        u)
          --> (fourier h (&2 zpow k * u + yy) *
               cexp(ii * Cx(&1/ &2) * Cx u) * fourier carleson_phi u))
                 sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\t. fourier h (&2 zpow k * t + yy) *
         cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t`; `u:real`]
   CFOURIER_CONVERGENCE_INTERIOR_CX) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [SUBGOAL_THEN
     `!a. (\z. fourier h (&2 zpow k * drop z + yy) *
               cexp(ii * Cx(&1/ &2) * Cx(drop z)) *
               fourier carleson_phi (drop z)) differentiable (at a)`
     ASSUME_TAC THENL
     [GEN_TAC THEN ASM_SIMP_TAC[CARLESON_G_DIFFERENTIABLE]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[VECTOR_DIFF_IMP_REIM_ABSINT] THEN
    MP_TAC(ISPECL
     [`\t. fourier h (&2 zpow k * t + yy) *
           cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t`; `u:real`]
     VECTOR_DIFF_IMP_REIM_DIFF) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[]);;

(* 286O(b), Fremlin 2070: the tile inner product as a 282A Fourier           *)
(* coefficient.                                                              *)
(* <h|phi_s> = 2^{k/2} 2pi c_{-n}(g), g(t) = hhat(2^k t + y_s) e^{it/2}      *)
(* phihat(t).                                                                *)
(* Truncates the R-integral of CARLESON_IP_SUBST to [-pi,pi] (phihat support *)
(* in                                                                        *)
(* [-1/5,1/5] subset [-pi,pi]) and identifies it with the 282A coefficient.  *)
let CARLESON_IP_COEFF = prove
 (`!(h:real->complex) (k:int) (nI:int) (nJ:int). schwartz h ==>
     carleson_ip h (k,nI,nJ) =
     Cx(sqrt(&2 zpow k)) * Cx(&2 * pi) *
     cfourier_coeff
       (\t. fourier h (&2 zpow k * t + tile_ymid(k,nI,nJ)) *
            cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t) (--nI)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_IP_SUBST] THEN
  REWRITE_TAC[GSYM COMPLEX_MUL_ASSOC] THEN AP_TERM_TAC THEN
  REWRITE_TAC[CFOURIER_COEFF_INTEGRAL_ID] THEN
  ONCE_REWRITE_TAC[CARLESON_G_EXPSPLIT] THEN
  MATCH_MP_TAC INTEGRAL_TRUNCATE_PIPI THEN CONJ_TAC THENL
   [REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[CARLESON_G_SUPPORT] THEN CONV_TAC COMPLEX_RING;
    REWRITE_TAC[GSYM CARLESON_G_EXPSPLIT] THEN
    ASM_SIMP_TAC[CARLESON_IP_TARGET_INTEGRABLE]]);;

(* x_sigma (y - y_s) = (n_I + 1/2) * ((y - y_s)/2^k): the tile modulation    *)
(* phase in                                                                  *)
(* terms of the rescaled frequency u = (y - y_s)/2^k. (dyho_mid +            *)
(* REAL_ZPOW_NEG.)                                                           *)
let TILE_XMID_YDIFF = prove
 (`!k nI nJ y. tile_xmid(k,nI,nJ) * (y - tile_ymid(k,nI,nJ)) =
               (real_of_int nI + &1 / &2) * ((y - tile_ymid(k,nI,nJ)) / &2 zpow
                 k)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[tile_xmid; dyho_mid] THEN
  SUBGOAL_THEN `~(&2 zpow k = &0)` MP_TAC THENL
   [MATCH_MP_TAC REAL_LT_IMP_NZ THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[REAL_ZPOW_NEG] THEN CONV_TAC REAL_FIELD);;

(* 286O-b-ii summand (Fremlin 2089-2090): the per-tile term <h|phi_sigma>    *)
(* phihat_s(y) factored as Cx(2pi) * (c_{-nI}(g) e^{-inI u}) * (e^{-iu/2}    *)
(* phihat(u)), u=(y-y_s)/2^k.                                                *)
let CARLESON_SUMMAND_PRODUCT = prove
 (`!(h:real->complex) k nI nJ y. schwartz h ==>
     carleson_ip h (k,nI,nJ) * fourier (phi_sigma (k,nI,nJ) carleson_phi) y =
     Cx(&2 * pi) *
     (cfourier_coeff
        (\t. fourier h (&2 zpow k * t + tile_ymid(k,nI,nJ)) *
             cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t) (--nI) *
      cexp(--(ii * Cx(real_of_int nI) * Cx((y - tile_ymid(k,nI,nJ)) / &2 zpow
        k)))) *
     (cexp(--(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,nI,nJ)) / &2 zpow k))) *
      fourier carleson_phi ((y - tile_ymid(k,nI,nJ)) / &2 zpow k))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_IP_COEFF] THEN
  ASM_SIMP_TAC[PHISIG_FHAT; CARLESON_PHI_SCHWARTZ] THEN
  REWRITE_TAC[tile_k] THEN
  SUBGOAL_THEN
   `cexp(--(ii * Cx(tile_xmid(k,nI,nJ)) * Cx(y - tile_ymid(k,nI,nJ)))) =
    cexp(--(ii * Cx(real_of_int nI) * Cx((y - tile_ymid(k,nI,nJ)) / &2 zpow
      k))) *
    cexp(--(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,nI,nJ)) / &2 zpow k)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM CEXP_ADD] THEN AP_TERM_TAC THEN
    REWRITE_TAC[GSYM CX_MUL] THEN
    MP_TAC(ISPECL [`k:int`; `nI:int`; `nJ:int`; `y:real`] TILE_XMID_YDIFF) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[CX_ADD; CX_MUL] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  SUBGOAL_THEN
    `Cx(sqrt(&2 zpow k)) * Cx(&1 / sqrt(&2 zpow k)) = Cx(&1)` MP_TAC THENL
   [REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
    SUBGOAL_THEN `&0 < sqrt(&2 zpow k)` MP_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LT THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      CONV_TAC REAL_FIELD]; ALL_TAC] THEN
  CONV_TAC COMPLEX_RING);;

(* 286O-b-ii finite truncation (Fremlin 2087-2090): the R_k tile-sum at      *)
(* fixed k,nJ over |nI|<=N equals Cx(2pi) * cfourier_partial g N u *         *)
(* (e^{-iu/2} phihat(u)). (tile_ymid is nI-independent -- fixed Jhat_k -- so *)
(* g and u are constant in nI.)                                              *)
let CARLESON_PERK_FINITE = prove
 (`!(h:real->complex) k nJ y N. schwartz h ==>
     vsum {nI:int | abs nI <= &N}
          (\nI. carleson_ip h (k,nI,nJ) * fourier (phi_sigma (k,nI,nJ)
            carleson_phi) y) =
     Cx(&2 * pi) *
     cfourier_partial
       (\t. fourier h (&2 zpow k * t + tile_ymid(k,&0,nJ)) *
            cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t)
       N ((y - tile_ymid(k,&0,nJ)) / &2 zpow k) *
     (cexp(--(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,&0,nJ)) / &2 zpow k))) *
      fourier carleson_phi ((y - tile_ymid(k,&0,nJ)) / &2 zpow k))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
    [`\t. fourier (h:real->complex) (&2 zpow k * t + tile_ymid(k,&0,nJ)) *
          cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t`;
     `N:num`;
     `(y - tile_ymid(k,&0,nJ)) / &2 zpow k`;
     `cexp(--(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,&0,nJ)) / &2 zpow k))) *
      fourier carleson_phi ((y - tile_ymid(k,&0,nJ)) / &2 zpow k)`]
    CARLESON_FINITE_REINDEX_SUM) THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `nI:int` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`h:real->complex`; `k:int`; `nI:int`; `nJ:int`; `y:real`]
    CARLESON_SUMMAND_PRODUCT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `tile_ymid(k,nI,nJ) = tile_ymid(k,&0,nJ)` SUBST1_TAC THENL
   [REWRITE_TAC[tile_ymid]; ALL_TAC] THEN
  REFL_TAC);;

(* Raw per-k limit: the finite tile-sum truncations converge, combining the  *)
(* finite identity CARLESON_PERK_FINITE with the tile-g limit                *)
(* CARLESON_G_LIMIT (LIM_COMPLEX_LMUL pulls the nI-independent Cx(2pi)*W     *)
(* factor out).                                                              *)
let CARLESON_PERK_RAWLIMIT = prove
 (`!(h:real->complex) k nJ y. schwartz h /\ --pi < (y - tile_ymid(k,&0,nJ)) /
   &2 zpow k /\
     (y - tile_ymid(k,&0,nJ)) / &2 zpow k < pi
     ==> ((\N. vsum {nI:int | abs nI <= &N}
                    (\nI. carleson_ip h (k,nI,nJ) *
                          fourier (phi_sigma (k,nI,nJ) carleson_phi) y))
          --> Cx(&2 * pi) *
              (fourier h (&2 zpow k * ((y - tile_ymid(k,&0,nJ)) / &2 zpow k) +
                tile_ymid(k,&0,nJ)) *
               cexp(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,&0,nJ)) / &2 zpow k))
                 *
               fourier carleson_phi ((y - tile_ymid(k,&0,nJ)) / &2 zpow k)) *
              (cexp(--(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,&0,nJ)) / &2 zpow
                k))) *
               fourier carleson_phi ((y - tile_ymid(k,&0,nJ)) / &2 zpow k)))
                 sequentially`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[CARLESON_PERK_FINITE] THEN
  ABBREV_TAC `W = cexp(--(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,&0,nJ)) / &2
    zpow k))) *
               fourier carleson_phi ((y - tile_ymid(k,&0,nJ)) / &2 zpow k)`
                 THEN
  ONCE_REWRITE_TAC[COMPLEX_RING `Cx(&2 * pi) * P * W = (Cx(&2 * pi) * W) * P`]
    THEN
  MATCH_MP_TAC LIM_COMPLEX_LMUL THEN
  MATCH_MP_TAC CARLESON_G_LIMIT THEN ASM_REWRITE_TAC[]);;

(* 286O-b-ii (Fremlin 2105): the per-k tile identity in limit form. The      *)
(* finite                                                                    *)
(* tile-sum over abs nI <= N of <h|phi_(k,nI,nJ)> phihat_(k,nI,nJ)(y)        *)
(* converges to                                                              *)
(* 2pi hhat(y) phihat(u)^2, u=(y-yhat_k)/2^k. (phihat(u)^2 = psi_k(y).) The  *)
(* RHS                                                                       *)
(* simplifies via 2^k u + yhat_k = y and cexp(iu/2) cexp(-iu/2) = 1.         *)
let CARLESON_PERK_LIMIT = prove
 (`!(h:real->complex) k nJ y. schwartz h /\ --pi < (y - tile_ymid(k,&0,nJ)) /
   &2 zpow k /\
     (y - tile_ymid(k,&0,nJ)) / &2 zpow k < pi
     ==> ((\N. vsum {nI:int | abs nI <= &N}
                    (\nI. carleson_ip h (k,nI,nJ) *
                          fourier (phi_sigma (k,nI,nJ) carleson_phi) y))
          --> Cx(&2 * pi) * fourier h y *
              (fourier carleson_phi ((y - tile_ymid(k,&0,nJ)) / &2 zpow k) *
               fourier carleson_phi ((y - tile_ymid(k,&0,nJ)) / &2 zpow k)))
                 sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `k:int`; `nJ:int`;
    `y:real`] CARLESON_PERK_RAWLIMIT) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN
    AP_TERM_TAC THEN
  AP_TERM_TAC THEN
  SUBGOAL_THEN
   `&2 zpow k * ((y - tile_ymid(k,&0,nJ)) / &2 zpow k) + tile_ymid(k,&0,nJ) =
     y`
   SUBST1_TAC THENL
   [SUBGOAL_THEN `~(&2 zpow k = &0)` MP_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_NZ THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      CONV_TAC REAL_FIELD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `cexp(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,&0,nJ)) / &2 zpow k)) *
    cexp(--(ii * Cx(&1/ &2) * Cx((y - tile_ymid(k,&0,nJ)) / &2 zpow k))) =
      Cx(&1)`
   MP_TAC THENL
   [REWRITE_TAC[GSYM CEXP_ADD] THEN
    REWRITE_TAC[COMPLEX_RING `a + --a = Cx(&0)`; CEXP_0]; ALL_TAC] THEN
  CONV_TAC COMPLEX_RING);;

(* fourier carleson_phi is real-valued, so its complex square is Cx of the   *)
(* real square of its real part -- the form the carleson_theta term uses.    *)
let CARLESON_PHIHAT_SQ_RE = prove
 (`!u. fourier carleson_phi u * fourier carleson_phi u =
       Cx(Re(fourier carleson_phi u) pow 2)`,
  GEN_TAC THEN
  MP_TAC(SPEC `u:real` (CONJUNCT1(CONJUNCT2 carleson_phi))) THEN
  REWRITE_TAC[REAL] THEN
  DISCH_THEN(fun th -> GEN_REWRITE_TAC (LAND_CONV o BINOP_CONV) [SYM th]) THEN
  REWRITE_TAC[GSYM CX_MUL; REAL_POW_2]);;

(* 286O-b-ii in the carleson_theta-term form (Fremlin 2105): the finite      *)
(* tile-sum                                                                  *)
(* converges to 2pi hhat(y) * (theta-term) where the theta-term is           *)
(* Re(phihat(2^{-k}(y-yhat_k)))^2 (= psi_k(y) = the single carleson_theta    *)
(* summand for the scale-k tile).  Normalises the frequency argument to      *)
(* 2 zpow(--k)*(y-yhat_k) and uses phihat real (CARLESON_PHIHAT_SQ_RE).      *)
let CARLESON_PERK_LIMIT_RE = prove
 (`!(h:real->complex) k nJ y. schwartz h /\ --pi < (y - tile_ymid(k,&0,nJ)) /
   &2 zpow k /\
     (y - tile_ymid(k,&0,nJ)) / &2 zpow k < pi
     ==> ((\N. vsum {nI:int | abs nI <= &N}
                    (\nI. carleson_ip h (k,nI,nJ) *
                          fourier (phi_sigma (k,nI,nJ) carleson_phi) y))
          --> Cx(&2 * pi) * fourier h y *
              Cx(Re(fourier carleson_phi (&2 zpow (--k) * (y -
                tile_ymid(k,&0,nJ)))) pow 2))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `k:int`; `nJ:int`;
    `y:real`] CARLESON_PERK_LIMIT) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN
    AP_TERM_TAC THEN
  AP_TERM_TAC THEN
  SUBGOAL_THEN
   `(y - tile_ymid(k,&0,nJ)) / &2 zpow k = &2 zpow (--k) * (y -
     tile_ymid(k,&0,nJ))`
   SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_NEG] THEN
    SUBGOAL_THEN `~(&2 zpow k = &0)` MP_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_NZ THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      CONV_TAC REAL_FIELD]; ALL_TAC] THEN
  REWRITE_TAC[CARLESON_PHIHAT_SQ_RE]);;

(* The finite tile partial sums are dominated, uniformly in N, by an L^2     *)
(* envelope                                                                  *)
(* Cx(2pi B) * phihat((z-yy)/2^k).  Via CARLESON_PERK_FINITE the sum equals  *)
(* Cx(2pi) cfp(G) N u (e^{-iu/2} phihat u), u=(z-yy)/2^k, and                *)
(* CFOURIER_PARTIAL_UNIF_                                                    *)
(* BOUND caps |cfp(G) N u| by B = |c_0(G)| + sum|c_k(G)| + sum|c_{-k}(G)|    *)
(* (the tile                                                                 *)
(* base G is Schwartz with support in [-1/5,1/5], so both 282Rb tails are    *)
(* summable).                                                                *)
(* This B is the fixed dominator for LSPACE_DOMINATED_CONVERGENCE in the     *)
(* b-ii limit.                                                               *)
let CARLESON_TILESUM_DOMINATED = prove
 (`!(h:real->complex) k nJ.
     schwartz h
     ==> ?B. &0 <= B /\
             !N z. norm(vsum {nI:int | abs nI <= &N}
                        (\nI. carleson_ip h (k,nI,nJ) *
                              fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop
                                z)))
                   <= norm(Cx(&2 * pi * B) *
                           fourier carleson_phi ((drop z - tile_ymid(k,&0,nJ))
                             / &2 zpow k))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `G = \t. fourier (h:real->complex) (&2 zpow k * t +
    tile_ymid(k,&0,nJ)) *
                      cexp(ii * Cx(&1/ &2) * Cx t) * fourier carleson_phi t`
                        THEN
  SUBGOAL_THEN `schwartz (G:real->complex)` ASSUME_TAC THENL
   [EXPAND_TAC "G" THEN MATCH_MP_TAC CARLESON_G_SCHWARTZ THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC `G:real->complex` CFOURIER_PARTIAL_UNIF_BOUND) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_CSUPP_SUMMABLE_POS;
       MATCH_MP_TAC SCHWARTZ_CSUPP_SUMMABLE_NEG] THEN
    EXISTS_TAC `&1 / &5` THEN ASM_REWRITE_TAC[] THEN
    (CONJ_TAC THENL [REAL_ARITH_TAC; ALL_TAC]) THEN
    (CONJ_TAC THENL [MP_TAC PI_APPROX_32 THEN REAL_ARITH_TAC; ALL_TAC]) THEN
    EXPAND_TAC "G" THEN REWRITE_TAC[] THEN X_GEN_TAC `t:real` THEN
      DISCH_TAC THEN
    MATCH_MP_TAC CARLESON_G_SUPPORT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  EXISTS_TAC `norm(cfourier_coeff (G:real->complex) (&0)) +
              real_infsum (from 1) (\k. norm(cfourier_coeff G (&k))) +
              real_infsum (from 1) (\k. norm(cfourier_coeff G (-- &k)))` THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPECL [`0`; `&0:real`]) THEN
    MP_TAC(ISPEC `cfourier_partial (G:real->complex) 0 (&0)` NORM_POS_LE) THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`N:num`; `z:real^1`] THEN
  ASM_SIMP_TAC[CARLESON_PERK_FINITE] THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `norm(cexp(--(ii * Cx(&1/ &2) *
                Cx((drop z - tile_ymid(k,&0,nJ)) / &2 zpow k)))) = &1`
                  SUBST1_TAC THENL
   [SUBGOAL_THEN
     `--(ii * Cx(&1/ &2) * Cx((drop z - tile_ymid(k,&0,nJ)) / &2 zpow k)) =
      ii * Cx(--(&1/ &2 * (drop z - tile_ymid(k,&0,nJ)) / &2 zpow k))`
        SUBST1_TAC THENL
     [REWRITE_TAC[CX_NEG; CX_MUL] THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
    REWRITE_TAC[NORM_CEXP_II]; ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_LID] THEN
  REWRITE_TAC[REAL_ABS_MUL; REAL_ABS_NUM] THEN
  SUBGOAL_THEN `abs pi = pi` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN MP_TAC PI_APPROX_32 THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [REAL_ARITH `&2 * pi * B = (&2 * pi)
    * B`] THEN
  REWRITE_TAC[REAL_ARITH
   `(&2 * pi) * nc * np <= ((&2 * pi) * absB) * np <=>
    (&2 * pi) * nc * np <= (&2 * pi) * absB * np`] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [MP_TAC PI_APPROX_32 THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
   [`N:num`; `(drop z - tile_ymid(k,&0,nJ)) / &2 zpow k`]) THEN
  REAL_ARITH_TAC);;

(* The per-k tile partial sums converge POINTWISE EVERYWHERE to 2pi hhat(y)  *)
(* Re(phihat(2^{-k}(y-yy)))^2. Interior u=(y-yy)/2^k in (-pi,pi):            *)
(* CARLESON_PERK_                                                            *)
(* LIMIT_RE. Exterior |u|>=pi (>1/5): phihat(u)=0 kills the limit AND every  *)
(* finite                                                                    *)
(* tile sum (CARLESON_PERK_FINITE + phihat support), so it is the constant 0 *)
(* sequence.                                                                 *)
let CARLESON_PERK_LIMIT_ALL = prove
 (`!(h:real->complex) k nJ y.
     schwartz h
     ==> ((\N. vsum {nI:int | abs nI <= &N}
                (\nI. carleson_ip h (k,nI,nJ) *
                      fourier (phi_sigma (k,nI,nJ) carleson_phi) y))
          --> Cx(&2 * pi) * fourier h y *
              Cx(Re(fourier carleson_phi
                (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ)))) pow 2))
         sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&2 zpow (--k) * (y - tile_ymid(k,&0,nJ)) =
                (y - tile_ymid(k,&0,nJ)) / &2 zpow k` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_NEG] THEN
    SUBGOAL_THEN `~(&2 zpow k = &0)` MP_TAC THENL
     [MATCH_MP_TAC REAL_LT_IMP_NZ THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
       REAL_ARITH_TAC;
      CONV_TAC REAL_FIELD]; ALL_TAC] THEN
  ASM_CASES_TAC `--pi < (y - tile_ymid(k,&0,nJ)) / &2 zpow k /\
                 (y - tile_ymid(k,&0,nJ)) / &2 zpow k < pi` THENL
   [MATCH_MP_TAC CARLESON_PERK_LIMIT_RE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `&1 / &5 < abs((y - tile_ymid(k,&0,nJ)) / &2 zpow k)` ASSUME_TAC THENL
   [MP_TAC PI_APPROX_32 THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `fourier carleson_phi ((y - tile_ymid(k,&0,nJ)) / &2 zpow k) = Cx(&0)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_PHI_FHAT_SUPPORT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[RE_CX; COMPLEX_NORM_CX] THEN
  REWRITE_TAC[REAL_POW_ZERO; ARITH; COMPLEX_MUL_RZERO; CX_INJ] THEN
  SUBGOAL_THEN
   `!N. vsum {nI:int | abs nI <= &N}
          (\nI. carleson_ip h (k,nI,nJ) *
                fourier (phi_sigma (k,nI,nJ) carleson_phi) y) = Cx(&0)`
   (fun th -> REWRITE_TAC[th; LIM_CONST]) THEN
  GEN_TAC THEN ASM_SIMP_TAC[CARLESON_PERK_FINITE] THEN
  ASM_REWRITE_TAC[COMPLEX_MUL_RZERO; COMPLEX_MUL_LZERO]);;

(* 286O(b), b-ii CORE: the per-k tile partial sums converge to 2pi hhat      *)
(* psi_k IN L^2.                                                             *)
(* LSPACE_DOMINATED_CONVERGENCE: f_N = tile sum (CARLESON_TILESUM_FOURIER_L2 *)
(* in L^2),                                                                  *)
(* limit g = 2pi hhat(y) Re(phihat(2^{-k}(y-yy)))^2, dominator               *)
(* CARLESON_DOMINATOR_L2                                                     *)
(* with the pointwise bound CARLESON_TILESUM_DOMINATED, pointwise conv       *)
(* CARLESON_PERK_                                                            *)
(* LIMIT_ALL (everywhere, so the exceptional set is empty). This L^2         *)
(* convergence is                                                            *)
(* what threads the spatial region integral through the tile-sum limit       *)
(* (LPRODUCT_L2LIM)                                                          *)
(* in the 286O(b) filter-limit identity.                                     *)
let CARLESON_PERK_L2LIM = prove
 (`!(h:real->complex) k nJ.
     schwartz h
     ==> ((\N. lnorm (:real^1) (&2)
              (\z. vsum {nI:int | abs nI <= &N}
                     (\nI. carleson_ip h (k,nI,nJ) *
                           fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop z))
                             -
                   Cx(&2 * pi) * fourier h (drop z) *
                   Cx(Re(fourier carleson_phi
                     (&2 zpow (--k) * (drop z - tile_ymid(k,&0,nJ)))) pow 2)))
          ---> &0) sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `h:real->complex` CARLESON_TILESUM_DOMINATED) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`k:int`; `nJ:int`]) THEN
  DISCH_THEN(X_CHOOSE_THEN `B:real` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL
   [`\N z. vsum {nI:int | abs nI <= &N}
             (\nI. carleson_ip h (k,nI,nJ) *
                   fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop z))`;
    `\z:real^1. Cx(&2 * pi) * fourier h (drop z) *
                Cx(Re(fourier carleson_phi
                  (&2 zpow (--k) * (drop z - tile_ymid(k,&0,nJ)))) pow 2)`;
    `\z:real^1. Cx(&2 * pi * B) *
                fourier carleson_phi ((drop z - tile_ymid(k,&0,nJ)) / &2 zpow
                  k)`;
    `(:real^1)`; `&2`; `{}:real^1->bool`]
   LSPACE_DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; DIFF_EMPTY; IN_UNIV] THEN
  ANTS_TAC THENL [ALL_TAC; SIMP_TAC[]] THEN
  REPEAT CONJ_TAC THENL
   [REAL_ARITH_TAC;
    REWRITE_TAC[CARLESON_TILESUM_FOURIER_L2];
    REWRITE_TAC[CARLESON_DOMINATOR_L2];
    ASM_REWRITE_TAC[];
    GEN_TAC THEN MATCH_MP_TAC CARLESON_PERK_LIMIT_ALL THEN
      ASM_REWRITE_TAC[]]);;

(* 286P(b,c) integral bound: int_F Ah <= 4 C9                                *)
(* ||h||_2                                                                   *)
(* sqrt(mu F). Via 256Mb (int_F Ah = sup over finite {z_i} of int_F          *)
(* max|v_{z_i}|),                                                            *)
(* the E_i argmax partition + 246K (K246_SIGN_TRICK), the 286O(b)            *)
(* filter-limit tile identity, Fubini over counting measure on Q, and        *)
(* CARLESON_286N.                                                            *)
(* Reduction to the selected-window tile bound: given                        *)
(* the                                                                       *)
(* bound norm(int_F' carleson_wsel) <= C9 ||h||_2 sqrt(mu FF) on every       *)
(* argmax-selected                                                           *)
(* window integral, CARLESON_286P_BOUND follows. Route: 256Mb (CARLESON_     *)
(* 256MB_A) reduces int_FF carleson_A h <= 4C9||h||_2 sqrt muFF to the       *)
(* finite-max                                                                *)
(* integral bound for every enumeration u; the two easy legs are             *)
(* CARLESON_V_ABSINT +                                                       *)
(* CARLESON_V_UNIF_BOUND; the finite-max leg is CARLESON_FINITEMAX_246K      *)
(* (246K sign trick,                                                         *)
(* giving F' + factor 4) chained with the tile-bound gate.                   *)
let CARLESON_286P_FROM_TILEBOUND = prove
 (`(?C9. &0 <= C9 /\
      !(h:real->complex) u n FF F'.
         schwartz h /\ real_measurable FF /\
         measurable F' /\ F' SUBSET (IMAGE lift FF)
         ==> norm(integral F' (\x:real^1. carleson_wsel h u n (drop x)))
             <= C9 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
               FF))
   ==> ?C9. &0 <= C9 /\
     !(h:real->complex) FF.
        schwartz h /\ real_measurable FF
        ==> real_integral FF (carleson_A h)
            <= &4 * C9 * lnorm (:real^1) (&2) (\z. h(drop z)) *
              sqrt(real_measure FF)`,
  DISCH_THEN(X_CHOOSE_THEN `C9:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `C9:real` THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CARLESON_256MB_A THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:num->real` THEN REPEAT CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN REWRITE_TAC[ETA_AX] THEN
    MATCH_MP_TAC CARLESON_V_ABSINT THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPEC `h:real->complex` CARLESON_V_UNIF_BOUND) THEN
      ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC MONO_EXISTS THEN MESON_TAC[];
    X_GEN_TAC `n:num` THEN
    MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`;
      `FF:real->bool`] CARLESON_FINITEMAX_246K) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `F':real^1->bool` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `norm(integral F' (\x:real^1. carleson_wsel h u n (drop x)))
                  <= C9 * lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z))
                    * sqrt(real_measure FF)`
     ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ABBREV_TAC `Q = C9 * lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z)) *
      sqrt(real_measure FF)` THEN
    REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN ASM_REAL_ARITH_TAC]);;

(* The symmetric integer scale-segment {k | abs k <= &K} is finite (needed   *)
(* for                                                                       *)
(* LIM_VSUM over scales in the tile-limit collapse). INT_ARITH recasts abs k *)
(* as                                                                        *)
(* the two-sided bound --&K <= k /\ k <= &K, then FINITE_INT_SEG.            *)
let CARLESON_FINITE_KSEG = prove
 (`!K:num. FINITE {k:int | abs k <= &K}`,
  GEN_TAC THEN
  SUBGOAL_THEN `{k:int | abs k <= &K} = {k:int | --(&K) <= k /\ k <= &K}`
   (fun th -> REWRITE_TAC[th; FINITE_INT_SEG]) THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN INT_ARITH_TAC);;

(* The flat cell-scale-frequency triple index set {(j,k,nI) : j<=n, abs      *)
(* k<=K, abs nI<=N} is finite (bounding CROSS product) -- for the            *)
(* tile-regroup VSUM_IMAGE_GEN reindex.                                      *)
let CARLESON_TRIPLE_FINITE = prove
 (`!n K N. FINITE {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <=
   &N}`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `{j:num | j <= n} CROSS {(k:int,nI:int) | abs k <= &K /\ abs nI <=
    &N}` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_CROSS THEN CONJ_TAC THENL
     [REWRITE_TAC[FINITE_NUMSEG_LE];
      MATCH_MP_TAC FINITE_SUBSET THEN
      EXISTS_TAC `{k:int | abs k <= &K} CROSS {nI:int | abs nI <= &N}` THEN
      REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_CROSS THEN REWRITE_TAC[CARLESON_FINITE_KSEG];
        REWRITE_TAC[SUBSET; FORALL_PAIR_THM; IN_ELIM_PAIR_THM; IN_CROSS;
          IN_ELIM_THM] THEN
        MESON_TAC[]]];
    REWRITE_TAC[SUBSET; FORALL_PAIR_THM; IN_ELIM_THM; IN_CROSS;
      IN_ELIM_PAIR_THM] THEN
    MESON_TAC[PAIR_EQ]]);;

(* Witness-uniqueness: for u_j witnessing scale ks (some nJ has u_j in       *)
(* Jr(ks,0,nJ)), the                                                         *)
(* SELECT'd witness index @nJ.u_j in Jr(ks,0,nJ) equals nJs IFF u_j IN       *)
(* Jr(ks,0,nJs).                                                             *)
(* (CARLESON_THETA_SINGLE_NJ tile-uniqueness + SELECT_CONV.) This identifies *)
(* which cells                                                               *)
(* j collapse to a given tile under (j,k,nI)|->(k,nI,@nJ.u_j in Jr(k,0,nJ))  *)
(* in the regroup.                                                           *)
let CARLESON_WITNJ_EQ = prove
 (`!(u:num->real) j ks nIs nJs.
     (?nJ. u j IN tile_Jr(ks,&0,nJ))
     ==> ((@nJ. u j IN tile_Jr(ks,&0,nJ)) = nJs <=> u j IN
       tile_Jr(ks,&0,nJs))`,
  REPEAT STRIP_TAC THEN EQ_TAC THENL
   [DISCH_THEN(SUBST1_TAC o SYM) THEN CONV_TAC SELECT_CONV THEN
     ASM_MESON_TAC[];
    DISCH_TAC THEN
    SUBGOAL_THEN
      `u (j:num) IN tile_Jr(ks,&0,(@nJ:int. u j IN tile_Jr(ks,&0,nJ)))`
      ASSUME_TAC THENL
     [CONV_TAC SELECT_CONV THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`ks:int`; `&0:int`;
      `(@nJ:int. (u:num->real) j IN tile_Jr(ks,&0,nJ))`;
                   `&0:int`; `nJs:int`;
                     `(u:num->real) j`] CARLESON_THETA_SINGLE_NJ) THEN
    ASM_REWRITE_TAC[]]);;

(* Per-tile collapse-preimage (FIBER) identity: within the (range-bounded,   *)
(* witnessed)                                                                *)
(* triple set, the fiber over a tile (ks,nIs,nJs) under the collapse map     *)
(* (j,k,nI)|->(k,nI,@nJ.u_j in Jr(k,0,nJ)) is exactly {j<=n | u_j in         *)
(* Jr(ks,0,nJs)}, tupled                                                     *)
(* by (\j. (j,ks,nIs)). This is the geometric heart of the tile-regroup:     *)
(* cells j sharing                                                           *)
(* a witness nJs collapse to the same tile. (=>): k=ks case +                *)
(* CARLESON_WITNJ_EQ; (<=):                                                  *)
(* WITNJ_EQ turns u_j in Jr(ks,0,nJs) back into witnJ = nJs.                 *)
let CARLESON_TILE_FIBER = prove
 (`!(u:num->real) n K N ks nIs nJs.
     abs ks <= &K /\ abs nIs <= &N
     ==> {t | t IN {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <=
       &N /\
                                        (?nJ:int. u j IN tile_Jr(k,&0,nJ))} /\
          (\(j,k,nI). (k,nI,(@nJ:int. u j IN tile_Jr(k,&0,nJ)))) t =
            (ks,nIs,nJs)} =
         IMAGE (\j:num. (j,ks,nIs)) {j:num | j <= n /\ u j IN
           tile_Jr(ks,&0,nJs)}`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_IMAGE; FORALL_PAIR_THM;
    EXISTS_PAIR_THM] THEN
  REWRITE_TAC[PAIR_EQ] THEN
  MAP_EVERY X_GEN_TAC [`j:num`; `k:int`; `nI:int`] THEN
  REWRITE_TAC[IN_ELIM_PAIR_THM] THEN EQ_TAC THEN STRIP_TAC THENL
   [EXISTS_TAC `j:num` THEN REPLICATE_TAC 2 (POP_ASSUM MP_TAC) THEN
    ASM_CASES_TAC `k:int = ks` THEN ASM_REWRITE_TAC[] THEN
      REPEAT DISCH_TAC THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`u:num->real`; `j:num`; `ks:int`; `nIs:int`;
      `nJs:int`] CARLESON_WITNJ_EQ) THEN
    (ANTS_TAC THENL [ASM_MESON_TAC[]; DISCH_TAC]) THEN ASM_MESON_TAC[];
    REPEAT (FIRST_X_ASSUM SUBST_ALL_TAC) THEN
    SUBGOAL_THEN `?nJ:int. u (x:num) IN tile_Jr(ks,&0,nJ)` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`u:num->real`; `x:num`; `ks:int`; `nIs:int`;
      `nJs:int`] CARLESON_WITNJ_EQ) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    REPEAT CONJ_TAC THEN TRY (ASM_MESON_TAC[]) THEN
    MAP_EVERY EXISTS_TAC [`x:num`; `ks:int`; `nIs:int`] THEN
      ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

(* Guard-into-sum: (if P then vsum s f else vec 0) = vsum s (\i. if P then f *)
(* i else 0),                                                                *)
(* for FINITE s (else-branch: VSUM_0). Lets the witness-guard move inside    *)
(* the nI-sum so                                                             *)
(* the triple sum flattens cleanly.                                          *)
let VSUM_IF_GUARD = prove
 (`!P s (f:A->real^N). FINITE s
     ==> (if P then vsum s f else vec 0) = vsum s (\i. if P then f i else vec
       0)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[ETA_AX] THEN
  ASM_SIMP_TAC[VSUM_0]);;

(* Fiber-sum reduction (tile-regroup STEP B inner): for a range-bounded tile *)
(* (ks,nIs,nJs),                                                             *)
(* the VSUM_IMAGE_GEN inner fiber-sum over the collapse-preimage reduces to  *)
(* the target                                                                *)
(* tile-summand carleson_ip h s * int_{F' cap g^-1[Jr_s]} phi_s. Chain:      *)
(* CARLESON_TILE_                                                            *)
(* FIBER (fiber = tupled j-cells) -> VSUM_IMAGE (inj tupling) -> on-set      *)
(* witnJ=nJs so the                                                          *)
(* tile is literally s (VSUM_EQ + CARLESON_WITNJ_EQ) -> VSUM_COMPLEX_LMUL    *)
(* (pull <h|s>) ->                                                           *)
(* CARLESON_CELL_SUM_INTEGRAL (merge j-cells; tile_Jr nI-indep aligns the    *)
(* cell set).                                                                *)
let CARLESON_TILE_FIBER_SUM = prove
 (`!(h:real->complex) u n FF F' K N ks nIs nJs.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF) /\
     abs ks <= &K /\ abs nIs <= &N
     ==> vsum {t | t IN {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI
       <= &N /\
                                        (?nJ:int. u j IN tile_Jr(k,&0,nJ))} /\
              (\(j,k,nI). (k,nI,(@nJ:int. u j IN tile_Jr(k,&0,nJ)))) t =
                (ks,nIs,nJs)}
              (\(j,k,nI). carleson_ip h (k,nI,(@nJ:int. u j IN
                tile_Jr(k,&0,nJ))) *
                          integral (F' INTER {x:real^1 | cargmax (\i:num.
                            carleson_v h (u i)) n (drop x) = j})
                            (\z. phi_sigma (k,nI,(@nJ:int. u j IN
                              tile_Jr(k,&0,nJ))) carleson_phi (drop z)))
         = carleson_ip h (ks,nIs,nJs) *
           integral (F' INTER {x:real^1 | (u(cargmax (\i:num. carleson_v h (u
             i)) n (drop x))) IN tile_Jr(ks,nIs,nJs)})
             (\z. phi_sigma (ks,nIs,nJs) carleson_phi (drop z))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`u:num->real`; `n:num`; `K:num`; `N:num`; `ks:int`; `nIs:int`;
    `nJs:int`] CARLESON_TILE_FIBER) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`\j:num. (j:num,ks:int,nIs:int)`;
     `\(j:num,k:int,nI:int). carleson_ip (h:real->complex) (k,nI,(@nJ:int. u j
       IN tile_Jr(k,&0,nJ))) *
                          integral (F' INTER {x:real^1 | cargmax (\i:num.
                            carleson_v h (u i)) n (drop x) = j})
                            (\z. phi_sigma (k,nI,(@nJ:int. u j IN
                              tile_Jr(k,&0,nJ))) carleson_phi (drop z))`;
     `{j:num | j <= n /\ u j IN tile_Jr(ks,&0,nJs)}`] VSUM_IMAGE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `{j:num | j <= n}` THEN
      REWRITE_TAC[FINITE_NUMSEG_LE; SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
      REWRITE_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o AP_TERM `FST:num#int#int->num`) THEN
        REWRITE_TAC[]];
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]] THEN
  SUBGOAL_THEN
    `FINITE {j:num | j <= n /\ u j IN tile_Jr (ks,&0,nJs)}` ASSUME_TAC THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `{j:num | j <= n}` THEN
    REWRITE_TAC[FINITE_NUMSEG_LE; SUBSET; IN_ELIM_THM] THEN
      MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `vsum {j | j <= n /\ u j IN tile_Jr (ks,&0,nJs)}
       (\x. carleson_ip (h:real->complex) (ks,nIs,(@nJ:int. u x IN tile_Jr
         (ks,&0,nJ))) *
            integral (F' INTER {x' | cargmax (\i. carleson_v h (u i)) n (drop
              x') = x})
              (\z. phi_sigma (ks,nIs,(@nJ:int. u x IN tile_Jr (ks,&0,nJ)))
                carleson_phi (drop z))) =
    vsum {j | j <= n /\ u j IN tile_Jr (ks,&0,nJs)}
       (\x. carleson_ip (h:real->complex) (ks,nIs,nJs) *
            integral (F' INTER {x' | cargmax (\i. carleson_v h (u i)) n (drop
              x') = x})
              (\z. phi_sigma (ks,nIs,nJs) carleson_phi (drop z)))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `j:num` THEN
     REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `(@nJ:int. u (j:num) IN tile_Jr (ks,&0,nJ)) = nJs` (fun th ->
      REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`u:num->real`; `j:num`; `ks:int`; `nIs:int`;
      `nJs:int`] CARLESON_WITNJ_EQ) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[]; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ASM_SIMP_TAC[VSUM_COMPLEX_LMUL] THEN AP_TERM_TAC THEN
  CONV_TAC SYM_CONV THEN
  SUBGOAL_THEN
    `tile_Jr(ks,&0,nJs) = tile_Jr(ks,nIs,nJs)` (fun th -> ONCE_REWRITE_TAC[th])
    THENL
   [REWRITE_TAC[tile_Jr]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\z:real^1. phi_sigma (ks,nIs,nJs) carleson_phi (drop z)`;
     `h:real->complex`; `u:num->real`; `n:num`; `F':real^1->bool`;
       `tile_Jr(ks,nIs,nJs)`]
     CARLESON_CELL_SUM_INTEGRAL) THEN
  ANTS_TAC THENL
   [X_GEN_TAC `j:num` THEN
    MATCH_MP_TAC CARLESON_PHISIG_PIECE_INTEGRABLE THEN
      EXISTS_TAC `FF:real->bool` THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [TRANS_TAC SUBSET_TRANS `F':real^1->bool` THEN
       ASM_REWRITE_TAC[INTER_SUBSET];
      MATCH_MP_TAC CARLESON_WSEL_PIECE_LMEAS THEN ASM_REWRITE_TAC[]];
    DISCH_THEN SUBST1_TAC THEN REFL_TAC]);;

(* Guard-into-sum specialized to the N-frequency segment (pre-proved; feeds  *)
(* the flatten's guard-move without an inline-MESON rewrite, which would run *)
(* away).                                                                    *)
let GUARD_NSEG = prove
 (`!P N (f:int->real^2).
     (if P then vsum {nI:int | abs nI <= &N} f else vec 0) =
     vsum {nI:int | abs nI <= &N} (\nI. if P then f nI else vec 0)`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC VSUM_IF_GUARD THEN
  SUBGOAL_THEN `{nI:int | abs nI <= &N} = {nI:int | --(&N) <= nI /\ nI <= &N}`
   (fun th -> REWRITE_TAC[th; FINITE_INT_SEG]) THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN INT_ARITH_TAC);;

(* The frequency segment {nI | abs nI <= &N} is finite (companion of         *)
(* CARLESON_FINITE_KSEG).                                                    *)
let CARLESON_FINITE_NSEG = prove
 (`!N:num. FINITE {nI:int | abs nI <= &N}`,
  GEN_TAC THEN SUBGOAL_THEN
    `{nI:int | abs nI <= &N} = {nI:int | --(&N) <= nI /\ nI <= &N}`
   (fun th -> REWRITE_TAC[th; FINITE_INT_SEG]) THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM] THEN INT_ARITH_TAC);;

(* The scale-frequency pair segment {(k,nI) | abs k<=K /\ abs nI<=N} is      *)
(* finite (CROSS).                                                           *)
let CARLESON_FINITE_KNSEG = prove
 (`!K N:num. FINITE {(k:int,nI:int) | abs k <= &K /\ abs nI <= &N}`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `{(k:int,nI:int) | abs k <= &K /\ abs nI <= &N} =
                {k:int | abs k <= &K} CROSS {nI:int | abs nI <= &N}`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[EXTENSION; FORALL_PAIR_THM; IN_ELIM_PAIR_THM; IN_CROSS;
     IN_ELIM_THM];
    MATCH_MP_TAC FINITE_CROSS THEN
      REWRITE_TAC[CARLESON_FINITE_KSEG; CARLESON_FINITE_NSEG]]);;

(* Tile-regroup STEP A (flatten): the nested guarded cell/scale/freq vsum of *)
(* b_{K,N}                                                                   *)
(* equals a single vsum over the flat triple index set. Guard moved inside   *)
(* the nI-sum                                                                *)
(* (GUARD_NSEG), then VSUM_VSUM_PRODUCT twice (inner (k,nI), outer (j,-))    *)
(* with the nested-                                                          *)
(* pair product set reconciled to the flat triple set (EXTENSION + PAIR_EQ)  *)
(* + VSUM_EQ for                                                             *)
(* the summand pair-pattern. Abstract in gg,Q so it is a pure combinatorial  *)
(* identity.                                                                 *)
let CARLESON_WSEL_FLATTEN = prove
 (`!(gg:num->int->int->real^2) (Q:num->int->bool) n K N.
    vsum {j:num | j <= n}
      (\j. vsum {k:int | abs k <= &K}
        (\k. if Q j k then vsum {nI:int | abs nI <= &N} (\nI. gg j k nI) else
          vec 0))
    = vsum {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N}
        (\(j,k,nI). if Q j k then gg j k nI else vec 0)`,
  REPEAT GEN_TAC THEN ONCE_REWRITE_TAC[GUARD_NSEG] THEN BETA_TAC THEN
  SUBGOAL_THEN
   `!j:num. vsum {k:int | abs k <= &K}
        (\k. vsum {nI:int | abs nI <= &N} (\nI. if Q j k then
          (gg:num->int->int->real^2) j k nI else vec 0))
      = vsum {(k:int,nI:int) | abs k <= &K /\ abs nI <= &N}
          (\(k,nI). if Q j k then gg j k nI else vec 0)`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN
    MP_TAC(ISPECL [`{k:int | abs k <= &K}`; `\k:int. {nI:int | abs nI <= &N}`;
       `\k nI. if (Q:num->int->bool) j k then (gg:num->int->int->real^2) j k nI
         else vec 0`]
       VSUM_VSUM_PRODUCT) THEN
    ASM_SIMP_TAC[CARLESON_FINITE_KSEG; CARLESON_FINITE_NSEG] THEN
    REWRITE_TAC[IN_ELIM_THM; ETA_AX]; ALL_TAC] THEN
  MP_TAC(ISPECL [`{j:num | j <= n}`;
    `\j:num. {(k:int,nI:int) | abs k <= &K /\ abs nI <= &N}`;
     `\j. \(k:int,nI:int). if (Q:num->int->bool) j k then
       (gg:num->int->int->real^2) j k nI else vec 0`]
     VSUM_VSUM_PRODUCT) THEN
  ASM_SIMP_TAC[FINITE_NUMSEG_LE; CARLESON_FINITE_KNSEG] THEN DISCH_THEN
    SUBST1_TAC THEN
  SUBGOAL_THEN
   `{(i:num,j:int#int) | i IN {j:num | j <= n} /\ j IN {(k:int,nI:int) | abs k
     <= &K /\ abs nI <= &N}}
    = {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N}`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[EXTENSION; FORALL_PAIR_THM; IN_ELIM_THM; IN_ELIM_PAIR_THM] THEN
    REWRITE_TAC[PAIR_EQ] THEN MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC VSUM_EQ THEN REWRITE_TAC[FORALL_PAIR_THM; IN_ELIM_PAIR_THM] THEN
  REPEAT STRIP_TAC THEN REWRITE_TAC[]);;

(* Sequential-limit vs distance-to-limit-null bridge (topology helper for    *)
(* the tile-limit diagonal extraction). (a --> L) <=> (\m. dist(a m,L)) ---> *)
(* 0.                                                                        *)
let LIM_DIST_NULL_EQ = prove
 (`!(a:num->real^N) L.
     (a --> L) sequentially <=> ((\m. dist(a m, L)) ---> &0) sequentially`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[LIM_SEQUENTIALLY; REALLIM_SEQUENTIALLY; REAL_SUB_RZERO] THEN
  REWRITE_TAC[MESON[dist; DIST_POS_LE;
    REAL_ABS_REFL] `abs(dist(x:real^N,y)) = dist(x,y)`]);;

(* Diagonal-sequence extraction: if a --> L and for each m the row b m N --> *)
(* a m                                                                       *)
(* (as N-->inf), there is a diagonal index nfun with (\m. b m (nfun m)) -->  *)
(* L. Pick                                                                   *)
(* nfun m with dist(b m (nfun m), a m) < 1/(m+1); then dist(b m(nfun m),L)   *)
(* <=                                                                        *)
(* 1/(m+1) + dist(a m,L) --> 0 by REALLIM_NULL_COMPARISON. Keystone for      *)
(* collapsing                                                                *)
(* the tile-limit's nested lim_K/lim_N into a single Qenum sequence.         *)
let LIM_DIAGONAL_SEQ = prove
 (`!(b:num->num->real^N) a (L:real^N).
     (a --> L) sequentially /\
     (!m. ((\N. b m N) --> a m) sequentially)
     ==> ?nfun:num->num. ((\m. b m (nfun m)) --> L) sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!m:num. ?N:num. dist(b m N:real^N, a m) < inv(&m + &1)`
   (fun th -> MP_TAC(REWRITE_RULE[SKOLEM_THM] th)) THENL
   [X_GEN_TAC `m:num` THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `m:num`) THEN
    REWRITE_TAC[LIM_SEQUENTIALLY] THEN
    DISCH_THEN(MP_TAC o SPEC `inv(&m + &1)`) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC REAL_LT_INV THEN REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `N:num` (MP_TAC o SPEC `N:num`)) THEN
    REWRITE_TAC[LE_REFL] THEN MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `nfun:num->num` ASSUME_TAC) THEN
  EXISTS_TAC `nfun:num->num` THEN
  ONCE_REWRITE_TAC[LIM_DIST_NULL_EQ] THEN CONV_TAC(DEPTH_CONV BETA_CONV) THEN
  MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN
  EXISTS_TAC `\m:num. inv(&m + &1) + dist(a m:real^N, L)` THEN CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
    X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `abs(dist((b:num->num->real^N) m ((nfun:num->num) m), L:real^N)) =
      dist((b:num->num->real^N) m ((nfun:num->num) m), L)`
     SUBST1_TAC THENL [REWRITE_TAC[REAL_ABS_REFL; DIST_POS_LE]; ALL_TAC] THEN
    MP_TAC(ISPECL
     [`(b:num->num->real^N) m ((nfun:num->num) m)`;
      `(a:num->real^N) m`; `L:real^N`] DIST_TRIANGLE) THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `m:num` o
      check(fun th -> is_forall(concl th) && free_in `nfun:num->num` (concl
        th))) THEN
    REAL_ARITH_TAC;
    MATCH_MP_TAC REALLIM_NULL_ADD THEN CONJ_TAC THENL
     [REWRITE_TAC[REALLIM_1_OVER_N_OFFSET];
      ASM_MESON_TAC[LIM_DIST_NULL_EQ]]]);;


(* Ahat_n f integrable on any measurable set (measurable + loc-L^1 const     *)
(* bound).                                                                   *)
let CARLESON_AHAT_TRUNC_INTEGRABLE_GEN = prove
 (`!(f:real->complex) n FF.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ &0 <= n /\ real_measurable FF
     ==> (\y. carleson_Ahat_trunc f n y) real_integrable_on FF`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `\y:real. inv(sqrt(&2 * pi)) *
     drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
       lift(norm((f:real->complex)(drop x)))))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC CARLESON_AHAT_TRUNC_MEASURABLE THEN ASM_REWRITE_TAC[];
    ONCE_REWRITE_TAC[GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
      ASM_REWRITE_TAC[GSYM REAL_MEASURABLE];
    X_GEN_TAC `y:real` THEN DISCH_TAC THEN
    SUBGOAL_THEN `&0 <= carleson_Ahat_trunc f n y` ASSUME_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_POS THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `carleson_Ahat_trunc f n y <= inv(sqrt(&2 * pi)) *
        drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
          lift(norm((f:real->complex)(drop x)))))`
     ASSUME_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_FINITE THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REAL_ARITH_TAC]);;

(* Truncated Schwartz bound: int_F Ahat_n h <= C10 ||h||_2 sqrt muF (from    *)
(* gate).                                                                    *)
let CARLESON_286T_TRUNC_SCHWARTZ = prove
 (`!(h:real->complex) FF n C10.
     &0 <= C10 /\ schwartz h /\ real_measurable FF /\ &0 <= n /\
     real_integral FF (carleson_Ahat h)
       <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure FF)
     ==> real_integral FF (\y. carleson_Ahat_trunc h n y)
         <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
           FF)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral FF (carleson_Ahat h)` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE_GEN THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC SCHWARTZ_L2 THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC CARLESON_AHAT_SCHWARTZ_INTEGRABLE THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `y:real` THEN DISCH_TAC THEN BETA_TAC THEN
    MATCH_MP_TAC CARLESON_AHAT_TRUNC_SCHWARTZ_LE THEN ASM_REWRITE_TAC[]]);;

(* Integrate the 286T(c) SUB_BOUND over [-M,M]: Ahat_n f-integral vs Ahat_n  *)
(* h.                                                                        *)
let CARLESON_TRUNC_DENSITY_STEP = prove
 (`!(f:real->complex) h M n.
     &0 <= n /\ (\z. f(drop z)) IN lspace (:real^1) (&2) /\ schwartz h
     ==> real_integral (real_interval[--(&M),&M]) (\y. carleson_Ahat_trunc f n
       y)
         <= real_integral (real_interval[--(&M),&M]) (\y. carleson_Ahat_trunc h
           n y) +
            (inv(sqrt(&2 * pi)) * sqrt(&2 * n) *
             lnorm (:real^1) (&2) (\z. f(drop z) - h(drop z))) * (&2 * &M)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z. (h:real->complex)(drop z)) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_L2 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\y. carleson_Ahat_trunc (f:real->complex) n y`;
    `\y. carleson_Ahat_trunc (h:real->complex) n y +
         inv(sqrt(&2 * pi)) * sqrt(&2 * n) *
         lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z))`;
    `real_interval[--(&M),&M]`] REAL_INTEGRAL_LE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE_GEN THEN
      ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
      MATCH_MP_TAC REAL_INTEGRABLE_ADD THEN CONJ_TAC THENL
       [MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE_GEN THEN
        ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
        ONCE_REWRITE_TAC[GSYM REAL_MUL_RID] THEN
          MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
        REWRITE_TAC[GSYM REAL_MEASURABLE; REAL_MEASURABLE_REAL_INTERVAL]];
      X_GEN_TAC `y:real` THEN DISCH_TAC THEN BETA_TAC THEN
      MATCH_MP_TAC CARLESON_AHAT_TRUNC_SUB_BOUND THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `b = c ==> a <= b ==> a <= c`) THEN
  W(MP_TAC o PART_MATCH (lhs o rand) REAL_INTEGRAL_ADD o lhs o snd) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE_GEN THEN
      ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
      ONCE_REWRITE_TAC[GSYM REAL_MUL_RID] THEN
        MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
      REWRITE_TAC[GSYM REAL_MEASURABLE; REAL_MEASURABLE_REAL_INTERVAL]];
    DISCH_THEN SUBST1_TAC] THEN
  AP_TERM_TAC THEN
  SUBGOAL_THEN `--(&M):real <= &M` ASSUME_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_INTEGRAL_CONST] THEN REAL_ARITH_TAC);;

(* lnorm reverse triangle: ||h||_2 <= ||f||_2 + ||f-h||_2.                   *)
let LNORM_TRIANGLE_SUB_H = prove
 (`!(f:real->complex) h.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ (\z. h(drop z)) IN lspace
       (:real^1) (&2)
     ==> lnorm (:real^1) (&2) (\z. h(drop z))
         <= lnorm (:real^1) (&2) (\z. f(drop z)) +
            lnorm (:real^1) (&2) (\z. f(drop z) - h(drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. h(drop z)) =
    (\z:real^1. (f:real->complex)(drop z) + --(f(drop z) - h(drop z)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  MP_TAC(ISPECL [`(:real^1)`; `&2`; `\z. (f:real->complex)(drop z)`;
                 `\z. --((f:real->complex)(drop z) - h(drop z))`]
                   LNORM_TRIANGLE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[REAL_ARITH `&1 <= &2`] THEN
    MATCH_MP_TAC LSPACE_NEG THEN MATCH_MP_TAC LSPACE_SUB THEN
    ASM_REWRITE_TAC[REAL_POS];
    REWRITE_TAC[LNORM_NEG]]);;

(* Arithmetic: 0<K, 0<=t, t<eps/K, 0<=K-1 ==> t*(K-1) <= eps.                *)
let TRUNC_EPS_ARITH = prove
 (`!K t eps. &0 < K /\ &0 <= t /\ t < eps / K /\ &0 <= K - &1
             ==> t * (K - &1) <= eps`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < eps / K` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `(eps / K) * (K - &1)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_RMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `(eps / K) * (K - &1) <= (eps / K) * K` MP_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
     REAL_ARITH_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_DIV_RMUL; REAL_LT_IMP_NZ]);;

(* [286T(c), H1] general truncated bound int_{[-M,M]} Ahat_n f <= C10        *)
(* ||f||_2                                                                   *)
(* sqrt(2M) for f in L^2, from the Schwartz gate by density (284N).  This is *)
(* exactly the H1 hypothesis of CARLESON_286T_FROM_TRUNC / CARLESON_286U_    *)
(* EXISTS_FROM_BOUNDS. ---                                                   *)
let CARLESON_286T_TRUNC_GENERAL = prove
 (`!(f:real->complex) M n C10.
     &0 <= C10 /\ &0 <= n /\ (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) FF.
        schwartz h /\ real_measurable FF
        ==> real_integral FF (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              FF))
     ==> real_integral (real_interval[--(&M),&M]) (\y. carleson_Ahat_trunc f n
       y)
         <= C10 * lnorm (:real^1) (&2) (\z. f(drop z)) * sqrt(&2 * &M)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_EPSILON THEN
  X_GEN_TAC `eps:real` THEN DISCH_TAC THEN
  ABBREV_TAC `K = &1 + C10 * sqrt(&2 * &M) +
               inv(sqrt(&2 * pi)) * sqrt(&2 * n) * (&2 * &M)` THEN
  SUBGOAL_THEN `&0 <= C10 * sqrt(&2 * &M)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN
     ASM_SIMP_TAC[SQRT_POS_LE; REAL_LE_MUL; REAL_POS];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 <= inv(sqrt(&2 * pi)) * sqrt(&2 * n) * (&2 * &M)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN
    SIMP_TAC[REAL_LE_INV_EQ; SQRT_POS_LE; REAL_LE_MUL; REAL_POS;
      PI_POS_LE] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN
    ASM_SIMP_TAC[SQRT_POS_LE; REAL_LE_MUL; REAL_POS];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < K` ASSUME_TAC THENL [EXPAND_TAC "K" THEN
    ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < eps / K` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_DIV THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC `\z. (f:real->complex)(drop z)` LSPACE_APPROXIMATE_SCHWARTZ)
    THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun dth -> MP_TAC(MATCH_MP dth (ASSUME `&0 < eps / K`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `h:real->complex` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
    `(\z. (h:real->complex)(drop z)) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_L2 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `real_measure(real_interval[--(&M),&M]) = &2 * &M` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->complex`; `h:real->complex`; `M:num`; `n:real`]
    CARLESON_TRUNC_DENSITY_STEP) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`h:real->complex`; `real_interval[--(&M),&M]`; `n:real`;
    `C10:real`]
    CARLESON_286T_TRUNC_SCHWARTZ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL] THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPECL [`h:real->complex`;
      `real_interval[--(&M),&M]`] th)) THEN
    ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;
    `h:real->complex`] LNORM_TRIANGLE_SUB_H) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`K:real`;
    `lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z))`;
                 `eps:real`] TRUNC_EPS_ARITH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC LNORM_POS_LE THEN REWRITE_TAC[REAL_ARITH `&1 <= &2`] THEN
      MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_POS];
      EXPAND_TAC "K" THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `C10 * lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z)) * sqrt(&2 * &M)
     +
    (inv(sqrt(&2 * pi)) * sqrt(&2 * n) *
     lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z))) * (&2 *
       &M)` THEN
  CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `C10 * lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z)) * sqrt(&2 * &M)
    <= C10 * lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z)) * sqrt(&2 *
      &M) +
       lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z)) * (C10
         * sqrt(&2 * &M))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC
     `C10 * (lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z)) +
             lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z)))
               *
      sqrt(&2 * &M)` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[REAL_MUL_ASSOC] THEN MATCH_MP_TAC REAL_LE_RMUL THEN
      SIMP_TAC[SQRT_POS_LE; REAL_LE_MUL; REAL_POS] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_ADD_RDISTRIB; REAL_ADD_LDISTRIB] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `(C10 * lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z)) * sqrt(&2 * &M)
     +
     lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z)) * (C10 *
       sqrt(&2 * &M))) +
    (inv(sqrt(&2 * pi)) * sqrt(&2 * n) *
     lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z))) * (&2 *
       &M)` THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(fun th ->
    if can (find_term (fun t -> t = `K - &1`)) (concl th)
    then MP_TAC th else NO_TAC) THEN
  EXPAND_TAC "K" THEN
  MATCH_MP_TAC(REAL_ARITH
   `c1 = t * cc /\ c2 = t * dd
    ==> t * ((&1 + cc + dd) - &1) <= eps
        ==> (a + c1) + c2 <= a + eps`) THEN
  CONJ_TAC THEN REAL_ARITH_TAC);;


(* --- 286U(b) contradiction, arithmetic core (Fremlin 3013-3020): the chain *)
(* e*muF <= (e * sqrt e)*sqrt muF forces muF <= e.  (Fremlin's eps muF <=    *)
(* eps^{3/2} sqrt muF => muF <= eps, with eps^{3/2} = eps*sqrt eps.) Square  *)
(* the                                                                       *)
(* hypothesis (both sides >= 0), use (sqrt x)^2 = x, cancel e^2*muF > 0. --- *)
let LNORM_TRUNC_CONG = prove
 (`!(f:real->complex) n.
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> lnorm (:real^1) (&2)
           (\z. (\x. if abs x <= &n then Cx(&0) else f x) (drop z)) =
         lnorm (:real^1) (&2)
           (\z. f(drop z) - (if z IN ball(vec 0,&n) then f(drop z) else vec
             0))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `(\z:real^1. if abs(drop z) <= &n then Cx(&0) else (f:real->complex)(drop
     z)) IN
    lspace (:real^1) (&2) /\
    (\z:real^1. f(drop z) - (if z IN ball(vec 0,&n) then f(drop z) else vec 0))
      IN
    lspace (:real^1) (&2)`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN
       `(\z:real^1. if abs(drop z) <= &n then Cx(&0) else
         (f:real->complex)(drop z)) =
        (\z:real^1. f(drop z) -
            (if z IN interval[lift(--(&n)),lift(&n)] then f(drop z) else vec
              0))`
       SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real^1` THEN
        REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP;
          REAL_ARITH `--(&n) <= drop w /\ drop w <= &n <=> abs(drop w) <= &n`]
            THEN
        COND_CASES_TAC THEN REWRITE_TAC[COMPLEX_SUB_RZERO; COMPLEX_VEC_0] THEN
        CONV_TAC COMPLEX_RING;
        MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_POS] THEN
        MATCH_MP_TAC TRUNC_IN_LSPACE THEN
        ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`; LEBESGUE_MEASURABLE_INTERVAL]];
      MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_POS] THEN
      MATCH_MP_TAC TRUNC_IN_LSPACE THEN
      ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`; LEBESGUE_MEASURABLE_BALL]];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_LE_ANTISYM] THEN
  CONJ_TAC THEN MATCH_MP_TAC LNORM_MONO THEN
  EXISTS_TAC `{lift(&n), lift(--(&n))}` THEN
  ASM_REWRITE_TAC[NEGLIGIBLE_INSERT; NEGLIGIBLE_SING; REAL_POS] THEN
  X_GEN_TAC `z:real^1` THEN
  REWRITE_TAC[IN_DIFF; IN_UNIV; IN_INSERT; NOT_IN_EMPTY; DE_MORGAN_THM;
              GSYM DROP_EQ; LIFT_DROP] THEN
  STRIP_TAC THEN
  REWRITE_TAC[BALL_1; IN_INTERVAL_1; VECTOR_SUB_LZERO; VECTOR_ADD_LID;
              DROP_NEG; LIFT_DROP; DROP_VEC] THEN
  COND_CASES_TAC THEN COND_CASES_TAC THEN
  REWRITE_TAC[COMPLEX_SUB_RZERO; COMPLEX_VEC_0; COMPLEX_SUB_REFL;
    REAL_LE_REFL] THEN
  ASM_REAL_ARITH_TAC);;

let CARLESON_TRUNC_LNORM_LIM = prove
 (`!(f:real->complex).
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> ((\n. lnorm (:real^1) (&2)
              (\z. (\x. if abs x <= &n then Cx(&0) else f x) (drop z))) --->
                &0)
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`sequentially`;
    `\n. lnorm (:real^1) (&2)
          (\z. (f:real->complex)(drop z) -
               (if z IN ball(vec 0,&n) then f(drop z) else vec 0))`;
    `\n. lnorm (:real^1) (&2)
          (\z. if abs(drop z) <= &n then Cx(&0) else (f:real->complex)(drop
            z))`;
    `&0:real`] REALLIM_TRANSFORM_EVENTUALLY) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
    X_GEN_TAC `n:num` THEN DISCH_TAC THEN CONV_TAC SYM_CONV THEN
    MP_TAC(ISPECL [`f:real->complex`; `n:num`] LNORM_TRUNC_CONG) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`\z:real^1. (f:real->complex)(drop z)`;
      `&2:real`] TRUNC_LNORM_LIM) THEN
    ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`]]);;

(* --- The oscillation-connector A_n -> 0 supplier: A_n = C10 ||f_1n||_2     *)
(* where                                                                     *)
(* f_1n = f off [-n,n] (the truncation), so ||f_1n||_2 -> 0                  *)
(* (CARLESON_TRUNC_LNORM_                                                    *)
(* LIM) and A_n -> 0 (REALLIM_LMUL).  This is the (A ---> &0) hypothesis of  *)
(* CARLESON_OSC_BADSET_NEG, with C10 the 286T constant. ---                  *)
let CARLESON_TRUNC_COEFF_LIM = prove
 (`!(f:real->complex) C10.
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> ((\n. C10 * lnorm (:real^1) (&2)
              (\z. (\x. if abs x <= &n then Cx(&0) else f x) (drop z))) --->
                &0)
         sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `((\n. C10 * lnorm (:real^1) (&2)
          (\z. (\x. if abs x <= &n then Cx(&0) else f x) (drop z))) ---> C10 *
            &0)
    sequentially`
   MP_TAC THENL
   [MATCH_MP_TAC REALLIM_LMUL THEN
    MATCH_MP_TAC CARLESON_TRUNC_LNORM_LIM THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_MUL_RZERO]]);;

(* --- 286U(a) connector (Fremlin mt286.tex 2966-2974): inf_n gamma_n(y)=0   *)
(* (stated as: gamma_m(y) gets arbitrarily small) gives the tail-Cauchy      *)
(* hypothesis of CARLESON_286U_CAUCHY/_SYMLIM for the truncated integral     *)
(* II a b = Cx(1/sqrt2pi) int_[a,b] e^{-ixy}f. For e>0, pick m with          *)
(* gamma_m(y)                                                                *)
(* <= e; each window-difference (a<=-m, b>=m) is a member of gamma_m's       *)
(* sup-set,                                                                  *)
(* hence <= gamma_m(y) <= e (pull the real scalar out of norm, member-<=-sup *)
(* via                                                                       *)
(* REAL_LE_SUP with the family's ?B bound). ---                              *)
let CARLESON_GAMMA_INF_CAUCHY = prove
 (`!(f:real->complex) y.
     (!n. ?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)) -
                  integral (IMAGE lift (real_interval[--(&n),&n]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <= B)
                      /\
     (!e. &0 < e ==> ?m. carleson_gamma f (&m) y <= e)
     ==> (!e. &0 < e ==> ?N. &0 <= N /\
          !a b. a <= --N /\ N <= b ==>
            norm((\a b. Cx(inv(sqrt(&2 * pi))) *
                  integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) a b -
                 (\a b. Cx(inv(sqrt(&2 * pi))) *
                  integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) (--N)
                      N) <= e)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `m:num`) THEN
  EXISTS_TAC `&m:real` THEN REWRITE_TAC[REAL_POS] THEN
  MAP_EVERY X_GEN_TAC [`a:real`; `b:real`] THEN STRIP_TAC THEN BETA_TAC THEN
  REWRITE_TAC[GSYM COMPLEX_SUB_LDISTRIB; COMPLEX_NORM_MUL;
    COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `abs(inv(sqrt(&2 * pi))) = inv(sqrt(&2 * pi))` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC REAL_LE_INV THEN
    MATCH_MP_TAC SQRT_POS_LE THEN MP_TAC PI_POS THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `carleson_gamma f (&m) y` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[carleson_gamma] THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `B:real` o SPEC `m:num`) THEN
  MP_TAC(ISPECL
   [`{ inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a',b']))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)) -
            integral (IMAGE lift (real_interval[--(&m),&m]))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
     | a',b' | a' <= --(&m) /\ &m <= b' }`;
    `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x))
              -
          integral (IMAGE lift (real_interval[--(&m),&m]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))`;
    `B:real`;
    `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x))
              -
          integral (IMAGE lift (real_interval[--(&m),&m]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))`]
   REAL_LE_SUP) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_REFL];
    REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC]);;

(* --- 286U(b) measurability of the "bad set" slice: for each e, the set     *)
(* {y | !m. gamma_m(y) >= e} = INTERS_m {y | gamma_m(y) >= e} is             *)
(* real-lebesgue-                                                            *)
(* measurable (countable intersection of measurable superlevels). This is    *)
(* the                                                                       *)
(* measurability prereq for the 286U(b) negligibility argument.  Each member *)
(* {gamma_(&m) >= e} is measurable by CARLESON_GAMMA_MEASURABLE (which needs *)
(* the                                                                       *)
(* window family bounded above at each y, supplied here for all m). ---      *)
let REAL_NEGLIGIBLE_BOUNDED_EXHAUSTION = prove
 (`!S:real->bool.
     (!M:num. real_negligible (S INTER real_interval[--(&M),&M]))
     ==> real_negligible S`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `S = UNIONS { S INTER real_interval[--(&M),&M] | M IN (:num) }`
   SUBST1_TAC THENL
   [MATCH_MP_TAC(SET_RULE
     `(!x. x IN S ==> ?u. u IN f /\ x IN u) /\ (!u. u IN f ==> u SUBSET S)
      ==> S = UNIONS f`) THEN
    CONJ_TAC THENL
     [X_GEN_TAC `x:real` THEN DISCH_TAC THEN
      MP_TAC(SPEC `abs x` REAL_ARCH_SIMPLE) THEN
      DISCH_THEN(X_CHOOSE_THEN `M:num` ASSUME_TAC) THEN
      EXISTS_TAC `S INTER real_interval[--(&M),&M]` THEN CONJ_TAC THENL
       [REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `M:num` THEN
        REWRITE_TAC[IN_UNIV];
        ASM_REWRITE_TAC[IN_INTER; IN_REAL_INTERVAL] THEN ASM_REAL_ARITH_TAC];
      REWRITE_TAC[FORALL_IN_GSPEC; IN_UNIV] THEN
      REWRITE_TAC[INTER_SUBSET]];
    ALL_TAC] THEN
  REWRITE_TAC[SIMPLE_IMAGE] THEN
  MP_TAC(ISPEC `\M:num. S INTER real_interval[--(&M),&M]`
    REAL_NEGLIGIBLE_COUNTABLE_UNIONS) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[GSYM SIMPLE_IMAGE] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[]);;

(* --- 286D->286U(b) WIRING: the truncated maximal family gives *)
(* the window-boundedness hypothesis of CARLESON_286U_EXISTS_AE a.e. Five    *)
(* bricks:                                                                   *)
(* (1) TRUNC_WINDOW_MEM_LE: a compact window [a,b] SUBSET [-n,n] contributes *)
(* a                                                                         *)
(*       member <= the truncated sup Ahat_n f y.                             *)
(* (2) AHAT_TRUNC_INTEGRABLE: Ahat_m f is integrable on any [-M,M]           *)
(* (measurable +                                                             *)
(*       bounded by the loc-L^1 constant, TRUNC_FINITE).                     *)
(* (3) AHAT_TRUNC_BADSET_NEG: {y | sup_m Ahat_m f y = inf} is NEGLIGIBLE,    *)
(* via                                                                       *)
(* 286D (CARLESON_SUP_AE_FINITE) on each [-M,M] (threaded truncated integral *)
(*       bounds) + bounded exhaustion.  This is the 286D output.             *)
(* (4) TRUNC_FAMILY_WINDOW_BOUND: where sup_m Ahat_m f y < inf, EVERY window *)
(* DIFFERENCE (a<=b) is bounded (any [a,b] sits in some [-M,M], so its norm  *)
(*       <= Ahat_M f y <= K; add the fixed [-n,n] term).                     *)
(* (5) OFF_BADSET_BOUNDED: off the bad set, sup_m Ahat_m f y is bounded by   *)
(* some                                                                      *)
(*       integer k+1.                                                        *)
(* Together: (\z. f(drop z)) in L^2 + uniform truncated bounds => the        *)
(* window-diff                                                               *)
(* family of CARLESON_286U_EXISTS_AE is bounded off a negligible set. ---    *)

(* (1) compact window [a,b] SUBSET [-n,n] gives a member <= the truncated    *)
(* sup.                                                                      *)
let CARLESON_TRUNC_WINDOW_MEM_LE = prove
 (`!(f:real->complex) n y a b.
     &0 <= n /\ --n <= a /\ a <= b /\ b <= n /\
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> inv(sqrt(&2 * pi)) *
         norm(integral (IMAGE lift (real_interval[a,b]))
                (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
         <= carleson_Ahat_trunc f n y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (f:real->complex)(drop z)) absolutely_integrable_on
    (IMAGE lift (real_interval[--n,n]))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[carleson_Ahat_trunc] THEN
  MP_TAC(ISPECL
   [`{ inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a',b']))
              (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
                x)))
     | a',b' | --n <= a' /\ a' <= b' /\ b' <= n }`;
    `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
              x)))`;
    `inv(sqrt(&2 * pi)) *
     drop(integral (IMAGE lift (real_interval[--n,n])) (\x.
       lift(norm((f:real->complex)(drop x)))))`;
    `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
              x)))`]
   REAL_LE_SUP) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`a:real`; `b:real`] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_REFL];
    X_GEN_TAC `w:real` THEN
    DISCH_THEN(X_CHOOSE_THEN `a2:real` (X_CHOOSE_THEN
      `b2:real` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
      MP_TAC PI_POS THEN REAL_ARITH_TAC;
      MATCH_MP_TAC CARLESON_TRUNC_WINDOW_LE_INT THEN ASM_REWRITE_TAC[]]]);;

(* (2) Ahat_m f is integrable on any [-M,M] (measurable, nonneg, bounded     *)
(* above by                                                                  *)
(* the loc-L^1 constant from TRUNC_FINITE).                                  *)
let CARLESON_AHAT_TRUNC_INTEGRABLE = prove
 (`!(f:real->complex) m M.
     (\z. f(drop z)) IN lspace (:real^1) (&2)
     ==> (\y. carleson_Ahat_trunc f (&m) y)
         real_integrable_on real_interval[--(&M),&M]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `\y:real. inv(sqrt(&2 * pi)) *
     drop(integral (IMAGE lift (real_interval[--(&m),&m])) (\x.
       lift(norm((f:real->complex)(drop x)))))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MEASURABLE_SUBSET THEN
    EXISTS_TAC `(:real)` THEN
    REWRITE_TAC[SUBSET_UNIV; REAL_MEASURABLE_REAL_INTERVAL] THEN
    MATCH_MP_TAC CARLESON_AHAT_TRUNC_MEASURABLE THEN ASM_REWRITE_TAC[REAL_POS];
    REWRITE_TAC[REAL_INTEGRABLE_CONST];
    X_GEN_TAC `y:real` THEN DISCH_TAC THEN
    SUBGOAL_THEN `&0 <= carleson_Ahat_trunc f (&m) y` ASSUME_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_POS THEN
       ASM_REWRITE_TAC[REAL_POS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `carleson_Ahat_trunc f (&m) y <= inv(sqrt(&2 * pi)) *
        drop(integral (IMAGE lift (real_interval[--(&m),&m])) (\x.
          lift(norm((f:real->complex)(drop x)))))`
     ASSUME_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_FINITE THEN
       ASM_REWRITE_TAC[REAL_POS] THEN
      MATCH_MP_TAC CARLESON_LSPACE2_LOCAL_ABSINT THEN
        ASM_REWRITE_TAC[REAL_POS];
      ASM_REAL_ARITH_TAC]]);;

(* (3) {y | sup_m Ahat_m f y = inf} is NEGLIGIBLE (286D output), given the   *)
(* uniform                                                                   *)
(* truncated integral bounds on each [-M,M].                                 *)
let CARLESON_AHAT_TRUNC_BADSET_NEG = prove
 (`!(f:real->complex).
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (!M:num. ?D. &0 <= D /\
        !m:num. real_integral (real_interval[--(&M),&M])
                  (\y. carleson_Ahat_trunc f (&m) y) <= D)
     ==> real_negligible
           {y | !k:num. ?m:num. &k + &1 < carleson_Ahat_trunc f (&m) y}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_BOUNDED_EXHAUSTION THEN
  X_GEN_TAC `M:num` THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `M:num`) THEN
  DISCH_THEN(X_CHOOSE_THEN `D:real` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL
   [`\m:num. (\y. carleson_Ahat_trunc (f:real->complex) (&m) y)`;
    `real_interval[--(&M),&M]`; `D:real`] CARLESON_SUP_AE_FINITE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
      ASM_REWRITE_TAC[];
      X_GEN_TAC `m:num` THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC CARLESON_AHAT_TRUNC_MEASURABLE THEN
         ASM_REWRITE_TAC[REAL_POS];
        MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE THEN ASM_REWRITE_TAC[];
        REPEAT STRIP_TAC THEN MATCH_MP_TAC CARLESON_AHAT_TRUNC_POS THEN
        ASM_REWRITE_TAC[REAL_POS];
        ASM_REWRITE_TAC[]];
      MAP_EVERY X_GEN_TAC [`m:num`; `y:real`] THEN DISCH_TAC THEN
      MATCH_MP_TAC CARLESON_AHAT_TRUNC_MONO THEN
      ASM_REWRITE_TAC[REAL_POS; REAL_OF_NUM_LE] THEN ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_ELIM_THM] THEN
  X_GEN_TAC `y:real` THEN REWRITE_TAC[CONJ_SYM]);;

(* (4) off the bad set (sup_m Ahat_m f y <= K), EVERY window DIFFERENCE is   *)
(* bounded                                                                   *)
(* -- any window [a,b] sits in some [-M,M] so its norm <= Ahat_M f y <= K.   *)
let CARLESON_TRUNC_FAMILY_WINDOW_BOUND = prove
 (`!(f:real->complex) y.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (?K. !m:num. carleson_Ahat_trunc f (&m) y <= K)
     ==> !n. ?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)) -
                  integral (IMAGE lift (real_interval[--(&n),&n]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <= B`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `K:real`)) THEN
  X_GEN_TAC `n:num` THEN
  EXISTS_TAC `K + inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[--(&n),&n]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
              x)))` THEN
  MAP_EVERY X_GEN_TAC [`a:real`; `b:real`] THEN DISCH_TAC THEN
  MP_TAC(SPEC `max (abs a) (abs b)` REAL_ARCH_SIMPLE) THEN
  DISCH_THEN(X_CHOOSE_TAC `M:num`) THEN
  SUBGOAL_THEN
    `--(&M) <= a /\ a <= b /\ b <= &M /\ &0 <= &M` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x)))
              +
    inv(sqrt(&2 * pi)) *
     norm(integral (IMAGE lift (real_interval[--(&n),&n]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop
              x)))` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[GSYM REAL_ADD_LDISTRIB] THEN MATCH_MP_TAC REAL_LE_LMUL THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
      MP_TAC PI_POS THEN REAL_ARITH_TAC;
      CONV_TAC NORM_ARITH];
    MATCH_MP_TAC REAL_LE_ADD2 THEN REWRITE_TAC[REAL_LE_REFL] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `carleson_Ahat_trunc f (&M) y` THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`f:real->complex`; `&M:real`; `y:real`; `a:real`;
       `b:real`]
        CARLESON_TRUNC_WINDOW_MEM_LE) THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]]);;

(* (5) off the bad set, sup_m Ahat_m f y is bounded by some integer k+1.     *)
let CARLESON_OFF_BADSET_BOUNDED = prove
 (`!(f:real->complex) y.
     ~(y IN {y | !k:num. ?m:num. &k + &1 < carleson_Ahat_trunc f (&m) y})
     ==> ?K. !m:num. carleson_Ahat_trunc f (&m) y <= K`,
  REPEAT GEN_TAC THEN
    REWRITE_TAC[IN_ELIM_THM; NOT_FORALL_THM; NOT_EXISTS_THM] THEN
  REWRITE_TAC[REAL_NOT_LT] THEN
  DISCH_THEN(X_CHOOSE_TAC `k:num`) THEN
  EXISTS_TAC `&k + &1` THEN ASM_REWRITE_TAC[]);;

(* --- H2-chain (toward the oscillation per-slice gamma bound): general-FF   *)
(* versions of the 286T maximal machinery + the UNTRUNCATED bound int_FF     *)
(* carleson_Ahat f <= C10 ||f||_2 sqrt muFF (any f in L^2, measurable FF,    *)
(* from                                                                      *)
(* the 286T(b) Schwartz gate). This is the direct input to                   *)
(* CARLESON_GAMMA_INT_                                                       *)
(* BOUND for the oscillation slices (Fremlin 286U(b)). ---                   *)
let REAL_INTEGRAL_CONST_MEASURABLE = prove
 (`!c FF. real_measurable FF ==> real_integral FF (\x. c) = c * real_measure
   FF`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(\x:real. c) = (\x. c * &1)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_MUL_RID]; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_INTEGRAL_LMUL; GSYM REAL_MEASURABLE;
    REAL_INTEGRAL_REAL_MEASURE]);;

let CARLESON_TRUNC_DENSITY_STEP_FF = prove
 (`!(f:real->complex) h FF n.
     &0 <= n /\ real_measurable FF /\
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\ schwartz h
     ==> real_integral FF (\y. carleson_Ahat_trunc f n y)
         <= real_integral FF (\y. carleson_Ahat_trunc h n y) +
            (inv(sqrt(&2 * pi)) * sqrt(&2 * n) *
             lnorm (:real^1) (&2) (\z. f(drop z) - h(drop z))) * (real_measure
               FF)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z. (h:real->complex)(drop z)) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_L2 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\y. carleson_Ahat_trunc (f:real->complex) n y`;
    `\y. carleson_Ahat_trunc (h:real->complex) n y +
         inv(sqrt(&2 * pi)) * sqrt(&2 * n) *
         lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z))`;
    `FF:real->bool`] REAL_INTEGRAL_LE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE_GEN THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_INTEGRABLE_ADD THEN CONJ_TAC THENL
       [MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE_GEN THEN ASM_REWRITE_TAC[];
        ONCE_REWRITE_TAC[GSYM REAL_MUL_RID] THEN
          MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
        ASM_REWRITE_TAC[GSYM REAL_MEASURABLE]];
      X_GEN_TAC `y:real` THEN DISCH_TAC THEN BETA_TAC THEN
      MATCH_MP_TAC CARLESON_AHAT_TRUNC_SUB_BOUND THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `b = c ==> a <= b ==> a <= c`) THEN
  W(MP_TAC o PART_MATCH (lhs o rand) REAL_INTEGRAL_ADD o lhs o snd) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE_GEN THEN ASM_REWRITE_TAC[];
      ONCE_REWRITE_TAC[GSYM REAL_MUL_RID] THEN
        MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
      ASM_REWRITE_TAC[GSYM REAL_MEASURABLE]];
    DISCH_THEN SUBST1_TAC] THEN
  AP_TERM_TAC THEN
  ASM_SIMP_TAC[REAL_INTEGRAL_CONST_MEASURABLE]);;

let CARLESON_286T_TRUNC_GENERAL_FF = prove
 (`!(f:real->complex) FF n C10.
     &0 <= C10 /\ &0 <= n /\ real_measurable FF /\
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG.
        schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> real_integral FF (\y. carleson_Ahat_trunc f n y)
         <= C10 * lnorm (:real^1) (&2) (\z. f(drop z)) * sqrt(real_measure
           FF)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_EPSILON THEN
  X_GEN_TAC `eps:real` THEN DISCH_TAC THEN
  ABBREV_TAC `K = &1 + C10 * sqrt(real_measure FF) +
               inv(sqrt(&2 * pi)) * sqrt(&2 * n) * (real_measure FF)` THEN
  SUBGOAL_THEN `&0 <= real_measure FF` ASSUME_TAC THENL
   [ASM_SIMP_TAC[REAL_MEASURE_POS_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= C10 * sqrt(real_measure FF)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_SIMP_TAC[SQRT_POS_LE]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 <= inv(sqrt(&2 * pi)) * sqrt(&2 * n) * (real_measure FF)`
     ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN
    SIMP_TAC[REAL_LE_INV_EQ; SQRT_POS_LE; REAL_LE_MUL; REAL_POS;
      PI_POS_LE] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN
      ASM_SIMP_TAC[SQRT_POS_LE; REAL_LE_MUL; REAL_POS];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < K` ASSUME_TAC THENL [EXPAND_TAC "K" THEN
    ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < eps / K` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_DIV THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC `\z. (f:real->complex)(drop z)` LSPACE_APPROXIMATE_SCHWARTZ)
    THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun dth -> MP_TAC(MATCH_MP dth (ASSUME `&0 < eps / K`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `h:real->complex` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
    `(\z. (h:real->complex)(drop z)) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_L2 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->complex`; `h:real->complex`; `FF:real->bool`;
    `n:real`]
    CARLESON_TRUNC_DENSITY_STEP_FF) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`; `n:real`; `C10:real`]
    CARLESON_286T_TRUNC_SCHWARTZ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPECL [`h:real->complex`;
      `FF:real->bool`] th)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`f:real->complex`;
    `h:real->complex`] LNORM_TRIANGLE_SUB_H) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`K:real`;
    `lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z))`;
                 `eps:real`] TRUNC_EPS_ARITH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC LNORM_POS_LE THEN REWRITE_TAC[REAL_ARITH `&1 <= &2`] THEN
      MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_POS];
      EXPAND_TAC "K" THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `C10 * lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z)) *
     sqrt(real_measure FF) +
    (inv(sqrt(&2 * pi)) * sqrt(&2 * n) *
     lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z))) *
       (real_measure FF)` THEN
  CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `C10 * lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z)) *
     sqrt(real_measure FF)
    <= C10 * lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z)) *
      sqrt(real_measure FF) +
       lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z)) * (C10
         * sqrt(real_measure FF))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC
     `C10 * (lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z)) +
             lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z)))
               *
      sqrt(real_measure FF)` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[REAL_MUL_ASSOC] THEN MATCH_MP_TAC REAL_LE_RMUL THEN
      ASM_SIMP_TAC[SQRT_POS_LE] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_ADD_RDISTRIB; REAL_ADD_LDISTRIB] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `(C10 * lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z)) *
     sqrt(real_measure FF) +
     lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z)) * (C10 *
       sqrt(real_measure FF))) +
    (inv(sqrt(&2 * pi)) * sqrt(&2 * n) *
     lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z) - h(drop z))) *
       (real_measure FF)` THEN
  CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(fun th ->
    if can (find_term (fun t -> t = `K - &1`)) (concl th)
    then MP_TAC th else NO_TAC) THEN
  EXPAND_TAC "K" THEN
  MATCH_MP_TAC(REAL_ARITH
   `c1 = t * cc /\ c2 = t * dd
    ==> t * ((&1 + cc + dd) - &1) <= eps
        ==> (a + c1) + c2 <= a + eps`) THEN
  CONJ_TAC THEN REAL_ARITH_TAC);;

let CARLESON_TRUNC_FAMILY_PLAIN_WINDOW_BOUND = prove
 (`!(f:real->complex) y.
     (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (?K. !m:num. carleson_Ahat_trunc f (&m) y <= K)
     ==> ?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x))) <= B`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_TAC `K:real`)) THEN
  EXISTS_TAC `K:real` THEN
  MAP_EVERY X_GEN_TAC [`a:real`; `b:real`] THEN DISCH_TAC THEN
  MP_TAC(SPEC `max (abs a) (abs b)` REAL_ARCH_SIMPLE) THEN
  DISCH_THEN(X_CHOOSE_TAC `M:num`) THEN
  SUBGOAL_THEN
    `--(&M) <= a /\ a <= b /\ b <= &M /\ &0 <= &M` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `carleson_Ahat_trunc f (&M) y` THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`f:real->complex`; `&M:real`; `y:real`; `a:real`; `b:real`]
      CARLESON_TRUNC_WINDOW_MEM_LE) THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

let CARLESON_286T_UNTRUNC = prove
 (`!(f:real->complex) FF C10.
     &0 <= C10 /\ real_measurable FF /\ (\z. f(drop z)) IN lspace (:real^1)
       (&2) /\
     (!(h:real->complex) GG.
        schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> carleson_Ahat f real_integrable_on FF /\
         real_integral FF (carleson_Ahat f)
           <= C10 * lnorm (:real^1) (&2) (\z. f(drop z)) * sqrt(real_measure
             FF)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC CARLESON_286T_FROM_TRUNC THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [EXISTS_TAC
     `{y | !k:num. ?m:num. &k + &1 < carleson_Ahat_trunc (f:real->complex) (&m)
       y}` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_BADSET_NEG THEN CONJ_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      X_GEN_TAC `M:num` THEN
      EXISTS_TAC `C10 * lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z)) *
        sqrt(&2 * &M)` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
         [MATCH_MP_TAC LNORM_POS_LE THEN
           ASM_REWRITE_TAC[REAL_ARITH `&1 <= &2`];
          MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_LE_MUL THEN
            REWRITE_TAC[REAL_POS]];
        X_GEN_TAC `m:num` THEN
        SUBGOAL_THEN
          `real_measure(real_interval[--(&M),&M]) = &2 * &M` ASSUME_TAC THENL
         [REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN
           REAL_ARITH_TAC; ALL_TAC] THEN
        MP_TAC(ISPECL [`f:real->complex`; `real_interval[--(&M),&M]`;
          `&m:real`; `C10:real`]
          CARLESON_286T_TRUNC_GENERAL_FF) THEN
        ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL; REAL_POS]];
      X_GEN_TAC `y:real` THEN DISCH_TAC THEN
      MATCH_MP_TAC CARLESON_TRUNC_FAMILY_PLAIN_WINDOW_BOUND THEN
        ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC CARLESON_OFF_BADSET_BOUNDED THEN ASM_REWRITE_TAC[]];
    X_GEN_TAC `m:num` THEN CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_INTEGRABLE_GEN THEN
       ASM_REWRITE_TAC[REAL_POS];
      MATCH_MP_TAC CARLESON_286T_TRUNC_GENERAL_FF THEN
        ASM_REWRITE_TAC[REAL_POS]]]);;

(* --- H2 outer-measure toolkit (Fremlin 286U(b) faithful, avoiding HOL's    *)
(* real-sup                                                                  *)
(* junk on the null set where the window family is unbounded): the           *)
(* oscillation bad                                                           *)
(* set is negligible via OUTER MEASURE (a slice sits inside a small-measure  *)
(* super-                                                                    *)
(* level set of Ahat f_1n plus a null set), so NO per-slice                  *)
(* gamma-measurability is                                                    *)
(* needed. ---                                                               *)

(* Superlevel set {y in FF | e < g y} is measurable (g integrable =>         *)
(* measurable on FF; g.chi_FF measurable on univ; MK_LEVEL_ID +              *)
(* MK_LEBMEAS_SUBSET).                                                       *)
let CARLESON_SUPERLEVEL_MEASURABLE = prove
 (`!(g:real->real) FF e.
     real_measurable FF /\ g real_integrable_on FF /\ &0 < e
     ==> real_measurable (FF INTER {y | e < g y})`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(g:real->real) real_measurable_on FF` ASSUME_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`FF INTER {y | e < (g:real->real) y}`;
    `FF:real->bool`] MK_LEBMEAS_SUBSET) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[INTER_SUBSET] THEN
    ASM_SIMP_TAC[MK_LEVEL_ID] THEN
    MP_TAC(ISPEC `\x. if x IN FF then (g:real->real) x else &0`
       REAL_MEASURABLE_ON_PREIMAGE_HALFSPACE_GT) THEN
    REWRITE_TAC[REAL_MEASURABLE_ON_UNIV] THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `e:real`) THEN
      REWRITE_TAC[];
    REWRITE_TAC[]]);;

(* Markov/Chebyshev on the superlevel set: e*mu(FF INTER {e<g}) <= int_FF g. *)
let CARLESON_SUPERLEVEL_MEASURE_BOUND = prove
 (`!(g:real->real) FF e.
     real_measurable FF /\ g real_integrable_on FF /\ &0 < e /\
     (!y. y IN FF ==> &0 <= g y)
     ==> e * real_measure (FF INTER {y | e < g y}) <= real_integral FF g`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `real_measurable (FF INTER {y | e < (g:real->real) y})` ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_SUPERLEVEL_MEASURABLE THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(g:real->real)
     real_integrable_on (FF INTER {y | e < g y})` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_ON_NONNEG_MEASURABLE_SUBSET THEN
    EXISTS_TAC `FF:real->bool` THEN ASM_REWRITE_TAC[INTER_SUBSET] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_MEASURABLE_IMP_REAL_LEBESGUE_MEASURABLE THEN
       ASM_REWRITE_TAC[];
      MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral (FF INTER {y | e < (g:real->real) y}) g` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CHEBYSHEV_MEASURE THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IN_INTER; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
      ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC REAL_INTEGRAL_SUBSET_LE THEN ASM_REWRITE_TAC[INTER_SUBSET]]);;

(* a.e.-nonneg variant: nonneg only OFF a null s0 (Ahat f_1n>=0 only where   *)
(* the window family is bounded, i.e. off the null set); via SPIKE_SET on FF *)
(* DIFF s0.                                                                  *)
let CARLESON_SUPERLEVEL_MEASURE_BOUND_AE = prove
 (`!(g:real->real) FF s0 e.
     real_measurable FF /\ g real_integrable_on FF /\ &0 < e /\
     real_negligible s0 /\
     (!y. y IN FF /\ ~(y IN s0) ==> &0 <= g y)
     ==> real_measurable (FF INTER {y | e < g y}) /\
         e * real_measure (FF INTER {y | e < g y}) <= real_integral FF g`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `real_measurable (FF INTER {y | e < (g:real->real) y})` ASSUME_TAC THENL
   [MATCH_MP_TAC CARLESON_SUPERLEVEL_MEASURABLE THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `FF' = FF DIFF (s0:real->bool)` THEN
  SUBGOAL_THEN `real_measurable (FF':real->bool)` ASSUME_TAC THENL
   [EXPAND_TAC "FF'" THEN MATCH_MP_TAC REAL_MEASURABLE_DIFF THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[REAL_MEASURABLE_MEASURABLE] THEN
    MATCH_MP_TAC NEGLIGIBLE_IMP_MEASURABLE THEN
      ASM_REWRITE_TAC[GSYM real_negligible];
    ALL_TAC] THEN
  SUBGOAL_THEN `(g:real->real) real_integrable_on FF'` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`g:real->real`; `FF:real->bool`;
     `FF':real->bool`] REAL_INTEGRABLE_SPIKE_SET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN
    EXISTS_TAC `s0:real->bool` THEN ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "FF'" THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `real_integral FF (g:real->real) = real_integral FF' g` SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SPIKE_SET THEN
    MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN EXISTS_TAC `s0:real->bool` THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "FF'" THEN SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_measure (FF INTER {y | e < (g:real->real) y}) =
    real_measure (FF' INTER {y | e < g y})`
   SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_MEASURE_REAL_NEGLIGIBLE_SYMDIFF THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN
    EXISTS_TAC `s0:real->bool` THEN ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "FF'" THEN
    REWRITE_TAC[SUBSET; IN_UNION; IN_DIFF; IN_INTER; IN_ELIM_THM] THEN
      MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`g:real->real`; `FF':real->bool`;
    `e:real`] CARLESON_SUPERLEVEL_MEASURE_BOUND) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  X_GEN_TAC `y:real` THEN EXPAND_TAC "FF'" THEN REWRITE_TAC[IN_DIFF] THEN
  STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* Outer-measure negligibility: FF SUBSET (L n UNION Z n) for all n, mu(L    *)
(* n)<=B n,                                                                  *)
(* Z n negligible, B n -> 0  ==>  FF negligible (REAL_NEGLIGIBLE_OUTER_LE).  *)
let CARLESON_SLICE_NEGLIGIBLE_OUTER = prove
 (`!FF (L:num->real->bool) (Z:num->real->bool) B.
     (!n. FF SUBSET (L n UNION Z n)) /\
     (!n. real_measurable (L n) /\ real_measure (L n) <= B n /\ real_negligible
       (Z n)) /\
     (B ---> &0) sequentially
     ==> real_negligible FF`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_NEGLIGIBLE_OUTER_LE] THEN
  X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  SUBGOAL_THEN `?N:num. (B:num->real) N <= e` STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [REALLIM_SEQUENTIALLY]) THEN
    DISCH_THEN(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `N:num` (MP_TAC o SPEC `N:num`)) THEN
    REWRITE_TAC[LE_REFL] THEN DISCH_TAC THEN EXISTS_TAC `N:num` THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `real_measurable ((L:num->real->bool) N) /\ real_measure (L N) <= B N /\
    real_negligible ((Z:num->real->bool) N)`
   STRIP_ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `real_measurable ((Z:num->real->bool) N)` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_MEASURABLE_MEASURABLE] THEN
    MATCH_MP_TAC NEGLIGIBLE_IMP_MEASURABLE THEN
    ASM_REWRITE_TAC[GSYM real_negligible]; ALL_TAC] THEN
  EXISTS_TAC `(L:num->real->bool) N UNION Z N` THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_MEASURABLE_UNION THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_measure((L:num->real->bool) N) + real_measure(Z N)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURE_UNION_LE THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `real_measure((Z:num->real->bool) N) = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC REAL_MEASURE_EQ_0 THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_ADD_RID] THEN ASM_REAL_ARITH_TAC]]);;

(* --- Per-slice outer negligibility (Fremlin 286U(b) contradiction,         *)
(* faithful): the                                                            *)
(* oscillation slice S_k INTER [-M,M] sits inside the superlevel             *)
(* {inv(2(k+1))<Ahat                                                         *)
(* f_1n} (measure -> 0) union the null domination-failure set s0, so it is   *)
(* null by                                                                   *)
(* CARLESON_SLICE_NEGLIGIBLE_OUTER -- NO gamma-measurability needed. ---     *)

(* SUBSET: off s0, inv(k+1) <= gamma_n <= Ahat f_1n, so inv(2(k+1)) < Ahat   *)
(* f_1n.                                                                     *)
let CARLESON_SLICE_SUBSET_SUPERLEVEL = prove
 (`!(f:real->complex) k M s0 (n:num).
     (!y. y IN real_interval[--(&M),&M] /\ ~(y IN s0)
          ==> carleson_gamma f (&n) y
              <= carleson_Ahat (\t. if abs t <= &n then Cx(&0) else f t) y)
     ==> ({y | !m:num. inv(&k + &1) <= carleson_gamma f (&m) y}
          INTER real_interval[--(&M),&M])
         SUBSET
         ((real_interval[--(&M),&M] INTER
           {y | inv(&(2 * (k+1))) < carleson_Ahat (\t. if abs t <= &n then
             Cx(&0) else f t) y})
          UNION s0)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[SUBSET; IN_INTER; IN_UNION; IN_ELIM_THM] THEN
  X_GEN_TAC `y:real` THEN STRIP_TAC THEN
  ASM_CASES_TAC `(y:real) IN s0` THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISJ1_TAC THEN ASM_REWRITE_TAC[IN_INTER; IN_ELIM_THM] THEN
  MATCH_MP_TAC REAL_LTE_TRANS THEN
  EXISTS_TAC `carleson_gamma f (&n) y` THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `inv(&k + &1)` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LT_INV2 THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_MUL; GSYM REAL_OF_NUM_ADD] THEN
      REAL_ARITH_TAC;
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* superlevel measure bound: mu([-M,M] INTER {inv(2(k+1))<Ahat f_1n}) <= A n *)
(* * 2(k+1).                                                                 *)
let CARLESON_SLICE_SUPERLEVEL_MEASURE_AE = prove
 (`!(f:real->complex) k M s0 A (n:num).
     real_negligible s0 /\
     carleson_Ahat (\t. if abs t <= &n then Cx(&0) else f t) real_integrable_on
       real_interval[--(&M),&M] /\
     real_integral (real_interval[--(&M),&M])
       (carleson_Ahat (\t. if abs t <= &n then Cx(&0) else f t)) <= A n /\
     (!y. y IN real_interval[--(&M),&M] /\ ~(y IN s0)
          ==> &0 <= carleson_Ahat (\t. if abs t <= &n then Cx(&0) else f t) y)
     ==> real_measurable (real_interval[--(&M),&M] INTER
           {y | inv(&(2 * (k+1))) < carleson_Ahat (\t. if abs t <= &n then
             Cx(&0) else f t) y}) /\
         real_measure (real_interval[--(&M),&M] INTER
           {y | inv(&(2 * (k+1))) < carleson_Ahat (\t. if abs t <= &n then
             Cx(&0) else f t) y})
         <= A n * &(2 * (k+1))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `c = inv(&(2 * (k+1)))` THEN
  SUBGOAL_THEN `&0 < c` ASSUME_TAC THENL
   [EXPAND_TAC "c" THEN MATCH_MP_TAC REAL_LT_INV THEN
    REWRITE_TAC[REAL_OF_NUM_LT] THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`carleson_Ahat (\t. if abs t <= &n then Cx(&0) else
    (f:real->complex) t)`;
                 `real_interval[--(&M),&M]`; `s0:real->bool`; `c:real`]
    CARLESON_SUPERLEVEL_MEASURE_BOUND_AE) THEN
  ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&(2 * (k + 1)) = inv c` SUBST1_TAC THENL
   [EXPAND_TAC "c" THEN REWRITE_TAC[REAL_INV_INV]; ALL_TAC] THEN
  REWRITE_TAC[GSYM real_div] THEN ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
  GEN_REWRITE_TAC (LAND_CONV) [REAL_MUL_SYM] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `real_integral (real_interval[--(&M),&M])
    (carleson_Ahat (\t. if abs t <= &n then Cx(&0) else (f:real->complex) t))`
      THEN
  ASM_REWRITE_TAC[]);;

let CARLESON_OSC_SLICE_NEG_AE = prove
 (`!(f:real->complex) k M s0 A.
     real_negligible s0 /\ (A ---> &0) sequentially /\
     (!n. carleson_Ahat (\t. if abs t <= &n then Cx(&0) else f t)
       real_integrable_on
            real_interval[--(&M),&M] /\
          real_integral (real_interval[--(&M),&M])
            (carleson_Ahat (\t. if abs t <= &n then Cx(&0) else f t)) <= A n /\
          (!y. y IN real_interval[--(&M),&M] /\ ~(y IN s0)
               ==> &0 <= carleson_Ahat (\t. if abs t <= &n then Cx(&0) else f
                 t) y) /\
          (!y. y IN real_interval[--(&M),&M] /\ ~(y IN s0)
               ==> carleson_gamma f (&n) y
                   <= carleson_Ahat (\t. if abs t <= &n then Cx(&0) else f t)
                     y))
     ==> real_negligible ({y | !m:num. inv(&k + &1) <= carleson_gamma f (&m) y}
                          INTER real_interval[--(&M),&M])`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CARLESON_SLICE_NEGLIGIBLE_OUTER THEN
  MAP_EVERY EXISTS_TAC
   [`\n:num. real_interval[--(&M),&M] INTER
         {y | inv(&(2 * (k+1))) < carleson_Ahat (\t. if abs t <= &n then Cx(&0)
           else f t) y}`;
    `\n:num. s0:real->bool`;
    `\n:num. (A n) * &(2 * (k+1))`] THEN
  REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [X_GEN_TAC `n:num` THEN
    MATCH_MP_TAC CARLESON_SLICE_SUBSET_SUPERLEVEL THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `n:num` THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN STRIP_TAC THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL [`f:real->complex`; `k:num`; `M:num`; `s0:real->bool`;
       `A:num->real`; `n:num`]
        CARLESON_SLICE_SUPERLEVEL_MEASURE_AE) THEN ASM_REWRITE_TAC[] THEN
          SIMP_TAC[];
      CONJ_TAC THENL
       [MP_TAC(ISPECL [`f:real->complex`; `k:num`; `M:num`; `s0:real->bool`;
         `A:num->real`; `n:num`]
          CARLESON_SLICE_SUPERLEVEL_MEASURE_AE) THEN ASM_REWRITE_TAC[] THEN
            SIMP_TAC[];
        ASM_REWRITE_TAC[]]];
    SUBGOAL_THEN
      `((\n. (A:num->real) n * &(2 * (k + 1))) ---> &0 * &(2 * (k + 1)))
      sequentially`
      MP_TAC THENL
     [MATCH_MP_TAC REALLIM_RMUL THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_MUL_LZERO]]]);;

(* --- 286U(b) hyp3 (oscillation) FULL ASSEMBLY: set where inf_n gamma_n > 0 *)
(* is                                                                        *)
(* negligible, given f in L^2 + the 286T(b) Schwartz gate.  s0 = UNIONS_n    *)
(* badset(f_1n) [countable union of AHAT_TRUNC_BADSET_NEG negligibles]; off  *)
(* s0                                                                        *)
(* every f_1n window family is bounded so AHAT_POS/GAMMA_LE_AHAT_L2 apply.   *)
(* Chains                                                                    *)
(* OSC_BADSET_UNIONS + COUNTABLE_UNIONS + BOUNDED_EXHAUSTION +               *)
(* OSC_SLICE_NEG_AE. ---                                                     *)
let CARLESON_TRUNC_BADSET_NEG_N = prove
 (`!(f:real->complex) n C10.
     &0 <= C10 /\ (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG.
        schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> real_negligible
           {y | !k:num. ?m:num. &k + &1 <
                carleson_Ahat_trunc (\t. if abs t <= &n then Cx(&0) else f t)
                  (&m) y}`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CARLESON_AHAT_TRUNC_BADSET_NEG THEN
  CONJ_TAC THENL
   [BETA_TAC THEN MATCH_MP_TAC CARLESON_TRUNC_LSPACE2 THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `M:num` THEN
  EXISTS_TAC `C10 * lnorm (:real^1) (&2)
      (\z. (\t. if abs t <= &n then Cx(&0) else (f:real->complex) t) (drop z))
        * sqrt(&2 * &M)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC LNORM_POS_LE THEN REWRITE_TAC[REAL_ARITH `&1 <= &2`] THEN
      MATCH_MP_TAC CARLESON_TRUNC_LSPACE2 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC SQRT_POS_LE THEN MATCH_MP_TAC REAL_LE_MUL THEN
        REWRITE_TAC[REAL_POS]];
    X_GEN_TAC `m:num` THEN
    SUBGOAL_THEN
      `real_measure(real_interval[--(&M),&M]) = &2 * &M` ASSUME_TAC THENL
     [REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN
       REAL_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`\t. if abs t <= &n then Cx(&0) else (f:real->complex) t`;
                   `real_interval[--(&M),&M]`; `&m:real`; `C10:real`]
      CARLESON_286T_TRUNC_GENERAL_FF) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL; REAL_POS] THEN
      BETA_TAC THEN MATCH_MP_TAC CARLESON_TRUNC_LSPACE2 THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]]);;

let CARLESON_S0_UNION_NEG = prove
 (`!(f:real->complex) C10.
     &0 <= C10 /\ (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG.
        schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> real_negligible
           (UNIONS { {y | !k:num. ?m:num. &k + &1 <
                     carleson_Ahat_trunc (\t. if abs t <= &n then Cx(&0) else f
                       t) (&m) y}
                   | n IN (:num) })`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_COUNTABLE_UNIONS THEN
  X_GEN_TAC `n:num` THEN
  MATCH_MP_TAC CARLESON_TRUNC_BADSET_NEG_N THEN
  EXISTS_TAC `C10:real` THEN ASM_REWRITE_TAC[]);;


(* --- 286U(b) OSCILLATION bad set negligible (Fremlin mt286.tex 2999-3020,  *)
(* the                                                                       *)
(* TRUE 286U(b) contradiction, distinct from the 286D maximal-finiteness     *)
(* above).                                                                   *)
(* The bad set {y | ~(inf_m gamma_m(y)=0)} where the tail-oscillation fails  *)
(* to                                                                        *)
(* vanish decomposes (CARLESON_OSC_BADSET_UNIONS) into the countable union   *)
(* over k                                                                    *)
(* of slices S_k = {y | !m. 1/(k+1) <= gamma_m(y)}. Each S_k is negligible:  *)
(* on                                                                        *)
(* S_k INTER [-M,M] (finite measure, via bounded exhaustion) apply           *)
(* PERSLICE_NEG                                                              *)
(* with e = 1/(k+1) (<= gamma_m everywhere on the slice) and A_n -> 0 --     *)
(* Fremlin's                                                                 *)
(* e muF <= int_F gamma_n <= A_n sqrt muF (A_n = C ||f_n||_2 -> 0 by the     *)
(* truncated                                                                 *)
(* 286T bound + TRUNC_LNORM_LIM) forces muF = 0. The per-slice integral      *)
(* bound                                                                     *)
(* (int_{S_k cap [-M,M]} gamma_n <= A_n sqrt mu) is threaded as a hypothesis *)
(* (supplied at instantiation by GAMMA_INT_BOUND + the deep 286T +           *)
(* TRUNC_LNORM_LIM).                                                         *)
(* This discharges the second negligible-set hypothesis of                   *)
(* CARLESON_286U_EXISTS_AE.                                                  *)
(* ---                                                                       *)

(* The y-dependent bad-set decomposition (companion of                       *)
(* CARLESON_BADSET_UNIONS with                                               *)
(* the family G y m depending on the set-builder variable y). Pure           *)
(* set-theory +                                                              *)
(* Archimedean (REAL_ARCH_INV).                                              *)
let CARLESON_OSC_BADSET_UNIONS = prove
 (`!(G:real->num->real).
     {y:real | ~(!e. &0 < e ==> ?m:num. G y m <= e)}
   = UNIONS { {y:real | !m:num. inv(&k + &1) <= G y m} | k IN (:num) }`,
  GEN_TAC THEN REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `y:real` THEN
  REWRITE_TAC[IN_UNIONS; IN_ELIM_THM] THEN EQ_TAC THENL
   [REWRITE_TAC[NOT_FORALL_THM; NOT_IMP; DE_MORGAN_THM] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:real` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPEC `e:real` REAL_ARCH_INV) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `{v:real | !m:num. inv(&(n - 1) + &1) <= G v m}` THEN
      CONJ_TAC THENL
     [EXISTS_TAC `n - 1` THEN REWRITE_TAC[IN_UNIV];
      REWRITE_TAC[IN_ELIM_THM] THEN
      SUBGOAL_THEN `&(n - 1) + &1 = &n` SUBST1_TAC THENL
       [MP_TAC(ASSUME `~(n = 0)`) THEN SPEC_TAC(`n:num`,`n:num`) THEN
        INDUCT_TAC THEN
        REWRITE_TAC[SUC_SUB1; ADD1; GSYM REAL_OF_NUM_ADD] THEN REAL_ARITH_TAC;
        ALL_TAC] THEN
      X_GEN_TAC `m:num` THEN
      MP_TAC(SPEC `m:num` (REWRITE_RULE[NOT_EXISTS_THM; REAL_NOT_LE]
        (ASSUME `~(?m:num. G (y:real) m <= e)`))) THEN ASM_REAL_ARITH_TAC];
    STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[IN_ELIM_THM]) THEN
    REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN
    EXISTS_TAC `inv(&k + &1) / &2` THEN
    SUBGOAL_THEN `&0 < inv(&k + &1)` ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_LT_INV THEN REAL_ARITH_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[NOT_EXISTS_THM; REAL_NOT_LE] THEN
    X_GEN_TAC `m:num` THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `m:num`) THEN ASM_REAL_ARITH_TAC]);;

(* The oscillation-badset negligibility, gamma-threaded form.                *)
let CARLESON_OSC_BADSET_FROM_UNTRUNC = prove
 (`!(f:real->complex) C10.
     &0 <= C10 /\ (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG.
        schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> real_negligible {y | ~(!e. &0 < e ==> ?m:num. carleson_gamma f (&m) y
       <= e)}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `\y m:num. carleson_gamma f (&m) y` CARLESON_OSC_BADSET_UNIONS)
    THEN
  REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_COUNTABLE_UNIONS THEN
  X_GEN_TAC `k:num` THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_BOUNDED_EXHAUSTION THEN
  X_GEN_TAC `M:num` THEN
  MATCH_MP_TAC CARLESON_OSC_SLICE_NEG_AE THEN
  MAP_EVERY EXISTS_TAC
   [`UNIONS { {y | !k:num. ?m:num. &k + &1 <
              carleson_Ahat_trunc (\t. if abs t <= &n then Cx(&0) else f t)
                (&m) y}
            | n IN (:num) }`;
    `\n. C10 * lnorm (:real^1) (&2)
          (\z. (\x. if abs x <= &n then Cx(&0) else f x) (drop z)) * sqrt(&2 *
            &M)`] THEN
  REPEAT CONJ_TAC THENL
   [(* s0 negligible                                                         *)
    MATCH_MP_TAC CARLESON_S0_UNION_NEG THEN EXISTS_TAC `C10:real` THEN
      ASM_REWRITE_TAC[];
    (* A n -> 0                                                              *)
    SUBGOAL_THEN
     `(\n. C10 * lnorm (:real^1) (&2)
           (\z. (\x. if abs x <= &n then Cx(&0) else f x) (drop z)) * sqrt(&2 *
             &M)) =
      (\n. (C10 * lnorm (:real^1) (&2)
            (\z. (\x. if abs x <= &n then Cx(&0) else f x) (drop z))) * sqrt(&2
              * &M))`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; REAL_MUL_ASSOC]; ALL_TAC] THEN
    SUBGOAL_THEN `((\n. (C10 * lnorm (:real^1) (&2)
            (\z. (\x. if abs x <= &n then Cx(&0) else f x) (drop z))) * sqrt(&2
              * &M)) ---> &0 * sqrt(&2 * &M))
      sequentially` MP_TAC THENL
     [MATCH_MP_TAC REALLIM_RMUL THEN
      MATCH_MP_TAC CARLESON_TRUNC_COEFF_LIM THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[REAL_MUL_LZERO]];
    (* per-n hyps                                                            *)
    X_GEN_TAC `n:num` THEN
    SUBGOAL_THEN
      `(\z. (\x. if abs x <= &n then Cx(&0) else (f:real->complex) x) (drop z))
      IN lspace (:real^1) (&2)`
      ASSUME_TAC THENL
     [BETA_TAC THEN MATCH_MP_TAC CARLESON_TRUNC_LSPACE2 THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`\t. if abs t <= &n then Cx(&0) else (f:real->complex) t`;
                   `real_interval[--(&M),&M]`;
                     `C10:real`] CARLESON_286T_UNTRUNC) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL]; STRIP_TAC] THEN
    SUBGOAL_THEN
      `real_measure(real_interval[--(&M),&M]) = &2 * &M` ASSUME_TAC THENL
     [REWRITE_TAC[REAL_MEASURE_REAL_INTERVAL] THEN
       REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `!y. ~(y IN UNIONS { {y | !k:num. ?m:num. &k + &1 <
              carleson_Ahat_trunc (\t. if abs t <= &n then Cx(&0) else
                (f:real->complex) t) (&m) y}
            | n IN (:num) })
          ==> ?K. !m:num. carleson_Ahat_trunc (\t. if abs t <= &n then Cx(&0)
            else f t) (&m) y <= K`
     ASSUME_TAC THENL
     [X_GEN_TAC `y:real` THEN DISCH_TAC THEN
      MATCH_MP_TAC CARLESON_OFF_BADSET_BOUNDED THEN
      FIRST_X_ASSUM(MP_TAC o check (fun th -> is_neg(concl th))) THEN
      REWRITE_TAC[IN_UNIONS; IN_ELIM_THM; CONTRAPOS_THM] THEN DISCH_TAC THEN
      EXISTS_TAC `{y | !k:num. ?m:num. &k + &1 <
            carleson_Ahat_trunc (\t. if abs t <= &n then Cx(&0) else
              (f:real->complex) t) (&m) y}` THEN
      CONJ_TAC THENL [EXISTS_TAC `n:num` THEN
        REWRITE_TAC[IN_UNIV]; ASM_REWRITE_TAC[IN_ELIM_THM]];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(MP_TAC o check (fun th -> can (find_term (fun t -> t =
        `sqrt(real_measure(real_interval[--(&M),&M]))`)) (concl th))) THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `y:real` THEN STRIP_TAC THEN
      MATCH_MP_TAC CARLESON_AHAT_POS THEN
      MP_TAC(ISPECL [`\t. if abs t <= &n then Cx(&0) else (f:real->complex) t`;
        `y:real`]
        CARLESON_TRUNC_FAMILY_PLAIN_WINDOW_BOUND) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `y:real` THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`f:real->complex`; `y:real`;
        `&n:real`] CARLESON_GAMMA_LE_AHAT_L2) THEN
      ASM_REWRITE_TAC[REAL_POS] THEN DISCH_THEN MATCH_MP_TAC THEN
      MP_TAC(ISPECL [`\t. if abs t <= &n then Cx(&0) else (f:real->complex) t`;
        `y:real`]
        CARLESON_TRUNC_FAMILY_PLAIN_WINDOW_BOUND) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

(* --- 286U(a) a.e.-EXISTENCE of the symmetric-window Fourier limit (Fremlin *)
(* mt286.tex 2960-2975 + 3011-3020 output).  Given (i) the window-difference *)
(* family bounded above at every (n,y) [so gamma_n is a genuine sup] and     *)
(* (ii) the                                                                  *)
(* "bad set" {y | ~(inf_n gamma_n(y)=0)} is NEGLIGIBLE [the 286U(b)          *)
(* contradiction,                                                            *)
(* supplied by the per-slice negligibility + 286T], the improper symmetric   *)
(* limit                                                                     *)
(* g(y) = lim_{a->inf} (1/sqrt2pi) int_{-a}^a e^{-ixy}f exists for a.e. y.   *)
(* Off the                                                                   *)
(* bad set, inf gamma_n=0 (the !e criterion) feeds CARLESON_GAMMA_INF_CAUCHY *)
(* ->                                                                        *)
(* the tail-Cauchy hyp of CARLESON_286U_SYMLIM -> the limit. (BETA_RULE      *)
(* bridges                                                                   *)
(* INF_CAUCHY's lambda-applied II to SYMLIM's beta-reduced hypothesis.) ---  *)
let SCALED_TWO_SIDED = prove
 (`!c a. &0 < c /\ &0 <= a
         ==> real_integral (real_interval[--a,a]) (\u. sin(c * u) / u) =
             &2 * real_integral (real_interval[&0,a]) (\u. sin(c * u) / u)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\u. sin(c * u) / u`;
    `a:real`] REAL_INTEGRAL_REFLECT_AND_ADD) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC SIN_STRETCH_OVER_X_INTEGRABLE THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`\u. sin(c * u) / u`; `&2:real`; `real_interval[&0,a]`]
    REAL_INTEGRAL_LMUL) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC SIN_STRETCH_OVER_X_INTEGRABLE THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC(MESON[] `x = y ==> real_integral s x = real_integral s y`) THEN
  REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
  REWRITE_TAC[REAL_MUL_RNEG; SIN_NEG; real_div; REAL_INV_NEG] THEN
    REAL_ARITH_TAC);;

(* Brick 1 (the centering term): int_0^pi sin((n+1/2)u)/u du -> pi/2.        *)
let SINEKERNEL_CENTERING_LIMIT = prove
 (`((\n. real_integral (real_interval[&0,pi]) (\u. sin((&n + &1 / &2) * u) /
   u))
    ---> pi / &2) sequentially`,
  SUBGOAL_THEN
   `!n. real_integral (real_interval[&0,pi]) (\u. sin((&n + &1 / &2) * u) / u)
     =
        inv(&2) *
        real_integral (real_interval[--pi,pi]) (\u. sin((&n + &1 / &2) * u) /
          u)`
   (fun th -> ONCE_REWRITE_TAC[th]) THENL
   [GEN_TAC THEN
    MP_TAC(ISPECL [`&n + &1 / &2`; `pi`] SCALED_TWO_SIDED) THEN
    ANTS_TAC THENL [MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[GSYM SIN_OVER_X_SAMPLE] THEN
  SUBGOAL_THEN `pi / &2 = inv(&2) * pi` SUBST1_TAC THENL
   [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REALLIM_LMUL THEN REWRITE_TAC[SIN_OVER_X_SAMPLE_LIMIT]);;

(* Periodic-reflect integrability (shared prerequisite for the fold/window   *)
(* bricks): for f abs-integrable on [-pi,pi] and 2pi-periodic, (\u. f(x-u))  *)
(* is                                                                        *)
(* abs-integrable on [-pi,pi] (f(x-u) may hit f OUTSIDE [-pi,pi];            *)
(* periodicity                                                               *)
(* covers it).  Via ABSOLUTELY_REAL_INTEGRABLE_PERIODIC_OFFSET + reflection. *)
let PERIODIC_REFLECT_INTEGRABLE = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      (!y. f(y + &2 * pi) = f y)
      ==> (\u. f(x - u)) absolutely_real_integrable_on real_interval[--pi,pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\u. (f:real->real)(x - u)) = (\u. f(--u + x))` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `--pi`; `pi`; `x:real`]
    ABSOLUTELY_REAL_INTEGRABLE_PERIODIC_OFFSET) THEN
  ASM_REWRITE_TAC[REAL_ARITH `pi - --pi = &2 * pi`] THEN
  REWRITE_TAC[absolutely_real_integrable_on] THEN STRIP_TAC THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`\v. (f:real->real)(v + x)`; `--pi:real`; `pi:real`]
      REAL_INTEGRABLE_REFLECT) THEN
    ASM_REWRITE_TAC[REAL_NEG_NEG] THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`\v. abs((f:real->real)(v + x))`; `--pi:real`; `pi:real`]
      REAL_INTEGRABLE_REFLECT) THEN
    ASM_REWRITE_TAC[REAL_NEG_NEG] THEN DISCH_TAC THEN ASM_REWRITE_TAC[]]);;

(* Bound: abs(sin(cu)*inv u) <= c  (c>0, u<>0), via abs(sin x)<=abs x.       *)
let SINC_ABS_BOUND = prove
 (`!c u. &0 < c /\ ~(u = &0) ==> abs (sin (c * u) * inv u) <= c`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_ABS_MUL; REAL_ABS_INV] THEN
  MP_TAC(SPEC `c * u:real` REAL_ABS_SIN_BOUND_LE) THEN
  REWRITE_TAC[REAL_ABS_MUL] THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < c ==> abs c = c`] THEN DISCH_TAC THEN
  SUBGOAL_THEN `c = (c * abs u) * inv(abs u)`
   (fun th -> GEN_REWRITE_TAC RAND_CONV [th]) THENL
   [SUBGOAL_THEN `~(abs u = &0)` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[REAL_ABS_ZERO]; ALL_TAC] THEN
    ASM_SIMP_TAC[GSYM REAL_MUL_ASSOC; REAL_MUL_RINV; REAL_MUL_RID];
    MATCH_MP_TAC REAL_LE_RMUL THEN
      ASM_REWRITE_TAC[REAL_LE_INV_EQ; REAL_ABS_POS]]);;

(* Product integrability: sin(cu)/u (bounded) times f(x-u)                   *)
(* (periodic-reflect).                                                       *)
let SINC_TIMES_PERIODIC_INTEGRABLE = prove
 (`!(f:real->real) x c.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      (!y. f(y + &2 * pi) = f y) /\ &0 < c
      ==> (\u. sin(c * u) / u * f(x - u))
          absolutely_real_integrable_on real_interval[--pi,pi]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN
    MATCH_MP_TAC SIN_STRETCH_OVER_X_INTEGRABLE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_BOUNDED_POS] THEN EXISTS_TAC `c:real` THEN
    ASM_REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `u:real` THEN
      DISCH_TAC THEN
    ASM_CASES_TAC `u = &0` THENL
     [ASM_REWRITE_TAC[real_div; REAL_INV_0; REAL_MUL_RZERO; REAL_ABS_NUM] THEN
      ASM_REAL_ARITH_TAC;
      REWRITE_TAC[real_div] THEN MATCH_MP_TAC SINC_ABS_BOUND THEN
        ASM_REWRITE_TAC[]];
    MATCH_MP_TAC PERIODIC_REFLECT_INTEGRABLE THEN ASM_REWRITE_TAC[]]);;

(* The evenness fold combines the two one-sided sine-kernel integrals:       *)
(* combine to the two-sided one:                                             *)
(*   int_0^pi sin(cu)/u f(x+u) + int_0^pi sin(cu)/u f(x-u)                   *)
(*     = int_[-pi,pi] sin(cu)/u f(x-u).                                      *)
(* Reflect the f(x+u) piece to [-pi,0] (sin(cu)/u even), then REAL_INTEGRAL_ *)
(* COMBINE (integrability via SINC_TIMES_PERIODIC_INTEGRABLE).               *)
let SINEKERNEL_FOLD = prove
 (`!(f:real->real) x c.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      (!y. f(y + &2 * pi) = f y) /\ &0 < c
      ==> real_integral (real_interval[&0,pi]) (\u. sin(c * u) / u * f(x + u))
        +
          real_integral (real_interval[&0,pi]) (\u. sin(c * u) / u * f(x - u))
            =
          real_integral (real_interval[--pi,pi]) (\u. sin(c * u) / u * f(x -
            u))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\u. sin(c * u) / u * f(x + u)`; `&0:real`; `pi`]
    REAL_INTEGRAL_REFLECT) THEN
  REWRITE_TAC[REAL_NEG_0] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  SUBGOAL_THEN
   `real_integral (real_interval[--pi,&0])
       (\x'. sin (c * --x') / --x' * f (x + --x')) =
    real_integral (real_interval[--pi,&0]) (\u. sin(c * u) / u * f(x - u))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_EQ THEN X_GEN_TAC `u:real` THEN DISCH_TAC THEN
    BETA_TAC THEN
    SUBGOAL_THEN `sin (c * --u) / --u = sin(c * u) / u` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_MUL_RNEG; SIN_NEG; real_div; REAL_INV_NEG] THEN
      REAL_ARITH_TAC;
      ALL_TAC] THEN
    AP_TERM_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\u. sin(c * u) / u * f(x - u)`; `--pi`; `pi`; `&0:real`]
    REAL_INTEGRAL_COMBINE) THEN
  ASM_SIMP_TAC[REAL_ARITH `&0 < pi ==> --pi <= &0 /\ &0 <= pi`; PI_POS] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC SINC_TIMES_PERIODIC_INTEGRABLE THEN ASM_REWRITE_TAC[]);;

(* Two-sided sinc limit: int_[-pi,pi] sin((n+1/2)u)/u du -> pi (= 2 * Brick  *)
(* 1).                                                                       *)
let SINEKERNEL_RL_INTERVAL = prove
 (`!H a b. H absolutely_real_integrable_on real_interval[a,b]
       ==> ((\n. real_integral (real_interval[a,b])
                   (\u. sin((&n + &1 / &2) * u) * H u)) ---> &0) sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[a,b])
                   (\u. sin((&n + &1 / &2) * u) * H u)) =
    (\n. real_integral (real_interval[a,b]) (\u. H u * sin((&n + &1 / &2) *
      u)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\u. if u IN real_interval[a,b] then H u else &0`]
    RIEMANN_LEBESGUE_RLINE) THEN
  REWRITE_TAC[ABSOLUTELY_REAL_INTEGRABLE_RESTRICT_UNIV] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!c. real_integral (:real)
          (\u. (if u IN real_interval[a,b] then H u else &0) * sin(c * u)) =
        real_integral (real_interval[a,b]) (\u. H u * sin(c * u))`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN
    MP_TAC(ISPECL [`\u. H u * sin(c * u)`; `real_interval[a,b]`]
      REAL_INTEGRAL_RESTRICT_UNIV) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN MATCH_MP_TAC REAL_INTEGRAL_EQ THEN
    X_GEN_TAC `u:real` THEN REWRITE_TAC[IN_UNIV] THEN COND_CASES_TAC THEN
    REWRITE_TAC[REAL_MUL_LZERO];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o MATCH_MP REALLIM_POSINFINITY_SEQ_SHIFT) THEN
  REWRITE_TAC[]);;

(* Periodicity of the discrete sine-kernel term in x.  For the a.e.-set      *)
(* extension: the window-bridge only proves convergence for |x|<pi, but the  *)
(* consumer CARLESON_286V_FROM_SINEKERNEL needs a genuinely negligible       *)
(* exceptional set covering all of R. f 2pi-periodic makes the [0,pi] kernel *)
(* integral 2pi-periodic in x, so convergence on (-pi,pi)\s0 extends to all  *)
(* x                                                                         *)
(* outside a countable union of 2pi-shifted copies of s0 (still negligible). *)
let PERIODIC_SHIFT_INTEGRABLE = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      (!y. f(y + &2 * pi) = f y)
      ==> (\u. f(x + u)) absolutely_real_integrable_on real_interval[--pi,pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(\u. (f:real->real)(x + u)) = (\u. f(u + x))` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `--pi`; `pi`; `x:real`]
    ABSOLUTELY_REAL_INTEGRABLE_PERIODIC_OFFSET) THEN
  ASM_REWRITE_TAC[REAL_ARITH `pi - --pi = &2 * pi`]);;

(* Product integrability for the f(x+u) piece (mirror of                     *)
(* SINC_TIMES_PERIODIC_INTEGRABLE); used in the T_n split.                   *)
let SINC_TIMES_SHIFT_INTEGRABLE = prove
 (`!(f:real->real) x c.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      (!y. f(y + &2 * pi) = f y) /\ &0 < c
      ==> (\u. sin(c * u) / u * f(x + u))
          absolutely_real_integrable_on real_interval[--pi,pi]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN
    MATCH_MP_TAC SIN_STRETCH_OVER_X_INTEGRABLE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_BOUNDED_POS] THEN EXISTS_TAC `c:real` THEN
    ASM_REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `u:real` THEN
      DISCH_TAC THEN
    ASM_CASES_TAC `u = &0` THENL
     [ASM_REWRITE_TAC[real_div; REAL_INV_0; REAL_MUL_RZERO; REAL_ABS_NUM] THEN
      ASM_REAL_ARITH_TAC;
      REWRITE_TAC[real_div] THEN MATCH_MP_TAC SINC_ABS_BOUND THEN
        ASM_REWRITE_TAC[]];
    MATCH_MP_TAC PERIODIC_SHIFT_INTEGRABLE THEN ASM_REWRITE_TAC[]]);;

(* T_n split (algebraic heart of the window bridge): the discrete            *)
(* sine-kernel                                                               *)
(* integral splits by linearity as (fold pieces) - (2 f x)(centering piece): *)
(*   int_0^pi sin(cu)((f(x+u)+f(x-u))-2fx)/u                                 *)
(* = (int sin(cu)/u f(x+u) + int sin(cu)/u f(x-u)) - (2fx) int sin(cu)/u.    *)
(* Each piece integrable on [0,pi] (SINC_TIMES_SHIFT/PERIODIC +              *)
(* SIN_STRETCH_OVER                                                          *)
(* _X_INTEGRABLE, restricted from [-pi,pi]); linearity via ASM_SIMP with     *)
(* REAL_INTEGRAL_SUB/ADD/LMUL (handles the beta-redexes).                    *)
let TN_SPLIT = prove
 (`!(f:real->real) x c.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      (!y. f(y + &2 * pi) = f y) /\ &0 < c
      ==> real_integral (real_interval[&0,pi])
            (\u. sin(c * u) * ((f(x + u) + f(x - u)) - &2 * f x) / u) =
          (real_integral (real_interval[&0,pi]) (\u. sin(c * u) / u * f(x + u))
            +
           real_integral (real_interval[&0,pi]) (\u. sin(c * u) / u * f(x -
             u))) -
          (&2 * f x) * real_integral (real_interval[&0,pi]) (\u. sin(c * u) /
            u)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `!g:real->real. g absolutely_real_integrable_on real_interval[--pi,pi]
                  ==> g real_integrable_on real_interval[&0,pi]`
   (LABEL_TAC "RESTR") THENL
   [REPEAT STRIP_TAC THEN
     MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `real_interval[--pi,pi]` THEN
      ASM_REWRITE_TAC[SUBSET_REAL_INTERVAL] THEN
    MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\u. sin(c * u) / u * f(x + u)) real_integrable_on real_interval[&0,pi] /\
                (\u. sin(c * u) / u * f(x - u)) real_integrable_on
                  real_interval[&0,pi] /\
                (\u. sin(c * u) / u) real_integrable_on real_interval[&0,pi]`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "RESTR" MATCH_MP_TAC THEN
       MATCH_MP_TAC SINC_TIMES_SHIFT_INTEGRABLE THEN
      ASM_REWRITE_TAC[];
      USE_THEN "RESTR" MATCH_MP_TAC THEN
        MATCH_MP_TAC SINC_TIMES_PERIODIC_INTEGRABLE THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC SIN_STRETCH_OVER_X_INTEGRABLE THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\u. sin(c * u) * ((f(x + u) + f(x - u)) - &2 * f x) / u) =
    (\u. (sin(c * u) / u * f(x + u) + sin(c * u) / u * f(x - u)) -
         (&2 * f x) * (sin(c * u) / u))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_INTEGRAL_SUB; REAL_INTEGRAL_ADD; REAL_INTEGRAL_LMUL;
               REAL_INTEGRABLE_ADD; REAL_INTEGRABLE_LMUL]);;

(* General substitution t = x - u: int_[a,b] G(x-u) du = int_[x-b,x-a] G(t)  *)
(* dt.                                                                       *)
(* Converts the continuous-sinc hypothesis's t-integral over [-pi,pi] into   *)
(* the                                                                       *)
(* u-window [x-pi,x+pi] carrying the PURE sin(cu) kernel, matching the       *)
(* target;                                                                   *)
(* the window mismatch then vanishes by SINEKERNEL_RL_INTERVAL (pure sin, no *)
(* phase).                                                                   *)
let SINC_SUBST_GEN = prove
 (`!(G:real->real) x a b. G real_integrable_on real_interval[x - b, x - a]
      ==> real_integral (real_interval[a,b]) (\u. G(x - u)) =
          real_integral (real_interval[x - b, x - a]) G`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `p = x - b:real` THEN ABBREV_TAC `q = x - a:real` THEN
  MP_TAC(ISPECL [`G:real->real`; `real_integral (real_interval[p:real,q]) G`;
                 `p:real`; `q:real`; `-- &1:real`; `x:real`]
    HAS_REAL_INTEGRAL_AFFINITY) THEN
  ASM_SIMP_TAC[REAL_INTEGRABLE_INTEGRAL] THEN
  REWRITE_TAC[REAL_ARITH `-- &1 = &0 <=> F`] THEN
  REWRITE_TAC[REAL_ARITH `-- &1 * x + c = c - x`; REAL_ABS_NEG;
    REAL_ABS_NUM] THEN
  REWRITE_TAC[REAL_INV_1; REAL_MUL_LID; REAL_INV_NEG] THEN
  SUBGOAL_THEN
   `IMAGE (\x'. -- &1 * (x' - x)) (real_interval [p:real,q]) =
     real_interval[a,b]`
   SUBST1_TAC THENL
   [MAP_EVERY EXPAND_TAC ["p"; "q"] THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL] THEN
      X_GEN_TAC `y:real` THEN
    EQ_TAC THENL
     [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      STRIP_TAC THEN EXISTS_TAC `x - y:real` THEN CONJ_TAC THEN
        ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  DISCH_THEN(ACCEPT_TAC o MATCH_MP REAL_INTEGRAL_UNIQUE));;

(* Reflection integrability on the FULL hypothesis window: (\u. f(x-u)) is   *)
(* abs-integrable on [x-pi,x+pi] whenever f is abs-integrable on [-pi,pi].   *)
(* PURE reflection (u |-> x-u maps [x-pi,x+pi] onto [-pi,pi]) via REAL_      *)
(* INTEGRABLE_AFFINITY on f and |f| -- NO periodicity needed. This covers    *)
(* the                                                                       *)
(* tail-integrability for BOTH window-mismatch tails at once (subintervals   *)
(* of                                                                        *)
(* [x-pi,x+pi]), sidestepping any 'periodic => integ on any interval' lemma. *)
let REFLECT_INTEGRABLE_WINDOW = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi]
      ==> (\u. f(x - u)) absolutely_real_integrable_on real_interval[x - pi, x
        + pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `real_interval[x - pi, x + pi] =
                IMAGE (\u. inv(-- &1) * (u - x)) (real_interval[--pi,pi])`
                  SUBST1_TAC THENL
   [REWRITE_TAC[REAL_INV_NEG; REAL_INV_1] THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL] THEN
      X_GEN_TAC `y:real` THEN
    EQ_TAC THENL
     [STRIP_TAC THEN EXISTS_TAC `x - y:real` THEN CONJ_TAC THEN
       ASM_REAL_ARITH_TAC;
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  POP_ASSUM MP_TAC THEN REWRITE_TAC[absolutely_real_integrable_on] THEN
  STRIP_TAC THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`f:real->real`; `--pi`; `pi`; `-- &1:real`; `x:real`]
      REAL_INTEGRABLE_AFFINITY) THEN
    ASM_REWRITE_TAC[REAL_ARITH `-- &1 = &0 <=> F`] THEN
    REWRITE_TAC[REAL_ARITH `-- &1 * u + x = x - u`];
    MP_TAC(ISPECL [`\t. abs((f:real->real) t)`; `--pi`; `pi`; `-- &1:real`;
      `x:real`]
      REAL_INTEGRABLE_AFFINITY) THEN
    ASM_REWRITE_TAC[REAL_ARITH `-- &1 = &0 <=> F`] THEN
    REWRITE_TAC[REAL_ARITH `-- &1 * u + x = x - u`]]);;

(* Sinc-product integrability on the hypothesis window [x-pi,x+pi].          *)
let SINC_TIMES_REFLECT_WINDOW = prove
 (`!(f:real->real) x c.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ &0 < c
      ==> (\u. sin(c * u) / u * f(x - u))
          absolutely_real_integrable_on real_interval[x - pi, x + pi]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN
    MATCH_MP_TAC SIN_STRETCH_OVER_X_INTEGRABLE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_BOUNDED_POS] THEN EXISTS_TAC `c:real` THEN
    ASM_REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `u:real` THEN
      DISCH_TAC THEN
    ASM_CASES_TAC `u = &0` THENL
     [ASM_REWRITE_TAC[real_div; REAL_INV_0; REAL_MUL_RZERO; REAL_ABS_NUM] THEN
      ASM_REAL_ARITH_TAC;
      REWRITE_TAC[real_div] THEN MATCH_MP_TAC SINC_ABS_BOUND THEN
        ASM_REWRITE_TAC[]];
    MATCH_MP_TAC REFLECT_INTEGRABLE_WINDOW THEN ASM_REWRITE_TAC[]]);;

(* The hypothesis kernel sin(c(x-t))/(x-t) is integrable on [-pi,pi]: it is  *)
(* a                                                                         *)
(* reflection (t |-> x-t) of the stretch sin(cu)/u, so                       *)
(* REAL_INTEGRABLE_AFFINITY                                                  *)
(* from SIN_STRETCH_OVER_X_INTEGRABLE on the source window [x-pi,x+pi]       *)
(* (whose                                                                    *)
(* image under t|->x-t is [-pi,pi]).  Feeds the substitution HYP_U_FORM that *)
(* rewrites the continuous-sinc hypothesis into the pure-sin(cu) u-window    *)
(* form.                                                                     *)
let HYP_KERNEL_INTEGRABLE = prove
 (`!c x. &0 < c
         ==> (\t. sin(c * (x - t)) / (x - t)) real_integrable_on
             real_interval[--pi,pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `real_interval[--pi,pi] =
                IMAGE (\t. inv(-- &1) * (t - x)) (real_interval[x - pi, x +
                  pi])`
   SUBST1_TAC THENL
   [REWRITE_TAC[REAL_INV_NEG; REAL_INV_1] THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL] THEN
      X_GEN_TAC `y:real` THEN
    EQ_TAC THENL
     [STRIP_TAC THEN EXISTS_TAC `x - y:real` THEN CONJ_TAC THEN
       ASM_REAL_ARITH_TAC;
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\t. sin(c * (x - t)) / (x - t)) = (\t. (\u. sin(c * u) / u)(-- &1 * t +
     x))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
    REWRITE_TAC[REAL_ARITH `-- &1 * t + x:real = x - t`]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRABLE_AFFINITY THEN
  REWRITE_TAC[REAL_ARITH `-- &1 = &0 <=> F`] THEN
  MATCH_MP_TAC SIN_STRETCH_OVER_X_INTEGRABLE THEN ASM_REWRITE_TAC[]);;

(* The full hypothesis integrand sin(c(x-t))/(x-t) * f(t) is absolutely      *)
(* integrable on [-pi,pi] (bounded kernel times f).                          *)
let HYP_INTEGRAND_INTEGRABLE = prove
 (`!(f:real->real) x c.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ &0 < c
      ==> (\t. sin(c * (x - t)) / (x - t) * f t)
          absolutely_real_integrable_on real_interval[--pi,pi]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN
    MATCH_MP_TAC HYP_KERNEL_INTEGRABLE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_BOUNDED_POS] THEN EXISTS_TAC `c:real` THEN
    ASM_REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `t:real` THEN
      DISCH_TAC THEN
    ASM_CASES_TAC `x - t = &0` THENL
     [ASM_REWRITE_TAC[real_div; REAL_INV_0; REAL_MUL_RZERO; REAL_ABS_NUM] THEN
      ASM_REAL_ARITH_TAC;
      REWRITE_TAC[real_div] THEN MATCH_MP_TAC SINC_ABS_BOUND THEN
        ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[]]);;

(* HYP_U_FORM: rewrite the continuous-sinc hypothesis integral into the PURE *)
(* sin(cu) u-window form.  int_[x-pi,x+pi] sin(cu)/u f(x-u) du =             *)
(* int_[-pi,pi] sin(c(x-t))/(x-t) f(t) dt.  SINC_SUBST_GEN (G = the hyp      *)
(* integrand, a=x-pi,b=x+pi; integrable by HYP_INTEGRAND_INTEGRABLE) + REAL_ *)
(* INTEGRAL_EQ integrand-simplify (x-(x-u)=u, needs the :real-annotated      *)
(* rewrite).                                                                 *)
let HYP_U_FORM = prove
 (`!(f:real->real) x c.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ &0 < c
      ==> real_integral (real_interval[x - pi, x + pi]) (\u. sin(c * u) / u *
        f(x - u)) =
          real_integral (real_interval[--pi,pi]) (\t. sin(c * (x - t)) / (x -
            t) * f t)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\t. sin(c * (x - t)) / (x - t) * f t`; `x:real`; `x - pi`;
    `x + pi`]
    SINC_SUBST_GEN) THEN
  REWRITE_TAC[REAL_ARITH `x - (x + pi) = --pi`;
    REAL_ARITH `x - (x - pi) = pi`] THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC HYP_INTEGRAND_INTEGRABLE THEN ASM_REWRITE_TAC[];
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC REAL_INTEGRAL_EQ THEN X_GEN_TAC `u:real` THEN DISCH_TAC THEN
    REWRITE_TAC[REAL_ARITH `x - (x - u):real = u`]]);;

(* Tail-kernel integrability: f(x-u)/u is abs-integrable on a tail [a,b]     *)
(* that                                                                      *)
(* lies in [x-pi,x+pi] and avoids 0 (so 1/u is bounded there): bounded(inv)  *)
(* *                                                                         *)
(* f(x-u) [REFLECT_INTEGRABLE_WINDOW restricted].  This is the H(u)=f(x-u)/u *)
(* that SINEKERNEL_RL_INTERVAL consumes for the window-mismatch tails.       *)
let TAIL_KERNEL_INTEGRABLE = prove
 (`!(f:real->real) x a b.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      real_interval[a,b] SUBSET real_interval[x - pi, x + pi] /\
      (!u. u IN real_interval[a,b] ==> ~(u = &0))
      ==> (\u. f(x - u) / u) absolutely_real_integrable_on real_interval[a,b]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `inv real_continuous_on real_interval[a,b]` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\x:real. x`;
     `real_interval[a,b]`] REAL_CONTINUOUS_ON_INV) THEN
    ASM_REWRITE_TAC[REAL_CONTINUOUS_ON_ID; ETA_AX]; ALL_TAC] THEN
  REWRITE_TAC[real_div] THEN ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET THEN
    ASM_REWRITE_TAC[REAL_CLOSED_REAL_INTERVAL];
    MATCH_MP_TAC REAL_COMPACT_IMP_BOUNDED THEN
    MATCH_MP_TAC REAL_COMPACT_CONTINUOUS_IMAGE THEN
    ASM_REWRITE_TAC[REAL_COMPACT_INTERVAL];
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `real_interval[x - pi, x + pi]` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REFLECT_INTEGRABLE_WINDOW THEN ASM_REWRITE_TAC[]]);;

(* Tail vanishing: on a tail [a,b] subset [x-pi,x+pi] avoiding 0, the sine-  *)
(* kernel integral -> 0 (SINEKERNEL_RL_INTERVAL with H=f(x-u)/u,             *)
(* TAIL_KERNEL_ INTEGRABLE).                                                 *)
let TAIL_VANISH = prove
 (`!(f:real->real) x a b.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      real_interval[a,b] SUBSET real_interval[x - pi, x + pi] /\
      (!u. u IN real_interval[a,b] ==> ~(u = &0))
      ==> ((\n. real_integral (real_interval[a,b])
             (\u. sin((&n + &1 / &2) * u) / u * f(x - u))) ---> &0)
               sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[a,b]) (\u. sin((&n + &1 / &2) * u) / u *
     f(x - u))) =
    (\n. real_integral (real_interval[a,b])
           (\u. sin((&n + &1 / &2) * u) * (\v. f(x - v) / v) u))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC SINEKERNEL_RL_INTERVAL THEN
  MATCH_MP_TAC TAIL_KERNEL_INTEGRABLE THEN ASM_REWRITE_TAC[]);;

(* Window decomposition (x in (0,pi)): the [-pi,pi] sine-kernel integral     *)
(* splits                                                                    *)
(* as the hypothesis window [x-pi,x+pi] plus the two mismatch tails.         *)
(* int_[-pi,pi] k = int_[x-pi,x+pi] k + int_[-pi,x-pi] k - int_[pi,x+pi] k,  *)
(* k(u)=sin((n+1/2)u)/u f(x-u). Two REAL_INTEGRAL_COMBINEs (within [-pi,pi]  *)
(* at                                                                        *)
(* x-pi via SINC_TIMES_PERIODIC_INTEGRABLE, within [x-pi,x+pi] at pi via     *)
(* SINC_                                                                     *)
(* TIMES_REFLECT_WINDOW) + REAL_ARITH.                                       *)
let WINDOW_DECOMP = prove
 (`!(f:real->real) x n.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      (!y. f(y + &2 * pi) = f y) /\ &0 < x /\ x < pi
      ==> real_integral (real_interval[--pi,pi]) (\u. sin((&n + &1 / &2) * u) /
        u * f(x - u)) =
          (real_integral (real_interval[x - pi, x + pi]) (\u. sin((&n + &1 /
            &2) * u) / u * f(x - u)) +
           real_integral (real_interval[--pi, x - pi]) (\u. sin((&n + &1 / &2)
             * u) / u * f(x - u))) -
           real_integral (real_interval[pi, x + pi]) (\u. sin((&n + &1 / &2) *
             u) / u * f(x - u))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &n + &1 / &2` ASSUME_TAC THENL
    [REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u))
     real_integrable_on real_interval[--pi,pi] /\
    (\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u))
      real_integrable_on real_interval[x - pi, x + pi]`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THENL
     [MATCH_MP_TAC SINC_TIMES_PERIODIC_INTEGRABLE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC SINC_TIMES_REFLECT_WINDOW THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u)`;
    `--pi`; `pi`; `x - pi`]
    REAL_INTEGRAL_COMBINE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; DISCH_TAC] THEN
  MP_TAC(ISPECL [`\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u)`;
    `x - pi`; `x + pi`; `pi`]
    REAL_INTEGRAL_COMBINE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; DISCH_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* The hypothesis-window limit: int_[x-pi,x+pi] sin((n+1/2)u)/u f(x-u) -> pi *)
(* f x from the continuous-sinc hypothesis (at a:=n+1/2) via HYP_U_FORM +    *)
(* REALLIM_ POSINFINITY_SEQ_SHIFT.                                           *)
let HN_LIMIT = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ &0 < x /\ x <
        pi /\
      ((\a. real_integral (real_interval[--pi,pi]) (\t. sin(a * (x - t)) / (x -
        t) * f t))
       ---> pi * f x) at_posinfinity
      ==> ((\n. real_integral (real_interval[x - pi, x + pi])
                  (\u. sin((&n + &1 / &2) * u) / u * f(x - u))) ---> pi * f x)
                    sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[x - pi, x + pi])
           (\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u))) =
    (\n. (\a. real_integral (real_interval[--pi,pi]) (\t. sin(a * (x - t)) / (x
      - t) * f t))
           (&n + &1 / &2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC HYP_U_FORM THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC REALLIM_POSINFINITY_SEQ_SHIFT THEN ASM_REWRITE_TAC[]);;

(* Limit-combine helper: (A->l, B->0, C->0) ==> (\n. (A n + B n) - C n) ->   *)
(* l. Reusable form (l = (l+&0)-&0 + REALLIM_SUB/ADD) for the window-bridge  *)
(* assembly, applied with A/B/C the three abbreviated integral-functions.    *)
let LIM_SUM2_SUB = prove
 (`!A B C l. (A ---> l) sequentially /\ (B ---> &0) sequentially /\
             (C ---> &0) sequentially
     ==> ((\n. (A n + B n) - C n) ---> l) sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `l = (l + &0) - &0` SUBST1_TAC THENL
    [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REALLIM_SUB THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REALLIM_ADD THEN ASM_REWRITE_TAC[]);;

(* Periodicity-shifted reflect window: (\u. f(x-u)) abs-integrable on the    *)
(* SHIFTED window [x-3pi,x-pi] (the k=-1 copy), needed for the LEFT window-  *)
(* mismatch tail [-pi,x-pi] (x in (0,pi)) which is NOT subset [x-pi,x+pi].   *)
(* f(x-u) = f((x-2pi)-u) by periodicity = REFLECT_INTEGRABLE_WINDOW at       *)
(* centre x-2pi (window [(x-2pi)-pi,(x-2pi)+pi] = [x-3pi,x-pi]).             *)
let REFLECT_INTEGRABLE_WINDOW_SHIFT = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y)
      ==> (\u. f(x - u)) absolutely_real_integrable_on real_interval[x - &3 *
        pi, x - pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\u. (f:real->real)(x - u)) = (\u. f((x - &2 * pi) - u))` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `u:real` THEN
    SUBGOAL_THEN `x - u:real = ((x - &2 * pi) - u) + &2 * pi` SUBST1_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `x - &2 * pi`] REFLECT_INTEGRABLE_WINDOW) THEN
  ASM_REWRITE_TAC[REAL_ARITH `(x - &2 * pi) - pi = x - &3 * pi`;
                  REAL_ARITH `(x - &2 * pi) + pi = x - pi`]);;

(* Shifted tail-kernel integrability: f(x-u)/u abs-integ on a tail [a,b]     *)
(* subset [x-3pi,x-pi] avoiding 0 (bounded inv *                             *)
(* REFLECT_INTEGRABLE_WINDOW_SHIFT).                                         *)
let TAIL_KERNEL_INTEGRABLE_SHIFT = prove
 (`!(f:real->real) x a b.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y) /\
      real_interval[a,b] SUBSET real_interval[x - &3 * pi, x - pi] /\
      (!u. u IN real_interval[a,b] ==> ~(u = &0))
      ==> (\u. f(x - u) / u) absolutely_real_integrable_on real_interval[a,b]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `inv real_continuous_on real_interval[a,b]` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\x:real. x`;
     `real_interval[a,b]`] REAL_CONTINUOUS_ON_INV) THEN
    ASM_REWRITE_TAC[REAL_CONTINUOUS_ON_ID; ETA_AX]; ALL_TAC] THEN
  REWRITE_TAC[real_div] THEN ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET THEN
    ASM_REWRITE_TAC[REAL_CLOSED_REAL_INTERVAL];
    MATCH_MP_TAC REAL_COMPACT_IMP_BOUNDED THEN
    MATCH_MP_TAC REAL_COMPACT_CONTINUOUS_IMAGE THEN
    ASM_REWRITE_TAC[REAL_COMPACT_INTERVAL];
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `real_interval[x - &3 * pi, x - pi]` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REFLECT_INTEGRABLE_WINDOW_SHIFT THEN ASM_REWRITE_TAC[]]);;

(* Shifted tail vanishing (left window-mismatch tail): int_[a,b]             *)
(* sin((n+1/2)u)/u f(x-u) -> 0 for [a,b] subset [x-3pi,x-pi] avoiding 0.     *)
let TAIL_VANISH_SHIFT = prove
 (`!(f:real->real) x a b.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y) /\
      real_interval[a,b] SUBSET real_interval[x - &3 * pi, x - pi] /\
      (!u. u IN real_interval[a,b] ==> ~(u = &0))
      ==> ((\n. real_integral (real_interval[a,b])
             (\u. sin((&n + &1 / &2) * u) / u * f(x - u))) ---> &0)
               sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[a,b]) (\u. sin((&n + &1 / &2) * u) / u *
     f(x - u))) =
    (\n. real_integral (real_interval[a,b])
           (\u. sin((&n + &1 / &2) * u) * (\v. f(x - v) / v) u))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC SINEKERNEL_RL_INTERVAL THEN
  MATCH_MP_TAC TAIL_KERNEL_INTEGRABLE_SHIFT THEN ASM_REWRITE_TAC[]);;

(* WINDOW BRIDGE (x in (0,pi)): the [-pi,pi] sine-kernel W_n -> pi f x, from *)
(* the continuous-sinc hypothesis.  W_n = int_[x-pi,x+pi] + (left tail) -    *)
(* (right tail) [WINDOW_DECOMP]; window integral -> pi f x [HN_LIMIT]; LEFT  *)
(* tail                                                                      *)
(* [-pi,x-pi] -> 0 [TAIL_VANISH_SHIFT, the k=-1 window] and RIGHT tail       *)
(* [pi,x+pi]                                                                 *)
(* -> 0 [TAIL_VANISH]; LIM_SUM2_SUB combines. KEY: WINDOW_DECOMP RHS written *)
(* with the 3 integrals as EXPLICIT ((\m. INTEG) n) apps so MATCH_MP_TAC     *)
(* LIM_SUM2_SUB HO-unifies; DISJ2_TAC for the SUBSET_REAL_INTERVAL           *)
(* disjuncts.                                                                *)
let WINDOW_BRIDGE_POS = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y) /\
      &0 < x /\ x < pi /\
      ((\a. real_integral (real_interval[--pi,pi]) (\t. sin(a * (x - t)) / (x -
        t) * f t))
       ---> pi * f x) at_posinfinity
      ==> ((\n. real_integral (real_interval[--pi,pi])
                  (\u. sin((&n + &1 / &2) * u) / u * f(x - u))) ---> pi * f x)
                    sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[--pi,pi]) (\u. sin((&n + &1 / &2) * u) /
     u * (f:real->real)(x - u))) =
    (\n. ((\m. real_integral (real_interval[x - pi, x + pi]) (\u. sin((&m + &1
      / &2) * u) / u * f(x - u))) n +
          (\m. real_integral (real_interval[--pi, x - pi]) (\u. sin((&m + &1 /
            &2) * u) / u * f(x - u))) n) -
          (\m. real_integral (real_interval[pi, x + pi]) (\u. sin((&m + &1 /
            &2) * u) / u * f(x - u))) n)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC WINDOW_DECOMP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC LIM_SUM2_SUB THEN REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC HN_LIMIT THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC TAIL_VANISH_SHIFT THEN
      ASM_REWRITE_TAC[SUBSET_REAL_INTERVAL; IN_REAL_INTERVAL] THEN
    CONJ_TAC THENL [DISJ2_TAC THEN MP_TAC PI_POS THEN ASM_REAL_ARITH_TAC;
                    REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC];
    MATCH_MP_TAC TAIL_VANISH THEN
      ASM_REWRITE_TAC[SUBSET_REAL_INTERVAL; IN_REAL_INTERVAL] THEN
    CONJ_TAC THENL [DISJ2_TAC THEN MP_TAC PI_POS THEN ASM_REAL_ARITH_TAC;
                    REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC]]);;

(* Payoff step: the discrete [0,pi] sine-kernel T_n = int_0^pi sin((n+1/2)u) *)
(* ((f(x+u)+f(x-u))-2fx)/u = W_n - (2fx)*C(n) per n [TN_SPLIT +              *)
(* SINEKERNEL_FOLD], so with W_n -> pi f x and C(n) -> pi/2, T_n -> pi fx -  *)
(* 2fx(pi/2) = 0.                                                            *)
let TN_SPLIT_FOLD_EQ = prove
 (`!(f:real->real) x n.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y)
      ==> real_integral (real_interval[&0,pi]) (\u. sin((&n + &1 / &2) * u) *
        (((f:real->real)(x + u) + f(x - u)) - &2 * f x) / u) =
          real_integral (real_interval[--pi,pi]) (\u. sin((&n + &1 / &2) * u) /
            u * f(x - u)) -
          (&2 * f x) * real_integral (real_interval[&0,pi]) (\u. sin((&n + &1 /
            &2) * u) / u)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `x:real`; `&n + &1 / &2`] TN_SPLIT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`f:real->real`; `x:real`;
    `&n + &1 / &2`] SINEKERNEL_FOLD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

(* T_n -> 0 (the CARLESON_286V_FROM_SINEKERNEL input) from W_n -> pi f x.    *)
(* GEN_REWRITE the limit-value &0 at RATOR_CONV o RAND_CONV (NOT SUBST1,     *)
(* which would also rewrite the [&0,pi] interval bound); REALLIM_SUB +       *)
(* REALLIM_LMUL + SINEKERNEL_CENTERING_LIMIT.                                *)
let TN_ZERO = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y) /\
      ((\n. real_integral (real_interval[--pi,pi])
              (\u. sin((&n + &1 / &2) * u) / u * f(x - u))) ---> pi * f x)
                sequentially
      ==> ((\n. real_integral (real_interval[&0,pi])
              (\u. sin((&n + &1 / &2) * u) * ((f(x + u) + f(x - u)) - &2 * f x)
                / u)) ---> &0) sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[&0,pi])
              (\u. sin((&n + &1 / &2) * u) * (((f:real->real)(x + u) + f(x -
                u)) - &2 * f x) / u)) =
    (\n. real_integral (real_interval[--pi,pi]) (\u. sin((&n + &1 / &2) * u) /
      u * f(x - u)) -
         (&2 * f x) * real_integral (real_interval[&0,pi]) (\u. sin((&n + &1 /
           &2) * u) / u))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     MATCH_MP_TAC TN_SPLIT_FOLD_EQ THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  GEN_REWRITE_TAC (RATOR_CONV o RAND_CONV)
   [REAL_ARITH `&0 = pi * (f:real->real) x - (&2 * f x) * (pi / &2)`] THEN
  MATCH_MP_TAC REALLIM_SUB THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REALLIM_LMUL THEN REWRITE_TAC[SINEKERNEL_CENTERING_LIMIT]);;

(* ==== Negative case x in (-pi,0): +2pi-shifted mirror of the window        *)
(* bridge. ==                                                                *)

(* HN_LIMIT with the (spurious) 0<x<pi dropped, so usable for both signs.    *)
let HN_LIMIT_GEN = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      ((\a. real_integral (real_interval[--pi,pi]) (\t. sin(a * (x - t)) / (x -
        t) * f t))
       ---> pi * f x) at_posinfinity
      ==> ((\n. real_integral (real_interval[x - pi, x + pi])
                  (\u. sin((&n + &1 / &2) * u) / u * f(x - u))) ---> pi * f x)
                    sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[x - pi, x + pi])
           (\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u))) =
    (\n. (\a. real_integral (real_interval[--pi,pi]) (\t. sin(a * (x - t)) / (x
      - t) * f t))
           (&n + &1 / &2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC HYP_U_FORM THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC REALLIM_POSINFINITY_SEQ_SHIFT THEN ASM_REWRITE_TAC[]);;

(* +2pi-shifted reflect window [x+pi,x+3pi] (k=+1 copy), for the RIGHT tail  *)
(* [x+pi,pi] of the x in (-pi,0) mismatch (there x-u in (-2pi,-pi]).         *)
let REFLECT_INTEGRABLE_WINDOW_SHIFT_POS = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y)
      ==> (\u. f(x - u)) absolutely_real_integrable_on real_interval[x + pi, x
        + &3 * pi]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\u. (f:real->real)(x - u)) = (\u. f((x + &2 * pi) - u))` SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `u:real` THEN
    SUBGOAL_THEN `(x + &2 * pi) - u:real = (x - u) + &2 * pi` SUBST1_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`f:real->real`; `x + &2 * pi`] REFLECT_INTEGRABLE_WINDOW) THEN
  ASM_REWRITE_TAC[REAL_ARITH `(x + &2 * pi) - pi = x + pi`;
                  REAL_ARITH `(x + &2 * pi) + pi = x + &3 * pi`]);;

let TAIL_KERNEL_INTEGRABLE_SHIFT_POS = prove
 (`!(f:real->real) x a b.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y) /\
      real_interval[a,b] SUBSET real_interval[x + pi, x + &3 * pi] /\
      (!u. u IN real_interval[a,b] ==> ~(u = &0))
      ==> (\u. f(x - u) / u) absolutely_real_integrable_on real_interval[a,b]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `inv real_continuous_on real_interval[a,b]` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\x:real. x`;
     `real_interval[a,b]`] REAL_CONTINUOUS_ON_INV) THEN
    ASM_REWRITE_TAC[REAL_CONTINUOUS_ON_ID; ETA_AX]; ALL_TAC] THEN
  REWRITE_TAC[real_div] THEN ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET THEN
    ASM_REWRITE_TAC[REAL_CLOSED_REAL_INTERVAL];
    MATCH_MP_TAC REAL_COMPACT_IMP_BOUNDED THEN
      MATCH_MP_TAC REAL_COMPACT_CONTINUOUS_IMAGE THEN
    ASM_REWRITE_TAC[REAL_COMPACT_INTERVAL];
    MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_ON_SUBINTERVAL THEN
    EXISTS_TAC `real_interval[x + pi, x + &3 * pi]` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REFLECT_INTEGRABLE_WINDOW_SHIFT_POS THEN ASM_REWRITE_TAC[]]);;

let TAIL_VANISH_SHIFT_POS = prove
 (`!(f:real->real) x a b.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y) /\
      real_interval[a,b] SUBSET real_interval[x + pi, x + &3 * pi] /\
      (!u. u IN real_interval[a,b] ==> ~(u = &0))
      ==> ((\n. real_integral (real_interval[a,b])
             (\u. sin((&n + &1 / &2) * u) / u * f(x - u))) ---> &0)
               sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[a,b]) (\u. sin((&n + &1 / &2) * u) / u *
     f(x - u))) =
    (\n. real_integral (real_interval[a,b]) (\u. sin((&n + &1 / &2) * u) * (\v.
      f(x - v) / v) u))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC SINEKERNEL_RL_INTERVAL THEN
  MATCH_MP_TAC TAIL_KERNEL_INTEGRABLE_SHIFT_POS THEN ASM_REWRITE_TAC[]);;

(* Window decomposition, x in (-pi,0) (ordering x-pi < -pi < x+pi < pi):     *)
(* int_[-pi,pi] k = int_[x-pi,x+pi] k - int_[x-pi,-pi] k + int_[x+pi,pi] k.  *)
let WINDOW_DECOMP_NEG = prove
 (`!(f:real->real) x n.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\
      (!y. f(y + &2 * pi) = f y) /\ --pi < x /\ x < &0
      ==> real_integral (real_interval[--pi,pi]) (\u. sin((&n + &1 / &2) * u) /
        u * f(x - u)) =
          (real_integral (real_interval[x - pi, x + pi]) (\u. sin((&n + &1 /
            &2) * u) / u * f(x - u)) -
           real_integral (real_interval[x - pi, --pi]) (\u. sin((&n + &1 / &2)
             * u) / u * f(x - u))) +
           real_integral (real_interval[x + pi, pi]) (\u. sin((&n + &1 / &2) *
             u) / u * f(x - u))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &n + &1 / &2` ASSUME_TAC THENL
    [REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u))
     real_integrable_on real_interval[--pi,pi] /\
    (\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u))
      real_integrable_on real_interval[x - pi, x + pi]`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THENL
     [MATCH_MP_TAC SINC_TIMES_PERIODIC_INTEGRABLE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC SINC_TIMES_REFLECT_WINDOW THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u)`;
    `x - pi`; `x + pi`; `--pi`]
    REAL_INTEGRAL_COMBINE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; DISCH_TAC] THEN
  MP_TAC(ISPECL [`\u. sin((&n + &1 / &2) * u) / u * (f:real->real)(x - u)`;
    `--pi`; `pi`; `x + pi`]
    REAL_INTEGRAL_COMBINE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; DISCH_TAC] THEN
  ASM_REAL_ARITH_TAC);;

(* Combine helper (neg): (A->l, B->0, C->0) ==> (\n. (A n - B n) + C n) ->   *)
(* l.                                                                        *)
let LIM_SUB2_ADD = prove
 (`!A B C l. (A ---> l) sequentially /\ (B ---> &0) sequentially /\
             (C ---> &0) sequentially
     ==> ((\n. (A n - B n) + C n) ---> l) sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `l = (l - &0) + &0` SUBST1_TAC THENL
    [REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REALLIM_ADD THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REALLIM_SUB THEN ASM_REWRITE_TAC[]);;

(* WINDOW BRIDGE (x in (-pi,0)): mirror of WINDOW_BRIDGE_POS.  LEFT tail     *)
(* [x-pi,-pi] plain reflect (TAIL_VANISH), RIGHT tail [x+pi,pi] the +2pi     *)
(* shift                                                                     *)
(* (TAIL_VANISH_SHIFT_POS); LIM_SUB2_ADD. Nonzero legs: MP_TAC PI_POS        *)
(* (x+pi>0).                                                                 *)
let WINDOW_BRIDGE_NEG = prove
 (`!(f:real->real) x.
      f absolutely_real_integrable_on real_interval[--pi,pi] /\ (!y. f(y + &2 *
        pi) = f y) /\
      --pi < x /\ x < &0 /\
      ((\a. real_integral (real_interval[--pi,pi]) (\t. sin(a * (x - t)) / (x -
        t) * f t))
       ---> pi * f x) at_posinfinity
      ==> ((\n. real_integral (real_interval[--pi,pi])
                  (\u. sin((&n + &1 / &2) * u) / u * f(x - u))) ---> pi * f x)
                    sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. real_integral (real_interval[--pi,pi]) (\u. sin((&n + &1 / &2) * u) /
     u * (f:real->real)(x - u))) =
    (\n. ((\m. real_integral (real_interval[x - pi, x + pi]) (\u. sin((&m + &1
      / &2) * u) / u * f(x - u))) n -
          (\m. real_integral (real_interval[x - pi, --pi]) (\u. sin((&m + &1 /
            &2) * u) / u * f(x - u))) n) +
          (\m. real_integral (real_interval[x + pi, pi]) (\u. sin((&m + &1 /
            &2) * u) / u * f(x - u))) n)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC WINDOW_DECOMP_NEG THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC LIM_SUB2_ADD THEN REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC HN_LIMIT_GEN THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC TAIL_VANISH THEN
      ASM_REWRITE_TAC[SUBSET_REAL_INTERVAL; IN_REAL_INTERVAL] THEN
    CONJ_TAC THENL [DISJ2_TAC THEN MP_TAC PI_POS THEN ASM_REAL_ARITH_TAC;
                    REPEAT STRIP_TAC THEN MP_TAC PI_POS THEN
                      ASM_REAL_ARITH_TAC];
    MATCH_MP_TAC TAIL_VANISH_SHIFT_POS THEN
      ASM_REWRITE_TAC[SUBSET_REAL_INTERVAL; IN_REAL_INTERVAL] THEN
    CONJ_TAC THENL [DISJ2_TAC THEN MP_TAC PI_POS THEN ASM_REAL_ARITH_TAC;
                    REPEAT STRIP_TAC THEN MP_TAC PI_POS THEN
                      ASM_REAL_ARITH_TAC]]);;

(* --- Helper: the discrete [0,pi] sine-kernel T_n is invariant under any    *)
(* integer multiple of the 2*pi period (iterated DISCRETE_KERNEL_PERIODIC).  *)
(* ---                                                                       *)
let REAL_REP_MOD_2PI = prove
 (`!x. ?k. integer k /\ --pi <= x - k * (&2 * pi) /\ x - k * (&2 * pi) < pi`,
  GEN_TAC THEN EXISTS_TAC `floor((x + pi) / (&2 * pi))` THEN
  MP_TAC(SPEC `(x + pi) / (&2 * pi)` FLOOR) THEN
  ABBREV_TAC `k = floor((x + pi) / (&2 * pi))` THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `&0 < &2 * pi` ASSUME_TAC THENL
   [MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`k:real`; `(x + pi) / (&2 * pi)`;
    `&2 * pi`] REAL_LE_RMUL) THEN
  MP_TAC(ISPECL [`(x + pi) / (&2 * pi)`; `k + &1`;
    `&2 * pi`] REAL_LT_RMUL) THEN
  ASM_SIMP_TAC[REAL_DIV_RMUL; REAL_LT_IMP_NZ; REAL_LT_IMP_LE] THEN
  REAL_ARITH_TAC);;

(* --- Helper: the union over all integer 2*pi-translates of a negligible    *)
(* set                                                                       *)
(* is negligible (countable union of translates). ---                        *)
let REAL_NEGLIGIBLE_TRANSLATE_UNION = prove
 (`!s. real_negligible s
       ==> real_negligible {x | ?k. integer k /\ (x - k * (&2 * pi)) IN s}`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC REAL_NEGLIGIBLE_SUBSET THEN
  EXISTS_TAC
   `UNIONS {IMAGE (\y:real. (&n * (&2 * pi)) + y) s UNION
            IMAGE (\y:real. ((-- &n) * (&2 * pi)) + y) s | n IN (:num)}` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_COUNTABLE_UNIONS THEN
    X_GEN_TAC `n:num` THEN MATCH_MP_TAC REAL_NEGLIGIBLE_UNION THEN
    CONJ_TAC THEN MATCH_MP_TAC REAL_NEGLIGIBLE_TRANSLATION THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_UNIONS] THEN
    X_GEN_TAC `x:real` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN (X_CHOOSE_TAC `n:num`) o
      REWRITE_RULE[INTEGER_CASES]) THEN
    EXISTS_TAC
     `IMAGE (\y:real. (&n * (&2 * pi)) + y) s UNION
      IMAGE (\y:real. ((-- &n) * (&2 * pi)) + y) s` THEN
    (CONJ_TAC THENL [MESON_TAC[IN_UNIV]; ALL_TAC]) THEN
    REWRITE_TAC[IN_UNION; IN_IMAGE] THENL
     [DISJ1_TAC; DISJ2_TAC] THEN
    EXISTS_TAC `x - k * (&2 * pi)` THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC]);;

(* For a representative x in (-pi,pi)                                       *)
(* off the origin, the continuous-sinc a.e. limit gives the discrete         *)
(* sine-kernel T_n(x) -> 0 (WINDOW_BRIDGE_POS/NEG + TN_ZERO).                *)
let TN_ZERO_REP = prove
 (`!(f:real->real) x.
     f absolutely_real_integrable_on real_interval[--pi,pi] /\
     (!y. f(y + &2 * pi) = f y) /\
     --pi < x /\ x < pi /\ ~(x = &0) /\
     ((\a. real_integral (real_interval[--pi,pi])
             (\t. sin(a * (x - t)) / (x - t) * f t)) ---> pi * f x)
               at_posinfinity
     ==> ((\n. real_integral (real_interval[&0,pi])
                 (\u. sin((&n + &1 / &2) * u) *
                      ((f(x + u) + f(x - u)) - &2 * f x) / u)) ---> &0)
                        sequentially`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC TN_ZERO THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o MATCH_MP (REAL_ARITH
    `~(x = &0) ==> &0 < x \/ x < &0`)) THENL
   [MATCH_MP_TAC WINDOW_BRIDGE_POS THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC WINDOW_BRIDGE_NEG THEN ASM_REWRITE_TAC[]]);;

(* 286V: continuous sinc to discrete sine kernel (Fremlin 286V               *)
(* lines 3099-3131): the bounded correction p_x(t)=(1/(2sin(t/2))-1/t)f(x-t) *)
(* is integrable, so by Riemann-Lebesgue the continuous sinc limit implies   *)
(* the discrete sine-kernel limit fed to CARLESON_286V_FROM_SINEKERNEL.      *)
(* The continuous-sinc hypothesis is guarded to the fundamental domain       *)
(* --pi < x < pi (Fremlin's "this is where we need to know that |x|<pi",     *)
(* line 3124: off [-pi,pi] the sinc integral -> 0, not f(x)); the discrete   *)
(* conclusion is extended to all x by 2*pi-periodicity of T_n                *)
(* (representative reduction + DISCRETE_KERNEL_PERIODIC_MULT).               *)
let CARLESON_286V_CONTINUOUS_TO_DISCRETE = prove
 (`!f. f square_integrable_on real_interval[--pi,pi] /\
       (!x. f(x + &2 * pi) = f x) /\
       (?s. real_negligible s /\
            !x. --pi < x /\ x < pi /\ ~(x IN s)
                ==> ((\a. inv(pi) *
                          real_integral (real_interval[--pi,pi])
                             (\t. sin(a * (x - t)) / (x - t) * f t))
                     ---> f x) at_posinfinity)
       ==> (?s. real_negligible s /\
                !x. ~(x IN s)
                    ==> ((\n. real_integral (real_interval[&0,pi])
                                (\u. sin((&n + &1 / &2) * u) *
                                     ((f(x + u) + f(x - u)) - &2 * f x) / u))
                         ---> &0) sequentially)`,
  GEN_TAC THEN STRIP_TAC THEN
  EXISTS_TAC
   `{x | ?k. integer k /\ (x - k * (&2 * pi)) IN (s UNION {--pi, &0})}` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_TRANSLATE_UNION THEN
    MATCH_MP_TAC REAL_NEGLIGIBLE_UNION THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_NEGLIGIBLE_COUNTABLE THEN
    SIMP_TAC[COUNTABLE_INSERT; COUNTABLE_SING];
    ALL_TAC] THEN
  REWRITE_TAC[IN_ELIM_THM; NOT_EXISTS_THM] THEN
  X_GEN_TAC `x:real` THEN DISCH_TAC THEN
  X_CHOOSE_THEN `k:real` STRIP_ASSUME_TAC (SPEC `x:real` REAL_REP_MOD_2PI) THEN
  ABBREV_TAC `r = x - k * (&2 * pi)` THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `k:real`) THEN
  ASM_REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; DE_MORGAN_THM] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `x = r + k * (&2 * pi)` SUBST1_TAC THENL
   [EXPAND_TAC "r" THEN REAL_ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[REAL_PERIODIC_INTEGER_MULTIPLE]) THEN
  SUBGOAL_THEN
   `!n. real_integral (real_interval[&0,pi])
          (\u. sin((&n + &1 / &2) * u) *
               ((f((r + k * (&2 * pi)) + u) + f((r + k * (&2 * pi)) - u)) -
                &2 * f(r + k * (&2 * pi))) / u) =
        real_integral (real_interval[&0,pi])
          (\u. sin((&n + &1 / &2) * u) *
               ((f(r + u) + f(r - u)) - &2 * f r) / u)`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MATCH_MP_TAC REAL_INTEGRAL_EQ THEN
    X_GEN_TAC `u:real` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `f((r + k * (&2 * pi)) + u) = f(r + u) /\
      f((r + k * (&2 * pi)) - u) = f(r - u) /\
      f(r + k * (&2 * pi)):real = f r`
     (fun th -> REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THEN
    ONCE_REWRITE_TAC[REAL_ARITH
      `(r + k * (&2 * pi)) + u:real = (r + u) + k * (&2 * pi)`;
     REAL_ARITH `(r + k * (&2 * pi)) - u:real = (r - u) + k * (&2 * pi)`] THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC TN_ZERO_REP THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC SQUARE_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
    ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL];
    REWRITE_TAC[REAL_PERIODIC_INTEGER_MULTIPLE] THEN ASM_REWRITE_TAC[];
    ASM_REAL_ARITH_TAC;
    ASM_REAL_ARITH_TAC;
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a. real_integral (real_interval[--pi,pi])
          (\t. sin(a * (r - t)) / (r - t) * f t) =
        pi * (inv(pi) * real_integral (real_interval[--pi,pi])
                (\t. sin(a * (r - t)) / (r - t) * f t))`
   (fun th -> ONCE_REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MP_TAC PI_POS THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  SUBGOAL_THEN
   `((\a. inv pi * real_integral (real_interval[--pi,pi])
             (\t. sin(a * (r - t)) / (r - t) * f t)) ---> f r) at_posinfinity`
   (MP_TAC o BETA_RULE o SPEC `pi` o MATCH_MP REALLIM_LMUL) THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[]]);;

(* Continuous-sinc convergence a.e. implies Fourier-series convergence a.e. *)
(* The continuous-sinc hypothesis is on the fundamental domain --pi<x<pi     *)
(* (Fremlin 286V line 3124); periodicity extends the conclusion to all x.    *)
let CARLESON_286V_FROM_CONTINUOUS_SINC = prove
 (`!f. f square_integrable_on real_interval[--pi,pi] /\
       (!x. f(x + &2 * pi) = f x) /\
       (?s. real_negligible s /\
            !x. --pi < x /\ x < pi /\ ~(x IN s)
                ==> ((\a. inv(pi) *
                          real_integral (real_interval[--pi,pi])
                             (\t. sin(a * (x - t)) / (x - t) * f t))
                     ---> f x) at_posinfinity)
       ==> ?s. real_negligible s /\
               !x. ~(x IN s)
                   ==> ((\n. sum(0..n) (\k. fourier_coefficient f k *
                                            trigonometric_set k x))
                        ---> f x) sequentially`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC CARLESON_286V_FROM_SINEKERNEL THEN
  FIRST_ASSUM(CONJUNCTS_THEN ASSUME_TAC) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC CARLESON_286V_CONTINUOUS_TO_DISCRETE THEN
  ASM_REWRITE_TAC[]);;

(* --- 286V-front sinc-kernel FT keystone (Fremlin 286V line 3072): the      *)
(* window                                                                    *)
(* function h_ax(y) = e^{ixy} on |y|<=a has FT hhat_ax(t) = (1/sqrt2pi) 2    *)
(* sin                                                                       *)
(* ((x-t)a)/(x-t); the underlying integral is int_{[-a,a]} e^{i c y} dy =    *)
(* 2 sin(a c)/c (c = x-t =/= 0), via the complex FTC (antiderivative         *)
(* e^{icy}/(ic)                                                              *)
(* = CEXP_IB_VECTOR_DERIV) + the endpoint combination CEXP_ENDPOINT_ID. This *)
(* is                                                                        *)
(* the concrete calc behind <g|h_ax> = <f_2|hhat_ax> (284Ob) in the 286V     *)
(* descent.                                                                  *)
let CARLESON_SINC_KERNEL_INTEGRAL = prove
 (`!a c. &0 <= a /\ ~(c = &0)
     ==> ((\y. cexp(ii * Cx c * Cx(drop y))) has_integral Cx(&2 * sin(a * c) /
       c))
         (interval[lift(--a), lift a])`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\y. cexp(ii * Cx c * Cx(drop y)) / (ii * Cx c)`;
    `\y. cexp(ii * Cx c * Cx(drop y))`;
    `lift(--a)`; `lift a`] FUNDAMENTAL_THEOREM_OF_CALCULUS) THEN
  REWRITE_TAC[LIFT_DROP] THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[LIFT_DROP] THEN ASM_REAL_ARITH_TAC;
      REPEAT STRIP_TAC THEN
      MATCH_MP_TAC HAS_VECTOR_DERIVATIVE_AT_WITHIN THEN
      MP_TAC(ISPECL [`c:real`; `x:real^1`] CEXP_IB_VECTOR_DERIV) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[LIFT_DROP] THEN
  MATCH_MP_TAC(MESON[] `x = y ==> (f has_integral x) s ==> (f has_integral y)
    s`) THEN
  MP_TAC(ISPECL [`a:real`; `c:real`] CEXP_ENDPOINT_ID) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  REWRITE_TAC[LIFT_DROP] THEN
  MATCH_MP_TAC(MESON[] `p = r /\ q = s ==> p/w - q/w = r/w - s/w`) THEN
  CONJ_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[CX_NEG] THEN
    SIMPLE_COMPLEX_ARITH_TAC);;

(* --- 286V-front: the window h_ax(y) = e^{ixy} on |y|<=a (0 outside), and   *)
(* its                                                                       *)
(* Fourier transform hhat_ax(t) = (1/sqrt2pi) 2 sin(a(x-t))/(x-t) (x =/= t). *)
(* First the raw integral int_R e^{-ity}h_ax = 2sin(a(x-t))/(x-t) [restrict  *)
(* to                                                                        *)
(* [-a,a] + combine exponents + CARLESON_SINC_KERNEL_INTEGRAL], then the     *)
(* fourier                                                                   *)
(* normalisation. ---                                                        *)
let CARLESON_HAX_FT_INTEGRAL = prove
 (`!a x t. &0 <= a /\ ~(x - t = &0)
     ==> integral (:real^1)
          (\y. cexp(--(ii * Cx t * Cx(drop y))) *
               (if abs(drop y) <= a then cexp(ii * Cx x * Cx(drop y)) else
                 Cx(&0))) =
         Cx(&2 * sin(a * (x - t)) / (x - t))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC INTEGRAL_UNIQUE THEN
  SUBGOAL_THEN
   `(\y. cexp(--(ii * Cx t * Cx(drop y))) *
         (if abs(drop y) <= a then cexp(ii * Cx x * Cx(drop y)) else Cx(&0))) =
    (\y. if y IN interval[lift(--a),lift a]
         then cexp(ii * Cx(x - t) * Cx(drop y)) else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `y:real^1` THEN
    REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP; COMPLEX_VEC_0] THEN
    REWRITE_TAC[REAL_ARITH `--a <= drop y /\ drop y <= a <=> abs(drop y) <= a`]
      THEN
    COND_CASES_TAC THEN REWRITE_TAC[COMPLEX_MUL_RZERO] THEN
    REWRITE_TAC[GSYM CEXP_ADD] THEN AP_TERM_TAC THEN
    REWRITE_TAC[CX_SUB] THEN SIMPLE_COMPLEX_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[HAS_INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC CARLESON_SINC_KERNEL_INTEGRAL THEN ASM_REWRITE_TAC[]);;

let CARLESON_HAX_FT = prove
 (`!a x t. &0 <= a /\ ~(x - t = &0)
     ==> fourier (\y. if abs y <= a then cexp(ii * Cx x * Cx y) else Cx(&0)) t
       =
         Cx(inv(sqrt(&2 * pi))) * Cx(&2 * sin(a * (x - t)) / (x - t))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[fourier] THEN
  MP_TAC(ISPECL [`a:real`; `x:real`; `t:real`] CARLESON_HAX_FT_INTEGRAL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[GSYM CX_INV; complex_div; COMPLEX_MUL_LID]);;

(* ------------------------------------------------------------------------- *)
(* Window-function infrastructure for the 286V sinc computation.  The window *)
(* h_ax(y) = e^{ixy} on |y|<=a, 0 elsewhere, is bounded (modulus 1) with     *)
(* compact support, hence both L^1 (HAX_ABSINT) and L^2 (HAX_L2).            *)
(* ------------------------------------------------------------------------- *)

let CEXP_LINEAR_CONTINUOUS = prove
 (`!c:complex s:real^1->bool. (\z. cexp(c * Cx(drop z))) continuous_on s`,
  REPEAT GEN_TAC THEN ONCE_REWRITE_TAC[GSYM o_DEF] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
    MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN REWRITE_TAC[CONTINUOUS_ON_ID];
    REWRITE_TAC[CONTINUOUS_ON_CEXP]]);;

let NORM_CEXP_II_XY = prove
 (`!x y:real. norm(cexp(ii * Cx x * Cx y)) = &1`,
  REPEAT GEN_TAC THEN REWRITE_TAC[NORM_CEXP] THEN
  SUBGOAL_THEN `ii * Cx x * Cx y = ii * Cx(x * y)` SUBST1_TAC THENL
   [REWRITE_TAC[CX_MUL] THEN SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[RE_MUL_II; IM_CX; REAL_NEG_0; REAL_EXP_0]);;

(* ------------------------------------------------------------------------- *)
(* Sinc L^2 domination: sin(a u)^2 / u^2 <= (2 a^2 + 2) inv(1+u^2) (u<>0);   *)
(* the pointwise bound making fourier h_ax square-integrable (dominator      *)
(* inv(1+u^2) is INV_SQ_REAL_INTEGRABLE).                                    *)
(* ------------------------------------------------------------------------- *)

let SINC_SQ_DOMINATION = prove
 (`!a u:real. ~(u = &0)
     ==> sin(a * u) pow 2 / u pow 2 <= (&2 * a pow 2 + &2) * inv(&1 + u pow
       2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < u pow 2` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_LT_LE; REAL_LE_POW_2] THEN
    CONV_TAC(RAND_CONV SYM_CONV) THEN REWRITE_TAC[REAL_POW_EQ_0] THEN
    ASM_REWRITE_TAC[ARITH]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &1 + u pow 2` ASSUME_TAC THENL
   [MP_TAC(SPEC `u:real` REAL_LE_POW_2) THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `sin(a * u) pow 2 <= &1` ASSUME_TAC THENL
   [MP_TAC(SPEC `a * u:real` SIN_BOUND) THEN DISCH_TAC THEN
    SUBGOAL_THEN `sin(a * u) pow 2 <= (&1) pow 2` MP_TAC THENL
     [ONCE_REWRITE_TAC[GSYM REAL_POW2_ABS] THEN
      REWRITE_TAC[GSYM REAL_LE_SQUARE_ABS] THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_POW_ONE]]; ALL_TAC] THEN
  SUBGOAL_THEN `sin(a * u) pow 2 <= a pow 2 * u pow 2` ASSUME_TAC THENL
   [MP_TAC(SPEC `a * u:real` REAL_ABS_SIN_BOUND_LE) THEN DISCH_TAC THEN
    SUBGOAL_THEN `sin(a * u) pow 2 <= (a * u) pow 2` MP_TAC THENL
     [ONCE_REWRITE_TAC[GSYM REAL_POW2_ABS] THEN
      REWRITE_TAC[GSYM REAL_LE_SQUARE_ABS] THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[REAL_POW_MUL]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `sin(a * u) pow 2 * (&1 + u pow 2) <= (&2 * a pow 2 + &2) * u pow 2`
   ASSUME_TAC THENL
   [ASM_CASES_TAC `u pow 2 <= &1` THENL
     [MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `(a pow 2 * u pow 2) * (&1 + u pow 2)` THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[] THEN
         ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_LE_TRANS THEN
        EXISTS_TAC `(a pow 2 * u pow 2) * &2` THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
           [MATCH_MP_TAC REAL_LE_MUL THEN REWRITE_TAC[REAL_LE_POW_2];
            ASM_REAL_ARITH_TAC];
          MP_TAC(SPEC `a:real` REAL_LE_POW_2) THEN
          MP_TAC(SPEC `u:real` REAL_LE_POW_2) THEN REAL_ARITH_TAC]];
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `&1 * (&1 + u pow 2)` THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[] THEN
         ASM_REAL_ARITH_TAC;
        SUBGOAL_THEN `&0 <= a pow 2 * u pow 2` MP_TAC THENL
         [MATCH_MP_TAC REAL_LE_MUL THEN
           REWRITE_TAC[REAL_LE_POW_2]; ALL_TAC] THEN
        MP_TAC(SPEC `u:real` REAL_LE_POW_2) THEN ASM_REAL_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `sin(a * u) pow 2 / u pow 2 =
    (sin(a * u) pow 2 * (&1 + u pow 2)) / (u pow 2 * (&1 + u pow 2))`
   SUBST1_TAC THENL
   [MP_TAC(ASSUME `&0 < u pow 2`) THEN MP_TAC(ASSUME `&0 < &1 + u pow 2`) THEN
    CONV_TAC REAL_FIELD; ALL_TAC] THEN
  SUBGOAL_THEN
   `(&2 * a pow 2 + &2) * inv(&1 + u pow 2) =
    ((&2 * a pow 2 + &2) * u pow 2) / (u pow 2 * (&1 + u pow 2))`
   SUBST1_TAC THENL
   [MP_TAC(ASSUME `&0 < u pow 2`) THEN MP_TAC(ASSUME `&0 < &1 + u pow 2`) THEN
    CONV_TAC REAL_FIELD; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_DIV2_EQ; REAL_LT_MUL]);;

let HAX_ABSINT = prove
 (`!a x:real.
     (\z:real^1. if abs(drop z) <= a then cexp(ii * Cx x * Cx(drop z)) else
       Cx(&0))
     absolutely_integrable_on (:real^1)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. if abs(drop z) <= a then cexp(ii * Cx x * Cx(drop z)) else
     Cx(&0)) =
    (\z:real^1. if z IN interval[lift(--a),lift a]
                then cexp((ii * Cx x) * Cx(drop z)) else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN
    REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP; COMPLEX_VEC_0;
      COMPLEX_MUL_ASSOC] THEN
    REWRITE_TAC[REAL_ARITH `--a <= drop z /\ drop z <= a <=> abs(drop z) <=
      a`];
    ALL_TAC] THEN
  REWRITE_TAC[ABSOLUTELY_INTEGRABLE_RESTRICT_UNIV] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_CONTINUOUS THEN
  REWRITE_TAC[CEXP_LINEAR_CONTINUOUS]);;

let HAX_L2 = prove
 (`!a x:real.
     (\z:real^1. if abs(drop z) <= a then cexp(ii * Cx x * Cx(drop z)) else
       Cx(&0))
     IN lspace (:real^1) (&2)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `!z:real^1. norm(if abs(drop z) <= a then cexp(ii * Cx x * Cx(drop z)) else
     Cx(&0))
               <= &1`
   ASSUME_TAC THENL
   [GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[NORM_CEXP_II_XY; REAL_LE_REFL; COMPLEX_NORM_CX; REAL_ABS_NUM;
      REAL_POS];
    ALL_TAC] THEN
  REWRITE_TAC[lspace; IN_ELIM_THM] THEN CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_MEASURABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      REWRITE_TAC[HAX_ABSINT];
    ALL_TAC] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC
   `\z:real^1. lift(norm(if abs(drop z) <= a then cexp(ii * Cx x * Cx(drop z))
                         else Cx(&0)))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_LIFT_RPOW THEN
    REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
    MATCH_MP_TAC MEASURABLE_ON_NORM THEN
    MATCH_MP_TAC INTEGRABLE_IMP_MEASURABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      REWRITE_TAC[HAX_ABSINT];
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN REWRITE_TAC[HAX_ABSINT];
    X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[NORM_LIFT; LIFT_DROP; RPOW_POW] THEN
    SUBGOAL_THEN
     `abs(norm(if abs(drop w) <= a then cexp(ii * Cx x * Cx(drop w)) else
       Cx(&0)) pow 2) =
      norm(if abs(drop w) <= a then cexp(ii * Cx x * Cx(drop w)) else Cx(&0))
        pow 2`
     SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC REAL_POW_LE THEN
      REWRITE_TAC[NORM_POS_LE]; ALL_TAC] THEN
    SUBGOAL_THEN
     `norm(if abs(drop w) <= a then cexp(ii * Cx x * Cx(drop w)) else Cx(&0))
       pow 2 =
      norm(if abs(drop w) <= a then cexp(ii * Cx x * Cx(drop w)) else Cx(&0)) *
      norm(if abs(drop w) <= a then cexp(ii * Cx x * Cx(drop w)) else Cx(&0))`
     SUBST1_TAC THENL [REWRITE_TAC[REAL_POW_2]; ALL_TAC] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[NORM_POS_LE]]);;

(* ------------------------------------------------------------------------- *)
(* Pointwise square-norm bound for the window transform: |fourier h_ax(t)|^2 *)
(* <= inv(2pi) 4 (2a^2+2) inv(1+(x-t)^2) for t <> x (CARLESON_HAX_FT +       *)
(* SINC_SQ_DOMINATION). The integrable dominator giving fourier h_ax in L^2. *)
(* ------------------------------------------------------------------------- *)
let HAX_FT_NORMSQ_BOUND = prove
 (`!a x t:real. &0 <= a /\ ~(x - t = &0)
     ==> norm(fourier (\y. if abs y <= a then cexp(ii * Cx x * Cx y) else
       Cx(&0)) t) pow 2
         <= inv(&2 * pi) * &4 * (&2 * a pow 2 + &2) * inv(&1 + (x - t) pow 2)`,
REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `norm(fourier (\y. if abs y <= a then cexp(ii * Cx x * Cx y) else Cx(&0)) t)
     pow 2 =
    inv(&2 * pi) * (&4 * (sin(a * (x - t)) pow 2 / (x - t) pow 2))`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`a:real`; `x:real`; `t:real`] CARLESON_HAX_FT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX; REAL_POW_MUL;
      REAL_POW2_ABS] THEN
    SUBGOAL_THEN `inv(sqrt(&2 * pi)) pow 2 = inv(&2 * pi)` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM REAL_POW_INV; REAL_POW_2; GSYM REAL_INV_MUL] THEN
      AP_TERM_TAC THEN MP_TAC(SPEC `&2 * pi` SQRT_POW_2) THEN
      SIMP_TAC[REAL_LE_MUL; REAL_POS; PI_POS_LE; REAL_LT_IMP_LE;
        REAL_POW_2] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC;
      AP_TERM_TAC THEN REWRITE_TAC[REAL_POW_DIV; REAL_POW_MUL] THEN
      REWRITE_TAC[REAL_ARITH `&2 pow 2 = &4`]];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < inv(&2 * pi)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_INV THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[REAL_ARITH `inv(&2*pi) * (&4 * bc) = (&4 * bc) * inv(&2*pi)`;
              REAL_ARITH `inv(&2*pi) * &4 * b * c = (&4 * (b * c)) *
                inv(&2*pi)`] THEN
  MATCH_MP_TAC REAL_LE_RMUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      MP_TAC(ISPECL [`a:real`; `x - t:real`] SINC_SQ_DOMINATION) THEN
      ASM_REWRITE_TAC[]];
    ASM_SIMP_TAC[REAL_LT_IMP_LE]]);;

(* ------------------------------------------------------------------------- *)
(* The inv(1+(x-t)^2) dominator (times a constant), integrable over the line *)
(* -- a translate of DOMINATOR_SQ_INTEGRABLE (INTEGRABLE_TRANSLATION).       *)
(* ------------------------------------------------------------------------- *)

let SINC_DOMINATOR_INTEGRABLE = prove
 (`!x C:real. (\z:real^1. lift(C * inv(&1 + (x - drop z) pow 2))) integrable_on
   (:real^1)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. lift(C * inv(&1 + (x - drop z) pow 2))) =
    (\z:real^1. (\w:real^1. lift((&2 * (C / &2)) * inv(&1 + drop w pow 2)))
                (--(lift x) + z))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN
    BETA_TAC THEN REWRITE_TAC[DROP_ADD; DROP_NEG; LIFT_DROP] THEN
      AP_TERM_TAC THEN
    SUBGOAL_THEN `&2 * C / &2 = C` SUBST1_TAC THENL
      [REAL_ARITH_TAC; ALL_TAC] THEN
    AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    MP_TAC(SPECL [`x:real`; `drop z`]
      (REAL_RING `!x dz:real. (--x + dz) pow 2 = (x - dz) pow 2`)) THEN
    REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[INTEGRABLE_TRANSLATION] THEN
  SUBGOAL_THEN
    `IMAGE (\z:real^1. --(lift x) + z) (:real^1) = (:real^1)` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_UNIV] THEN
    X_GEN_TAC `w:real^1` THEN EXISTS_TAC `lift x + w:real^1` THEN
      VECTOR_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[DOMINATOR_SQ_INTEGRABLE]);;

(* ------------------------------------------------------------------------- *)
(* fourier h_ax IN L^2: continuous (FOURIER_CONTINUOUS_ON) => measurable,    *)
(* and                                                                       *)
(* |fourier h_ax|^2 dominated a.e. by the integrable sinc dominator          *)
(* (HAX_FT_NORMSQ_BOUND off the single point t=x).                           *)
(* ------------------------------------------------------------------------- *)

let HAX_FT_L2 = prove
 (`!a x:real. &0 <= a
     ==> (\z:real^1. fourier (\y. if abs y <= a then cexp(ii * Cx x * Cx y)
       else Cx(&0))
                            (drop z))
         IN lspace (:real^1) (&2)`,
REPEAT STRIP_TAC THEN
  ABBREV_TAC `Fh = \z:real^1. fourier (\y. if abs y <= a then cexp(ii * Cx x *
    Cx y)
                                          else Cx(&0)) (drop z)` THEN
  SUBGOAL_THEN `(Fh:real^1->complex) continuous_on (:real^1)` ASSUME_TAC THENL
   [EXPAND_TAC "Fh" THEN MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN
    REWRITE_TAC[ETA_AX; HAX_ABSINT]; ALL_TAC] THEN
  SUBGOAL_THEN `(Fh:real^1->complex) measurable_on (:real^1)` ASSUME_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[lspace; IN_ELIM_THM] THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE_AE
    THEN
  EXISTS_TAC `\z:real^1. lift((inv(&2 * pi) * &4 * (&2 * a pow 2 + &2)) *
                              inv(&1 + (x - drop z) pow 2))` THEN
  EXISTS_TAC `{lift x}` THEN
  REWRITE_TAC[NEGLIGIBLE_SING] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_LIFT_RPOW THEN
     REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
    MATCH_MP_TAC MEASURABLE_ON_NORM THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SINC_DOMINATOR_INTEGRABLE];
    X_GEN_TAC `z:real^1` THEN REWRITE_TAC[IN_DIFF; IN_UNIV; IN_SING] THEN
    DISCH_TAC THEN REWRITE_TAC[NORM_LIFT; LIFT_DROP; RPOW_POW] THEN
    ABBREV_TAC `N = norm((Fh:real^1->complex) z)` THEN
    SUBGOAL_THEN `~(x - drop z = &0)` ASSUME_TAC THENL
     [REWRITE_TAC[REAL_SUB_0] THEN DISCH_TAC THEN
      UNDISCH_TAC `~(z:real^1 = lift x)` THEN REWRITE_TAC[] THEN
      REWRITE_TAC[GSYM LIFT_DROP] THEN
        ASM_REWRITE_TAC[LIFT_DROP; LIFT_EQ]; ALL_TAC] THEN
    REWRITE_TAC[real_abs] THEN COND_CASES_TAC THENL
     [EXPAND_TAC "N" THEN EXPAND_TAC "Fh" THEN
      MP_TAC(ISPECL [`a:real`; `x:real`; `drop z`] HAX_FT_NORMSQ_BOUND) THEN
      ASM_REWRITE_TAC[] THEN REWRITE_TAC[REAL_MUL_ASSOC];
      POP_ASSUM MP_TAC THEN MP_TAC(SPEC `N:real` REAL_LE_POW_2) THEN
      REAL_ARITH_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* fourier h_ax represents the Fourier transform of h_ax (h_ax is L^1, so    *)
(* this is just the multiplication formula 283O with a Schwartz test fn).    *)
(* ------------------------------------------------------------------------- *)

let HAX_REPS = prove
 (`!a x:real. !k. schwartz k
     ==> integral (:real^1)
           (\z. fourier (\y. if abs y <= a then cexp(ii * Cx x * Cx y) else
             Cx(&0))
                        (drop z) * k(drop z)) =
         integral (:real^1)
           (\z. (\y. if abs y <= a then cexp(ii * Cx x * Cx y) else Cx(&0))
             (drop z) *
                fourier k (drop z))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\y. if abs y <= a then cexp(ii * Cx x * Cx y) else Cx(&0)`;
     `k:real->complex`]
   FOURIER_283O) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[ETA_AX] THEN
      MP_TAC(ISPECL [`a:real`; `x:real`] HAX_ABSINT) THEN
      MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      REWRITE_TAC[FUN_EQ_THM];
      MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC]);;

(* ------------------------------------------------------------------------- *)
(* <g|h_ax> unfolds to the truncated integral INT_{[-a,a]} e^{-ixy} g(y) dy  *)
(* (cnj of the window puts a minus in the exponent).                         *)
(* ------------------------------------------------------------------------- *)

let LPRODUCT_G_HAX = prove
 (`!a x:real g:real^1->complex. &0 <= a
     ==> lproduct (:real^1) g
           (\z. if abs(drop z) <= a then cexp(ii * Cx x * Cx(drop z)) else
             Cx(&0)) =
         integral (:real^1)
           (\z. if abs(drop z) <= a then g z * cexp(--(ii * Cx x * Cx(drop z)))
                else Cx(&0))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lproduct] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN COND_CASES_TAC THEN
  REWRITE_TAC[CNJ_CX; COMPLEX_MUL_RZERO] THEN
  AP_TERM_TAC THEN REWRITE_TAC[CNJ_CEXP] THEN AP_TERM_TAC THEN
  REWRITE_TAC[CNJ_MUL; CNJ_II; CNJ_CX] THEN SIMPLE_COMPLEX_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* If p = q a.e. then <f|p> = INT f * cnj q: the second slot of the inner    *)
(* product depends only on the a.e.-class (INTEGRAL_SPIKE).                  *)
(* ------------------------------------------------------------------------- *)

let FOURIER_L2_UNIQUE = prove
 (`!g1 g2:real^1->complex.
     g1 IN lspace (:real^1) (&2) /\ g2 IN lspace (:real^1) (&2) /\
     (!h. schwartz h
          ==> integral (:real^1) (\z. g1 z * h(drop z)) =
              integral (:real^1) (\z. g2 z * h(drop z)))
     ==> negligible {x | ~(g1 x = g2 x)}`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `d = \x:real^1. (g1:real^1->complex) x - g2 x` THEN
  SUBGOAL_THEN `(d:real^1->complex) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [EXPAND_TAC "d" THEN MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_POS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!h. schwartz h
        ==> integral (:real^1) (\z. (d:real^1->complex) z * h(drop z)) =
          Cx(&0)`
   (LABEL_TAC "DZERO") THENL
   [X_GEN_TAC `h:real->complex` THEN DISCH_TAC THEN EXPAND_TAC "d" THEN
    SUBGOAL_THEN
     `(\z:real^1. ((g1:real^1->complex) z - g2 z) * h(drop z)) =
      (\z. g1 z * h(drop z) - g2 z * h(drop z))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN SIMPLE_COMPLEX_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
      `(\z:real^1. cnj(h(drop z))) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
     [MATCH_MP_TAC LSPACE_CNJ THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
      ASM_REWRITE_TAC[ETA_AX]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(\z:real^1. (g1:real^1->complex) z * h(drop z)) integrable_on (:real^1)
       /\
      (\z:real^1. (g2:real^1->complex) z * h(drop z)) integrable_on (:real^1)`
     STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN
      MP_TAC(ISPECL [`(:real^1)`; `g1:real^1->complex`;
        `\z:real^1. cnj(h(drop z))`]
        L2_CNJ_PRODUCT_INTEGRABLE) THEN
      MP_TAC(ISPECL [`(:real^1)`; `g2:real^1->complex`;
        `\z:real^1. cnj(h(drop z))`]
        L2_CNJ_PRODUCT_INTEGRABLE) THEN
      ASM_REWRITE_TAC[CNJ_CNJ];
      ASM_SIMP_TAC[INTEGRAL_SUB] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `h:real->complex`) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      REWRITE_TAC[COMPLEX_SUB_REFL]];
    ALL_TAC] THEN
  MP_TAC(ISPEC `\x:real^1. cnj((d:real^1->complex) x)` SCHWARTZ_SEQ) THEN
  ASM_SIMP_TAC[LSPACE_CNJ] THEN
  DISCH_THEN(X_CHOOSE_THEN `kn:num->real->complex` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
    `lproduct (:real^1) (d:real^1->complex) d = Cx(&0)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPEC `sequentially` LIM_UNIQUE) THEN
    EXISTS_TAC
     `\n. lproduct (:real^1) d (\z:real^1. cnj((kn:num->real->complex) n (drop
       z)))` THEN
    REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY] THEN CONJ_TAC THENL
     [MATCH_MP_TAC LPRODUCT_L2LIM_RSLOT THEN ASM_REWRITE_TAC[] THEN
      CONJ_TAC THENL
       [GEN_TAC THEN MATCH_MP_TAC LSPACE_CNJ THEN
        MATCH_MP_TAC SCHWARTZ_L2 THEN ASM_SIMP_TAC[ETA_AX];
        X_GEN_TAC `e:real` THEN DISCH_TAC THEN
        MP_TAC(SPEC `e:real` REAL_ARCH_INV) THEN ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `N:num` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `N:num` THEN X_GEN_TAC `n:num` THEN DISCH_TAC THEN
        SUBGOAL_THEN
         `lnorm (:real^1) (&2) (\x. cnj((kn:num->real->complex) n (drop x)) - d
           x) =
          lnorm (:real^1) (&2) (\x. cnj(d x) - kn n (drop x))`
         SUBST1_TAC THENL
         [REWRITE_TAC[lnorm] THEN
          AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
          REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
          AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
          GEN_REWRITE_TAC LAND_CONV [GSYM COMPLEX_NORM_CNJ] THEN
          REWRITE_TAC[CNJ_SUB; CNJ_CNJ] THEN REWRITE_TAC[NORM_SUB];
          ALL_TAC] THEN
        MATCH_MP_TAC REAL_LTE_TRANS THEN EXISTS_TAC `inv(&n + &1)` THEN
        ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_LE_TRANS THEN
        EXISTS_TAC `inv(&N)` THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_INV2 THEN CONJ_TAC THENL
           [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC;
            RULE_ASSUM_TAC(REWRITE_RULE[GE; GSYM REAL_OF_NUM_LE]) THEN
            ASM_REAL_ARITH_TAC];
          ASM_SIMP_TAC[REAL_LT_IMP_LE]]];
      SUBGOAL_THEN
       `!n. lproduct (:real^1) (d:real^1->complex)
              (\z. cnj((kn:num->real->complex) n (drop z))) = Cx(&0)`
       (fun th -> REWRITE_TAC[th; LIM_CONST]) THEN
      GEN_TAC THEN REWRITE_TAC[lproduct; CNJ_CNJ] THEN
      REMOVE_THEN "DZERO" MATCH_MP_TAC THEN ASM_SIMP_TAC[ETA_AX]];
    ALL_TAC] THEN
  SUBGOAL_THEN `lnorm (:real^1) (&2) (d:real^1->complex) = &0` MP_TAC THENL
   [SUBGOAL_THEN
     `(\x:real^1. lift(norm((d:real^1->complex) x) pow 2)) integrable_on
       (:real^1)`
     ASSUME_TAC THENL
     [MP_TAC(ISPECL [`(:real^1)`; `&2`;
       `d:real^1->complex`] LSPACE_IMP_INTEGRABLE) THEN
      ASM_REWRITE_TAC[RPOW_POW]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(lnorm (:real^1) (&2) (d:real^1->complex)) pow 2 = &0` MP_TAC THENL
     [MP_TAC(ISPECL [`d:real^1->complex`] LNORM2_SQ) THEN
       ASM_REWRITE_TAC[] THEN
      DISCH_THEN SUBST1_TAC THEN
      MP_TAC(ISPECL [`(:real^1)`; `d:real^1->complex`] LPRODUCT_SELF) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o AP_TERM `Re`) THEN
      REWRITE_TAC[RE_CX] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
        REWRITE_TAC[RE_CX];
      REWRITE_TAC[REAL_POW_EQ_0] THEN SIMP_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`(:real^1)`; `&2`; `d:real^1->complex`] LNORM_EQ_0) THEN
  ASM_REWRITE_TAC[REAL_ARITH `~(&2 = &0)`] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_UNIV] THEN
  X_GEN_TAC `x:real^1` THEN EXPAND_TAC "d" THEN
  REWRITE_TAC[COMPLEX_SUB_0; COMPLEX_VEC_0]);;

(* ------------------------------------------------------------------------- *)
(* The L^2 norm depends only on the a.e.-equivalence class.                  *)
(* ------------------------------------------------------------------------- *)

let LNORM_EQ_AE = prove
 (`!s p (f:real^1->complex) g.
     negligible {x | ~(f x = g x)} ==> lnorm s p f = lnorm s p g`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lnorm] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  MATCH_MP_TAC INTEGRAL_SPIKE THEN
  EXISTS_TAC `{x:real^1 | ~((f:real^1->complex) x = g x)}` THEN
  ASM_REWRITE_TAC[IN_DIFF; IN_ELIM_THM] THEN
  X_GEN_TAC `x:real^1` THEN STRIP_TAC THEN
  ASM_CASES_TAC `(f:real^1->complex) x = g x` THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* <w|w> = Cx(||w||_2^2) for w in L^2 (self inner product is the             *)
(* norm-square).                                                             *)
(* ------------------------------------------------------------------------- *)

let LPRODUCT_SELF_NORM = ISPEC `(:real^1)` LPRODUCT_SELF_LNORM;;

(* ------------------------------------------------------------------------- *)
(* Complex polarization identity for the L^2 inner product:                  *)
(*   4<u|v> = <u+v|u+v> - <u-v|u-v> + i<u+iv|u+iv> - i<u-iv|u-iv>.           *)
(* Pure pointwise complex algebra under the integral (integrands merged by   *)
(* INTEGRAL linearity, then COMPLEX_RING pointwise).                         *)
(* ------------------------------------------------------------------------- *)

let LPRODUCT_POLARIZE = prove
 (`!u v:real^1->complex.
     u IN lspace (:real^1) (&2) /\ v IN lspace (:real^1) (&2)
     ==> Cx(&4) * lproduct (:real^1) u v =
         lproduct (:real^1) (\x. u x + v x) (\x. u x + v x) -
         lproduct (:real^1) (\x. u x - v x) (\x. u x - v x) +
         ii * lproduct (:real^1) (\x. u x + ii * v x) (\x. u x + ii * v x) -
         ii * lproduct (:real^1) (\x. u x - ii * v x) (\x. u x - ii * v x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x:real^1. u x + v x) IN lspace (:real^1) (&2) /\
    (\x:real^1. u x - v x) IN lspace (:real^1) (&2) /\
    (\x:real^1. u x + ii * v x) IN lspace (:real^1) (&2) /\
    (\x:real^1. u x - ii * v x) IN lspace (:real^1) (&2)`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    TRY(MATCH_MP_TAC LSPACE_ADD) THEN TRY(MATCH_MP_TAC LSPACE_SUB) THEN
    ASM_REWRITE_TAC[REAL_POS] THEN
    MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[lproduct] THEN
  SUBGOAL_THEN
   `(\x. (u x + v x) * cnj(u x + v x)) integrable_on (:real^1) /\
    (\x. (u x - v x) * cnj(u x - v x)) integrable_on (:real^1) /\
    (\x. (u x + ii * v x) * cnj(u x + ii * v x)) integrable_on (:real^1) /\
    (\x. (u x - ii * v x) * cnj(u x - ii * v x)) integrable_on (:real^1) /\
    (\x:real^1. u x * cnj(v x)) integrable_on (:real^1)`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM INTEGRAL_COMPLEX_LMUL; GSYM INTEGRAL_SUB;
    GSYM INTEGRAL_ADD;
    INTEGRABLE_COMPLEX_LMUL; INTEGRABLE_SUB; INTEGRABLE_ADD] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[CNJ_ADD; CNJ_SUB; CNJ_MUL; CNJ_II] THEN CONV_TAC COMPLEX_RING);;

(* ------------------------------------------------------------------------- *)
(* A Fourier-transform representative preserves the L^2 norm: if chat        *)
(* represents the FT of c (both in L^2) then ||chat||_2 = ||c||_2.  From     *)
(* FOURIER_L2_REP (some g with ||g|| = ||c||) + FOURIER_L2_UNIQUE (chat = g  *)
(* a.e.) + LNORM_EQ_AE.                                                      *)
(* ------------------------------------------------------------------------- *)

let FOURIER_L2_REP_NORM = prove
 (`!c chat:real^1->complex.
     c IN lspace (:real^1) (&2) /\ chat IN lspace (:real^1) (&2) /\
     (!h. schwartz h
          ==> integral (:real^1) (\z. chat z * h(drop z)) =
              integral (:real^1) (\z. c z * fourier h (drop z)))
     ==> lnorm (:real^1) (&2) chat = lnorm (:real^1) (&2) c`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `c:real^1->complex` FOURIER_L2_REP) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:real^1->complex` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `lnorm (:real^1) (&2) (chat:real^1->complex) =
    lnorm (:real^1) (&2) (g:real^1->complex)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC LNORM_EQ_AE THEN
    MATCH_MP_TAC FOURIER_L2_UNIQUE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `h:real->complex` THEN DISCH_TAC THEN ASM_SIMP_TAC[];
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Fremlin 284Ob: bilinear Parseval on L^2.  If a, b in L^2 have Fourier     *)
(* transforms represented by ahat, bhat then <a|b> = <ahat|bhat>, i.e.       *)
(*   INT a * cnj b = INT ahat * cnj bhat.                                    *)
(* Proof (Fremlin's polarization): for all complex p, q the combination      *)
(* p a + q b has representative p ahat + q bhat (represents relation is      *)
(* linear), so <p a+q b | same> = <p ahat+q bhat | same> (both = Cx(norm^2)  *)
(* and the norms agree by FOURIER_L2_REP_NORM).  Expanding <a|b> and         *)
(* <ahat|bhat> by LPRODUCT_POLARIZE, the four self-products match termwise   *)
(* (p, q = 1, +-1, +-i), so 4<a|b> = 4<ahat|bhat>.                           *)
(* ------------------------------------------------------------------------- *)

let PARSEVAL_L2_BILINEAR = prove
 (`!a b ahat bhat:real^1->complex.
     a IN lspace (:real^1) (&2) /\ b IN lspace (:real^1) (&2) /\
     ahat IN lspace (:real^1) (&2) /\ bhat IN lspace (:real^1) (&2) /\
     (!h. schwartz h ==> integral (:real^1) (\z. ahat z * h(drop z)) =
                         integral (:real^1) (\z. a z * fourier h (drop z))) /\
     (!h. schwartz h ==> integral (:real^1) (\z. bhat z * h(drop z)) =
                         integral (:real^1) (\z. b z * fourier h (drop z)))
     ==> lproduct (:real^1) a b = lproduct (:real^1) ahat bhat`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!p q:complex.
       lproduct (:real^1) (\x. p * a x + q * b x) (\x. p * a x + q * b x) =
       lproduct (:real^1) (\x. p * ahat x + q * bhat x)
                          (\x. p * ahat x + q * bhat x)`
   (LABEL_TAC "SELF") THENL
   [REPEAT GEN_TAC THEN
    SUBGOAL_THEN
     `(\x:real^1. p * a x + q * b x) IN lspace (:real^1) (&2) /\
      (\x:real^1. p * ahat x + q * bhat x) IN lspace (:real^1) (&2)`
     STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC LSPACE_ADD THEN ASM_REWRITE_TAC[REAL_POS] THEN
      CONJ_TAC THEN MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_SIMP_TAC[LPRODUCT_SELF_NORM] THEN AP_TERM_TAC THEN AP_THM_TAC THEN
    AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC FOURIER_L2_REP_NORM THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `h:real->complex` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(\z:real^1. cnj(h(drop z))) IN lspace (:real^1) (&2) /\
                  (\z:real^1. cnj(fourier h(drop z))) IN lspace (:real^1) (&2)`
     STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC LSPACE_CNJ THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
      ASM_SIMP_TAC[SCHWARTZ_FOURIER; ETA_AX];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(\x:real^1. (p * ahat x + q * bhat x) * h(drop x)) =
      (\x. p * (ahat x * h(drop x)) + q * (bhat x * h(drop x)))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN SIMPLE_COMPLEX_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(\x:real^1. (p * a x + q * b x) * fourier h (drop x)) =
      (\x. p * (a x * fourier h(drop x)) + q * (b x * fourier h(drop x)))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN SIMPLE_COMPLEX_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(\x:real^1. ahat x * h(drop x)) integrable_on (:real^1) /\
      (\x:real^1. bhat x * h(drop x)) integrable_on (:real^1) /\
      (\x:real^1. a x * fourier h(drop x)) integrable_on (:real^1) /\
      (\x:real^1. b x * fourier h(drop x)) integrable_on (:real^1)`
     STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL [`(:real^1)`; `ahat:real^1->complex`;
         `\z:real^1. cnj(h(drop z))`]
          L2_CNJ_PRODUCT_INTEGRABLE) THEN ASM_REWRITE_TAC[CNJ_CNJ];
        MP_TAC(ISPECL [`(:real^1)`; `bhat:real^1->complex`;
          `\z:real^1. cnj(h(drop z))`]
          L2_CNJ_PRODUCT_INTEGRABLE) THEN ASM_REWRITE_TAC[CNJ_CNJ];
        MP_TAC(ISPECL [`(:real^1)`; `a:real^1->complex`;
          `\z:real^1. cnj(fourier h(drop z))`]
          L2_CNJ_PRODUCT_INTEGRABLE) THEN ASM_REWRITE_TAC[CNJ_CNJ];
        MP_TAC(ISPECL [`(:real^1)`; `b:real^1->complex`;
          `\z:real^1. cnj(fourier h(drop z))`]
          L2_CNJ_PRODUCT_INTEGRABLE) THEN ASM_REWRITE_TAC[CNJ_CNJ]];
      ALL_TAC] THEN
    ASM_SIMP_TAC[INTEGRAL_ADD; INTEGRABLE_COMPLEX_LMUL;
      INTEGRAL_COMPLEX_LMUL] THEN
    BINOP_TAC THEN AP_TERM_TAC THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `Cx(&4) * lproduct (:real^1) a b = Cx(&4) * lproduct (:real^1) ahat bhat`
   MP_TAC THENL
   [MP_TAC(ISPECL [`a:real^1->complex`;
     `b:real^1->complex`] LPRODUCT_POLARIZE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    MP_TAC(ISPECL [`ahat:real^1->complex`;
      `bhat:real^1->complex`] LPRODUCT_POLARIZE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    USE_THEN "SELF" (fun th ->
      MP_TAC(SPECL [`Cx(&1)`; `Cx(&1)`] th) THEN
      MP_TAC(SPECL [`Cx(&1)`; `--Cx(&1)`] th) THEN
      MP_TAC(SPECL [`Cx(&1)`; `ii`] th) THEN
      MP_TAC(SPECL [`Cx(&1)`; `--ii`] th)) THEN
    REWRITE_TAC[COMPLEX_MUL_LID; COMPLEX_MUL_LNEG] THEN
    REWRITE_TAC[GSYM complex_sub] THEN
    DISCH_THEN SUBST1_TAC THEN DISCH_THEN SUBST1_TAC THEN
    DISCH_THEN SUBST1_TAC THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC;
    MP_TAC(COMPLEX_RING `~(Cx(&4) = Cx(&0))`) THEN
    SIMP_TAC[COMPLEX_EQ_MUL_LCANCEL]]);;

(* Single-tile region-Parseval (Fremlin 2139-2142 per tile): the spatial     *)
(* tile integral int_R phi_sigma equals the frequency pairing lproduct       *)
(* phihat_sigma chi_R-hat, where g = chi_R-hat is the abstract L^2 rep       *)
(* (CARLESON_CHIHAT_REP). This is the per-tile heart of the 286O(b) spatial  *)
(* identity: it turns EACH int_R phi_sigma into a frequency integral against *)
(* chi_R-hat, ready for the sum-vs-integral interchange with the freq-side   *)
(* tile-sum CARLESON_PERK_LIMIT_RE.                                          *)
let CARLESON_PHISIG_REGION_PARSEVAL = prove
 (`!(s:int#int#int) (R:real^1->bool) g.
     measurable R /\
     g IN lspace (:real^1) (&2) /\
     (!h. schwartz h
          ==> integral (:real^1) (\z. g z * h(drop z)) =
              integral (:real^1) (\z. (if z IN R then Cx(&1) else Cx(&0)) *
                fourier h (drop z)))
     ==> integral R (\z. phi_sigma s carleson_phi (drop z)) =
         lproduct (:real^1) (\z. fourier (phi_sigma s carleson_phi) (drop z))
           g`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[CARLESON_PHISIG_REGION_LPRODUCT] THEN
  MATCH_MP_TAC PARSEVAL_L2_BILINEAR THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[PHISIG_IN_LSPACE2];
    MATCH_MP_TAC CARLESON_CHI_L2_UNIV THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[PHISIG_FOURIER_L2];
    ASM_REWRITE_TAC[];
    CONV_TAC(DEPTH_CONV BETA_CONV) THEN X_GEN_TAC `h:real->complex` THEN
      DISCH_TAC THEN
    MP_TAC(ISPECL [`phi_sigma s carleson_phi`;
      `h:real->complex`] FOURIER_283O) THEN
    ANTS_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC SCHWARTZ_ABSINT THEN
      ONCE_REWRITE_TAC[ETA_AX] THEN
        ASM_REWRITE_TAC[PHISIG_CARLESON_SCHWARTZ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    CONV_TAC(DEPTH_CONV BETA_CONV) THEN ASM_REWRITE_TAC[]]);;

(* 286O(b) finite-sum aggregate (Fremlin 2136-2143): summing the per-tile    *)
(* region- Parseval over a FINITE tile family P converts the spatial         *)
(* tile-sum integral sum_{s in P} <h|phi_s> int_R phi_s into ONE frequency   *)
(* pairing of the summed transform against chi_R-hat: lproduct (sum_{s in P} *)
(* <h|phi_s> phihat_s) chi_R-hat. LPRODUCT_LSUM (pull the finite sum out of  *)
(* lproduct's 1st slot) + LPRODUCT_LMUL (pull each <h|phi_s> scalar) + the   *)
(* per-tile CARLESON_PHISIG_REGION_PARSEVAL. Integrability side-conditions   *)
(* from L2_CNJ_PRODUCT_INTEGRABLE (phihat_s, g both L2).                     *)
let CARLESON_TILESUM_REGION_PARSEVAL = prove
 (`!(h:real->complex) (P:(int#int#int)->bool) (R:real^1->bool) g.
     FINITE P /\ measurable R /\
     g IN lspace (:real^1) (&2) /\
     (!hh. schwartz hh
          ==> integral (:real^1) (\z. g z * hh(drop z)) =
              integral (:real^1) (\z. (if z IN R then Cx(&1) else Cx(&0)) *
                fourier hh (drop z)))
     ==> vsum P (\s. carleson_ip h s * integral R (\z. phi_sigma s carleson_phi
       (drop z))) =
         lproduct (:real^1)
           (\z. vsum P (\s. carleson_ip h s * fourier (phi_sigma s
             carleson_phi) (drop z))) g`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `lproduct (:real^1)
      (\z. vsum P (\s. carleson_ip h s * fourier (phi_sigma s carleson_phi)
        (drop z))) g =
    vsum P (\s. carleson_ip h s *
                lproduct (:real^1) (\z. fourier (phi_sigma s carleson_phi)
                  (drop z)) g)`
   SUBST1_TAC THENL
   [W(MP_TAC o PART_MATCH (lhs o rand) LPRODUCT_LSUM o lhs o snd) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
      MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC LSPACE_COMPLEX_LMUL THEN REWRITE_TAC[PHISIG_FOURIER_L2];
      DISCH_THEN SUBST1_TAC] THEN
    MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN
    MATCH_MP_TAC LPRODUCT_LMUL THEN
    MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN
    REWRITE_TAC[PHISIG_FOURIER_L2] THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC VSUM_EQ THEN X_GEN_TAC `s:int#int#int` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN AP_TERM_TAC THEN
    MATCH_MP_TAC CARLESON_PHISIG_REGION_PARSEVAL THEN ASM_REWRITE_TAC[]]);;

(* Bridge from an L^2-norm "---> 0" limit to the epsilon-delta hypothesis    *)
(* form of                                                                   *)
(* LPRODUCT_L2LIM.  Since lnorm >= 0, abs(lnorm - 0) < e is just lnorm < e.  *)
let REALLIM_TO_L2LIM_HYP = prove
 (`!(gn:num->real^1->complex) (g:real^1->complex).
     ((\N. lnorm (:real^1) (&2) (\x. gn N x - g x)) ---> &0) sequentially
     ==> (!e. &0 < e ==> ?N. !n. n >= N
              ==> lnorm (:real^1) (&2) (\x. gn n x - g x) < e)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN
  DISCH_TAC THEN X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `N:num` THEN
  DISCH_TAC THEN X_GEN_TAC `n:num` THEN REWRITE_TAC[GE] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN ASM_REWRITE_TAC[] THEN
    REAL_ARITH_TAC);;

(* The b-ii limit function 2pi hhat psi_k is in L^2 (extracted from the DCT  *)
(* that proves CARLESON_PERK_L2LIM: LSPACE_DOMINATED_CONVERGENCE's first     *)
(* conclusion).                                                              *)
let CARLESON_PERK_LIMFN_L2 = prove
 (`!(h:real->complex) k nJ.
     schwartz h
     ==> (\z. Cx(&2 * pi) * fourier h (drop z) *
              Cx(Re(fourier carleson_phi
                (&2 zpow (--k) * (drop z - tile_ymid(k,&0,nJ)))) pow 2))
         IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `h:real->complex` CARLESON_TILESUM_DOMINATED) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`k:int`; `nJ:int`]) THEN
  DISCH_THEN(X_CHOOSE_THEN `B:real` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL
   [`\N z. vsum {nI:int | abs nI <= &N}
             (\nI. carleson_ip h (k,nI,nJ) *
                   fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop z))`;
    `\z:real^1. Cx(&2 * pi) * fourier h (drop z) *
                Cx(Re(fourier carleson_phi
                  (&2 zpow (--k) * (drop z - tile_ymid(k,&0,nJ)))) pow 2)`;
    `\z:real^1. Cx(&2 * pi * B) *
                fourier carleson_phi ((drop z - tile_ymid(k,&0,nJ)) / &2 zpow
                  k)`;
    `(:real^1)`; `&2`; `{}:real^1->bool`]
   LSPACE_DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; DIFF_EMPTY; IN_UNIV] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REAL_ARITH_TAC;
      REWRITE_TAC[CARLESON_TILESUM_FOURIER_L2];
      REWRITE_TAC[CARLESON_DOMINATOR_L2];
      ASM_REWRITE_TAC[];
      GEN_TAC THEN MATCH_MP_TAC CARLESON_PERK_LIMIT_ALL THEN
        ASM_REWRITE_TAC[]];
    REWRITE_TAC[ETA_AX] THEN SIMP_TAC[]]);;

(* The scaled bump phihat(2^{-k}(y-c)) is Schwartz (affine reparametrisation *)
(* of the Schwartz phihat, scale 2^{-k} nonzero).                            *)
let SCALED_PHIHAT_SCHWARTZ = prove
 (`!k (c:real). schwartz (\y. fourier carleson_phi (&2 zpow (--k) * (y - c)))`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `(\y. fourier carleson_phi (&2 zpow (--k) * (y - c))) =
                (\y. fourier carleson_phi (--(&2 zpow (--k) * c) + &2 zpow
                  (--k) * y))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(BETA_RULE(ISPECL [`fourier carleson_phi`; `&2 zpow (--k)`;
    `--(&2 zpow (--k) * c)`]
    SCHWARTZ_AFFINE)) THEN
  DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_FOURIER THEN REWRITE_TAC[CARLESON_PHI_SCHWARTZ];
    MATCH_MP_TAC REAL_LT_IMP_NZ THEN MATCH_MP_TAC REAL_ZPOW_LT THEN
      REAL_ARITH_TAC]);;

(* The scaled bump vanishes off |y - c| <= 2^k/5 (phihat support             *)
(* [-1/5,1/5]).                                                              *)
let SCALED_PHIHAT_SUPPORT = prove
 (`!k (c:real) y. &2 zpow k / &5 < abs(y - c)
                  ==> fourier carleson_phi (&2 zpow (--k) * (y - c)) = Cx(&0)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC CARLESON_PHI_FHAT_SUPPORT THEN
  SUBGOAL_THEN `&0 < &2 zpow k` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&2 zpow (--k) * (y - c) = (y - c) / &2 zpow k` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ZPOW_NEG] THEN UNDISCH_TAC `&0 < &2 zpow k` THEN
     CONV_TAC REAL_FIELD;
    ALL_TAC] THEN
  REWRITE_TAC[REAL_ABS_DIV] THEN
  SUBGOAL_THEN `abs(&2 zpow k) = &2 zpow k` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LT_RDIV_EQ] THEN
  UNDISCH_TAC `&2 zpow k / &5 < abs(y - c)` THEN
  ASM_SIMP_TAC[REAL_LT_LDIV_EQ] THEN REAL_ARITH_TAC);;

(* The b-ii limit function m_k = 2pi hhat psi_k,                             *)
(* psi_k(y)=Re(phihat(2^{-k}(y-yy)))^2,                                      *)
(* is SCHWARTZ. Rewrite Cx(Re(phihat)^2) = phihat*phihat                     *)
(* (CARLESON_PHIHAT_SQ_RE), so                                               *)
(* m_k = Cx(2pi)*(hhat*(phihat_scaled*phihat_scaled)): a constant times a    *)
(* Schwartz                                                                  *)
(* (hhat, 284C) product with a compactly-supported Schwartz square, all      *)
(* closed by                                                                 *)
(* SCHWARTZ_CMUL/SCHWARTZ_CSUPP_MUL. This is stronger than                   *)
(* CARLESON_PERK_LIMFN_L2                                                    *)
(* (Schwartz => absint => usable in FOURIER_283O for the R1 region           *)
(* rep-step).                                                                *)
let CARLESON_PERK_LIMFN_SCHWARTZ = prove
 (`!(h:real->complex) k nJ. schwartz h ==>
     schwartz (\y. Cx(&2 * pi) * fourier h y *
                   Cx(Re(fourier carleson_phi (&2 zpow (--k) * (y -
                     tile_ymid(k,&0,nJ)))) pow 2))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\y. Cx(&2 * pi) * fourier h y *
         Cx(Re(fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ))))
           pow 2)) =
    (\y. Cx(&2 * pi) *
         (fourier h y *
          (fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ))) *
           fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ))))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV) [GSYM
      CARLESON_PHIHAT_SQ_RE] THEN
    SPEC_TAC(`fourier carleson_phi (&2 zpow (--k) * (x -
      tile_ymid(k,&0,nJ)))`,`C:complex`) THEN
    SPEC_TAC(`fourier (h:real->complex) x`,`B:complex`) THEN
    SPEC_TAC(`Cx(&2 * pi)`,`A:complex`) THEN
    REPEAT GEN_TAC THEN CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  MP_TAC(BETA_RULE(ISPECL
   [`\y. fourier (h:real->complex) y *
         (fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ))) *
          fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ))))`;
    `Cx(&2 * pi)`] SCHWARTZ_CMUL)) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
   [`fourier (h:real->complex)`;
    `\y. fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ))) *
         fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ)))`;
    `&2 zpow k / &5 + abs(tile_ymid(k,&0,nJ))`] SCHWARTZ_CSUPP_MUL)) THEN
  DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `&0 < &2 zpow k` MP_TAC THENL
     [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
       REAL_ARITH_TAC;
    MATCH_MP_TAC SCHWARTZ_FOURIER THEN ASM_REWRITE_TAC[];
    MP_TAC(BETA_RULE(ISPECL
     [`\y. fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ)))`;
      `\y. fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ)))`;
      `&2 zpow k / &5 + abs(tile_ymid(k,&0,nJ))`] SCHWARTZ_CSUPP_MUL)) THEN
    DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
     [SUBGOAL_THEN `&0 < &2 zpow k` MP_TAC THENL
       [MATCH_MP_TAC REAL_ZPOW_LT THEN REAL_ARITH_TAC; ALL_TAC] THEN
         REAL_ARITH_TAC;
      REWRITE_TAC[SCALED_PHIHAT_SCHWARTZ];
      REWRITE_TAC[SCALED_PHIHAT_SCHWARTZ];
      X_GEN_TAC `y:real` THEN DISCH_TAC THEN
        MATCH_MP_TAC SCALED_PHIHAT_SUPPORT THEN
      ASM_REAL_ARITH_TAC];
    X_GEN_TAC `y:real` THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ))) =
       Cx(&0)`
     (fun th -> REWRITE_TAC[th; COMPLEX_MUL_LZERO]) THEN
    MATCH_MP_TAC SCALED_PHIHAT_SUPPORT THEN ASM_REAL_ARITH_TAC]);;

(* R2a: the b-ii limit function WITHOUT the 2pi factor, hhat(y)              *)
(* Re(phihat(...))^2, is also Schwartz (= inv(2pi) times                     *)
(* CARLESON_PERK_LIMFN_SCHWARTZ, SCHWARTZ_CMUL).                             *)
let CARLESON_PERK_LIMFN0_SCHWARTZ = prove
 (`!(h:real->complex) k nJ. schwartz h ==>
     schwartz (\y. fourier h y *
                   Cx(Re(fourier carleson_phi (&2 zpow (--k) * (y -
                     tile_ymid(k,&0,nJ)))) pow 2))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `k:int`;
    `nJ:int`] CARLESON_PERK_LIMFN_SCHWARTZ) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `Cx(inv(&2 * pi))` o MATCH_MP SCHWARTZ_CMUL) THEN
  MATCH_MP_TAC EQ_IMP THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
  GEN_TAC THEN
  SUBGOAL_THEN `Cx(inv(&2 * pi)) * Cx(&2 * pi) = Cx(&1)` MP_TAC THENL
   [REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
    MATCH_MP_TAC REAL_MUL_LINV THEN MP_TAC PI_POS THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  CONV_TAC COMPLEX_RING);;

(* R2a: pull the Cx(2pi) scalar out of the CARLESON_PERK_286OB limit         *)
(* function's                                                                *)
(* inverse transform. fourier(2pi hhat psi_k)(--x) = 2pi fourier(hhat        *)
(* psi_k)(--x).                                                              *)
(* FOURIER_LMUL (integrability from SCHWARTZ_MOD_ABSINT on the no-2pi        *)
(* Schwartz fn                                                               *)
(* CARLESON_PERK_LIMFN0_SCHWARTZ). This exposes the CARLESON_PERK_286OB      *)
(* limit as                                                                  *)
(* 2pi times the (hhat psi_k)check window -- matching carleson_w's 2pi (hhat *)
(* theta_z)                                                                  *)
(* check form (carleson_w h z x = Cx(2pi) fourier(hhat*Cx theta_z)(--x)) at  *)
(* a single                                                                  *)
(* scale, the entry point for the R2 scale-sum.                              *)
let INTEGRAL_REGION_LPRODUCT = prove
 (`!(f:real^1->complex) (R:real^1->bool).
     integral R f = lproduct (:real^1) f (\x. if x IN R then Cx(&1) else
       Cx(&0))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[lproduct] THEN
  GEN_REWRITE_TAC LAND_CONV [GSYM INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN COND_CASES_TAC THEN
  REWRITE_TAC[CNJ_CX; COMPLEX_MUL_RID; COMPLEX_MUL_RZERO; COMPLEX_VEC_0]);;

(* The inverse transform (m)check(x)=fourier m(--x) of a Schwartz m          *)
(* REPRESENTS m as an L^2 Fourier representative: int m*hh = int             *)
(* (m)check*fourier hh for schwartz hh. Via FOURIER_283O on (m)check (a      *)
(* reflected transform, Schwartz) plus the inversion fourier((m)check) = m   *)
(* (PHI_IS_FOURIER, m Schwartz).                                             *)
let CARLESON_CHECK_REPS = prove
 (`!(m:real->complex) hh. schwartz m /\ schwartz hh
     ==> integral (:real^1) (\z. m(drop z) * hh(drop z)) =
         integral (:real^1) (\z. fourier m (--drop z) * fourier hh (drop z))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\x. fourier (m:real->complex) (--x)`;
    `hh:real->complex`] FOURIER_283O) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPEC `\u. fourier (m:real->complex) (--u)` SCHWARTZ_ABSINT) THEN
      ANTS_TAC THENL
       [MATCH_MP_TAC SCHWARTZ_REFLECT THEN REWRITE_TAC[ETA_AX] THEN
        MATCH_MP_TAC SCHWARTZ_FOURIER THEN ASM_REWRITE_TAC[]; REWRITE_TAC[]];
      MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `!w. fourier (\x. fourier (m:real->complex) (--x)) w = m w`
   (fun th -> REWRITE_TAC[th; FOURIER_REFLECT]) THENL
   [GEN_TAC THEN ASM_SIMP_TAC[PHI_IS_FOURIER]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[]);;

(* R1 (rep-step of 286O(b)): for Schwartz m and gg = chi_R-hat rep,          *)
(*   int_R (m)check = lproduct(m, gg).                                       *)
(* int_R (m)check = lproduct((m)check, chi_R) [INTEGRAL_REGION_LPRODUCT] and *)
(* then                                                                      *)
(* PARSEVAL_L2_BILINEAR (284Ob) with a=(m)check (L^2 + reps m via            *)
(* CARLESON_CHECK_REPS),                                                     *)
(* b=chi_R, ahat=m, bhat=gg. Applied with m = 2pi hhat psi_k, this converts  *)
(* the                                                                       *)
(* CARLESON_PERK_SPATIAL_LIMIT limit lproduct(2pi hhat psi_k, chiR-hat) into *)
(* the                                                                       *)
(* spatial 2pi int_R (hhat psi_k)check of Fremlin 286O-b-ii.                 *)
let CARLESON_PERK_WINDOW_REGION = prove
 (`!(m:real->complex) (R:real^1->bool) gg.
     schwartz m /\ measurable R /\ gg IN lspace (:real^1) (&2) /\
     (!hh. schwartz hh
          ==> integral (:real^1) (\z. gg z * hh(drop z)) =
              integral (:real^1) (\z. (if z IN R then Cx(&1) else Cx(&0)) *
                fourier hh (drop z)))
     ==> integral R (\z. fourier m (--drop z)) =
         lproduct (:real^1) (\z. m (drop z)) gg`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[INTEGRAL_REGION_LPRODUCT] THEN
  MATCH_MP_TAC PARSEVAL_L2_BILINEAR THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPEC `\u. fourier (m:real->complex) (--u)` SCHWARTZ_L2) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_REFLECT THEN REWRITE_TAC[ETA_AX] THEN
      MATCH_MP_TAC SCHWARTZ_FOURIER THEN ASM_REWRITE_TAC[]; REWRITE_TAC[]];
    MATCH_MP_TAC CARLESON_CHI_L2_UNIV THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC SCHWARTZ_L2 THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    CONV_TAC(DEPTH_CONV BETA_CONV) THEN X_GEN_TAC `hh:real->complex` THEN
      DISCH_TAC THEN
    MP_TAC(ISPECL [`m:real->complex`;
      `hh:real->complex`] CARLESON_CHECK_REPS) THEN
    ASM_REWRITE_TAC[];
    CONV_TAC(DEPTH_CONV BETA_CONV) THEN ASM_REWRITE_TAC[]]);;

(* The finite spatial=frequency Parseval bridge                              *)
(* (CARLESON_TILESUM_REGION_PARSEVAL) reindexed by the integer nI over the   *)
(* per-k tile family {(k,nI,nJ) : |nI|<=N}. The map nI |-> (k,nI,nJ) is      *)
(* injective, so VSUM_IMAGE reindexes both the spatial sum and the frequency *)
(* sum inside lproduct.                                                      *)
let CARLESON_PERK_REGION_PARSEVAL = prove
 (`!(h:real->complex) (k:int) (nJ:int) (N:num) (R:real^1->bool) gg.
     measurable R /\ gg IN lspace (:real^1) (&2) /\
     (!hh. schwartz hh
          ==> integral (:real^1) (\z. gg z * hh(drop z)) =
              integral (:real^1) (\z. (if z IN R then Cx(&1) else Cx(&0)) *
                fourier hh (drop z)))
     ==> vsum {nI:int | abs nI <= &N}
              (\nI. carleson_ip h (k,nI,nJ) *
                    integral R (\z. phi_sigma (k,nI,nJ) carleson_phi (drop z)))
                      =
         lproduct (:real^1)
           (\z. vsum {nI:int | abs nI <= &N}
                  (\nI. carleson_ip h (k,nI,nJ) *
                        fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop z)))
                          gg`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!(FF:int#int#int->real^2).
      vsum (IMAGE (\nI:int. ((k:int),nI,(nJ:int))) {nI:int | abs nI <= &N}) FF
        =
      vsum {nI:int | abs nI <= &N} (\nI. FF(k,nI,nJ))`
   ASSUME_TAC THENL
   [GEN_TAC THEN
    MP_TAC(ISPECL [`\nI:int. ((k:int),nI,(nJ:int))`; `FF:int#int#int->real^2`;
      `{nI:int | abs nI <= &N}`] VSUM_IMAGE) THEN
    REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN ANTS_TAC THENL
     [MAP_EVERY X_GEN_TAC [`a:int`; `b:int`] THEN REWRITE_TAC[PAIR_EQ] THEN
       SIMP_TAC[];
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[o_DEF]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real->complex`;
    `IMAGE (\nI:int. ((k:int),nI,(nJ:int))) {nI:int | abs nI <= &(N:num)}`;
    `R:real^1->bool`;
      `gg:real^1->complex`] CARLESON_TILESUM_REGION_PARSEVAL) THEN
  ASM_SIMP_TAC[FINITE_IMAGE; CFOURIER_INDEX_FINITE]);;

(* 286O(b) per-k SPATIAL limit: the finite tile-sum spatial region integrals *)
(* over abs nI <= N of <h|(k,nI,nJ)> int_R phi_(k,nI,nJ) converge (as        *)
(* N->inf) to                                                                *)
(* lproduct(2pi hhat psi_k, chiR-hat). Rewrite each finite sum by the per-k  *)
(* Parseval                                                                  *)
(* bridge (= lproduct(tile_sum_freq_N, gg)) and pass the L^2-limit           *)
(* CARLESON_PERK_L2LIM                                                       *)
(* through the inner-product's first slot (LPRODUCT_L2LIM). This is the      *)
(* spatial side                                                              *)
(* of Fremlin 286O(b).                                                       *)
let CARLESON_PERK_SPATIAL_LIMIT = prove
 (`!(h:real->complex) (k:int) (nJ:int) (R:real^1->bool) gg.
     schwartz h /\ measurable R /\ gg IN lspace (:real^1) (&2) /\
     (!hh. schwartz hh
          ==> integral (:real^1) (\z. gg z * hh(drop z)) =
              integral (:real^1) (\z. (if z IN R then Cx(&1) else Cx(&0)) *
                fourier hh (drop z)))
     ==> ((\N. vsum {nI:int | abs nI <= &N}
                (\nI. carleson_ip h (k,nI,nJ) *
                      integral R (\z. phi_sigma (k,nI,nJ) carleson_phi (drop
                        z))))
          --> lproduct (:real^1)
                (\z. Cx(&2 * pi) * fourier h (drop z) *
                     Cx(Re(fourier carleson_phi
                       (&2 zpow (--k) * (drop z - tile_ymid(k,&0,nJ)))) pow 2))
                         gg)
         sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!N. vsum {nI:int | abs nI <= &N}
          (\nI. carleson_ip h (k,nI,nJ) *
                integral R (\z. phi_sigma (k,nI,nJ) carleson_phi (drop z))) =
        lproduct (:real^1)
          (\z. vsum {nI:int | abs nI <= &N}
                 (\nI. carleson_ip h (k,nI,nJ) *
                       fourier (phi_sigma (k,nI,nJ) carleson_phi) (drop z)))
                         gg`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN MATCH_MP_TAC CARLESON_PERK_REGION_PARSEVAL THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC LPRODUCT_L2LIM THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[CARLESON_TILESUM_FOURIER_L2];
    MATCH_MP_TAC CARLESON_PERK_LIMFN_L2 THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`h:real->complex`; `k:int`;
      `nJ:int`] CARLESON_PERK_L2LIM) THEN
    ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o MATCH_MP REALLIM_TO_L2LIM_HYP)]);;

(* Fremlin 286O(b-ii), per-k, in LIMIT form: the finite tile-sum spatial     *)
(* region                                                                    *)
(* integrals converge to 2pi int_R (hhat psi_k)check. Combine                *)
(* CARLESON_PERK_SPATIAL_                                                    *)
(* LIMIT (the limit is lproduct(2pi hhat psi_k, chiR-hat)) with              *)
(* CARLESON_PERK_WINDOW_                                                     *)
(* REGION (R1: that lproduct = int_R of the inverse transform of 2pi hhat    *)
(* psi_k, since                                                              *)
(* 2pi hhat psi_k is Schwartz by CARLESON_PERK_LIMFN_SCHWARTZ). This is      *)
(* exactly the                                                               *)
(* spatial side 2pi int_F (hhat psi_k)check = sum_{sigma in R_k} <h|phi_s>   *)
(* int_F phi_s                                                               *)
(* of Fremlin's 286O(b-ii), read as an N->inf limit over the R_k tile index. *)
let CARLESON_PERK_286OB = prove
 (`!(h:real->complex) (k:int) (nJ:int) (R:real^1->bool) gg.
     schwartz h /\ measurable R /\ gg IN lspace (:real^1) (&2) /\
     (!hh. schwartz hh
          ==> integral (:real^1) (\z. gg z * hh(drop z)) =
              integral (:real^1) (\z. (if z IN R then Cx(&1) else Cx(&0)) *
                fourier hh (drop z)))
     ==> ((\N. vsum {nI:int | abs nI <= &N}
                (\nI. carleson_ip h (k,nI,nJ) *
                      integral R (\z. phi_sigma (k,nI,nJ) carleson_phi (drop
                        z))))
          --> integral R (\z. fourier (\y. Cx(&2 * pi) * fourier h y *
                     Cx(Re(fourier carleson_phi (&2 zpow (--k) * (y -
                       tile_ymid(k,&0,nJ)))) pow 2))
                     (--drop z)))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\y. Cx(&2 * pi) * fourier (h:real->complex) y *
                  Cx(Re(fourier carleson_phi (&2 zpow (--k) * (y -
                    tile_ymid(k,&0,nJ)))) pow 2)`;
                 `R:real^1->bool`;
                   `gg:real^1->complex`] CARLESON_PERK_WINDOW_REGION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC CARLESON_PERK_LIMFN_SCHWARTZ THEN
     ASM_REWRITE_TAC[];
    DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  MATCH_MP_TAC CARLESON_PERK_SPATIAL_LIMIT THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* R2d (Fremlin 286O-b-iv): the k-sum interchange.  With CARLESON_PSI_SUM_   *)
(* LIMIT giving theta_z = sum_k psi_k POINTWISE (286O-a-i), the remaining    *)
(* content is int_F (hhat theta_z)check = sum_k int_F (hhat psi_k)check via  *)
(* dominated convergence.  These bricks set up the per-K finite partial sum: *)
(*  - DYHO_OUTSIDE_MID_DIST + CARLESON_PSI_BARE: since the phihat^2 bump has *)
(* support half-width 2^k/5 STRICTLY inside the dyadic cell Jl (half-width   *)
(*    2^k/4 > 2^k/5), the cell-cut in carleson_psi is REDUNDANT -- when z    *)
(*    witnesses at scale k (z in Jr(k,0,nJ0)), carleson_psi z k equals the   *)
(*    bare bump Re(phihat(2^{-k}(y - ymid)))^2 for ALL y.                    *)
(*  - CARLESON_PSI_SUMMAND_SCHWARTZ(_ALL): hence \y. hhat y * Cx(psi_k y) is *)
(*    Schwartz (bare-bump case = CARLESON_PERK_LIMFN0_SCHWARTZ; no-witness   *)
(*    case = the zero function, SCHWARTZ_ZERO).                              *)
(* - CX_VSUM + CARLESON_PSI_FOURIER_KSUM: fourier of the K-partial-sum       *)
(* window                                                                    *)
(*    = the vsum of per-k windows (FOURIER_VSUM over Schwartz summands).     *)
(* ========================================================================= *)

(* Cx is additive over finite sums (Cx(sum) = vsum(Cx . -)).                 *)
let CX_VSUM = prove
 (`!s (f:A->real). FINITE s ==> Cx(sum s f) = vsum s (\i. Cx(f i))`,
  GEN_TAC THEN GEN_TAC THEN SPEC_TAC(`s:A->bool`,`s:A->bool`) THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN
  SIMP_TAC[SUM_CLAUSES; VSUM_CLAUSES; CX_ADD] THEN
  REWRITE_TAC[GSYM COMPLEX_VEC_0; CX_INJ]);;

(* A point outside a dyadic cell is at least a half-width from its midpoint. *)
let DYHO_OUTSIDE_MID_DIST = prove
 (`!b n y. ~(y IN dyho b n) ==> &2 zpow b / &2 <= abs(y - dyho_mid b n)`,
  REWRITE_TAC[dyho; dyho_mid; IN_ELIM_THM; DE_MORGAN_THM; REAL_NOT_LE;
    REAL_NOT_LT] THEN
  REPEAT GEN_TAC THEN MP_TAC(ISPECL [`&2:real`; `b:int`] REAL_ZPOW_LT) THEN
  REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN DISCH_TAC THEN
  ABBREV_TAC `p = &2 zpow b` THEN ABBREV_TAC `m = real_of_int n` THEN
  ASM_REAL_ARITH_TAC);;

(* KEYSTONE: when z witnesses a scale-k right-half tile, the sharp cell-cut  *)
(* in carleson_psi is redundant -- psi equals the bare phihat^2 bump         *)
(* everywhere, because the bump (support 2^k/5) sits inside the cell Jl      *)
(* (half-width 2^k/4).                                                       *)
let CARLESON_PSI_BARE = prove
 (`!(k:int) nJ0 z y.
     z IN tile_Jr(k,&0,nJ0)
     ==> carleson_psi z k y =
         Re(fourier carleson_phi (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ0))))
           pow 2`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_psi] THEN COND_CASES_TAC THENL
   [SUBGOAL_THEN
     `(@nJ:int. z IN tile_Jr(k,&0,nJ) /\ y IN tile_Jl(k,&0,nJ)) = nJ0`
     (fun th -> REWRITE_TAC[th]) THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `nJw:int` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
      `z IN tile_Jr(k,&0,(@nJ:int. z IN tile_Jr(k,&0,nJ) /\ y IN
      tile_Jl(k,&0,nJ))) /\
                  y IN tile_Jl(k,&0,(@nJ:int. z IN tile_Jr(k,&0,nJ) /\ y IN
                    tile_Jl(k,&0,nJ)))`
     STRIP_ASSUME_TAC THENL
     [CONV_TAC SELECT_CONV THEN EXISTS_TAC `nJw:int` THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`k:int`; `&0:int`;
      `(@nJ:int. z IN tile_Jr(k,&0,nJ) /\ y IN tile_Jl(k,&0,nJ))`;
                   `&0:int`; `nJ0:int`;
                     `z:real`] CARLESON_THETA_SINGLE_NJ) THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `~(y IN tile_Jl(k,&0,nJ0))` ASSUME_TAC THENL
     [DISCH_TAC THEN
       UNDISCH_TAC `~(?nJ:int. z IN tile_Jr(k,&0,nJ) /\
        y IN tile_Jl(k,&0,nJ))` THEN
      REWRITE_TAC[] THEN EXISTS_TAC `nJ0:int` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[tile_Jl]) THEN REWRITE_TAC[tile_ymid] THEN
    MP_TAC(ISPECL [`k - &1:int`; `&2 * nJ0:int`;
      `y:real`] DYHO_OUTSIDE_MID_DIST) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `fourier carleson_phi (&2 zpow (--k) * (y - dyho_mid (k - &1)(&2 * nJ0)))
      = Cx(&0)`
     (fun th -> REWRITE_TAC[th; RE_CX] THEN REAL_ARITH_TAC) THEN
    MATCH_MP_TAC SCALED_PHIHAT_SUPPORT THEN
    SUBGOAL_THEN
      `&2 zpow k / &5 < &2 zpow (k - &1) / &2` (fun th -> ASM_MESON_TAC[th;
      REAL_LTE_TRANS]) THEN
    SUBGOAL_THEN `&2 zpow (k - &1) = &2 zpow k / &2` SUBST1_TAC THENL
     [SUBGOAL_THEN `k - &1:int = k + (-- &1)` SUBST1_TAC THENL
       [INT_ARITH_TAC; ALL_TAC] THEN
      SIMP_TAC[REAL_ZPOW_ADD; REAL_ARITH `~(&2 = &0)`] THEN
      REWRITE_TAC[REAL_ZPOW_NEG; REAL_ZPOW_1] THEN
        REAL_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`&2:real`; `k:int`] REAL_ZPOW_LT) THEN
    REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN REAL_ARITH_TAC]);;

(* When z witnesses at scale k, the summand hhat * Cx(psi_k) is Schwartz.    *)
let CARLESON_PSI_SUMMAND_SCHWARTZ = prove
 (`!(h:real->complex) k nJ0 z.
     schwartz h /\ z IN tile_Jr(k,&0,nJ0)
     ==> schwartz (\y. fourier h y * Cx(carleson_psi z k y))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(\y. fourier h y * Cx(carleson_psi z k y)) =
                (\y. fourier h y * Cx(Re(fourier carleson_phi
                       (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ0)))) pow 2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    MATCH_MP_TAC CARLESON_PSI_BARE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC CARLESON_PERK_LIMFN0_SCHWARTZ THEN ASM_REWRITE_TAC[]);;

(* For every scale k, the summand hhat * Cx(psi_k) is Schwartz (bare-bump    *)
(* when z witnesses a right-half at scale k; the zero function otherwise).   *)
let CARLESON_PSI_SUMMAND_SCHWARTZ_ALL = prove
 (`!(h:real->complex) k z.
     schwartz h
     ==> schwartz (\y. fourier h y * Cx(carleson_psi z k y))`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `?nJ:int. z IN tile_Jr(k,&0,nJ)` THENL
   [FIRST_X_ASSUM(X_CHOOSE_TAC `nJ0:int`) THEN
    MATCH_MP_TAC CARLESON_PSI_SUMMAND_SCHWARTZ THEN ASM_MESON_TAC[];
    SUBGOAL_THEN
      `(\y. fourier h y * Cx(carleson_psi z k y)) = (\y:real. Cx(&0))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      SUBGOAL_THEN `carleson_psi z k x = &0` SUBST1_TAC THENL
       [MATCH_MP_TAC CARLESON_PSI_ZERO THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[COMPLEX_MUL_RZERO];
      REWRITE_TAC[SCHWARTZ_ZERO]]]);;

(* The Fourier transform of the K-partial-sum window equals the vsum of the  *)
(* per-scale windows (finite fourier-linearity over Schwartz summands).      *)
let CARLESON_PSI_FOURIER_KSUM = prove
 (`!(h:real->complex) z K w.
     schwartz h
     ==> fourier (\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k.
       carleson_psi z k y))) w =
         vsum {k:int | abs k <= &K} (\k. fourier (\y. fourier h y *
           Cx(carleson_psi z k y)) w)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k. carleson_psi z k y)))
     =
    (\y. vsum {k:int | abs k <= &K} (\k. fourier h y * Cx(carleson_psi z k
      y)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    SIMP_TAC[CX_VSUM; CFOURIER_INDEX_FINITE] THEN
    SIMP_TAC[GSYM VSUM_COMPLEX_LMUL; CFOURIER_INDEX_FINITE]; ALL_TAC] THEN
  MP_TAC(ISPECL [`{k:int | abs k <= &K}`;
                 `\k y. fourier (h:real->complex) y * Cx(carleson_psi z k y)`;
                 `w:real`] FOURIER_VSUM) THEN
  REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN
  ANTS_TAC THENL
   [X_GEN_TAC `k:int` THEN DISCH_TAC THEN
    MATCH_MP_TAC CARLESON_PSI_SUMMAND_SCHWARTZ_ALL THEN ASM_REWRITE_TAC[];
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* Every finite scale-partial-sum of the bumps lies in [0,1] (each is 0 or   *)
(* theta_z <= 1 by CARLESON_PSI_PARTIAL + CARLESON_THETA_BOUNDS). This is    *)
(* the                                                                       *)
(* |value| <= 1 fact the K-window uniform bound and the DCT dominators need. *)
let CARLESON_PSI_PARTIAL_BOUNDS = prove
 (`!z y K. &0 <= sum {k:int | abs k <= &K} (\k. carleson_psi z k y) /\
           sum {k:int | abs k <= &K} (\k. carleson_psi z k y) <= &1`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`z:real`; `y:real`] CARLESON_THETA_BOUNDS) THEN
  MP_TAC(ISPECL [`z:real`; `y:real`;
    `{k:int | abs k <= &K}`] CARLESON_PSI_PARTIAL) THEN
  REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC);;

(* The K-partial-sum window integrand \y. hhat y * Cx(sum_{abs k<=K} psi_k   *)
(* y) is Schwartz -- it is a FINITE vsum of the Schwartz per-scale summands  *)
(* (CARLESON_ PSI_SUMMAND_SCHWARTZ_ALL), via SCHWARTZ_VSUM.                  *)
let CARLESON_KWINDOW_INTEGRAND_SCHWARTZ = prove
 (`!(h:real->complex) z K.
     schwartz h
     ==> schwartz (\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k.
       carleson_psi z k y)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k. carleson_psi z k y)))
     =
    (\y. vsum {k:int | abs k <= &K} (\k. fourier h y * Cx(carleson_psi z k
      y)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    SIMP_TAC[CX_VSUM; CFOURIER_INDEX_FINITE] THEN
    SIMP_TAC[GSYM VSUM_COMPLEX_LMUL; CFOURIER_INDEX_FINITE]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\k y. fourier (h:real->complex) y * Cx(carleson_psi z k y)`;
                 `{k:int | abs k <= &K}`] SCHWARTZ_VSUM) THEN
  REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN BETA_TAC THEN
  DISCH_THEN MATCH_MP_TAC THEN
  X_GEN_TAC `k:int` THEN DISCH_TAC THEN
  MATCH_MP_TAC CARLESON_PSI_SUMMAND_SCHWARTZ_ALL THEN ASM_REWRITE_TAC[]);;

(* Generic tile-window bound: for any h and any g with |g| <= 1 whose        *)
(* modulated                                                                 *)
(* integrand hhat * Cx g is absolutely integrable, the window 2pi (hhat      *)
(* g)check                                                                   *)
(* is bounded by sqrt(2pi) int|hhat|, UNIFORMLY in x. (Fremlin's window      *)
(* estimate;                                                                 *)
(* both the theta-window and the K-partial-sum window are instances. Only    *)
(* |g|<=1                                                                    *)
(* and integrability of the modulated integrand are used -- via              *)
(* FOURIER_BOUND +                                                           *)
(* int|hhat g| <= int|hhat|.)                                                *)
let CARLESON_WINDOW_BOUND_GENERIC = prove
 (`!(h:real->complex) g x.
     schwartz h /\ (!y. abs(g y) <= &1) /\
     (\z. fourier h (drop z) * Cx(g(drop z))) absolutely_integrable_on
       (:real^1)
     ==> norm(Cx(&2 * pi) * fourier (\y. fourier h y * Cx(g y)) (--x))
         <= sqrt(&2 * pi) *
            drop(integral (:real^1) (\y. lift(norm(fourier (h:real->complex)
              (drop y)))))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `abs(&2 * pi) = &2 * pi` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`\y. fourier (h:real->complex) y * Cx(g y)`;
    `--x:real`] FOURIER_BOUND) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MP_TAC(ISPECL [`( * ):complex->complex->complex`;
                     `\u:real^1. cexp(--(ii * Cx(--x) * Cx(drop u)))`;
                     `\u:real^1. fourier (h:real->complex) (drop u) * Cx(g(drop
                       u))`;
                     `(:real^1)`]
                       ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT) THEN
      REWRITE_TAC[BILINEAR_COMPLEX_MUL] THEN BETA_TAC THEN DISCH_THEN
        MATCH_MP_TAC THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
        SUBGOAL_THEN
         `(\u:real^1. cexp(--(ii * Cx(--x) * Cx(drop u)))) =
          cexp o (\u. --((ii * Cx(--x)) * Cx(drop u)))`
         SUBST1_TAC THENL [REWRITE_TAC[o_DEF; COMPLEX_MUL_ASSOC]; ALL_TAC] THEN
        MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
          REWRITE_TAC[CONTINUOUS_ON_CEXP] THEN
        MATCH_MP_TAC CONTINUOUS_ON_NEG THEN
          MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN
        REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
          MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN
        REWRITE_TAC[CONTINUOUS_ON_ID];
        REWRITE_TAC[bounded; FORALL_IN_IMAGE] THEN EXISTS_TAC `&1` THEN
        X_GEN_TAC `u:real^1` THEN REWRITE_TAC[IN_UNIV] THEN
        SUBGOAL_THEN
          `--(ii * Cx(--x) * Cx(drop u)) =
           ii * Cx(--(--x * drop u))` SUBST1_TAC THENL
         [REWRITE_TAC[CX_NEG; CX_MUL] THEN
           SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[NORM_CEXP_II; REAL_LE_REFL];
        ASM_REWRITE_TAC[]];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `&0 < sqrt(&2 * pi)` ASSUME_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `(&2 * pi) * (&1 / sqrt(&2 * pi)) = sqrt(&2 * pi)` ASSUME_TAC THENL
   [MP_TAC(SPEC `&2 * pi` SQRT_POW_2) THEN
    ANTS_TAC THENL [MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
    POP_ASSUM MP_TAC THEN CONV_TAC REAL_FIELD; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `(&2 * pi) *
              (&1 / sqrt(&2 * pi) *
               drop(integral (:real^1)
                 (\y. lift(norm(fourier (h:real->complex) (drop y) * Cx(g(drop
                   y)))))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MP_TAC PI_POS THEN REAL_ARITH_TAC; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_ASSOC] THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC INTEGRAL_DROP_LE THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
    MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
      ASM_REWRITE_TAC[];
    X_GEN_TAC `y:real^1` THEN REWRITE_TAC[IN_UNIV; LIFT_DROP] THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
    ASM_REWRITE_TAC[]]);;

(* R2d-1: the K-partial-sum window is bounded by sqrt(2pi) int|hhat|         *)
(* uniformly                                                                 *)
(* in z, K, x -- an instance of CARLESON_WINDOW_BOUND_GENERIC at g = the     *)
(* partial                                                                   *)
(* sum (|g|<=1 by CARLESON_PSI_PARTIAL_BOUNDS, integrand Schwartz by         *)
(* CARLESON_                                                                 *)
(* KWINDOW_INTEGRAND_SCHWARTZ). This is the constant x-dominator for the     *)
(* DCT.                                                                      *)
let CARLESON_KWINDOW_UNIFORM_BOUND = prove
 (`!(h:real->complex) z K x.
     schwartz h
     ==> norm(Cx(&2 * pi) *
              fourier (\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k.
                carleson_psi z k y))) (--x))
         <= sqrt(&2 * pi) *
            drop(integral (:real^1) (\y. lift(norm(fourier (h:real->complex)
              (drop y)))))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CARLESON_WINDOW_BOUND_GENERIC THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [GEN_TAC THEN
     MP_TAC(ISPECL [`z:real`; `y:real`; `K:num`]
       CARLESON_PSI_PARTIAL_BOUNDS) THEN
    ABBREV_TAC `S = sum {k:int | abs k <= &K} (\k. carleson_psi z k y)` THEN
      REAL_ARITH_TAC;
    MP_TAC(ISPECL [`h:real->complex`; `z:real`;
      `K:num`] CARLESON_KWINDOW_INTEGRAND_SCHWARTZ) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o MATCH_MP SCHWARTZ_ABSINT) THEN
    REWRITE_TAC[]]);;

(* ========================================================================= *)
(* R2d STEP A (Fremlin 286O-b-iv, the inner dominated-convergence pass): the *)
(* K-partial-sum window converges POINTWISE IN x to the theta window.  This  *)
(* is DOMINATED_CONVERGENCE on the y-integral inside fourier, with dominator *)
(* norm(hhat) (|cexp|=1, |sum_K psi|<=1), then multiply through by the       *)
(* fourier                                                                   *)
(* constant.                                                                 *)
(* ========================================================================= *)

(* A cexp-modulated Schwartz integrand is integrable on the whole line       *)
(* (bounded measurable cexp times an absolutely integrable Schwartz          *)
(* function).                                                                *)
let SCHWARTZ_MODULATED_INTEGRABLE = prove
 (`!(f:real->complex) x. schwartz f
     ==> (\u. cexp(--(ii * Cx(--x) * Cx(drop u))) * f(drop u)) integrable_on
       (:real^1)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC SCHWARTZ_MOD_INT THEN ASM_REWRITE_TAC[]);;

(* The raw fourier-integral of the K-partial-sum window converges to that of *)
(* the theta window (DOMINATED_CONVERGENCE in y; dominator norm(hhat),       *)
(* ptwise limit from CARLESON_PSI_SUM_LIMIT, |sum_K psi|<=1 by               *)
(* PARTIAL_BOUNDS).                                                          *)
let CARLESON_KWINDOW_INTEGRAL_LIMIT = prove
 (`!(h:real->complex) z x.
     schwartz h
     ==> ((\K. integral (:real^1)
                (\u. cexp(--(ii * Cx(--x) * Cx(drop u))) *
                     (fourier h (drop u) * Cx(sum {k:int | abs k <= &K} (\k.
                       carleson_psi z k (drop u))))))
          --> integral (:real^1)
                (\u. cexp(--(ii * Cx(--x) * Cx(drop u))) *
                     (fourier h (drop u) * Cx(carleson_theta z (drop u)))))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\K u. cexp(--(ii * Cx(--x) * Cx(drop u))) *
           (fourier (h:real->complex) (drop u) * Cx(sum {k:int | abs k <= &K}
             (\k. carleson_psi z k (drop u))))`;
    `\u. cexp(--(ii * Cx(--x) * Cx(drop u))) *
         (fourier (h:real->complex) (drop u) * Cx(carleson_theta z (drop u)))`;
    `\u:real^1. lift(norm(fourier (h:real->complex) (drop u)))`;
    `(:real^1)`] DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [X_GEN_TAC `N:num` THEN
      MP_TAC(ISPECL [`\y. fourier (h:real->complex) y * Cx(sum {k:int | abs k
        <= &N} (\k. carleson_psi z k y))`;
                     `x:real`] SCHWARTZ_MODULATED_INTEGRABLE) THEN
      REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      MATCH_MP_TAC CARLESON_KWINDOW_INTEGRAND_SCHWARTZ THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
        ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`N:num`; `w:real^1`] THEN DISCH_TAC THEN
      REWRITE_TAC[LIFT_DROP; COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
      SUBGOAL_THEN `norm(cexp(--(ii * Cx(--x) * Cx(drop(w:real^1))))) = &1`
       (fun th -> REWRITE_TAC[th]) THENL
       [SUBGOAL_THEN
         `--(ii * Cx(--x) * Cx(drop(w:real^1))) = ii * Cx(--(--x * drop w))`
         SUBST1_TAC THENL
         [REWRITE_TAC[CX_NEG; CX_MUL] THEN
           SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[NORM_CEXP_II]; ALL_TAC] THEN
      REWRITE_TAC[REAL_MUL_LID] THEN
      GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
      MP_TAC(ISPECL [`z:real`; `drop(w:real^1)`;
        `N:num`] CARLESON_PSI_PARTIAL_BOUNDS) THEN
      ABBREV_TAC `S = sum {k:int | abs k <= &N} (\k. carleson_psi z k
        (drop(w:real^1)))` THEN
      REAL_ARITH_TAC;
      X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
      REPEAT(MATCH_MP_TAC LIM_COMPLEX_LMUL) THEN
      MP_TAC(ISPECL [`z:real`; `drop(w:real^1)`] CARLESON_PSI_SUM_LIMIT) THEN
      REWRITE_TAC[REALLIM_COMPLEX; o_DEF]];
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]);;

(* Abstract fourier-value limit: if the raw modulated integrals converge, so *)
(* do                                                                        *)
(* the fourier values (fourier = Cx(1/sqrt(2pi)) * that integral).           *)
(* Abstracting                                                               *)
(* over the window family ff/gg keeps any inner fourier folded.              *)
let FOURIER_VALUE_LIM = prove
 (`!(ff:num->real->complex) gg x.
     ((\K. integral (:real^1) (\u. cexp(--(ii * Cx(--x) * Cx(drop u))) * ff K
       (drop u)))
      --> integral (:real^1) (\u. cexp(--(ii * Cx(--x) * Cx(drop u))) * gg(drop
        u))) sequentially
     ==> ((\K. fourier (ff K) (--x)) --> fourier gg (--x)) sequentially`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[fourier] THEN
  MATCH_MP_TAC LIM_COMPLEX_LMUL THEN ASM_REWRITE_TAC[]);;

(* R2d STEP A [KEY]: the K-partial-sum window fourier value converges        *)
(* pointwise in x to the theta window fourier value.                         *)
let CARLESON_KWINDOW_FOURIER_LIMIT = prove
 (`!(h:real->complex) z x.
     schwartz h
     ==> ((\K. fourier (\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k.
       carleson_psi z k y))) (--x))
          --> fourier (\y. fourier h y * Cx(carleson_theta z y)) (--x))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
   [`\K y. fourier (h:real->complex) y * Cx(sum {k:int | abs k <= &K} (\k.
     carleson_psi z k y))`;
    `\y. fourier (h:real->complex) y * Cx(carleson_theta z y)`;
    `x:real`] FOURIER_VALUE_LIM)) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  ASM_SIMP_TAC[CARLESON_KWINDOW_INTEGRAL_LIMIT]);;

(* R2d STEP B prerequisites: the K-partial-sum complex window is continuous  *)
(* in x (fourier of the L^1 K-window integrand) and absolutely integrable on *)
(* any measurable region (continuous + uniformly bounded on a finite-measure *)
(* set). These supply the DCT integrability/measurability hypotheses for the *)
(* outer x-integral pass.                                                    *)
let CARLESON_KWINDOW_CONTINUOUS = prove
 (`!(h:real->complex) z K. schwartz h
     ==> (\x:real^1. Cx(&2 * pi) *
                     fourier (\y. fourier h y * Cx(sum {k:int | abs k <= &K}
                       (\k. carleson_psi z k y))) (--drop x))
         continuous_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_LMUL THEN
  SUBGOAL_THEN
   `(\x:real^1. fourier (\y. fourier (h:real->complex) y * Cx(sum {k:int | abs
     k <= &K} (\k. carleson_psi z k y))) (--drop x)) =
    (\x:real^1. fourier (\y. fourier (h:real->complex) y * Cx(sum {k:int | abs
      k <= &K} (\k. carleson_psi z k y))) (drop x)) o (\x. --x)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; DROP_NEG]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_NEG THEN REWRITE_TAC[CONTINUOUS_ON_ID];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    REWRITE_TAC[SUBSET_UNIV] THEN
    MP_TAC(ISPEC `\y. fourier (h:real->complex) y * Cx(sum {k:int | abs k <=
      &K} (\k. carleson_psi z k y))` FOURIER_CONTINUOUS_ON) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[] THEN MATCH_MP_TAC SCHWARTZ_ABSINT THEN
      MATCH_MP_TAC CARLESON_KWINDOW_INTEGRAND_SCHWARTZ THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[]]]);;

let CARLESON_KWINDOW_ABSINT = prove
 (`!(h:real->complex) z K R.
     schwartz h /\ real_measurable R
     ==> (\x:real^1. Cx(&2 * pi) *
              fourier (\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k.
                carleson_psi z k y))) (--drop x))
         absolutely_integrable_on (IMAGE lift R)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC `\x:real^1. lift(sqrt(&2 * pi) *
                   drop(integral (:real^1) (\y. lift(norm(fourier
                     (h:real->complex) (drop y))))))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_MEASURABLE_SUBSET THEN
     EXISTS_TAC `(:real^1)` THEN
    REWRITE_TAC[SUBSET_UNIV] THEN CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
      MATCH_MP_TAC CARLESON_KWINDOW_CONTINUOUS THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE]];
    REWRITE_TAC[INTEGRABLE_ON_CONST] THEN DISJ2_TAC THEN
    ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE];
    X_GEN_TAC `w:real^1` THEN REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:real` STRIP_ASSUME_TAC) THEN
    REWRITE_TAC[LIFT_DROP] THEN
    MP_TAC(ISPECL [`h:real->complex`; `z:real`; `K:num`;
      `drop(w:real^1)`] CARLESON_KWINDOW_UNIFORM_BOUND) THEN
    ASM_REWRITE_TAC[]]);;

(* R2d STEP B [KEY, the outer dominated-convergence pass]: over any          *)
(* measurable                                                                *)
(* region R, the K-partial-sum window integral converges to the theta window *)
(* (= carleson_w) integral.  DOMINATED_CONVERGENCE over IMAGE lift R (finite *)
(* measure): ptwise-in-x conv = STEP A (CARLESON_KWINDOW_FOURIER_LIMIT)      *)
(* times                                                                     *)
(* Cx(2pi); constant x-dominator sqrt(2pi) int|hhat|                         *)
(* (CARLESON_KWINDOW_UNIFORM_                                                *)
(* BOUND); each K-window absint on R (CARLESON_KWINDOW_ABSINT).              *)
let CARLESON_W_REGION_INTEGRAL_LIMIT = prove
 (`!(h:real->complex) z R.
     schwartz h /\ real_measurable R
     ==> ((\K. integral (IMAGE lift R)
                (\x. Cx(&2 * pi) *
                     fourier (\y. fourier h y * Cx(sum {k:int | abs k <= &K}
                       (\k. carleson_psi z k y))) (--drop x)))
          --> integral (IMAGE lift R) (\x. carleson_w h z (drop x)))
         sequentially`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_w] THEN
  MP_TAC(ISPECL
   [`\K x:real^1. Cx(&2 * pi) *
           fourier (\y. fourier (h:real->complex) y * Cx(sum {k:int | abs k <=
             &K} (\k. carleson_psi z k y))) (--drop x)`;
    `\x:real^1. Cx(&2 * pi) * fourier (\y. fourier (h:real->complex) y *
      Cx(carleson_theta z y)) (--drop x)`;
    `\x:real^1. lift(sqrt(&2 * pi) * drop(integral (:real^1) (\y.
      lift(norm(fourier (h:real->complex) (drop y))))))`;
    `IMAGE lift R`] DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [X_GEN_TAC `N:num` THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MP_TAC(ISPECL [`h:real->complex`; `z:real`; `N:num`;
        `R:real->bool`] CARLESON_KWINDOW_ABSINT) THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[INTEGRABLE_ON_CONST] THEN DISJ2_TAC THEN
      ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE];
      MAP_EVERY X_GEN_TAC [`N:num`; `w:real^1`] THEN DISCH_TAC THEN
      REWRITE_TAC[LIFT_DROP] THEN
      MATCH_MP_TAC CARLESON_KWINDOW_UNIFORM_BOUND THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
      MATCH_MP_TAC LIM_COMPLEX_LMUL THEN
      MATCH_MP_TAC CARLESON_KWINDOW_FOURIER_LIMIT THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]);;

(* ========================================================================= *)
(* R2d STEP C + assembly (Fremlin 286O-b-iv complete): finite integral-      *)
(* linearity moves int_R inside the finite k-sum, then combine with STEP B.  *)
(* ========================================================================= *)

(* Each per-scale window is continuous in x (fourier of the Schwartz per-k   *)
(* integrand) and integrable on any measurable region (continuous + bounded  *)
(* via |carleson_psi z k|<=1, WINDOW_BOUND_GENERIC; 2pi>1 transfers the      *)
(* Cx(2pi) window bound to the bare window).                                 *)
let CARLESON_PERKWINDOW_CONTINUOUS = prove
 (`!(h:real->complex) z k. schwartz h
     ==> (\x:real^1. fourier (\y. fourier h y * Cx(carleson_psi z k y)) (--drop
       x))
         continuous_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x:real^1. fourier (\y. fourier (h:real->complex) y * Cx(carleson_psi z k
     y)) (--drop x)) =
    (\x:real^1. fourier (\y. fourier (h:real->complex) y * Cx(carleson_psi z k
      y)) (drop x)) o (\x. --x)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM; DROP_NEG]; ALL_TAC] THEN
  MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_ON_NEG THEN REWRITE_TAC[CONTINUOUS_ON_ID];
    MATCH_MP_TAC CONTINUOUS_ON_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    REWRITE_TAC[SUBSET_UNIV] THEN
    MP_TAC(ISPEC `\y. fourier (h:real->complex) y * Cx(carleson_psi z k y)`
      FOURIER_CONTINUOUS_ON) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[] THEN MATCH_MP_TAC SCHWARTZ_ABSINT THEN
      MATCH_MP_TAC CARLESON_PSI_SUMMAND_SCHWARTZ_ALL THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[]]]);;

let CARLESON_PSI_ABS_LE_1 = prove
 (`!z k y. abs(carleson_psi z k y) <= &1`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`z:real`; `y:real`] CARLESON_THETA_BOUNDS) THEN
  MP_TAC(ISPECL [`z:real`; `k:int`; `y:real`] CARLESON_PSI_CASES) THEN
  REAL_ARITH_TAC);;

let CARLESON_PERKWINDOW_INTEGRABLE = prove
 (`!(h:real->complex) z k R.
     schwartz h /\ real_measurable R
     ==> (\x:real^1. fourier (\y. fourier h y * Cx(carleson_psi z k y)) (--drop
       x))
         integrable_on (IMAGE lift R)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC `\x:real^1. lift(sqrt(&2 * pi) *
                   drop(integral (:real^1) (\y. lift(norm(fourier
                     (h:real->complex) (drop y))))))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_MEASURABLE_SUBSET THEN
     EXISTS_TAC `(:real^1)` THEN
    REWRITE_TAC[SUBSET_UNIV] THEN CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
      MATCH_MP_TAC CARLESON_PERKWINDOW_CONTINUOUS THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE]];
    REWRITE_TAC[INTEGRABLE_ON_CONST] THEN DISJ2_TAC THEN
    ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE];
    X_GEN_TAC `w:real^1` THEN REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:real` STRIP_ASSUME_TAC) THEN
    REWRITE_TAC[LIFT_DROP] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `norm(Cx(&2 * pi) * fourier (\y. fourier (h:real->complex) y *
      Cx(carleson_psi z k y)) (--drop w))` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
      GEN_REWRITE_TAC LAND_CONV [GSYM REAL_MUL_LID] THEN
      MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
      MP_TAC PI_APPROX_32 THEN REAL_ARITH_TAC;
      MP_TAC(ISPECL [`h:real->complex`; `\y. carleson_psi z k y`;
        `drop(w:real^1)`] CARLESON_WINDOW_BOUND_GENERIC) THEN
      REWRITE_TAC[ETA_AX] THEN DISCH_THEN MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[CARLESON_PSI_ABS_LE_1] THEN
      MP_TAC(ISPECL [`h:real->complex`; `k:int`;
        `z:real`] CARLESON_PSI_SUMMAND_SCHWARTZ_ALL) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o MATCH_MP SCHWARTZ_ABSINT) THEN
        REWRITE_TAC[]]]);;

(* STEP C: int_R of the K-partial-sum window = Cx(2pi) times the finite      *)
(* k-sum of per-scale window integrals (CARLESON_PSI_FOURIER_KSUM inside +   *)
(* INTEGRAL_VSUM + INTEGRAL_COMPLEX_LMUL; each per-k window integrable on    *)
(* R).                                                                       *)
let CARLESON_W_REGION_KSUM_EQ = prove
 (`!(h:real->complex) z K R.
     schwartz h /\ real_measurable R
     ==> integral (IMAGE lift R)
           (\x. Cx(&2 * pi) *
                fourier (\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k.
                  carleson_psi z k y))) (--drop x)) =
         Cx(&2 * pi) *
         vsum {k:int | abs k <= &K}
           (\k. integral (IMAGE lift R)
                  (\x. fourier (\y. fourier h y * Cx(carleson_psi z k y))
                    (--drop x)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!x:real^1. fourier (\y. fourier (h:real->complex) y * Cx(sum {k:int | abs k
     <= &K} (\k. carleson_psi z k y))) (--drop x) =
               vsum {k:int | abs k <= &K} (\k. fourier (\y. fourier h y *
                 Cx(carleson_psi z k y)) (--drop x))`
   ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC CARLESON_PSI_FOURIER_KSUM THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\k x:real^1. fourier (\y. fourier (h:real->complex) y * Cx(carleson_psi z
     k y)) (--drop x)`;
    `IMAGE lift R`; `{k:int | abs k <= &K}`] INTEGRAL_VSUM) THEN
  REWRITE_TAC[CFOURIER_INDEX_FINITE] THEN BETA_TAC THEN
  ANTS_TAC THENL
   [X_GEN_TAC `k:int` THEN DISCH_TAC THEN
    MATCH_MP_TAC CARLESON_PERKWINDOW_INTEGRABLE THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(fun th -> REWRITE_TAC[SYM th]) THEN
  ASM_SIMP_TAC[INTEGRAL_COMPLEX_LMUL; INTEGRABLE_VSUM; CFOURIER_INDEX_FINITE;
               CARLESON_PERKWINDOW_INTEGRABLE]);;

(* R2d COMPLETE (Fremlin 286O-b-iv): int_R carleson_w = lim_K Cx(2pi) *      *)
(* sum_{abs k<=K} int_R (per-k window).  Combines STEP B (CARLESON_W_REGION_ *)
(* INTEGRAL_LIMIT) with STEP C (CARLESON_W_REGION_KSUM_EQ) by rewriting the  *)
(* K-window integral sequence.                                               *)
let CARLESON_W_REGION_KSUM = prove
 (`!(h:real->complex) z R.
     schwartz h /\ real_measurable R
     ==> ((\K. Cx(&2 * pi) *
                vsum {k:int | abs k <= &K}
                  (\k. integral (IMAGE lift R)
                         (\x. fourier (\y. fourier h y * Cx(carleson_psi z k
                           y)) (--drop x))))
          --> integral (IMAGE lift R) (\x. carleson_w h z (drop x)))
         sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\K. Cx(&2 * pi) *
          vsum {k:int | abs k <= &K}
            (\k. integral (IMAGE lift R)
                   (\x. fourier (\y. fourier (h:real->complex) y *
                     Cx(carleson_psi z k y)) (--drop x)))) =
    (\K. integral (IMAGE lift R)
          (\x. Cx(&2 * pi) *
               fourier (\y. fourier h y * Cx(sum {k:int | abs k <= &K} (\k.
                 carleson_psi z k y))) (--drop x)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `K:num` THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARLESON_W_REGION_KSUM_EQ THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC CARLESON_W_REGION_INTEGRAL_LIMIT THEN ASM_REWRITE_TAC[]);;

(* R3c: the R2d k-sum over an ARBITRARY measurable real^1 piece P (not just  *)
(* IMAGE                                                                     *)
(* lift R). Since P = IMAGE lift (IMAGE drop P) and real_measurable(IMAGE    *)
(* drop P) <=>                                                               *)
(* measurable P (REAL_MEASURABLE_MEASURABLE), CARLESON_W_REGION_KSUM applies *)
(* verbatim.                                                                 *)
(* This lets the 286P cell-pieces F' INTER cell j feed the tile-sum.         *)
let CARLESON_W_PIECE_KSUM = prove
 (`!(h:real->complex) z P.
     schwartz h /\ measurable P
     ==> ((\K. Cx(&2 * pi) *
                vsum {k:int | abs k <= &K}
                  (\k. integral P (\x. fourier (\y. fourier h y *
                    Cx(carleson_psi z k y)) (--drop x))))
          --> integral P (\x. carleson_w h z (drop x)))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`;
    `IMAGE drop (P:real^1->bool)`] CARLESON_W_REGION_KSUM) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[REAL_MEASURABLE_MEASURABLE] THEN
    SUBGOAL_THEN
      `IMAGE lift (IMAGE drop (P:real^1->bool)) = P` (fun th ->
      ASM_REWRITE_TAC[th]) THEN
    REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID];
    SUBGOAL_THEN
      `IMAGE lift (IMAGE drop (P:real^1->bool)) = P` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID];
      REWRITE_TAC[]]]);;

(* R3d helper: pull a complex scalar Cx c out of a region integral of a      *)
(* Schwartz                                                                  *)
(* fourier-window. Cx c * int_P fourier g(--) = int_P fourier(Cx c * g)(--), *)
(* via                                                                       *)
(* FOURIER_LMUL (constant into fourier) + INTEGRAL_COMPLEX_LMUL (fourier     *)
(* g(--) is absolutely integrable on P, being a reflected Schwartz Fourier  *)
(* transform).                                                               *)
let FOURIER_REGION_CMUL = prove
 (`!(g:real->complex) c P.
     schwartz g /\ measurable P
     ==> Cx c * integral P (\x. fourier g (--drop x)) =
         integral P (\x. fourier (\y. Cx c * g y) (--drop x))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `!x:real^1. fourier (\y. Cx c * (g:real->complex) y) (--drop x) = Cx c *
    fourier g (--drop x)`
   (fun th -> REWRITE_TAC[th]) THENL
   [X_GEN_TAC `x:real^1` THEN MATCH_MP_TAC FOURIER_LMUL THEN
    MATCH_MP_TAC SCHWARTZ_MODULATED_INTEGRABLE THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONV_TAC SYM_CONV THEN MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `(:real^1)` THEN
  ASM_SIMP_TAC[SUBSET_UNIV; MEASURABLE_IMP_LEBESGUE_MEASURABLE] THEN
  SUBGOAL_THEN `schwartz (\x. fourier (g:real->complex) (--x))` MP_TAC THENL
   [MP_TAC(ISPEC `fourier (g:real->complex)` SCHWARTZ_REFLECT) THEN
    ANTS_TAC THENL [MATCH_MP_TAC SCHWARTZ_FOURIER THEN
      ASM_REWRITE_TAC[]; REWRITE_TAC[]]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o MATCH_MP SCHWARTZ_ABSINT) THEN REWRITE_TAC[]);;

(* R3d per-cell-per-scale [KEY]: for a witnessing tile (z in Jr(k,nI0,nJ))   *)
(* and any                                                                   *)
(* measurable region P, the nI-partial-sum of <h|(k,nI,nJ)> int_P phi_sigma  *)
(* converges                                                                 *)
(* to 2pi int_P (hhat psi_k)check. This is CARLESON_PERK_286OB (gg from      *)
(* CHIHAT_REP,                                                               *)
(* carleson_psi = the bare Re^2 bump via PSI_BARE, Cx(2pi) pulled via        *)
(* FOURIER_REGION_                                                           *)
(* CMUL). Connects the 286N tile-sum side to the R3c PIECE_KSUM per-k window *)
(* side.                                                                     *)
let CARLESON_PERK_PIECE_LIMIT = prove
 (`!(h:real->complex) k nI0 nJ z P.
     schwartz h /\ measurable P /\ z IN tile_Jr(k,nI0,nJ)
     ==> ((\N. vsum {nI:int | abs nI <= &N}
                (\nI. carleson_ip h (k,nI,nJ) *
                      integral P (\z. phi_sigma (k,nI,nJ) carleson_phi (drop
                        z))))
          --> Cx(&2 * pi) * integral P (\x. fourier (\y. fourier h y *
            Cx(carleson_psi z k y)) (--drop x)))
         sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `z IN tile_Jr(k,&0,nJ)` ASSUME_TAC THENL
   [RULE_ASSUM_TAC(REWRITE_RULE[tile_Jr]) THEN
     ASM_REWRITE_TAC[tile_Jr]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\y. fourier (h:real->complex) y * Cx(carleson_psi z k y)) =
    (\y. fourier h y * Cx(Re(fourier carleson_phi (&2 zpow (--k) * (y -
      tile_ymid(k,&0,nJ)))) pow 2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    MATCH_MP_TAC CARLESON_PSI_BARE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\y. fourier (h:real->complex) y * Cx(Re(fourier carleson_phi
    (&2 zpow (--k) * (y - tile_ymid(k,&0,nJ)))) pow 2)`;
                 `&2 * pi`; `P:real^1->bool`] FOURIER_REGION_CMUL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC CARLESON_PERK_LIMFN0_SCHWARTZ THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPEC `P:real^1->bool` CARLESON_CHIHAT_REP) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `gg:real^1->complex` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`h:real->complex`; `k:int`; `nJ:int`; `P:real^1->bool`;
    `gg:real^1->complex`] CARLESON_PERK_286OB) THEN
  ASM_REWRITE_TAC[]);;

(* R3e norm-limit principle: a UNIFORM-in-K bound on the K-partial tile-sum  *)
(* norms transfers to the limit int_P carleson_w (LIM_NORM_UBOUND on         *)
(* CARLESON_W_PIECE_KSUM). Converts a per-cell tile-sum bound into the       *)
(* per-cell window-integral bound the triangle inequality                    *)
(* (CARLESON_WSEL_INTEGRAL_TRIANGLE) needs.                                  *)
let CARLESON_WSEL_KSUM = prove
 (`!(h:real->complex) u n FF F'.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF)
     ==> ((\K. Cx(&2 * pi) *
             vsum {j:num | j <= n}
               (\j. vsum {k:int | abs k <= &K}
                  (\k. integral (F' INTER {x:real^1 | cargmax (\i:num.
                    carleson_v h (u i)) n (drop x) = j})
                       (\x. fourier (\y. fourier h y * Cx(carleson_psi (u j) k
                         y)) (--drop x)))))
          --> integral F' (\x:real^1. carleson_wsel h u n (drop x)))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`; `FF:real->bool`;
    `F':real^1->bool`]
    CARLESON_WSEL_REGION_DECOMP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `(\K. Cx(&2 * pi) *
             vsum {j:num | j <= n}
               (\j. vsum {k:int | abs k <= &K}
                  (\k. integral (F' INTER {x:real^1 | cargmax (\i:num.
                    carleson_v h (u i)) n (drop x) = j})
                       (\x. fourier (\y. fourier h y * Cx(carleson_psi (u j) k
                         y)) (--drop x))))) =
    (\K. vsum {j:num | j <= n}
               (\j. Cx(&2 * pi) * vsum {k:int | abs k <= &K}
                  (\k. integral (F' INTER {x:real^1 | cargmax (\i:num.
                    carleson_v h (u i)) n (drop x) = j})
                       (\x. fourier (\y. fourier h y * Cx(carleson_psi (u j) k
                         y)) (--drop x)))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    ASM_SIMP_TAC[GSYM VSUM_COMPLEX_LMUL; FINITE_NUMSEG_LE]; ALL_TAC] THEN
  MATCH_MP_TAC LIM_VSUM THEN REWRITE_TAC[FINITE_NUMSEG_LE] THEN
  X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
  MATCH_MP_TAC CARLESON_W_PIECE_KSUM THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MEASURABLE_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `F':real^1->bool` THEN
  ASM_SIMP_TAC[CARLESON_WSEL_PIECE_LMEAS; INTER_SUBSET]);;

(* 286P(b) reduction: a UNIFORM-in-K bound B on the aggregate double-sum     *)
(* norm yields norm(int_F' carleson_wsel) <= B (LIM_NORM_UBOUND on           *)
(* CARLESON_WSEL_KSUM). This reduces CARLESON_WSEL_INTEGRAL_BOUND to a       *)
(* per-K finite tile-double-sum bound (then regroup-by-tile + uniform        *)
(* CARLESON_286N once).                                                      *)
let CARLESON_WSEL_PERKTERM_LIMIT = prove
 (`!(h:real->complex) (z:real) P k.
     schwartz h /\ measurable P
     ==> ((\N. if (?nJ:int. z IN tile_Jr(k,&0,nJ))
               then vsum {nI:int | abs nI <= &N}
                     (\nI. carleson_ip h (k,nI,(@nJ:int. z IN
                       tile_Jr(k,&0,nJ))) *
                           integral P (\w. phi_sigma (k,nI,(@nJ:int. z IN
                             tile_Jr(k,&0,nJ))) carleson_phi (drop w)))
               else vec 0)
          --> Cx(&2 * pi) * integral P (\x. fourier (\y. fourier h y *
            Cx(carleson_psi z k y)) (--drop x)))
         sequentially`,
  REPEAT STRIP_TAC THEN
    ASM_CASES_TAC `?nJ:int. (z:real) IN tile_Jr(k,&0,nJ)` THEN
  ASM_REWRITE_TAC[] THENL
   [FIRST_X_ASSUM(X_CHOOSE_TAC `nJw:int`) THEN
    SUBGOAL_THEN
      `(z:real) IN tile_Jr(k,&0,(@nJ:int. z IN tile_Jr(k,&0,nJ)))`
       ASSUME_TAC THENL
     [CONV_TAC SELECT_CONV THEN EXISTS_TAC `nJw:int` THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`h:real->complex`; `k:int`; `&0:int`;
      `(@nJ:int. (z:real) IN tile_Jr(k,&0,nJ))`; `z:real`;
      `P:real^1->bool`] CARLESON_PERK_PIECE_LIMIT) THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN
      `!y. carleson_psi (z:real) k y = &0` (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN MATCH_MP_TAC CARLESON_PSI_ZERO THEN
       ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[COMPLEX_MUL_RZERO; FOURIER_0] THEN
    SUBGOAL_THEN `integral P (\x:real^1. Cx(&0)) = Cx(&0)` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM COMPLEX_VEC_0; INTEGRAL_0]; ALL_TAC] THEN
    REWRITE_TAC[COMPLEX_MUL_RZERO; GSYM COMPLEX_VEC_0; LIM_CONST]]);;

(* The argmax-cell piece F' INTER cell_j is measurable (F' measurable + cell *)
(* lebesgue-measurable + INTER_SUBSET, via                                   *)
(* MEASURABLE_LEBESGUE_MEASURABLE_SUBSET).                                   *)
let CARLESON_CELL_PIECE_MEASURABLE = prove
 (`!(h:real->complex) u n F' j.
    schwartz h /\ measurable F'
    ==> measurable (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h (u i)) n
      (drop x) = j})`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MEASURABLE_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `F':real^1->bool` THEN
  ASM_SIMP_TAC[CARLESON_WSEL_PIECE_LMEAS; INTER_SUBSET]);;

(* Inner N-limit at fixed K: the guarded (j,k,nI) triple-sum converges       *)
(* (N->inf) to                                                               *)
(* the WSEL_KSUM K-aggregate (in per-term Cx(2pi) form). Double LIM_VSUM     *)
(* over the                                                                  *)
(* finite cell set j<=n (FINITE_NUMSEG_LE) and scale set abs k<=K            *)
(* (CARLESON_FINITE_                                                         *)
(* KSEG), each (j,k)-term = CARLESON_WSEL_PERKTERM_LIMIT at z:=u j, P:= F'   *)
(* INTER                                                                     *)
(* cell_j (measurable via                                                    *)
(* CARLESON_CELL_PIECE_MEASURABLE). Cx(2pi) stays per-term (recovered        *)
(* outside via                                                               *)
(* VSUM_COMPLEX_LMUL when wiring to CARLESON_WSEL_KSUM).                     *)
let CARLESON_WSEL_PERK_INNER_LIMIT = prove
 (`!(h:real->complex) u n FF F' K.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF)
     ==> ((\N. vsum {j:num | j <= n}
                (\j. vsum {k:int | abs k <= &K}
                  (\k. if (?nJ:int. (u j) IN tile_Jr(k,&0,nJ))
                       then vsum {nI:int | abs nI <= &N}
                             (\nI. carleson_ip h (k,nI,(@nJ:int. (u j) IN
                               tile_Jr(k,&0,nJ))) *
                                   integral (F' INTER {x:real^1 | cargmax
                                     (\i:num. carleson_v h (u i)) n (drop x) =
                                      j})
                                     (\w. phi_sigma (k,nI,(@nJ:int. (u j) IN
                                       tile_Jr(k,&0,nJ))) carleson_phi (drop
                                        w)))
                       else vec 0)))
          --> vsum {j:num | j <= n}
                (\j. vsum {k:int | abs k <= &K}
                  (\k. Cx(&2 * pi) * integral (F' INTER {x:real^1 | cargmax
                    (\i:num. carleson_v h (u i)) n (drop x) = j})
                       (\x. fourier (\y. fourier h y * Cx(carleson_psi (u j) k
                         y)) (--drop x)))))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC LIM_VSUM THEN REWRITE_TAC[FINITE_NUMSEG_LE] THEN
  X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
  MATCH_MP_TAC LIM_VSUM THEN REWRITE_TAC[CARLESON_FINITE_KSEG] THEN
  X_GEN_TAC `k:int` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `(u:num->real) j`;
    `F' INTER {x:real^1 | cargmax (\i:num. carleson_v (h:real->complex) (u i))
      n (drop x) = j}`;
    `k:int`] CARLESON_WSEL_PERKTERM_LIMIT) THEN
  ASM_SIMP_TAC[CARLESON_CELL_PIECE_MEASURABLE]);;

(* WSEL_KSUM in per-term Cx(2pi) form: the K-aggregate a_K = the double sum  *)
(* with                                                                      *)
(* Cx(2pi) distributed inside each term (VSUM_COMPLEX_LMUL twice, over the   *)
(* finite                                                                    *)
(* cell + scale sets), which converges to int_F' wsel by CARLESON_WSEL_KSUM. *)
(* Matches                                                                   *)
(* CARLESON_WSEL_PERK_INNER_LIMIT's RHS so the two feed LIM_DIAGONAL_SEQ.    *)
let CARLESON_WSEL_KSUM_PERTERM = prove
 (`!(h:real->complex) u n FF F'.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF)
     ==> ((\K. vsum {j:num | j <= n}
                (\j. vsum {k:int | abs k <= &K}
                  (\k. Cx(&2 * pi) * integral (F' INTER {x:real^1 | cargmax
                    (\i:num. carleson_v h (u i)) n (drop x) = j})
                       (\x. fourier (\y. fourier h y * Cx(carleson_psi (u j) k
                         y)) (--drop x)))))
          --> integral F' (\x:real^1. carleson_wsel h u n (drop x)))
         sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\K. vsum {j:num | j <= n}
                (\j. vsum {k:int | abs k <= &K}
                  (\k. Cx(&2 * pi) * integral (F' INTER {x:real^1 | cargmax
                    (\i:num. carleson_v (h:real->complex) (u i)) n (drop x) =
                     j})
                       (\x. fourier (\y. fourier h y * Cx(carleson_psi (u j) k
                         y)) (--drop x))))) =
    (\K. Cx(&2 * pi) *
             vsum {j:num | j <= n}
               (\j. vsum {k:int | abs k <= &K}
                  (\k. integral (F' INTER {x:real^1 | cargmax (\i:num.
                    carleson_v h (u i)) n (drop x) = j})
                       (\x. fourier (\y. fourier h y * Cx(carleson_psi (u j) k
                         y)) (--drop x)))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `K:num` THEN
    ASM_SIMP_TAC[VSUM_COMPLEX_LMUL; FINITE_NUMSEG_LE;
      CARLESON_FINITE_KSEG] THEN
    AP_TERM_TAC THEN MATCH_MP_TAC VSUM_EQ THEN
    X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
    ASM_SIMP_TAC[VSUM_COMPLEX_LMUL; CARLESON_FINITE_KSEG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`; `FF:real->bool`;
    `F':real^1->bool`]
    CARLESON_WSEL_KSUM) THEN ASM_REWRITE_TAC[]);;

(* Diagonal collapse (LIM_DIAGONAL_SEQ): from a_K --> int_F' wsel            *)
(* (KSUM_PERTERM) and                                                        *)
(* the per-fixed-K inner limit b_{K,N} --> a_K (PERK_INNER_LIMIT), extract a *)
(* single                                                                    *)
(* diagonal nfun with (\K. b_{K, nfun K}) --> int_F' wsel. b_{K,N} is the    *)
(* guarded                                                                   *)
(* (j,k,nI) triple-sum truncated at scale K, nI-index N. This fuses the      *)
(* nested lim_K/                                                             *)
(* lim_N of the tile-limit into one sequential limit -- the analytic core of *)
(* 286P(b).                                                                  *)
let CARLESON_WSEL_DIAG_LIMIT = prove
 (`!(h:real->complex) u n FF F'.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF)
     ==> ?nfun:num->num.
           ((\K. vsum {j:num | j <= n}
                (\j. vsum {k:int | abs k <= &K}
                  (\k. if (?nJ:int. (u j) IN tile_Jr(k,&0,nJ))
                       then vsum {nI:int | abs nI <= &(nfun K)}
                             (\nI. carleson_ip h (k,nI,(@nJ:int. (u j) IN
                               tile_Jr(k,&0,nJ))) *
                                   integral (F' INTER {x:real^1 | cargmax
                                     (\i:num. carleson_v h (u i)) n (drop x) =
                                      j})
                                     (\w. phi_sigma (k,nI,(@nJ:int. (u j) IN
                                       tile_Jr(k,&0,nJ))) carleson_phi (drop
                                        w)))
                       else vec 0)))
            --> integral F' (\x:real^1. carleson_wsel h u n (drop x)))
              sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\K N. vsum {j:num | j <= n}
                (\j. vsum {k:int | abs k <= &K}
                  (\k. if (?nJ:int. (u j) IN tile_Jr(k,&0,nJ))
                       then vsum {nI:int | abs nI <= &N}
                             (\nI. carleson_ip h (k,nI,(@nJ:int. (u j) IN
                               tile_Jr(k,&0,nJ))) *
                                   integral (F' INTER {x:real^1 | cargmax
                                     (\i:num. carleson_v h (u i)) n (drop x) =
                                      j})
                                     (\w. phi_sigma (k,nI,(@nJ:int. (u j) IN
                                       tile_Jr(k,&0,nJ))) carleson_phi (drop
                                        w)))
                       else vec 0))`;
    `\K. vsum {j:num | j <= n}
                (\j. vsum {k:int | abs k <= &K}
                  (\k. Cx(&2 * pi) * integral (F' INTER {x:real^1 | cargmax
                    (\i:num. carleson_v h (u i)) n (drop x) = j})
                       (\x. fourier (\y. fourier h y * Cx(carleson_psi (u j) k
                         y)) (--drop x))))`;
    `integral F' (\x:real^1. carleson_wsel h u n (drop x))`]
   LIM_DIAGONAL_SEQ) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`;
       `FF:real->bool`; `F':real^1->bool`]
        CARLESON_WSEL_KSUM_PERTERM) THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `K:num` THEN
      MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`;
        `FF:real->bool`; `F':real^1->bool`; `K:num`]
        CARLESON_WSEL_PERK_INNER_LIMIT) THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[]]);;

(* =====================================================================     *)
(* 286P(b) FUBINI-OVER-COUNTING regroup (Fremlin mt286 2315-2337): the       *)
(* per-K aggregate b_{K,N} (guarded cell/scale/freq triple-sum) EQUALS the   *)
(* g-selector tile-sum over Qenum = IMAGE fmap {witnessed triples}.  This    *)
(* is the reindex that turns the diagonal-limit's b_{K,nfun K} into the      *)
(* CARLESON_WSEL_TILE_LIMIT tile-sum.  STEP A (FLATTEN) + guard-restrict +   *)
(* VSUM_IMAGE_GEN + per-tile STEP B (TILE_FIBER_SUM).                        *)
(* =====================================================================     *)

let CARLESON_WITSET_MEM = prove
 (`!(u:num->real) n K N j k nI.
     (j,k,nI) IN {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N
       /\
                                          (?nJ:int. u j IN tile_Jr(k,&0,nJ))}
     <=> j <= n /\ abs k <= &K /\ abs nI <= &N /\ (?nJ:int. u j IN
       tile_Jr(k,&0,nJ))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_ELIM_THM; PAIR_EQ] THEN
  EQ_TAC THENL
   [STRIP_TAC THEN REPEAT (FIRST_X_ASSUM SUBST_ALL_TAC) THEN
     ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    STRIP_TAC THEN MAP_EVERY EXISTS_TAC [`j:num`;`k:int`;`nI:int`] THEN
      ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

let CARLESON_GUARD_RESTRICT = prove
 (`!(u:num->real) n K N (Fc:num#int#int->complex).
     vsum {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N}
        (\(j,k,nI). if (?nJ:int. (u j) IN tile_Jr(k,&0,nJ)) then Fc(j,k,nI)
          else vec 0)
    = vsum {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N /\
      (?nJ:int. u j IN tile_Jr(k,&0,nJ))}
        (\(j,k,nI). Fc(j,k,nI))`,
  REPEAT GEN_TAC THEN
  TRANS_TAC EQ_TRANS
   `vsum {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N /\
     (?nJ:int. u j IN tile_Jr(k,&0,nJ))}
        (\(j,k,nI). if (?nJ:int. (u j) IN tile_Jr(k,&0,nJ)) then
          (Fc:num#int#int->complex)(j,k,nI) else vec 0)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC VSUM_SUPERSET THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
      REWRITE_TAC[FORALL_PAIR_THM; CARLESON_WITSET_MEM] THEN
      MAP_EVERY X_GEN_TAC [`j:num`;`k:int`;`nI:int`] THEN
      REWRITE_TAC[IN_ELIM_THM; PAIR_EQ] THEN STRIP_TAC THEN
      REPEAT(FIRST_X_ASSUM(SUBST_ALL_TAC o SYM o
        check(fun th -> is_eq(concl th) && is_var(lhs(concl th))))) THEN
      COND_CASES_TAC THEN REWRITE_TAC[] THEN
      UNDISCH_TAC `~((j:num) <= n /\ abs(k:int) <= &K /\ abs(nI:int) <= &N /\
        (?nJ:int. u j IN tile_Jr(k,&0,nJ)))` THEN
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC VSUM_EQ THEN
      REWRITE_TAC[FORALL_PAIR_THM; CARLESON_WITSET_MEM] THEN
    MAP_EVERY X_GEN_TAC [`j:num`;`k:int`;`nI:int`] THEN STRIP_TAC THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MP_TAC o check (fun th -> is_neg(concl th))) THEN
      REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

let CARLESON_WSEL_TILE_REGROUP = prove
 (`!(h:real->complex) u n FF F' K N.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF)
     ==> vsum {j:num | j <= n}
           (\j. vsum {k:int | abs k <= &K}
             (\k. if (?nJ:int. (u j) IN tile_Jr(k,&0,nJ))
                  then vsum {nI:int | abs nI <= &N}
                        (\nI. carleson_ip h (k,nI,(@nJ:int. (u j) IN
                          tile_Jr(k,&0,nJ))) *
                              integral (F' INTER {x:real^1 | cargmax (\i:num.
                                carleson_v h (u i)) n (drop x) = j})
                                (\z. phi_sigma (k,nI,(@nJ:int. (u j) IN
                                  tile_Jr(k,&0,nJ))) carleson_phi (drop z)))
                  else vec 0))
         = vsum (IMAGE (\(j,k,nI). (k,nI,(@nJ:int. (u j) IN tile_Jr(k,&0,nJ))))
                       {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI
                         <= &N /\
                                        (?nJ:int. u j IN tile_Jr(k,&0,nJ))})
             (\s. carleson_ip h s *
                  integral (F' INTER {x:real^1 | (u(cargmax (\i:num. carleson_v
                    h (u i)) n (drop x))) IN tile_Jr s})
                    (\z. phi_sigma s carleson_phi (drop z)))`,
  REPEAT STRIP_TAC THEN
  ONCE_REWRITE_TAC[CARLESON_WSEL_FLATTEN] THEN
  SUBGOAL_THEN
   `vsum {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N}
        (\(j,k,nI). if (?nJ:int. (u j) IN tile_Jr(k,&0,nJ))
                    then carleson_ip (h:real->complex) (k,nI,(@nJ:int. (u j) IN
                      tile_Jr(k,&0,nJ))) *
                         integral (F' INTER {x:real^1 | cargmax (\i:num.
                           carleson_v h (u i)) n (drop x) = j})
                           (\z. phi_sigma (k,nI,(@nJ:int. (u j) IN
                             tile_Jr(k,&0,nJ))) carleson_phi (drop z))
                    else vec 0)
    = vsum {(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N /\
      (?nJ:int. u j IN tile_Jr(k,&0,nJ))}
        (\(j,k,nI). carleson_ip (h:real->complex) (k,nI,(@nJ:int. (u j) IN
          tile_Jr(k,&0,nJ))) *
                    integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v
                      h (u i)) n (drop x) = j})
                      (\z. phi_sigma (k,nI,(@nJ:int. (u j) IN
                        tile_Jr(k,&0,nJ))) carleson_phi (drop z)))`
   SUBST1_TAC THENL
   [CONV_TAC(DEPTH_CONV GEN_BETA_CONV) THEN
    MP_TAC(ISPECL [`u:num->real`;`n:num`;`K:num`;`N:num`;
      `\(j:num,k:int,nI:int). carleson_ip (h:real->complex) (k,nI,(@nJ:int. (u
        j) IN tile_Jr(k,&0,nJ))) *
                   integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v h
                     (u i)) n (drop x) = j})
                     (\z. phi_sigma (k,nI,(@nJ:int. (u j) IN tile_Jr(k,&0,nJ)))
                       carleson_phi (drop z))`]
     CARLESON_GUARD_RESTRICT) THEN
    CONV_TAC(DEPTH_CONV GEN_BETA_CONV) THEN DISCH_THEN
      ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\(j:num,k:int,nI:int). (k,nI,(@nJ:int. (u j) IN tile_Jr(k,&0,nJ)))`;
    `\(j:num,k:int,nI:int). carleson_ip (h:real->complex) (k,nI,(@nJ:int. (u j)
      IN tile_Jr(k,&0,nJ))) *
                    integral (F' INTER {x:real^1 | cargmax (\i:num. carleson_v
                      h (u i)) n (drop x) = j})
                      (\z. phi_sigma (k,nI,(@nJ:int. (u j) IN
                        tile_Jr(k,&0,nJ))) carleson_phi (drop z))`;
    `{(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N /\ (?nJ:int.
      u j IN tile_Jr(k,&0,nJ))}`]
   VSUM_IMAGE_GEN) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `{(j:num,k:int,nI:int) | j <= n /\ abs k <= &K /\ abs nI <= &N}`
      THEN
    REWRITE_TAC[CARLESON_TRIPLE_FINITE; SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
    DISCH_THEN SUBST1_TAC] THEN
  MATCH_MP_TAC VSUM_EQ THEN REWRITE_TAC[IN_IMAGE] THEN
  X_GEN_TAC `s:int#int#int` THEN
  DISCH_THEN(X_CHOOSE_THEN
    `t:num#int#int` (CONJUNCTS_THEN2 SUBST1_TAC MP_TAC)) THEN
  SPEC_TAC(`t:num#int#int`,`t:num#int#int`) THEN
    REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC [`j0:num`;`k0:int`;`nI0:int`] THEN
  REWRITE_TAC[CARLESON_WITSET_MEM] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`; `FF:real->bool`;
    `F':real^1->bool`;
     `K:num`; `N:num`; `k0:int`; `nI0:int`;
       `(@nJ:int. (u:num->real) j0 IN tile_Jr(k0,&0,nJ))`]
     CARLESON_TILE_FIBER_SUM) THEN
  ASM_REWRITE_TAC[]);;


(* The selected-window tile bound. This                                      *)
(* is Fremlin 286P(b)'s norm(int_F' sum_i v_i chi_Ei) <= C9 ||h||_2 sqrt(mu  *)
(* F'): the                                                                  *)
(* E_i-argmax cell-decomposition (CARLESON_WSEL_REGION_DECOMP) + per-cell    *)
(* R2d tile-sum                                                              *)
(* (CARLESON_W_PIECE_KSUM + CARLESON_PERK_PIECE_LIMIT) +                     *)
(* Fubini-over-counting over the                                             *)
(* tile set + CARLESON_286N region bound.                                    *)
(* 286P(b) per-finite-tile-set bound: for any FINITE tile set Q, the         *)
(* g-selector                                                                *)
(* tile-sum (g = the argmax selector) over the F'-RESTRICTED regions F' cap  *)
(* g^-1[Jr_s] is bounded by C9 ||h||_2 sqrt muFF.  VSUM_NORM (triangle) +    *)
(* region-rewrite (F' cap g^-1[Jr_s] = IMAGE lift{x in drop F' | g x in      *)
(* Jr_s}) +                                                                  *)
(* CARLESON_286N_SCALED ONCE with FF := IMAGE drop F' (giving sqrt(mu(drop   *)
(* F'))) +                                                                   *)
(* sqrt-monotone sqrt(mu(drop F')) <= sqrt(mu FF) (MEASURE_SUBSET, F' SUBSET *)
(* lift FF).                                                                 *)
let CARLESON_WSEL_PERM_BOUND = prove
 (`?C9. &0 <= C9 /\
     !(h:real->complex) u n FF F' Q.
        schwartz h /\ real_measurable FF /\
        measurable F' /\ F' SUBSET (IMAGE lift FF) /\ &0 < real_measure(IMAGE
          drop F') /\
        FINITE Q /\
        (\x. u(cargmax (\i:num. carleson_v h (u i)) n x)) real_measurable_on
          (:real) /\
        (!t. cw_tile t real_integrable_on
              {x | x IN (IMAGE drop F') /\ (u(cargmax (\i:num. carleson_v h (u
                i)) n x)) IN tile_J t})
        ==> norm(vsum Q
              (\s. carleson_ip h s *
                   integral (F' INTER {x:real^1 | (u(cargmax (\i:num.
                     carleson_v h (u i)) n (drop x))) IN tile_Jr s})
                     (\z. phi_sigma s carleson_phi (drop z))))
            <= C9 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              FF)`,
  X_CHOOSE_THEN `C9:real` STRIP_ASSUME_TAC CARLESON_286N_SCALED THEN
  EXISTS_TAC `C9:real` THEN ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `real_measurable(IMAGE drop (F':real^1->bool))` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_MEASURABLE_MEASURABLE] THEN
    SUBGOAL_THEN
      `IMAGE lift (IMAGE drop (F':real^1->bool)) = F'` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID];
       ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `sum Q
      (\s. norm(carleson_ip (h:real->complex) s *
             integral (F' INTER {x:real^1 | (u(cargmax (\i:num. carleson_v h (u
               i)) n (drop x))) IN tile_Jr s})
               (\z. phi_sigma s carleson_phi (drop z))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC VSUM_NORM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Rewrite each F'-restricted region as the 286N FF-slot region with       *)
  (* FF:=drop F'.                                                            *)
  SUBGOAL_THEN
   `!s:int#int#int.
      F' INTER {x:real^1 | (u(cargmax (\i:num. carleson_v (h:real->complex) (u
        i)) n (drop x))) IN tile_Jr s} =
      IMAGE lift {x | x IN (IMAGE drop F') /\
                      (u(cargmax (\i:num. carleson_v h (u i)) n x)) IN tile_Jr
                        s}`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN CONV_TAC SYM_CONV THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE; IN_ELIM_THM; IN_INTER] THEN
    X_GEN_TAC `y:real^1` THEN EQ_TAC THENL
     [STRIP_TAC THEN ASM_REWRITE_TAC[LIFT_DROP] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[IN_IMAGE]) THEN ASM_MESON_TAC[LIFT_DROP];
      STRIP_TAC THEN EXISTS_TAC `drop(y:real^1)` THEN
      ASM_REWRITE_TAC[LIFT_DROP; IN_IMAGE] THEN
        ASM_MESON_TAC[LIFT_DROP]]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `C9 * lnorm (:real^1) (&2) (\z. (h:real->complex)(drop z)) *
              sqrt(real_measure(IMAGE drop (F':real^1->bool)))` THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPECL
     [`\x. u(cargmax (\i:num. carleson_v (h:real->complex) (u i)) n x)`;
      `IMAGE drop (F':real^1->bool)`; `h:real->complex`;
        `Q:(int#int#int)->bool`] o
      check(fun th -> is_forall(concl th) &&
        can (find_term (fun t -> t = `carleson_ip`)) (concl th) &&
        can (find_term (fun t -> t = `sqrt`)) (concl th))) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC LNORM_POS_LE THEN ASM_SIMP_TAC[SCHWARTZ_L2]; ALL_TAC] THEN
    MATCH_MP_TAC SQRT_MONO_LE THEN
    REWRITE_TAC[REAL_MEASURE_MEASURE] THEN
    SUBGOAL_THEN
      `IMAGE lift (IMAGE drop (F':real^1->bool)) = F'` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURE_SUBSET THEN
    ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE]]);;

(* 286P(b) tile-limit identity (Fremlin's Fubini-over-counting /             *)
(* regroup-by-tile,                                                          *)
(* mt286 2269-2358): int_F' carleson_wsel is the sequential limit of finite  *)
(* g-selector tile-sums sum_{s in Qenum m} <h|phi_s> int_{F' cap g^-1[Jr_s]} *)
(* phi_s                                                                     *)
(* (g x = u(cargmax..x)), where Qenum enumerates finite tile-subsets.        *)
(* Regions are                                                               *)
(* F'-RESTRICTED (F' INTER {x | g(drop x) IN Jr_s}) -- F' is the 246K        *)
(* sign-selection                                                            *)
(* set, a proper subset of lift FF, so the regroup is over F' rather than    *)
(* all of FF. This packages the per-cell (WSEL_REGION_DECOMP) + per-scale    *)
(* (PERK_PIECE_                                                              *)
(* LIMIT) + cell-merge (CELL_SUM_INTEGRAL) triple-limit interchange over F'. *)
(* [The analytic core of 286P.]                                             *)
(* Discharge of CARLESON_WSEL_TILE_LIMIT: Qenum := IMAGE fmap {witnessed     *)
(* triples at (m,nfun m)}; the tile-sum over Qenum m = the diagonal          *)
(* b_{m,nfun m} (TILE_REGROUP), which -> int_F' wsel (DIAG_LIMIT).           *)
let CARLESON_WSEL_TILE_LIMIT = prove
 (`!(h:real->complex) u n FF F'.
     schwartz h /\ real_measurable FF /\ measurable F' /\ F' SUBSET (IMAGE lift
       FF)
     ==> ?Qenum:num->(int#int#int)->bool.
           (!m. FINITE(Qenum m)) /\
           (\x. u(cargmax (\i:num. carleson_v h (u i)) n x)) real_measurable_on
             (:real) /\
           (!t. cw_tile t real_integrable_on
                 {x | x IN (IMAGE drop F') /\ (u(cargmax (\i:num. carleson_v h
                   (u i)) n x)) IN tile_J t}) /\
           ((\m. vsum (Qenum m)
                   (\s. carleson_ip h s *
                        integral (F' INTER {x:real^1 | (u(cargmax (\i:num.
                          carleson_v h (u i)) n (drop x))) IN tile_Jr s})
                          (\z. phi_sigma s carleson_phi (drop z))))
            --> integral F' (\x:real^1. carleson_wsel h u n (drop x)))
              sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`; `FF:real->bool`;
    `F':real^1->bool`]
    CARLESON_WSEL_DIAG_LIMIT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `nfun:num->num` ASSUME_TAC) THEN
  EXISTS_TAC
   `\m. IMAGE (\(j,k,nI). (k,nI,(@nJ:int. (u j) IN tile_Jr(k,&0,nJ))))
              {(j:num,k:int,nI:int) | j <= n /\ abs k <= &m /\ abs nI <= &(nfun
                m) /\
                                       (?nJ:int. u j IN tile_Jr(k,&0,nJ))}`
                                         THEN
  REPEAT CONJ_TAC THENL
   [GEN_TAC THEN BETA_TAC THEN MATCH_MP_TAC FINITE_IMAGE THEN
    MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `{(j:num,k:int,nI:int) | j <= n /\ abs k <= &m /\ abs nI <=
      &(nfun m)}` THEN
    REWRITE_TAC[CARLESON_TRIPLE_FINITE; SUBSET; IN_ELIM_THM] THEN MESON_TAC[];
    MATCH_MP_TAC CARLESON_G_SELECTOR_MEASURABLE THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN MATCH_MP_TAC CARLESON_G_CWTILE_INTEGRABLE THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[REAL_MEASURABLE_MEASURABLE] THEN
    SUBGOAL_THEN
      `IMAGE lift (IMAGE drop (F':real^1->bool)) = F'` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID];
       ASM_REWRITE_TAC[]];
    SUBGOAL_THEN
     `(\m. vsum ((\m. IMAGE (\(j,k,nI). (k,nI,(@nJ:int. (u j) IN
       tile_Jr(k,&0,nJ))))
                {(j:num,k:int,nI:int) | j <= n /\ abs k <= &m /\ abs nI <=
                  &(nfun m) /\
                                         (?nJ:int. u j IN tile_Jr(k,&0,nJ))})
                                           m)
               (\s. carleson_ip (h:real->complex) s *
                    integral (F' INTER {x:real^1 | (u(cargmax (\i:num.
                      carleson_v h (u i)) n (drop x))) IN tile_Jr s})
                      (\z. phi_sigma s carleson_phi (drop z))))
        = (\m. vsum {j:num | j <= n}
                  (\j. vsum {k:int | abs k <= &m}
                    (\k. if (?nJ:int. (u j) IN tile_Jr(k,&0,nJ))
                         then vsum {nI:int | abs nI <= &(nfun m)}
                               (\nI. carleson_ip h (k,nI,(@nJ:int. (u j) IN
                                 tile_Jr(k,&0,nJ))) *
                                     integral (F' INTER {x:real^1 | cargmax
                                       (\i:num. carleson_v h (u i)) n (drop x)
                                        = j})
                                       (\w. phi_sigma (k,nI,(@nJ:int. (u j) IN
                                         tile_Jr(k,&0,nJ))) carleson_phi (drop
                                          w)))
                         else vec 0)))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `m:num` THEN BETA_TAC THEN
      CONV_TAC SYM_CONV THEN
      MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`;
        `FF:real->bool`; `F':real^1->bool`; `m:num`; `(nfun:num->num) m`]
        CARLESON_WSEL_TILE_REGROUP) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

(* Tile-limit + per-finite-set bound: norm(int_F'                            *)
(* carleson_wsel) <= C9 ||h||_2 sqrt muFF. muFF=0: F' negligible (subset of  *)
(* lift FF                                                                   *)
(* with measure 0), integral 0. muFF>0: LIM_NORM_UBOUND on the tile-limit,   *)
(* each                                                                      *)
(* finite partial-sum bounded by CARLESON_WSEL_PERM_BOUND.                   *)
let CARLESON_WSEL_INTEGRAL_BOUND = prove
 (`?C9. &0 <= C9 /\
      !(h:real->complex) u n FF F'.
         schwartz h /\ real_measurable FF /\
         measurable F' /\ F' SUBSET (IMAGE lift FF)
         ==> norm(integral F' (\x:real^1. carleson_wsel h u n (drop x)))
             <= C9 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
               FF)`,
  X_CHOOSE_THEN `C9:real` STRIP_ASSUME_TAC CARLESON_WSEL_PERM_BOUND THEN
  EXISTS_TAC `C9:real` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC
   [`h:real->complex`; `u:num->real`; `n:num`; `FF:real->bool`;
     `F':real^1->bool`] THEN
  STRIP_TAC THEN
  ASM_CASES_TAC `negligible (F':real^1->bool)` THENL
   [ASM_SIMP_TAC[INTEGRAL_ON_NEGLIGIBLE; NORM_0] THEN
    REWRITE_TAC[REAL_MUL_ASSOC] THEN MATCH_MP_TAC REAL_LE_MUL THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC LNORM_POS_LE THEN ASM_SIMP_TAC[SCHWARTZ_L2];
      MATCH_MP_TAC SQRT_POS_LE THEN
      REWRITE_TAC[REAL_MEASURE_MEASURE] THEN MATCH_MP_TAC MEASURE_POS_LE THEN
      ASM_REWRITE_TAC[GSYM REAL_MEASURABLE_MEASURABLE]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 < real_measure(IMAGE drop (F':real^1->bool))` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_MEASURE_MEASURE] THEN
    SUBGOAL_THEN
      `IMAGE lift (IMAGE drop (F':real^1->bool)) = F'` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM IMAGE_o; o_DEF; LIFT_DROP; IMAGE_ID]; ALL_TAC] THEN
    MP_TAC(ISPEC `F':real^1->bool` MEASURE_POS_LE) THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPEC `F':real^1->bool` NEGLIGIBLE_EQ_MEASURE_0) THEN
      ASM_REWRITE_TAC[] THEN
    REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real->complex`; `u:num->real`; `n:num`; `FF:real->bool`;
    `F':real^1->bool`]
    CARLESON_WSEL_TILE_LIMIT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN
    `Qenum:num->(int#int#int)->bool` STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC(ISPEC `sequentially` LIM_NORM_UBOUND) THEN
  EXISTS_TAC
   `\(m:num). vsum (Qenum m)
          (\s. carleson_ip (h:real->complex) s *
               integral (F' INTER {x:real^1 | (u(cargmax (\i:num. carleson_v h
                 (u i)) n (drop x))) IN tile_Jr s})
                 (\z. phi_sigma s carleson_phi (drop z)))` THEN
  REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY; EVENTUALLY_SEQUENTIALLY] THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM(fun th -> if can (find_term (fun t -> t = `carleson_wsel`))
     (concl th)
       then MP_TAC th else NO_TAC) THEN REWRITE_TAC[];
    EXISTS_TAC `0` THEN X_GEN_TAC `m:num` THEN DISCH_TAC THEN BETA_TAC THEN
    FIRST_ASSUM(MP_TAC o SPECL
     [`h:real->complex`; `u:num->real`; `n:num`; `FF:real->bool`;
       `F':real^1->bool`;
      `(Qenum:num->(int#int#int)->bool) m`] o
      check(fun th -> is_forall(concl th) &&
        can (find_term (fun t -> t = `carleson_ip`)) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* 286P(b,c) DEEP integral bound: int_F Ah <= 4 C9 ||h||_2 sqrt(mu F), from  *)
(* the selected-window tile bound CARLESON_WSEL_INTEGRAL_BOUND via           *)
(* CARLESON_286P_FROM_TILEBOUND.                                             *)
let CARLESON_286P_BOUND = prove
 (`?C9. &0 <= C9 /\
     !(h:real->complex) FF.
        schwartz h /\ real_measurable FF
        ==> real_integral FF (carleson_A h)
            <= &4 * C9 * lnorm (:real^1) (&2) (\z. h(drop z)) *
              sqrt(real_measure FF)`,
  MATCH_MP_TAC CARLESON_286P_FROM_TILEBOUND THEN
  ACCEPT_TAC CARLESON_WSEL_INTEGRAL_BOUND);;

(* 286P (Fremlin 1939-2360): Ah is measurable (CARLESON_A_MEASURABLE) AND    *)
(* int_F Ah <= 4 C9 ||h||_2 sqrt(mu F) (CARLESON_286P_BOUND, the deep gate). *)

let CARLESON_286P = prove
 (`?C9. &0 <= C9 /\
     !(h:real->complex) FF.
        schwartz h /\ real_measurable FF
        ==> (carleson_A h) real_measurable_on (:real) /\
            real_integral FF (carleson_A h)
            <= &4 * C9 * lnorm (:real^1) (&2) (\z. h(drop z)) *
              sqrt(real_measure FF)`,
  X_CHOOSE_THEN `C9:real` STRIP_ASSUME_TAC CARLESON_286P_BOUND THEN
  EXISTS_TAC `C9:real` THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THENL
   [MATCH_MP_TAC CARLESON_A_MEASURABLE THEN ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(MP_TAC o SPECL [`h:real->complex`; `FF:real->bool`]) THEN
    ASM_REWRITE_TAC[]]);;

(* Whole-line reflection preserves lspace membership.                        *)
let LSPACE_REFLECT = prove
 (`!g:real^1->complex. g IN lspace (:real^1) (&2)
     ==> (\z. g(--z)) IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o REWRITE_RULE[lspace; IN_ELIM_THM]) THEN
  REWRITE_TAC[lspace; IN_ELIM_THM] THEN STRIP_TAC THEN CONJ_TAC THENL
   [ONCE_REWRITE_TAC[MEASURABLE_ON_REFLECT] THEN
    ASM_REWRITE_TAC[REFLECT_UNIV];
    SUBGOAL_THEN
     `(\x:real^1. lift(norm((g:real^1->complex)(--x)) rpow &2)) =
      (\x. (\z. lift(norm((g:real^1->complex) z) rpow &2)) (--x))`
     SUBST1_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
    ONCE_REWRITE_TAC[INTEGRABLE_REFLECT_GEN] THEN
    ASM_REWRITE_TAC[REFLECT_UNIV]]);;

(* The L^p norm is reflection-invariant (same integrand after z |-> --z).    *)
let LNORM_REFLECT = prove
 (`!(g:real^1->complex) p. lnorm (:real^1) p (\z. g(--z)) = lnorm (:real^1) p
   g`,
  REPEAT GEN_TAC THEN REWRITE_TAC[lnorm] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  SUBGOAL_THEN
   `(\x:real^1. lift(norm((g:real^1->complex)(--x)) rpow p)) =
    (\x. (\z. lift(norm((g:real^1->complex) z) rpow p)) (--x))`
   SUBST1_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
  ONCE_REWRITE_TAC[INTEGRAL_REFLECT_GEN] THEN REWRITE_TAC[REFLECT_UNIV]);;

(* ========================================================================= *)
(* 286S(c)/286T(b) descent (Fremlin 2827-2948): from the 286P tile bound to  *)
(* the linearized maximal bound. S6 = kernel domination (286S(c)), S7 = 286T *)
(* (b), S8 = assembly discharging CARLESON_286T_FROM_286P with C10 = 4 C9    *)
(* log2                                                                      *)
(* / (pi thetatilde_1(0)) (>=0 since thetatilde_1(0)>0).                     *)
(* ------------------------------------------------------------------------- *)
(* S6 (ATILDE_KERNEL_DOM) and S7 (AHAT_LE_ATILDE) are the two key analytic   *)
(* inputs; the S8 assembly below is built FROM them.                         *)
(* ========================================================================= *)

(* fourier(hcheck) = h where hcheck = \x. fourier h(--x)                     *)
(* [DOUBLE_TRANSFORM+REFLECT].                                               *)
let HCHECK_FT = prove
 (`!(h:real->complex) z. schwartz h ==> fourier (\x. fourier h (--x)) z = h z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`] DOUBLE_TRANSFORM) THEN
    ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`fourier(h:real->complex)`; `z:real`] FOURIER_REFLECT) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* schwartz(hcheck).                                                         *)
let SCHWARTZ_HCHECK = prove
 (`!(h:real->complex). schwartz h ==> schwartz (\x. fourier h (--x))`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(ISPEC `fourier(h:real->complex)` SCHWARTZ_REFLECT) THEN
  ANTS_TAC THENL [MATCH_MP_TAC SCHWARTZ_FOURIER THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[]);;

(* =================================================================         *)
(* S6 = ATILDE_KERNEL_DOM (Fremlin 286S(c)) and its sub-lemmas.              *)
(* Target: 2pi*norm(fourier(hhat.thetatilde_z)(-x))                          *)
(* <= carleson_Atilde h x.  Route: Mn(w)->tt_z(w) (DCT in a) + FOURIER       *)
(* _VALUE_LIM => fourier(hhat Mn)->fourier(hhat tt_z); per-n Wn<=Aavg;       *)
(* liminf.                                                                   *)
(* =================================================================         *)

(* ===== S6 STEP A: Cesaro partial qn(a,w) -> g(a,w,z), sequentially, all w  *)
(* =====                                                                     *)
let QN_SEQ_LIMIT = prove
 (`!alpha y z. &0 < alpha
   ==> ((\n. inv(&n) * real_integral (real_interval[&0,&n]) (\beta.
     carleson_theta' z alpha beta y))
        ---> carleson_g alpha y z) sequentially`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `(y:real) < z` THENL
   [MP_TAC(SPECL [`alpha:real`; `y:real`; `z:real`] CARLESON_G_AVG_LIMIT) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o BETA_RULE o MATCH_MP REALLIM_POSINFINITY_SEQUENTIALLY)
      THEN
    REWRITE_TAC[];
    SUBGOAL_THEN `(z:real) <= y` ASSUME_TAC THENL
      [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `carleson_g alpha y z = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC CARLESON_G_TRIVIAL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(\n. inv(&n) * real_integral (real_interval[&0,&n]) (\beta.
       carleson_theta' z alpha beta y)) =
      (\n. &0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      SUBGOAL_THEN
        `(\beta. carleson_theta' z alpha beta y) =
         (\beta:real. &0)` SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
        MATCH_MP_TAC CARLESON_THETA'_SUPPORT THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[REAL_INTEGRAL_0; REAL_MUL_RZERO]];
      REWRITE_TAC[REALLIM_CONST]]]);;

(* 0 <= qn(a,w) <= 1.                                                        *)
let QN_BOUNDS = prove
 (`!z alpha beta_n y. &0 <= inv(&beta_n) * real_integral
   (real_interval[&0,&beta_n]) (\beta. carleson_theta' z alpha beta y) /\
      inv(&beta_n) * real_integral (real_interval[&0,&beta_n]) (\beta.
        carleson_theta' z alpha beta y) <= &1`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `beta_n = 0` THENL
   [ASM_REWRITE_TAC[REAL_INV_0; REAL_MUL_LZERO] THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &beta_n` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral (real_interval[&0,&beta_n]) (\beta. carleson_theta' z alpha
     beta y) <= &beta_n /\
    &0 <= real_integral (real_interval[&0,&beta_n]) (\beta. carleson_theta' z
      alpha beta y)`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `real_integral (real_interval[&0,&beta_n]) (\beta:real. &1)`
        THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INTEGRAL_LE THEN
        REWRITE_TAC[THETA'_BETA_INTEGRABLE; REAL_INTEGRABLE_CONST] THEN
        REPEAT STRIP_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS];
        SIMP_TAC[REAL_INTEGRAL_CONST; REAL_ARITH `&0 <= &beta_n`] THEN
          REAL_ARITH_TAC];
      MATCH_MP_TAC REAL_INTEGRAL_POS THEN
      REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN
      REPEAT STRIP_TAC THEN REWRITE_TAC[CARLESON_THETA'_BOUNDS]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN REWRITE_TAC[REAL_POS]; ASM_REWRITE_TAC[]];
    REWRITE_TAC[GSYM REAL_LE_RDIV_EQ; real_div] THEN
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
    ASM_SIMP_TAC[GSYM real_div; REAL_LE_LDIV_EQ] THEN
    ASM_REWRITE_TAC[REAL_MUL_LID]]);;

(* |inv a * qn| <= 1 on [1,2].                                               *)
let MN_INTEGRAND_BOUND = prove
 (`!z w k alpha. &1 <= alpha /\ alpha <= &2
   ==> abs(inv alpha * (inv(&k) * real_integral (real_interval[&0,&k]) (\beta.
     carleson_theta' z alpha beta w))) <= &1`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`z:real`; `alpha:real`; `k:num`; `w:real`] QN_BOUNDS) THEN
    STRIP_TAC THEN
  REWRITE_TAC[REAL_ABS_BOUNDS] THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&0` THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC; ASM_REWRITE_TAC[]]];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `&1 * (inv(&k) * real_integral (real_interval[&0,&k]) (\beta.
      carleson_theta' z alpha beta w))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_RMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INV_LE_1 THEN ASM_REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
      REWRITE_TAC[REAL_MUL_LID] THEN ASM_REWRITE_TAC[]]]);;

(* ===== S6 STEP B: Mn(w) -> carleson_thetatilde z w (DCT in a over [1,2])   *)
(* =====                                                                     *)
let MN_SEQ_LIMIT = prove
 (`!(z:real) w.
     ((\n. real_integral (real_interval[&1,&2])
              (\alpha. inv alpha * (inv(&n) * real_integral
                (real_interval[&0,&n])
                        (\beta. carleson_theta' z alpha beta w))))
        ---> carleson_thetatilde z w) sequentially`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_thetatilde] THEN
  MP_TAC(ISPECL
   [`\n alpha. inv alpha * (inv(&n) * real_integral (real_interval[&0,&n])
                (\beta. carleson_theta' z alpha beta w))`;
    `\alpha. inv alpha * carleson_g alpha w z`;
    `\alpha:real. &1`;
    `real_interval[&1,&2]`] REAL_DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [(* (1) each f n integrable on [1,2]                                    *)
      X_GEN_TAC `k:num` THEN
      MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
      EXISTS_TAC `(\alpha:real. &1)` THEN REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL
         [`\alpha:real. inv alpha`;
          `\alpha:real. inv(&k) * real_integral (real_interval[&0,&k]) (\beta.
            carleson_theta' z alpha beta w)`;
          `real_interval[&1,&2]`] REAL_MEASURABLE_ON_MUL) THEN
        REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET
           THEN
          REWRITE_TAC[REAL_CLOSED_REAL_INTERVAL] THEN
          MATCH_MP_TAC REAL_CONTINUOUS_ON_INV THEN
          REWRITE_TAC[REAL_CONTINUOUS_ON_ID; IN_REAL_INTERVAL] THEN
          REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC;
          REWRITE_TAC[CARLESON_AN_MEASURABLE]];
        REWRITE_TAC[REAL_INTEGRABLE_CONST];
        X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
          STRIP_TAC THEN
        MATCH_MP_TAC MN_INTEGRAND_BOUND THEN ASM_REWRITE_TAC[]];
      (* (2) dominator &1 integrable                                         *)
      REWRITE_TAC[REAL_INTEGRABLE_CONST];
      (* (3) |f n alpha| <= 1 on [1,2]                                       *)
      MAP_EVERY X_GEN_TAC [`k:num`; `alpha:real`] THEN
      REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
      MATCH_MP_TAC MN_INTEGRAND_BOUND THEN ASM_REWRITE_TAC[];
      (* (4) f n alpha -> g alpha ptwise                                     *)
      X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
        STRIP_TAC THEN
      MATCH_MP_TAC REALLIM_LMUL THEN
      MATCH_MP_TAC QN_SEQ_LIMIT THEN ASM_REAL_ARITH_TAC];
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]);;

(* 0 <= Mn(w) <= 1.                                                          *)
let MN_LE1 = prove
 (`!z w n. &0 <= real_integral (real_interval[&1,&2])
              (\alpha. inv alpha * (inv(&n) * real_integral
                (real_interval[&0,&n]) (\beta. carleson_theta' z alpha beta
                 w))) /\
           real_integral (real_interval[&1,&2])
              (\alpha. inv alpha * (inv(&n) * real_integral
                (real_interval[&0,&n]) (\beta. carleson_theta' z alpha beta
                 w))) <= &1`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\alpha. inv alpha * (inv(&n) * real_integral (real_interval[&0,&n])
     (\beta. carleson_theta' z alpha beta w)))
    real_integrable_on real_interval[&1,&2]`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
    EXISTS_TAC `(\alpha:real. &1)` THEN REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`\alpha:real. inv alpha`;
        `\alpha:real. inv(&n) * real_integral (real_interval[&0,&n]) (\beta.
          carleson_theta' z alpha beta w)`;
        `real_interval[&1,&2]`] REAL_MEASURABLE_ON_MUL) THEN
      REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET THEN
        REWRITE_TAC[REAL_CLOSED_REAL_INTERVAL] THEN
        MATCH_MP_TAC REAL_CONTINUOUS_ON_INV THEN
        REWRITE_TAC[REAL_CONTINUOUS_ON_ID; IN_REAL_INTERVAL] THEN
        REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC;
        REWRITE_TAC[CARLESON_AN_MEASURABLE]];
      REWRITE_TAC[REAL_INTEGRABLE_CONST];
      X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
        STRIP_TAC THEN
      MATCH_MP_TAC MN_INTEGRAND_BOUND THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
      STRIP_TAC THEN
    MP_TAC(ISPECL [`z:real`; `alpha:real`; `n:num`; `w:real`] QN_BOUNDS) THEN
      STRIP_TAC THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC; ASM_REWRITE_TAC[]];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral (real_interval[&1,&2]) (\alpha:real. &1)` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_LE THEN
       ASM_REWRITE_TAC[REAL_INTEGRABLE_CONST] THEN
      X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
        STRIP_TAC THEN
      MP_TAC(ISPECL [`z:real`; `w:real`; `n:num`;
        `alpha:real`] MN_INTEGRAND_BOUND) THEN
      ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC;
      SIMP_TAC[REAL_INTEGRAL_CONST; REAL_ARITH `&1 <= &2`] THEN
        REAL_ARITH_TAC]]);;

(* Aavg h n x <= M0 * log2 uniformly (M0 = sqrt2pi int|hhat|); STEP D input
   (guarantees the running-inf/liminf converges to a finite value).          *)
let AAVG_UNIF_BOUND = prove
 (`!(h:real->complex) n x. schwartz h /\ ~(n = 0)
   ==> carleson_Aavg h n x
       <= (sqrt(&2 * pi) * drop(integral (:real^1) (\y. lift(norm(fourier
         (h:real->complex) (drop y)))))) * log(&2)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `M0 = sqrt(&2 * pi) * drop(integral (:real^1) (\y.
    lift(norm(fourier (h:real->complex) (drop y)))))` THEN
  SUBGOAL_THEN `&0 <= M0` ASSUME_TAC THENL
   [EXPAND_TAC "M0" THEN MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LE THEN MP_TAC PI_POS THEN REAL_ARITH_TAC;
      MATCH_MP_TAC INTEGRAL_DROP_POS THEN
        REWRITE_TAC[LIFT_DROP; NORM_POS_LE] THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
        ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[carleson_Aavg; carleson_Sinner] THEN
  SUBGOAL_THEN `&0 < &n` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `inv(&n) * real_integral (real_interval[&1,&2]) (\alpha. inv alpha
    * (&n * M0))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN REWRITE_TAC[REAL_POS]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC A_ITERATE_INTEGRABLE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_INTEGRABLE_RMUL THEN MP_TAC INV_INTEGRABLE_1_2 THEN
        REWRITE_TAC[ETA_AX];
      X_GEN_TAC `alpha:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
        STRIP_TAC THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `real_integral (real_interval[&0,&n]) (\beta:real. M0)` THEN
        CONJ_TAC THENL
       [MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC AMD_BSLICE_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
           ASM_REAL_ARITH_TAC;
          REWRITE_TAC[REAL_INTEGRABLE_CONST];
          X_GEN_TAC `beta:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
            STRIP_TAC THEN
          EXPAND_TAC "M0" THEN MATCH_MP_TAC AMD_UNIF_BOUND THEN
            ASM_REWRITE_TAC[] THEN
          ASM_REAL_ARITH_TAC];
        SIMP_TAC[REAL_INTEGRAL_CONST; REAL_ARITH `&0 <= &n`] THEN
          REAL_ARITH_TAC]];
    SUBGOAL_THEN
     `real_integral (real_interval[&1,&2]) (\alpha. inv alpha * (&n * M0)) =
      real_integral (real_interval[&1,&2]) (\alpha. (&n * M0) * inv alpha)`
     SUBST1_TAC THENL
     [AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
       REWRITE_TAC[REAL_MUL_AC]; ALL_TAC] THEN
    MP_TAC(ISPECL [`\a:real. inv a`; `&n * M0:real`;
      `real_interval[&1,&2]`] REAL_INTEGRAL_LMUL) THEN
    ANTS_TAC THENL [REWRITE_TAC[INV_INTEGRABLE_1_2]; ALL_TAC] THEN
    BETA_TAC THEN DISCH_THEN SUBST1_TAC THEN
      REWRITE_TAC[INV_INTEGRAL_1_2_LOG2] THEN
    ASM_SIMP_TAC[REAL_FIELD `~(&n = &0) ==> inv(&n) * ((&n * M0) * log(&2)) =
      M0 * log(&2)`;
                 REAL_OF_NUM_EQ] THEN REWRITE_TAC[REAL_LE_REFL]]);;

(* STEP D core: f->L, f<=g ptwise, g bounded-below with running-inf ->G ==>  *)
(* L<=G. (Abstract liminf-domination; assembles STEP D of                    *)
(* ATILDE_KERNEL_DOM.)                                                       *)
let LIMINF_DOM = prove
 (`!f g L G.
     (f ---> L) sequentially /\
     (!n:num. f n <= g n) /\
     (?b. !n. b <= g n) /\
     ((\m. inf {g n | n >= m}) ---> G) sequentially
     ==> L <= G`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`sequentially`; `f:num->real`; `g:num->real`; `L:real`;
    `G:real`] HAS_LIMINF_LE) THEN
  REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REALLIM_IMP_HAS_LIMINF THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[HAS_LIMINF_SEQUENTIALLY_REALLIM_INF] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ASM_REWRITE_TAC[]];
    MATCH_MP_TAC ALWAYS_EVENTUALLY THEN ASM_REWRITE_TAC[]]);;

(* STEP D input (iv): the running-inf of Aavg converges (bounded monotone).
   Each inf-tail sits in [0, M0 log2] (M0 = sqrt2pi int|hhat|); the tail-inf
   is nondecreasing in m (REAL_LE_INF_SUBSET on nested tails).               *)
let AAVG_RUNNINGINF_CONV = prove
 (`!(h:real->complex) x. schwartz h
   ==> ?G. ((\m. inf {carleson_Aavg h n x | n >= m}) ---> G) sequentially`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CONVERGENT_REAL_BOUNDED_MONOTONE THEN
  ABBREV_TAC `M0 = sqrt(&2 * pi) * drop(integral (:real^1) (\y.
    lift(norm(fourier (h:real->complex) (drop y)))))` THEN
  SUBGOAL_THEN
   `!m. &0 <= inf {carleson_Aavg h n x | n >= m} /\
        inf {carleson_Aavg h n x | n >= m} <= M0 * log(&2)`
   ASSUME_TAC THENL
   [GEN_TAC THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INF THEN
      REWRITE_TAC[FORALL_IN_GSPEC] THEN CONJ_TAC THENL
       [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
        MAP_EVERY EXISTS_TAC [`carleson_Aavg h m x`; `m:num`] THEN
          REWRITE_TAC[GE; LE_REFL];
        REPEAT STRIP_TAC THEN MATCH_MP_TAC AAVG_NONNEG THEN ASM_REWRITE_TAC[]];
      MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `carleson_Aavg h (m + 1) x` THEN CONJ_TAC THENL
       [MATCH_MP_TAC INF_LE_ELEMENT THEN CONJ_TAC THENL
         [EXISTS_TAC `&0` THEN REWRITE_TAC[FORALL_IN_GSPEC] THEN
          REPEAT STRIP_TAC THEN MATCH_MP_TAC AAVG_NONNEG THEN
            ASM_REWRITE_TAC[];
          REWRITE_TAC[IN_ELIM_THM] THEN EXISTS_TAC `m + 1` THEN
          REWRITE_TAC[GE] THEN ARITH_TAC];
        EXPAND_TAC "M0" THEN MATCH_MP_TAC AAVG_UNIF_BOUND THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[REAL_BOUNDED_POS] THEN
    EXISTS_TAC `abs(M0 * log(&2)) + &1` THEN
    REWRITE_TAC[FORALL_IN_IMAGE; IN_UNIV] THEN BETA_TAC THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      GEN_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `x':num`) THEN DISCH_TAC THEN
      MATCH_MP_TAC(REAL_ARITH `&0 <= i /\ i <= b ==> abs(i) <= abs(b) + &1`)
        THEN
      ASM_REWRITE_TAC[]];
    DISJ1_TAC THEN GEN_TAC THEN BETA_TAC THEN
    MATCH_MP_TAC REAL_LE_INF_SUBSET THEN REPEAT CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      MAP_EVERY EXISTS_TAC [`carleson_Aavg h (SUC n) x`; `SUC n`] THEN
        REWRITE_TAC[GE; LE_REFL];
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
      EXISTS_TAC `n':num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      EXISTS_TAC `&0` THEN REWRITE_TAC[FORALL_IN_GSPEC] THEN
      REPEAT STRIP_TAC THEN MATCH_MP_TAC AAVG_NONNEG THEN
        ASM_REWRITE_TAC[]]]);;

(* STEP D input (iii): the n=0 degenerate case of WN_LE_AAVG.  At n=0 the inner
   factor inv(&0)=&0 collapses the multiplier Mn_0 to &0, so the transform is
   vec 0 (norm 0), and carleson_Aavg h 0 x = inv(&0)*Sinner = &0.            *)
let WN_LE_AAVG_ZERO = prove
 (`!(h:real->complex) z x. schwartz h
   ==> &2 * pi * norm(fourier (\w. fourier h w *
         Cx(real_integral (real_interval[&1,&2])
             (\alpha. inv alpha * (inv(&0) * real_integral
               (real_interval[&0,&0])
                       (\beta. carleson_theta' z alpha beta w))))) (--x))
       <= carleson_Aavg h 0 x`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[carleson_Aavg; REAL_INV_0; REAL_MUL_LZERO] THEN
  SUBGOAL_THEN
   `(\w. fourier (h:real->complex) w *
       Cx(real_integral (real_interval[&1,&2]) (\alpha. inv alpha * &0))) =
    (\w:real. vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[REAL_MUL_RZERO; REAL_INTEGRAL_0] THEN
    REWRITE_TAC[GSYM COMPLEX_VEC_0; COMPLEX_MUL_RZERO];
    ALL_TAC] THEN
  REWRITE_TAC[fourier; COMPLEX_VEC_0; COMPLEX_MUL_RZERO] THEN
  REWRITE_TAC[GSYM COMPLEX_VEC_0; INTEGRAL_0; COMPLEX_MUL_RZERO] THEN
  REWRITE_TAC[COMPLEX_VEC_0; COMPLEX_MUL_RZERO; COMPLEX_NORM_0;
              REAL_MUL_RZERO; REAL_LE_REFL]);;

(* Bilinear step of Fremlin 286V: <g|h_ax> = <f2|fourier h_ax>, where f2     *)
(* represents the Fourier transform of g.  Direct PARSEVAL_L2_BILINEAR with  *)
(* a:=g, b:=h_ax, ahat:=f2, bhat:=fourier h_ax (HAX_L2/HAX_FT_L2 give L^2,   *)
(* HAX_REPS gives that fourier h_ax represents the FT of h_ax).              *)
let SINC_BILINEAR = prove
 (`!a x:real g f2:real^1->complex. &0 <= a /\
     g IN lspace (:real^1) (&2) /\ f2 IN lspace (:real^1) (&2) /\
     (!k. schwartz k ==> integral (:real^1) (\z. f2 z * k(drop z)) =
                         integral (:real^1) (\z. g z * fourier k (drop z)))
     ==> lproduct (:real^1) g
           (\z. if abs(drop z) <= a then cexp(ii * Cx x * Cx(drop z)) else
             Cx(&0)) =
         lproduct (:real^1) f2
           (\z. fourier (\y. if abs y <= a then cexp(ii * Cx x * Cx y) else
             Cx(&0))
                        (drop z))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC PARSEVAL_L2_BILINEAR THEN
  ASM_REWRITE_TAC[HAX_L2] THEN CONJ_TAC THENL
   [MATCH_MP_TAC HAX_FT_L2 THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `k:real->complex` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`a:real`; `x:real`; `k:real->complex`] HAX_REPS) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Sinc-window algebra pieces for 286V line 3074-3079:                       *)
(*  SINC_CONST_ID: inv(sqrt2pi)*(inv(sqrt2pi)*(2 s)) = inv pi * s;           *)
(*  WINDOW_INT_LPRODUCT: INT_{[-a,a]} e^{-ixt} G = <G|h_ax>;                 *)
(*  SINC_LPRODUCT_REAL: <f2|fourier h_ax> = INT f2(t) * (real sinc value).   *)
(* ------------------------------------------------------------------------- *)

let SINC_CONST_ID = prove
 (`!s:real. inv(sqrt(&2 * pi)) * (inv(sqrt(&2 * pi)) * (&2 * s)) = inv pi * s`,
  GEN_TAC THEN
  SUBGOAL_THEN
    `inv(sqrt(&2 * pi)) * inv(sqrt(&2 * pi)) = inv(&2 * pi)` MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_INV_MUL] THEN AP_TERM_TAC THEN
    MP_TAC(SPEC `&2 * pi` SQRT_POW_2) THEN
    SIMP_TAC[REAL_LE_MUL; REAL_POS; PI_POS_LE; REAL_LT_IMP_LE; REAL_POW_2] THEN
    REWRITE_TAC[REAL_POW_2] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC;
    DISCH_TAC THEN
    SUBGOAL_THEN `inv(sqrt(&2 * pi)) * (inv(sqrt(&2 * pi)) * (&2 * s)) =
                  (inv(sqrt(&2 * pi)) * inv(sqrt(&2 * pi))) * &2 * s`
                    SUBST1_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN MP_TAC PI_POS THEN CONV_TAC REAL_FIELD]);;
let WINDOW_INT_LPRODUCT = prove
 (`!a x:real G:real^1->complex. &0 <= a
     ==> integral (IMAGE lift (real_interval[--a,a]))
           (\z. cexp(--(ii * Cx x * Cx(drop z))) * G z) =
         lproduct (:real^1) G
           (\z. if abs(drop z) <= a then cexp(ii * Cx x * Cx(drop z)) else
             Cx(&0))`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[LPRODUCT_G_HAX] THEN
  REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
  GEN_REWRITE_TAC (LAND_CONV) [GSYM INTEGRAL_RESTRICT_UNIV] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP] THEN
  REWRITE_TAC[REAL_ARITH `--a <= drop z /\ drop z <= a <=> abs(drop z) <= a`]
    THEN
  COND_CASES_TAC THEN REWRITE_TAC[COMPLEX_MUL_RZERO; COMPLEX_VEC_0] THEN
  SIMPLE_COMPLEX_ARITH_TAC);;
let SINC_LPRODUCT_REAL = prove
 (`!a x:real f2:real^1->complex. &0 <= a
     ==> lproduct (:real^1) f2
           (\z. fourier (\y. if abs y <= a then cexp(ii * Cx x * Cx y) else
             Cx(&0)) (drop z)) =
         integral (:real^1)
           (\z. f2 z * Cx(inv(sqrt(&2 * pi)) *
                         (&2 * sin(a * (x - drop z)) / (x - drop z))))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lproduct] THEN
  MATCH_MP_TAC INTEGRAL_SPIKE THEN
  EXISTS_TAC `{lift x}` THEN REWRITE_TAC[NEGLIGIBLE_SING] THEN
  X_GEN_TAC `z:real^1` THEN REWRITE_TAC[IN_DIFF; IN_UNIV; IN_SING] THEN
  DISCH_TAC THEN REWRITE_TAC[] THEN AP_TERM_TAC THEN
  SUBGOAL_THEN `~(x - drop z = &0)` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_SUB_0] THEN DISCH_TAC THEN
    UNDISCH_TAC `~(z:real^1 = lift x)` THEN REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM LIFT_DROP] THEN
      ASM_REWRITE_TAC[LIFT_DROP; LIFT_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`a:real`; `x:real`; `drop z`] CARLESON_HAX_FT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[GSYM CX_MUL; CNJ_CX]);;

(* ------------------------------------------------------------------------- *)
(* Integrability of the sinc integrand f2(t) * Cx(sin(a(x-t))/(x-t)): a.e.   *)
(* equal to a scalar multiple of the L^2 product f2 * cnj(fourier h_ax).     *)
(* ------------------------------------------------------------------------- *)

let SINC_INTEGRAND_INTEGRABLE = prove
 (`!a x:real f2:real^1->complex. &0 <= a /\ f2 IN lspace (:real^1) (&2)
     ==> (\z. f2 z * Cx(sin(a * (x - drop z)) / (x - drop z))) integrable_on
       (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\z:real^1. Cx(sqrt(&2 * pi) / &2) *
        (f2 z * cnj(fourier (\y. if abs y <= a then cexp(ii * Cx x * Cx y)
                                 else Cx(&0)) (drop z)))`;
    `\z:real^1. f2 z * Cx(sin(a * (x - drop z)) / (x - drop z))`;
    `{lift x}`; `(:real^1)`] INTEGRABLE_SPIKE) THEN
  REWRITE_TAC[NEGLIGIBLE_SING] THEN
  ANTS_TAC THENL
   [X_GEN_TAC `z:real^1` THEN REWRITE_TAC[IN_DIFF; IN_UNIV; IN_SING] THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `~(x - drop z = &0)` ASSUME_TAC THENL
     [REWRITE_TAC[REAL_SUB_0] THEN DISCH_TAC THEN
      UNDISCH_TAC `~(z:real^1 = lift x)` THEN REWRITE_TAC[] THEN
      REWRITE_TAC[GSYM LIFT_DROP] THEN
        ASM_REWRITE_TAC[LIFT_DROP; LIFT_EQ]; ALL_TAC] THEN
    REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`a:real`; `x:real`; `drop z`] CARLESON_HAX_FT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[GSYM CX_MUL; CNJ_CX] THEN
    SUBGOAL_THEN
     `Cx(sqrt(&2 * pi) / &2) *
      (f2 z * Cx(inv(sqrt(&2 * pi)) * (&2 * sin(a * (x - drop z)) / (x - drop
        z)))) =
      f2 z * Cx(sqrt(&2 * pi) / &2 *
                (inv(sqrt(&2 * pi)) * (&2 * sin(a * (x - drop z)) / (x - drop
                  z))))`
     SUBST1_TAC THENL
     [REWRITE_TAC[GSYM CX_MUL] THEN SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
    AP_TERM_TAC THEN AP_TERM_TAC THEN
    MP_TAC(SPEC `&2 * pi` SQRT_POS_LT) THEN
    ANTS_TAC THENL [MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
    ABBREV_TAC `q = sqrt(&2 * pi)` THEN DISCH_TAC THEN
    SUBGOAL_THEN `q * inv q = &1` MP_TAC THENL
     [MATCH_MP_TAC REAL_MUL_RINV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    CONV_TAC REAL_FIELD;
    DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN
    MATCH_MP_TAC L2_CNJ_PRODUCT_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC HAX_FT_L2 THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Fremlin 286V lines 3069-3079: the full sinc computation.  For f2          *)
(* representing the FT of G,                                                 *)
(*   (1/sqrt2pi) INT_{[-a,a]} e^{-ixt} G                                     *)
(*     = (1/pi) INT f2(t) sin(a(x-t))/(x-t) dt.                              *)
(* ------------------------------------------------------------------------- *)

let SINC_WINDOW_IDENTITY = prove
 (`!a x:real G f2:real^1->complex. &0 <= a /\
     G IN lspace (:real^1) (&2) /\ f2 IN lspace (:real^1) (&2) /\
     (!k. schwartz k ==> integral (:real^1) (\z. f2 z * k(drop z)) =
                         integral (:real^1) (\z. G z * fourier k (drop z)))
     ==> Cx(inv(sqrt(&2 * pi))) *
         integral (IMAGE lift (real_interval[--a,a]))
           (\z. cexp(--(ii * Cx x * Cx(drop z))) * G z) =
         Cx(inv pi) *
         integral (:real^1) (\z. f2 z * Cx(sin(a * (x - drop z)) / (x - drop
           z)))`,
REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[WINDOW_INT_LPRODUCT] THEN
  MP_TAC(ISPECL [`a:real`; `x:real`; `G:real^1->complex`; `f2:real^1->complex`]
    SINC_BILINEAR) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  ASM_SIMP_TAC[SINC_LPRODUCT_REAL] THEN
  (* pull constants into both integrals                                      *)
  SUBGOAL_THEN
   `Cx(inv(sqrt(&2 * pi))) *
    integral (:real^1)
      (\z. f2 z * Cx(inv(sqrt(&2 * pi)) *
                     (&2 * sin(a * (x - drop z)) / (x - drop z)))) =
    integral (:real^1)
      (\z. Cx(inv(sqrt(&2 * pi))) *
           (f2 z * Cx(inv(sqrt(&2 * pi)) *
                      (&2 * sin(a * (x - drop z)) / (x - drop z)))))`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
    SUBGOAL_THEN
     `(\z:real^1. f2 z * Cx(inv(sqrt(&2 * pi)) *
                    (&2 * sin(a * (x - drop z)) / (x - drop z)))) =
      (\z:real^1. Cx(inv(sqrt(&2 * pi)) * &2) *
                  (f2 z * Cx(sin(a * (x - drop z)) / (x - drop z))))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[GSYM CX_MUL] THEN
      SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN
    MATCH_MP_TAC SINC_INTEGRAND_INTEGRABLE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `Cx(inv pi) *
    integral (:real^1) (\z. f2 z * Cx(sin(a * (x - drop z)) / (x - drop z))) =
    integral (:real^1)
      (\z. Cx(inv pi) * (f2 z * Cx(sin(a * (x - drop z)) / (x - drop z))))`
   SUBST1_TAC THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
    MATCH_MP_TAC SINC_INTEGRAND_INTEGRABLE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `Cx(inv(sqrt(&2 * pi))) *
      (f2 z * Cx(inv(sqrt(&2 * pi)) * (&2 * sin(a * (x - drop z)) / (x - drop
        z)))) =
    f2 z * Cx(inv(sqrt(&2 * pi)) *
             (inv(sqrt(&2 * pi)) * (&2 * (sin(a * (x - drop z)) / (x - drop
               z)))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM CX_MUL] THEN SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `Cx(inv pi) * (f2 z * Cx(sin(a * (x - drop z)) / (x - drop z))) =
    f2 z * Cx(inv pi * (sin(a * (x - drop z)) / (x - drop z)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[GSYM CX_MUL] THEN SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[SINC_CONST_ID]);;

(* ------------------------------------------------------------------------- *)
(* L^2 is closed under reflection z |-> g(--z): measurability via            *)
(* MEASURABLE_ON_REFLECT + REFLECT_UNIV, norm^2-integrability via            *)
(* INTEGRABLE_REFLECT_GEN (IMAGE (--) (:real^1) = (:real^1)).                *)
(* ------------------------------------------------------------------------- *)

(* ------------------------------------------------------------------------- *)
(* Fremlin 284O(a)/284Ie (L^2 inverse-Fourier representative): for f_1 in    *)
(* L^2                                                                       *)
(* there is G in L^2 with lnorm G = lnorm f_1 such that f_1 REPRESENTS the   *)
(* Fourier transform of G, i.e. INT f_1 * h = INT G * fourier h for every    *)
(* Schwartz h.  (Equivalently, G represents the INVERSE Fourier transform of *)
(* f_1, 284Ie.)  This is the honest direction needed in 286V so that the     *)
(* window-limit f_2 of G lands on f_1 itself, not its reflection.            *)
(*                                                                           *)
(* Construction: g_0 = FOURIER_L2_REP of f_1 (g_0 represents FT of f_1);     *)
(* take                                                                      *)
(* G(z) = g_0(--z).  Then INT G * fourier h = INT g_0(--z) fourier h(z)      *)
(* = [reflect] INT g_0(w) fourier h(--w) = INT g_0 * fourier(reflect h)      *)
(* = [g_0 rep, reflect h Schwartz] INT f_1 * fourier(fourier(reflect h))     *)
(* = [DOUBLE_TRANSFORM: fourier(fourier k)(w) = k(--w)] INT f_1 * h.         *)
(* ------------------------------------------------------------------------- *)

let FOURIER_L2_REP_INV = prove
 (`!f1:real^1->complex. f1 IN lspace (:real^1) (&2)
     ==> ?G. G IN lspace (:real^1) (&2) /\
             lnorm (:real^1) (&2) G = lnorm (:real^1) (&2) f1 /\
             (!h. schwartz h
                  ==> integral (:real^1) (\z. f1 z * h(drop z)) =
                      integral (:real^1) (\z. G z * fourier h (drop z)))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_THEN `g0:real^1->complex` STRIP_ASSUME_TAC o
    MATCH_MP FOURIER_L2_REP) THEN
  EXISTS_TAC `\z:real^1. (g0:real^1->complex)(--z)` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC LSPACE_REFLECT THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[LNORM_REFLECT];
    X_GEN_TAC `h:real->complex` THEN DISCH_TAC THEN BETA_TAC THEN
    SUBGOAL_THEN
     `(\z:real^1. (g0:real^1->complex)(--z) * fourier h (drop z)) =
      (\z. (\w. (g0:real^1->complex) w * fourier h (drop(--w))) (--z))`
     SUBST1_TAC THENL [REWRITE_TAC[VECTOR_NEG_NEG]; ALL_TAC] THEN
    GEN_REWRITE_TAC (RAND_CONV) [INTEGRAL_REFLECT_GEN] THEN
    REWRITE_TAC[REFLECT_UNIV; DROP_NEG] THEN
    SUBGOAL_THEN
     `(\w:real^1. (g0:real^1->complex) w * fourier h (--(drop w))) =
      (\w. g0 w * fourier (\x. h(--x)) (drop w))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
      REWRITE_TAC[GSYM FOURIER_REFLECT]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `fourier (\x. (h:real->complex)(--x))`) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC SCHWARTZ_FOURIER THEN MATCH_MP_TAC SCHWARTZ_REFLECT THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[] THEN AP_TERM_TAC THEN
    MP_TAC(ISPECL [`\x. (h:real->complex)(--x)`;
      `--(drop z):real`] DOUBLE_TRANSFORM) THEN
    ANTS_TAC THENL [MATCH_MP_TAC SCHWARTZ_REFLECT THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[REAL_NEG_NEG] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[REAL_NEG_NEG]]);;

(* ------------------------------------------------------------------------- *)
(* 286U(c) DCT-dominator infrastructure (Fremlin 286D + 284F): the maximal   *)
(* function Ahat(G) of an L^2 function G, times a Schwartz weight, is        *)
(* L^1(R).                                                                   *)
(*                                                                           *)
(* Building block: Ahat(G) integrable on any interval [a,b] with             *)
(* int_{[a,b]} Ahat(G) <= C10 ||G||_2 sqrt(b-a), from CARLESON_286T_UNTRUNC  *)
(* at FF = real_interval[a,b] (muFF = b-a).                                  *)
(* ------------------------------------------------------------------------- *)

let CARLESON_AHAT_INTERVAL_BOUND = prove
 (`!(G:real->complex) C10 a b.
     &0 <= C10 /\ a <= b /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> carleson_Ahat G real_integrable_on real_interval[a,b] /\
         real_integral (real_interval[a,b]) (carleson_Ahat G)
           <= C10 * lnorm (:real^1) (&2) (\z. G(drop z)) * sqrt(b - a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`G:real->complex`; `real_interval[a,b]`; `C10:real`]
    CARLESON_286T_UNTRUNC) THEN
  ASM_SIMP_TAC[REAL_MEASURABLE_REAL_INTERVAL; REAL_MEASURE_REAL_INTERVAL] THEN
  ASM_SIMP_TAC[REAL_ARITH `a <= b ==> max (b - a) (&0) = b - a`]);;

(* Finite decomposition of [0, n+1] into unit intervals: for Ff integrable   *)
(* on                                                                        *)
(* each [k,k+1], int_{[0,n+1]} Ff = sum_{k=0}^{n} int_{[k,k+1]} Ff.          *)
(* (Iterated                                                                 *)
(* REAL_INTEGRAL_COMBINE.) Feeds the uniform bound on int_{[-N,N]}           *)
(* Ahat*weight.                                                              *)

let INTERVAL_UNIT_DECOMP = prove
 (`!Ff:real->real n.
     (!k. Ff real_integrable_on real_interval[&k, &k + &1])
     ==> Ff real_integrable_on real_interval[&0, &(n+1)] /\
         real_integral (real_interval[&0, &(n+1)]) Ff =
         sum (0..n) (\k. real_integral (real_interval[&k, &k + &1]) Ff)`,
  GEN_TAC THEN INDUCT_TAC THENL
   [REWRITE_TAC[ADD_CLAUSES; SUM_CLAUSES_NUMSEG] THEN
    CONV_TAC REAL_RAT_REDUCE_CONV THEN ASM_REWRITE_TAC[REAL_ADD_LID] THEN
    DISCH_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `0`) THEN
    CONV_TAC REAL_RAT_REDUCE_CONV THEN REWRITE_TAC[REAL_ADD_LID];
    DISCH_TAC THEN FIRST_X_ASSUM(fun th -> MP_TAC(MATCH_MP th (ASSUME
      `!k. (Ff:real->real) real_integrable_on real_interval[&k, &k + &1]`)))
        THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `&(SUC n + 1):real = &(n + 1) + &1` SUBST1_TAC THENL
     [REWRITE_TAC[GSYM REAL_OF_NUM_ADD; GSYM REAL_OF_NUM_SUC] THEN
       REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `Ff real_integrable_on real_interval[&0, &(n+1) + &1]`
     ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRABLE_COMBINE THEN EXISTS_TAC `&(n+1):real` THEN
      ASM_REWRITE_TAC[REAL_LE_ADDR; REAL_POS] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `n+1`) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[SUM_CLAUSES_NUMSEG; LE_0] THEN
    MP_TAC(ISPECL [`Ff:real->real`; `&0:real`; `&(n+1) + &1:real`;
      `&(n+1):real`]
      REAL_INTEGRAL_COMBINE) THEN
    ASM_REWRITE_TAC[REAL_LE_ADDR; REAL_POS] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    AP_TERM_TAC THEN
    SUBGOAL_THEN `&(SUC n):real = &(n+1) /\ (&(SUC n):real) + &1 = &(n+1) + &1`
      (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_SUC; REAL_OF_NUM_ADD] THEN
    REWRITE_TAC[ADD1] THEN REAL_ARITH_TAC]);;

(* Monotonicity of the real integral under an a.e.-inequality (f <= g off a  *)
(* negligible set), both integrable. Spike f to f' = g on s (else f): f' <=  *)
(* g                                                                         *)
(* everywhere, int f' = int f (REAL_INTEGRAL_SPIKE), f' integrable           *)
(* (REAL_INTEGRABLE_SPIKE_EQ), so REAL_INTEGRAL_LE applies.  Reusable: the   *)
(* maximal function Ahat is only >= 0 a.e. (junk where its window sup is     *)
(* +inf).                                                                    *)

let REAL_INTEGRAL_LE_AE = prove
 (`!f g s t.
     real_negligible s /\ f real_integrable_on t /\ g real_integrable_on t /\
     (!x. x IN (t DIFF s) ==> f x <= g x)
     ==> real_integral t f <= real_integral t g`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `real_integral t (f:real->real) =
    real_integral t (\x. if x IN s then g x else f x)`
   SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_SPIKE THEN EXISTS_TAC `s:real->bool` THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_DIFF] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`f:real->real`;
     `\x. if x IN s then (g:real->real) x else f x`;
                   `s:real->bool`;
                     `t:real->bool`] REAL_INTEGRABLE_SPIKE_EQ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_DIFF] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th] THEN ASM_REWRITE_TAC[])];
    ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN BETA_TAC THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[REAL_LE_REFL] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_DIFF]]);;

(* On a unit interval [k,k+1] (k a natural, so k >= 0), Ahat(G)*inv(1+y^2)   *)
(* is integrable: commute to inv(1+y^2)*Ahat(G) and use                      *)
(* REAL_INTEGRABLE_DECREASING_ PRODUCT (inv(1+y^2) is decreasing on [k,k+1], *)
(* Ahat(G) integrable there).                                                *)

let SHELL_INTEGRABLE_1 = prove
 (`!(G:real->complex) k.
     carleson_Ahat G real_integrable_on real_interval[&k, &k + &1]
     ==> (\y. carleson_Ahat G y * inv(&1 + y pow 2)) real_integrable_on
       real_interval[&k, &k + &1]`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\y. carleson_Ahat (G:real->complex) y * inv(&1 + y pow 2)) =
    (\y. (\x. inv(&1 + x pow 2)) y * carleson_Ahat G y)`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`carleson_Ahat (G:real->complex)`; `\x. inv(&1 + x pow 2)`;
                 `&k:real`;
                   `&k + &1:real`] REAL_INTEGRABLE_DECREASING_PRODUCT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MAP_EVERY X_GEN_TAC [`x:real`; `y:real`] THEN
  REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC REAL_LE_INV2 THEN CONJ_TAC THENL
   [MP_TAC(SPEC `x:real` REAL_LE_POW_2) THEN REAL_ARITH_TAC;
    REWRITE_TAC[REAL_LE_LADD] THEN MATCH_MP_TAC REAL_POW_LE2 THEN
    ASM_REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The 0-extension of a real square-integrable f on [-pi,pi], embedded via   *)
(* Cx,                                                                       *)
(* is in L^2(R): measurable (MEASURABLE_ON_UNIV + Cx-compose of the real-    *)
(* measurable f) and norm^2 = f^2.chi_[-pi,pi] integrable.                   *)
(* ------------------------------------------------------------------------- *)

let CARLESON_H1_BOUND = prove
 (`!(f:real->complex) C10.
     &0 <= C10 /\ (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> (!M. ?D. &0 <= D /\
            !m. real_integral (real_interval[--(&M),&M])
                  (\y. carleson_Ahat_trunc f (&m) y) <= D)`,
  REPEAT STRIP_TAC THEN
  EXISTS_TAC `C10 * lnorm (:real^1) (&2) (\z. (f:real->complex)(drop z)) *
    sqrt(&2 * &M)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC LNORM_POS_LE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC SQRT_POS_LE THEN REAL_ARITH_TAC];
    X_GEN_TAC `m:num` THEN
    MP_TAC(ISPECL [`f:real->complex`; `M:num`; `&m:real`; `C10:real`]
      CARLESON_286T_TRUNC_GENERAL) THEN
    ASM_REWRITE_TAC[REAL_POS]]);;

(* Ahat(G) >= 0 almost everywhere (for L^2 G under the 286T gate). Ahat is a *)
(* HOL sup of a NONNEGATIVE set, but that sup is junk where the window       *)
(* family is                                                                 *)
(* unbounded (Ahat = +inf), so nonnegativity is only a.e. Off the negligible *)
(* bad set {y | !k. ?m. k+1 < Ahat_trunc G m y}                              *)
(* (CARLESON_AHAT_TRUNC_BADSET_NEG,                                          *)
(* fed by CARLESON_H1_BOUND) the truncated family is bounded                 *)
(* (CARLESON_OFF_BADSET_BOUNDED) hence so is the window family               *)
(* (CARLESON_TRUNC_FAMILY_PLAIN_WINDOW_BOUND), so CARLESON_AHAT_POS gives >= *)
(* 0.                                                                        *)

let CARLESON_AHAT_NONNEG_AE = prove
 (`!(G:real->complex) C10.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> ?s. real_negligible s /\ !y. ~(y IN s) ==> &0 <= carleson_Ahat G y`,
  REPEAT STRIP_TAC THEN
  EXISTS_TAC `{y | !k:num. ?m:num. &k + &1 < carleson_Ahat_trunc
    (G:real->complex) (&m) y}` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CARLESON_AHAT_TRUNC_BADSET_NEG THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CARLESON_H1_BOUND THEN EXISTS_TAC `C10:real` THEN
      ASM_REWRITE_TAC[];
    X_GEN_TAC `y:real` THEN DISCH_TAC THEN
    MATCH_MP_TAC CARLESON_AHAT_POS THEN
    MATCH_MP_TAC CARLESON_TRUNC_FAMILY_PLAIN_WINDOW_BOUND THEN
      ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CARLESON_OFF_BADSET_BOUNDED THEN ASM_REWRITE_TAC[]]);;

(* Per-shell decay bound: int_{[k,k+1]} Ahat(G)*inv(1+y^2) <=                *)
(*   inv(1+k^2) * (C10 ||G||_2).  Pointwise inv(1+y^2) <= inv(1+k^2) a.e.    *)
(* (REAL_INTEGRAL_LE_AE off the Ahat-nonneg bad set) then int Ahat over the  *)
(* unit                                                                      *)
(* interval <= C10||G|| (CARLESON_AHAT_INTERVAL_BOUND, sqrt 1 = 1). Feeds    *)
(* the                                                                       *)
(* geometric shell-sum bound sum_k inv(1+k^2) < inf for the L^1 dominator.   *)

let CARLESON_AHAT_SHELL_BOUND = prove
 (`!(G:real->complex) C10 k.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> real_integral (real_interval[&k, &k + &1])
           (\y. carleson_Ahat G y * inv(&1 + y pow 2))
         <= inv(&1 + &k pow 2) * (C10 * lnorm (:real^1) (&2) (\z. G(drop z)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`G:real->complex`; `C10:real`] CARLESON_AHAT_NONNEG_AE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:real->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`G:real->complex`; `C10:real`; `&k:real`; `&k + &1:real`]
    CARLESON_AHAT_INTERVAL_BOUND) THEN
  ASM_REWRITE_TAC[REAL_LE_ADDR; REAL_POS] THEN
  REWRITE_TAC[REAL_ARITH `(&k + &1) - &k = &1`; SQRT_1; REAL_MUL_RID] THEN
  STRIP_TAC THEN
  TRANS_TAC REAL_LE_TRANS
   `real_integral (real_interval[&k, &k + &1])
                (\y. carleson_Ahat G y * inv(&1 + &k pow 2))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LE_AE THEN
    EXISTS_TAC `s:real->bool` THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC SHELL_INTEGRABLE_1 THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_INTEGRABLE_RMUL THEN ASM_REWRITE_TAC[ETA_AX];
      X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_DIFF; IN_REAL_INTERVAL] THEN
      STRIP_TAC THEN BETA_TAC THEN MATCH_MP_TAC REAL_LE_LMUL THEN
      CONJ_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC REAL_LE_INV2 THEN CONJ_TAC THENL
         [MP_TAC(SPEC `&k:real` REAL_LE_POW_2) THEN REAL_ARITH_TAC;
          REWRITE_TAC[REAL_LE_LADD] THEN MATCH_MP_TAC REAL_POW_LE2 THEN
          ASM_REWRITE_TAC[REAL_POS]]]];
    MP_TAC(ISPECL [`carleson_Ahat (G:real->complex)`; `inv(&1 + &k pow 2)`;
                   `real_interval[&k, &k + &1]`] REAL_INTEGRAL_RMUL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    GEN_REWRITE_TAC LAND_CONV [REAL_MUL_SYM] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [REWRITE_TAC[REAL_LE_INV_EQ] THEN
      MP_TAC(SPEC `&k:real` REAL_LE_POW_2) THEN REAL_ARITH_TAC;
      ASM_REWRITE_TAC[]]]);;

(* Geometric shell-sum ingredients for the L^1 dominator.  Per-shell weight  *)
(* telescopes: for k >= 1, inv(1+k^2) <= inv(k^2) <= 2(inv k - inv(k+1))     *)
(* (cross-multiplied k(k+1) <= 2(1+k^2)); summing k=1..n telescopes to <= 2, *)
(* and                                                                       *)
(* the k=0 term is 1, so sum_{k=0}^{n} inv(1+k^2) <= 3.                      *)

let SHELL_TERM_TELESCOPE = prove
 (`!k. 1 <= k ==> inv(&1 + &k pow 2) <= &2 * (inv(&k) - inv(&k + &1))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&1 <= &k` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[REAL_OF_NUM_LE]; ALL_TAC] THEN
  SUBGOAL_THEN
    `&0 < &k /\ &0 < &k + &1 /\ &0 < &1 + &k pow 2` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(MP_TAC(SPEC `&k:real` REAL_LE_POW_2)) THEN
     ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
    `&2 * (inv(&k) - inv(&k + &1)) = &2 / (&k * (&k + &1))` SUBST1_TAC THENL
   [REWRITE_TAC[real_div] THEN MATCH_MP_TAC(REAL_FIELD
      `&0 < a /\ &0 < b /\ b - a = &1 ==> &2 * (inv a - inv b) = &2 * inv(a *
        b)`) THEN
    ASM_REWRITE_TAC[] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &k * (&k + &1)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
  SUBGOAL_THEN
    `inv(&1 + &k pow 2) * (&k * (&k + &1)) =
     (&k * (&k + &1)) / (&1 + &k pow 2)`
   SUBST1_TAC THENL [REWRITE_TAC[real_div] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_LDIV_EQ] THEN
  REWRITE_TAC[REAL_POW_2; REAL_ADD_LDISTRIB; REAL_MUL_RID] THEN
  SUBGOAL_THEN `&k <= &k * &k` ASSUME_TAC THENL
   [GEN_REWRITE_TAC LAND_CONV [GSYM REAL_MUL_RID] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REAL_ARITH_TAC; ASM_REAL_ARITH_TAC]);;

let SHELL_SUM_BOUND = prove
 (`!n. sum (0..n) (\k. inv(&1 + &k pow 2)) <= &3`,
  GEN_TAC THEN DISJ_CASES_TAC(ARITH_RULE `n = 0 \/ 1 <= n`) THENL
   [ASM_REWRITE_TAC[SUM_SING_NUMSEG] THEN
     CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  ASM_SIMP_TAC[SUM_CLAUSES_LEFT; LE_0] THEN
  REWRITE_TAC[REAL_POW_2] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
  MATCH_MP_TAC(REAL_ARITH `s <= &2 ==> &1 + s <= &3`) THEN
    REWRITE_TAC[ADD_CLAUSES] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sum (1..n) (\k. &2 * (inv(&k) - inv(&k + &1)))` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE_NUMSEG THEN X_GEN_TAC `k:num` THEN STRIP_TAC THEN
    REWRITE_TAC[GSYM REAL_POW_2] THEN MATCH_MP_TAC SHELL_TERM_TELESCOPE THEN
      ASM_REWRITE_TAC[];
    REWRITE_TAC[SUM_LMUL] THEN
    SUBGOAL_THEN `sum (1..n) (\k. inv(&k) - inv(&k + &1)) =
      sum (1..n) (\k. (\j. inv(&j)) k - (\j. inv(&j)) (k + 1))` SUBST1_TAC
        THENL
     [MATCH_MP_TAC SUM_EQ_NUMSEG THEN REPEAT STRIP_TAC THEN
       REWRITE_TAC[GSYM REAL_OF_NUM_ADD];
      ALL_TAC] THEN
    REWRITE_TAC[SUM_DIFFS] THEN ASM_REWRITE_TAC[REAL_INV_1] THEN
    MATCH_MP_TAC(REAL_ARITH `&0 <= q ==> &2 * (&1 - q) <= &2`) THEN
    REWRITE_TAC[REAL_LE_INV_EQ; REAL_OF_NUM_ADD; REAL_POS]]);;

(* Uniform bound on the shell-sum decomposition of int_{[0,N+1]}             *)
(* Ahat(G)*inv(1+y^2):                                                       *)
(*   sum_{k=0}^{N} int_{[k,k+1]} Ahat(G)*inv(1+y^2) <= 3 (C10 ||G||_2).      *)
(* Each shell integral <= inv(1+k^2)(C10||G||) (CARLESON_AHAT_SHELL_BOUND);  *)
(* SUM_RMUL + SHELL_SUM_BOUND gives the geometric total <= 3(C10||G||).      *)

let AHAT_HALF_SUMBOUND = prove
 (`!(G:real->complex) C10 N.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> sum (0..N)
           (\k. real_integral (real_interval[&k, &k + &1])
                  (\y. carleson_Ahat G y * inv(&1 + y pow 2)))
         <= &3 * (C10 * lnorm (:real^1) (&2) (\z. G(drop z)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `&0 <= C10 * lnorm (:real^1) (&2) (\z. (G:real->complex)(drop z))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC LNORM_POS_LE THEN ASM_REWRITE_TAC[REAL_ARITH `&1 <= &2`];
    ALL_TAC] THEN
  TRANS_TAC REAL_LE_TRANS
   `sum (0..N) (\k. inv(&1 + &k pow 2) *
                (C10 * lnorm (:real^1) (&2) (\z. (G:real->complex)(drop z))))`
                  THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC SUM_LE_NUMSEG THEN X_GEN_TAC `k:num` THEN STRIP_TAC THEN
     BETA_TAC THEN
    MATCH_MP_TAC CARLESON_AHAT_SHELL_BOUND THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SUM_RMUL] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN ASM_REWRITE_TAC[SHELL_SUM_BOUND]]);;

(* Reflection of the maximal function: carleson_Ahat G (--y) =               *)
(* carleson_Ahat (\x. G(--x)) y. The window integral at [a,b] with frequency *)
(* --y                                                                       *)
(* over G equals the window integral at [--b,--a] with frequency y over the  *)
(* reflected function (substitution x |-> --x, INTEGRAL_REFLECT); the two    *)
(* sup-sets                                                                  *)
(* coincide under the bijection [a,b] <-> [--b,--a] on {a<=b}. Lets the      *)
(* negative                                                                  *)
(* half-line int_{[-N,0]} Ahat(G) be handled via Ahat of the reflected L^2   *)
(* function.                                                                 *)

let AHAT_WINDOW_REFLECT = prove
 (`!(G:real->complex) y a b.
     integral (IMAGE lift (real_interval[a,b]))
       (\x. cexp(--(ii * Cx(--y) * Cx(drop x))) * G(drop x)) =
     integral (IMAGE lift (real_interval[--b,--a]))
       (\x. cexp(--(ii * Cx y * Cx(drop x))) * (\t. G(--t))(drop x))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
  MP_TAC(ISPECL
   [`\x. cexp(--(ii * Cx y * Cx(drop x))) * (G:real->complex)(--(drop x))`;
    `lift(--b)`; `lift(--a)`] INTEGRAL_REFLECT) THEN
  REWRITE_TAC[DROP_NEG; LIFT_DROP; VECTOR_NEG_NEG; LIFT_NEG] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC INTEGRAL_EQ THEN X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
  REWRITE_TAC[REAL_NEG_NEG; VECTOR_NEG_NEG] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[CX_NEG] THEN SIMPLE_COMPLEX_ARITH_TAC);;

let CARLESON_AHAT_REFLECT = prove
 (`!(G:real->complex) y. carleson_Ahat G (--y) = carleson_Ahat (\x. G(--x)) y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[carleson_Ahat] THEN AP_TERM_TAC THEN
  GEN_REWRITE_TAC I [EXTENSION] THEN X_GEN_TAC `v:real` THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  SUBGOAL_THEN
   `!a b. integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx(--y) * Cx(drop x))) * (G:real->complex)(drop
              x)) =
          integral (IMAGE lift (real_interval[--b,--a]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * G(--drop x))`
   ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN
    MP_TAC(ISPECL [`G:real->complex`; `y:real`; `a:real`;
      `b:real`] AHAT_WINDOW_REFLECT) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  EQ_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `a:real` (X_CHOOSE_THEN
    `b:real` STRIP_ASSUME_TAC)) THENL
   [MAP_EVERY EXISTS_TAC [`--b:real`; `--a:real`] THEN
    (CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC]) THEN
    ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    ASM_REWRITE_TAC[REAL_NEG_NEG];
    MAP_EVERY EXISTS_TAC [`--b:real`; `--a:real`] THEN
    (CONJ_TAC THENL [ASM_REAL_ARITH_TAC; ALL_TAC]) THEN
    ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`--b:real`; `--a:real`]) THEN
    REWRITE_TAC[REAL_NEG_NEG] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
      REFL_TAC]);;

(* Positive half-line uniform bound: int_{[0,N+1]} Ahat(G)*inv(1+y^2) <=     *)
(* 3(C10||G||_2), combining the unit-interval decomposition with the         *)
(* geometric shell-sum bound.                                                *)

let AHAT_HALF_BOUND = prove
 (`!(G:real->complex) C10 N.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> real_integral (real_interval[&0, &(N+1)])
           (\y. carleson_Ahat G y * inv(&1 + y pow 2))
         <= &3 * (C10 * lnorm (:real^1) (&2) (\z. G(drop z)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`\y. carleson_Ahat (G:real->complex) y * inv(&1 + y pow 2)`;
    `N:num`]
    INTERVAL_UNIT_DECOMP) THEN
  ANTS_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC SHELL_INTEGRABLE_1 THEN
    MP_TAC(ISPECL [`G:real->complex`; `C10:real`; `&k:real`; `&k + &1:real`]
      CARLESON_AHAT_INTERVAL_BOUND) THEN
    ASM_REWRITE_TAC[REAL_LE_ADDR; REAL_POS] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC AHAT_HALF_SUMBOUND THEN ASM_REWRITE_TAC[]]);;

(* The maximal-function integrand is reflection-related: at frequency --y    *)
(* over G it equals the reflected function's at y (CARLESON_AHAT_REFLECT +   *)
(* (--y)^2 = y^2).                                                           *)

let AHAT_REFLECT_INTEGRAND = prove
 (`!(G:real->complex) y.
     carleson_Ahat G (--y) * inv(&1 + (--y) pow 2) =
     carleson_Ahat (\x. G(--x)) y * inv(&1 + y pow 2)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[CARLESON_AHAT_REFLECT] THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[REAL_POW_2] THEN REAL_ARITH_TAC);;

(* The negative half-line integral is the reflected function's positive      *)
(* half-line integral (substitution y |-> --y, REAL_INTEGRAL_REFLECT +       *)
(* double reflection).                                                       *)

let AHAT_NEGHALF_REFLECT_ID = prove
 (`!(G:real->complex) N.
     real_integral (real_interval[--(&(N+1)), &0])
       (\y. carleson_Ahat G y * inv(&1 + y pow 2)) =
     real_integral (real_interval[&0, &(N+1)])
       (\u. carleson_Ahat (\x. G(--x)) u * inv(&1 + u pow 2))`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`\u. carleson_Ahat (\x. (G:real->complex)(--x)) u * inv(&1 + u
    pow 2)`;
                 `&0:real`; `&(N+1):real`] REAL_INTEGRAL_REFLECT) THEN
  REWRITE_TAC[REAL_NEG_0] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_INTEGRAL_EQ THEN X_GEN_TAC `y:real` THEN
  REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`\x. (G:real->complex)(--x)`;
    `y:real`] CARLESON_AHAT_REFLECT) THEN
  REWRITE_TAC[REAL_NEG_NEG; ETA_AX] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[REAL_POW_2] THEN REAL_ARITH_TAC);;

(* Negative half-line uniform bound, from the positive one at the reflected  *)
(* L^2 function (LSPACE_REFLECT, LNORM_REFLECT: same L^2 norm).              *)

let AHAT_NEGHALF_BOUND = prove
 (`!(G:real->complex) C10 N.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> real_integral (real_interval[--(&(N+1)), &0])
           (\y. carleson_Ahat G y * inv(&1 + y pow 2))
         <= &3 * (C10 * lnorm (:real^1) (&2) (\z. G(drop z)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[AHAT_NEGHALF_REFLECT_ID] THEN
  SUBGOAL_THEN `lnorm (:real^1) (&2) (\z. (G:real->complex)(drop z)) =
                lnorm (:real^1) (&2) (\z. (\x. G(--x))(drop z))` SUBST1_TAC
                  THENL
   [REWRITE_TAC[DROP_NEG] THEN
    MP_TAC(ISPECL [`\z:real^1. (G:real->complex)(drop z)`;
      `&2`] LNORM_REFLECT) THEN
    REWRITE_TAC[DROP_NEG] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN REFL_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC AHAT_HALF_BOUND THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[DROP_NEG] THEN
  MP_TAC(ISPEC `\z:real^1. (G:real->complex)(drop z)` LSPACE_REFLECT) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[DROP_NEG]);;

(* Integrability of Ahat(G)*inv(1+y^2) on each half-interval [0,N+1] /       *)
(* [-(N+1),0] (first conjunct of INTERVAL_UNIT_DECOMP; negative half via     *)
(* reflection).                                                              *)

let AHAT_W_INTEG_POS = prove
 (`!(G:real->complex) C10 N.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> (\y. carleson_Ahat G y * inv(&1 + y pow 2)) real_integrable_on
       real_interval[&0, &(N+1)]`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`\y. carleson_Ahat (G:real->complex) y * inv(&1 + y pow 2)`;
    `N:num`]
    INTERVAL_UNIT_DECOMP) THEN
  ANTS_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC SHELL_INTEGRABLE_1 THEN
    MP_TAC(ISPECL [`G:real->complex`; `C10:real`; `&k:real`; `&k + &1:real`]
      CARLESON_AHAT_INTERVAL_BOUND) THEN
    ASM_REWRITE_TAC[REAL_LE_ADDR; REAL_POS] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
    STRIP_TAC THEN ASM_REWRITE_TAC[]]);;

let AHAT_W_INTEG_NEG = prove
 (`!(G:real->complex) C10 N.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> (\y. carleson_Ahat G y * inv(&1 + y pow 2)) real_integrable_on
       real_interval[--(&(N+1)), &0]`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  GEN_REWRITE_TAC I [GSYM REAL_INTEGRABLE_REFLECT] THEN
  REWRITE_TAC[REAL_NEG_0; REAL_NEG_NEG] THEN
  SUBGOAL_THEN
   `(\x. carleson_Ahat (G:real->complex) (--x) * inv(&1 + (--x) pow 2)) =
    (\x. carleson_Ahat (\t. G(--t)) x * inv(&1 + x pow 2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[AHAT_REFLECT_INTEGRAND];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\y. carleson_Ahat (\t. (G:real->complex)(--t)) y * inv(&1 + y
    pow 2)`; `N:num`]
    INTERVAL_UNIT_DECOMP) THEN
  ANTS_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC SHELL_INTEGRABLE_1 THEN
    MP_TAC(ISPECL [`\t. (G:real->complex)(--t)`; `C10:real`; `&k:real`;
      `&k + &1:real`]
      CARLESON_AHAT_INTERVAL_BOUND) THEN
    ASM_REWRITE_TAC[REAL_LE_ADDR; REAL_POS] THEN
    ANTS_TAC THENL
     [REWRITE_TAC[DROP_NEG] THEN
      MP_TAC(ISPEC `\z:real^1. (G:real->complex)(drop z)` LSPACE_REFLECT) THEN
      ASM_REWRITE_TAC[] THEN REWRITE_TAC[DROP_NEG];
      STRIP_TAC THEN ASM_REWRITE_TAC[]];
    STRIP_TAC THEN ASM_REWRITE_TAC[]]);;

(* Combined symmetric-interval bound: int_{[-(N+1),N+1]} Ahat G*inv(1+y^2)   *)
(* <= 6(C10||G||_2), via REAL_INTEGRAL_COMBINE at 0 + the two half-line      *)
(* bounds.                                                                   *)

let AHAT_MM_BOUND = prove
 (`!(G:real->complex) C10 N.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> real_integral (real_interval[--(&(N+1)), &(N+1)])
           (\y. carleson_Ahat G y * inv(&1 + y pow 2))
         <= &6 * (C10 * lnorm (:real^1) (&2) (\z. G(drop z)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`G:real->complex`; `C10:real`; `N:num`] AHAT_W_INTEG_NEG) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`G:real->complex`; `C10:real`; `N:num`] AHAT_W_INTEG_POS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`\y. carleson_Ahat (G:real->complex) y * inv(&1 + y pow 2)`;
                 `--(&(N+1)):real`; `&(N+1):real`;
                   `&0:real`] REAL_INTEGRAL_COMBINE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REAL_ARITH_TAC; REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRABLE_COMBINE THEN EXISTS_TAC `&0:real` THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THEN REAL_ARITH_TAC];
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC(REAL_ARITH `a <= &3 * m /\ b <= &3 * m ==> a + b <= &6 * m`)
      THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL [`G:real->complex`; `C10:real`;
       `N:num`] AHAT_NEGHALF_BOUND) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`G:real->complex`; `C10:real`;
        `N:num`] AHAT_HALF_BOUND) THEN
      ASM_REWRITE_TAC[]]]);;

(* The everywhere-nonneg version max(Ahat G,0)*inv(1+y^2) (needed for MCT:   *)
(* plain Ahat*inv is nonneg only a.e., breaking pointwise monotonicity) is   *)
(* integrable on [-(N+1),N+1] with the same 6(C10||G||) bound: it agrees     *)
(* a.e. with Ahat G*inv (CARLESON_AHAT_NONNEG_AE) so                         *)
(* REAL_INTEGRABLE_SPIKE_EQ / REAL_INTEGRAL_SPIKE transfer both              *)
(* integrability and the AHAT_MM_BOUND value.                                *)

let AHATPOS_MM = prove
 (`!(G:real->complex) C10 N.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> (\y. max (carleson_Ahat G y) (&0) * inv(&1 + y pow 2))
           real_integrable_on real_interval[--(&(N+1)), &(N+1)] /\
         real_integral (real_interval[--(&(N+1)), &(N+1)])
           (\y. max (carleson_Ahat G y) (&0) * inv(&1 + y pow 2))
         <= &6 * (C10 * lnorm (:real^1) (&2) (\z. G(drop z)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `(\y. carleson_Ahat (G:real->complex) y * inv(&1 + y pow 2))
      real_integrable_on real_interval[--(&(N+1)), &(N+1)]`
   ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_COMBINE THEN EXISTS_TAC `&0:real` THEN
    REPEAT CONJ_TAC THENL
     [REAL_ARITH_TAC; REAL_ARITH_TAC;
      MP_TAC(ISPECL [`G:real->complex`; `C10:real`;
        `N:num`] AHAT_W_INTEG_NEG) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`G:real->complex`; `C10:real`;
        `N:num`] AHAT_W_INTEG_POS) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`G:real->complex`; `C10:real`] CARLESON_AHAT_NONNEG_AE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:real->bool` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!y. y IN (real_interval[--(&(N+1)), &(N+1)] DIFF s)
        ==> max (carleson_Ahat (G:real->complex) y) (&0) * inv(&1 + y pow 2) =
            carleson_Ahat G y * inv(&1 + y pow 2)`
   ASSUME_TAC THENL
   [X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_DIFF] THEN STRIP_TAC THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[] THEN
      REAL_ARITH_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`\y. carleson_Ahat (G:real->complex) y * inv(&1 + y pow 2)`;
      `\y. max (carleson_Ahat (G:real->complex) y) (&0) * inv(&1 + y pow 2)`;
      `s:real->bool`;
        `real_interval[--(&(N+1)), &(N+1)]`] REAL_INTEGRABLE_SPIKE_EQ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[]];
    SUBGOAL_THEN
     `real_integral (real_interval[--(&(N+1)), &(N+1)])
        (\y. max (carleson_Ahat (G:real->complex) y) (&0) * inv(&1 + y pow 2))
          =
      real_integral (real_interval[--(&(N+1)), &(N+1)])
        (\y. carleson_Ahat G y * inv(&1 + y pow 2))`
     SUBST1_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_SPIKE THEN EXISTS_TAC `s:real->bool` THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_DIFF] THEN
      STRIP_TAC THEN CONV_TAC SYM_CONV THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_DIFF];
      MATCH_MP_TAC AHAT_MM_BOUND THEN ASM_REWRITE_TAC[]]]);;

(* Fremlin 286D conclusion (L^1 form): the maximal function Ahat(G) of an    *)
(* L^2 fn,                                                                   *)
(* weighted by inv(1+y^2), is integrable on the whole line.                  *)
(* Monotone-convergence                                                      *)
(* over the everywhere-nonneg truncations max(Ahat                           *)
(* G,0)*inv*chi_{[-(k+1),k+1]}:                                              *)
(* each integrable (AHATPOS_MM + REAL_INTEGRABLE_RESTRICT_UNIV), increasing  *)
(* (max>=0,                                                                  *)
(* interval nesting), converging pointwise (eventually inside the window,    *)
(* REAL_ARCH_SIMPLE), with truncated integrals bounded by 6(C10||G||)        *)
(* (AHATPOS_MM);                                                             *)
(* the limit is a.e. equal to Ahat G*inv(1+y^2) (SPIKE off the nonneg bad    *)
(* set).                                                                     *)

let AHAT_W_INTEGRABLE = prove
 (`!(G:real->complex) C10.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> (\y. carleson_Ahat G y * inv(&1 + y pow 2)) real_integrable_on
       (:real)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`G:real->complex`; `C10:real`] CARLESON_AHAT_NONNEG_AE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:real->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL
   [`\y. max (carleson_Ahat (G:real->complex) y) (&0) * inv(&1 + y pow 2)`;
    `\y. carleson_Ahat (G:real->complex) y * inv(&1 + y pow 2)`;
    `s:real->bool`; `(:real)`] REAL_INTEGRABLE_SPIKE_EQ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `y:real` THEN
     REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
    STRIP_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[] THEN
      REAL_ARITH_TAC;
    DISCH_THEN(SUBST1_TAC o SYM)] THEN
  SUBGOAL_THEN
   `(\y. max (carleson_Ahat (G:real->complex) y) (&0) * inv (&1 + y pow 2))
     real_integrable_on (:real) /\
    ((\k. real_integral (:real)
       (\y. if y IN real_interval[--(&(k+1)), &(k+1)]
            then max (carleson_Ahat (G:real->complex) y) (&0) * inv(&1 + y pow
              2) else &0))
     ---> real_integral (:real) (\y. max (carleson_Ahat (G:real->complex) y)
       (&0) * inv (&1 + y pow 2)))
     sequentially`
   (fun th -> REWRITE_TAC[CONJUNCT1 th]) THEN
  MATCH_MP_TAC REAL_MONOTONE_CONVERGENCE_INCREASING THEN
  REPEAT CONJ_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[REAL_INTEGRABLE_RESTRICT_UNIV] THEN
    MP_TAC(ISPECL [`G:real->complex`; `C10:real`; `k:num`] AHATPOS_MM) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    REWRITE_TAC[ADD1; GSYM REAL_OF_NUM_ADD] THEN
    COND_CASES_TAC THEN COND_CASES_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[IN_REAL_INTERVAL]) THENL
     [REWRITE_TAC[REAL_LE_REFL];
      ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [REAL_ARITH_TAC;
        REWRITE_TAC[REAL_LE_INV_EQ] THEN
          MP_TAC(SPEC `x:real` REAL_LE_POW_2) THEN REAL_ARITH_TAC];
      REWRITE_TAC[REAL_LE_REFL]];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    MP_TAC(SPEC `abs x` REAL_ARCH_SIMPLE) THEN
    DISCH_THEN(X_CHOOSE_TAC `K:num`) THEN
    MATCH_MP_TAC REALLIM_EVENTUALLY THEN
    REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `K:num` THEN
    X_GEN_TAC `k:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    COND_CASES_TAC THEN REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MP_TAC) THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
    SUBGOAL_THEN `&K <= &k` MP_TAC THENL
     [ASM_REWRITE_TAC[REAL_OF_NUM_LE]; ALL_TAC] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN ASM_REAL_ARITH_TAC;
    REWRITE_TAC[real_bounded; FORALL_IN_GSPEC; IN_UNIV] THEN
    EXISTS_TAC `&6 * (C10 * lnorm (:real^1) (&2) (\z. (G:real->complex)(drop
      z)))` THEN
    X_GEN_TAC `k:num` THEN
    REWRITE_TAC[REAL_INTEGRAL_RESTRICT_UNIV] THEN
    MP_TAC(ISPECL [`G:real->complex`; `C10:real`; `k:num`] AHATPOS_MM) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `&0 <= real_integral (real_interval [-- &(k + 1),&(k + 1)])
                    (\y. max (carleson_Ahat (G:real->complex) y) (&0) * inv (&1
                      + y pow 2))`
     ASSUME_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `y:real` THEN DISCH_TAC THEN MATCH_MP_TAC REAL_LE_MUL THEN
      CONJ_TAC THENL [REAL_ARITH_TAC;
        REWRITE_TAC[REAL_LE_INV_EQ] THEN
          MP_TAC(SPEC `y:real` REAL_LE_POW_2) THEN REAL_ARITH_TAC];
      ASM_REAL_ARITH_TAC]]);;

(* Auxiliary measurability facts for the 286U(c) DCT dominator.              *)

let ONE_PLUS_YSQ_MEASURABLE = prove
 (`(\y. &1 + y pow 2) real_measurable_on (:real)`,
  MATCH_MP_TAC REAL_MEASURABLE_ON_ADD THEN
    REWRITE_TAC[REAL_MEASURABLE_ON_CONST] THEN
  REWRITE_TAC[REAL_POW_2] THEN MATCH_MP_TAC REAL_MEASURABLE_ON_MUL THEN
  CONJ_TAC THEN
    MATCH_MP_TAC REAL_CONTINUOUS_IMP_REAL_MEASURABLE_ON_CLOSED_SUBSET THEN
  REWRITE_TAC[REAL_CONTINUOUS_ON_ID; REAL_CLOSED_UNIV]);;

(* Ahat(G) is real-measurable on R for L^2 G: Ahat G = (Ahat G *             *)
(* inv(1+y^2))*(1+y^2),                                                      *)
(* first factor measurable (AHAT_W_INTEGRABLE => integrable => measurable),  *)
(* second                                                                    *)
(* continuous.  (Avoids the L^1 hypothesis of CARLESON_AHAT_MEASURABLE.)     *)

let CARLESON_AHAT_MEASURABLE_L2 = prove
 (`!(G:real->complex) C10.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> carleson_Ahat G real_measurable_on (:real)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `carleson_Ahat (G:real->complex) =
    (\y. (carleson_Ahat G y * inv(&1 + y pow 2)) * (&1 + y pow 2))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN
    SUBGOAL_THEN `inv(&1 + x pow 2) * (&1 + x pow 2) = &1` SUBST1_TAC THENL
     [MATCH_MP_TAC REAL_MUL_LINV THEN MP_TAC(SPEC `x:real` REAL_LE_POW_2) THEN
       REAL_ARITH_TAC;
      REWRITE_TAC[REAL_MUL_RID]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURABLE_ON_MUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN
    MATCH_MP_TAC AHAT_W_INTEGRABLE THEN EXISTS_TAC `C10:real` THEN
      ASM_REWRITE_TAC[];
    REWRITE_TAC[ONE_PLUS_YSQ_MEASURABLE]]);;

(* norm o (Schwartz h) is real-measurable on R (h continuous by              *)
(* SCHWARTZ_CONT, norm continuous, composition measurable).                  *)

let NORM_SCHWARTZ_MEASURABLE = prove
 (`!h:real->complex. schwartz h ==> (\y. norm(h y)) real_measurable_on
   (:real)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `h:real->complex` SCHWARTZ_CONT) THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
  REWRITE_TAC[real_measurable_on; IMAGE_LIFT_UNIV; o_DEF] THEN
  MP_TAC(ISPECL [`\x:real^1. (h:real->complex)(drop x)`;
    `\w:real^2. lift(norm w)`]
    MEASURABLE_ON_COMPOSE_CONTINUOUS) THEN
  REWRITE_TAC[o_DEF] THEN
  DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[GSYM o_DEF; CONTINUOUS_ON_LIFT_NORM]]);;

(* Fremlin 284F / 286U(c) DCT dominator: for L^2 G and Schwartz h,           *)
(* Ahat(G)*|h| is                                                            *)
(* integrable on R. Schwartz decay norm(h y) <= C*inv(1+y^2)                 *)
(* (SCHWARTZ_DECAY_EXISTS)                                                   *)
(* dominates by C*(max(Ahat G,0)*inv(1+y^2)); the latter is Ahat G*inv a.e.  *)
(* (nonneg                                                                   *)
(* bad set) hence integrable (AHAT_W_INTEGRABLE + SPIKE).  Measurability of  *)
(* Ahat G*|h| = CARLESON_AHAT_MEASURABLE_L2 * NORM_SCHWARTZ_MEASURABLE (via  *)
(* max, since                                                                *)
(* Ahat is nonneg only a.e., use REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE at    *)
(* max(Ahat,0)).                                                             *)

let AHAT_SCHWARTZ_DOM = prove
 (`!(G:real->complex) (h:real->complex) C10.
     &0 <= C10 /\ (\z. G(drop z)) IN lspace (:real^1) (&2) /\ schwartz h /\
     (!(k:real->complex) GG. schwartz k /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat k)
            <= C10 * lnorm (:real^1) (&2) (\z. k(drop z)) * sqrt(real_measure
              GG))
     ==> (\y. carleson_Ahat G y * norm(h y)) real_integrable_on (:real)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPEC `h:real->complex` SCHWARTZ_DECAY_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `C:real` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`G:real->complex`; `C10:real`] CARLESON_AHAT_NONNEG_AE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:real->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL
   [`\y. max (carleson_Ahat (G:real->complex) y) (&0) * norm((h:real->complex)
     y)`;
    `\y. carleson_Ahat (G:real->complex) y * norm((h:real->complex) y)`;
    `s:real->bool`; `(:real)`] REAL_INTEGRABLE_SPIKE_EQ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `y:real` THEN
     REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
    STRIP_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[] THEN
      REAL_ARITH_TAC;
    DISCH_THEN(SUBST1_TAC o SYM)] THEN
  MATCH_MP_TAC REAL_MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `\y. C * (max (carleson_Ahat (G:real->complex) y) (&0) * inv(&1 +
    y pow 2))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC REAL_MEASURABLE_ON_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_MEASURABLE_ON_MAX THEN
       REWRITE_TAC[REAL_MEASURABLE_ON_CONST] THEN
      REWRITE_TAC[ETA_AX] THEN
      MATCH_MP_TAC CARLESON_AHAT_MEASURABLE_L2 THEN EXISTS_TAC `C10:real` THEN
        ASM_REWRITE_TAC[];
      MATCH_MP_TAC NORM_SCHWARTZ_MEASURABLE THEN ASM_REWRITE_TAC[]];
    MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
    MP_TAC(ISPECL [`\y. carleson_Ahat (G:real->complex) y * inv(&1 + y pow 2)`;
      `\y. max (carleson_Ahat (G:real->complex) y) (&0) * inv(&1 + y pow 2)`;
      `s:real->bool`; `(:real)`] REAL_INTEGRABLE_SPIKE_EQ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `y:real` THEN
       REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
      STRIP_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `y:real`) THEN ASM_REWRITE_TAC[] THEN
        REAL_ARITH_TAC;
      DISCH_THEN(SUBST1_TAC o SYM)] THEN
    MATCH_MP_TAC AHAT_W_INTEGRABLE THEN EXISTS_TAC `C10:real` THEN
      ASM_REWRITE_TAC[];
    X_GEN_TAC `y:real` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN
      `&0 <= max (carleson_Ahat (G:real->complex) y) (&0)` ASSUME_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_ABS_MUL] THEN
    SUBGOAL_THEN
      `abs(max (carleson_Ahat (G:real->complex) y) (&0)) = max (carleson_Ahat G
      y) (&0)`
     SUBST1_TAC THENL [ASM_REWRITE_TAC[REAL_ABS_REFL]; ALL_TAC] THEN
    REWRITE_TAC[REAL_ABS_NORM] THEN
    SUBGOAL_THEN
      `C * (max (carleson_Ahat (G:real->complex) y) (&0) * inv(&1 + y pow 2)) =
                  max (carleson_Ahat G y) (&0) * (C * inv(&1 + y pow 2))`
     SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[]]);;

(* For L^2 G and Schwartz h, G * (fourier h) is integrable on R (both in     *)
(* L^2, product dominated by norm(G)*norm(fourier h) which is L^1 by         *)
(* LSPACE_INTEGRABLE_PRODUCT). This is the "f * hhat integrable" fact        *)
(* closing the 286U(c) DCT+Fubini chain.                                     *)

let GFOURIERH_INTEGRABLE = prove
 (`!(G:real^1->complex) h:real->complex.
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> (\z. G z * fourier h (drop z)) integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z:real^1. fourier (h:real->complex) (drop z)) IN lspace (:real^1) (&2)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC SCHWARTZ_FOURIER_L2 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(G:real^1->complex) measurable_on (:real^1)` ASSUME_TAC THENL
   [UNDISCH_TAC `(G:real^1->complex) IN lspace (:real^1) (&2)` THEN
    REWRITE_TAC[lspace; IN_ELIM_THM] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z:real^1. fourier (h:real->complex) (drop z)) measurable_on (:real^1)`
   ASSUME_TAC THENL
   [UNDISCH_TAC `(\z:real^1. fourier (h:real->complex) (drop z)) IN lspace
     (:real^1) (&2)` THEN
    REWRITE_TAC[lspace; IN_ELIM_THM] THEN SIMP_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `\z:real^1. lift(norm((G:real^1->complex) z) * norm(fourier
    (h:real->complex) (drop z)))` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`(:real^1)`; `&2`; `&2`; `G:real^1->complex`;
                   `\z:real^1. fourier (h:real->complex) (drop z)`]
                     LSPACE_INTEGRABLE_PRODUCT) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC REAL_RAT_REDUCE_CONV;
    X_GEN_TAC `z:real^1` THEN
      REWRITE_TAC[IN_UNIV; LIFT_DROP; COMPLEX_NORM_MUL] THEN
    REWRITE_TAC[REAL_LE_REFL]]);;

(* Compactly-supported Schwartz L^2-approximation (284N with the support     *)
(* bound                                                                     *)
(* exposed): any L^2 function is L^2-approximable by a Schwartz function     *)
(* that is                                                                   *)
(* ALSO compactly supported (vanishes for abs x > c). Same construction as   *)
(* 284N                                                                      *)
(* (eta_R * P, supported in [-(|R|+2),|R|+2] via ETA_SUPPORT). The compact   *)
(* support                                                                   *)
(* upgrades L^2-convergence to L^1-convergence, giving uniform               *)
(* Fourier-transform                                                         *)
(* convergence -- the missing ingredient for fourier(L1capL2) in L^2.        *)
let LSPACE_APPROXIMATE_SCHWARTZ_CSUPP = prove
 (`!f:real^1->real^2. f IN lspace (:real^1) (&2)
     ==> !e. &0 < e
             ==> ?h c. schwartz h /\ (!x. abs x > c ==> h x = Cx(&0)) /\
                     lnorm (:real^1) (&2) (\x. f x - (\z. h(drop z)) x) < e`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`f:real^1->real^2`; `&2`; `e / &2`]
        LSPACE_APPROXIMATE_COMPACT_SUPPORT) THEN
  ASM_REWRITE_TAC[REAL_HALF; REAL_ARITH `&0 < &2`] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:real^1->real^2`
    (X_CHOOSE_THEN `R:real` STRIP_ASSUME_TAC)) THEN
  ABBREV_TAC `s = interval[lift(--(abs R + &2)), lift(abs R + &2)]` THEN
  SUBGOAL_THEN
   `bounded s /\ measurable s /\ lebesgue_measurable(s:real^1->bool)`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "s" THEN
    REWRITE_TAC[BOUNDED_INTERVAL; MEASURABLE_INTERVAL;
      LEBESGUE_MEASURABLE_INTERVAL];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`g:real^1->real^2`; `s:real^1->bool`; `&2`; `e / &2`]
        LSPACE_APPROXIMATE_VECTOR_POLYNOMIAL_FUNCTION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[REAL_HALF; REAL_ARITH `&1 <= &2`] THEN
    MATCH_MP_TAC LSPACE_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `P:real^1->real^2` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `\x. Cx(eta (abs R) x) * (P:real^1->real^2)(lift x)` THEN
  EXISTS_TAC `abs R + &2` THEN
  REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC ETAP_SCHWARTZ THEN ASM_REWRITE_TAC[REAL_ABS_POS];
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN
    SUBGOAL_THEN `eta (abs R) x = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC ETA_SUPPORT THEN ASM_REWRITE_TAC[REAL_ABS_POS] THEN
       ASM_REAL_ARITH_TAC;
      REWRITE_TAC[COMPLEX_MUL_LZERO]];
    ALL_TAC] THEN
  REWRITE_TAC[LIFT_DROP] THEN
  SUBGOAL_THEN
    `!x:real^1. Cx(eta (abs R) (drop x)) * (g:real^1->real^2) x = g x`
   ASSUME_TAC THENL
   [X_GEN_TAC `x:real^1` THEN
    ASM_CASES_TAC `norm(x:real^1) <= abs R` THENL
     [SUBGOAL_THEN `eta (abs R) (drop x) = &1` SUBST1_TAC THENL
       [MATCH_MP_TAC ETA_ONE THEN
        POP_ASSUM MP_TAC THEN REWRITE_TAC[NORM_REAL; GSYM drop] THEN
          REAL_ARITH_TAC;
        REWRITE_TAC[COMPLEX_MUL_LID]];
      SUBGOAL_THEN `(g:real^1->real^2) x = vec 0` SUBST1_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REAL_ARITH_TAC;
        REWRITE_TAC[COMPLEX_VEC_0; COMPLEX_MUL_RZERO]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x:real^1. Cx(eta (abs R) (drop x)) * (P:real^1->real^2) x) IN lspace
     (:real^1) (&2)`
   ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(\x:real^1. Cx(eta (abs R) (drop x)) * (P:real^1->real^2) x) =
      (\z:real^1. (\x. Cx(eta (abs R) x) * P(lift x))(drop z))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; LIFT_DROP];
      MATCH_MP_TAC SCHWARTZ_L2 THEN MATCH_MP_TAC ETAP_SCHWARTZ THEN
      ASM_REWRITE_TAC[REAL_ABS_POS]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LET_TRANS THEN
  EXISTS_TAC `lnorm (:real^1) (&2) (\x. f x - (g:real^1->real^2) x) +
              lnorm (:real^1) (&2) (\x. (g:real^1->real^2) x -
                                        Cx(eta (abs R) (drop x)) * P x)` THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\x. f x - Cx(eta (abs R) (drop x)) * (P:real^1->real^2) x) =
      (\x. (\x. f x - g x) x + (\x. g x - Cx(eta (abs R) (drop x)) * P x) x)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN VECTOR_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC LNORM_TRIANGLE THEN
    REWRITE_TAC[REAL_ARITH `&1 <= &2`; REAL_ARITH `&0 <= &2`] THEN
    CONJ_TAC THEN MATCH_MP_TAC LSPACE_SUB THEN
      ASM_REWRITE_TAC[REAL_ARITH `&0 <= &2`];
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `a < e / &2 /\ b <= e / &2 ==> a + b < e`) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `(\x. (g:real^1->real^2) x - Cx(eta (abs R) (drop x)) * P x) =
    (\x. Cx(eta (abs R) (drop x)) * ((g:real^1->real^2) x - P x))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
    REWRITE_TAC[COMPLEX_SUB_LDISTRIB] THEN ASM_REWRITE_TAC[] THEN
      VECTOR_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `lnorm (:real^1) (&2) (\x. Cx(eta (abs R) (drop x)) * ((g:real^1->real^2) x
     - P x)) =
    lnorm s (&2) (\x. Cx(eta (abs R) (drop x)) * ((g:real^1->real^2) x - P x))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC LNORM_SUPPORTED THEN REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
    X_GEN_TAC `x:real^1` THEN EXPAND_TAC "s" THEN
    REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP] THEN DISCH_TAC THEN
    SUBGOAL_THEN `eta (abs R) (drop x) = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC ETA_SUPPORT THEN
       REWRITE_TAC[REAL_ABS_POS; NORM_REAL; GSYM drop] THEN
      POP_ASSUM MP_TAC THEN REAL_ARITH_TAC;
      REWRITE_TAC[COMPLEX_VEC_0; COMPLEX_MUL_LZERO]];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `lnorm s (&2) (\x. (g:real^1->real^2) x - P x)` THEN
  ASM_SIMP_TAC[REAL_LT_IMP_LE] THEN
  MATCH_MP_TAC LNORM_MONO THEN EXISTS_TAC `{}:real^1->bool` THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; DIFF_EMPTY; REAL_ARITH `&0 <= &2`] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC LSPACE_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    SUBGOAL_THEN
     `(\x:real^1. Cx(eta (abs R) (drop x)) * ((g:real^1->real^2) x - P x)) =
      (\x. g x - Cx(eta (abs R) (drop x)) * P x)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
      REWRITE_TAC[COMPLEX_SUB_LDISTRIB] THEN ASM_REWRITE_TAC[] THEN
        VECTOR_ARITH_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_ARITH `&0 <= &2`];
    MATCH_MP_TAC LSPACE_SUB THEN ASM_REWRITE_TAC[REAL_ARITH `&0 <= &2`] THEN
    MATCH_MP_TAC LSPACE_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV];
    X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_LID] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
    MP_TAC(SPECL [`abs R`; `drop x`] ETA_BOUNDS) THEN REAL_ARITH_TAC]);;

(* Compactly-supported Schwartz sequence: for f in L^2 there is a sequence   *)
(* of                                                                        *)
(* Schwartz functions fn, each supported in [-(cn n),cn n], with ||f -       *)
(* fn||_2 <                                                                  *)
(* 1/(n+1). SKOLEM-wraps LSPACE_APPROXIMATE_SCHWARTZ_CSUPP (twice: fn and    *)
(* cn).                                                                      *)
let SCHWARTZ_SEQ_CSUPP = prove
 (`!f:real^1->real^2. f IN lspace (:real^1) (&2)
     ==> ?fn:num->real->complex. ?cn:num->real.
           (!n. schwartz (fn n)) /\
           (!n x. abs x > cn n ==> fn n x = Cx(&0)) /\
           (!n. lnorm (:real^1) (&2) (\z. f z - fn n (drop z)) < inv(&n +
             &1))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP LSPACE_APPROXIMATE_SCHWARTZ_CSUPP) THEN
  DISCH_THEN(MP_TAC o GEN `n:num` o SPEC `inv(&n + &1)`) THEN
  REWRITE_TAC[REAL_LT_INV_EQ] THEN
  SIMP_TAC[REAL_ARITH `&0 <= &n ==> &0 < &n + &1`; REAL_POS] THEN
  REWRITE_TAC[SKOLEM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `fn:num->real->complex` MP_TAC) THEN
  REWRITE_TAC[SKOLEM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `cn:num->real` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`fn:num->real->complex`; `cn:num->real`] THEN
  ASM_REWRITE_TAC[]);;

(* The smooth plateau times a Schwartz function is Schwartz: eta_R * psi is  *)
(* smooth                                                                    *)
(* (LEIBNIZ_CHAIN of eta's chain ETA_CHAIN with psi's Schwartz chain) and    *)
(* compactly                                                                 *)
(* supported (in [-(R+2),R+2], CHAIN_SUPPORT from ETA_SUPPORT), hence        *)
(* Schwartz                                                                  *)
(* (COMPACT_SUPPORT_SMOOTH_IMP_SCHWARTZ). Mirrors ETAP_SCHWARTZ but with a   *)
(* Schwartz                                                                  *)
(* factor instead of a polynomial. Used to force a COMMON compact support on *)
(* the                                                                       *)
(* Schwartz approximants of a compactly-supported L^2 function.              *)
let ETA_SCHWARTZ_MUL = prove
 (`!R (psi:real->complex). &0 <= R /\ schwartz psi
     ==> schwartz (\x. Cx(eta R x) * psi x)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `en:num->real->complex` STRIP_ASSUME_TAC o
    REWRITE_RULE[schwartz]) THEN
  X_CHOOSE_THEN
    `q:num->real->complex` STRIP_ASSUME_TAC (SPEC `R:real` ETA_CHAIN) THEN
  MP_TAC(ISPECL [`q:num->real->complex`;
    `en:num->real->complex`] LEIBNIZ_CHAIN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:num->real->complex` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
    `(\x. Cx (eta R x) * (psi:real->complex) x) = (s:num->real->complex) 0`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC COMPACT_SUPPORT_SMOOTH_IMP_SCHWARTZ THEN
  EXISTS_TAC `R + &2` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[real_gt] THEN MATCH_MP_TAC CHAIN_SUPPORT THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_REAL_ARITH_TAC;
    X_GEN_TAC `x:real` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eta R x = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC ETA_SUPPORT THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      REWRITE_TAC[CX_MUL; COMPLEX_MUL_LZERO; CX_INJ]]]);;

(* For G in L^2, the windowed function WG = G.chi[-n,n] is approximated in   *)
(* L^2 by a                                                                  *)
(* sequence of Schwartz functions ALL supported in the FIXED interval        *)
(* [-(n+2),n+2].                                                             *)
(* Construction: psi_k = eta_n . xi_k where xi_k -> WG in L^2                *)
(* (SCHWARTZ_SEQ_CSUPP)                                                      *)
(* and eta_n is the smooth plateau = 1 on [-n,n], supported in [-(n+2),n+2]. *)
(* Since                                                                     *)
(* eta_n = 1 on the support of WG, WG - eta_n.xi_k = eta_n.(WG - xi_k),      *)
(* whose L^2                                                                 *)
(* norm is <= ||WG - xi_k|| -> 0. The fixed common support is what lets the  *)
(* forward                                                                   *)
(* transforms fourier(psi_k) converge uniformly (via L^1) to fourier(WG).    *)
let FIXED_SUPP_SCHWARTZ_SEQ = prove
 (`!(G:real^1->complex) n.
     G IN lspace (:real^1) (&2)
     ==> ?psi:num->real->complex.
           (!k. schwartz (psi k)) /\
           (!k x. abs x > &n + &2 ==> psi k x = Cx(&0)) /\
           ((\k. lnorm (:real^1) (&2)
                 (\z. (if abs(drop z) <= &n then G z else vec 0) - psi k (drop
                   z))) ---> &0)
           sequentially`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `WG = \z:real^1. if abs(drop z) <= &n then (G:real^1->complex) z
    else vec 0` THEN
  SUBGOAL_THEN `(WG:real^1->complex) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [EXPAND_TAC "WG" THEN
    SUBGOAL_THEN
     `(\z:real^1. if abs(drop z) <= &n then (G:real^1->complex) z else vec 0) =
      (\z. if z IN {z | abs(drop z) <= &n} then G z else vec 0)`
     SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
    MATCH_MP_TAC TRUNC_IN_LSPACE THEN
      ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
    SUBGOAL_THEN
      `{z:real^1 | abs(drop z) <= &n} = interval[lift(--(&n)),lift(&n)]`
      SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_INTERVAL_1; LIFT_DROP] THEN
       GEN_TAC THEN REAL_ARITH_TAC;
      REWRITE_TAC[LEBESGUE_MEASURABLE_INTERVAL]]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP SCHWARTZ_SEQ_CSUPP) THEN
  DISCH_THEN(X_CHOOSE_THEN `xi:num->real->complex`
    (X_CHOOSE_THEN `cn:num->real` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
    `!k. (\z:real^1. (xi:num->real->complex) k (drop z)) IN lspace (:real^1)
    (&2)` ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
     ASM_SIMP_TAC[ETA_AX]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k. (\z:real^1. Cx(eta (&n) (drop z)) * (xi:num->real->complex) k (drop z))
     IN lspace (:real^1) (&2)`
   ASSUME_TAC THENL
   [GEN_TAC THEN
    SUBGOAL_THEN
     `(\z:real^1. Cx(eta (&n) (drop z)) * (xi:num->real->complex) k (drop z)) =
      (\z. (\x. Cx(eta (&n) x) * xi k x)(drop z))`
     SUBST1_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC SCHWARTZ_L2 THEN MATCH_MP_TAC ETA_SCHWARTZ_MUL THEN
      ASM_SIMP_TAC[REAL_POS; ETA_AX];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!(k:num) z:real^1.
        (WG:real^1->complex) z - Cx(eta (&n) (drop z)) *
          (xi:num->real->complex) k (drop z) =
        Cx(eta (&n) (drop z)) * (WG z - xi k (drop z))`
   ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[COMPLEX_SUB_LDISTRIB] THEN
    SUBGOAL_THEN `Cx(eta (&n) (drop z)) * (WG:real^1->complex) z = WG z`
     (fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "WG" THEN COND_CASES_TAC THENL
     [SUBGOAL_THEN `eta (&n) (drop z) = &1` SUBST1_TAC THENL
       [MATCH_MP_TAC ETA_ONE THEN
         ASM_REWRITE_TAC[]; REWRITE_TAC[COMPLEX_MUL_LID]];
      REWRITE_TAC[COMPLEX_VEC_0; COMPLEX_MUL_RZERO]]; ALL_TAC] THEN
  EXISTS_TAC `\k x. Cx(eta (&n) x) * (xi:num->real->complex) k x` THEN
  REPEAT CONJ_TAC THENL
   [GEN_TAC THEN REWRITE_TAC[] THEN MATCH_MP_TAC ETA_SCHWARTZ_MUL THEN
    ASM_REWRITE_TAC[REAL_POS; ETA_AX];
    MAP_EVERY X_GEN_TAC [`k:num`; `x:real`] THEN REWRITE_TAC[] THEN
      DISCH_TAC THEN
    SUBGOAL_THEN `eta (&n) x = &0` SUBST1_TAC THENL
     [MATCH_MP_TAC ETA_SUPPORT THEN REWRITE_TAC[REAL_POS] THEN
      POP_ASSUM MP_TAC THEN
        REWRITE_TAC[real_gt]; REWRITE_TAC[COMPLEX_MUL_LZERO]];
    REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `!z:real^1. (if abs(drop z) <= &n then (G:real^1->complex) z else vec 0) =
       WG z`
     (fun th -> REWRITE_TAC[th]) THENL
     [FIRST_ASSUM(SUBST1_TAC o GSYM) THEN REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN
    EXISTS_TAC `\k. lnorm (:real^1) (&2) (\z. (WG:real^1->complex) z -
      (xi:num->real->complex) k (drop z))` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
      X_GEN_TAC `k:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
      MATCH_MP_TAC(REAL_ARITH `&0 <= x /\ x <= y ==> abs x <= y`) THEN
        CONJ_TAC THENL
       [MATCH_MP_TAC LNORM_POS_LE THEN
         ASM_SIMP_TAC[LSPACE_SUB; REAL_POS]; ALL_TAC] THEN
      MATCH_MP_TAC LNORM_MONO THEN EXISTS_TAC `{}:real^1->bool` THEN
      REWRITE_TAC[NEGLIGIBLE_EMPTY; DIFF_EMPTY; IN_UNIV;
        REAL_ARITH `&0 <= &2`] THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC LSPACE_SUB THEN ASM_SIMP_TAC[REAL_POS]; ALL_TAC] THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC LSPACE_SUB THEN ASM_SIMP_TAC[REAL_POS]; ALL_TAC] THEN
       (X_GEN_TAC `z:real^1` THEN ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
        GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_LID] THEN
        MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
        MP_TAC(SPECL [`&n:real`; `drop(z:real^1)`] ETA_BOUNDS) THEN
          REAL_ARITH_TAC);
      MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN
      EXISTS_TAC `\k. inv(&k + &1)` THEN CONJ_TAC THENL
       [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
        X_GEN_TAC `k:num` THEN DISCH_TAC THEN
        MATCH_MP_TAC(REAL_ARITH `&0 <= x /\ x < y ==> abs x <= y`) THEN
          CONJ_TAC THENL
         [MATCH_MP_TAC LNORM_POS_LE THEN
           ASM_SIMP_TAC[LSPACE_SUB; REAL_POS]; ASM_SIMP_TAC[]];
        REWRITE_TAC[REALLIM_1_OVER_N_OFFSET]]]]);;

(* Complex conjugation preserves vector derivatives (cnj is R-linear): if f  *)
(* has                                                                       *)
(* vector derivative f' then cnj o f has vector derivative cnj f'. Via       *)
(* DIFF_CHAIN_                                                               *)
(* AT with the linear map cnj (HAS_DERIVATIVE_LINEAR + LINEAR_CNJ).          *)
let HAS_VECTOR_DERIVATIVE_CNJ = prove
 (`!(f:real^1->complex) f' x.
     (f has_vector_derivative f') (at x)
     ==> ((\z. cnj(f z)) has_vector_derivative cnj f') (at x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z:real^1. cnj((f:real^1->complex) z)) = cnj o f` SUBST1_TAC THENL
   [REWRITE_TAC[o_DEF]; ALL_TAC] THEN
  REWRITE_TAC[has_vector_derivative] THEN
  SUBGOAL_THEN
    `(\y:real^1. drop y % cnj (f':complex)) = cnj o (\y. drop y % f')`
    SUBST1_TAC THENL
   [REWRITE_TAC[o_DEF; FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[COMPLEX_CMUL; CNJ_MUL; CNJ_CX]; ALL_TAC] THEN
  MATCH_MP_TAC DIFF_CHAIN_AT THEN CONJ_TAC THENL
   [UNDISCH_TAC `((f:real^1->complex) has_vector_derivative f') (at x)` THEN
    REWRITE_TAC[has_vector_derivative];
    MATCH_MP_TAC HAS_DERIVATIVE_LINEAR THEN REWRITE_TAC[LINEAR_CNJ]]);;

(* Schwartz functions are closed under complex conjugation: the derivative   *)
(* chain of cnj o h is cnj of h's chain (HAS_VECTOR_DERIVATIVE_CNJ), and the *)
(* decay bounds are unchanged (norm(cnj z) = norm z).                        *)
let SCHWARTZ_CNJ = prove
 (`!h:real->complex. schwartz h ==> schwartz (\x. cnj(h x))`,
  GEN_TAC THEN REWRITE_TAC[schwartz] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num->real->complex` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `\n x. cnj((d:num->real->complex) n x)` THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[FUN_EQ_THM];
    MAP_EVERY X_GEN_TAC [`n:num`; `x:real`] THEN
    MP_TAC(ISPECL
     [`\z:real^1. (d:num->real->complex) n (drop z)`;
      `(d:num->real->complex) (SUC n) x`;
        `lift x`] HAS_VECTOR_DERIVATIVE_CNJ) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`k:num`; `m:num`] THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`k:num`; `m:num`]) THEN
    REWRITE_TAC[COMPLEX_NORM_CNJ]]);;

(* Plain (non-cnj) product integrability: for g in L^2 and h Schwartz, g(z)  *)
(* h(z) is                                                                   *)
(* integrable on R. Via the cnj trick: g*h = g*cnj(cnj h), and cnj o h is in *)
(* L^2                                                                       *)
(* (LSPACE_CNJ + SCHWARTZ_L2), so L2_CNJ_PRODUCT_INTEGRABLE applies.         *)
let L2_SCHWARTZ_PRODUCT_INTEGRABLE = prove
 (`!(g:real^1->complex) (h:real->complex).
     g IN lspace (:real^1) (&2) /\ schwartz h
     ==> (\z. g z * h(drop z)) integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z:real^1. cnj((h:real->complex)(drop z))) IN lspace (:real^1) (&2)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC LSPACE_CNJ THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
     ASM_REWRITE_TAC[ETA_AX]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(:real^1)`; `g:real^1->complex`;
    `\z:real^1. cnj((h:real->complex)(drop z))`]
    L2_CNJ_PRODUCT_INTEGRABLE) THEN
  ASM_REWRITE_TAC[CNJ_CNJ]);;

(* L^p membership is invariant under a.e.-equality: if g in L^p and g = f    *)
(* a.e.,                                                                     *)
(* then f in L^p. Measurability + norm^p-integrability both transfer via the *)
(* spike                                                                     *)
(* lemmas (MEASURABLE_ON_SPIKE / INTEGRABLE_SPIKE on the null disagreement   *)
(* set).                                                                     *)
(* Used to pass "in L^2" across the a.e.-limit identifications in the        *)
(* 286U(c)                                                                   *)
(* value-identification.                                                     *)
let LSPACE_AE_CONG = prove
 (`!(f:real^1->real^2) g p s.
     g IN lspace s p /\ negligible {x:real^1 | ~(g x = f x)}
     ==> f IN lspace s p`,
  REPEAT GEN_TAC THEN REWRITE_TAC[lspace; IN_ELIM_THM] THEN STRIP_TAC THEN
    CONJ_TAC THENL
   [UNDISCH_TAC `(g:real^1->real^2) measurable_on s` THEN
    MATCH_MP_TAC MEASURABLE_ON_SPIKE THEN
    EXISTS_TAC `{x:real^1 | ~((g:real^1->real^2) x = f x)}` THEN
    ASM_REWRITE_TAC[IN_DIFF; IN_ELIM_THM] THEN
    REPEAT STRIP_TAC THEN CONV_TAC SYM_CONV THEN ASM_REWRITE_TAC[];
    UNDISCH_TAC `(\x:real^1. lift(norm((g:real^1->real^2) x) rpow p))
      integrable_on s` THEN
    MATCH_MP_TAC INTEGRABLE_SPIKE THEN
    EXISTS_TAC `{x:real^1 | ~((g:real^1->real^2) x = f x)}` THEN
    ASM_REWRITE_TAC[IN_DIFF; IN_ELIM_THM] THEN
    REPEAT STRIP_TAC THEN AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      AP_TERM_TAC THEN
    ASM_REWRITE_TAC[]]);;

(* The indicator of a compact interval is in L^2 (bounded, finite measure):  *)
(* measurable (MEASURABLE_ON_CASES) with norm^2-integrand = the interval     *)
(* indicator                                                                 *)
(* (finite-measure constant, INTEGRABLE_RESTRICT_UNIV + INTEGRABLE_CONST). A *)
(* test                                                                      *)
(* function for the subinterval-integral bridge in the L^2 test-uniqueness   *)
(* argument.                                                                 *)
let INDICATOR_INTERVAL_L2 = prove
 (`!a b:real. (\z:real^1. if z IN interval[lift a, lift b] then Cx(&1) else
   Cx(&0))
              IN lspace (:real^1) (&2)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[lspace; IN_ELIM_THM] THEN CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_CASES THEN
    REWRITE_TAC[SET_RULE `{z | z IN s} = s`; LEBESGUE_MEASURABLE_INTERVAL;
                MEASURABLE_ON_CONST];
    SUBGOAL_THEN
     `(\z:real^1. lift(norm(if z IN interval[lift a,lift b] then Cx(&1) else
       Cx(&0)) rpow &2)) =
      (\z:real^1. if z IN interval[lift a,lift b] then lift(&1) else vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN COND_CASES_TAC THEN
      REWRITE_TAC[COMPLEX_NORM_CX; REAL_ABS_NUM] THENL
       [REWRITE_TAC[RPOW_ONE];
        SIMP_TAC[RPOW_ZERO; REAL_OF_NUM_EQ; ARITH_EQ; LIFT_NUM]]; ALL_TAC] THEN
    REWRITE_TAC[INTEGRABLE_RESTRICT_UNIV; INTEGRABLE_CONST]]);;

(* L^2-to-L^1 bound for compactly-supported functions: if d in L^2 vanishes  *)
(* for                                                                       *)
(* abs x > c, then INT norm(d) <= K ||d||_2 for a constant K (=              *)
(* ||chi[-c-1,c+1]||_2,                                                      *)
(* finite). HOELDER (p=q=2) with the second factor the indicator of the      *)
(* support                                                                   *)
(* interval; norm(d) = norm(d)*norm(chi) since d = 0 off the interval. Turns *)
(* L^2-convergence of compactly-supported functions into L^1-convergence.    *)
let PLANCHEREL_L2_REP_ISOMETRY = prove
 (`!(a:real^1->complex) b ga gb.
     a IN lspace (:real^1) (&2) /\ b IN lspace (:real^1) (&2) /\
     ga IN lspace (:real^1) (&2) /\ gb IN lspace (:real^1) (&2) /\
     (!h. schwartz h ==> integral (:real^1) (\z. ga z * h(drop z)) =
                         integral (:real^1) (\z. a z * fourier h (drop z))) /\
     (!h. schwartz h ==> integral (:real^1) (\z. gb z * h(drop z)) =
                         integral (:real^1) (\z. b z * fourier h (drop z)))
     ==> lnorm (:real^1) (&2) (\z. ga z - gb z) = lnorm (:real^1) (&2) (\z. a z
       - b z)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `\z:real^1. (a:real^1->complex) z - b z` FOURIER_L2_REP) THEN
  ASM_SIMP_TAC[LSPACE_SUB; REAL_POS] THEN
  DISCH_THEN(X_CHOOSE_THEN `g':real^1->complex` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `lnorm (:real^1) (&2) (\z. (ga:real^1->complex) z - gb z) = lnorm (:real^1)
     (&2) (g':real^1->complex)`
   (fun th -> ASM_REWRITE_TAC[th]) THEN
  MATCH_MP_TAC LNORM_EQ_AE THEN
  MATCH_MP_TAC FOURIER_L2_UNIQUE THEN
  ASM_SIMP_TAC[LSPACE_SUB; REAL_POS] THEN
  X_GEN_TAC `h:real->complex` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `integral (:real^1) (\z. ((ga:real^1->complex) z - gb z) *
     (h:real->complex)(drop z)) =
    integral (:real^1) (\z. ((a:real^1->complex) z - b z) * fourier h (drop
      z))`
   (fun th -> ASM_SIMP_TAC[th]) THEN
  SUBGOAL_THEN
   `(\z. ((ga:real^1->complex) z - gb z) * (h:real->complex)(drop z)) =
    (\z. ga z * h(drop z) - gb z * h(drop z))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\z. ((a:real^1->complex) z - b z) * fourier h (drop z)) =
    (\z. a z * fourier h(drop z) - b z * fourier h(drop z))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `integral (:real^1) (\z. (ga:real^1->complex) z * (h:real->complex)(drop z)
     - gb z * h(drop z)) =
    integral (:real^1) (\z. ga z * h(drop z)) - integral (:real^1) (\z. gb z *
      h(drop z))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC INTEGRAL_SUB THEN CONJ_TAC THEN
    MATCH_MP_TAC L2_SCHWARTZ_PRODUCT_INTEGRABLE THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `integral (:real^1) (\z. (a:real^1->complex) z * fourier h(drop z) - b z *
     fourier h(drop z)) =
    integral (:real^1) (\z. a z * fourier h(drop z)) - integral (:real^1) (\z.
      b z * fourier h(drop z))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC INTEGRAL_SUB THEN CONJ_TAC THEN
    MATCH_MP_TAC GFOURIERH_INTEGRABLE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* reusable Cx if-then-else real-integral bridge: integral over R of the     *)
(* Cx-valued interval-restricted g equals Cx of the real interval-integral.  *)
(* (The Cx-analog of CARLESON_INTERVAL_REAL_BRIDGE; used for the 2D-box      *)
(* Cx-pull                                                                   *)
(* in the w-outer side of MNF_FOURIER_BOX.)                                  *)
(* ------------------------------------------------------------------------- *)
let LINEAR_CX_DROP = prove
 (`linear (\v:real^1. Cx(drop v))`,
  REWRITE_TAC[linear; DROP_ADD; DROP_CMUL; CX_ADD; CX_MUL] THEN
  REWRITE_TAC[COMPLEX_CMUL; GSYM CX_MUL] THEN REPEAT STRIP_TAC THEN
  SIMPLE_COMPLEX_ARITH_TAC);;

let LIFT_RESTRICT_INTEGRABLE = prove
 (`!(g:real->real) c d. g real_integrable_on real_interval[c,d]
   ==> (\t:real^1. if c <= drop t /\ drop t <= d then lift(g(drop t)) else vec
     0)
       integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\t:real^1. if c <= drop t /\ drop t <= d then lift(g(drop t)) else vec 0)
     =
    (\t:real^1. if t IN interval[lift c,lift d] then (lift o g o drop) t else
      vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN GEN_TAC THEN
    REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP]; ALL_TAC] THEN
  REWRITE_TAC[INTEGRABLE_RESTRICT_UNIV] THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[REAL_INTEGRABLE_ON]) THEN
  REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; ETA_AX]);;

let CX_INTERVAL_REAL_BRIDGE = prove
 (`!(g:real->real) c d. g real_integrable_on real_interval[c,d]
   ==> integral (:real^1)
         (\t. if c <= drop t /\ drop t <= d then Cx(g(drop t)) else vec 0) =
       Cx(real_integral (real_interval[c,d]) g)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\t:real^1. if c <= drop t /\ drop t <= d then Cx(g(drop t)) else vec 0) =
    (\v:real^1. Cx(drop v)) o (\t:real^1. if c <= drop t /\ drop t <= d then
      lift(g(drop t)) else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[LIFT_DROP; DROP_VEC; COMPLEX_VEC_0];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\t:real^1. if c <= drop t /\ drop t <= d then lift(g(drop t)) else vec 0`;
    `(:real^1)`; `\v:real^1. Cx(drop v)`] INTEGRAL_LINEAR) THEN
  ASM_SIMP_TAC[LINEAR_CX_DROP; LIFT_RESTRICT_INTEGRABLE] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`g:real->real`; `c:real`;
    `d:real`] CARLESON_INTERVAL_REAL_BRIDGE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[LIFT_DROP]);;

(* ------------------------------------------------------------------------- *)
(* S6 keystone step (c), pieces of MNF_FOURIER_BOX (box-Fubini identity).    *)
(* ------------------------------------------------------------------------- *)

(* inner w-integral of the box kernel at fixed (a,b) (a<>0):                 *)
(*   integral_w Cx(inv a)*(cexp(-i(-x)w)*fhat(w))*Cx(theta'_zab w)           *)
(*   = Cx(inv a)*Cx sqrt2pi * V_ab,  V_ab = fourier(hhat.theta'_zab)(-x).    *)
(* INTEGRAL_COMPLEX_LMUL (pull Cx inv a) + FOURIER_INNER_INTEGRAL; integrand *)
(* absint via FOURIER_MODULATION_ABSINT + CARLESON_FHAT_THETA'_ABSINT.       *)
let MNF_INNER_W_EVAL = prove
 (`!(h:real->complex) z0 x a b. schwartz h /\ ~(a = &0)
   ==> integral (:real^1)
         (\w. Cx(inv a) *
              (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w)) *
              Cx(carleson_theta' z0 a b (drop w))) =
       Cx(inv a) * Cx(sqrt(&2*pi)) * fourier (\w. fourier h w *
         Cx(carleson_theta' z0 a b w)) (--x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!w:real^1. Cx(inv a) *
            (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w)) *
            Cx(carleson_theta' z0 a b (drop w)) =
            Cx(inv a) * (cexp(--(ii * Cx(--x) * Cx(drop w))) *
              (\u. fourier (h:real->complex) u * Cx(carleson_theta' z0 a b
                u))(drop w))`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN REWRITE_TAC[] THEN SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\w:real^1. cexp(--(ii * Cx(--x) * Cx(drop w))) * (\u. fourier
     (h:real->complex) u * Cx(carleson_theta' z0 a b u))(drop w)`;
    `(:real^1)`; `Cx(inv a)`] INTEGRAL_COMPLEX_LMUL) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC FOURIER_MODULATION_ABSINT THEN
    MP_TAC(ISPECL [`h:real->complex`; `z0:real`; `a:real`;
      `b:real`] CARLESON_FHAT_THETA'_ABSINT) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[GSYM COMPLEX_MUL_ASSOC] THEN AP_TERM_TAC THEN
  MP_TAC(ISPECL [`\u. fourier (h:real->complex) u * Cx(carleson_theta' z0 a b
    u)`; `--x:real`]
    INNER_INT_FOURIER) THEN
  REWRITE_TAC[]);;

(* (a,b)-OUTER side of the FUBINI swap: integral_ab(integral_w K) evaluates  *)
(* (MNF_INNER_W_EVAL on each box slice, off-box integral of vec0 = 0) to the *)
(* box integral of Cx(inv a)*Cx sqrt2pi * V_ab.                              *)
let MNF_SIDE_AB = prove
 (`!(h:real->complex) z0 x n. schwartz h
   ==> integral (:real^(1,1)finite_sum)
         (\ab. integral (:real^1)
            (\w. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                    &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
                 then Cx(inv(drop(fstcart ab))) *
                      (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop
                        w)) *
                      Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart
                        ab)) (drop w))
                 else vec 0)) =
       integral (:real^(1,1)finite_sum)
         (\ab. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                  &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then Cx(inv(drop(fstcart ab))) * Cx(sqrt(&2*pi)) *
                    fourier (\w. fourier h w * Cx(carleson_theta' z0
                      (drop(fstcart ab)) (drop(sndcart ab)) w)) (--x)
               else vec 0)`,
  REPEAT STRIP_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
  X_GEN_TAC `ab:real^(1,1)finite_sum` THEN
  COND_CASES_TAC THEN REWRITE_TAC[INTEGRAL_0] THEN
  MP_TAC(ISPECL [`h:real->complex`; `z0:real`; `x:real`;
    `drop(fstcart(ab:real^(1,1)finite_sum))`;
                 `drop(sndcart(ab:real^(1,1)finite_sum))`] MNF_INNER_W_EVAL)
                   THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL [ASM_REAL_ARITH_TAC; DISCH_THEN
    ACCEPT_TAC]);;

(* w-outer inner-b slice: at fixed a=drop x in [1,2], the b-line integral of *)
(* the                                                                       *)
(* box-restricted Cx(inv a)*Cx(theta'_zab w) collapses                       *)
(* (CX_INTERVAL_REAL_BRIDGE + pull                                           *)
(* the real scalar inv a) to Cx(inv a * int_[0,n] theta'_zab w). (Extracted  *)
(* so the                                                                    *)
(* MNF_ABBOX_CX_NESTED per-x slice is a single MATCH_MP_TAC, avoiding deep   *)
(* THENL.)                                                                   *)
let MNF_INNER_B_EVAL = prove
 (`!z0 w n x. &1 <= drop x /\ drop x <= &2 ==>
    integral(:real^1)(\y. if &1 <= drop x /\ drop x <= &2 /\ &0 <= drop y /\
      drop y <= &n
                          then Cx(inv(drop x)) * Cx(carleson_theta' z0 (drop
                            x)(drop y) w) else vec 0)
    = Cx(inv(drop x) * real_integral(real_interval[&0,&n])(\b. carleson_theta'
      z0 (drop x) b w))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\y. if &1 <= drop x /\ drop x <= &2 /\ &0 <= drop y /\ drop y <= &n
         then Cx(inv(drop x)) * Cx(carleson_theta' z0 (drop x)(drop y) w) else
           vec 0) =
    (\y. if &0 <= drop y /\ drop y <= &n
         then Cx(inv(drop x) * carleson_theta' z0 (drop x)(drop y) w) else vec
           0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `y:real^1` THEN
    REWRITE_TAC[GSYM CX_MUL] THEN
    SUBGOAL_THEN
     `(&1 <= drop x /\ drop x <= &2 /\ &0 <= drop(y:real^1) /\ drop y <= &n)
       <=>
      (&0 <= drop y /\ drop y <= &n)` SUBST1_TAC THENL
     [ASM_REAL_ARITH_TAC; REFL_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\b. inv(drop(x:real^1)) * carleson_theta' z0 (drop x) b w`;
                 `&0:real`; `&n:real`] CX_INTERVAL_REAL_BRIDGE) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
     REWRITE_TAC[THETA'_BETA_INTEGRABLE]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o BETA_RULE) THEN
  AP_TERM_TAC THEN MATCH_MP_TAC REAL_INTEGRAL_LMUL THEN
    REWRITE_TAC[THETA'_BETA_INTEGRABLE]);;

(* fs-type box integral of Cx(inv a)*Cx(theta'_zab w) = Cx( int_[1,2](1/a)   *)
(* int_[0,n] theta' ).                                                       *)
(* Core of the w-outer side of MNF_FOURIER_BOX. Inner (a,b)-Fubini           *)
(* [MNF_ABKERNEL_FS_ABSINT]                                                  *)
(* -> per-x slice via MNF_INNER_B_EVAL (x in [1,2]) / INTEGRAL_0 (x off box) *)
(* -> outer-a CX                                                             *)
(* bridge [THETA'_A_ITERATE_INTEGRABLE].                                     *)
let MNF_ABBOX_CX_NESTED = prove
 (`!z0:real w:real n:num.
     integral (:real^(1,1)finite_sum)
       (\ab. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
             then Cx(inv(drop(fstcart ab))) * Cx(carleson_theta' z0
               (drop(fstcart ab)) (drop(sndcart ab)) w) else vec 0) =
     Cx(real_integral (real_interval[&1,&2])
          (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
            carleson_theta' z0 a b w)))`,
  REPEAT GEN_TAC THEN
  MP_TAC(MATCH_MP FUBINI_INTEGRAL (SPECL [`z0:real`;`w:real`;`n:num`]
    MNF_ABKERNEL_FS_ABSINT)) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN DISCH_THEN
    SUBST1_TAC THEN
  SUBGOAL_THEN
   `(\x:real^1. integral (:real^1)
       (\y. if &1 <= drop x /\ drop x <= &2 /\ &0 <= drop y /\ drop y <= &n
            then Cx(inv(drop x)) * Cx(carleson_theta' z0 (drop x) (drop y) w)
              else vec 0)) =
    (\x:real^1. if &1 <= drop x /\ drop x <= &2
                then Cx(inv(drop x) * real_integral (real_interval[&0,&n]) (\b.
                  carleson_theta' z0 (drop x) b w))
                else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN COND_CASES_TAC THENL
     [MATCH_MP_TAC MNF_INNER_B_EVAL THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `(\y:real^1. if &1 <= drop x /\ drop x <= &2 /\ &0 <= drop y /\ drop y
         <= &n
            then Cx(inv(drop x)) * Cx(carleson_theta' z0 (drop x) (drop y) w)
              else vec 0) = (\y:real^1. vec 0)`
       SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN COND_CASES_TAC THEN
         ASM_MESON_TAC[];
        REWRITE_TAC[INTEGRAL_0]]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`\a. inv a * real_integral (real_interval[&0,&n]) (\b.
    carleson_theta' z0 a b w)`;
                 `&1:real`; `&2:real`] CX_INTERVAL_REAL_BRIDGE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[THETA'_A_ITERATE_INTEGRABLE];
    DISCH_THEN(SUBST1_TAC o BETA_RULE) THEN REFL_TAC]);;

(* w-outer inner side: at fixed w, the ab-box integral of the full transform *)
(* kernel                                                                    *)
(* factors the ab-constant cexp(-i(-x)w)*fhat(w) to the front                *)
(* (INTEGRAL_COMPLEX_LMUL;                                                   *)
(* box kernel integrable = MNF_ABKERNEL_FS_ABSINT) and evaluates the         *)
(* remaining box                                                             *)
(* integral by MNF_ABBOX_CX_NESTED to Cx(NMn w), NMn w = int_[1,2](1/a)      *)
(* int_[0,n] theta'.                                                         *)
let MNF_SIDEW_INNER = prove
 (`!(h:real->complex) z0 x n w.
     integral (:real^(1,1)finite_sum)
       (\ab. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
             then Cx(inv(drop(fstcart ab))) *
                  (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w)) *
                  Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart ab))
                    (drop w))
             else vec 0) =
     (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w)) *
     Cx(real_integral (real_interval[&1,&2])
          (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
            carleson_theta' z0 a b (drop w))))`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\ab:real^(1,1)finite_sum. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <=
     &2 /\
                &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
             then Cx(inv(drop(fstcart ab))) *
                  (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w)) *
                  Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart ab))
                    (drop w))
             else vec 0) =
    (\ab:real^(1,1)finite_sum. (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h
      (drop w)) *
      (if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
          &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
       then Cx(inv(drop(fstcart ab))) * Cx(carleson_theta' z0 (drop(fstcart
         ab)) (drop(sndcart ab)) (drop w))
       else vec 0))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[COND_CLAUSES; COMPLEX_VEC_0; COMPLEX_MUL_RZERO] THEN
    ABBREV_TAC `Mp = cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier
      (h:real->complex)(drop w)` THEN
    ABBREV_TAC `Pp = Cx(inv(drop(fstcart(x':real^(1,1)finite_sum))))` THEN
    ABBREV_TAC `Sp = Cx(carleson_theta' z0
      (drop(fstcart(x':real^(1,1)finite_sum))) (drop(sndcart x'))
      (drop w))` THEN
    CONV_TAC COMPLEX_RING;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\ab:real^(1,1)finite_sum. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <=
     &2 /\
          &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
       then Cx(inv(drop(fstcart ab))) * Cx(carleson_theta' z0 (drop(fstcart
         ab)) (drop(sndcart ab)) (drop w))
       else vec 0`;
    `(:real^(1,1)finite_sum)`;
    `cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier (h:real->complex) (drop w)`]
   INTEGRAL_COMPLEX_LMUL) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    REWRITE_TAC[MNF_ABKERNEL_FS_ABSINT];
    DISCH_THEN SUBST1_TAC] THEN
  AP_TERM_TAC THEN REWRITE_TAC[MNF_ABBOX_CX_NESTED]);;

(* S6 KEYSTONE: box-Fubini identity (MNF_FOURIER_BOX, Fremlin 2827-2868).    *)
(*   Cx sqrt2pi * fourier(\w. fhat w * Cx(NMn w))(--x) = SIDEAB, where       *)
(* NMn w = int_[1,2](1/a) int_[0,n] theta'_zab(w) (un-normalized nested avg) *)
(* and                                                                       *)
(* SIDEAB = int_ab(box? Cx(inv a)*Cx sqrt2pi * V_ab : 0), V_ab =             *)
(* fourier(fhat theta')(-x).                                                 *)
(* Both Fubini directions equal the pivot integral(:iterated) fullK:         *)
(* LHS route: INNER_INT_FOURIER + MNF_SIDEW_INNER^-1 +                  *)
(* FUBINI_INTEGRAL_ALT^-1;                                                   *)
(* RHS route: FUBINI_INTEGRAL + MNF_SIDE_AB. fullK abs-int =                 *)
(* MNF_KERNEL_BOX_ABSINT.                                                    *)
let MNF_FOURIER_BOX = prove
 (`!(h:real->complex) z0 x n. schwartz h
   ==> Cx(sqrt(&2*pi)) *
       fourier (\w. fourier h w *
         Cx(real_integral (real_interval[&1,&2])
              (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                carleson_theta' z0 a b w)))) (--x) =
       integral (:real^(1,1)finite_sum)
         (\ab. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                  &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then Cx(inv(drop(fstcart ab))) * Cx(sqrt(&2*pi)) *
                    fourier (\w. fourier h w * Cx(carleson_theta' z0
                      (drop(fstcart ab)) (drop(sndcart ab)) w)) (--x)
               else vec 0)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\u. fourier (h:real->complex) u *
         Cx(real_integral (real_interval[&1,&2])
              (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                carleson_theta' z0 a b u)))`;
    `--x:real`] INNER_INT_FOURIER) THEN
  REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  SUBGOAL_THEN
   `(\w:real^1. cexp(--(ii * Cx(--x) * Cx(drop w))) *
        (fourier (h:real->complex) (drop w) *
              Cx(real_integral (real_interval[&1,&2])
                   (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                     carleson_theta' z0 a b (drop w)))))) =
    (\w:real^1. integral (:real^(1,1)finite_sum)
        (\ab. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                 &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
              then Cx(inv(drop(fstcart ab))) *
                   (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w)) *
                   Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart ab))
                     (drop w))
              else vec 0))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real^1` THEN REWRITE_TAC[] THEN
    REWRITE_TAC[MNF_SIDEW_INNER] THEN
    REWRITE_TAC[COMPLEX_MUL_ASSOC];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP FUBINI_INTEGRAL_ALT
    (MATCH_MP (SPECL[`h:real->complex`;`z0:real`;`x:real`;`n:num`]
      MNF_KERNEL_BOX_ABSINT)
              (ASSUME `schwartz (h:real->complex)`))) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MP_TAC(MATCH_MP FUBINI_INTEGRAL
    (MATCH_MP (SPECL[`h:real->complex`;`z0:real`;`x:real`;`n:num`]
      MNF_KERNEL_BOX_ABSINT)
              (ASSUME `schwartz (h:real->complex)`))) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(SPECL[`h:real->complex`;`z0:real`;`x:real`;`n:num`] MNF_SIDE_AB) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* S6 STEP C prerequisites: the box-marginal is integrable + norm-bounded.   *)
(* ------------------------------------------------------------------------- *)

(* the (a,b)-marginal (integral_w fullK) is INTEGRABLE, via                  *)
(* FUBINI_ABSOLUTELY_ INTEGRABLE (2nd conjunct = has_integral) on            *)
(* MNF_KERNEL_BOX_ABSINT.                                                    *)
let MNF_MARGINAL_INT = prove
 (`!(h:real->complex) z0 x n. schwartz h
   ==> (\ab:real^(1,1)finite_sum. integral (:real^1)
          (\w. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                  &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then Cx(inv(drop(fstcart ab))) *
                    (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w))
                      *
                    Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart ab))
                      (drop w))
               else vec 0))
       integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(MATCH_MP FUBINI_ABSOLUTELY_INTEGRABLE
    (MATCH_MP (SPECL[`h:real->complex`;`z0:real`;`x:real`;`n:num`]
      MNF_KERNEL_BOX_ABSINT)
              (ASSUME `schwartz (h:real->complex)`))) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  STRIP_TAC THEN ASM_MESON_TAC[integrable_on]);;

(* abstract arithmetic for the marginal norm bound: 2p*ia*s*V <= s*ia*A from *)
(* 2p*V<=A. (name p, not pi, to avoid the pi-constant clash that makes       *)
(* REAL_RING throw find.)                                                    *)
let MARGINAL_ARITH = prove
 (`!s ia V A p:real. &0 <= ia /\ &0 <= s /\ &0 <= V /\ &2 * p * V <= A /\ &0 <=
   p
   ==> &2 * p * ia * s * V <= s * ia * A`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `s * ia * (&2 * p * V)` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC REAL_EQ_IMP_LE THEN CONV_TAC REAL_RING;
    SUBGOAL_THEN
      `s * ia * A =
       (s * ia) * A /\ s * ia * (&2 * p * V) = (s * ia) * (&2 * p * V)`
     (fun th -> REWRITE_TAC[th]) THENL
     [CONJ_TAC THEN CONV_TAC REAL_RING; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[REAL_LE_MUL]]);;

(* pointwise: 2pi * norm(marginal ab) <= box? sqrt2pi*(1/a)*amd h a b x : 0. *)
(* COND_CASES_TAC reduces the w-independent box cond (also inside the \w) to *)
(* true/false; on-box, MNF_INNER_W_EVAL evaluates the integral to Cx(inv     *)
(* a)*Cx sqrt2pi*V_ab, and 2pi norm V_ab <= amd (286Q, a>=1>0); off-box the  *)
(* integral of vec0 is 0.                                                    *)
let MNF_MARGINAL_NORM_BOUND = prove
 (`!(h:real->complex) z0 x n ab. schwartz h
   ==> &2 * pi * norm(integral (:real^1)
          (\w. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                  &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then Cx(inv(drop(fstcart ab))) *
                    (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w))
                      *
                    Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart ab))
                      (drop w))
               else vec 0))
       <= (if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
              &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
           then sqrt(&2*pi) * (inv(drop(fstcart ab)) *
                carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) x)
           else &0)`,
  REPEAT STRIP_TAC THEN COND_CASES_TAC THEN REWRITE_TAC[COND_CLAUSES] THENL
   [MP_TAC(ISPECL [`h:real->complex`; `z0:real`; `x:real`;
                   `drop(fstcart(ab:real^(1,1)finite_sum))`;
                   `drop(sndcart(ab:real^(1,1)finite_sum))`] MNF_INNER_W_EVAL)
                     THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    SUBGOAL_THEN
      `abs(inv(drop(fstcart(ab:real^(1,1)finite_sum)))) = inv(drop(fstcart
      ab))` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_INV] THEN AP_TERM_TAC THEN
       ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `abs(sqrt(&2*pi)) = sqrt(&2*pi)` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC SQRT_POS_LE THEN
       MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`h:real->complex`; `z0:real`;
                   `drop(fstcart(ab:real^(1,1)finite_sum))`;
                   `drop(sndcart(ab:real^(1,1)finite_sum))`;
                     `x:real`] CARLESON_286Q_KERNEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[carleson_amd] THEN
    ABBREV_TAC `V = norm(fourier (\w. fourier (h:real->complex) w *
      Cx(carleson_theta' z0 (drop(fstcart(ab:real^(1,1)finite_sum)))
      (drop(sndcart ab)) w)) (--x))` THEN
    ABBREV_TAC `A = carleson_A (carleson_modulate
      (drop(sndcart(ab:real^(1,1)finite_sum))) (carleson_dilate (drop(fstcart
      ab)) (h:real->complex))) (x / drop(fstcart ab))` THEN
    ABBREV_TAC `ia = inv(drop(fstcart(ab:real^(1,1)finite_sum)))` THEN
    ABBREV_TAC `s = sqrt(&2 * pi)` THEN
    SUBGOAL_THEN `&0 <= ia /\ &0 <= s` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [EXPAND_TAC "ia" THEN MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
        EXPAND_TAC "s" THEN MATCH_MP_TAC SQRT_POS_LE THEN MP_TAC PI_POS THEN
          REAL_ARITH_TAC];
      ALL_TAC] THEN
    DISCH_TAC THEN
    MATCH_MP_TAC MARGINAL_ARITH THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [EXPAND_TAC "V" THEN REWRITE_TAC[NORM_POS_LE]; MP_TAC PI_POS THEN
       REAL_ARITH_TAC];
    REWRITE_TAC[INTEGRAL_0; NORM_0; REAL_MUL_RZERO; REAL_LE_REFL]]);;

(* Mn(w) = inv n * NMn(w) as an integral identity: pull the constant inv n   *)
(* out of the outer a-integral (REAL_INTEGRAL_LMUL +                         *)
(* THETA'_A_ITERATE_INTEGRABLE, integrand ring).                             *)
let MN_EQ_INVN_NMN = prove
 (`!z n w.
     real_integral (real_interval[&1,&2])
       (\alpha. inv alpha * (inv(&n) * real_integral (real_interval[&0,&n])
                  (\beta. carleson_theta' z alpha beta w))) =
     inv(&n) * real_integral (real_interval[&1,&2])
       (\a. inv a * real_integral (real_interval[&0,&n]) (\b. carleson_theta' z
         a b w))`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPECL [`\a. inv a * real_integral (real_interval[&0,&n]) (\b.
    carleson_theta' z a b w)`;
                 `inv(&n):real`;
                   `real_interval[&1,&2]`] REAL_INTEGRAL_LMUL) THEN
  ANTS_TAC THENL [REWRITE_TAC[THETA'_A_ITERATE_INTEGRABLE]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC REAL_INTEGRAL_EQ THEN X_GEN_TAC `a:real` THEN DISCH_TAC THEN
  REWRITE_TAC[REAL_MUL_AC]);;

(* ------------------------------------------------------------------------- *)
(* S6 STEP C = WN_LE_AAVG : 2pi*norm(fourier(fhat*Mn)(-x)) <= carleson_Aavg  *)
(* h n x.                                                                    *)
(* ------------------------------------------------------------------------- *)

(* ------------------------------------------------------------------------- *)
(* NMn w-measurability for Step C: w |-> Cx(NMn w) is measurable.            *)
(* NMn w = int_[1,2](1/a) int_[0,n] theta'_zab(w). Route: on each window     *)
(* [-R,R]                                                                    *)
(* the box2d x [-R,R] kernel is abs-integrable (finite measure, |.|<=1);     *)
(* FUBINI                                                                    *)
(* gives its w-marginal (= Cx(NMn w) on the window, MNF_ABBOX_CX_NESTED)     *)
(* integrable                                                                *)
(* hence measurable; MEASURABLE_ON_LIMIT over R=&m -> Cx(NMn) measurable on  *)
(* R.                                                                        *)
(* ------------------------------------------------------------------------- *)

(* real^(1,(1,1)finite_sum)finite_sum <-> real^3 shuffle (w outer): z |->    *)
(* [a;b;w] with a=fst(snd z), b=snd(snd z), w=fst z; transfers               *)
(* CARLESON_THETA'_3D.                                                       *)
let SHUF3W_LINEAR = prove
 (`linear (\z:real^(1,(1,1)finite_sum)finite_sum.
      vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
        drop(fstcart z)]:real^3) /\
   (!u v:real^(1,(1,1)finite_sum)finite_sum.
      (\z. vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
        drop(fstcart z)]:real^3) u =
      (\z. vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
        drop(fstcart z)]:real^3) v ==> u = v)`,
  CONJ_TAC THENL
   [REWRITE_TAC[linear] THEN CONJ_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3] THEN
    SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VECTOR_3; DIMINDEX_3;
      ARITH] THEN
    REWRITE_TAC[FSTCART_ADD; SNDCART_ADD; FSTCART_CMUL; SNDCART_CMUL; DROP_ADD;
      DROP_CMUL] THEN
    REWRITE_TAC[VECTOR_3] THEN REAL_ARITH_TAC;
    REPEAT GEN_TAC THEN REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `drop(fstcart(sndcart(u:real^(1,(1,1)finite_sum)finite_sum))) =
       drop(fstcart(sndcart v)) /\
      drop(sndcart(sndcart u)) = drop(sndcart(sndcart v)) /\
      drop(fstcart u) = drop(fstcart v)`
     STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM MP_TAC THEN
       REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3] THEN
       SIMP_TAC[]; ALL_TAC] THEN
    ONCE_REWRITE_TAC[PASTECART_EQ] THEN REWRITE_TAC[GSYM DROP_EQ] THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[PASTECART_EQ] THEN
    REWRITE_TAC[GSYM DROP_EQ] THEN ASM_REWRITE_TAC[]]);;

let SHUF3W_IMAGE = prove
 (`IMAGE (\z:real^(1,(1,1)finite_sum)finite_sum.
      vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
        drop(fstcart z)]:real^3)
      (:real^(1,(1,1)finite_sum)finite_sum) = (:real^3)`,
  MATCH_MP_TAC SURJECTIVE_IMAGE_EQ THEN REWRITE_TAC[IN_UNIV] THEN
  X_GEN_TAC `p:real^3` THEN
  EXISTS_TAC `pastecart (lift((p:real^3)$3)) (pastecart (lift(p$1))
    (lift(p$2))):real^(1,(1,1)finite_sum)finite_sum` THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART; LIFT_DROP] THEN
  REWRITE_TAC[CART_EQ; DIMINDEX_3; FORALL_3; VECTOR_3] THEN
  CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[]);;

let SHUF3WC = prove
 (`!hh:real^3->complex.
     (hh o (\z:real^(1,(1,1)finite_sum)finite_sum.
        vector[drop(fstcart(sndcart z)); drop(sndcart(sndcart z));
          drop(fstcart z)]:real^3))
       measurable_on (:real^(1,(1,1)finite_sum)finite_sum)
     <=> hh measurable_on (:real^3)`,
  GEN_TAC THEN
  MP_TAC(ISPECL
   [`\z:real^(1,(1,1)finite_sum)finite_sum. vector[drop(fstcart(sndcart z));
     drop(sndcart(sndcart z)); drop(fstcart z)]:real^3`;
    `hh:real^3->complex`;
      `(:real^(1,(1,1)finite_sum)finite_sum)`]
      MEASURABLE_ON_LINEAR_IMAGE_EQ_GEN) THEN
  REWRITE_TAC[SHUF3W_LINEAR; DIMINDEX_FINITE_SUM; DIMINDEX_1; DIMINDEX_3;
    ARITH] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[SHUF3W_IMAGE]);;

let CX_THETA_WOUTER_MEASURABLE = prove
 (`!z0. (\z:real^(1,(1,1)finite_sum)finite_sum.
          Cx(carleson_theta' z0 (drop(fstcart(sndcart z)))
            (drop(sndcart(sndcart z))) (drop(fstcart z))))
        measurable_on (:real^(1,(1,1)finite_sum)finite_sum)`,
  GEN_TAC THEN
  MP_TAC(ISPEC `\p:real^3. Cx(carleson_theta' z0 (p$1) (p$2) (p$3))` SHUF3WC)
    THEN
  MATCH_MP_TAC(TAUT `b /\ (a <=> c) ==> (a <=> b) ==> c`) THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\p:real^3. Cx(carleson_theta' z0 (p$1) (p$2) (p$3))) =
      (\v:real^1. Cx(drop v)) o (\p:real^3. lift(carleson_theta' z0 (p$1) (p$2)
        (p$3)))`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_ON_COMPOSE_CONTINUOUS THEN
    REWRITE_TAC[CARLESON_THETA'_3D_MEASURABLE; CONTINUOUS_ON_CX_LIFT;
      LIFT_DROP; CONTINUOUS_ON_ID];
    AP_THM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM; o_THM] THEN
    GEN_TAC THEN REWRITE_TAC[VECTOR_3]]);;

let CX_INVA_WOUTER_MEASURABLE = prove
 (`(\z:real^(1,(1,1)finite_sum)finite_sum. Cx(inv(drop(fstcart(sndcart z)))))
   measurable_on (:real^(1,(1,1)finite_sum)finite_sum)`,
  MP_TAC(ISPEC `\p:real^3. Cx(inv(p$1))` SHUF3WC) THEN
  MATCH_MP_TAC(TAUT `b /\ (a <=> c) ==> (a <=> b) ==> c`) THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\p:real^3. Cx(inv(p$1))) = (\v:real^1. Cx(drop v)) o (\p:real^3.
       lift(inv(p$1)))`
     SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_ON_COMPOSE_CONTINUOUS THEN
    REWRITE_TAC[CONTINUOUS_ON_CX_LIFT; LIFT_DROP; CONTINUOUS_ON_ID] THEN
    MATCH_MP_TAC MEASURABLE_ON_LIFT_INV THEN CONJ_TAC THENL
     [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
      MATCH_MP_TAC CONTINUOUS_ON_LIFT_COMPONENT_COMPOSE THEN
        REWRITE_TAC[CONTINUOUS_ON_ID];
      REWRITE_TAC[IN_UNIV; NEGLIGIBLE_STANDARD_HYPERPLANE]];
    AP_THM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM; o_THM] THEN
    GEN_TAC THEN REWRITE_TAC[VECTOR_3]]);;

let WBOX_REGION_MEASURABLE = prove
 (`!n R. measurable {z:real^(1,(1,1)finite_sum)finite_sum |
             abs(drop(fstcart z)) <= R /\
             &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2
               /\
             &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <=
               &n}`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `{z:real^(1,(1,1)finite_sum)finite_sum |
             abs(drop(fstcart z)) <= R /\
             &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2
               /\
             &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n}
               =
    (interval[lift(--R),lift R]) PCROSS
    ((interval[lift(&1),lift(&2)]) PCROSS (interval[lift(&0),lift(&n)]))`
   SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; FORALL_PASTECART; PASTECART_IN_PCROSS; IN_ELIM_THM;
                FSTCART_PASTECART; SNDCART_PASTECART; IN_INTERVAL_1;
                  LIFT_DROP] THEN
    REWRITE_TAC[REAL_ARITH `--R <= w /\ w <= R <=> abs w <= R`] THEN
      CONV_TAC TAUT;
    ONCE_REWRITE_TAC[MEASURABLE_PCROSS] THEN REPEAT DISJ2_TAC THEN
      CONJ_TAC THENL
     [REWRITE_TAC[MEASURABLE_INTERVAL];
      ONCE_REWRITE_TAC[MEASURABLE_PCROSS] THEN REPEAT DISJ2_TAC THEN
      REWRITE_TAC[MEASURABLE_INTERVAL]]]);;

(* window x box kernel abs-int on the w-outer iterated type.                 *)
let WBOX_KERNEL_ABSINT = prove
 (`!z0 n R.
     (\z:real^(1,(1,1)finite_sum)finite_sum.
        if abs(drop(fstcart z)) <= R /\
           &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
           &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n
        then Cx(inv(drop(fstcart(sndcart z)))) *
             Cx(carleson_theta' z0 (drop(fstcart(sndcart z)))
               (drop(sndcart(sndcart z))) (drop(fstcart z)))
        else vec 0)
     absolutely_integrable_on (:real^(1,(1,1)finite_sum)finite_sum)`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC
   `\z:real^(1,(1,1)finite_sum)finite_sum.
       if abs(drop(fstcart z)) <= R /\
          &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
          &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n
       then lift(&1) else vec 0` THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\z:real^(1,(1,1)finite_sum)finite_sum.
        if abs(drop(fstcart z)) <= R /\
           &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
           &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n
        then Cx(inv(drop(fstcart(sndcart z)))) *
             Cx(carleson_theta' z0 (drop(fstcart(sndcart z)))
               (drop(sndcart(sndcart z))) (drop(fstcart z)))
        else vec 0) =
      (\z:real^(1,(1,1)finite_sum)finite_sum.
        if z IN {z:real^(1,(1,1)finite_sum)finite_sum |
                   abs(drop(fstcart z)) <= R /\
                   &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z))
                     <= &2 /\
                   &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z))
                     <= &n}
        then Cx(inv(drop(fstcart(sndcart z)))) *
             Cx(carleson_theta' z0 (drop(fstcart(sndcart z)))
               (drop(sndcart(sndcart z))) (drop(fstcart z)))
        else vec 0)`
     SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_ON_RESTRICT THEN CONJ_TAC THENL
     [MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN
      REWRITE_TAC[CX_INVA_WOUTER_MEASURABLE; CX_THETA_WOUTER_MEASURABLE];
      MATCH_MP_TAC MEASURABLE_IMP_LEBESGUE_MEASURABLE THEN
        REWRITE_TAC[WBOX_REGION_MEASURABLE]];
    SUBGOAL_THEN
     `(\z:real^(1,(1,1)finite_sum)finite_sum.
        if abs(drop(fstcart z)) <= R /\
           &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z)) <= &2 /\
           &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z)) <= &n
             then lift(&1) else vec 0) =
      (\z:real^(1,(1,1)finite_sum)finite_sum.
        if z IN {z:real^(1,(1,1)finite_sum)finite_sum |
                   abs(drop(fstcart z)) <= R /\
                   &1 <= drop(fstcart(sndcart z)) /\ drop(fstcart(sndcart z))
                     <= &2 /\
                   &0 <= drop(sndcart(sndcart z)) /\ drop(sndcart(sndcart z))
                     <= &n} then lift(&1) else vec 0)`
     SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
    REWRITE_TAC[INTEGRABLE_RESTRICT_UNIV; INTEGRABLE_ON_CONST;
      WBOX_REGION_MEASURABLE];
    X_GEN_TAC `z:real^(1,(1,1)finite_sum)finite_sum` THEN
      REWRITE_TAC[IN_UNIV] THEN COND_CASES_TAC THEN
    REWRITE_TAC[NORM_0; NORM_LIFT; LIFT_DROP; DROP_VEC; REAL_ABS_NUM;
      REAL_LE_REFL] THEN
    REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC
      `abs(inv(drop(fstcart(sndcart(z:real^(1,(1,1)finite_sum)finite_sum))))) *
      &1` THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[REAL_ABS_POS] THEN
      MP_TAC(ISPECL
       [`z0:real`;
        `drop(fstcart(sndcart(z:real^(1,(1,1)finite_sum)finite_sum)))`;
        `drop(sndcart(sndcart(z:real^(1,(1,1)finite_sum)finite_sum)))`;
        `drop(fstcart(z:real^(1,(1,1)finite_sum)finite_sum))`]
       CARLESON_THETA'_BOUNDS) THEN REAL_ARITH_TAC;
      REWRITE_TAC[REAL_MUL_RID] THEN MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `abs(inv(&1))` THEN CONJ_TAC THENL
       [REWRITE_TAC[REAL_ABS_INV] THEN MATCH_MP_TAC REAL_LE_INV2 THEN
         ASM_REAL_ARITH_TAC;
        CONV_TAC REAL_RAT_REDUCE_CONV]]]);;

(* the windowed w-marginal (= Cx(NMn w) on |w|<=R via MNF_ABBOX_CX_NESTED)   *)
(* is integrable.                                                            *)
let NMN_WINDOW_INT = prove
 (`!z0 n R.
     (\w:real^1. if abs(drop w) <= R
                 then Cx(real_integral (real_interval[&1,&2])
                          (\a. inv a * real_integral (real_interval[&0,&n])
                            (\b. carleson_theta' z0 a b (drop w))))
                 else vec 0)
     integrable_on (:real^1)`,
  REPEAT GEN_TAC THEN
  MP_TAC(MATCH_MP FUBINI_ABSOLUTELY_INTEGRABLE
    (SPECL[`z0:real`;`n:num`;`R:real`] WBOX_KERNEL_ABSINT)) THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  DISCH_THEN(MP_TAC o CONJUNCT2) THEN
  SUBGOAL_THEN
   `(\w:real^1. integral (:real^(1,1)finite_sum)
       (\ab. if abs(drop w) <= R /\
                &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
             then Cx(inv(drop(fstcart ab))) *
                  Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart ab))
                    (drop w))
             else vec 0)) =
    (\w:real^1. if abs(drop w) <= R
                then Cx(real_integral (real_interval[&1,&2])
                         (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                           carleson_theta' z0 a b (drop w))))
                else vec 0)`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real^1` THEN
    ASM_CASES_TAC `abs(drop(w:real^1)) <= R` THEN ASM_REWRITE_TAC[] THENL
     [MP_TAC(ISPECL [`z0:real`; `drop(w:real^1)`;
       `n:num`] MNF_ABBOX_CX_NESTED) THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN AP_TERM_TAC THEN
        REWRITE_TAC[FUN_EQ_THM];
      REWRITE_TAC[INTEGRAL_0]];
    MESON_TAC[integrable_on]]);;

(* CX(NMn) w-measurable: MEASURABLE_ON_LIMIT over R=&m (windowed -> Cx(NMn)  *)
(* ptwise).                                                                  *)
let CX_NMN_W_MEASURABLE = prove
 (`!z0 n. (\w:real^1. Cx(real_integral (real_interval[&1,&2])
                (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                  carleson_theta' z0 a b (drop w)))))
          measurable_on (:real^1)`,
  REPEAT GEN_TAC THEN
  MATCH_MP_TAC MEASURABLE_ON_LIMIT THEN
  EXISTS_TAC
   `\m:num. \w:real^1. if abs(drop w) <= &m
                 then Cx(real_integral (real_interval[&1,&2])
                          (\a. inv a * real_integral (real_interval[&0,&n])
                            (\b. carleson_theta' z0 a b (drop w))))
                 else vec 0` THEN
  EXISTS_TAC `{}:real^1->bool` THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; DIFF_EMPTY; IN_UNIV] THEN CONJ_TAC THENL
   [X_GEN_TAC `m:num` THEN MATCH_MP_TAC INTEGRABLE_IMP_MEASURABLE THEN
    REWRITE_TAC[NMN_WINDOW_INT];
    X_GEN_TAC `w:real^1` THEN
    MP_TAC(ISPEC `abs(drop(w:real^1))` REAL_ARCH_SIMPLE) THEN
    DISCH_THEN(X_CHOOSE_TAC `M:num`) THEN
    MATCH_MP_TAC LIM_EVENTUALLY THEN
    REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `M:num` THEN
    X_GEN_TAC `p:num` THEN DISCH_TAC THEN
    COND_CASES_TAC THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN `abs(drop(w:real^1)) <= &p` (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&M:real` THEN
    ASM_REWRITE_TAC[REAL_OF_NUM_LE]]);;

(* 0 <= NMn <= n.                                                            *)
let NMN_BOUNDS = prove
 (`!z0 n w. &0 <= real_integral (real_interval[&1,&2])
                (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                  carleson_theta' z0 a b w)) /\
            real_integral (real_interval[&1,&2])
                (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                  carleson_theta' z0 a b w)) <= &n`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\a. inv a * real_integral (real_interval[&0,&n]) (\b. carleson_theta' z0 a
     b w)) real_integrable_on real_interval[&1,&2]`
   ASSUME_TAC THENL [REWRITE_TAC[THETA'_A_ITERATE_INTEGRABLE]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_POS THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `a:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_INTEGRAL_POS THEN
        REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN
      X_GEN_TAC `b:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`z0:real`;`a:real`;`b:real`;`w:real`]
        CARLESON_THETA'_BOUNDS) THEN REAL_ARITH_TAC];
    MATCH_MP_TAC REAL_LE_TRANS THEN
    EXISTS_TAC `real_integral (real_interval[&1,&2]) (\a:real. &n)` THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC REAL_INTEGRAL_LE THEN
       ASM_REWRITE_TAC[REAL_INTEGRABLE_CONST] THEN
      X_GEN_TAC `a:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN STRIP_TAC THEN
      MATCH_MP_TAC REAL_LE_TRANS THEN
        EXISTS_TAC `&1 * real_integral (real_interval[&0,&n]) (\b.
        carleson_theta' z0 a b w)` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_RMUL THEN CONJ_TAC THENL
         [MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `inv(&1)` THEN
           CONJ_TAC THENL
           [MATCH_MP_TAC REAL_LE_INV2 THEN
             ASM_REAL_ARITH_TAC; CONV_TAC REAL_RAT_REDUCE_CONV];
          MATCH_MP_TAC REAL_INTEGRAL_POS THEN
            REWRITE_TAC[THETA'_BETA_INTEGRABLE] THEN
          X_GEN_TAC `b:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
            STRIP_TAC THEN
          MP_TAC(ISPECL [`z0:real`;`a:real`;`b:real`;`w:real`]
            CARLESON_THETA'_BOUNDS) THEN REAL_ARITH_TAC];
        REWRITE_TAC[REAL_MUL_LID] THEN
        MATCH_MP_TAC REAL_LE_TRANS THEN
          EXISTS_TAC `real_integral (real_interval[&0,&n]) (\b:real. &1)` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC REAL_INTEGRAL_LE THEN
           REWRITE_TAC[THETA'_BETA_INTEGRABLE; REAL_INTEGRABLE_CONST] THEN
          X_GEN_TAC `b:real` THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
            STRIP_TAC THEN
          MP_TAC(ISPECL [`z0:real`;`a:real`;`b:real`;`w:real`]
            CARLESON_THETA'_BOUNDS) THEN REAL_ARITH_TAC;
          SIMP_TAC[REAL_INTEGRAL_CONST; REAL_ARITH `&0 <= &n`] THEN
            REAL_ARITH_TAC]];
      SIMP_TAC[REAL_INTEGRAL_CONST; REAL_ARITH `&1 <= &2`] THEN
        REAL_ARITH_TAC]]);;

(* THE FINAL GATE: w |-> fhat(w)*Cx(NMn w) absolutely           *)
(* integrable. measurable [fhat * CX_NMN_W_MEASURABLE] + dominated by        *)
(* n*|fhat| [NMN_BOUNDS].                                                    *)
let CARLESON_FHAT_NMN_ABSINT = prove
 (`!(h:real->complex) z0 n. schwartz h
   ==> (\w. fourier h (drop w) *
            Cx(real_integral (real_interval[&1,&2])
                 (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                   carleson_theta' z0 a b (drop w)))))
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
  EXISTS_TAC `\w:real^1. &n % lift(norm(fourier (h:real->complex) (drop w)))`
    THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN CONJ_TAC THENL
     [MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
       ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[ABSOLUTELY_INTEGRABLE_MEASURABLE] THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[];
      REWRITE_TAC[CX_NMN_W_MEASURABLE]];
    MATCH_MP_TAC INTEGRABLE_CMUL THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
    MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
      ASM_REWRITE_TAC[];
    X_GEN_TAC `w:real^1` THEN REWRITE_TAC[IN_UNIV] THEN BETA_TAC THEN
    REWRITE_TAC[DROP_CMUL; LIFT_DROP; COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN
      EXISTS_TAC `norm(fourier (h:real->complex)(drop w)) * &n` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
      MP_TAC(ISPECL [`z0:real`; `n:num`; `drop(w:real^1)`] NMN_BOUNDS) THEN
        REAL_ARITH_TAC;
      REWRITE_TAC[REAL_MUL_SYM; REAL_LE_REFL]]]);;

(* fourier(fhat*Mn) = Cx(inv n) * fourier(fhat*NMn) (Mn = inv n * NMn,       *)
(* FOURIER_LMUL).                                                            *)
let FHAT_MN_FACTOR = prove
 (`!(h:real->complex) z0 x n. schwartz h ==>
    fourier (\w. fourier h w *
       Cx(real_integral (real_interval[&1,&2])
            (\alpha. inv alpha * (inv(&n) * real_integral
              (real_interval[&0,&n])
                       (\beta. carleson_theta' z0 alpha beta w))))) (--x) =
    Cx(inv(&n)) * fourier (\w. fourier h w *
       Cx(real_integral (real_interval[&1,&2])
            (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
              carleson_theta' z0 a b w)))) (--x)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[MN_EQ_INVN_NMN; CX_MUL] THEN
  SUBGOAL_THEN
   `(\w. fourier (h:real->complex) w *
         Cx(inv(&n)) *
         Cx(real_integral (real_interval[&1,&2])
              (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                carleson_theta' z0 a b w)))) =
    (\w. Cx(inv(&n)) *
         (fourier (h:real->complex) w *
          Cx(real_integral (real_interval[&1,&2])
               (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
                 carleson_theta' z0 a b w)))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  MATCH_MP_TAC FOURIER_LMUL THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC FOURIER_MODULATION_ABSINT THEN
  MP_TAC(ISPECL [`h:real->complex`; `z0:real`;
    `n:num`] CARLESON_FHAT_NMN_ABSINT) THEN
  ASM_REWRITE_TAC[]);;

(* abstract on-box arithmetic: N <= inv s*(ia*amd) from 2p*N <= s*(ia*amd),  *)
(* s*s=2p, s>0.                                                              *)
let NORMBOX_PT_ARITH = prove
 (`!N ia amd s p:real. &0 < p /\ &0 < s /\ s * s = &2 * p /\ &0 <= ia /\ &0 <=
   amd /\
     &2 * p * N <= s * (ia * amd)
   ==> N <= inv s * (ia * amd)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < &2 * p` ASSUME_TAC THENL
    [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  ONCE_REWRITE_TAC[GSYM(MATCH_MP REAL_LE_LMUL_EQ (ASSUME `&0 < &2 * p`))] THEN
  SUBGOAL_THEN
    `(&2 * p) * inv s * (ia * amd) = s * (ia * amd)` SUBST1_TAC THENL
   [ONCE_REWRITE_TAC[GSYM(ASSUME `s * s = &2 * p`)] THEN
    SUBGOAL_THEN `s * inv s = &1` MP_TAC THENL
     [MATCH_MP_TAC REAL_MUL_RINV THEN ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    CONV_TAC REAL_RING;
    REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN ASM_REWRITE_TAC[]]);;

(* pointwise dominator: norm(marginal ab) <= box? inv(sqrt2pi)*(1/a)*amd :   *)
(* 0.                                                                        *)
let MARGINAL_NORM_DOM = prove
 (`!(h:real->complex) z0 x n ab. schwartz h
   ==> norm(integral (:real^1)
          (\w. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                  &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then Cx(inv(drop(fstcart ab))) *
                    (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w))
                      *
                    Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart ab))
                      (drop w))
               else vec 0))
       <= (if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
              &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
           then inv(sqrt(&2*pi)) * (inv(drop(fstcart ab)) *
                carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) x)
           else &0)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `z0:real`; `x:real`; `n:num`;
    `ab:real^(1,1)finite_sum`]
    MNF_MARGINAL_NORM_BOUND) THEN
  ASM_REWRITE_TAC[] THEN
  COND_CASES_TAC THEN
  REWRITE_TAC[INTEGRAL_0; NORM_0; REAL_LE_REFL] THEN DISCH_TAC THEN
  MATCH_MP_TAC NORMBOX_PT_ARITH THEN EXISTS_TAC `pi:real` THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC PI_POS THEN REAL_ARITH_TAC;
    MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN REAL_ARITH_TAC;
    MP_TAC(SPEC `&2 * pi` SQRT_POW_2) THEN
    ANTS_TAC THENL [MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_POW_2];
    MATCH_MP_TAC REAL_LE_INV THEN ASM_REAL_ARITH_TAC;
    MATCH_MP_TAC AMD_NONNEG THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ASM_REWRITE_TAC[]]);;

(* the dominator g ab = box? inv(sqrt2pi)*(1/a)*amd : 0 (lifted) is          *)
(* integrable.                                                               *)
let MARGINAL_DOM_INT = prove
 (`!(h:real->complex) x n. schwartz h
   ==> (\ab:real^(1,1)finite_sum.
          lift(if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                  &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
               then inv(sqrt(&2*pi)) * (inv(drop(fstcart ab)) *
                    carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) x)
               else &0))
       integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `n:num`; `x:real`] AMD_ABBOX_ABSINT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE) THEN
  DISCH_THEN(MP_TAC o SPEC `inv(sqrt(&2*pi))` o MATCH_MP INTEGRABLE_CMUL) THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `ab:real^(1,1)finite_sum` THEN
  COND_CASES_TAC THEN
  REWRITE_TAC[VECTOR_MUL_RZERO; COND_CLAUSES; GSYM LIFT_CMUL; LIFT_NUM] THEN
  AP_TERM_TAC THEN
  SUBGOAL_THEN `drop(fstcart(ab:real^(1,1)finite_sum)) > &0` ASSUME_TAC THENL
   [ASM_REAL_ARITH_TAC; ASM_REWRITE_TAC[]]);;

(* int_ab(box? inv(sqrt2pi)*(1/a)*amd : 0) = inv(sqrt2pi) * Sinner.          *)
let DOM_INTEGRAL_EQ = prove
 (`!(h:real->complex) x n. schwartz h /\ ~(n = 0)
   ==> drop(integral (:real^(1,1)finite_sum)
          (\ab. lift(if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                        &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
                     then inv(sqrt(&2*pi)) * (inv(drop(fstcart ab)) *
                          carleson_amd h (drop(fstcart ab)) (drop(sndcart ab))
                            x)
                     else &0)))
       = inv(sqrt(&2*pi)) * carleson_Sinner h n x`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\ab:real^(1,1)finite_sum. lift(if &1 <= drop(fstcart ab) /\ drop(fstcart
     ab) <= &2 /\
                        &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
                     then inv(sqrt(&2*pi)) * (inv(drop(fstcart ab)) *
                          carleson_amd h (drop(fstcart ab)) (drop(sndcart ab))
                            x)
                     else &0)) =
    (\ab:real^(1,1)finite_sum. inv(sqrt(&2*pi)) %
       (if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
           &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
        then lift(inv(drop(fstcart ab)) *
             (if drop(fstcart ab) > &0
              then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) x else
                &0))
        else vec 0))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `ab:real^(1,1)finite_sum` THEN
    COND_CASES_TAC THEN
    REWRITE_TAC[COND_CLAUSES; VECTOR_MUL_RZERO; LIFT_NUM; GSYM LIFT_CMUL] THEN
    AP_TERM_TAC THEN
    SUBGOAL_THEN `drop(fstcart(ab:real^(1,1)finite_sum)) > &0` ASSUME_TAC THENL
     [ASM_REAL_ARITH_TAC; ASM_REWRITE_TAC[REAL_MUL_ASSOC]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\ab:real^(1,1)finite_sum. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <=
     &2 /\
           &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
        then lift(inv(drop(fstcart ab)) *
             (if drop(fstcart ab) > &0
              then carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) x else
                &0))
        else vec 0`;
    `inv(sqrt(&2*pi))`; `(:real^(1,1)finite_sum)`] INTEGRAL_CMUL) THEN
  ANTS_TAC THENL
   [MP_TAC(ISPECL [`h:real->complex`; `n:num`; `x:real`] AMD_ABBOX_ABSINT) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[absolutely_integrable_on] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o BETA_RULE) THEN REWRITE_TAC[DROP_CMUL] THEN
  MP_TAC(ISPECL [`h:real->complex`; `n:num`; `x:real`] SINNER_FIXEDX) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

(* sqrt2pi * norm(int_ab marginal) <= Sinner.                                *)
let NORM_BOXT_LE = prove
 (`!(h:real->complex) z0 x n. schwartz h /\ ~(n = 0)
   ==> sqrt(&2*pi) * norm(integral (:real^(1,1)finite_sum)
          (\ab. integral (:real^1)
            (\w. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
                    &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
                 then Cx(inv(drop(fstcart ab))) *
                      (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop
                        w)) *
                      Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart
                        ab)) (drop w))
                 else vec 0)))
       <= carleson_Sinner h n x`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\ab:real^(1,1)finite_sum. integral (:real^1)
       (\w. if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
               &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
            then Cx(inv(drop(fstcart ab))) *
                 (cexp(--(ii * Cx(--x) * Cx(drop w))) * fourier h (drop w)) *
                 Cx(carleson_theta' z0 (drop(fstcart ab)) (drop(sndcart ab))
                   (drop w))
            else vec 0)`;
    `\ab:real^(1,1)finite_sum.
       lift(if &1 <= drop(fstcart ab) /\ drop(fstcart ab) <= &2 /\
               &0 <= drop(sndcart ab) /\ drop(sndcart ab) <= &n
            then inv(sqrt(&2*pi)) * (inv(drop(fstcart ab)) *
                 carleson_amd h (drop(fstcart ab)) (drop(sndcart ab)) x)
            else &0)`;
    `(:real^(1,1)finite_sum)`] INTEGRAL_NORM_BOUND_INTEGRAL) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC MNF_MARGINAL_INT THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC MARGINAL_DOM_INT THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `ab:real^(1,1)finite_sum` THEN
        REWRITE_TAC[IN_UNIV; LIFT_DROP] THEN
      MATCH_MP_TAC MARGINAL_NORM_DOM THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real->complex`; `x:real`; `n:num`] DOM_INTEGRAL_EQ) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `&0 < sqrt(&2*pi)` ASSUME_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `sqrt(&2*pi) * (inv(sqrt(&2*pi)) * carleson_Sinner h n x)` THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN ASM_SIMP_TAC[REAL_LT_IMP_LE];
    REWRITE_TAC[REAL_MUL_ASSOC] THEN
    ASM_SIMP_TAC[REAL_MUL_RINV; REAL_LT_IMP_NZ; REAL_MUL_LID; REAL_LE_REFL]]);;

(* bridge: 2pi*norm(fourier(fhat*NMn)(-x)) <= Sinner.                        *)
let TWOPI_NORM_F_LE_SINNER = prove
 (`!(h:real->complex) z x n. schwartz h /\ ~(n = 0)
   ==> &2 * pi * norm(fourier (\w. fourier h w *
         Cx(real_integral (real_interval[&1,&2])
             (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
               carleson_theta' z a b w)))) (--x))
       <= carleson_Sinner h n x`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`; `x:real`;
    `n:num`] NORM_BOXT_LE) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`; `x:real`;
    `n:num`] MNF_FOURIER_BOX) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`; `x:real`;
    `n:num`] MNF_SIDE_AB) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun sideab -> DISCH_THEN(fun box ->
    ASSUME_TAC(TRANS box (SYM sideab)))) THEN
  FIRST_X_ASSUM(fun th -> REWRITE_TAC[SYM th]) THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN
    `abs(sqrt(&2*pi)) = sqrt(&2*pi)` (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC SQRT_POS_LE THEN
     MP_TAC PI_POS THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `a = b ==> a <= s ==> b <= s`) THEN
  SUBGOAL_THEN `sqrt(&2*pi) * sqrt(&2*pi) = &2 * pi` MP_TAC THENL
   [MP_TAC(SPEC `&2 * pi` SQRT_POW_2) THEN
    ANTS_TAC THENL [MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_POW_2];
    CONV_TAC REAL_RING]);;

(* STEP C: 2pi*norm(fourier(fhat*Mn)(-x)) <= carleson_Aavg h n x  (n<>0).    *)
let WN_LE_AAVG = prove
 (`!(h:real->complex) z x n. schwartz h /\ ~(n = 0)
   ==> &2 * pi * norm(fourier (\w. fourier h w *
         Cx(real_integral (real_interval[&1,&2])
             (\alpha. inv alpha * (inv(&n) * real_integral
               (real_interval[&0,&n])
                       (\beta. carleson_theta' z alpha beta w))))) (--x))
       <= carleson_Aavg h n x`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`; `x:real`;
    `n:num`] FHAT_MN_FACTOR) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX; carleson_Aavg] THEN
  ABBREV_TAC `Fnrm = norm(fourier (\w. fourier (h:real->complex) w *
       Cx(real_integral (real_interval[&1,&2])
            (\a. inv a * real_integral (real_interval[&0,&n]) (\b.
              carleson_theta' z a b w)))) (--x))` THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`; `x:real`;
    `n:num`] TWOPI_NORM_F_LE_SINNER) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `abs(inv(&n)) = inv(&n)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_INV; REAL_ABS_NUM]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 <= inv(&n)` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LE_INV THEN REWRITE_TAC[REAL_POS]; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `inv(&n) * carleson_Sinner h n x` THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `&2 * pi * inv(&n) * Fnrm = inv(&n) * (&2 * pi * Fnrm)` SUBST1_TAC THENL
     [REWRITE_TAC[REAL_MUL_AC]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[REAL_LE_REFL]]);;

(* ------------------------------------------------------------------------- *)
(* S6 STEP B' + D : the DCT n-average limit Wn -> 2pi norm(fourier(fhat.tt)) *)
(* and the liminf-domination assembling ATILDE_KERNEL_DOM.                   *)
(* ------------------------------------------------------------------------- *)

(* Mn_n-integrand absint (from the NMn version, Mn = inv n * NMn).           *)
let CARLESON_FHAT_MN_ABSINT = prove
 (`!(h:real->complex) z0 n. schwartz h
   ==> (\u. fourier h (drop u) *
            Cx(real_integral (real_interval[&1,&2])
                (\alpha. inv alpha * (inv(&n) * real_integral
                  (real_interval[&0,&n])
                          (\beta. carleson_theta' z0 alpha beta (drop u))))))
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\u. fourier (h:real->complex) (drop u) *
            Cx(real_integral (real_interval[&1,&2])
                (\alpha. inv alpha * (inv(&n) * real_integral
                  (real_interval[&0,&n])
                          (\beta. carleson_theta' z0 alpha beta (drop u)))))) =
    (\u. Cx(inv(&n)) * (fourier (h:real->complex) (drop u) *
            Cx(real_integral (real_interval[&1,&2])
                (\a. inv a * real_integral (real_interval[&0,&n])
                          (\b. carleson_theta' z0 a b (drop u))))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[MN_EQ_INVN_NMN; CX_MUL] THEN
    CONV_TAC COMPLEX_RING;
    ALL_TAC] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_COMPLEX_LMUL THEN
  MP_TAC(ISPECL [`h:real->complex`; `z0:real`;
    `n:num`] CARLESON_FHAT_NMN_ABSINT) THEN
  ASM_REWRITE_TAC[]);;

(* STEP B' integrand limit: the modulated w-integrals converge (DCT). Mn_n w *)
(* -> thetatilde z w (MN_SEQ_LIMIT), dominated by |fhat(w)| (|Mn_n|<=1).     *)
let MN_INTEGRAL_LIMIT = prove
 (`!(h:real->complex) z x. schwartz h
   ==> ((\n. integral (:real^1)
              (\u. cexp(--(ii * Cx(--x) * Cx(drop u))) *
                   (fourier h (drop u) *
                    Cx(real_integral (real_interval[&1,&2])
                        (\alpha. inv alpha * (inv(&n) * real_integral
                          (real_interval[&0,&n])
                                  (\beta. carleson_theta' z alpha beta (drop
                                    u))))))))
          --> integral (:real^1)
              (\u. cexp(--(ii * Cx(--x) * Cx(drop u))) *
                   (fourier h (drop u) * Cx(carleson_thetatilde z (drop u)))))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\n u. cexp(--(ii * Cx(--x) * Cx(drop u))) *
           (fourier (h:real->complex) (drop u) *
            Cx(real_integral (real_interval[&1,&2])
                (\alpha. inv alpha * (inv(&n) * real_integral
                  (real_interval[&0,&n])
                          (\beta. carleson_theta' z alpha beta (drop u))))))`;
    `\u. cexp(--(ii * Cx(--x) * Cx(drop u))) *
         (fourier (h:real->complex) (drop u) * Cx(carleson_thetatilde z (drop
           u)))`;
    `\u:real^1. lift(norm(fourier (h:real->complex) (drop u)))`;
    `(:real^1)`] DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [X_GEN_TAC `N:num` THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC FOURIER_MODULATION_ABSINT THEN
      MP_TAC(ISPECL [`h:real->complex`; `z:real`;
        `N:num`] CARLESON_FHAT_MN_ABSINT) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      MP_TAC(ISPEC `h:real->complex` SCHWARTZ_FHAT_ABSINT) THEN
        ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`N:num`; `w:real^1`] THEN DISCH_TAC THEN
      REWRITE_TAC[LIFT_DROP; COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
      SUBGOAL_THEN `norm(cexp(--(ii * Cx(--x) * Cx(drop(w:real^1))))) = &1`
       (fun th -> REWRITE_TAC[th]) THENL
       [SUBGOAL_THEN
         `--(ii * Cx(--x) * Cx(drop(w:real^1))) = ii * Cx(--(--x * drop w))`
         SUBST1_TAC THENL
         [REWRITE_TAC[CX_NEG; CX_MUL] THEN
           SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
        REWRITE_TAC[NORM_CEXP_II]; ALL_TAC] THEN
      REWRITE_TAC[REAL_MUL_LID] THEN
      GEN_REWRITE_TAC RAND_CONV [GSYM REAL_MUL_RID] THEN
      REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
      MP_TAC(ISPECL [`z:real`; `drop(w:real^1)`; `N:num`] MN_LE1) THEN
      REAL_ARITH_TAC;
      X_GEN_TAC `w:real^1` THEN DISCH_TAC THEN
      REPEAT(MATCH_MP_TAC LIM_COMPLEX_LMUL) THEN
      REWRITE_TAC[GSYM CX_MUL] THEN
      MP_TAC(ISPECL [`z:real`; `drop(w:real^1)`] MN_SEQ_LIMIT) THEN
      REWRITE_TAC[REALLIM_COMPLEX; o_DEF]];
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]);;

(* STEP B': fourier(fhat*Mn_n)(-x) -> fourier(fhat*thetatilde)(-x)           *)
(* (FOURIER_VALUE_LIM).                                                      *)
let FHAT_MN_FOURIER_LIMIT = prove
 (`!(h:real->complex) z x. schwartz h
   ==> ((\n. fourier (\w. fourier h w *
              Cx(real_integral (real_interval[&1,&2])
                  (\alpha. inv alpha * (inv(&n) * real_integral
                    (real_interval[&0,&n])
                            (\beta. carleson_theta' z alpha beta w))))) (--x))
        --> fourier (\w. fourier h w * Cx(carleson_thetatilde z w)) (--x))
          sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL
   [`\n w. fourier (h:real->complex) w *
           Cx(real_integral (real_interval[&1,&2])
               (\alpha. inv alpha * (inv(&n) * real_integral
                 (real_interval[&0,&n])
                         (\beta. carleson_theta' z alpha beta w))))`;
    `\w. fourier (h:real->complex) w * Cx(carleson_thetatilde z w)`;
    `x:real`] FOURIER_VALUE_LIM)) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `z:real`; `x:real`] MN_INTEGRAL_LIMIT) THEN
  ASM_REWRITE_TAC[]);;

(* WN_LIMIT: Wn n = 2pi*norm(fourier(fhat*Mn_n)(-x)) ->                      *)
(* 2pi*norm(fourier(fhat*thetatilde)(-x)).                                   *)
let WN_LIMIT = prove
 (`!(h:real->complex) z x. schwartz h
   ==> ((\n. &2 * pi * norm(fourier (\w. fourier h w *
              Cx(real_integral (real_interval[&1,&2])
                  (\alpha. inv alpha * (inv(&n) * real_integral
                    (real_interval[&0,&n])
                            (\beta. carleson_theta' z alpha beta w))))) (--x)))
        ---> &2 * pi * norm(fourier (\w. fourier h w * Cx(carleson_thetatilde z
          w)) (--x))) sequentially`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC REALLIM_LMUL THEN
  MP_TAC(ISPECL [`sequentially`;
    `\n. fourier (\w. fourier (h:real->complex) w *
              Cx(real_integral (real_interval[&1,&2])
                  (\alpha. inv alpha * (inv(&n) * real_integral
                    (real_interval[&0,&n])
                            (\beta. carleson_theta' z alpha beta w))))) (--x)`;
    `fourier (\w. fourier (h:real->complex) w * Cx(carleson_thetatilde z w))
      (--x)`] LIM_NORM) THEN
  ANTS_TAC THENL
   [MP_TAC(ISPECL [`h:real->complex`; `z:real`;
     `x:real`] FHAT_MN_FOURIER_LIMIT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[REAL_TENDSTO; o_DEF; LIFT_DROP; ETA_AX] THEN
  DISCH_TAC THEN MATCH_MP_TAC REALLIM_LMUL THEN ASM_REWRITE_TAC[]);;

(* S6 = 286S(c) KERNEL DOMINATION (Fremlin 286S(c), 2827-2868).          *)
(* liminf-domination (LIMINF_DOM): Wn -> 2pi                     *)
(* norm(fourier(fhat.tt))(-x) [WN_LIMIT], Wn n <= Aavg h n x [WN_LE_AAVG     *)
(* (n<>0) + WN_LE_AAVG_ZERO], Aavg bounded below by 0 [AAVG_NONNEG],         *)
(* running-inf Aavg -> carleson_Atilde h x [AAVG_RUNNINGINF_CONV].           *)
let ATILDE_KERNEL_DOM = prove
 (`!(h:real->complex) z x. schwartz h
   ==> &2 * pi * norm(fourier (\w. fourier h w * Cx(carleson_thetatilde z w))
     (--x))
       <= carleson_Atilde h x`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\n. &2 * pi * norm(fourier (\w. fourier (h:real->complex) w *
          Cx(real_integral (real_interval[&1,&2])
              (\alpha. inv alpha * (inv(&n) * real_integral
                (real_interval[&0,&n])
                        (\beta. carleson_theta' z alpha beta w))))) (--x))`;
    `\n. carleson_Aavg h n x`;
    `&2 * pi * norm(fourier (\w. fourier (h:real->complex) w *
      Cx(carleson_thetatilde z w)) (--x))`;
    `carleson_Atilde h x`] LIMINF_DOM) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`h:real->complex`; `z:real`; `x:real`] WN_LIMIT) THEN
     ASM_REWRITE_TAC[];
    GEN_TAC THEN ASM_CASES_TAC `n = 0` THENL
     [ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`h:real->complex`; `z:real`;
        `x:real`] WN_LE_AAVG_ZERO) THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(REAL_ARITH `a = b ==> a <= c ==> b <= c`) THEN
      AP_TERM_TAC THEN AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN
        AP_TERM_TAC THEN
      REWRITE_TAC[REAL_INV_0] THEN AP_TERM_TAC THEN
        REWRITE_TAC[FUN_EQ_THM] THEN
      GEN_TAC THEN REWRITE_TAC[];
      MP_TAC(ISPECL [`h:real->complex`; `z:real`; `x:real`;
        `n:num`] WN_LE_AAVG) THEN
      ASM_REWRITE_TAC[]];
    EXISTS_TAC `&0` THEN GEN_TAC THEN MATCH_MP_TAC AAVG_NONNEG THEN
      ASM_REWRITE_TAC[];
    REWRITE_TAC[carleson_Atilde] THEN
    MP_TAC(ISPECL [`h:real->complex`; `x:real`] AAVG_RUNNINGINF_CONV) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `reallim sequentially (\m. inf {carleson_Aavg h n x | n >= m}) = G`
     (fun th -> ASM_REWRITE_TAC[th]) THEN
    MATCH_MP_TAC REALLIM_OF_CONVERGENT THEN ASM_REWRITE_TAC[]]);;

(* S6 at H = hcheck (fourier(hcheck) = h simplifies the multiplier).         *)
let KERNEL_DOM_HCHECK = prove
 (`!(h:real->complex) a y. schwartz h
   ==> &2 * pi * norm(fourier (\w. (h:real->complex) w * Cx(carleson_thetatilde
     a w)) (y))
       <= carleson_Atilde (\x. fourier h (--x)) (--y)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\x. fourier (h:real->complex) (--x)`; `a:real`;
    `--y:real`] ATILDE_KERNEL_DOM) THEN
  ANTS_TAC THENL [MATCH_MP_TAC SCHWARTZ_HCHECK THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[REAL_NEG_NEG] THEN
  SUBGOAL_THEN
   `(\w. fourier (\x. fourier (h:real->complex) (--x)) w *
     Cx(carleson_thetatilde a w)) =
    (\w. (h:real->complex) w * Cx(carleson_thetatilde a w))`
   (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `w:real` THEN
  ASM_SIMP_TAC[HCHECK_FT]);;

(* ============ S7 = AHAT_LE_ATILDE (286T(b)) full build ============        *)
(* NB: avoid COMPLEX_RING / SIMPLE_COMPLEX_ARITH on giant integral atoms     *)
(* (server-wedge risk) -- abstract integrals to fresh vars first.            *)

(* halfline lebesgue-measurable.                                             *)
let HALFLINE_LMEAS = prove
 (`!c. lebesgue_measurable {x:real^1 | drop x < c}`,
  GEN_TAC THEN MATCH_MP_TAC LEBESGUE_MEASURABLE_OPEN THEN
  REWRITE_TAC[drop; REWRITE_RULE[real_gt] OPEN_HALFSPACE_COMPONENT_LT]);;

(* window over IMAGE lift[a,b] as a UNIV if-integral.                        *)
let WINDOW_RESTRICT = prove
 (`!(h:real->complex) a b y. a <= b
   ==> integral (IMAGE lift (real_interval[a,b])) (\x. cexp(--(ii * Cx y *
     Cx(drop x))) * h(drop x)) =
       integral (:real^1) (\x. if a <= drop x /\ drop x <= b then cexp(--(ii *
         Cx y * Cx(drop x))) * h(drop x) else Cx(&0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `integral (:real^1) (\x. if a <= drop x /\ drop x <= b
                            then cexp(--(ii * Cx y * Cx(drop x))) *
                              (h:real->complex)(drop x) else Cx(&0)) =
    integral {x:real^1 | a <= drop x /\ drop x <= b} (\x. cexp(--(ii * Cx y *
      Cx(drop x))) * h(drop x))`
   SUBST1_TAC THENL
   [MP_TAC(ISPECL [`\x:real^1. cexp(--(ii * Cx y * Cx(drop x))) *
     (h:real->complex)(drop x)`;
                   `{x:real^1 | a <= drop x /\ drop x <= b}`]
                     INTEGRAL_RESTRICT_UNIV) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REWRITE_TAC[IN_ELIM_THM; COMPLEX_VEC_0];
    AP_THM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE_LIFT_DROP; IN_ELIM_THM;
      IN_REAL_INTERVAL]]);;

(* L1: truncated modulated Schwartz absint on UNIV.                          *)
let TRUNC_ABSINT = prove
 (`!(h:real->complex) c y. schwartz h
   ==> (\x. cexp(--(ii * Cx y * Cx(drop x))) * (if drop x < c then
     (h:real->complex)(drop x) else Cx(&0)))
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x. cexp(--(ii * Cx y * Cx(drop x))) * (if drop x < c then
     (h:real->complex)(drop x) else Cx(&0))) =
    (\x. if x IN {x:real^1 | drop x < c}
         then (\x. cexp(--(ii * Cx y * Cx(drop x))) * h(drop x)) x else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; IN_ELIM_THM] THEN GEN_TAC THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[COMPLEX_MUL_RZERO; COMPLEX_VEC_0];
    ALL_TAC] THEN
  REWRITE_TAC[ABSOLUTELY_INTEGRABLE_RESTRICT_UNIV] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `(:real^1)` THEN REWRITE_TAC[SUBSET_UNIV; HALFLINE_LMEAS] THEN
  MATCH_MP_TAC FOURIER_MODULATION_ABSINT THEN
  MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[]);;

(* L1': same, cexp INSIDE the if (matches the window integrand form).        *)
let TRUNC_ABSINT2 = prove
 (`!(h:real->complex) c y. schwartz h
   ==> (\x. if drop x < c then cexp(--(ii * Cx y * Cx(drop x))) *
     (h:real->complex)(drop x) else Cx(&0))
       absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x. if drop x < c then cexp(--(ii * Cx y * Cx(drop x))) *
     (h:real->complex)(drop x) else Cx(&0)) =
    (\x. if x IN {x:real^1 | drop x < c}
         then (\x. cexp(--(ii * Cx y * Cx(drop x))) * h(drop x)) x else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; IN_ELIM_THM] THEN GEN_TAC THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[COMPLEX_VEC_0];
    ALL_TAC] THEN
  REWRITE_TAC[ABSOLUTELY_INTEGRABLE_RESTRICT_UNIV] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
  EXISTS_TAC `(:real^1)` THEN REWRITE_TAC[SUBSET_UNIV; HALFLINE_LMEAS] THEN
  MATCH_MP_TAC FOURIER_MODULATION_ABSINT THEN
  MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[]);;

(* scalar-swap helper (div-form; applied forward to avoid complex_div        *)
(* rewrite that stack-overflows when traversing the giant integral atom).    *)
let CX_DIV_SWAP = prove
 (`!s b (z:complex). Cx(&1)/s * (Cx b * z) = Cx b * (Cx(&1)/s * z)`,
  REPEAT GEN_TAC THEN CONV_TAC COMPLEX_RING);;

(* L2: fourier(h.tt_c)(y) = Cx tt10 * fourier(1_{<c} h)(y).                  *)
let MULT_ONESIDED = prove
 (`!(h:real->complex) c y. schwartz h
   ==> fourier (\w. (h:real->complex) w * Cx(carleson_thetatilde c w)) (y) =
       Cx(carleson_thetatilde (&1) (&0)) * fourier (\w. if w < c then h w else
         Cx(&0)) y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[fourier] THEN
  SUBGOAL_THEN
   `(\x. cexp (--(ii * Cx y * Cx (drop x))) *
         ((h:real->complex) (drop x) * Cx (carleson_thetatilde c (drop x)))) =
    (\x. Cx(carleson_thetatilde (&1)(&0)) *
         (cexp (--(ii * Cx y * Cx (drop x))) *
          (if drop x < c then h(drop x) else Cx(&0))))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
    MP_TAC(ISPECL [`drop(x:real^1)`; `c:real`] CARLESON_THETATILDE_VALUE) THEN
    DISCH_THEN SUBST1_TAC THEN
    COND_CASES_TAC THEN CONV_TAC COMPLEX_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `integral (:real^1) (\x. Cx(carleson_thetatilde (&1)(&0)) *
         (cexp (--(ii * Cx y * Cx (drop x))) * (if drop x < c then
           (h:real->complex)(drop x) else Cx(&0)))) =
    Cx(carleson_thetatilde (&1)(&0)) *
    integral (:real^1) (\x. cexp (--(ii * Cx y * Cx (drop x))) * (if drop x < c
      then h(drop x) else Cx(&0)))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MP_TAC(ISPECL [`h:real->complex`; `c:real`; `y:real`] TRUNC_ABSINT) THEN
      ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_ACCEPT_TAC CX_DIV_SWAP);;

(* indicator pointwise: (if x<b then G else 0) - (if x<a then G else 0) =    *)
(* (if a<=x<b then G else 0). window-split integrand identity (scalar G,     *)
(* COND algebra -- fast, no integral atoms).                                 *)
let SPLIT_INTEGRAND = prove
 (`!a b (G:real^1->complex) x. a <= b
   ==> (if drop x < b then G x else Cx(&0)) - (if drop x < a then G x else
     Cx(&0)) =
       (if a <= drop x /\ drop x < b then G x else Cx(&0))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REPEAT COND_CASES_TAC THEN
  REWRITE_TAC[COMPLEX_SUB_REFL; COMPLEX_SUB_RZERO] THEN
  ASM_REAL_ARITH_TAC);;

(* the closed vs half-open window integrals agree ({drop x=b} null).         *)
let WINDOW_HALFOPEN = prove
 (`!(h:real->complex) a b y.
     integral (:real^1) (\x. if a <= drop x /\ drop x <= b then cexp(--(ii * Cx
       y * Cx(drop x))) * h(drop x) else Cx(&0)) =
     integral (:real^1) (\x. if a <= drop x /\ drop x < b then cexp(--(ii * Cx
       y * Cx(drop x))) * h(drop x) else Cx(&0))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC INTEGRAL_SPIKE THEN
  EXISTS_TAC `{x:real^1 | drop x = b}` THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM COMPLEX_VEC_0] THEN
    SUBGOAL_THEN
      `{x:real^1 | drop x = b} = {x:real^1 | x$1 = b}` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; drop];
      REWRITE_TAC[NEGLIGIBLE_STANDARD_HYPERPLANE]];
    X_GEN_TAC `x:real^1` THEN REWRITE_TAC[IN_DIFF; IN_UNIV; IN_ELIM_THM] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN
      `(drop x <= b <=> drop x < b)` (fun th -> REWRITE_TAC[th]) THEN
    ASM_REAL_ARITH_TAC]);;

(* WINDOW_SPLIT: closed-window integral = TB - TA (half-line integrals).     *)
let WINDOW_SPLIT = prove
 (`!(h:real->complex) a b y. schwartz h /\ a <= b
   ==> integral (:real^1) (\x. if a <= drop x /\ drop x <= b then cexp(--(ii *
     Cx y * Cx(drop x))) * h(drop x) else Cx(&0)) =
       integral (:real^1) (\x. if drop x < b then cexp(--(ii * Cx y * Cx(drop
         x))) * h(drop x) else Cx(&0)) -
       integral (:real^1) (\x. if drop x < a then cexp(--(ii * Cx y * Cx(drop
         x))) * h(drop x) else Cx(&0))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[WINDOW_HALFOPEN] THEN
  MP_TAC(ISPECL [`h:real->complex`; `b:real`; `y:real`] TRUNC_ABSINT2) THEN
  ASM_REWRITE_TAC[] THEN
    DISCH_THEN(ASSUME_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE) THEN
  MP_TAC(ISPECL [`h:real->complex`; `a:real`; `y:real`] TRUNC_ABSINT2) THEN
  ASM_REWRITE_TAC[] THEN
    DISCH_THEN(ASSUME_TAC o MATCH_MP ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE) THEN
  MP_TAC(ISPECL
   [`\x:real^1. if drop x < b then cexp(--(ii * Cx y * Cx(drop x))) *
     (h:real->complex)(drop x) else Cx(&0)`;
    `\x:real^1. if drop x < a then cexp(--(ii * Cx y * Cx(drop x))) *
      (h:real->complex)(drop x) else Cx(&0)`;
    `(:real^1)`] INTEGRAL_SUB) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
  ASM_SIMP_TAC[SPLIT_INTEGRAND]);;

(* TC = int_UNIV(if drop x<c then e^{-iyx}h else 0) = Cx sqrt2pi *           *)
(* fourier(1_{<c}h)(y).                                                      *)
let TC_FOURIER = prove
 (`!(h:real->complex) c y.
     integral (:real^1) (\x. if drop x < c then cexp(--(ii * Cx y * Cx(drop
       x))) * h(drop x) else Cx(&0)) =
     Cx(sqrt(&2 * pi)) * fourier (\w. if w < c then h w else Cx(&0)) y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[fourier] THEN
  SUBGOAL_THEN
   `(\x:real^1. cexp(--(ii * Cx y * Cx(drop x))) * (if drop x < c then
     (h:real->complex)(drop x) else Cx(&0))) =
    (\x. if drop x < c then cexp(--(ii * Cx y * Cx(drop x))) * h(drop x) else
      Cx(&0))`
   (fun th -> REWRITE_TAC[GSYM th]) THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[COMPLEX_MUL_RZERO]; ALL_TAC] THEN
  ABBREV_TAC `II = integral (:real^1) (\x. cexp(--(ii * Cx y * Cx(drop x))) *
                       (if drop x < c then (h:real->complex)(drop x) else
                         Cx(&0)))` THEN
  SUBGOAL_THEN `~(Cx(sqrt(&2 * pi)) = Cx(&0))` ASSUME_TAC THENL
   [REWRITE_TAC[CX_INJ] THEN MATCH_MP_TAC REAL_LT_IMP_NZ THEN
    MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `Cx(sqrt(&2 * pi)) * (Cx(&1)/Cx(sqrt(&2*pi)) * II) =
    (Cx(sqrt(&2*pi)) * Cx(&1)/Cx(sqrt(&2*pi))) * II` SUBST1_TAC THENL
   [CONV_TAC COMPLEX_RING; ALL_TAC] THEN
  ASM_SIMP_TAC[COMPLEX_DIV_LMUL; COMPLEX_MUL_LID; COMPLEX_MUL_RID]);;

(* norm(fourier(1_{<c}h)(y)) <= Atilde hcheck(-y) / (2 pi tt10).             *)
let FC_NORM_LE = prove
 (`!(h:real->complex) c y. schwartz h
   ==> norm(fourier (\w. if w < c then (h:real->complex) w else Cx(&0)) y)
       <= carleson_Atilde (\x. fourier h (--x)) (--y) / (&2 * pi *
         carleson_thetatilde (&1)(&0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&0 < carleson_thetatilde (&1)(&0)` ASSUME_TAC THENL
   [REWRITE_TAC[CARLESON_THETATILDE_1_0_POS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `Cx(carleson_thetatilde (&1)(&0)) * fourier (\w. if w < c then
     (h:real->complex) w else Cx(&0)) y =
    fourier (\w. h w * Cx(carleson_thetatilde c w)) y`
   (MP_TAC o AP_TERM `norm:complex->real`) THENL
   [MP_TAC(ISPECL [`h:real->complex`; `c:real`; `y:real`] MULT_ONESIDED) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN
    `abs(carleson_thetatilde (&1)(&0)) = carleson_thetatilde (&1)(&0)`
    SUBST1_TAC THENL
   [ASM_REAL_ARITH_TAC; ALL_TAC] THEN
  (* now hyp: tt * norm F_c = norm(fourier(h tt_c)); goal: norm F_c <= AT/(2 *)
  (* pi tt).                                                                 *)
  DISCH_TAC THEN
  MP_TAC(ISPECL [`h:real->complex`; `c:real`; `y:real`] KERNEL_DOM_HCHECK) THEN
  ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `FC = norm(fourier (\w. if w < c then (h:real->complex) w else
    Cx(&0)) y)` THEN
  ABBREV_TAC `NN = norm(fourier (\w. (h:real->complex) w *
    Cx(carleson_thetatilde c w)) y)` THEN
  ABBREV_TAC `AT = carleson_Atilde (\x. fourier (h:real->complex) (--x)) (--y)`
    THEN
  ABBREV_TAC `tt = carleson_thetatilde (&1)(&0)` THEN
  (* hyps: tt * FC = NN,  2 pi * NN <= AT,  0 < tt,  0 < pi (PI_POS)         *)
  STRIP_TAC THEN
  SUBGOAL_THEN `&2 * pi * tt * FC <= AT` MP_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) then SUBST1_TAC th else NO_TAC)
     THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 * pi * tt` ASSUME_TAC THENL
   [MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_MUL THEN MP_TAC PI_POS THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `AT / (&2 * pi * carleson_thetatilde (&1)(&0)) = AT / (&2 * pi * tt)`
   SUBST1_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ] THEN
  REWRITE_TAC[REAL_ARITH `FC * (&2 * pi * tt) = &2 * pi * tt * FC`] THEN
  ASM_REWRITE_TAC[]);;

(* WINDOW_LE: each Ahat window summand <= inv(pi tt10) Atilde hcheck(-y).    *)
let WINDOW_LE = prove
 (`!(h:real->complex) a b y. schwartz h /\ a <= b
   ==> inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[a,b])) (\x. cexp(--(ii * Cx y *
         Cx(drop x))) * h(drop x)))
       <= inv(pi * carleson_thetatilde (&1)(&0)) * carleson_Atilde (\x. fourier
         h (--x)) (--y)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[WINDOW_RESTRICT; WINDOW_SPLIT; TC_FOURIER] THEN
  SUBGOAL_THEN `&0 < carleson_thetatilde (&1)(&0)` ASSUME_TAC THENL
   [REWRITE_TAC[CARLESON_THETATILDE_1_0_POS]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `inv(sqrt(&2 * pi)) *
    (norm(Cx(sqrt(&2 * pi)) * fourier (\w. if w < b then (h:real->complex) w
      else Cx(&0)) y) +
     norm(Cx(sqrt(&2 * pi)) * fourier (\w. if w < a then (h:real->complex) w
       else Cx(&0)) y))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN MATCH_MP_TAC SQRT_POS_LE THEN
      MP_TAC PI_POS THEN REAL_ARITH_TAC;
      NORM_ARITH_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[COMPLEX_NORM_MUL; COMPLEX_NORM_CX] THEN
  SUBGOAL_THEN `abs(sqrt(&2 * pi)) = sqrt(&2 * pi)` SUBST1_TAC THENL
   [REWRITE_TAC[REAL_ABS_REFL] THEN MATCH_MP_TAC SQRT_POS_LE THEN
    MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`h:real->complex`; `b:real`; `y:real`] FC_NORM_LE) THEN
  MP_TAC(ISPECL [`h:real->complex`; `a:real`; `y:real`] FC_NORM_LE) THEN
  ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `FB = norm(fourier (\w. if w < b then (h:real->complex) w else
    Cx(&0)) y)` THEN
  ABBREV_TAC `FA = norm(fourier (\w. if w < a then (h:real->complex) w else
    Cx(&0)) y)` THEN
  ABBREV_TAC `AT = carleson_Atilde (\x. fourier (h:real->complex) (--x)) (--y)`
    THEN
  ABBREV_TAC `tt = carleson_thetatilde (&1)(&0)` THEN
  STRIP_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `&0 < sqrt(&2 * pi)` ASSUME_TAC THENL
   [MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
     REAL_ARITH_TAC; ALL_TAC] THEN
  (* inv sqrt2pi * (sqrt2pi*FB + sqrt2pi*FA) = FB+FA <= 2*(AT/(2 pi tt)) =   *)
  (* AT/(pi tt)                                                              *)
  SUBGOAL_THEN
    `inv(sqrt(&2 * pi)) * (sqrt(&2 * pi) * FB + sqrt(&2 * pi) * FA) = FB + FA`
   SUBST1_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP REAL_LT_IMP_NZ) THEN
     CONV_TAC REAL_FIELD; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC `AT / (&2 * pi * tt) + AT / (&2 * pi * tt)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_ADD2 THEN ASM_REWRITE_TAC[];
    MP_TAC PI_POS THEN MP_TAC(ASSUME `&0 < tt`) THEN CONV_TAC REAL_FIELD]);;

(* S7 = AHAT_LE_ATILDE: sup over windows via REAL_SUP_LE.                    *)
let AHAT_LE_ATILDE = prove
 (`!(h:real->complex) y. schwartz h
   ==> carleson_Ahat h y
       <= inv(pi * carleson_thetatilde (&1) (&0)) *
          carleson_Atilde (\x. fourier h (--x)) (--y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[carleson_Ahat] THEN
  MATCH_MP_TAC REAL_SUP_LE THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    MAP_EVERY EXISTS_TAC
     [`inv(sqrt(&2 * pi)) *
       norm(integral (IMAGE lift (real_interval[&0,&0])) (\x. cexp(--(ii * Cx y
         * Cx(drop x))) * (h:real->complex)(drop x)))`;
      `&0:real`; `&0:real`] THEN
    REWRITE_TAC[REAL_LE_REFL];
    REWRITE_TAC[IN_ELIM_THM] THEN REPEAT STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC WINDOW_LE THEN ASM_REWRITE_TAC[]]);;

(* carleson_Atilde h integrable on FF (from the 286P hypothesis via          *)
(* REAL_FATOU).                                                              *)
let ATILDE_INTEGRABLE_F = prove
 (`!(h:real->complex) FF C9.
     schwartz h /\ real_measurable FF /\ &0 <= C9 /\
     (!(g:real->complex) GG. schwartz g /\ real_measurable GG
          ==> real_integral GG (carleson_A g) <= &4 * C9 * lnorm (:real^1) (&2)
            (\z. g (drop z)) * sqrt (real_measure GG))
   ==> (\x. carleson_Atilde h x) real_integrable_on FF`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `B = &4 * C9 * log(&2) * lnorm (:real^1) (&2) (\z.
    (h:real->complex) (drop z)) * sqrt(real_measure FF)` THEN
  MP_TAC(ISPECL [`carleson_Aavg (h:real->complex)`; `FF:real->bool`;
    `B:real`] REAL_FATOU_LIMINF) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [GEN_TAC THEN GEN_REWRITE_TAC (RATOR_CONV o RAND_CONV) [GSYM ETA_AX] THEN
      MATCH_MP_TAC AAVG_ABSINT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL
     [REPEAT GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC AAVG_NONNEG THEN
       ASM_REWRITE_TAC[];
      GEN_TAC THEN GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [GSYM ETA_AX] THEN
      EXPAND_TAC "B" THEN MATCH_MP_TAC AAVG_INT_F_ALLN THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:real->real` (X_CHOOSE_THEN
    `k:real->bool` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`g:real->real`; `\x. carleson_Atilde (h:real->complex) x`;
    `k:real->bool`; `FF:real->bool`] REAL_INTEGRABLE_SPIKE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  X_GEN_TAC `x:real` THEN REWRITE_TAC[IN_DIFF] THEN STRIP_TAC THEN
  REWRITE_TAC[carleson_Atilde] THEN
  MATCH_MP_TAC REALLIM_OF_CONVERGENT THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[IN_DIFF]);;

(* reflection preserves real-measurability.                                  *)
let REFLECT_RMEAS = prove
 (`!s. real_measurable s ==> real_measurable (IMAGE (--) s)`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `IMAGE (--) s = IMAGE (\x. --(&1) * x) s` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE] THEN
     MESON_TAC[REAL_MUL_LID; REAL_ARITH `--(&1) * x = --x`];
    ASM_SIMP_TAC[REAL_MEASURABLE_SCALING]]);;

(* reflection preserves real-measure.                                        *)
let REFLECT_RMEASURE = prove
 (`!s. real_measurable s ==> real_measure (IMAGE (--) s) = real_measure s`,
  GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `IMAGE (--) s = IMAGE (\x. --(&1) * x) s` SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_IMAGE] THEN
     MESON_TAC[REAL_MUL_LID; REAL_ARITH `--(&1) * x = --x`];
    ALL_TAC] THEN
  MATCH_MP_TAC REAL_MEASURE_UNIQUE THEN
  MP_TAC(ISPECL [`s:real->bool`; `--(&1):real`;
    `real_measure s`] HAS_REAL_MEASURE_SCALING) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[GSYM HAS_REAL_MEASURE_MEASURE];
    REWRITE_TAC[REAL_ABS_NEG; REAL_ABS_NUM; REAL_MUL_LID]]);;

(* ||hcheck||_2 = ||h||_2  (reflection isometry + Plancherel).               *)
let HCHECK_LNORM = prove
 (`!(h:real->complex). schwartz h
   ==> lnorm (:real^1) (&2) (\z. fourier h (--(drop z))) = lnorm (:real^1) (&2)
     (\z. h (drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. fourier h (--(drop z))) = (\z. (\w:real^1. fourier
     (h:real->complex) (drop w)) (--z))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; DROP_NEG]; ALL_TAC] THEN
  REWRITE_TAC[LNORM_REFLECT] THEN
  MATCH_MP_TAC PLANCHEREL_LNORM_SCHWARTZ THEN ASM_REWRITE_TAC[]);;

(* (\y. Atilde hcheck(-y)) integrable on FF (reflection of                   *)
(* ATILDE_INTEGRABLE_F).                                                     *)
let REFL_ATILDE_INT = prove
 (`!(h:real->complex) FF C9.
     schwartz h /\ real_measurable FF /\ &0 <= C9 /\
     (!(g:real->complex) GG. schwartz g /\ real_measurable GG
          ==> real_integral GG (carleson_A g) <= &4 * C9 * lnorm (:real^1) (&2)
            (\z. g (drop z)) * sqrt (real_measure GG))
   ==> (\y. carleson_Atilde (\x. fourier (h:real->complex) (--x)) (--y))
     real_integrable_on FF`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[REAL_INTEGRABLE_REFLECT_GEN] THEN
  MP_TAC(ISPECL [`\x. fourier (h:real->complex) (--x)`;
    `IMAGE (--) (FF:real->bool)`; `C9:real`] ATILDE_INTEGRABLE_F) THEN
  ASM_SIMP_TAC[SCHWARTZ_HCHECK; REFLECT_RMEAS] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[ETA_AX]);;

(* S8 tail: int_FF (\y. inv(pi tt10) Atilde hcheck(-y)) <= C10 ||h|| sqrt    *)
(* muF.                                                                      *)
let S8_TAIL = prove
 (`!(h:real->complex) FF C9.
     schwartz h /\ real_measurable FF /\ &0 <= C9 /\
     (!(g:real->complex) GG. schwartz g /\ real_measurable GG
          ==> real_integral GG (carleson_A g) <= &4 * C9 * lnorm (:real^1) (&2)
            (\z. g (drop z)) * sqrt (real_measure GG))
   ==> real_integral FF (\y. inv(pi * carleson_thetatilde (&1)(&0)) *
                             carleson_Atilde (\x. fourier (h:real->complex)
                               (--x)) (--y))
       <= (&4 * C9 * log(&2) / (pi * carleson_thetatilde (&1)(&0))) *
          lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure FF)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `real_integral FF (\y. inv(pi * carleson_thetatilde (&1)(&0)) *
                          carleson_Atilde (\x. fourier (h:real->complex) (--x))
                            (--y)) =
    inv(pi * carleson_thetatilde (&1)(&0)) *
    real_integral FF (\y. carleson_Atilde (\x. fourier (h:real->complex) (--x))
      (--y))`
   SUBST1_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LMUL THEN
    MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`;
      `C9:real`] REFL_ATILDE_INT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `real_integral FF (\y. carleson_Atilde (\x. fourier (h:real->complex) (--x))
     (--y)) =
    real_integral (IMAGE (--) FF) (\y. carleson_Atilde (\x. fourier
      (h:real->complex) (--x)) y)`
   SUBST1_TAC THENL
   [REWRITE_TAC[real_integral] THEN AP_TERM_TAC THEN ABS_TAC THEN
    REWRITE_TAC[HAS_REAL_INTEGRAL_REFLECT_GEN]; ALL_TAC] THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `inv(pi * carleson_thetatilde (&1)(&0)) *
    (&4 * C9 * log(&2) * lnorm (:real^1) (&2) (\z. fourier (h:real->complex)
      (--(drop z))) *
     sqrt(real_measure (IMAGE (--) FF)))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_LMUL THEN CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_INV THEN
      MATCH_MP_TAC REAL_LE_MUL THEN
      MP_TAC PI_POS THEN MP_TAC CARLESON_THETATILDE_1_0_POS THEN
        REAL_ARITH_TAC;
      MP_TAC(ISPECL [`\x. fourier (h:real->complex) (--x)`;
        `IMAGE (--) (FF:real->bool)`; `C9:real`] ATILDE_INT_F_BOUND) THEN
      ASM_SIMP_TAC[SCHWARTZ_HCHECK; REFLECT_RMEAS] THEN
      REWRITE_TAC[ETA_AX]]; ALL_TAC] THEN
  ASM_SIMP_TAC[HCHECK_LNORM; REFLECT_RMEASURE] THEN
  MATCH_MP_TAC REAL_EQ_IMP_LE THEN
  REWRITE_TAC[real_div] THEN CONV_TAC REAL_RING);;

(* 286Q/R/S/T reduction (Fremlin 2361-2948): the tile bound 286P propagates  *)
(* via                                                                       *)
(* 286Q (dilation theta') -> 286R (averaged bump theta-tilde) -> 286S (int_F *)
(* Atilde h <= 4 C9 log2 ...) -> 286T(b) (Ahat h <= (1/(pi thetatilde_1(0))) *)
(* Atilde                                                                    *)
(* hcheck(-y), C10 = 4 C9 log2/(pi thetatilde_1(0))) to the linearized       *)
(* maximal                                                                   *)
(* operator.                                                    *)
let CARLESON_286T_FROM_286P = prove
 (`(?C9. &0 <= C9 /\
      !(h:real->complex) FF.
         schwartz h /\ real_measurable FF
         ==> (carleson_A h) real_measurable_on (:real) /\
             real_integral FF (carleson_A h)
             <= &4 * C9 * lnorm (:real^1) (&2) (\z. h(drop z)) *
               sqrt(real_measure FF))
     ==> ?C10. &0 <= C10 /\
         !(h:real->complex) FF.
            schwartz h /\ real_measurable FF
            ==> real_integral FF (carleson_Ahat h)
                <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) *
                  sqrt(real_measure FF)`,
  DISCH_THEN(X_CHOOSE_THEN `C9:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `&4 * C9 * log(&2) / (pi * carleson_thetatilde (&1) (&0))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_DIV THEN CONJ_TAC THENL
     [MATCH_MP_TAC LOG_POS THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
       [MP_TAC PI_POS THEN REAL_ARITH_TAC;
        MP_TAC CARLESON_THETATILDE_1_0_POS THEN REAL_ARITH_TAC]];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`h:real->complex`; `FF:real->bool`] THEN STRIP_TAC THEN
  MATCH_MP_TAC REAL_LE_TRANS THEN
  EXISTS_TAC
   `real_integral FF (\y. inv(pi * carleson_thetatilde (&1)(&0)) *
                          carleson_Atilde (\x. fourier (h:real->complex) (--x))
                            (--y))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRAL_LE THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_SCHWARTZ_INTEGRABLE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN
      MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`;
        `C9:real`] REFL_ATILDE_INT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN
        ACCEPT_TAC];
      X_GEN_TAC `y:real` THEN DISCH_TAC THEN BETA_TAC THEN
      MATCH_MP_TAC AHAT_LE_ATILDE THEN ASM_REWRITE_TAC[]];
    MP_TAC(ISPECL [`h:real->complex`; `FF:real->bool`; `C9:real`] S8_TAIL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN
      ACCEPT_TAC]]);;

(* 286T(b): the Schwartz maximal bound from the 286P estimates.              *)
let CARLESON_286T_SCHWARTZ = prove
 (`?C10. &0 <= C10 /\
     !(h:real->complex) FF.
        schwartz h /\ real_measurable FF
        ==> real_integral FF (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              FF)`,
  MATCH_MP_TAC CARLESON_286T_FROM_286P THEN ACCEPT_TAC CARLESON_286P);;


(* An L^2 function on R is absolutely integrable (L^1) on any compact        *)
(* interval, since the interval has finite measure: L^2 restricted to it     *)
(* (LSPACE_SUBSET) then L^2 c L^1 on finite measure (LSPACE_INCLUSION,       *)
(* p=1<=q=2) and lspace(&1)=absolutely_integrable. Feeds the Fubini-strip    *)
(* step of 286U(c) (G|[-n,n] is L^1, so the tower's global-L^1 Fubini        *)
(* machinery applies).                                                       *)

let LSPACE_ABSINT_ON_INTERVAL = prove
 (`!(G:real^1->complex) a b.
     G IN lspace (:real^1) (&2)
     ==> G absolutely_integrable_on (IMAGE lift (real_interval[a,b]))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[GSYM LSPACE_1] THEN
  MP_TAC(ISPECL [`IMAGE lift (real_interval[a,b])`; `&1`; `&2`]
    (INST_TYPE [`:1`,`:M`; `:2`,`:N`] LSPACE_INCLUSION)) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL; MEASURABLE_INTERVAL] THEN
    CONV_TAC REAL_RAT_REDUCE_CONV;
    REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC LSPACE_SUBSET THEN EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV; IMAGE_LIFT_REAL_INTERVAL;
      LEBESGUE_MEASURABLE_INTERVAL]]);;
(* An L^2 function with compact support is absolutely integrable (L^1) on    *)
(* the whole line: restrict to the containing interval [-(c+1),c+1]          *)
(* (LSPACE_ABSINT_ON_INTERVAL) and note it agrees with its restriction there *)
(* (vanishes outside).                                                       *)
let CSUPP_L2_ABSINT = prove
 (`!(e:real^1->complex) c.
     e IN lspace (:real^1) (&2) /\ &0 <= c /\ (!z. abs(drop z) > c ==> e z =
       Cx(&0))
     ==> e absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`e:real^1->complex`; `--(c+ &1):real`;
    `c+ &1:real`] LSPACE_ABSINT_ON_INTERVAL) THEN
  ASM_REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN
  SUBGOAL_THEN
   `e absolutely_integrable_on interval[lift(--(c+ &1)),lift(c+ &1)] <=>
    (\z. if z IN interval[lift(--(c+ &1)),lift(c+ &1)] then (e:real^1->complex)
      z else vec 0)
      absolutely_integrable_on (:real^1)`
   SUBST1_TAC THENL
   [REWRITE_TAC[ABSOLUTELY_INTEGRABLE_RESTRICT_UNIV]; ALL_TAC] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN COND_CASES_TAC THEN
  REWRITE_TAC[COMPLEX_VEC_0] THEN CONV_TAC SYM_CONV THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN POP_ASSUM MP_TAC THEN
  REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP] THEN REAL_ARITH_TAC);;

(* Explicit-constant form of the compact-support L^2 -> L^1 bound (the       *)
(* Cauchy-                                                                   *)
(* Schwarz constant K = ||chi[-(c+1),c+1]||_2 is displayed rather than       *)
(* existential,                                                              *)
(* so a whole SEQUENCE of csupp functions can share the same K). HOELDER     *)
(* (p=q=2)                                                                   *)
(* with the interval indicator; off the interval e vanishes so the           *)
(* norm-product                                                              *)
(* matches norm(e) exactly.                                                  *)
let CSUPP_L2_L1_EXPLICIT = prove
 (`!(e:real^1->complex) c.
     e IN lspace (:real^1) (&2) /\ &0 <= c /\ (!z. abs(drop z) > c ==> e z =
       Cx(&0))
     ==> drop(integral (:real^1) (\z. lift(norm(e z)))) <=
         lnorm (:real^1) (&2) e *
         lnorm (:real^1) (&2) (\z:real^1. if z IN interval[lift(--(c+ &1)),
           lift(c+ &1)] then Cx(&1) else Cx(&0))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`(:real^1)`; `&2`; `&2`; `e:real^1->complex`;
    `\z:real^1. if z IN interval[lift(--(c+ &1)), lift(c+ &1)] then Cx(&1) else
      Cx(&0)`]
   HOELDER_INEQUALITY) THEN
  ASM_REWRITE_TAC[INDICATOR_INTERVAL_L2] THEN
  ANTS_TAC THENL [CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `a = b ==> b <= c ==> a <= c`) THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
  X_GEN_TAC `z:real^1` THEN AP_TERM_TAC THEN
  COND_CASES_TAC THEN
    REWRITE_TAC[COMPLEX_NORM_CX; REAL_ABS_NUM; REAL_MUL_RID] THEN
  SUBGOAL_THEN
    `(e:real^1->complex) z = Cx(&0)` (fun th -> REWRITE_TAC[th;
    COMPLEX_NORM_CX; REAL_ABS_NUM]) THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN
    POP_ASSUM MP_TAC THEN REWRITE_TAC[IN_INTERVAL_1; LIFT_DROP] THEN
      REAL_ARITH_TAC;
    REWRITE_TAC[REAL_MUL_RZERO]]);;

(* L^1 convergence from L^2 convergence on a FIXED compact support: if d k   *)
(* -> 0 in                                                                   *)
(* L^2 and all d k vanish outside [-c,c], then int norm(d k) -> 0.           *)
(* Comparison                                                                *)
(* (REALLIM_NULL_COMPARISON) against K * ||d k||_2 with the shared K from    *)
(* CSUPP_L2_L1_EXPLICIT; K * ||d k|| -> 0 by REALLIM_NULL_RMUL. This turns   *)
(* the                                                                       *)
(* L^2-approximation into the L^1 control needed for uniform Fourier         *)
(* convergence.                                                              *)
let L1_LIM_FROM_L2_CSUPP = prove
 (`!(d:num->real^1->complex) c.
     &0 <= c /\
     (!k. (d k) IN lspace (:real^1) (&2)) /\
     (!k z. abs(drop z) > c ==> d k z = Cx(&0)) /\
     ((\k. lnorm (:real^1) (&2) (d k)) ---> &0) sequentially
     ==> ((\k. drop(integral (:real^1) (\z. lift(norm(d k z))))) ---> &0)
       sequentially`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN
  EXISTS_TAC `\k. lnorm (:real^1) (&2) ((d:num->real^1->complex) k) *
     lnorm (:real^1) (&2) (\z:real^1. if z IN interval[lift(--(c+ &1)), lift(c+
       &1)] then Cx(&1) else Cx(&0))` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
    X_GEN_TAC `k:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC(REAL_ARITH `&0 <= x /\ x <= y ==> abs x <= y`) THEN
      CONJ_TAC THENL
     [MATCH_MP_TAC INTEGRAL_DROP_POS THEN CONJ_TAC THENL
       [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
        MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
        MATCH_MP_TAC CSUPP_L2_ABSINT THEN EXISTS_TAC `c:real` THEN
          ASM_REWRITE_TAC[ETA_AX];
        REWRITE_TAC[LIFT_DROP; NORM_POS_LE]];
      MATCH_MP_TAC CSUPP_L2_L1_EXPLICIT THEN ASM_SIMP_TAC[]];
    MATCH_MP_TAC REALLIM_NULL_RMUL THEN ASM_REWRITE_TAC[]]);;


(* Distributional-uniqueness for L^2 functions: if d in L^2 pairs to zero    *)
(* against                                                                   *)
(* every Schwartz test function, d = 0 a.e. L2_SUBINTERVAL_ZERO gives        *)
(* int_{[a,b]}                                                               *)
(* d = 0 on every interval; INTEGRAL_ZERO_ON_SUBINTERVALS_IMP_ZERO_AE_ALT    *)
(* concludes; d is integrable on each interval by                           *)
(* LSPACE_ABSINT_ON_INTERVAL.                                                *)
let WINDOWED_FOURIER_REPS = prove
 (`!(G:real^1->complex) (h:real->complex) n.
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> integral (:real^1) (\z. fourier (\x. if abs x <= &n then G(lift x)
       else Cx(&0)) (drop z) * h(drop z)) =
         integral (:real^1) (\z. (\x. if abs x <= &n then G(lift x) else
           Cx(&0))(drop z) * fourier h (drop z))`,
  REPEAT STRIP_TAC THEN CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC FOURIER_283O THEN CONJ_TAC THENL
   [SUBGOAL_THEN
     `(\z. (\x. if abs x <= &n then (G:real^1->complex)(lift x) else
       Cx(&0))(drop z)) =
      (\z. if drop z IN real_interval[--(&n),&n] then G z else vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
       REWRITE_TAC[IN_REAL_INTERVAL] THEN
      REWRITE_TAC[REAL_ARITH `--(&n) <= drop z /\ drop z <= &n <=> abs(drop z)
        <= &n`] THEN
      REWRITE_TAC[LIFT_DROP; COMPLEX_VEC_0]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!z:real^1. (drop z IN real_interval[--(&n),&n]) <=> z IN
       interval[lift(--(&n)), lift(&n)]`
     (fun th -> ONCE_REWRITE_TAC[th]) THENL
     [GEN_TAC THEN
       REWRITE_TAC[IN_INTERVAL_1; IN_REAL_INTERVAL; LIFT_DROP]; ALL_TAC] THEN
    REWRITE_TAC[ABSOLUTELY_INTEGRABLE_RESTRICT_UNIV] THEN
    REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
    MATCH_MP_TAC LSPACE_ABSINT_ON_INTERVAL THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[ETA_AX] THEN MATCH_MP_TAC SCHWARTZ_ABSINT THEN
      ASM_REWRITE_TAC[]]);;

(* The closed-window truncations phin = G*chi[-n,n] converge to G in L^2     *)
(* norm:                                                                     *)
(* ||phin - G||_2 -> 0.  Lebesgue dominated convergence (LSPACE_DOMINATED_   *)
(* CONVERGENCE) with dominator G and pointwise limit (eventually abs(drop x) *)
(* <= &n,                                                                    *)
(* REAL_ARCH_SIMPLE).  Feeds the L^2-Cauchy-ness of the window transforms.   *)
let CLOSED_WINDOW_LNORM_LIM = prove
 (`!(G:real^1->complex).
     G IN lspace (:real^1) (&2)
     ==> ((\n. lnorm (:real^1) (&2)
              (\z. (if abs(drop z) <= &n then G z else vec 0) - G z)) ---> &0)
         sequentially`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\n:num. \z:real^1. if abs(drop z) <= &n then (G:real^1->complex) z else
     vec 0`;
    `G:real^1->complex`; `G:real^1->complex`; `(:real^1)`; `&2`;
      `{}:real^1->bool`]
   LSPACE_DOMINATED_CONVERGENCE) THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; DIFF_EMPTY; IN_UNIV] THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [REAL_ARITH_TAC;
      GEN_TAC THEN
      SUBGOAL_THEN
       `(\z:real^1. if abs(drop z) <= &n then (G:real^1->complex) z else vec 0)
         =
        (\z. if z IN {z | abs(drop z) <= &n} then G z else vec 0)`
       SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
      MATCH_MP_TAC TRUNC_IN_LSPACE THEN
      ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
      SUBGOAL_THEN
        `{z:real^1 | abs(drop z) <= &n} = interval[lift(--(&n)),lift(&n)]`
       SUBST1_TAC THENL
       [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_INTERVAL_1; LIFT_DROP] THEN
        GEN_TAC THEN REAL_ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[LEBESGUE_MEASURABLE_INTERVAL];
      ASM_REWRITE_TAC[];
      REPEAT GEN_TAC THEN COND_CASES_TAC THEN
        REWRITE_TAC[NORM_0; NORM_POS_LE; REAL_LE_REFL];
      X_GEN_TAC `x:real^1` THEN MATCH_MP_TAC LIM_EVENTUALLY THEN
      REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN
      MP_TAC(ISPEC `abs(drop(x:real^1))` REAL_ARCH_SIMPLE) THEN
      DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN EXISTS_TAC `N:num` THEN
      X_GEN_TAC `n:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `abs(drop(x:real^1)) <= &n` (fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `&N:real` THEN
      ASM_REWRITE_TAC[REAL_OF_NUM_LE]];
    STRIP_TAC THEN ASM_REWRITE_TAC[]]);;

(* Modulation e^{-idx} preserves absolute integrability on any               *)
(* Lebesgue-measurable set (cexp unimodular +                                *)
(* ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT); the interval version   *)
(* of FOURIER_MODULATION_ABSINT, needed for the strip-Fubini y-slice.        *)

let MODULATION_ABSINT_LMEAS = prove
 (`!(G:real^1->complex) d s.
     lebesgue_measurable s /\ G absolutely_integrable_on s
     ==> (\x. cexp(--(ii * Cx d * Cx(drop x))) * G x) absolutely_integrable_on
       s`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`( * ):complex->complex->complex`;
                 `\x:real^1. cexp(--(ii * Cx d * Cx(drop x)))`;
                 `G:real^1->complex`; `s:real^1->bool`]
    ABSOLUTELY_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT) THEN
  ASM_REWRITE_TAC[BILINEAR_COMPLEX_MUL] THEN DISCH_THEN MATCH_MP_TAC THEN
    CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_LEBESGUE_MEASURABLE_SUBSET THEN
     EXISTS_TAC `(:real^1)` THEN
    ASM_REWRITE_TAC[SUBSET_UNIV] THEN
    MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    SUBGOAL_THEN `(\x:real^1. cexp(--(ii * Cx d * Cx(drop x)))) =
                  cexp o (\x. --((ii * Cx d) * Cx(drop x)))`
     SUBST1_TAC THENL [REWRITE_TAC[o_DEF; COMPLEX_MUL_ASSOC]; ALL_TAC] THEN
    MATCH_MP_TAC CONTINUOUS_ON_COMPOSE THEN
      REWRITE_TAC[CONTINUOUS_ON_CEXP] THEN
    MATCH_MP_TAC CONTINUOUS_ON_NEG THEN
      MATCH_MP_TAC CONTINUOUS_ON_COMPLEX_MUL THEN
    REWRITE_TAC[CONTINUOUS_ON_CONST] THEN
      MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN
    REWRITE_TAC[CONTINUOUS_ON_ID];
    REWRITE_TAC[bounded; FORALL_IN_IMAGE] THEN EXISTS_TAC `&1` THEN
    X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `--(ii * Cx d * Cx(drop x)) = ii * Cx(--(d * drop x))` SUBST1_TAC THENL
     [REWRITE_TAC[CX_NEG; CX_MUL] THEN SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[NORM_CEXP_II] THEN REAL_ARITH_TAC]);;

(* L^1 bound on the difference of Fourier transforms: norm(fhat(y) -         *)
(* ghat(y)) is at                                                            *)
(* most (1/sqrt2pi) times the L^1 norm of f - g. Linearity of fourier        *)
(* (FOURIER_ADD/                                                             *)
(* FOURIER_LMUL, valid since both modulated integrands are integrable via    *)
(* MODULATION_ABSINT_LMEAS) collapses fhat - ghat to fourier(f-g); then      *)
(* FOURIER_BOUND.                                                            *)
let FOURIER_DIFF_L1_BOUND = prove
 (`!(f:real->complex) g y.
     (\z. f(drop z)) absolutely_integrable_on (:real^1) /\
     (\z. g(drop z)) absolutely_integrable_on (:real^1)
     ==> norm(fourier f y - fourier g y) <=
         &1 / sqrt(&2 * pi) * drop(integral (:real^1) (\z. lift(norm(f(drop z)
           - g(drop z)))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x))
     integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC MODULATION_ABSINT_LMEAS THEN
      ASM_REWRITE_TAC[LEBESGUE_MEASURABLE_UNIV]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\x. cexp(--(ii * Cx y * Cx(drop x))) * (g:real->complex)(drop x))
     integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC MODULATION_ABSINT_LMEAS THEN
      ASM_REWRITE_TAC[LEBESGUE_MEASURABLE_UNIV]; ALL_TAC] THEN
  SUBGOAL_THEN
    `fourier (f:real->complex) y - fourier g y = fourier (\x. f x - g x) y`
   SUBST1_TAC THENL
   [SUBGOAL_THEN `(\x. (f:real->complex) x - g x) = (\x. f x + (--(&1)) % g x)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[COMPLEX_CMUL] THEN
      SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `fourier (\x. (f:real->complex) x + --(&1) % g x) y = fourier f y +
       fourier (\x. --(&1) % g x) y`
     SUBST1_TAC THENL
     [MATCH_MP_TAC FOURIER_ADD THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[COMPLEX_CMUL] THEN
      SUBGOAL_THEN
        `(\x. cexp(--(ii * Cx y * Cx(drop x))) * (Cx(--(&1)) *
        (g:real->complex)(drop x))) =
                    (\x. Cx(--(&1)) * (cexp(--(ii * Cx y * Cx(drop x))) *
                      g(drop x)))`
       SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
         SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[COMPLEX_CMUL] THEN
    SUBGOAL_THEN
      `fourier (\x. Cx(--(&1)) * (g:real->complex) x) y =
       Cx(--(&1)) * fourier g y`
     SUBST1_TAC THENL
     [MATCH_MP_TAC FOURIER_LMUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`\x. (f:real->complex) x - g x`; `y:real`] FOURIER_BOUND) THEN
  REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN
       `(\x. cexp(--(ii * Cx y * Cx(drop x))) * ((f:real->complex)(drop x) -
         g(drop x))) =
        (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x) -
             cexp(--(ii * Cx y * Cx(drop x))) * g(drop x))`
       SUBST1_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
         SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
      MATCH_MP_TAC INTEGRABLE_SUB THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `(\x. lift(norm((f:real->complex)(drop x) - g(drop x)))) =
        (\x. lift(norm((\z. f(drop z) - g(drop z)) x)))` SUBST1_TAC THENL
       [REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
      MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_SUB THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[]);;

(* Uniform (pointwise-everywhere) Fourier convergence from L^1 convergence:  *)
(* if the                                                                    *)
(* L^1 norms int norm(a k - b) -> 0, then fhat(a k)(y) -> fhat(b)(y) for     *)
(* every y.                                                                  *)
(* Immediate from FOURIER_DIFF_L1_BOUND via LIM_NULL_COMPARISON. This is the *)
(* pointwise                                                                 *)
(* limit that gets reconciled (by FATOU) with the L^2 RIESZ limit in         *)
(* WINDOWED_FOURIER_L2.                                                      *)
let FOURIER_UNIF_LIM_FROM_L1 = prove
 (`!(a:num->real->complex) b y.
     (!k. (\z. a k (drop z)) absolutely_integrable_on (:real^1)) /\
     (\z. b(drop z)) absolutely_integrable_on (:real^1) /\
     ((\k. drop(integral (:real^1) (\z. lift(norm(a k (drop z) - b(drop z))))))
       ---> &0) sequentially
     ==> ((\k. fourier ((a:num->real->complex) k) y) --> fourier b y)
       sequentially`,
  REPEAT STRIP_TAC THEN ONCE_REWRITE_TAC[LIM_NULL] THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC LIM_NULL_COMPARISON THEN
  EXISTS_TAC `\k. &1 / sqrt(&2 * pi) *
     drop(integral (:real^1) (\z. lift(norm((a:num->real->complex) k (drop z) -
       b(drop z)))))` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `0` THEN
    X_GEN_TAC `k:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC FOURIER_DIFF_L1_BOUND THEN ASM_SIMP_TAC[];
    REWRITE_TAC[LIFT_CMUL] THEN
    SUBST1_TAC(VECTOR_ARITH `vec 0:real^1 = &1 / sqrt(&2 * pi) % vec 0`) THEN
    MATCH_MP_TAC LIM_CMUL THEN
    FIRST_X_ASSUM(MP_TAC) THEN REWRITE_TAC[TENDSTO_REAL; o_DEF; LIFT_NUM]]);;

(* NORM_RPOW2_LIM: complex limit -> norm-rpow-2 real limit                   *)
let NORM_RPOW2_LIM = prove
 (`!(c:num->complex) L.
     ((\k. c k) --> L) sequentially
     ==> ((\k. norm(c k) rpow &2) ---> norm(L) rpow &2) sequentially`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[RPOW_POW] THEN
  MATCH_MP_TAC REALLIM_POW THEN
  REWRITE_TAC[TENDSTO_REAL; o_DEF] THEN
  MP_TAC(ISPECL [`sequentially`; `\k. (c:num->complex) k`;
    `L:complex`] LIM_NORM) THEN
  ASM_REWRITE_TAC[]);;

(* NORM_RPOW2_LIM_VEC: complex limit -> lift(norm-rpow-2) vector limit       *)
let NORM_RPOW2_LIM_VEC = prove
 (`!(c:num->complex) L.
     ((\k. c k) --> L) sequentially
     ==> ((\k. lift(norm(c k) rpow &2)) --> lift(norm(L) rpow &2))
       sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\k. lift(norm((c:num->complex) k) rpow &2)) =
     lift o (\k. norm(c k) rpow &2)`
   SUBST1_TAC THENL [REWRITE_TAC[o_DEF]; ALL_TAC] THEN
  REWRITE_TAC[GSYM TENDSTO_REAL] THEN MATCH_MP_TAC NORM_RPOW2_LIM THEN
    ASM_REWRITE_TAC[]);;

(* FATOU_L2_LIMIT_MEMBER: pointwise limit of L2 fns with uniformly bounded   *)
(* L2-norm is L2                                                             *)
let FATOU_L2_LIMIT_MEMBER = prove
 (`!(gk:num->real^1->complex) g B.
     (!k. (\z. gk k z) IN lspace (:real^1) (&2)) /\
     (!k. lnorm (:real^1) (&2) (\z. gk k z) <= B) /\
     (\z. g z) measurable_on (:real^1) /\
     (!z. ((\k. gk k z) --> g z) sequentially)
     ==> (\z. g z) IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lspace; IN_ELIM_THM] THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\k:num z:real^1. lift(norm((gk:num->real^1->complex) k z) rpow &2)`;
    `\z:real^1. lift(norm((g:real^1->complex) z) rpow &2)`;
    `(:real^1)`; `{}:real^1->bool`; `max (&0) (B rpow &2)`] FATOU) THEN
  REWRITE_TAC[NEGLIGIBLE_EMPTY; DIFF_EMPTY; IN_UNIV] THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [GEN_TAC THEN
      SUBGOAL_THEN
        `(\z. (gk:num->real^1->complex) n z) IN lspace (:real^1) (&2)`
         MP_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[lspace; IN_ELIM_THM] THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL
     [REPEAT STRIP_TAC THEN REWRITE_TAC[LIFT_DROP] THEN
      MATCH_MP_TAC RPOW_POS_LE THEN REWRITE_TAC[NORM_POS_LE]; ALL_TAC] THEN
    CONJ_TAC THENL
     [X_GEN_TAC `z:real^1` THEN REWRITE_TAC[] THEN
      MATCH_MP_TAC NORM_RPOW2_LIM_VEC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    GEN_TAC THEN
    MP_TAC(ISPECL [`(:real^1)`; `&2`;
      `\z. (gk:num->real^1->complex) n z`] INTEGRAL_LNORM_RPOW) THEN
    ANTS_TAC THENL [ASM_SIMP_TAC[] THEN
      CONV_TAC REAL_RAT_REDUCE_CONV; ALL_TAC] THEN
    REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[LIFT_DROP] THEN
    MATCH_MP_TAC REAL_LE_TRANS THEN EXISTS_TAC `B rpow &2` THEN CONJ_TAC THENL
     [MATCH_MP_TAC RPOW_LE2 THEN ASM_SIMP_TAC[LNORM_POS_LE] THEN
       CONV_TAC REAL_RAT_REDUCE_CONV;
      REAL_ARITH_TAC];
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]);;

(* An L^2 function truncated to a symmetric window is still in L^2           *)
(* (TRUNC_IN_LSPACE on the interval [-n,n]).                                 *)
let WINDOW_L2 = prove
 (`!(G:real^1->complex) n.
     G IN lspace (:real^1) (&2)
     ==> (\z. (if abs(drop z) <= &n then (G:real^1->complex) z else vec 0)) IN
       lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. if abs(drop z) <= &n then (G:real^1->complex) z else vec 0) =
    (\z. if z IN {z | abs(drop z) <= &n} then G z else vec 0)`
   SUBST1_TAC THENL [REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  MATCH_MP_TAC TRUNC_IN_LSPACE THEN ASM_REWRITE_TAC[REAL_ARITH `&0 < &2`] THEN
  SUBGOAL_THEN
    `{z:real^1 | abs(drop z) <= &n} = interval[lift(--(&n)),lift(&n)]`
    SUBST1_TAC THENL
   [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_INTERVAL_1; LIFT_DROP] THEN
     GEN_TAC THEN REAL_ARITH_TAC;
    REWRITE_TAC[LEBESGUE_MEASURABLE_INTERVAL]]);;

(* Uniform L^2-norm bound for an L^2-convergent sequence: if psi_k(drop) ->  *)
(* phin(drop) in L^2 then ||psi_k(drop)||_2 is bounded (reverse triangle     *)
(* LNORM_REV + convergent sequences are bounded).                            *)
let PSI_LNORM_BOUNDED = prove
 (`!(phin:real->complex) (psi:num->real->complex).
     (\z. (phin:real->complex)(drop z)) IN lspace (:real^1) (&2) /\
     (!k. (\z. (psi:num->real->complex) k (drop z)) IN lspace (:real^1) (&2))
       /\
     ((\k. lnorm (:real^1) (&2) (\z. (phin:real->complex)(drop z) - psi k (drop
       z))) ---> &0) sequentially
     ==> ?B. !k. lnorm (:real^1) (&2) (\z. (psi:num->real->complex) k (drop z))
       <= B`,
  REPEAT STRIP_TAC THEN
  MP_TAC(MATCH_MP REAL_CONVERGENT_IMP_BOUNDED (ASSUME
   `((\k. lnorm (:real^1) (&2) (\z. (phin:real->complex)(drop z) - psi k (drop
     z))) ---> &0) sequentially`)) THEN
  REWRITE_TAC[REAL_BOUNDED_POS; FORALL_IN_IMAGE; IN_UNIV] THEN
  DISCH_THEN(X_CHOOSE_THEN `M:real` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `lnorm (:real^1) (&2) (\z. (phin:real->complex)(drop z)) + M` THEN
  X_GEN_TAC `k:num` THEN
  MP_TAC(ISPECL [`(:real^1)`; `\z. (psi:num->real->complex) k (drop z)`;
    `\z. (phin:real->complex)(drop z)`] LNORM_REV) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `lnorm (:real^1) (&2) (\z. (psi:num->real->complex) k (drop z) - phin(drop
    z)) =
                lnorm (:real^1) (&2) (\z. (phin:real->complex)(drop z) - psi k
                  (drop z))`
   SUBST1_TAC THENL
   [GEN_REWRITE_TAC LAND_CONV [GSYM LNORM_NEG] THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN VECTOR_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `k:num`) THEN REAL_ARITH_TAC);;

(* fourier of the windowed function phin = G*chi[-n,n] (L1 cap L2) is in     *)
(* L^2. FATOU on norm(fourier(psi_k)) rpow 2 (integral = ||psi_k||_2 rpow 2, *)
(* bounded) with pointwise limit norm(fourier phin) rpow 2 (uniform FT       *)
(* convergence from L^1).                                                    *)
let WINDOWED_FOURIER_L2 = prove
 (`!(G:real^1->complex) n.
     G IN lspace (:real^1) (&2)
     ==> (\z. fourier (\x. if abs x <= &n then G(lift x) else Cx(&0)) (drop z))
       IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `phin = \x. if abs x <= &n then (G:real^1->complex)(lift x) else
    Cx(&0)` THEN
  SUBGOAL_THEN
   `!z:real^1. (phin:real->complex)(drop z) = (if abs(drop z) <= &n then
     (G:real^1->complex) z else vec 0)`
   ASSUME_TAC THENL
   [X_GEN_TAC `z:real^1` THEN EXPAND_TAC "phin" THEN
    REWRITE_TAC[LIFT_DROP; COMPLEX_VEC_0]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z. (phin:real->complex)(drop z)) IN lspace (:real^1) (&2)`
     ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(\z. (phin:real->complex)(drop z)) = (\z. if abs(drop z) <= &n then
       (G:real^1->complex) z else vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC WINDOW_L2 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`G:real^1->complex`; `n:num`] FIXED_SUPP_SCHWARTZ_SEQ) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `psi:num->real->complex` STRIP_ASSUME_TAC) THEN
  (* L^2-approx of phin(drop) by psi_k(drop)                                 *)
  SUBGOAL_THEN
   `((\k. lnorm (:real^1) (&2) (\z. (phin:real->complex)(drop z) - psi k (drop
     z))) ---> &0) sequentially`
   ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(\(k:num). lnorm (:real^1) (&2) (\z. (phin:real->complex)(drop z) -
       (psi:num->real->complex) k (drop z))) =
      (\(k:num). lnorm (:real^1) (&2)
           (\z. (if abs(drop z) <= &n then (G:real^1->complex) z else vec 0) -
             psi k (drop z)))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `k:num` THEN AP_TERM_TAC THEN
      REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN
      AP_THM_TAC THEN AP_TERM_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* L1 convergence (fixed support [-(n+2),n+2])                             *)
  SUBGOAL_THEN
   `((\k. drop(integral (:real^1) (\z. lift(norm((phin:real->complex)(drop z) -
     psi k (drop z)))))) ---> &0)
    sequentially`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`\(k:num) (z:real^1). (phin:real->complex)(drop z) - psi k
     (drop z)`; `&n + &2`]
      L1_LIM_FROM_L2_CSUPP) THEN
    BETA_TAC THEN DISCH_THEN MATCH_MP_TAC THEN
    REWRITE_TAC[REAL_ARITH `&0 <= &n + &2`] THEN
    CONJ_TAC THENL
     [GEN_TAC THEN MATCH_MP_TAC LSPACE_SUB THEN
      REWRITE_TAC[REAL_POS] THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        MATCH_MP_TAC SCHWARTZ_L2 THEN ASM_SIMP_TAC[ETA_AX]]; ALL_TAC] THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`k:num`; `z:real^1`] THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
        `(if abs(drop(z:real^1)) <= &n then (G:real^1->complex) z else vec 0) =
        Cx(&0) /\
                    (psi:num->real->complex) k (drop z) = Cx(&0)`
        (fun th -> REWRITE_TAC[th; COMPLEX_SUB_REFL]) THEN
      CONJ_TAC THENL
       [COND_CASES_TAC THENL
         [SUBGOAL_THEN `F` CONTR_TAC THEN
           ASM_REAL_ARITH_TAC; REWRITE_TAC[COMPLEX_VEC_0]];
        FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN ASM_REAL_ARITH_TAC];
      FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
  (* the three FOURIER_UNIF_LIM_FROM_L1 hypotheses                           *)
  SUBGOAL_THEN
   `!k. (\z. (psi:num->real->complex) k (drop z)) absolutely_integrable_on
     (:real^1)`
   ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC SCHWARTZ_ABSINT THEN
     ASM_SIMP_TAC[ETA_AX]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(\z. (phin:real->complex)(drop z)) absolutely_integrable_on (:real^1)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC CSUPP_L2_ABSINT THEN EXISTS_TAC `&n + &2` THEN
    ASM_REWRITE_TAC[REAL_ARITH `&0 <= &n + &2`] THEN
    X_GEN_TAC `z:real^1` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    COND_CASES_TAC THENL
     [SUBGOAL_THEN `F` CONTR_TAC THEN
       ASM_REAL_ARITH_TAC; REWRITE_TAC[COMPLEX_VEC_0]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `((\k. drop(integral (:real^1) (\z. lift(norm((psi:num->real->complex) k
     (drop z) - phin(drop z)))))) ---> &0)
    sequentially`
   ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(\(k:num). drop(integral (:real^1) (\z.
       lift(norm((psi:num->real->complex) k (drop z) - phin(drop z)))))) =
      (\(k:num). drop(integral (:real^1) (\z.
        lift(norm((phin:real->complex)(drop z) - psi k (drop z))))))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `k:num` THEN AP_TERM_TAC THEN
       AP_TERM_TAC THEN
      REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:real^1` THEN AP_TERM_TAC THEN
      REWRITE_TAC[NORM_SUB]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!y. ((\k. fourier ((psi:num->real->complex) k) y) --> fourier
     (phin:real->complex) y) sequentially`
   ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC FOURIER_UNIF_LIM_FROM_L1 THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* FATOU: fourier phin in L2, as ptwise-lim of fourier(psi_k) with bounded *)
  (* L2-norm                                                                 *)
  SUBGOAL_THEN
    `!k. (\z. (psi:num->real->complex) k (drop z)) IN lspace (:real^1) (&2)`
   ASSUME_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
     ASM_SIMP_TAC[ETA_AX]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?B. !k. lnorm (:real^1) (&2) (\z. (psi:num->real->complex) k (drop z)) <=
     B`
   STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`phin:real->complex`;
     `psi:num->real->complex`] PSI_LNORM_BOUNDED) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC FATOU_L2_LIMIT_MEMBER THEN
  MAP_EVERY EXISTS_TAC
   [`\k:num z:real^1. fourier ((psi:num->real->complex) k) (drop z)`;
     `B:real`] THEN
  REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [GEN_TAC THEN MATCH_MP_TAC SCHWARTZ_FOURIER_L2 THEN ASM_SIMP_TAC[ETA_AX];
    GEN_TAC THEN
    SUBGOAL_THEN
     `lnorm (:real^1) (&2) (\z. fourier ((psi:num->real->complex) k) (drop z))
       =
      lnorm (:real^1) (&2) (\z. (psi:num->real->complex) k (drop z))`
     SUBST1_TAC THENL
     [MATCH_MP_TAC PLANCHEREL_LNORM_SCHWARTZ THEN
       ASM_SIMP_TAC[ETA_AX]; ASM_REWRITE_TAC[]];
    MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    MATCH_MP_TAC FOURIER_CONTINUOUS_ON THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* P3 assembly toward f2 in L2 (window transforms W_n = fourier(phin_n) ->   *)
(* RIESZ limit).                                                             *)

let PHIN_DROP_L2 = prove
 (`!(G:real^1->complex) n.
     G IN lspace (:real^1) (&2)
     ==> (\z. (\x. if abs x <= &n then (G:real^1->complex)(lift x) else
       Cx(&0))(drop z)) IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z. (\x. if abs x <= &n then (G:real^1->complex)(lift x) else Cx(&0))(drop
     z)) =
    (\z. if abs(drop z) <= &n then (G:real^1->complex) z else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[LIFT_DROP; COMPLEX_VEC_0]; ALL_TAC] THEN
  MATCH_MP_TAC WINDOW_L2 THEN ASM_REWRITE_TAC[]);;

let WINDOW_TRANSFORM_ISOMETRY = prove
 (`!(G:real^1->complex) m n.
     G IN lspace (:real^1) (&2)
     ==> lnorm (:real^1) (&2)
          (\z. fourier (\x. if abs x <= &m then G(lift x) else Cx(&0)) (drop z)
            -
               fourier (\x. if abs x <= &n then G(lift x) else Cx(&0)) (drop
                 z)) =
         lnorm (:real^1) (&2)
          (\z. (\x. if abs x <= &m then G(lift x) else Cx(&0))(drop z) -
               (\x. if abs x <= &n then G(lift x) else Cx(&0))(drop z))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC PLANCHEREL_L2_REP_ISOMETRY THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC PHIN_DROP_L2 THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC PHIN_DROP_L2 THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC WINDOWED_FOURIER_L2 THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC WINDOWED_FOURIER_L2 THEN ASM_REWRITE_TAC[];
    GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC WINDOWED_FOURIER_REPS THEN
      ASM_REWRITE_TAC[];
    GEN_TAC THEN DISCH_TAC THEN MATCH_MP_TAC WINDOWED_FOURIER_REPS THEN
      ASM_REWRITE_TAC[]]);;

let PHIN_DROP_LNORM_LIM = prove
 (`!(G:real^1->complex).
     G IN lspace (:real^1) (&2)
     ==> ((\n. lnorm (:real^1) (&2)
              (\z. (\x. if abs x <= &n then (G:real^1->complex)(lift x) else
                Cx(&0))(drop z) - G z)) ---> &0)
         sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!n. (\z. (\x. if abs x <= &n then (G:real^1->complex)(lift x) else
     Cx(&0))(drop z) - G z) =
        (\z. (if abs(drop z) <= &n then (G:real^1->complex) z else vec 0) - G
          z)`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[LIFT_DROP; COMPLEX_VEC_0]; ALL_TAC] THEN
  MATCH_MP_TAC CLOSED_WINDOW_LNORM_LIM THEN ASM_REWRITE_TAC[]);;

let WINDOW_TRANSFORM_CAUCHY = prove
 (`!(G:real^1->complex).
     G IN lspace (:real^1) (&2)
     ==> !e. &0 < e ==> ?N. !m n. m >= N /\ n >= N
              ==> lnorm (:real^1) (&2)
                   (\z. fourier (\x. if abs x <= &m then G(lift x) else Cx(&0))
                     (drop z) -
                        fourier (\x. if abs x <= &n then G(lift x) else Cx(&0))
                          (drop z)) < e`,
  GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP PHIN_DROP_LNORM_LIM) THEN
  REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN DISCH_TAC THEN
  X_GEN_TAC `e:real` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e / &2`) THEN ASM_REWRITE_TAC[REAL_HALF] THEN
  DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN
  EXISTS_TAC `N:num` THEN MAP_EVERY X_GEN_TAC [`m:num`; `n:num`] THEN
    STRIP_TAC THEN
  MP_TAC(ISPECL [`G:real^1->complex`; `m:num`;
    `n:num`] WINDOW_TRANSFORM_ISOMETRY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC REAL_LET_TRANS THEN
  EXISTS_TAC `lnorm (:real^1) (&2)
     (\z. (\x. if abs x <= &m then (G:real^1->complex)(lift x) else
       Cx(&0))(drop z) - G z) +
              lnorm (:real^1) (&2)
     (\z. G z - (\x. if abs x <= &n then (G:real^1->complex)(lift x) else
       Cx(&0))(drop z))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC LNORM_TRIANGLE_SUB THEN
     ASM_SIMP_TAC[PHIN_DROP_L2]; ALL_TAC] THEN
  MATCH_MP_TAC(REAL_ARITH `x < e / &2 /\ y < e / &2 ==> x + y < e`) THEN
  CONJ_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `m:num`) THEN ANTS_TAC THENL
     [ASM_ARITH_TAC; REAL_ARITH_TAC];
    SUBGOAL_THEN
     `lnorm (:real^1) (&2)
       (\z. G z - (\x. if abs x <= &n then (G:real^1->complex)(lift x) else
         Cx(&0))(drop z)) =
      lnorm (:real^1) (&2)
       (\z. (\x. if abs x <= &n then (G:real^1->complex)(lift x) else
         Cx(&0))(drop z) - G z)`
     SUBST1_TAC THENL
     [GEN_REWRITE_TAC LAND_CONV [GSYM LNORM_NEG] THEN AP_TERM_TAC THEN
      REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN VECTOR_ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o SPEC `n:num`) THEN ANTS_TAC THENL
      [ASM_ARITH_TAC; REAL_ARITH_TAC]]);;

let WINDOW_TRANSFORM_RIESZ = prove
 (`!(G:real^1->complex).
     G IN lspace (:real^1) (&2)
     ==> ?ginf. ginf IN lspace (:real^1) (&2) /\
                !e. &0 < e ==> ?N. !n. n >= N
                    ==> lnorm (:real^1) (&2)
                         (\z. fourier (\x. if abs x <= &n then G(lift x) else
                           Cx(&0)) (drop z) - ginf z) < e`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\n:num. \z:real^1. fourier (\x. if abs x <= &n then
     (G:real^1->complex)(lift x) else Cx(&0)) (drop z)`;
    `&2`; `(:real^1)`] RIESZ_FISCHER) THEN
  REWRITE_TAC[REAL_ARITH `&1 <= &2`] THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [GEN_TAC THEN REWRITE_TAC[] THEN MATCH_MP_TAC WINDOWED_FOURIER_L2 THEN
       ASM_REWRITE_TAC[];
      X_GEN_TAC `e:real` THEN DISCH_TAC THEN
      MP_TAC(ISPEC `G:real^1->complex` WINDOW_TRANSFORM_CAUCHY) THEN
        ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[]]);;

(* g_inf (the RIESZ limit of the window transforms W_n =                     *)
(* fourier(G.chi[-n,n])) is in                                               *)
(* L^2 AND represents the Fourier transform of G: int g_inf.h = int          *)
(* G.fourier h for                                                           *)
(* every Schwartz h. Both int(W_n.h) -> int(g_inf.h) (LPRODUCT_L2LIM, W_n -> *)
(* g_inf)                                                                    *)
(* and int(W_n.h) = int(phin_n.fourier h) (WINDOWED_FOURIER_REPS) ->         *)
(* int(G.fourier h)                                                          *)
(* (LPRODUCT_L2LIM, phin_n -> G); LIM_UNIQUE pins the two limits equal.      *)
let STRIP286_XSLICE = prove
 (`!(G:real^1->complex) (h:real->complex) n x0.
     schwartz h
     ==> (\y. if drop x0 IN real_interval[--(&n),&n]
              then cexp(--(ii * Cx(drop x0) * Cx(drop y))) * G x0 * h(drop y)
              else vec 0) absolutely_integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `drop(x0:real^1) IN real_interval[--(&n),&n]` THEN
  ASM_REWRITE_TAC[ABSOLUTELY_INTEGRABLE_0] THEN
  SUBGOAL_THEN
   `(\y. cexp(--(ii * Cx(drop x0) * Cx(drop y))) * (G:real^1->complex) x0 *
     h(drop y)) =
    (\y. G x0 * (cexp(--(ii * Cx(drop x0) * Cx(drop y))) *
      (h:real->complex)(drop y)))`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_COMPLEX_LMUL THEN
  MATCH_MP_TAC FOURIER_MODULATION_ABSINT THEN
  MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[]);;

let STRIP286_INTEGRAND_MEASURABLE = prove
 (`!(G:real^1->complex) (h:real->complex) n.
     G measurable_on (:real^1) /\ schwartz h
     ==> (\z:real^(1,1)finite_sum.
            if drop(fstcart z) IN real_interval[--(&n),&n]
            then cexp(--(ii * Cx(drop(fstcart z)) * Cx(drop(sndcart z)))) *
                 G(fstcart z) * h(drop(sndcart z))
            else vec 0) measurable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC MEASURABLE_ON_CASES THEN
  REWRITE_TAC[STRIP_MEASURABLE; MEASURABLE_ON_0] THEN
  MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
     REWRITE_TAC[CEXP_FSTSND_CONTINUOUS];
    ALL_TAC] THEN
  MATCH_MP_TAC MEASURABLE_ON_COMPLEX_MUL THEN CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_COMPOSE_FSTCART THEN ASM_REWRITE_TAC[];
    MP_TAC(INST_TYPE [`:1`,`:M`; `:1`,`:N`]
             (ISPEC `\z. (h:real->complex)(drop z)`
               MEASURABLE_ON_COMPOSE_SNDCART)) THEN
    REWRITE_TAC[o_DEF; ETA_AX] THEN DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC CONTINUOUS_IMP_MEASURABLE_ON THEN
    MATCH_MP_TAC SCHWARTZ_CONT THEN ASM_REWRITE_TAC[]]);;

(* The inner (y-)norm-integral of the plane integrand at a fixed frequency x *)
(* is the step function 1_[-n,n](x) * norm(G x) * INT_R norm(h): both cexp   *)
(* factors are modulus 1, so the norm is 1_win(x) norm(G x) norm(h y), and   *)
(* INT_y pulls the x-constant.                                               *)

let STRIP286_INNER_NORM = prove
 (`!(G:real^1->complex) (h:real->complex) n x.
     schwartz h
     ==> integral (:real^1) (\y. lift(norm(
           if drop(fstcart(pastecart (x:real^1) y)) IN real_interval[--(&n),&n]
           then cexp(--(ii * Cx(drop(fstcart(pastecart x y))) *
             Cx(drop(sndcart(pastecart x y))))) *
                G(fstcart(pastecart x y)) * h(drop(sndcart(pastecart x y)))
           else vec 0))) =
         (if drop x IN real_interval[--(&n),&n]
          then norm(G x) % integral (:real^1) (\y. lift(norm(h(drop y)))) else
            vec 0)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  SUBGOAL_THEN
   `!y. (norm(if drop x IN real_interval[--(&n),&n]
              then cexp(--(ii * Cx(drop x) * Cx(drop y))) * (G:real^1->complex)
                x * h(drop y) else vec 0)) =
        (if drop x IN real_interval[--(&n),&n] then norm(G x) *
          norm((h:real->complex)(drop y)) else &0)`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN COND_CASES_TAC THEN REWRITE_TAC[NORM_0] THEN
    REWRITE_TAC[COMPLEX_NORM_MUL] THEN
    SUBGOAL_THEN
      `norm(cexp(--(ii * Cx(drop x) * Cx(drop y)))) = &1` SUBST1_TAC THENL
     [SUBGOAL_THEN
       `--(ii * Cx(drop x) * Cx(drop y)) = ii * Cx(--(drop x * drop y))`
       SUBST1_TAC THENL
       [REWRITE_TAC[CX_NEG; CX_MUL] THEN
         SIMPLE_COMPLEX_ARITH_TAC; REWRITE_TAC[NORM_CEXP_II]];
      REWRITE_TAC[REAL_MUL_LID]];
    ALL_TAC] THEN
  COND_CASES_TAC THEN
  ASM_REWRITE_TAC[LIFT_NUM; INTEGRAL_0] THEN
  REWRITE_TAC[LIFT_CMUL] THEN
  MATCH_MP_TAC INTEGRAL_CMUL THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
  MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
  MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[]);;

(* Outer x-integrability of the inner-norm step function: the x-marginal of  *)
(* the                                                                       *)
(* iterated norm integral (a step fn = norm(G x) times a constant vector on  *)
(* the                                                                       *)
(* window, 0 off it) is integrable over the whole line.  This is the second  *)
(* Tonelli premise for STRIP286_INTEGRAND_ABSINT (integrability of the       *)
(* iterated                                                                  *)
(* norm integral).  norm(G x) integrable on the window = LSPACE_ABSINT_ON_   *)
(* INTERVAL + ABSOLUTELY_INTEGRABLE_NORM; the scalar-times-const map is      *)
(* linear.                                                                   *)
let STRIP286_INNER_INTEGRABLE = prove
 (`!(G:real^1->complex) n (C:real^1).
     G IN lspace (:real^1) (&2)
     ==> (\x. if drop x IN real_interval[--(&n),&n] then norm(G x) % C else vec
       0)
         integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!x:real^1. (drop x IN real_interval[--(&n),&n]) <=> x IN
     interval[lift(--(&n)), lift(&n)]`
   (fun th -> ONCE_REWRITE_TAC[th]) THENL
   [GEN_TAC THEN
     REWRITE_TAC[IN_INTERVAL_1; IN_REAL_INTERVAL; LIFT_DROP]; ALL_TAC] THEN
  REWRITE_TAC[INTEGRABLE_RESTRICT_UNIV] THEN
  SUBGOAL_THEN
   `(\x. norm((G:real^1->complex) x) % (C:real^1)) =
    (\v:real^1. drop v % C) o (\x. lift(norm((G:real^1->complex) x)))`
   SUBST1_TAC THENL [REWRITE_TAC[o_DEF; LIFT_DROP]; ALL_TAC] THEN
  MATCH_MP_TAC INTEGRABLE_LINEAR THEN CONJ_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_NORM THEN
    REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
    MATCH_MP_TAC LSPACE_ABSINT_ON_INTERVAL THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[linear; DROP_ADD; DROP_CMUL] THEN
    CONJ_TAC THEN REPEAT GEN_TAC THEN VECTOR_ARITH_TAC]);;

(* 2D ABSOLUTE integrability of the 286U(c) plane integrand: the Tonelli     *)
(* premise for the Fubini order-swap in CARLESON_286U_C. FUBINI_TONELLI      *)
(* given                                                                     *)
(* (i) 2D measurability [STRIP286_INTEGRAND_MEASURABLE, G measurable from    *)
(* L^2],                                                                     *)
(* (ii) empty bad-x-slice set [each x-slice absolutely integrable, STRIP286_ *)
(* XSLICE], (iii) integrability of the iterated norm-integral                *)
(* [STRIP286_INNER_                                                          *)
(* NORM rewrites it to the step fn, STRIP286_INNER_INTEGRABLE].              *)
let STRIP286_INTEGRAND_ABSINT = prove
 (`!(G:real^1->complex) (h:real->complex) n.
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> (\z:real^(1,1)finite_sum.
            if drop(fstcart z) IN real_interval[--(&n),&n]
            then cexp(--(ii * Cx(drop(fstcart z)) * Cx(drop(sndcart z)))) *
                 G(fstcart z) * h(drop(sndcart z))
            else vec 0) absolutely_integrable_on (:real^(1,1)finite_sum)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC
   `\z:real^(1,1)finite_sum.
       if drop(fstcart z) IN real_interval[--(&n),&n]
       then cexp(--(ii * Cx(drop(fstcart z)) * Cx(drop(sndcart z)))) *
            (G:real^1->complex)(fstcart z) * (h:real->complex)(drop(sndcart z))
       else vec 0`
   (INST_TYPE [`:1`,`:M`; `:1`,`:N`] FUBINI_TONELLI)) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC STRIP286_INTEGRAND_MEASURABLE THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `(G:real^1->complex) IN lspace (:real^1) (&2)` THEN
    REWRITE_TAC[lspace; IN_ELIM_THM] THEN SIMP_TAC[];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN CONJ_TAC THENL
   [REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
    SUBGOAL_THEN
     `{x:real^1 | ~((\y. if drop x IN real_interval[--(&n),&n]
                          then cexp(--(ii * Cx(drop x) * Cx(drop y))) *
                               (G:real^1->complex) x * (h:real->complex)(drop
                                 y)
                          else vec 0) absolutely_integrable_on (:real^1))} =
                            {}`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; NOT_IN_EMPTY] THEN
      X_GEN_TAC `x0:real^1` THEN REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`G:real^1->complex`; `h:real->complex`; `n:num`;
        `x0:real^1`]
        STRIP286_XSLICE) THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[NEGLIGIBLE_EMPTY]];
    ASM_SIMP_TAC[STRIP286_INNER_NORM] THEN
    MATCH_MP_TAC STRIP286_INNER_INTEGRABLE THEN ASM_REWRITE_TAC[]]);;

(* Per-window Fubini order swap: the 286U(c) inner double integral over the  *)
(* strip abs x <= n may be evaluated x-then-y or y-then-x.  Immediate from   *)
(* FUBINI_INTEGRAL_SWAP + the 2D absolute integrability STRIP286_INTEGRAND_  *)
(* ABSINT. Mirrors fourier_inversion's STRIP_FUBINI_SWAP but carries the     *)
(* extra                                                                     *)
(* L^2 factor G(x) (vs the L^1 f there).                                     *)
let FUBINI_STRIP_286U = prove
 (`!(G:real^1->complex) (h:real->complex) n.
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> integral (:real^1)
           (\x. integral (:real^1) (\y.
              if drop(fstcart(pastecart (x:real^1) y)) IN
                real_interval[--(&n),&n]
              then cexp(--(ii * Cx(drop(fstcart(pastecart x y))) *
                               Cx(drop(sndcart(pastecart x y))))) *
                   G(fstcart(pastecart x y)) * h(drop(sndcart(pastecart x y)))
              else vec 0)) =
         integral (:real^1)
           (\y. integral (:real^1) (\x.
              if drop(fstcart(pastecart (x:real^1) y)) IN
                real_interval[--(&n),&n]
              then cexp(--(ii * Cx(drop(fstcart(pastecart x y))) *
                               Cx(drop(sndcart(pastecart x y))))) *
                   G(fstcart(pastecart x y)) * h(drop(sndcart(pastecart x y)))
              else vec 0))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC
   `\z:real^(1,1)finite_sum.
       if drop(fstcart z) IN real_interval[--(&n),&n]
       then cexp(--(ii * Cx(drop(fstcart z)) * Cx(drop(sndcart z)))) *
            (G:real^1->complex)(fstcart z) * (h:real->complex)(drop(sndcart z))
       else vec 0` (INST_TYPE [`:1`,`:M`;
         `:1`,`:N`] FUBINI_INTEGRAL_SWAP)) THEN
  ASM_SIMP_TAC[STRIP286_INTEGRAND_ABSINT]);;

(* --- The two evaluated sides of the per-window Fubini identity (mirrors    *)
(* fourier_inversion.ml's LHS_SIDE / RHS_SIDE for 283H).                     *)
(*                                                                           *)
(* LHS (x-outer): the inner y-integral of e^{-ixy}G(x)h(y) over the whole    *)
(* line                                                                      *)
(* pulls the x-constant G(x) out and reproduces sqrt2pi*fourier h (x)        *)
(* [FOURIER_                                                                 *)
(* INNER_INTEGRAL]; the outer x-integral over the strip collapses to the     *)
(* interval                                                                  *)
(* integral of G(x) sqrt2pi hhat(x).                                         *)
let LHS286_OUTER_INTEGRAND = prove
 (`!(G:real^1->complex) (h:real->complex) n x.
     schwartz h
     ==> integral (:real^1)
           (\y. if drop(fstcart(pastecart (x:real^1) y)) IN
             real_interval[--(&n),&n]
                then cexp(--(ii * Cx(drop(fstcart(pastecart x y))) *
                                 Cx(drop(sndcart(pastecart x y))))) *
                     G(fstcart(pastecart x y)) * h(drop(sndcart(pastecart x
                       y)))
                else vec 0) =
         (if drop x IN real_interval[--(&n),&n]
          then G x * Cx(sqrt(&2 * pi)) * fourier h (drop x)
          else vec 0)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  COND_CASES_TAC THEN REWRITE_TAC[INTEGRAL_0] THEN
  SUBGOAL_THEN
   `!y. cexp(--(ii * Cx(drop x) * Cx(drop y))) * (G:real^1->complex) x *
     (h:real->complex)(drop y) =
        G x * (cexp(--(ii * Cx(drop x) * Cx(drop y))) * h(drop y))`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\y:real^1. cexp(--(ii * Cx(drop(x:real^1)) * Cx(drop y))) *
     (h:real->complex)(drop y)`;
    `(:real^1)`; `(G:real^1->complex) x`] INTEGRAL_COMPLEX_LMUL) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC FOURIER_MODULATION_ABSINT THEN
    MATCH_MP_TAC SCHWARTZ_ABSINT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o BETA_RULE) THEN
  REWRITE_TAC[INNER_INT_FOURIER] THEN
  REWRITE_TAC[COMPLEX_MUL_ASSOC]);;

let LHS286_SIDE = prove
 (`!(G:real^1->complex) (h:real->complex) n.
     schwartz h
     ==> integral (:real^1)
           (\x. integral (:real^1) (\y.
              if drop(fstcart(pastecart (x:real^1) y)) IN
                real_interval[--(&n),&n]
              then cexp(--(ii * Cx(drop(fstcart(pastecart x y))) *
                               Cx(drop(sndcart(pastecart x y))))) *
                   G(fstcart(pastecart x y)) * h(drop(sndcart(pastecart x y)))
              else vec 0)) =
         integral (interval[lift(--(&n)), lift(&n)])
           (\x. G x * Cx(sqrt(&2 * pi)) * fourier h (drop x))`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[LHS286_OUTER_INTEGRAND] THEN
  SUBGOAL_THEN
   `(\x. if drop x IN real_interval[--(&n),&n]
         then (G:real^1->complex) x * Cx(sqrt(&2 * pi)) * fourier h (drop x)
         else vec 0) =
    (\x:real^1. if x IN interval[lift(--(&n)),lift(&n)]
         then G x * Cx(sqrt(&2 * pi)) * fourier h (drop x)
         else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[IN_INTERVAL_1; IN_REAL_INTERVAL; LIFT_DROP]; ALL_TAC] THEN
  REWRITE_TAC[INTEGRAL_RESTRICT_UNIV]);;

(* RHS (y-outer): the inner x-integral pulls out the y-constant h(y) and     *)
(* leaves                                                                    *)
(* the window transform INT_{[-n,n]} e^{-ixy}G(x)dx (G is L^1 on the compact *)
(* window, LSPACE_ABSINT_ON_INTERVAL); the outer y-integral is over the      *)
(* whole                                                                     *)
(* line. The cexp arg is commuted so MODULATION_ABSINT_LMEAS's fixed         *)
(* frequency                                                                 *)
(* (here drop y) is in front.                                                *)
let RHS286_OUTER_INTEGRAND = prove
 (`!(G:real^1->complex) (h:real->complex) n y.
     G IN lspace (:real^1) (&2)
     ==> integral (:real^1)
           (\x. if drop(fstcart(pastecart (x:real^1) y)) IN
             real_interval[--(&n),&n]
                then cexp(--(ii * Cx(drop(fstcart(pastecart x y))) *
                                 Cx(drop(sndcart(pastecart x y))))) *
                     G(fstcart(pastecart x y)) * h(drop(sndcart(pastecart x
                       y)))
                else vec 0) =
         h(drop y) * integral (interval[lift(--(&n)), lift(&n)])
                       (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[FSTCART_PASTECART; SNDCART_PASTECART] THEN
  SUBGOAL_THEN
   `!x:real^1. (if drop x IN real_interval[--(&n),&n]
                then cexp(--(ii * Cx(drop x) * Cx(drop y))) *
                  (G:real^1->complex) x * (h:real->complex)(drop y)
                else vec 0) =
               (h:real->complex)(drop y) * (if drop x IN
                 real_interval[--(&n),&n]
                            then cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x
                            else vec 0)`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[COMPLEX_MUL_RZERO; COMPLEX_VEC_0] THEN
    SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`\x:real^1. if drop x IN real_interval[--(&n),&n]
                then cexp(--(ii * Cx(drop x) * Cx(drop(y:real^1)))) *
                  (G:real^1->complex) x
                else vec 0`;
    `(:real^1)`; `(h:real->complex)(drop y)`] INTEGRAL_COMPLEX_LMUL) THEN
  ANTS_TAC THENL
   [SUBGOAL_THEN
     `!x:real^1. (drop x IN real_interval[--(&n),&n]) <=> x IN
       interval[lift(--(&n)), lift(&n)]`
     (fun th -> ONCE_REWRITE_TAC[th]) THENL
     [GEN_TAC THEN
       REWRITE_TAC[IN_INTERVAL_1; IN_REAL_INTERVAL; LIFT_DROP]; ALL_TAC] THEN
    REWRITE_TAC[INTEGRABLE_RESTRICT_UNIV] THEN
    SUBGOAL_THEN
     `(\x:real^1. cexp(--(ii * Cx(drop x) * Cx(drop y))) * (G:real^1->complex)
       x) =
      (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) * G x)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      SUBGOAL_THEN
        `ii * Cx(drop x) * Cx(drop y) =
         ii * Cx(drop y) * Cx(drop x)` SUBST1_TAC THENL
       [SIMPLE_COMPLEX_ARITH_TAC; REFL_TAC]; ALL_TAC] THEN
    MATCH_MP_TAC ABSOLUTELY_INTEGRABLE_IMP_INTEGRABLE THEN
    MATCH_MP_TAC MODULATION_ABSINT_LMEAS THEN
    REWRITE_TAC[LEBESGUE_MEASURABLE_INTERVAL] THEN
    REWRITE_TAC[GSYM IMAGE_LIFT_REAL_INTERVAL] THEN
    MATCH_MP_TAC LSPACE_ABSINT_ON_INTERVAL THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o BETA_RULE) THEN AP_TERM_TAC THEN
  SUBGOAL_THEN
   `(\x. if drop x IN real_interval[--(&n),&n]
         then cexp(--(ii * Cx(drop x) * Cx(drop y))) * (G:real^1->complex) x
         else vec 0) =
    (\x:real^1. if x IN interval[lift(--(&n)),lift(&n)]
         then cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x
         else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
    REWRITE_TAC[IN_INTERVAL_1; IN_REAL_INTERVAL; LIFT_DROP]; ALL_TAC] THEN
  REWRITE_TAC[INTEGRAL_RESTRICT_UNIV]);;

let RHS286_SIDE = prove
 (`!(G:real^1->complex) (h:real->complex) n.
     G IN lspace (:real^1) (&2)
     ==> integral (:real^1)
           (\y. integral (:real^1) (\x.
              if drop(fstcart(pastecart (x:real^1) y)) IN
                real_interval[--(&n),&n]
              then cexp(--(ii * Cx(drop(fstcart(pastecart x y))) *
                               Cx(drop(sndcart(pastecart x y))))) *
                   G(fstcart(pastecart x y)) * h(drop(sndcart(pastecart x y)))
              else vec 0)) =
         integral (:real^1)
           (\y. h(drop y) * integral (interval[lift(--(&n)), lift(&n)])
                              (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G
                                x))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC INTEGRAL_EQ THEN
  X_GEN_TAC `y:real^1` THEN DISCH_TAC THEN BETA_TAC THEN
  MATCH_MP_TAC RHS286_OUTER_INTEGRAND THEN ASM_REWRITE_TAC[]);;

(* Per-window Fubini identity (Fremlin 286U(c), the n-th equality before the *)
(* n->inf limit): INT_{[-n,n]} G(x) sqrt2pi hhat(x) = INT_R h(y) (window     *)
(* transform_n)(y). Chains LHS286_SIDE and RHS286_SIDE through               *)
(* FUBINI_STRIP_286U.                                                        *)
let CARLESON_286U_STRIP_RAW = prove
 (`!(G:real^1->complex) (h:real->complex) n.
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> integral (interval[lift(--(&n)), lift(&n)])
           (\x. G x * Cx(sqrt(&2 * pi)) * fourier h (drop x)) =
         integral (:real^1)
           (\y. h(drop y) * integral (interval[lift(--(&n)), lift(&n)])
                              (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G
                                x))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`G:real^1->complex`; `h:real->complex`;
    `n:num`] LHS286_SIDE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MP_TAC(SPECL [`G:real^1->complex`; `h:real->complex`;
    `n:num`] RHS286_SIDE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC FUBINI_STRIP_286U THEN ASM_REWRITE_TAC[]);;

(* --- The clean (non-DCT) half of 286U(c): the outer n->inf limit.          *)
(*                                                                           *)
(* G(x) sqrt2pi hhat(x) is integrable on R (GFOURIERH_INTEGRABLE scaled), so *)
(* its                                                                       *)
(* symmetric-interval integrals converge to the whole-line integral          *)
(* [SYMMETRIC_                                                               *)
(* INTERVAL_LIMIT + LIM_POSINFINITY_SEQUENTIALLY]. Combined with the         *)
(* per-window                                                                *)
(* Fubini identity CARLESON_286U_STRIP_RAW (termwise equal to INT_R h W_n),  *)
(* this                                                                      *)
(* pins lim_n INT_R h(y) W_n(y) dy = INT_R G sqrt2pi hhat.                   *)
let GHHAT_SCALED_INTEGRABLE = prove
 (`!(G:real^1->complex) h:real->complex.
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> (\x. G x * Cx(sqrt(&2 * pi)) * fourier h (drop x)) integrable_on
       (:real^1)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\x. (G:real^1->complex) x * Cx(sqrt(&2 * pi)) * fourier h (drop x)) =
    (\x. Cx(sqrt(&2 * pi)) * (G x * fourier h (drop x)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC INTEGRABLE_COMPLEX_LMUL THEN
  MATCH_MP_TAC GFOURIERH_INTEGRABLE THEN ASM_REWRITE_TAC[]);;

let GHHAT_INTERVAL_LIMIT = prove
 (`!(G:real^1->complex) (h:real->complex).
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> ((\n. integral (interval[lift(--(&n)), lift(&n)])
                 (\x. G x * Cx(sqrt(&2 * pi)) * fourier h (drop x)))
          --> integral (:real^1) (\x. G x * Cx(sqrt(&2 * pi)) * fourier h (drop
            x)))
         sequentially`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC LIM_POSINFINITY_SEQUENTIALLY THEN
  MATCH_MP_TAC SYMMETRIC_INTERVAL_LIMIT THEN
  MATCH_MP_TAC GHHAT_SCALED_INTEGRABLE THEN ASM_REWRITE_TAC[]);;

(* The y-marginal INT_x F_n(x,y) = h(y) W_n(y) is integrable in y: FUBINI_   *)
(* ABSOLUTELY_INTEGRABLE_ALT on the (absolutely integrable) plane integrand  *)
(* yields integrability of the x-marginal, which RHS286_OUTER_INTEGRAND      *)
(* rewrites as h(y) W_n(y).                                                  *)
let RHS286_MARGINAL_INTEGRABLE = prove
 (`!(G:real^1->complex) (h:real->complex) n.
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> (\y. h(drop y) * integral (interval[lift(--(&n)), lift(&n)])
                           (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x))
         integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`G:real^1->complex`; `h:real->complex`;
    `n:num`] STRIP286_INTEGRAND_ABSINT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o MATCH_MP (INST_TYPE [`:1`,`:M`;
    `:1`,`:N`] FUBINI_ABSOLUTELY_INTEGRABLE_ALT)) THEN
  REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC INTEGRABLE_EQ THEN
  EXISTS_TAC
   `\y:real^1. integral (:real^1) (\x.
       if drop(fstcart(pastecart (x:real^1) y)) IN real_interval[--(&n),&n]
       then cexp(--(ii * Cx(drop(fstcart(pastecart x y))) *
                        Cx(drop(sndcart(pastecart x y))))) *
            (G:real^1->complex)(fstcart(pastecart x y)) *
              (h:real->complex)(drop(sndcart(pastecart x y)))
       else vec 0)` THEN
  CONJ_TAC THENL
   [X_GEN_TAC `y:real^1` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`G:real^1->complex`; `h:real->complex`; `n:num`; `y:real^1`]
      RHS286_OUTER_INTEGRAND) THEN ASM_REWRITE_TAC[];
    FIRST_ASSUM(MP_TAC o MATCH_MP HAS_INTEGRAL_INTEGRABLE) THEN
    REWRITE_TAC[ETA_AX]]);;

(* The bridge to the outer limit: lim_n INT_R h(y) W_n(y) dy = INT_R G       *)
(* sqrt2pi                                                                   *)
(* hhat. (CARLESON_286U_STRIP_RAW makes each term equal to the interval      *)
(* integral                                                                  *)
(* of G sqrt2pi hhat; GHHAT_INTERVAL_LIMIT sends the sequence to its         *)
(* whole-line                                                                *)
(* limit.)                                                                   *)
let HWN_LIMIT = prove
 (`!(G:real^1->complex) (h:real->complex).
     G IN lspace (:real^1) (&2) /\ schwartz h
     ==> ((\n. integral (:real^1)
                 (\y. h(drop y) * integral (interval[lift(--(&n)), lift(&n)])
                                    (\x. cexp(--(ii * Cx(drop x) * Cx(drop y)))
                                      * G x)))
          --> integral (:real^1) (\x. G x * Cx(sqrt(&2 * pi)) * fourier h (drop
            x)))
         sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\n. integral (:real^1)
           (\y. h(drop y) * integral (interval[lift(--(&n)), lift(&n)])
                              (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) *
                                (G:real^1->complex) x))) =
    (\n. integral (interval[lift(--(&n)), lift(&n)])
           (\x. G x * Cx(sqrt(&2 * pi)) * fourier h (drop x)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC CARLESON_286U_STRIP_RAW THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC GHHAT_INTERVAL_LIMIT THEN ASM_REWRITE_TAC[]);;

(* --- 286U(c) DCT + Fubini heart (ABSTRACT form, Fremlin 286U(c) lines      *)
(* 3040-                                                                     *)
(* 3049): given the a.e. window-limit f2 (i.e. W_n(y) -> sqrt2pi f2(y) off a *)
(* null                                                                      *)
(* t) and an L^1 dominator D >= norm(h W_n) off t, the representative f2     *)
(* satisfies                                                                 *)
(* INT_R f2 h = INT_R G hhat (equivalently after the sqrt2pi factor).        *)
(* Lebesgue                                                                  *)
(* DCT [DOMINATED_CONVERGENCE_AE, per-window integrability =                 *)
(* RHS286_MARGINAL_                                                          *)
(* INTEGRABLE] sends lim_n INT_R h W_n to INT_R h sqrt2pi f2; HWN_LIMIT      *)
(* sends the                                                                 *)
(* same sequence to INT_R G sqrt2pi hhat; LIM_UNIQUE identifies them.        *)
(*                                                                           *)
(* Kept abstract in (f2, t, D) so the concrete window-limit materialization  *)
(* and                                                                       *)
(* the Ahat-dominator (AHAT_SCHWARTZ_DOM, norm W_n <= sqrt2pi Ahat G) are    *)
(* wired                                                                     *)
(* in separately.                                                            *)
let CARLESON_286U_C_ABSTRACT = prove
 (`!(G:real^1->complex) (h:real->complex) (f2:real^1->complex) (t:real^1->bool)
   (D:real^1->real^1).
     G IN lspace (:real^1) (&2) /\ schwartz h /\ negligible t /\
     D integrable_on (:real^1) /\
     (!n y. ~(y IN t) ==>
        norm(h(drop y) * integral (interval[lift(--(&n)), lift(&n)])
                           (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x))
        <= drop(D y)) /\
     (!y. ~(y IN t) ==>
        ((\n. h(drop y) * integral (interval[lift(--(&n)), lift(&n)])
                            (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x))
         --> h(drop y) * Cx(sqrt(&2 * pi)) * f2 y) sequentially)
     ==> integral (:real^1) (\y. h(drop y) * Cx(sqrt(&2 * pi)) * f2 y) =
         integral (:real^1) (\x. G x * Cx(sqrt(&2 * pi)) * fourier h (drop
           x))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`\n y:real^1. (h:real->complex)(drop y) * integral (interval[lift(--(&n)),
     lift(&n)])
                    (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) *
                      (G:real^1->complex) x)`;
    `\y:real^1. (h:real->complex)(drop y) * Cx(sqrt(&2 * pi)) *
      (f2:real^1->complex) y`;
    `D:real^1->real^1`; `(:real^1)`;
      `t:real^1->bool`] DOMINATED_CONVERGENCE_AE) THEN
  ASM_REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
  ANTS_TAC THENL
   [X_GEN_TAC `k:num` THEN MATCH_MP_TAC RHS286_MARGINAL_INTEGRABLE THEN
     ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(SPECL [`G:real^1->complex`; `h:real->complex`] HWN_LIMIT) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL
   [`sequentially`;
    `\n. integral (:real^1)
          (\y. (h:real->complex)(drop y) * integral (interval[lift(--(&n)),
            lift(&n)])
                 (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) *
                   (G:real^1->complex) x))`;
    `integral (:real^1) (\y. (h:real->complex)(drop y) * Cx(sqrt(&2 * pi)) *
      (f2:real^1->complex) y)`;
    `integral (:real^1) (\x. (G:real^1->complex) x * Cx(sqrt(&2 * pi)) *
      fourier h (drop x))`]
   LIM_UNIQUE) THEN
  ASM_REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY]);;

(* Pointwise window <= maximal bound (the DCT dominator, Fremlin 286U(c)     *)
(* line                                                                      *)
(* 3043 "1/sqrt2pi |INT_{-n}^n e^{-ixy}f| <= Af(y)"): the STRIP window       *)
(* W_n(y) =                                                                  *)
(* INT_{[-n,n]} e^{-ixy}G(x)dx satisfies inv sqrt2pi norm(W_n) <=            *)
(* carleson_Ahat                                                             *)
(* (G o lift)(drop y), whenever the truncated-integral family at y is        *)
(* bounded                                                                   *)
(* (off the null bad set).  Reconciles the STRIP form (G:real^1->complex,    *)
(* cexp arg drop-x first) with the Ahat form (f:real->complex via f(drop x), *)
(* freq                                                                      *)
(* first) via IMAGE_LIFT_REAL_INTERVAL + cexp-arg commute + f := G o lift.   *)
let WINDOW_DOMINATION_BOUND = prove
 (`!(G:real^1->complex) (y:real^1) n.
     (?B. !a b. a <= b ==> inv(sqrt(&2 * pi)) *
             norm(integral (IMAGE lift (real_interval[a,b]))
                    (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) * G(lift(drop
                      x)))) <= B)
     ==> inv(sqrt(&2 * pi)) *
         norm(integral (interval[lift(--(&n)), lift(&n)])
                (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x))
         <= carleson_Ahat (\u. G(lift u)) (drop y)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `integral (interval[lift(--(&n)), lift(&n)])
       (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * (G:real^1->complex) x) =
    integral (IMAGE lift (real_interval[--(&n),&n]))
       (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) * G(lift(drop x)))`
   SUBST1_TAC THENL
   [REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN MATCH_MP_TAC INTEGRAL_EQ THEN
    X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN REWRITE_TAC[LIFT_DROP] THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`\u. (G:real^1->complex)(lift u)`; `drop(y:real^1)`;
    `--(&n):real`; `&n:real`]
    CARLESON_AHAT_WINDOW_LE) THEN
  REWRITE_TAC[] THEN ANTS_TAC THENL
   [REWRITE_TAC[REAL_ARITH `--(&n) <= &n`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

(* The concrete DCT dominator (Fremlin 286U(c) / 284F): sqrt2pi Ahat(G o     *)
(* lift)                                                                     *)
(* norm(h) is integrable on R. From AHAT_SCHWARTZ_DOM (Ahat G norm h in L^1) *)
(* at                                                                        *)
(* the real-fn G o lift, scaled by sqrt2pi and pushed through the            *)
(* real->vector                                                              *)
(* integrability bridge REAL_INTEGRABLE_ON.                                  *)
let DOMINATOR_286U_INTEGRABLE = prove
 (`!(G:real^1->complex) (h:real->complex) C10.
     &0 <= C10 /\ G IN lspace (:real^1) (&2) /\ schwartz h /\
     (!(k:real->complex) GG. schwartz k /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat k)
            <= C10 * lnorm (:real^1) (&2) (\z. k(drop z)) * sqrt(real_measure
              GG))
     ==> (\y. lift(sqrt(&2 * pi) * carleson_Ahat (\u. G(lift u)) (drop y) *
       norm(h(drop y))))
         integrable_on (:real^1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\u. (G:real^1->complex)(lift u)`; `h:real->complex`;
    `C10:real`] AHAT_SCHWARTZ_DOM) THEN
  ASM_REWRITE_TAC[LIFT_DROP; ETA_AX] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(\y. sqrt(&2 * pi) * (carleson_Ahat (\u. (G:real^1->complex)(lift u)) y *
     norm((h:real->complex) y)))
    real_integrable_on (:real)`
   MP_TAC THENL
   [MATCH_MP_TAC REAL_INTEGRABLE_LMUL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[REAL_INTEGRABLE_ON; o_DEF; LIFT_DROP; IMAGE_LIFT_UNIV] THEN
  MATCH_MP_TAC EQ_IMP THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN AP_TERM_TAC THEN REAL_ARITH_TAC);;

(* Scaled window reconciliation: sqrt2pi times the (normalized) Ahat-window  *)
(* integral (freq drop y first, plain G x) recovers the STRIP window W_n     *)
(* (freq                                                                     *)
(* drop x first).  Two cexp args commute; the two sqrt2pi factors cancel.    *)
let WINDOW_RECONCILE_GX = prove
 (`!(G:real^1->complex) (y:real^1) n.
     Cx(sqrt(&2 * pi)) *
     (Cx(inv(sqrt(&2 * pi))) *
      integral (IMAGE lift (real_interval[--(&n),&n]))
        (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) * G x)) =
     integral (interval[lift(--(&n)), lift(&n)])
        (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `Cx(sqrt(&2 * pi)) * Cx(inv(sqrt(&2 * pi))) = Cx(&1)` (fun th ->
   REWRITE_TAC[COMPLEX_MUL_ASSOC; th; COMPLEX_MUL_LID]) THENL
   [REWRITE_TAC[GSYM CX_MUL] THEN AP_TERM_TAC THEN
    MATCH_MP_TAC REAL_MUL_RINV THEN
    MATCH_MP_TAC REAL_LT_IMP_NZ THEN MATCH_MP_TAC SQRT_POS_LT THEN
    MP_TAC PI_POS THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[IMAGE_LIFT_REAL_INTERVAL] THEN MATCH_MP_TAC INTEGRAL_EQ THEN
  X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN BETA_TAC THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  SIMPLE_COMPLEX_ARITH_TAC);;

let CARLESON_286U_WINDOW_AE_STRONG = prove
 (`!(f:real->complex) C10.
     &0 <= C10 /\ (\z. f(drop z)) IN lspace (:real^1) (&2) /\
     (!(h:real->complex) GG. schwartz h /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat h)
            <= C10 * lnorm (:real^1) (&2) (\z. h(drop z)) * sqrt(real_measure
              GG))
     ==> ?s. real_negligible s /\
             !y. ~(y IN s)
                 ==> (?K. !m:num. carleson_Ahat_trunc f (&m) y <= K) /\
                     ?z. ((\a. Cx(inv(sqrt(&2 * pi))) *
                          integral (IMAGE lift (real_interval[--a,a]))
                            (\x. cexp(--(ii * Cx y * Cx(drop x))) * f(drop x)))
                              --> z)
                     at_posinfinity`,
  REPEAT STRIP_TAC THEN
  EXISTS_TAC
   `{y | !k:num. ?m:num. &k + &1 < carleson_Ahat_trunc (f:real->complex) (&m)
     y} UNION
    {y | ~(!e. &0 < e ==> ?m:num. carleson_gamma f (&m) y <= e)}` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_UNION THEN CONJ_TAC THENL
     [MATCH_MP_TAC CARLESON_AHAT_TRUNC_BADSET_NEG THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`f:real->complex`; `C10:real`] CARLESON_H1_BOUND) THEN
        ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`f:real->complex`;
        `C10:real`] CARLESON_OSC_BADSET_FROM_UNTRUNC) THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  X_GEN_TAC `y:real` THEN REWRITE_TAC[IN_UNION; DE_MORGAN_THM] THEN
    STRIP_TAC THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CARLESON_OFF_BADSET_BOUNDED THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPEC
   `\a b. Cx(inv(sqrt(&2 * pi))) *
          integral (IMAGE lift (real_interval[a,b]))
            (\x. cexp(--(ii * Cx y * Cx(drop x))) * (f:real->complex)(drop x))`
   CARLESON_286U_SYMLIM) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(BETA_RULE(ISPECL [`f:real->complex`;
    `y:real`] CARLESON_GAMMA_INF_CAUCHY)) THEN
  DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`f:real->complex`;
     `y:real`] CARLESON_TRUNC_FAMILY_WINDOW_BOUND) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    MATCH_MP_TAC CARLESON_OFF_BADSET_BOUNDED THEN ASM_REWRITE_TAC[];
    UNDISCH_TAC `~(y IN {y | ~(!e. &0 < e ==> ?m:num. carleson_gamma
      (f:real->complex) (&m) y <= e)})` THEN
    REWRITE_TAC[IN_ELIM_THM]]);;

(* ========================================================================= *)
(* Chebyshev machinery for L^2 -> convergence in measure (Fremlin 273).      *)
(* Used to reconcile the pointwise a.e. window-limit f2 with the L^2 RIESZ   *)
(* limit g_inf of the SAME window-transform sequence, giving f2 = g_inf a.e. *)
(* hence f2 IN L^2 (via LSPACE_AE_CONG).                                     *)
(* ========================================================================= *)

(* The superlevel set {norm(d)>=e} is measurable for d in L^2 (its indicator *)
(* is dominated by the integrable norm(d)^2/e^2).                            *)
let L2_SUPERLEVEL_MEASURABLE = prove
 (`!(d:real^1->complex) e. d IN lspace (:real^1) (&2) /\ &0 < e
     ==> measurable {x:real^1 | norm(d x) >= e}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `lebesgue_measurable {x:real^1 | norm((d:real^1->complex) x) >= e}`
    ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(\x:real^1. lift(norm((d:real^1->complex) x))) measurable_on (:real^1)`
     MP_TAC THENL
     [MATCH_MP_TAC MEASURABLE_ON_NORM THEN
      RULE_ASSUM_TAC(REWRITE_RULE[lspace; IN_ELIM_THM]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[MEASURABLE_ON_PREIMAGE_HALFSPACE_COMPONENT_GE] THEN
    DISCH_THEN(MP_TAC o SPECL [`e:real`; `1`]) THEN
    REWRITE_TAC[DIMINDEX_1; ARITH; GSYM drop; LIFT_DROP]; ALL_TAC] THEN
  REWRITE_TAC[MEASURABLE_INTEGRABLE] THEN
  MATCH_MP_TAC MEASURABLE_BOUNDED_BY_INTEGRABLE_IMP_INTEGRABLE THEN
  EXISTS_TAC `\x:real^1. lift(norm((d:real^1->complex) x) pow 2 / e pow 2)`
    THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC MEASURABLE_ON_CASES THEN
    ASM_REWRITE_TAC[MEASURABLE_ON_CONST; IN_ELIM_THM];
    SUBGOAL_THEN
      `(\x:real^1. lift(norm((d:real^1->complex) x) pow 2 / e pow 2)) =
                  (\x. inv(e pow 2) % lift(norm(d x) pow 2))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REWRITE_TAC[GSYM DROP_EQ; DROP_CMUL; LIFT_DROP] THEN
        REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC INTEGRABLE_CMUL THEN
    RULE_ASSUM_TAC(REWRITE_RULE[lspace; IN_ELIM_THM]) THEN
      ASM_REWRITE_TAC[GSYM RPOW_POW];
    X_GEN_TAC `x:real^1` THEN DISCH_TAC THEN BETA_TAC THEN
    REWRITE_TAC[LIFT_DROP] THEN COND_CASES_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[IN_ELIM_THM]) THEN
    REWRITE_TAC[NORM_1; DROP_VEC; REAL_ABS_NUM; NORM_0] THENL
     [SUBGOAL_THEN `&0 < e pow 2` ASSUME_TAC THENL
       [MATCH_MP_TAC REAL_POW_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_SIMP_TAC[REAL_LE_RDIV_EQ; REAL_MUL_LID] THEN
      MATCH_MP_TAC REAL_POW_LE2 THEN
      UNDISCH_TAC `norm((d:real^1->complex) x) >= e` THEN
      UNDISCH_TAC `&0 < e` THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_DIV THEN REWRITE_TAC[REAL_LE_POW_2]]]);;

(* Chebyshev multiplicative form: e^2 * measure{norm d>=e} <= int_univ       *)
(* norm(d)^2                                                                 *)
let CHEBYSHEV_L2_MEASURE = prove
 (`!(d:real^1->complex) e.
     d IN lspace (:real^1) (&2) /\ &0 < e
     ==> measure {x:real^1 | norm(d x) >= e} * e pow 2 <=
         drop(integral (:real^1) (\x. lift(norm(d x) pow 2)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`d:real^1->complex`; `e:real`] L2_SUPERLEVEL_MEASURABLE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `(\x:real^1. lift(norm((d:real^1->complex) x) pow 2)) integrable_on
    (:real^1)` ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP LSPACE_IMP_INTEGRABLE) THEN
     REWRITE_TAC[RPOW_POW]; ALL_TAC] THEN
  SUBGOAL_THEN
   `measure {x:real^1 | norm((d:real^1->complex) x) >= e} * e pow 2 =
    drop(integral (:real^1) (\x. if x IN {x | norm(d x) >= e} then lift(e pow
      2) else vec 0))`
   SUBST1_TAC THENL
   [REWRITE_TAC[INTEGRAL_RESTRICT_UNIV] THEN
    SUBGOAL_THEN
      `(\x:real^1. lift(e pow 2)) =
       (\x:real^1. (e pow 2) % vec 1)` SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; GSYM DROP_EQ; DROP_CMUL; DROP_VEC;
       LIFT_DROP] THEN REAL_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[INTEGRAL_CMUL; INTEGRABLE_ON_CONST; INTEGRAL_MEASURE;
      DROP_CMUL; LIFT_DROP] THEN
    MATCH_ACCEPT_TAC REAL_MUL_SYM; ALL_TAC] THEN
  MATCH_MP_TAC INTEGRAL_DROP_LE THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[INTEGRABLE_RESTRICT_UNIV] THEN
    REWRITE_TAC[INTEGRABLE_ON_CONST] THEN DISJ2_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `x:real^1` THEN REWRITE_TAC[IN_UNIV] THEN BETA_TAC THEN
    COND_CASES_TAC THEN
  REWRITE_TAC[LIFT_DROP; DROP_VEC] THENL
   [POP_ASSUM MP_TAC THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
    MATCH_MP_TAC REAL_POW_LE2 THEN
    UNDISCH_TAC `norm((d:real^1->complex) x) >= e` THEN
    UNDISCH_TAC `&0 < e` THEN REAL_ARITH_TAC;
    REWRITE_TAC[REAL_LE_POW_2]]);;

(* per-n Chebyshev: measure{norm(dn n - g)>=e} <= L_n^2 / e^2                *)
let MEASURE_L2_DIFF_BOUND = prove
 (`!(dn:num->real^1->complex) (g:real^1->complex) e n.
     (!m. dn m IN lspace (:real^1) (&2)) /\ g IN lspace (:real^1) (&2) /\ &0 <
       e
     ==> measure {x:real^1 | norm(dn n x - g x) >= e} <=
         (lnorm (:real^1) (&2) (\x. dn n x - g x)) pow 2 / e pow 2`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\x:real^1. (dn:num->real^1->complex) n x - g x) IN lspace (:real^1) (&2)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC LSPACE_SUB THEN
     REWRITE_TAC[REAL_ARITH `&0 <= &2`; ETA_AX] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\x:real^1. (dn:num->real^1->complex) n x - g x`;
    `e:real`] CHEBYSHEV_L2_MEASURE) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`(:real^1)`; `&2`;
    `\x:real^1. (dn:num->real^1->complex) n x - g x`] INTEGRAL_LNORM_RPOW) THEN
  ASM_REWRITE_TAC[REAL_ARITH `~(&2 = &0)`; RPOW_POW; LIFT_DROP] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[LIFT_DROP] THEN
  ASM_SIMP_TAC[REAL_LE_RDIV_EQ; REAL_POW_LT] THEN REAL_ARITH_TAC);;

(* L^2 convergence implies convergence in measure (the                       *)
(* CONVERGENCE_IN_MEASURE hyp)                                               *)
let L2_LIM_IMP_IN_MEASURE = prove
 (`!(dn:num->real^1->complex) (g:real^1->complex).
     (!n. dn n IN lspace (:real^1) (&2)) /\ g IN lspace (:real^1) (&2) /\
     ((\n. lnorm (:real^1) (&2) (\x. dn n x - g x)) ---> &0) sequentially
     ==> !e. &0 < e
             ==> eventually
                 (\n. ?t. {x:real^1 | x IN (:real^1) /\ dist(dn n x, g x) >= e}
                   SUBSET t /\
                          measurable t /\ measure t < e)
                 sequentially`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `((\n. (lnorm (:real^1) (&2) (\x. (dn:num->real^1->complex) n x - g x)) pow
     2 / e pow 2) ---> &0) sequentially`
   ASSUME_TAC THENL
   [SUBGOAL_THEN
     `(\n. (lnorm (:real^1) (&2) (\x. (dn:num->real^1->complex) n x - g x)) pow
       2 / e pow 2) =
      (\n. inv(e pow 2) * (lnorm (:real^1) (&2) (\x. dn n x - g x)) pow 2)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REWRITE_TAC[real_div] THEN
       REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `&0 = inv(e pow 2) * &0` SUBST1_TAC THENL
      [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REALLIM_LMUL THEN MATCH_MP_TAC REALLIM_NULL_POW THEN
      ASM_REWRITE_TAC[ARITH]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[REALLIM_SEQUENTIALLY]) THEN
  DISCH_THEN(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN
  DISCH_THEN(X_CHOOSE_THEN `N:num` (fun th -> EXISTS_TAC `N:num` THEN
    ASSUME_TAC th)) THEN
  X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  REWRITE_TAC[dist] THEN
  EXISTS_TAC `{x:real^1 | norm((dn:num->real^1->complex) n x - g x) >= e}` THEN
  REWRITE_TAC[IN_UNIV; SUBSET_REFL] THEN CONJ_TAC THENL
   [MATCH_MP_TAC L2_SUPERLEVEL_MEASURABLE THEN
     ASM_SIMP_TAC[LSPACE_SUB; REAL_ARITH `&0 <= &2`; ETA_AX];
    MATCH_MP_TAC REAL_LET_TRANS THEN
    EXISTS_TAC `(lnorm (:real^1) (&2) (\x. (dn:num->real^1->complex) n x - g
      x)) pow 2 / e pow 2` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC MEASURE_L2_DIFF_BOUND THEN ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN ASM_REWRITE_TAC[] THEN
        REAL_ARITH_TAC]]);;

(* L^2-limit g and a.e.-pointwise-limit f of the same sequence agree a.e.    *)
(* (via CONVERGENCE_IN_MEASURE: extract an a.e.-convergent subsequence -> g, *)
(* which also -> f pointwise; LIM_UNIQUE pins f = g off the negligible       *)
(* union).                                                                   *)
let L2_AE_LIMIT_UNIQUE = prove
 (`!(dn:num->real^1->complex) (g:real^1->complex) (f:real^1->complex) s0.
     (!n. dn n IN lspace (:real^1) (&2)) /\ g IN lspace (:real^1) (&2) /\
     ((\n. lnorm (:real^1) (&2) (\x. dn n x - g x)) ---> &0) sequentially /\
     negligible s0 /\
     (!x. ~(x IN s0) ==> ((\n. dn n x) --> f x) sequentially)
     ==> negligible {x:real^1 | ~(f x = g x)}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`dn:num->real^1->complex`; `g:real^1->complex`;
    `(:real^1)`] CONVERGENCE_IN_MEASURE) THEN
  ASM_SIMP_TAC[L2_LIM_IMP_IN_MEASURE] THEN
  ANTS_TAC THENL
   [GEN_TAC THEN RULE_ASSUM_TAC(REWRITE_RULE[LSPACE_ALT; IN_ELIM_THM]) THEN
    ASM_SIMP_TAC[LSPACE_ALT; IN_ELIM_THM]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:num->num` (X_CHOOSE_THEN
    `t:real^1->bool` STRIP_ASSUME_TAC)) THEN
  MATCH_MP_TAC NEGLIGIBLE_SUBSET THEN
  EXISTS_TAC `s0 UNION (t:real^1->bool)` THEN
  ASM_SIMP_TAC[NEGLIGIBLE_UNION] THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_UNION; DE_MORGAN_THM] THEN
  X_GEN_TAC `x:real^1` THEN
  GEN_REWRITE_TAC I [GSYM CONTRAPOS_THM] THEN
  REWRITE_TAC[DE_MORGAN_THM] THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `((\n. (dn:num->real^1->complex) n x) --> f x) sequentially`
     ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`\m. (dn:num->real^1->complex) m x`; `r:num->num`;
    `(f:real^1->complex) x`] LIM_SUBSEQUENCE) THEN
  ASM_REWRITE_TAC[o_DEF] THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `((\n. (dn:num->real^1->complex) (r n) x) --> g x) sequentially` ASSUME_TAC
    THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `x:real^1`) THEN
     ASM_REWRITE_TAC[IN_UNIV; IN_DIFF]; ALL_TAC] THEN
  ASM_MESON_TAC[LIM_UNIQUE; TRIVIAL_LIMIT_SEQUENTIALLY]);;

(* ========================================================================= *)
(* 286U(c) CONCRETE (Fremlin 286U): the a.e. window-limit f2 of G REPRESENTS *)
(* the Fourier transform of G.  Materializes f2(y) via SELECT from the a.e.  *)
(* window-limit (CARLESON_286U_WINDOW_AE_STRONG), proves W_n(y) -> sqrt2pi   *)
(* f2(y) sequentially off the badset (WINDOW_RECONCILE_GX + LIM scaling),    *)
(* and                                                                       *)
(* feeds the DCT heart CARLESON_286U_C_ABSTRACT with the concrete dominator  *)
(* sqrt2pi Ahat(G) norm h (DOMINATOR_286U_INTEGRABLE) and the window <=      *)
(* maximal bound (WINDOW_DOMINATION_BOUND, using the pointwise boundedness   *)
(* supplied at the same y). Conclusion: the sqrt2pi-scaled                   *)
(* representation identity int_R f2 h = int_R G hhat.                        *)
(* ========================================================================= *)
let WINDOW_TRUNC_INTEGRAL_AS_WN = prove
 (`!(G:real^1->complex) n y.
     integral (interval[lift(--(&n)), lift(&n)])
       (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x) =
     Cx(sqrt(&2 * pi)) *
     fourier (\x. if abs x <= &n then (G:real^1->complex)(lift x) else Cx(&0))
       (drop y)`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN
   `(\x:real^1. cexp(--(ii * Cx(drop x) * Cx(drop y))) * (G:real^1->complex) x)
     =
    (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) * G x)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
    AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    SIMPLE_COMPLEX_ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`\u. (G:real^1->complex)(lift u)`; `--(&n):real`; `&n:real`;
    `y:real^1`]
    CARLESON_TRUNC_AS_FOURIER) THEN
  REWRITE_TAC[LIFT_DROP; IMAGE_LIFT_REAL_INTERVAL] THEN
  DISCH_THEN(fun th -> GEN_REWRITE_TAC LAND_CONV [th]) THEN
  AP_TERM_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `u:real` THEN
  REWRITE_TAC[IN_REAL_INTERVAL] THEN
  COND_CASES_TAC THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_REAL_ARITH_TAC);;

(* f2 in L^2 (Fremlin 286U / 284Ib: the window-limit representative lies in  *)
(* L^2).                                                                     *)
let WINDOW_LIMIT_L2 = prove
 (`!(G:real^1->complex) (f2:real^1->complex) s.
     G IN lspace (:real^1) (&2) /\ real_negligible s /\
     (!y. ~(drop y IN s) ==>
        ((\n. integral (interval[lift(--(&n)), lift(&n)])
                (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x))
         --> Cx(sqrt(&2 * pi)) * f2 y) sequentially)
     ==> f2 IN lspace (:real^1) (&2)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC `G:real^1->complex` WINDOW_TRANSFORM_RIESZ) THEN
    ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ginf:real^1->complex` STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC LSPACE_AE_CONG THEN
  EXISTS_TAC `ginf:real^1->complex` THEN ASM_REWRITE_TAC[] THEN
  ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN
  MATCH_MP_TAC L2_AE_LIMIT_UNIQUE THEN
  MAP_EVERY EXISTS_TAC
   [`\n:num. \z:real^1. fourier (\x. if abs x <= &n then
     (G:real^1->complex)(lift x) else Cx(&0)) (drop z)`;
    `{y:real^1 | drop y IN s}`] THEN
  REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [GEN_TAC THEN BETA_TAC THEN MATCH_MP_TAC WINDOWED_FOURIER_L2 THEN
     ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN X_GEN_TAC `e:real` THEN
      DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `N:num` ASSUME_TAC) THEN EXISTS_TAC `N:num` THEN
    X_GEN_TAC `n:num` THEN REWRITE_TAC[GE] THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[GE]; ALL_TAC] THEN
    MATCH_MP_TAC(REAL_ARITH `&0 <= x /\ x = a ==> a < e ==> abs(x - &0) < e`)
      THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC LNORM_POS_LE THEN MATCH_MP_TAC LSPACE_SUB THEN
      ASM_REWRITE_TAC[REAL_POS] THEN MATCH_MP_TAC WINDOWED_FOURIER_L2 THEN
        ASM_REWRITE_TAC[];
      AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
        REWRITE_TAC[]];
    SUBGOAL_THEN `{y:real^1 | drop y IN s} = IMAGE lift s` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_IMAGE] THEN
      X_GEN_TAC `y:real^1` THEN EQ_TAC THENL
       [DISCH_TAC THEN EXISTS_TAC `drop(y:real^1)` THEN
         ASM_REWRITE_TAC[LIFT_DROP];
        STRIP_TAC THEN ASM_REWRITE_TAC[LIFT_DROP]]; ALL_TAC] THEN
     UNDISCH_TAC `real_negligible s` THEN REWRITE_TAC[real_negligible];
    X_GEN_TAC `y:real^1` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `y:real^1`) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[WINDOW_TRUNC_INTEGRAL_AS_WN] THEN
    SUBGOAL_THEN `&0 < sqrt(&2 * pi)` ASSUME_TAC THENL
     [MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
       REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `Cx(inv(sqrt(&2*pi)))` o MATCH_MP
      LIM_COMPLEX_LMUL) THEN
    SUBGOAL_THEN
      `Cx(inv(sqrt(&2*pi))) * Cx(sqrt(&2 * pi)) = Cx(&1)` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM CX_MUL; CX_INJ] THEN MATCH_MP_TAC REAL_MUL_LINV THEN
      ASM_REAL_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `(\n. Cx(inv(sqrt(&2*pi))) *
           (\n. Cx (sqrt (&2 * pi)) *
                fourier (\x. if abs x <= &n then (G:real^1->complex) (lift x)
                  else Cx (&0)) (drop y)) n) =
      (\n. fourier (\x. if abs x <= &n then (G:real^1->complex) (lift x) else
        Cx (&0)) (drop y))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
       REWRITE_TAC[COMPLEX_MUL_ASSOC] THEN
      ASM_REWRITE_TAC[COMPLEX_MUL_LID]; ALL_TAC] THEN
    REWRITE_TAC[COMPLEX_MUL_ASSOC] THEN ASM_REWRITE_TAC[COMPLEX_MUL_LID]]);;

(* ========================================================================= *)
(* 286V-descent bricks (Fremlin 286V first half): the pieces assembling into *)
(* CARLESON_286U_SINC.                                                       *)
(* ========================================================================= *)

(* STEP A: the Cx-lift of the zero-extension of a square-integrable f is in  *)
(* L^2. norm(Cx(f t)) = abs(f t); (abs(f t))^2 = f t^2 integrable on         *)
(* [-pi,pi].                                                                 *)
let CARLESON_F1_L2 = prove
 (`!f. f square_integrable_on real_interval[--pi,pi]
     ==> (\z:real^1. if drop z IN real_interval[--pi,pi] then Cx(f(drop z))
       else Cx(&0))
         IN lspace (:real^1) (&2)`,
  GEN_TAC THEN REWRITE_TAC[square_integrable_on] THEN STRIP_TAC THEN
  REWRITE_TAC[lspace; IN_ELIM_THM] THEN CONJ_TAC THENL
   [REWRITE_TAC[GSYM COMPLEX_VEC_0] THEN
    SUBGOAL_THEN
     `(\z:real^1. if drop z IN real_interval[--pi,pi] then Cx(f(drop z)) else
       vec 0) =
      (\z. if z IN IMAGE lift (real_interval[--pi,pi]) then (\w. Cx(f(drop w)))
        z else vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REWRITE_TAC[IN_IMAGE_LIFT_DROP; LIFT_DROP]; ALL_TAC] THEN
    REWRITE_TAC[MEASURABLE_ON_UNIV] THEN
    SUBGOAL_THEN
     `(\w:real^1. Cx(f(drop w))) = (\v:real^1. Cx(drop v)) o (\w:real^1.
       lift(f(drop w)))`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM; o_THM; LIFT_DROP]; ALL_TAC] THEN
    MATCH_MP_TAC MEASURABLE_ON_COMPOSE_CONTINUOUS_0 THEN REPEAT CONJ_TAC THENL
     [UNDISCH_TAC `(f:real->real) real_measurable_on real_interval[--pi,pi]`
       THEN
      REWRITE_TAC[real_measurable_on; o_DEF];
      MATCH_MP_TAC CONTINUOUS_ON_CX_DROP THEN REWRITE_TAC[CONTINUOUS_ON_ID];
      REWRITE_TAC[DROP_VEC; COMPLEX_VEC_0]];
    SUBGOAL_THEN
     `(\x:real^1. lift(norm(if drop x IN real_interval[--pi,pi] then Cx(f(drop
       x)) else Cx(&0)) rpow &2)) =
      (\x. if drop x IN real_interval[--pi,pi] then lift(f(drop x) pow 2) else
        vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `x:real^1` THEN
      COND_CASES_TAC THEN
      REWRITE_TAC[COMPLEX_NORM_CX; NORM_0; RPOW_POW] THENL
       [REWRITE_TAC[REAL_POW2_ABS];
        REWRITE_TAC[REAL_ABS_NUM; REAL_POW_ZERO; ARITH; LIFT_NUM]];
          ALL_TAC] THEN
    SUBGOAL_THEN
     `(\x:real^1. if drop x IN real_interval[--pi,pi] then lift(f(drop x) pow
       2) else vec 0) =
      (\x. if x IN IMAGE lift (real_interval[--pi,pi])
           then (\w:real^1. lift(f(drop w) pow 2)) x else vec 0)`
     SUBST1_TAC THENL
     [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
      REWRITE_TAC[IN_IMAGE_LIFT_DROP]; ALL_TAC] THEN
    REWRITE_TAC[INTEGRABLE_RESTRICT_UNIV] THEN
    UNDISCH_TAC `(\x. f x pow 2) real_integrable_on real_interval[--pi,pi]`
      THEN
    REWRITE_TAC[REAL_INTEGRABLE_ON; o_DEF]]);;


(* STEP B: CONCRETE quantified over ALL test functions h (f2 is              *)
(* h-independent,                                                            *)
(* being the SELECT of the a.e. window limit). Identical to CARLESON_286U_C_ *)
(* CONCRETE but with the FT-representation given for every Schwartz h.       *)
let SINC_REP_EQUALITY = prove
 (`!(f1:real^1->complex) (f2:real^1->complex) (g:real^1->complex)
   (h:real->complex).
     f1 IN lspace (:real^1) (&2) /\ f2 IN lspace (:real^1) (&2) /\
     g IN lspace (:real^1) (&2) /\ schwartz h /\
     integral (:real^1) (\y. h(drop y) * Cx(sqrt(&2 * pi)) * f2 y) =
     integral (:real^1) (\x. g x * Cx(sqrt(&2 * pi)) * fourier h (drop x)) /\
     integral (:real^1) (\z. f1 z * h(drop z)) =
     integral (:real^1) (\z. g z * fourier h (drop z))
     ==> integral (:real^1) (\z. f2 z * h(drop z)) =
         integral (:real^1) (\z. f1 z * h(drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z:real^1. cnj(h(drop z))) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [MATCH_MP_TAC LSPACE_CNJ THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
     ASM_REWRITE_TAC[ETA_AX]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z:real^1. cnj(fourier h (drop z))) IN lspace (:real^1) (&2)` ASSUME_TAC
    THENL
   [MATCH_MP_TAC LSPACE_CNJ THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
    MP_TAC(ISPEC `fourier(h:real->complex)` SCHWARTZ_CNJ) THEN
    ANTS_TAC THENL [MATCH_MP_TAC SCHWARTZ_FOURIER THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[ETA_AX] THEN DISCH_TAC THEN MATCH_MP_TAC SCHWARTZ_FOURIER THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z:real^1. (f2:real^1->complex) z * h(drop z)) integrable_on (:real^1)`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(:real^1)`; `f2:real^1->complex`;
     `\z:real^1. cnj(h(drop z))`] L2_CNJ_PRODUCT_INTEGRABLE) THEN
    ASM_REWRITE_TAC[CNJ_CNJ]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z:real^1. (g:real^1->complex) z * fourier h (drop z)) integrable_on
    (:real^1)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(:real^1)`; `g:real^1->complex`;
     `\z:real^1. cnj(fourier h (drop z))`] L2_CNJ_PRODUCT_INTEGRABLE) THEN
    ASM_REWRITE_TAC[CNJ_CNJ]; ALL_TAC] THEN
  SUBGOAL_THEN `~(Cx(sqrt(&2 * pi)) = Cx(&0))` ASSUME_TAC THENL
   [REWRITE_TAC[CX_INJ] THEN MATCH_MP_TAC REAL_LT_IMP_NZ THEN
    MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `Cx(sqrt(&2*pi)) * integral (:real^1) (\y. (f2:real^1->complex) y *
     (h:real->complex)(drop y)) =
    Cx(sqrt(&2*pi)) * integral (:real^1) (\x. (g:real^1->complex) x * fourier h
      (drop x))`
   MP_TAC THENL
   [SUBGOAL_THEN
     `Cx(sqrt(&2*pi)) * integral (:real^1) (\y. (f2:real^1->complex) y *
       (h:real->complex)(drop y)) =
      integral (:real^1) (\y. h(drop y) * Cx(sqrt(&2 * pi)) * f2 y)`
     SUBST1_TAC THENL
     [MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC `integral (:real^1) (\y. Cx(sqrt(&2*pi)) *
        ((f2:real^1->complex) y * (h:real->complex)(drop y)))` THEN
      CONJ_TAC THENL
       [CONV_TAC SYM_CONV THEN MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
         ASM_REWRITE_TAC[];
        MATCH_MP_TAC INTEGRAL_EQ THEN GEN_TAC THEN REWRITE_TAC[] THEN
          SIMPLE_COMPLEX_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `Cx(sqrt(&2*pi)) * integral (:real^1) (\x. (g:real^1->complex) x * fourier
       h (drop x)) =
      integral (:real^1) (\x. g x * Cx(sqrt(&2 * pi)) * fourier h (drop x))`
     SUBST1_TAC THENL
     [MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC `integral (:real^1) (\x. Cx(sqrt(&2*pi)) *
        ((g:real^1->complex) x * fourier h (drop x)))` THEN
      CONJ_TAC THENL
       [CONV_TAC SYM_CONV THEN MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
         ASM_REWRITE_TAC[];
        MATCH_MP_TAC INTEGRAL_EQ THEN GEN_TAC THEN REWRITE_TAC[] THEN
          SIMPLE_COMPLEX_ARITH_TAC];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[COMPLEX_EQ_MUL_LCANCEL] THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
  ASM_MESON_TAC[]);;

(* R2: sinc kernel times f is real-integrable on [-pi,pi]                    *)
(* (bounded*measurable*abs-int).                                             *)
let SINC_KERNEL_TIMES_F_INTEGRABLE = prove
 (`!(f:real->real) a x.
     &0 < a /\ f square_integrable_on real_interval[--pi,pi]
     ==> (\t. f t * sin(a * (x - t)) / (x - t)) real_integrable_on
       real_interval[--pi,pi]`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_IMP_INTEGRABLE THEN
  SUBGOAL_THEN
   `(\t. (f:real->real) t * sin(a * (x - t)) / (x - t)) =
    (\t. (\u. sin(a * (x - u)) / (x - u)) t * f t)`
   SUBST1_TAC THENL [REWRITE_TAC[FUN_EQ_THM] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC ABSOLUTELY_REAL_INTEGRABLE_BOUNDED_MEASURABLE_PRODUCT THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC INTEGRABLE_IMP_REAL_MEASURABLE THEN
    SUBGOAL_THEN
     `(\u. sin(a * (x - u)) / (x - u)) = (\u. (\t. sin(a * t) / t) (x - u))`
     SUBST1_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`\t. sin(a * t) / t`; `x - pi:real`; `x + pi:real`;
      `-- &1:real`; `x:real`]
      REAL_INTEGRABLE_AFFINITY) THEN
    REWRITE_TAC[REAL_ARITH `-- &1 * u + x = x - u`;
      REAL_ARITH `inv(-- &1) * (u - x) = x - u`] THEN
    ANTS_TAC THENL
     [REWRITE_TAC[REAL_ARITH `~(-- &1 = &0)`] THEN
      MATCH_MP_TAC SIN_STRETCH_OVER_X_INTEGRABLE THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `IMAGE (\x'. x - x') (real_interval [x - pi,x + pi]) =
       real_interval[--pi,pi]`
     SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_IMAGE; IN_REAL_INTERVAL] THEN
      X_GEN_TAC `u:real` THEN EQ_TAC THENL
       [STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
        DISCH_TAC THEN EXISTS_TAC `x - u:real` THEN ASM_REAL_ARITH_TAC];
      DISCH_THEN ACCEPT_TAC];
    REWRITE_TAC[REAL_BOUNDED_POS] THEN EXISTS_TAC `a:real` THEN
    ASM_REWRITE_TAC[FORALL_IN_IMAGE] THEN X_GEN_TAC `u:real` THEN
      DISCH_TAC THEN
    ASM_CASES_TAC `u:real = x` THENL
     [ASM_REWRITE_TAC[REAL_SUB_REFL; real_div; REAL_INV_0; REAL_MUL_RZERO;
       SIN_0] THEN
      ASM_REAL_ARITH_TAC;
      REWRITE_TAC[real_div] THEN
      MP_TAC(ISPECL [`a:real`; `x - u:real`] SINC_ABS_BOUND) THEN
      ASM_REWRITE_TAC[REAL_SUB_0] THEN ASM_SIMP_TAC[EQ_SYM_EQ]];
    MATCH_MP_TAC SQUARE_INTEGRABLE_IMP_ABSOLUTELY_INTEGRABLE THEN
    ASM_REWRITE_TAC[REAL_MEASURABLE_REAL_INTERVAL]]);;

(* R2: collapse int_R f1.Cx(sinc) = Cx(real_integral[-pi,pi] f.sinc), f1 the *)
(* Cx-ext.                                                                   *)
let SINC_F1_INTEGRAL_COLLAPSE = prove
 (`!(f:real->real) a x.
     (\t. f t * sin(a * (x - t)) / (x - t)) real_integrable_on
       real_interval[--pi,pi]
     ==> integral (:real^1)
           (\z. (if drop z IN real_interval[--pi,pi] then Cx(f(drop z)) else
             Cx(&0)) *
                Cx(sin(a * (x - drop z)) / (x - drop z))) =
         Cx(real_integral (real_interval[--pi,pi])
              (\t. f t * sin(a * (x - t)) / (x - t)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(\z:real^1. (if drop z IN real_interval[--pi,pi] then Cx(f(drop z)) else
     Cx(&0)) *
                Cx(sin(a * (x - drop z)) / (x - drop z))) =
    (\z. if z IN IMAGE lift (real_interval[--pi,pi])
         then (\w. Cx(f(drop w) * (sin(a * (x - drop w)) / (x - drop w)))) z
           else vec 0)`
   SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
     REWRITE_TAC[IN_IMAGE_LIFT_DROP] THEN
    COND_CASES_TAC THEN
    REWRITE_TAC[GSYM CX_MUL; COMPLEX_VEC_0; COMPLEX_MUL_LZERO]; ALL_TAC] THEN
  GEN_REWRITE_TAC (LAND_CONV) [INTEGRAL_RESTRICT_UNIV] THEN
  MP_TAC(ISPECL [`\t. f t * sin(a * (x - t)) / (x - t)`;
                 `real_interval[--pi,pi]`] CX_REAL_INTEGRAL_BRIDGE) THEN
  REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[REAL_MUL_ASSOC]);;


(* Clean f2-rep for all k: from the scaled ALLH/FULL rep (int k.sqrt2pi.f2 = *)
(* int g.sqrt2pi.fourier k), derive int f2.k = int g.fourier k (factor +     *)
(* cancel).                                                                  *)
let SINC_F2_CLEAN_REP = prove
 (`!(f2:real^1->complex) (g:real^1->complex) (k:real->complex).
     f2 IN lspace (:real^1) (&2) /\ g IN lspace (:real^1) (&2) /\ schwartz k /\
     integral (:real^1) (\y. k(drop y) * Cx(sqrt(&2 * pi)) * f2 y) =
     integral (:real^1) (\x. g x * Cx(sqrt(&2 * pi)) * fourier k (drop x))
     ==> integral (:real^1) (\z. f2 z * k(drop z)) =
         integral (:real^1) (\z. g z * fourier k (drop z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `(\z:real^1. cnj(k(drop z))) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [MATCH_MP_TAC LSPACE_CNJ THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
     ASM_REWRITE_TAC[ETA_AX]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z:real^1. cnj(fourier k (drop z))) IN lspace (:real^1) (&2)` ASSUME_TAC
    THENL
   [MATCH_MP_TAC LSPACE_CNJ THEN MATCH_MP_TAC SCHWARTZ_L2 THEN
    MP_TAC(ISPEC `fourier(k:real->complex)` SCHWARTZ_CNJ) THEN
    ANTS_TAC THENL [MATCH_MP_TAC SCHWARTZ_FOURIER THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[ETA_AX] THEN DISCH_TAC THEN MATCH_MP_TAC SCHWARTZ_FOURIER THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z:real^1. (f2:real^1->complex) z * k(drop z)) integrable_on (:real^1)`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(:real^1)`; `f2:real^1->complex`;
     `\z:real^1. cnj(k(drop z))`] L2_CNJ_PRODUCT_INTEGRABLE) THEN
    ASM_REWRITE_TAC[CNJ_CNJ]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(\z:real^1. (g:real^1->complex) z * fourier k (drop z)) integrable_on
    (:real^1)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(:real^1)`; `g:real^1->complex`;
     `\z:real^1. cnj(fourier k (drop z))`] L2_CNJ_PRODUCT_INTEGRABLE) THEN
    ASM_REWRITE_TAC[CNJ_CNJ]; ALL_TAC] THEN
  SUBGOAL_THEN `~(Cx(sqrt(&2 * pi)) = Cx(&0))` ASSUME_TAC THENL
   [REWRITE_TAC[CX_INJ] THEN MATCH_MP_TAC REAL_LT_IMP_NZ THEN
    MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
      REAL_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `Cx(sqrt(&2*pi)) * integral (:real^1) (\y. (f2:real^1->complex) y *
     (k:real->complex)(drop y)) =
    Cx(sqrt(&2*pi)) * integral (:real^1) (\x. (g:real^1->complex) x * fourier k
      (drop x))`
   MP_TAC THENL
   [SUBGOAL_THEN
     `Cx(sqrt(&2*pi)) * integral (:real^1) (\y. (f2:real^1->complex) y *
       (k:real->complex)(drop y)) =
      integral (:real^1) (\y. k(drop y) * Cx(sqrt(&2 * pi)) * f2 y)`
     SUBST1_TAC THENL
     [MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC `integral (:real^1) (\y. Cx(sqrt(&2*pi)) *
        ((f2:real^1->complex) y * (k:real->complex)(drop y)))` THEN
      CONJ_TAC THENL
       [CONV_TAC SYM_CONV THEN MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
         ASM_REWRITE_TAC[];
        MATCH_MP_TAC INTEGRAL_EQ THEN GEN_TAC THEN REWRITE_TAC[] THEN
          SIMPLE_COMPLEX_ARITH_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN
     `Cx(sqrt(&2*pi)) * integral (:real^1) (\x. (g:real^1->complex) x * fourier
       k (drop x)) =
      integral (:real^1) (\x. g x * Cx(sqrt(&2 * pi)) * fourier k (drop x))`
     SUBST1_TAC THENL
     [MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC `integral (:real^1) (\x. Cx(sqrt(&2*pi)) *
        ((g:real^1->complex) x * fourier k (drop x)))` THEN
      CONJ_TAC THENL
       [CONV_TAC SYM_CONV THEN MATCH_MP_TAC INTEGRAL_COMPLEX_LMUL THEN
         ASM_REWRITE_TAC[];
        MATCH_MP_TAC INTEGRAL_EQ THEN GEN_TAC THEN REWRITE_TAC[] THEN
          SIMPLE_COMPLEX_ARITH_TAC]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[COMPLEX_EQ_MUL_LCANCEL] THEN ASM_REWRITE_TAC[]);;


(* CARLESON_286U_C_FULL = ALLH + the at_posinfinity window limit for f2 (3rd *)
(* conjunct).                                                                *)
let CARLESON_286U_C_FULL = prove
 (`!(G:real^1->complex) C10.
     &0 <= C10 /\ G IN lspace (:real^1) (&2) /\
     (!(k:real->complex) GG. schwartz k /\ real_measurable GG
        ==> real_integral GG (carleson_Ahat k)
            <= C10 * lnorm (:real^1) (&2) (\z. k(drop z)) * sqrt(real_measure
              GG))
     ==> ?f2 s. real_negligible s /\
         (!y. ~(drop y IN s) ==>
            ((\a. Cx(inv(sqrt(&2 * pi))) *
                  integral (IMAGE lift (real_interval[--a,a]))
                    (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) * G x)) --> f2
                      y)
             at_posinfinity) /\
         (!h. schwartz h
              ==> integral (:real^1) (\y. h(drop y) * Cx(sqrt(&2 * pi)) * f2 y)
                =
                  integral (:real^1) (\x. G x * Cx(sqrt(&2 * pi)) * fourier h
                    (drop x)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`\u. (G:real^1->complex)(lift u)`;
    `C10:real`] CARLESON_286U_WINDOW_AE_STRONG) THEN
  ASM_REWRITE_TAC[LIFT_DROP; ETA_AX] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:real->bool` STRIP_ASSUME_TAC) THEN
  ABBREV_TAC
   `f2 = \y:real^1. (@z. ((\a. Cx(inv(sqrt(&2 * pi))) *
                          integral (IMAGE lift (real_interval[--a,a]))
                            (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) *
                              (G:real^1->complex) x)) --> z)
                     at_posinfinity)` THEN
  EXISTS_TAC `f2:real^1->complex` THEN EXISTS_TAC `s:real->bool` THEN
  ASM_REWRITE_TAC[] THEN
  (* the at_posinfinity limit conjunct: f2 y = the SELECT, extract the limit *)
  SUBGOAL_THEN
   `!y:real^1. ~(drop y IN s) ==>
        ((\a. Cx(inv(sqrt(&2 * pi))) *
              integral (IMAGE lift (real_interval[--a,a]))
                (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) *
                  (G:real^1->complex) x)) --> f2 y)
         at_posinfinity`
   ASSUME_TAC THENL
   [X_GEN_TAC `y:real^1` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `drop(y:real^1)`) THEN
      ASM_REWRITE_TAC[LIFT_DROP] THEN
    DISCH_THEN(X_CHOOSE_TAC `z:complex` o CONJUNCT2) THEN
    EXPAND_TAC "f2" THEN REWRITE_TAC[] THEN
    CONV_TAC SELECT_CONV THEN EXISTS_TAC `z:complex` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `h:real->complex` THEN DISCH_TAC THEN
  MATCH_MP_TAC CARLESON_286U_C_ABSTRACT THEN
  MAP_EVERY EXISTS_TAC
   [`{y:real^1 | drop y IN s}`;
    `\y:real^1. lift(sqrt(&2 * pi) * carleson_Ahat (\u.
      (G:real^1->complex)(lift u)) (drop y) * norm((h:real->complex)(drop
       y)))`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `{y:real^1 | drop y IN s} = IMAGE lift s` SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_IMAGE] THEN
      X_GEN_TAC `y:real^1` THEN EQ_TAC THENL
       [DISCH_TAC THEN EXISTS_TAC `drop(y:real^1)` THEN
         ASM_REWRITE_TAC[LIFT_DROP];
        STRIP_TAC THEN ASM_REWRITE_TAC[LIFT_DROP]]; ALL_TAC] THEN
    ASM_MESON_TAC[real_negligible];
    MATCH_MP_TAC DOMINATOR_286U_INTEGRABLE THEN EXISTS_TAC `C10:real` THEN
      ASM_REWRITE_TAC[];
    X_GEN_TAC `n:num` THEN X_GEN_TAC `y:real^1` THEN
    REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
    REWRITE_TAC[LIFT_DROP; COMPLEX_NORM_MUL] THEN
    SUBGOAL_THEN
     `sqrt(&2 * pi) * carleson_Ahat (\u. (G:real^1->complex)(lift u)) (drop y)
       * norm((h:real->complex)(drop y)) =
      norm(h(drop y)) * (sqrt(&2 * pi) * carleson_Ahat (\u. G(lift u)) (drop
        y))`
     SUBST1_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[NORM_POS_LE] THEN
    MP_TAC(ISPECL [`G:real^1->complex`; `y:real^1`;
      `n:num`] WINDOW_DOMINATION_BOUND) THEN
    ANTS_TAC THENL
     [MP_TAC(ISPECL [`\u. (G:real^1->complex)(lift u)`; `drop(y:real^1)`]
        CARLESON_TRUNC_FAMILY_PLAIN_WINDOW_BOUND) THEN
      REWRITE_TAC[LIFT_DROP; ETA_AX] THEN DISCH_THEN MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `drop(y:real^1)`) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      DISCH_TAC THEN
      SUBGOAL_THEN `&0 < sqrt(&2 * pi)` ASSUME_TAC THENL
       [MATCH_MP_TAC SQRT_POS_LT THEN MP_TAC PI_POS THEN
         REAL_ARITH_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
       `norm(integral (interval[lift(--(&n)), lift(&n)])
              (\x. cexp(--(ii * Cx(drop x) * Cx(drop(y:real^1)))) *
                (G:real^1->complex) x)) =
        sqrt(&2 * pi) * (inv(sqrt(&2 * pi)) *
          norm(integral (interval[lift(--(&n)), lift(&n)])
                 (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) * G x)))`
       SUBST1_TAC THENL
       [SUBGOAL_THEN `sqrt(&2 * pi) * inv(sqrt(&2 * pi)) = &1` MP_TAC THENL
         [MATCH_MP_TAC REAL_MUL_RINV THEN
           ASM_REAL_ARITH_TAC; CONV_TAC REAL_FIELD]; ALL_TAC] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN ASM_REWRITE_TAC[] THEN
        ASM_REAL_ARITH_TAC];
    X_GEN_TAC `y:real^1` THEN REWRITE_TAC[IN_ELIM_THM] THEN DISCH_TAC THEN
    MATCH_MP_TAC LIM_COMPLEX_LMUL THEN
    (* the sequential window limit for the C_ABSTRACT hyp: derive from the   *)
    (* at_posinf one                                                         *)
    FIRST_X_ASSUM(MP_TAC o SPEC `y:real^1`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `!n. integral (interval[lift(--(&n)), lift(&n)])
            (\x. cexp(--(ii * Cx(drop x) * Cx(drop(y:real^1)))) *
              (G:real^1->complex) x) =
          Cx(sqrt(&2 * pi)) *
          (\a. Cx(inv(sqrt(&2 * pi))) *
               integral (IMAGE lift (real_interval[--a,a]))
                 (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) * G x)) (&n)`
     (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN REWRITE_TAC[] THEN CONV_TAC SYM_CONV THEN
      REWRITE_TAC[WINDOW_RECONCILE_GX]; ALL_TAC] THEN
    MATCH_MP_TAC LIM_COMPLEX_LMUL THEN
    MATCH_MP_TAC LIM_POSINFINITY_SEQUENTIALLY THEN ASM_REWRITE_TAC[]]);;


(* 286U-driven continuous-sinc convergence a.e. (Fremlin 286V lines 3056-    *)
(* 3087): extend f to f_1 (0 off [-pi,pi]); let g in L^2 represent the       *)
(* (inverse) Fourier transform of f_1 (PLANCHEREL_L2/284O).  286U gives      *)
(* f_2(x)=lim_a (1/sqrt2pi)int_{-a}^a e^{-ixy}g = f_1(x) a.e. (284Ib); the   *)
(* sinc algebra rewrites int_{-a}^a e^{-ixy}g = (2/sqrt2pi)int_{-pi}^pi      *)
(* sin(a(x-t))/(x-t)f(t)dt, giving the continuous sinc limit for f.  This is *)
(* the analytic heart (286U maximal-inequality a.e.-existence + sinc calc).  *)
let CARLESON_286U_SINC = prove
 (`!f. f square_integrable_on real_interval[--pi,pi] /\
       (!x. f(x + &2 * pi) = f x)
       ==> ?s. real_negligible s /\
               !x. --pi < x /\ x < pi /\ ~(x IN s)
                   ==> ((\a. inv(pi) *
                             real_integral (real_interval[--pi,pi])
                                (\t. sin(a * (x - t)) / (x - t) * f t))
                        ---> f x) at_posinfinity`,

  GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPEC `f:real->real` CARLESON_F1_L2) THEN ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `f1 = \z:real^1. if drop z IN real_interval[--pi,pi] then
    Cx(f(drop z)) else Cx(&0)` THEN
  DISCH_TAC THEN
  FIRST_ASSUM(X_CHOOSE_THEN
    `g:real^1->complex` STRIP_ASSUME_TAC o MATCH_MP FOURIER_L2_REP_INV) THEN
  X_CHOOSE_THEN `C10:real` STRIP_ASSUME_TAC CARLESON_286T_SCHWARTZ THEN
  MP_TAC(ISPECL [`g:real^1->complex`; `C10:real`] CARLESON_286U_C_FULL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `f2:real^1->complex` (X_CHOOSE_THEN
    `sw:real->bool` STRIP_ASSUME_TAC)) THEN
  (* sequential window limit for f2 (WINDOW_LIMIT_L2's hyp form) from the    *)
  (* at_posinf one                                                           *)
  SUBGOAL_THEN
   `!y:real^1. ~(drop y IN sw) ==>
       ((\n. integral (interval[lift(--(&n)), lift(&n)])
               (\x. cexp(--(ii * Cx(drop x) * Cx(drop y))) *
                 (g:real^1->complex) x))
        --> Cx(sqrt(&2 * pi)) * f2 y) sequentially`
   ASSUME_TAC THENL
   [X_GEN_TAC `y:real^1` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `!n. integral (interval[lift(--(&n)), lift(&n)])
            (\x. cexp(--(ii * Cx(drop x) * Cx(drop(y:real^1)))) *
              (g:real^1->complex) x) =
          Cx(sqrt(&2 * pi)) *
          (\a. Cx(inv(sqrt(&2 * pi))) *
               integral (IMAGE lift (real_interval[--a,a]))
                 (\x. cexp(--(ii * Cx(drop y) * Cx(drop x))) * g x)) (&n)`
     (fun th -> REWRITE_TAC[th]) THENL
     [GEN_TAC THEN REWRITE_TAC[] THEN CONV_TAC SYM_CONV THEN
       REWRITE_TAC[WINDOW_RECONCILE_GX]; ALL_TAC] THEN
    MATCH_MP_TAC LIM_COMPLEX_LMUL THEN
    MATCH_MP_TAC LIM_POSINFINITY_SEQUENTIALLY THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `y:real^1`) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* f2 in L2                                                                *)
  SUBGOAL_THEN `(f2:real^1->complex) IN lspace (:real^1) (&2)` ASSUME_TAC THENL
   [MATCH_MP_TAC WINDOW_LIMIT_L2 THEN
    MAP_EVERY EXISTS_TAC [`g:real^1->complex`; `sw:real->bool`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* clean f2-rep for all k                                                  *)
  SUBGOAL_THEN
   `!k. schwartz k ==> integral (:real^1) (\z. (f2:real^1->complex) z * k(drop
     z)) =
                       integral (:real^1) (\z. (g:real^1->complex) z * fourier
                         k (drop z))`
   ASSUME_TAC THENL
   [X_GEN_TAC `k:real->complex` THEN DISCH_TAC THEN
     MATCH_MP_TAC SINC_F2_CLEAN_REP THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* f2 = f1 a.e.                                                            *)
  SUBGOAL_THEN
    `negligible {x:real^1 | ~((f2:real^1->complex) x = f1 x)}` ASSUME_TAC THENL
   [MATCH_MP_TAC FOURIER_L2_UNIQUE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `h:real->complex` THEN DISCH_TAC THEN
    MATCH_MP_TAC SINC_REP_EQUALITY THEN EXISTS_TAC `g:real^1->complex` THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* badset + per-x sinc limit                                               *)
  EXISTS_TAC `sw UNION {x:real | ~((f2:real^1->complex)(lift x) = f1(lift x))}`
    THEN CONJ_TAC THENL
   [MATCH_MP_TAC REAL_NEGLIGIBLE_UNION THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REWRITE_TAC[real_negligible] THEN MATCH_MP_TAC NEGLIGIBLE_SUBSET THEN
      EXISTS_TAC `{x:real^1 | ~((f2:real^1->complex) x = f1 x)}` THEN
        ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[SUBSET; IN_IMAGE; IN_ELIM_THM] THEN
      X_GEN_TAC `z:real^1` THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[LIFT_DROP]]; ALL_TAC] THEN
  X_GEN_TAC `x:real` THEN
    REWRITE_TAC[IN_UNION; DE_MORGAN_THM; IN_ELIM_THM] THEN STRIP_TAC THEN
  (* the (1/pi) int f2.sinc at_posinf limit via R2-core                      *)
  (* (SINC_WINDOW_IDENTITY + transfer)                                       *)
  SUBGOAL_THEN
   `((\a. Cx(inv pi) *
          integral (:real^1) (\z. (f2:real^1->complex) z * Cx(sin(a * (x - drop
            z)) / (x - drop z))))
     --> f2(lift x)) at_posinfinity`
   ASSUME_TAC THENL
   [MATCH_MP_TAC LIM_TRANSFORM_EVENTUALLY THEN
    EXISTS_TAC
     `\a. Cx(inv(sqrt(&2 * pi))) *
          integral (IMAGE lift (real_interval[--a,a]))
            (\z. cexp(--(ii * Cx x * Cx(drop z))) * (g:real^1->complex) z)`
              THEN
    CONJ_TAC THENL
     [REWRITE_TAC[EVENTUALLY_AT_POSINFINITY] THEN EXISTS_TAC `&0` THEN
      X_GEN_TAC `a:real` THEN DISCH_TAC THEN
      MATCH_MP_TAC SINC_WINDOW_IDENTITY THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `a >= &0` THEN REAL_ARITH_TAC;
      UNDISCH_TAC
       `!y:real^1. ~(drop y IN sw)
          ==> ((\a. Cx (inv (sqrt (&2 * pi))) *
                    integral (IMAGE lift (real_interval [--a,a]))
                    (\x. cexp (--(ii * Cx (drop y) * Cx (drop x))) *
                      (g:real^1->complex) x)) -->
               f2 y) at_posinfinity` THEN
      DISCH_THEN(MP_TAC o SPEC `lift x`) THEN REWRITE_TAC[LIFT_DROP] THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* f2(lift x) = Cx(f x) (specific point, off the badset)                   *)
  SUBGOAL_THEN `(f2:real^1->complex)(lift x) = Cx(f x)` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXPAND_TAC "f1" THEN REWRITE_TAC[LIFT_DROP] THEN
    COND_CASES_TAC THENL
     [REWRITE_TAC[];
      POP_ASSUM MP_TAC THEN REWRITE_TAC[IN_REAL_INTERVAL] THEN
        ASM_REAL_ARITH_TAC]; ALL_TAC] THEN
  (* replace f2 by f1 in the integral (INTEGRAL_SPIKE) + collapse to real,   *)
  (* eventually a>0                                                          *)
  ONCE_REWRITE_TAC[REALLIM_COMPLEX] THEN REWRITE_TAC[o_DEF] THEN
  MATCH_MP_TAC LIM_TRANSFORM_EVENTUALLY THEN
  EXISTS_TAC
   `\a. Cx(inv pi) *
        integral (:real^1) (\z. (f2:real^1->complex) z * Cx(sin(a * (x - drop
          z)) / (x - drop z)))` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_AT_POSINFINITY] THEN EXISTS_TAC `&1` THEN
    X_GEN_TAC `a:real` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
    (* int f2.sinc = int f1.sinc (SPIKE) = Cx(real_int f.sinc) (COLLAPSE);   *)
    (* then Cx(inv pi)*Cx r = Cx(inv pi * r)                                 *)
    SUBGOAL_THEN
     `integral (:real^1) (\z. (f2:real^1->complex) z * Cx(sin(a * (x - drop z))
       / (x - drop z))) =
      integral (:real^1) (\z. (f1:real^1->complex) z * Cx(sin(a * (x - drop z))
        / (x - drop z)))`
     SUBST1_TAC THENL
     [MATCH_MP_TAC INTEGRAL_SPIKE THEN
      EXISTS_TAC `{x:real^1 | ~((f2:real^1->complex) x = f1 x)}` THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:real^1` THEN
      REWRITE_TAC[IN_DIFF; IN_UNIV; IN_ELIM_THM] THEN
      DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[]; ALL_TAC] THEN
    EXPAND_TAC "f1" THEN
    MP_TAC(ISPECL [`f:real->real`; `a:real`;
      `x:real`] SINC_F1_INTEGRAL_COLLAPSE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC SINC_KERNEL_TIMES_F_INTEGRABLE THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `a >= &1` THEN REAL_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[GSYM CX_MUL] THEN
    AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
    REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN REAL_ARITH_TAC;
    FIRST_ASSUM(SUBST1_TAC o SYM o
      check(fun th -> concl th = `(f2:real^1->complex)(lift x) = Cx(f x)`))
        THEN
    FIRST_ASSUM ACCEPT_TAC]);;

(* ========================================================================= *)
(* Carleson's theorem, Fourier-series form (Fremlin 286V).                   *)
(*                                                                           *)
(* The Fourier series of a square-integrable, 2*pi-periodic function         *)
(* converges to it almost everywhere.  Stated in the exact vocabulary of     *)
(* 100/fourier.ml (fourier_coefficient / trigonometric_set / partial sums),  *)
(* with "almost everywhere" expressed via real_negligible.                   *)
(* ========================================================================= *)

let CARLESON_THEOREM = prove
 (`!f. f square_integrable_on real_interval[--pi,pi] /\
       (!x. f(x + &2 * pi) = f x)
       ==> ?s. real_negligible s /\
               !x. ~(x IN s)
                   ==> ((\n. sum(0..n) (\k. fourier_coefficient f k *
                                            trigonometric_set k x))
                        ---> f x) sequentially`,
  GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC CARLESON_286V_FROM_CONTINUOUS_SINC THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC CARLESON_286U_SINC THEN ASM_REWRITE_TAC[]);;
